    [Test]
    public async Task TestServerSideNullCoalescingWithIsNull()
    {
        var defaultCategory = 1;
        var categoryId = 0;

        var result = await _database.Products
            .Where(p => p.CategoryID == Sql.Ext.SqlServer().IsNull(categoryId, defaultCategory))
            .Select(p => new
            {
                p.ProductID,
                p.ProductName,
                CategoryId = Sql.Ext.SqlServer().IsNull(p.CategoryID, defaultCategory)
            })
            .ToListAsync();

        Assert.IsNotNull(result);
        Assert.IsTrue(result.All(r => r.CategoryId == defaultCategory));
    }

    [Test]
    public async Task TestNullReplacementInAggregateQuery()
    {
        var maxUnitPriceCategory = await GetSupplierIdWithMaxUnitPrice();

        var supplierProducts = await _database.Products
            .Where(p => p.SupplierID == maxUnitPriceCategory)
            .Select(p => new
            {
                p.ProductID,
                UnitPrice = Sql.Ext.SqlServer().IsNull(p.UnitPrice, 0),
                CategoryName = _database.Categories
                    .Where(c => c.CategoryID == p.CategoryID)
                    .Select(c => c.CategoryName)
                    .FirstOrDefault() ?? "Uncategorized"
            })
            .OrderByDescending(p => p.UnitPrice)
            .Take(5)
            .ToListAsync();

        Assert.IsNotNull(supplierProducts);
        Assert.IsTrue(supplierProducts.Any());
    }

    [Test]
    public async Task TestComplexNullHandlingScenario()
    {
        var complexQuery = await _database.Products
            .Where(p =>
