using System;
using Renci.SshNet.Messages.Connection;

namespace Renci.SshNet.Channels
{
    public abstract class ServerChannel : Channel, IDisposable
    {
        private uint localWindowSize;
        private uint localPacketSize;
        private int remoteChannelNumber;
        private uint remoteWindowSize;
        private uint remotePacketSize;

        protected ServerChannel(Session session) : base(session)
        {
            localWindowSize = InitialLocalWindowSize;
            localPacketSize = InitialLocalPacketSize;
        }

        public virtual void Initialize(ChannelOpenConfirmationMessage message)
        {
            if (message == null)
                throw new ArgumentNullException(nameof(message));

            RemoteChannelNumber = message.RecipientChannel;
            RemoteWindowSize = message.InitialWindowSize;
            RemotePacketSize = message.MaximumPacketSize;
        }

        protected virtual void SendOpenConfirmation()
        {
            var message = new ChannelOpenConfirmationMessage
            {
                RecipientChannel = RemoteChannelNumber,
                SenderChannel = LocalChannelNumber,
                InitialWindowSize = LocalWindowSize,
                MaximumPacketSize = LocalPacketSize
            };

            SendMessage(message);
        }

        public int RemoteChannelNumber
        {
            get => remoteChannelNumber;
            protected set => remoteChannelNumber = value;
        }

        public uint RemoteWindowSize
        {
            get => remoteWindowSize;
            protected set => remoteWindowSize = value;
        }

        public uint RemotePacketSize
        {
            get => remotePacketSize;
            protected set => remotePacketSize = value;
        }

        public uint LocalWindowSize
        {
            get => localWindowSize;
            protected set => localWindowSize = value;
        }

        public uint LocalPacketSize
        {
            get => localPacketSize;
            protected set => localPacketSize = value;
        }

        public abstract void Close();

        protected virtual void Dispose(bool disposing)
        {
            if (disposing)
            {
                // Perform cleanup operations
                Close();
            }
        }

        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }
    }
}

