public interface IIncrementalAnalyzer
{
    Task NewSolutionSnapshotAsync(Solution solution, CancellationToken cancellationToken);
    Task DocumentOpenAsync(DocumentId documentId, CancellationToken cancellationToken);
    Task DocumentCloseAsync(DocumentId documentId, CancellationToken cancellationToken);
    Task DocumentResetAsync(DocumentId documentId, CancellationToken cancellationToken);
    Task AnalyzeSyntaxAsync(Document document, CancellationToken cancellationToken);
    Task AnalyzeDocumentAsync(Document document, CancellationToken cancellationToken);
    Task AnalyzeProjectAsync(Project project, CancellationToken cancellationToken);
}

public abstract class IncrementalAnalyzerBase : IIncrementalAnalyzer
{
    public virtual Task NewSolutionSnapshotAsync(Solution solution, CancellationToken cancellationToken)
    {
        // Default implementation does nothing
        return Task.CompletedTask;
    }

    public virtual Task DocumentOpenAsync(DocumentId documentId, CancellationToken cancellationToken)
    {
        // Default implementation does nothing
        return Task.CompletedTask;
    }

    public virtual Task DocumentCloseAsync(DocumentId documentId, CancellationToken cancellationToken)
    {
        // Default implementation does nothing
        return Task.CompletedTask;
    }

    public virtual Task DocumentResetAsync(DocumentId documentId, CancellationToken cancellationToken)
    {
        // Default implementation does nothing
        return Task.CompletedTask;
    }

    public abstract Task AnalyzeSyntaxAsync(Document document, CancellationToken cancellationToken);

    public abstract Task AnalyzeDocumentAsync(Document document, CancellationToken cancellationToken);

    public abstract Task AnalyzeProjectAsync(Project project, CancellationToken cancellationToken);
}

