    /// Captures the results of the test assertions at the moment of failure.
    /// </summary>
    [Serializable]
    public class MultipleAssertionException : AssertionException
    {
        private readonly ITestResult _testResult;

        /// <summary>
        /// Gets the test result associated with this exception.
        /// </summary>
        public ITestResult TestResult
        {
            get { return _testResult; }
        }

        /// <summary>
        /// Indicates the state of the test result.
        /// This property is overridden to always represent a failure state.
        /// </summary>
        public virtual ResultState ResultState
        {
            get { return ResultState.Failure; }
        }

        /// <summary>
        /// Initializes a new instance of the MultipleAssertionException class with the specified test result.
        /// </summary>
        /// <param name="testResult">The test result containing the details of the failed assertions.</param>
        /// <exception cref="ArgumentNullException">Thrown when the testResult is null.</exception>
        public MultipleAssertionException(ITestResult testResult)
            : base("Multiple assertions failed during test execution.")
        {
            if (testResult == null)
            {
                throw new ArgumentNullException(nameof(testResult));
            }

            _testResult = testResult;
        }

        /// <summary>
        /// Initializes a new instance of the MultipleAssertionException class with serialized data.
        /// </summary>
        /// <param name="info">The SerializationInfo that holds the serialized object data.</param>
        /// <param name="context">The StreamingContext that contains contextual information.</param>
        /// <exception cref="ArgumentNullException">Thrown when the info is null.</exception>
        protected MultipleAssertionException(SerializationInfo info, StreamingContext context)
            : base(info, context)
        {
            if (info == null)
            {
                throw new ArgumentNullException(nameof(info));
            }

            _testResult = (ITestResult)info.GetValue("TestResult", typeof(ITestResult));
        }

