namespace Libretro
{
    /// <summary>
    /// Specifies the layout of a pixel.
    /// </summary>
    public enum PixelFormat : int
    {
        /// <summary>
        /// 16-bit unsigned integer, layout is [X, R5, G5, B5] native endian.
        /// </summary>
        RGB555 = 0,
        /// <summary>
        /// 32-bit unsigned integer, layout is [X, R8, G8, B8] native endian.
        /// </summary>
        XRGB8888 = 1,
        /// <summary>
        /// 16-bit unsigned integer, layout is [R5, G6, B5] native endian.
        /// </summary>
        RGB565 = 2,
    }

    /// <summary>
    /// 32-bit pixel (XRGB8888) represented in floating point.
    /// </summary>
    public struct Pixel
    {
        /// <summary>
        /// Red bit.
        /// </summary>
        public float R;
        /// <summary>
        /// Green bit.
        /// </summary>
        public float G;
        /// <summary>
        /// Blue bit.
        /// </summary>
        public float B;
        /// <summary>
        /// X bit. This is ignored.
        /// </summary>
        public float X;

        public Pixel(float r, float g, float b)
        {
            R = r;
            G = g;
            B = b;
            // for converting to other Color structs, like OpenTK
            // XNA uses ToXRGB8888
            X = 1.0f;
        }

        /// <summary>
        /// Converts this pixel into a 32-bit unsigned integer with the layout of XRGB8888.
        /// </summary>
        /// <returns>A 32-bit integer representing the color of this pixel.</returns>
        public uint ToXRGB8888()
        {
            byte r = (byte)(R * 255);
            byte g = (byte)(G * 255);
            byte b = (byte)(B * 255);
            uint result = 255;
            result |= (uint)r << 8;
            result |= (uint)g << 16;
            result |= (uint)b << 24;
            return result;
        }
    }
}

