namespace gView.Framework.Metadata
{
    public partial class FormMetadata : Form
    {
        private object _metadataObject;
        private Metadata _metadata;
        private XmlStream _xmlStream;

        public FormMetadata(object metadataObject)
        {
            InitializeComponent();
            _metadataObject = metadataObject;
        }

        private void FormMetadata_Load(object sender, EventArgs e)
        {
            try
            {
                _metadata = new Metadata(_metadataObject);
                LoadMetadataProviders();
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Error loading metadata: {ex.Message}", "Metadata Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        private void LoadMetadataProviders()
        {
            var providers = MetadataProviderManager.GetProviders(_metadataObject);

            foreach (var provider in providers)
            {
                var propertyPage = provider.CreatePropertyPage();
                if (propertyPage != null)
                {
                    TabPage tabPage = new TabPage(provider.Title);
                    propertyPage.Dock = DockStyle.Fill;
                    tabPage.Controls.Add(propertyPage);
                    tabControl1.TabPages.Add(tabPage);
                }
            }
        }

        private void btnOK_Click(object sender, EventArgs e)
        {
            SaveMetadata();
            DialogResult = DialogResult.OK;
            Close();
        }

        private void SaveMetadata()
        {
            foreach (TabPage tabPage in tabControl1.TabPages)
            {
                var propertyPage = tabPage.Controls[0] as IPropertyPage;
                if (propertyPage != null)
                {
                    propertyPage.ApplyChanges();
                }
            }
        }

        public XmlStream Stream
        {
            get
            {
                if (_xmlStream == null)
                {
                    _xmlStream = new XmlStream();
                }
                return _xmlStream;
            }
        }

        private void btnCancel_Click(object sender, EventArgs e)
        {
            DialogResult = DialogResult.Cancel;
            Close();
        }
    }

    public interface IMetadataProvider
    {
        string Title { get; }
        IPropertyPage CreatePropertyPage();
    }

