namespace TechnicalIndicators
{
    // Base class for length-based indicators
    public abstract class LengthIndicator<T>
    {
        public int Length { get; private set; }

        protected LengthIndicator(int length)
        {
            Length = length;
        }

        public T Process(T input)
        {
            return OnProcess(input);
        }

        protected abstract T OnProcess(T input);

        public virtual void Reset() { }
    }

    // Implementation of the Relative Strength Index (RSI) indicator
    [DisplayName("Relative Strength Index")]
    public class RelativeStrengthIndex : LengthIndicator<decimal>
    {
        // Smoothing averages: one for gains, one for losses.
        private SmoothedMovingAverage _gain;
        private SmoothedMovingAverage _loss;
        private bool _isInitialized;
        private decimal _last;

        // Constructor initializing with default period of 14
        public RelativeStrengthIndex(int period = 14)
            : base(period)
        {
            ResetSmoothing();
            _isInitialized = false;
        }

        // Processes a new price input and returns the computed RSI value.
        protected override decimal OnProcess(decimal input)
        {
            // For the very first input, initialize the indicator state.
            if (!_isInitialized)
            {
                _last = input;
                _isInitialized = true;
                // No meaningful RSI on first value.
                return 0m;
            }

            // Calculate the difference (delta) from the previous value.
            decimal delta = input - _last;
            _last = input;

            // Separate gains and losses
            decimal gain = delta > 0 ? delta : 0m;
            decimal loss = delta < 0 ? -delta : 0m;

            // Feed gains and losses into their respective smoothed moving averages.
            _gain.Update(gain);
            _loss.Update(loss);

            // Retrieve smoothed averages.
            decimal avgGain = _gain.Current;
            decimal avgLoss = _loss.Current;

            // Avoid division by zero; if no losses, return a maximal RSI value.
            if (avgLoss == 0m)
                return 100m;

            // Calculate ratio and then the normalized RSI value.
            decimal rs = avgGain / avgLoss;
            decimal rsi = 100m - (100m / (1m + rs));
            return rsi;
        }

        // Reinitialize internal state when parameters have changed.

