public class TableLine
{
    public string Title { get; }
    public List<string> Data { get; }

    public TableLine(string title, params string[] data)
    {
        Title = title;
        Data = data.ToList();
    }
}

public class Table
{
    private readonly List<TableLine> _lines;
    private readonly int[] _columnWidths;

    public Table()
    {
        _lines = new List<TableLine>();
        _columnWidths = new int[0];
    }

    public void AddLine(string title, params string[] data)
    {
        var line = new TableLine(title, data);
        _lines.Add(line);
        UpdateColumnWidths(line);
    }

    private void UpdateColumnWidths(TableLine line)
    {
        if (_columnWidths.Length < line.Data.Count + 1)
        {
            Array.Resize(ref _columnWidths, line.Data.Count + 1);
        }

        _columnWidths[0] = Math.Max(_columnWidths[0], line.Title.Length);

        for (int i = 0; i < line.Data.Count; i++)
        {
            _columnWidths[i + 1] = Math.Max(_columnWidths[i + 1], line.Data[i].Length);
        }
    }

    public override string ToString()
    {
        var sb = new StringBuilder();
        sb.AppendLine(DrawBorder());

        for (int i = 0; i < _lines.Count; i++)
        {
            var line = _lines[i];
            sb.AppendLine(FormatLine(line));
            sb.AppendLine(DrawBorder());
        }

        return sb.ToString();
    }

    private string DrawBorder()
    {
        var border = new StringBuilder();
        border.Append("+");
        for (int width in _columnWidths)
        {
            border.Append(new string('-', width + 2));
            border.Append("+");
        }
        return border.ToString();
    }

    private string FormatLine(TableLine line)
    {
        var formattedLine = new StringBuilder("|");
        formattedLine.Append(" " + line.Title.PadRight(_columnWidths[0]) + " |");

        for (int i = 0; i < line.Data.Count; i++)
        {
            formattedLine.Append(" " + line.Data[i].PadRight(_columnWidths[i + 1]) + " |");
        }

        return formattedLine.ToString();
    }
}

public class TableBuilder
{
    private readonly Table _table;

    public TableBuilder()
    {
        _table = new Table();
    }

    public TableBuilder AddRow(string title, params string[] data)
    {
        _table.AddLine(title, data);
        return this;
    }

    public string Build()
    {
        return _table.ToString();
    }
}

