namespace LongMult
{
    public class LongMult
    {
        private static byte[] stringToDigits(String num)
        {
            byte[] result = new byte[num.Length];
            for (int i = 0; i < num.Length; i++)
            {
                char c = num[i];
                if (c < '0' || c > '9')
                {
                    throw new ArgumentException("Invalid digit " + c + " found at position " + i);
                }
                result[num.Length - 1 - i] = (byte)(c - '0');
            }
            return result;
        }

        public static String longMult(String num1, String num2)
        {
            byte[] left = stringToDigits(num1);
            byte[] right = stringToDigits(num2);
            byte[] result = new byte[left.Length + right.Length];
            for (int rightPos = 0; rightPos < right.Length; rightPos++)
            {
                byte rightDigit = right[rightPos];
                byte temp = 0;
                for (int leftPos = 0; leftPos < left.Length; leftPos++)
                {
                    temp += result[leftPos + rightPos];
                    temp += rightDigit * left[leftPos];
                    result[leftPos + rightPos] = (byte)(temp % 10);
                    temp /= 10;
                }
                int destPos = rightPos + left.Length;
                while (temp!= 0)
                {
                    temp += result[destPos] & 0xFFFFFFFFL;
                    result[destPos] = (byte)(temp % 10);
                    temp /= 10;
                    destPos++;
                }
            }
            StringBuilder stringResultBuilder = new StringBuilder(result.Length);
            for (int i = result.Length - 1; i >= 0; i--)
            {
                byte digit = result[i];
                if (digit!= 0 || stringResultBuilder.Length > 0)
                {
                    stringResultBuilder.Append((char)(digit + '0'));
                }
            }
            return stringResultBuilder.ToString();
        }

        public static void Main(String[] args)
        {
            Console.WriteLine(longMult("18446744073709551616", "18446744073709551616"));
        }
    }
}

using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Xml;

namespace AutomatedLab
{

    public class PathValidator : XmlValidator, IValidate
    {
        public PathValidator()
        {
            messageContainer = RunValidation();
        }

        public override IEnumerable<ValidationMessage> Validate()
        {
            var pathsNotFound = new List<string>();

            foreach (var doc in docs)
            {
                var paths = doc.SelectNodes("//Path").OfType<XmlElement>().Select(e => e.InnerText);

                foreach (var path in paths)
                {
                    if (path.StartsWith("http"))
                    {
                        yield return new ValidationMessage()
                        {
                            Message = "URI skipped",
                            TargetObject = path,
                            Type = MessageType.Verbose
                        };

                        continue;
                    }

                    if (!File.Exists(path) & !Directory.Exists(path))
                    {
                        yield return new ValidationMessage()
                        {
                            Message = "The path could not be found",
                            TargetObject = path,
                            Type = MessageType.Error
                        };
                    }
                    else
                    {
                        yield return new ValidationMessage()
                        {
                            Message = "Path verified successfully",
                            TargetObject = path,
                            Type = MessageType.Verbose
                        };
                    }
                }
            }
        }
    }
}

 
using System;
using System.Drawing;
using System.Windows.Forms;
 
class BasicBitmapStorage
{
    public Bitmap image;
 
    public BasicBitmapStorage(int width, int height)
    {
        image = new Bitmap(width, height);
    }
 
    public void fill(Color c)
    {
        Graphics g = Graphics.FromImage(image);
        g.Clear(c);
    }
 
    public void setPixel(int x, int y, Color c)
    {
        image.SetPixel(x, y, c);
    }
 
    public Color getPixel(int x, int y)
    {
        return image.GetPixel(x, y);
    }
}
 
class Library
{
    static void drawCircle(BasicBitmapStorage bbs, int centerX, int centerY, int radius, Color circleColor)
    {
        int d = (5 - radius * 4) / 4;
        int x = 0;
        int y = radius;
 
        do
        {
            bbs.setPixel(centerX + x, centerY + y, circleColor);
            bbs.setPixel(centerX + x, centerY - y, circleColor);
            bbs.setPixel(centerX - x, centerY + y, circleColor);
            bbs.setPixel(centerX - x, centerY - y, circleColor);
            bbs.setPixel(centerX + y, centerY + x, circleColor);
            bbs.setPixel(centerX + y, centerY - x, circleColor);
            bbs.setPixel(centerX - y, centerY + x, circleColor);
            bbs.setPixel(centerX - y, centerY - x, circleColor);
 
            if (d < 0)
            {
                d += 2 * x + 1;
            }
            else
            {
                d += 2 * (x - y) + 1;
                y--;
            }
            x++;
        }
        while (x <= y);
    }
 
    static void Main(string[] args)
    {
        BasicBitmapStorage bbs = new BasicBitmapStorage(400, 400);
        bbs.fill(Color.Pink);
        drawCircle(bbs, 200, 200, 100, Color.Black);
        drawCircle(bbs, 200, 200, 50, Color.White);
 
        Form form = new Form();
        form.Text = "Bresenham's circle algorithm";
        form.Size = new Size(400, 400);
        form.BackgroundImage = bbs.image;
        form.ShowDialog();
    }
}

