public partial class Appointments : System.Web.UI.Page
{
    private AppointmentClient proxy;

    protected void Page_Load(object sender, EventArgs e)
    {
        if (!IsPostBack)
        {
            proxy = new AppointmentClient();
            string username = Session["Username"].ToString();
            DataTable dt = proxy.GetAppointmentHistory(username);
            CustomizeColumns(dt);
            GridView1.DataSource = dt;
            GridView1.DataBind();

            DayPilotCalendar1.DataSource = GetFutureAppointments(dt);
            DayPilotCalendar1.DataBind();
        }
    }

    private DataTable GetFutureAppointments(DataTable dt)
    {
        DataTable futureAppointments = dt.Clone();
        DateTime today = DateTime.Today;

        foreach (DataRow row in dt.Rows)
        {
            DateTime appointmentDate = Convert.ToDateTime(row["AppointmentDate"]);
            if (appointmentDate >= today)
            {
                futureAppointments.ImportRow(row);
            }
        }

        DayPilotCalendar1.StartDate = today;
        DayPilotCalendar1.Days = 7;
        return futureAppointments;
    }

    private void CustomizeColumns(DataTable dt)
    {
        dt.Columns["PatientName"].ColumnName = "Patient";
        dt.Columns["DoctorName"].ColumnName = "Doctor";
        dt.Columns["AppointmentDate"].ColumnName = "Date";
        dt.Columns["AppointmentTime"].ColumnName = "Time";
        dt.Columns["Reason"].ColumnName = "Reason for Visit";
    }
}

