using System;
using RestSharp;
using DropNet.Models;

namespace DropboxSDK
{
    public partial class DropNetClient
    {
        private readonly string _apiKey;
        private readonly string _appSecret;
        private UserLogin _userLogin;
        private readonly RestClient _apiClient;

        public DropNetClient(string apiKey, string appSecret)
        {
            _apiKey = apiKey;
            _appSecret = appSecret;
            _apiClient = new RestClient("https://api.dropboxapi.com/2/");
        }

        public UserLogin CurrentUser => _userLogin;

        #if !WINDOWS_PHONE
        public string GetTokenAndBuildUrl(string redirectUri)
        {
            var authClient = new RestClient("https://www.dropbox.com/");
            var request = new RestRequest("oauth2/authorize", Method.Get);
            request.AddParameter("client_id", _apiKey);
            request.AddParameter("response_type", "code");
            request.AddParameter("redirect_uri", redirectUri);
            return authClient.BuildUri(request).ToString();
        }
        #endif

        public OAuth2AccessToken GetAccessToken(string code, string redirectUri)
        {
            var tokenClient = new RestClient("https://api.dropbox.com/");
            var request = new RestRequest("oauth2/token", Method.Post);
            request.AddParameter("code", code);
            request.AddParameter("grant_type", "authorization_code");
            request.AddParameter("client_id", _apiKey);
            request.AddParameter("client_secret", _appSecret);
            request.AddParameter("redirect_uri", redirectUri);

            var response = tokenClient.Execute<OAuth2AccessToken>(request);
            if (!response.IsSuccessful)
                throw new Exception($"Token exchange failed: {response.ErrorMessage}");

            _userLogin = new UserLogin { Token = response.Data.AccessToken };
            return response.Data;
        }

