using System;
using System.Collections;
 
namespace RosettaCode {
    class SierpinskiTriangle {
        int len;
        BitArray b;
 
        public SierpinskiTriangle(int n) {
            if (n < 1) {
                throw new ArgumentOutOfRangeException("Order must be greater than zero");
            }
            len = 1 << (n+1);
            b = new BitArray(len+1, false);
            b[len>>1] = true;
        }
 
        public void Display() {
            for (int j = 0; j < len / 2; j++) {
                for (int i = 0; i < b.Count; i++) {
                    Console.Write("{0}", b[i] ? "*" : " ");
                }
                Console.WriteLine();
                NextGen();
            }
        }
 
        private void NextGen() {
            BitArray next = new BitArray(b.Count, false);
            for (int i = 0; i < b.Count; i++) {
                if (b[i]) {
                    next[i - 1] = next[i - 1] ^ true;
                    next[i + 1] = next[i + 1] ^ true;
                }
            }
            b = next;
        }
    }
}

 
using System;
using System.Collections.Generic;
using System.Linq;
 
public static class Tree
{
    public static List<object> flattenList(List<object> nestList)
    {
        var flatList = new List<object>();
 
        void flatten(List<object> list)
        {
            foreach (var e in list)
            {
                if (!(e is List<object>))
                    flatList.Add(e);
                else
                    flatten((List<object>)e);
            }
        }
 
        flatten(nestList);
        return flatList;
    }
 
    public static List<List<object>> operator *(List<object> left, List<object> right)
    {
        var prod = new List<List<object>>();
        foreach (var e in left)
        {
            foreach (var f in right)
            {
                prod.Add(new List<object> { e, f });
            }
        }
        return prod;
    }
 
    public static List<List<object>> nAryCartesianProduct(List<List<object>> lists)
    {
        if (lists.Count < 2)
            throw new ArgumentException("lists.Count < 2");
        return lists.Skip(2).Aggregate(lists[0] * lists[1], (cp, ls) => cp * ls).Select(flattenList).ToList();
    }
 
    public static void printNAryProduct(List<List<object>> lists)
    {
        Console.WriteLine($"{string.Join(" x ", lists)} = ");
        Console.WriteLine("[");
        Console.WriteLine(string.Join("\n    ", nAryCartesianProduct(lists).Select(x => x.ToString())));
        Console.WriteLine("]\n");
    }
 
    public static void Main(string[] args)
    {
        Console.WriteLine("[1, 2] x [3, 4] = {0}", string.Join(", ", (List<object>)listOf(1, 2) * listOf(3, 4)));
        Console.WriteLine("[3, 4] x [1, 2] = {0}", string.Join(", ", (List<object>)listOf(3, 4) * listOf(1, 2)));
        Console.WriteLine("[1, 2] x []     = {0}", string.Join(", ", (List<object>)listOf(1, 2) * listOf()));
        Console.WriteLine("[]     x [1, 2] = {0}", string.Join(", ", (List<object>)listOf() * listOf(1, 2)));
        Console.WriteLine("[1, a] x [2, b] = {0}", string.Join(", ", (List<object>)listOf(1, 'a') * listOf(2, 'b')));
        Console.WriteLine();
        printNAryProduct(listOf(listOf(1776, 1789), listOf(7, 12), listOf(4, 14, 23), listOf(0, 1)));
        printNAryProduct(listOf(listOf(1, 2, 3), listOf(30), listOf(500, 100)));
        printNAryProduct(listOf(listOf(1, 2, 3), listOf(), listOf(500, 100)));
        printNAryProduct(listOf(listOf(1, 2, 3), listOf(30), listOf('a', 'b')));
    }
 
    public static List<object> listOf(params object[] args)
    {
        return args.ToList();
    }
}

