public static class LanguageHelper
{
    private const string LanguageKey = "Language";
    public const string German = "de";
    public const string English = "en";

    public static void SetLanguage(string languageCode)
    {
        if (string.IsNullOrEmpty(languageCode))
        {
            languageCode = English;
        }

        if (languageCode != German && languageCode != English)
        {
            languageCode = English;
        }

        HttpContext.Current.Session[LanguageKey] = languageCode;
    }

    public static string GetLanguage()
    {
        if (HttpContext.Current == null)
        {
            return English;
        }

        if (HttpContext.Current.Session[LanguageKey] != null)
        {
            return HttpContext.Current.Session[LanguageKey].ToString();
        }

        if (HttpContext.Current.Request.UserLanguages != null && HttpContext.Current.Request.UserLanguages.Length > 0)
        {
            foreach (var lang in HttpContext.Current.Request.UserLanguages)
            {
                if (lang.StartsWith(German))
                {
                    return German;
                }
                if (lang.StartsWith(English))
                {
                    return English;
                }
            }
        }

        return English;
    }

    public static void AddElement<T>(List<T> list, T element)
    {
        if (list == null)
        {
            throw new ArgumentNullException("list");
        }

        list.Add(element);
    }

    public static bool HasElement<T>(List<T> list, T element)
    {
        if (list == null)
        {
            throw new ArgumentNullException("list");
        }

        return list.Contains(element);
    }
}

