public class SqlCommandAnalyzer
{
    private static readonly ConcurrentDictionary<string, CommandStatistics> _commandStatistics
        = new ConcurrentDictionary<string, CommandStatistics>();

    private readonly IExceptionLogger _exceptionLogger;
    private readonly IAppMessenger _appMessenger;

    public SqlCommandAnalyzer(IExceptionLogger exceptionLogger, IAppMessenger appMessenger)
    {
        _exceptionLogger = exceptionLogger;
        _appMessenger = appMessenger;
    }

    public CommandStatistics SetCommandStatistics(Command command)
    {
        try
        {
            string normalizedHash = SetNormalizedSqlHash(command.SqlText);

            return _commandStatistics.GetOrAdd(normalizedHash, key =>
                RunAnalysis(command, key));
        }
        catch (Exception ex)
        {
            _exceptionLogger.LogError(ex);
            return null;
        }
    }

    private CommandStatistics RunAnalysis(Command command, string normalizedHash)
    {
        var statistics = new CommandStatistics
        {
            NormalizedSqlHash = normalizedHash,
            OriginalCommand = command,
            FirstExecutedAt = DateTime.UtcNow,
            ExecutionCount = 1
        };

        var fragmentVisitor = new RunTSqlFragmentVisitor();
        fragmentVisitor.AnalyzeFragmentVisitor(command.SqlText);

        statistics.AnalysisDetails = fragmentVisitor.GetAnalysisResult();

        return statistics;
    }

    private string SetNormalizedSqlHash(string sqlText)
    {
        using (var md5 = MD5.Create())
        {
            byte[] inputBytes = Encoding.UTF8.GetBytes(NormalizeSqlQuery(sqlText));
            byte[] hashBytes = md5.ComputeHash(inputBytes);
            return Convert.ToBase64String(hashBytes);
        }
    }

    private string NormalizeSqlQuery(string sqlText)
    {
        // Basic SQL normalization: remove comments, extra whitespaces, parameter values
        return sqlText.ToLower()
            .Replace("\r", " ")
            .Replace("\n", " ")
            .Replace("\t", " ")
            .Trim();
    }
}

