    public class DbAuthenticate : IAuthenticate
    {
        private readonly IUnitOfWork unitOfWork;
        private static readonly Logger logger = LogManager.GetCurrentClassLogger();

        public DbAuthenticate(IUnitOfWork unitOfWork)
        {
            this.unitOfWork = unitOfWork;
        }

        public User AuthenticateUser(string email, string password, string hostName)
        {
            try
            {
                if (string.IsNullOrEmpty(email) || string.IsNullOrEmpty(password) || string.IsNullOrEmpty(hostName))
                {
                    logger.Warn("Invalid email, password, or host name provided.");
                    throw new ArgumentException("Email, password, and host name must be provided.");
                }

                var user = unitOfWork.UserRepository.GetUserByEmail(email);
                if (user == null || user.IsDeleted || user.AcquisitionType != AcquisitionType.Specific)
                {
                    logger.Warn($"User not found or is not eligible for access: {email}");
                    throw new UnauthorizedAccessException("User not found or not authorized.");
                }

                if (!IsUserAuthorizedForCompany(user, hostName))
                {
                    logger.Warn($"User {email} does not have access to company: {hostName}");
                    throw new UnauthorizedAccessException("User is not authorized for this company.");
                }

                var decryptedPassword = DecryptPassword(user.EncryptedPassword);
                if (decryptedPassword != password)
                {
                    logger.Warn($"Password mismatch for user {email}");
                    throw new UnauthorizedAccessException("Invalid password.");
                }

                logger.Info($"User {email} authenticated successfully.");
                return user;
            }
            catch (Exception ex)
            {
                logger.Error(ex, "An error occurred during authentication.");
                throw; // Re-throw the exception to be handled upstream.
            }
