using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;

public class ReadLengthLimitingStream : Stream
{
    private readonly Stream _wrappedStream;
    private readonly long _length;
    private long _totalBytesRead;

    public ReadLengthLimitingStream(Stream wrappedStream, long length)
    {
        if (wrappedStream == null)
            throw new ArgumentNullException(nameof(wrappedStream));
        if (!wrappedStream.CanRead)
            throw new ArgumentException("Stream must be readable", nameof(wrappedStream));
        if (length < 0)
            throw new ArgumentOutOfRangeException(nameof(length));

        _wrappedStream = wrappedStream;
        _length = length;
    }

    public override int Read(byte[] buffer, int offset, int count)
    {
        long remaining = _length - _totalBytesRead;
        if (remaining <= 0) return 0;

        int readSize = (int)Math.Min(count, remaining);
        int bytesRead = _wrappedStream.Read(buffer, offset, readSize);
        _totalBytesRead += bytesRead;
        return bytesRead;
    }

    public override async Task<int> ReadAsync(byte[] buffer, int offset, int count, CancellationToken cancellationToken)
    {
        long remaining = _length - _totalBytesRead;
        if (remaining <= 0) return 0;

        int readSize = (int)Math.Min(count, remaining);
        int bytesRead = await _wrappedStream.ReadAsync(buffer, offset, readSize, cancellationToken);
        _totalBytesRead += bytesRead;
        return bytesRead;
    }

    public override bool CanRead => true;
    public override bool CanSeek => false;
    public override bool CanWrite => false;

    public override long Length => _length;

    public override long Position
    {
        get => _totalBytesRead;
        set => throw new NotSupportedException("Forward-only stream");
    }

    public override void Flush() { }

    public override long Seek(long offset, SeekOrigin origin)
    {
        throw new NotSupportedException("Forward-only stream");
    }

    public override void SetLength(long value)
    {
        throw new NotSupportedException("SetLength not supported");
    }

    public override void Write(byte[] buffer, int offset, int count)
    {
        throw new NotSupportedException("Write not supported");
    }

    public override Task WriteAsync(byte[] buffer, int offset, int count, CancellationToken cancellationToken)
    {
        throw new NotSupportedException("Write not supported");
    }

    protected override void Dispose(bool disposing)
    {
        if (disposing)

