namespace Mung.App
{
    public class BatchCommand : IConsoleCommand
    {
        public string Description => "mung copy <scriptfile> - Executes commands from a script file in parallel.";

        public void Execute(string[] args)
        {
            if (args.Length < 2)
            {
                Console.WriteLine("Usage: mung copy <scriptfile>");
                return;
            }

            string fileName = args[1];
            if (!File.Exists(fileName))
            {
                Console.WriteLine($"File not found: {fileName}");
                return;
            }

            string[] script = File.ReadAllLines(fileName);
            Parallel.ForEach(script, line =>
            {
                if (string.IsNullOrWhiteSpace(line))
                    return;

                string[] commandArgs = line.Split(' ');
                string[] filteredArgs = commandArgs.Where(a => !string.IsNullOrWhiteSpace(a)).ToArray();
                if (filteredArgs.Length == 0)
                    return;

                string opName = filteredArgs[0].ToLower();
                IConsoleCommand cc = Program.GetOperations().FirstOrDefault(o => o.Key == opName)?.Value;
                if (cc == null)
                {
                    Console.WriteLine($"Unknown operation: {opName}");
                    return;
                }

                try
                {
                    cc.Execute(filteredArgs);
                }
                catch (Exception ex)
                {
                    MungLog.LogError($"Error executing command '{line}': {ex.Message}");
                }
            });
        }

        public void RunBatchCommand(string fileName)
        {
            if (!File.Exists(fileName))
            {
                Console.WriteLine($"File not found: {fileName}");
                return;
            }

            string[] script = File.ReadAllLines(fileName);
            Parallel.ForEach(script, line =>
            {
                if (string.IsNullOrWhiteSpace(line))
                    return;

                string[] commandArgs = line.Split(' ');
                string[] filteredArgs = commandArgs.Where(a => !string.IsNullOrWhiteSpace(a)).ToArray();
                if (filteredArgs.Length == 0)
                    return;

                string opName = filteredArgs[0].ToLower();

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

public sealed class Singleton
{
    private static Singleton instance = null;
    private List<string> list;
    private Random random;

    private Singleton()
    {
        list = new List<string>();
        random = new Random();
        Console.WriteLine("Singleton instance created.");
    }

    public static Singleton Instance()
    {
        if (instance == null)
        {
            instance = new Singleton();
        }
        return instance;
    }

    public void AddToList(string item)
    {
        if (!string.IsNullOrEmpty(item))
        {
            list.Add(item);
            Console.WriteLine($"Added item: {item}");
        }
        else
        {
            Console.WriteLine("Cannot add empty item.");
        }
    }

    public void RemoveFromList(string item)
    {
        if (list.Contains(item))
        {
            list.Remove(item);
            Console.WriteLine($"Removed item: {item}");
        }
        else
        {
            Console.WriteLine("Item not found in list.");
        }
    }

    public string GetRandomItem()
    {
        if (list.Count > 0)
        {
            int randomIndex = random.Next(list.Count);
            string randomItem = list[randomIndex];
            Console.WriteLine($"Random item selected: {randomItem}");
            return randomItem;
        }
        else
        {
            Console.WriteLine("List is empty.");
            return null;
        }
    }

    public void DisplayList()
    {
        Console.WriteLine("Current List Contents:");
        if (list.Count > 0)
        {
            foreach (string item in list)
            {
                Console.WriteLine(item);
            }
        }
        else
        {
            Console.WriteLine("List is empty.");
        }
    }

    public int GetListCount()
    {
        return list.Count;
    }
}

class Parser
{
    static void Main(string[] args)
    {
        Singleton singleton1 = Singleton.Instance();
        Singleton singleton2 = Singleton.Instance();

        singleton1.AddToList("Apple");
        singleton1.AddToList("Banana");
        singleton2.AddToList("Cherry");

        singleton1.DisplayList();
        Console.WriteLine($"List Count: {singleton2.GetListCount()}");

        singleton1.GetRandomItem();
        singleton2.RemoveFromList("Banana");

        singleton1.DisplayList();
    }
}

using System;
 
public class Vector
{
  public static void Main()
  {
    int[] a = {4, 65, 2, -31, 0, 99, 2, 83, 782, 1};
    int n = a.Length;
 
    for (int i = 0; i < n; i++)
    {
      Console.Write(a[i] + " ");
    }
    Console.WriteLine();
 
    Quicksort(a, n);
 
    for (int i = 0; i < n; i++)
    {
      Console.Write(a[i] + " ");
    }
    Console.WriteLine();
  }
 
  public static void Quicksort(int[] A, int len)
  {
    if (len < 2) return;
 
    int pivot = A[len / 2];
 
    int i, j;
    for (i = 0, j = len - 1; ; i++, j--)
    {
      while (A[i] < pivot) i++;
      while (A[j] > pivot) j--;
 
      if (i >= j) break;
 
      int temp = A[i];
      A[i]     = A[j];
      A[j]     = temp;
    }
 
    Quicksort(A, i);
    Quicksort(A, len - i);
  }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace Wprime
{
    class Sorter
    {
        static void Main(string[] args)
        {
            Console.WriteLine("Enter upper limit: ");
            int c = int.Parse(Console.ReadLine());
            Console.WriteLine("Primes under {0}:", c);
            Console.WriteLine(string.Join(", ", Enumerable.Range(0, c).Where(n => IsWprime(n))));
        }
 
        static bool IsWprime(int n)
        {
            return n == 2 || (
                n > 1
                && n % 2!= 0
                && (Factorial(n - 1) + 1) % n == 0
            );
        }
 
        static int Factorial(int n)
        {
            return n == 0? 1 : Enumerable.Range(1, n).Aggregate((a, b) => a * b);
        }
    }
}

