public class StateResetInProcess
{
    private readonly IComponentModel _componentModel;

    public StateResetInProcess(IComponentModel componentModel)
    {
        _componentModel = componentModel;
    }

    public async Task ResetGlobalOptionsAsync(CancellationToken cancellationToken)
    {
        var globalOptions = await GetComponentModelServiceAsync<IGlobalOptionService>(cancellationToken);
        await SwitchToMainThreadAsync(cancellationToken);
        globalOptions.SetGlobalOption(new OptionKey(CSharpNavigationBarOptions.NavigationBar, LanguageNames.CSharp), true);
    }

    public async Task ResetHostSettingsAsync(CancellationToken cancellationToken)
    {
        var editorOptionsFactoryService = await GetComponentModelServiceAsync<IEditorOptionsFactoryService>(cancellationToken);
        var options = editorOptionsFactoryService.GlobalOptions;

        await SetUseSuggestionModeAsync(options, true, cancellationToken);
        await SetUseSuggestionModeAsync(options, false, cancellationToken);

        await SwitchToMainThreadAsync(cancellationToken);
        SetOptionValue(options, new EditorOptionKey<bool>("Roslyn.ResponsiveCompletion"), false);

        var latencyGuardOptionKey = new EditorOptionKey<bool>("Roslyn.TypingLatencyGuard");
        SetOptionValue(options, latencyGuardOptionKey, false);
    }

    private async Task<T> GetComponentModelServiceAsync<T>(CancellationToken cancellationToken)
    {
        await SwitchToMainThreadAsync(cancellationToken);
        return _componentModel.GetService<T>();
    }

    private Task SwitchToMainThreadAsync(CancellationToken cancellationToken)
    {
        return JoinableTaskFactory.SwitchToMainThreadAsync(cancellationToken);
    }

    private async Task SetUseSuggestionModeAsync(IEditorOptions options, bool isDebugger, CancellationToken cancellationToken)
    {
        await SwitchToMainThreadAsync(cancellationToken);
        var key = new EditorOptionKey<bool>(isDebugger ? "Roslyn.UseSuggestionMode_Debugger" : "Roslyn.UseSuggestionMode_NonDebugger");
        SetOptionValue(options, key, true);
    }

    private void SetOptionValue<T>(IEditorOptions options, EditorOptionKey<T> key, T value)
    {
        options.SetOptionValue(key, value);
    }
}

using Gimpfu;
using System;
using System.Collections.Generic;

public class QR : Plugin
{
    private string text;
    private string encoding;
    private string error_correction;
    private int margin;

    public static void Main(string[] args)
    {
        // Entry point for the GIMP plug-in
        GimpPlugin.Init();
        QR qrPlugin = new QR();
        qrPlugin.Register();
    }

    public void Register()
    {
        // Register the procedure in GIMP
        Gimpfu.Func.Register("generate_qr_code",
            "Generate a QR code.",
            "Generates a QR code based on user-defined parameters.",
            $"© 2023 QR Code Generator",
            "GPL",
            "Pythonical-based example",
            new ParamSpec[]
            {
                new ParamString("text", "Text", "Content of the QR code", ""),
                new ParamString("encoding", "Encoding", "Encoding type (e.g., 'UTF-8')", "UTF-8"),
                new ParamString("error_correction", "Error Correction", "Error correction level (L, M, Q, H)", "M"),
                new ParamInt("margin", "Margin Size", "Margin size around the QR code", 4)
            },
            new ParamSpec[]
            {
                new ParamImage("image", "Image", "Image to render the QR code on")
            },
            new ProcedureDelegate(GenerateQRCode)
        );
    }

    private void GenerateQRCode(params object[] args)
    {
        text = (string)args[0];
        encoding = (string)args[1];
        error_correction = (string)args[2];
        margin = (int)args[3];
        Image image = (Image)args[4];

        QRCodeRenderer renderer = new QRCodeRenderer(text, encoding, error_correction, margin);
        Bitmap qrBitmap = renderer.Render();

        PasteQRCodeOntoImage(image, qrBitmap);
    }

    private void PasteQRCodeOntoImage(Image image, Bitmap qrBitmap)
    {
        // Logic to paste the QR bitmap onto the GIMP image
        Gimpfu.Layer qrLayer = new Gimpfu.Layer(qrBitmap);
        image.AddLayer(qrLayer);
        qrLayer.SetPosition(10, 10);  // Positioning the QR code
        image.Update();
    }

}

