using System;
using System.Collections.Generic;

namespace DrumEmulator
{
    // Interface for memory manipulation
    public interface IMemory
    {
        void Write(int address, int value);
        int Read(int address);
    }

    // A simple memory implementation for demonstration
    public class Memory : IMemory
    {
        private int[] memory;
        public Memory(int size)
        {
            memory = new int[size];
        }
        public void Write(int address, int value)
        {
            if (address >= 0 && address < memory.Length)
            {
                memory[address] = value;
            }
        }
        public int Read(int address)
        {
            return (address >= 0 && address < memory.Length) ? memory[address] : 0;
        }
    }

    // Represents a Drum Sound loaded in memory.
    public class DrumSound
    {
        public int SampleLength { get; private set; }
        public int[] Samples { get; private set; }

        public DrumSound(int sampleLength, int[] samples)
        {
            SampleLength = sampleLength;
            Samples = samples;
        }
    }

    // Abstract drum bank that contains fixed number of drum sounds.
    public abstract class DrumBank
    {
        protected const int DRUM_COUNT = 10;
        protected const int SOUND_STRIDE = 20; // Memory block size per sound
        protected int baseOffset;
        protected IMemory memory;
        protected List<DrumSound> drumSounds;

        // Preset sound parameters: each array represents drum sample values.
        protected int[][] presetSounds = new int[][]
        {
            new int[]{1, 2, 3, 4},
            new int[]{5, 6, 7},
            new int[]{8, 9, 10, 11, 12},
            new int[]{13, 14},
            new int[]{15, 16, 17, 18},
            new int[]{19, 20, 21},
            new int[]{22, 23, 24, 25},
            new int[]{26, 27},
            new int[]{28, 29, 30},
            new int[]{31, 32, 33, 34, 35}
        };

        public DrumBank(IMemory memoryHandler, int startOffset)
        {
            memory = memoryHandler;
            baseOffset = startOffset;
            drumSounds = new List<DrumSound>(DRUM_COUNT);
            GenerateDrumSounds();
        }

        // Generates and writes the drum sound data into memory.
        private void GenerateDrumSounds()
        {
            for (int i = 0; i < DRUM_COUNT; i++)
            {
                int offset = baseOffset + i * SOUND_STRIDE;
                int[] samples = presetSounds[i];
                int length = samples.Length;

