namespace Circle
{
    class Service
    {
        struct Point
        {
            public double x;
            public double y;
        }
 
        static double distance(Point p1, Point p2)
        {
            return Math.Sqrt(Math.Pow(p1.x - p2.x, 2) + Math.Pow(p1.y - p2.y, 2));
        }
 
        static void describe_circle(Point p1, Point p2, double r)
        {
            double sep = distance(p1, p2);
 
            if (sep == 0)
            {
                if (r == 0)
                {
                    Console.WriteLine("No circles can be drawn through {0}", p1);
                }
                else
                {
                    Console.WriteLine("Infinitely many circles can be drawn through {0}", p1);
                }
            }
            else if (sep == 2 * r)
            {
                Console.WriteLine("Given points are opposite ends of a diameter of the circle with center ({0:F4},{1:F4}) and r {2:F4}",
                    (p1.x + p2.x) / 2, (p1.y + p2.y) / 2, r);
            }
            else if (sep > 2 * r)
            {
                Console.WriteLine("Given points are farther away from each other than a diameter of a circle with r {0:F4}", r);
            }
            else
            {
                double mirror_dist = Math.Sqrt(r * r - (sep / 2) * (sep / 2));
 
                Console.WriteLine("Two circles are possible.");
                Console.WriteLine("Circle C1 with center ({0:F4}, {1:F4}), r {2:F4} and Circle C2 with center ({3:F4}, {4:F4}), r {5:F4}",
                    ((p1.x + p2.x) / 2) + mirror_dist * (p1.y - p2.y) / sep, (p1.y + p2.y) / 2 + mirror_dist * (p2.x - p1.x) / sep,
                    r,
                    (p1.x + p2.x) / 2 - mirror_dist * (p1.y - p2.y) / sep, (p1.y + p2.y) / 2 - mirror_dist * (p2.x - p1.x) / sep, r);
            }
        }
 
