    // Event args for loading state
    public class LoadStateEventArgs : EventArgs
    {
        public object NavigationParameter { get; private set; }
        public Dictionary<string, object> PageState { get; private set; }

        public LoadStateEventArgs(object navigationParameter, Dictionary<string, object> pageState)
        {
            NavigationParameter = navigationParameter;
            PageState = pageState;
        }
    }

    // Event args for saving state
    public class SaveStateEventArgs : EventArgs
    {
        public Dictionary<string, object> PageState { get; private set; }

        public SaveStateEventArgs(Dictionary<string, object> pageState)
        {
            PageState = pageState;
        }
    }

    // Helper class encapsulating navigation event handling.
    public class NavigationHelper
    {
        public event EventHandler<LoadStateEventArgs> LoadState;
        public event EventHandler<SaveStateEventArgs> SaveState;

        // Simulate triggering LoadState during OnNavigatedTo
        public void OnNavigatedTo(NavigationEventArgs e)
        {
            Dictionary<string, object> state = e.NavigationMode == NavigationMode.New ?
                new Dictionary<string, object>() : (e.Parameter as Dictionary<string, object>) ?? new Dictionary<string, object>();

            LoadState?.Invoke(this, new LoadStateEventArgs(e.Parameter, state));
        }

        // Simulate triggering SaveState during OnNavigatedFrom
        public void OnNavigatedFrom(NavigationEventArgs e)
        {
            Dictionary<string, object> state = new Dictionary<string, object>();
            SaveState?.Invoke(this, new SaveStateEventArgs(state));
            // In a real implementation state would be persisted.
        }
    }

    // Abstract base class for pages with navigation state management.
    public abstract class StatefulPage : Page
    {
        // Constant key for page state
        protected const string StateKey = "PageStateKey";

        private NavigationHelper navigationHelper;

        protected StatefulPage()
        {
            navigationHelper = new NavigationHelper();
            navigationHelper.LoadState += NavigationHelper_LoadState;
            navigationHelper.SaveState += NavigationHelper_SaveState;
        }

        // Expose the navigation helper if needed by derived pages.
        public NavigationHelper NavigationHelper
        {

