        obj.MarkNew();
        await obj.CreateAsync(criteria, isSync);
        obj.ThrowIfBusy();
        obj.OnDataPortalInvokeComplete(eventArgs);
        return new DataPortalResult(obj.Instance);
      }
      catch (Exception ex)
      {
        try
        {
          if (obj != null)
            obj.OnDataPortalException(eventArgs, ex);
        }
        catch
        {
