using System;
 
public class Vector
{
    public static void Main(string[] args)
    {
        string[] a = new string[] { "ABC", "DEF", "G", "H" };
        for (int i = 0; i < 5; i++)
        {
            quibble(Console.Out, a, i);
            Console.Out.WriteLine();
        }
    }
 
    public static void quibble<T>(System.IO.TextWriter o, T[] i, int e)
    {
        o.Write("{");
        if (e!= 0)
        {
            T n = i[0];
            string more = "";
            for (int j = 1; j < e; j++)
            {
                o.Write(more + n);
                more = ", ";
                n = i[j];
            }
            o.Write((more == ""? "" : " and ") + n);
        }
        o.Write("}");
    }
}

