[TestFixture]
public class IntegrationTests
{
    private LidgrenServerConnectionListener _connectionListener;
    private string _applicationId;
    private GenericServerEndpoint _server;
    private OperationDispatcher _dispatcher;
    private IPAddress _listenAddress;
    private string _host;
    private int _port;

    [SetUp]
    public void SetUp()
    {
        _applicationId = "TestApp";
        _listenAddress = IPAddress.Parse("0.0.0.0");
        _host = "localhost";
        _port = 3231;

        var serverConfig = new ServerConfig
        {
            ApplicationId = _applicationId,
            ListenAddress = _listenAddress,
            Port = _port
        };

        _connectionListener = new LidgrenServerConnectionListener(serverConfig);
        _dispatcher = new OperationDispatcher();
        _server = new GenericServerEndpoint(_dispatcher, new BinaryMessageSerializer());

        _dispatcher.RegisterHandler<ICalculator>(new Calculator());
        _dispatcher.RegisterHandler<IGreeter>(new Greeter());

        _server.Start(_connectionListener);
    }

    [TearDown]
    public void TearDown()
    {
        _server.Stop();
        _connectionListener.Dispose();
    }

    private ClientConnection CreateClientConnection()
    {
        var connectionConfig = new ConnectionConfig
        {
            ApplicationId = _applicationId,
            Host = _host,
            Port = _port
        };

        var channel = new LidgrenClientChannel(connectionConfig);
        return new ClientConnection(channel, new BinaryMessageSerializer());
    }

    [Test]
    public void Should_execute_remote_operations()
    {
        using (var clientConnection = CreateClientConnection())
        {
            clientConnection.Open();

            var remoteExecutor = new RemoteExecutor(clientConnection);

            var calculator = remoteExecutor.GetRemote<ICalculator>();
            var result = calculator.Add(5, 3);
            Assert.AreEqual(8, result);

            var greeter = remoteExecutor.GetRemote<IGreeter>();
            var greeting = greeter.Greet("Alice");
            Assert.AreEqual("Hello, Alice!", greeting);
        }
    }
}

