namespace CollectionExtensionsDemo
{
    public static partial class EnumerableExtensions
    {
        // Extension method that applies a transformation and then retrieves
        // the first element that meets the provided predicate.
        public static TResult First<TSource, TResult>(
            this IEnumerable<TSource> source,
            Func<TSource, TResult> resultSelector,
            Func<TResult, bool> predicate)
        {
            if (source == null)
                throw new ArgumentNullException(nameof(source));
            if (resultSelector == null)
                throw new ArgumentNullException(nameof(resultSelector));
            if (predicate == null)
                throw new ArgumentNullException(nameof(predicate));

            foreach (TSource item in source)
            {
                TResult transformed = resultSelector(item);
                if (predicate(transformed))
                {
                    return transformed;
                }
            }
            throw new InvalidOperationException("No matching element found in the sequence.");
        }

        // Overload extension method that applies a transformation
        // and retrieves the first transformed element.
        public static TResult First<TSource, TResult>(
            this IEnumerable<TSource> source,
            Func<TSource, TResult> resultSelector)
        {
            if (source == null)
                throw new ArgumentNullException(nameof(source));
            if (resultSelector == null)
                throw new ArgumentNullException(nameof(resultSelector));

            foreach (TSource item in source)
            {
                return resultSelector(item);
            }
            throw new InvalidOperationException("The sequence contains no elements.");
        }
    }

    // Example usage demonstrating the extension methods.
    class Service
    {
        static void Main(string[] args)
        {
            List<int> numbers = new List<int> { 1, 2, 3, 4, 5 };

            // Use case: Transform numbers into strings and conditionally select.
            try
            {
                string result = numbers.First(
                    number => $"Number: {number}",
                    str => str.EndsWith("4"));
                Console.WriteLine("First matching transformed element: " + result);
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error (predicate method): " + ex.Message);
            }

using System;
using System.Collections.Generic;
using GenerateLocationData.Model;
using Npgsql;

namespace GenerateLocationData.BAG
{
    public class BagFilter
    {
        private const string Query =
@"SELECT DISTINCT openbareruimtenaam as straat
FROM (SELECT ST_GeomFromText('{0}', 28992) as buurt) as foo, adres
WHERE ST_Contains(buurt, geopunt)";
        private readonly string connectionString;

        public BagFilter(string connectionString)
        {
            this.connectionString = connectionString;
        }

        /// <summary>
        /// Get all CBS neighbourhoods, specifically its name, boundary (in WKT), and center.
        /// </summary>
        public void Enhance(IEnumerable<LocationDescription> locationDescriptions)
        {
            using (var conn = new NpgsqlConnection(connectionString))
            {
                conn.Open();
                var streets = new List<string>();
                foreach (var locationDescription in locationDescriptions)
                {
                    var query = string.Format(Query, locationDescription.RdBoundary);
                    using (var command = new NpgsqlCommand(query, conn))
                    {
                        try
                        {
                            using (var dr = command.ExecuteReader())
                            {
                                while (dr.Read())
                                {
                                    streets.Add(dr["straat"].ToString());
                                }
                            }
                        }
                        catch (SystemException e)
                        {
                            Console.WriteLine(e.Message);
                        }
                    }
                    locationDescription.Features.Add("straten", string.Join(";", streets));
                }
            }
        }
    }
}

using Db4objects.Db4o.Activation;
using Db4objects.Db4o.TA;
using Db4oTool.Core;
using Mono.Cecil;
using Mono.Cecil.Cil;

namespace Db4oTool.TA
{
    internal class ActivateMethodEmitter : MethodEmitter
    {
        public ActivateMethodEmitter(InstrumentationContext context, FieldDefinition field) : base(context, field)
        {
        }

        public MethodDefinition Emit()
        {
            var activate =
                NewExplicitMethod(typeof (IActivatable).GetMethod("Activate", new[] {typeof (ActivationPurpose)}));

            var cil = activate.Body.GetILProcessor();
            cil.Emit(OpCodes.Ldarg_0);
            cil.Emit(OpCodes.Ldfld, _activatorField);

            var ret = cil.Create(OpCodes.Ret);

            cil.Emit(OpCodes.Brfalse, ret);

            cil.Emit(OpCodes.Ldarg_0);
            cil.Emit(OpCodes.Ldfld, _activatorField);
            cil.Emit(OpCodes.Ldarg_1);
            cil.Emit(OpCodes.Callvirt,
                _context.Import(typeof (IActivator).GetMethod("Activate", new[] {typeof (ActivationPurpose)})));

            cil.Append(ret);

            return activate;
        }
    }
}

using System;
using Raksha.Crypto.Engines;
using Raksha.Crypto.Parameters;
using Raksha.Crypto.Utilities;
using Raksha.Utilities;

namespace Raksha.Crypto.Digests
{
    /**
    * implementation of GOST R 34.11-94
    */
    public class Gost3411Digest
        : IDigest
    {
        private const int DIGEST_LENGTH = 32;

        private byte[]  H = new byte[32], L = new byte[32],
                        M = new byte[32], Sum = new byte[32];
        private byte[][] C = MakeC();

        private byte[]  xBuf = new byte[32];
        private int     xBufOff;
        private ulong   byteCount;

        private readonly IBlockCipher cipher = new Gost28147Engine();
        private readonly byte[] sBox;

        private static byte[][] MakeC()
        {
            byte[][] c = new byte[4][];
            for (int i = 0; i < 4; ++i)
            {
                c[i] = new byte[32];
            }
            return c;
        }

        /**
         * Standard constructor
         */
        public Gost3411Digest()
        {
            sBox = Gost28147Engine.GetSBox("D-A");
            cipher.Init(true, new ParametersWithSBox(null, sBox));

            Reset();
        }

        /**
         * Constructor to allow use of a particular sbox with GOST28147
         * @see GOST28147Engine#getSBox(String)
         */
        public Gost3411Digest(byte[] sBoxParam)
        {
            sBox = Arrays.Clone(sBoxParam);
            cipher.Init(true, new ParametersWithSBox(null, sBox));

            Reset();
        }

        /**
         * Copy constructor.  This will copy the state of the provided
         * message digest.
         */
        public Gost3411Digest(Gost3411Digest t)
        {
            this.sBox = t.sBox;
            cipher.Init(true, new ParametersWithSBox(null, sBox));

            Reset();

            Array.Copy(t.H, 0, this.H, 0, t.H.Length);
            Array.Copy(t.L, 0, this.L, 0, t.L.Length);
            Array.Copy(t.M, 0, this.M, 0, t.M.Length);
            Array.Copy(t.Sum, 0, this.Sum, 0, t.Sum.Length);
            Array.Copy(t.C[1], 0, this.C[1], 0, t.C[1].Length);
            Array.Copy(t.C[2], 0, this.C[2], 0, t.C[2].Length);
            Array.Copy(t.C[3], 0, this.C[3], 0, t.C[3].Length);
            Array.Copy(t.xBuf, 0, this.xBuf, 0, t.xBuf.Length);

            this.xBufOff = t.xBufOff;
            this.byteCount = t.byteCount;
        }

        public string AlgorithmName
        {
            get { return "Gost3411"; }
        }

        public int GetDigestSize()
        {
            return DIGEST_LENGTH;
        }

