            argslist.Add(new Tuple<string, object>("c", "hello world"));
            argslist.Add(new Tuple<string, object>("u", "hello \u2641"));
            argslist.Add(new Tuple<string, object>("l", new List<int> { 1, 2, 3, 4, 5 }));
            argslist.Add(new Tuple<string, object>("d", new List<double> { 1.0, 2.0, 3.14 }));

            foreach (var item in argslist)
            {
                Array a = new Array();
                a.ob_item = Marshal.AllocHGlobal(Marshal.SizeOf(item.Item2));
                Marshal.StructureToPtr(item.Item2, a.ob_item, false);
                a.ob_size = Marshal.SizeOf(item.Item2);
                Console.WriteLine(a.ob_item + "\tSize = " + a.ob_size);
                Marshal.FreeHGlobal(a.ob_item);
            }
        }
    }
}

namespace ParquetSharp.Bytes
{
    using System;
    using ParquetSharp.External;

    /**
     * Based on DataOutputStream but in little endian and without the String/char methods
     *
     *
     */
    public class LittleEndianDataOutputStream : OutputStream
    {
        private readonly OutputStream @out;

        /**
         * Creates a new data output stream to write data to the specified
         * underlying output stream. The counter <code>written</code> is
         * set to zero.
         *
         * @param   out   the underlying output stream, to be saved for later
         *                use.
         * @see     java.io.FilterOutputStream#out
         */
        public LittleEndianDataOutputStream(OutputStream @out)
        {
            this.@out = @out;
        }

        /**
         * Writes the specified byte (the low eight bits of the argument
         * <code>b</code>) to the underlying output stream. If no exception
         * is thrown, the counter <code>written</code> is incremented by
         * <code>1</code>.
         * <p>
         * Implements the <code>write</code> method of <code>OutputStream</code>.
         *
         * @param      b   the <code>byte</code> to be written.
         * @exception  IOException  if an I/O error occurs.
         * @see        java.io.FilterOutputStream#out
         */
        public override void WriteByte(byte b)
        {
            @out.WriteByte(b);
        }

        /**
         * Writes <code>len</code> bytes from the specified byte array
         * starting at offset <code>off</code> to the underlying output stream.
         * If no exception is thrown, the counter <code>written</code> is
         * incremented by <code>len</code>.
         *
         * @param      b     the data.
         * @param      off   the start offset in the data.
         * @param      len   the number of bytes to write.
         * @exception  IOException  if an I/O error occurs.
         * @see        java.io.FilterOutputStream#out
         */
        public override void Write(byte[] b, int off, int len)
        {
            @out.Write(b, off, len);
        }

        /**
         * Flushes this data output stream. This forces any buffered output
         * bytes to be written out to the stream.
         * <p>
         * The <code>flush</code> method of <code>DataOutputStream</code>
         * calls the <code>flush</code> method of its underlying output stream.
         *
         * @exception  IOException  if an I/O error occurs.
         * @see        java.io.FilterOutputStream#out

