public class Report
{
    public List<Page> Pages { get; set; }
    public int Width { get; set; }
    public int Height { get; set; }

    public Report(int width, int height)
    {
        Width = width;
        Height = height;
        Pages = new List<Page>();
    }
}

public class Page
{
    public string Content { get; set; }

    public Page(string content)
    {
        Content = content;
    }
}

public class CairoPdfWriter
{
    public byte[] GetFileBytes(Report report)
    {
        string tempFilePath = Path.GetTempFileName();
        try
        {
            using (var surface = new PdfSurface(tempFilePath, report.Width, report.Height))
            {
                using (var context = new Context(surface))
                {
                    RenderReport(context, report);
                }
                surface.Flush();
            }

            return File.ReadAllBytes(tempFilePath);
        }
        finally
        {
            try
            {
                File.Delete(tempFilePath);
            }
            catch
            {
                // Log exception if needed; keeping it silent for cleanup
            }
        }
    }

    private void RenderReport(Context context, Report report)
    {
        foreach (var page in report.Pages)
        {
            context.ShowPage(); // Start a new page in the PDF
            DrawContent(context, page.Content);
        }
    }

    private void DrawContent(Context context, string content)
    {
        // Assuming some font settings here
        context.SelectFontFace("Sans", FontSlant.Normal, FontWeight.Normal);
        context.SetFontSize(12);

        // Move to a start position
        context.MoveTo(50, 50);
        context.ShowText(content);
    }
}

