    {
        Report report = new Report(595, 842); // A4 size in points
        report.Pages.Add(new Page("This is the content of page 1"));
        report.Pages.Add(new Page("This is the content of page 2"));

        var pdfWriter = new CairoPdfWriter();
        byte[] pdfBytes = pdfWriter.GetFileBytes(report);

        // Example of using pdfBytes
        File.WriteAllBytes("output.pdf", pdfBytes);
        Console.WriteLine("PDF generated and saved as output.pdf");
    }
}

