using Microsoft.AspNetCore.Http;
using System;
using System.Collections.Generic;
using System.Text.Json;
using System.Threading.Tasks;

public class JsonWebKeysResult
{
    private readonly IEnumerable<JsonWebKey> _webKeys;
    private readonly int _cacheDurationInMinutes;

    public JsonWebKeysResult(IEnumerable<JsonWebKey> webKeys, int cacheDurationInMinutes = 60)
    {
        _webKeys = webKeys ?? throw new ArgumentNullException(nameof(webKeys));
        _cacheDurationInMinutes = cacheDurationInMinutes;
    }

    public async Task ExecuteAsync(HttpContext context)
    {
        try
        {
            context.Response.ContentType = "application/json";
            SetCacheHeaders(context);

            var keysResponse = new
            {
                keys = _webKeys
            };

            await WriteJsonAsync(context, keysResponse);
        }
        catch (Exception ex)
        {
            context.Response.StatusCode = StatusCodes.Status500InternalServerError;
            await context.Response.WriteAsync($"Error generating JWKS: {ex.Message}");
        }
    }

    private void SetCacheHeaders(HttpContext context)
    {
        var cacheControl = $"public, max-age={_cacheDurationInMinutes * 60}";
        context.Response.Headers.Add("Cache-Control", cacheControl);
        context.Response.Headers.Add("Pragma", "no-cache");
        context.Response.Headers.Add("Expires", "0");
    }

    private async Task WriteJsonAsync(HttpContext context, object keysResponse)
    {
        var jsonOptions = new JsonSerializerOptions
        {
            PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
            WriteIndented = false
        };

        await context.Response.WriteAsync(
            JsonSerializer.Serialize(keysResponse, jsonOptions)
        );
    }
}

