namespace GenuineChannels.Http
{
    /// <summary>
    /// Represents the types of HTTP packets used in client-server communication.
    /// </summary>
    internal enum HttpPacketType
    {
        /// <summary>
        /// Represents a standard, usual HTTP packet.
        /// </summary>
        Usual,

        /// <summary>
        /// Indicates a packet related to listening for incoming requests.
        /// </summary>
        Listening,

        /// <summary>
        /// Indicates a packet used to reset the connection during establishment.
        /// </summary>
        Establishing_ResetConnection,

        /// <summary>
        /// Represents a packet used during the connection establishment phase.
        /// </summary>
        Establishing,

        /// <summary>
        /// Indicates a scenario where double requests are detected.
        /// </summary>
        DoubleRequests,

        /// <summary>
        /// Represents a repeated request packet.
        /// </summary>
        RequestRepeated,

        /// <summary>
        /// Indicates a desynchronization state between client and server.
        /// </summary>
        Desynchronization,

        /// <summary>
        /// Represents a response packet from the sender.
        /// </summary>
        SenderResponse,

        /// <summary>
        /// Indicates that the listener has timed out.
        /// </summary>
        ListenerTimedOut,

        /// <summary>
        /// Represents a packet indicating the connection was closed manually.
        /// </summary>
        ClosedManually,

        /// <summary>
        /// Indicates an error packet from the sender.
        /// </summary>
        SenderError,

        /// <summary>
        /// Represents an unknown or unrecognized packet type.
        /// </summary>
        Unknown
    }
}

using System;
using System.Linq;
using BenchmarkDotNet.Configs;
using BenchmarkDotNet.Jobs;
using BenchmarkDotNet.Exporters;
using Xunit;

namespace BenchmarkDotNet.Tests
{
    public class ConfigParserTests
    {
        [Theory]
        [InlineData("--jobs=dry", "exporters=html,rplot")]
        [InlineData("--jobs=dry", "exporters", "html,rplot")]
        public void SimpleConfigParsedCorrectly(params string[] args)
        {
            var parser = new ConfigParser();
            // We allow args with and without the double dashes (i.e. '--jobs=' and 'jobs=')
            var config = parser.Parse(args);

            Assert.Equal(1, config.GetJobs().Count());
            Assert.Contains(Job.Dry, config.GetJobs());

            Assert.Equal(2, config.GetExporters().Count());
            Assert.Contains(HtmlExporter.Default, config.GetExporters());
            Assert.Contains(RPlotExporter.Default, config.GetExporters());

            Assert.Equal(0, config.GetColumnProviders().Count());
            Assert.Equal(0, config.GetDiagnosers().Count());
            Assert.Equal(0, config.GetAnalysers().Count());
            Assert.Equal(0, config.GetLoggers().Count());
        }

        [Fact]
        public void SimpleConfigAlternativeVersionParserCorrectly()
        {
            var parser = new ConfigParser();
            // To make it easier, we allow "jobs" and "job",
            // plus casing doesn't matter, so "Dry" and "dry" are both valid
            var config = parser.Parse(new[] { "job=Dry" });

            Assert.Equal(1, config.GetJobs().Count());
            Assert.Contains(Job.Dry, config.GetJobs());
        }

        [Fact]
        public void UnknownConfigThrows()
        {
            var parser = new ConfigParser();
            Assert.Throws<InvalidOperationException>(() => parser.Parse(new[] { "jobs=unknown" }));
        }
    }
}

using System;
using System.IO;
using System.Windows.Forms;

public class CodeViewer : UserControl
{
    private TextBox textEditorControl;
    private CodeLocation currentLocation;

    public CodeViewer()
    {
        InitializeComponent();
    }

    private void InitializeComponent()
    {
        this.textEditorControl = new TextBox();
        this.textEditorControl.Multiline = true;
        this.textEditorControl.Dock = DockStyle.Fill;
        this.textEditorControl.ReadOnly = true;
        this.textEditorControl.ScrollBars = ScrollBars.Both;
        this.textEditorControl.KeyDown += TextEditorControl_KeyDown;
        this.Controls.Add(this.textEditorControl);
    }

    public void LoadFile(CodeLocation location)
    {
        if (location == CodeLocation.Unknown || !File.Exists(location.FilePath))
        {
            textEditorControl.Text = "File not found or location unknown.";
            return;
        }

        currentLocation = location;
        textEditorControl.Text = File.ReadAllText(location.FilePath);

        if (location.Line > 0 && location.Column > 0)
        {
            JumpTo(location.Line, location.Column);
        }
    }

    public void JumpTo(int line, int column)
    {
        if (line <= 0 || column <= 0) return;

        int index = GetIndexFromLineAndColumn(line, column);
        if (index >= 0 && index < textEditorControl.Text.Length)
        {
            textEditorControl.SelectionStart = index;
            textEditorControl.SelectionLength = 0;
            textEditorControl.ScrollToCaret();
        }
    }

    private int GetIndexFromLineAndColumn(int line, int column)
    {
        string[] lines = textEditorControl.Text.Split(new[] { Environment.NewLine }, StringSplitOptions.None);
        if (line > lines.Length) return -1;

        int index = 0;
        for (int i = 0; i < line - 1; i++)
        {
            index += lines[i].Length + Environment.NewLine.Length;
        }

        index += Math.Min(column - 1, lines[line - 1].Length);
        return index;
    }

    private void TextEditorControl_KeyDown(object sender, KeyEventArgs e)
    {
        e.SuppressKeyPress = true; // Suppress key presses to prevent editing
    }
}

