namespace ComputerVision
{
    public class Brisk : Feature2D
    {
        private IntPtr _ptr;

        public Brisk(int thresh = 30, int octaves = 3, float patternScale = 1.0f)
        {
            _ptr = cveBriskCreate(thresh, octaves, patternScale);
            if (_ptr == IntPtr.Zero)
                throw new Exception("Failed to create BRISK detector");
        }

        ~Brisk()
        {
            DisposeObject();
        }

        protected override void DisposeObject()
        {
            if (_ptr != IntPtr.Zero)
            {
                cveBriskRelease(ref _ptr);
                _ptr = IntPtr.Zero;
            }
            base.DisposeObject();
        }

        [DllImport("opencv_features2d2413", CallingConvention = CallingConvention.Cdecl)]
        private static extern IntPtr cveBriskCreate(int thresh, int octaves, float patternScale);

        [DllImport("opencv_features2d2413", CallingConvention = CallingConvention.Cdecl)]
        private static extern void cveBriskRelease(ref IntPtr brisk);

        public override IntPtr Ptr
        {
            get { return _ptr; }
        }

        public void DetectAndCompute(IInputArray image, IInputArray mask, out VectorOfKeyPoint keypoints, IOutputArray descriptors, bool useProvidedKeypoints = false)
        {
            if (image == null)
                throw new ArgumentNullException(nameof(image));
            if (mask == null)
                mask = new Mat();
            if (descriptors == null)
                throw new ArgumentNullException(nameof(descriptors));

            keypoints = new VectorOfKeyPoint();
            cveBriskDetectAndCompute(_ptr, image.Ptr, mask.Ptr, keypoints.Ptr, descriptors.Ptr, useProvidedKeypoints ? 1 : 0);
        }

        [DllImport("opencv_features2d2413", CallingConvention = CallingConvention.Cdecl)]
        private static extern void cveBriskDetectAndCompute(IntPtr brisk, IntPtr image, IntPtr mask, IntPtr keypoints, IntPtr descriptors, int useProvidedKeypoints);
    }
}

using System;
