namespace LZW
{
    class Game
    {
        static void Main(string[] args)
        {
            List<int> compressed = compress("TOBEORNOTTOBEORTOBEORNOT");
            Console.WriteLine(compressed);
            string decompressed = decompress(compressed);
            Console.WriteLine(decompressed);
        }

        public static List<int> compress(string uncompressed)
        {
            // Build the dictionary.
            int dictSize = 256;
            Dictionary<string, int> dictionary = new Dictionary<string, int>();
            for (int i = 0; i < 256; i++)
                dictionary.Add("" + (char)i, i);

            string w = "";
            List<int> result = new List<int>();
            foreach (char c in uncompressed.ToCharArray())
            {
                string wc = w + c;
                if (dictionary.ContainsKey(wc))
                    w = wc;
                else
                {
                    result.Add(dictionary[w]);
                    // Add wc to the dictionary.
                    dictionary.Add(wc, dictSize++);
                    w = "" + c;
                }
            }

            // Output the code for w.
            if (!w.Equals(""))
                result.Add(dictionary[w]);
            return result;
        }

        public static string decompress(List<int> compressed)
        {
            // Build the dictionary.
            int dictSize = 256;
            Dictionary<int, string> dictionary = new Dictionary<int, string>();
            for (int i = 0; i < 256; i++)
                dictionary.Add(i, "" + (char)i);

            string w = "" + (char)(int)compressed.Remove(0);
            StringBuilder result = new StringBuilder(w);
            foreach (int k in compressed)
            {
                string entry;
                if (dictionary.ContainsKey(k))
                    entry = dictionary[k];
                else if (k == dictSize)
                    entry = w + w.ElementAt(0);
                else
                    throw new ArgumentException("Bad compressed k: " + k);

                result.Append(entry);

                // Add w+entry[0] to the dictionary.
                dictionary.Add(dictSize++, w + entry.ElementAt(0));

                w = entry;
            }
            return result.ToString();
        }
    }
}

using System.Collections.Generic;
