public class PapyrusParameterEditorViewModel : BaseParameterViewModel
{
    private PapyrusParameterDefinition parameter;
    private string name;
    private bool isArray;
    private string selectedType;
    private List<string> typeReferences;

    public string Name
    {
        get => name;
        set => SetProperty(ref name, value);
    }

    public bool IsArray
    {
        get => isArray;
        set => SetProperty(ref isArray, value);
    }

    public string SelectedType
    {
        get => selectedType;
        set => SetProperty(ref selectedType, value);
    }

    public List<string> TypeReferences
    {
        get => typeReferences;
        set => SetProperty(ref typeReferences, value);
    }

    public PapyrusParameterEditorViewModel(PapyrusParameterDefinition parameter = null)
    {
        TypeReferences = new List<string>
        {
            "int", "float", "bool", "string", "Form", "ObjectReference", "Actor", "ScriptObject"
        };

        if (parameter != null)
        {
            this.parameter = parameter;
            Name = parameter.Name;
            IsArray = parameter.Type.EndsWith("[]");
            SelectedType = IsArray ? parameter.Type.Substring(0, parameter.Type.Length - 2) : parameter.Type;

            if (!TypeReferences.Contains(SelectedType))
            {
                TypeReferences.Add(SelectedType);
            }
        }
        else
        {
            Name = "NewParameter";
            IsArray = false;
            SelectedType = TypeReferences.First();
        }
    }

    public PapyrusParameterDefinition GetParameterDefinition()
    {
        string typeName = IsArray ? $"{SelectedType}[]" : SelectedType;
        return new PapyrusParameterDefinition
        {
            Name = Name,
            Type = typeName
        };
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
 
namespace ProjectEuler
{
    class Problem108
    {
        static ulong mpow(ulong a, ulong p, ulong m)
        {
            ulong r = 1;
            while (p > 0)
            {
                if ((1 & p) == 1) r = r * a % m;
                a = a * a % m;
                p >>= 1;
            }
            return r;
        }
 
        static ulong ipow(ulong a, ulong p)
        {
            ulong r = 1;
            while (p > 0)
            {
                if ((1 & p) == 1) r = r * a;
                a *= a;
                p >>= 1;
            }
            return r;
        }
 
        static ulong gcd(ulong m, ulong n)
        {
            ulong t;
            while (m > 0)
            {
                t = m;
                m = n % m;
                n = t;
            }
            return n;
        }
 
        static ulong lcm(ulong m, ulong n)
        {
            ulong g = gcd(m, n);
            return m / g * n;
        }
 
        static ulong multi_order_p(ulong a, ulong p, ulong e)
        {
            ulong[] fac = new ulong[10000];
            ulong m = ipow(p, e);
            ulong t = m / p * (p - 1);
            int i, len = get_factors(t, fac);
            for (i = 0; i < len; i++)
                if (mpow(a, fac[i], m) == 1)
                    return fac[i];
            return 0;
        }
 
        static ulong multi_order(ulong a, ulong m)
        {
            prime_factor[] pf = new prime_factor[100];
            int i, len = get_prime_factors(m, pf);
            ulong res = 1;
            for (i = 0; i < len; i++)
                res = lcm(res, multi_order_p(a, pf[i].p, pf[i].e));
            return res;
        }
 
        static void Main(string[] args)
        {
            sieve();
            Console.WriteLine(multi_order(37, 1000));
            Console.WriteLine(multi_order(54, 100001));
        }
    }
}

using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Linq;

public class ReadableAndWritablePropertiesTypeInspector : TypeInspectorSkeleton
{
    private readonly ITypeDescriptor _innerTypeDescriptor;

    public ReadableAndWritablePropertiesTypeInspector(ITypeDescriptor innerTypeDescriptor)
    {
        _innerTypeDescriptor = innerTypeDescriptor ?? throw new ArgumentNullException(nameof(innerTypeDescriptor));
    }

    public override IEnumerable<IPropertyDescriptor> GetProperties(Type type, object container)
    {
        var properties = _innerTypeDescriptor.GetProperties(type, container);
        var filteredProperties = properties.Where(p => IsReadableAndWritable(p));
        return filteredProperties.ToList();
    }

    private bool IsReadableAndWritable(IPropertyDescriptor propertyDescriptor)
    {
        return propertyDescriptor.IsReadable && propertyDescriptor.IsWritable;
    }
}

public interface ITypeDescriptor
{
    IEnumerable<IPropertyDescriptor> GetProperties(Type type, object container);
}

public class TypeInspectorSkeleton : ITypeDescriptor
{
    public virtual IEnumerable<IPropertyDescriptor> GetProperties(Type type, object container)
    {
        // This would normally return all properties of the type.
        return TypeDescriptor.GetProperties(type).Cast<PropertyDescriptor>()
            .Select(pd => new PropertyDescriptorWrapper(pd));
    }
}

public interface IPropertyDescriptor
{
    string Name { get; }
    bool IsReadable { get; }
    bool IsWritable { get; }
}

public class PropertyDescriptorWrapper : IPropertyDescriptor
{
    private readonly PropertyDescriptor _propertyDescriptor;

    public PropertyDescriptorWrapper(PropertyDescriptor propertyDescriptor)
    {
        _propertyDescriptor = propertyDescriptor;
    }

    public string Name => _propertyDescriptor.Name;

    public bool IsReadable => _propertyDescriptor.CanRead;

    public bool IsWritable => _propertyDescriptor.CanResetValue && _propertyDescriptor.SetValue != null;
}

// Example usage of the `ReadableAndWritablePropertiesTypeInspector`
public class ExampleUsage
{
    public void Execute()
    {
        var originalInspector = new TypeInspectorSkeleton();
        var customInspector = new ReadableAndWritablePropertiesTypeInspector(originalInspector);

        var properties = customInspector.GetProperties(typeof(SomeClass), null);
        foreach (var property in properties)
        {
            Console.WriteLine(property.Name);
        }
    }
}

