public class Monitor
{
    private bool finish = false;
    private int interval = 1000; // Default interval in milliseconds
    private string filename = "monitor_data.txt";
    private LinkedList<string> processes = new LinkedList<string>();
    private List<MonitorResource> resources = new List<MonitorResource>();

    public void setInterval(int interval)
    {
        this.interval = interval;
    }

    public void setFilename(string filename)
    {
        this.filename = filename;
    }

    public void setProcess(LinkedList<string> processes)
    {
        this.processes = processes;
    }

    public void prepareMonitoring()
    {
        resources.Add(new CPUMonitor());
        resources.Add(new MemoryMonitor());
        resources.Add(new DiskResource());
    }

    public void start()
    {
        Thread monitorThread = new Thread(new ThreadStart(ThreadProc));
        monitorThread.Start();
    }

    public void stop()
    {
        finish = true;
        saveResults();
    }

    private void ThreadProc()
    {
        while (!finish)
        {
            foreach (var resource in resources)
            {
                resource.captureValue();
            }
            Thread.Sleep(interval);
        }
    }

    private void saveResults()
    {
        using (System.IO.StreamWriter file = new System.IO.StreamWriter(filename))
        {
            foreach (var resource in resources)
            {
                file.WriteLine(resource.saveResults());
            }
        }
    }
}

