public class Hamming
{
    public static IEnumerable<int> HammingNumbers()
    {
        var nextHam = 1;
        var queues = new List<Tuple<int, Queue<int>>>
        {
            new Tuple<int, Queue<int>>(2, new Queue<int>()),
            new Tuple<int, Queue<int>>(3, new Queue<int>()),
            new Tuple<int, Queue<int>>(5, new Queue<int>())
        };

        while (true)
        {
            yield return nextHam;

            foreach (var queue in queues)
            {
                queue.Item2.Enqueue(nextHam * queue.Item1);
            }

            nextHam = queues.Select(queue => queue.Item2.Peek()).Min();

            foreach (var queue in queues)
            {
                if (queue.Item2.Peek() == nextHam)
                {
                    queue.Item2.Dequeue();
                }
            }
        }
    }
}

