    {
        private readonly IMenuService _menuService;
        private ShellMenu _menu;

        [ImportingConstructor]
        public MenuRegionAdapter(IRegionBehaviorFactory regionBehaviorFactory, IMenuService menuService)
            : base(regionBehaviorFactory)
        {
            _menuService = menuService;
        }

        protected override void Adapt(IRegion region, ShellMenu regionTarget)
        {
            _menu = regionTarget;
            regionTarget.ItemsSource = new SortedMenuItemCollection();

            region.ActiveViews.CollectionChanged += ActiveViewsOnCollectionChanged;
        }

        private void ActiveViewsOnCollectionChanged(object sender, NotifyCollectionChangedEventArgs e)
        {
            if (e.Action == NotifyCollectionChangedAction.Add)
            {
                foreach (var newItem in e.NewItems)
                {
                    RegisterMenuItem(newItem);
                }
            }
        }

        private void RegisterMenuItem(object view)
        {
            var menuItem = view as IMenuItem;
                _menuService.RegisterMenuItem(_menu, menuItem);
        }
        protected override IRegion CreateRegion()
        {
            return new AllActiveRegion();
        }
    }

    public interface IMenuService
    {
        void RegisterMenuItem(ItemsControl menu, IMenuItem menuItem);
    }
