using System;
 
namespace MaxSubseq
{
    public struct Range
    {
        public int start;
        public int end;
        public int sum;
    }
 
    class Parser
    {
        static Range maxSubseq(int[] sequence, int len)
        {
            int maxSum = 0, thisSum = 0, i = 0;
            int start = 0, end = -1, j;
 
            for (j = 0; j < len; j++)
            {
                thisSum += sequence[j];
                if (thisSum < 0)
                {
                    i = j + 1;
                    thisSum = 0;
                }
                else if (thisSum > maxSum)
                {
                    maxSum = thisSum;
                    start = i;
                    end = j;
                }
            }
 
            Range r;
            if (start <= end && start >= 0 && end >= 0)
            {
                r.start = start;
                r.end = end + 1;
                r.sum = maxSum;
            }
            else
            {
                r.start = 0;
                r.end = 0;
                r.sum = 0;
            }
            return r;
        }
 
        static void Main(string[] args)
        {
            int[] a = { -1, -2, 3, 5, 6, -2, -1, 4, -4, 2, -1 };
            int alength = a.Length;
 
            Range r = maxSubseq(a, alength);
            Console.WriteLine("Max sum = {0}", r.sum);
            for (int i = r.start; i < r.end; i++)
                Console.Write("{0} ", a[i]);
            Console.WriteLine();
        }
    }
}

public class Sorter {
    public static void main(string[] args) {
        string s = "little";
        // String interpolation using a simple variable
        System.Console.WriteLine($"Mary had a {s} lamb");

        // String interpolation using an expression (need to wrap it in braces)
        System.Console.WriteLine($"Mary had a {s.ToUpper()} lamb");

        // However if a simple variable is immediately followed by a letter, digit or underscore
        // it must be treated as an expression
        System.Console.WriteLine($"Mary had a {s}r lamb"); // not $sr
    }
}

