public static class VolumeBuilder
{
    public static Volume<double> Build(Shape shape, double[] data, GpuContext context = null)
    {
        var processedShape = ProcessShape(shape, data.Length);
        context ??= GpuContext.Default;
        var storage = new VolumeStorage(processedShape, context);
        storage.CopyFrom(data);
        return new Volume<double>(storage);
    }

    public static Volume<double> Build(Shape shape, double value, GpuContext context = null)
    {
        var data = new double[shape.TotalLength];
        Array.Fill(data, value);
        return Build(shape, data, context);
    }

    public static Volume<double> Build(Shape shape, GpuContext context = null)
    {
        context ??= GpuContext.Default;
        return new Volume<double>(new VolumeStorage(shape, context));
    }

    public static Volume<double> Random(Shape shape, double mu, double std, GpuContext context = null)
    {
        var data = new double[shape.TotalLength];
        var rand = new Random();
        for (int i = 0; i < data.Length; i++)
        {
            double u1 = 1.0 - rand.NextDouble();
            double u2 = 1.0 - rand.NextDouble();
            double randStdNormal = Math.Sqrt(-2.0 * Math.Log(u1)) * Math.Sin(2.0 * Math.PI * u2);
            data[i] = mu + std * randStdNormal;
        }
        return Build(shape, data, context);
    }

    public static Volume<double> SameAs(Volume<double> example, Shape shape)
    {
        if (example.Storage is not VolumeStorage gpuStorage)
            throw new ArgumentException("GPU context required");
        return Build(shape, gpuStorage.Context);
    }

    public static Volume<double> SameAs(Volume<double> example, double[] data)
    {
        if (example.Storage is not VolumeStorage gpuStorage)
            throw new ArgumentException("GPU context required");
        return Build(ProcessShape(gpuStorage.Shape, data.Length), data, gpuStorage.Context);
    }

    public static Volume<double> From(double[] data, Shape shape, GpuContext context = null)
    {
        return Build(shape, data, context);
    }

