namespace ConvexHull
{
    public class Point : IComparable<Point>
    {
        public int X { get; set; }
        public int Y { get; set; }
 
        public Point(int x, int y)
        {
            X = x;
            Y = y;
        }
 
        public int CompareTo(Point other)
        {
            return X.CompareTo(other.X);
        }
 
        public override string ToString()
        {
            return $"({X}, {Y})";
        }
    }
 
    public class ConvexHull
    {
        private static List<Point> ConvexHull(List<Point> p)
        {
            if (p.Count == 0) return new List<Point>();
            p.Sort();
            var h = new List<Point>();
 
            // lower hull
            foreach (var pt in p)
            {
                while (h.Count >= 2 &&!Ccw(h[h.Count - 2], h[h.Count - 1], pt))
                {
                    h.RemoveAt(h.Count - 1);
                }
                h.Add(pt);
            }
 
            // upper hull
            var t = h.Count + 1;
            for (var i = p.Count - 1; i >= 0; i--)
            {
                var pt = p[i];
                while (h.Count >= t &&!Ccw(h[h.Count - 2], h[h.Count - 1], pt))
                {
                    h.RemoveAt(h.Count - 1);
                }
                h.Add(pt);
            }
 
            h.RemoveAt(h.Count - 1);
            return h;
        }
 
        // ccw returns true if the three points make a counter-clockwise turn
        private static bool Ccw(Point a, Point b, Point c)
        {
            return ((b.X - a.X) * (c.Y - a.Y)) > ((b.Y - a.Y) * (c.X - a.X));
        }
 
        public static void Main(string[] args)
        {
            var points = new List<Point>
            {
                new Point(16, 3),
                new Point(12, 17),
                new Point(0, 6),
                new Point(-4, -6),
                new Point(16, 6),
 
                new Point(16, -7),
                new Point(16, -3),
                new Point(17, -4),
                new Point(5, 19),
                new Point(19, -8),
 
                new Point(3, 16),
                new Point(12, 13),
                new Point(3, -4),
                new Point(17, 5),
                new Point(-3, 15),
 
                new Point(-3, -9),
                new Point(0, 11),
                new Point(-9, -3),
                new Point(-4, -2),
                new Point(12, 10)
            };
 
            var hull = ConvexHull(points);

public static bool perf(int n)
{
    int sum = 0;
    for (int i = 1; i < n; i++)
    {
        if (n % i == 0)
        {
            sum += i;
        }
    }
    return sum == n;
}

