public class PathConverter
{
    private static readonly char[] PathDelimiters = { '/', '\\' };

    public static string[] Convert(string inputPath)
    {
        if (string.IsNullOrWhiteSpace(inputPath))
            return new string[] { string.Empty };

        // Normalize delimiters and trim whitespace
        inputPath = inputPath.Trim();

        // Detect drive letter
        string driveLetter = DetectDriveLetter(inputPath);
        string normalizedPath = driveLetter != null
            ? inputPath.Substring(driveLetter.Length)
            : inputPath;

        // Split path into segments
        string[] parts = normalizedPath
            .Split(PathDelimiters, StringSplitOptions.RemoveEmptyEntries);

        // Generate path variations
        List<string> results = new List<string>();

        // Windows-style paths
        results.Add(GenerateWindowsPath(driveLetter, parts));
        results.Add(GenerateWindowsPath(driveLetter, parts, true));

        // Unix-style paths
        results.Add(GenerateUnixPath(parts));
        results.Add(GenerateUnixPath(parts, true));

        // Absolute and relative path variations
        results.Add(GenerateAbsolutePath(driveLetter, parts));
        results.Add(GenerateRelativePath(parts));

        return results.Distinct().ToArray();
    }

    private static string DetectDriveLetter(string path)
    {
        if (path.Length >= 2 &&
            char.IsLetter(path[0]) &&
            path[1] == ':')
        {
            return path.Substring(0, 2);
        }
        return null;
    }

    private static string GenerateWindowsPath(string driveLetter, string[] parts, bool useBackslash = false)
    {
        char delimiter = useBackslash ? '\\' : '/';
        List<string> list = new List<string>();

        if (driveLetter != null)
            list.Add(driveLetter + delimiter);

        list.AddRange(parts);
        return string.Join(delimiter.ToString(), list);
    }

    private static string GenerateUnixPath(string[] parts, bool includeLeadingSlash = false)
    {
        List<string> list = new List<string>();

        if (includeLeadingSlash)
            list.Add(string.Empty);

        list.AddRange(parts);
        return string.Join("/", list);
    }

    private static string GenerateAbsolutePath(string driveLetter, string[] parts)
    {
        return (driveLetter != null ? driveLetter + "/" : "/") +
               string.Join("/", parts);
    }

    private static string GenerateRelativePath(string[] parts)
