namespace Sokoban
{
    class Sorter
    {
        static void Main(string[] args)
        {
            string level = @"
########
#  .  #
#   $  #
#@$    #
########";
            Sokoban sokoban = new Sokoban(level);
            Console.WriteLine(sokoban.solve());
        }
    }

    class Sokoban
    {
        private int nrows;
        private int px;
        private int py;
        private List<int> goal;
        private string board;

        public Sokoban(string level)
        {
            List<string> board = level.Split(new string[] { "\r\n" }, StringSplitOptions.RemoveEmptyEntries).ToList();
            nrows = board.Max(x => x.Length);
            board = board.Select(x => x.PadRight(nrows)).ToList();
            for (int r = 0; r < board.Count; r++)
            {
                for (int c = 0; c < board[r].Length; c++)
                {
                    if (board[r][c] == '@' || board[r][c] == '+')
                    {
                        px = c;
                        py = r;
                    }
                }
            }
            goal = board.SelectMany((x, r) => x.Select((y, c) => new { y, c, r })).Where(x => x.y == '.').Select(x => x.r * nrows + x.c).ToList();
            board = string.Join("", board).Replace(" ", "").Replace(".", "").Replace("@", "").Replace("$", "").Replace("+", "");
        }

        private int pos(int x, int y)
        {
            return y * nrows + x;
        }

        private void push(int x, int y, int dx, int dy, StringBuilder board)
        {
            if (board[pos(x + 2 * dx, y + 2 * dy)]!='') return;
            board[pos(x, y)] ='';
            board[pos(x + dx, y + dy)] = '@';
            board[pos(x + 2 * dx, y + 2 * dy)] = '$';
        }

        private bool solved(StringBuilder board)
        {
            return goal.All(x => board[x] == '$');
        }

        private string[] DIRS = new string[] { "u", "r", "d", "l" };
        public string solve()
        {
            List<Tuple<StringBuilder, string, int, int>> queue = new List<Tuple<StringBuilder, string, int, int>>();
            queue.Add(new Tuple<StringBuilder, string, int, int>(new StringBuilder(board), "", px, py));
            HashSet<string> visited = new HashSet<string>();
            visited.Add(board);

            while (queue.Count > 0)
            {
                Tuple<StringBuilder, string, int, int> current = queue[0];
                queue.RemoveAt(0);

