using System;
using System.Numerics;
 
namespace RosettaCode
{
    class Vector
    {
        static void Main(string[] args)
        {
            string msg = "Rosetta Code";
 
            BigInteger n = BigInteger.Parse("9516311845790656153499716760847001433441357");
            BigInteger e = BigInteger.Parse("65537");
            BigInteger d = BigInteger.Parse("5617843187844953170308463622230283376298685");
 
            BigInteger msgInt = BigInteger.Parse(msg);
            BigInteger enc = ModExp(msgInt, e, n);
            BigInteger dec = ModExp(enc, d, n);
            string msgDec = dec.ToString();
 
            Console.WriteLine("msg as txt: {0}", msg);
            Console.WriteLine("msg as num: {0}", msgInt);
            Console.WriteLine("enc as num: {0}", enc);
            Console.WriteLine("dec as num: {0}", dec);
            Console.WriteLine("dec as txt: {0}", msgDec);
        }
 
        static BigInteger ModExp(BigInteger b, BigInteger e, BigInteger n)
        {
            if (n == 0)
            {
                throw new ArgumentException("modulus is zero");
            }
            if (b >= n)
            {
                // base is too large and should be split into blocks
                throw new ArgumentException("base is >= modulus");
            }
            if (BigInteger.GreatestCommonDivisor(b, n)!= 1)
            {
                throw new ArgumentException("base and modulus are not relatively prime");
            }
 
            BigInteger bb = b;
            BigInteger ee = e;
            BigInteger result = 1;
            while (ee!= 0)
            {
                if (ee % 2 == 1)
                {
                    result = (result * bb) % n;
                }
                ee >>= 1;
                bb = (bb * bb) % n;
            }
            return result;
        }
    }
}

using System;
using System.Collections.Generic;
 
public class Node
{
    public int val;
    public Node back;
 
    public Node(int val)
    {
        this.val = val;
    }
}
 
public class Service
{
    public static void Main()
    {
        Console.WriteLine(string.Join(", ", lis(new int[] { 3, 2, 6, 4, 5, 1 })));
        Console.WriteLine(string.Join(", ", lis(new int[] { 0, 8, 4, 12, 2, 10, 6, 14, 1, 9, 5, 13, 3, 11, 7, 15 })));
    }
 
    public static List<int> lis(int[] n)
    {
        List<Node> pileTops = new List<Node>();
        // sort into piles
        for (int i = 0; i < n.Length; i++)
        {
            // binary search
            int low = 0, high = pileTops.Count - 1;
            while (low <= high)
            {
                int mid = low + (high - low) / 2;
                if (pileTops[mid].val >= n[i])
                {
                    high = mid - 1;
                }
                else
                {
                    low = mid + 1;
                }
            }
            int index = low;
            Node node = new Node(n[i]);
            if (index > 0)
            {
                node.back = pileTops[index - 1];
            }
            pileTops[index] = node;
        }
 
        List<int> result = new List<int>();
        Node node = pileTops[pileTops.Count - 1];
        while (node!= null)
        {
            result.Insert(0, node.val);
            node = node.back;
        }
        return result;
    }
}

