using System;
using System.Collections.Generic;
using System.Linq;
using Hatfield.EnviroData.WQDataProfile;
using Hatfield.EnviroData.QualityAssurance.DataQualityCheckingRules;

public class GetWaterQualityActionDataByIdsCriteria
{
    private readonly IWQDataRepository _wqDataRepository;
    private readonly ChemistryValueCheckingRule _chemistryValueCheckingRule;

    public GetWaterQualityActionDataByIdsCriteria(IWQDataRepository wqDataRepository, ChemistryValueCheckingRule chemistryValueCheckingRule)
    {
        _wqDataRepository = wqDataRepository ?? throw new ArgumentNullException(nameof(wqDataRepository));
        _chemistryValueCheckingRule = chemistryValueCheckingRule ?? throw new ArgumentNullException(nameof(chemistryValueCheckingRule));
    }

    public string CriteriaDescription => "Fetches water quality actions based on specific action IDs provided by the quality assurance rule.";

    public IEnumerable<WaterQualitySampleDataAction> FetchData()
    {
        var allWQSampleDataActions = _wqDataRepository.GetAllWaterQualitySampleDataActions();
        var result = new List<WaterQualitySampleDataAction>();

        if (_chemistryValueCheckingRule.ActionIds == null || !_chemistryValueCheckingRule.ActionIds.Any())
        {
            throw new InvalidOperationException("No action IDs provided in the quality assurance rule.");
        }

        foreach (var actionId in _chemistryValueCheckingRule.ActionIds)
        {
            var matchingAction = allWQSampleDataActions.FirstOrDefault(action => action.ActionId == actionId);
            if (matchingAction != null)
            {
                result.Add(matchingAction);
            }
        }

        return result;
    }
}

