using AutoMapper;

namespace DomainMappingExample
{
    // Interface ensuring consistency for domain entities
    public interface IEntity
    {
        string Version { get; set; }
        int BuildNumber { get; set; }
        string Configuration { get; set; }
    }

    // Domain model representing a specific entity
    public class DomainModel : IEntity
    {
        public string Version { get; set; }
        public int BuildNumber { get; set; }
        public string Environment { get; set; }
        public string Configuration { get; set; }
        public DateTime ReleaseDate { get; set; }
        public List<string> Features { get; set; }

        // Static method to configure mapping from a DTO to this model
        public static void ConfigureMapping(IMapperConfigurationExpression cfg)
        {
            // Create a mapping between DataTransferObject and DomainModel
            cfg.CreateMap<DataTransferObject, DomainModel>()
                .ForMember(dest => dest.Version, opt => opt.MapFrom(src => src.VersionInfo))
                .ForMember(dest => dest.BuildNumber, opt => opt.MapFrom(src => src.BuildId))
                .ForMember(dest => dest.Environment, opt => opt.MapFrom(src => src.DeploymentEnvironment))
                .ForMember(dest => dest.Configuration, opt => opt.MapFrom(src => src.ConfigSettings))
                .ForMember(dest => dest.ReleaseDate, opt => opt.MapFrom(src => src.DateReleased))
                .ForMember(dest => dest.Features, opt => opt.MapFrom(src => src.FeatureList))
                .AfterMap((src, dest) => SetAdditionalMappings(src, dest));
        }

        // Private generic method responsible for additional mapping configurations
        private static void SetAdditionalMappings<T>(T source, DomainModel dest) where T : IDataTransferObject
        {
            // Example: if the DTO implements extra data, we could use it here.
            if (source.ExtraInfo != null)
            {
                // Append extra info to configuration settings (if needed)
                dest.Configuration += " | " + source.ExtraInfo;
            }
        }
    }

    // Contract for the data transfer object to ensure required properties
    public interface IDataTransferObject
    {
        string VersionInfo { get; }
        int BuildId { get; }
        string DeploymentEnvironment { get; }
        string ConfigSettings { get; }
        DateTime DateReleased { get; }
        List<string> FeatureList { get; }
        string ExtraInfo { get; }
    }

