using System;
using System.Collections.Generic;
using OpenMetaverse;
using OpenSim.Framework;

public delegate void ConsoleMessage(UUID agentId, string message);

public interface IRegionConsole
{
    event ConsoleMessage OnConsoleOutput;

    bool RunCommand(UUID agentId, string command);
    void SendConsoleOutput(UUID agentId, string message);
    void AddCommand(string commandName, string helpText, Func<UUID, string[], bool> commandHandler);
    string GetCommandHelp(string commandName);
}

public class RegionConsoleManager : IRegionConsole
{
    private Dictionary<string, CommandInfo> _registeredCommands;
    public event ConsoleMessage OnConsoleOutput;

    public RegionConsoleManager()
    {
        _registeredCommands = new Dictionary<string, CommandInfo>();
        InitializeDefaultCommands();
    }

    private void InitializeDefaultCommands()
    {
        AddCommand("help", "Display available commands", HandleHelpCommand);
        AddCommand("status", "Show region status", HandleStatusCommand);
    }

    public bool RunCommand(UUID agentId, string command)
    {
        string[] parts = command.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
        if (parts.Length == 0) return false;

        string commandName = parts[0].ToLower();
        string[] args = parts.Length > 1 ? parts[1..] : Array.Empty<string>();

        if (_registeredCommands.TryGetValue(commandName, out CommandInfo cmdInfo))
        {
            return cmdInfo.Handler(agentId, args);
        }

        SendConsoleOutput(agentId, $"Unknown command: {commandName}");
        return false;
    }

    public void SendConsoleOutput(UUID agentId, string message)
    {
        OnConsoleOutput?.Invoke(agentId, message);
    }

    public void AddCommand(string commandName, string helpText, Func<UUID, string[], bool> commandHandler)
    {
        _registeredCommands[commandName.ToLower()] = new CommandInfo
        {
            Name = commandName,
            HelpText = helpText,
            Handler = commandHandler
        };
    }

    public string GetCommandHelp(string commandName)
    {
        return _registeredCommands.TryGetValue(commandName.ToLower(), out CommandInfo cmdInfo)
            ? cmdInfo.HelpText
            : "Command not found";
    }

    private bool HandleHelpCommand(UUID agentId, string[] args)
    {
        foreach (var cmd in _registeredCommands)
