    public class OverUnderProgram
    {
        private static int _number;
        private readonly GameLoop _gameLoop;

        public OverUnderProgram(GameLoop gameLoop)
        {
            _gameLoop = gameLoop;
            _number = new StaticRandomNumberValueProvider().Provide();
        }

        public void StartGame()
        {
            Console.WriteLine("Welcome to the Number Guessing Game!");
            _gameLoop.Run();
        }
