    public class GameLoop
    {
        private readonly YouWin _youWin;
        private readonly TooLow _tooLow;
        private readonly TooHigh _tooHigh;

        public GameLoop(YouWin youWin, TooLow tooLow, TooHigh tooHigh)
        {
            _youWin = youWin;
            _tooLow = tooLow;
            _tooHigh = tooHigh;
        }

        public void Run()
        {
            while (true)
            {
                Console.Write("Guess a number between 1 and 100: ");
                if (int.TryParse(Console.ReadLine(), out int guess))
                {
                    if (guess < OverUnderProgram._number)
                    {
                        Console.WriteLine(_tooLow.Provide());
                    }
                    else if (guess > OverUnderProgram._number)
                    {
                        Console.WriteLine(_tooHigh.Provide());
                    }
                    else
                    {
                        Console.WriteLine(_youWin.Provide());
                        break;
                    }
                }
                else
                {
                    Console.WriteLine("Please enter a valid number.");
                }
            }
        }
    }

