using Avalonia.Media;
using Avalonia.Platform;
using Avalonia.Rendering.Utilities;
using Cairo;

public class ImageBrushImpl
{
    private Bitmap _bitmap;
    private Size _targetSize;
    private TilingMode _tilingMode;
    private Context _context;

    public ImageBrushImpl(Bitmap bitmap, Size targetSize, TilingMode tilingMode)
    {
        _bitmap = bitmap;
        _targetSize = targetSize;
        _tilingMode = tilingMode;
    }

    public void Render(Context context)
    {
        _context = context;
        CalculateAndDraw();
    }

    private void CalculateAndDraw()
    {
        var intermediate = new Cairo.ImageSurface(_bitmap, _bitmap.Width, _bitmap.Height);
        double width = _targetSize.Width;
        double height = _targetSize.Height;

        PushClip(new Rect(0, 0, width, height));

        switch (_tilingMode)
        {
            case TilingMode.Repeat:
                DrawImage(intermediate, width, height);
                break;
            case TilingMode.Reflect:
                DrawReflectedImage(intermediate, width, height);
                break;
        }

        PopClip();
    }

    private void PushClip(Rect rect)
    {
        _context.Save();
        _context.Rectangle(rect.X, rect.Y, rect.Width, rect.Height);
        _context.Clip();
    }

    private void DrawImage(ImageSurface surface, double width, double height)
    {
        for (double x = 0; x < width; x += surface.Width)
        {
            for (double y = 0; y < height; y += surface.Height)
            {
                _context.SetSource(surface, x, y);
                _context.Paint();
            }
        }
    }

    private void DrawReflectedImage(ImageSurface surface, double width, double height)
    {
        for (double x = 0; x < width; x += surface.Width)
        {
            for (double y = 0; y < height; y += surface.Height)
            {
                _context.SetSource(surface, x, y);
                _context.Paint();
                _context.SetSource(surface, x + surface.Width, y);
                _context.Scale(-1, 1);
                _context.Paint();
                _context.Scale(-1, 1);
            }
        }
    }

    private void PopClip()
    {
        _context.Restore();
    }

    private void InitTranslate(double x, double y)
    {
        _context.Translate(x, y);
    }
}

public enum TilingMode
{
    Repeat,
    Reflect
}

