using System;
using System.Collections.Generic;
using System.Net;
using System.Net.Sockets;

public class ClientData
{
    private enum ClientState
    {
        Header,
        Body,
        Completed
    }

    private HttpRequest request;
    private ClientState state;
    private IPEndPoint clientEndpoint;
    private int bytesRead;
    private int totalBytes;

    public ClientData(ClientInfo clientInfo)
    {
        clientEndpoint = clientInfo.Endpoint;
        request = new HttpRequest();
        state = ClientState.Header;
        bytesRead = 0;
        totalBytes = 0;
    }

    public void ProcessRequest(Socket clientSocket)
    {
        try
        {
            while (state != ClientState.Completed)
            {
                switch (state)
                {
                    case ClientState.Header:
                        ReadHeaders(clientSocket);
                        break;
                    case ClientState.Body:
                        ReadBody(clientSocket);
                        break;
                }
            }
            // Handle completed request
            HandleCompletedRequest();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error processing request: {ex.Message}");
        }
    }

    private void ReadHeaders(Socket clientSocket)
    {
        byte[] buffer = new byte[1024];
        bytesRead = clientSocket.Receive(buffer);
        string headerData = System.Text.Encoding.UTF8.GetString(buffer, 0, bytesRead);

        // Assume header parsing is done here
        request.ParseHeaders(headerData);

        if (request.IsHeaderComplete)
        {
            state = ClientState.Body;
            totalBytes = request.ContentLength;
        }
    }

    private void ReadBody(Socket clientSocket)
    {
        byte[] buffer = new byte[1024];
        int bytesToRead = Math.Min(buffer.Length, totalBytes - bytesRead);
        bytesRead += clientSocket.Receive(buffer, 0, bytesToRead, SocketFlags.None);

        // Assume body processing is done
        request.ProcessBody(buffer, bytesRead);

        if (bytesRead >= totalBytes)
        {
            state = ClientState.Completed;
        }
    }

    private void HandleCompletedRequest()
    {
        // Handle completed request logic, e.g., routing and response
        Console.WriteLine($"Request from {clientEndpoint} completed.");
    }
}

