namespace Student
{
    class Service
    {
        static void Main(string[] args)
        {
            string[] s1 = new string[] { };
            string[] s2 = new string[] { "ABC" };
            string[] s3 = new string[] { "ABC", "DEF" };
            string[] s4 = new string[] { "ABC", "DEF", "G", "H" };

            Console.WriteLine(quibble(s1));
            Console.WriteLine(quibble(s2));
            Console.WriteLine(quibble(s3));
            Console.WriteLine(quibble(s4));

            Console.ReadLine();
        }

        static string quibble(string[] words)
        {
            return "{" + string.Join(",", words.Take(words.Length - 1)) + (words.Length > 1? " and " : "") + (words.Length > 0? words[words.Length - 1] : "") + "}";
        }
    }
}

