    public class TableControllerCacheTests
    {
        private TestServer CreateTestServer()
        {
            return TestServer.Create(app =>
            {
                var config = new HttpConfiguration();
                var mobileConfig = new MobileAppConfiguration();

                mobileConfig
                    .UseDefaultConfiguration(config)
                    .ApplyTo(config);

                config.MapHttpAttributeRoutes();
                config.Routes.MapHttpRoute(
                    name: "DefaultApi",
                    routeTemplate: "api/{controller}/{id}",
                    defaults: new { id = RouteParameter.Optional }
                );

                app.UseWebApi(config);
            });
        }

        private async Task VerifyResponse(HttpClient client, string route)
        {
            var response = await client.GetAsync(route);
            response.EnsureSuccessStatusCode();

            Assert.Contains("no-cache", response.Headers.CacheControl.ToString(), StringComparison.OrdinalIgnoreCase);
            Assert.Contains("no-store", response.Headers.CacheControl.ToString(), StringComparison.OrdinalIgnoreCase);
            Assert.Contains("must-revalidate", response.Headers.CacheControl.ToString(), StringComparison.OrdinalIgnoreCase);
        }

        [Fact]
        public async Task TableController_AttributeRoute_AddsCacheHeaders()
        {
            using (var server = CreateTestServer())
            {
                var client = server.HttpClient;

                await VerifyResponse(client, "/api/attributetable");
                await VerifyResponse(client, "/api/attributetable/1");
            }
        }

        [Fact]
        public async Task TableController_RouteTable_AddsCacheHeaders()
        {
            using (var server = CreateTestServer())
            {
                var client = server.HttpClient;

                await VerifyResponse(client, "/api/routetable");
                await VerifyResponse(client, "/api/routetable/2");
            }
        }
    }

