namespace XfsFileSystem.Configuration
{
    /// <summary>
    /// Represents configuration options for the XFS file system.
    /// </summary>
    public sealed class XfsFileSystemOptions
    {
        /// <summary>
        /// Gets the character encoding used for file names.
        /// </summary>
        public Encoding FileNameEncoding { get; private set; }

        /// <summary>
        /// Gets a value indicating whether a custom encoding is configured.
        /// </summary>
        public bool HasCustomEncoding { get; private set; }

        /// <summary>
        /// Initializes a new instance of the XfsFileSystemOptions with default UTF-8 encoding.
        /// </summary>
        public XfsFileSystemOptions()
        {
            FileNameEncoding = Encoding.UTF8;
            HasCustomEncoding = false;
        }

        /// <summary>
        /// Initializes a new instance of the XfsFileSystemOptions with optional custom encoding.
        /// </summary>
        /// <param name="parameters">File system configuration parameters.</param>
        public XfsFileSystemOptions(FileSystemParameters parameters)
        {
            if (parameters == null)
            {
                FileNameEncoding = Encoding.UTF8;
                HasCustomEncoding = false;
                return;
            }

            try
            {
                FileNameEncoding = parameters.Encoding ?? Encoding.UTF8;
                HasCustomEncoding = parameters.Encoding != null;
            }
            catch (Exception ex)
            {
                // Fallback to default UTF-8 encoding if initialization fails
                FileNameEncoding = Encoding.UTF8;
                HasCustomEncoding = false;

                // Optional: Log the exception for diagnostics
                OnEncodingConfigurationError(ex);
            }
        }

        /// <summary>
        /// Validates the configured file name encoding.
        /// </summary>
        /// <returns>True if encoding is valid, otherwise false.</returns>
        public bool ValidateEncoding()
        {
            try
            {
                var testBytes = FileNameEncoding.GetBytes("Test");
                return testBytes.Length > 0;
            }
            catch
            {
                return false;
            }
        }

        /// <summary>
        /// Handles encoding configuration errors.
        /// </summary>
        /// <param name="exception">The exception that occurred during encoding configuration.</param>

