namespace LoggingFramework
{
    public class LoggingEventData
    {
        public string Domain { get; set; }
        public string User { get; set; }
        public string Method { get; set; }
        public string File { get; set; }
        public int LineNumber { get; set; }
        public Level Severity { get; set; }
        public string Message { get; set; }
        public Exception Exception { get; set; }
    }

    public class LocationInfo
    {
        public string ClassName { get; set; }
        public string MethodName { get; set; }
        public string FileName { get; set; }
        public int LineNumber { get; set; }
    }

    public static class LoggingEventBuilder
    {
        public static LoggingEventData Build(Level severity, string message, Exception ex = null)
        {
            // Get the calling method information using stack frame.
            StackFrame frame = new StackFrame(2, true);
            var method = frame.GetMethod();
            var location = new LocationInfo
            {
                ClassName = method.DeclaringType != null ? method.DeclaringType.FullName : "UnknownClass",
                MethodName = method.Name,
                FileName = frame.GetFileName() ?? "UnknownFile",
                LineNumber = frame.GetFileLineNumber()
            };

            // Gather user and domain details.
            string domainName = AppDomain.CurrentDomain.FriendlyName;
            string userName = Thread.CurrentPrincipal != null && Thread.CurrentPrincipal.Identity != null
                ? Thread.CurrentPrincipal.Identity.Name
                : "UnknownUser";

            // Sanitize message by escaping characters that can cause issues.
            string safeMessage = Sanitize(message);
            // Fallback to exception message if necessary.
            if (string.IsNullOrEmpty(safeMessage) && ex != null)
            {
                safeMessage = Sanitize(ex.Message);
            }

            // Build the logging event data.
            var logEventData = new LoggingEventData
            {
                Domain = domainName,
                User = userName,
                Method = location.ClassName + "." + location.MethodName,
                File = location.FileName,
                LineNumber = location.LineNumber,
                Severity = severity,
                Message = safeMessage,
                Exception = ex
            };

