    [AttributeUsage(AttributeTargets.Class | AttributeTargets.Method, Inherited = false, AllowMultiple = true)]
    public class WebDavAttribute : Attribute
    {
        public string Server { get; private set; }
        public string ConfigurationCategory { get; private set; }

        public WebDavAttribute(string server, string category = "default")
        {
            Server = server;
            ConfigurationCategory = category;
        }
    }

    public class WebDavConfiguration
    {
        private static WebDavConfiguration _instance;
        public static WebDavConfiguration Current => _instance ?? (_instance = new WebDavConfiguration());

        public string Server { get; private set; }
        public string UserName { get; private set; }
        public string Password { get; private set; }

        private WebDavConfiguration()
        {
            LoadDefaultConfiguration();
        }

        private void LoadDefaultConfiguration()
        {
            Server = ConfigurationManager.AppSettings["WebDavServer"] ?? "localhost";
            UserName = ConfigurationManager.AppSettings["WebDavUsername"] ?? "admin";
            Password = ConfigurationManager.AppSettings["WebDavPassword"] ?? string.Empty;
        }

        public void Resolve(MemberInfo memberInfo)
        {
            var webDavAttributes = memberInfo.GetCustomAttributes<WebDavAttribute>(false);

            foreach (var attribute in webDavAttributes)
            {
                if (!string.IsNullOrEmpty(attribute.Server))
                {
                    Server = attribute.Server;
                }

                if (!string.IsNullOrEmpty(attribute.ConfigurationCategory))
                {
                    ResolveConfigurationByCategory(attribute.ConfigurationCategory);
                }
            }
        }

        private void ResolveConfigurationByCategory(string category)
        {
            try
            {
                var addinRegistry = AddinRegistry.GetGlobalRegistry();
                var extension = addinRegistry.GetExtensions<IWebDavConfigurationProvider>()
                    .FirstOrDefault(p => p.CanResolve(category));

                if (extension != null)
                {
                    var config = extension.Resolve(category);
                    Server = config.Server ?? Server;
                    UserName = config.UserName ?? UserName;
                    Password = config.Password ?? Password;

