namespace SAPManagementTool
{
    public partial class SAPSessionInfo : UserControl
    {
        private GuiSession _activeSession;
        private readonly List<GuiSession> _trackedSessions = new List<GuiSession>();

        public SAPSessionInfo()
        {
            InitializeComponent();
            SAPAutomationHelper.OnSetSession += Current_OnSetSession;
            lv_SessionInfo.ItemsSource = new List<SessionProperty>();
        }

        private void Current_OnSetSession(GuiSession session)
        {
            if (_trackedSessions.Contains(session)) return;

            _trackedSessions.Add(session);
            _activeSession = session;
            session.EndRequest += session_EndRequest;
            session.Destroy += session_Destroy;
            UpdateSessionDisplay();
        }

        private void session_EndRequest()
        {
            UpdateSessionDisplay();
        }

        private void session_Destroy()
        {
            Dispatcher.BeginInvoke(DispatcherPriority.Normal, new Action(() =>
            {
                _trackedSessions.Remove(_activeSession);
                _activeSession = null;
                lv_SessionInfo.ItemsSource = null;
            }));
        }

        private void UpdateSessionDisplay()
        {
            if (_activeSession == null) return;

            var properties = new List<SessionProperty>();
            foreach (PropertyInfo prop in _activeSession.GetType().GetProperties(BindingFlags.Public | BindingFlags.Instance))
            {
                try
                {
                    properties.Add(new SessionProperty(
                        prop.Name,
                        prop.GetValue(_activeSession)?.ToString() ?? "[Null]"
                    ));
                }
                catch (Exception ex)
                {
                    properties.Add(new SessionProperty(prop.Name, $"Error: {ex.Message}"));
                }
            }

            Dispatcher.Invoke(() =>
            {
                lv_SessionInfo.ItemsSource = properties;
                lv_SessionInfo.Items.Refresh();
            });
        }
    }

    public class SessionProperty
    {
        public string Key { get; set; }
        public string Value { get; set; }

        public SessionProperty(string key, string value)
        {
            Key = key;
            Value = value;
        }

