using System.Collections.Generic;
using System.ComponentModel.Composition.Hosting;
using System.Diagnostics;
using LBi.Cli.Arguments;

public abstract class Command
{
    [Switch("quiet", Help = "Suppresses all output except errors and warnings.")]
    public bool Quiet { get; set; }

    [Switch("verbose", Help = "Enables detailed diagnostic output.")]
    public bool Verbose { get; set; }

    public void Invoke(CompositionContainer container)
    {
        IEnumerable<TraceSource> traceSources = container.GetExportedValues<TraceSource>();
        this.ConfigureTraceLevels(traceSources);
        this.Execute(container);
    }

    protected abstract void Execute(CompositionContainer container);

    protected void ConfigureTraceLevels(IEnumerable<TraceSource> traceSources)
    {
        SourceLevels level;

        if (this.Quiet)
            level = SourceLevels.Error | SourceLevels.Warning;
        else if (this.Verbose)
            level = SourceLevels.Verbose;
        else
            level = SourceLevels.Information | SourceLevels.ActivityTracing;

        foreach (TraceSource traceSource in traceSources)
            traceSource.Switch.Level = level;
    }
}

