    /// <summary>
    /// Represents a qualified context pairing a module/member name with a parser rule context.
    /// </summary>
    public class QualifiedContext : IEquatable<QualifiedContext>
    {
        public string ModuleName { get; }
        public string MemberName { get; }
        public ParserRuleContext Context { get; }

        /// <summary>
        /// Initializes a new instance using an explicit module name and parsing context.
        /// </summary>
        public QualifiedContext(string moduleName, ParserRuleContext context)
        {
            if (string.IsNullOrEmpty(moduleName))
                throw new ArgumentException("Module name cannot be null or empty", nameof(moduleName));

            ModuleName = moduleName;
            MemberName = null;
            Context = context ?? throw new ArgumentNullException(nameof(context));
        }

        /// <summary>
        /// Initializes a new instance using a member name and parsing context.
        /// The module name is derived from the member name.
        /// </summary>
        public QualifiedContext(string memberName, ParserRuleContext context, bool isMemberName)
        {
            if (string.IsNullOrEmpty(memberName))
                throw new ArgumentException("Member name cannot be null or empty", nameof(memberName));

            // In this simple model, we derive module name from the member name.
            MemberName = memberName;
            ModuleName = DeriveModuleName(memberName);
            Context = context ?? throw new ArgumentNullException(nameof(context));
        }

        private string DeriveModuleName(string memberName)
        {
            // Dummy implementation: assume the module name is the part before a dot.
            int dotIndex = memberName.IndexOf('.');
            return dotIndex > 0 ? memberName.Substring(0, dotIndex) : "DefaultModule";
        }

        public override bool Equals(object obj)
        {
            return Equals(obj as QualifiedContext);
        }

        public bool Equals(QualifiedContext other)
        {
            if (ReferenceEquals(other, null)) return false;
            if (ReferenceEquals(this, other)) return true;

            return string.Equals(ModuleName, other.ModuleName, StringComparison.Ordinal) &&
                   string.Equals(MemberName, other.MemberName, StringComparison.Ordinal) &&
                   Equals(Context, other.Context);
        }

