using Rubberduck.VBEditor;
using System;

namespace Rubberduck.Inspections
{
    public class IgnoreOnceQuickFix : CodeInspectionQuickFix
    {
        private readonly ParserRuleContext _context;
        private readonly QualifiedSelection _selection;
        private readonly string _inspectionName;
        private readonly string _annotationText;

        public IgnoreOnceQuickFix(ParserRuleContext context, QualifiedSelection selection, string inspectionName)
        {
            _context = context;
            _selection = selection;
            _inspectionName = inspectionName;
            _annotationText = $"@Ignore {inspectionName}";
        }

        public override void Fix()
        {
            if (_selection.SelectionType == SelectionType.QualifiedModuleName || _selection.SelectionType == SelectionType.Project)
            {
                throw new InvalidOperationException("Ignore once cannot be applied at module or project level.");
            }

            var module = _selection.QualifiedName.Component.CodeModule;
            var line = _selection.Selection.StartLine;
            var existingLine = module.get_Lines(line, 1);

            if (existingLine.Contains("@Ignore"))
            {
                var existingAnnotations = existingLine.Split(new[] { '@' }, StringSplitOptions.RemoveEmptyEntries);
                var newAnnotations = string.Join("@", existingAnnotations) + "@" + _annotationText;
                module.ReplaceLine(line, newAnnotations.TrimStart('@'));
            }
            else
            {
                module.InsertLines(line, _annotationText);
            }
        }

        public override string Description => $"Ignore {_inspectionName} once.";
    }
}

