public class SuperWeaponType : AbstractType
{
    private readonly Dictionary<string, object> _properties;
    private readonly IConfigurationSection _configuration;

    public SuperWeaponType(IConfigurationSection configuration)
    {
        _configuration = configuration;
        _properties = new Dictionary<string, object>();
        LoadRules();
    }

    private void LoadRules()
    {
        WeaponType = GetEnum<WeaponType>("WeaponType", WeaponType.Undefined);
        ActionType = GetEnum<Action>("ActionType", Action.None);

        Sound = LoadSound("Sound");
        BuildingType = GetReference<BuildingType>("BuildingType");

        Damage = Get<int>("Damage", 0);
        Range = Get<double>("Range", 1000.0);
        ReloadTime = Get<TimeSpan>("ReloadTime", TimeSpan.FromSeconds(30));

        RequiredTechnology = GetStringArray("RequiredTechnology");
        IsLaunchable = Get<bool>("IsLaunchable", false);
        MaxSimultaneousLaunches = Get<int>("MaxSimultaneousLaunches", 1);

        LoadAdditionalProperties();
    }

    private void LoadAdditionalProperties()
    {
        foreach(var key in _configuration.GetKeys())
        {
            if (!_properties.ContainsKey(key))
            {
                _properties[key] = _configuration.GetValue(key);
            }
        }
    }

    private T GetEnum<T>(string key, T defaultValue) where T : struct
    {
        string value = _configuration.GetValue(key);
        return Enum.TryParse(value, out T result) ? result : defaultValue;
    }

    private T Get<T>(string key, T defaultValue)
    {
        return _configuration.TryGetValue(key, out T value) ? value : defaultValue;
    }

    private Sound LoadSound(string key)
    {
        string soundFile = _configuration.GetValue(key);
        return soundFile != null ? new Sound(soundFile) : null;
    }

    private T GetReference<T>(string key) where T : class
    {
        string referenceName = _configuration.GetValue(key);
        return referenceName != null ? ReferenceManager.Get<T>(referenceName) : null;
    }

    private string[] GetStringArray(string key)
    {
        return _configuration.GetValue(key)?.Split(',') ?? Array.Empty<string>();
    }

    public WeaponType WeaponType { get; private set; }
    public Action ActionType { get; private set; }
    public Sound Sound { get; private set; }
    public BuildingType BuildingType { get; private set; }
    public int Damage { get; private set; }
    public double Range { get; private set; }
    public TimeSpan ReloadTime { get; private set; }

class Segment
{
    public Segment(PointF p1, PointF p2)
    {
        P1 = p1;
        P2 = p2;
    }
 
    public readonly PointF P1;
    public readonly PointF P2;
 
    public float Length()
    {
        return (float)Math.Sqrt(LengthSquared());
    }
 
    public float LengthSquared()
    {
        return (P1.X - P2.X) * (P1.X - P2.X)
            + (P1.Y - P2.Y) * (P1.Y - P2.Y);
    }
}

using System;
using System.IO;
 
namespace GetLine
{
    internal class Manager
    {
        private static void Main(string[] args)
        {
            Console.WriteLine(GetLine(args[0], uint.Parse(args[1])));
        }
 
        private static string GetLine(string path, uint line)
        {
            using (var reader = new StreamReader(path))
            {
                try
                {
                    for (uint i = 0; i <= line; i++)
                    {
                        if (reader.EndOfStream)
                            return string.Format("There {1} less than {0} line{2} in the file.", line,
                                                 ((line == 1) ? "is" : "are"), ((line == 1) ? "" : "s"));
 
                        if (i == line)
                            return reader.ReadLine();
 
                        reader.ReadLine();
                    }
                }
                catch (IOException ex)
                {
                    return ex.Message;
                }
                catch (OutOfMemoryException ex)
                {
                    return ex.Message;
                }
            }
 
            throw new Exception("Something bad happened.");
        }
    }
}

using System;

public class SumMultiples
{
    public static long GetSum(long n)
    {
        long sum = 0;
        for (int i = 3; i < n; i++)
        {
            if (i % 3 == 0 || i % 5 == 0) sum += i;
        }
        return sum;
    }
    public static void Main(string[] args)
    {
        Console.WriteLine(GetSum(1000));
    }
}

