    /// <summary>
    /// Represents a specialized policy for managing database query execution
    /// with configurable parallel processing and queuing parameters.
    /// </summary>
    public class QueryPolicy : Policy
    {
        /// <summary>
        /// Maximum number of concurrent nodes allowed for query execution.
        /// Controls parallel query distribution across database cluster.
        /// </summary>
        public int maxConcurrentNodes { get; set; }

        /// <summary>
        /// Defines the maximum size of record retrieval queue for buffering query results.
        /// Helps manage memory and processing efficiency during distributed queries.
        /// </summary>
        public int recordQueueSize { get; set; }

        /// <summary>
        /// Default constructor initializes query policy with specific configuration defaults.
        /// Disables query retry mechanism and sets initial concurrent node and queue parameters.
        /// </summary>
        public QueryPolicy() : base()
        {
            // Disable query retry by default
            this.maxRetries = 0;

            // Set default maximum concurrent nodes for query execution
            this.maxConcurrentNodes = Environment.ProcessorCount;

            // Configure default record queue size for result buffering
            this.recordQueueSize = 5000;

            // Apply additional default query policy configurations
            this.socketTimeout = 30000;   // 30 seconds socket timeout
            this.totalTimeout = 60000;    // 1 minute total query timeout
        }

        /// <summary>
        /// Validates and adjusts query policy configuration parameters.
        /// Ensures consistent and safe query execution settings.
        /// </summary>
        public void ValidateConfiguration()
        {
            // Ensure maximum concurrent nodes is within reasonable range
            maxConcurrentNodes = Math.Max(1, Math.Min(maxConcurrentNodes, 32));

            // Validate record queue size constraints
            recordQueueSize = Math.Clamp(recordQueueSize, 100, 10000);
        }

