namespace Helper
{
    class Converter
    {
        static void Main(string[] args)
        {
            var floors = Enumerable.Range(1, 5);

            var result = floors.SelectMany(b =>
                floors.SelectMany(c =>
                    floors.SelectMany(f =>
                        floors.SelectMany(m =>
                            floors.SelectMany(s =>
                                new[] { new { b, c, f, m, s } }
                                   .Where(x =>
                                        new[] { x.b, x.c, x.f, x.m, x.s }
                                           .Distinct()
                                           .Count() == 5 &&
                                        x.b!= 5 && x.c!= 1 && x.f!= 1 && x.f!= 5 &&
                                        x.m > x.c && Math.Abs(x.s - x.f) > 1 && Math.Abs(x.c - x.f) > 1)
                                   .Select(x => new
                                    {
                                        Baker = x.b,
                                        Cooper = x.c,
                                        Fletcher = x.f,
                                        Miller = x.m,
                                        Smith = x.s
                                    })))));

            foreach (var item in result)
            {
                Console.WriteLine(item);
            }
        }
    }
