namespace XfsFileSystem
{
    // Base class for file system options.
    public abstract class FileSystemOptionsBase
    {
        // Base class can be extended with common options in the future.
    }

    // Encapsulates external parameters for file system configuration.
    public class FileSystemParameters
    {
        // Optional parameter for file name encoding.
        // If null, the default encoding will be used.
        public Encoding FileNameEncoding { get; set; }

        // Additional parameters can be added here.
        public FileSystemParameters()
        {
            // Initialize more parameters if needed.
        }
    }

    // Immutable class for XFS file system settings.
    public sealed class XfsFileSystemOptions : FileSystemOptionsBase
    {
        // Default encoding is set to UTF8.
        private static readonly Encoding DefaultEncoding = Encoding.UTF8;

        // Property representing the encoding used for file names.
        public Encoding FileNameEncoding { get; }

        // Default constructor that initializes options with standard settings.
        public XfsFileSystemOptions()
        {
            FileNameEncoding = DefaultEncoding;
        }

        // Parameterized constructor that allows customization from external parameters.
        public XfsFileSystemOptions(FileSystemParameters parameters)
        {
            if (parameters == null)
            {
                // Use default encoding if no parameters are provided.
                FileNameEncoding = DefaultEncoding;
            }
            else
            {
                // Use provided encoding if available, otherwise fallback.
                FileNameEncoding = parameters.FileNameEncoding ?? DefaultEncoding;
            }
        }
    }

    // Example program demonstrating the usage of XfsFileSystemOptions.
    class Logger
    {
        static void Main(string[] args)
        {
            // Example 1: Using the default constructor.
            XfsFileSystemOptions defaultOptions = new XfsFileSystemOptions();
            Console.WriteLine("Default FileNameEncoding: " + defaultOptions.FileNameEncoding.EncodingName);

            // Example 2: Using the parameterized constructor with custom settings.
            FileSystemParameters customParams = new FileSystemParameters
            {
                // Setting the custom encoding to ASCII.
                FileNameEncoding = Encoding.ASCII
            };

            XfsFileSystemOptions customOptions = new XfsFileSystemOptions(customParams);

