using log4net.Util;

public class LoggingEventDataBuilder
{
    public static LoggingEventData Build(StackFrame frame, Severity severity, string message, Exception exception, PropertiesDictionary properties)
    {
        var loggingEventData = new LoggingEventData();

        loggingEventData.Domain = AppDomain.CurrentDomain.FriendlyName;
        loggingEventData.Identity = Thread.CurrentPrincipal?.Identity?.Name;
        loggingEventData.Level = MapSeverityToLevel(severity);

        var method = frame.GetMethod();
        loggingEventData.ClassName = method.DeclaringType?.FullName;
        loggingEventData.MethodName = method.Name;
        loggingEventData.FileName = frame.GetFileName();
        loggingEventData.LineNumber = frame.GetFileLineNumber().ToString();

        loggingEventData.LoggerName = method.DeclaringType?.FullName;
        loggingEventData.Message = message ?? exception?.Message;
        loggingEventData.TimeStamp = DateTime.UtcNow;
        loggingEventData.UserName = HttpContext.Current?.User?.Identity?.Name ?? Environment.UserName;

        if (properties != null)
        {
            loggingEventData.Properties = properties;
        }

        return loggingEventData;
    }

    private static Level MapSeverityToLevel(Severity severity)
    {
        switch (severity)
        {
            case Severity.Debug:
                return Level.Debug;
            case Severity.Info:
                return Level.Info;
            case Severity.Warn:
                return Level.Warn;
            case Severity.Error:
                return Level.Error;
            case Severity.Fatal:
                return Level.Fatal;
            default:
                return Level.Info;
        }
    }
}

public enum Severity
{
    Debug,
    Info,
    Warn,
    Error,
    Fatal
}

public class LoggingEventData
{
    public string Domain { get; set; }
    public string Identity { get; set; }
    public Level Level { get; set; }
    public string ClassName { get; set; }
    public string MethodName { get; set; }
    public string FileName { get; set; }
    public string LineNumber { get; set; }
    public string LoggerName { get; set; }
    public string Message { get; set; }
    public DateTime TimeStamp { get; set; }
    public string UserName { get; set; }
    public PropertiesDictionary Properties { get; set; }
}

