namespace BuildUtilities
{
    public static class ReflectionHelper
    {
        public static T GetAttribute<T>(ICustomAttributeProvider provider) where T : Attribute
        {
            try
            {
                var attributes = provider.GetCustomAttributes(typeof(T), false);
                return attributes.Length > 0 ? (T)attributes[0] : null;
            }
            catch (Exception ex)
            {
                return null;
            }
        }

        public static bool HasAttribute<T>(ICustomAttributeProvider provider) where T : Attribute
        {
            try
            {
                return provider.GetCustomAttributes(typeof(T), false).Length > 0;
            }
            catch
            {
                return false;
            }
        }

        public static bool IsOutput(ITaskItem taskItem)
        {
            return taskItem.GetMetadata("IsOutput")?.Equals("true", StringComparison.OrdinalIgnoreCase) ?? false;
        }

        public static bool IsRequired(ITaskItem taskItem)
        {
            return taskItem.GetMetadata("Required")?.Equals("true", StringComparison.OrdinalIgnoreCase) ?? false;
        }

        public static Assembly LoadAssembly(string assemblyPath, TaskLoggingHelper log)
        {
            if (string.IsNullOrWhiteSpace(assemblyPath))
            {
                log?.LogWarning("Attempted to load null or empty assembly path");
                return null;
            }

            try
            {
                if (!File.Exists(assemblyPath))
                {
                    log?.LogError($"Assembly file not found: {assemblyPath}");
                    return null;
                }

                return Assembly.LoadFrom(assemblyPath);
            }
            catch (BadImageFormatException ex)
            {
                log?.LogError($"Invalid assembly format: {assemblyPath}");
                log?.LogErrorFromException(ex);
                return null;
            }
            catch (FileLoadException ex)
            {
                log?.LogError($"Unable to load assembly: {assemblyPath}");
                log?.LogErrorFromException(ex);
                return null;
            }
            catch (Exception ex)
            {
                log?.LogError($"Unexpected error loading assembly: {assemblyPath}");
                log?.LogErrorFromException(ex);
                return null;

