using AlarmWorkflow.Core.Models; // Assuming there is a core model namespace
using AlarmWorkflow.UI.Contracts; // Assuming there is a UI contracts namespace

namespace AlarmWorkflow.ViewModels
{
    [DebuggerDisplay("ID: {Operation.Id}, Timestamp: {Operation.Timestamp}")]
    public class OperationViewModel : ViewModelBase
    {
        private Operation _operation;

        public OperationViewModel(Operation operation = null)
        {
            _operation = operation ?? new Operation();
        }

        public int Id
        {
            get => _operation.Id;
            set
            {
                if (_operation.Id != value)
                {
                    _operation.Id = value;
                    OnPropertyChanged(nameof(Id));
                }
            }
        }

        public string Description
        {
            get => _operation.Description;
            set
            {
                if (_operation.Description != value)
                {
                    _operation.Description = value;
                    OnPropertyChanged(nameof(Description));
                }
            }
        }

        public DateTime Timestamp
        {
            get => _operation.Timestamp;
            set
            {
                if (_operation.Timestamp != value)
                {
                    _operation.Timestamp = value;
                    OnPropertyChanged(nameof(Timestamp));
                }
            }
        }

        public bool IsActive
        {
            get => _operation.IsActive;
            set
            {
                if (_operation.IsActive != value)
                {
                    _operation.IsActive = value;
                    OnPropertyChanged(nameof(IsActive));
                }
            }
        }

        public void UpdateOperation(Operation operation)
        {
            if (operation == null) throw new ArgumentNullException(nameof(operation));
            _operation = operation;
            OnPropertyChanged(nameof(Id));
            OnPropertyChanged(nameof(Description));
            OnPropertyChanged(nameof(Timestamp));
            OnPropertyChanged(nameof(IsActive));
        }

        public Operation GetOperation()
        {
            return _operation;
        }

        public override string ToString()
        {
            return $"{Description} (ID: {Id}, Active: {IsActive})";
        }
    }
}

public static class ArrayExtensions
{
    public static T[] Permutationsort<T>(this T[] array) where T : IComparable<T>
    {
        var permutations = array.Permutation();
        foreach (var perm in permutations)
        {
            if (perm.Sorted())
            {
                return perm;
            }
        }
        return null;
    }

    public static bool Sorted<T>(this T[] array) where T : IComparable<T>
    {
        for (int i = 0; i < array.Length - 1; i++)
        {
            if (array[i].CompareTo(array[i + 1]) > 0)
            {
                return false;
            }
        }
        return true;
    }
}

