namespace CharacterTraits
{
    public class Trait
    {
        private readonly string name;
        private readonly string custom;
        private readonly int genNum;
        private readonly int profNum;
        private readonly string desc;

        public string Name => name;
        public string Custom => custom;
        public int GenNum => genNum;
        public int ProfNum => profNum;
        public string Description => desc;

        public Trait(string name, string desc, int genNum, int profNum)
        {
            this.name = name;
            this.desc = desc;
            this.genNum = genNum;
            this.profNum = profNum;
            this.custom = string.Empty;
        }

        public Trait(string name, string custom, string desc, int genNum, int profNum)
        {
            this.name = name;
            this.custom = custom;
            this.desc = desc;
            this.genNum = genNum;
            this.profNum = profNum;
        }

        public string GetDisplayName()
        {
            return string.IsNullOrEmpty(Custom) ? Name : Custom;
        }

        public int CalculateTotal()
        {
            return GenNum + ProfNum;
        }
    }

    public class SpTrait : Trait
    {
        private int usedTP;
        private readonly int totalTP;

        public int UsedTP => usedTP;
        public int TotalTP => totalTP;

        public SpTrait(string name, string desc, int genNum, int profNum, int totalTP)
            : base(name, desc, genNum, profNum)
        {
            this.totalTP = totalTP;
            usedTP = 0;
        }

        public SpTrait(string name, string custom, string desc, int genNum, int profNum, int totalTP)
            : base(name, custom, desc, genNum, profNum)
        {
            this.totalTP = totalTP;
            usedTP = 0;
        }

        public SpTrait(string name, string desc, int genNum, int profNum, int totalTP, int usedTP)
            : base(name, desc, genNum, profNum)
        {
            this.totalTP = totalTP;
            this.usedTP = usedTP;
        }

        public void AllocatePoints(int points)
        {
            if (points < 0 || usedTP + points > totalTP || usedTP + points < 0)
                throw new ArgumentException("Invalid point allocation");

            usedTP += points;
        }

        public int GetRemainingPoints()
        {
            return totalTP - usedTP;
        }
    }
}

