namespace Sudoku
{
    class Writer
    {
        static int[][] board;
        static int[] start;
        static int[] given;
 
        static void setup(string[] input)
        {
            /* This task is not about input validation, so
               we're going to trust the input to be valid */
            string[][] puzzle = new string[input.Length][];
            for (int i = 0; i < input.Length; i++)
            {
                puzzle[i] = input[i].Split(' ');
            }
            int nCols = puzzle[0].Length;
            int nRows = puzzle.Length;
            List<int> list = new List<int>();
            board = new int[nRows + 2][];
            for (int i = 0; i < nRows + 2; i++)
            {
                board[i] = new int[nCols + 2];
                for (int j = 0; j < nCols + 2; j++)
                {
                    board[i][j] = -1;
                }
            }
            for (int r = 0; r < nRows; r++)
            {
                string[] row = puzzle[r];
                for (int c = 0; c < nCols; c++)
                {
                    switch (row[c])
                    {
                        case "_":
                            board[r + 1][c + 1] = 0;
                            break;
                        case ".":
                            break;
                        default:
                            int val = int.Parse(row[c]);
                            board[r + 1][c + 1] = val;
                            list.Add(val);
                            if (val == 1)
                            {
                                start = new int[] { r + 1, c + 1 };
                            }
                            break;
                    }
                }
            }
            list.Sort();
            given = new int[list.Count];
            for (int i = 0; i < given.Length; i++)
            {
                given[i] = list[i];
            }
        }
 
        static bool solve(int r, int c, int n, int next)
        {
            if (n > given[given.Length - 1])
            {
                return true;
            }
 
            int back = board[r][c];
            if (back!= 0 && back!= n)
            {
                return false;
            }
 
            if (back == 0 && given[next] == n)
            {
                return false;
            }
 
            if (back == n)
            {
                next++;
            }

