public static string Split(string str)
{
    Console.WriteLine(" input string: {0}", str);
    var s = str.ToCharArray().GroupBy(c => c).Select(g => new string(g.ToArray())).Aggregate((a, b) => a + ", " + b);
    Console.WriteLine("output string: {0}", s);
    return s;
}

