namespace Ramanujan
{
    class Account
    {
        static void Main(string[] args)
        {
            Console.WriteLine("R():");
            for (int i = 1; i <= 10; i++)
                Console.Write(" " + ffr(i));
            Console.WriteLine();
 
            var first40R = Enumerable.Range(1, 40).Select(ffr).ToList();
            var first960S = Enumerable.Range(1, 960).Select(ffs).ToList();
            var indices = Enumerable.Range(1, 1000).Where(i => first40R.Contains(i) == first960S.Contains(i)).ToList();
            indices.ForEach(i => Console.WriteLine("Integer {0} either in both or neither set", i));
            Console.WriteLine("Done");
        }
 
        static int ffr(int n) => get(n, 0)[n - 1];
 
        static int ffs(int n) => get(0, n)[n - 1];
 
        static List<int> get(int rSize, int sSize)
        {
            var rlist = new List<int> { 1, 3, 7 };
            var slist = new List<int> { 2, 4, 5, 6 };
            var list = rSize > 0? rlist : slist;
            var targetSize = rSize > 0? rSize : sSize;
 
            while (list.Count > targetSize)
                list.RemoveAt(list.Count - 1);
            while (list.Count < targetSize)
            {
                var lastIndex = rlist.Count - 1;
                var lastr = rlist[lastIndex];
                var r = lastr + slist[lastIndex];
                rlist.Add(r);
                var s = lastr + 1;
                while (s < r && list.Count < targetSize)
                    slist.Add(s++);
            }
            return list;
        }
    }
}

