public static class ParamPassing
{
    private static string[] _sharedParameters;
    public static int WM_SHOWME = RegisterWindowMessage("WM_SHOWME");

    [DllImport("user32.dll")]
    private static extern uint RegisterWindowMessage(string message);

    public static void ConfigureParameters(string[] parameters)
    {
        _sharedParameters = parameters;
    }

    public static string[] GetSharedParameters() => _sharedParameters;
}

public static class ExtensionsParameterPassing
{
    public static void AddHookParameterPassing(this Window window)
    {
        var handle = new WindowInteropHelper(window).Handle;
        HwndSource source = HwndSource.FromHwnd(handle);
        source.AddHook(HandleMessages);
    }

    private static IntPtr HandleMessages(IntPtr hwnd, int msg, IntPtr wParam, IntPtr lParam, ref bool handled)
    {
        if (msg == ParamPassing.WM_SHOWME)
        {
            ProcessIncomingInstance(hwnd);
            handled = true;
        }
        return IntPtr.Zero;
    }

    private static void ProcessIncomingInstance(IntPtr currentWindowHandle)
    {
        Application.Current.Dispatcher.Invoke(() =>
        {
            var currentWindow = Application.Current.MainWindow;
            if (currentWindow != null)
            {
                if (currentWindow.WindowState == WindowState.Minimized)
                {
                    UnsafeNative.ShowWindow(currentWindowHandle, UnsafeNative.SW_RESTORE);
                }

                UnsafeNative.SetForegroundWindow(currentWindowHandle);
                HandleParameterRouting();
            }
        });
    }

    private static void HandleParameterRouting()
    {
        string[] incomingParams = ParamPassing.GetSharedParameters();
        if (incomingParams != null && incomingParams.Length > 0)
        {
            // Custom parameter processing logic
            foreach (string param in incomingParams)
            {
                // Process each parameter
                ProcessParameter(param);
            }
        }
    }

