public abstract class SldrWritingSystemFactory<T>
{
    protected abstract T ConstructDefinition();
    protected abstract T ConstructDefinition(string ietfLanguageTag);
    protected abstract T ConstructDefinition(T existingDefinition);

    public virtual T Create(string ietfLanguageTag, out T ws)
    {
        string cachePath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "SLDRCache");
        string templatePath = Path.Combine(cachePath, ietfLanguageTag + ".ldml");

        if (!Directory.Exists(cachePath))
        {
            Directory.CreateDirectory(cachePath);
        }

        if (File.Exists(templatePath))
        {
            ws = ConstructDefinitionFromTemplate(templatePath);
        }
        else
        {
            string filename;
            if (GetLdmlFromSldr(cachePath, ietfLanguageTag, out filename))
            {
                ws = ConstructDefinitionFromTemplate(filename);
            }
            else
            {
                ws = ConstructDefinition(ietfLanguageTag);
            }
        }

        return ws;
    }

    private T ConstructDefinitionFromTemplate(string templatePath)
    {
        string ldmlData = File.ReadAllText(templatePath);
        return LdmlDataMapper.Read(ldmlData);
    }

    protected virtual bool GetLdmlFromSldr(string path, string id, out string filename)
    {
        filename = Path.Combine(path, id + ".ldml");
        // Simulate Sldr service call
        if (Sldr.DownloadLdmlFile(id, filename))
        {
            return true;
        }
        return false;
    }
}

