using System;
using System.Net.Http;
using System.Threading.Tasks;
using System.Xml.Linq;
using System.Diagnostics;

public class HttpServiceBusReceiver
{
    private readonly string _url;
    private readonly string _id;
    private const string CLIENT_HEADER_NAME = "X-Client-ID";

    public HttpServiceBusReceiver(string url, string id)
    {
        _url = url;
        _id = id;
    }

    public async Task<IncomingHttpMessage> ReceiveAsync(TimeSpan delay)
    {
        using (HttpClient client = new HttpClient())
        {
            client.DefaultRequestHeaders.Add(CLIENT_HEADER_NAME, GetClientHeaderValue());
            string requestUrl = $"{_url}?id={_id}";

            try
            {
                HttpResponseMessage response = await client.GetAsync(requestUrl);
                if (!response.IsSuccessStatusCode)
                {
                    Debug.WriteLine($"Failed to receive message: {response.StatusCode}");
                    return null;
                }

                var content = await response.Content.ReadAsStringAsync();
                return ProcessContent(content);
            }
            catch (HttpRequestException e)
            {
                Debug.WriteLine($"Request error: {e.Message}");
                return null;
            }
            finally
            {
                if (delay.TotalMilliseconds > 0)
                {
                    await Task.Delay(delay);
                }
            }
        }
    }

    private string GetClientHeaderValue()
    {
        return Guid.NewGuid().ToString();
    }

    private IncomingHttpMessage ProcessContent(string content)
    {
        try
        {
            XDocument xmlDocument = XDocument.Parse(content);
            var messageElement = xmlDocument.Root.Element("Message");
            if (messageElement != null)
            {
                return new IncomingHttpMessage
                {
                    Content = messageElement.Value,
                    ReceivedTime = DateTime.UtcNow
                };
            }
            else
            {
                Debug.WriteLine("No message element found in content.");
                return null;
            }
        }
        catch (Exception e)
        {
            Debug.WriteLine($"Error processing content: {e.Message}");
            return null;
        }
    }
}

