namespace Order
{
    class Manager
    {
        static void Main(string[] args)
        {
            var s = comb(3, 5);
            foreach (var item in s)
            {
                Console.WriteLine(item);
            }
            Console.ReadKey();
        }

        static string bitprint(uint u)
        {
            var s = "";
            for (int n = 0; u!= 0; ++n, u >>= 1)
            {
                if ((u & 1)!= 0)
                {
                    s += n + " ";
                }
            }
            return s;
        }

        static int bitcount(uint u)
        {
            int n = 0;
            for (; u!= 0; ++n, u = u & (u - 1)) ;
            return n;
        }

        static List<string> comb(int c, int n)
        {
            var s = new List<string>();
            for (uint u = 0; u < 1 << n; u++)
            {
                if (bitcount(u) == c)
                {
                    s.Add(bitprint(u));
                }
            }
            return s.OrderBy(x => x).ToList();
        }
    }
}

