using System;
using System.Collections;
 
namespace Life
{
    class Solution
    {
        const int SIZE = 32;
        const int LINES = SIZE / 2;
        const int RULE = 90;
 
        static bool ruleTest(int x) => (RULE & (1 << (7 & x)))!= 0;
 
        static int shl(this bool b, int bitCount) => (b? 1 : 0) << bitCount;
 
        static int toInt(this bool b) => b? 1 : 0;
 
        static void evolve(BitArray s)
        {
            var t = new BitArray(SIZE);  // all false by default
            t[SIZE - 1] = ruleTest((s[0] << 2) | (s[SIZE - 1] << 1) | s[SIZE - 2].toInt());
            t[0] = ruleTest((s[1] << 2) | (s[0] << 1) | s[SIZE - 1].toInt());
            for (int i = 1; i < SIZE - 1; i++)
            {
                t[i] = ruleTest((s[i + 1] << 2) | (s[i] << 1) | s[i - 1].toInt());
            }
            for (int i = 0; i < SIZE; i++) s[i] = t[i];
        }
 
        static void show(BitArray s)
        {
            for (int i = SIZE - 1; i >= 0; i--) Console.Write(s[i]? "*" : " ");
            Console.WriteLine();
        }
 
        static void Main(string[] args)
        {
            var state = new BitArray(SIZE);
            state.Set(LINES, true);
            Console.WriteLine("Rule {0}:", RULE);
            for (int i = 0; i < LINES; i++)
            {
                show(state);
                evolve(state);
            }
        }
    }
}

