public class AggregateModel
{
    public string Name { get; set; }
    public Type Type { get; set; }
    public Dictionary<string, Type> Properties { get; set; }

    public AggregateModel(string name, Type type)
    {
        Name = name;
        Type = type;
        Properties = new Dictionary<string, Type>();
    }

    public void AddProperty(string propertyName, Type propertyType)
    {
        Properties[propertyName] = propertyType;
    }
}

public class AggregateLambdaState
{
    public string AggregateName { get; private set; }
    public Type AggregateType { get; private set; }
    public AggregateModel AggregateModel { get; private set; }

    public AggregateLambdaState(string aggregateName, Type aggregateType, AggregateModel aggregateModel)
    {
        AggregateName = aggregateName;
        AggregateType = aggregateType;
        AggregateModel = aggregateModel;
    }

    public void CheckParameter(string parameterName, Type parameterType)
    {
        if (!AggregateModel.Properties.ContainsKey(parameterName))
        {
            throw new ArgumentException($"Parameter '{parameterName}' does not exist in aggregate '{AggregateName}'.");
        }

        if (AggregateModel.Properties[parameterName] != parameterType)
        {
            throw new ArgumentException($"Parameter '{parameterName}' must be of type {AggregateModel.Properties[parameterName]}.");
        }
    }

    public Expression CreateSelector(string path)
    {
        var propertyInfo = ParsePath(path);
        return Expression.Property(Expression.Parameter(AggregateType, "x"), propertyInfo);
    }

    public Type GetDataFieldInfo(string path)
    {
        var property = ParsePath(path);
        return AggregateModel.Properties[property];
    }

    private string ParsePath(string path)
    {
        var parts = path.Split('.');
        string currentProperty = parts[0];

        if (!AggregateModel.Properties.ContainsKey(currentProperty))
        {
            throw new ArgumentException($"Property '{currentProperty}' not found in aggregate '{AggregateName}'.");
        }

        for (int i = 1; i < parts.Length; i++)
        {
            currentProperty = parts[i];

            if (!AggregateModel.Properties.ContainsKey(currentProperty))
            {
                throw new ArgumentException($"Property '{currentProperty}' not found in aggregate '{AggregateName}'.");
            }
        }

        return currentProperty;
    }
}

