public class SingleValueAccessor : TransformationRule
{
    public override TransformationResult TryReduce(List<Expression> expressions)
    {
        if (expressions.Count != 2)
        {
            return TransformationResult.Failure;
        }

        var firstExpression = expressions[0];
        var secondExpression = expressions[1] as IdentifierExpression;

        if (firstExpression is TypeAccessExpression typeAccess &&
            typeAccess.AccessedType is EnumType enumType &&
            secondExpression != null)
        {
            var enumValue = enumType.Values.FirstOrDefault(v => v.Name == secondExpression.Identifier);
            if (enumValue != null)
            {
                var singleValueType = SingleValueTypeFor(enumValue);
                var resultExpression = new TypeAccessExpression(singleValueType);
                return TransformationResult.Success(resultExpression);
            }
        }

        return TransformationResult.Failure;
    }

    private TangentType SingleValueTypeFor(EnumValue enumValue)
    {
        // TODO: Refactor to use ExpressionDeclaration rules
        return enumValue.DeclaringType.GenericParameters.FirstOrDefault() ?? enumValue.DeclaringType;
    }
}

public class TransformationResult
{
    public static TransformationResult Success(Expression expression) => new TransformationResult { Success = true, Result = expression };
    public static TransformationResult Failure => new TransformationResult { Success = false };

    public bool Success { get; private set; }
    public Expression Result { get; private set; }
}

