                ShouldContain(result, "TestPackage");
                ShouldContain(result, "1.0.0");
                ShouldContain(result, "2.0.0-beta");
                ShouldNotContain(result, "UnrelatedPackage");
            }

            [Test]
            public void SearchFilters_ExcludeIrrelevantPackages()
            {
                string feedPath = PathToContent("example-feed.xml");
                string result = moo($"search AnotherPackage --source \"{feedPath}\"");

                ShouldContain(result, "AnotherPackage 3.2.1");
                ShouldNotContain(result, "TestPackage");
                ShouldNotContain(result, "UnrelatedPackage");
            }

            [Test]
            public void SearchDisplaysAllVersions()
            {
                string feedPath = PathToContent("example-feed.xml");
                string result = moo($"search MultiVersionPackage --source \"{feedPath}\"");

