public static class ArrayExtensions
{
    public static T[] QuickSort<T>(this T[] array) where T : IComparable
    {
        if (array.Length <= 1)
            return array;
        var pivot = array[0];
        var less = array.Skip(1).Where(x => x.CompareTo(pivot) < 0).ToArray();
        var greatereq = array.Skip(1).Where(x => x.CompareTo(pivot) >= 0).ToArray();
        return less.QuickSort().Concat(new[] { pivot }).Concat(greatereq.QuickSort()).ToArray();
    }
}

