namespace WebAssemblyInstructions
{
    public enum Operator
    {
        I64Const = 0x21 // Example Operator for i64.const
    }

    public class VarInt64Instruction
    {
        private readonly Operator opValue;
        private readonly long immediate;

        public VarInt64Instruction(Operator opValue, long immediate)
        {
            this.opValue = opValue;
            this.immediate = immediate;
        }

        public Operator GetOperator()
        {
            return opValue;
        }

        public long GetImmediate()
        {
            return immediate;
        }

        public void WriteToBinary(BinaryWriter writer)
        {
            writer.Write((byte)opValue);
            WriteVarInt64(writer, immediate);
        }

        private void WriteVarInt64(BinaryWriter writer, long value)
        {
            while ((value & ~0x7F) != 0)
            {
                writer.Write((byte)((value & 0x7F) | 0x80));
                value >>= 7;
            }
            writer.Write((byte)value);
        }

        public string Dump()
        {
            var sb = new StringBuilder();
            sb.AppendLine($"Operator: {opValue}");
            sb.AppendLine($"Immediate: {immediate}");
            return sb.ToString();
        }
    }

    public class Graph
    {
        public static void Main(string[] args)
        {
            using (var memoryStream = new MemoryStream())
            using (var binaryWriter = new BinaryWriter(memoryStream))
            {
                var instruction = new VarInt64Instruction(Operator.I64Const, 12345678901234567);
                instruction.WriteToBinary(binaryWriter);

                Console.WriteLine("Instruction written to binary.");
                Console.WriteLine(instruction.Dump());

                // For demonstration, print the binary data in a readable format
                Console.WriteLine("Binary data: " + BitConverter.ToString(memoryStream.ToArray()));
            }
        }
    }
}

