using System;
using Server;

[Serial]
public class Grubber : BaseCreature
{
    private const int MeatAmount = 1;
    private const int HidesAmount = 2;
    private Timer m_FleeTimer;

    public Grubber() : base(AIType.AI_Animal, FightMode.Aggressor)
    {
        Body = 0x28;
        SetStr(15);
        SetDex(200);
        SetInt(25);

        SetHits(20);
        SetDamage(2, 4);

        SetSkill(SkillName.Wrestling, 20);
        SetSkill(SkillName.Tactics, 0);
        SetSkill(SkillName.MagicResist, 10);
        SetSkill(SkillName.Hiding, 95);

        Fame = 50;
        Karma = 0;
        VirtualArmor = 10;
    }

    public override int Meat => MeatAmount;
    public override int Hides => HidesAmount;
    public override bool AlwaysFlee => true;

    public override int GetAttackSound() => 0x4F6;
    public override int GetHurtSound() => 0x4F7;
    public override int GetDeathSound() => 0x4F8;

    public override Mobile Combatant
    {
        get => base.Combatant;
        set
        {
            base.Combatant = value;
            if (value != null && m_FleeTimer == null && !Controlled)
            {
                if (Utility.RandomDouble() < 0.9)
                {
                    m_FleeTimer = Timer.DelayCall(TimeSpan.FromSeconds(1), TimeSpan.FromSeconds(1), CheckStopFlee);
                    Say("*fleeing*");
                }
            }
        }
    }

    private void CheckStopFlee()
    {
        if (Utility.RandomDouble() < 0.1 || !Alive)
        {
            m_FleeTimer?.Stop();
            m_FleeTimer = null;
            Combatant = null;
            Say("*calms*");
        }
    }

    public override void OnDeath(Container c)
    {
        base.OnDeath(c);
        c.AddItem(new RawRibs(MeatAmount));
        c.AddItem(new Leather(HidesAmount));
    }

    public override void Serialize(GenericWriter writer)
    {
        base.Serialize(writer);
        writer.Write(1); // Version
    }

    public override void Deserialize(GenericReader reader)
    {
        base.Deserialize(reader);
        int version = reader.ReadInt();

        if (version < 1)
        {
            SetSkill(SkillName.Hiding, 95);
            SetSkill(SkillName.Tactics, 0);
        }
    }
}

