using System;
using System.Collections.Generic;
using FluentAssertions;

namespace Microsoft.Languages.Core
{
    public interface IToken<TTokenType>
    {
        TTokenType TokenType { get; }
        int StartPosition { get; }
        int Length { get; }
    }

    public struct TokenData<TTokenType>
    {
        public TTokenType TokenType { get; }
        public int StartPosition { get; }
        public int Length { get; }

        public TokenData(TTokenType tokenType, int startPosition, int length)
        {
            TokenType = tokenType;
            StartPosition = startPosition;
            Length = length;
        }
    }

    public class TokensCompare<TTokenType, TTokenClass>
        where TTokenClass : IToken<TTokenType>
    {
        public void Compare(ICollection<TTokenClass> expectedTokens, ICollection<TTokenClass> actualTokens)
        {
            expectedTokens.Count.Should().Be(actualTokens.Count, "the token counts should match.");

            using (var expectedEnumerator = expectedTokens.GetEnumerator())
            using (var actualEnumerator = actualTokens.GetEnumerator())
            {
                while (expectedEnumerator.MoveNext() && actualEnumerator.MoveNext())
                {
                    var expectedToken = expectedEnumerator.Current;
                    var actualToken = actualEnumerator.Current;

                    expectedToken.TokenType.Should().Be(actualToken.TokenType,
                        "token types at position {0} should match.", expectedToken.StartPosition);
                    expectedToken.StartPosition.Should().Be(actualToken.StartPosition,
                        "start positions at position {0} should match.", expectedToken.StartPosition);
                    expectedToken.Length.Should().Be(actualToken.Length,
                        "lengths at position {0} should match.", expectedToken.StartPosition);
                }
            }
        }
    }
}

using System;
using System.Diagnostics;
using System.Threading;

public enum LogLevel
{
    Debug = 0,
    Info = 1,
    Warn = 2,
    Error = 3,
    Fatal = 4
}

public interface IKafkaLog
{
    void Log(LogLevel level, string message, params object[] args);
    void DebugFormat(string format, params object[] args);
    void InfoFormat(string format, params object[] args);
    void WarnFormat(string format, params object[] args);
    void ErrorFormat(string format, params object[] args);
    void FatalFormat(string format, params object[] args);
}

public class DefaultTraceLog : IKafkaLog
{
    private readonly LogLevel _minLevel;

    public DefaultTraceLog(LogLevel minLevel = LogLevel.Info)
    {
        _minLevel = minLevel;
    }

    private void WriteLog(LogLevel level, string message)
    {
        if (level < _minLevel)
            return;

        string threadInfo = $"Thread-{Thread.CurrentThread.ManagedThreadId}";
        string timestamp = DateTime.UtcNow.ToString("yyyy-MM-dd HH:mm:ss.fff");
        string formattedMessage = $"[{timestamp}] [{threadInfo}] [{level}] {message}";

        Trace.WriteLine(formattedMessage);
    }

    public void Log(LogLevel level, string message, params object[] args)
    {
        if (args != null && args.Length > 0)
        {
            message = string.Format(message, args);
        }

        WriteLog(level, message);
    }

    public void DebugFormat(string format, params object[] args)
    {
        Log(LogLevel.Debug, format, args);
    }

    public void InfoFormat(string format, params object[] args)
    {
        Log(LogLevel.Info, format, args);
    }

    public void WarnFormat(string format, params object[] args)
    {
        Log(LogLevel.Warn, format, args);
    }

    public void ErrorFormat(string format, params object[] args)
    {
        Log(LogLevel.Error, format, args);
    }

    public void FatalFormat(string format, params object[] args)
    {
        Log(LogLevel.Fatal, format, args);
    }
}

using System;
using System.Collections.Generic;
using System.Numerics;
 
namespace RosettaCode
{
    class Checker
    {
        static void Main()
        {
            List<BigInteger> candidates = new List<BigInteger>(new BigInteger[] { 1000, 100000, 10000000, 10000000000, 1000000000000000 });
            candidates.Add(BigInteger.Parse("100000000000000000000"));
 
            foreach (BigInteger candidate in candidates)
            {
                BigInteger c = candidate - 1;
                BigInteger answer3 = GetSumOfNumbersDivisibleByN(c, 3);
                BigInteger answer5 = GetSumOfNumbersDivisibleByN(c, 5);
                BigInteger answer15 = GetSumOfNumbersDivisibleByN(c, 15);
 
                Console.WriteLine("The sum of numbers divisible by 3 or 5 between 1 and {0} is {1}", c, answer3 + answer5 - answer15);
            }
 
            Console.ReadKey(true);
        }
 
        private static BigInteger GetSumOfNumbersDivisibleByN(BigInteger candidate, uint n)
        {
            BigInteger largest = candidate;
            while (largest % n > 0)
                largest--;
            BigInteger totalCount = (largest / n);
            BigInteger pairCount = totalCount / 2;
            bool unpairedNumberOnFoldLine = (totalCount % 2 == 1);
            BigInteger pairSum = largest + n;
            return pairCount * pairSum + (unpairedNumberOnFoldLine ? pairSum / 2 : 0);
        }
 
    }
}

