 namespace DevCore.TfsNotificationRelay
 {
  public class ReleaseCreatedNotification
  {
  public static string ToMessage(ReleaseNotification releaseNotification, BotElement bot, TextElement textTemplates)
  {
  string template = textTemplates.ReleaseCreated;
  string message = template.FormatWith(new
  {
  releaseNotification.TeamProjectCollection,
  releaseNotification.ProjectName,
  releaseNotification.ReleaseDefinition,
  releaseNotification.ReleaseStatus,
  releaseNotification.ReleaseUrl,
  releaseNotification.ReleaseName,
  releaseNotification.ReleaseReason,
  releaseNotification.CreatedByUniqueName,
  releaseNotification.CreatedByDisplayName,
  releaseNotification.CreatedOn,
  UserName = GetMappedUser(bot, releaseNotification.CreatedByUniqueName)
  });
  return message;
  }

  public static EventRuleElement GetRuleMatch(ReleaseNotification releaseNotification, List<EventRuleElement> rules)
  {
  return GetRulesMatch(releaseNotification, rules).FirstOrDefault();
  }

  public static IEnumerable<EventRuleElement> GetRulesMatch(ReleaseNotification releaseNotification, List<EventRuleElement> rules)
  {
  return rules.Where(r => r.Collection == releaseNotification.TeamProjectCollection && r.Events.Contains(TfsEvents.ReleaseCreated));
  }

  private static string FormatWith(this string format, object source)
  {
  return FormatWith(format, null, source);
  }

  private static string FormatWith(this string format, IFormatProvider provider, object source)
  {
  if (format == null)
  throw new ArgumentNullException("format");

  System.Text.StringBuilder sb = new System.Text.StringBuilder();
  System.Text.RegularExpressions.Regex r = new System.Text.RegularExpressions.Regex(@"\{(?<property>[\w\.\[\]]+)(?:,(?<format>[^}]+))?\}",
  System.Text.RegularExpressions.RegexOptions.IgnoreCase);
  System.Text.RegularExpressions.Match m = r.Match(format);
  while (m.Success)
  {
  System.Text.RegularExpressions.Group propertyGroup = m.Groups["property"];
  System.Text.RegularExpressions.Group formatGroup = m.Groups["format"];
  object propertyValue = DevCore.TfsNotificationRelay.Extensions.ObjectExtensions.GetPropertyValue(source, propertyGroup.Value);
  if (propertyValue == null)
  sb.Append(m.Value);
  else
  {
  if (string.IsNullOrEmpty(formatGroup.Value))
  sb.Append(propertyValue);
  else
  sb.Append(string.Format(provider, "{0:" + formatGroup.Value + "}", propertyValue));
  }
  m = m.NextMatch();
  }

