namespace DesignPatternsDemo
{
    // Singleton class
    public class Singleton
    {
        private static Singleton instance;
        private Singleton() { }
        public static Singleton Instance => instance ??= new Singleton();
        public void DoSomething() => Console.WriteLine("Singleton instance doing something.");
    }

    // Person class for Iterator
    public class Person
    {
        public string Name { get; }
        public Person(string name) => Name = name;
    }

    // Aggregate for Iterator
    public class People : IEnumerable<Person>
    {
        private List<Person> people = new List<Person>();
        public void AddPerson(Person person) => people.Add(person);
        public IEnumerator<Person> GetEnumerator() => people.GetEnumerator();
        IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
    }

    // Ship interface
    public interface IShip
    {
        string GetName();
    }

    // Concrete Ship classes
    public class CargoShip : IShip
    {
        public string GetName() => "Cargo Ship";
    }

    public class CruiseShip : IShip
    {
        public string GetName() => "Cruise Ship";
    }

    // Ship Factory
    public static class ShipFactory
    {
        public static IShip CreateShip(int type)
        {
            return type switch
            {
                1 => new CargoShip(),
                2 => new CruiseShip(),
                _ => throw new ArgumentException("Invalid ship type.")
            };
        }
    }

    class Vector
    {
        static void Main(string[] args)
        {
            Console.WriteLine("Choose a design pattern to demonstrate:");
            Console.WriteLine("1: Singleton");
            Console.WriteLine("2: Iterator");
            Console.WriteLine("3: Factory");
            int designPat = int.Parse(Console.ReadLine());

            switch (designPat)
            {
                case 1:
                    Singleton singleton = Singleton.Instance;
                    singleton.DoSomething();
                    break;
                case 2:
                    People people = new People();
                    people.AddPerson(new Person("Alice"));
                    people.AddPerson(new Person("Bob"));
                    foreach (var person in people)
                    {
                        Console.WriteLine($"Person: {person.Name}");
                    }
                    break;
                case 3:

