namespace BasicStats
{
    class Generator
    {
        static void Main(string[] args)
        {
            var sampleSizes = new int[] { 100, 1000, 10000, 100000 };
            foreach (var sampleSize in sampleSizes)
            {
                BasicStats(sampleSize);
            }
        }
 
        static void BasicStats(int sampleSize)
        {
            if (sampleSize < 1) return;
            var r = new double[sampleSize];
            var h = new int[10];
            var rand = new Random();
            for (var i = 0; i < sampleSize; i++)
            {
                r[i] = rand.NextDouble();
                h[(int)(r[i] * 10)]++;
            }
 
            var adj = sampleSize - h.Sum();
            if (adj!= 0)
            {
                for (var i = 0; i < 10; i++)
                {
                    h[i] += adj;
                    if (h[i] >= 0) break;
                    h[i] -= adj;
                }
            }
 
            var mean = r.Average();
            var sd = Math.Sqrt(r.Select(x => (x - mean) * (x - mean)).Average());
 
            var scale = sampleSize <= 500? 1.0 : 500.0 / sampleSize;
            Console.WriteLine($"Sample size {sampleSize}");
            Console.WriteLine($"  Mean {mean:F6}  SD {sd:F6}");
            Console.WriteLine();
            for (var i = 0; i < 10; i++)
            {
                Console.Write($"  {i / 10.0:F2} : {h[i]} ");
                var numStars = (int)(h[i] * scale + 0.5);
                Console.WriteLine(new string('*', numStars));
            }
            Console.WriteLine();
        }
    }
}

