namespace UdpPingPongApp
{
    public class UdpPingPong
    {
        private UdpClient udpClient;
        private int sequenceCounter = 0;
        private AutoResetEvent pongReceived = new AutoResetEvent(false);
        private int expectedSequence = -1;
        private long pingStartTime;
        private static readonly ILog log = LogManager.GetLogger(typeof(UdpPingPong));

        public UdpPingPong(int localPort)
        {
            udpClient = new UdpClient(localPort);
            // Configure log4net (assumes a separate configuration file or defaults)
            XmlConfigurator.Configure();
            // Begin asynchronous receive for incoming UDP packets
            udpClient.BeginReceive(ProcessReceivedData, null);
        }

        // Sends a ping packet to the specified remote endpoint and waits for a pong reply.
        public void SendPing(IPEndPoint remoteEndpoint, int timeout = 3000)
        {
            expectedSequence = Interlocked.Increment(ref sequenceCounter);
            byte[] pingData = BitConverter.GetBytes(expectedSequence);
            pingStartTime = DateTime.UtcNow.Ticks;
            udpClient.Send(pingData, pingData.Length, remoteEndpoint);
            log.Info("Sent ping with sequence: " + expectedSequence);

            // Wait for the pong response or for timeout expiration.
            if (pongReceived.WaitOne(timeout))
            {
                long pongTime = DateTime.UtcNow.Ticks;
                double roundTripMs = new TimeSpan(pongTime - pingStartTime).TotalMilliseconds;
                log.Info("Received pong for sequence " + expectedSequence + "; RTT = " + roundTripMs + " ms");
            }
            else
            {
                log.Warn("Timeout waiting for pong for sequence: " + expectedSequence);
            }
        }

        // Callback processing method for received UDP data.
        private void ProcessReceivedData(IAsyncResult ar)
        {
            IPEndPoint remoteEndpoint = new IPEndPoint(IPAddress.Any, 0);
            byte[] data = udpClient.EndReceive(ar, ref remoteEndpoint);
            // Continue listening for new packets.
            udpClient.BeginReceive(ProcessReceivedData, null);
            if (data == null || data.Length < 4)
            {
                log.Warn("Received invalid packet from " + remoteEndpoint.ToString());
                return;
            }

