using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Esper.Epl;
using log4net;

public class LatencySpikeMonitor
{
    private const int LatencyThreshold = 20000;
    private readonly IList<OperationMeasurement> _measurements;
    private static readonly ILog Log = LogManager.GetLogger(typeof(LatencySpikeMonitor));

    public LatencySpikeMonitor()
    {
        _measurements = new List<OperationMeasurement>();
        Start();
    }

    private void Start()
    {
        // Assuming Esper's event engine is initialized and configured
        var epl = "SELECT * FROM OperationMeasurement WHERE latency > " + LatencyThreshold;
        EsperClient.Instance.EPStatement.Create(epl).Events += OnLatencyEvent;
    }

    private void OnLatencyEvent(object sender, EventArgs e)
    {
        // Fetch all relevant events
        var highLatencyEvents = e.GetEvents<OperationMeasurement>();
        foreach (var measurement in highLatencyEvents)
        {
            LogLatencyEvent(measurement);
        }
    }

    private void LogLatencyEvent(OperationMeasurement measurement)
    {
        string message = $"High latency detected: Operation={measurement.OperationId}, Latency={measurement.Latency}, Timestamp={measurement.Timestamp}";
        Log.Error(message);
        Console.WriteLine(message); // Output to console for demonstration
    }

    public void AddMeasurement(OperationMeasurement measurement)
    {
        _measurements.Add(measurement);
        // Assume the event system will automatically pick up this measurement
        EsperClient.Instance.EPEvent.Send(measurement);
    }

    public class OperationMeasurement
    {
        public string OperationId { get; set; }
        public int Latency { get; set; }
        public DateTime Timestamp { get; set; }

        public OperationMeasurement(string operationId, int latency)
        {
            OperationId = operationId;
            Latency = latency;
            Timestamp = DateTime.UtcNow;
        }
    }
}

