using JetBrains.Annotations;
using Oberon0.Compiler.Definitions;
using Oberon0.Compiler.Expressions.Constant;
using Oberon0.Compiler.Expressions.Operations.Internal;
using Oberon0.Compiler.Types;

namespace Oberon0.Compiler.Expressions.Operations
{
    [ArithmeticOperation(OberonGrammarLexer.OP_MUL, BaseTypes.IntType, BaseTypes.IntType, BaseTypes.IntType)]
    [ArithmeticOperation(OberonGrammarLexer.OP_MUL, BaseTypes.IntType, BaseTypes.RealType, BaseTypes.RealType)]
    [ArithmeticOperation(OberonGrammarLexer.OP_MUL, BaseTypes.RealType, BaseTypes.IntType, BaseTypes.RealType)]
    [ArithmeticOperation(OberonGrammarLexer.OP_MUL, BaseTypes.RealType, BaseTypes.RealType, BaseTypes.RealType)]
    [UsedImplicitly]
    internal class OpMulNumber : BinaryOperation
    {
        internal override Expression BinaryOperate(Block block, BinaryExpression bin, IArithmeticOpMetadata operationParameters)
        {
            if (bin.LeftHandSide is ConstantExpression l && bin.RightHandSide is ConstantExpression r)
            {
                if (l.ValueType == BaseTypes.IntType && r.ValueType == BaseTypes.IntType)
                {
                    return new ConstantExpression(l.IntValue * r.IntValue, BaseTypes.IntType);
                }

                if (l.ValueType == BaseTypes.RealType && r.ValueType == BaseTypes.RealType)
                {
                    return new ConstantExpression(l.RealValue * r.RealValue, BaseTypes.RealType);
                }

                if (l.ValueType == BaseTypes.IntType && r.ValueType == BaseTypes.RealType)
                {
                    return new ConstantExpression(l.IntValue.ToDouble() * r.RealValue, BaseTypes.RealType);
                }

                if (l.ValueType == BaseTypes.RealType && r.ValueType == BaseTypes.IntType)
                {
                    return new ConstantExpression(l.RealValue * r.IntValue.ToDouble(), BaseTypes.RealType);
                }
            }

            return bin; // expression remains the same
        }
    }
}

