namespace Axiom.Core.Controllers
{
    /// <summary>
    /// Represents a generic controller function for transforming values dynamically during frame updates
    /// </summary>
    /// <typeparam name="T">The type of value to be transformed</typeparam>
    public interface IControllerFunction<T>
    {
        /// <summary>
        /// Executes the value transformation for the current frame
        /// </summary>
        /// <param name="sourceValue">The input value to be modified</param>
        /// <returns>The transformed value after applying the controller function logic</returns>
        T Execute(T sourceValue);
    }

    /// <summary>
    /// Base implementation of a linear interpolation controller function
    /// </summary>
    /// <typeparam name="T">The numeric type for interpolation</typeparam>
    public abstract class BaseInterpolationController<T> : IControllerFunction<T>
        where T : struct, IComparable<T>
    {
        /// <summary>
        /// Minimum value for interpolation range
        /// </summary>
        protected T MinValue { get; set; }

        /// <summary>
        /// Maximum value for interpolation range
        /// </summary>
        protected T MaxValue { get; set; }

        /// <summary>
        /// Initializes a new instance of the interpolation controller
        /// </summary>
        /// <param name="minValue">The minimum boundary value</param>
        /// <param name="maxValue">The maximum boundary value</param>
        protected BaseInterpolationController(T minValue, T maxValue)
        {
            MinValue = minValue;
            MaxValue = maxValue;
        }

        /// <summary>
        /// Default implementation of value transformation
        /// </summary>
        /// <param name="sourceValue">The input value to transform</param>
        /// <returns>The transformed value</returns>
        public abstract T Execute(T sourceValue);
    }
}

using System;
 
public class Handler
{
    public static int p(int l, int n)
    {
        int test = 0;
        double logv = Math.Log(2.0) / Math.Log(10.0);
        int factor = 1;
        int loop = l;
        while (loop > 10)
        {
            factor *= 10;
            loop /= 10;
        }
        while (n > 0)
        {
            int val;
 
            test++;
            val = (int)(factor * Math.Pow(10.0, Math.IEEERemainder(test * logv, 1)));
            if (val == l)
            {
                n--;
            }
        }
        return test;
    }
 
    public static void runTest(int l, int n)
    {
        Console.WriteLine("p({0}, {1}) = {2}", l, n, p(l, n));
    }
 
    public static void Main()
    {
        runTest(12, 1);
        runTest(12, 2);
        runTest(123, 45);
        runTest(123, 12345);
        runTest(123, 678910);
    }
}

