namespace Kata.Impl
{
    public class CompositeIterator<T> : IIterator<IEnumerable<T>>
    {
        private readonly IIterator<T>[] _iterators;
        private readonly ICollection<IIterator<T>> _iteratorsToReset;

        public CompositeIterator(params IIterator<T>[] iterators)
        {
            if (iterators == null)
            {
                throw new ArgumentNullException(nameof(iterators));
            }

            if (iterators.Any(iter => iter == null))
            {
                throw new ArgumentException("iterator cannot be null");
            }

            _iterators = iterators;
            _iteratorsToReset = new LinkedList<IIterator<T>>();
        }

        private bool IsEnd => _iteratorsToReset.Count == _iterators.Length;

        public IEnumerable<T> Current => _iterators.Select(iterator => iterator.Current);

        public bool MoveNext()
        {
            if (IsEnd)
            {
                return false;
            }

            _iteratorsToReset.Clear();

            foreach (var iterator in _iterators)
            {
                if (iterator.MoveNext())
                {
                    break;
                }
                _iteratorsToReset.Add(iterator);
            }

            if (IsEnd)
            {
                return false;
            }

            Reset(_iteratorsToReset);

            return true;
        }

        public void Reset()
        {
            _iteratorsToReset.Clear();
            Reset(_iterators);
        }

        private static void Reset(IEnumerable<IIterator<T>> iterators)
        {
            foreach (var iterator in iterators)
            {
                iterator.Reset();
            }
        }
    }
}

