public class Achievement
{
    public int Value { get; set; }
    public DateTime LastUpdated { get; set; }
    public List<AchievementHistory> History { get; } = new List<AchievementHistory>();

    public int GetValueChangeFrom(DateTime date)
    {
        if (date > LastUpdated || History.Count == 0)
            return 0;

        AchievementHistory closestEntry = null;
        foreach (var entry in History)
        {
            if (entry.DateTime > date) break;
            closestEntry = entry;
        }
        return closestEntry != null ? Value - closestEntry.Value : 0;
    }
}

public class AchievementHistory
{
    public DateTime DateTime { get; set; }
    public int Value { get; set; }

    public AchievementHistory() { }

    public AchievementHistory(Achievement achievement)
    {
        DateTime = achievement.LastUpdated;
        Value = achievement.Value;
    }
}

