namespace RiotArchiveFormat
{
    public class RAFFileListEntry
    {
        private readonly byte[] directoryFileContent;
        private readonly int offsetEntry;
        private readonly RAF parentArchive;

        public RAFFileListEntry(RAF parentArchive, byte[] directoryFileContent, int offsetEntry)
        {
            this.parentArchive = parentArchive;
            this.directoryFileContent = directoryFileContent;
            this.offsetEntry = offsetEntry;
        }

        public uint Hash
        {
            get
            {
                return BitConverter.ToUInt32(directoryFileContent, offsetEntry);
            }
        }

        public uint Offset
        {
            get
            {
                return BitConverter.ToUInt32(directoryFileContent, offsetEntry + 4);
            }
        }

        public uint Size
        {
            get
            {
                return BitConverter.ToUInt32(directoryFileContent, offsetEntry + 8);
            }
        }

        public string GetFileName
        {
            get
            {
                int stringOffset = (int)BitConverter.ToUInt32(directoryFileContent, offsetEntry + 12);
                int length = Array.IndexOf(parentArchive.StringTable, (byte)0, stringOffset) - stringOffset;

                return Encoding.ASCII.GetString(
                    parentArchive.StringTable,
                    stringOffset,
                    length
                );
            }
        }

        public override string ToString()
        {
            return $"RAF Entry: {GetFileName} (Hash: {Hash:X8}, Size: {Size} bytes)";
        }

        public byte[] ExtractFileData()
        {
            byte[] fileData = new byte[Size];
            Array.Copy(
                parentArchive.FileData,
                (int)Offset,
                fileData,
                0,
                (int)Size
            );
            return fileData;
        }
    }

