using System;
 
public class Manager
{
    public static string CompoundDuration(int n)
    {
        if (n < 0) return ""; // task doesn't ask for negative integers to be converted
        if (n == 0) return "0 sec";
        int weeks;
        int days;
        int hours;
        int minutes;
        int seconds;
        int divisor = 7 * 24 * 60 * 60;
        int rem;
        string result = "";
 
        weeks = n / divisor;
        rem = n % divisor;
        divisor /= 7;
        days = rem / divisor;
        rem %= divisor;
        divisor /= 24;
        hours = rem / divisor;
        rem %= divisor;
        divisor /= 60;
        minutes = rem / divisor;
        seconds = rem % divisor;
 
        if (weeks > 0) result += $"{weeks} wk, ";
        if (days > 0) result += $"{days} d, ";
        if (hours > 0) result += $"{hours} hr, ";
        if (minutes > 0) result += $"{minutes} min, ";
        if (seconds > 0)
            result += $"{seconds} sec";
        else
            result = result.Substring(0, result.Length - 2);
        return result;
    }
 
