namespace Converter
{
    class Game
    {
        static void Main(string[] args)
        {
            var d5 = new D5();
            var d7 = new D7(d5);
            test_distribution(d5, 1000000, 0.001);
            test_distribution(d7, 1000000, 0.001);
        }

        static void test_distribution(Func<int> d, int n, double epsilon)
        {
            var counts = new int[7];
            for (int i = 0; i < n; ++i)
            {
                ++counts[d() - 1];
            }
            for (int i = 0; i < 7; ++i)
            {
                Console.WriteLine(counts[i] / (double)n);
            }
        }

        class D5
        {
            public int Invoke()
            {
                return 5.0 * new Random().NextDouble() + 1;
            }
        }

        class D7
        {
            private D5 d5;
            private int rem;
            private int max;

            public D7(D5 d5)
            {
                this.d5 = d5;
                rem = 0;
                max = 1;
            }

            public int Invoke()
            {
                while (rem / 7 == max / 7)
                {
                    while (max < 7)
                    {
                        int rand5 = d5.Invoke() - 1;
                        max *= 5;
                        rem = 5 * rem + rand5;
                    }

                    int groups = max / 7;
                    if (rem >= 7 * groups)
                    {
                        rem -= 7 * groups;
                        max -= 7 * groups;
                    }
                }

                int result = rem % 7;
                rem /= 7;
                max /= 7;
                return result + 1;
            }
        }
    }
}

