public abstract class PasswordService
{
    // Base class for password handling services
}

public class ClearTextPasswordService : PasswordService
{
    // Process the password for storage (returns the password unchanged)
    public string ProcessPasswordForStorage(string clearTextPassword)
    {
        return clearTextPassword;
    }

    // Compare the provided password with the stored password
    public bool PasswordEquals(string clearTextPassword, string storedPassword)
    {
        return string.Equals(clearTextPassword, storedPassword, StringComparison.Ordinal);
    }
}

class Service
{
    static void Main()
    {
        ClearTextPasswordService passwordService = new ClearTextPasswordService();

        string passwordToStore = "myInsecurePassword";
        string storedPassword = passwordService.ProcessPasswordForStorage(passwordToStore);

        Console.WriteLine("Stored Password: " + storedPassword);

        string passwordToCheck = "myInsecurePassword";
        bool isMatch = passwordService.PasswordEquals(passwordToCheck, storedPassword);

        Console.WriteLine("Password Match: " + isMatch);
    }
}

