            _translationService = translationService;
        }

        public override ConversationResponse Respond(HttpContextBase context, LuisResult luisResult)
        {
            // Define the virtual path for the version XML file.
            string virtualPath = "~/App_Data/Version.xml";
            // Map the virtual path to a physical location on the server.
            string physicalPath = context.Server.MapPath(virtualPath);

            // Check if the version file exists.
            if (!File.Exists(physicalPath))
            {
                // Gracefully return an empty response if file is missing.
                return _responseFactory.Create(string.Empty);
            }

            try
            {
                // Load the XML document from the file.
                XDocument xmlDoc = XDocument.Load(physicalPath);

                // Navigate to find the version elements: major, minor, and revision.
                string major = xmlDoc.Descendants("major").FirstOrDefault()?.Value ?? "0";
                string minor = xmlDoc.Descendants("minor").FirstOrDefault()?.Value ?? "0";
                string revision = xmlDoc.Descendants("revision").FirstOrDefault()?.Value ?? "0";

                // Format the localized response using the translation service.
                string localizedText = _translationService.Translate("CurrentSystemVersion", context);
                string message = string.Format("{0}: {1}.{2}.{3}", localizedText, major, minor, revision);

                // Create and return a conversational response.
                return _responseFactory.Create(message);
            }
            catch (Exception ex)
            {
                // Optionally log the exception details here.
                // For now, we return an empty response.

