public class TimeOscillator
{
    private DS3232Connection _ds3232;
    private const byte STATUS_REGISTER = 0x0F;
    private const byte CONTROL_REGISTER = 0x0E;
    private const byte EOSC_BIT = 7;
    private const byte BBSQW_BIT = 2;

    public TimeOscillator(DS3232Connection ds3232)
    {
        _ds3232 = ds3232;
    }

    public bool IsOscillatorStopped
    {
        get
        {
            byte status = _ds3232.Read(STATUS_REGISTER);
            return (status & (1 << EOSC_BIT)) != 0;
        }
    }

    public bool IsBusy
    {
        get
        {
            byte status = _ds3232.Read(STATUS_REGISTER);
            return (status & (1 << BBSQW_BIT)) != 0;
        }
    }

    public void EnableOnBattery()
    {
        _ds3232.WriteBit(CONTROL_REGISTER, EOSC_BIT, false);
    }

    public void DisableOnBattery()
    {
        _ds3232.WriteBit(CONTROL_REGISTER, EOSC_BIT, true);
    }

    public void ToggleEnableOnBattery()
    {
        _ds3232.ToggleBit(CONTROL_REGISTER, EOSC_BIT);
    }

    public void Test()
    {
        Console.WriteLine("Testing TimeOscillator...");
        Console.WriteLine("Is Oscillator Stopped: " + IsOscillatorStopped);
        Console.WriteLine("Is Busy: " + IsBusy);

        Console.WriteLine("Disabling Oscillator on Battery...");
        DisableOnBattery();
        Console.WriteLine("Is Oscillator Stopped: " + IsOscillatorStopped);

        Console.WriteLine("Enabling Oscillator on Battery...");
        EnableOnBattery();
        Console.WriteLine("Is Oscillator Stopped: " + IsOscillatorStopped);

        Console.WriteLine("Toggling Oscillator on Battery...");
        ToggleEnableOnBattery();
        Console.WriteLine("Is Oscillator Stopped: " + IsOscillatorStopped);

        Console.WriteLine("Test Complete.");
    }
}

