public interface IArguments
{
    object GetValue();
}

public class ExpressionEventArgs : EventArgs
{
    private string _expression;
    private Exception _exception;
    private List<IArguments> _arguments;
    private object _result;

    public string Expression => _expression;
    public Exception Exception => _exception;
    public IReadOnlyList<IArguments> Arguments => _arguments.AsReadOnly();
    public object Result => _result;

    public ExpressionEventArgs(string expression, List<IArguments> arguments)
    {
        _expression = expression;
        _arguments = arguments;
        _result = null;
        _exception = null;
    }

    public void SetResult(object result)
    {
        _result = result;
    }

    public void SetException(Exception exception)
    {
        _exception = exception;
    }

    public void LogEvent()
    {
        Console.WriteLine($"Expression: {_expression}");
        if (_exception != null)
        {
            Console.WriteLine($"Exception: {_exception.Message}");
        }
        Console.WriteLine("Arguments:");
        foreach (var arg in _arguments)
        {
            Console.WriteLine($"- {arg.GetValue()}");
        }
        Console.WriteLine($"Result: {_result}");
    }
}

public class Argument : IArguments
{
    private object _value;

    public Argument(object value)
    {
        _value = value;
    }

    public object GetValue()
    {
        return _value;
    }
}

public class ExpressionEvaluator
{
    public event EventHandler<ExpressionEventArgs> ExpressionEvaluated;

    public void Evaluate(string expression, List<IArguments> arguments)
    {
        var eventArgs = new ExpressionEventArgs(expression, arguments);
        try
        {
            var result = ExecuteExpression(expression, arguments);
            eventArgs.SetResult(result);
        }
        catch (Exception ex)
        {
            eventArgs.SetException(ex);
        }
        finally
        {
            OnExpressionEvaluated(eventArgs);
        }
    }

    protected virtual void OnExpressionEvaluated(ExpressionEventArgs e)
    {
        ExpressionEvaluated?.Invoke(this, e);
    }

    private object ExecuteExpression(string expression, List<IArguments> arguments)
    {
        // Simulated expression evaluation logic
        if (expression == "Throw")
        {
            throw new InvalidOperationException("Simulated exception");
        }
        return 42; // Simulated result
    }
}

