public static double Distance(Point p1, Point p2)
{
    var dx = Math.Abs(p1.X - p2.X);
    var dy = Math.Abs(p1.Y - p2.Y);
    return Math.Sqrt(dx * dx + dy * dy);
}
 
public static (double distance, Point[] points) BruteforceClosestPair(Point[] arr)
{
    if (arr.Length < 2)
    {
        return (double.PositiveInfinity, null);
    }
    else
    {
        var minDist = Distance(arr[0], arr[1]);
        var minPoints = new[] { arr[0], arr[1] };
 
        for (var i = 0; i < arr.Length - 1; i++)
        {
            for (var j = i + 1; j < arr.Length; j++)
            {
                if (Distance(arr[i], arr[j]) < minDist)
                {
                    minDist = Distance(arr[i], arr[j]);
                    minPoints = new[] { arr[i], arr[j] };
                }
            }
        }
        return (minDist, minPoints);
    }
}

