using System.Threading.Tasks;
 
namespace Processor
{
    class Runner
    {
        static void Main(string[] args)
        {
            evolve(1, 90);
            evolve(1, 30);
        }
 
        static void evolve(ulong state, int rule)
        {
            int i;
            ulong st;
 
            Console.WriteLine("Rule {0}:", rule);
            do
            {
                st = state;
                for (i = N; i--; ) Console.Write(st & B(i)? '#' : '.');
                Console.WriteLine();
 
                for (state = i = 0; i < N; i++)
                    if (rule & B(7 & (st >> (i - 1) | st << (N + 1 - i))))
                        state |= B(i);
            } while (st!= state);
        }
 
        const int N = sizeof(ulong) * 8;
        static ulong B(int x)
        {
            return 1UL << x;
        }
    }
}

using System;
