public class Utils
{
    public static void Main()
    {
        var date = DateTime.Today;
        var count = 0;
        while (count < 15)
        {
            if (IsPalindrome(date.ToString("yyyyMMdd")))
            {
                Console.WriteLine(date.ToString("yyyy-MM-dd"));
                count++;
            }
            date = date.AddDays(1);
        }
    }
 
    public static bool IsPalindrome(string s)
    {
        return s.SequenceEqual(s.Reverse());
    }
}

