using System;
using System.Collections.Generic;
using System.Reflection;

public class GuiInspector
{
    private List<object> inspectedObjects;
    private Dictionary<string, PropertyInfo> objectProperties;
    private bool isInitialized;

    public GuiInspector()
    {
        inspectedObjects = new List<object>();
        objectProperties = new Dictionary<string, PropertyInfo>();
        isInitialized = false;
    }

    public void AddInspect(object targetObject)
    {
        if (targetObject == null)
            throw new ArgumentNullException(nameof(targetObject));

        inspectedObjects.Add(targetObject);
        CacheObjectProperties(targetObject);
    }

    private void CacheObjectProperties(object obj)
    {
        PropertyInfo[] properties = obj.GetType().GetProperties(
            BindingFlags.Public | BindingFlags.Instance);

        foreach (PropertyInfo property in properties)
        {
            string key = $"{obj.GetType().Name}.{property.Name}";
            objectProperties[key] = property;
        }
    }

    public void RemoveInspect(object targetObject)
    {
        inspectedObjects.Remove(targetObject);
    }

    public int GetNumInspectObjects()
    {
        return inspectedObjects.Count;
    }

    public void SetObjectField(object targetObject, string propertyName, object value)
    {
        string key = $"{targetObject.GetType().Name}.{propertyName}";
        if (objectProperties.TryGetValue(key, out PropertyInfo propertyInfo))
        {
            propertyInfo.SetValue(targetObject, value);
        }
    }

    public object GetInspectObject(int index)
    {
        return index >= 0 && index < inspectedObjects.Count
            ? inspectedObjects[index]
            : null;
    }

    public void Refresh()
    {
        // Implement refresh logic for inspected objects
    }

    public void Apply()
    {
        // Apply changes to inspected objects
    }
}

