    public partial class SAPSessionInfo : UserControl
    {
        // Assume lv_SessionInfo is the ListView defined in XAML that displays session details.
        private ListView lv_SessionInfo;
        private GuiSession _currentSession;
        private SAPAutomationHelper _automationHelper;

        public SAPSessionInfo()
        {
            InitializeComponent();
            _automationHelper = new SAPAutomationHelper();
            SetupSessionEventSubscriptions();
        }

        private void SetupSessionEventSubscriptions()
        {
            // Assume Current_OnSetSession is triggered when a new session is set.
            _automationHelper.OnSetSession += Current_OnSetSession;
        }

        private void Current_OnSetSession(GuiSession session)
        {
            // Unsubscribe from previous events if any.
            if (_currentSession != null)
            {
                _currentSession.EndRequest -= Session_EndRequest;
                _currentSession.Destroy -= Session_Destroy;
            }

            _currentSession = session;
            if (_currentSession != null)
            {
                // Subscribe to session-specific events.
                _currentSession.EndRequest += Session_EndRequest;
                _currentSession.Destroy += Session_Destroy;
            }
            // Update the UI with current session properties.
            showSessionInfo();
        }

        private void Session_EndRequest(string info)
        {
            // Handle end of request event from session.
            showSessionInfo();
        }

        private void Session_Destroy(object sender, EventArgs e)
        {
            // Clean up UI when session is destroyed.
            Dispatcher.Invoke(() =>
            {
                lv_SessionInfo.ItemsSource = null;
            });
        }

        private void showSessionInfo()
        {
            if (_currentSession == null)
                return;

            // Retrieve dynamic properties from the session info through automation helper.
            object sessionInfo = _automationHelper.GetSessionInfo(_currentSession);
            if (sessionInfo == null)
                return;

            List<KeyValuePair<string, object>> infoList = new List<KeyValuePair<string, object>>();
            Type infoType = sessionInfo.GetType();

