namespace Artemis.Layers
{
    public class FolderLayerType : LayerType
    {
        private readonly ILayerModel _layerModel;
        private readonly SimplePropertiesModel _propertiesModel;

        public FolderLayerType(ILayerModel layerModel)
        {
            _layerModel = layerModel;
            _propertiesModel = new SimplePropertiesModel();
            DrawType = DrawType.Keyboard;
        }

        public override void DrawThumbnail(DrawingContext context, Rect bounds)
        {
            if (context == null || bounds == null)
                return;

            var folderIcon = CreateFolderIcon(bounds);
            context.DrawGeometry(Brushes.Gray, new Pen(Brushes.DarkGray, 1), folderIcon);
        }

        private Geometry CreateFolderIcon(Rect bounds)
        {
            var geometry = new StreamGeometry();
            using (var context = geometry.Open())
            {
                context.BeginFigure(new Point(bounds.Left, bounds.Bottom), true, true);
                context.LineTo(new Point(bounds.Right, bounds.Bottom), true, false);
                context.LineTo(new Point(bounds.Right, bounds.Top + bounds.Height * 0.7), true, false);
                context.LineTo(new Point(bounds.Left + bounds.Width * 0.2, bounds.Top + bounds.Height * 0.7), true, false);
                context.Close();
            }
            return geometry;
        }

        public override void Draw(DrawingContext context, Rect bounds)
        {
            // Minimal drawing for folder layer type
            if (context == null)
                return;
        }

        public override void Update()
        {
            // Implement layer update logic
            foreach (var childLayer in _layerModel.ChildLayers)
            {
                childLayer.Update();
            }
        }

        protected override void SetupProperties()
        {
            _propertiesModel.AddProperty("Name", "Folder Layer");
            _propertiesModel.AddProperty("Visible", true);
            _propertiesModel.AddProperty("Expanded", false);
        }

        protected override void SetupViewModel()
        {
            ViewModel = new FolderPropertiesViewModel
            {
                Name = _propertiesModel.GetProperty<string>("Name"),
                IsVisible = _propertiesModel.GetProperty<bool>("Visible"),
                IsExpanded = _propertiesModel.GetProperty<bool>("Expanded")
            };
        }
    }
}

 
using System;
 
public class Nybble
{
    public bool n3;
    public bool n2;
    public bool n1;
    public bool n0;
 
    public Nybble(bool n3, bool n2, bool n1, bool n0)
    {
        this.n3 = n3;
        this.n2 = n2;
        this.n1 = n1;
        this.n0 = n0;
    }
 
    public int toInt()
    {
        return (n0? 1 : 0) + (n1? 2 : 0) + (n2? 4 : 0) + (n3? 8 : 0);
    }
 
    public override string ToString()
    {
        return $"{(n3? 1 : 0)}{(n2? 1 : 0)}{(n1? 1 : 0)}{(n0? 1 : 0)}";
    }
}
 
public static class Extensions
{
    public static int I(this bool b)
    {
        return b? 1 : 0;
    }
 
    public static bool B(this int i)
    {
        return i!= 0;
    }
 
    public static Nybble toNybble(this int i)
    {
        bool[] n = new bool[4];
        for (int k = 0; k <= 3; k++)
        {
            n[k] = ((i >> k) & 1).B();
        }
        return new Nybble(n[3], n[2], n[1], n[0]);
    }
 
    public static bool xorGate(bool a, bool b)
    {
        return (a &&!b) || (!a && b);
    }
 
    public static Tuple<bool, bool> halfAdder(bool a, bool b)
    {
        return new Tuple<bool, bool>(xorGate(a, b), a && b);
    }
 
    public static Tuple<bool, bool> fullAdder(bool a, bool b, bool c)
    {
        var s1c1 = halfAdder(c, a);
        var s2c2 = halfAdder(s1c1.Item1, b);
        return new Tuple<bool, bool>(s2c2.Item1, s1c1.Item2 || s2c2.Item2);
    }
 
    public static Tuple<Nybble, int> fourBitAdder(Nybble a, Nybble b)
    {
        var s0c0 = fullAdder(a.n0, b.n0, false);
        var s1c1 = fullAdder(a.n1, b.n1, s0c0.Item2);
        var s2c2 = fullAdder(a.n2, b.n2, s1c1.Item2);
        var s3c3 = fullAdder(a.n3, b.n3, s2c2.Item2);
        return new Tuple<Nybble, int>(new Nybble(s3c3.Item1, s2c2.Item1, s1c1.Item1, s0c0.Item1), s3c3.Item2.I());
    }
}
 
public class Order
{
    public static void Main(string[] args)
    {
        Console.WriteLine(" A      B     C  R     I    J    S");
        for (int i = 0; i <= 15; i++)
        {
            for (int j = i; j <= Math.Min(i + 1, 15); j++)
            {
                test(i, j);
            }
        }
    }
 
    public static void test(int i, int j)
    {
        Nybble a = i.toNybble();
        Nybble b = j.toNybble();
        var r = fourBitAdder(a, b);
        int s = r.Item2 * 16 + r.Item1.toInt();
        Console.WriteLine($"{a} + {b} = {r.Item2} {r.Item1} ({i} + {j} = {s})");
    }
}

