using System.Transactions;
using NServiceBus;
using NServiceBus.AcceptanceTesting;
using NUnit.Framework;

public class DTCTest
{
    [Test]
    public void Should_enlist_the_receive_in_the_dtc_tx()
    {
        var context = Scenario.Define<Context>()
            .WithEndpoint<DTCEndpoint>(b => b.When(session => session.SendLocal(new MyMessage())))
            .Done(c => c.HandlerInvoked)
            .Run();

        Assert.IsTrue(context.HandlerInvoked);
        Assert.IsFalse(context.CanEnlistPromotable);
    }

    public class Context : ScenarioContext
    {
        public bool HandlerInvoked { get; set; }
        public bool CanEnlistPromotable { get; set; }
    }

    public class DTCEndpoint : EndpointConfigurationBuilder
    {
        public DTCEndpoint()
        {
            EndpointSetup<DefaultServer>();
        }
    }

    public class MyMessage : ICommand { }

    public class MyMessageHandler : IHandleMessages<MyMessage>
    {
        public Context Context { get; set; }

        public Task Handle(MyMessage message, IMessageHandlerContext handlerContext)
        {
            Context.HandlerInvoked = true;

            using (var tx = new TransactionScope(TransactionScopeOption.Required, TransactionScopeAsyncFlowOption.Enabled))
            {
                var promotable = new FakePromotableResourceManager();
                Context.CanEnlistPromotable = Transaction.Current.EnlistPromotableSinglePhase(promotable);

                tx.Complete();
            }

            return Task.CompletedTask;
        }
    }

    public class FakePromotableResourceManager : IPromotableSinglePhaseNotification
    {
        public void Initialize() { }
        public void SinglePhaseCommit(SinglePhaseEnlistment singlePhaseEnlistment) { }
        public void Rollback(SinglePhaseEnlistment singlePhaseEnlistment) { }
        public byte[] Promote() => Array.Empty<byte>();
    }
}

