for (int i = 1; i <= 10; i++)
{
    Console.WriteLine(i + " : " + string.Join(" x ", factor(i)));
}

static List<int> factor(int n)
{
    var factors = new List<int>();
    if (n == 1) return new List<int> { 1 };
    for (int p = 2; p <= n; )
    {
        if ((n % p) == 0)
        {
            factors.Add(p);
            n /= p;
        }
        else p++;
    }
    return factors;
}

