public class EdgeHost
{
    private readonly ConcurrentDictionary<string, IFable> Fables = new ConcurrentDictionary<string, IFable>();
    private readonly ConcurrentDictionary<(string fableName, string topicName, object sink), IDisposable> Subscribtions = new ConcurrentDictionary<(string, string, object), IDisposable>();

    public void AddFable(string fableName, IFable fable)
    {
        Fables.TryAdd(fableName, fable);
    }

    public void RemoveFable(string fableName)
    {
        Fables.TryRemove(fableName, out _);
    }

    public void SubscribeTopic(object payload)
    {
        var fableName = (string)payload.GetType().GetProperty("fable").GetValue(payload);
        var topicName = (string)payload.GetType().GetProperty("topic").GetValue(payload);
        var sink = payload.GetType().GetProperty("sink").GetValue(payload);

        SubscribeTopicPrivate(fableName, topicName, sink);
    }

    private void SubscribeTopicPrivate(string fableName, string topicName, object sink)
    {
        if (!Fables.TryGetValue(fableName, out var fable))
        {
            throw new Exception($"Fable '{fableName}' not found.");
        }

        var key = (fableName, topicName, sink);

        if (!Subscribtions.ContainsKey(key))
        {
            var eventSink = new EdgeEventSink(sink);
            var subscribtion = fable.Subscribe(topicName, eventSink.OnEvent);
            Subscribtions.TryAdd(key, subscribtion);
        }
    }

    public void UnsubscribeTopic(object payload)
    {
         var fableName = (string)payload.GetType().GetProperty("fable").GetValue(payload);
         var topicName = (string)payload.GetType().GetProperty("topic").GetValue(payload);
         var sink = payload.GetType().GetProperty("sink").GetValue(payload);

        var key = (fableName, topicName, sink);

        if (Subscribtions.TryRemove(key, out var subscribtion))
        {
            subscribtion.Dispose();
        }
    }
}

public interface IFable
{
    IDisposable Subscribe(string topic, Action<object> onEvent);
}

