using Microsoft.Extensions.Logging;
using Newtonsoft.Json;
using StackExchange.Redis;
using System.Collections.Generic;
using System.Threading.Tasks;

public class RedisBasketRepository : IBasketRepository
{
    private readonly ILogger<RedisBasketRepository> _logger;
    private readonly ConnectionMultiplexer _redis;
    private readonly IDatabase _database;

    public RedisBasketRepository(ILoggerFactory loggerFactory, ConnectionMultiplexer redis)
    {
        _logger = loggerFactory.CreateLogger<RedisBasketRepository>();
        _redis = redis;
        _database = redis.GetDatabase();
    }

    public async Task<bool> DeleteBasketAsync(string id)
    {
        var deleted = await _database.KeyDeleteAsync(id);
        if (deleted)
        {
            _logger.LogInformation($"Basket {id} deleted successfully.");
        }
        else
        {
            _logger.LogWarning($"Basket {id} not found or could not be deleted.");
        }
        return deleted;
    }

    public async Task<CustomerBasket> GetBasketAsync(string customerId)
    {
        var data = await _database.StringGetAsync(customerId);
        if (data.IsNullOrEmpty)
        {
            _logger.LogInformation($"Basket for customer {customerId} not found.");
            return null;
        }
        return JsonConvert.DeserializeObject<CustomerBasket>(data);
    }

    public async Task<CustomerBasket> UpdateBasketAsync(CustomerBasket basket)
    {
        var created = await _database.StringSetAsync(basket.CustomerId, JsonConvert.SerializeObject(basket));
        if (!created)
        {
            _logger.LogError($"Failed to update basket for customer {basket.CustomerId}.");
            return null;
        }
        _logger.LogInformation($"Basket for customer {basket.CustomerId} updated successfully.");
        return await GetBasketAsync(basket.CustomerId);
    }

    public async Task<List<string>> GetUsers()
    {
        var server = GetServer();
        var keys = server.Keys(pattern: "user-*");
        var users = new List<string>();
        foreach (var key in keys)
        {
            users.Add(key.ToString());
        }
        return users;
    }

    private IServer GetServer()
    {
        var endpoint = _redis.GetEndPoints();
        return _redis.GetServer(endpoint[0]);
    }
}

