namespace LearningSystem.Services
{
    public class TrainerService
    {
        private readonly LearningSystemDbContext _context;
        private readonly IMapper _mapper;

        public TrainerService(LearningSystemDbContext context, IMapper mapper)
        {
            _context = context;
            _mapper = mapper;
        }

        public async Task<IEnumerable<CourseListingServiceModel>> CoursesAsync(int trainerId)
        {
            return await _context.Courses
                .Where(c => c.TrainerId == trainerId)
                .ProjectTo<CourseListingServiceModel>(_mapper.ConfigurationProvider)
                .ToListAsync();
        }

        public async Task<bool> IsTrainerAsync(int trainerId, int courseId)
        {
            return await _context.Courses
                .AnyAsync(c => c.Id == courseId && c.TrainerId == trainerId);
        }

        public async Task<IEnumerable<StudentInCourseServiceModel>> StudentsInCourseAsync(int courseId)
        {
            return await _context.StudentCourses
                .Where(sc => sc.CourseId == courseId)
                .Select(sc => new StudentInCourseServiceModel
                {
                    StudentId = sc.StudentId,
                    CourseId = sc.CourseId,
                    Grade = sc.Grade
                })
                .ToListAsync();
        }

        public async Task<bool> AddGradeAsync(int studentId, int courseId, double grade)
        {
            var studentCourse = await _context.StudentCourses
                .FirstOrDefaultAsync(sc => sc.StudentId == studentId && sc.CourseId == courseId);

            if (studentCourse == null)
            {
                return false;
            }

            studentCourse.Grade = grade;
            await _context.SaveChangesAsync();
            return true;
        }
    }

