namespace UWPApp
{
    public class PageBase : Page
    {
        private NavigationHelper _navigationHelper;
        private const string StateKey = "PageState";

        public PageBase()
        {
            _navigationHelper = new NavigationHelper(this);
            _navigationHelper.LoadState += NavigationHelperLoadState;
            _navigationHelper.SaveState += NavigationHelperSaveState;
        }

        protected override void OnNavigatedTo(NavigationEventArgs e)
        {
            base.OnNavigatedTo(e);
            _navigationHelper.OnNavigatedTo(e);
        }

        protected override void OnNavigatedFrom(NavigationEventArgs e)
        {
            base.OnNavigatedFrom(e);
            _navigationHelper.OnNavigatedFrom(e);
        }

        private void NavigationHelperLoadState(object sender, LoadStateEventArgs e)
        {
            if (e.PageState != null && e.PageState.ContainsKey(StateKey))
            {
                LoadState(e.PageState[StateKey]);
            }
        }

        private void NavigationHelperSaveState(object sender, SaveStateEventArgs e)
        {
            var state = SaveState();
            if (state != null)
            {
                e.PageState[StateKey] = state;
            }
        }

        protected virtual void LoadState(object state)
        {
            // Override in derived classes to load custom state
        }

        protected virtual object SaveState()
        {
            // Override in derived classes to save custom state
            return null;
        }
    }

    public class NavigationHelper
    {
        private Page _page;

        public NavigationHelper(Page page)
        {
            _page = page;
        }

        public event LoadStateEventHandler LoadState;
        public event SaveStateEventHandler SaveState;

        public void OnNavigatedTo(NavigationEventArgs e)
        {
            LoadState?.Invoke(this, new LoadStateEventArgs(e.Parameter, _page.Frame.BackStackDepth));
        }

        public void OnNavigatedFrom(NavigationEventArgs e)
        {
            SaveState?.Invoke(this, new SaveStateEventArgs(_page.Frame.BackStackDepth));
        }
    }

    public class LoadStateEventArgs
    {
        public object NavigationParameter { get; }
        public int NavigationState { get; }

        public LoadStateEventArgs(object navigationParameter, int navigationState)
        {
            NavigationParameter = navigationParameter;
            NavigationState = navigationState;

