using UnityEngine;

public class Dinas : SolidBlock
{
    private static Block coalReference;

    public override Block Clone()
    {
        return new Dinas
        {
            temperature = temperature,
            press = press,
            transmissivity = transmissivity
        };
    }

    public override void Update()
    {
        base.Update();
        dinasMoveRule();
        dinasReduceRule();
    }

    private void dinasMoveRule()
    {
        Vector2Int belowPos = BlocksEngine.GetDirPos(position, Dir.down);
        Block belowBlock = BlocksManager.GetBlock(belowPos);

        if (belowBlock is FluidBlock || belowBlock is AirBlock)
        {
            BlocksEngine.SwapBlocks(position, belowPos);
        }
    }

    private void dinasReduceRule()
    {
        if (temperature <= 600) return;

        foreach (Dir dir in new[] { Dir.up, Dir.left, Dir.down, Dir.right })
        {
            Vector2Int checkPos = BlocksEngine.GetDirPos(position, dir);
            Block neighbor = BlocksManager.GetBlock(checkPos);

            if (neighbor is Coal)
            {
                dinasReduceMethod();
                return;
            }
        }
    }

    private void dinasReduceMethod()
    {
        Silicon newBlock = new Silicon
        {
            temperature = temperature,
            press = press * 0.8f
        };

        BlocksManager.ReplaceBlock(position, newBlock);
    }

    private void OnEnable()
    {
        if (coalReference == null)
            coalReference = BlocksManager.GetBlockPrototype<Coal>();
    }
}

