class Builder
{
    static void RunCode(string code)
    {
        int accumulator = 0;
        var opcodes = new Dictionary<char, Action>
        {
            {'H', () => Console.WriteLine("Hello, World!"))},
            {'Q', () => Console.WriteLine(code) },
            {'9', () => Console.WriteLine(Enumerable.Range(1,100).Reverse().Select(n => string.Format("{0} bottles of beer on the wall\n{0} bottles of beer\nTake one down, pass it around\n{1} bottles of beer on the wall\n", n, n-1)).Aggregate((a,b) => a + "\n" + b))},
            {'+', () => accumulator++ }
        }
 
        foreach(var c in code)
            opcodes[c]();
    }
}

using System;
using System.Collections.Generic;

namespace ConditionFramework
{
    public abstract class ConditionBase
    {
        public abstract bool Evaluate();

        public AndCondition And(ConditionBase other)
        {
            if (this is AndCondition andCond)
            {
                andCond.AddCondition(other);
                return andCond;
            }
            return new AndCondition(this, other);
        }

        public OrCondition Or(ConditionBase other)
        {
            if (this is OrCondition orCond)
            {
                orCond.AddCondition(other);
                return orCond;
            }
            return new OrCondition(this, other);
        }

        public NotCondition Not()
        {
            return new NotCondition(this);
        }
    }

    public class AndCondition : ConditionBase
    {
        private readonly List<ConditionBase> _conditions = new List<ConditionBase>();

        public AndCondition(params ConditionBase[] initialConditions)
        {
            _conditions.AddRange(initialConditions);
        }

        public void AddCondition(ConditionBase condition)
        {
            _conditions.Add(condition);
        }

        public override bool Evaluate()
        {
            foreach (var condition in _conditions)
            {
                if (!condition.Evaluate())
                    return false;
            }
            return true;
        }
    }

    public class OrCondition : ConditionBase
    {
        private readonly List<ConditionBase> _conditions = new List<ConditionBase>();

        public OrCondition(params ConditionBase[] initialConditions)
        {
            _conditions.AddRange(initialConditions);
        }

        public void AddCondition(ConditionBase condition)
        {
            _conditions.Add(condition);
        }

        public override bool Evaluate()
        {
            foreach (var condition in _conditions)
            {
                if (condition.Evaluate())
                    return true;
            }
            return false;
        }
    }

    public class NotCondition : ConditionBase
    {
        private readonly ConditionBase _condition;

        public NotCondition(ConditionBase condition)
        {
            _condition = condition;
        }

        public override bool Evaluate()
        {
            return !_condition.Evaluate();
        }
    }

    public class SimpleCondition : ConditionBase
    {
        private readonly bool _state;

        public SimpleCondition(bool state)
        {

/*============================================================
