using System;
using System.Drawing;
using System.Windows.Forms;
 
namespace JuliaSet
{
    public class JuliaPanel : Panel
    {
        public JuliaPanel()
        {
            this.Size = new Size(800, 600);
            this.BackColor = Color.White;
        }
 
        private int maxIterations = 300;
        private double zoom = 1;
        private double moveX = 0.0;
        private double moveY = 0.0;
        private double cX = -0.7;
        private double cY = 0.27015;
 
        protected override void OnPaint(PaintEventArgs e)
        {
            base.OnPaint(e);
            e.Graphics.SmoothingMode = System.Drawing.Drawing2D.SmoothingMode.AntiAlias;
            Bitmap image = new Bitmap(this.Width, this.Height);
            for (int x = 0; x < this.Width; x++)
            {
                for (int y = 0; y < this.Height; y++)
                {
                    double zx = 1.5 * (x - this.Width / 2) / (0.5 * zoom * this.Width) + moveX;
                    double zy = (y - this.Height / 2) / (0.5 * zoom * this.Height) + moveY;
                    double i = maxIterations;
                    while (zx * zx + zy * zy < 4 && i > 0)
                    {
                        double tmp = zx * zx - zy * zy + cX;
                        zy = 2.0 * zx * zy + cY;
                        zx = tmp;
                        i--;
                    }
                    image.SetPixel(x, y, Color.FromArgb(maxIterations / (int)i % 1, 1, (int)(i > 0? 1 : 0)));
                }
            }
            e.Graphics.DrawImage(image, 0, 0);
        }
    }
 
    public class Manager
    {
        public static void Main()
        {
            Application.Run(new Form()
            {
                Text = "Julia Set",
                Size = new Size(800, 600),
                StartPosition = FormStartPosition.CenterScreen,
                FormBorderStyle = FormBorderStyle.FixedSingle,
                MaximizeBox = false,
                MinimizeBox = false,
                Controls = { new JuliaPanel() }
            });
        }
    }
}

