namespace OlafBot
{
    public static class Logics
    {
        public static void Combo(EventArgs args)
        {
            var target = Targets.TargetSelector.GetTarget(Vars.Q.Range, DamageType.Physical);
            if (target == null || !target.IsValidTarget() || Check(target))
                return;

            if (HasSheenBuff() && GetValue<MenuBool>("useSheen").Value)
            {
                Cast(Vars.Q, target);
            }

            if (Vars.W.IsReady() && GetValue<MenuBool>("useW").Value)
            {
                if (target.HasBuffOfType(BuffType.Slow) || target.Distance(GameObjects.Player) < Vars.W.Range * 0.8f)
                {
                    Vars.W.Cast();
                }
            }

            if (Vars.Q.IsReady() && GetValue<MenuBool>("useQ").Value)
            {
                var pred = GetPrediction(target);
                if (pred.HitChance >= HitChance.High)
                {
                    Vars.Q.Cast(pred.CastPosition);
                }
            }
        }

        private static bool HasSheenBuff()
        {
            return GameObjects.Player.HasBuff("sheen") || GameObjects.Player.HasBuff("lichbane") || GameObjects.Player.HasBuff("triforce");
        }

        private static bool IsValidTarget(float range)
        {
            var target = Targets.TargetSelector.GetTarget(range, DamageType.Physical);
            return target != null && target.IsValidTarget(range);
        }

        private static bool Check(GameObject target)
        {
            return target.IsInvulnerable || target.IsZombie || target.HasBuff("JudicatorIntervention");
        }

        private static bool IsReady(Spell.SpellBase spell)
        {
            return spell.IsReady;
        }

        private static T GetValue<T>(string name) where T : ValueBase
        {
            return Vars.Menu[name];
        }

        private static void Cast(Spell.SpellBase spell, GameObject target)
        {
            if (spell.IsReady && target.IsValidTarget(spell.Range))
            {
                var pred = GetPrediction(target);
                if (pred.HitChance >= HitChance.High)
                {
                    spell.Cast(pred.CastPosition);
                }
            }
        }

