// Encapsulates animation tasks for building entries
public class InitialBuildingEntryAnimation : MonoBehaviour
{
    private float baseStaggerTime = 1.0f;
    private float structStaggerTime = 0.5f;
    private float terrainStaggerTime = 0.3f;
    private List<Task> runTasks = new List<Task>();

    private TaskManager taskManager;

    void Start()
    {
        taskManager = new TaskManager();
        Init();
    }

    void Update()
    {
        taskManager.UpdateTasks();
    }

    // Initializes the animation tasks
    private void Init()
    {
        QueueBuildingEntryTasks();
        taskManager.StartTasks(runTasks);
    }

    // Queues different building entry animations
    private void QueueBuildingEntryTasks()
    {
        runTasks.Add(new Task("MainBase", baseStaggerTime));
        runTasks.Add(new Task("AdditionalStructure1", structStaggerTime));
        runTasks.Add(new Task("AdditionalStructure2", structStaggerTime));
        runTasks.Add(new Task("TerrainFeature1", terrainStaggerTime));
    }
}

// Manages and executes tasks sequentially
public class TaskManager
{
    private Queue<Task> taskQueue = new Queue<Task>();
    private bool isExecuting = false;

    public void StartTasks(List<Task> tasks)
    {
        foreach (var task in tasks)
        {
            taskQueue.Enqueue(task);
        }
        if (!isExecuting)
        {
            ExecuteNextTask();
        }
    }

    private void ExecuteNextTask()
    {
        if (taskQueue.Count > 0)
        {
            isExecuting = true;
            Task currentTask = taskQueue.Dequeue();
            MonoBehaviour.StartCoroutine(AnimateTask(currentTask));
        }
        else
        {
            isExecuting = false;
        }
    }

    private IEnumerator AnimateTask(Task task)
    {
        Debug.Log($"Animating: {task.Name}");
        yield return new WaitForSeconds(task.Time);
        Debug.Log($"Completed: {task.Name}");
        ExecuteNextTask();
    }

    public void UpdateTasks()
    {
        // Logic for updating task status (if necessary)
    }
}

