using Castle.DynamicProxy;
using Sitecore.Data.Items;
using Glass.Sitecore.Mapper.Configuration;

namespace SitecoreProxy
{
  // Custom proxy generation hook to filter methods for interception.
  public class CustomProxyGenerationHook : IProxyGenerationHook
  {
    public void MethodsInspected() { }
    public void NonProxyableMemberNotification(Type type, System.Reflection.MemberInfo memberInfo) { }
    public bool ShouldInterceptMethod(System.Reflection.MethodInfo methodInfo)
    {
      // Intercept only public methods, skipping getters/setters.
      return methodInfo.IsPublic && !methodInfo.IsSpecialName;
    }
  }

  // Interceptor for interface proxies.
  public class InterfaceInterceptor : IInterceptor
  {
    public void Intercept(IInvocation invocation)
    {
      // Retrieve Sitecore item data or mapping logic here.
      Console.WriteLine("Intercepting interface method: " + invocation.Method.Name);
      invocation.ReturnValue = null;
    }
  }

  // Interceptor for class proxies.
  public class ClassInterceptor : IInterceptor
  {
    public void Intercept(IInvocation invocation)
    {
      // Extend class behavior by handling method interception.
      Console.WriteLine("Intercepting class method: " + invocation.Method.Name);
      invocation.Proceed();
    }
  }

  // Configuration object representing Sitecore class mapping.
  public class SitecoreClassConfig
  {
    public Type TargetType { get; set; }
    public string MappingDetails { get; set; }
  }

  // Central class that creates dynamic proxies for Sitecore items.
  public static class DynamicProxyFactory
  {
    private static readonly ProxyGenerator ProxyGenerator = new ProxyGenerator();
    private static readonly ProxyGenerationOptions ProxyOptions = new ProxyGenerationOptions(new CustomProxyGenerationHook());

    public static T CreateProxy<T>(SitecoreClassConfig config, Item item) where T : class
    {
      Type targetType = config.TargetType;
      // If the target type is an interface, create an interface proxy without a target.
      if (targetType.IsInterface)
      {
        return ProxyGenerator.CreateInterfaceProxyWithoutTarget<T>(ProxyOptions, new InterfaceInterceptor());
      }
      // For classes, create a proxy that inherits from the concrete type.
      return ProxyGenerator.CreateClassProxy(targetType, ProxyOptions, new ClassInterceptor()) as T;
    }
  }

