        {
            Source = string.Empty;
        }
    }

    public class ClientInfo
    {
        public IPEndPoint EndPoint { get; private set; }

        public ClientInfo(IPEndPoint endPoint)
        {
            EndPoint = endPoint;
        }
    }

    public class ClientData
    {
        public HttpRequest Request { get; private set; }
        public ClientState State { get; private set; }
        public int BytesRead { get; private set; }
        public int BytesSkipped { get; private set; }
        public ClientInfo Info { get; private set; }

        public ClientData(ClientInfo info)
        {
            Info = info;
            Request = new HttpRequest();
            Request.Source = info.EndPoint?.Address.ToString() ?? "Unknown";
            State = ClientState.ProcessingHeaders;
            BytesRead = 0;
            BytesSkipped = 0;
        }

        public void ProcessHeader(byte[] data, int offset, int count)
        {
            // Mock processing logic: increment counters for demonstration
            BytesRead += count;
            if (IsHeaderComplete(data, offset, count))
            {
                State = ClientState.ProcessingBody;
            }
        }

        private bool IsHeaderComplete(byte[] data, int offset, int count)
        {
            // Check for the CRLF CRLF sequence indicating end of HTTP headers
            if (count < 4)
                return false;
            for (int i = offset; i < offset + count - 3; i++)
            {
                if (data[i] == '\r' && data[i + 1] == '\n' &&
                    data[i + 2] == '\r' && data[i + 3] == '\n')
                {
                    return true;
                }
            }
            return false;
        }
    }

