public static class NetUtility
{
    private static Random s_randomGenerator;
    private static byte[] s_randomMacBytes;
    private static object s_lockObject = new object();

    static NetUtility()
    {
        s_randomGenerator = new Random(Environment.TickCount);
        InitializeMacAddressBytes();
    }

    private static void InitializeMacAddressBytes()
    {
        s_randomMacBytes = new byte[6];
        s_randomGenerator.NextBytes(s_randomMacBytes);
        s_randomMacBytes[0] &= 0xFE; // Ensure unicast address
    }

    public static byte[] GetMacAddressBytes()
    {
        lock (s_lockObject)
        {
            if (s_randomMacBytes == null)
            {
                InitializeMacAddressBytes();
            }
            return (byte[])s_randomMacBytes.Clone();
        }
    }

    public static IPAddress GetMyAddress(Context context)
    {
        try
        {
            WifiManager wifiManager = (WifiManager)context.GetSystemService(Context.WifiService);
            int ipAddress = wifiManager.ConnectionInfo.IpAddress;

            byte[] bytes = BitConverter.GetBytes(ipAddress);
            Array.Reverse(bytes);
            return new IPAddress(bytes);
        }
        catch (Exception)
        {
            return IPAddress.Loopback;
        }
    }

    public static string ComputeSHAHash(byte[] input, int hashLength = 256)
    {
        using (var hashAlgorithm = hashLength == 256
            ? SHA256.Create()
            : (HashAlgorithm)SHA512.Create())
        {
            byte[] hashBytes = hashAlgorithm.ComputeHash(input);
            return BitConverter.ToString(hashBytes).Replace("-", "");
        }
    }

    public static long GetPlatformSeed()
    {
        return (long)DateTime.UtcNow.Ticks ^ Environment.TickCount ^ GetHashCode();
    }
}

