namespace MyApp
{
    [Register("AppDelegate")]
    public class AppDelegate : UIApplicationDelegate
    {
        private UIWindow _window;
        private Home _home;
        private Bootstrapper _bootstrapper;

        public override bool FinishedLaunching(UIApplication application, NSDictionary launchOptions)
        {
            _window = new UIWindow(UIScreen.MainScreen.Bounds);
            _bootstrapper = new Bootstrapper();
            _bootstrapper.FinishedBootstrapping += OnFinishedBootstrapping;

            // Initialize Home screen and set as root
            _home = _bootstrapper.Resolve<Home>();
            _window.RootViewController = _home;

            // Customize appearance
            SetAppearance();

            // Show the window
            _window.MakeKeyAndVisible();

            // Start bootstrapping process
            _bootstrapper.Bootstrap();

            return true;
        }

        private void OnFinishedBootstrapping(object sender, System.EventArgs e)
        {
            // Simulate loading delay
            BeginInvokeOnMainThread(async () =>
            {
                await System.Threading.Tasks.Task.Delay(2000); // 2-second delay
                BTProgressHUD.Dismiss();

                // Transition to Login screen
                var login = _bootstrapper.Resolve<Login>();
                var navigationController = new UINavigationController(login);
                _window.RootViewController = navigationController;
            });
        }

        private void SetAppearance()
        {
            // Customize navigation bar appearance
            UINavigationBar.Appearance.BarTintColor = UIColor.FromRGB(0, 122, 255);
            UINavigationBar.Appearance.TintColor = UIColor.White;
            UINavigationBar.Appearance.TitleTextAttributes = new UIStringAttributes
            {
                ForegroundColor = UIColor.White
            };

            // Customize status bar style
            UIApplication.SharedApplication.SetStatusBarStyle(UIStatusBarStyle.LightContent, false);
        }
    }

    public class Bootstrapper
    {
        public event EventHandler FinishedBootstrapping;

        public void Bootstrap()
        {
            // Simulate bootstrapping process
            BeginInvokeOnMainThread(async () =>
            {
                await System.Threading.Tasks.Task.Delay(1000); // Simulate async work
                FinishedBootstrapping?.Invoke(this, EventArgs.Empty);
            });
        }

