{
    // ViewModel to persist log text.
    public class SettingsViewModel
    {
        public string LogText { get; set; }

        public SettingsViewModel()
        {
            LogText = string.Empty;
        }
    }

    // Logging module implementing a singleton-like pattern.
    public class LogsModules : IModule, IDisposable
    {
        private static LogsModules _current;
        public static LogsModules Current
        {
            get
            {
                if (_current == null)
                    _current = new LogsModules();
                return _current;
            }
        }

        public SettingsViewModel SettingsViewModel { get; set; }

        // Private constructor ensures only one instance.
        private LogsModules()
        {
            SettingsViewModel = new SettingsViewModel();
            Initialize();
        }

        // Sets up subscriptions to global messaging events.
        public void Initialize()
        {
            // Subscribe to standard log messages.
            GenericMessager.Current.Register<string>("LogMessage", AppendLogs);
            // Subscribe to exception notifications.
            GenericMessager.Current.Register<Exception>("LogException", AppendLogsForException);
        }

        // Appends a timestamped message to the log and forwards it.
        public void AppendLogs(string message)
        {
            string timestamp = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss.fff");
            string logEntry = $"[{timestamp}] {message}{Environment.NewLine}";
            SettingsViewModel.LogText += logEntry;

            // Forward the log message to a designated helper.
            LogHelper.LogMessage(logEntry);
        }

        // Handles exception logging; appends to log and forwards details.
        public void AppendLogsForException(Exception ex)
        {
            string timestamp = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss.fff");
            string logEntry = $"[{timestamp}] Exception: {ex.Message}{Environment.NewLine}";
            SettingsViewModel.LogText += logEntry;

            // Forward the exception details for further processing.
            LogHelper.LogException(ex, logEntry);
        }

        // Cleanup: Unregister event handlers.
        public void Dispose()
        {

