using System;
using Serilog;
using Serilog.Configuration;
using Serilog.Events;
using Serilog.Sinks.NLog;

namespace Serilog.Sinks.NLog
{
    public static class LoggerConfigurationsNLogExtensions
    {
        /// <summary>
        /// Adds a sink that writes log events to NLog.
        /// </summary>
        /// <param name="sinkConfiguration">The logger sink configuration.</param>
        /// <param name="restrictedToMinimumLevel">The minimum log event level required
        /// in order to pass an event to the sink.</param>
        /// <param name="formatProvider">Supplies culture-specific formatting information, or null.</param>
        /// <returns>Configuration object allowing method chaining.</returns>
        public static LoggerConfiguration NLog(
            this LoggerSinkConfiguration sinkConfiguration,
            LogEventLevel restrictedToMinimumLevel = LevelAlias.Minimum,
            IFormatProvider formatProvider = null)
        {
            if (sinkConfiguration == null)
            {
                throw new ArgumentNullException(nameof(sinkConfiguration));
            }

            return sinkConfiguration.Sink(new NLogSink(formatProvider), restrictedToMinimumLevel);
        }
    }
}

