public class ExpressionCache
{
    private readonly Dictionary<string, WeakReference<ParsedExpression>> cache;
    private int cacheHits;
    private int cacheAccessCount;

    public ExpressionCache()
    {
        cache = new Dictionary<string, WeakReference<ParsedExpression>>();
        cacheHits = 0;
        cacheAccessCount = 0;
    }

    public ParsedExpression this[string expression]
    {
        get
        {
            cacheAccessCount++;
            if (cache.TryGetValue(expression, out var weakRef) && weakRef.TryGetTarget(out var parsedExpr))
            {
                cacheHits++;
                return parsedExpr;
            }
            else
            {
                var newParsedExpression = ParseExpression(expression);
                cache[expression] = new WeakReference<ParsedExpression>(newParsedExpression);
                CleanupCache();
                return newParsedExpression;
            }
        }
    }

    private ParsedExpression ParseExpression(string expression)
    {
        // Placeholder for actual parsing logic
        Console.WriteLine($"Parsing new expression: {expression}");
        return new ParsedExpression(expression); // Assuming ParsedExpression is implemented elsewhere
    }

    private void CleanupCache()
    {
        if (cacheAccessCount % 10 == 0) // Cleanup every 10 accesses
        {
            var keysToRemove = cache
                .Where(kv => !kv.Value.TryGetTarget(out _))
                .Select(kv => kv.Key)
                .ToList();

            foreach (var key in keysToRemove)
            {
                cache.Remove(key);
            }
        }
    }

    public void DisplayCacheStatistics()
    {
        Console.WriteLine($"Cache Hits: {cacheHits}");
        Console.WriteLine($"Cache Access Count: {cacheAccessCount}");
        Console.WriteLine($"Current Cache Size: {cache.Count}");
    }
}

