namespace MersennePrime
{
    class Library
    {
        static bool IsPrime(ulong n)
        {
            if (n < 2)
                return false;
            if (n % 2 == 0)
                return n == 2;
            if (n % 3 == 0)
                return n == 3;
            for (ulong p = 5; p * p <= n; p += 4)
            {
                if (n % p == 0)
                    return false;
                p += 2;
                if (n % p == 0)
                    return false;
            }
            return true;
        }
 
        static void Main(string[] args)
        {
            CultureInfo.CurrentCulture = CultureInfo.InvariantCulture;
            Console.WriteLine(" n          M(n)             Prime?");
            Console.WriteLine("-----------------------------------");
            ulong m0 = 1, m1 = 1;
            for (ulong i = 0; i < 42; ++i)
            {
                ulong m =
                    i > 1? (m1 * (2 * i + 1) + m0 * (3 * i - 3)) / (i + 2) : 1;
                Console.WriteLine("{0,2}{1,25}  {2}", i, m, IsPrime(m)? "true" : "false");
                m0 = m1;
                m1 = m;
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

namespace DigitalStore
{
    class Reader
    {
        static void Main(string[] args)
        {
            // Define available games and their prices
            Dictionary<string, double> availableGames = new Dictionary<string, double>();
            availableGames.Add("OutFall 4", 39.99);
            availableGames.Add("CS: OG", 15.99);
            availableGames.Add("Zplinter Zell", 19.99);
            availableGames.Add("Honored 2", 59.99);
            availableGames.Add("RoverWatch", 29.99);
            availableGames.Add("RoverWatch Origins Edition", 39.99);

            // Read the starting balance from input
            Console.Write("Enter your starting balance: ");
            double balance = double.Parse(Console.ReadLine());
            double initialBalance = balance;
            double totalSpent = 0.0;

            // Prepare a list to capture the games user wants to buy
            List<string> gamePurchases = new List<string>();

            // Read user inputs until the termination keyword "Game Time" is entered
            while (true)
            {
                string gameInput = Console.ReadLine();
                if (gameInput == "Game Time")
                {
                    break;
                }
                gamePurchases.Add(gameInput);
            }

            // Process each game purchase request
            foreach (string game in gamePurchases)
            {
                // Check if the game exists in our store
                if (!availableGames.ContainsKey(game))
                {
                    Console.WriteLine("Not Found");
                    continue;
                }

                double gamePrice = availableGames[game];

                // Check if the game is affordable
                if (gamePrice > balance)
                {
                    Console.WriteLine("Too Expensive");
                    continue;
                }

                // Deduct the price and update total spent
                balance -= gamePrice;
                totalSpent += gamePrice;
                Console.WriteLine("Bought {0}", game);

                // If balance hits zero, end the purchasing session
                if (balance == 0)
                {
                    Console.WriteLine("Out of money!");
                    return;
                }
            }

            // Output summary of the transaction
            Console.WriteLine("Total spent: ${0:F2}. Remaining: ${1:F2}", totalSpent, balance);
        }
    }
}

