using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

public class Converter
{
    public Dictionary<string, string> Convert(string inputPath)
    {
        var results = new Dictionary<string, string>();

        if (string.IsNullOrEmpty(inputPath))
        {
            results["WindowsBackslash"] = string.Empty;
            results["WindowsDoubleBackslash"] = string.Empty;
            results["UnixForwardslash"] = string.Empty;
            results["ModifiedUnixForwardslash"] = string.Empty;
            return results;
        }

        var parts = inputPath.Split(new[] { '\\', '/' }, StringSplitOptions.RemoveEmptyEntries);
        if (parts.Length == 0)
        {
            results["WindowsBackslash"] = inputPath;
            results["WindowsDoubleBackslash"] = inputPath;
            results["UnixForwardslash"] = inputPath;
            results["ModifiedUnixForwardslash"] = inputPath;
            return results;
        }

        var first = parts[0];
        bool driver = first.Length == 2 && first[1] == ':';
        bool driver2 = first.Length > 2 && first[1] == ':' && first[2] == '\\';
        bool skipSecond = driver2;

        var list = new List<string>();
        for (int i = 0; i < parts.Length; i++)
        {
            var item = parts[i];
            if (skipSecond && i == 1)
            {
                continue;
            }
            list.Add(item);
        }

        var last = list.Last();
        var s3 = string.Join("/", list);

        results["WindowsBackslash"] = driver2 ? $"{first}\\{string.Join("\\", list.Skip(1))}" : string.Join("\\", list);
        results["WindowsDoubleBackslash"] = driver2 ? $"{first}\\\\{string.Join("\\\\", list.Skip(1))}" : string.Join("\\\\", list);
        results["UnixForwardslash"] = s3;
        results["ModifiedUnixForwardslash"] = driver ? $"{first.Replace(':', '_')}/{s3.Substring(first.Length - 1)}" : s3;

        if (inputPath.EndsWith("/") || inputPath.EndsWith("\\"))
        {
            results["WindowsBackslash"] += "\\";
            results["WindowsDoubleBackslash"] += "\\\\";
            results["UnixForwardslash"] += "/";
            results["ModifiedUnixForwardslash"] += "/";
        }

        return results;
    }
}

