[AttributeUsage(AttributeTargets.Class | AttributeTargets.Method)]
public class OutputAttribute : Attribute { }

[AttributeUsage(AttributeTargets.Class | AttributeTargets.Method)]
public class RequiredAttribute : Attribute { }

public class ReflectionHelper
{
    private string assemblyFullName;

    public ReflectionHelper(string assemblyFullName)
    {
        this.assemblyFullName = assemblyFullName;
    }

    public T GetAttribute<T>(object obj) where T : Attribute
    {
        var type = obj.GetType();
        return type.GetCustomAttributes(typeof(T), true).FirstOrDefault() as T;
    }

    public bool HasAttribute<T>(object obj) where T : Attribute
    {
        var type = obj.GetType();
        return type.GetCustomAttributes(typeof(T), true).Any();
    }

    public bool IsOutput(object obj)
    {
        return HasAttribute<OutputAttribute>(obj);
    }

    public bool IsRequired(object obj)
    {
        return HasAttribute<RequiredAttribute>(obj);
    }

    public Assembly LoadAssembly()
    {
        try
        {
            return Assembly.Load(AssemblyName.GetAssemblyName(assemblyFullName));
        }
        catch (FileNotFoundException ex)
        {
            LogError($"Assembly not found: {ex.Message}");
            throw;
        }
        catch (ReflectionTypeLoadException ex)
        {
            LogError($"Type load exception: {ex.Message}");
            throw;
        }
        catch (Exception ex)
        {
            LogError($"An error occurred while loading assembly: {ex.Message}");
            throw;
        }
    }

    private void LogError(string message)
    {
        Console.WriteLine($"Error: {message}"); // Replace with actual logging implementation
    }

    public List<string> GetAssemblyTypes()
    {
        var assembly = LoadAssembly();
        return assembly.GetTypes().Select(t => t.FullName).ToList();
    }

    public void InspectTypesInAssembly()
    {
        var types = GetAssemblyTypes();
        foreach (var type in types)
        {
            var obj = Activator.CreateInstance(Type.GetType(type));
            Console.WriteLine($"Inspecting {type}");
            if (IsOutput(obj))
            {
                Console.WriteLine($"{type} has Output attribute.");
            }
            if (IsRequired(obj))
            {
                Console.WriteLine($"{type} has Required attribute.");
            }
        }
    }
}

using NUnit.Framework;
using Magnum.TestFramework;
using System;

namespace MassTransit.Util.Tests
{
    public static class UriExtensions
    {
        public static Uri AppendToPath(this Uri uri, string pathSegment)
        {
            var basePath = uri.AbsolutePath.TrimEnd('/');
            var newPath = $"{basePath}/{pathSegment.TrimStart('/')}";
            var builder = new UriBuilder(uri) { Path = newPath };
            return builder.Uri;
        }
    }

    [TestFixture]
    public class Advanced_Uri_Specs
    {
        private Uri _baseUri;
        private Uri _newUri;

        [Scenario]
        public void AppendPath_ToComplexUri_PreservesComponents()
        {
            "Given URI with credentials, port, and query".Execute(There_s_an_advanced_uri);
            "When appending path segment".Execute(() => _newUri = _baseUri.AppendToPath("segment"));
            "Then maintains all components with new path".Execute(Can_append_to_path);
        }

        private void There_s_an_advanced_uri()
        {
            _baseUri = new Uri("http://user:pass@example.com:8080/base?query=123");
        }

        private void Can_append_to_path()
        {
            Assert.That(_newUri.ToString(), Is.EqualTo("http://user:pass@example.com:8080/base/segment?query=123"));
        }
    }

    [TestFixture]
    public class Simple_Uri_Specs
    {
        private Uri _baseUri;
        private Uri _newUri;

        [Scenario]
        public void AppendPath_ToBasicUri_HandlesTrailingSlash()
        {
            "Given URI with trailing slash".Execute(There_s_a_simple_uri);
            "When appending path".Execute(() => _newUri = _baseUri.AppendToPath("endpoint"));
            "Then constructs clean path".Execute(The_uri_extensions_are_capable_of_parsing_it);
        }

        [Scenario]
        public void AppendPath_WithExistingQuery_PreservesParameters()
        {
            "Given URI with query string".Execute(() => _baseUri = new Uri("https://api.com?page=2"));
            "When appending path".Execute(() => _newUri = _baseUri.AppendToPath("next"));
            "Then retains original query".Execute(() => Assert.That(_newUri.Query, Is.EqualTo("?page=2")));
        }

        private void There_s_a_simple_uri()
        {
            _baseUri = new Uri("http://localhost/base/");
        }

        private void The_uri_extensions_are_capable_of_parsing_it()
        {
            Assert.That(_newUri.AbsolutePath, Is.EqualTo("/base/endpoint"));
        }
    }
}

