public class NuSpec : IEquatable<NuSpec>
{
    [XmlElement("metadata")]
    public Metadata Metadata { get; set; }

    public static NuSpec LoadFromFile(string path)
    {
        using var stream = File.OpenRead(path);
        return LoadFromStream(stream);
    }

    public static NuSpec LoadFromStream(Stream stream)
    {
        var serializer = new XmlSerializer(typeof(NuSpec));
        return (NuSpec)serializer.Deserialize(stream);
    }

    public bool Equals(NuSpec other) => other != null && Metadata == other.Metadata;
    public override bool Equals(object obj) => Equals(obj as NuSpec);

    public override int GetHashCode() => Metadata?.GetHashCode() ?? 0;

    public static bool operator ==(NuSpec left, NuSpec right) => Equals(left, right);
    public static bool operator !=(NuSpec left, NuSpec right) => !Equals(left, right);

    public class Metadata : IEquatable<Metadata>
    {
        [XmlElement("id")]
        public string Id { get; set; }

        [XmlElement("version")]
        public string Version { get; set; }

        [XmlElement("authors")]
        public string Authors { get; set; }

        [XmlElement("description")]
        public string Description { get; set; }

        public bool Equals(Metadata other) => other != null &&
            Id == other.Id &&
            Version == other.Version &&
            Authors == other.Authors &&
            Description == other.Description;

        public override bool Equals(object obj) => Equals(obj as Metadata);

        public override int GetHashCode() => HashCode.Combine(
            Id, Version, Authors, Description);

        public static bool operator ==(Metadata left, Metadata right) => Equals(left, right);
        public static bool operator !=(Metadata left, Metadata right) => !Equals(left, right);
    }
}

