namespace Cache
{
    class Helper
    {
        static void process(int lineNum, string buffer)
        {
            string[] days = new string[7];
            int i = 0, d = 0, j = 0;
 
            while (buffer[i]!= 0)
            {
                if (buffer[i] =='')
                {
                    days[d] = buffer.Substring(j, i - j);
                    ++d;
                    j = i + 1;
                }
                else if (buffer[i] == '\n' || buffer[i] == '\r')
                {
                    days[d] = buffer.Substring(j, i - j);
                    ++d;
                    break;
                }
                else
                {
                    days[d] = buffer.Substring(j, i - j);
                    ++j;
                }
 
                if (d >= 7)
                {
                    Console.WriteLine("There aren't 7 days in line {0}", lineNum);
                    return;
                }
                ++i;
            }
            if (buffer[i] == '\0')
            {
                days[d] = buffer.Substring(j, i - j);
                ++d;
            }
 
            if (d < 7)
            {
                Console.WriteLine("There aren't 7 days in line {0}", lineNum);
                return;
            }
            else
            {
                int len = 0;
 
                for (len = 1; len < 64; ++len)
                {
                    int d1;
                    for (d1 = 0; d1 < 7; ++d1)
                    {
                        int d2;
                        for (d2 = d1 + 1; d2 < 7; ++d2)
                        {
                            int unique = 0;
                            for (i = 0; i < len; ++i)
                            {
                                if (days[d1][i]!= days[d2][i])
                                {
                                    unique = 1;
                                    break;
                                }
                            }
                            if (!unique)
                            {
                                goto next_length;
                            }
                        }
                    }
 
                    // uniqueness found for this length
                    Console.Write("{0} ", len);
                    for (i = 0; i < 7; ++i)
                    {
                        Console.Write(" {0}", days[i]);
