using MassTransit;
using System;
using System.Threading.Tasks;

public class RequeueCommand
{
    private readonly string _uriString;
    private readonly int _count;

    public RequeueCommand(string uriString, int count)
    {
        _uriString = uriString;
        _count = count;
    }

    public async Task<(bool, string)> Execute()
    {
        try
        {
            var uri = new Uri(_uriString);
            var transport = Bus.Factory.CreateDuplexTransport(uri);
            int requeuedCount = 0;
            string messageInfo = "";

            for (int i = 0; i < _count; i++)
            {
                var receiveContext = await transport.Receive(TimeSpan.Zero);

                if (receiveContext != null)
                {
                    var message = receiveContext.GetMessageBody<object>();
                    if (message != null)
                    {
                        await transport.Send(message, context => { });
                        requeuedCount++;
                        messageInfo += $"Requeued message: {message}\n";
                    }
                    else
                    {
                        messageInfo += "Message body was null.\n";
                    }
                    await receiveContext.Complete();
                }
                else
                {
                    messageInfo += "No message received.\n";
                }
            }

            return (true, $"Successfully requeued {requeuedCount} messages.\n{messageInfo}");
        }
        catch (Exception ex)
        {
            return (false, $"Error: {ex.Message}");
        }
    }
}

