namespace Aerospike.Client
{
    public class Policy
    {
        public int maxRetries { get; set; }
        public int socketTimeout { get; set; }
        public int totalTimeout { get; set; }

        public Policy()
        {
            maxRetries = 2;
            socketTimeout = 30000;
            totalTimeout = 0;
        }
    }

    public class QueryPolicy : Policy
    {
        public int maxConcurrentNodes { get; set; }
        public int recordQueueSize { get; set; }

        public QueryPolicy() : base()
        {
            maxConcurrentNodes = 0; // 0 means no limit
            recordQueueSize = 5000;
            maxRetries = 0; // Disable retries for queries
        }

        public QueryPolicy(QueryPolicy other) : base(other)
        {
            maxConcurrentNodes = other.maxConcurrentNodes;
            recordQueueSize = other.recordQueueSize;
        }

        public void SetMaxConcurrentNodes(int maxNodes)
        {
            if (maxNodes < 0)
            {
                throw new ArgumentException("maxConcurrentNodes must be non-negative");
            }
            maxConcurrentNodes = maxNodes;
        }

        public void SetRecordQueueSize(int queueSize)
        {
            if (queueSize <= 0)
            {
                throw new ArgumentException("recordQueueSize must be positive");
            }
            recordQueueSize = queueSize;
        }

        public void EnableRetries(int retries)
        {
            if (retries < 0)
            {
                throw new ArgumentException("maxRetries must be non-negative");
            }
            maxRetries = retries;
        }

        public void DisableRetries()
        {
            maxRetries = 0;
        }

        public override string ToString()
        {
            return $"QueryPolicy {{ maxRetries={maxRetries}, socketTimeout={socketTimeout}, totalTimeout={totalTimeout}, maxConcurrentNodes={maxConcurrentNodes}, recordQueueSize={recordQueueSize} }}";
        }
    }
}

using System;
