using Cairo;

public class CairoPdfWriter
{
    public byte[] GetFileBytes(Report report)
    {
        string filename = Path.GetTempFileName() + ".pdf";
        FileStream fs = null;
        Document document = null;
        try
        {
            document = new Document(report);
            fs = new FileStream(filename, FileMode.Create);

            // Create a PDF surface
            PdfSurface surface = new PdfSurface(fs, document.PageWidth, document.PageHeight);

            // Create a Cairo context
            using (Context context = new Context(surface))
            {
                // Render each page of the report
                for (int pageNumber = 0; pageNumber < document.PageCount; pageNumber++)
                {
                    RenderCairo render = new RenderCairo(document, context, pageNumber);
                    render.Render();
                    context.ShowPage();
                }
            }

            // Flush and close the surface
            surface.Flush();
            surface.Finish();

            // Read the PDF file into a byte array
            byte[] fileBytes = File.ReadAllBytes(filename);

            return fileBytes;
        }
        catch (Exception ex)
        {
            Console.WriteLine("An error occurred: " + ex.Message);
            return null;
        }
        finally
        {
            // Ensure the file is deleted
            if (fs != null)
            {
                fs.Close();
                fs.Dispose();
            }
            if (File.Exists(filename))
            {
                File.Delete(filename);
            }
        }
    }
}

