using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

public class ManifestFile
{
    public string Version { get; private set; }
    public List<PatchFile> PatchFiles { get; private set; }

    public ManifestFile(string version)
    {
        Version = version;
        PatchFiles = new List<PatchFile>();
    }

    public ManifestFile(Stream manifestStream)
    {
        using (BinaryReader reader = new BinaryReader(manifestStream, Encoding.UTF8))
        {
            Version = reader.ReadString();
            int patchCount = reader.ReadInt32();
            PatchFiles = new List<PatchFile>();

            for (int i = 0; i < patchCount; i++)
            {
                bool hasUrl = reader.ReadBoolean();
                long address = reader.ReadInt64();
                string hash = reader.ReadString();
                string url = hasUrl ? reader.ReadString() : null;

                PatchFiles.Add(new PatchFile(address, hash, url));
            }
        }
    }

    public void AddPatchFile(PatchFile patchFile)
    {
        PatchFiles.Add(patchFile);
    }

    public void WriteTo(Stream manifestStream)
    {
        using (BinaryWriter writer = new BinaryWriter(manifestStream, Encoding.UTF8))
        {
            writer.Write(Version);
            writer.Write(PatchFiles.Count);

            foreach (PatchFile patchFile in PatchFiles)
            {
                writer.Write(patchFile.DownloadUrl != null);
                writer.Write(patchFile.Address);
                writer.Write(patchFile.Hash);

                if (patchFile.DownloadUrl != null)
                {
                    writer.Write(patchFile.DownloadUrl);
                }
            }
        }
    }

    public byte[] ToByteArray()
    {
        using (MemoryStream stream = new MemoryStream())
        {
            WriteTo(stream);
            return stream.ToArray();
        }
    }
}

public class PatchFile
{
    public long Address { get; private set; }
    public string Hash { get; private set; }
    public string DownloadUrl { get; private set; }

    public PatchFile(long address, string hash, string downloadUrl = null)
    {
        Address = address;
        Hash = hash;
        DownloadUrl = downloadUrl;
    }
}

