namespace GoToCSharp
{
    class Shape
    {
        static void Main(string[] args)
        {
            var t1 = new BinaryTree();
            var t2 = new BTree();
            var a1 = Average(t1);
            var a2 = Average(t2);
            Console.WriteLine("binary tree average: {0}", a1);
            Console.WriteLine("b-tree average: {0}", a2);
        }
 
        static double Average(IIntCollection c)
        {
            var sum = 0;
            var count = 0;
            c.MapElements(n =>
            {
                sum += n;
                count++;
            });
            return (double)sum / count;
        }
    }
 
