public class RewardBasedVideoAdClient : IRewardBasedVideoAdClient
{
    private RewardBasedVideoAd rewardBasedVideoAd;

    public event EventHandler<EventArgs> OnAdLoaded;
    public event EventHandler<AdFailedToLoadEventArgs> OnAdFailedToLoad;
    public event EventHandler<EventArgs> OnAdOpening;
    public event EventHandler<EventArgs> OnAdStarted;
    public event EventHandler<Reward> OnAdRewarded;
    public event EventHandler<EventArgs> OnAdClosed;
    public event EventHandler<EventArgs> OnAdLeavingApplication;

    public void CreateRewardBasedVideoAd()
    {
        rewardBasedVideoAd = RewardBasedVideoAd.Instance;

        // Subscribe to ad events
        rewardBasedVideoAd.OnAdLoaded += (sender, args) => OnAdLoaded?.Invoke(this, args);
        rewardBasedVideoAd.OnAdFailedToLoad += (sender, args) => OnAdFailedToLoad?.Invoke(this, args);
        rewardBasedVideoAd.OnAdOpening += (sender, args) => OnAdOpening?.Invoke(this, args);
        rewardBasedVideoAd.OnAdStarted += (sender, args) => OnAdStarted?.Invoke(this, args);
        rewardBasedVideoAd.OnAdRewarded += (sender, reward) => OnAdRewarded?.Invoke(this, reward);
        rewardBasedVideoAd.OnAdClosed += (sender, args) => OnAdClosed?.Invoke(this, args);
        rewardBasedVideoAd.OnAdLeavingApplication += (sender, args) => OnAdLeavingApplication?.Invoke(this, args);
    }

    public void LoadAd(AdRequest request, string adUnitId)
    {
        rewardBasedVideoAd.LoadAd(request, adUnitId);
    }

    public bool IsLoaded()
    {
        return rewardBasedVideoAd.IsLoaded();
    }

    public void ShowRewardBasedVideoAd()
    {
        if (IsLoaded())
        {
            rewardBasedVideoAd.Show();
        }
    }
}

