using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace Timer
{
    class Graph
    {
        static double log2(double number)
        {
            return Math.Log(number) / Math.Log(2);
        }
 
        static void Main(string[] args)
        {
            string teststring = args[0];
            Dictionary<char, int> frequencies = new Dictionary<char, int>();
            foreach (char c in teststring)
            {
                if (frequencies.ContainsKey(c))
                {
                    frequencies[c]++;
                }
                else
                {
                    frequencies.Add(c, 1);
                }
            }
            int numlen = teststring.Length;
            double infocontent = 0;
            foreach (KeyValuePair<char, int> p in frequencies)
            {
                double freq = (double)p.Value / numlen;
                infocontent -= freq * log2(freq);
            }
 
            Console.WriteLine("The information content of " + teststring + " is " + infocontent);
        }
    }
}

