    public class ContentElement : ContentControl, ISilverlightContainerElement
    {
        private FrameworkElement _rootElement;
        private readonly object _lockObject = new object();

        public ContentElement()
        {
            ConfigureDefaultProperties();
        }

        private void ConfigureDefaultProperties()
        {
            Margin = new Thickness(5);
            TabStop = true;
            HorizontalContentAlignment = HorizontalAlignment.Stretch;
            VerticalContentAlignment = VerticalAlignment.Stretch;
        }

        public FrameworkElement CreateFrameworkElement()
        {
            return _rootElement;
        }

        public void AddChild(FrameworkElement element)
        {
            if (element == null)
                throw new ArgumentNullException(nameof(element));

            lock (_lockObject)
            {
                if (_rootElement != null)
                {
                    RemoveChild();
                }

                if (IsValidChild(element))
                {
                    _rootElement = element;
                    Content = _rootElement;
                }
                else
                {
                    throw new InvalidOperationException("Invalid child element type.");
                }
            }
        }

        public void RemoveChild()
        {
            lock (_lockObject)
            {
                if (_rootElement != null)
                {
                    Content = null;
                    _rootElement = null;
                }
            }
        }

        private bool IsValidChild(FrameworkElement element)
        {
            return element is UIElement &&
                   !(element is ContentControl) &&
                   !(element is Panel);
        }

