public class Achievement
{
    public List<AchievementHistory> History { get; private set; } = new List<AchievementHistory>();

    public void AddHistory(DateTime date, int value)
    {
        History.Add(new AchievementHistory(date, value));
    }

    public int GetValueChangeFrom(DateTime date)
    {
        int valueChange = 0;
        AchievementHistory previousRecord = null;

        foreach (var record in History)
        {
            if (record.Date <= date)
            {
                if (previousRecord != null)
                {
                    valueChange += record.Value - previousRecord.Value;
                }
                previousRecord = record;
            }
        }

        return valueChange;
    }
}

