namespace Avalonia.Cairo
{
    public class ImageBrushImpl : IBrushImpl
    {
        private readonly ITileBrush _tileBrush;
        private readonly IBitmapImpl _bitmap;
        private readonly Size _targetSize;
        private SurfacePattern _platformBrush;

        public ImageBrushImpl(ITileBrush tileBrush, IBitmapImpl bitmap, Size targetSize)
        {
            _tileBrush = tileBrush;
            _bitmap = bitmap;
            _targetSize = targetSize;
            _platformBrush = CreatePattern();
        }

        private SurfacePattern CreatePattern()
        {
            var calculator = new TileBrushCalculator(_tileBrush, _bitmap, _targetSize);
            var intermediateSize = calculator.IntermediateSize;
            var intermediateSurface = new ImageSurface(Format.Argb32, (int)intermediateSize.Width, (int)intermediateSize.Height);
            using (var context = new Context(intermediateSurface))
            {
                context.Matrix = calculator.TransformMatrix;
                context.PushClip(calculator.ClipGeometry);
                DrawImage(context, _bitmap, intermediateSize);
                context.PopClip();
            }

            var pattern = new SurfacePattern(intermediateSurface);
            pattern.Extend = Extend.Reflect; // Current limitation
            pattern.Matrix = calculator.PatternMatrix;
            return pattern;
        }

        private void DrawImage(Context context, IBitmapImpl bitmap, Size size)
        {
            var imageSurface = bitmap.ToCairoSurface();
            context.SetSourceSurface(imageSurface, 0, 0);
            context.Rectangle(0, 0, size.Width, size.Height);
            context.Fill();
            imageSurface.Dispose();
        }

        public void Dispose()
        {
            _platformBrush.Dispose();
        }

        public object PlatformBrush => _platformBrush;
    }

    public struct TileBrushCalculator
    {
        private readonly ITileBrush _tileBrush;
        private readonly IBitmapImpl _bitmap;
        private readonly Size _targetSize;

        public TileBrushCalculator(ITileBrush tileBrush, IBitmapImpl bitmap, Size targetSize)
        {
            _tileBrush = tileBrush;
            _bitmap = bitmap;
            _targetSize = targetSize;
        }

        public Size IntermediateSize => _bitmap.Size;

        public Matrix TransformMatrix => CalculateTransformMatrix();

        public Matrix PatternMatrix => CalculatePatternMatrix();

