namespace AchievementValidation
{
    // Class to hold historical records of achievement values.
    public class AchievementHistory
    {
        public DateTime Date { get; set; }
        public double Value { get; set; }

        public AchievementHistory(DateTime date, double value)
        {
            Date = date;
            Value = value;
        }
    }

    // Achievement class with a list of historical value records.
    public class Achievement
    {
        public double CurrentValue { get; private set; }
        public List<AchievementHistory> History { get; private set; }

        public Achievement(double currentValue)
        {
            CurrentValue = currentValue;
            History = new List<AchievementHistory>();
        }

        // Adds a historical record.
        public void AddHistory(DateTime date, double value)
        {
            History.Add(new AchievementHistory(date, value));
        }

        // Computes the change in value from the historical record at or before the given date.
        public double GetValueChangeFrom(DateTime queryDate)
        {
            if (History.Count == 0)
                return 0;

            // Assume history records are added in chronological order.
            DateTime latestRecordDate = History[History.Count - 1].Date;
            // If the query is for a future date relative to the latest record, return zero.
            if (queryDate > latestRecordDate)
                return 0;

            AchievementHistory targetRecord = null;
            // Find the most recent record at or before the queryDate.
            for (int i = History.Count - 1; i >= 0; i--)
            {
                if (History[i].Date <= queryDate)
                {
                    targetRecord = History[i];
                    break;
                }
            }
            if (targetRecord == null)
                return 0;
            return CurrentValue - targetRecord.Value;
        }
    }

