public class RasPiCameraNodeConfig
{
    public string Uuid { get; set; }
    public string FrontendServer { get; set; }
    public string ApiServer { get; set; }
    public int ApiPort { get; set; }
    public bool UseSecureConnection { get; set; }
    public string NodeToken { get; set; }
    public List<string> ActiveConfigurations { get; set; }

    public RasPiCameraNodeConfig()
    {
        Uuid = Guid.NewGuid().ToString();
        FrontendServer = "localhost";
        ApiServer = "127.0.0.1";
        ApiPort = 8080;
        UseSecureConnection = false;
        NodeToken = GenerateNodeToken();
        ActiveConfigurations = new List<string>();
    }

    private string GenerateNodeToken()
    {
        return Convert.ToBase64String(Guid.NewGuid().ToByteArray())
            .Replace("/", "_")
            .Replace("+", "-")
            .Substring(0, 22);
    }
}

public class ConfigurationManager
{
    private const string ConfigFilePath = "./node_config.json";
    private YConfig<RasPiCameraNodeConfig> configHandler;

    public RasPiCameraNodeConfig Configuration { get; private set; }

    public void Init()
    {
        try
        {
            Configuration = Retrieve();
            if (Configuration == null)
            {
                Configuration = GenerateDefaultConfiguration();
                Save();
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Configuration initialization error: {ex.Message}");
            Configuration = GenerateDefaultConfiguration();
            Save();
        }
    }

    private RasPiCameraNodeConfig Retrieve()
    {
        try
        {
            return configHandler.Load(ConfigFilePath);
        }
        catch
        {
            return null;
        }
    }

    private RasPiCameraNodeConfig GenerateDefaultConfiguration()
    {
        var defaultConfig = new RasPiCameraNodeConfig();
        AddActiveConf(defaultConfig, "default");
        return defaultConfig;
    }

    private void AddActiveConf(RasPiCameraNodeConfig config, string configName)
    {
        if (!config.ActiveConfigurations.Contains(configName))
        {
            config.ActiveConfigurations.Add(configName);
        }
    }

    public void Save()
    {
        try
        {
            configHandler.Save(Configuration, ConfigFilePath);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Configuration save failed: {ex.Message}");
        }
    }

