public partial class FinancialServices : System.Web.UI.Page
{
    private string strUserName;

    protected void Page_Load(object sender, EventArgs e)
    {
        try
        {
            strUserName = Session["Username"] as string;

            if (string.IsNullOrEmpty(strUserName))
            {
                LogError("Unauthorized access attempt.");
                Response.Redirect("~/Login.aspx");
            }

            if (!IsPostBack)
            {
                LoadExistingCards();
            }
        }
        catch (Exception ex)
        {
            LogError(ex.Message);
            Response.Redirect("~/Error.aspx");
        }
    }

    private void LoadExistingCards()
    {
        try
        {
            DataTable dtCreditCards = new DataTable();
            DataTable dtDebitCards = new DataTable();

            // Assuming BL_VirtualCard is a business layer for card information
            BL_VirtualCard virtualCardBL = new BL_VirtualCard();
            dtCreditCards = virtualCardBL.GetCreditCardsByUser(strUserName);
            dtDebitCards = virtualCardBL.GetDebitCardsByUser(strUserName);

            if (dtCreditCards.Rows.Count > 0)
            {
                grdCreditCards.DataSource = dtCreditCards;
                grdCreditCards.DataBind();
            }
            else
            {
                lblCreditCardMessage.Text = "No credit cards found.";
            }

            if (dtDebitCards.Rows.Count > 0)
            {
                grdDebitCards.DataSource = dtDebitCards;
                grdDebitCards.DataBind();
            }
            else
            {
                lblDebitCardMessage.Text = "No debit cards found.";
            }
        }
        catch (SqlException sqlEx)
        {
            LogError(sqlEx.Message);
            lblErrorMessage.Text = "Database error occurred. Please try again later.";
        }
        catch (Exception ex)
        {
            LogError(ex.Message);
            lblErrorMessage.Text = "An unexpected error occurred. Please try again.";
        }
    }

    private void LogError(string message)
    {
        // Custom logging utility
        ErrorLogger.Log(message);
    }
}

