namespace RestApiPagination
{
    /// <summary>
    /// A generic container representing a single page of results from a paginated API response.
    /// </summary>
    /// <typeparam name="T">The type of items held in the page.</typeparam>
    public class PageContainer<T> : IEnumerable<T>
    {
        // The collection of items deserialized from the JSON "value" property.
        [JsonProperty("value")]
        private List<T> _items;

        // The pagination link deserialized from the JSON "nextLink" property.
        [JsonProperty("nextLink")]
        private string _nextPageLink;

        /// <summary>
        /// Initializes a new instance of the <see cref="PageContainer{T}"/> class.
        /// </summary>
        public PageContainer()
        {
            _items = new List<T>();
        }

        /// <summary>
        /// Gets a read-only list of the items present in the page.
        /// </summary>
        public IReadOnlyList<T> Items
        {
            get { return _items.AsReadOnly(); }
        }

        /// <summary>
        /// Gets the link to the next page of results.
        /// </summary>
        public string NextPageLink
        {
            get { return _nextPageLink; }
            private set { _nextPageLink = value; }
        }

        /// <summary>
        /// Adds a collection of items to the current page and sets the next page link.
        /// This method may be utilized during JSON deserialization.
        /// </summary>
        /// <param name="items">The collection of items to add.</param>
        /// <param name="nextPageLink">The URL for the next page of results.</param>
        public void AddRange(IEnumerable<T> items, string nextPageLink = null)
        {
            if (items != null)
            {
                _items.AddRange(items);
            }
            _nextPageLink = nextPageLink;
        }

        /// <summary>
        /// Returns a strongly typed enumerator for iterating through the items.
        /// </summary>
        /// <returns>An enumerator over the items.</returns>
        public IEnumerator<T> GetEnumerator()
        {
            // If no items are present, return an empty iterator.
            if (_items != null)
            {
                return _items.GetEnumerator();
            }
            return Enumerable.Empty<T>().GetEnumerator();
        }

