namespace CryptoFramework
{
    // Base interface for cryptographic hashing operations.
    public interface IHash
    {
        // Computes the hash for a given byte array.
        byte[] ComputeHash(byte[] data);
    }

    // Interface for 32-bit hash algorithms.
    public interface IHash32 : IHash
    {
        // Computes a 32-bit hash value for the provided data.
        uint ComputeHash32(byte[] data);
    }

    // Interface for 64-bit hash algorithms.
    public interface IHash64 : IHash
    {
        // Computes a 64-bit hash value for the provided data.
        ulong ComputeHash64(byte[] data);
    }

    // Interface for 128-bit hash algorithms.
    public interface IHash128 : IHash
    {
        // Computes a 128-bit hash value; for example, returns a Guid.
        Guid ComputeHash128(byte[] data);
    }

    // Interface that defines a keyed object.
    public interface IWithKey
    {
        // Gets or sets the key used in keyed hashing algorithms.
        byte[] Key { get; set; }
    }

    // Hash algorithms accepting a key.
    public interface IHashWithKey : IHash, IWithKey
    {
        // Computes a hash based on both data and the key.
        byte[] ComputeHashWithKey(byte[] data);
    }

    // Interface for fast 32-bit hash computations.
    public interface IFastHash32
    {
        // Fast processing of a single byte.
        uint FastHash(byte data);

        // Fast processing of an entire byte array.
        uint FastHash(byte[] data);

        // Fast processing of a single char.
        uint FastHash(char data);

        // Fast processing of an entire char array.
        uint FastHash(char[] data);

        // Fast processing of a string.
        uint FastHash(string data);
    }

    // Interface for block-based hash computations.
    public interface IBlockHash : IHash
    {
        // Initializes the hash algorithm for block processing.
        void Initialize();

        // Processes a block of data.
        void TransformBlock(byte[] data, int offset, int count);

        // Finalizes the block hash computation.
        byte[] TransformFinal();
    }

    // Interface for non-block hash computations.
    public interface INonBlockHash : IHash
    {
        // Directly computes hash without block initialization.
        byte[] ComputeNonBlockHash(byte[] data);
    }

    // Interface for checksum operations.
    public interface IChecksum
    {
        // Computes the checksum value.
        uint ComputeChecksum(byte[] data);

