using Db4oUnit;

namespace DatabasePersistenceTest
{
    public class CascadingUpdateDepthTest : ITestCase
    {
        private const int RootId = 100;
        private const int ChildId = 200;

        private class Item
        {
            private int _id;
            private string _name;
            private Item _childItem;

            public Item(int id, string name, Item childItem = null)
            {
                _id = id;
                _name = name;
                _childItem = childItem;
            }

            public int ID { get { return _id; } set { _id = value; } }
            public string Name { get { return _name; } set { _name = value; } }
            public Item ChildItem { get { return _childItem; } set { _childItem = value; } }
        }

        private IObjectContainer _database;

        public void Configure(IConfiguration config)
        {
            config.ObjectClass(typeof(Item)).CascadeOnDelete(true);
            config.ObjectClass(typeof(Item)).CascadeOnUpdate(true);
        }

        public void SetUp()
        {
            IConfiguration config = Db4oFactory.NewConfiguration();
            Configure(config);
            _database = Db4oFactory.OpenFile(config, "testDatabase.db4o");
        }

        public void TearDown()
        {
            if (_database != null)
            {
                _database.Close();
            }
        }

        public void TestUpdateDepth()
        {
            // Create nested item structure
            Item childItem = new Item(ChildId, "Child Item");
            Item rootItem = new Item(RootId, "Root Item", childItem);

            // Store initial items
            _database.Store(rootItem);
            _database.Commit();

            // Retrieve and verify initial state
            Item retrievedRoot = QueryItemByID(RootId);
            AssertNotNull(retrievedRoot);
            AssertEquals(RootId, retrievedRoot.ID);
            AssertEquals("Root Item", retrievedRoot.Name);
            AssertNotNull(retrievedRoot.ChildItem);
            AssertEquals(ChildId, retrievedRoot.ChildItem.ID);

            // Update root item's identifier
            retrievedRoot.ID = RootId + 1;
            _database.Store(retrievedRoot);
            _database.Commit();

            // Verify updated object
            Item updatedRoot = QueryItemByID(RootId + 1);
            AssertNotNull(updatedRoot);
            AssertEquals(RootId + 1, updatedRoot.ID);

