namespace Fonet.Fo
{
    public class Title : ToBeImplementedElement
    {
        private class Maker : IMarker
        {
            public FObj Make(FObj parent, PropertyList properties)
            {
                return new Title(parent, properties);
            }
        }

        private readonly AccessibilityProps accessibilityProps;
        private readonly AuralProps auralProps;
        private readonly BorderAndPadding borderProps;
        private readonly FontState fontState;

        public Title(FObj parent, PropertyList properties) : base(parent, properties)
        {
            accessibilityProps = new AccessibilityProps();
            auralProps = new AuralProps();
            borderProps = new BorderAndPadding();
            fontState = new FontState();

            accessibilityProps.GetAccessibilityProperties(properties);
            auralProps.GetAuralProperties(properties);
            borderProps.GetBorderAndPadding(properties);
            fontState.GetFontProperties(properties);
        }

        public static IMarker GetMaker()
        {
            return new Maker();
        }

        public override LayoutStatus Layout(Area area)
        {
            var props = new PropertyManager(properties);

            // Process baseline-shift (supports length or enum)
            var baselineShift = props.GetProperty("baseline-shift");
            if (baselineShift != null)
            {
                if (baselineShift is Length)
                    fontState.BaselineShift = (Length)baselineShift;
                else if (baselineShift is BaselineShiftType)
                    fontState.BaselineShiftType = (BaselineShiftType)baselineShift;
            }

            // Process color properties
            var color = props.GetProperty("color") as ColorType;
            if (color != null)
                fontState.Color = color;

            // Process line-height (supports number, length, or enum)
            var lineHeight = props.GetProperty("line-height");
            if (lineHeight != null)
                fontState.SetLineHeight(lineHeight);

            // Process visibility and z-index
            var visibility = props.GetEnumProperty("visibility");
            var zIndex = props.GetIntProperty("z-index");

            // Delegate remaining layout to base implementation
            return base.Layout(area);
        }

        protected override void AddChild(FObj child)
        {
            if (child is ToBeImplementedElement)
                children.Add(child);
        }

