namespace NetFusion.Bootstrap.Plugins
{
    public class ModuleHealthCheck
    {
        private readonly List<HealthAspectCheck> _aspectsChecks = new List<HealthAspectCheck>();

        public string PluginModuleType { get; }

        public IReadOnlyCollection<HealthAspectCheck> AspectChecks => _aspectsChecks.AsReadOnly();

        public HealthCheckStatusType ModuleHealth
        {
            get
            {
                if (!_aspectsChecks.Any())
                    return HealthCheckStatusType.Healthy;

                return _aspectsChecks.Max(check => check.Status);
            }
        }

        public ModuleHealthCheck(string pluginModuleType)
        {
            PluginModuleType = pluginModuleType ?? throw new ArgumentNullException(nameof(pluginModuleType));
        }

        public void RecordAspect(HealthAspectCheck aspectCheck)
        {
            if (aspectCheck == null)
                throw new ArgumentNullException(nameof(aspectCheck));

            _aspectsChecks.Add(aspectCheck);
        }
    }

    public struct HealthAspectCheck
    {
        public string AspectName { get; }
        public HealthCheckStatusType Status { get; }

        public HealthAspectCheck(string aspectName, HealthCheckStatusType status)
        {
            AspectName = aspectName ?? throw new ArgumentNullException(nameof(aspectName));
            Status = status;
        }
    }

    public enum HealthCheckStatusType
    {
        Healthy,
        Warning,
        Critical
    }
}

