    public abstract class AObjectJsonWriter<T>
    {
        public abstract Task WriteObjectAsync(JsonTextWriter jsonWriter, T obj, CancellationToken cancellationToken = default);
    }

    public class SyncCollectionRemovePostResponseObjectJsonWriter : AObjectJsonWriter<ITraktSyncCollectionRemovePostResponse>
    {
        private readonly SyncPostResponseGroupObjectJsonWriter _deletedWriter = new SyncPostResponseGroupObjectJsonWriter();
        private readonly SyncCollectionPostResponseNotFoundGroupObjectJsonWriter _notFoundWriter = new SyncCollectionPostResponseNotFoundGroupObjectJsonWriter();

        public override async Task WriteObjectAsync(JsonTextWriter jsonWriter, ITraktSyncCollectionRemovePostResponse response, CancellationToken cancellationToken = default)
        {
            if (jsonWriter == null)
                throw new ArgumentNullException(nameof(jsonWriter));

            await jsonWriter.WriteStartObjectAsync(cancellationToken).ConfigureAwait(false);
            if (response.Deleted != null)
            {
                await jsonWriter.WritePropertyNameAsync(JsonProperties.Deleted, cancellationToken).ConfigureAwait(false);
                await _deletedWriter.WriteObjectAsync(jsonWriter, response.Deleted, cancellationToken).ConfigureAwait(false);
            }
            if (response.NotFound != null)
            {
                await jsonWriter.WritePropertyNameAsync(JsonProperties.NotFound, cancellationToken).ConfigureAwait(false);
                await _notFoundWriter.WriteObjectAsync(jsonWriter, response.NotFound, cancellationToken).ConfigureAwait(false);
            }
            await jsonWriter.WriteEndObjectAsync(cancellationToken).ConfigureAwait(false);
        }
    }

