namespace Converter
{
    class Service
    {
        static void Main(string[] args)
        {
            double rad, deg;
            rad = Math.PI / 4;
            deg = 45.0;
            Console.WriteLine("Sine: {0} {1}", Math.Sin(rad), Math.Sin(deg * Math.PI / 180));
            Console.WriteLine("Cosine: {0} {1}", Math.Cos(rad), Math.Cos(deg * Math.PI / 180));
            Console.WriteLine("Tangent: {0} {1}", Math.Tan(rad), Math.Tan(deg * Math.PI / 180));
            double arcsine = Math.Asin(Math.Sin(rad));
            Console.WriteLine("Arcsine: {0} {1}", arcsine, arcsine * 180 / Math.PI);
            double arccosine = Math.Acos(Math.Cos(rad));
            Console.WriteLine("Arccosine: {0} {1}", arccosine, arccosine * 180 / Math.PI);
            double arctangent = Math.Atan(Math.Tan(rad));
            Console.WriteLine("Arctangent: {0} {1}", arctangent, arctangent * 180 / Math.PI);
            Console.ReadKey();
        }
    }
}

public IEnumerable<IEnumerable<T>> GetPowerSet<T>(List<T> list)
{
    return from m in Enumerable.Range(0, 1 << list.Count)
                  select
                      from i in Enumerable.Range(0, list.Count)
                      where (m & (1 << i)) != 0
                      select list[i];
}
 
public void PowerSetofColors()
{
    var colors = new List<KnownColor> { KnownColor.Red, KnownColor.Green,
        KnownColor.Blue, KnownColor.Yellow };
 
    var result = GetPowerSet(colors);
 
    Console.Write( string.Join( Environment.NewLine,
        result.Select(subset =>
            string.Join(",", subset.Select(clr => clr.ToString()).ToArray())).ToArray()));
}

