        Assert.AreEqual("John", badPerson.first_name);
        Assert.AreEqual("Doe", badPerson.last_name);
    }

    [Test]
    public void TestExplicitMapping()
    {
        var person = new Person { FirstName = "Jane", LastName = "Smith" };
        Assert.AreEqual("Jane", person.FirstName);
        Assert.AreEqual("Smith", person.LastName);
    }

