namespace PathConverter
{
    class Converter
    {
        public static string[] Convert(string input)
        {
            var results = new string[4];
            if (String.IsNullOrEmpty(input)) return results;

            var parts = input.Split(new[] { '/', '\\' });
            if (parts.Length < 2) return results;

            // suppose input is valid path to make things simple

            var first = parts[0];
            string driver = null;
            string driver2 = null;
            bool skipSecond = false;
            if (first == String.Empty)
            {
                var second = parts[1];
                if (second.Length == 1 && Char.IsLetter(second, 0))
                {
                    driver = second + ':';
                    driver2 = "/" + second;
                    skipSecond = true;
                }
            }
            else if (first.EndsWith(":"))
            {
                driver = first;
                driver2 = "/" + first.TrimEnd(':');
            }

            var list = new List<string> { driver ?? first };
            // clear the extra path delimiters
            var i = skipSecond ? 2 : 1;
            for (; i < parts.Length; i++)
            {
                var item = parts[i];
                if (item != String.Empty) list.Add(item);
            }
            // the last path delimiter should be preserved
            var last = parts.Last();
            if (last == String.Empty) list.Add(last);

            var s3 = String.Join(@"/", list);
            results = new string[]
            {
                String.Join(@"\", list),
                String.Join(@"\\", list),
                s3,
                s3
            };

            if (!String.IsNullOrEmpty(driver2))
            {
                list[0] = driver2;
                results[3] = String.Join(@"/", list);
            }

            return results;
        }
    }
}

using System;
 
public class Tree
{
    public static void Main()
    {
        int[] list = new int[] { 31, 41, 59, 26, 53, 58, 97, 93, 23, 84 };
        Console.WriteLine("unsorted: " + string.Join(", ", list));
 
        BubbleSort(list);
        Console.WriteLine("sorted!  " + string.Join(", ", list));
    }
 
    public static void BubbleSort(int[] a)
    {
        for (int itemCount = a.Length - 1; ; itemCount--)
        {
            bool hasChanged = false;
            for (int index = 0; index < itemCount; index++)
            {
                if (a[index] > a[index + 1])
                {
                    int temp = a[index];
                    a[index] = a[index + 1];
                    a[index + 1] = temp;
                    hasChanged = true;
                }
            }
            if (hasChanged == false)
            {
                break;
            }
        }
    }
}

using UnityEngine;
using System.Collections;
using System.Collections.Generic;
using BeatManagement;

public class InitialBuildingEntryAnimation : Task
{
    private TaskManager subtaskManager;
    private float baseStaggerTime = 0.5f;
    private float structStaggerTime = 0.75f;
    private float terrainStaggerTime = 1.0f;
    private bool run_tasks = false;

    public InitialBuildingEntryAnimation()
    {
        subtaskManager = new TaskManager();
    }

    public override void Init()
    {
        run_tasks = true;
        ScheduleSubtasks();
    }

    public override void Update()
    {
        if (run_tasks && Services.Clock.OnQuarterBeat())
        {
            subtaskManager.Update();
            if (subtaskManager.IsComplete())
            {
                MarkAsComplete();
            }
        }
    }

    private void ScheduleSubtasks()
    {
        List<GameObject> playerBases = Services.MapManager.GetPlayerBases();
        List<GameObject> structures = Services.MapManager.GetStructures();
        List<GameObject> terrainElements = Services.MapManager.GetTerrainElements();

        int baseCount = playerBases.Count;
        int structCount = structures.Count;
        int terrainCount = terrainElements.Count;

        for (int i = 0; i < baseCount; i++)
        {
            float delay = baseStaggerTime * i;
            subtaskManager.AddTask(new Wait(delay));
            subtaskManager.AddTask(new BuildingDropAnimation(playerBases[i]));
        }

        for (int i = 0; i < structCount; i++)
        {
            float delay = structStaggerTime * i;
            subtaskManager.AddTask(new Wait(delay));
            subtaskManager.AddTask(new BuildingDropAnimation(structures[i]));
        }

        for (int i = 0; i < terrainCount; i++)
        {
            float delay = terrainStaggerTime * i;
            subtaskManager.AddTask(new Wait(delay));
            subtaskManager.AddTask(new BuildingDropAnimation(terrainElements[i]));
        }
    }
}

public class TaskManager
{
    private Queue<Task> tasks = new Queue<Task>();

    public void AddTask(Task task)
    {
        tasks.Enqueue(task);
        task.Init();
    }

    public void Update()
    {
        if (tasks.Count > 0)
        {
            Task currentTask = tasks.Peek();
            currentTask.Update();
            if (currentTask.IsComplete())
            {
                tasks.Dequeue();
            }
        }
    }

    public bool IsComplete()
    {
        return tasks.Count == 0;
    }
}

