    {

using System;
using System.Collections;
using System.Security.Util;

namespace SecurityExample
{
    // Abstract base class representing a permission.
    public abstract class Permission
    {
        public string Name { get; set; }
        public Permission(string name)
        {
            Name = name;
        }
        public override string ToString()
        {
            return $"Permission: {Name}";
        }
    }

    // Sample subclass representing a file permission.
    public class FilePermission : Permission
    {
        public string FilePath { get; private set; }
        public FilePermission(string name, string filePath)
            : base(name)
        {
            FilePath = filePath;
        }
        public override string ToString()
        {
            return $"FilePermission: {Name}, FilePath: {FilePath}";
        }
    }

    // Represents a set of permissions using token-based storage.
    public class PermissionSet
    {
        private object[] tokens;
        public PermissionSet(object[] tokenArray)
        {
            tokens = tokenArray;
        }
        // Returns a token-based enumerator for the internal tokens.
        public TokenBasedEnumerator GetTokenEnumerator()
        {
            return new TokenBasedEnumerator(tokens);
        }
    }

    // Provides a lower-level token-based enumeration mechanism.
    public class TokenBasedEnumerator : IEnumerator
    {
        private object[] tokens;
        private int currentIndex = -1;
        public TokenBasedEnumerator(object[] tokens)
        {
            this.tokens = tokens;
        }
        public object Current
        {
            get
            {
                if (currentIndex < 0 || currentIndex >= tokens.Length)
                    throw new InvalidOperationException();
                return tokens[currentIndex];
            }
        }
        public bool MoveNext()
        {
            currentIndex++;
            return currentIndex < tokens.Length;
        }
        public void Reset()
        {
            currentIndex = -1;
        }
    }

    // Custom enumerator that wraps the token-based enumerator to expose valid permissions.
    public class PermissionEnumerator : IEnumerator
    {
        private PermissionSet permissionSet;
