namespace ModelFramework.Extensions
{
    public static class ModelElementExtensions
    {
        public static IEnumerable<IModelElement> Descendants(this IModelElement element)
        {
            if (element == null) return Enumerable.Empty<IModelElement>();

            var descendants = new DescendantsCollection();
            TraverseDescendants(element, descendants);
            return descendants;
        }

        private static void TraverseDescendants(IModelElement element, DescendantsCollection descendants)
        {
            foreach (var child in element.GetChildren())
            {
                descendants.Add(child);
                TraverseDescendants(child, descendants);
            }
        }

        public static void Serialize(this IModelElement element, string filePath, IModelSerializer serializer = null)
        {
            if (element == null) return;

            serializer ??= GetDefaultSerializer();
            EnsureDirectoryExists(filePath);

            using var fileStream = new FileStream(filePath, FileMode.Create, FileAccess.Write);
            Serialize(element, fileStream, serializer);
        }

        public static void Serialize(this IModelElement element, Stream stream, IModelSerializer serializer = null)
        {
            if (element == null || stream == null) return;

            serializer ??= GetDefaultSerializer();
            var model = element.Model ?? new Model { RootElements = { element } };

            serializer.Serialize(model, stream);
        }

        private static void EnsureDirectoryExists(string filePath)
        {
            var directory = Path.GetDirectoryName(filePath);
            if (!string.IsNullOrEmpty(directory) && !Directory.Exists(directory))
            {
                Directory.CreateDirectory(directory);
            }
        }

        private static IModelSerializer GetDefaultSerializer()
        {
            // Implement or inject default serialization mechanism
            throw new NotImplementedException("Default model serializer not configured");
        }

