        }

        [Test]
        public void Test_SimpleCase_IdentifiesInefficientPattern()
        {
            var code = @"
                var numbers = new List<object> { 1, 2, 3.5, 4, 5 };
                var count = numbers.Cast<int>().Count();
            ";

            var expectedIssue = new DiagnosticResult
            {
                Id = analyzer.Id,
                Message = "Consider using 'OfType<int>().Count()' instead of 'Cast<int>().Count()'.",
            };

            Analyze(code, expectedIssue);
        }

        [Test]
        public void Test_SimpleCase_SuggestsReplacement()
        {
            var code = @"
                var numbers = new List<object> { 1, 2, 3.5, 4, 5 };
                var count = numbers.Cast<int>().Count();
            ";

            var correctedCode = @"
                var numbers = new List<object> { 1, 2, 3.5, 4, 5 };
                var count = numbers.OfType<int>().Count();
            ";

            VerifyFix(code, correctedCode);
        }

        [Test]
        public void Test_ComplexPredicate_IdentifiesAndSuggests()
        {
            var code = @"
                var mixedList = new List<object> { 'a', 1, 2, 3, 'b' };
                var count = mixedList.Cast<int>().Count(x => x > 1);
