namespace WpfReportViewerApp
{
    public partial class MainWindow : Window
    {
        private ReportViewer rv;
        private object parameters;

        public MainWindow()
        {
            InitializeComponent();
            InitializeReportViewer();
        }

        private void InitializeReportViewer()
        {
            // Initialize Xwt for WPF compatibility
            Xwt.Application.Initialize(ToolkitType.Wpf);

            // Create an instance of the report viewer
            rv = new ReportViewer();

            // Configure the report viewer to use the XwtWinforms backend
            rv.Backend = new XwtWinformsBackend();

            // Load a report based on the machine's environment
            string reportPath = GetReportPath();
            rv.LoadReport(new Uri(reportPath), parameters);

            // Convert the Xwt widget to a WPF panel
            var xwtWidget = rv.GetWidget();
            var w = (FrameworkElement)Xwt.Engine.WidgetRegistry.GetNativeWidget(xwtWidget);

            // Set the WPF panel as the main content of the window
            this.Content = w;
        }

        private string GetReportPath()
        {
            // Hardcoded report path for debugging purposes
            string machineName = Environment.MachineName;
            if (machineName == "DEBUG_MACHINE")
            {
                return @"C:\Reports\SampleReport.rdl";
            }
            else
            {
                return @"C:\Reports\DefaultReport.rdl";
            }
        }
    }
