namespace MyApp.Events
{
    // Custom event arguments for notifying changes in a DataGridView column's auto-size mode.
    public class DataGridColumnAutoSizeChangedEventArgs : EventArgs
    {
        // Read-only property for the grid column.
        public DataGridViewColumn GridColumn { get; }

        // Read-only property for the previous auto-size mode of the grid column.
        public DataGridViewAutoSizeColumnMode PreviousAutoSizeMode { get; }

        // Constructor that initializes the event arguments with the provided grid column and its previous auto-size mode.
        public DataGridColumnAutoSizeChangedEventArgs(DataGridViewColumn gridColumn, DataGridViewAutoSizeColumnMode previousMode)
        {
            // Validate that the provided grid column is not null.
            Debug.Assert(gridColumn != null, "Grid column cannot be null.");
            if (gridColumn == null)
            {
                throw new ArgumentNullException(nameof(gridColumn), "Grid column cannot be null.");
            }

            GridColumn = gridColumn;
            PreviousAutoSizeMode = previousMode;
        }
    }

    // A custom DataGridView that triggers an event when a column's auto-size mode changes.
    public class CustomDataGridView : DataGridView
    {
        // Event triggered after a column's auto-size mode changes.
        public event EventHandler<DataGridColumnAutoSizeChangedEventArgs> ColumnAutoSizeChanged;

        // Method to simulate a change in a grid column's auto-size mode.
        public void OnColumnAutoSizeChanged(DataGridViewColumn column, DataGridViewAutoSizeColumnMode oldMode)
        {
            var args = new DataGridColumnAutoSizeChangedEventArgs(column, oldMode);
            ColumnAutoSizeChanged?.Invoke(this, args);
        }

        // Public method to change the auto-size mode of a specified column.
        public void ChangeColumnAutoSizeMode(int columnIndex, DataGridViewAutoSizeColumnMode newMode)
        {
            if (Columns.Count > columnIndex)
            {
                // Retrieve the specified column.
                DataGridViewColumn column = Columns[columnIndex];
                // Store the previous auto-size mode.
                DataGridViewAutoSizeColumnMode oldMode = column.AutoSizeMode;
                // Change to the new auto-size mode.
                column.AutoSizeMode = newMode;
                // Notify subscribers about this change.
                OnColumnAutoSizeChanged(column, oldMode);
            }
        }

using System;
