public class Graph
{
    public static bool isPrime(int n)
    {
        if (n < 2) return false;
        if (n % 2 == 0) return n == 2;
        var limit = (int)Math.Sqrt(n);
        return Enumerable.Range(3, limit - 3).Step(2).All(it => n % it!= 0);
    }
 
    public static void Main(string[] args)
    {
        // test by printing all primes below 100 say
        Enumerable.Range(2, 99 - 2).Where(it => isPrime(it)).ForEach(it => Console.Write(it + " "));
    }
}

