public class HealthManager : MonoBehaviour
{
    // Maximum health of the entity.
    public float maxHealth = 100f;

    // Actual current health value.
    private float currentHealth;

    // Displayed health value for smooth UI animation.
    private float displayedHealth;

    // Determines if this entity is a player.
    public bool isPlayer = false;

    // Flag to track if the entity is dead.
    private bool isDead = false;

    // Reference to the UI Image component representing the health bar.
    public Image healthBar;

    // Reference to the GameManager, used for player death handling.
    public GameManager gameManager;

    // Speed at which the health bar transitions.
    public float lerpSpeed = 3f;

    // Key for saving the player's health persistently.
    private const string HealthKey = "PlayerHealth";

    // Called when the script instance is being loaded.
    void Start()
    {
        InitializeHealth();
    }

    // Initialize the health values and update the UI accordingly.
    public void InitializeHealth()
    {
        // If this entity is a player, load saved health if available.
        if (isPlayer && PlayerPrefs.HasKey(HealthKey))
        {
            currentHealth = PlayerPrefs.GetFloat(HealthKey);
        }
        else
        {
            currentHealth = maxHealth;
            if (isPlayer)
            {
                PlayerPrefs.SetFloat(HealthKey, currentHealth);
                PlayerPrefs.Save();
            }
        }

        // Set the displayed health to match the current value.
        displayedHealth = currentHealth;

        // Update the health bar UI.
        UpdateHealthBarUI();
    }

    // Update is called once per frame.
    void Update()
    {
        // Smoothly interpolate the displayed health toward the actual health.
        if (Mathf.Abs(displayedHealth - currentHealth) > 0.01f)
        {
            displayedHealth = Mathf.Lerp(displayedHealth, currentHealth, Time.deltaTime * lerpSpeed);
            UpdateHealthBarUI();
        }
    }

    // Update the health bar UI based on the displayed health value.
    void UpdateHealthBarUI()
    {

