public static double power(double base, int exponent)
{
  int zerodir;
  double factor;
  if (exponent < 0)
  {
    zerodir = 1;
    factor = 1/base;
  }
  else
  {
    zerodir = -1;
    factor = base;
  }

  double result = 1;
  while (exponent!= 0)
  {
    if (exponent % 2!= 0)
    {
      result *= factor;
      exponent += zerodir;
    }
    else
    {
      factor *= factor;
      exponent /= 2;
    }
  }
  return result;
}

