namespace Catalan
{
    class Service
    {
        static void Main(string[] args)
        {
            var fc = new List<int>();
            var c2 = new List<int>();
            var c3 = new List<int>();
            Func<int, int> fact = n => fc[n]!= 0? fc[n] : fc[n] = (n!= 0? n * fact(n - 1) : 1);
            Func<int, int> cata1 = n => (int)Math.Floor(fact(2 * n) / fact(n + 1) / fact(n) +.5);
            Func<int, int> cata2 = n =>
            {
                if (n == 0) return 1;
                if (c2[n] == 0)
                {
                    var s = 0;
                    for (var i = 0; i < n; i++) s += cata2(i) * cata2(n - i - 1);
                    c2[n] = s;
                }
                return c2[n];
            };
            Func<int, int> cata3 = n =>
            {
                if (n == 0) return 1;
                return c3[n]!= 0? c3[n] : c3[n] = (4 * n - 2) * cata3(n - 1) / (n + 1);
            };
            Console.WriteLine("       meth1   meth2   meth3");
            for (var i = 0; i <= 15; i++)
                Console.WriteLine(i + "\t" + cata1(i) + "\t" + cata2(i) + "\t" + cata3(i));
            Console.ReadKey();
        }
    }
}

