        }

        public ActionResult Index()
        {
            try
            {
                var apiDescriptions = _configuration.GetApiDescriptions();
                return View(apiDescriptions);
            }
            catch (Exception ex)
            {
                // Log exception (not implemented here)
                return View(ErrorViewName);
            }
        }

        public ActionResult Api(string id)
        {
            if (string.IsNullOrEmpty(id))
            {
                return View(ErrorViewName);
            }

            try
            {
                var apiDetail = _configuration.GetApiDetailById(id);
                if (apiDetail == null)
                {
                    return View(ErrorViewName);
                }

                return View(apiDetail);
            }
            catch (Exception ex)
            {
                // Log exception (not implemented here)
                return View(ErrorViewName);
            }
        }

        public ActionResult ResourceModel(string modelName)
        {
            if (string.IsNullOrEmpty(modelName))
            {
                return View(ErrorViewName);
            }

            try
            {
                var modelDescription = _configuration.GetModelDescription(modelName);
                if (modelDescription == null)
                {
                    return View(ErrorViewName);
                }

                return View(modelDescription);
            }
            catch (Exception ex)
            {
                // Log exception (not implemented here)
                return View(ErrorViewName);
            }
        }
