namespace InteropDemo
{
    // Defines a configuration structure for interacting with an external embedded framework.
    [StructLayout(LayoutKind.Sequential, Pack = 8)]
    public struct EmbeddedFrameworkConfig
    {
        public int Size; // Size of the structure
        public bool EnableProcessManagement; // Flag to enable process management
        public IntPtr ProcessPath; // Pointer to process executable path string
        public bool EnableLogging; // Flag to enable logging
        public int LogLevel; // Logging level (e.g., 0=none, 1=error, 2=info, etc.)
        public IntPtr LogFilePath; // Pointer to log file path string
        public bool DebugMode; // Flag to enable debugging mode
        public IntPtr DebugConfigPath; // Pointer to debug configuration file path
    }

    // Provides helper methods for allocation and deallocation of unmanaged memory
    // for the EmbeddedFrameworkConfig structure.
    public static class ConfigNativeInterop
    {
        // Size of the structure is computed once at runtime.
        public static readonly int ConfigSize;

        static ConfigNativeInterop()
        {
            ConfigSize = Marshal.SizeOf(typeof(EmbeddedFrameworkConfig));
        }

        // Allocates unmanaged memory for the EmbeddedFrameworkConfig structure,
        // initializes default values, and returns a pointer to the allocated memory.
        public static IntPtr AllocateConfig()
        {
            IntPtr configPtr = Marshal.AllocHGlobal(ConfigSize);
            EmbeddedFrameworkConfig config = new EmbeddedFrameworkConfig();

            // Initialize configuration with default values.
            config.Size = ConfigSize;
            config.EnableProcessManagement = false;
            config.ProcessPath = IntPtr.Zero;
            config.EnableLogging = true;
            config.LogLevel = 2;
            config.LogFilePath = IntPtr.Zero;
            config.DebugMode = false;
            config.DebugConfigPath = IntPtr.Zero;

            // Copy the managed structure to unmanaged memory.
            Marshal.StructureToPtr(config, configPtr, false);
            return configPtr;
        }

        // Frees the previously allocated unmanaged memory and cleans up the structure.
        public static void FreeConfig(IntPtr configPtr)
        {
            if (configPtr != IntPtr.Zero)
            {
                // Ensure any unmanaged data attached to the structure gets cleaned up.
                Marshal.DestroyStructure<EmbeddedFrameworkConfig>(configPtr);

