public class MainWindowPresenter : DependencyObject, IPresenter
{
    private readonly Dictionary<int, PivotItem> _panelRegistry = new Dictionary<int, PivotItem>();

    public static readonly DependencyProperty PanelsProperty = DependencyProperty.Register(
        "Panels", typeof(ObservableCollection<PivotItem>), typeof(MainWindowPresenter), null);

    public ObservableCollection<PivotItem> Panels
    {
        get => (ObservableCollection<PivotItem>)GetValue(PanelsProperty);
        set => SetValue(PanelsProperty, value);
    }

    public MainWindowPresenter()
    {
        if (DesignerProperties.GetIsInDesignMode(this)) return;

        Panels = new ObservableCollection<PivotItem>();
        Shell.Instance.ShowError += (s, e) => ShowError(e.Error, e.Status);
        Shell.Instance.ShowStatus += (s, e) => ShowStatus(e.Status);
        Shell.Instance.ShowView += (s, e) => ShowView(e.View, e.Region);
    }

    private PivotItem GetPanel(string region)
    {
        if (!int.TryParse(region, out int regionNum)) regionNum = 0;

        if (!_panelRegistry.TryGetValue(regionNum, out PivotItem panel))
        {
            panel = new PivotItem();
            Panels.Add(panel);
            _panelRegistry.Add(regionNum, panel);
        }
        return panel;
    }

    private void ShowView(object view, string region)
    {
        if (view is FrameworkElement element && !string.IsNullOrEmpty(region))
        {
            var panel = GetPanel(region);
            panel.Content = new ContentPresenter { Content = element };

            if (element.DataContext is IViewModel vm)
                panel.Header = new TextBlock { Text = vm.Title };
        }
    }

    private void ShowError(string message, string status)
    {
        MessageBox.Show($"{status}: {message}", "Error", MessageBoxButton.OK);
    }

    private void ShowStatus(string status)
    {
        Shell.Instance.Status = new Status { IsBusy = !string.IsNullOrEmpty(status), Text = status };
    }

    public void Startup()
    {
        if (DesignerProperties.GetIsInDesignMode(this)) return;

        try
        {
            var view = new OrderEdit();
            view.DataContext = new OrderVm();
            ShowView(view, "0");
        }
        catch (Exception ex)
        {
            Shell.Instance.ShowError(ex.Message, "Startup Error");
        }
    }
}

