namespace NXTLib
{
    public static class Utils
    {
        public static string AddressByte2String(byte[] address, bool withColons = true)
        {
            if (address == null || address.Length != 6)
                throw new ArgumentException("Invalid Bluetooth address byte array.");

            var sb = new StringBuilder();
            for (int i = 0; i < address.Length; i++)
            {
                sb.Append(address[i].ToString("X2"));
                if (withColons && i < address.Length - 1)
                    sb.Append(":");
            }
            return sb.ToString();
        }

        public static byte[] AddressString2Byte(string address)
        {
            if (string.IsNullOrEmpty(address) || address.Length != 17)
                throw new ArgumentException("Invalid Bluetooth address string.");

            var bytes = new byte[6];
            var parts = address.Split(':');
            for (int i = 0; i < parts.Length; i++)
            {
                bytes[i] = Convert.ToByte(parts[i], 16);
            }
            return bytes;
        }

        public static List<T> Combine<T>(List<T> list1, List<T> list2)
        {
            var combined = new List<T>();
            if (list1 != null)
                combined.AddRange(list1);
            if (list2 != null)
                combined.AddRange(list2);
            return combined;
        }

        public static int GetValue(this string input, int defaultValue = 0)
        {
            if (int.TryParse(input, out int result))
                return result;
            return defaultValue;
        }
    }

    public class Brick
    {
        public string Name { get; set; }
        public byte[] Address { get; set; }

        public override string ToString()
        {
            return $"{Name} ({Utils.AddressByte2String(Address)})";
        }
    }
}

