namespace Holidays
{
    class Graph
    {
        static void Main(string[] args)
        {
            var holidayOffsets = new List<Tuple<string, int>>
            {
                new Tuple<string, int>("Easter", 0),
                new Tuple<string, int>("Ascension", 39),
                new Tuple<string, int>("Pentecost", 49),
                new Tuple<string, int>("Trinity", 56),
                new Tuple<string, int>("C/Christi", 60)
            };
 
            Func<string, int, string> padCenter = (s, n) =>
            {
                var len = s.Length;
                if (n <= len) return s;
                return s.PadLeft((n + len) / 2).PadRight(n);
            };
 
            Func<int, DateTime> calculateEaster = (year) =>
            {
                var a = year % 19;
                var b = year / 100;
                var c = year % 100;
                var d = b / 4;
                var e = b % 4;
                var f = (b + 8) / 25;
                var g = (b - f + 1) / 3;
                var h = (19 * a + b - d - g + 15) % 30;
                var i = c / 4;
                var k = c % 4;
                var l = (32 + 2 * e + 2 * i - h - k) % 7;
                var m = (a + 11 * h + 22 * l) / 451;
                var n = h + l - 7 * m + 114;
                var month = n / 31 - 1;  // months indexed from 0
                var day = (n % 31) + 1;
                return new DateTime(year, month, day);
            };
 
            Action<int> outputHolidays = (year) =>
            {
                var date = calculateEaster(year);
                Console.Write("{0,4}  ", year);
                var po = 0;
                foreach (var holidayOffset in holidayOffsets)
                {
                    var h = holidayOffset.Item1;
                    var o = holidayOffset.Item2;
                    date = date.AddDays(o - po);
                    po = o;
                    Console.Write("{0}  ", date.ToString("dd MMM", CultureInfo.InvariantCulture).PadCenter(h.Length));
                }
                Console.WriteLine();
            };
 
            Console.WriteLine("Year  Easter  Ascension  Pentecost  Trinity  C/Christi");
            Console.WriteLine(" CE   Sunday  Thursday    Sunday    Sunday   Thursday ");
            Console.WriteLine("----  ------  ---------  ---------  -------  ---------");
            for (var year = 400; year <= 2100; year += 100) outputHolidays(year);
            Console.WriteLine();

