    public class YouWin : IGameState
    {
        public bool Evaluate(int guess, int target) => guess == target;
        public void Execute() => Console.WriteLine("Congratulations! You guessed the number!");
    }

    public class TooHigh : IGameState
    {
        public bool Evaluate(int guess, int target) => guess > target;
        public void Execute() => Console.WriteLine("Your guess is too high. Try again!");
    }

    public class TooLow : IGameState
    {
        public bool Evaluate(int guess, int target) => guess < target;
        public void Execute() => Console.WriteLine("Your guess is too low. Try again!");
    }

    public interface IGameState
    {
        bool Evaluate(int guess, int target);
        void Execute();
    }

    public class GuessANumber
    {
        private readonly IGameState[] _states;
        private readonly int _targetNumber;

        public GuessANumber(IGameState[] states)
        {
            _states = states;
            _targetNumber = StaticRandomNumberValueProvider.Provide();
        }

        public bool Play()
        {
            while (true)
            {
                Console.Write("Enter your guess (0-100): ");
                if (!int.TryParse(Console.ReadLine(), out int userGuess))
                {
                    Console.WriteLine("Invalid input. Please enter a number.");
                    continue;
                }

                foreach (var state in _states)
                {
                    if (state.Evaluate(userGuess, _targetNumber))
                    {
                        state.Execute();
                        return state is YouWin;
                    }
                }
            }
        }
    }

