    {
        private readonly GuessANumber _game;

        public GameLoop(GuessANumber game)
        {
            _game = game;
        }

        public void Start()
        {
            bool playAgain;
            do
            {
                bool won = _game.Play();
                Console.WriteLine(won ? "You won the game!" : "Game over.");

