    class Handler
    {
        static void Main(string[] args)
        {
            // create 15 buckets
            Buckets buckets = new Buckets(15);
 
            // the randomize thread
            Thread t1 = new Thread(() => randomize(buckets));
            t1.Start();
 
            // the equalize thread
            Thread t2 = new Thread(() => equalize(buckets));
            t2.Start();
 
            // main thread, display
            try
            {
                while (true)
                {
                    print_state(buckets);
                    Thread.Sleep(1000);
                }
            }
            catch (Exception)
            {
                terminate.Set();
            }
 
            // wait until all worker threads finish
            t1.Join();
            t2.Join();
        }
 
        static EventWaitHandle terminate = new EventWaitHandle(false, EventResetMode.ManualReset);
 
        class Buckets
        {
            public int nbuckets;
            public int[] values;
            public object locker = new object();
 
            public Buckets(int nbuckets)
            {
                this.nbuckets = nbuckets;
                this.values = new int[nbuckets];
                for (int i = 0; i < nbuckets; i++)
                {
                    this.values[i] = new Random().Next(10);
                }
            }
 
            public int this[int i]
            {
                get { return this.values[i]; }
            }
 
            public void transfer(int src, int dst, int amount)
            {
                lock (locker)
                {
                    amount = Math.Min(amount, this.values[src]);
                    this.values[src] -= amount;
                    this.values[dst] += amount;
                }
            }
 
            public int[] snapshot()
            {
                // copy of the current state (synchronized)
                lock (locker)
                {
                    return this.values.ToArray();
                }
            }
        }
 
