    public static class BluetoothHelper
    {
        // Converts a 6-byte address to a formatted string.
        public static string ByteArrayToAddressString(byte[] address, bool includeDelimiters = true)
        {
            if (address == null || address.Length != 6)
            {
                throw new ArgumentException("Address must be a 6-byte array.");
            }
            StringBuilder sb = new StringBuilder();
            for (int i = address.Length - 1; i >= 0; i--)
            {
                sb.Append(address[i].ToString("X2"));
                if (includeDelimiters && i > 0)
                {
                    sb.Append(":");
                }
            }
            return sb.ToString();
        }

        // Converts a formatted address string back into a 6-byte array.
        public static byte[] AddressStringToByteArray(string addressString, bool hasDelimiters = true)
        {
            if (string.IsNullOrEmpty(addressString))
            {
                throw new ArgumentNullException("addressString");
            }
            byte[] address = new byte[6];
            if (hasDelimiters)
            {
                string[] parts = addressString.Split(new char[] { ':', '-' }, StringSplitOptions.RemoveEmptyEntries);
                if (parts.Length != 6)
                {
                    throw new FormatException("Invalid address format.");
                }
                for (int i = 0; i < 6; i++)
                {
                    address[5 - i] = Convert.ToByte(parts[i], 16);
                }
            }
            else
            {
                if (addressString.Length != 12)
                {
                    throw new FormatException("Invalid address format length for continuous string.");
                }
                for (int i = 0; i < 6; i++)
                {
                    string byteStr = addressString.Substring(i * 2, 2);
                    address[5 - i] = Convert.ToByte(byteStr, 16);
                }
            }
            return address;
        }

