public interface ICodeModelInstanceFactory
{
    FileCodeModel CreateFileCodeModel(CPSProject project, string filePath);
}

[Export(typeof(ICodeModelInstanceFactory))]
public class CPSCodeModelInstanceFactory : ICodeModelInstanceFactory
{
    public FileCodeModel CreateFileCodeModel(CPSProject project, string filePath) =>
        new FileCodeModel(project, filePath);
}

public class CPSProject : Project
{
    private readonly Lazy<CodeModel> _projectCodeModel;
    private readonly Dictionary<string, FileCodeModel> _fileCodeModels = new Dictionary<string, FileCodeModel>(StringComparer.OrdinalIgnoreCase);
    private readonly IVisualStudioWorkspace _visualStudioWorkspace;
    private readonly ICodeModelInstanceFactory _factory;
    private readonly IVisualStudioProject _visualStudioProject;

    [ImportingConstructor]
    public CPSProject(
        IVisualStudioWorkspace workspace,
        IVisualStudioProject project,
        ICodeModelInstanceFactory factory)
    {
        _visualStudioWorkspace = workspace;
        _visualStudioProject = project;
        _factory = factory;
        _projectCodeModel = new Lazy<CodeModel>(CreateProjectCodeModel);
    }

    public CodeModel GetCodeModel() => _projectCodeModel.Value;

    public FileCodeModel GetFileCodeModel(string filePath)
    {
        lock (_fileCodeModels)
        {
            if (!_fileCodeModels.TryGetValue(filePath, out var codeModel))
            {
                codeModel = TryCreateFileCodeModelThroughProjectSystem(filePath);
                if (codeModel != null) _fileCodeModels[filePath] = codeModel;
            }
            return codeModel;
        }
    }

    private FileCodeModel TryCreateFileCodeModelThroughProjectSystem(string filePath)
    {
        var projectItem = GetProjectItem(filePath);
        return projectItem != null ? _factory.CreateFileCodeModel(this, filePath) : null;
    }

    public ProjectItem GetProjectItem(string filePath)
    {
        var documentId = _visualStudioWorkspace.CurrentSolution.GetDocumentIdsWithFilePath(filePath).FirstOrDefault();
        return documentId != null ? _visualStudioWorkspace.GetProjectItem(documentId) : null;
    }

    private CodeModel CreateProjectCodeModel() => new CodeModel(this);
}

