namespace DiversityTheorem
{
    class Converter
    {
        static void Main(string[] args)
        {
            var truth = 49.0;
            var predictions = new List<double> { 48.0, 47.0, 51.0 };
            DiversityTheorem(truth, predictions);
            predictions.Add(42.0);
            DiversityTheorem(truth, predictions);
        }
 
        static double Mean(List<double> a)
        {
            return a.Sum() / a.Count;
        }
 
        static double MeanSquareDiff(List<double> a, List<double> predictions)
        {
            return Mean(predictions.Select(x => Math.Pow(x - a.First(), 2)).ToList());
        }
 
        static void DiversityTheorem(double truth, List<double> predictions)
        {
            var average = Mean(predictions);
            Console.WriteLine("truth: {0}, predictions {1}", truth, string.Join(",", predictions));
            Console.WriteLine("average-error: {0}", MeanSquareDiff(new List<double> { truth }, predictions));
            Console.WriteLine("crowd-error: {0}", Math.Pow(truth - average, 2));
            Console.WriteLine("diversity: {0}", MeanSquareDiff(new List<double> { average }, predictions));
            Console.WriteLine();
        }
    }
}

