using UnityEngine;
using LuaInterface;

public class Lua_UnityEngine_JointTranslationLimits2D
{
    private JointTranslationLimits2D limits;

    public Lua_UnityEngine_JointTranslationLimits2D()
    {
        limits = new JointTranslationLimits2D();
    }

    public void SetMinLimit(float minLimit)
    {
        try
        {
            if (minLimit < limits.max)
            {
                limits.min = minLimit;
            }
            else
            {
                Debug.LogError("Minimum limit cannot be greater than maximum limit.");
            }
        }
        catch (System.Exception e)
        {
            Debug.LogError("Error setting minimum limit: " + e.Message);
        }
    }

    public void SetMaxLimit(float maxLimit)
    {
        try
        {
            if (maxLimit > limits.min)
            {
                limits.max = maxLimit;
            }
            else
            {
                Debug.LogError("Maximum limit cannot be less than minimum limit.");
            }
        }
        catch (System.Exception e)
        {
            Debug.LogError("Error setting maximum limit: " + e.Message);
        }
    }

    public float GetMinLimit()
    {
        return limits.min;
    }

    public float GetMaxLimit()
    {
        return limits.max;
    }

    public void SetLimits(float minLimit, float maxLimit)
    {
        try
        {
            if (minLimit < maxLimit)
            {
                limits.min = minLimit;
                limits.max = maxLimit;
            }
            else
            {
                Debug.LogError("Invalid limits: min should be less than max.");
            }
        }
        catch (System.Exception e)
        {
            Debug.LogError("Error setting limits: " + e.Message);
        }
    }

    [LuaFunction("SetMinLimit")]
    public void LuaSetMinLimit(float minLimit)
    {
        SetMinLimit(minLimit);
    }

    [LuaFunction("SetMaxLimit")]
    public void LuaSetMaxLimit(float maxLimit)
    {
        SetMaxLimit(maxLimit);
    }

    [LuaFunction("GetMinLimit")]
    public float LuaGetMinLimit()
    {
        return GetMinLimit();
    }

    [LuaFunction("GetMaxLimit")]
    public float LuaGetMaxLimit()
    {
        return GetMaxLimit();
    }

    [LuaFunction("SetLimits")]
    public void LuaSetLimits(float minLimit, float maxLimit)
    {
        SetLimits(minLimit, maxLimit);
    }
}

