namespace DesignPatterns
{
    // Singleton Pattern
    public class Singleton
    {
        private static Singleton instance;
        private Singleton() { }

        public static Singleton Instance
        {
            get
            {
                if (instance == null)
                {
                    instance = new Singleton();
                }
                return instance;
            }
        }

        public void Foo()
        {
            Console.WriteLine("Singleton Foo method called.");
        }
    }

    // Iterator Pattern
    public class Person
    {
        public string Name { get; set; }
    }

    public class People : IEnumerable<Person>
    {
        private List<Person> pList = new List<Person>();

        public void Add(Person person)
        {
            pList.Add(person);
        }

        public IEnumerator<Person> GetEnumerator()
        {
            return pList.GetEnumerator();
        }

        IEnumerator IEnumerable.GetEnumerator()
        {
            return GetEnumerator();
        }
    }

    // Factory Pattern
    public abstract class Ship
    {
        public abstract void ShipStatus();
    }

    public class RocketShip : Ship
    {
        public override void ShipStatus()
        {
            Console.WriteLine("Rocket Ship - Speed: 1000 km/h");
        }
    }

    public class SpaceShip : Ship
    {
        public override void ShipStatus()
        {
            Console.WriteLine("Space Ship - Speed: 5000 km/h");
        }
    }

    public class ShipFactory
    {
        public Ship MakeShip(string type)
        {
            switch (type)
            {
                case "Rocket":
                    return new RocketShip();
                case "Space":
                    return new SpaceShip();
                default:
                    throw new ArgumentException("Unknown ship type");
            }
        }
    }

