            {
                // Iterator Pattern
                People people = new People();
                people.Add(new Person { Name = "Alice" });
                people.Add(new Person { Name = "Bob" });

using System;
using System.Runtime.InteropServices;

public static class NativeMethods
{
    public static class Darwin
    {
        private const int CTL_KERN = 1;
        private const int KERN_OSRELEASE = 2;
        private const int BUFFER_LENGTH = 256;

        [DllImport("libc", SetLastError = true)]
        private static extern int sysctl(
            ref int[] name,
            uint namelen,
            IntPtr oldp,
            ref IntPtr oldlenp,
            IntPtr newp,
            IntPtr newlen);

        public static string GetKernelRelease()
        {
            int[] mib = new int[] { CTL_KERN, KERN_OSRELEASE };
            IntPtr bufferSize = IntPtr.Zero;

            // First call to get the required buffer size
            int result = sysctl(ref mib, (uint)mib.Length, IntPtr.Zero, ref bufferSize, IntPtr.Zero, IntPtr.Zero);
            if (result != 0)
            {
                throw new PlatformNotSupportedException("Failed to get buffer size for kernel release.");
            }

            if (bufferSize.ToInt32() > BUFFER_LENGTH)
            {
                throw new PlatformNotSupportedException("Buffer size for kernel release is too large.");
            }

            // Allocate buffer for the kernel release string
            byte* buffer = stackalloc byte[BUFFER_LENGTH];
            bufferSize = (IntPtr)BUFFER_LENGTH;

            // Second call to get the kernel release string
            result = sysctl(ref mib, (uint)mib.Length, (IntPtr)buffer, ref bufferSize, IntPtr.Zero, IntPtr.Zero);
            if (result != 0)
            {
                throw new PlatformNotSupportedException("Failed to get kernel release.");
            }

            // Convert the byte array to a string
            string kernelRelease = Marshal.PtrToStringAnsi((IntPtr)buffer);
            return kernelRelease;
        }
    }
}

//---------------------------------------------------------------------------------------------
// onLine is invoked whenever the TCP object receives a line from the server. Treat the first
// word as a "command" and dispatch to an appropriate handler.
//---------------------------------------------------------------------------------------------
function TCPDebugger::onLine(%this, %line)
{
   echo("Got line=>" @ %line);
   %cmd = firstWord(%line);
   %rest = restWords(%line);

   if (%cmd $= "PASS") {
      %this.handlePass(%rest);
   }
   else if(%cmd $= "COUT") {
      %this.handleLineOut(%rest);
   }
   else if(%cmd $= "FILELISTOUT") {
      %this.handleFileList(%rest);
   }
   else if(%cmd $= "BREAKLISTOUT") {
      %this.handleBreakList(%rest);
   }
   else if(%cmd $= "BREAK") {
      %this.handleBreak(%rest);
   }
   else if(%cmd $= "RUNNING") {
      %this.handleRunning();
   }
   else if(%cmd $= "EVALOUT") {
      %this.handleEvalOut(%rest);
   }
   else {
      %this.handleError(%line);
   }
}

// Handler for PASS response.
function TCPDebugger::handlePass(%this, %message)
{
   if (%message $= "WrongPass") {
      DebuggerConsoleView.print("Disconnected - wrong password.");
      %this.disconnect();
   }
   else if(%message $= "Connected.") {
      DebuggerConsoleView.print("Connected.");
      DebuggerStatus.setValue("CONNECTED");
      %this.send("FILELIST\r\n");
   }
}

// Handler for COUT response.
function TCPDebugger::handleLineOut(%this, %line)
{
   DebuggerConsoleView.print(%line);
}

// Handler for FILELISTOUT response.
function TCPDebugger::handleFileList(%this, %line)
{
   DebuggerFilePopup.clear();
   %word = 0;
   while ((%file = getWord(%line, %word)) !$= "") {
      %word++;
      DebuggerFilePopup.add(%file, %word);
   }
}

// Handler for BREAKLISTOUT response.
function TCPDebugger::handleBreakList(%this, %line)
{
   %file = getWord(%line, 0);
   if (%file != $DebuggerFile) {
      return;
   }
   %pairs = getWord(%line, 1);
   %curLine = 1;
   DebuggerFileView.clearBreakPositions();

   // Set the possible break positions.
   for (%i = 0; %i < %pairs; %i++) {
      %skip = getWord(%line, %i * 2 + 2);
      %breaks = getWord(%line, %i * 2 + 3);
      %curLine += %skip;
      for (%j = 0; %j < %breaks; %j++) {
         DebuggerFileView.setBreakPosition(%curLine);
         %curLine++;
      }
   }

   // Now set the actual break points.
   for (%i = 0; %i < DebuggerBreakPoints.rowCount(); %i++) {
      %breakText = DebuggerBreakPoints.getRowText(%i);
      %breakLine = getField(%breakText, 0);

