namespace Tree
{
    class Processor
    {
        static void Main(string[] args)
        {
            Random rand = new Random();
            const int calls = 1000000;
            double max;
            bool flatEnough;
            max = distCheck(dice7, 7, calls, 500, rand);
            Console.WriteLine("Max delta: {0} Flat enough: {1}", max, flatEnough);
            max = distCheck(dice7, 7, calls, 500, rand);
            Console.WriteLine("Max delta: {0} Flat enough: {1}", max, flatEnough);
            Console.ReadKey();
        }

        static int dice5(Random rand)
        {
            return rand.Next(5) + 1;
        }

        static int dice7(Random rand)
        {
            int i;
            for (; ; )
            {
                i = 5 * dice5(rand) + dice5(rand);
                if (i < 27)
                {
                    break;
                }
            }
            return (i / 3) - 1;
        }

        static double distCheck(Func<Random, int> f, int n, int repeats, double delta, Random rand)
        {
            int[] count = new int[n];
            for (int i = 0; i < repeats; i++)
            {
                count[f(rand) - 1]++;
            }
            double expected = (double)repeats / (double)n;
            double max = 0;
            for (int i = 0; i < n; i++)
            {
                max = Math.Max(max, Math.Abs((double)count[i] - expected));
            }
            return max;
        }
    }
}

