using System;
using System.Collections.Generic;
using System.Text;
using System.Xml;

public enum ExtensionDirection
{
    Left,
    Right,
    Up,
    Down
}

public class BookmarkWordTable
{
    private ExtensionDirection _Extension;

    public ExtensionDirection Extension
    {
        get { return _Extension; }
        set { _Extension = value; }
    }

    public BookmarkWordTable() {}

    public static BookmarkWordTable MappingFromNode(XmlNode node)
    {
        if (node == null)
            throw new ArgumentNullException(nameof(node));

        BookmarkWordTable tableConfig = new BookmarkWordTable();

        if (node.Attributes != null)
        {
            var extensionAttr = node.Attributes["Extension"];
            if (extensionAttr != null)
            {
                if (Enum.TryParse(extensionAttr.Value, true, out ExtensionDirection direction))
                {
                    tableConfig.Extension = direction;
                }
                else
                {
                    throw new FormatException($"Invalid value for Extension: {extensionAttr.Value}");
                }
            }
        }
        return tableConfig;
    }

    public XmlNode MappingToNode(XmlDocument xmlDoc)
    {
        if (xmlDoc == null)
            throw new ArgumentNullException(nameof(xmlDoc));

        XmlElement tableNode = xmlDoc.CreateElement("BookmarkWordTable");
        tableNode.SetAttribute("Extension", Extension.ToString());

        return tableNode;
    }

    public string Serialize()
    {
        XmlDocument xmlDoc = new XmlDocument();
        XmlNode rootNode = MappingToNode(xmlDoc);
        xmlDoc.AppendChild(rootNode);
        return xmlDoc.OuterXml;
    }

    public static BookmarkWordTable Deserialize(string xmlData)
    {
        if (string.IsNullOrEmpty(xmlData))
            throw new ArgumentNullException(nameof(xmlData));

        XmlDocument xmlDoc = new XmlDocument();
        xmlDoc.LoadXml(xmlData);
        return MappingFromNode(xmlDoc.DocumentElement);
    }
}

// Example usage
class Parser
{
    static void Main()
    {
        // Creating an instance and serializing it
        BookmarkWordTable table = new BookmarkWordTable
        {
            Extension = ExtensionDirection.Right
        };
        string xml = table.Serialize();
        Console.WriteLine($"Serialized XML: {xml}");

        // Deserializing the XML back to an object
        BookmarkWordTable deserializedTable = BookmarkWordTable.Deserialize(xml);
        Console.WriteLine($"Deserialized Extension: {deserializedTable.Extension}");
    }

