namespace LongPrimes
{
    class Stack
    {
        static void Main(string[] args)
        {
            long_primes(500, 8192000);
        }
 
        static void long_primes(long limit1, long limit2)
        {
            var sieve = new PrimeSieve(limit2);
            long count = 0;
            long limit = limit1;
            long prime = 3;
            while (prime < limit2)
            {
                if (is_long_prime(sieve, prime))
                {
                    if (prime < limit1)
                    {
                        Console.Write("{0} ", prime);
                    }
                    if (prime > limit)
                    {
                        Console.WriteLine("\nNumber of long primes up to {0}: {1}", limit, count);
                        limit *= 2;
                    }
                    count++;
                }
                prime += 2;
            }
            Console.WriteLine("\nNumber of long primes up to {0}: {1}", limit, count);
        }
 
        static bool is_long_prime(PrimeSieve sieve, long prime)
        {
            if (!sieve.is_prime(prime))
            {
                return false;
            }
            if (10 % prime == 0)
            {
                return false;
            }
            long n = prime - 1;
            long m = n;
            long p = 2;
            while (p * p <= n)
            {
                if (sieve.is_prime(p) && m % p == 0)
                {
                    if (modpow(10, n / p, prime) == 1)
                    {
                        return false;
                    }
                    while (m % p == 0)
                    {
                        m /= p;
                    }
                }
                p += 1;
            }
            if (m == 1)
            {
                return true;
            }
            return modpow(10, n / m, prime)!= 1;
        }
 
        static long modpow(long base, long exp, long n)
        {
            if (n == 1)
            {
                return 0;
            }
            long result = 1;
            base %= n;
            while (exp > 0)
            {
                if ((exp & 1) == 1)
                {
                    result = (result * base) % n;
                }
                base = (base * base) % n;
                exp >>= 1;
            }
            return result;
        }
    }
 
