using System;

class P09_SortArray
{
    static void SwapPositionsInArray(int[] array, int firstIndex, int secondIndex)
    {
        int tempVar = array[firstIndex];
        array[firstIndex] = array[secondIndex];
        array[secondIndex] = tempVar;
    }

    static int FindBiggestInRange(int[] array, int start, int end)
    {
        int biggest = int.MinValue;

        for (int i = start; i <= end; i++)
        {
            if (array[i] > biggest)
            {
                biggest = array[i];
            }
        }

        return biggest;
    }

    static void PrintArray(int[] array)
    {
        for (int i = 0; i <= array.GetUpperBound(0); i++)
        {
            Console.Write("{0, 4}", array[i]);
        }

        Console.WriteLine();
    }

    static int[] CreateRandomArray(int sizeOfArray)
    {
        int[] array = new int[sizeOfArray];
        Random digit = new Random();

        for (int i = 0; i < sizeOfArray; i++)
        {
            array[i] = digit.Next(-100, 100);
        }

        return array;
    }

    static void Main()
    {
        int[] array = CreateRandomArray(10);
        Console.Write("random array is:");
        PrintArray(array);
        int arrayLastIndex = array.GetUpperBound(0);

        for (int i = 0; i < arrayLastIndex - 1; i++)
        {
            int biggest = FindBiggestInRange(array, 0, arrayLastIndex - i);
            int indexOfBiggest = Array.IndexOf(array, biggest);
            SwapPositionsInArray(array, indexOfBiggest, arrayLastIndex - i);
        }

        Console.Write(" ascending sort:");
        PrintArray(array);

        for (int i = 0; i < arrayLastIndex - 1; i++)
        {
            int biggest = FindBiggestInRange(array, i, arrayLastIndex);
            int indexOfBiggest = Array.IndexOf(array, biggest);
            SwapPositionsInArray(array, indexOfBiggest, i);
        }

        Console.Write("descending sort:");
        PrintArray(array);
    }
}

using OpenTK;
using OpenTK.Graphics;
namespace OpenGLTest
{
    class Graph
    {
        static void Main(string[] args)
        {
            //Create the OpenGL window
            GameWindow window = new GameWindow(640, 480, GraphicsMode.Default, "OpenGL Example");
 
            GL.MatrixMode(MatrixMode.Projection);
            GL.LoadIdentity();
            GL.Ortho(-30.0, 30.0, -30.0, 30.0, -30.0, 30.0);
            GL.MatrixMode(MatrixMode.Modelview);
 
            //Add event handler to render to the window when called
            window.RenderFrame += new RenderFrameEvent(a_RenderFrame);
            //Starts the window's updating/rendering events
            window.Run();
        }
        static void a_RenderFrame(GameWindow sender, RenderFrameEventArgs e)
        {
            GL.ClearColor(0.3f, 0.3f, 0.3f, 0f);
            GL.Clear(ClearBufferMask.ColorBufferBit | ClearBufferMask.DepthBufferBit);
 
            GL.ShadeModel(ShadingModel.Smooth);
 
            GL.LoadIdentity();
            GL.Translate(-15.0f, -15.0f, 0.0f);
 
            GL.Begin(BeginMode.Triangles);
            GL.Color3(1.0f, 0.0f, 0.0f);
            GL.Vertex2(0.0f, 0.0f);
            GL.Color3(0.0f, 1.0f, 0.0f);
            GL.Vertex2(30f, 0.0f);
            GL.Color3(0.0f, 0.0f, 1.0f);
            GL.Vertex2(0.0f, 30.0f);
            GL.End();
            //Swaps the buffers on the window so that what we draw becomes visible
            sender.SwapBuffers();
        }
    }
}

