namespace Parser
{
    class Processor
    {
        static void Main(string[] args)
        {
            var values = new List<int> { 1, 2, 3 };
            var permutations = GetPermutations(values, values.Count);
            foreach (var permutation in permutations)
            {
                Console.WriteLine(string.Join(",", permutation));
            }
            Console.ReadKey();
        }

        static IEnumerable<IEnumerable<T>> GetPermutations<T>(IEnumerable<T> list, int length)
        {
            if (length == 1) return list.Select(t => new T[] { t });
            return GetPermutations(list, length - 1)
               .SelectMany(t => list.Where(e =>!t.Contains(e)),
                    (t1, t2) => t1.Concat(new T[] { t2 }));
        }
    }
}

using Hazelcast.Client.Protocol.Util;
using Hazelcast.IO.Serialization;

namespace Hazelcast.Client.Protocol.Codec
{
    public static class ListLastIndexOfCodec
    {
        public const int RequestMessageType = 0x050200;
        public const int ResponseMessageType = 0x050201;
        private const int RequestInitialFrameSize = ClientMessage.HeaderSize;
        private const int ResponseResponseFieldOffset = ClientMessage.HeaderSize;
        private const int ResponseInitialFrameSize = ResponseResponseFieldOffset + Bits.IntSizeInBytes;

        public static ClientMessage EncodeRequest(string name, IData value)
        {
            var requiredDataSize = RequestInitialFrameSize + ParameterUtil.CalculateDataSize(name) + ParameterUtil.CalculateDataSize(value);
            var clientMessage = ClientMessage.CreateForEncode(requiredDataSize);
            clientMessage.SetMessageType(RequestMessageType);
            clientMessage.SetRetryable(true);

            clientMessage.Set(name);
            clientMessage.Set(value);
            clientMessage.UpdateFrameLength();
            return clientMessage;
        }

        public static int CalculateRequestDataSize(string name, IData value)
        {
            var dataSize = RequestInitialFrameSize;
            dataSize += ParameterUtil.CalculateDataSize(name);
            dataSize += ParameterUtil.CalculateDataSize(value);
            return dataSize;
        }

        public static ResponseParameters DecodeResponse(ClientMessage clientMessage)
        {
            var parameters = new ResponseParameters();
            var initialFrame = clientMessage.GetInitialFrame();
            parameters.Response = clientMessage.GetInt(initialFrame.Content, ResponseResponseFieldOffset);
            return parameters;
        }

        public class ResponseParameters
        {
            public int Response { get; set; }
        }
    }
}

