    public class BookmarkWordTable
    {
        private ExtensionDirection _Extension;
        public string Name { get; set; }
        public int StartIndex { get; set; }
        public int EndIndex { get; set; }

        public ExtensionDirection Extension
        {
            get => _Extension;
            set => _Extension = value;
        }

        public static BookmarkWordTable MappingFromNode(XmlNode node)
        {
            if (node == null)
                return null;

            try
            {
                var result = new BookmarkWordTable
                {
                    Name = GetAttributeValue(node, "Name"),
                    StartIndex = ParseIntAttribute(node, "StartIndex"),
                    EndIndex = ParseIntAttribute(node, "EndIndex")
                };

                string extensionValue = GetAttributeValue(node, "Extension");
                result.Extension = ParseExtensionDirection(extensionValue);

                return result;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error mapping bookmark word table: {ex.Message}");
                return null;
            }
        }

        public XmlNode MappingToNode(XmlDocument document)
        {
            if (document == null)
                throw new ArgumentNullException(nameof(document));

            try
            {
                XmlNode node = document.CreateElement("BookmarkWordTable");

                AddAttribute(document, node, "Name", Name);
                AddAttribute(document, node, "StartIndex", StartIndex.ToString());
                AddAttribute(document, node, "EndIndex", EndIndex.ToString());
                AddAttribute(document, node, "Extension", Extension.ToString());

                return node;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error converting bookmark word table to XML: {ex.Message}");
                return null;
            }
        }

        private static string GetAttributeValue(XmlNode node, string attributeName)
        {
            var attribute = node.Attributes[attributeName];
            return attribute?.Value;
        }

        private static int ParseIntAttribute(XmlNode node, string attributeName)
        {
            string value = GetAttributeValue(node, attributeName);

