using System;
    public class AksTest
    {
        static long[] c = new long[100];
 
        static void Main(string[] args)
        {
        for (int n = 0; n < 10; n++) {
        coef(n);
        Console.Write("(x-1)^" + n + " = ");
        show(n);
        Console.WriteLine("");
    }
       Console.Write("Primes:");
      for (int n = 1; n <= 63; n++)
         if (is_prime(n))
           Console.Write(n + " ");
 
        Console.WriteLine('\n');
            Console.ReadLine();
        }
 
        static void coef(int n)
        {
            int i, j;
 
            if (n < 0 || n > 63) System.Environment.Exit(0);// gracefully deal with range issue
 
            for (c[i = 0] = 1L; i < n; c[0] = -c[0], i++)
                for (c[1 + (j = i)] = 1L; j > 0; j--)
                    c[j] = c[j - 1] - c[j];
        }
 
        static bool is_prime(int n)
        {
            int i;
 
            coef(n);
            c[0] += 1;
            c[i = n] -= 1;
 
            while (i-- != 0 && (c[i] % n) == 0) ;
 
            return i < 0;
        }
 
        static void show(int n)
        {
            do {
                Console.Write("+" + c[n] + "x^" + n);
            }while (n-- != 0);
        }
    }

using System;
 
namespace RosettaVampireNumber
{
    class Timer
    {
        static void Main(string[] args)
        {
            int i, j, n;
            ulong x;
            var f = new ulong[16];
            var bigs = new ulong[] { 16758243290880UL, 24959017348650UL, 14593825548650UL, 0 };
            ulong[] tens = new ulong[20];
            tens[0] = 1;
            for (i = 1; i < 20; i++)
                tens[i] = tens[i - 1] * 10;
 
            for (x = 1, n = 0; n < 25; x++)
            {
                if ((j = fangs(x, f, tens)) == 0) continue;
                Console.Write(++n + ": ");
                show_fangs(x, f, j);
            }
 
            Console.WriteLine();
            for (i = 0; bigs[i] > 0 ; i++)
            {
                if ((j = fangs(bigs[i], f, tens)) > 0)
                    show_fangs(bigs[i], f, j);
                else
                    Console.WriteLine(bigs[i] + " is not vampiric.");
            }
            Console.ReadLine();
        }
 
        private static void show_fangs(ulong x, ulong[] f, int cnt)
        {
            Console.Write(x);
            int i;
            for (i = 0; i < cnt; i++)
                Console.Write(" = " + f[i] + " * " + (x / f[i]));
            Console.WriteLine();
        }
 
        private static int fangs(ulong x, ulong[] f, ulong[] tens)
        {
            int n = 0;
            int nd = ndigits(x);
            if ((nd & 1) > 0) return 0;
            nd /= 2;
 
            ulong lo, hi;
            lo = Math.Max(tens[nd - 1], (x + tens[nd] - 2) / (tens[nd] - 1));
            hi = Math.Min(x / lo, (ulong) Math.Sqrt(x));
 
            ulong a, b, t = dtally(x);
            for (a = lo; a <= hi; a++)
            {
                b = x / a;
                if (a * b == x && ((a % 10) > 0 || (b % 10) > 0) && t == dtally(a) + dtally(b))
                    f[n++] = a;
            }
 
            return n;
        }
 
        private static ulong dtally(ulong x)
        {
            ulong t = 0;
            while (x > 0)
            {
                t += 1UL << (int)((x % 10) * 6);
                x /= 10;
            }
 
            return t;
        }
 
        private static int ndigits(ulong x)
        {
            int n = 0;
            while (x > 0)
            {
                n++;
                x /= 10;
            }
            return n;
        }
    }
}

namespace Appccelerate.StateMachine
{
    using System;
    using Appccelerate.StateMachine.Machine;
    using Appccelerate.StateMachine.Machine.Contexts;

    using FakeItEasy;

    using FluentAssertions;

    using Xunit;

    /// <summary>
    /// Tests that the extensions can interact with the state machine.
    /// </summary>
    public class ExtensionTest
    {
        private readonly StateMachine<States, Events> testee;
        private readonly IExtension<States, Events> extension;
        private readonly OverrideExtension overrideExtension;

        /// <summary>
        /// Initializes a new instance of the <see cref="ExtensionTest"/> class.
        /// </summary>
        public ExtensionTest()
        {
            this.testee = new StateMachine<States, Events>();

            this.extension = A.Fake<IExtension<States, Events>>();
            this.overrideExtension = new OverrideExtension();
            this.testee.AddExtension(this.extension);
            this.testee.AddExtension(this.overrideExtension);
        }

        /// <summary>
        /// When the state machine is initialized then the extensions get notified.
        /// </summary>
        [Fact]
        public void Initialize()
        {
            States initialState = States.A;

            this.testee.Initialize(initialState);

            A.CallTo(() => this.extension.InitializingStateMachine(this.testee, ref initialState))
                .MustHaveHappened();

            A.CallTo(() => this.extension.InitializedStateMachine(this.testee, initialState))
                .MustHaveHappened();
        }

        [Fact]
        public void EnterInitialState()
        {
            const States InitialState = States.A;

            this.testee.Initialize(InitialState);
            this.testee.EnterInitialState();

            A.CallTo(() => this.extension.EnteringInitialState(this.testee, InitialState))
                .MustHaveHappened();

            A.CallTo(() => this.extension.EnteredInitialState(
                    this.testee,
                    InitialState,
                    A<TransitionContext<States, Events>>.That.Matches(context => context.State == null)))
                .MustHaveHappened();
        }

        /// <summary>
        /// An extension can override the state to which the state machine is initialized.
        /// </summary>
        [Fact]
        public void OverrideInitialState()
        {
            this.overrideExtension.OverriddenState = States.B;

            this.testee.Initialize(States.A);
            this.testee.EnterInitialState();

