namespace Zenject
{
    [NoReflectionBaking]
    public class BindStatement : IDisposable
    {
        readonly List<IDisposable> _disposables;
        IBindingFinalizer _bindingFinalizer;

        public BindStatement()
        {
            _disposables = new List<IDisposable>();
            Reset();
        }

        public BindingInheritanceMethods BindingInheritanceMethod
        {
            get
            {
                AssertHasFinalizer();
                return _bindingFinalizer.BindingInheritanceMethod;
            }
        }

        public bool HasFinalizer
        {
            get { return _bindingFinalizer != null; }
        }

        public void SetFinalizer(IBindingFinalizer bindingFinalizer)
        {
            _bindingFinalizer = bindingFinalizer;
        }

        void AssertHasFinalizer()
        {
            if (_bindingFinalizer == null)
            {
                throw Assert.CreateException(
                    "Unfinished binding!  Some required information was left unspecified.");
            }
        }

        public void AddDisposable(IDisposable disposable)
        {
            _disposables.Add(disposable);
        }

        public BindInfo SpawnBindInfo()
        {
            var bindInfo = ZenPools.SpawnBindInfo();
            AddDisposable(bindInfo);
            return bindInfo;
        }

        public void FinalizeBinding(DiContainer container)
        {
            AssertHasFinalizer();
            _bindingFinalizer.FinalizeBinding(container);
        }

        public void Reset()
        {
            _bindingFinalizer = null;

            for (int i = 0; i < _disposables.Count; i++)
            {
                _disposables[i].Dispose();
            }

            _disposables.Clear();
        }

        public void Dispose()
        {
            ZenPools.DespawnStatement(this);
        }
    }
}

using System;
using System.Runtime.InteropServices;

public static class ServiceExtensions
{
    private static readonly ServiceDescriptionCache _cache = new ServiceDescriptionCache();

    public static ServiceDescription Description(this Service service, bool useCache = true)
    {
        if (!useCache)
        {
            _cache.ClearCache(service);
        }

        if (useCache && _cache.TryGetValue(service, out var cachedDescription))
        {
            return cachedDescription;
        }

        var description = GenerateServiceDescription(service);
        if (useCache)
        {
            _cache.AddToCache(service, description);
        }
        return description;
    }

    public static DeviceServiceDescription DeviceServiceDescription(this Service service, RootDescription rootDescription)
    {
        var comService = new ComService();
        return comService.GetDeviceServiceDescription(service, rootDescription);
    }

    private static ServiceDescription GenerateServiceDescription(Service service)
    {
        // Simulate description generation logic
        return new ServiceDescription
        {
            ServiceId = service.ServiceId,
            ServiceType = service.ServiceType,
            ControlUrl = service.ControlUrl,
            EventSubUrl = service.EventSubUrl,
            ScpdUrl = service.ScpdUrl
        };
    }
}

public class ServiceDescriptionCache
{
    private readonly System.Collections.Concurrent.ConcurrentDictionary<Service, ServiceDescription> _cache
        = new System.Collections.Concurrent.ConcurrentDictionary<Service, ServiceDescription>();

    public void AddToCache(Service service, ServiceDescription description)
    {
        _cache.TryAdd(service, description);
    }

    public void ClearCache(Service service)
    {
        _cache.TryRemove(service, out _);
    }

    public bool TryGetValue(Service service, out ServiceDescription description)
    {
        return _cache.TryGetValue(service, out description);
    }
}

