using Microsoft.AspNetCore.Identity;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using System;
using System.Collections.Generic;

public static class IdentityExtensions
{
    public static void UseSelfIdentity(this IServiceCollection services)
    {
        services.AddIdentity<AppUser, AppUserRole>(options =>
        {
            options.User.RequireUniqueEmail = true;
        }).AddDefaultTokenProviders();

        services.AddSingleton<IUserStore<AppUser>>(provider => new UserStore());
        services.AddSingleton<IRoleStore<AppUserRole>>(provider => new RoleStore());
        services.AddSingleton<IUserValidator<AppUser>>(provider => new AppUserValidator());
        services.AddSingleton<IPasswordValidator<AppUser>>(provider => new AppUserPasswordValidator());
        services.AddSingleton<ILookupNormalizer>(provider => new KeyNormalizer());
        services.AddSingleton<IdentityErrorDescriber>();

        services.AddSingleton(provider => CreateUserManager(provider));
    }

    private static UserManager<AppUser> CreateUserManager(IServiceProvider provider)
    {
        var store = provider.GetService<IUserStore<AppUser>>();
        var optionsAccessor = new OptionsWrapper<IdentityOptions>(new IdentityOptions());
        var passwordHasher = new PasswordHasher<AppUser>();
        var userValidators = new List<IUserValidator<AppUser>> { provider.GetService<IUserValidator<AppUser>>() };
        var passwordValidators = new List<IPasswordValidator<AppUser>> { provider.GetService<IPasswordValidator<AppUser>>() };
        var keyNormalizer = provider.GetService<ILookupNormalizer>();
        var errors = new IdentityErrorDescriber();
        var logger = new Logger<UserManager<AppUser>>(new LoggerFactory());

        return new UserManager<AppUser>(store, optionsAccessor, passwordHasher, userValidators, passwordValidators, keyNormalizer, errors, provider, logger);
    }
}

