    public class ThriftConnection : IConnection, IDisposable
    {
        private readonly ConcurrentDictionary<Uri, ConcurrentQueue<Rest.Client>> _clients =
            new ConcurrentDictionary<Uri, ConcurrentQueue<Rest.Client>>();
        private readonly Semaphore _resourceLock;
        private readonly int _timeout;
        private readonly int _poolSize;
        private bool _disposed;
        private readonly IConnectionConfigurationValues _connectionSettings;

        public ThriftConnection(IConnectionConfigurationValues connectionSettings)
        {
            this._connectionSettings = connectionSettings;
            this._timeout = connectionSettings.Timeout;
            var connectionPool = this._connectionSettings.ConnectionPool;
            var maximumConnections = Math.Max(1, connectionSettings.MaximumAsyncConnections);
            var maximumUrls = connectionPool.MaxRetries + 1;
            this._poolSize = maximumConnections;
            this._resourceLock = new Semaphore(_poolSize, _poolSize);

            int seed; int initialSeed = 0; bool shouldPingHint;

            for (var i = 0; i < maximumUrls; i++)
            {
                var uri = connectionPool.GetNext(initialSeed, out seed, out shouldPingHint);
                var queue = new ConcurrentQueue<Rest.Client>();
                for (var c = 0; c < maximumConnections; c++)
                {
                    var host = uri.Host;
                    var port = uri.Port;
                    var tsocket = new TSocket(host, port);
                    var transport = new TBufferedTransport(tsocket, 1024);
                    var protocol = new TBinaryProtocol(transport);
                    var client = new Rest.Client(protocol);
                    tsocket.Timeout = this._connectionSettings.Timeout;
                    tsocket.TcpClient.SendTimeout = this._connectionSettings.Timeout;
                    tsocket.TcpClient.ReceiveTimeout = this._connectionSettings.Timeout;
                    //tsocket.TcpClient.NoDelay = true;

using System;

public class Nth
{
    public static string OrdinalAbbrev(int n)
    {
        string ans = "th"; //most of the time it should be "th"
        if (n % 100 / 10 == 1) return ans; //teens are all "th"
        switch (n % 10)
        {
            case 1:
                ans = "st";
                break;
            case 2:
                ans = "nd";
                break;
            case 3:
                ans = "rd";
                break;
        }
        return ans;
    }

    public static void Main(string[] args)
    {
        for (int i = 0; i <= 25; i++)
        {
            Console.Write(i + OrdinalAbbrev(i) + " ");
        }
        Console.WriteLine();
        for (int i = 250; i <= 265; i++)
        {
            Console.Write(i + OrdinalAbbrev(i) + " ");
        }
        Console.WriteLine();
        for (int i = 1000; i <= 1025; i++)
        {
            Console.Write(i + OrdinalAbbrev(i) + " ");
        }
    }
}

using System;
class Matrix {
 
  static bool sameDigits(int n, int b) {
    int f = n % b;
    while ((n /= b) > 0) if (n % b != f) return false;
    return true;
  }
 
  static bool isBrazilian(int n) {
    if (n < 7) return false;
    if (n % 2 == 0) return true;
    for (int b = 2; b < n - 1; b++) if (sameDigits(n, b)) return true;
    return false;
  }
 
  static bool isPrime(int n) {
    if (n < 2) return false;
    if (n % 2 == 0) return n == 2;
    if (n % 3 == 0) return n == 3;
    int d = 5;
    while (d * d <= n) {
      if (n % d == 0) return false; d += 2;
      if (n % d == 0) return false; d += 4;
    }
    return true;
  }
 
  static void Main(string[] args) {
    foreach (string kind in ",odd ,prime ".Split(',')) {
      bool quiet = false; int BigLim = 99999, limit = 20;
      Console.WriteLine("First {0} {1}Brazilian numbers:", limit, kind);
      int c = 0, n = 7;
      while (c < BigLim) {
        if (isBrazilian(n)) {
          if (!quiet) Console.Write("{0:n0} ", n);
          if (++c == limit) { Console.Write("\n\n"); quiet = true; }
        }
        if (quiet && kind != "") continue;
        switch (kind) {
          case "": n++; break;
          case "odd ": n += 2; break;
          case "prime ":
            while (true) {
              n += 2;
              if (isPrime(n)) break;
            } break;
        }
      }
      if (kind == "") Console.WriteLine("The {0:n0}th Brazilian number is: {1:n0}\n", BigLim + 1, n);
    }
  }
}

using System;
using System.Collections.Generic;
 
public class Utils
{
    public static IEnumerable<int[]> Combinations(int m, int n)
    {
            int[] result = new int[m];
            Stack<int> stack = new Stack<int>();
            stack.Push(0);
 
            while (stack.Count > 0)
           {
                int index = stack.Count - 1;
                int value = stack.Pop();
 
                while (value < n)
               {
                    result[index++] = ++value;
                    stack.Push(value);
 
                    if (index == m)
                    {
                        yield return result;
                        break;
                    }
                }
            }
    }
 
    static void Main()
    {
        foreach (int[] c in Combinations(3, 5))
        {
            Console.WriteLine(string.Join(",", c));
            Console.WriteLine();
        }
    }
}

