public class AircraftIdleManager
{
    private readonly Actor self;
    private readonly AircraftInfo aircraftInfo;
    private readonly World world;

    public AircraftIdleManager(Actor actor, AircraftInfo info, World gameWorld)
    {
        self = actor;
        aircraftInfo = info;
        world = gameWorld;
    }

    public void TickIdle()
    {
        if (ShouldReturnToBase())
        {
            ReturnToNearestAirfield();
        }
        else if (ShouldCircleAlternativeLocation())
        {
            NavigateToAlternativeLocation();
        }
        else
        {
            HandleUnitStranded();
        }
    }

    private bool ShouldReturnToBase()
    {
        return aircraftInfo.CanRearm && IsLowOnSupplies();
    }

    private bool ShouldCircleAlternativeLocation()
    {
        return !CanLandAtAlliedAirfield() && HasAlternativeLocations();
    }

    private void ReturnToNearestAirfield()
    {
        var availableAirfields = ChooseAirfield();

        if (availableAirfields != null)
        {
            self.QueueActivity(new ReturnToBaseActivity(availableAirfields));
        }
        else
        {
            HandleNoAirfieldAvailable();
        }
    }

    private Actor ChooseAirfield()
    {
        return world.Actors
            .Where(a => IsValidAirfield(a))
            .OrderBy(a => (a.Location - self.Location).Length)
            .FirstOrDefault();
    }

    private bool IsValidAirfield(Actor airfield)
    {
        return airfield.Owner.Stances[self.Owner] == Stance.Ally &&
               airfield.HasTrait<Buildable>() &&
               airfield.Trait<AirfieldInfo>().CanLand;
    }

    private void NavigateToAlternativeLocation()
    {
        var alternativeLocation = FindAlternativeCirclingLocation();

        if (alternativeLocation != null)
        {
            self.QueueActivity(new CircleAroundLocationActivity(alternativeLocation));
        }
    }

    private bool IsLowOnSupplies()
    {
        var ammoTrait = self.Trait<AmmoSupplyTrait>();
        return ammoTrait.CurrentAmmo < ammoTrait.MaxAmmo * 0.3;
    }

    private bool CanLandAtAlliedAirfield()
    {
        return world.Actors.Any(a => IsValidAirfield(a));
    }

    private bool HasAlternativeLocations()
    {
        return FindAlternativeCirclingLocation() != null;
    }

    private CPos? FindAlternativeCirclingLocation()
    {
        // Implement logic to find safe alternative location
        return null;
    }

using UnityEngine;
using UnityEngine.UI;
using System.Collections;

public class HealthTracker : MonoBehaviour
{
    [Header("Health Configuration")]
    public float maxHealth = 100f;
    public float currentHealth;
    public float savedHealth;
    public bool dead = false;
    public bool isPlayer = false;

    [Header("UI Components")]
    public RectTransform healthBar;
    public Image healthBarFill;
    public GameObject deathEffect;

    [Header("Animation Settings")]
    public float smoothSpeed = 2f;
    private float displayHealth;

    [Header("Audio & Effects")]
    public AudioClip damageSound;
    public AudioClip deathSound;

    private GameManager gameManager;
    private AudioSource audioSource;

    private void Awake()
    {
        currentHealth = maxHealth;
        displayHealth = maxHealth;
        gameManager = FindObjectOfType<GameManager>();
        audioSource = GetComponent<AudioSource>();
    }

    private void Update()
    {
        UpdateHealthBar();
        CheckDeathCondition();
    }

    private void UpdateHealthBar()
    {
        displayHealth = Mathf.Lerp(displayHealth, currentHealth, Time.deltaTime * smoothSpeed);
        float healthPercentage = displayHealth / maxHealth;
        healthBar.localScale = new Vector3(healthPercentage, 1f, 1f);

        healthBarFill.color = Color.Lerp(Color.red, Color.green, healthPercentage);
    }

    public void DealDamage(float damageAmount)
    {
        if (dead) return;

        currentHealth = Mathf.Max(currentHealth - damageAmount, 0);
        PlayDamageSound();
    }

    private void PlayDamageSound()
    {
        if (audioSource && damageSound)
        {
            audioSource.PlayOneShot(damageSound);
        }
    }

    private void CheckDeathCondition()
    {
        if (currentHealth <= 0 && !dead)
        {
            dead = true;
            HandleDeath();
        }
    }

    private void HandleDeath()
    {
        if (isPlayer)
        {
            gameManager.GameOver();
        }

        SpawnDeathEffect();
        PlayDeathSound();
        DisableEntity();
    }

    private void SpawnDeathEffect()
    {
        if (deathEffect)
        {
            Instantiate(deathEffect, transform.position, Quaternion.identity);
        }
    }

    private void PlayDeathSound()
    {
        if (audioSource && deathSound)
        {
            audioSource.PlayOneShot(deathSound);
        }
    }

    private void DisableEntity()
    {
        GetComponent<Collider>().enabled = false;
        GetComponent<Renderer>().enabled = false;
    }

using System;
using System.Collections.Generic;
using System.Runtime.CompilerServices;

public class WordSearchIndex
{
    public string[] Words { get; set; }

    public WordSearchIndex(string[] words)
    {
        Words = words;
    }
}

public class IndexCache
{
    private readonly Dictionary<string, WeakReference<WordSearchIndex>> _cache;

    public IndexCache()
    {
        _cache = new Dictionary<string, WeakReference<WordSearchIndex>>();
    }

    public void AddIndex(string filename, WordSearchIndex index)
    {
        if (string.IsNullOrEmpty(filename) || index == null)
            throw new ArgumentNullException("Filename and index cannot be null.");

        var weakRef = new WeakReference<WordSearchIndex>(index);
        _cache[filename] = weakRef;
    }

    public WordSearchIndex GetIndex(string filename)
    {
        if (string.IsNullOrEmpty(filename))
            throw new ArgumentNullException("Filename cannot be null.");

        if (_cache.TryGetValue(filename, out WeakReference<WordSearchIndex> weakRef))
        {
            if (weakRef.TryGetTarget(out WordSearchIndex index))
            {
                return index;
            }
            else
            {
                // Remove the entry if the weak reference has been collected
                _cache.Remove(filename);
            }
        }
        return null;
    }

    public void CleanUp()
    {
        // Optional method to clear out collected indices
        var keysToRemove = new List<string>();

        foreach (var kvp in _cache)
        {
            if (!kvp.Value.TryGetTarget(out _))
            {
                keysToRemove.Add(kvp.Key);
            }
        }

        foreach (var key in keysToRemove)
        {
            _cache.Remove(key);
        }
    }
}

// Example Usage
public class Product
{
    public static void Main()
    {
        IndexCache indexCache = new IndexCache();

        string filename = "example.txt";
        var index = new WordSearchIndex(new[] { "word1", "word2", "word3" });

        indexCache.AddIndex(filename, index);
        Console.WriteLine("Index added for file: " + filename);

        var retrievedIndex = indexCache.GetIndex(filename);
        Console.WriteLine("Retrieved Index: " + (retrievedIndex != null ? string.Join(", ", retrievedIndex.Words) : "null"));

        // Simulating GC to collect unreferenced WordSearchIndex
        index = null;
        GC.Collect();
        GC.WaitForPendingFinalizers();

        retrievedIndex = indexCache.GetIndex(filename);

using System;
using Windows.UI.Xaml;
using Microsoft.VisualStudio.TestTools.UnitTesting;

public static class TestUtilities
{
    public static void AssertThrowsInvalidOperationException(Action action)
    {
        Assert.ThrowsException<InvalidOperationException>(action);
    }

    public static void AssertThrowsArgumentException(Action action)
    {
        Assert.ThrowsException<ArgumentException>(action);
    }

    public static void AssertDetached(StubBehavior behavior)
    {
        Assert.AreEqual(1, behavior.DetachCount, "Detach count should be 1.");
        Assert.IsNull(behavior.AssociatedObject, "Associated object should be null.");
    }

    public static void AssertNotDetached(StubBehavior behavior)
    {
        Assert.AreEqual(0, behavior.DetachCount, "Detach count should be 0.");
    }

    public static void AssertAttached(StubBehavior behavior, DependencyObject associatedObject)
    {
        Assert.AreEqual(1, behavior.AttachCount, "Attach count should be 1.");
        Assert.AreSame(associatedObject, behavior.AssociatedObject, "Associated object should match.");
    }

    public static void AssertNotAttached(StubBehavior behavior)
    {
        Assert.AreEqual(0, behavior.AttachCount, "Attach count should be 0.");
        Assert.IsNull(behavior.AssociatedObject, "Associated object should be null.");
    }
}

public class StubBehavior
{
    public int AttachCount { get; private set; }
    public int DetachCount { get; private set; }
    public DependencyObject AssociatedObject { get; private set; }

    public void Attach(DependencyObject associatedObject)
    {
        if (associatedObject == null)
        {
            throw new ArgumentNullException(nameof(associatedObject));
        }

        if (this.AssociatedObject != null)
        {
            throw new InvalidOperationException("Behavior is already attached.");
        }

        this.AssociatedObject = associatedObject;
        AttachCount++;
    }

    public void Detach()
    {
        if (this.AssociatedObject == null)
        {
            throw new InvalidOperationException("Behavior is not attached.");
        }

        this.AssociatedObject = null;
        DetachCount++;
    }
}

