namespace TextProc3
{
    class Logger
    {
        static void Main(string[] args)
        {
            string line;
            int count = 0, maxcount = 0;
            List<string> times = new List<string>();
            System.IO.StreamReader file = new StreamReader("mlijobs.txt");
            while ((line = file.ReadLine()) != null)
            {
                string[] lineelements = line.Split(' ');
                switch (lineelements[1])
                {
                    case "IN":
                        count--;
                        break;
                    case "OUT":
                        count++;
                        if (count > maxcount)
                        {
                            maxcount = count;
                            times.Clear();
                            times.Add(lineelements[3]);
                        }else if(count == maxcount){
                            times.Add(lineelements[3]);
                        }
                        break;
                }
            }
            file.Close();
            Console.WriteLine(maxcount);
            foreach (string time in times)
            {
                Console.WriteLine(time);
            }
        }
    }
}

using System;
using System.Threading;
using ChakraCore.NET;

public class ContextSwitchService : IDisposable
{
    private JavaScriptContext context;
    private EventWaitHandle handle;
    private bool disposed = false;

    public ContextSwitchService()
    {
        handle = new EventWaitHandle(true, EventResetMode.ManualReset);
        context = JavaScriptContext.Create(); // Assuming this initializes a new JS context
    }

    public void Enter()
    {
        if (!handle.WaitOne(0))
        {
            handle.WaitOne(); // Wait until it's safe to enter the context
        }
        handle.Reset(); // Indicate we're entering a critical section
    }

    public void Leave()
    {
        handle.Set(); // Indicate context is now free
    }

    public void With(Action action)
    {
        if (action == null)
            throw new ArgumentNullException(nameof(action));

        try
        {
            Enter();
            action();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error executing action: {ex.Message}");
        }
        finally
        {
            Leave();
        }
    }

    public T With<T>(Func<T> func)
    {
        if (func == null)
            throw new ArgumentNullException(nameof(func));

        T result = default;

        try
        {
            Enter();
            result = func();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error executing function: {ex.Message}");
        }
        finally
        {
            Leave();
        }

        return result;
    }

    public void RunScript(string script)
    {
        try
        {
            Enter();
            JavaScriptContext.RunScript(script); // Assuming this method runs the script in the context
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error running script: {ex.Message}");
        }
        finally
        {
            Leave();
        }
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    protected virtual void Dispose(bool disposing)
    {
        if (disposed)
            return;

        if (disposing)
        {
            handle?.Close();
            context?.Dispose(); // Assuming the context has a Dispose method
        }

        disposed = true;
    }

    ~ContextSwitchService()
    {
        Dispose(false);
    }
}

