using System.Linq;
 
public class Sundaram
{
    public static void Main()
    {
        var primes = SundaramSieve(100);
        Console.WriteLine(string.Join(", ", primes));
        Console.WriteLine($"\nThe {1_000_000}th sundaram prime is {SundaramSieve(1_000_000)[1_000_000 - 1]}");
    }
 
    public static IEnumerable<int> SundaramSieve(int upto)
    {
        var n = (int)(2.4 * upto * Math.Log(upto)) / 2;
        var k = (n - 3) / 2 + 1;
        var bools = new bool[k];
        for (var i = 0; i <= (int)Math.Sqrt(n) - 3 / 2 + 1; i++)
        {
            var p = 2 * i + 3;
            var s = (p * p - 3) / 2;
            for (var j = s; j <= k; j += p)
            {
                bools[j] = false;
            }
        }
        return bools.Select((b, i) => b? (i + 1) * 2 + 1 : 0).Where(x => x!= 0);
    }
}

