namespace Order
{
    class Library
    {
        static void Main(string[] args)
        {
            var lstA = new List<Dictionary<string, object>>()
            {
                new Dictionary<string, object>() { { "age", 27 }, { "name", "Jonah" } },
                new Dictionary<string, object>() { { "age", 18 }, { "name", "Alan" } },
                new Dictionary<string, object>() { { "age", 28 }, { "name", "Glory" } },
                new Dictionary<string, object>() { { "age", 18 }, { "name", "Popeye" } },
                new Dictionary<string, object>() { { "age", 28 }, { "name", "Alan" } }
            };
            var lstB = new List<Dictionary<string, object>>()
            {
                new Dictionary<string, object>() { { "character", "Jonah" }, { "nemesis", "Whales" } },
                new Dictionary<string, object>() { { "character", "Jonah" }, { "nemesis", "Spiders" } },
                new Dictionary<string, object>() { { "character", "Alan" }, { "nemesis", "Ghosts" } },
                new Dictionary<string, object>() { { "character", "Alan" }, { "nemesis", "Zombies" } },
                new Dictionary<string, object>() { { "character", "Glory" }, { "nemesis", "Buffy" } },
                new Dictionary<string, object>() { { "character", "Bob" }, { "nemesis", "foo" } }
            };
 
            var result = hashJoin(lstA, lstB, "name=character");
 
            foreach (var item in result)
            {
                foreach (var key in item.Keys)
                {
                    Console.WriteLine(key + " : " + item[key]);
                }
                Console.WriteLine();
            }
 
            Console.ReadLine();
        }
 
        static List<Dictionary<string, object>> hashJoin(List<Dictionary<string, object>> tblA, List<Dictionary<string, object>> tblB, string strJoin)
        {
            var jA = strJoin.Split('=')[0];
            var jB = strJoin.Split('=')[1];
            var M = tblB.GroupBy(x => x[jB]).ToDictionary(x => x.Key, x => x.ToList());
 
            return tblA.SelectMany(x =>
            {
                List<Dictionary<string, object>> match;
                if (M.TryGetValue(x[jA], out match))
                {
                    return match.Select(row => dictConcat(x, row));
                }
                return new List<Dictionary<string, object>>();
            }).ToList();
        }

