namespace SimulationFramework
{
    [StorableClass]
    public abstract class SimulationEnvelope
    {
        private List<double> rawOutput;
        private double fitnessScore;

        public SimulationEnvelope()
        {
            this.rawOutput = new List<double>();
            this.fitnessScore = 0.0;
        }

        public SimulationEnvelope(List<double> output, double score)
        {
            this.rawOutput = new List<double>(output);
            this.fitnessScore = score;
        }

        [Storable]
        public List<double> RawOutput
        {
            get { return rawOutput; }
            set { rawOutput = value ?? new List<double>(); }
        }

        [Storable]
        public double FitnessScore
        {
            get { return fitnessScore; }
            set { fitnessScore = value; }
        }

        public void AddRawOutput(double value)
        {
            rawOutput.Add(value);
        }

        public void ClearRawOutput()
        {
            rawOutput.Clear();
        }

        public void UpdateFitnessScore(double score)
        {
            fitnessScore = score;
        }

        public double GetRawOutput(int index)
        {
            if (index < 0 || index >= rawOutput.Count)
                throw new IndexOutOfRangeException("Invalid index for RawOutput.");
            return rawOutput[index];
        }

        public int GetRawOutputCount()
        {
            return rawOutput.Count;
        }

        public void CloneFrom(SimulationEnvelope other)
        {
            if (other == null) throw new ArgumentNullException(nameof(other));
            this.rawOutput = new List<double>(other.rawOutput);
            this.fitnessScore = other.fitnessScore;
        }

        public abstract void DeserializeData(string serializedData);
        public abstract string SerializeData();

        protected virtual void OnDeserializationComplete()
        {
            // Additional logic after deserialization can be implemented by subclasses
        }

        protected virtual void OnSerializationComplete()
        {
            // Additional logic after serialization can be implemented by subclasses
        }
    }

    public class ConcreteSimulationEnvelope : SimulationEnvelope
    {
        public ConcreteSimulationEnvelope() : base() { }

