using System;
using System.Data.Linq.Mapping;
using NUnit.Framework;

namespace PeopleDatabase
{
    [Table(Name = "people")]
    public class BadPerson
    {
        public string FirstName { get; set; }
        public string LastName { get; set; }
    }

    [Table(Name = "people")]
    public class Person
    {
        [Column(Name = "first_name")]
        public string FirstName { get; set; }

        [Column(Name = "last_name")]
        public string LastName { get; set; }
    }

    [TestFixture]
    public class PersonTests
    {
        private Person _person;
        private BadPerson _badPerson;

        [SetUp]
        public void Setup()
        {
            _person = new Person
            {
                FirstName = "John",
                LastName = "Doe"
            };

            _badPerson = new BadPerson
            {
                FirstName = "Jane",
                LastName = "Smith"
            };
        }

        [Test]
        public void PersonMapping_ValidAttributes_ShouldReturnCorrectValues()
        {
            Assert.AreEqual("John", _person.FirstName);
            Assert.AreEqual("Doe", _person.LastName);
        }

        [Test]
        public void BadPersonMapping_NoAttributes_ShouldReturnDefaultValues()
        {
            Assert.AreEqual("Jane", _badPerson.FirstName);
            Assert.AreEqual("Smith", _badPerson.LastName);
        }

        [Test]
        public void PersonMapping_ShouldHaveColumnAttributes()
        {
            var attributes = (ColumnAttribute[])typeof(Person)
                .GetProperty("FirstName")
                .GetCustomAttributes(typeof(ColumnAttribute), false);

            Assert.IsNotEmpty(attributes);
            Assert.AreEqual("first_name", attributes[0].Name);
        }

        [Test]
        public void BadPersonMapping_ShouldNotHaveColumnAttributes()
        {
            var attributes = (ColumnAttribute[])typeof(BadPerson)
                .GetProperty("FirstName")
                .GetCustomAttributes(typeof(ColumnAttribute), false);

            Assert.IsEmpty(attributes);
        }
    }
}

using System;
