public class PermissionSetEnumerator : IEnumerator
{
    private PermissionSetEnumeratorInternal m_enumerator;

    public PermissionSetEnumerator(PermissionSet permSet)
    {
        m_enumerator = new PermissionSetEnumeratorInternal(permSet);
    }

    public object Current => m_enumerator.Current;

    public bool MoveNext()
    {
        return m_enumerator.MoveNext();
    }

    public void Reset()
    {
        m_enumerator.Reset();
    }

    public int GetCurrentIndex()
    {
        return m_enumerator.GetCurrentIndex();
    }
}

internal struct PermissionSetEnumeratorInternal
{
    private TokenBasedSetEnumerator enm;
    private PermissionSet m_permSet;

    public PermissionSetEnumeratorInternal(PermissionSet permSet)
    {
        m_permSet = permSet;
        enm = new TokenBasedSetEnumerator(permSet.GetTokenBasedSet());
    }

    public object Current
    {
        get
        {
            if (enm.Current is IPermission permission)
            {
                return permission;
            }
            throw new InvalidOperationException("Current item is not a valid permission.");
        }
    }

    public bool MoveNext()
    {
        while (enm.MoveNext())
        {
            if (enm.Current is IPermission)
            {
                return true;
            }
        }
        return false;
    }

    public void Reset()
    {
        enm.Reset();
    }

    public int GetCurrentIndex()
    {
        return enm.Index;
    }
}

internal class TokenBasedSetEnumerator
{
    private TokenBasedSet m_set;
    private int m_index;

    public TokenBasedSetEnumerator(TokenBasedSet set)
    {
        m_set = set;
        m_index = -1;
    }

    public object Current => m_set[m_index];

    public bool MoveNext()
    {
        m_index++;
        return m_index < m_set.Count;
    }

    public void Reset()
    {
        m_index = -1;
    }

    public int Index => m_index;
}

internal class TokenBasedSet
{
    private object[] m_items;

    public TokenBasedSet(object[] items)
    {
        m_items = items;
    }

    public object this[int index] => m_items[index];

    public int Count => m_items.Length;
}

