namespace MetadataApp
{
    public class MetadataForm : Form
    {
        private TabControl tabControl;
        private IMetadata _metadata;
        private List<IMetadataProvider> _providers;

        public MetadataForm(Stream xmlStream)
        {
            InitializeComponent();
            // Read metadata from XML stream using a designated metadata reader
            MetadataReader reader = new MetadataReader();
            _metadata = reader.Read(xmlStream);
            // Retrieve metadata providers from the metadata object
            _providers = new List<IMetadataProvider>(_metadata.GetProviders());
            this.Load += MetadataForm_Load;
        }

        private void InitializeComponent()
        {
            this.tabControl = new TabControl();
            this.tabControl.Dock = DockStyle.Fill;
            this.Text = "Metadata Editor";
            this.ClientSize = new Size(600, 400);
            this.Controls.Add(this.tabControl);
        }

        private void MetadataForm_Load(object sender, EventArgs e)
        {
            // Dynamically add tab pages for each metadata provider that supports a property page
            foreach (IMetadataProvider provider in _providers)
            {
                if (provider is IPropertyPage propertyPageProvider)
                {
                    Control pageControl = propertyPageProvider.CreatePropertyPage();
                    // If the control expects an external metadata object, provide it
                    if (pageControl is IMetadataReceiver receiver)
                    {
                        receiver.SetMetadata(_metadata);
                    }
                    TabPage tabPage = new TabPage(provider.ProviderName);
                    pageControl.Dock = DockStyle.Fill;
                    tabPage.Controls.Add(pageControl);
                    tabControl.TabPages.Add(tabPage);
                }
            }
        }

        // Exposes a property that outputs the current metadata as an XML stream
        public Stream MetadataStream
        {
            get
            {
                MemoryStream stream = new MemoryStream();
                MetadataWriter writer = new MetadataWriter();
                writer.Write(_metadata, stream);
                stream.Position = 0;
                return stream;

