public class Wolf { }
public class Lion { }
public class Grass { }
public class Boar { }
public class Zombie { }

public class EngineExtend
{
    private Engine engine;
    private string[] commandWords;
    public EngineExtend(Engine engine)
    {
        this.engine = engine;
    }

    public void ExecuteBirthCommand(string command)
    {
        commandWords = command.Split(' ');
        string organismType = commandWords[1];
        string name = commandWords[2];
        Point location = Point.Parse(commandWords[3]);

        switch (organismType.ToLower())
        {
            case "wolf":
                Wolf newWolf = new Wolf();
                engine.AddOrganism(newWolf);
                break;
            case "lion":
                Lion newLion = new Lion();
                engine.AddOrganism(newLion);
                break;
            case "grass":
                Grass newGrass = new Grass();
                engine.AddOrganism(newGrass);
                break;
            case "boar":
                Boar newBoar = new Boar();
                engine.AddOrganism(newBoar);
                break;
            case "zombie":
                Zombie newZombie = new Zombie();
                engine.AddOrganism(newZombie);
                break;
            default:
                Console.WriteLine("Unknown organism type: " + organismType);
                break;
        }
    }
}

