    // TestSceneLoader manages the process of loading content and transitions.
    public class TestSceneLoader : LoadingScene
    {
        private IFont _font;
        private TestScene _targetScene;

        public TestSceneLoader(TestScene targetScene)
            : base("TestSceneLoader")
        {
            _targetScene = targetScene;
        }

        // LoadContent is responsible for resource initialization.
        public override void LoadContent()
        {
            base.LoadContent();
            // Create the font resource for text rendering.
            _font = Content.Load<IFont>("Fonts/LoaderFont");
        }

        // OnCompleted is triggered when all loading steps are finished.
        protected override void OnCompleted()
        {
            base.OnCompleted();
            // Define the sliding transition effect for a smooth scene change.
            SlideTransition transition = new SlideTransition(Vectors2.Right, 0.5f);
            SceneManager.TransitionTo(_targetScene, transition);
        }

        // Render the loading progress and status details.
        public override void Render(GraphicsDevice graphics, GameTime gameTime)
        {
            // Clear the screen with a defined background color.
            graphics.Clear(Color.CornflowerBlue);

            // Build loading progress information.
            StringBuilder progressText = new StringBuilder();
            progressText.AppendLine("Loading Assets...");
            progressText.AppendFormat("Completed: {0}/{1}", CompletedElements, TotalElements);
            progressText.AppendLine();
            progressText.AppendFormat("Currently loading: {0}", CurrentElement != null ? CurrentElement.Name : "None");

            // Draw the progress text using the loaded font.
            if (_font != null)
            {
                graphics.DrawString(_font, progressText.ToString(), new Vector2(50, 50), Color.White);
            }

            base.Render(graphics, gameTime);
        }
    }

