using System.Collections.Immutable;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.LanguageServices;
using Microsoft.CodeAnalysis.Shared.Extensions;

public class OperatorSymbolReferenceFinder
{
    private readonly ISyntaxFactsService _syntaxFacts;

    public OperatorSymbolReferenceFinder(ISyntaxFactsService syntaxFacts)
    {
        _syntaxFacts = syntaxFacts;
    }

    public async Task<ImmutableArray<Location>> FindReferencesAsync(
        IMethodSymbol operatorSymbol, Project project, CancellationToken cancellationToken)
    {
        if (!CanFind(operatorSymbol))
            return ImmutableArray<Location>.Empty;

        var documents = await DetermineDocumentsToSearchAsync(project, cancellationToken).ConfigureAwait(false);
        var references = ImmutableArray.CreateBuilder<Location>();

        foreach (var document in documents)
        {
            var documentReferences = await FindReferencesInDocumentAsync(document, operatorSymbol, cancellationToken).ConfigureAwait(false);
            references.AddRange(documentReferences);
        }

        return references.ToImmutable();
    }

    private bool CanFind(IMethodSymbol symbol)
    {
        return symbol.MethodKind == MethodKind.UserDefinedOperator;
    }

    private async Task<ImmutableArray<Document>> DetermineDocumentsToSearchAsync(Project project, CancellationToken cancellationToken)
    {
        // Simplified logic to return all documents in the project
        return await Task.FromResult(project.Documents.ToImmutableArray());
    }

    private async Task<ImmutableArray<Location>> FindReferencesInDocumentAsync(
        Document document, IMethodSymbol operatorSymbol, CancellationToken cancellationToken)
    {
        var root = await document.GetSyntaxRootAsync(cancellationToken).ConfigureAwait(false);
        var semanticModel = await document.GetSemanticModelAsync(cancellationToken).ConfigureAwait(false);
        var references = ImmutableArray.CreateBuilder<Location>();

        foreach (var token in root.DescendantTokens())
        {
            if (IsPotentialReference(token, operatorSymbol, semanticModel))
            {
                references.Add(token.GetLocation());
            }
        }

        return references.ToImmutable();
    }

    private bool IsPotentialReference(SyntaxToken token, IMethodSymbol operatorSymbol, SemanticModel semanticModel)
    {
        if (!_syntaxFacts.IsOperator(token))
            return false;

        var symbolInfo = semanticModel.GetSymbolInfo(token.Parent);

