    public class DeleteEntry
    {
        private readonly PwEntry _entry;
        private string _statusMessage;

        public DeleteEntry(PwEntry entry)
        {
            _entry = entry ?? throw new ArgumentNullException(nameof(entry));
        }

        public void DeleteEntryConfirmed()
        {
            AlertDialog.Builder dialog = new AlertDialog.Builder(Application.Context);
            dialog.SetTitle("Delete Entry");
            dialog.SetMessage($"Are you sure you want to delete the entry '{_entry.Strings.Get("Title")}'?");
            dialog.SetPositiveButton("Yes", (sender, e) => ConfirmDelete());
            dialog.SetNegativeButton("No", (sender, e) => UpdateStatusMessage("Deletion canceled."));
            dialog.Show();
        }

        private void ConfirmDelete()
        {
            if (CanRecycle())
            {
                RecycleEntry();
            }
            else
            {
                PerformDelete();
            }
        }

        private bool CanRecycle()
        {
            // Logic to determine if recycling is supported
            return true; // Assuming it is for this example
        }

        private void RecycleEntry()
        {
            // Logic to mark entry as deleted but keep it in storage
            _statusMessage = $"{_entry.Strings.Get("Title")} has been recycled.";
            UpdateDatabase();
            ShowStatus();
        }

        private void PerformDelete()
        {
            // Logic to perform the actual deletion from the database
            UpdateDatabase(true);
            _statusMessage = $"{_entry.Strings.Get("Title")} has been permanently deleted.";
            ShowStatus();
        }

        private void UpdateDatabase(bool isPermanent = false)
        {
            // Database update logic here
            if (isPermanent)
            {
                // Permanently delete logic
                Database.Global.DeleteEntry(_entry);
            }
            else
            {
                // Recycle entry logic
                Database.Global.RecycleEntry(_entry);
            }
        }

        private void ShowStatus()
        {
            // Displaying the status message to the user
            Toast.MakeText(Application.Context, _statusMessage, ToastLength.Long).Show();
        }

