        private void UpdateRelatedGroups()
        {

using System;

namespace Appccelerate.StateMachine.Events
{
    /// <summary>
    /// Event arguments for capturing exceptions during state machine transitions
    /// </summary>
    /// <typeparam name="TState">The type of state in the state machine</typeparam>
    /// <typeparam name="TEvent">The type of events in the state machine</typeparam>
    public class TransitionExceptionEventArgs<TState, TEvent> : EventArgs
        where TState : IComparable
        where TEvent : IComparable
    {
        /// <summary>
        /// Initializes a new instance of the TransitionExceptionEventArgs class
        /// </summary>
        /// <param name="context">The transition context containing state and event information</param>
        /// <param name="exception">The exception that occurred during the transition</param>
        public TransitionExceptionEventArgs(
            ITransitionContext<TState, TEvent> context,
            Exception exception)
        {
            Context = context ?? throw new ArgumentNullException(nameof(context));
            Exception = exception ?? throw new ArgumentNullException(nameof(exception));
        }

        /// <summary>
        /// Gets the transition context associated with the exception
        /// </summary>
        public ITransitionContext<TState, TEvent> Context { get; }

        /// <summary>
        /// Gets the exception that occurred during the state machine transition
        /// </summary>
        public Exception Exception { get; }

        /// <summary>
        /// Gets the current state of the state machine at the time of the exception
        /// </summary>
        public TState CurrentState => Context.CurrentState;

        /// <summary>
        /// Gets the event that triggered the transition which resulted in an exception
        /// </summary>
        public TEvent Event => Context.Event;
    }

    /// <summary>
    /// Interface defining the context of a state machine transition
    /// </summary>
    /// <typeparam name="TState">The type of state in the state machine</typeparam>
    /// <typeparam name="TEvent">The type of events in the state machine</typeparam>
    public interface ITransitionContext<TState, TEvent>
        where TState : IComparable
        where TEvent : IComparable
    {
        /// <summary>
        /// Gets the current state of the state machine
        /// </summary>
        TState CurrentState { get; }

        /// <summary>
        /// Gets the event that triggered the transition
        /// </summary>
        TEvent Event { get; }
    }
}

