public interface IDutyService
{
    Task<List<RoleEntity>> GetList(string keyword);
    Task<RoleEntity> GetForm(string keyValue);
    Task Delete(string keyValue);
    Task Save(RoleEntity roleEntity, string keyValue);
}

public class DutyService : IDutyService
{
    private readonly IService _service;
    private readonly IHttpContextAccessor _httpContextAccessor;

    public DutyService(IService service, IHttpContextAccessor httpContextAccessor)
    {
        _service = service;
        _httpContextAccessor = httpContextAccessor;
    }

    public async Task<List<RoleEntity>> GetList(string keyword)
    {
        var url = $"api/roles?keyword={keyword}";
        var response = await HttpHelper.GetAsync(url);
        var content = await response.Content.ReadAsStringAsync();
        return JsonConvert.DeserializeObject<List<RoleEntity>>(content);
    }

    public async Task<RoleEntity> GetForm(string keyValue)
    {
        var url = $"api/roles/{keyValue}";
        var response = await HttpHelper.GetAsync(url);
        var content = await response.Content.ReadAsStringAsync();
        return JsonConvert.DeserializeObject<RoleEntity>(content);
    }

    public async Task Delete(string keyValue)
    {
        var url = $"api/roles/{keyValue}";
        await HttpHelper.DeleteAsync(url);
    }

    public async Task Save(RoleEntity roleEntity, string keyValue)
    {
        roleEntity.Category = "System";
        roleEntity.CreateUserId = _httpContextAccessor.HttpContext.User.FindFirst("userId")?.Value;
        roleEntity.CreateTime = DateTime.Now;
        roleEntity.ModifyUserId = _httpContextAccessor.HttpContext.User.FindFirst("userId")?.Value;
        roleEntity.ModifyTime = DateTime.Now;

        if (string.IsNullOrEmpty(keyValue))
        {
            await _service.InsertAsync(roleEntity);
        }
        else
        {
            roleEntity.Id = keyValue;
            await _service.UpdateAsync(roleEntity);
        }
    }
}

public class RoleEntity
