namespace GameFramework.Creatures
{
    public class Hydra : BaseCreature
    {
        private const int MAX_HEADS = 7;
        private int _currentHeads;
        private bool _isRegenerating;

        [Constructable]
        public Hydra() : base(AIType.AI_Mage, FightMode.Closest, 10, 1, 0.2, 0.4)
        {
            Name = "Mythical Hydra";
            Body = 0x109;
            BaseSoundID = 0x16A;

            InitializeHydraAttributes();
            ConfigureCombatStats();
            SetupResistances();
        }

        private void InitializeHydraAttributes()
        {
            _currentHeads = MAX_HEADS;
            _isRegenerating = false;

            SetStr(500, 750);
            SetDex(80, 120);
            SetInt(200, 350);
            SetHits(1000, 1500);
        }

        private void ConfigureCombatStats()
        {
            SetDamage(15, 25);
            SetDamageType(ResistanceType.Physical, 40);
            SetDamageType(ResistanceType.Fire, 30);
            SetDamageType(ResistanceType.Poison, 30);
        }

        private void SetupResistances()
        {
            SetResistance(ResistanceType.Physical, 45, 55);
            SetResistance(ResistanceType.Fire, 60, 70);
            SetResistance(ResistanceType.Cold, 30, 40);
            SetResistance(ResistanceType.Poison, 50, 60);
            SetResistance(ResistanceType.Energy, 40, 50);
        }

        public override void OnDeath(Container container)
        {
            base.OnDeath(container);
            GenerateLoot(container);
            HandleHeadRegeneration();
        }

        private void GenerateLoot(Container container)
        {
            int lootMultiplier = _currentHeads * 2;

            container.AddItem(new HydraScale(lootMultiplier));
            container.AddItem(new Gold(Utility.RandomMinMax(500, 1000)));

            if (Utility.RandomDouble() < 0.25)
            {
                container.AddItem(new MagicWeapon());
            }
        }

        private void HandleHeadRegeneration()
        {
            if (!_isRegenerating && _currentHeads < MAX_HEADS)
            {
                _isRegenerating = true;
                Timer.DelayCall(TimeSpan.FromSeconds(30), RegenerateHead);
            }
        }

        private void RegenerateHead()
        {
            if (_currentHeads < MAX_HEADS)
            {
                _currentHeads++;
                Hits += 100;
                _isRegenerating = false;
            }
        }

