    {
        public string UnitName { get; }
        public Func<Message, Task> Outgoing { get; set; }

        public MessageUnit(string unitName)
        {
            UnitName = unitName;
            Outgoing = async (msg) => await Task.CompletedTask;
        }

        public async Task StartAsync()
        {
            Console.WriteLine($"Starting {UnitName}...");
            await Task.Delay(50);
        }

        public async Task StopAsync()
        {
            Console.WriteLine($"Stopping {UnitName}...");
            await Task.Delay(50);
        }

