        if (healthBar != null && displayedHealth != currentHealth) //animate health bar
        {
            if (displayedHealth < currentHealth)
                displayedHealth += Time.deltaTime * 50f;
            else
                displayedHealth -= Time.deltaTime * 50f;

            if (Mathf.Abs(displayedHealth - currentHealth) < 1)
                displayedHealth = currentHealth;

            healthBar.GetComponent<RectTransform>().sizeDelta = new Vector2(displayedHealth, 100f);
        }
    }

    //returns true if the target dies
    public bool dealDamage(float dmg)
    {
        currentHealth -= dmg;
        if (currentHealth <= 0)
        {
            currentHealth = 0;
            dead = true;

            if (isPlayer)
                gameManager.EndGame();
        }

        savedHealth = currentHealth;
        return dead;
    }

    public void SetHealth(float amount)
    {
        currentHealth = amount;
        savedHealth = amount;
        displayedHealth = amount;
        if (healthBar != null)
            healthBar.GetComponent<RectTransform>().sizeDelta = new Vector2(amount, 100f);
    }

}

using UnityEngine;
using System.Collections;

public class ElevatorBehaviour : MonoBehaviour
{
    public Vector2 iniPos;
    public Vector2 finalPos;
    public float timeDuration = 2f;
    public float startDelay = 1f;
    public bool activeDown;
    public bool activeUp;

    private float currentTime;

    private void Update()
    {
        if (activeDown)
        {
            DownElevator();
        }
        else if (activeUp)
        {
            UpElevator();
        }
    }

    private void DownElevator()
    {
        currentTime += Time.deltaTime;
        float t = Mathf.Clamp01(currentTime / timeDuration);
        float easedT = BackEaseOut(t);
        transform.position = Vector2.Lerp(iniPos, finalPos, easedT);

        if (currentTime >= timeDuration)
        {
            transform.position = finalPos;
            currentTime = 0f;
            activeDown = false;
        }
    }

    private void UpElevator()
    {
        currentTime += Time.deltaTime;
        float t = Mathf.Clamp01(currentTime / timeDuration);
        float easedT = BackEaseOut(t);
        transform.position = Vector2.Lerp(iniPos, finalPos, easedT);

        if (currentTime >= timeDuration)
        {
            transform.position = finalPos;
            currentTime = 0f;
            activeUp = false;
            Vector2 temp = iniPos;
            iniPos = finalPos;
            finalPos = temp;
        }
    }

    private float BackEaseOut(float t)
    {
        const float c1 = 1.70158f;
        float c3 = c1 + 1;
        return 1 + c3 * Mathf.Pow(t - 1, 3) + c1 * Mathf.Pow(t - 1, 2);
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        if (other.CompareTag("Player"))
        {
            StartCoroutine(DelayUpMovement());
        }
    }

    private IEnumerator DelayUpMovement()
    {
        yield return new WaitForSeconds(startDelay);
        Vector2 temp = iniPos;
        iniPos = finalPos;
        finalPos = temp;
        activeUp = true;
    }
}

public class DoublyLinkedList : LinkedList
{
    public DoublyLinkedList(int value, DoublyLinkedList next, DoublyLinkedList prev)
    {
        _value = value;
        _next = next;
        _prev = prev;
    }

    public DoublyLinkedList Prev
    {
        get { return _prev; }
        set { _prev = value; }
    }

    private DoublyLinkedList _prev;
}

public static class DoublyLinkedListExtensions
{
    public static DoublyLinkedList CreateDoublyLinkedListFromArray(int[] ary)
    {
        DoublyLinkedList node, prev, head = new DoublyLinkedList(ary[0], null, null);
        prev = head;
        for (int i = 1; i < ary.Length; i++)
        {
            node = new DoublyLinkedList(ary[i], null, prev);
            prev.Next = node;
            prev = node;
        }
        return head;
    }
}

