namespace Vector
{
    class Generator
    {
        static void Main(string[] args)
        {
            int i, zeroCount = 0, firstNonZero = -1;
            double[] vector;
 
            if (args.Length == 0)
            {
                Console.WriteLine("Usage : {0} <Vector component coefficients seperated by single space>", args[0]);
            }
 
            else
            {
                Console.Write("Vector for [");
                for (i = 0; i < args.Length; i++)
                {
                    Console.Write("{0},", args[i]);
                }
                Console.Write("\b] -> ");
 
                vector = new double[args.Length];
 
                for (i = 0; i < args.Length; i++)
                {
                    vector[i] = double.Parse(args[i]);
                    if (vector[i] == 0.0)
                        zeroCount++;
                    if (vector[i]!= 0.0 && firstNonZero == -1)
                        firstNonZero = i;
                }
 
                if (zeroCount == args.Length)
                {
                    Console.Write("0");
                }
 
                else
                {
                    for (i = 0; i < args.Length; i++)
                    {
                        if (i == firstNonZero && vector[i] == 1)
                            Console.Write("e{0} ", i + 1);
                        else if (i == firstNonZero && vector[i] == -1)
                            Console.Write("- e{0} ", i + 1);
                        else if (i == firstNonZero && vector[i] < 0 && Math.Abs(vector[i]) - Math.Abs(vector[i]) > 0.0)
                            Console.Write("- {0} e{1} ", Math.Abs(vector[i]), i + 1);
                        else if (i == firstNonZero && vector[i] < 0 && Math.Abs(vector[i]) - Math.Abs(vector[i]) == 0.0)
                            Console.Write("- {0} e{1} ", Math.Abs(vector[i]), i + 1);
                        else if (i == firstNonZero && vector[i] > 0 && Math.Abs(vector[i]) - Math.Abs(vector[i]) > 0.0)
                            Console.Write("{0} e{1} ", vector[i], i + 1);
                        else if (i == firstNonZero && vector[i] > 0 && Math.Abs(vector[i]) - Math.Abs(vector[i]) == 0.0)
                            Console.Write("{0} e{1} ", vector[i], i + 1);
                        else if (Math.Abs(vector[i]) == 1.0 && i!= 0)
                            Console.Write("{0} e{1} ", (vector[i] == -1)? '-' : '+', i + 1);

