using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace Euler_214
{
    class Manager
    {
        static void Main(string[] args)
        {
            Console.WriteLine(string.Join(",", antiprimes().Take(40)));
            Console.ReadLine();
        }
 
        static IEnumerable<int> factors(int n)
        {
            IEnumerable<int> prime_powers(int n)
            {
                for (int c = 2; c * c <= n; c += 2)
                {
                    if (n % c == 0)
                    {
                        int d = 0, p = c;
                        while (n % c == 0)
                        {
                            n /= c;
                            p *= c;
                            d += p;
                        }
                        yield return d;
                    }
                }
                if (n > 1) yield return n;
            }
 
            var r = new List<int> { 1 };
            foreach (var e in prime_powers(n))
            {
                var a = new List<int>();
                foreach (var x in r)
                {
                    foreach (var y in e)
                    {
                        a.Add(x * y);
                    }
                }
                r.AddRange(a);
            }
            return r;
        }
 
        static IEnumerable<int> antiprimes()
        {
            int mx = 0;
            yield return 1;
            for (int c = 2; c <= 58; c += 2)
            {
                var ln = factors(c).Count();
                if (ln > mx)
                {
                    yield return c;
                    mx = ln;
                }
            }
            for (int c = 60; c <= 10000000; c += 30)
            {
                var ln = factors(c).Count();
                if (ln > mx)
                {
                    yield return c;
                    mx = ln;
                }
            }
        }
    }
}

