using System;
using System.Collections.Generic;

public class Heap<T>
{
    private readonly IList<T> _list;
    private readonly IComparer<T> _comparer;
    private int _size;

    public Heap(IList<T> list, int count, IComparer<T> comparer = null)
    {
        if (list == null)
            throw new ArgumentNullException(nameof(list));
        if (count < 0 || count > list.Count)
            throw new ArgumentOutOfRangeException(nameof(count));

        _comparer = comparer ?? Comparer<T>.Default;
        _list = list;
        _size = count;
        Heapify();
    }

    public int Count => _size;

    public T PeekRoot()
    {
        if (_size == 0)
            throw new InvalidOperationException("Heap is empty.");
        return _list[0];
    }

    public T PopRoot()
    {
        T root = PeekRoot();
        _size--;
        SwapCells(0, _size);
        HeapDown(0);
        return root;
    }

    public void Insert(T item)
    {
        if (_size == _list.Count)
            _list.Add(item);
        else
            _list[_size] = item;
        _size++;
        HeapUp(_size - 1);
    }

    private void Heapify()
    {
        for (int i = Parent(_size - 1); i >= 0; i--)
            HeapDown(i);
    }

    private void HeapUp(int index)
    {
        while (index > 0)
        {
            int parentIndex = Parent(index);
            if (_comparer.Compare(_list[index], _list[parentIndex]) <= 0)
                break;
            SwapCells(index, parentIndex);
            index = parentIndex;
        }
    }

    private void HeapDown(int index)
    {
        while (true)
        {
            int leftChild = LeftChild(index);
            int rightChild = RightChild(index);
            int current = index;

            if (leftChild < _size && _comparer.Compare(_list[leftChild], _list[current]) > 0)
                current = leftChild;
            if (rightChild < _size && _comparer.Compare(_list[rightChild], _list[current]) > 0)
                current = rightChild;

            if (current == index)
                break;

            SwapCells(index, current);
            index = current;
        }
    }

    private static int Parent(int index) => (index - 1) / 2;
    private static int LeftChild(int index) => 2 * index + 1;
    private static int RightChild(int index) => 2 * index + 2;

    private void SwapCells(int i, int j)
    {
        T temp = _list[i];
        _list[i] = _list[j];
        _list[j] = temp;
    }
}

