using UnityEngine;
using System.Collections.Generic;

public interface ISequenceInterpreter
{
    bool CanHandle(SequenceNode node);
    ISequenceInterpreter Clone();
}

public abstract class SequenceInterpreterFactory : ScriptableObject
{
    private static SequenceInterpreterFactoryImp _instance;
    public static SequenceInterpreterFactory Instance
    {
        get
        {
            if (_instance == null)
            {
                _instance = ScriptableObject.CreateInstance<SequenceInterpreterFactoryImp>();
            }
            return _instance;
        }
    }

    public abstract ISequenceInterpreter CreateSequenceInterpreterFor(SequenceNode node);
}

public class SequenceInterpreterFactoryImp : SequenceInterpreterFactory
{
    private List<ISequenceInterpreter> sequenceInterpreters = new List<ISequenceInterpreter>();

    public override ISequenceInterpreter CreateSequenceInterpreterFor(SequenceNode node)
    {
        foreach (var interpreter in sequenceInterpreters)
        {
            if (interpreter.CanHandle(node))
            {
                return interpreter.Clone();
            }
        }
        Debug.LogWarning("No interpreter found for the given sequence node.");
        return null;
    }

    public void RegisterInterpreter(ISequenceInterpreter interpreter)
    {
        if (!sequenceInterpreters.Contains(interpreter))
        {
            sequenceInterpreters.Add(interpreter);
        }
    }

    // Uncomment for dynamic loading of interpreters at runtime
    // public void LoadInterpretersFromResources()
    // {
    //     var loadedInterpreters = Resources.LoadAll<ISequenceInterpreter>("Interpreters");
