public static bool prime(int a)
{
    if (a == 2)
    {
        return true;
    }
    else if (a <= 1 || a % 2 == 0)
    {
        return false;
    }
    else
    {
        var divisors = Enumerable.Range(3, (int)Math.Sqrt(a)).Where(d => d % 2 == 0);
        return divisors.All(d => a % d!= 0);
    }
}

public static void Main()
{
    var result = Enumerable.Range(1, 50).Where(i => prime(i));
    Console.WriteLine(string.Join(", ", result));
}

