internal class OpenExplorerCommand : ICommand
{
    private readonly IServiceProvider _serviceProvider;
    private const string CommandId = "OpenPowerShellCommandExplorer";
    private const string Description = "Open PowerShell Command Explorer";

    public OpenExplorerCommand(IServiceProvider serviceProvider)
    {
        _serviceProvider = serviceProvider ?? throw new ArgumentNullException(nameof(serviceProvider));
    }

    public void Execute(object sender, EventArgs args)
    {
        try
        {
            var shell = (IVsShell)_serviceProvider.GetService(typeof(SVsShell));
            var explorer = new CommandExplorer();
            explorer.Show();
            shell.SetMode(Mode.CommandExplorer);
        }
        catch (Exception ex)
        {
            // Handle exceptions appropriately
            System.Diagnostics.Debug.WriteLine("Error opening Command Explorer: " + ex.Message);
            // You might want to show the error in a user-friendly way
        }
    }

    public void QueryStatus(object sender, CommandStatusEventArgs args)
    {
        if (args == null) throw new ArgumentNullException(nameof(args));

        // Check if the command can be executed based on context
        bool canExecute = CheckExecutionContext();

        args.Enabled = canExecute;
        args.Visible = true; // Always show the command for this example
        args.SetStatus(canExecute ? CommandStatus.Enabled : CommandStatus.Disabled);
    }

    private bool CheckExecutionContext()
    {
        // Here you might want to check specific conditions to enable or disable the command
        bool isPowerShellAvailable = IsPowerShellAvailable();
        return isPowerShellAvailable;
    }

    private bool IsPowerShellAvailable()
    {
        // Check if PowerShell is installed and accessible
        // Use proper checks based on the requirements of your application
        return true; // Assuming PowerShell is always available for this example
    }
}

