using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace Maze
{
    class Validator
    {
        static void Main(string[] args)
        {
            Console.WriteLine(make_maze());
        }
 
        static string make_maze(int w = 16, int h = 8)
        {
            var vis = new int[h][];
            for (int i = 0; i < h; i++)
            {
                vis[i] = new int[w + 1];
            }
            vis[h - 1][w] = 1;
 
            var ver = new string[h][];
            for (int i = 0; i < h; i++)
            {
                ver[i] = new string[w + 1];
            }
            ver[h - 1][w] = "|";
 
            var hor = new string[h + 1][];
            for (int i = 0; i < h + 1; i++)
            {
                hor[i] = new string[w + 1];
            }
            hor[h][w] = "+";
 
            walk(randrange(w), randrange(h));
 
            var s = new StringBuilder();
            for (int i = 0; i < h + 1; i++)
            {
                for (int j = 0; j < w + 1; j++)
                {
                    s.Append(hor[i][j]);
                }
                s.Append("\n");
                for (int j = 0; j < w + 1; j++)
                {
                    s.Append(ver[i][j]);
                }
                s.Append("\n");
            }
            return s.ToString();
 
            void walk(int x, int y)
            {
                vis[y][x] = 1;
 
                var d = new List<(int, int)>();
                d.Add((x - 1, y));
                d.Add((x, y + 1));
                d.Add((x + 1, y));
                d.Add((x, y - 1));
                d = d.OrderBy(x => randrange(4)).ToList();
                foreach (var (xx, yy) in d)
                {
                    if (vis[yy][xx] == 1) continue;
                    if (xx == x) hor[Math.Max(y, yy)][x] = "+  ";
                    if (yy == y) ver[y][Math.Max(x, xx)] = "   ";
                    walk(xx, yy);
                }
            }
        }
 
        static int randrange(int n)
        {
            return new Random().Next(n);
        }
    }
}

