class Reader
{
    static void Main()
    {
        using (var context = new NetMQContext())
        {
            const string endpoint1 = "inproc://step1";
            const string endpoint2 = "inproc://step2";

            using (var socket1 = context.CreatePairSocket())
            using (var socket2 = context.CreatePairSocket())
            using (var socket3 = context.CreatePairSocket())
            {
                socket1.Bind(endpoint1);
                socket2.Connect(endpoint1);
                socket2.Bind(endpoint2);
                socket3.Connect(endpoint2);

                var thread1 = new Thread(() => Step1(socket2));
                var thread2 = new Thread(() => Step2(socket3));
                var thread3 = new Thread(() => Step3(socket1));

                thread1.Start();
                thread2.Start();
                thread3.Start();

                thread1.Join();
                thread2.Join();
                thread3.Join();
            }
        }
    }

    static void Step1(PairSocket socket)
    {
        Console.WriteLine("Step 1: Preparing to send signal");

        try
        {
            socket.SendFrame("Signal from Step 1");
            Console.WriteLine("Step 1: Signal sent successfully");

            string receivedMessage = socket.ReceiveFrameString();
            Console.WriteLine($"Step 1 received: {receivedMessage}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Step 1 error: {ex.Message}");
        }
    }

    static void Step2(PairSocket socket)
    {
        Console.WriteLine("Step 2: Waiting for signal");

        try
        {
            string receivedMessage = socket.ReceiveFrameString();
            Console.WriteLine($"Step 2 received: {receivedMessage}");

            socket.SendFrame("Signal from Step 2");
            Console.WriteLine("Step 2: Signal sent successfully");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Step 2 error: {ex.Message}");
        }
    }

    static void Step3(PairSocket socket)
    {
        Console.WriteLine("Step 3: Waiting for signals");

        try
        {
            string receivedMessage = socket.ReceiveFrameString();
