        for (int x = 0; x < state.Grid.GetLength(0); x++)
        {
            for (int y = 0; y < state.Grid.GetLength(1); y++)
            {
                if (state.Grid[x, y] != null && state.Grid[x, y].Color == tileColor)
                {
                    // Here we would check the tile's move rules based on its type
                    validMoves.AddRange(GetMovesForTile(state, x, y));
                }
            }
        }

        return validMoves;
    }

    private IEnumerable<Position> GetMovesForTile(GameState state, int x, int y)
    {
        // This is a stub for demonstration; in real case, check actual game rules.
        var potentialMoves = new List<Position>();

        if (x + 1 < state.Grid.GetLength(0)) potentialMoves.Add(new Position(x + 1, y)); // Move right
        if (y + 1 < state.Grid.GetLength(1)) potentialMoves.Add(new Position(x, y + 1)); // Move down

        return potentialMoves;
    }
}

