namespace RosettaCodeData
{
    class MinimumNumberOnlyZeroAndOne
    {
        static void Main(string[] args)
        {
            foreach (int n in GetTestCases())
            {
                BigInteger result = GetA004290(n);
                Console.WriteLine("A004290({0}) = {1} = {2} * {3}", n, result, n, result / n);
            }
        }
 
        private static List<int> GetTestCases()
        {
            List<int> testCases = new List<int>();
            for (int i = 1; i <= 10; i++)
            {
                testCases.Add(i);
            }
            for (int i = 95; i <= 105; i++)
            {
                testCases.Add(i);
            }
            foreach (int i in new int[] { 297, 576, 594, 891, 909, 999, 1998, 2079, 2251, 2277, 2439, 2997, 4878 })
            {
                testCases.Add(i);
            }
            return testCases;
        }
 
        private static BigInteger GetA004290(int n)
        {
            if (n == 1)
            {
                return BigInteger.One;
            }
            int[][] L = new int[n][];
            for (int i = 0; i < n; i++)
            {
                L[i] = new int[n];
            }
            for (int i = 2; i < n; i++)
            {
                L[0][i] = 0;
            }
            L[0][0] = 1;
            L[0][1] = 1;
            int m = 0;
            BigInteger ten = BigInteger.One * 10;
            BigInteger nBi = BigInteger.One * n;
            while (true)
            {
                m++;
                //  if L[m-1, (-10^m) mod n] = 1 then break
                if (L[m - 1][Mod(BigInteger.Pow(ten, m) * -1, nBi).ToInt32()] == 1)
                {
                    break;
                }
                L[m][0] = 1;
                for (int k = 1; k < n; k++)
                {
                    //L[m][k] = Math.Max(L[m-1][k], L[m-1][mod(k-pow(10,m), n)]);
                    L[m][k] = Math.Max(L[m - 1][k], L[m - 1][Mod(BigInteger.One * k - BigInteger.Pow(ten, m), nBi).ToInt32()]);
                }
            }
            //int r = pow(10,m);
            //int k = mod(-pow(10,m), n);
            BigInteger r = BigInteger.Pow(ten, m);
            BigInteger k = Mod(r * -1, nBi);
            for (int j = m - 1; j >= 1; j--)
            {
                if (L[j - 1][k.ToInt32()] == 0)
                {
                    //r = r + pow(10, j);
                    //k = mod(k-pow(10, j), n);
                    r = r + BigInteger.Pow(ten, j);

