namespace A004290
{
    class Converter
    {
        static int mod(int m, int n)
        {
            int result = m % n;
            if (result < 0)
            {
                result = result + n;
            }
            return result;
        }

        static int getA004290(int n)
        {
            if (n == 1)
            {
                return 1;
            }
            int[,] arr = new int[n, n];
            arr[0, 0] = 1;
            arr[0, 1] = 1;
            int m = 0;
            while (true)
            {
                m = m + 1;
                if (arr[m - 1, mod(-10 ^ m, n)] == 1)
                {
                    break;
                }
                arr[m, 0] = 1;
                for (int k = 1; k < n; k++)
                {
                    arr[m, k] = Math.Max(arr[m - 1, k], arr[m - 1, mod(k - 10 ^ m, n)]);
                }
            }
            int r = 10 ^ m;
            int k = mod(-r, n);
            for (int j = m - 1; j > 0; j--)
            {
                if (arr[j - 1, k] == 0)
                {
                    r = r + 10 ^ j;
                    k = mod(k - 10 ^ j, n);
                }
            }
            if (k == 1)
            {
                r = r + 1;
            }
            return r;
        }

        static void Main(string[] args)
        {
            List<int> testCases = new List<int>();
            for (int i = 1; i <= 10; i++)
            {
                testCases.Add(i);
            }
            for (int i = 95; i <= 105; i++)
            {
                testCases.Add(i);
            }
            testCases.AddRange(new int[] { 297, 576, 594, 891, 909, 999, 1998, 2079, 2251, 2277, 2439, 2997, 4878 });
            foreach (int n in testCases)
            {
                int result = getA004290(n);
                Console.WriteLine("A004290({0}) = {1} = {2} * {3}", n, result, n, result / n);
            }
        }
    }
}

