using Xunit;

public class ContestantsControllerTests
{
    private readonly Mock<IMediator> _mediatorMock;
    private readonly ContestantsController _systemUnderTest;

    public ContestantsControllerTests()
    {
        _mediatorMock = new Mock<IMediator>();
        _systemUnderTest = new ContestantsController(_mediatorMock.Object);
    }

    [Fact]
    public async Task GetContestantsAttempts_WithValidIdAndResults_ReturnsOk()
    {
        // Arrange
        var contestantId = Guid.NewGuid();
        var attempts = new List<Attempt> { new Attempt() };
        _mediatorMock.Setup(m => m.Send(It.IsAny<GetAttemptsQuery>(), default))
                      .ReturnsAsync(attempts);

        // Act
        var result = await _systemUnderTest.GetContestantsAttempts(contestantId);

        // Assert
        var okResult = Assert.IsType<OkObjectResult>(result);
        Assert.Equal(200, okResult.StatusCode);
    }

    [Fact]
    public async Task GetContestantsAttempts_WithValidIdAndNoResults_ReturnsNotFound()
    {
        // Arrange
        var contestantId = Guid.NewGuid();
        _mediatorMock.Setup(m => m.Send(It.IsAny<GetAttemptsQuery>(), default))
                      .ReturnsAsync(new List<Attempt>());

        // Act
        var result = await _systemUnderTest.GetContestantsAttempts(contestantId);

        // Assert
        var notFoundResult = Assert.IsType<NotFoundResult>(result);
        Assert.Equal(404, notFoundResult.StatusCode);
    }

    [Fact]
    public async Task GetContestantsAttempts_WithInvalidId_ReturnsBadRequest()
    {
        // Arrange
        var invalidContestantId = Guid.Empty;

        // Act
        var result = await _systemUnderTest.GetContestantsAttempts(invalidContestantId);

        // Assert
        var badRequestResult = Assert.IsType<BadRequestResult>(result);
        Assert.Equal(400, badRequestResult.StatusCode);
    }
}

