namespace ProjectEuler
{
    class Solution
    {
        static void Main(string[] args)
        {
            string data = @"55
94 48
95 30 96
77 71 26 67
97 13 76 38 45
07 36 79 16 37 68
48 07 09 18 70 26 06
18 72 79 46 59 79 29 90
20 76 87 11 32 07 07 49 18
27 83 58 35 71 11 25 57 29 85
14 64 36 96 27 11 58 56 92 18 55
02 90 03 60 48 49 41 46 33 36 47 23
92 50 48 02 36 59 42 79 72 20 82 77 42
56 78 38 80 39 75 02 71 66 66 01 03 55 72
44 25 67 84 71 67 11 61 40 57 58 89 40 56 36
85 32 25 85 57 48 84 35 47 62 17 01 01 99 89 52
06 71 28 75 94 48 37 10 23 51 06 48 53 18 74 98 15
27 02 92 23 08 71 76 84 15 52 92 63 81 10 44 10 69 93";
            Console.WriteLine(solve(data));
            Console.ReadLine();
        }
        static int solve(string data)
        {
            List<List<int>> tri = new List<List<int>>();
            foreach (string row in data.Split(new string[] { "\r\n" }, StringSplitOptions.RemoveEmptyEntries))
            {
                tri.Add(row.Split(' ').Select(x => int.Parse(x)).ToList());
            }
            while (tri.Count > 1)
            {
                List<int> t0 = tri[tri.Count - 1];
                List<int> t1 = tri[tri.Count - 2];
                tri.RemoveAt(tri.Count - 1);
                tri.RemoveAt(tri.Count - 1);
                List<int> t2 = new List<int>();
                for (int i = 0; i < t1.Count; i++)
                {
                    t2.Add(Math.Max(t0[i], t0[i + 1]) + t1[i]);
                }
                tri.Add(t2);
            }
            return tri[0][0];
        }
    }
}

using System;

public class SortMappingDefinition
{
    public const string DIRECTION_ASCENDING = "asc";
    public const string DIRECTION_DESCENDING = "desc";

    public string Field { get; private set; }
    public string Destination { get; private set; }
    public string DefaultDirection { get; private set; }

    // Constructor for implicit mapping (source and destination are the same).
    public SortMappingDefinition(string field)
    {
        if (string.IsNullOrWhiteSpace(field))
        {
            throw new ArgumentException("Field cannot be null or empty.", nameof(field));
        }

        Field = field;
        Destination = field;
        DefaultDirection = DIRECTION_ASCENDING; // Default to ascending.
    }

    // Constructor for explicit mapping (source and destination can be different).
    public SortMappingDefinition(string field, string destination)
    {
        if (string.IsNullOrWhiteSpace(field))
        {
            throw new ArgumentException("Field cannot be null or empty.", nameof(field));
        }
        if (string.IsNullOrWhiteSpace(destination))
        {
            throw new ArgumentException("Destination cannot be null or empty.", nameof(destination));
        }

        Field = field;
        Destination = destination;
        DefaultDirection = DIRECTION_ASCENDING; // Default to ascending.
    }

    // Constructor for explicit mapping with custom default direction.
    public SortMappingDefinition(string field, string destination, string defaultDirection)
    {
        if (string.IsNullOrWhiteSpace(field))
        {
            throw new ArgumentException("Field cannot be null or empty.", nameof(field));
        }
        if (string.IsNullOrWhiteSpace(destination))
        {
            throw new ArgumentException("Destination cannot be null or empty.", nameof(destination));
        }
        if (string.IsNullOrWhiteSpace(defaultDirection))
        {
            throw new ArgumentException("Default direction cannot be null or empty.", nameof(defaultDirection));
        }
        //  ui layer uses lowercase 'asc' and 'desc'.
        if (defaultDirection != DIRECTION_ASCENDING && defaultDirection != DIRECTION_DESCENDING)
        {
            throw new ArgumentException("Invalid default direction.  Must be 'asc' or 'desc'.", nameof(defaultDirection));
        }

        Field = field;
        Destination = destination;
        DefaultDirection = defaultDirection;
    }
}

