using System;
 
class Game {
 
    // translated from java example
    static long js(int l, int n) {
        long res = 0, f = 1;
        double lf = Math.Log10(2);
        for (int i = l; i > 10; i /= 10) f *= 10;
        while (n > 0)
            if ((int)(f * Math.Pow(10, ++res * lf % 1)) == l) n--;
        return res;
    }
 
    // translated from go integer example (a.k.a. go translation of pascal alternative example)
    static long gi(int ld, int n) {
        string Ls = ld.ToString();
        long res = 0, count = 0, f = 1;
        for (int i = 1; i <= 18 - Ls.Length; i++) f *= 10;
        const long ten18 = (long)1e18; long probe = 1;
        do {
            probe <<= 1; res++; if (probe >= ten18)
                do {
                    if (probe >= ten18) probe /= 10;
                    if (probe / f == ld)
                        if (++count >= n) { count--; break; }
                    probe <<= 1; res++;
                } while (true);
            string ps = probe.ToString();
            if (ps.Substring(0, Math.Min(Ls.Length, ps.Length)) == Ls)
                if (++count >= n) break;
        } while (true);
        return res;
    }
 
    // translated from pascal alternative example
    static long pa(int ld, int n) {
        double L_float64 = Math.Pow(2, 64);
        ulong Log10_2_64 = (ulong)(L_float64 * Math.Log10(2));
        double Log10Num; ulong LmtUpper, LmtLower, Frac64;
        long res = 0, dgts = 1, cnt;
        for (int i = ld; i >= 10; i /= 10) dgts *= 10;
        Log10Num = Math.Log10((ld + 1.0) / dgts);
        // '316' was a limit
        if (Log10Num >= 0.5) {
            LmtUpper = (ld + 1.0) / dgts < 10.0 ? (ulong)(Log10Num * (L_float64 * 0.5)) * 2 + (ulong)(Log10Num * 2) : 0;
            Log10Num = Math.Log10((double)ld / dgts);
            LmtLower = (ulong)(Log10Num * (L_float64 * 0.5)) * 2 + (ulong)(Log10Num * 2);
        } else {
            LmtUpper = (ulong)(Log10Num * L_float64);
            LmtLower = (ulong)(Math.Log10((double)ld / dgts) * L_float64);
        }
        cnt = 0; Frac64 = 0; if (LmtUpper != 0)
            do {
                res++; Frac64 += Log10_2_64;
                if ((Frac64 >= LmtLower) & (Frac64 < LmtUpper))
                    if (++cnt >= n) break;
            } while (true);
        else // '999..'
            do {
                res++; Frac64 += Log10_2_64;
                if (Frac64 >= LmtLower) if (++cnt >= n) break;
            } while (true);
        return res;
    }

using System;
using System.Linq;
using System.Collections.Generic;
 
public class Circle
{
    public double X { get; private set; }
    public double Y { get; private set; }
    public double R { get; private set; }
 
    public Circle(double x, double y, double r)
    {
        X = x;
        Y = y;
        R = r;
    }
 
    public static Circle Apollonius(Circle c1, Circle c2, Circle c3, int s1 = 1, int s2 = 1, int s3 = 1)
    {
        double x1 = c1.X;
        double y1 = c1.Y;
        double r1 = c1.R;
        double x2 = c2.X;
        double y2 = c2.Y;
        double r2 = c2.R;
        double x3 = c3.X;
        double y3 = c3.Y;
        double r3 = c3.R;
 
        double v11 = 2 * x2 - 2 * x1;
        double v12 = 2 * y2 - 2 * y1;
        double v13 = x1 * x1 - x2 * x2 + y1 * y1 - y2 * y2 - r1 * r1 + r2 * r2;
        double v14 = 2 * s2 * r2 - 2 * s1 * r1;
 
        double v21 = 2 * x3 - 2 * x2;
        double v22 = 2 * y3 - 2 * y2;
        double v23 = x2 * x2 - x3 * x3 + y2 * y2 - y3 * y3 - r2 * r2 + r3 * r3;
        double v24 = 2 * s3 * r3 - 2 * s2 * r2;
 
        double w12 = v12 / v11;
        double w13 = v13 / v11;
        double w14 = v14 / v11;
 
        double w22 = v22 / v21 - w12;
        double w23 = v23 / v21 - w13;
        double w24 = v24 / v21 - w14;
 
        double p = -w23 / w22;
        double q = w24 / w22;
        double m = -w12 * p - w13;
        double n = w14 - w12 * q;
 
        double a = n * n + q * q - 1;
        double b = 2 * m * n - 2 * n * x1 + 2 * p * q - 2 * q * y1 + 2 * s1 * r1;
        double c = x1 * x1 + m * m - 2 * m * x1 + p * p + y1 * y1 - 2 * p * y1 - r1 * r1;
 
        double d = b * b - 4 * a * c;
        double rs = (-b - Math.Sqrt(d)) / (2 * a);
        double xs = m + n * rs;
        double ys = p + q * rs;
 
        return new Circle(xs, ys, rs);
    }
 
    public override string ToString()
    {
        return string.Format("Circle: x={0}, y={1}, r={2}", X, Y, R);
    }
}
 
public class Writer
{
    public static void Main()
    {
        var c1 = new Circle(0, 0, 1);
        var c2 = new Circle(2, 4, 2);
        var c3 = new Circle(4, 0, 1);
 
        Console.WriteLine(c1);
        Console.WriteLine(c2);
        Console.WriteLine(c3);
 
        Console.WriteLine(Circle.Apollonius(c1, c2, c3));
        Console.WriteLine(Circle.Apollonius(c1, c2, c3, -1, -1, -1));
    }
}

