public abstract class Control : INotifyPropertyChanged
{
    private double _value;

    public string Name { get; set; }
    public int ChannelID { get; set; }
    public ControlType Type { get; set; }
    public int State { get; set; }
    public APCMiniController ApcMiniController { get; set; }

    public double Value
    {
        get { return _value; }
        set
        {
            if (_value != value)
            {
                _value = value;
                OnPropertyChanged();

                // Update LED based on control type
                if (Type == ControlType.Fader)
                {
                    // Logic for Fader
                    ApcMiniController?.SetLed(ChannelID, (int)(value * 127));
                }
                else if (Type == ControlType.MatrixButton)
                {
                    // Logic for Matrix Buttons
                }
                else if (Type == ControlType.DedicatedButton)
                {
                    // Logic for Dedicated Buttons
                }

                // Send MIDI message
                ApcMiniController?.SendControlChange(ChannelID, (int)(value * 127));
            }
        }
    }

    public event PropertyChangedEventHandler PropertyChanged;

    protected virtual void OnPropertyChanged([CallerMemberName] string propertyName = null)
    {
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
    }
}

