namespace Humble_Numbers
{
    class Library
    {
        static bool isHumble(int i)
        {
            if (i <= 1) return true;
            if (i % 2 == 0) return isHumble(i / 2);
            if (i % 3 == 0) return isHumble(i / 3);
            if (i % 5 == 0) return isHumble(i / 5);
            if (i % 7 == 0) return isHumble(i / 7);
            return false;
        }
 
        static void Main(string[] args)
        {
            int limit = short.MaxValue;
            int[] humble = new int[16];
            int count = 0;
            int num = 1;
            char[] buffer = new char[16];
 
            for (int i = 0; i < humble.Length; i++)
            {
                humble[i] = 0;
            }
 
            for (; count < limit; num++)
            {
                if (isHumble(num))
                {
                    int len = num.ToString().Length;
                    if (len >= 16)
                    {
                        break;
                    }
                    humble[len]++;
 
                    if (count < 50)
                    {
                        Console.Write(num + " ");
                    }
                    count++;
                }
            }
            Console.WriteLine("\n\n");
 
            Console.WriteLine("Of the first {0} humble numbers:", count);
            for (num = 1; num < 10; num++)
            {
                Console.WriteLine("{0,5} have {1} digits", humble[num], num);
            }
 
            Console.ReadLine();
        }
    }
}

