namespace CatLib.FileSystem
{
    public interface IHandler
    {
        // Properties
        string Path { get; }
        bool IsExists { get; }
        bool IsDir { get; }

        // Methods for file/directory operations
        void Rename(string newName);
        void Move(string newPath);
        void Copy(string copyPath);
        void Delete();

        // Methods for retrieving attributes and size
        FileAttributes GetAttributes();
        long GetSize();

        // Additional utility methods
        bool Exists();
        bool IsDirectory();
    }

    public class FileSystemHandler : IHandler
    {
        public string Path { get; private set; }

        public FileSystemHandler(string path)
        {
            Path = path;
        }

        public bool IsExists => File.Exists(Path) || Directory.Exists(Path);

        public bool IsDir => Directory.Exists(Path);

        public void Rename(string newName)
        {
            if (IsDir)
            {
                Directory.Move(Path, System.IO.Path.Combine(System.IO.Path.GetDirectoryName(Path), newName));
            }
            else
            {
                File.Move(Path, System.IO.Path.Combine(System.IO.Path.GetDirectoryName(Path), newName));
            }
        }

        public void Move(string newPath)
        {
            if (IsDir)
            {
                Directory.Move(Path, newPath);
            }
            else
            {
                File.Move(Path, newPath);
            }
        }

        public void Copy(string copyPath)
        {
            if (IsDir)
            {
                CopyDirectory(Path, copyPath);
            }
            else
            {
                File.Copy(Path, copyPath);
            }
        }

        public void Delete()
        {
            if (IsDir)
            {
                Directory.Delete(Path, true);
            }
            else
            {
                File.Delete(Path);
            }
        }

        public FileAttributes GetAttributes()
        {
            return IsDir ? Directory.GetAttributes(Path) : File.GetAttributes(Path);
        }

        public long GetSize()
        {
            if (IsDir)
            {
                return GetDirectorySize(Path);
            }
            else
            {
                return new FileInfo(Path).Length;
            }
        }

        public bool Exists()
        {
            return IsExists;
        }

        public bool IsDirectory()
        {
            return IsDir;
        }

