using AutoMapper;
using PortableLeagueApi.Core.Models;
using PortableLeagueApi.Core.Services;
using PortableLeagueApi.Interfaces.Static;
using PortableLeagueApi.Static.Models.DTO;

namespace PortableLeagueApi.Static.Models
{
    public class Realm : ApiModel, IRealm
    {
        public string BaseCdnUrl { get; set; }

        public string LatestChangedCssVersion { get; set; }

        public string LatestChangedDragonMagicVersion { get; set; }

        public string DefaultLanguage { get; set; }

        public string LegacyScript { get; set; }

        public IDictionary<string, string> LatestChangedVersionForEachDataType { get; set; }

        public int ProfileIconMax { get; set; }

        public string Store { get; set; }

        public string CurrentVersion { get; set; }

        internal static void CreateMap(AutoMapperService autoMapperService)
        {
            CreateMap<Realm>(autoMapperService);
            CreateMap<IRealm>(autoMapperService).As<Realm>();
        }

        private static IMappingExpression<RealmDto, T> CreateMap<T>(AutoMapperService autoMapperService)
            where T : IRealm
        {
            return autoMapperService.CreateApiModelMap<RealmDto, T>()
                .ForMember(x => x.BaseCdnUrl, x => x.MapFrom(z => z.Cdn))
                .ForMember(x => x.LatestChangedCssVersion, x => x.MapFrom(z => z.Css))
                .ForMember(x => x.LatestChangedDragonMagicVersion, x => x.MapFrom(z => z.Dd))
                .ForMember(x => x.DefaultLanguage, x => x.MapFrom(z => z.L))
                .ForMember(x => x.LegacyScript, x => x.MapFrom(z => z.Lg))
                .ForMember(x => x.LatestChangedVersionForEachDataType, x => x.MapFrom(z => z.N))
                .ForMember(x => x.ProfileIconMax, x => x.MapFrom(z => z.Profileiconmax))
                .ForMember(x => x.CurrentVersion, x => x.MapFrom(z => z.V));
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace Matrix
{
    class Utils
    {
        static void Main(string[] args)
        {
            int mn, mx;
            int[] inclusive_range = { 1, 10 };
            mn = inclusive_range[0];
            mx = inclusive_range[1];
            Console.WriteLine("Think of a number between {0} and {1} and wait for me to guess it.", inclusive_range[0], inclusive_range[1]);
            Console.WriteLine("On every guess of mine you should state whether the guess was too high, too low, or equal to your number by typing h, l, or =");
            int i = 0;
            while (true)
            {
                i++;
                int guess = (mn + mx) / 2;
                Console.Write("Guess {0} is: {1}. The score for which is (h,l,=): ", i, guess);
                string txt = Console.ReadLine().ToLower();
                if (txt.Length == 0)
                {
                    Console.WriteLine("  I don't understand your input of '{0}' ?", txt);
                    continue;
                }
                if (txt[0] == 'h')
                {
                    mx = guess - 1;
                }
                if (txt[0] == 'l')
                {
                    mn = guess + 1;
                }
                if (txt[0] == '=')
                {
                    Console.WriteLine("  Ye-Haw!!");
                    break;
                }
                if ((mn > mx) || (mn < inclusive_range[0]) || (mx > inclusive_range[1]))
                {
                    Console.WriteLine("Please check your scoring as I cannot find the value");
                    break;
                }
            }
            Console.WriteLine("\nThanks for keeping score.");
            Console.ReadLine();
        }
    }
}

using System;
using ConvNetSharp.Volume.GPU.Double;

namespace GpuVolumeBuilder
{
    public class VolumeBuilder
    {
        private readonly GpuContext _gpuContext;
        private readonly Shape _targetShape;
        private VolumeStorage<double> _volumeStorage;

        public VolumeBuilder(GpuContext gpuContext, Shape shape)
        {
            _gpuContext = gpuContext ?? throw new ArgumentNullException(nameof(gpuContext));
            _targetShape = shape ?? throw new ArgumentNullException(nameof(shape));
        }

        public Volume Build()
        {
            if (_volumeStorage == null)
            {
                throw new InvalidOperationException("Volume storage has not been initialized.");
            }

            return new Volume(_gpuContext, _volumeStorage);
        }

        public VolumeBuilder Random(double mean = 0.0, double stdDev = 1.0)
        {
            var randomData = new double[_targetShape.TotalLength];
            var random = new Random();

            for (int i = 0; i < randomData.Length; i++)
            {
                randomData[i] = RandomUtilities.BoxMullerTransform(random, mean, stdDev);
            }

            _volumeStorage = new VolumeStorage<double>(_targetShape, randomData);
            return this;
        }

        public VolumeBuilder SameAs(Volume sourceVolume)
        {
            if (sourceVolume == null)
            {
                throw new ArgumentNullException(nameof(sourceVolume));
            }

            _volumeStorage = new VolumeStorage<double>(sourceVolume.Shape, new double[sourceVolume.Shape.TotalLength]);
            return this;
        }

        public VolumeBuilder From(double[] sourceData)
        {
            if (sourceData == null)
            {
                throw new ArgumentNullException(nameof(sourceData));
            }

            if (sourceData.Length != _targetShape.TotalLength)
            {
                throw new ArgumentException("Data length does not match volume shape.");
            }

            _volumeStorage = new VolumeStorage<double>(_targetShape, sourceData);
            return this;
        }

        private static class RandomUtilities
        {
            public static double BoxMullerTransform(Random random, double mean, double stdDev)
            {
                double u1 = 1.0 - random.NextDouble();
                double u2 = 1.0 - random.NextDouble();
                double randStdNormal = Math.Sqrt(-2.0 * Math.Log(u1)) * Math.Sin(2.0 * Math.PI * u2);
                return mean + (stdDev * randStdNormal);
            }

