using System;
using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;
using System.Diagnostics.Contracts;

public interface IObjectWithGetCode
{
    string Code { get; }
}

public interface IObjectWithGetInfo
{
    string Info { get; }
}

public abstract class EntityBase
{
    // Base class for entities
}

public class Person : EntityBase, IObjectWithGetCode, IObjectWithGetInfo
{
    [Required]
    [StringLength(50, ErrorMessage = "Code cannot exceed 50 characters.")]
    public string Code { get; private set; }

    [Required]
    [StringLength(256, ErrorMessage = "Info cannot exceed 256 characters.")]
    public string Info { get; private set; }

    [Required]
    [StringLength(100, ErrorMessage = "First Name cannot exceed 100 characters.")]
    public string FirstName { get; private set; }

    [Required]
    [StringLength(100, ErrorMessage = "Last Name cannot exceed 100 characters.")]
    public string LastName { get; private set; }

    public List<RouteEntry> PeriodRouteEntries { get; private set; }
    public List<FuelEntry> PeriodFuelEntries { get; private set; }

    public Person(string code, string info, string firstName, string lastName)
    {
        Code = code;
        Info = info;
        FirstName = firstName;
        LastName = lastName;
        Init();
    }

    private void Init()
    {
        PeriodRouteEntries = new List<RouteEntry>();
        PeriodFuelEntries = new List<FuelEntry>();
    }

    public void AddPeriodRouteEntry(RouteEntry entry)
    {
        Contract.Requires(entry != null, "Entry cannot be null.");
        Contract.Requires(!PeriodRouteEntries.Contains(entry), "Entry already associated with this person.");

        PeriodRouteEntries.Add(entry);
        entry.SetPerson(this);
    }

    public void AddPeriodFuelEntry(FuelEntry entry)
    {
        Contract.Requires(entry != null, "Entry cannot be null.");
        Contract.Requires(!PeriodFuelEntries.Contains(entry), "Entry already associated with this person.");

        PeriodFuelEntries.Add(entry);
        entry.SetPerson(this);
    }
}

public class RouteEntry
{
    private Person _person;

    public void SetPerson(Person person)
    {
        _person = person;
    }
}

public class FuelEntry
{
    private Person _person;

    public void SetPerson(Person person)
    {
        _person = person;
    }
}

using System.IO;
using System.Linq;
 
namespace CSV_data_manipulation
{
    class Stack
    {
        static void Main()
        {
            var input = File.ReadAllLines("test_in.csv");
            var output = input.Select((line, i) =>
            {
                if (i == 0)
                    return line + ",SUM";
                var sum = line.Split(',').Select(int.Parse).Sum();
                return line + "," + sum;
            }).ToArray();
            File.WriteAllLines("test_out.csv", output);
        }
    }
}

using System;
using System.Collections.Generic;
using Antlr4.Runtime;
using Rubberduck.Parsing.VBA;
using Rubberduck.VBEditor;

namespace Rubberduck.Quickfixes
{
    // Base class for quick fix handlers
    public abstract class QuickFixBase
    {
        public abstract void Fix();
    }

    // Represents a selection in the code editor
    public class CodeSelection
    {
        public int LineNumber { get; set; }  // 1-indexed line number where fix is applied

        public CodeSelection(int lineNumber)
        {
            LineNumber = lineNumber;
        }
    }

    // Represents a simple code module for a VBA project
    public class CodeModule
    {
        public List<string> Lines { get; private set; }

        public CodeModule(List<string> lines)
        {
            Lines = lines;
        }
    }

    // Quick fix implementation to suppress a specific code inspection warning
    public class SuppressInspectionQuickFix : QuickFixBase
    {
        private readonly CodeModule _module;
        private readonly CodeSelection _selection;
        private readonly string _inspectionName;
        private const string AnnotationMarker = "'@SuppressWarning:";

        // Initializes the quick fix with provided code module, selection and inspection name.
        public SuppressInspectionQuickFix(CodeModule module, CodeSelection selection, string inspectionName)
        {
            _module = module ?? throw new ArgumentNullException(nameof(module));
            _selection = selection ?? throw new ArgumentNullException(nameof(selection));
            _inspectionName = inspectionName ?? throw new ArgumentNullException(nameof(inspectionName));
        }

        // Overridden method that applies the corrective fix
        public override void Fix()
        {
            // Determine the insertion index (0-indexed)
            int insertionIndex = _selection.LineNumber - 1;

            // Determine if preceding line already has an annotation comment.
            int annotationLineIndex = insertionIndex - 1;
            if (annotationLineIndex >= 0)
            {
