    // Base test fixture class from the unit testing framework.
    public class BaseTestFixture
    {
        public virtual void OneTimeSetUp() { }
        public virtual void OneTimeTearDown() { }
    }

    // Reflective helper to retrieve methods with specific attributes.
    public static class ReflectionHelper
    {
        public static MethodInfo[] GetMethodsByAttribute(Type type, Type attributeType)
        {
            return Array.FindAll(
                type.GetMethods(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic),
                method => method.GetCustomAttributes(attributeType, true).Length > 0);
        }
    }

    // Specialized test fixture that extends BaseTestFixture.
    public class SpecializedTestFixture : BaseTestFixture
    {
        private Type testClassType;
        private MethodInfo[] fixtureSetUpMethods;
        private MethodInfo[] fixtureTearDownMethods;
        private MethodInfo[] testSetUpMethods;
        private MethodInfo[] testTearDownMethods;

        // Result object that tracks assertion counts.
        public class TestResult
        {
            public int AssertionCount { get; set; }
        }

        public TestResult Result { get; private set; }

        public SpecializedTestFixture(Type testClassType)
        {
            this.testClassType = testClassType;
            Result = new TestResult();
            InitializeLifecycleMethods();
        }

        private void InitializeLifecycleMethods()
        {
            fixtureSetUpMethods = ReflectionHelper.GetMethodsByAttribute(testClassType, typeof(OneTimeSetUpAttribute));
            fixtureTearDownMethods = ReflectionHelper.GetMethodsByAttribute(testClassType, typeof(OneTimeTearDownAttribute));
            testSetUpMethods = ReflectionHelper.GetMethodsByAttribute(testClassType, typeof(SetUpAttribute));
            testTearDownMethods = ReflectionHelper.GetMethodsByAttribute(testClassType, typeof(TearDownAttribute));
        }

        public override void OneTimeSetUp()
        {
            base.OneTimeSetUp();
            foreach (var method in fixtureSetUpMethods)
            {
                ExecuteMethod(method);
            }
