public class Character : MonoBehaviour
{
    [SerializeField] private float movementSpeed = 5f;
    [SerializeField] private string baseSpritePath = "Characters/DefaultSprite";
    [SerializeField] private string modSpritePath = "Mods/CharacterSprites";

    private SpriteRenderer spriteRenderer;
    private Sprite currentSprite;
    private Vector3 movement;
    private bool isModEnabled = false;

    private void Awake()
    {
        spriteRenderer = GetComponent<SpriteRenderer>();
        LoadInitialSprite();
    }

    private void LoadInitialSprite()
    {
        try
        {
            currentSprite = LoadSprite(baseSpritePath);
            spriteRenderer.sprite = currentSprite;
        }
        catch (System.Exception e)
        {
            Debug.LogError($"Failed to load base sprite: {e.Message}");
        }
    }

    private Sprite LoadSprite(string path)
    {
        #if UNITY_EDITOR
            return Resources.Load<Sprite>(path);
        #else
            return LoadCrossplatformSprite(path);
        #endif
    }

    private Sprite LoadCrossplatformSprite(string path)
    {
        Sprite loadedSprite = null;

        if (isModEnabled)
        {
            string modPath = Path.Combine(Application.persistentDataPath, modSpritePath);
            loadedSprite = LoadModSprite(modPath);
        }

        return loadedSprite ?? Resources.Load<Sprite>(path);
    }

    private Sprite LoadModSprite(string modPath)
    {
        if (Directory.Exists(modPath))
        {
            string[] spriteFiles = Directory.GetFiles(modPath, "*.png");
            if (spriteFiles.Length > 0)
            {
                byte[] spriteBytes = File.ReadAllBytes(spriteFiles[0]);
                Texture2D texture = new Texture2D(2, 2);
                texture.LoadImage(spriteBytes);
                return Sprite.Create(texture, new Rect(0, 0, texture.width, texture.height), new Vector2(0.5f, 0.5f));
            }
        }
        return null;
    }

    private void Update()
    {
        HandleMovementInput();
        UpdateCharacterPosition();
    }

    private void HandleMovementInput()
    {
        float horizontalInput = Input.GetAxis("Horizontal");
        float verticalInput = Input.GetAxis("Vertical");
        movement = new Vector3(horizontalInput, verticalInput, 0).normalized;
    }

    private void UpdateCharacterPosition()
    {
        transform.position += movement * movementSpeed * Time.deltaTime;
    }

