    private const int BONUS_STRENGTH = 3;
    private const int BONUS_MANA = 2;

    private const float FIRE_RESISTANCE = 0.10f;
    private const float WATER_RESISTANCE = 0.15f;
    private const float EARTH_RESISTANCE = 0.20f;
    private const float WIND_RESISTANCE = 0.05f;

    public override string Label => "Darden's Dragon Turtle Hide Helm";
    public override float Weight => BASE_WEIGHT;

    public int StrengthBonus { get; private set; }
    public int ManaBonus { get; private set; }
    public float FireResistance { get; private set; }
    public float WaterResistance { get; private set; }
    public float EarthResistance { get; private set; }
    public float WindResistance { get; private set; }

    public DardensDragonTurtleHideHelm()
    {
        StrengthBonus = BONUS_STRENGTH;
        ManaBonus = BONUS_MANA;
        FireResistance = FIRE_RESISTANCE;
        WaterResistance = WATER_RESISTANCE;
        EarthResistance = EARTH_RESISTANCE;
        WindResistance = WIND_RESISTANCE;
    }

    public void Serialize(string filePath)
    {
        IFormatter formatter = new BinaryFormatter();
        using (Stream stream = new FileStream(filePath, FileMode.Create, FileAccess.Write))
        {
            formatter.Serialize(stream, this);
        }
    }

    public static DardensDragonTurtleHideHelm Deserialize(string filePath)
    {
        IFormatter formatter = new BinaryFormatter();
        using (Stream stream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
        {
            return (DardensDragonTurtleHideHelm)formatter.Deserialize(stream);
        }
    }

    public void DisplayStats()
    {
