        Console.WriteLine($"Weight: {Weight}");
        Console.WriteLine($"Strength Bonus: {StrengthBonus}");
        Console.WriteLine($"Mana Bonus: {ManaBonus}");
        Console.WriteLine($"Fire Resistance: {FireResistance * 100}%");
        Console.WriteLine($"Water Resistance: {WaterResistance * 100}%");
        Console.WriteLine($"Earth Resistance: {EarthResistance * 100}%");
        Console.WriteLine($"Wind Resistance: {WindResistance * 100}%");
    }
}

