var months = new List<string> {
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"
};
 
public class Birthday
{
    public int month;
    public int day;
 
    public override string ToString() => $"{months[month - 1]} {day}";
 
    public bool monthUniqueIn(List<Birthday> bds) => bds.Count(x => this.month == x.month) == 1;
 
    public bool dayUniqueIn(List<Birthday> bds) => bds.Count(x => this.day == x.day) == 1;
 
    public bool monthWithUniqueDayIn(List<Birthday> bds) => bds.Any(x => (this.month == x.month) && x.dayUniqueIn(bds));
}
 
public static void Main(string[] args)
{
    var choices = new List<Birthday> {
        new Birthday { month = 5, day = 15 }, new Birthday { month = 5, day = 16 }, new Birthday { month = 5, day = 19 }, new Birthday { month = 6, day = 17 },
        new Birthday { month = 6, day = 18 }, new Birthday { month = 7, day = 14 }, new Birthday { month = 7, day = 16 }, new Birthday { month = 8, day = 14 },
        new Birthday { month = 8, day = 15 }, new Birthday { month = 8, day = 17 }
    };
 
    // Albert knows the month but doesn't know the day.
    // So the month can't be unique within the choices.
    var filtered = choices.Where(x =>!x.monthUniqueIn(choices)).ToList();
 
    // Albert also knows that Bernard doesn't know the answer.
    // So the month can't have a unique day.
    filtered = filtered.Where(x =>!x.monthWithUniqueDayIn(filtered)).ToList();
 
    // Bernard now knows the answer.
    // So the day must be unique within the remaining choices.
    filtered = filtered.Where(x => x.dayUniqueIn(filtered)).ToList();
 
    // Albert now knows the answer too.
    // So the month must be unique within the remaining choices.
    filtered = filtered.Where(x => x.monthUniqueIn(filtered)).ToList();
 
    if (filtered.Count == 1)
        Console.WriteLine($"Cheryl's birthday is {filtered[0]}");
    else
        Console.WriteLine("Something went wrong!");
}

