using System;
using System.IO;
using System.Linq;
using System.Reflection;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Scripting;
using Microsoft.CodeAnalysis.Scripting.Hosting;

public class CSharpCompiler
{
    public virtual void Compile(string code) { /* Base compile logic */ }
}

public class CSharpInteractiveCompiler : CSharpCompiler
{
    private string responseFile;
    private string baseDirectory;
    private string analyzerLoader;

    public CSharpInteractiveCompiler(string responseFile, string baseDirectory, string analyzerLoader)
    {
        this.responseFile = responseFile;
        this.baseDirectory = baseDirectory;
        this.analyzerLoader = analyzerLoader;
    }

    public void PrintLogo()
    {
        Console.WriteLine("C# Interactive Compiler v1.0");
        Console.WriteLine("Powered by Roslyn.");
    }

    public void PrintHelp()
    {
        Console.WriteLine("Help Instructions:");
        Console.WriteLine("1. Type your C# code and press Enter to execute.");
        Console.WriteLine("2. Use 'exit' to terminate the session.");
    }

    public string GetAssemblyFileVersion()
    {
        var version = Assembly.GetExecutingAssembly().GetName().Version;
        return version.ToString();
    }

    public MetadataReferenceResolver GetCommandLineMetadataReferenceResolver()
    {
        return new MetadataReferenceResolver(baseDirectory);
    }

    public override void Compile(string code)
    {
        var scriptOptions = ScriptOptions.Default
            .WithReferences(AppDomain.CurrentDomain.GetAssemblies()
                .Where(a => !a.IsDynamic)
                .Select(a => MetadataReference.CreateFromFile(a.Location)))
            .WithImports("System", "System.Collections.Generic");

        Script.Compile(code, scriptOptions).GetCompilation();
    }

    public void Execute(string code)
    {
        try
        {
            var script = CSharpScript.Create(code, GetCommandLineMetadataReferenceResolver());
            var result = script.RunAsync().Result;
            Console.WriteLine("Execution Result: " + result.ReturnValue);
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error during execution: " + ex.Message);
        }
    }

    public void Start()
    {
        PrintLogo();
        PrintHelp();

        string input;
        while ((input = Console.ReadLine()) != "exit")
        {
            Compile(input);
            Execute(input);
        }
    }
}

