    public static class ArrayExtensions
    {
        public static T[] Shuffle<T>(this T[] array)
        {
            Random random = new Random();
            int n = array.Length;
            while (n > 1)
            {
                int k = random.Next(n--);
                T temp = array[n];
                array[n] = array[k];
                array[k] = temp;
            }
            return array;
        }
 
        public static T[] PancakeSort<T>(this T[] array) where T : IComparable<T>
        {
            int numFlips = 0;
            for (int endIdx = array.Length - 1; endIdx > 0; endIdx--)
            {
                T max = array.Take(endIdx + 1).Max();
                int maxIdx = Array.IndexOf(array, max);
                if (maxIdx == endIdx) continue;
                if (maxIdx > 0)
                {
                    array = array.Take(maxIdx + 1).Reverse().Concat(array.Skip(maxIdx + 1)).ToArray();
                    numFlips++;
                    Console.WriteLine(string.Format("{0}: {1}", numFlips, string.Join(",", array)));
                }
                array = array.Take(endIdx + 1).Reverse().Concat(array.Skip(endIdx + 1)).ToArray();
                numFlips++;
                Console.WriteLine(string.Format("{0}: {1}", numFlips, string.Join(",", array)));
            }
            return array;
        }
    }
}

