namespace PubSubComponent
{
    // A simple delegate for message events.
    public delegate void MessageReceivedHandler(string message);

    // The MessageBroker class facilitates publish/subscribe functionality.
    public class MessageBroker
    {
        // An event to notify subscribers about a new message.
        public event MessageReceivedHandler MessageReceived;

        // Publishes a message to all subscribers.
        public void Publish(string message)
        {
            Console.WriteLine("Publishing message: " + message);
            // Safely invoke the event.
            MessageReceived?.Invoke(message);
        }

        // Subscribes a new listener to the message notification.
        public void Subscribe(MessageReceivedHandler handler)
        {
            Console.WriteLine("Subscriber added.");
            MessageReceived += handler;
        }
    }

    // An example subscriber that handles messages.
    internal class MessageSubscriber
    {
        // Method to handle incoming messages.
        public void OnMessageReceived(string message)
        {
            Console.WriteLine("Subscriber received: " + message);
        }
    }

    // The Sorter class demonstrates publish/subscribe usage.
    public class Sorter
    {
        public static void Main(string[] args)
        {
            MessageBroker broker = new MessageBroker();
            MessageSubscriber subscriber = new MessageSubscriber();

            // Register the subscriber's event handler.
            broker.Subscribe(subscriber.OnMessageReceived);

            // Publish a couple of messages.
            broker.Publish("Hello, world!");
            broker.Publish("Publish/Subscribe messaging in .NET.");

