public static class TestsToRun
{
    private static readonly List<Action> testActions = new List<Action>();

    public static void LoadTests(Assembly assembly)
    {
        var testClasses = assembly.GetTypes()
            .Where(t => t.GetCustomAttribute<TestClassAttribute>() != null);

        foreach (var testClass in testClasses)
        {
            var testMethods = GetMethods(testClass);
            testActions.AddRange(testMethods);
        }
    }

    private static IEnumerable<Action> GetMethods(Type testClass)
    {
        return testClass.GetMethods(BindingFlags.Public | BindingFlags.Instance)
            .Where(m => m.GetCustomAttribute<FactAttribute>() != null
                        && m.GetCustomAttribute<LongRunningAttribute>() == null)
            .Select(method => CreateTestAction(testClass, method));
    }

    private static Action CreateTestAction(Type testClass, MethodInfo method)
    {
        return () =>
        {
            using (var instance = (IDisposable)Activator.CreateInstance(testClass))
            {
                method.Invoke(instance, null);
            }
        };
    }

    public static void RunTests()
    {
        foreach (var testAction in testActions)
        {
            try
            {
                testAction.Invoke();
                Console.WriteLine($"Test {testAction.Method.DeclaringType.Name}.{testAction.Method.Name} passed.");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Test {testAction.Method.DeclaringType.Name}.{testAction.Method.Name} failed: {ex.Message}");
            }
        }
    }
}

