using System;
using System.Collections.Generic;

public class Node
{
    public int Value { get; set; }
    public Node Next { get; set; }

    public Node(int value)
    {
        Value = value;
        Next = null;
    }
}

public class Order
{
    private Node head;

    public void Insert(int value)
    {
        Node newNode = new Node(value);
        if (head == null)
        {
            head = newNode;
            return;
        }

        Node current = head;
        while (current.Next != null)
        {
            current = current.Next;
        }
        current.Next = newNode;
    }

    public void RemoveDuplicates()
    {
        if (head == null) return;

        HashSet<int> seenValues = new HashSet<int>();
        Node current = head;
        Node prev = null;

        while (current != null)
        {
            if (seenValues.Contains(current.Value))
            {
                prev.Next = current.Next; // Remove the current node
            }
            else
            {
                seenValues.Add(current.Value);
                prev = current; // Move prev pointer
            }
            current = current.Next; // Move to next node
        }
    }

    public void Display()
    {
        Node current = head;
        if (current == null)
        {
            Console.WriteLine("The list is empty.");
            return;
        }

        Console.Write("Unique elements in the linked list: ");
        while (current != null)
        {
            Console.Write(current.Value + " ");
            current = current.Next;
        }
        Console.WriteLine();
    }

    public static void Main(string[] args)
    {
        Order linkedList = new Order();

        Console.WriteLine("Enter integers for the linked list (enter 'done' to finish):");

        while (true)
        {
            string input = Console.ReadLine();
            if (input.ToLower() == "done")
                break;

            if (int.TryParse(input, out int value))
            {
                linkedList.Insert(value);
            }
            else
            {
                Console.WriteLine("Please enter a valid integer.");
            }
        }

        Console.WriteLine("Original linked list:");
        linkedList.Display();

        linkedList.RemoveDuplicates();

        Console.WriteLine("Linked list after removing duplicates:");
        linkedList.Display();
    }
}

