namespace PierpontPrimes
{
    class Processor
    {
        static void Main(string[] args)
        {
            int n = 50, m = 250;
            Console.WriteLine("First {0} Pierpont primes of the first kind:", n);
            PrintColumns(PierpontPrimes(1).Take(n).ToArray(), 10);
            Console.WriteLine("{0}th Pierpont prime of the first kind: {1}", m, PierpontPrimes(1).Take(m).Last());
            Console.WriteLine();
            Console.WriteLine("First {0} Pierpont primes of the second kind:", n);
            PrintColumns(PierpontPrimes(-1).Take(n).ToArray(), 10);
            Console.WriteLine("{0}th Pierpont prime of the second kind: {1}", m, PierpontPrimes(-1).Take(m).Last());
            Console.ReadLine();
        }
 
        static IEnumerable<BigInteger> PierpontPrimes(int num)
        {
            return SmoothGenerator(new BigInteger[] { 2, 3 }).Select(x => x + num).Where(x => x.IsProbablyPrime());
        }
 
        static IEnumerable<BigInteger> SmoothGenerator(BigInteger[] ar)
        {
            var nextSmooth = 1;
            var queues = ar.Select(x => new { x, queue = new Queue<BigInteger>() }).ToArray();
            while (true)
            {
                yield return nextSmooth;
                foreach (var queue in queues)
                {
                    queue.queue.Enqueue(nextSmooth * queue.x);
                }
                nextSmooth = queues.Select(x => x.queue.Peek()).Min();
                foreach (var queue in queues)
                {
                    if (queue.queue.Peek() == nextSmooth)
                    {
                        queue.queue.Dequeue();
                    }
                }
            }
        }
 
        static void PrintColumns(BigInteger[] ar, int n)
        {
            for (int i = 0; i < ar.Length; i += n)
            {
                for (int j = 0; j < n; j++)
                {
                    Console.Write("{0,10}", ar[i + j]);
                }
                Console.WriteLine();
            }
        }
    }
}

