public abstract class XmlRpcRequest
{
    public abstract string MethodName { get; }
    public abstract object[] Parameters { get; }
}

public class SingleXmlRpcRequest : XmlRpcRequest
{
    private string method;
    private object[] parameters;

    public SingleXmlRpcRequest(string method, params object[] parameters)
    {
        this.method = method;
        this.parameters = parameters;
    }

    public override string MethodName => method;
    public override object[] Parameters => parameters;
}

public class MultiCallRequest : XmlRpcRequest
{
    // Internal collection to store individual XML-RPC requests
    private List<XmlRpcRequest> requests = new List<XmlRpcRequest>();

    // Adds a new individual request to the collection
    public void Add(XmlRpcRequest request)
    {
        requests.Add(request);
    }

    // Fixed identifier for the XML-RPC multicall method
    public override string MethodName => "system.multicall";

    // Aggregates individual requests into a single array of parameters
    public override object[] Parameters
    {
        get
        {
            var callList = new List<Dictionary<string, object>>();
            // Clear previous aggregated data and rebuild the parameter list
            foreach (var req in requests)
            {
                var call = new Dictionary<string, object>
                {
                    { "methodName", req.MethodName },
                    { "params", req.Parameters }
                };
                callList.Add(call);
            }
            // The multicall method accepts a single parameter: the array of calls.
            return new object[] { callList.ToArray() };
        }
    }
}

