    // This class models a single combinatorial dimension by encapsulating
    // a named collection of immutable test values.
    public class CombinatorialDimension
    {
        private readonly string _name;
        private readonly ReadOnlyCollection<object> _values;

        /// <summary>
        /// Initializes a new instance of the CombinatorialDimension class.
        /// Validates the provided name and values and converts the values
        /// into an immutable list.
        /// </summary>
        /// <param name="name">The textual identifier for the dimension.</param>
        /// <param name="values">An enumerable collection of items representing test values.</param>
        public CombinatorialDimension(string name, IEnumerable<object> values)
        {
            // Validate that the name is neither null nor empty.
            ExceptionUtilities.CheckArgumentNotNullOrEmpty(name, nameof(name));

            // Validate that the collection of values is provided.
            ExceptionUtilities.CheckArgumentNotNull(values, nameof(values));

            // Set the name.
            _name = name;

            // Convert the enumerable collection into a list and wrap it as a read-only collection.
            _values = new List<object>(values).AsReadOnly();
        }

        /// <summary>
        /// Gets the name of the combinatorial dimension.
        /// </summary>
