using System.Collections.Generic;
using System.Linq;
using BenchmarkDotNet.Analysers;
using BenchmarkDotNet.Engines;
using BenchmarkDotNet.Environments;
using BenchmarkDotNet.Mathematics;
using BenchmarkDotNet.Reports;

public class ZeroMeasurementAnalyser : IAnalyser
{
    private const double FallbackResolutionNs = 1.0;
    private const double SigmaThreshold = 3.0;

    public IEnumerable<Conclusion> Analyze(Summary summary)
    {
        foreach (var report in summary.Reports)
        {
            var workload = GetSamples(report, false);
            var overhead = GetSamples(report, true);

            if (!workload.Any()) continue;

            var workloadStats = CalculateStats(workload);
            if (overhead.Any())
            {
                var overheadStats = CalculateStats(overhead);
                if (HasEquivalentMeans(workloadStats, overheadStats))
                    yield return CreateWarning(report, "Workload statistically indistinguishable from overhead");
            }
            else
            {
                var resolution = GetSystemResolution(report);
                if (workloadStats.Mean < SigmaThreshold * resolution)
                    yield return CreateWarning(report, $"Workload mean ({workloadStats.Mean:n1}ns) below precision threshold ({SigmaThreshold * resolution:n1}ns)");
            }
        }
    }

    private List<double> GetSamples(BenchmarkReport report, bool isOverhead)
    {
        return report.AllRuns
            .Where(r => r.IsOverhead == isOverhead)
            .SelectMany(r => r.Measurements)
            .Select(m => m.Nanoseconds)
            .ToList();
    }

    private Statistics CalculateStats(List<double> samples)
    {
        return new Statistics(samples.RemoveOutliers());
    }

    private bool HasEquivalentMeans(Statistics a, Statistics b)
    {
        return new WelchTTest(a, b).GetConfidenceInterval(0.95).Contains(0);
    }

    private double GetSystemResolution(BenchmarkReport report)
    {
        var cpuFreq = report.BenchmarkCase.Job.Environment.Cpu?.Frequency ?? 0;
        return cpuFreq > 0 ? 1e9 / cpuFreq : FallbackResolutionNs;
    }

    private Conclusion CreateWarning(BenchmarkReport report, string message)
    {
        return Conclusion.CreateWarning($"{report.BenchmarkCase.Descriptor.DisplayInfo}: {message}");
    }
}

