namespace SQLiteDatabaseUtility
{
    /// <summary>
    /// Provides basic SQLite database management functionalities such as
    /// creating new database files and executing SQL commands.
    /// </summary>
    public class DatabaseManager
    {
        /// <summary>
        /// Creates a new SQLite database file at the specified file path.
        /// </summary>
        /// <param name="dbFilePath">Full path to the new SQLite database file.</param>
        public static void CreateDB(string dbFilePath)
        {
            // Check if file already exists to avoid overwriting.
            if (File.Exists(dbFilePath))
            {
                Console.WriteLine("Database file already exists: " + dbFilePath);
                return;
            }

            try
            {
                // Create the SQLite database file.
                SQLiteConnection.CreateFile(dbFilePath);
                Console.WriteLine("Database created successfully at: " + dbFilePath);
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error creating database file: " + ex.Message);
            }
        }

        /// <summary>
        /// Executes a given SQL command on the SQLite database using the provided connection string.
        /// </summary>
        /// <param name="connectionString">The connection string to the SQLite database.</param>
        /// <param name="sqlQuery">The SQL query/command to execute.</param>
        public static void ExecuteSql(string connectionString, string sqlQuery)
        {
            try
            {
                // Open the connection using a "using" block to ensure proper disposal.
                using (SQLiteConnection connection = new SQLiteConnection(connectionString))
                {
                    connection.Open();

                    // Create a command object with the provided SQL query.
                    using (SQLiteCommand command = new SQLiteCommand(sqlQuery, connection))
                    {
                        // Execute the SQL command. Use ExecuteNonQuery for commands that do not return results.
                        int result = command.ExecuteNonQuery();
                        Console.WriteLine("SQL executed successfully. Rows affected: " + result);
                    }

                    connection.Close();
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error executing SQL command: " + ex.Message);
            }

 
