namespace RamerDouglasPeucker
{
    class Generator
    {
        public class Point
        {
            public double X { get; set; }
            public double Y { get; set; }
 
            public Point(double x, double y)
            {
                X = x;
                Y = y;
            }
 
            public override string ToString()
            {
                return $"({X}, {Y})";
            }
        }
 
        static double PerpendicularDistance(Point pt, Point lineStart, Point lineEnd)
        {
            double dx = lineEnd.X - lineStart.X;
            double dy = lineEnd.Y - lineStart.Y;
 
            // Normalize
            double mag = Math.Sqrt(dx * dx + dy * dy);
            if (mag > 0.0)
            {
                dx /= mag;
                dy /= mag;
            }
            double pvx = pt.X - lineStart.X;
            double pvy = pt.Y - lineStart.Y;
 
            // Get dot product (project pv onto normalized direction)
            double pvdot = dx * pvx + dy * pvy;
 
            // Scale line direction vector and substract it from pv
            double ax = pvx - pvdot * dx;
            double ay = pvy - pvdot * dy;
 
            return Math.Sqrt(ax * ax + ay * ay);
        }
 
        static void RamerDouglasPeucker(List<Point> pointList, double epsilon, List<Point> outPoints)
        {
            if (pointList.Count < 2) throw new ArgumentException("Not enough points to simplify");
 
            // Find the point with the maximum distance from line between start and end
            double dmax = 0.0;
            int index = 0;
            int end = pointList.Count - 1;
            for (int i = 1; i < end; i++)
            {
                double d = PerpendicularDistance(pointList[i], pointList[0], pointList[end]);
                if (d > dmax)
                {
                    index = i;
                    dmax = d;
                }
            }
 
            // If max distance is greater than epsilon, recursively simplify
            if (dmax > epsilon)
            {
                var recResults1 = new List<Point>();
                var recResults2 = new List<Point>();
                var firstLine = pointList.Take(index + 1).ToList();
                var lastLine = pointList.Skip(index).ToList();
                RamerDouglasPeucker(firstLine, epsilon, recResults1);
                RamerDouglasPeucker(lastLine, epsilon, recResults2);
 
                // build the result list

