namespace MyWebApp.Authentication
{
    // ActionResult for facilitating external authentication.
    public class ExternalLoginResult : ActionResult
    {
        public string Provider { get; private set; }
        public string ReturnUrl { get; private set; }

        public ExternalLoginResult(string provider, string returnUrl)
        {
            if (string.IsNullOrEmpty(provider))
            {
                throw new ArgumentException("Provider must not be empty.", nameof(provider));
            }
            if (string.IsNullOrEmpty(returnUrl))
            {
                throw new ArgumentException("ReturnUrl must not be empty.", nameof(returnUrl));
            }
            Provider = provider;
            ReturnUrl = returnUrl;
        }

        public override void ExecuteResult(ControllerContext context)
        {
            if (context == null)
            {
                throw new ArgumentNullException(nameof(context));
            }

            // Initiate the external authentication process.
            OAuthWebSecurity.RequestAuthentication(Provider, ReturnUrl);
        }
    }

    // Controller demonstrating the usage of ExternalLoginResult.
    public class AccountController : Controller
    {
        // GET: /Account/ExternalLogin
        public ActionResult ExternalLogin(string provider, string returnUrl)
        {
            if (string.IsNullOrEmpty(provider))
            {
                return new HttpStatusCodeResult(400, "Bad Request: Provider missing.");
            }
            if (string.IsNullOrEmpty(returnUrl))
            {
                return new HttpStatusCodeResult(400, "Bad Request: ReturnUrl missing.");
            }

            // Return the custom action result to trigger external authentication.
            return new ExternalLoginResult(provider, returnUrl);
        }

        // Callback after external authentication.
        public ActionResult ExternalLoginCallback()
        {
            // Process user information here after a successful external login.
            return View();
        }

        // Action to sign out the user.
        public ActionResult LogOff()
        {
            // Sign out logic would be implemented here.
            return RedirectToAction("Index", "Home");
        }
    }

