namespace MultiplicativeOrder {
    // Taken from https://stackoverflow.com/a/33918233
    public static class PrimeExtensions {
        // Random generator (thread safe)
        private static ThreadLocal<Random> s_Gen = new ThreadLocal<Random>(
          () => {
              return new Random();
          }
        );
 
        // Random generator (thread safe)
        private static Random Gen {
            get {
                return s_Gen.Value;
            }
        }
 
        public static bool IsProbablyPrime(this BigInteger value, int witnesses = 10) {
            if (value <= 1)
                return false;
 
            if (witnesses <= 0)
                witnesses = 10;
 
            BigInteger d = value - 1;
            int s = 0;
 
            while (d % 2 == 0) {
                d /= 2;
                s += 1;
            }
 
            byte[] bytes = new byte[value.ToByteArray().LongLength];
            BigInteger a;
 
            for (int i = 0; i < witnesses; i++) {
                do {
                    Gen.NextBytes(bytes);
 
                    a = new BigInteger(bytes);
                }
                while (a < 2 || a >= value - 2);
 
                BigInteger x = BigInteger.ModPow(a, d, value);
                if (x == 1 || x == value - 1)
                    continue;
 
                for (int r = 1; r < s; r++) {
                    x = BigInteger.ModPow(x, 2, value);
 
                    if (x == 1)
                        return false;
                    if (x == value - 1)
                        break;
                }
 
                if (x != value - 1)
                    return false;
            }
 
            return true;
        }
    }
 
    static class Helper {
        public static BigInteger Sqrt(this BigInteger self) {
            BigInteger b = self;
            while (true) {
                BigInteger a = b;
                b = self / a + a >> 1;
                if (b >= a) return a;
            }
        }
 
        public static long BitLength(this BigInteger self) {
            BigInteger bi = self;
            long bitlength = 0;
            while (bi != 0) {
                bitlength++;
                bi >>= 1;
            }
            return bitlength;
        }
 
        public static bool BitTest(this BigInteger self, int pos) {
            byte[] arr = self.ToByteArray();
            int idx = pos / 8;
            int mod = pos % 8;
            if (idx >= arr.Length) {

