public interface IDatabaseObjectScriptEngine
{
    IEnumerable<string> Script(Database database);
}

public class DatabaseObjectScripter
{
    private readonly IEnumerable<IDatabaseObjectScriptEngine> _engines;

    public DatabaseObjectScripter(IEnumerable<IDatabaseObjectScriptEngine> engines = null)
    {
        _engines = engines ?? GetDefaultEngines(new Server());
    }

    public IEnumerable<string> Script(string databaseName)
    {
        var server = new Server();
        var database = server.Databases[databaseName];
        var scripts = new List<string>();

        foreach (var engine in _engines)
        {
            scripts.AddRange(engine.Script(database));
        }

        return scripts;
    }

    private IEnumerable<IDatabaseObjectScriptEngine> GetDefaultEngines(Server server)
    {
        return new List<IDatabaseObjectScriptEngine>
        {
            new AssemblyScriptEngine(),
            new RoleScriptEngine(),
            new SchemaScriptEngine(),
            new ServiceBrokerContractScriptEngine(),
            new ServiceBrokerMessageTypeScriptEngine(),
            new ServiceBrokerQueueScriptEngine(),
            new ServiceBrokerRouteScriptEngine(),
            new ServiceBrokerServiceScriptEngine(),
            new UserScriptEngine()
        };
    }
}

public class AssemblyScriptEngine : IDatabaseObjectScriptEngine
{
    public IEnumerable<string> Script(Database database)
    {
        return database.Assemblies.Cast<Assembly>().Select(a => a.Script().ToString());
    }
}

public class RoleScriptEngine : IDatabaseObjectScriptEngine
{
    public IEnumerable<string> Script(Database database)
    {
        return database.Roles.Cast<DatabaseRole>().Select(r => r.Script().ToString());
    }
}

public class SchemaScriptEngine : IDatabaseObjectScriptEngine
{
    public IEnumerable<string> Script(Database database)
    {
        return database.Schemas.Cast<Schema>().Select(s => s.Script().ToString());
    }
}

public class ServiceBrokerContractScriptEngine : IDatabaseObjectScriptEngine
{
    public IEnumerable<string> Script(Database database)
    {
        return database.ServiceBroker.Contracts.Cast<ServiceContract>().Select(c => c.Script().ToString());
    }
}

public class ServiceBrokerMessageTypeScriptEngine : IDatabaseObjectScriptEngine
{
    public IEnumerable<string> Script(Database database)
    {
        return database.ServiceBroker.MessageTypes.Cast<MessageType>().Select(m => m.Script().ToString());
    }
}

