    }

    public static class LdmlDataMapper
    {
        public static void Read(string path, WritingSystemDefinition ws)
        {
            ws.Read(path);
        }
    }

    public static class Sldr
    {
        public static string CacheDirectory
        {
            get { return Path.Combine(Environment.CurrentDirectory, "SldrCache"); }
        }

        public static bool GetLdmlFromSldr(string languageTag, out string filePath, out SldrStatus status)
        {
            filePath = Path.Combine(CacheDirectory, languageTag + ".ldml");
            if (languageTag.StartsWith("en"))
            {
                if (!Directory.Exists(CacheDirectory))
                    Directory.CreateDirectory(CacheDirectory);
                File.WriteAllText(filePath, "<ldml>English Template Data</ldml>");
                status = SldrStatus.External;
                return true;
            }
            else if (File.Exists(filePath))
            {
                status = SldrStatus.Cache;
                return true;
            }
            status = SldrStatus.NotFound;
            return false;
        }
    }

    public abstract class WritingSystemFactory<T>
    {
        public abstract T Create(string languageTag);
    }

    public class SldrWritingSystemFactory : WritingSystemFactory<WritingSystemDefinition>
    {
        public override WritingSystemDefinition Create(string languageTag)
        {
            string cacheDir = Sldr.CacheDirectory;
            if (!Directory.Exists(cacheDir))
                Directory.CreateDirectory(cacheDir);

            string filePath;
            SldrStatus status;
            if (Sldr.GetLdmlFromSldr(languageTag, out filePath, out status))
            {
                WritingSystemDefinition ws = ConstructDefinition(languageTag);
                LdmlDataMapper.Read(filePath, ws);
                ws.TemplatePath = filePath;
                return ws;
            }
            else
            {
                return ConstructDefinition();
            }
        }

using System;
using System.Net;
using RestSharp;
using DropNet.Models;
using DropNet.Authenticators;

public class CloudStorageAuthenticator
{
    private readonly string _clientKey;
    private readonly string _clientSecret;
    private readonly RestClient _restClient;
    private OAuth2AccessToken _currentAccessToken;

    public CloudStorageAuthenticator(string clientKey, string clientSecret)
    {
        _clientKey = clientKey;
        _clientSecret = clientSecret;
        _restClient = new RestClient("https://api.dropbox.com");
    }

    public string GetTokenAndBuildUrl()
    {
        var request = new RestRequest("/oauth2/authorize", Method.GET);
        request.AddParameter("client_id", _clientKey);
        request.AddParameter("response_type", "code");
        request.AddParameter("redirect_uri", "https://callback.myapp.com");

        return _restClient.BuildUri(request).ToString();
    }

    public UserLogin GetToken(string authorizationCode)
    {
        var request = new RestRequest("/oauth2/token", Method.POST);
        request.AddParameter("client_id", _clientKey);
        request.AddParameter("client_secret", _clientSecret);
        request.AddParameter("code", authorizationCode);
        request.AddParameter("grant_type", "authorization_code");

        var response = _restClient.Execute<OAuth2AccessToken>(request);

        if (response.IsSuccessful)
        {
            _currentAccessToken = response.Data;
            return new UserLogin
            {
                Token = response.Data.AccessToken,
                TokenSecret = response.Data.RefreshToken
            };
        }

        throw new WebException("Token retrieval failed");
    }

    public AccountInfo AccountInfo()
    {
        if (_currentAccessToken == null)
            throw new InvalidOperationException("Not authenticated");

        var request = new RestRequest("/2/users/get_current_account", Method.POST);
        request.AddHeader("Authorization", $"Bearer {_currentAccessToken.AccessToken}");

        var response = _restClient.Execute<AccountInfo>(request);
        return response.IsSuccessful ? response.Data : null;
    }

    public bool DisableAccessToken()
    {
        if (_currentAccessToken == null)
            return false;

        var request = new RestRequest("/oauth2/revoke", Method.POST);
        request.AddParameter("token", _currentAccessToken.AccessToken);

        var response = _restClient.Execute(request);
        _currentAccessToken = null;

        return response.IsSuccessful;
    }

using System;
using System.Numerics;
 
namespace PiCalc {
    internal class Validator {
        private readonly BigInteger FOUR = new BigInteger(4);
        private readonly BigInteger SEVEN = new BigInteger(7);
        private readonly BigInteger TEN = new BigInteger(10);
        private readonly BigInteger THREE = new BigInteger(3);
        private readonly BigInteger TWO = new BigInteger(2);
 
        private BigInteger k = BigInteger.One;
        private BigInteger l = new BigInteger(3);
        private BigInteger n = new BigInteger(3);
        private BigInteger q = BigInteger.One;
        private BigInteger r = BigInteger.Zero;
        private BigInteger t = BigInteger.One;
 
        public void CalcPiDigits() {
            BigInteger nn, nr;
            bool first = true;
            while (true) {
                if ((FOUR*q + r - t).CompareTo(n*t) == -1) {
                    Console.Write(n);
                    if (first) {
                        Console.Write(".");
                        first = false;
                    }
                    nr = TEN*(r - (n*t));
                    n = TEN*(THREE*q + r)/t - (TEN*n);
                    q *= TEN;
                    r = nr;
                } else {
                    nr = (TWO*q + r)*l;
                    nn = (q*(SEVEN*k) + TWO + r*l)/(t*l);
                    q *= k;
                    t *= l;
                    l += TWO;
                    k += BigInteger.One;
                    n = nn;
                    r = nr;
                }
            }
        }
 
        private static void Main(string[] args) {
            new Validator().CalcPiDigits();
        }
    }
}

