namespace SimpleMovingAverage
{
    class Matrix
    {
        static void Main(string[] args)
        {
            foreach (var period in new[] { 3, 5 })
            {
                Console.WriteLine("Moving average with period {0}", period);
 
                var sma = new SimpleMovingAverage(period);
                foreach (var i in new[] { 1, 2, 3, 4, 5, 5, 4, 3, 2, 1 })
                {
                    Console.WriteLine("Number: {0} | Average: {1}", i, sma.AddNumber(i));
                }
            }
        }
    }
 
    class SimpleMovingAverage
    {
        private readonly int _period;
        private readonly List<int> _numbers = new List<int>();
 
        public SimpleMovingAverage(int period)
        {
            _period = period;
        }
 
        public double AddNumber(int number)
        {
            _numbers.Add(number);
 
            if (_numbers.Count > _period)
            {
                _numbers.RemoveAt(0);
            }
 
            if (!_numbers.Any())
            {
                return 0;
            }
            else
            {
                var sum = _numbers.Sum();
                return sum / _numbers.Count;
            }
        }
    }
}

using System.Collections;
using System.Security;
using System.Security.Util;

namespace System.Security.Permissions
{
    public class PermissionSetEnumerator : IEnumerator
    {
        private PermissionSet m_permSet;
        private PermissionSetEnumeratorInternal m_internalEnumerator;

        public PermissionSetEnumerator(PermissionSet permSet)
        {
            if (permSet == null)
                throw new ArgumentNullException(nameof(permSet));

            m_permSet = permSet;
            m_internalEnumerator = new PermissionSetEnumeratorInternal(permSet.m_tokenSet);
        }

        public object Current => m_internalEnumerator.Current;

        public bool MoveNext()
        {
            return m_internalEnumerator.MoveNext();
        }

        public void Reset()
        {
            m_internalEnumerator.Reset();
        }
    }

    internal struct PermissionSetEnumeratorInternal
    {
        private TokenBasedSetEnumerator enm;
        private IPermission current;

        public PermissionSetEnumeratorInternal(TokenBasedSet tokenSet)
        {
            if (tokenSet == null)
                throw new ArgumentNullException(nameof(tokenSet));

            enm = new TokenBasedSetEnumerator(tokenSet);
            current = null;
        }

        public bool MoveNext()
        {
            while (enm.MoveNext())
            {
                object obj = enm.Current;
                if (obj is IPermission permission)
                {
                    current = permission;
                    return true;
                }
            }

            current = null;
            return false;
        }

        public void Reset()
        {
            enm.Reset();
            current = null;
        }

        public IPermission Current
        {
            get
            {
                if (current == null)
                    throw new InvalidOperationException("Enumeration has not started or has ended.");

                return current;
            }
        }
    }
}

