            {
                throw new ArgumentNullException(nameof(message));
            }

            var feedback = ParseFeedback(message);
            await _feedbackRepository.StoreFeedbackAsync(feedback, cancellationToken);

            var confirmationMessage = await GetAnswerAsync(_ratingConfirmation, cancellationToken);
            await _sender.SendMessageAsync(confirmationMessage, message.From, cancellationToken);
        }
        catch (Exception ex)
        {
            var failureMessage = await GetAnswerAsync(_ratingFailed, cancellationToken);
            await _sender.SendMessageAsync(failureMessage, message.From, cancellationToken);
            // Log the exception for further analysis
            Console.WriteLine($"Error processing message: {ex.Message}");
        }
