    private void InitializeTilesetTree()
    {
        advTree.Nodes.Clear();
        foreach (Tileset tileset in tilesets)
        {
            Node tilesetNode = CreateTilesetNode(tileset);
            advTree.Nodes.Add(tilesetNode);
        }
        advTree.NodeDoubleClick += node_NodeDoubleClick;
    }

    private Node CreateTilesetNode(Tileset tileset)
    {
        Node node = new Node(tileset.Name);
        node.Tag = tileset;
        node.Cells.Add(new Cell("Not Selected"));
        return node;
    }

    private void node_NodeDoubleClick(object sender, TreeNodeMouseEventArgs e)
    {
        Node selectedNode = e.Node;
        Tileset tileset = selectedNode.Tag as Tileset;

        if (fileDialog.ShowDialog() == DialogResult.OK)
        {
            string selectedFilePath = fileDialog.FileName;
            tilesetFilesList[tileset.Name] = selectedFilePath;
            UpdateNodeStatus(selectedNode, selectedFilePath);
            CheckLoadButtonStatus();
        }
    }

    private void UpdateNodeStatus(Node node, string filePath)
    {
        node.Cells[1].Text = System.IO.Path.GetFileName(filePath);
    }

    private void CheckLoadButtonStatus()
    {
        btnLoad.Enabled = tilesetFilesList.Count == tilesets.Count;
    }

    private void btnLoad_Click(object sender, EventArgs e)
    {
        if (tilesetFilesList.Count == tilesets.Count)
        {
            foreach (Tileset tileset in tilesets)
            {
                tileset.ImagePath = tilesetFilesList[tileset.Name];
            }
            DialogResult = DialogResult.OK;
            Close();
        }
    }

    private void btnCancel_Click(object sender, EventArgs e)
    {
        DialogResult = DialogResult.Cancel;
        Close();
    }
}

