using System;
using System.IO;
using System.Windows.Forms;
using System.Xml;
using gView.Framework.Data;
using gView.Framework.Metadata;

public class FormMetadata : Form
{
    private Metadata _metadata;
    private object _metadataObject;
    private TabControl _tabControl;

    public FormMetadata(Stream xmlStream, object metadataObject)
    {
        _metadataObject = metadataObject;
        LoadMetadata(xmlStream);
        InitializeComponent();
    }

    private void LoadMetadata(Stream xmlStream)
    {
        using (XmlReader reader = XmlReader.Create(xmlStream))
        {
            // Assume LoadFromXml is a method that initializes metadata from XML
            _metadata = MetadataFactory.LoadFromXml(reader);
        }
    }

    private void InitializeComponent()
    {
        this._tabControl = new TabControl();
        this.ClientSize = new System.Drawing.Size(800, 600);
        this.Controls.Add(_tabControl);
        this.Load += new EventHandler(this.FormMetadata_Load);
    }

    private void FormMetadata_Load(object sender, EventArgs e)
    {
        foreach (var provider in _metadata.Providers)
        {
            TabPage tabPage = new TabPage(provider.Name);
            Control propertyPage = CreatePropertyPage(provider);
            tabPage.Controls.Add(propertyPage);
            _tabControl.TabPages.Add(tabPage);
        }
    }

    private Control CreatePropertyPage(IMetadataProvider provider)
    {
        // Create a control for each provider's properties
        UserControl propertyPage = new UserControl();
        propertyPage.Dock = DockStyle.Fill;

        // Dynamic creation of controls based on provider's metadata
        foreach (var property in provider.Properties)
        {
            Label label = new Label
            {
                Text = property.Name,
                AutoSize = true
            };
            TextBox textBox = new TextBox
            {
                Text = property.Value,
                Dock = DockStyle.Top
            };

            propertyPage.Controls.Add(textBox);
            propertyPage.Controls.Add(label);
        }

        return propertyPage;
    }

    public Stream GenerateXmlStream()
    {
        MemoryStream memoryStream = new MemoryStream();
        using (XmlWriter writer = XmlWriter.Create(memoryStream))
        {
            // Assume SaveToXml is a method that writes metadata to XML
            _metadata.SaveToXml(writer);
        }
        memoryStream.Position = 0;
        return memoryStream;
    }
}

using System;
using System.Linq;
using System.Collections.Generic;
 
public struct Card
{
    public Card(string rank, string suit) : this()
    {
        Rank = rank;
        Suit = suit;
    }
 
    public string Rank { get; }
    public string Suit { get; }
 
    public override string ToString() => $"{Rank} of {Suit}";
}
 
public class Deck : IEnumerable<Card>
{
    static readonly string[] ranks = { "Two", "Three", "Four", "Five", "Six",
        "Seven", "Eight", "Nine", "Ten", "Jack", "Queen", "King", "Ace" };
    static readonly string[] suits = { "Clubs", "Diamonds", "Hearts", "Spades" };
    readonly List<Card> cards;
 
    public Deck() {
        cards = (from suit in suits
                from rank in ranks
                select new Card(rank, suit)).ToList();
    }
 
    public int Count => cards.Count;
 
    public void Shuffle() {
        // using Knuth Shuffle (see at http://rosettacode.org/wiki/Knuth_shuffle)
        var random = new Random();
        for (int i = 0; i < cards.Count; i++) {
            int r = random.Next(i, cards.Count);
            var temp = cards[i];
            cards[i] = cards[r];
            cards[r] = temp;
        }
    }
 
    public Card Deal() {
        int last = cards.Count - 1;
        Card card = cards[last];
        //Removing from the front will shift the other items back 1 spot,
        //so that would be an O(n) operation. Removing from the back is O(1).
        cards.RemoveAt(last);
        return card;
    }
 
    public IEnumerator<Card> GetEnumerator() {
        //Reverse enumeration of the list so that they are returned in the order they would be dealt.
        //LINQ's Reverse() copies the entire list. Let's avoid that.
        for (int i = cards.Count - 1; i >= 0; i--)
            yield return cards[i];
    }
 
    System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() => GetEnumerator();
}

