public abstract class BaseTestCase
{
    public abstract string TestName { get; }
    public abstract bool RunTest();
}

public class SampleTest : BaseTestCase
{
    public override string TestName => "Sample Test";

    public override bool RunTest()
    {
        // Dummy test logic
        Debug.Log("Executing " + TestName);
        return true;
    }
}

public class TestResult
{
    public bool AllPassed;
    public List<string> FailedTests = new List<string>();
    public string Summary
    {
        get
        {
            return AllPassed ? "All tests passed." : "Some tests failed: " + string.Join(", ", FailedTests);
        }
    }
}

public class TestSuite
{
    private List<BaseTestCase> testCases = new List<BaseTestCase>();

    public TestSuite()
    {
        DiscoverTests();
    }

    private void DiscoverTests()
    {
        // Discover tests by scanning the assembly for subclasses of BaseTestCase
        Type baseType = typeof(BaseTestCase);
        foreach (Type type in Assembly.GetExecutingAssembly().GetTypes())
        {
            if (type.IsSubclassOf(baseType) && !type.IsAbstract)
            {
                BaseTestCase instance = (BaseTestCase)Activator.CreateInstance(type);
                testCases.Add(instance);
            }
        }
    }

    public TestResult RunAllTests()
    {
        TestResult result = new TestResult { AllPassed = true };
        foreach (var test in testCases)
        {
            bool passed = test.RunTest();
            if (!passed)
            {
                result.AllPassed = false;
                result.FailedTests.Add(test.TestName);
            }
        }
        return result;
    }
}

