using UnityEngine;
using System.Collections;

public class GravitySwitch : MonoBehaviour
{
    [Header("Physics Settings")]
    public float gravityStrength = 9.81f;
    public float rotationSpeed = 5f;
    public bool isGravityReversed = false;

    [Header("Game State")]
    private bool isGameActive = false;
    private bool isGameOver = false;
    private int currentScore = 0;
    private int bestScore = 0;

    [Header("Player Components")]
    public Rigidbody2D playerRigidbody;
    public Transform playerTransform;
    public SpriteRenderer playerSprite;

    [Header("Visual Effects")]
    public GameObject[] jetEffects;
    public GameObject[] explosionPrefabs;
    public GameObject[] characterPieces;

    [Header("Audio")]
    public AudioClip gravityChangeSFX;
    public AudioClip explosionSFX;

    private AudioSource audioSource;
    private Vector2 currentGravityVector;

    void Start()
    {
        Initialize();
    }

    void Initialize()
    {
        audioSource = GetComponent<AudioSource>();
        bestScore = PlayerPrefs.GetInt("BestScore", 0);
        currentGravityVector = Physics2D.gravity;
        ResetGameState();
    }

    void Update()
    {
        if (!isGameActive || isGameOver) return;

        HandlePlayerControls();
        UpdateGravity();
        TrackScore();
    }

    void HandlePlayerControls()
    {
        if (Input.GetKeyDown(KeyCode.Space) || Input.GetMouseButtonDown(0))
        {
            SwitchGravity();
        }
    }

    void SwitchGravity()
    {
        isGravityReversed = !isGravityReversed;
        currentGravityVector = isGravityReversed
            ? new Vector2(0, -gravityStrength)
            : new Vector2(0, gravityStrength);

        Physics2D.gravity = currentGravityVector;
        RotatePlayer();
        PlayGravityChangeSFX();
    }

    void RotatePlayer()
    {
        float targetRotation = isGravityReversed ? 180f : 0f;
        playerTransform.rotation = Quaternion.Lerp(
            playerTransform.rotation,
            Quaternion.Euler(0, 0, targetRotation),
            rotationSpeed * Time.deltaTime
        );
    }

    void UpdateGravity()
    {
        playerRigidbody.AddForce(currentGravityVector, ForceMode2D.Force);
    }

    void TrackScore()
    {
        currentScore++;
        UpdateBestScore();
    }

    void UpdateBestScore()
    {
        if (currentScore > bestScore)
        {
            bestScore = currentScore;
            PlayerPrefs.SetInt("BestScore", bestScore);
            PlayerPrefs.Save();
        }
    }

