using Newtonsoft.Json;

namespace NotificationHub
{
    public class MpnsCredential
    {
        [JsonProperty("mpnsCertificate")]
        public string MpnsCertificate { get; set; }

        [JsonProperty("certificateKey")]
        public string CertificateKey { get; set; }

        [JsonProperty("thumbprint")]
        public string Thumbprint { get; set; }

        // Default constructor
        public MpnsCredential() { }

        // Constructor with parameters
        public MpnsCredential(string mpnsCertificate, string certificateKey, string thumbprint)
        {
            MpnsCertificate = mpnsCertificate;
            CertificateKey = certificateKey;
            Thumbprint = thumbprint;
        }

        // Method to validate certificate
        public bool IsValid()
        {
            return !string.IsNullOrWhiteSpace(MpnsCertificate) &&
                   !string.IsNullOrWhiteSpace(CertificateKey) &&
                   !string.IsNullOrWhiteSpace(Thumbprint);
        }

        // Method to serialize to JSON
        public string ToJson()
        {
            return JsonConvert.SerializeObject(this);
        }

        // Method to populate from JSON
        public static MpnsCredential FromJson(string json)
        {
            return JsonConvert.DeserializeObject<MpnsCredential>(json);
        }
    }

    // Example usage of MpnsCredential class
    class Program
    {
        static void Main(string[] args)
        {
            var credential = new MpnsCredential("my-cert", "my-key", "my-thumbprint");

            if (credential.IsValid())
            {
                string json = credential.ToJson();
                System.Console.WriteLine("Serialized JSON: " + json);

                var deserializedCredential = MpnsCredential.FromJson(json);
                System.Console.WriteLine("Deserialized Thumbprint: " + deserializedCredential.Thumbprint);
            }
            else
            {
                System.Console.WriteLine("Invalid MPNS Credentials.");
            }
        }
    }
}

