using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

public abstract class DnsRecordBase
{
    public string DomainName { get; set; }
    public int TimeToLive { get; set; }

    public abstract int MaximumRecordDataLength { get; }
}

public interface ITextRecord
{
    string TextData { get; }
}

public class TxtRecord : DnsRecordBase, ITextRecord
{
    private const int MaxTextLength = 255;
    private List<string> textEntries;

    public TxtRecord(string domainName, int ttl, IEnumerable<string> textData)
    {
        DomainName = domainName;
        TimeToLive = ttl;
        textEntries = new List<string>(textData);
    }

    public string TextData => string.Join(" ", textEntries);

    public override int MaximumRecordDataLength => MaxTextLength * textEntries.Count;

    public static TxtRecord ParseRecordData(string domainName, int ttl, byte[] data)
    {
        var textEntries = new List<string>();
        int offset = 0;

        while (offset < data.Length)
        {
            int length = data[offset];
            offset++;

            if (length == 0 || offset + length > data.Length)
                break;

            string textEntry = Encoding.UTF8.GetString(data, offset, length);
            textEntries.Add(textEntry);
            offset += length;
        }

        return new TxtRecord(domainName, ttl, textEntries);
    }

    public byte[] EncodeRecordData()
    {
        List<byte> data = new List<byte>();

        foreach (var entry in textEntries)
        {
            if (entry.Length > MaxTextLength)
                throw new ArgumentOutOfRangeException(nameof(entry), "Text entry exceeds maximum length.");

            data.Add((byte)entry.Length);
            data.AddRange(Encoding.UTF8.GetBytes(entry));
        }

        return data.ToArray();
    }

    public override string ToString()
    {
        return $"TXT Record for {DomainName} (TTL: {TimeToLive}): {TextData}";
    }
}

