public class HtmlExample : Form
{
    private WebBrowser webBrowserControl;
    private JObject json;
    private XslCompiledTransform transform;

    public HtmlExample()
    {
        InitializeComponents();
        LoadJson();
        LoadXslt();
    }

    private void InitializeComponents()
    {
        webBrowserControl = new WebBrowser { Dock = DockStyle.Fill };
        var viewJsonButton = new Button { Text = "View JSON", Dock = DockStyle.Top };
        var viewXsltButton = new Button { Text = "View XSLT", Dock = DockStyle.Top };
        var viewResultButton = new Button { Text = "View Result", Dock = DockStyle.Top };
        var viewAsXmlButton = new Button { Text = "View as XML", Dock = DockStyle.Top };

        viewJsonButton.Click += ViewJsonButton_Click;
        viewXsltButton.Click += ViewXsltButton_Click;
        viewResultButton.Click += ViewResultButton_Click;
        viewAsXmlButton.Click += ViewAsXmlButton_Click;

        Controls.Add(webBrowserControl);
        Controls.Add(viewJsonButton);
        Controls.Add(viewXsltButton);
        Controls.Add(viewResultButton);
        Controls.Add(viewAsXmlButton);
    }

    private void LoadJson()
    {
        json = JObject.Parse("{ \"name\": \"John\", \"age\": 30, \"city\": \"New York\" }");
    }

    private void LoadXslt()
    {
        transform = new XslCompiledTransform();
        var xsltStream = Assembly.GetExecutingAssembly().GetManifestResourceStream("ExampleXslt.xslt");
        using (var reader = XmlReader.Create(xsltStream))
        {
            transform.Load(reader);
        }
    }

    private void ViewJsonButton_Click(object sender, EventArgs e)
    {
        webBrowserControl.DocumentText = FormatAsWeb(json.ToString());
    }

    private void ViewXsltButton_Click(object sender, EventArgs e)
    {
        var xsltStream = Assembly.GetExecutingAssembly().GetManifestResourceStream("ExampleXslt.xslt");
        using (var reader = new StreamReader(xsltStream))
        {
            webBrowserControl.DocumentText = FormatAsWeb(reader.ReadToEnd());
        }
    }

    private void ViewResultButton_Click(object sender, EventArgs e)
    {
        var navigator = new JsonXPathNavigator(json);
        var results = new StringBuilder();
        using (var writer = XmlWriter.Create(results))
        {
            transform.Transform(navigator, null, writer);
        }

