    protected SequenceInterpreterFactory()
    {
        if (Instance != null)
        {
            Debug.LogError("Attempted to create a second instance of a singleton class.");
        }
        else
        {
            Instance = this;
        }
    }

    public abstract ISequenceInterpreter CreateSequenceInterpreterFor(SequenceNode node);
}

public class SequenceInterpreterFactoryImp : SequenceInterpreterFactory
{
    private List<ISequenceInterpreter> sequenceInterpreters;

    public SequenceInterpreterFactoryImp()
    {
        sequenceInterpreters = new List<ISequenceInterpreter>
        {
            ScriptableObject.CreateInstance<SimpleContentInterpreter>(),
            ScriptableObject.CreateInstance<CheckableInterpreter>(),
            ScriptableObject.CreateInstance<DialogInterpreter>(),
            ScriptableObject.CreateInstance<GameEventInterpreter>()
        };

        // Future enhancement: Dynamically load interpreters from assemblies
        // foreach (var assembly in System.AppDomain.CurrentDomain.GetAssemblies())
        // {
