        //     {
        //         if (typeof(ISequenceInterpreter).IsAssignableFrom(type) && !type.IsInterface)
        //         {
        //             sequenceInterpreters.Add((ISequenceInterpreter)ScriptableObject.CreateInstance(type));
        //         }
        //     }
        // }
    }

    public override ISequenceInterpreter CreateSequenceInterpreterFor(SequenceNode node)
    {
        foreach (var interpreter in sequenceInterpreters)
        {
            if (interpreter.CanHandle(node))
            {
                return interpreter.Clone();
            }
        }
        return null;
    }
