    class Shape
    {
        static void Main(string[] args)
        {
            for (int i = 2; i <= 9; i++)
            {
                SuperD(i, 10);
            }
        }
 
        static void SuperD(int d, int max)
        {
            var start = DateTime.Now;
            var test = "";
            for (int i = 0; i < d; i++)
            {
                test += d;
            }
 
            var n = 0;
            var i = 0;
            Console.WriteLine($"First {max} super-{d} numbers:");
            while (n < max)
            {
                i++;
                var value = BigInteger.Pow(i, d) * d;
                if (value.ToString().Contains(test))
                {
                    n++;
                    Console.Write($"{i} ");
                }
            }
            var end = DateTime.Now;
            Console.WriteLine($"\nRun time {(end - start).TotalMilliseconds} ms\n");
        }
    }
}

