public enum LB { DOS, UNIX, MAC }

public class FileRead
{
    public List<string> Lines { get; set; }
    public bool TrailingTerminator { get; set; }
}

public static class ReadingUtil
{
    public static FileRead BuildAndRead(LB lineBreak, bool includeBOM, bool includeTrailingTerminator)
    {
        string path = MakeFile(lineBreak, includeBOM, includeTrailingTerminator);
        try
        {
            return ReadFile(path, includeBOM);
        }
        finally
        {
            File.Delete(path);
        }
    }

    private static string MakeFile(LB lineBreak, bool includeBOM, bool includeTrailingTerminator)
    {
        string lineEnd = lineBreak switch
        {
            LB.DOS => "\r\n",
            LB.UNIX => "\n",
            LB.MAC => "\r",
            _ => throw new ArgumentException("Invalid line break type")
        };

        StringBuilder sb = new StringBuilder();
        sb.Append("0 HEAD").Append(lineEnd);
        sb.Append("1 SOUR TEST").Append(lineEnd);
        sb.Append("1 DATE 2024").Append(includeTrailingTerminator ? lineEnd : "");

        Encoding encoding = includeBOM ? Encoding.UTF8 : new UTF8Encoding(false);
        string path = Path.GetTempFileName();
        File.WriteAllText(path, sb.ToString(), encoding);
        return path;
    }

    private static FileRead ReadFile(string path, bool expectedBOM)
    {
        Encoding encoding = expectedBOM ? Encoding.UTF8 : new UTF8Encoding(false);
        string content = File.ReadAllText(path, encoding);

        List<string> lines = new List<string>();
        int start = 0;
        for (int i = 0; i < content.Length; i++)
        {
            if (content[i] == '\r')
            {
                if (i + 1 < content.Length && content[i + 1] == '\n')
                {
                    lines.Add(content.Substring(start, i - start));
                    i++;
                    start = i + 1;
                }
                else
                {
                    lines.Add(content.Substring(start, i - start));
                    start = i + 1;
                }
            }
            else if (content[i] == '\n')
            {
                lines.Add(content.Substring(start, i - start));
                start = i + 1;
            }
        }
        if (start < content.Length)
        {
            lines.Add(content.Substring(start));
        }

        bool trailing = content.EndsWith("\r") || content.EndsWith("\n") || content.EndsWith("\r\n");

        return new FileRead
        {

