namespace CustomIdentity
{
    public class AppUser : IdentityUser { }
    public class AppUserRole : IdentityRole { }

    public static class IdentityServiceExtensions
    {
        public static IServiceCollection UseSelfIdentity(this IServiceCollection services)
        {
            services.AddIdentityCore<AppUser>(options => {
                options.User.RequireUniqueEmail = true;
                options.Password.RequiredLength = 12;
                options.Password.RequireNonAlphanumeric = options.Password.RequireDigit =
                    options.Password.RequireLowercase = options.Password.RequireUppercase = true;
                options.Lockout.MaxFailedAccessAttempts = 5;
                options.Lockout.DefaultLockoutTimeSpan = TimeSpan.FromMinutes(15);
                options.SignIn.RequireConfirmedEmail = true;
            })
            .AddUserManager<AppUser>(provider => CreateUserManager(provider))
            .AddRoles<AppUserRole>()
