[Serializable]
public class IsoUnityCollectionType : JSONAble
{
    private IsoUnityList l = new IsoUnityList();
    private string whatIs;

    public IsoUnityCollectionType(Type type)
    {
        whatIs = type.FullName;
    }

    public IList GetList()
    {
        return l;
    }

    public void SetList(IList newList)
    {
        if (CanHandle(newList))
        {
            l = new IsoUnityList(newList);
        }
        else
        {
            Debug.LogError("Invalid list type provided for IsoUnityCollectionType");
        }
    }

    public bool CanHandle(object o)
    {
        return o is IList;
    }

    public IsoUnityCollectionType Clone()
    {
        IsoUnityCollectionType newInstance = new IsoUnityCollectionType(Type.GetType(whatIs));
        newInstance.SetList(l.Clone());
        return newInstance;
    }

    public JSONObject ToJSONObject()
    {
        JSONObject json = new JSONObject();
        json.AddField("whatIs", whatIs);
        json.AddField("items", l.ToJSONObject());
        return json;
    }

    public void FromJSONObject(JSONObject json)
    {
        whatIs = json["whatIs"].str;
        l.FromJSONObject(json["items"]);
    }

    public string Value
    {
        get => whatIs;
        set => whatIs = value;
    }

    [Serializable]
    public class IsoUnityList : IList
    {
        private List<object> internalList = new List<object>();

        public IsoUnityList() { }

        public IsoUnityList(IList list)
        {
            foreach (var item in list)
            {
                internalList.Add(item);
            }
        }

        public JSONObject ToJSONObject()
        {
            JSONObject jsonArray = new JSONObject(JSONObject.Type.Array);
            foreach (var item in internalList)
            {
                jsonArray.Add(item.ToString()); // Define your specific serialization here
            }
            return jsonArray;
        }

        public void FromJSONObject(JSONObject json)
        {
            internalList.Clear();
            for (int i = 0; i < json.Count; i++)
            {
                internalList.Add(json[i].str); // Define your specific deserialization here
            }
        }

        public int Count => internalList.Count;

        public bool IsReadOnly => false;

        public object this[int index]
        {
            get => internalList[index];
            set => internalList[index] = value;
        }

using System;
using System.IO;
 
namespace Generator
{
    class Writer
    {
        static void Main(string[] args)
        {
            string line;
            StreamReader input = new StreamReader("input.txt");
            StreamWriter output = new StreamWriter("output.txt");
 
            if (output.BaseStream.CanWrite)
            {
                if (input.BaseStream.CanRead)
                {
                    while ((line = input.ReadLine())!= null)
                    {
                        output.WriteLine(line);
                    }
                    input.Close(); // Not necessary - will be closed when variable goes out of scope.
                }
                else
                {
                    Console.WriteLine("input.txt cannot be opened!");
                }
                output.Close(); // Not necessary - will be closed when variable goes out of scope.
            }
            else
            {
                Console.WriteLine("output.txt cannot be written to!");
            }
        }
    }
}

