using UnityEngine;
using System.Collections;
using System.Collections.Generic;
using Uduino;

public class ArduinoController : MonoBehaviour
{
    // Uduino board instance.
    private UduinoManager uduinoManager;

    // Logical mapping of pins.
    private int analogInputPin;
    private int digitalOutputPin;

    // Called before the first frame update.
    void Start()
    {
        // Retrieve UduinoManager instance.
        uduinoManager = UduinoManager.Instance;

        // Subscribe to the board connected event.
        uduinoManager.OnBoardConnected += BoardConnected;
    }

    // This method is called when the Arduino board is connected.
    void BoardConnected(UduinoDevice board)
    {
        Debug.Log("Arduino board connected. Configuring pins...");

        // Retrieve physical pin numbers from board mapping.
        analogInputPin = uduinoManager.GetPinFromBoard("A0"); // analog pin A0
        digitalOutputPin = uduinoManager.GetPinFromBoard("D13"); // digital pin 13

        // Set pin modes accordingly.
        board.pinMode(analogInputPin, PinMode.Input);
        board.pinMode(digitalOutputPin, PinMode.Output);

        // Initial writing to digital output pin.
        board.digitalWrite(digitalOutputPin, DigitalState.Low);
    }

    // Update is called once per frame.
    void Update()
    {
        // Ensure that the board is connected before proceeding.
        if (UduinoManager.Instance.IsBoardReady())
        {
            // Read the analog value from the input pin.
            int sensorValue = UduinoManager.Instance.analogRead(analogInputPin);

            // Log the analog sensor reading for monitoring.
            Debug.Log("Analog Sensor Value: " + sensorValue);

            // Set the digital output pin to a high state.
            UduinoManager.Instance.digitalWrite(digitalOutputPin, DigitalState.High);
        }
    }
}

