public class CustomIdentityConfiguration
{
    public static IServiceCollection UseSelfIdentity(this IServiceCollection services)
    {
        services.AddIdentity<AppUser, AppUserRole>(options =>
        {
            ConfigureIdentityOptions(options);
        })
        .AddUserStore<UserStore>()
        .AddRoleStore<RoleStore>()
        .AddUserManager<CustomUserManager>()
        .AddSignInManager<CustomSignInManager>()
        .AddDefaultTokenProviders();

        return services;
    }

    private static void ConfigureIdentityOptions(IdentityOptions options)
    {
        options.Password.RequireDigit = true;
        options.Password.RequiredLength = 8;
        options.Password.RequireNonAlphanumeric = true;
        options.Password.RequireUppercase = true;
        options.Password.RequireLowercase = true;

        options.Lockout.DefaultLockoutTimeSpan = TimeSpan.FromMinutes(15);
        options.Lockout.MaxFailedAccessAttempts = 5;
        options.Lockout.AllowedForNewUsers = true;

        options.User.RequireUniqueEmail = true;
    }

    public class CustomUserManager : UserManager<AppUser>
    {
        public CustomUserManager(
            IUserStore<AppUser> store,
            ILogger<CustomUserManager> logger,
            IPasswordHasher<AppUser> passwordHasher)
            : base(
                store,
                null,
                passwordHasher,
                new[] { new AppUserValidator() },
                new[] { new AppUserPasswordValidator() },
                null,
                logger,
                null,
                null)
        {
        }
    }

    public class AppUserValidator : UserValidator<AppUser>
    {
        public override async Task<IdentityResult> ValidateAsync(UserManager<AppUser> manager, AppUser user)
        {
            var result = await base.ValidateAsync(manager, user);
            var errors = result.Errors.ToList();

            if (string.IsNullOrWhiteSpace(user.FirstName))
            {
                errors.Add(new IdentityError
                {
                    Description = "First name is required"
                });
            }

            return errors.Count > 0

