namespace ConstraintSolver
{
    // Abstract base class defining the structure of a variable in the constraint-solving system.
    public abstract class AbstractVariable
    {
        // The variable's name.
        public string Name { get; protected set; }

        // The variable's numeric value.
        public double Value { get; protected set; }

        // Base constructor to initialize name and value.
        protected AbstractVariable(string name, double value)
        {
            Name = name;
            Value = value;
        }

        // Abstract properties indicating the variable's behavior within the constraint system.
        public abstract bool IsDummy { get; }
        public abstract bool IsExternal { get; }
        public abstract bool IsPivotable { get; }
        public abstract bool IsRestricted { get; }

        // Returns a formatted string representation, using invariant culture for numeric values.
        public override string ToString()
        {
            string formattedValue = Value.ToString("F2", CultureInfo.InvariantCulture);
            return string.Format("{0}:{1}", Name, formattedValue);
        }
    }

    // Concrete implementation of a constraint variable.
    public class ConcreteVariable : AbstractVariable
    {
        // Default constructor: initializes with a default name and zero value.
        public ConcreteVariable() : this("var", 0.0)
        {
        }

        // Constructor with a specified name and a default zero value.
        public ConcreteVariable(string name) : this(name, 0.0)
        {
        }

        // Constructor with a specified value and a default name.
        public ConcreteVariable(double value) : this("var", value)
        {
        }

        // Constructor with both specified name and value.
        public ConcreteVariable(string name, double value) : base(name, value)
        {
        }

        // Indicates that this variable is not a dummy.
        public override bool IsDummy
        {
            get { return false; }
        }

        // Indicates that this variable is external (user-defined).
        public override bool IsExternal
        {
            get { return true; }
        }

        // Indicates that this variable cannot be pivoted.
        public override bool IsPivotable
        {
            get { return false; }
        }

        // Indicates that no restrictions (such as non-negativity) apply to this variable.
        public override bool IsRestricted
        {
            get { return false; }
        }

