namespace MontyHall
{
    class Cache
    {
        static void Main(string[] args)
        {
            int games = 100000;
            Random r = new Random();
 
            int switcherWins = 0, keeperWins = 0, shown = 0;
            for (int i = 0; i < games; i++)
            {
                int[] doors = new int[3];
                doors[r.Next(3)] = 1; // Set which one has the car
                int choice = r.Next(3); // Choose a door
                for (shown = r.Next(3); shown == choice || doors[shown] == 1; shown = r.Next(3)) { }
                switcherWins += doors[3 - choice - shown];
                keeperWins += doors[choice];
            }
            float floatGames = (float)games;
            Console.WriteLine("Switcher Wins: {0} ({1:0.00}%)",
                switcherWins, (float)switcherWins / floatGames * 100);
            Console.WriteLine("Keeper Wins: {0} ({1:0.00}%)",
                keeperWins, (float)keeperWins / floatGames * 100);
        }
    }
}

