using System.Collections.Generic;
using ASC.Notify.Model;

namespace CommunityPlatform
{
    public class BirthdaysSubscriptionManager
    {
        private readonly ISubscriptionProvider subscriptionProvider;

        public BirthdaysSubscriptionManager(ISubscriptionProvider provider)
        {
            subscriptionProvider = provider ?? throw new ArgumentNullException(nameof(provider));
        }

        public List<SubscriptionType> GetSubscriptionTypes()
        {
            var subscriptionTypes = new List<SubscriptionType>
            {
                new SubscriptionType
                {
                    Id = Guid.NewGuid(),
                    Name = "Birthday Notifications",
                    NotifyUser = true,
                    IsMultipleSubscription = true
                },
                new SubscriptionType
                {
                    Id = Guid.NewGuid(),
                    Name = "Special Birthday Events",
                    NotifyUser = true,
                    IsMultipleSubscription = false
                }
            };
            return subscriptionTypes;
        }

        public List<SubscriptionObject> GetSubscriptionObjects(Guid userId)
        {
            var subscriptions = new List<SubscriptionObject>();
            foreach (var type in GetSubscriptionTypes())
            {
                subscriptions.Add(new SubscriptionObject
                {
                    UserId = userId,
                    SubscriptionTypeId = type.Id,
                    IsSubscribed = subscriptionProvider.IsUserSubscribed(userId, type.Id)
                });
            }
            return subscriptions;
        }

        public bool IsEmptySubscriptionType(SubscriptionType type)
        {
            if (type == null) throw new ArgumentNullException(nameof(type));
            return !subscriptionProvider.HasActiveSubscriptions(type.Id);
        }
    }

    public interface ISubscriptionProvider
    {
        bool IsUserSubscribed(Guid userId, Guid subscriptionTypeId);
        bool HasActiveSubscriptions(Guid subscriptionTypeId);
    }

    public class SubscriptionObject
    {
        public Guid UserId { get; set; }
        public Guid SubscriptionTypeId { get; set; }
        public bool IsSubscribed { get; set; }
    }

    public class SubscriptionType
    {
        public Guid Id { get; set; }
        public string Name { get; set; }
        public bool NotifyUser { get; set; }
        public bool IsMultipleSubscription { get; set; }
    }

namespace ImageGallery.Web.Areas.Admin.Controllers
