public interface ISequenceInterpreter
{
    bool CanHandle(SequenceNode node);
    void Interpret(SequenceNode node);
    ISequenceInterpreter Clone();
}

[Serializable]
public abstract class BaseSequenceInterpreter : ISequenceInterpreter
{
    public abstract bool CanHandle(SequenceNode node);
    public abstract void Interpret(SequenceNode node);
    public abstract ISequenceInterpreter Clone();
}

public class SequenceInterpreterFactory
{
    private static SequenceInterpreterFactory _instance;
    private List<ISequenceInterpreter> _sequenceInterpreters;

    public static SequenceInterpreterFactory Instance
    {
        get
        {
            if (_instance == null)
            {
                _instance = new SequenceInterpreterFactory();
            }
            return _instance;
        }
    }

    private SequenceInterpreterFactory()
    {
        _sequenceInterpreters = new List<ISequenceInterpreter>();
        InitializeDefaultInterpreters();
    }

    private void InitializeDefaultInterpreters()
    {
        RegisterInterpreter(new DialogSequenceInterpreter());
        RegisterInterpreter(new EventSequenceInterpreter());
    }

    public void RegisterInterpreter(ISequenceInterpreter interpreter)
    {
        _sequenceInterpreters.Add(interpreter);
    }

    public ISequenceInterpreter CreateSequenceInterpreterFor(SequenceNode node)
    {
        foreach (var interpreter in _sequenceInterpreters)
        {
            if (interpreter.CanHandle(node))
            {
                return interpreter.Clone();
            }
        }

        throw new InvalidOperationException("No suitable interpreter found for the sequence node.");
    }

    // TODO: Implement dynamic interpreter discovery via reflection or assembly scanning
}

public class SequenceNode
{
    public string Type { get; set; }
    public Dictionary<string, object> Data { get; set; }
}

