using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;

namespace EmailFormatter
{
    /// <summary>
    /// Represents an email field according to RFC 822 specification.
    /// </summary>
    public class Field
    {
        private string m_Name;
        private string m_Body;

        // Constructor to initialize the field with a name and body
        public Field(string name, string body)
        {
            Name = name;
            Body = body;
        }

        // Property for the Name of the email field
        public string Name
        {
            get { return m_Name; }
            set
            {
                if (string.IsNullOrWhiteSpace(value))
                    throw new ArgumentException("Field name cannot be null or empty.");
                m_Name = value;
            }
        }

        // Property for the Body of the email field
        public string Body
        {
            get { return m_Body; }
            set
            {
                if (string.IsNullOrWhiteSpace(value))
                    throw new ArgumentException("Field body cannot be null or empty.");
                m_Body = value;
            }
        }

        // Method to return a formatted string of the field
        public string FormatField()
        {
            return $"{Name}: {Body}";
        }

        // Method to validate if the name of the field follows RFC 822 naming conventions
        public bool IsValidFieldName()
        {
            return Regex.IsMatch(m_Name, @"^[!-9;-~]+$");
        }

        // Method to set both name and body at once
        public void SetField(string name, string body)
        {
            Name = name;
            Body = body;
        }

        // Override ToString for easier display
        public override string ToString()
        {
            return FormatField();
        }
    }

    class Product
    {
        static void Main(string[] args)
        {
            // Example usage of the Field class
            Field emailField = new Field("Subject", "Hello World!");

            Console.WriteLine(emailField.ToString());

            // Update the field
            emailField.SetField("From", "example@example.com");
            Console.WriteLine(emailField.FormatField());

            // Validate field name
            Console.WriteLine($"Is '{emailField.Name}' a valid field name? {emailField.IsValidFieldName()}");
        }
    }
}

using System;
using System.IO;
using System.Linq;
using System.Web;
using System.Xml.Linq;

public class VersionIntent : BaseOleIntent
{
    private readonly HttpContext _context;

    public VersionIntent(HttpContext context)
    {
        _context = context;
    }

    public string Respond(string userQuery)
    {
        if (string.IsNullOrEmpty(userQuery))
        {
            return "Please provide a query regarding the version information.";
        }

        string versionFilePath = GetVersionFilePath();

        if (!File.Exists(versionFilePath))
        {
            return "Version information file not found.";
        }

        try
        {
            var versionDetails = ParseVersionInfo(versionFilePath);
            return FormatResponse(versionDetails);
        }
        catch (Exception ex)
        {
            return $"An error occurred while retrieving version information: {ex.Message}";
        }
    }

    private string GetVersionFilePath()
    {
        // Assuming the XML file is stored in the App_Data folder
        return Path.Combine(_context.Server.MapPath("~/App_Data"), "version.xml");
    }

    private (string Major, string Minor, string Revision) ParseVersionInfo(string filePath)
    {
        XDocument document = XDocument.Load(filePath);

        var versionElement = document.Descendants("version").FirstOrDefault();
        if (versionElement == null)
        {
            throw new Exception("Version element not found in the XML file.");
        }

        string major = versionElement.Element("major")?.Value ?? "0";
        string minor = versionElement.Element("minor")?.Value ?? "0";
        string revision = versionElement.Element("revision")?.Value ?? "0";

        return (major, minor, revision);
    }

    private string FormatResponse((string Major, string Minor, string Revision) versionDetails)
    {
        return $"Current version: {versionDetails.Major}.{versionDetails.Minor}.{versionDetails.Revision}";
    }
}

