using System;
using System.Drawing;
 
namespace Raster
{
    public partial class Bitmap
    {
        // Circle plots a circle with center x, y and radius r.
        // Limiting behavior:
        // r < 0 plots no pixels.
        // r = 0 plots a single pixel at x, y.
        // r = 1 plots four pixels in a diamond shape around the center pixel at x, y.
        public void Circle(int x, int y, int r, Pixel p)
        {
            if (r < 0)
            {
                return;
            }
            // Bresenham algorithm
            int x1 = -r;
            int y1 = 0;
            int err = 2 - 2 * r;
            while (true)
            {
                SetPx(x - x1, y + y1, p);
                SetPx(x - y1, y - x1, p);
                SetPx(x + x1, y - y1, p);
                SetPx(x + y1, y + x1, p);
                int r1 = err;
                if (r1 > x1)
                {
                    x1++;
                    err += x1 * 2 + 1;
                }
                if (r1 <= y1)
                {
                    y1++;
                    err += y1 * 2 + 1;
                }
                if (x1 >= 0)
                {
                    break;
                }
            }
        }
 
        public void CircleRgb(int x, int y, int r, Rgb c)
        {
            Circle(x, y, r, c.Pixel());
        }
    }
}

