    // Interface for a custom interception policy.
    public interface IInterceptionPolicy
    {
        bool IsInterceptable(Type type);
        IInterceptionBehavior GetInterceptor();
    }

    // Interface for an interception behavior.
    public interface IInterceptionBehavior
    {
        bool CanIntercept(Type type);
        // Assume other interception-related members here.
    }

    // Helper interface for interception-related operations.
    public interface IInterceptionHelper
    {
        IInterceptionPolicy RetrievePolicy(IBuilderContext context);
    }

