    {
        private readonly IInterceptionHelper _interceptionHelper;
        private readonly IInterceptionBehavior _defaultInterceptor;

        public CustomInterceptionStrategy(IInterceptionHelper interceptionHelper, IInterceptionBehavior defaultInterceptor)
        {
            if (interceptionHelper == null)
                throw new ArgumentNullException("interceptionHelper");
            _interceptionHelper = interceptionHelper;
            _defaultInterceptor = defaultInterceptor;
        }

        // PreBuildUp is called before the object is constructed.
        public override void PreBuildUp(IBuilderContext context)
        {
            if (context == null)
                throw new ArgumentNullException("context");

            // Retrieve interception policy using the helper.
            IInterceptionPolicy policy = _interceptionHelper.RetrievePolicy(context);
            Type typeToBuild = context.BuildKey.Type;
            IInterceptionBehavior chosenInterceptor = null;

            // If a policy exists and its interceptor can intercept the type...
            if (policy != null)
            {
                if (policy.IsInterceptable(typeToBuild))
                {
