    public class MainWindowPresenter
    {
        public static readonly DependencyProperty PanelsProperty =
            DependencyProperty.Register("Panels", typeof(ObservableCollection<PivotItem>), typeof(MainWindowPresenter), new PropertyMetadata(new ObservableCollection<PivotItem>()));

        public ObservableCollection<PivotItem> Panels
        {
            get { return (ObservableCollection<PivotItem>)GetValue(PanelsProperty); }
            set { SetValue(PanelsProperty, value); }
        }

        private Shell _shell;

        public MainWindowPresenter(Shell shell)
        {
            _shell = shell;
            _shell.OnShowError += (title, message) =>
            {
                MessageBox.Show(message, title, MessageBoxButton.OK);
            };

            _shell.OnShowStatus += (message) =>
            {
                // Implement status display logic here if needed
            };

            _shell.OnShowView += (view, header, id) =>
            {
                var panel = GetPanel(id);
                panel.Content = view;
                panel.Header = header;
            };

            if (!DesignerProperties.IsInDesignTool)
            {
                try
                {
                    _shell.ShowView<OrderEdit, OrderVm>(0);
                }
                catch (Exception ex)
                {
                    _shell.ShowError("Error", ex.Message);
                }
            }
        }

        private PivotItem GetPanel(int id)
        {
            var panel = Panels.FirstOrDefault(p => p.Name == "Panel" + id);
            if (panel == null)
            {
                panel = new PivotItem { Name = "Panel" + id };
                Panels.Add(panel);
            }
            return panel;
        }
    }
}

