// USING A LIST MONAD DIRECTLY, WITHOUT SPECIAL SYNTAX FOR LIST COMPREHENSIONS
 
(function (n) {
 
    return mb(r(1,     n), function (x) {  // x <- [1..n]
    return mb(r(1 + x, n), function (y) {  // y <- [1+x..n]
    return mb(r(1 + y, n), function (z) {  // z <- [1+y..n]
 
       return x * x + y * y === z * z? [[x, y, z]] : [];
 
    })})});
 
 
    // LIBRARY FUNCTIONS
 
    // Monadic bind for lists
    function mb(xs, f) {
        return [].concat.apply([], xs.map(f));
    }
 
    // Monadic return for lists is simply lambda x -> [x]
    // as in [[x, y, z]] : [] above
 
    // Integer range [m..n]
    function r(m, n) {
        return Array.apply(null, Array(n - m + 1))
           .map(function (n, x) {
                return m + x;
            });
    }
 
})(100);

using UnityEngine;
using System;
using System.Collections;
using System.Collections.Generic;

[Serializable]
public abstract class IsoUnityType : ScriptableObject
{
    public abstract IsoUnityType Clone();
}

[Serializable]
public class IsoUnityList<T> : List<T> { }

[Serializable]
public class IsoUnityCollectionType : IsoUnityType
{
    // Tracks the expected type for the collection items.
    [SerializeField]
    private string whatIs = "";

    // The internal custom list storing collection data.
    [SerializeField]
    private IsoUnityList<object> collection = new IsoUnityList<object>();

    // Property-based accessor for the collection.
    public object Value
    {
        get
        {
            // Ensure the type information matches the expected descriptor.
            if (!String.IsNullOrEmpty(whatIs) && collection.Count > 0)
            {
                Type expectedType = Type.GetType(whatIs);
                if (expectedType != null && collection[0] != null &&
                    collection[0].GetType() != expectedType)
                {
                    Debug.LogWarning("Collection type mismatch. Expected: " + whatIs);
                }
            }
            return collection;
        }
        set
        {
            // Validate that the provided value is a list.
            if (!CanHandle(value))
            {
                Debug.LogError("Provided value is not a list.");
                return;
            }
            IList newList = (IList)value;

            // Update the 'whatIs' field for type consistency if list isn't empty.
            if (newList.Count > 0 && newList[0] != null)
            {
                whatIs = newList[0].GetType().AssemblyQualifiedName;
            }
            else
            {
                whatIs = "";
            }

            // If the value is not of the custom type, wrap it.
            if (!(value is IsoUnityList<object>))
            {
                collection = new IsoUnityList<object>();
                foreach(object item in newList)
                {
                    collection.Add(item);
                }
            }
            else
            {
                collection = (IsoUnityList<object>)value;
            }
        }
    }

    // Checks if the provided object is a compatible list type.
    public bool CanHandle(object value)
    {
        return value is IList;
    }

    // Creates a deep clone of this instance.
    public override IsoUnityType Clone()
    {
        IsoUnityCollectionType clone = CreateInstance<IsoUnityCollectionType>();

