  public int M(int x, out int y){
    Contract.Requires(Contract.Result<int>() == x);        // bad
    Contract.Requires(Contract.ValueAtReturn(out y) == x); // bad but not caught
    Contract.Requires(Contract.OldValue(x) == x);          // bad
    y = 3;
    return x;
