using System;
using System.Drawing;
using GMap.NET.WindowsForms.Markers;

public enum AlertLevel
{
    Green,
    Orange,
    Red
}

public class GMapMarkerADSBPlane : GMapMarker
{
    private float heading;
    private AlertLevel alertLevel;
    private Bitmap iconGreen;
    private Bitmap iconOrange;
    private Bitmap iconRed;

    public GMapMarkerADSBPlane(PointLatLng position, float heading, AlertLevel alertLevel)
        : base(position)
    {
        this.heading = heading;
        this.alertLevel = alertLevel;
        LoadIcons();
    }

    private void LoadIcons()
    {
        try
        {
            iconGreen = new Bitmap("resources/aircraft_green.png");
            iconOrange = new Bitmap("resources/aircraft_orange.png");
            iconRed = new Bitmap("resources/aircraft_red.png");
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error loading icons: " + ex.Message);
        }
    }

    public override void OnRender(Graphics g)
    {
        Bitmap selectedIcon = GetSelectedIcon();

        if (selectedIcon != null)
        {
            g.TranslateTransform(LocalPosition.X + selectedIcon.Width / 2, LocalPosition.Y + selectedIcon.Height / 2);
            g.RotateTransform(heading);
            g.TranslateTransform(-selectedIcon.Width / 2, -selectedIcon.Height / 2);

            g.DrawImage(selectedIcon, new Point(0, 0));
            g.ResetTransform();
        }
    }

    private Bitmap GetSelectedIcon()
    {
        switch (alertLevel)
        {
            case AlertLevel.Green:
                return iconGreen;
            case AlertLevel.Orange:
                return iconOrange;
            case AlertLevel.Red:
                return iconRed;
            default:
                return null;
        }
    }

    public float Heading
    {
        get { return heading; }
        set { heading = value; }
    }

    public AlertLevel AlertLevelStatus
    {
        get { return alertLevel; }
        set { alertLevel = value; }
    }
}

