public abstract class TermVerificationTriggerAttribute : Attribute
{
    public string TermMatch { get; }
    public string TermCase { get; }

    protected TermVerificationTriggerAttribute(string termMatch, string termCase)
    {
        TermMatch = termMatch;
        TermCase = termCase;
    }

    public abstract void VerifyHeading(VerificationContext context, string[] expectedValues, int index);
}

public class VerificationContext
{
    public UIComponent[] UIComponents { get; set; }

    public UIComponent FindComponentByIndex(int index)
    {
        if (index < 0 || index >= UIComponents.Length) return null;
        return UIComponents[index];
    }

    public UIComponent FindComponentByName(string name)
    {
        return UIComponents.FirstOrDefault(c => c.Name.Equals(name, StringComparison.OrdinalIgnoreCase));
    }
}

public class UIComponent
{
    public string Name { get; set; }
    public string Content { get; set; }

    public bool IsDisplayed { get; set; }
}

[AttributeUsage(AttributeTargets.Method)]
public class VerifyHeadingTriggerAttribute : TermVerificationTriggerAttribute
{
    public int Index { get; }

    public VerifyHeadingTriggerAttribute(string termMatch, string termCase, int index)
        : base(termMatch, termCase)
    {
        Index = index;
    }

    public override void VerifyHeading(VerificationContext context, string[] expectedValues, int index)
    {
        int attempts = 0;
        const int maxAttempts = 5;
        const int delayBetweenAttempts = 1000; // milliseconds

        while (attempts < maxAttempts)
        {
            var component = context.FindComponentByIndex(index);
            if (component != null && component.IsDisplayed)
            {
                if (MatchContent(component.Content, expectedValues))
                {
                    Console.WriteLine($"Heading matched successfully: {component.Content}");
                    return;
                }
            }

            attempts++;
            Thread.Sleep(delayBetweenAttempts);
        }

        Console.WriteLine("Heading verification failed.");
    }

    private bool MatchContent(string actualContent, string[] expectedValues)
    {
        return expectedValues.Any(expected =>
            string.Equals(actualContent, expected, StringComparison.CurrentCultureIgnoreCase));
    }
}

