        {
            int value = 1234567890;
            byte[] expected = { 0x49, 0x96, 0x02, 0xD2 };
            byte[] bytes = _encoder.Encode(value);
            Assert.AreEqual(expected, bytes);
        }

        [Test]
        public void Encode_Long()
        {
            long value = 1234567890123456789;
            byte[] expected = { 0x11, 0x22, 0x10, 0xF4, 0x7D, 0x52, 0xDC, 0x15 };
            byte[] bytes = _encoder.Encode(value);
            Assert.AreEqual(new byte[] { 0x11, 0x22, 0x10, 0xF4, 0x7D, 0x52, 0xDC, 0x15 }, bytes);
        }

        [Test]
        public void Encode_Bool_True()
        {
            bool value = true;
            byte[] expected = { 0x74, 0x72, 0x75, 0x65 };
            byte[] bytes = _encoder.Encode(value);
            CollectionAssert.AreEqual(new byte[] { 1 }, bytes);
        }

        [Test]
        public void Encode_Bool_False()
        {
            bool value = false;
            byte[] expected = { 0x66, 0x61, 0x6c, 0x73, 0x65 };
            byte[] bytes = _encoder.Encode(value);
            CollectionAssert.AreEqual(new byte[] { 0 }, bytes);
        }

        [Test]
        public void Encode_Double()
        {
            double value = 123.456;
            byte[] expected = { 0x40, 0x5E, 0xDD, 0x2F, 0x1A, 0x9F, 0xBE, 0x77 };
            byte[] bytes = _encoder.Encode(value);
            CollectionAssert.AreEqual(new byte[] {0x40, 0x5E, 0xDD, 0x2F, 0x1A, 0x9F, 0xBE, 0x77}, bytes);
        }
    }
