[assembly: ForumApp.ModuleOrderAttribute(10)]
using System;
using System.Collections.Generic;
using System.Reflection;

namespace ForumApp
{
    // Custom attribute to specify module load order at the assembly level.
    [AttributeUsage(AttributeTargets.Assembly, AllowMultiple = false)]
    public class ModuleOrderAttribute : Attribute
    {
        // Private field to hold the sort order value.
        private readonly int sortOrder;

        // Protected property to access the sort order.
        protected int SortOrder
        {
            get { return sortOrder; }
        }

        // Constructor that initializes the module order.
        public ModuleOrderAttribute(int order)
        {
            sortOrder = order;
        }
    }

    // Interface representing a forum module.
    public interface IForumModule
    {
        void Initialize();
    }

    // Class responsible for loading modules within the forum application.
    public class ModuleLoader
    {
        // Loads and displays the module order defined at the assembly level.
        public static void LoadModules()
        {
            Assembly currentAssembly = Assembly.GetExecutingAssembly();
            // Retrieve the ModuleOrder attribute from the assembly.
            object[] attributes = currentAssembly.GetCustomAttributes(typeof(ModuleOrderAttribute), false);
            if (attributes.Length > 0)
            {
                ModuleOrderAttribute orderAttribute = (ModuleOrderAttribute)attributes[0];
                // Use reflection to access the protected SortOrder property.
                PropertyInfo propertyInfo = typeof(ModuleOrderAttribute).GetProperty("SortOrder", BindingFlags.NonPublic | BindingFlags.Instance);
                if (propertyInfo != null)
                {
                    object orderValue = propertyInfo.GetValue(orderAttribute);
                    Console.WriteLine("Module load order defined in assembly: " + orderValue);
                }
            }
            else
            {
                Console.WriteLine("No ModuleOrder attribute found in assembly.");
            }
        }
    }

    // First example forum module.
    public class ForumModuleExample : IForumModule
    {
        public void Initialize()
        {
            Console.WriteLine("ForumModuleExample has been initialized.");
        }
    }

    // Second example forum module.
    public class AnotherForumModule : IForumModule
    {
        public void Initialize()
        {
            Console.WriteLine("AnotherForumModule has been initialized.");
        }
    }

