using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading.Tasks;

namespace SExpr
{
    class Checker
    {
        static void Main(string[] args)
        {
            string str = "((data \"quoted data\" 123 4.5)\n (data (!@# (4.5) \"(more\" \"data)\")))";
            Console.WriteLine("text:\n" + str.Replace("\n", "\n").Replace(" ", " ") + "\n\n");
            var sexpr = str.ParseSexpr();
            if (sexpr == null)
                Console.WriteLine("Invalid s-expr!");
            else
                Console.WriteLine("s-expr:\n" + sexpr + "\n\n" + (sexpr is List<object>? "pretty print:\n" + sexpr.ToPretty() : ""));
            Console.ReadKey();
        }

        public static object ParseSexpr(this string str)
        {
            var t = Regex.Matches(str, @"\s*(""[^""]*""|\(|\)|""|[^\s()""]+)");
            int c = 0;
            for (int i = t.Count - 1; i >= 0; i--)
            {
                var ti = t[i].Value.Trim();
                if (ti == "\"") return null;
                else if (ti == "(") t[i] = "[", c += 1;
                else if (ti == ")") t[i] = "]", c -= 1;
                else if (double.TryParse(ti, out double n)) t[i] = n.ToString();
                else t[i] = "'" + ti.Replace("'", "\\'") + "'";
                if (i > 0 && ti!= "]" && t[i - 1].Value.Trim()!= "(") t.Insert(i, ",");
                if (c == 0) return t.Count == 0? null : t.Cast<object>().ToArray();
            }
            return null;
        }

        public static string ToPretty(this object obj)
        {
            if (obj is List<object> list)
            {
                var s = "";
                for (int i = 0, e = list.Count; i < e; i++)
                    s += (s == ""? "" : " ") + list[i];
                return "(" + s + ")";
            }
            else
                return obj.ToString();
        }
    }
}

