namespace NRules
{
    public class ExpressionEventArgs : EventArgs
    {
        private readonly object[] _arguments;
        private readonly IArguments _lazyArguments;

        public Expression Expression { get; }
        public Exception Exception { get; }
        public object Result { get; }

        public ExpressionEventArgs(Expression expression, Exception exception, object[] arguments, object result)
        {
            Expression = expression;
            Exception = exception;
            _arguments = arguments;
            Result = result;
        }

        public ExpressionEventArgs(Expression expression, Exception exception, IArguments arguments, object result)
        {
            Expression = expression;
            Exception = exception;
            _lazyArguments = arguments;
            Result = result;
        }

        public object[] Arguments
        {
            get
            {
                if (_arguments != null)
                {
                    return _arguments;
                }
                if (_lazyArguments != null)
                {
                    return _lazyArguments.GetArguments();
                }
                return Array.Empty<object>();
            }
        }
    }

    public interface IArguments
    {
        object[] GetArguments();
    }

    public class LazyArguments : IArguments
    {
        private readonly Func<object[]> _argumentsFactory;

        public LazyArguments(Func<object[]> argumentsFactory)
        {
            _argumentsFactory = argumentsFactory;
        }

        public object[] GetArguments()
        {
            return _argumentsFactory();
        }
    }
}

using System;
using System.Collections.Generic;
using Npgsql;

public class BagFilter
{
    private string connectionString;

    public BagFilter(string connString)
    {
        connectionString = connString;
    }

    public void Enhance(List<LocationDescription> locations)
    {
        using (var connection = new NpgsqlConnection(connectionString))
        {
            connection.Open();

            foreach (var location in locations)
            {
                try
                {
                    var streetNames = GetStreetsWithinBoundary(connection, location.Boundary);
                    location.Features.AddRange(streetNames);
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error processing location {location.Name}: {ex.Message}");
                }
            }
        }
    }

    private HashSet<string> GetStreetsWithinBoundary(NpgsqlConnection connection, string wktBoundary)
    {
        var streetNames = new HashSet<string>();
        string query = @"
            SELECT DISTINCT street_name
            FROM streets
            WHERE ST_Within(geom, ST_GeomFromText(:boundary, 4326))";

        using (var cmd = new NpgsqlCommand(query, connection))
        {
            cmd.Parameters.AddWithValue("boundary", wktBoundary);

            using (var reader = cmd.ExecuteReader())
            {
                while (reader.Read())
                {
                    streetNames.Add(reader.GetString(0));
                }
            }
        }
        return streetNames;
    }
}

public struct LocationDescription
{
    public string Name { get; set; }
    public string Boundary { get; set; }
    public List<string> Features { get; set; }

    public LocationDescription(string name, string boundary)
    {
        Name = name;
        Boundary = boundary;
        Features = new List<string>();
    }
}

