    public SkipExpressionNode(MethodCallExpressionParseInfo parseInfo, Expression count)
        : base(parseInfo)
    {
        _cachedCount = new ResolvedExpressionCache<Expression>(this, count);
    }

    protected override void Resolve(ParameterExpression inputParameter, Expression expressionToBeResolved, ClauseGenerationContext clauseGenerationContext)
    {
        Source.Resolve(inputParameter, expressionToBeResolved, clauseGenerationContext);
    }

    public override Expression Resolve(
        ParameterExpression inputParameter,
        Expression expressionToBeResolved,
        ClauseGenerationContext clauseGenerationContext)
    {
        return Source.Resolve(inputParameter, expressionToBeResolved, clauseGenerationContext);
    }

    protected override QueryModel ApplyNodeSpecificSemantics(QueryModel queryModel, ClauseGenerationContext clauseGenerationContext)
    {
        var countExpression = Count;
        var constantCount = countExpression as ConstantExpression;
        var skipValue = constantCount?.Value as int? ?? 0;

        var existingSkipTake = queryModel.BodyClauses.OfType<SkipTakeClause>().FirstOrDefault();
        if (existingSkipTake != null)
        {
            existingSkipTake.Skip = skipValue;
        }
        else
        {
            queryModel.BodyClauses.Add(new SkipTakeClause(skipValue, null));
        }

        return queryModel;
    }

    private static MethodInfo GetGenericMethodDefinition<T>(Expression<System.Func<IEnumerable<T>, int, IEnumerable<T>>> expression)
    {
        return ((MethodCallExpression)expression.Body).Method.GetGenericMethodDefinition();
    }
}

public class SkipTakeClause : IBodyClause
{
    public int? Skip { get; set; }
    public int? Take { get; set; }

    public SkipTakeClause(int? skip, int? take)
    {
        Skip = skip;
        Take = take;
    }

