using OmniSharp.Extensions.LanguageServer.Server;
using System;
using System.Collections.Concurrent;

public class LanguageServerLoggerFactory : ILoggerFactory
{
    private readonly IOmniSharpEnvironment _environment;
    private readonly ConcurrentDictionary<string, ILogger> _loggerCache;
    private readonly LogLevel _minimumLogLevel;
    private ILoggerProvider _defaultProvider;

    public LanguageServerLoggerFactory(
        IOmniSharpEnvironment environment,
        LogLevel minimumLogLevel = LogLevel.Information)
    {
        _environment = environment ?? throw new ArgumentNullException(nameof(environment));
        _loggerCache = new ConcurrentDictionary<string, ILogger>();
        _minimumLogLevel = minimumLogLevel;
        _defaultProvider = new NullLoggerProvider();
    }

    public void AddProvider(ILoggerProvider provider)
    {
        _defaultProvider = provider ?? throw new ArgumentNullException(nameof(provider));
        _loggerCache.Clear();
    }

    public ILogger CreateLogger(string categoryName)
    {
        return _loggerCache.GetOrAdd(categoryName, name =>
            CreateLoggerInternal(name, _defaultProvider));
    }

    private ILogger CreateLoggerInternal(string categoryName, ILoggerProvider provider)
    {
        var logger = provider.CreateLogger(categoryName);
        return new FilteredLogger(logger, categoryName, _minimumLogLevel, _environment);
    }

    public void Dispose()
    {
        _defaultProvider?.Dispose();
        _loggerCache.Clear();
    }

    private class FilteredLogger : ILogger
    {
        private readonly ILogger _innerLogger;
        private readonly string _categoryName;
        private readonly LogLevel _minimumLogLevel;
        private readonly IOmniSharpEnvironment _environment;

        public FilteredLogger(
            ILogger innerLogger,
            string categoryName,
            LogLevel minimumLogLevel,
            IOmniSharpEnvironment environment)
        {
            _innerLogger = innerLogger;
            _categoryName = categoryName;
            _minimumLogLevel = minimumLogLevel;
            _environment = environment;
        }

        public IDisposable BeginScope<TState>(TState state) => _innerLogger.BeginScope(state);

        public bool IsEnabled(LogLevel logLevel)
        {
            return ShouldLog(logLevel) && _innerLogger.IsEnabled(logLevel);
        }

        public void Log<TState>(
            LogLevel logLevel,
            EventId eventId,
            TState state,
            Exception exception,

