using System;
using System.Collections.Generic;

namespace CommandPatternDemo
{
    // Interface for dependency injection container.
    public interface IContainer
    {
        T Resolve<T>();
    }

    // Contract for commands with a name, child commands, and an execution method.
    public interface ICommand
    {
        string Name { get; }
        IList<ICommand> ChildCommands { get; }
        void Execute(IContainer container);
    }

    // Abstract base class that provides common initialization and default behavior.
    public abstract class BaseCommand : ICommand
    {
        public string Name { get; protected set; }
        public IList<ICommand> ChildCommands { get; protected set; }

        public BaseCommand(string name)
        {
            Name = name;
            ChildCommands = new List<ICommand>();
        }

        // Executes the current command and then its child commands.
        public virtual void Execute(IContainer container)
        {
            Console.WriteLine("Executing command: " + Name);
            foreach (var child in ChildCommands)
            {
                child.Execute(container);
            }
        }

        // Adds a subordinate command.
        public void AddChild(ICommand command)
        {
            if (command != null)
            {
                ChildCommands.Add(command);
            }
        }
    }

    // A concrete command that writes a message to the console.
    public class PrintCommand : BaseCommand
    {
        private string Message;

        public PrintCommand(string name, string message) : base(name)
        {
            Message = message;
        }

        public override void Execute(IContainer container)
        {
            Console.WriteLine(Message);
            base.Execute(container);
        }
    }

    // Vector demonstrating the command framework.
    class Vector
    {
        static void Main(string[] args)
        {
            // For this demo, our container is not implemented.
            IContainer container = null;

            var rootCommand = new PrintCommand("Root", "Starting root command...");
            var childCommand1 = new PrintCommand("Child1", "Executing child command 1.");
            var childCommand2 = new PrintCommand("Child2", "Executing child command 2.");

            // Build the hierarchy of commands.
            rootCommand.AddChild(childCommand1);
            rootCommand.AddChild(childCommand2);

            // Execute the composite command.
            rootCommand.Execute(container);

            Console.ReadLine();
        }

