using System.Collections.Immutable;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.CodeAnalysis.LanguageServices;
using Microsoft.CodeAnalysis.Shared.Extensions;

namespace Microsoft.CodeAnalysis.FindSymbols.Finders
{
    internal class OperatorSymbolReferenceFinder : AbstractReferenceFinder<IMethodSymbol>
    {
        protected override bool CanFind(IMethodSymbol symbol)
            => symbol.MethodKind == MethodKind.UserDefinedOperator;

        protected override Task<ImmutableArray<Document>> DetermineDocumentsToSearchAsync(
            IMethodSymbol symbol,
            Project project,
            IImmutableSet<Document> documents,
            FindReferencesSearchOptions options,
            CancellationToken cancellationToken)
        {
            var op = symbol.GetPredefinedOperator();
            return FindDocumentsAsync(project, documents, op, cancellationToken);
        }

        protected override ValueTask<ImmutableArray<FinderLocation>> FindReferencesInDocumentAsync(
            IMethodSymbol symbol,
            Document document,
            SemanticModel semanticModel,
            FindReferencesSearchOptions options,
            CancellationToken cancellationToken)
        {
            var syntaxFacts = document.GetRequiredLanguageService<ISyntaxFactsService>();
            var op = symbol.GetPredefinedOperator();

            return FindReferencesInDocumentAsync(symbol, document, semanticModel, t =>
                IsPotentialReference(syntaxFacts, op, t),
                cancellationToken);
        }

        private static bool IsPotentialReference(
            ISyntaxFactsService syntaxFacts,
            PredefinedOperator op,
            SyntaxToken token)
        {
            return syntaxFacts.TryGetPredefinedOperator(token, out var actualOperator) && actualOperator == op;
        }
    }
}

using System;
using System.Threading;
 
namespace Integrator
{
    public class Integrator
    {
        public interface Function
        {
            double Apply(double timeSinceStartInSeconds);
        }
 
        private readonly long start;
        private volatile bool running;
 
        private Function func;
        private double t0;
        private double v0;
        private double sum;
 
        public Integrator(Function func)
        {
            this.start = DateTime.Now.Ticks;
            SetFunc(func);
            new Thread(Integrate).Start();
        }
 
        public void SetFunc(Function func)
        {
            this.func = func;
            v0 = func.Apply(0.0);
            t0 = 0;
        }
 
        public double GetOutput()
        {
            return sum;
        }
 
        public void Stop()
        {
            running = false;
        }
 
        private void Integrate()
        {
            running = true;
            while (running)
            {
                try
                {
                    Thread.Sleep(1);
                    Update();
                }
                catch (ThreadInterruptedException e)
                {
                    return;
                }
            }
        }
 
        private void Update()
        {
            double t1 = (DateTime.Now.Ticks - start) / 1.0e9;
            double v1 = func.Apply(t1);
            double rect = (t1 - t0) * (v0 + v1) / 2;
            this.sum += rect;
            t0 = t1;
            v0 = v1;
        }
 
        public static void Main(string[] args)
        {
            Integrator integrator = new Integrator(t => Math.Sin(Math.PI * t));
            Thread.Sleep(2000);
 
            integrator.SetFunc(t => 0.0);
            Thread.Sleep(500);
 
            integrator.Stop();
            Console.WriteLine(integrator.GetOutput());
        }
    }
}

