    // A constant sequence generator providing fixed numbers.
    public class ConstantSequence
    {
        private readonly int _value;

        public ConstantSequence(int value)
        {
            _value = value;
        }

        public int Next()
        {
            return _value;
        }
    }

    // Trigger that counts method invocations and triggers an exception based on filters.
    public class CountedTrigger
    {
        private readonly ConstantSequence _sequence;
        private int _currentCount;
        private readonly int _triggerCount;
        private readonly string _filter;

        public CountedTrigger(ConstantSequence sequence, int triggerCount, string filter)
        {
            _sequence = sequence;
            _triggerCount = triggerCount;
            _filter = filter;
            _currentCount = 0;
        }

        public bool ShouldTrigger(string argument)
        {
            _currentCount++;
            if (_currentCount >= _triggerCount && argument == _filter)
            {
                _currentCount = 0; // Reset counter after triggering.
                return true;
            }
            return false;
        }
    }

    // Phantom exception provider that throws exceptions conditionally.
    public static class PhantomExceptionProvider
    {
        // Trigger for exceptions based on a specific identifier.
        private static CountedTrigger _identifierTrigger =
            new CountedTrigger(new ConstantSequence(1), 3, "TEST_ID");

