namespace NotificationLinter
{
    // Dummy attribute to mark notification reference fields.
    [AttributeUsage(AttributeTargets.Field)]
    public class NotificationReferenceAttribute : Attribute
    {
        // If set, this indicates a field name that holds the notification type.
        public string NotificationTypeField { get; set; }
        // Or use a fixed notification type.
        public string FixedNotificationType { get; set; }
    }

    // Dummy structure representing sound or notification info.
    public struct SoundInfo
    {
        public string Key;
        public string Description;
    }

    // Dummy Ruleset class that holds actors and a notification registry.
    public class Ruleset
    {
        public Dictionary<string, List<SoundInfo>> Notifications = new Dictionary<string, List<SoundInfo>>();
        public List<ActorInfo> Actors = new List<ActorInfo>();
    }

    // Dummy ActorInfo to simulate game actors.
    public class ActorInfo
    {
        public string Name;
        public List<object> Traits = new List<object>();
    }

    // Linting pass interface.
    public interface ILintRulesPass
    {
        void Run(Ruleset rules);
    }

    // Implementation of the linting pass.
    public class CheckNotifications : ILintRulesPass
    {
        public void Run(Ruleset rules)
        {
            foreach (var actor in rules.Actors)
            {
                foreach (var trait in actor.Traits)
                {
                    // Get all fields from the trait through reflection.
                    var fields = trait.GetType().GetFields(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);
                    foreach (var field in fields)
                    {
                        if (!HasNotificationReferenceAttribute(field))
                            continue;

                        var attribute = field.GetCustomAttribute<NotificationReferenceAttribute>();
                        string notificationType = null;

                        // Determine notification type from separate field or fixed attribute value.
                        if (!string.IsNullOrEmpty(attribute.NotificationTypeField))
                        {
                            // Fetch the value of the specified field.
                            notificationType = GetFieldValue(trait, attribute.NotificationTypeField) as string;
                        }

