using System;
using System.Runtime.InteropServices;

public enum CefLogSeverity
{
    Default,
    Verbose,
    Info,
    Warning,
    Error,
    Fatal
}

[StructLayout(LayoutKind.Sequential)]
public struct CefString
{
    private IntPtr str;
    private UIntPtr length;

    public static CefString Create(string value)
    {
        var managedString = value ?? string.Empty;
        var length = (UIntPtr)managedString.Length;
        var buffer = Marshal.StringToHGlobalUni(managedString);

        return new CefString
        {
            str = buffer,
            length = length
        };
    }

    public void Free()
    {
        if (str != IntPtr.Zero)
        {
            Marshal.FreeHGlobal(str);
            str = IntPtr.Zero;
            length = UIntPtr.Zero;
        }
    }
}

[StructLayout(LayoutKind.Sequential)]
public struct CefSettings
{
    public UIntPtr size;
    public IntPtr browserSubprocessPath;
    public int cachePath; // Assuming a path represented as an integer offset
    public CefLogSeverity logSeverity;
    public CefString userAgent;

    [DllImport("kernel32.dll")]
    public static extern IntPtr LocalAlloc(uint uFlags, UIntPtr uBytes);

    [DllImport("kernel32.dll")]
    public static extern IntPtr LocalFree(IntPtr hMem);

    public static CefSettings Alloc()
    {
        var settingsSize = (UIntPtr)Marshal.SizeOf<CefSettings>();
        var ptr = LocalAlloc(0, settingsSize);
        var settings = Marshal.PtrToStructure<CefSettings>(ptr);
        settings.size = settingsSize;
        return settings;
    }

    public static void Free(ref CefSettings settings)
    {
        if (settings.userAgent.str != IntPtr.Zero)
        {
            settings.userAgent.Free();
        }
        // Free the CefSettings structure memory if necessary
        LocalFree(Marshal.UnsafeAddrOfPinnedArrayElement(new[] { settings }, 0));
    }
}

public class CefConfiguration
{
    public CefSettings Settings { get; private set; }

    public CefConfiguration()
    {
        Settings = CefSettings.Alloc();
    }

    public void SetBrowserSubprocessPath(string path)
    {
        Settings.browserSubprocessPath = Marshal.StringToHGlobalUni(path);
    }

    public void SetUserAgent(string userAgent)
    {
        Settings.userAgent = CefString.Create(userAgent);
    }

    public void SetCachePath(int cachePath)
    {
        Settings.cachePath = cachePath;
    }

    public void SetLogSeverity(CefLogSeverity severity)
    {
        Settings.logSeverity = severity;
    }

    public void Dispose()
    {

