using System;
 
namespace Product
{
    class Checker
    {
        static void Main(string[] args)
        {
            double sum = 0.0;
            int prod = 1;
            double recsum = 0.0;
            for (int i = 1; i < 11; i++)
            {
                sum += i;
                prod *= i;
                recsum += 1.0 / i;
            }
            double avg = sum / 10.0;
            double gmean = Math.Pow(prod, 0.1);
            double hmean = 10.0 / recsum;
            Console.WriteLine("Average: {0}, Geometric mean: {1}, Harmonic mean: {2}", avg, gmean, hmean);
            if (avg >= gmean && gmean >= hmean)
            {
                Console.WriteLine("Correct calculation");
            }
            else
            {
                Console.WriteLine("Incorrect calculation");
            }
            Console.ReadKey();
        }
    }
}

