namespace HeuristicLab.Optimization {
  [Item("SimulationEnvelope", "Base class for simulation results storage and management")]
  [StorableType("8A9F4E2B-3D0C-4F7D-9B1E-7C8D6A3F5B2E")]
  public abstract class SimulationEnvelope : Item, ISimulationEnvelope {
    [Storable]
    private IEnumerable<double> rawOutput;
    [Storable]
    private double fitnessScore;

    [VisibleName("Raw Output")]
    [Category("Simulation Data")]
    public virtual IEnumerable<double> RawOutput {
      get { return rawOutput; }
      protected set { rawOutput = value; }
    }

    [VisibleName("Fitness Score")]
    [Category("Performance Metrics")]
    public virtual double FitnessScore {
      get { return fitnessScore; }
      protected set { fitnessScore = value; }
    }

    [StorableConstructor]
    protected SimulationEnvelope(StorableConstructorFlag deserializing) : base(deserializing) { }

    protected SimulationEnvelope(SimulationEnvelope original, Cloner cloner)
      : base(original, cloner) {
      rawOutput = original.rawOutput != null ? new List<double>(original.rawOutput) : null;
      fitnessScore = original.fitnessScore;
    }

    protected SimulationEnvelope() : base() { }

    protected SimulationEnvelope(bool testMode) : this() {
      if (testMode) {
        RawOutput = new List<double> { 0.1, 0.5, 0.9 };
        FitnessScore = 0.82;
      }
    }

    public override IDeepCloneable Clone(Cloner cloner) {
      return new SimulationEnvelope(this, cloner);
    }

    public virtual void Reset() {
      rawOutput = null;
      fitnessScore = double.NaN;
    }

    public virtual void AddDataPoint(double value) {
      var list = rawOutput != null ? new List<double>(rawOutput) : new List<double>();
      list.Add(value);
      RawOutput = list;
    }

    public virtual void CalculateAggregateMetrics() {
      if (rawOutput == null) return;
      // Placeholder for actual metric calculation logic
      FitnessScore = new Statistics.Mean().Calculate(rawOutput);
    }

    [StorableHook(HookType.AfterDeserialization)]
    private void AfterDeserialization() {
      if (rawOutput == null) rawOutput = new List<double>();
    }

    public override string ToString() {
      return $"Fitness: {FitnessScore:0.####}, Data Points: {RawOutput?.Count() ?? 0}";
    }
  }
}

