    class Stack
    {
        static void Main(string[] args)
        {
            const int min = 1, max = 13;
            List<Triple> solutions90 = new List<Triple>();
            List<Triple> solutions60 = new List<Triple>();
            List<Triple> solutions120 = new List<Triple>();

            for (int a = min; a <= max; ++a)
            {
                int a2 = a * a;
                for (int b = a; b <= max; ++b)
                {
                    int b2 = b * b, ab = a * b;
                    int c2 = a2 + b2;
                    int c = isqrt(c2);
                    if (c <= max && c * c == c2)
                        solutions90.Add(new Triple(a, b, c));
                    else
                    {
                        c2 = a2 + b2 - ab;
                        c = isqrt(c2);
                        if (c <= max && c * c == c2)
                            solutions60.Add(new Triple(a, b, c));
                        else
                        {
                            c2 = a2 + b2 + ab;
                            c = isqrt(c2);
                            if (c <= max && c * c == c2)
                                solutions120.Add(new Triple(a, b, c));
                        }
                    }
                }
            }

            Console.WriteLine("There are " + solutions60.Count + " solutions for gamma = 60 degrees:");
            print_vector(solutions60);

            Console.WriteLine("There are " + solutions90.Count + " solutions for gamma = 90 degrees:");
            print_vector(solutions90);

            Console.WriteLine("There are " + solutions120.Count + " solutions for gamma = 120 degrees:");
            print_vector(solutions120);

            const int max2 = 10000;
            int count = 0;
            for (int a = min; a <= max2; ++a)
            {
                for (int b = a + 1; b <= max2; ++b)
                {
                    int c2 = a * a + b * b - a * b;
                    int c = isqrt(c2);
                    if (c <= max2 && c * c == c2)
                        ++count;
                }
            }
            Console.WriteLine("There are " + count + " solutions for gamma = 60 degrees in the range " + min + " to " + max2 + " where the sides are not all of the same length.");
            Console.ReadLine();
        }

