public interface IUnitLoader
{
    IEnumerable<UnitNode> LoadSynonyms();
    IEnumerable<Pairings> LoadFormPairings(IEnumerable<UnitNode> synonyms);
}

public class StaticUnitLoader : IUnitLoader
{
    private readonly IDataStore store;

    public StaticUnitLoader(IDataStore dataStore)
    {
        store = dataStore;
    }

    public IEnumerable<UnitNode> LoadSynonyms()
    {
        var synonyms = store.GetUnitSynonyms()
                            .Distinct()
                            .OrderBy(s => s.Name)
                            .Select(s => new UnitNode(s))
                            .ToList();

        return synonyms;
    }

    public IEnumerable<Pairings> LoadFormPairings(IEnumerable<UnitNode> synonyms)
    {
        var pairings = new List<Pairings>();

        foreach (var unit in synonyms)
        {
            var ingredientForms = store.GetIngredientForms(unit.Name);
            foreach (var form in ingredientForms)
            {
                pairings.Add(new Pairings
                {
                    IngredientForm = new IngredientForm(form),
                    Synonym = unit
                });
            }
        }

        return pairings.Distinct().ToList();
    }
}

public class UnitNode
{
    public string Name { get; private set; }

    public UnitNode(string name)
    {
        Name = name;
    }
}

public class Pairings
{
    public IngredientForm IngredientForm { get; set; }
    public UnitNode Synonym { get; set; }
}

public class IngredientForm
{
    public string Form { get; private set; }

    public IngredientForm(string form)
    {
        Form = form;
    }
}

public interface IDataStore
{
    IEnumerable<string> GetUnitSynonyms();
    IEnumerable<string> GetIngredientForms(string unitName);
}

// Example usage
public class Matrix
{
    public static void Main(string[] args)
    {
        IDataStore dataStore = new InMemoryDataStore(); // Assume this is properly implemented
        IUnitLoader unitLoader = new StaticUnitLoader(dataStore);

        var synonyms = unitLoader.LoadSynonyms();
        var pairings = unitLoader.LoadFormPairings(synonyms);

        // Output or process the loaded synonyms and their pairings as needed
        foreach (var pairing in pairings)
        {
            Console.WriteLine($"Ingredient Form: {pairing.IngredientForm.Form}, Synonym: {pairing.Synonym.Name}");
        }
    }
}

