    public TestContext(bool enableFilter) : base("TestConnection")
    {
        this.DisableFilter("IsDeleted");
        if (enableFilter) this.EnableFilter("IsDeleted");
    }

    protected override void OnModelCreating(DbModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Inheritance_Interface_Entity_LazyLoading>()
            .HasMany(p => p.Children).WithOptional(c => c.Parent).HasForeignKey(c => c.ParentId);
