public class TestSceneLoader : LoadingScene
{
    private IFont _font;
    private Vector2 _position;

    public TestSceneLoader(Scene targetScene) : base(targetScene)
    {
    }

    protected override void LoadContent(IContentLoader loader)
    {
        base.LoadContent(loader);
        _font = loader.Load<IFont>("Fonts/DefaultFont");
    }

    protected override void OnCompleted()
    {
        base.OnCompleted();
        this.TransitionManager.Add(new SlideTransition(this.TargetScene, SlideDirection.Left, 1.0f));
    }

    protected override void Render(IRenderManager renderManager)
    {
        base.Render(renderManager);

        renderManager.GraphicsDevice.Clear(Color.Black);

        if (_font != null)
        {
            string progressText = $"Loading: {this.CompletedElements} / {this.TotalElements}";
            Vector2 textSize = _font.MeasureString(progressText);

            _position = new Vector2(
                (renderManager.GraphicsDevice.Width - textSize.X) / 2,
                (renderManager.GraphicsDevice.Height - textSize.Y) / 2
            );

            renderManager.Render(_font, progressText, _position, Color.White);
        }
    }
}

