using System.Text.Json;

namespace YourNamespace
{
    public class JsonWebKeysResult : IEndpointResult
    {
        public JsonWebKeysResult(IEnumerable<JsonWebKey> webKeys, long? maxAge = null)
        {
            WebKeys = webKeys;
            MaxAge = maxAge;
        }

        public IEnumerable<JsonWebKey> WebKeys { get; }
        public long? MaxAge { get; }

        public async Task ExecuteAsync(HttpContext context)
        {
            context.Response.ContentType = "application/json";
            context.Response.Headers.Add("Cache-Control", "no-store, no-cache, must-revalidate");
            context.Response.Headers.Add("Pragma", "no-cache");

            if (MaxAge.HasValue)
            {
                SetCache(context, MaxAge.Value);
            } else {
                SetCache(context, 3600); // Default cache for 1 hour
            }

            var jwks = new { keys = WebKeys };
            await WriteJsonAsync(context, jwks);
        }

        private void SetCache(HttpContext context, long maxAge)
        {
            context.Response.Headers["Cache-Control"] = $"public, max-age={maxAge}";
            context.Response.Headers["Expires"] = DateTime.UtcNow.AddSeconds(maxAge).ToString("r");
        }

        private async Task WriteJsonAsync(HttpContext context, object value)
        {
            var json = JsonSerializer.Serialize(value, new JsonSerializerOptions { WriteIndented = false });
            await context.Response.WriteAsync(json);
        }
    }
}

