class Graph
{
    private List<string> vertices;
    private int numVertices;
    private List<List<bool>> adjacency;
 
    public Graph(string s, List<(int, int)> edges)
    {
        vertices = s.Split(", ");
        numVertices = vertices.Count;
        adjacency = new List<List<bool>>();
        for (int i = 0; i < numVertices; i++)
        {
            adjacency.Add(new List<bool>());
            for (int j = 0; j < numVertices; j++)
            {
                adjacency[i].Add(false);
            }
        }
        foreach (var edge in edges)
        {
            adjacency[edge.Item1][edge.Item2] = true;
        }
    }
 
    private bool hasDependency(int r, List<int> todo)
    {
        return todo.Any(it => adjacency[r][it]);
    }
 
    public List<string> topoSort()
    {
        List<string> result = new List<string>();
        List<int> todo = new List<int>();
        for (int i = 0; i < numVertices; i++)
        {
            todo.Add(i);
        }
        try
        {
            while (todo.Count > 0)
            {
                for (int i = 0; i < todo.Count; i++)
                {
                    int r = todo[i];
                    if (!hasDependency(r, todo))
                    {
                        todo.RemoveAt(i);
                        result.Add(vertices[r]);
                        break;
                    }
                }
                throw new Exception("Graph has cycles");
            }
        }
        catch (Exception e)
        {
            Console.WriteLine(e);
            return null;
        }
        return result;
    }
}
 
