namespace Logger
{
    class Account
    {
        static void Main(string[] args)
        {
            var engine = new Random();
            var results = new int[10];
            for (int i = 0; i < 1000000; i++)
            {
                results[one_of_n(10, engine)]++;
            }
            foreach (var item in results)
            {
                Console.Write(item + " ");
            }
            Console.ReadKey();
        }
 
        static int one_of_n(int n, Random engine)
        {
            int choice = 0;
            for (int i = 0; i < n; i++)
            {
                if (engine.Next(0, i + 1) == 0)
                {
                    choice = i;
                }
            }
            return choice;
        }
    }
}

