using System;
using System.Collections.Generic;
using System.IO;

public struct TrackSection
{
    public int Length;
    public float Curvature;
    public float Height;
    public int Flags;
    public float LeftVergeWidth;
    public float RightVergeWidth;
    public List<TrackSectionCommand> Commands;

    public TrackSection(int length, float curvature, float height, int flags, float leftVergeWidth, float rightVergeWidth)
    {
        Length = length;
        Curvature = curvature;
        Height = height;
        Flags = flags;
        LeftVergeWidth = leftVergeWidth;
        RightVergeWidth = rightVergeWidth;
        Commands = new List<TrackSectionCommand>();
    }
}

public struct TrackSectionCommand
{
    public int CommandId;
    public List<int> Arguments;

    public TrackSectionCommand(int commandId, List<int> arguments)
    {
        CommandId = commandId;
        Arguments = arguments;
    }
}

public static class TrackSectionReader
{
    public static (int, List<TrackSection>) Read(BinaryReader reader, int startPosition)
    {
        reader.BaseStream.Position = startPosition;
        List<TrackSection> sections = new List<TrackSection>();
        TrackSection currentSection = new TrackSection(0, 0, 0, 0, 0, 0);

        while (true)
        {
            byte firstByte = reader.ReadByte();
            byte secondByte = reader.ReadByte();

            if (firstByte == 255 && secondByte == 255)
            {
                break;
            }

            if (firstByte == 255)
            {
                int commandId = secondByte;
                int argumentCount = reader.ReadByte();
                List<int> arguments = new List<int>();

                for (int i = 0; i < argumentCount; i++)
                {
                    arguments.Add(reader.ReadByte());
                }

                currentSection.Commands.Add(new TrackSectionCommand(commandId, arguments));
            }
            else
            {
                if (currentSection.Length != 0)
                {
                    sections.Add(currentSection);
                }

                currentSection = new TrackSection(
                    (firstByte << 8) | secondByte,
                    reader.ReadSingle(),
                    reader.ReadSingle(),
                    reader.ReadInt32(),
                    reader.ReadSingle(),
                    reader.ReadSingle()
                );
            }
        }

        if (currentSection.Length != 0)
        {
            sections.Add(currentSection);
        }

