#if ANDROID
using Android.Net;
using Android.Net.Wifi;
using Android.App;
#endif

public static class NetUtility
{
    private static readonly Lazy<byte[]> s_randomMacBytes = new Lazy<byte[]>(GenerateRandomMac);
    private static readonly SHA1 s_sha1 = SHA1.Create();
    private const int MacAddressLength = 6;

    private static byte[] GenerateRandomMac()
    {
        byte[] bytes = new byte[MacAddressLength];
        MWCRandom.GetBytes(bytes);
        bytes[0] &= 0xFE;
        bytes[0] |= 0x02;
        return bytes;
    }

    public static byte[] GetMacAddressBytes()
    {
#if ANDROID
        try
        {
            WifiManager wifiManager = (WifiManager)Application.Context.GetSystemService(Context.WifiService);
            if (wifiManager == null || !wifiManager.IsWifiEnabled)
                return s_randomMacBytes.Value;

            string mac = wifiManager.ConnectionInfo?.MacAddress;
            if (!string.IsNullOrEmpty(mac))
                return mac.Split(':').Select(b => Convert.ToByte(b, 16)).ToArray();
        }
        catch (Exception) { }
#endif
        return s_randomMacBytes.Value;
    }

    public static byte[] GetMyAddress()
    {
#if ANDROID
        try
        {
            WifiManager wifiManager = (WifiManager)Application.Context.GetSystemService(Context.WifiService);
            DhcpInfo dhcp = wifiManager?.DhcpInfo;
            if (dhcp == null) return new byte[4];

            byte[] bytes = BitConverter.GetBytes(dhcp.IpAddress);
            if (BitConverter.IsLittleEndian) Array.Reverse(bytes);
            return bytes;
        }
        catch (Exception)
        {
            return new byte[4];
        }
#else
        return new byte[4];
#endif
    }

    public static byte[] GetBroadcastAddress(byte[] ipBytes, byte[] maskBytes)
    {
        if (ipBytes.Length != 4 || maskBytes.Length != 4)
            throw new ArgumentException("Invalid IP/subnet");

        byte[] broadcast = new byte[4];
        for (int i = 0; i < 4; i++)
            broadcast[i] = (byte)(ipBytes[i] | (byte)~maskBytes[i]);
        return broadcast;
    }

    public static string ComputeSHAHash(byte[] input)
    {
        lock (s_sha1)
        {
            byte[] hash = s_sha1.ComputeHash(input);
            return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
        }
    }
}

