public class GameEventArgs : EventArgs
{
    public int TurnNumber { get; set; }
}

public class ViewModel
{
    public event EventHandler<GameEventArgs> TurnUpdated;

    private readonly List<StepViewModel> _steps = new List<StepViewModel>();
    private int _turnNumber;

    public IReadOnlyList<StepViewModel> Steps => _steps.AsReadOnly();
    public int TurnNumber
    {
        get => _turnNumber;
        private set
        {
            _turnNumber = value;
            OnTurnUpdated(new GameEventArgs { TurnNumber = value });
            SetCurrentStep(value);
        }
    }

    public ViewModel()
    {
        Initialize();
    }

    private void Initialize()
    {
        CreateStepViewModels();
        TurnUpdated += ViewModel_TurnUpdated;
    }

    private void CreateStepViewModels()
    {
        _steps.Add(new StepViewModel("Preparation"));
        _steps.Add(new StepViewModel("Action"));
        _steps.Add(new StepViewModel("Resolution"));
        _steps.Add(new StepViewModel("Cleanup"));
    }

    private void ViewModel_TurnUpdated(object sender, GameEventArgs e)
    {
        Console.WriteLine($"Turn updated to: {e.TurnNumber}");
    }

    public void Receive(int turnNumber)
    {
        TurnNumber = turnNumber;
    }

    private void SetCurrentStep(int turnNumber)
    {
        if (turnNumber < 0 || turnNumber >= _steps.Count) return;

        foreach (var step in _steps)
        {
            step.IsActive = false;
        }

        _steps[turnNumber].IsActive = true;
        Console.WriteLine($"Current step set to: {_steps[turnNumber].Name}");
    }
}

public class StepViewModel
{
    public string Name { get; }
    public bool IsActive { get; set; }

    public StepViewModel(string name)
    {
        Name = name;
        IsActive = false;
    }
}

// Example of usage
public class Employee
{
    public static void Main()
    {
        var viewModel = new ViewModel();
        viewModel.Receive(0); // Updates to Preparation step
        viewModel.Receive(1); // Updates to Action step
        viewModel.Receive(2); // Updates to Resolution step
        viewModel.Receive(3); // Updates to Cleanup step
    }
}

