    public class SqlConnectionFake
    {
        private readonly string _tableName;
        public List<Switch> Features { get; private set; }
        public Action OpenAction { get; set; }

        public SqlConnectionFake(string tableName)
        {
            _tableName = tableName;
            Features = new List<Switch>();
        }

        public void Open()
        {
            OpenAction?.Invoke();
        }

        public SqlCommandFake CreateCommand(string commandText)
        {
            if (commandText.Contains($"INSERT INTO {_tableName}"))
            {
                return new InsertSwitchCommandFake(commandText, this);
            }
            else if (commandText.Contains($"DELETE FROM {_tableName}"))
            {
                return new DeleteSwitchCommandFake(commandText, this);
            }
            else if (commandText.Contains($"SELECT * FROM {_tableName}"))
            {
                return new SelectSwitchCommandFake(commandText, this);
            }
            else if (commandText.Contains($"UPDATE {_tableName}"))
            {
                return new UpdateSwitchCommandFake(commandText, this);
            }
            else
            {
                throw new NotSupportedException("Command not supported.");
            }
        }
    }

