    public override void Initialize()
    {
        world = FSWorldComponent.World;

        // Create the basket body
        Body basketBody = BodyFactory.CreateBody(world, new FVector2(0, -5));
        basketBody.BodyType = BodyType.Dynamic;
        basketBody.IsBullet = true;

        // Attach bottom rectangle fixture to the basket
        AttachRectangle(basketBody, 2f, 0.2f, new FVector2(0, -0.1f), 0f, 0.3f, 0.2f);

        // Attach left rectangle fixture to the basket
        AttachRectangle(basketBody, 0.2f, 2f, new FVector2(-1, 0.9f), 0f, 0.3f, 0.2f);

        // Attach right rectangle fixture to the basket
        AttachRectangle(basketBody, 0.2f, 2f, new FVector2(1, 0.9f), 0f, 0.3f, 0.2f);

        // Create 5 small circular bodies
        for (int i = 0; i < 5; i++)
        {
            float radius = Random.Range(0.1f, 0.3f);
            float x = Random.Range(-3f, 3f);
            float y = Random.Range(5f, 10f);
            Body smallBody = BodyFactory.CreateBody(world, new FVector2(x, y));
            smallBody.BodyType = BodyType.Dynamic;
            smallBody.IsBullet = true;
            AttachCircle(smallBody, radius, 1f, new FVector2(0, 0), 0.3f, 0.2f);
        }
    }

    private void AttachRectangle(Body body, float width, float height, FVector2 offset, float angle, float restitution, float friction)
    {
        PolygonShape rectangleShape = new PolygonShape(PolygonShape.Box(width, height), 1f);
        Fixture fixture = body.CreateFixture(rectangleShape, 1f);
        fixture.Restitution = restitution;
        fixture.Friction = friction;
        fixture.Body.IsBullet = true;
        fixture.Body.SetTransform(fixture.Body.Position + offset, angle);
    }

    private void AttachCircle(Body body, float radius, float density, FVector2 offset, float restitution, float friction)
    {
        CircleShape circleShape = new CircleShape(radius, density);
        Fixture fixture = body.CreateFixture(circleShape, density);
        fixture.Restitution = restitution;
        fixture.Friction = friction;
        fixture.Body.IsBullet = true;
        fixture.Body.SetTransform(fixture.Body.Position + offset, 0f);
    }

    public override void Update(float deltaTime)
    {
        world.Step(deltaTime);
    }
}

