public interface IAuthenticate
{
    User AuthenticateUser(string hostName, string email, string password, IUnitOfWork unitOfWork);
}

public class DbAuthenticate : IAuthenticate
{
    private static readonly Logger logger = LogManager.GetCurrentClassLogger();

    public User AuthenticateUser(string hostName, string email, string password, IUnitOfWork unitOfWork)
    {
        logger.Info($"Attempting to authenticate user with email: {email} for host: {hostName}");

        try
        {
            var user = unitOfWork.Users.GetUserByEmail(email);

            if (user == null)
            {
                logger.Warn($"User with email: {email} not found.");
                throw new UserException("User not found.");
            }

            if (user.IsDeleted)
            {
                logger.Warn($"User with email: {email} is deleted.");
                throw new UserException("User is deleted.");
            }

            if (user.AcquisitionType != AcquisitionEnum.OnPremise)
            {
                logger.Warn($"User with email: {email} does not have on-premise acquisition.");
                throw new UserException("User does not have on-premise acquisition.");
            }

            var companyAccess = user.CompanyAccesses.FirstOrDefault(ca => ca.HostName == hostName);

            if (companyAccess == null)
            {
                logger.Warn($"User with email: {email} does not have access to host: {hostName}.");
                throw new UserException("User does not have access to the specified company.");
            }

using System;
using System.Collections.Generic;
