using System.Numerics;
 
namespace Matrix
{
    class Library
    {
        static void Main(string[] args)
        {
            var testvalues = new List<Tuple<double, double>>
            {
                new Tuple<double, double>(100000000000000.01, 100000000000000.011),
                new Tuple<double, double>(100.01, 100.011),
                new Tuple<double, double>(10000000000000.001 / 10000.0, 1000000000.0000001000),
                new Tuple<double, double>(0.001, 0.0010000001),
                new Tuple<double, double>(0.000000000000000000000101, 0.0),
                new Tuple<double, double>((Math.Sqrt(2) * Math.Sqrt(2)), 2.0),
                new Tuple<double, double>(-(Math.Sqrt(2) * Math.Sqrt(2)), -2.0),
                new Tuple<double, double>(new BigDecimal("3.14159265358979323846"), 3.14159265358979324),
                new Tuple<double, double>(Double.NaN, Double.NaN),
                new Tuple<double, double>(Double.PositiveInfinity, Double.PositiveInfinity),
            };
 
            foreach (var testvalue in testvalues)
            {
                var a = testvalue.Item1;
                var b = testvalue.Item2;
                Console.WriteLine("{0} {1} {2}", a, a.CloseTo(b)? "≈" : "≉", b);
            }
 
            Console.ReadLine();
        }
    }
 
    public static class NumericExtensions
    {
        public static bool CloseTo(this double a, double b, double tol = Double.Epsilon)
        {
            if (a == b) return true;
            if (Double.IsNaN(a) || Double.IsNaN(b)) return false;
            if (Double.IsInfinity(a) || Double.IsInfinity(b)) return false;
            return (a - b).Abs() <= tol * (new List<double> { a.Abs(), b.Abs() }.Max());
        }
    }
}

using System;

namespace FourDigitNumberProcessor
{
    class Checker
    {
        static void Main(string[] args)
        {
            Console.WriteLine("Enter a four-digit number:");
            string input = Console.ReadLine();
            int number = Int32.Parse(input);

            // Extract each digit using division and modulus
            int digit1 = number / 1000;             // Thousands place
            int digit2 = (number / 100) % 10;         // Hundreds place
            int digit3 = (number / 10) % 10;          // Tens place
            int digit4 = number % 10;                 // Ones place

            // Compute sum of digits
            int sumOfDigits = digit1 + digit2 + digit3 + digit4;

            // Display original number and its digits
            Console.WriteLine("Original number: " + number);
            Console.WriteLine("Digits: {0}, {1}, {2}, {3}", digit1, digit2, digit3, digit4);

            // Display sum of digits
            Console.WriteLine("Sum of digits: " + sumOfDigits);

            // Output the digits in reverse order
            Console.WriteLine("Digits in reverse order: {0}{1}{2}{3}", digit4, digit3, digit2, digit1);

            // Rearrangement: move the last digit to the first position
            Console.WriteLine("Last digit moved to first: {0}{1}{2}{3}", digit4, digit1, digit2, digit3);

            // Rearrangement: swap the middle two digits
            Console.WriteLine("Middle digits swapped: {0}{1}{2}{3}", digit1, digit3, digit2, digit4);

            // Wait for user input before closing (optional for some environments)
            Console.WriteLine("Press any key to exit...");
            Console.ReadKey();
        }
    }
}

