        private void PopulateTree()
        {
            tilesetFilesList.Nodes.Clear();
            foreach (var tileset in tilesets)
            {
                var node = new Node
                {
                    Text = tileset.File ?? $"Tileset ({tileset.Size.X}x{tileset.Size.Y})",
                    Tag = tileset
                };
                tilesetFilesList.Nodes.Add(node);
            }
            UpdateLoadButtonState();
        }

        private void node_NodeDoubleClick(object sender, TreeNodeMouseEventArgs e)
        {
            if (tilesetBrowseDialog.ShowDialog() == DialogResult.OK)
            {
                var tileset = e.Node.Tag as Tileset;
                tileset.File = tilesetBrowseDialog.FileName;
                e.Node.Text = tileset.File;
                UpdateLoadButtonState();
            }
        }

        private void UpdateLoadButtonState()
        {
            btnLoad.Enabled = tilesets.All(t => !string.IsNullOrEmpty(t.File));
        }

