namespace SshServer
{
    public abstract class ServerChannel : IDisposable
    {
        protected ISession Session { get; private set; }
        protected uint LocalChannelNumber { get; private set; }
        protected uint RemoteChannelNumber { get; private set; }
        protected uint LocalWindowSize { get; private set; }
        protected uint LocalPacketSize { get; private set; }
        protected uint RemoteWindowSize { get; private set; }
        protected uint RemotePacketSize { get; private set; }

        public event EventHandler<ChannelOpenEventArgs> ChannelOpened;

        protected ServerChannel(ISession session)
        {
            Session = session ?? throw new ArgumentNullException(nameof(session));
        }

        public void Initialize(uint localChannelNumber, uint remoteChannelNumber, uint remoteWindowSize, uint remotePacketSize)
        {
            LocalChannelNumber = localChannelNumber;
            RemoteChannelNumber = remoteChannelNumber;
            RemoteWindowSize = remoteWindowSize;
            RemotePacketSize = remotePacketSize;

            // Set default local window size and packet size
            LocalWindowSize = 0x20000;
            LocalPacketSize = 0x4000;

            // Raise the ChannelOpened event
            ChannelOpened?.Invoke(this, new ChannelOpenEventArgs(RemoteChannelNumber, RemoteWindowSize, RemotePacketSize));
        }

        protected void SendMessage(ChannelOpenConfirmationMessage message)
        {
            if (Session == null)
                throw new InvalidOperationException("Session is not initialized.");

            Session.SendMessage(message);
        }

        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }

        protected virtual void Dispose(bool disposing)
        {
            if (disposing)
            {
                // Remove event handlers
                ChannelOpened = null;

                // Additional cleanup can be performed here if necessary
            }
        }

        ~ServerChannel()
        {
            Dispose(false);
        }
    }

