using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Cors;
using System.Net.Mime;

[ApiController]
[Route("api/[controller]")]
[EnableCors("AllowSpecificOrigin")]
public class DiscountsController : ControllerBase
{
    private readonly IDiscountApplicationService _discountService;
    private readonly IGalleryApplicationService _galleryService;

    public DiscountsController(
        IDiscountApplicationService discountService,
        IGalleryApplicationService galleryService)
    {
        _discountService = discountService ??
            throw new ArgumentNullException(nameof(discountService));
        _galleryService = galleryService ??
            throw new ArgumentNullException(nameof(galleryService));
    }

    [HttpGet("list")]
    [ProducesResponseType(typeof(IEnumerable<Branch>), 200)]
    [ProducesResponseType(400)]
    public async Task<IActionResult> GetAllDiscountsAsync(
        [FromQuery] DateTime? synchronizationDate = null)
    {
        try
        {
            if (synchronizationDate.HasValue && synchronizationDate > DateTime.UtcNow)
            {
                return BadRequest("Invalid synchronization date");
            }

            var discounts = await _discountService
                .GetDiscountsAsync(synchronizationDate);

            return Ok(discounts);
        }
        catch (Exception ex)
        {
            return StatusCode(500, $"Internal server error: {ex.Message}");
        }
    }

    [HttpGet("images/{imageId}")]
    [ProducesResponseType(200)]
    [ProducesResponseType(404)]
    public async Task<IActionResult> GetImageAsync(string imageId)
    {
        try
        {
            var imageStream = await _galleryService.GetImageStreamAsync(imageId);

            if (imageStream == null)
                return NotFound();

            return File(imageStream, MediaTypeNames.Image.Jpeg);
        }
        catch
        {
            return StatusCode(500, "Error retrieving image");
        }
    }

    [HttpGet("logos/{logoId}")]
    [ProducesResponseType(200)]
    [ProducesResponseType(404)]
    public async Task<IActionResult> GetLogoAsync(string logoId)
    {
        try
        {
            var logoStream = await _galleryService.GetLogoStreamAsync(logoId);

            if (logoStream == null)
                return NotFound();

            return File(logoStream, MediaTypeNames.Image.Png);
        }
        catch
        {
            return StatusCode(500, "Error retrieving logo");
        }
    }
}

using System;
using System.IO;

public interface IConfigurationManager
{
    void Initialize();
    void CleanUp();
}

public class JovianPaths
{
    public string RenderServer { get; private set; }
    public string RenderCache { get; private set; }
    public string CssCompiler { get; private set; }

    public JovianPaths(string baseDirectory)
    {
        RenderServer = Path.Combine(baseDirectory, "RenderServer");
        RenderCache = Path.Combine(baseDirectory, "Cache");
        CssCompiler = Path.Combine(baseDirectory, "CssCompiler");
    }

    public void ValidateAndCreateDirectories()
    {
        CreateDirectory(RenderServer);
        CreateDirectory(RenderCache);
        CreateDirectory(CssCompiler);
    }

    private void CreateDirectory(string path)
    {
        if (!Directory.Exists(path))
        {
            try
            {
                Directory.CreateDirectory(path);
                Console.WriteLine($"Directory created: {path}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error creating directory {path}: {ex.Message}");
            }
        }
    }

    public void CleanUpDirectories()
    {
        CleanUpDirectory(RenderCache);
    }

    private void CleanUpDirectory(string path)
    {
        if (Directory.Exists(path))
        {
            try
            {
                Directory.Delete(path, true);
                Console.WriteLine($"Directory cleaned up: {path}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error cleaning directory {path}: {ex.Message}");
            }
        }
    }
}

public class JovianEnvironment : IConfigurationManager
{
    public JovianPaths MyPaths { get; private set; }

    public JovianEnvironment(string baseDirectory)
    {
        MyPaths = new JovianPaths(baseDirectory);
    }

    public void Initialize()
    {
        Console.WriteLine("Initializing Jovian Environment...");
        MyPaths.ValidateAndCreateDirectories();
    }

    public void CleanUp()
    {
        Console.WriteLine("Cleaning up Jovian Environment...");
        MyPaths.CleanUpDirectories();
    }
}

