public static bool is_prime(uint n)
{
    uint p;
    if (!(n & 1) || n < 2 ) return n == 2;
 
    /* comparing p*p <= n can overflow */
    for (p = 3; p <= n/p; p += 2)
        if (!(n % p)) return false;
    return true;
}

