using UnityEngine;

public class ControlFeuVehicule : MonoBehaviour
{
    public GameObject[] feux; // Array of light game objects
    public Material feuVert; // Material for green light
    public Material feuOrange; // Material for orange light
    public Material feuRouge; // Material for red light
    public Material feuVertPieton; // Material for pedestrian green light
    public Material feuRougePieton; // Material for pedestrian red light
    public GameObject feuPieton; // Pedestrian light game object

    private int cpt = 0; // Counter for timing
    private int changementFeu = 100; // Threshold for light change
    private int changementEtat = 0; // State of the traffic lights

    void Start()
    {
        // Initialize random interval for light changes
        changementFeu = Random.Range(80, 120);
        SetTrafficLightState(0); // Start with red light
    }

    void Update()
    {
        cpt++;
        if (cpt >= changementFeu)
        {
            cpt = 0;
            // Randomly determine the next state
            changementEtat = Random.Range(0, 3);
            SetTrafficLightState(changementEtat);
            // Set new random interval for next light change
            changementFeu = Random.Range(80, 120);
        }
    }

    void SetTrafficLightState(int state)
    {
        switch (state)
        {
            case 0: // Red light for vehicles, Green for pedestrians
                SetFeu(feuRouge, feuVertPieton);
                break;
            case 1: // Orange light for vehicles, Red for pedestrians
                SetFeu(feuOrange, feuRougePieton);
                break;
            case 2: // Green light for vehicles, Red for pedestrians
                SetFeu(feuVert, feuRougePieton);
                break;
        }
    }

    void SetFeu(Material vehiculeFeu, Material pietonFeu)
    {
        foreach (GameObject feu in feux)
        {
            Renderer renderer = feu.GetComponent<Renderer>();
            if (renderer != null)
            {
                renderer.material = vehiculeFeu;
            }
        }

        Renderer pietonRenderer = feuPieton.GetComponent<Renderer>();
        if (pietonRenderer != null)
        {
            pietonRenderer.material = pietonFeu;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Text;
using System.IO;

namespace KISS
{
    /// <summary>
    /// A manifest file is a file that has a version and references a bunch of patch files.
    /// </summary>
    public class ManifestFile
    {
        public string Version = "";
        public List<PatchFile> PatchFiles = new List<PatchFile>();

        public ManifestFile(string Path, string Version, List<PatchFile> PatchFiles)
        {
            bool HasURLs = false;
            BinaryWriter Writer = new BinaryWriter(File.Create(Path));
            Writer.Write((string)Version);

            if (PatchFiles[0].URL != "")
                HasURLs = true;

            foreach (PatchFile PFile in PatchFiles)
            {
                if (!HasURLs)
                    Writer.Write((string)PFile.Address + "," + PFile.FileHash);
                else
                    Writer.Write((string)PFile.Address + "," + PFile.FileHash + PFile.URL);
            }

            Writer.Flush();
            Writer.Close();
        }

        /// <summary>
        /// Creates a ManifestFile instance from a downloaded stream.
        /// </summary>
        /// <param name="ManifestStream"></param>
        public ManifestFile(Stream ManifestStream)
        {
            BinaryReader Reader = new BinaryReader(ManifestStream);
            Reader.BaseStream.Position = 0; //IMPORTANT!

            Version = Reader.ReadString();
            int NumFiles = Reader.ReadInt32();

            for(int i = 0; i < NumFiles; i++)
            {
                string PatchFileStr = Reader.ReadString();
                string[] SplitPatchFileStr = PatchFileStr.Split(",".ToCharArray());

                PatchFiles.Add(new PatchFile()
                {
                    Address = SplitPatchFileStr[0],
                    FileHash = SplitPatchFileStr[1],
                    URL = SplitPatchFileStr[2]
                });
            }

            Reader.Close();
        }
    }
}

