class InvertedIndex
{
    static Dictionary<TItem, IEnumerable<TKey>> Invert<TKey, TItem>(Dictionary<TKey, IEnumerable<TItem>> dictionary)
    {
        return dictionary
            .SelectMany(keyValuePair => keyValuePair.Value.Select(item => new KeyValuePair<TItem, TKey>(item, keyValuePair.Key)))
            .GroupBy(keyValuePair => keyValuePair.Key)
            .ToDictionary(group => group.Key, group => group.Select(keyValuePair => keyValuePair.Value));
    }
 
    static void Main()
    {
        Console.Write("files: ");
        var files = Console.ReadLine();
        Console.Write("find: ");
        var find = Console.ReadLine();
        var dictionary = files.Split().ToDictionary(file => file, file => File.ReadAllText(file).Split().AsEnumerable());
        Console.WriteLine("{0} found in: {1}", find, string.Join(" ", Invert(dictionary)[find]));
    }
}

using System;
using SharpGL.SceneGraph.Cameras;
using SharpGL.SceneGraph;
using SharpGL;

public class ArcBallCamera : PerspectiveCamera
{
    private ArcBall arcBall;
    private float radius = 5.0f;
    private float theta = 0.0f;
    private float phi = 0.0f;

    public ArcBallCamera(string name) : base(name)
    {
        arcBall = new ArcBall();
        InitializeCamera();
    }

    private void InitializeCamera()
    {
        SetCameraPosition(radius);
        arcBall.SetBounds(800, 600);
    }

    private void SetCameraPosition(float distance)
    {
        Position = new OpenGLVector(0, 0, distance);
        UpdateViewMatrix();
    }

    public void TransformProjectionMatrix(OpenGL gl, int width, int height)
    {
        gl.MatrixMode(OpenGL.GL_PROJECTION);
        gl.LoadIdentity();
        SetPerspective(gl, 45.0f, (float)width / height, 0.1f, 1000.0f);

        gl.MatrixMode(OpenGL.GL_MODELVIEW);
        gl.LoadIdentity();
        UpdateViewMatrix();
    }

    private void SetPerspective(OpenGL gl, float fov, float aspect, float near, float far)
    {
        gl.Perspective(fov, aspect, near, far);
    }

    public void UpdateViewMatrix()
    {
        var lookAt = arcBall.GetRotationVector();
        var eye = new OpenGLVector(Position.X + lookAt.X, Position.Y + lookAt.Y, Position.Z + lookAt.Z);
        OpenGLMatrix.LookAt(eye, Position, new OpenGLVector(0, 1, 0));
    }

    public void MouseDrag(int x, int y)
    {
        arcBall.MouseDrag(x, y);
        UpdateViewMatrix();
    }

    public void MouseDown(int x, int y)
    {
        arcBall.MouseDown(x, y);
    }

    public void MouseUp(int x, int y)
    {
        arcBall.MouseUp(x, y);
    }

    public void Reset()
    {
        arcBall.Reset();
        SetCameraPosition(radius);
    }
}

