using System;
using System.Collections;
using System.Collections.Generic;

public class StringDictionary : IEnumerable<KeyValuePair<string, string>>
{
    private Hashtable _values;

    public StringDictionary()
    {
        _values = new Hashtable();
    }

    public class DuplicateKeyException : Exception
    {
        public DuplicateKeyException(string message) : base(message) { }
    }

    public void Add(string key, string value)
    {
        if (string.IsNullOrEmpty(key))
        {
            throw new ArgumentNullException(nameof(key), "Key cannot be null or empty");
        }

        if (_values.ContainsKey(key))
        {
            throw new DuplicateKeyException($"Key '{key}' already exists in the dictionary");
        }

        _values[key] = value;
    }

    public string this[string key]
    {
        get
        {
            if (!_values.ContainsKey(key))
            {
                throw new KeyNotFoundException($"Key '{key}' not found in dictionary");
            }
            return (string)_values[key];
        }
        set
        {
            if (string.IsNullOrEmpty(key))
            {
                throw new ArgumentNullException(nameof(key), "Key cannot be null or empty");
            }
            _values[key] = value;
        }
    }

    public bool ContainsKey(string key)
    {
        return _values.ContainsKey(key);
    }

    public void Clear()
    {
        _values.Clear();
    }

    public int Count
    {
        get { return _values.Count; }
    }

    public string[] Keys
    {
        get
        {
            string[] keys = new string[_values.Count];
            _values.Keys.CopyTo(keys, 0);
            return keys;
        }
    }

    public string[] Values
    {
        get
        {
            string[] values = new string[_values.Count];
            _values.Values.CopyTo(values, 0);
            return values;
        }
    }

    public bool Remove(string key)
    {
        if (_values.ContainsKey(key))
        {
            _values.Remove(key);
            return true;
        }
        return false;
    }

    public IEnumerator<KeyValuePair<string, string>> GetEnumerator()
    {
        foreach (DictionaryEntry entry in _values)
        {
            yield return new KeyValuePair<string, string>((string)entry.Key, (string)entry.Value);
        }
    }

    IEnumerator IEnumerable.GetEnumerator()
    {
        return GetEnumerator();
    }
}

namespace RosettaCode.ProperDivisors
{
    using System;
    using System.Collections.Generic;
    using System.Linq;
 
    internal static class Cache
    {
        private static IEnumerable<int> ProperDivisors(int number)
        {
            return
                Enumerable.Range(1, number / 2)
                    .Where(divisor => number % divisor == 0);
        }
 
        private static void Main()
        {
            foreach (var number in Enumerable.Range(1, 10))
            {
                Console.WriteLine("{0}: {{{1}}}", number,
                    string.Join(", ", ProperDivisors(number)));
            }
 
            var record = Enumerable.Range(1, 20000).Select(number => new
            {
                Number = number,
                Count = ProperDivisors(number).Count()
            }).OrderByDescending(currentRecord => currentRecord.Count).First();
            Console.WriteLine("{0}: {1}", record.Number, record.Count);
        }
    }
}

