using UnityEngine;
using System.Collections;

public class InventoryBehavior : MonoBehaviour
{
    private const int _MaxAcornAmount = 100; // Maximum acorns the player can hold
    private int _acornsPerDay = 20; // Acorns required for each day
    private int acornCount = 0; // Total acorns collected
    private bool[] _days = new bool[5]; // Active state of each day
    public bool InventoryFull { get; private set; } = false;
    public bool InTheNest { get; private set; } = false;

    void Start()
    {
        InitializeGame();
    }

    void Update()
    {
        if (InTheNest)
        {
            CheckInventory();
        }
    }

    private void InitializeGame()
    {
        for (int i = 0; i < _days.Length; i++)
        {
            _days[i] = false; // Set all days to inactive initially
        }
        acornCount = 0; // Reset acorn count
        InventoryFull = false; // Inventory not full at start
        SetDay(0, true); // Activate the first day
    }

    private void OnTriggerEnter(Collider other)
    {
        if (other.CompareTag("nest"))
        {
            InTheNest = true;
            UpdateAcornPerDay();
        }
    }

    private void UpdateAcornPerDay()
    {
        if (acornCount >= _MaxAcornAmount)
        {
            InventoryFull = true;
            return;
        }

        // Increment acorn count when player is in the nest
        if (InTheNest)
        {
            acornCount += 1; // Collect an acorn
            CheckInventory();
        }
    }

    private void CheckInventory()
    {
        if (InventoryFull)
        {
            Debug.Log("Inventory is full! Cannot collect more acorns.");
            return;
        }

        if (acornCount >= _acornsPerDay)
        {
            TransitionToNextDay();
        }
    }

    private void TransitionToNextDay()
    {
        for (int i = 0; i < _days.Length; i++)
        {
            if (_days[i])
            {
                if (i + 1 < _days.Length)
                {
                    SetDay(i, false); // Deactivate current day
                    SetDay(i + 1, true); // Activate next day
                    acornCount = 0; // Reset acorn count for the new day
                    Debug.Log($"Transitioning to Day {i + 2}!");
                }
                break;
            }
        }
    }

    private void SetDay(int day, bool state)
    {
        if (day >= 0 && day < _days.Length)
        {
            _days[day] = state;
            Debug.Log($"Day {day + 1} status set to {state}");
        }
    }

    public bool GetDay(int day)
    {

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Security.Cryptography;
using System.Threading;
 
namespace Converter
{
    class Tree
    {
        static void Main(string[] args)
        {
            var hh = new string[] {
                "1115dd800feaacefdf481f1f9070374a2a81e27880f187396db67958b207cbad",
                "3a7bd3e2360a3d29eea436fcfb7e44c735d117c42d1c1835420b6b9942dd4f1b",
                "74e1bb62f8dabb8125a58852b63bdf6eaef667cb56ac7f7cdba6d7305c50a22f",
            };
            var hd = new byte[hh.Length][];
            for (int i = 0; i < hh.Length; i++)
            {
                hd[i] = new byte[32];
                var hex = hh[i];
                for (int j = 0; j < 32; j++)
                {
                    hd[i][j] = (byte)Convert.ToInt32(hex.Substring(j * 2, 2), 16);
                }
            }
            var wg = new CountdownEvent(26);
            for (char c = 'a'; c <= 'z'; c++)
            {
                var c1 = c;
                var hd1 = hd;
                var wg1 = wg;
                Task.Run(() => bf4(c1, hd1, wg1));
            }
            wg.Wait();
        }
 
        static void bf4(char c, byte[][] hd, CountdownEvent wg)
        {
            var p = new byte[] { (byte)c, (byte)'a', (byte)'a', (byte)'a', (byte)'a' };
            var p1 = p.Skip(1).ToArray();
            while (true)
            {
                var ph = SHA256.Create().ComputeHash(p);
                for (int i = 0; i < hd.Length; i++)
                {
                    if (hd[i].SequenceEqual(ph))
                    {
                        Console.WriteLine(Encoding.ASCII.GetString(p) + " " + hh[i]);
                    }
                }
                for (int i = 0; i < p1.Length; i++)
                {
                    if (p1[i] < 'z')
                    {
                        p1[i]++;
                        break;
                    }
                    p1[i] = 'a';
                }
                wg.Signal();
                return;
            }
        }
    }
}

using UnityEngine;
using System.Collections;
using System.Collections.Generic;

namespace IsoUnity {
    public class IsoUnityCollectionType : IsoUnityType
    {
        [SerializeField]
        private IsoUnityList l;
        [SerializeField]
        private string whatIs = "";

        public override IsoUnityType clone()
        {
            return IsoUnityCollectionType.CreateInstance<IsoUnityCollectionType>();
        }

        public override bool canHandle(object o)
        {
            return o is IList<object>;
        }

        public override object Value
        {
            get
            {
                if (whatIs == l.GetType().ToString()) return l;

                return null;
            }
            set
            {
                if (value is IList<object>) {
                    var lo = value as IList<object>;
                    if (lo is IsoUnityList)
                    {
                        l = lo as IsoUnityList;
                    }
                    else
                    {
                        var myList = IsoUnityList.CreateInstance<IsoUnityList>();
                        foreach (var o in lo)
                            myList.Add(o);
                        l = myList;
                    }
                    whatIs = l.GetType().ToString();
                }
            }
        }

        public override void fromJSONObject(JSONObject json)
        {
            List<JSONObject> ljo = json.list;
            if (this.l == null)
                this.l = ScriptableObject.CreateInstance<IsoUnityList>();
            else
                this.l.Clear();
            foreach (var jo in ljo)
            {
                JSONAble unserialized = JSONSerializer.UnSerialize(jo);
                this.l.Add(unserialized);
            }
        }

        public override JSONObject toJSONObject()
        {
            JSONObject[] array = new JSONObject[l.Count];
            int i = 0;
            foreach (var o in this.l.getSerializable())
            {
                array[i] = JSONSerializer.Serialize(o);
                i++;
            }
            return new JSONObject(array);
        }

    }
}

