using System;
using System.IO;

public class NonDisposableStream : Stream
{
    private readonly Stream _baseStream;

    public NonDisposableStream(Stream baseStream)
    {
        if (baseStream == null)
            throw new ArgumentNullException(nameof(baseStream));

        _baseStream = baseStream;
    }

    public override bool CanRead => _baseStream.CanRead;
    public override bool CanSeek => _baseStream.CanSeek;
    public override bool CanWrite => _baseStream.CanWrite;
    public override long Length => _baseStream.Length;
    public override long Position
    {
        get => _baseStream.Position;
        set => _baseStream.Position = value;
    }

    public override void Flush()
    {
        _baseStream.Flush();
    }

    public override int Read(byte[] buffer, int offset, int count)
    {
        return _baseStream.Read(buffer, offset, count);
    }

    public override long Seek(long offset, SeekOrigin origin)
    {
        return _baseStream.Seek(offset, origin);
    }

    public override void SetLength(long value)
    {
        _baseStream.SetLength(value);
    }

    public override void Write(byte[] buffer, int offset, int count)
    {
        _baseStream.Write(buffer, offset, count);
    }

    public override void WriteByte(byte value)
    {
        _baseStream.WriteByte(value);
    }

    public override int ReadByte()
    {
        return _baseStream.ReadByte();
    }

    public override void CopyTo(Stream destination, int bufferSize)
    {
        _baseStream.CopyTo(destination, bufferSize);
    }

    protected override void Dispose(bool disposing)
    {
        // Do nothing to prevent the base stream from being disposed
    }

    public override bool CanTimeout => _baseStream.CanTimeout;
    public override int ReadTimeout
    {
        get => _baseStream.ReadTimeout;
        set => _baseStream.ReadTimeout = value;
    }

    public override int WriteTimeout
    {
        get => _baseStream.WriteTimeout;
        set => _baseStream.WriteTimeout = value;
    }
}

public static List<T> Flatten<T>(this List<T> list)
{
    return list.Aggregate(new List<T>(), (acc, val) =>
    {
        if (val.GetType() == typeof(List<T>))
        {
            return acc.Concat(Flatten((List<T>)val)).ToList();
        }
        else
        {
            return acc.Concat(new List<T> { val }).ToList();
        }
    });
}

