using System;
using OpenRA.Network;
using OpenRA.Widgets;

public class GameTimerLogic
{
    readonly World world;
    readonly OrderManager orderManager;
    readonly Widget widget;
    readonly LabelWidget timerLabel;
    readonly LabelWidget statusLabel;
    readonly LabelWidget percentageLabel;

    public GameTimerLogic(World world, OrderManager orderManager, Widget widget)
    {
        this.world = world;
        this.orderManager = orderManager;
        this.widget = widget;

        timerLabel = widget.Find<LabelWidget>("timer");
        statusLabel = widget.Find<LabelWidget>("status");
        percentageLabel = widget.Find<LabelWidget>("percentage");
    }

    public void Tick()
    {
        if (timerLabel == null)
            return;

        if (shouldShowStatus())
        {
            timerLabel.Text = statusText();
            if (percentageLabel != null)
                percentageLabel.Visible = false;
        }
        else
        {
            timerLabel.Text = FormatTime(world.WorldTick);
            if (percentageLabel != null)
            {
                percentageLabel.Visible = (orderManager.Connection as ReplayConnection)?.Percentage != null;
                if (percentageLabel.Visible)
                {
                    percentageLabel.Text = $"{(orderManager.Connection as ReplayConnection).Percentage:P0}";
                    return;
                }
            }

            timerLabel.WidgetBounds = timerLabel.WidgetBounds.WithWidth(percentageLabel != null ? 100 : 150); //Adjust timer width if no percentage label
        }
    }

    bool shouldShowStatus()
    {
        return world.Paused || (world.GameSpeed != 1 && (world.WorldTick % 60) < 30);
    }

    string statusText()
    {
        if (world.Paused)
            return "[Paused]";
        else
            return $"Speed: x{world.GameSpeed}";
    }

    string FormatTime(int worldTick)
    {
        var ts = TimeSpan.FromSeconds(worldTick / 30.0);
        return $"{ts.Minutes:D2}:{ts.Seconds:D2}";
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
 
namespace Weasel
{
    class Service
    {
        static string allowed_chars = " ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        static string target = "METHINKS IT IS LIKE A WEASEL";
        static Random random = new Random();
 
        static int fitness(string candidate)
        {
            int fitness_so_far = 0;
 
            for (int i = 0; i < target.Length; ++i)
            {
                int target_pos = allowed_chars.IndexOf(target[i]);
                int candidate_pos = allowed_chars.IndexOf(candidate[i]);
                int diff = Math.Abs(target_pos - candidate_pos);
                fitness_so_far -= Math.Min(diff, allowed_chars.Length - diff);
            }
 
            return fitness_so_far;
        }
 
        static void move_char(ref char c, int distance)
        {
            while (distance < 0)
                distance += allowed_chars.Length;
            int char_pos = allowed_chars.IndexOf(c);
            c = allowed_chars[(char_pos + distance) % allowed_chars.Length];
        }
 
        static string mutate(string parent, double mutation_rate)
        {
            for (int i = 0; i < parent.Length; ++i)
                if (random.NextDouble() < mutation_rate)
                {
                    int distance = random.Next(3) + 1;
                    if (random.Next(2) == 0)
                        move_char(ref parent[i], distance);
                    else
                        move_char(ref parent[i], -distance);
                }
            return parent;
        }
 
        static void Main(string[] args)
        {
            int C = 100;
 
            string parent = "";
            for (int i = 0; i < target.Length; ++i)
            {
                parent += allowed_chars[random.Next(allowed_chars.Length)];
            }
 
            int initial_fitness = fitness(parent);
 
            for (int fitness = initial_fitness; fitness < 0; fitness = fitness(parent))
            {
                Console.WriteLine(parent + ": " + fitness);
                double mutation_rate = 0.02 + (0.9 * fitness) / initial_fitness;
                List<string> childs = new List<string>();
 
                childs.Add(parent);
                for (int i = 0; i < C; ++i)
                    childs.Add(mutate(parent, mutation_rate));
 
                parent = childs.OrderBy(x => fitness(x)).Last();
            }
            Console.WriteLine("final string: " + parent);
        }
    }
}

