using System;
using System.Collections.Generic;
using System.Linq;
using NUnit.Framework;

namespace SensorTests
{
    [TestFixture]
    public class SensorTests
    {
        private SensorFixture _sensorFixture;

        [SetUp]
        public void Setup()
        {
            _sensorFixture = new SensorFixture();
        }

        [Test]
        [TestCaseSource(typeof(SensorTestsData), nameof(SensorTestsData.ValidImpulseTestCases))]
        public void SetImpulse_ValidValues_ShouldUpdateImpulse(double impulseValue)
        {
            // Arrange
            var sensor = _sensorFixture.CreateSensor();

            // Act
            sensor.SetImpulse(impulseValue);

            // Assert
            Assert.AreEqual(impulseValue, sensor.GetImpulse(), 0.001);
        }

        [Test]
        [TestCaseSource(typeof(SensorTestsData), nameof(SensorTestsData.InvalidImpulseTestCases))]
        public void SetImpulse_InvalidValues_ShouldClampToValidRange(double impulseValue)
        {
            // Arrange
            var sensor = _sensorFixture.CreateSensor();

            // Act
            sensor.SetImpulse(impulseValue);

            // Assert
            Assert.That(sensor.GetImpulse(), Is.InRange(0.0, 1.0));
        }

        [Test]
        public void SensorInit_DefaultImpulse_ShouldBeZero()
        {
            // Arrange & Act
            var sensor = _sensorFixture.CreateSensor();

            // Assert
            Assert.AreEqual(0.0, sensor.GetImpulse(), 0.001);
        }
    }

    public static class SensorTestsData
    {
        public static IEnumerable<double> ValidImpulseTestCases()
        {
            yield return 0.0;
            yield return 0.5;
            yield return 1.0;
        }

        public static IEnumerable<double> InvalidImpulseTestCases()
        {
            yield return -1.0;
            yield return 1.5;
            yield return double.NegativeInfinity;
            yield return double.PositiveInfinity;
        }
    }

    public abstract class SensorFixture
    {
        public virtual Sensor CreateSensor()
        {
            return new ConcreteSensor();
        }
    }

    public abstract class Sensor
    {
        private double _impulse;

        public double GetImpulse() => _impulse;

        public void SetImpulse(double value)
        {
            _impulse = Math.Clamp(value, 0.0, 1.0);
        }
    }

    public class ConcreteSensor : Sensor
    {
    }
}

