        public Guid Id { get; }
        public string Name { get; }
        public EntityReference Category { get; }
        public int SortOrder { get; }
        public bool IsActive { get; }

        public WebLinkSet(Entity sourceEntity, IEnumerable<IWebLink> webLinks)
        {
            if (sourceEntity == null)
                throw new ArgumentNullException(nameof(sourceEntity));

            _sourceEntity = sourceEntity;
            _webLinks = (webLinks ?? Enumerable.Empty<IWebLink>()).ToList().AsReadOnly();

            Id = sourceEntity.Id;
            Name = GetAttribute<string>("name");
            Category = GetAttribute<EntityReference>("category");
            SortOrder = GetAttribute<int>("sortorder", 0);
            IsActive = GetAttribute<bool>("isactive", false);
        }

        public T GetAttribute<T>(string attributeName, T defaultValue = default)
        {
            try
            {
                if (!_sourceEntity.Attributes.Contains(attributeName))
                    return defaultValue;

                object value = _sourceEntity.GetAttributeValue<object>(attributeName);
                return value is T typedValue ? typedValue : defaultValue;
            }
            catch (Exception)
            {
                return defaultValue;
            }
        }

        public IReadOnlyCollection<IWebLink> GetWebLinks() => _webLinks;

        public IWebLink GetWebLinkByName(string name) =>
            _webLinks.FirstOrDefault(link =>
                link.Name.Equals(name, StringComparison.OrdinalIgnoreCase));

        public int WebLinkCount => _webLinks.Count;

        public bool HasWebLinks => _webLinks.Any();

        public override string ToString() =>
            $"WebLinkSet: {Name ?? "Unnamed"} (ID: {Id}, Links: {WebLinkCount})";

        public bool Equals(WebLinkSet other) =>
            other != null && Id == other.Id;

        public override bool Equals(object obj) =>
            obj is WebLinkSet set && Equals(set);

        public override int GetHashCode() =>
            Id.GetHashCode();
    }

