using UnityEngine;
using HutongGames.PlayMaker;

namespace HutongGames.PlayMaker.Actions
{
    [ActionCategory(ActionCategory.Device)]
    [Tooltip("Gets the device roll angle (rotation around Z axis).")]
    public class GetDeviceRoll : FsmStateAction
    {
        public enum BaseOrientation
        {
            Portrait,
            LandscapeLeft,
            LandscapeRight
        }

        [RequiredField]
        [UIHint(UIHint.Variable)]
        [Tooltip("Store the roll angle in a float variable.")]
        public FsmFloat storeAngle;

        [Tooltip("The base orientation of the device.")]
        public BaseOrientation baseOrientation;

        [Tooltip("Optionally limit the angle.")]
        public FsmFloat limitAngle;

        [Tooltip("Apply some smoothing to the angle.")]
        public FsmFloat smoothing;

        [Tooltip("Repeat every frame.")]
        public bool everyFrame;

        private float currentAngle;

        public override void Reset()
        {
            storeAngle = null;
            baseOrientation = BaseOrientation.Portrait;
            limitAngle = new FsmFloat { UseVariable = true };
            smoothing = 0f;
            everyFrame = false;
        }

        public override void OnEnter()
        {
            DoGetDeviceRoll();

            if (!everyFrame)
            {
                Finish();
            }
        }

        public override void OnUpdate()
        {
            DoGetDeviceRoll();
        }

        void DoGetDeviceRoll()
        {
            Vector3 acceleration = Input.acceleration;
            float angle = Mathf.Atan2(acceleration.y, acceleration.x) * Mathf.Rad2Deg;

            switch (baseOrientation)
            {
                case BaseOrientation.Portrait:
                    angle += 90;
                    break;
                case BaseOrientation.LandscapeLeft:
                    break;
                case BaseOrientation.LandscapeRight:
                    angle += 180;
                    break;
            }

            angle = Mathf.Repeat(angle, 360);

            if (!limitAngle.IsNone)
            {
                angle = Mathf.Clamp(angle, -limitAngle.Value, limitAngle.Value);
            }

            if (smoothing.Value > 0)
            {
                currentAngle = Mathf.LerpAngle(currentAngle, angle, smoothing.Value * Time.deltaTime);
                angle = currentAngle;
            }

            storeAngle.Value = angle;
        }
    }
}

