using PronoFoot.Business.Contracts;
using PronoFoot.Business.Models;
using PronoFoot.Data;

namespace PronoFoot.Business.Services
{
    public class FixtureService : IFixtureService
    {
        private readonly IFixtureRepository fixtureRepository;

        public FixtureService(IFixtureRepository fixtureRepository)
        {
            this.fixtureRepository = fixtureRepository;
        }

        public FixtureModel GetFixture(int fixtureId)
        {
            var fixture = fixtureRepository.GetFixture(fixtureId);

            return new FixtureModel(fixture);
        }

        public FixtureModel GetNextFixture(int editionId)
        {
            var query = from f in fixtureRepository.GetFixturesForEdition(editionId)
                        let fm = new FixtureModel(f)
                        where fm.CanBeForecast
                        orderby fm.Date
                        select fm;

            return query.FirstOrDefault();
        }

        public IEnumerable<FixtureModel> GetFixtures(IEnumerable<int> fixtureIds)
        {
            var fixtures = fixtureRepository.GetFixtures(fixtureIds);

            var fixtureModels = fixtures.Select(x => new FixtureModel(x));

            return fixtureModels.ToList();
        }

        public IEnumerable<FixtureModel> GetFixturesForDay(int dayId)
        {
            var fixtures = fixtureRepository.GetFixturesForDay(dayId);

            var fixtureModels = fixtures.Select(x => new FixtureModel(x));

            return fixtureModels.ToList();
        }

        public IEnumerable<FixtureModel> GetFixturesForEdition(int editionId)
        {
            var fixtures = fixtureRepository.GetFixturesForEdition(editionId);

            var fixtureModels = fixtures.Select(x => new FixtureModel(x));

            return fixtureModels.ToList();
        }
    }
}

using System;
using System.Net;
using System.Security.Cryptography;
using Android.Net.Wifi;

public static class NetUtility
{
    private static readonly byte[] s_randomMacBytes = new byte[6];
    private static readonly SHA1 s_sha = SHA1.Create();
    private static readonly int s_timeInitialized = Environment.TickCount;

    static NetUtility()
    {
        var random = new Random(GetPlatformSeed());
        random.NextBytes(s_randomMacBytes);
    }

    public static byte[] GetMacAddressBytes()
    {
        return s_randomMacBytes;
    }

    public static IPAddress GetMyAddress()
    {
#if __ANDROID__
        var wifiManager = Android.App.Application.Context.GetSystemService(Android.Content.Context.WifiService) as WifiManager;
        if (wifiManager != null)
        {
            var dhcpInfo = wifiManager.DhcpInfo;
            if (dhcpInfo != null)
            {
                return CreateAddressFromBytes(BitConverter.GetBytes(dhcpInfo.IpAddress));
            }
        }
#endif
        return IPAddress.Any;
    }

    public static IPAddress GetBroadcastAddress()
    {
        var ip = GetMyAddress();
        var mask = GetSubnetMask();
        var broadcastBytes = new byte[4];
        for (int i = 0; i < 4; i++)
        {
            broadcastBytes[i] = (byte)(ip.GetAddressBytes()[i] | ~mask.GetAddressBytes()[i]);
        }
        return new IPAddress(broadcastBytes);
    }

    public static IPAddress GetSubnetMask()
    {
#if __ANDROID__
        var wifiManager = Android.App.Application.Context.GetSystemService(Android.Content.Context.WifiService) as WifiManager;
        if (wifiManager != null)
        {
            var dhcpInfo = wifiManager.DhcpInfo;
            if (dhcpInfo != null)
            {
                return CreateAddressFromBytes(BitConverter.GetBytes(dhcpInfo.Netmask));
            }
        }
#endif
        return IPAddress.None;
    }

    public static byte[] ComputeSHAHash(byte[] data)
    {
        return s_sha.ComputeHash(data);
    }

    public static void Sleep(int milliseconds)
    {
        System.Threading.Thread.Sleep(milliseconds);
    }

    private static IPAddress CreateAddressFromBytes(byte[] bytes)
    {
        if (bytes.Length == 4)
        {
            return new IPAddress(bytes);
        }
        return IPAddress.Any;
    }

    private static int GetPlatformSeed()
    {
        return Environment.TickCount;
    }
}

public static class NetTime
{
    public static int Now => Environment.TickCount - NetUtility.s_timeInitialized;
}

using UnityEngine;
using System.Collections;
using System.Collections.Generic;
using BeatManagement;

public class InitialBuildingEntryAnimation : Task
{
    private TaskManager subtaskManager;
    private float baseStaggerTime;
    private float structStaggerTime;
    private float terrainStaggerTime;
    private bool run_tasks = false;

    protected override void Init()
    {
        baseStaggerTime = Services.Clock.EighthLength();
        structStaggerTime = Services.Clock.SixteenthLength();
        terrainStaggerTime = Services.Clock.ThirtySecondLength();
        subtaskManager = new TaskManager();

        for (int i = 0; i < 2; i++)
        {
            Task dropTask = new Wait(baseStaggerTime * i);
            dropTask.Then(new BuildingDropAnimation(Services.GameManager.Players[i].mainBase));
            subtaskManager.Do(dropTask);
        }
        for (int i = 0; i < Services.MapManager.structuresOnMap.Count; i++)
        {
            Task dropTask = new Wait((structStaggerTime * i) + (baseStaggerTime * 2));
            dropTask.Then(new BuildingDropAnimation(Services.MapManager.structuresOnMap[i]));
            subtaskManager.Do(dropTask);
        }

        for (int i = 0; i < Services.MapManager.terrainOnMap.Count; i++)
        {
            Task dropTask = new Wait((terrainStaggerTime * i) + (baseStaggerTime * 2));
            dropTask.Then(new BuildingDropAnimation(Services.MapManager.terrainOnMap[i]));
            subtaskManager.Do(dropTask);
        }

        // Task waitTask = new Wait((structStaggerTime * Services.MapManager.structuresOnMap.Count) + (baseStaggerTime * 2));
        // waitTask.Then(new ActionTask(() => { SetStatus(TaskStatus.Success); }));

        //subtaskManager.Do(waitTask);

        Services.Clock.SyncFunction(() => { run_tasks = true; }, Clock.BeatValue.Quarter);
    }

    internal override void Update()
    {
        if (run_tasks)
        {
            subtaskManager.Update();
            if (subtaskManager.tasksInProcessCount == 0)
                SetStatus(TaskStatus.Success);
        }
    }

}

