using System;
using System.Collections.Generic;
using System.Linq;
 
namespace BrazilianNumbers
{
    class Shape
    {
        static bool SameDigits(ulong x, ulong base)
        {
            var f = x % base;
            var n = x;
            while (n > 0)
            {
                if (n % base!= f)
                {
                    return false;
                }
                n /= base;
            }
 
            return true;
        }
 
        static bool IsBrazilian(ulong x)
        {
            if (x < 7)
            {
                return false;
            };
            if (x % 2 == 0)
            {
                return true;
            };
 
            for (var base = 2; base < (x - 1); base++)
            {
                if (SameDigits(x, base))
                {
                    return true;
                }
            }
            return false;
        }
 
        static void Main(string[] args)
        {
            var counter = 0;
            var limit = 20;
            var bigLimit = 100_000;
            var bigResult = 0UL;
            var br = new List<ulong>();
            var o = new List<ulong>();
            var p = new List<ulong>();
 
            for (var x = 7UL; ; x++)
            {
                if (IsBrazilian(x))
                {
                    counter++;
                    if (br.Count < limit)
                    {
                        br.Add(x);
                    }
                    if (o.Count < limit && x % 2 == 1)
                    {
                        o.Add(x);
                    }
                    if (p.Count < limit && Primes.IsPrime(x))
                    {
                        p.Add(x);
                    }
                    if (counter == bigLimit)
                    {
                        bigResult = x;
                        break;
                    }
                }
            }
            Console.WriteLine($"First {limit} Brazilian numbers:");
            Console.WriteLine(string.Join(", ", br));
            Console.WriteLine($"\nFirst {limit} odd Brazilian numbers:");
            Console.WriteLine(string.Join(", ", o));
            Console.WriteLine($"\nFirst {limit} prime Brazilian numbers:");
            Console.WriteLine(string.Join(", ", p));
 
            Console.WriteLine($"\nThe {bigLimit}th Brazilian number: {bigResult}");
        }
    }
}

using System;

public class CompoundException : Exception
{
    public CompoundException()
        : base("An error occurred.")
    {
    }

    public CompoundException(string message)
        : base(message)
    {
    }

    public CompoundException(string message, Exception innerException)
        : base(message, innerException)
    {
    }

    public CompoundException(Exception innerException)
        : base("An error occurred.", innerException)
    {
    }

    public CompoundException(string message, params Exception[] innerExceptions)
        : base(message)
    {
        this.InnerExceptions = innerExceptions;
    }

    public Exception[] InnerExceptions { get; private set; }

    public override string Message
    {
        get
        {
            var baseMessage = base.Message;
            if (InnerExceptions != null && InnerExceptions.Length > 0)
            {
                var innerMessages = string.Join("; ", Array.ConvertAll(InnerExceptions, e => e.Message));
                return $"{baseMessage} Inner exceptions: {innerMessages}";
            }
            return baseMessage;
        }
    }

    public static void LogErrors(CompoundException compoundEx)
    {
        Console.WriteLine("Logging Compound Exception:");
        Console.WriteLine($"Message: {compoundEx.Message}");
        Console.WriteLine("Inner Exceptions:");

        foreach (var ex in compoundEx.InnerExceptions)
        {
            Console.WriteLine($" - {ex.Message}");
        }
    }
}

class Solution
{
    static void Main()
    {
        try
        {
            throw new InvalidOperationException("First error occurred.");
        }
        catch (Exception ex1)
        {
            try
            {
                throw new NullReferenceException("Second error occurred.");
            }
            catch (Exception ex2)
            {
                var compoundException = new CompoundException("Multiple errors occurred", ex1, ex2);
                CompoundException.LogErrors(compoundException);
            }
        }
    }
}

using System;
