namespace SubarraySumCounter
{
    public class Queue
    {
        // Returns the count of continuous subarrays in a binary array that sum exactly to the target.
        public int NumSubarraysWithSum(int[] nums, int target)
        {
            if (nums == null || nums.Length == 0)
                return 0;

            // Special handling for target zero where only subarrays composed entirely of zeros qualify.
            if (target == 0)
            {
                int count = 0;
                int consecutiveZeros = 0;

                for (int i = 0; i < nums.Length; i++)
                {
                    if (nums[i] == 0)
                    {
                        consecutiveZeros++;
                    }
                    else
                    {
                        if (consecutiveZeros > 0)
                        {
                            count += consecutiveZeros * (consecutiveZeros + 1) / 2;
                            consecutiveZeros = 0;
                        }
                    }
                }
                if (consecutiveZeros > 0)
                {
                    count += consecutiveZeros * (consecutiveZeros + 1) / 2;
                }
                return count;
            }
            else
            {
                int count = 0;
                int cumulative = 0;
                Dictionary<int, int> freq = new Dictionary<int, int>();
                freq[0] = 1;

                // Use prefix sum and a frequency dictionary to count complementary subarray sums.
                foreach (int num in nums)
                {
                    cumulative += num;
                    if (freq.ContainsKey(cumulative - target))
                    {
                        count += freq[cumulative - target];
                    }
                    if (!freq.ContainsKey(cumulative))
                    {
                        freq[cumulative] = 0;
                    }
                    freq[cumulative]++;
                }
                return count;
            }
        }
    }

