        {
            try
            {
                using (var uow = _unitOfWorkManager.Begin())
                {
                    var product = ObjectMapper.Map<Product>(input);
                    var createdProduct = await _productRepository.InsertAsync(product);
                    await uow.CompleteAsync();
                    return ObjectMapper.Map<ProductDto>(createdProduct);
                }
            }
            catch (Exception ex)
            {
                Logger.Error("Product creation failed", ex);
                throw;
            }
        }

        public async Task<ProductDto> CreateProductAndRollback(ProductCreateInput input)
        {
            using (var transactionScope = new TransactionScope(TransactionScopeAsyncFlowOption.Enabled))
            {
                try
                {
                    var product = ObjectMapper.Map<Product>(input);
                    await _productRepository.InsertAsync(product);

                    // Simulate an error to force rollback
                    if (product.Price < 0)
                    {
                        throw new InvalidOperationException("Invalid product price");
                    }

                    transactionScope.Complete();
                    return ObjectMapper.Map<ProductDto>(product);
                }
                catch
                {
                    transactionScope.Dispose();
                    throw;
                }
            }
        }

