public static class QueuePolicyServiceCollectionExtensions
{
    public static IServiceCollection AddQueuePolicy(this IServiceCollection services, Action<QueuePolicyOptions> configureOptions)
    {
        if (services == null)
        {
            throw new ArgumentNullException(nameof(services));
        }

        if (configureOptions == null)
        {
            throw new ArgumentNullException(nameof(configureOptions));
        }

        var options = new QueuePolicyOptions();
        configureOptions(options);

        if (options.MaxConcurrentRequests <= 0)
        {
            throw new ArgumentException("MaxConcurrentRequests must be greater than zero.");
        }

        services.AddSingleton<IQueuePolicy>(new QueuePolicy(options.MaxConcurrentRequests));
        return services;
    }

    public static IServiceCollection AddStackPolicy(this IServiceCollection services, Action<QueuePolicyOptions> configureOptions)
    {
        if (services == null)
        {
            throw new ArgumentNullException(nameof(services));
        }

        if (configureOptions == null)
        {
            throw new ArgumentNullException(nameof(configureOptions));
        }

        var options = new QueuePolicyOptions();
        configureOptions(options);

        if (options.MaxConcurrentRequests <= 0)
        {
            throw new ArgumentException("MaxConcurrentRequests must be greater than zero.");
        }

        services.AddSingleton<IQueuePolicy>(new StackPolicy(options.MaxConcurrentRequests));
        return services;
    }
}

