namespace Lzw
{
    /** Compress a string to a list of output symbols. */
    public static class Lzw
    {
        public static List<int> compress(string uncompressed)
        {
            // Build the dictionary.
            int dictSize = 256;
            var dictionary = new Dictionary<string, int>();
            for (int i = 0; i < dictSize; i++)
            {
                dictionary.Add(i.ToString(), i);
            }
 
            var w = "";
            var result = new List<int>();
            foreach (var c in uncompressed)
            {
                var wc = w + c;
                if (dictionary.ContainsKey(wc))
                {
                    w = wc;
                }
                else
                {
                    result.Add(dictionary[w]);
                    // Add wc to the dictionary.
                    dictionary.Add(wc, dictSize++);
                    w = c.ToString();
                }
            }
 
            // Output the code for w
            if (!string.IsNullOrEmpty(w))
            {
                result.Add(dictionary[w]);
            }
            return result;
        }
 
        /** Decompress a list of output symbols to a string. */
        public static string decompress(List<int> compressed)
        {
            // Build the dictionary.
            int dictSize = 256;
            var dictionary = new Dictionary<int, string>();
            for (int i = 0; i < dictSize; i++)
            {
                dictionary.Add(i, i.ToString());
            }
 
            var w = dictionary[compressed[0]];
            var result = new StringBuilder(w);
            foreach (var k in compressed.Skip(1))
            {
                string entry;
                if (dictionary.ContainsKey(k))
                {
                    entry = dictionary[k];
                }
                else if (k == dictSize)
                {
                    entry = w + w[0];
                }
                else
                {
                    throw new ArgumentException("Bad compressed k: " + k);
                }
                result.Append(entry);
 
                // Add w + entry[0] to the dictionary.
                dictionary.Add(dictSize++, w + entry[0]);
                w = entry;
            }
            return result.ToString();
        }
    }
 
