public class VixWinNumbered {
    private Patient _currentPatient;
    private string _programPath;
    private ProgramProperties _programProps;

    public VixWinNumbered(Patient patient) {
        _currentPatient = patient;
        _programPath = GetProgramPath();
        _programProps = GetProgramProperties();
    }

    public bool SendData() {
        try {
            string patientIdentifier = GetPatientIdentifier();
            string imageFolderPath = CreatePatientImageDirectory(patientIdentifier);

            if (!Directory.Exists(imageFolderPath)) {
                Directory.CreateDirectory(imageFolderPath);
            }

            ProcessStartInfo startInfo = ConfigureProcessStartInfo(patientIdentifier, imageFolderPath);
            Process.Start(startInfo);

            return true;
        }
        catch (Exception ex) {
            MessageBox.Show($"Error launching VixWin: {ex.Message}", "Integration Error",
                MessageBoxButtons.OK, MessageBoxIcon.Error);
            return false;
        }
    }

    private string GetPatientIdentifier() {
        string identifierType = GetPropVal("IdentifierType");
        return identifierType == "PatNum"
            ? _currentPatient.PatNum.ToString()
            : _currentPatient.ChartNumber;
    }

    private string CreatePatientImageDirectory(string patientIdentifier) {
        string basePath = GetPropVal("ImageStoragePath");
        string patientSubdirectory = Path.Combine(basePath, patientIdentifier);
        return patientSubdirectory;
    }

    private ProcessStartInfo ConfigureProcessStartInfo(string patientIdentifier, string imageFolderPath) {
        return new ProcessStartInfo {
            FileName = _programPath,
            Arguments = $"/patient:{patientIdentifier} /imagedir:\"{imageFolderPath}\"",
            UseShellExecute = false,
            CreateNoWindow = true
        };
    }

    private string GetProgramPath() {
        string defaultPath = @"C:\Program Files\VixWin\VixWin.exe";
        string configuredPath = GetPropVal("ProgramPath");
        return string.IsNullOrEmpty(configuredPath) ? defaultPath : configuredPath;
    }

    private ProgramProperties GetProgramProperties() {
        // Simulated method to retrieve program configuration
        return new ProgramProperties();
    }

    private string GetPropVal(string propertyName) {
        // Simulated method to retrieve property values
        return _programProps.GetValue(propertyName);
    }
}

