public class InNamespaceString : MultipleMatchBasedOnPatternBase
{
    private readonly IStructuralSearchPattern _pattern;

    public InNamespaceString()
    {
        _pattern = CSharpStructuralSearchPattern.CreatePattern("$builder$.InNamespace($argument$)");
    }

    protected override IStructuralSearchPattern Pattern => _pattern;

    protected override IEnumerable<IComponentRegistration> DoCreateRegistrations(IMultipleMatchResult matchResult)
    {
        var registrations = new List<IComponentRegistration>();
        foreach (var match in matchResult.MatchedResults)
        {
            var argumentNode = match.GetMatchedElement<ICSharpArgument>("argument");
            var builderNode = match.GetMatchedElement<ICSharpExpression>("builder");

            if (argumentNode?.Value == null || builderNode == null)
                continue;

            var namespaceString = argumentNode.Value.GetStringValue();
            if (string.IsNullOrWhiteSpace(namespaceString))
                continue;

            var psiModule = match.MatchSourceFile.GetPsiModule();
            var resolvedNamespace = NamespaceUtil.ResolveNamespace(namespaceString, psiModule);
            if (resolvedNamespace == null)
                continue;

            var strictMatching = matchResult.Context.GetData("StrictNamespaceMatching") as bool? ?? false;
            var typesInNamespace = GetTypesInNamespace(resolvedNamespace, strictMatching);

            registrations.AddRange(CreateComponentRegistrations(typesInNamespace, builderNode));
        }
        return registrations;
    }

    private IEnumerable<ITypeElement> GetTypesInNamespace(INamespace ns, bool strict)
    {
        var types = new List<ITypeElement>();
        foreach (var member in ns.GetMembers())
        {
            if (member is INamespace childNs && !strict)
                types.AddRange(GetTypesInNamespace(childNs, false));
            else if (member is ITypeElement type)
                types.Add(type);
        }
        return types;
    }

    private IEnumerable<IComponentRegistration> CreateComponentRegistrations(
        IEnumerable<ITypeElement> types, ICSharpExpression builder)
    {
        foreach (var type in types)
        {
            yield return new ComponentRegistration
            {
                Type = type,

