namespace CoercionTests
{
    [TestFixture]
    public class CoercionSimpleBuilder
    {
        private ExprBuilder builder;

        [SetUp]
        public void Setup() => builder = new ExprBuilder();

        [Test]
        public void IntToRealCoercion()
        {
            var constant = Literal.Create(Type.Int, 5);
            var result = ApplyCoercion(ArithmeticCoercion.CoercionType.ToReal, constant);
            Assert.AreEqual(Type.Real, result.Type);
            Assert.AreEqual("ToReal(5)", result.ToString());
        }

        [Test]
        public void RealToIntCoercion()
        {
            var constant = Literal.Create(Type.Real, 3.14);
            var result = ApplyCoercion(ArithmeticCoercion.CoercionType.ToInt, constant);
            Assert.AreEqual(Type.Int, result.Type);
            Assert.AreEqual("ToInt(3.14)", result.ToString());
        }

        [Test]
        public void ToRealWrongOperandType()
        {
            var constant = Literal.Create(Type.Bool, true);
            Assert.Throws<ExprTypeCheckException>(() =>
                ApplyCoercion(ArithmeticCoercion.CoercionType.ToReal, constant));
        }

        [Test]
        public void ToIntWrongOperandType()
        {
            var constant = Literal.Create(Type.String, "invalid");
            Assert.Throws<ExprTypeCheckException>(() =>
                ApplyCoercion(ArithmeticCoercion.CoercionType.ToInt, constant));
        }

        private Expr ApplyCoercion(ArithmeticCoercion.CoercionType coercion, Expr operand)
        {
            return coercion switch
            {
                ArithmeticCoercion.CoercionType.ToReal => builder.ToReal(operand),
                ArithmeticCoercion.CoercionType.ToInt => builder.ToInt(operand),
                _ => throw new ArgumentException("Invalid coercion type")
            };
        }
    }

    public class ArithmeticCoercion
    {
        public enum CoercionType { ToReal, ToInt }
    }

    public class ExprBuilder
    {
        public Expr ToReal(Expr e)
        {
            if (!e.Type.IsInt) throw new ExprTypeCheckException();
            return new CoercionExpr(ArithmeticCoercion.CoercionType.ToReal, e);
        }

        public Expr ToInt(Expr e)
        {
            if (!e.Type.IsReal) throw new ExprTypeCheckException();
            return new CoercionExpr(ArithmeticCoercion.CoercionType.ToInt, e);
        }
    }

    public class CoercionExpr : Expr
    {
        public ArithmeticCoercion.CoercionType Op { get; }

