    class Field
    {
        private bool[][] s;
        private int w, h;
 
        public Field(int w, int h)
        {
            s = new bool[h][];
            for (int i = 0; i < h; i++)
            {
                s[i] = new bool[w];
            }
            this.w = w;
            this.h = h;
        }
 
        public void Set(int x, int y, bool b)
        {
            s[y][x] = b;
        }
 
        public bool Next(int x, int y)
        {
            int on = 0;
            for (int i = -1; i <= 1; i++)
            {
                for (int j = -1; j <= 1; j++)
                {
                    if (State(x + i, y + j) &&!(j == 0 && i == 0))
                    {
                        on++;
                    }
                }
            }
            return on == 3 || on == 2 && State(x, y);
        }
 
        public bool State(int x, int y)
        {
            for (; y < 0; y += h) ;
            for (; x < 0; x += w) ;
            return s[y % h][x % w];
        }
 
        public override string ToString()
        {
            var buf = new StringBuilder();
            for (int y = 0; y < h; y++)
            {
                for (int x = 0; x < w; x++)
                {
                    char b ='';
                    if (State(x, y))
                    {
                        b = '*';
                    }
                    buf.Append(b);
                }
                buf.Append('\n');
            }
            return buf.ToString();
        }
    }
 
