    class Converter
    {
        static void Main(string[] args)
        {
            var s1 = "I am the original string";
            var r1 = new Regex("^.*string$");
            if (s1.Matches(r1)) Console.WriteLine("`" + s1 + "` matches `" + r1 + "`");
            var r2 = new Regex("original");
