    public class TransitMapper
    {
        public void DisplayStopInfo(StopAtShape stop)
        {
            Console.WriteLine(stop.ToString());
        }

        public double CalculateDistanceFromPrevious(StopAtShape currentStop, StopAtShape previousStop)
        {
            // Placeholder for distance calculation logic
            // Assuming a simple calculation based on offsets for demonstration purposes
            return Math.Abs(currentStop.StopOffset - previousStop.StopOffset);
        }

        public void ProcessStops()
        {
            StopAtShape stop1 = new StopAtShape("Trip1", "StopA", 1, 0.5);
            StopAtShape stop2 = new StopAtShape("Trip1", "StopB", 2, 1.2);

            DisplayStopInfo(stop1);
            DisplayStopInfo(stop2);
            double distance = CalculateDistanceFromPrevious(stop2, stop1);
            Console.WriteLine($"Distance between stops: {distance}");
        }
    }

