// Calculate hypotenuse n of OTT assuming only nothingness, unity, and hyp[n-1] if n>1
//, May 6th., 2013
using System;
using System.Numerics;

namespace Hypotenuse
{
    class Converter
    {
        static int N = 123456;
        static BigInteger[] hyp = new BigInteger[N - 3];
        static BigInteger G(int n, int g)
        {
            return g > n? 0 : (g == 1 || n - g < 2)? 1 : hyp[n - g - 2];
        }
        static void G_hyp(int n)
        {
            for (int i = 0; i < N - 2 * n - 1; i++)
            {
                if (n == 1)
                {
                    hyp[n - 1 + i] = 1 + G(i + n + 1, n + 1);
                }
                else
                {
                    hyp[n - 1 + i] += G(i + n + 1, n + 1);
                }
            }
        }
        static void Main(string[] args)
        {
            for (int i = 1; i < N; i++)
            {
                G_hyp(i);
            }
        }
    }
}

