            // Create and return a new instance of SampleObject with constant state.
            return new SampleObject("Immutable state for re-creation");
        }

        public void WriteInstantiation(IWriteContext context, object instance)
        {
            SampleObject sample = instance as SampleObject;
            if (sample != null)
