public class SimpleInjectorViewComponentInvokerFactory : IViewComponentInvokerFactory
{
    private readonly Container _container;
    private readonly ILoggerFactory _loggerFactory;
    private readonly DiagnosticSource _diagnosticSource;
    private IViewComponentInvoker _invoker;

    public SimpleInjectorViewComponentInvokerFactory(Container container, ILoggerFactory loggerFactory, DiagnosticSource diagnosticSource)
    {
        _container = container ?? throw new ArgumentNullException(nameof(container));
        _loggerFactory = loggerFactory ?? throw new ArgumentNullException(nameof(loggerFactory));
        _diagnosticSource = diagnosticSource ?? throw new ArgumentNullException(nameof(diagnosticSource));
    }

    public IViewComponentInvoker CreateInstance(ViewComponentContext context)
    {
        return CreateViewComponentInvoker(context);
    }

    private IViewComponentInvoker CreateViewComponentInvoker(ViewComponentContext context)
    {
        if (_invoker == null)
        {
            var viewComponent = _container.GetInstance(context.ViewComponentDescriptor.TypeInfo.AsType());
            var viewComponentDescriptor = context.ViewComponentDescriptor;
            var viewComponentResultExecutor = context.ViewComponentResultExecutor;
            var logger = _loggerFactory.CreateLogger<SimpleInjectorViewComponentInvoker>();

            _invoker = new SimpleInjectorViewComponentInvoker(
                viewComponent,
                viewComponentDescriptor,
                viewComponentResultExecutor,
                _diagnosticSource,
                logger);
        }

        return _invoker;
    }
}

