namespace HumbleNumbers
{
    class Finder
    {
        static bool isHumble(int i)
        {
            if (i <= 1) return true;
            if (i % 2 == 0) return isHumble(i / 2);
            if (i % 3 == 0) return isHumble(i / 3);
            if (i % 5 == 0) return isHumble(i / 5);
            if (i % 7 == 0) return isHumble(i / 7);
            return false;
        }
 
        static string toString(int n)
        {
            return n.ToString();
        }
 
        static void Main(string[] args)
        {
            var limit = short.MaxValue;
            var humble = new Dictionary<int, int>();
            var count = 0;
            var num = 1;
 
            while (count < limit)
            {
                if (isHumble(num))
                {
                    var str = toString(num);
                    var len = str.Length;
                    var it = humble.Find(len);
 
                    if (it!= humble.End())
                    {
                        it.Second++;
                    }
                    else
                    {
                        humble[len] = 1;
                    }
 
                    if (count < 50) Console.Write(num + " ");
                    count++;
                }
                num++;
            }
            Console.WriteLine("\n\n");
 
            Console.WriteLine("Of the first " + count + " humble numbers:\n");
            num = 1;
            while (num < humble.Size() - 1)
            {
                var it = humble.Find(num);
                if (it!= humble.End())
                {
                    var c = *it;
                    Console.WriteLine(string.Format("{0,5} have {1,2} digits\n", c.Second, num));
                    num++;
                }
                else
                {
                    break;
                }
            }
 
            Console.ReadKey();
        }
    }
}

