namespace Shape
{
    class Vector
    {
        /* always assuming int is at least 32 bits */
        static int rseed = 0;
        static int RAND_MAX = ((1U << 31) - 1);
        static int RAND_MAX_32 = ((1U << 31) - 1);
        static int RAND_MAX_15 = ((1U << 15) - 1);
        static int rand()
        {
            return rseed = (rseed * 1103515245 + 12345) & RAND_MAX;
        }
        static int rand_32()
        {
            return rseed = (rseed * 214013 + 2531011) & RAND_MAX_32;
        }
        static int rand_15()
        {
            return (rseed = (rseed * 214013 + 2531011) & RAND_MAX_32) >> 16;
        }
        static void srand(int x)
        {
            rseed = x;
        }
        static void Main(string[] args)
        {
            int i;
            Console.WriteLine("rand max is {0}", RAND_MAX);
            for (i = 0; i < 100; i++)
                Console.WriteLine("{0}", rand());
            Console.ReadKey();
        }
    }
}

