namespace Game
{
    class Library
    {
        static void Main(string[] args)
        {
            double[] values = { 1, 3, 6, 6, 6, 6, 7, 7, 12, 12, 12, 12, 17 };
            int len = values.Length;
            vcount[] vc;
            int n_modes = get_mode(values, len, out vc);
            Console.WriteLine("got {0} modes:", n_modes);
            for (int i = 0; i < n_modes; i++)
                Console.WriteLine("\tvalue = {0}, count = {1}", vc[i].v, vc[i].c);
        }
        static int cmp_dbl(double a, double b)
        {
            double x = a - b;
            return x < 0? -1 : x > 0? 1 : 0;
        }
        static int vc_cmp(vcount a, vcount b)
        {
            return b.c - a.c;
        }
        static int get_mode(double[] x, int len, out vcount[] list)
        {
            int i, j;
            vcount[] vc;
            /* sort values */
            Array.Sort(x);
            /* count occurence of each value */
            for (i = 0, j = 1; i < len - 1; i++, j += (x[i]!= x[i + 1]));
            list = vc = new vcount[j];
            vc[0].v = x[0];
            vc[0].c = 1;
            /* generate list value-count pairs */
            for (i = j = 0; i < len - 1; i++, vc[j].c++)
                if (x[i]!= x[i + 1]) vc[++j].v = x[i + 1];
            /* sort that by count in descending order */
            Array.Sort(vc, vc_cmp);
            /* the number of entries with same count as the highest */
            for (i = 0; i <= j && vc[i].c == vc[0].c; i++);
            return i;
        }
    }
    struct vcount
    {
        public double v;
        public int c;
    }
}

 
