using System;
using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;
using System.Diagnostics.Contracts;

public class Person
{
    [Required]
    [StringLength(50)]
    public string FirstName { get; set; }

    [Required]
    [StringLength(50)]
    public string LastName { get; set; }

    public string Code { get; private set; }

    private List<PeriodRouteEntry> _periodRouteEntries;
    private List<PeriodFuelEntry> _periodFuelEntries;

    public IReadOnlyCollection<PeriodRouteEntry> PeriodRouteEntries
        => _periodRouteEntries ??= new List<PeriodRouteEntry>();

    public IReadOnlyCollection<PeriodFuelEntry> PeriodFuelEntries
        => _periodFuelEntries ??= new List<PeriodFuelEntry>();

    public Person(string firstName, string lastName)
    {
        ValidatePersonData(firstName, lastName);
        FirstName = firstName;
        LastName = lastName;
        GeneratePersonCode();
    }

    private void ValidatePersonData(string firstName, string lastName)
    {
        Contract.Requires<ArgumentException>(!string.IsNullOrWhiteSpace(firstName), "First name is required");
        Contract.Requires<ArgumentException>(!string.IsNullOrWhiteSpace(lastName), "Last name is required");
    }

    private void GeneratePersonCode()
    {
        Code = $"{FirstName.Substring(0, 1)}{LastName.Substring(0, 1)}{Guid.NewGuid():N}".ToUpper();
    }

    public void AddPeriodRouteEntry(PeriodRouteEntry entry)
    {
        ValidateRouteEntry(entry);
        _periodRouteEntries ??= new List<PeriodRouteEntry>();
        _periodRouteEntries.Add(entry);
        entry.AssignPerson(this);
    }

    public void AddPeriodFuelEntry(PeriodFuelEntry entry)
    {
        ValidateFuelEntry(entry);
        _periodFuelEntries ??= new List<PeriodFuelEntry>();
        _periodFuelEntries.Add(entry);
        entry.AssignPerson(this);
    }

    private void ValidateRouteEntry(PeriodRouteEntry entry)
    {
        Contract.Requires<ArgumentNullException>(entry != null, "Route entry cannot be null");
    }

    private void ValidateFuelEntry(PeriodFuelEntry entry)
    {
        Contract.Requires<ArgumentNullException>(entry != null, "Fuel entry cannot be null");
    }
}

using UnityEngine;
using System.Collections;
using System.Collections.Generic;

public class InitialBuildingEntryAnimation : MonoBehaviour
{
    private TaskManager subtaskManager;
    private float baseStaggerTime = 0.2f;
    private float structStaggerTime = 0.4f;
    private float terrainStaggerTime = 0.6f;
    private bool run_tasks = true;

    void Start()
    {
        Init();
    }

    void Update()
    {
        if (run_tasks)
        {
            subtaskManager.Update();
            if (subtaskManager.IsComplete())
            {
                run_tasks = false;
                Debug.Log("Animation sequence completed successfully.");
            }
        }
    }

    private void Init()
    {
        subtaskManager = new TaskManager();
        SyncFunction();
    }

    private void SyncFunction()
    {
        subtaskManager.Do(new Wait(Services.Clock.GetNextBeatTime()))
            .Then(new ActionTask(() => StartBaseDropAnimation()))
            .Then(new Wait(baseStaggerTime))
            .Then(new ActionTask(() => StartStructureDropAnimation()))
            .Then(new Wait(structStaggerTime))
            .Then(new ActionTask(() => StartTerrainDropAnimation()));
    }

    private void StartBaseDropAnimation()
    {
        List<GameObject> playerBases = Services.MapManager.GetPlayerBases();
        foreach (var baseObj in playerBases)
        {
            subtaskManager.Do(new BuildingDropAnimation(baseObj));
        }
    }

    private void StartStructureDropAnimation()
    {
        List<GameObject> structures = Services.MapManager.GetStructures();
        foreach (var structure in structures)
        {
            subtaskManager.Do(new BuildingDropAnimation(structure));
        }
    }

    private void StartTerrainDropAnimation()
    {
        List<GameObject> terrainElements = Services.MapManager.GetTerrainElements();
        foreach (var terrain in terrainElements)
        {
            subtaskManager.Do(new BuildingDropAnimation(terrain));
        }
    }
}

