public interface ITenantIdentificationStrategy
{
    bool TryIdentifyTenant(out string tenantId);
}

public static class ServiceInfoBuilder
{
    public static GetServiceInfoResponse Build(IMultitenantService service, IDependency dependency, ITenantIdentificationStrategy tenantIdentificationStrategy)
    {
        var response = new GetServiceInfoResponse();
        string tenantId;
        bool success = tenantIdentificationStrategy.TryIdentifyTenant(out tenantId);

        response.TenantId = success ? tenantId : "DefaultTenant";

        response.ServiceName = service.GetType().Name;
        response.InstanceId = Guid.NewGuid().ToString(); // Example of instance ID

        if (dependency != null)
        {
            response.DependencyName = dependency.GetType().Name;
        }
        else
        {
            response.DependencyName = "NoDependency";
        }

        return response;
    }
}

