using NMF.Expressions;
using NMF.Models;
using NMF.Models.Collections;
using NMF.Models.Repository;
using System.IO;
using System.Linq;

namespace NMF.Models
{
    public static class ModelExtensions
    {
        public static IEnumerableExpression<IModelElement> Descendants(this IModelElement element)
        {
            return new DescendantsCollection(element);
        }

        public static void Serialize(this IModelElement element, string path)
        {
            var model = element.Model;
            if (model == null)
            {
                model = new Model();
                model.RootElements.Add(element);
            }
            if (model.ModelUri == null)
            {
                model.ModelUri = new System.Uri(Path.GetFullPath(path), System.UriKind.Absolute);
            }
            using (var fs = new FileStream(path, FileMode.Create, FileAccess.Write))
            {
                element.Model.Repository.Serializer.Serialize(element, fs, model.ModelUri);
            }
        }

        public static void Serialize(this IModelElement element, string path, System.Uri baseUri)
        {
            var model = element.Model;
            if (model == null)
            {
                model = new Model();
                model.RootElements.Add(element);
                model.ModelUri = baseUri;
            }
            using (var fs = new FileStream(path, FileMode.Create, FileAccess.Write))
            {
                element.Model.Repository.Serializer.Serialize(element, fs, baseUri);
            }
        }
        public static void Serialize(this IModelElement element, Stream target, System.Uri uri)
        {
            var model = element.Model;
            if(model == null)
            {
                model = new Model();
                model.RootElements.Add(element);
                model.ModelUri = uri;
            }
            element.Model.Repository.Serializer.Serialize(element, target, uri);
        }

        public static void Serialize(this IModelElement element, string path, IModelSerializer serializer)
        {
             var model = element.Model ?? new Model { ModelUri = new System.Uri(Path.GetFullPath(path), System.UriKind.Absolute) };
             if(model.RootElements.All( root => root != element))
             {
                  model.RootElements.Add(element);
             }
             using (var fs = new FileStream(path, FileMode.Create))
             {
                 serializer.Serialize(element, fs, model.ModelUri);
             }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
 
public class Mode
{
    public static List<T> mode<T>(List<T> coll)
    {
        var seen = new Dictionary<T, int>();
        int max = 0;
        var maxElems = new List<T>();
        foreach (var value in coll)
        {
            if (seen.ContainsKey(value))
                seen[value] = seen[value] + 1;
            else
                seen[value] = 1;
            if (seen[value] > max)
            {
                max = seen[value];
                maxElems.Clear();
                maxElems.Add(value);
            }
            else if (seen[value] == max)
            {
                maxElems.Add(value);
            }
        }
        return maxElems;
    }
 
    public static void Main(string[] args)
    {
        Console.WriteLine(mode(new List<int> { 1, 3, 6, 6, 6, 6, 7, 7, 12, 12, 17 })); // prints [6]
        Console.WriteLine(mode(new List<int> { 1, 1, 2, 4, 4 })); // prints [1, 4]
    }
}

