namespace Timer
{
    class Vector
    {
        const int SIZE = 80;
        const int RULE = 30;
        const int RULE_TEST = (RULE & 1 << (7 & (x)));

        static void evolve(BitArray s)
        {
            int i;
            BitArray t = new BitArray(SIZE);
            t[SIZE - 1] = RULE_TEST(s[0] << 2 | s[SIZE - 1] << 1 | s[SIZE - 2]);
            t[0] = RULE_TEST(s[1] << 2 | s[0] << 1 | s[SIZE - 1]);
            for (i = 1; i < SIZE - 1; i++)
                t[i] = RULE_TEST(s[i + 1] << 2 | s[i] << 1 | s[i - 1]);
            for (i = 0; i < SIZE; i++) s[i] = t[i];
        }
        static void show(BitArray s)
        {
            int i;
            for (i = SIZE; --i; ) Console.Write(s[i]? '#' :'');
            Console.WriteLine();
        }
        static void Main(string[] args)
        {
            int i;
            BitArray state = new BitArray(SIZE);
            state <<= SIZE / 2;
            for (i = 0; i < 10; i++)
            {
                show(state);
                evolve(state);
            }
        }
    }
}

