        public static int p(int year) {
            return (int)((double)year + Math.Floor((double)year/4) - Math.Floor((double)year/100) + Math.Floor((double)year/400)) % 7;
        }
        public static int is_long_year(int year) {
            return p(year) == 4 || p(year - 1) == 3;
        }
        public static void print_long_years(int from, int to) {
            for (int year = from; year <= to; ++year) {
                if (is_long_year(year)) {
                    Console.Write(year + " ");
                }
            }
        }
    }
}

