using System;
 
namespace RadixSort
{
    class Vector
    {
        static void Sort(int[] old)
        {
            int i, j;
            int[] tmp = new int[old.Length];
            for (int shift = 31; shift > -1; --shift)
            {
                j = 0;
                for (i = 0; i < old.Length; ++i)
                {
                    bool move = (old[i] << shift) >= 0;
                    if (shift == 0 ? !move : move)  // shift the 0's to old's head
                        old[i-j] = old[i];
                    else                            // move the 1's to tmp
                        tmp[j++] = old[i];
                }
                Array.Copy(tmp, 0, old, old.Length-j, j);
            }
        }
        static void Main(string[] args)
        {
            int[] old = new int[] { 2, 5, 1, -3, 4 };
            Console.WriteLine(string.Join(", ", old));
            Sort(old);
            Console.WriteLine(string.Join(", ", old));
            Console.Read();
        }
    }
}

using System;
using System.Collections.Generic;
using BenchmarkDotNet.Reports;
using BenchmarkDotNet.Analysers;
using System.Linq;

public class ZeroMeasurementAnalyser : AnalyserBase
{
    private const double FallbackCpuResolutionValue = 1e-9; // 1 nanosecond
    private static readonly string Id = "ZeroMeasurementAnalyser";

    public override void AnalyseReport(BenchmarkReport report)
    {
        var cpuFrequency = GetCpuFrequency();
        var threshold = cpuFrequency > 0 ? 1.0 / cpuFrequency : FallbackCpuResolutionValue;

        var overheadMeasurements = report.GetOverheadMeasurements();
        var workloadMeasurements = report.GetWorkloadMeasurements();

        var overheadStats = GetStatistics(overheadMeasurements);
        var workloadStats = GetStatistics(workloadMeasurements);

        if (IsNegligible(overheadStats, threshold))
        {
            CreateWarning("Warning: Overhead measurements are negligible, indicating unreliable benchmarking.");
        }

        if (IsNegligible(workloadStats, threshold))
        {
            CreateWarning("Warning: Workload measurements are negligible, indicating potential performance measurement issues.");
        }
    }

    private double GetCpuFrequency()
    {
        // Implementation to retrieve CPU frequency, returns in Hz
        // Placeholder for actual CPU frequency retrieval logic
        return 3200000000; // Example: 3.2 GHz
    }

    private Statistics GetStatistics(IEnumerable<double> measurements)
    {
        if (!measurements.Any())
            return new Statistics(0, 0, 0);

        var mean = measurements.Average();
        var variance = measurements.Select(m => Math.Pow(m - mean, 2)).Average();
        var stdDev = Math.Sqrt(variance);

        return new Statistics(mean, stdDev, measurements.Count());
    }

    private bool IsNegligible(Statistics stats, double threshold)
    {
        return stats.Mean < threshold || stats.StdDev < threshold;
    }

    private void CreateWarning(string message)
    {
        // Implementation to log a warning message to the user
        Console.WriteLine(message);
    }

    private class Statistics
    {
        public double Mean { get; }
        public double StdDev { get; }
        public int Count { get; }

        public Statistics(double mean, double stdDev, int count)
        {
            Mean = mean;
            StdDev = stdDev;
            Count = count;
        }
    }
}

