public class Pinger : IDisposable
{
    private static readonly ILog _log = LogManager.GetLogger(typeof(Pinger));
    private readonly UdpClient _udpClient;
    private byte _pingSeq;
    private readonly object _syncLock = new object();
    private readonly AutoResetEvent _pingEvent = new AutoResetEvent(false);
    private readonly Dictionary<byte, DateTime> _pendingPings = new Dictionary<byte, DateTime>();

    public Guid Id { get; } = Guid.NewGuid();

    public Pinger(IPEndPoint localEndpoint)
    {
        _udpClient = new UdpClient(localEndpoint);
        _udpClient.BeginReceive(ReceiveCallback, null);
    }

    private void ReceiveCallback(IAsyncResult ar)
    {
        try
        {
            IPEndPoint remoteEp = new IPEndPoint(IPAddress.Any, 0);
            byte[] data = _udpClient.EndReceive(ar, ref remoteEp);
            _udpClient.BeginReceive(ReceiveCallback, null);

            if (data.Length < 2) return;

            byte type = data[0];
            byte seq = data[1];

            if (type == 0x01)
                ProcessPong(seq);
            else if (type == 0x00)
                ProcessPing(seq, remoteEp);
        }
        catch (Exception ex)
        {
            _log.Error("Receive error", ex);
        }
    }

    private void ProcessPing(byte seq, IPEndPoint remoteEp)
    {
        byte[] pongData = { 0x01, seq };
        _udpClient.Send(pongData, pongData.Length, remoteEp);
        _log.Debug($"Sent pong for seq {seq} to {remoteEp}");
    }

    private void ProcessPong(byte seq)
    {
        lock (_syncLock)
        {
            if (_pendingPings.TryGetValue(seq, out DateTime sentTime))
            {
                _pendingPings.Remove(seq);
                var rtt = DateTime.UtcNow - sentTime;
                _log.Debug($"Received pong for seq {seq}, RTT: {rtt.TotalMilliseconds}ms");
                _pingEvent.Set();
            }
        }
    }

    public double Ping(IPEndPoint remoteEp, int timeoutMs = 3000)
    {
        byte currentSeq;
        lock (_syncLock)
        {
            currentSeq = ++_pingSeq;
            byte[] pingData = { 0x00, currentSeq };
            _udpClient.Send(pingData, pingData.Length, remoteEp);
            _pendingPings[currentSeq] = DateTime.UtcNow;
            _log.Debug($"Sent ping seq {currentSeq} to {remoteEp}");
        }

        if (!_pingEvent.WaitOne(timeoutMs))
        {
            lock (_syncLock) _pendingPings.Remove(currentSeq);

