    static void Main(string[] args)
    {
        using (var context = new Context(1))
        {
            using (var step3 = context.Socket(SocketType.PAIR))
            {
                step3.Bind("inproc://step3");

                Thread t1 = new Thread(() => Step1(context));
                t1.Start();

                byte[] message = step3.Receive();
                Console.WriteLine("Test Successful!");
            }
        }
    }

    static void Step1(Context context)
    {
        using (var step2 = context.Socket(SocketType.PAIR))
        {
            step2.Bind("inproc://step2");

            Thread t2 = new Thread(() => Step2(context));
            t2.Start();

            byte[] message = step2.Receive();

            using (var step1 = context.Socket(SocketType.PAIR))
            {
                step1.Connect("inproc://step3");
                step1.Send(Encoding.Unicode.GetBytes(""), 0);
            }
        }
    }

    static void Step2(Context context)
    {
        using (var step1 = context.Socket(SocketType.PAIR))
        {
            step1.Bind("inproc://step1");

            using (var step2 = context.Socket(SocketType.PAIR))
            {
                step2.Connect("inproc://step2");
                step2.Send(Encoding.Unicode.GetBytes(""), 0);
            }

            byte[] message = step1.Receive();

        }
    }
}

