using System.Linq;
using OpenRA.Activities;
using OpenRA.Mods.RA.Activities;
using OpenRA.Mods.RA.Buildings;
using OpenRA.Traits;
using OpenRA;

namespace OpenRA.Mods.RA.Traits
{
    public class ReturnOnIdleInfo : TraitInfo<ReturnOnIdle> { }

    public class ReturnOnIdle : INotifyIdle
    {
        public void TickIdle(Actor self)
        {
            if (self.CurrentActivity is null)
            {
                if (self.World.Map.GetMapCell(self.Location).TerrainHeight > 0)
                    return;

                var airfield = ChooseAirfield(self);

                if (airfield != null)
                {
                    self.QueueActivity(new ReturnToBase(self, new Target(airfield), true));
                    self.QueueActivity(new OrderUnloadCargo(self));
                    return;
                }

                var building = self.World.Actors.OfType<Building>().Where(b => b.Owner == self.Owner && b.Stance == Stance.Ally).FirstOrDefault();

                if (building != null)
                {
                    self.QueueActivity(new Move(self, building.CenterPosition()));
                    self.QueueActivity(new Orbit(self, new Target(building), 10));
                    return;
                }

                self.QueueActivity(new FlyOffMapAndRemove(self));
            }
        }

        Building ChooseAirfield(Actor self)
        {
            return self.World.Actors.OfType<Building>()
                .Where(b => b.Info.HasTraitInfo<RequiresAirfieldInfo>() && b.Owner == self.Owner && b.Stance == Stance.Ally)
                .OrderBy(b => (b.CenterPosition() - self.CenterPosition()).LengthSq())
                .FirstOrDefault();
        }
    }

    public class FlyAwayOnIdleInfo : TraitInfo<FlyAwayOnIdle> { }

    public class FlyAwayOnIdle : INotifyIdle
    {
        public void TickIdle(Actor self)
        {
            if (self.CurrentActivity is null)
            {
                self.QueueActivity(new FlyOffMapAndRemove(self));
            }
        }
    }
}

