            RemoteClient = remoteClient;
            IgnoreClient = ignoreClient;
            Text = text;
            Number = number;
            Number2 = number2;
            Number3 = number3;
            Number4 = number4;
            Number5 = number5;
            Number6 = number6;
            Number7 = number7;
