        {
            return $"WhoAmI: {WhoAmI}, MsgType: {MsgType}, RemoteClient: {RemoteClient}, IgnoreClient: {IgnoreClient}, Text: {Text}, Number: {Number}, Number2: {Number2}, Number3: {Number3}, Number4: {Number4}, Number5: {Number5}, Number6: {Number6}, Number7: {Number7}";
        }

        public bool Equals(ScrapedSentData other)
        {
            return WhoAmI == other.WhoAmI &&
                   MsgType == other.MsgType &&
                   RemoteClient == other.RemoteClient &&
                   IgnoreClient == other.IgnoreClient &&
                   Equals(Text, other.Text) &&
                   Number.Equals(other.Number) &&
                   Number2.Equals(other.Number2) &&
                   Number3.Equals(other.Number3) &&
                   Number4.Equals(other.Number4) &&
                   Number5.Equals(other.Number5) &&
                   Number6.Equals(other.Number6) &&
                   Number7.Equals(other.Number7);
        }

        public override int GetHashCode()
        {
            unchecked
            {
                var hashCode = WhoAmI;
                hashCode = (hashCode * 397) ^ MsgType;
                hashCode = (hashCode * 397) ^ RemoteClient;
                hashCode = (hashCode * 397) ^ IgnoreClient.GetHashCode();
                hashCode = (hashCode * 397) ^ (Text != null ? Text.GetHashCode() : 0);
                hashCode = (hashCode * 397) ^ Number.GetHashCode();

