    public class PropertyTypePicker : ListBox
    {
        private string _value;
        private bool _multiple;

        public PropertyTypePicker()
        {
            CssClass = "property-type-picker";
        }

        protected override void OnInit(EventArgs e)
        {
            base.OnInit(e);

            SelectionMode = _multiple ? ListSelectionMode.Multiple : ListSelectionMode.Single;

            // Assuming GetAvailablePropertyTypes() is a method to retrieve available property types
            var propertyTypes = GetAvailablePropertyTypes();

            foreach (var propertyType in propertyTypes)
            {
                if (!Items.Cast<ListItem>().Any(item => item.Value == propertyType.ToString()))
                {
                    Items.Add(new ListItem(propertyType.ToString(), propertyType.ToString()));
                }
            }

            if (!string.IsNullOrEmpty(_value))
            {
                string[] selectedValues = _value.Split(',');
                foreach (string selectedValue in selectedValues)
                {
                    ListItem item = Items.FindByValue(selectedValue.Trim());
                    if (item != null)
                    {
                        item.Selected = true;
                    }
                }
            }
        }

        public string Value
        {
            get
            {
                return string.Join(",", Items.Cast<ListItem>().Where(i => i.Selected).Select(i => i.Value));
            }
            set
