namespace Org.Apache.REEF.Driver.Evaluator
{
    public sealed class DefaultEvaluatorFailureHandler : IObserver<IFailedEvaluator>
    {
        private static readonly Logger Logger = Logger.GetLogger(typeof(DefaultEvaluatorFailureHandler));

        [Inject]
        private DefaultEvaluatorFailureHandler()
        {
            // Private constructor to support dependency injection
        }

        /// <summary>
        /// Handles the next failed evaluator event by logging and throwing a detailed exception.
        /// </summary>
        /// <param name="failedEvaluator">The failed evaluator instance</param>
        public void OnNext(IFailedEvaluator failedEvaluator)
        {
            if (failedEvaluator == null)
            {
                throw new ArgumentNullException(nameof(failedEvaluator),
                    "Failed evaluator cannot be null");
            }

            string errorMessage = GenerateFailureErrorMessage(failedEvaluator);

            Logger.Log(Level.Error, errorMessage);
            throw new EvaluatorException(errorMessage, failedEvaluator);
        }

        /// <summary>
        /// Generates a comprehensive error message for the failed evaluator.
        /// </summary>
        private string GenerateFailureErrorMessage(IFailedEvaluator failedEvaluator)
        {
            return string.Format(
                System.Globalization.CultureInfo.InvariantCulture,
                "Evaluator Failed: ID={0}, Reason={1}, Context={2}",
                failedEvaluator.Id,
                failedEvaluator.FailedReason ?? "Unknown Reason",
                failedEvaluator.Context ?? "No Additional Context"
            );
        }

        /// <summary>
        /// Handles error events during failed evaluator processing.
        /// </summary>
        public void OnError(Exception error)
        {
            if (error != null)
            {
                Logger.Log(Level.Error,
                    $"Error in DefaultEvaluatorFailureHandler: {error.Message}",
                    error);
            }
        }

        /// <summary>
        /// Handles completion of failed evaluator event stream.
        /// </summary>
        public void OnCompleted()
        {
            Logger.Log(Level.Info, "Failed Evaluator Event Stream Completed");
        }
    }

