    public static void Main()
    {
        int n = 10_000;
        var res = Enumerable.Range(1, n).Where(x => x.IsSmith()).ToList();
        Console.WriteLine($"{res.Count} smith numbers below {n}:");
        Console.WriteLine($"{string.Join(", ", res.Take(5))},... {string.Join(", ", res.Skip(res.Count - 5))}");
