using System;
using System.Collections.Generic;

public class Heap<T>
{
    private List<T> _list;
    private IComparer<T> _comparer;
    public int Count { get; private set; }

    public Heap(IComparer<T> comparer, List<T> initialList = null)
    {
        _comparer = comparer ?? throw new ArgumentNullException(nameof(comparer));
        _list = initialList ?? new List<T>();
        Count = _list.Count;
        Heapify();
    }

    private void Heapify()
    {
        for (int i = (Count / 2) - 1; i >= 0; i--)
        {
            HeapDown(i);
        }
    }

    public T PopRoot()
    {
        if (Count == 0)
            throw new InvalidOperationException("Heap is empty.");

        T root = _list[0];
        _list[0] = _list[Count - 1];
        _list.RemoveAt(Count - 1);
        Count--;
        HeapDown(0);
        return root;
    }

    public T PeekRoot()
    {
        if (Count == 0)
            throw new InvalidOperationException("Heap is empty.");

        return _list[0];
    }

    public void Insert(T item)
    {
        _list.Add(item);
        Count++;
        HeapUp(Count - 1);
    }

    private void HeapUp(int index)
    {
        while (index > 0 && _comparer.Compare(_list[index], _list[Parent(index)]) < 0)
        {
            SwapCells(index, Parent(index));
            index = Parent(index);
        }
    }

    private void HeapDown(int index)
    {
        while (true)
        {
            int leftChildIndex = LeftChild(index);
            int rightChildIndex = RightChild(index);
            int smallestIndex = index;

            if (SafeIndex(leftChildIndex) && _comparer.Compare(_list[leftChildIndex], _list[smallestIndex]) < 0)
            {
                smallestIndex = leftChildIndex;
            }

            if (SafeIndex(rightChildIndex) && _comparer.Compare(_list[rightChildIndex], _list[smallestIndex]) < 0)
            {
                smallestIndex = rightChildIndex;
            }

            if (smallestIndex == index)
                break;

            SwapCells(index, smallestIndex);
            index = smallestIndex;
        }
    }

    private int Parent(int index)
    {
        return (index - 1) / 2;
    }

    private int LeftChild(int index)
    {
        return (index * 2) + 1;
    }

