namespace Localwire.Graphinder.Core.Algorithms.SimulatedAnnealing.Setup
{
    using System;
    using CoolingStrategies;
    using Helpers;

    /// <summary>
    /// Represents initial setup for simulated annealing cooling
    /// </summary>
    public class CoolingSetup : ISelfValidable
    {
        /// <summary>
        /// Creates setup for cooling of simulated annealing
        /// </summary>
        /// <param name="initTemp">Initial temperature for system</param>
        /// <param name="coolingRate">Cooling rate of the system</param>
        /// <param name="coolingStrategy">Strategy for cooling the system</param>
        public CoolingSetup(double initTemp, double coolingRate, ICoolingStrategy coolingStrategy)
        {
            if (coolingRate <= 0)
                throw new ArgumentOutOfRangeException(nameof(coolingRate));
            if (initTemp <= 0)
                throw new ArgumentOutOfRangeException(nameof(initTemp));
            if (coolingStrategy == null)
                throw new ArgumentNullException(nameof(coolingStrategy));
            CoolingRate = coolingRate;
            InitialTemperature = initTemp;
            CoolingStrategy = coolingStrategy;
        }

        /// <summary>
        /// Initial temperature for the system
        /// </summary>
        public double InitialTemperature { get; private set; }

        /// <summary>
        /// Cooling rate for the system
        /// </summary>
        public double CoolingRate { get; private set; }

        /// <summary>
        /// Chosen cooling strategy for annealing.
        /// </summary>
        public ICoolingStrategy CoolingStrategy { get; private set; }

        /// <summary>
        /// Decides if state of object is valid.
        /// </summary>
        public bool IsValid()
        {
            return CoolingRate > 0 && InitialTemperature > 0 && CoolingStrategy != null;
        }
    }
}

using System;
class Graph
{
    static void Main(string[] args)
    {
        Func<int, int> outfunc = Composer<int, int, int>.Compose(functA, functB);
        Console.WriteLine(outfunc(5)); //Prints 100
    }
    static int functA(int i) { return i * 10; }
    static int functB(int i) { return i + 5; }
    class Composer<A, B, C>
    {
        public static Func<C, A> Compose(Func<B, A> a, Func<C, B> b)
        {
            return delegate(C i) { return a(b(i)); };
        }
    }
}

using System;
using System.Collections.Generic;
 
namespace HumbleNumbers {
    class Graph {
        static bool IsHumble(int i) {
            if (i <= 1) return true;
            if (i % 2 == 0) return IsHumble(i / 2);
            if (i % 3 == 0) return IsHumble(i / 3);
            if (i % 5 == 0) return IsHumble(i / 5);
            if (i % 7 == 0) return IsHumble(i / 7);
            return false;
        }
 
        static void Main() {
            var limit = short.MaxValue;
            Dictionary<int, int> humble = new Dictionary<int, int>();
            var count = 0;
            var num = 1;
 
            while (count < limit) {
                if (IsHumble(num)) {
                    var str = num.ToString();
                    var len = str.Length;
                    if (humble.ContainsKey(len)) {
                        humble[len]++;
                    } else {
                        humble[len] = 1;
                    }
                    if (count < 50) Console.Write("{0} ", num);
                    count++;
                }
                num++;
            }
            Console.WriteLine("\n");
 
            Console.WriteLine("Of the first {0} humble numbers:", count);
            num = 1;
            while (num < humble.Count - 1) {
                if (humble.ContainsKey(num)) {
                    var c = humble[num];
                    Console.WriteLine("{0,5} have {1,2} digits", c, num);
                    num++;
                } else {
                    break;
                }
            }
        }
    }
}

