namespace XmlToJsonTransformation
{
    // Interface to enforce a collection of items on the source container.
    public interface IItemized<TItem>
    {
        List<TItem> Items { get; }
    }

    // Generic converter class that transforms XML-based container items into cleaned JSON item objects.
    public class ItemizedTypeConverter<TSource, TItemSource, TDestination>
        where TSource : IItemized<TItemSource>
    {
        private readonly IMapper _mapper;

        public ItemizedTypeConverter(IMapper mapper)
        {
            _mapper = mapper ?? throw new ArgumentNullException(nameof(mapper));
        }

        // Converts the source container's items to a read-only collection of destination objects.
        public IReadOnlyCollection<TDestination> Convert(TSource source)
        {
            if (source == null || source.Items == null)
            {
                return new ReadOnlyCollection<TDestination>(new List<TDestination>());
            }

            // Map the list of source items to a list of destination objects.
            List<TDestination> mappedItems = _mapper.Map<List<TDestination>>(source.Items);

            // Wrap the result into a read-only collection.
            return new ReadOnlyCollection<TDestination>(mappedItems);
        }
    }

    // Example XML-based container model.
    public class XmlContainer : IItemized<XmlItem>
    {
        public List<XmlItem> Items { get; set; }
    }

    // Example XML item model.
    public class XmlItem
    {
        public int Id { get; set; }
        public string Name { get; set; }
    }

    // Example cleaned JSON item model.
    public class JsonItem
    {
        public int Id { get; set; }
        public string Title { get; set; }
    }

