namespace XmlCollectionUnitTests
{
    [TestClass]
    public class XmlCollectionTests : GivenWhenThenTestBase
    {
        private XmlCollection<string> _xmlCollection;
        private XmlCollectionThens _thens;

        [TestInitialize]
        public void TestSetup()
        {
            _thens = new XmlCollectionThens();
        }

        [TestMethod]
        public void XmlCollection_InitsWithoutItems_ShouldBeEmpty()
        {
            // Given: An XML collection is instantiated without any initial items.
            GivenXmlCollectionWithoutItems();

            // When: We inspect the state of the collection.
            WhenInspectCollection();

            // Then: The collection should be empty.
            _thens.CollectionCount.Should().Be(0, "because no items were provided during initialization");
            _thens.Items.Should().BeEmpty("because no items were added to the collection");
        }

        [TestMethod]
        public void XmlCollection_InitsWithPredefinedItems_ShouldReflectItemsCorrectly()
        {
            // Given: An XML collection is instantiated with a set of predefined items.
            string[] initialItems = { "Alpha", "Bravo", "Charlie" };
            GivenXmlCollectionWithItems(initialItems);

            // When: We inspect the state of the collection.
            WhenInspectCollection();

            // Then: The collection should contain exactly the initial items in the same order.
            _thens.CollectionCount.Should().Be(3, "because three items were provided for initialization");
            _thens.Items.Should().ContainInOrder(initialItems, "because the initialization should preserve the item order");
        }

        [TestMethod]
        public void XmlCollection_AddItem_ShouldIncreaseCollectionCountAndContainNewItem()
        {
            // Given: An XML collection is instantiated without any initial items.
            GivenXmlCollectionWithoutItems();

            // When: A new item is added to the collection.
            string newItem = "Delta";
            WhenAddItem(newItem);

            // Then: The collection should now contain the new item, and the count should be one.
            _thens.CollectionCount.Should().Be(1, "because one item has been added to an initially empty collection");
            _thens.Items.Should().Contain(newItem, "because the added item should be present in the collection");
        }

