public static class EnumerableExtensions
{
    // CartesianProduct for two sequences: returns tuples (T1, T2)
    public static IEnumerable<(T1, T2)> CartesianProduct<T1, T2>(this IEnumerable<T1> first, IEnumerable<T2> second)
    {
        if (first == null) throw new ArgumentNullException(nameof(first));
        if (second == null) throw new ArgumentNullException(nameof(second));
        foreach (var item1 in first)
        {
            foreach (var item2 in second)
            {
                yield return (item1, item2);
            }
        }
    }

    // CartesianProduct for multiple sequences: returns all possible combinations as IEnumerable<T> in list form
    public static IEnumerable<IEnumerable<T>> CartesianProduct<T>(this IEnumerable<IEnumerable<T>> sequences)
    {
        if (sequences == null) throw new ArgumentNullException(nameof(sequences));
        // initialize with empty product
        IEnumerable<IEnumerable<T>> result = new[] { Enumerable.Empty<T>() };
        foreach (var sequence in sequences)
        {
            if (sequence == null)
                throw new ArgumentException("One of the sequences is null", nameof(sequences));
            result = result.SelectMany(
                acc => sequence,
                (acc, item) => acc.Concat(new[] { item })
            );
        }
        return result;
    }

    // CartesianProduct for list of lists specifically for easier usage.
    public static IEnumerable<List<T>> CartesianProduct<T>(this List<List<T>> lists)
    {
        if (lists == null) throw new ArgumentNullException(nameof(lists));
        IEnumerable<List<T>> result = new List<List<T>> { new List<T>() };
        foreach (var list in lists)
        {
            if (list == null)
                throw new ArgumentException("One of the lists is null", nameof(lists));
            result = result.SelectMany(
                acc => list,
                (acc, item) =>
                {
                    var newAcc = new List<T>(acc);
                    newAcc.Add(item);
                    return newAcc;
                }
            );
        }
        return result;
    }

    // Concat extension method to append a single element to an IEnumerable<T>
    public static IEnumerable<T> Concat<T>(this IEnumerable<T> source, T element)
    {
        if (source == null) throw new ArgumentNullException(nameof(source));
        foreach (T item in source)
        {
            yield return item;
        }

