using System;
using System.Collections.Generic;
using DES.Interfaces;

namespace DES.Implementation
{
    public class PermutationService : IPermutationService
    {
        private const int PERMUTATION_BITS_AMOUNT = 64;

        private readonly List<int> initialPermutationIndexes = new List<int>
        {
            58, 50, 42, 34, 26, 18, 10, 2,
            60, 52, 44, 36, 28, 20, 12, 4,
            62, 54, 46, 38, 30, 22, 14, 6,
            64, 56, 48, 40, 32, 24, 16, 8,
            57, 49, 41, 33, 25, 17, 9, 1,
            59, 51, 43, 35, 27, 19, 11, 3,
            61, 53, 45, 37, 29, 21, 13, 5,
            63, 55, 47, 39, 31, 23, 15, 7
        };

        private readonly List<int> finalPermutationIndexes = new List<int>
        {
            40, 8, 48, 16, 56, 24, 64, 32,
            39, 7, 47, 15, 55, 23, 63, 31,
            38, 6, 46, 14, 54, 22, 62, 30,
            37, 5, 45, 13, 53, 21, 61, 29,
            36, 4, 44, 12, 52, 20, 60, 28,
            35, 3, 43, 11, 51, 19, 59, 27,
            34, 2, 42, 10, 50, 18, 58, 26,
            33, 1, 41, 9, 49, 17, 57, 25
        };

        public void InitialPermutation(ref List<bool> bits)
        {
            if (bits.Count != PERMUTATION_BITS_AMOUNT)
            {
                throw new ArgumentException("Invalid bit count for Initial Permutation.");
            }

            List<bool> permutedList = new List<bool>(new bool[PERMUTATION_BITS_AMOUNT]);

            for (int i = 0; i < PERMUTATION_BITS_AMOUNT; i++)
            {
                permutedList[i] = bits[initialPermutationIndexes[i] - 1];
            }
            bits = permutedList;

        }
        public void FinialPermutation(ref List<bool> bits)
        {
             if (bits.Count != PERMUTATION_BITS_AMOUNT)
            {
                throw new ArgumentException("Invalid bit count for final Permutation.");
            }

            List<bool> permutedList = new List<bool>(new bool[PERMUTATION_BITS_AMOUNT]);

            for (int i = 0; i < PERMUTATION_BITS_AMOUNT; i++)
            {
                 permutedList[i] = bits[finalPermutationIndexes[i] - 1];
            }

             bits = permutedList;
        }
    }
}

