public class StarItemController : A_ItemController
{
    [SerializeField] private string id;
    [SerializeField] private float addScoreRate = 1.0f;
    [SerializeField] private float completeFirstMoveDelay = 1.0f;

    private AddPositionGravity[] addPositionGravities;
    private PlayerChaseOnSpeed playerChase;
    private Transform refChasePlayer;
    private bool isFirstMove;

    public bool IsFirstMove => isFirstMove;

    protected override void Awake()
    {
        base.Awake();
        addPositionGravities = GetComponents<AddPositionGravity>();
        playerChase = GetComponent<PlayerChaseOnSpeed>();
    }

    private void Start()
    {
        refChasePlayer = ReferenceManager.Instance.PlayerTransform;
        InitializeBehavior();
    }

    private void InitializeBehavior()
    {
        isFirstMove = true;
        SetAllAddPositionGravityActive(true);
        playerChase.enabled = false;
        StartCoroutine(FirstMoveRoutine());
    }

    private IEnumerator FirstMoveRoutine()
    {
        yield return new WaitForSeconds(completeFirstMoveDelay);
        StartChasePlayer();
    }

    public void StartChasePlayer()
    {
        if (!isFirstMove) return;

        isFirstMove = false;
        SetAllAddPositionGravityActive(false);
        playerChase.enabled = true;
        playerChase.SetTarget(refChasePlayer);
        LockMovementOrientation();
    }

    private void LockMovementOrientation()
    {
        Rigidbody2D rb2D = GetComponent<Rigidbody2D>();
        if (rb2D != null)
        {
            rb2D.angularVelocity = 0f;
            rb2D.freezeRotation = true;
        }
        else
        {
            Rigidbody rb3D = GetComponent<Rigidbody>();
            rb3D?.FreezeRotation();
        }
        transform.rotation = Quaternion.identity;
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        if (other.CompareTag("Player")) HandleCollection();
    }

    private void OnTriggerEnter(Collider other)
    {
        if (other.CompareTag("Player")) HandleCollection();
    }

    private void HandleCollection()
    {
        ScoreManager.Instance.AddScore(addScoreRate);
        SoundManager.Instance.PlaySFX("StarCollect");
        Release();
    }

    public override void OnAwakeByPool()
    {
        base.OnAwakeByPool();
        ResetItemState();
        gameObject.SetActive(true);
    }

    private void ResetItemState()
    {
        StopAllCoroutines();
        isFirstMove = true;
        transform.rotation = Quaternion.identity;

