        static void Main(string[] args)
        {
            Console.WriteLine(multOrder(37, 1000)); // 100
            BigInteger b = BigInteger.Pow(10, 20) - 1;
            Console.WriteLine(multOrder(2, b)); // 3748806900
            Console.WriteLine(multOrder(17, b)); // 1499522760
            b = 100001;
            Console.WriteLine(multOrder(54, b));
            Console.WriteLine(BigInteger.ModPow(54, multOrder(54, b), b));
            if (Enumerable.Range(1, multOrder(54, b) - 1).Any(r => BigInteger.ModPow(54, r, b) == 1))
            {
                Console.WriteLine("Exists a power r < 9090 where pow(54,r,b)==1");
            }
            else
            {
                Console.WriteLine("Everything checks.");
            }
            Console.ReadLine();
        }
        public static BigInteger gcd(BigInteger a, BigInteger b)
        {
            while (b!= 0)
            {
                BigInteger t = b;
                b = a % b;
                a = t;
            }
            return a;
        }
        public static BigInteger lcm(BigInteger a, BigInteger b)
        {
            return (a * b) / gcd(a, b);
        }
        public static bool isPrime(BigInteger p)
        {
            return (p > 1) && Enumerable.All(factored(p), r => r.Item2 == p);
        }
        static List<BigInteger> primeList = new List<BigInteger>() { 2, 3, 5, 7 };
        public static IEnumerable<BigInteger> primes()
        {
            foreach (var p in primeList)
            {
                yield return p;
            }
            BigInteger p = 11;
            while (true)
            {
                p += 2;
                while (!isPrime(p))
                {
                    p += 2;
                }
                primeList.Add(p);
                yield return p;
            }
        }
        public static IEnumerable<Tuple<BigInteger, BigInteger>> factored(BigInteger a)
        {
            foreach (var p in primes())
            {
                BigInteger j = 0;
                while (a % p == 0)
                {
                    a /= p;
                    j += 1;
                }
                if (j > 0)
                {
                    yield return new Tuple<BigInteger, BigInteger>(p, j);
                }
                if (a < p * p) break;
            }

