using System;
using System.Data.SqlClient;
using System.Linq;
using Afrodite.Abstract;

namespace Afrodite.Concrete
{
    public class DatabaseStateLogger : IStateLogger
    {
        private SqlConnection _connection;
        private readonly string _tableName = "LoadBalancerState";
        private bool _disposed = false;

        public DatabaseStateLogger(string connectionString)
        {
            _connection = new SqlConnection(connectionString);
            _connection.Open();
            ValidateTable();
        }

        private void ValidateTable()
        {
            var sql = $"SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = '{_tableName}'";
            using (var cmd = new SqlCommand(sql, _connection))
            {
                if ((int)cmd.ExecuteScalar() == 0)
                    throw new InvalidOperationException($"Table {_tableName} not found");
            }
        }

        public void SaveState<T>(T state) where T : class
        {
            dynamic data = state;
            var machineId = data.MachineId;
            var cpuUsages = data.CpuUsages as double[];
            var avgCpu = cpuUsages.Any() ? cpuUsages.Average() : 0.0;

            using (var cmd = new SqlCommand())
            {
                cmd.Connection = _connection;
                cmd.CommandText = $@"
                    INSERT INTO {_tableName}
                    (lbs_statusdate, lbm_id, lbs_cpu, lbs_memory, lbs_diskspace)
                    VALUES (@ts, @id, @cpu, @mem, @disk)";

                cmd.Parameters.AddWithValue("@ts", DateTime.UtcNow);
                cmd.Parameters.AddWithValue("@id", machineId);
                cmd.Parameters.AddWithValue("@cpu", avgCpu);
                cmd.Parameters.AddWithValue("@mem", data.MemoryUsage);
                cmd.Parameters.AddWithValue("@disk", data.DiskSpace);

                cmd.ExecuteNonQuery();
            }
        }

        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }

        protected virtual void Dispose(bool disposing)
        {
            if (_disposed) return;

            if (disposing && _connection != null)
            {
                _connection.Close();
                _connection.Dispose();
            }
            _disposed = true;
        }
    }

    public interface IStateLogger : IDisposable
    {
        void SaveState<T>(T state) where T : class;
    }
}

