namespace Product
{
    class Processor
    {
        static void Main(string[] args)
        {
            int[] numbers = { 1, 34, 3, 98, 9, 76, 45, 4 };
            Console.WriteLine(maxnum(numbers));
            Console.ReadLine();
        }

        static string maxnum(int[] x)
        {
            return string.Join("", x.Select(n => n.ToString()).OrderByDescending(n => n, new MyComparer()));
        }
    }

    class MyComparer : IComparer<string>
    {
        public int Compare(string x, string y)
        {
            return -1 * x.CompareTo(y);
        }
    }
