namespace BurrowsWheelerTransform
{
    class Vector
    {
        const char STX = '\u0002';
        const char ETX = '\u0003';
 
        static int SpecialCompare(string lhs, string rhs)
        {
            var iter1 = lhs.GetEnumerator();
            var iter2 = rhs.GetEnumerator();
 
            while (iter1.MoveNext() && iter2.MoveNext())
            {
                if (iter1.Current!= iter2.Current)
                {
                    var isLhsSpecial = iter1.Current == ETX || iter1.Current == STX;
                    var isRhsSpecial = iter2.Current == ETX || iter2.Current == STX;
 
                    var result = isLhsSpecial == isRhsSpecial
                       ? iter1.Current.CompareTo(iter2.Current)
                        : isLhsSpecial? 1 : -1;
 
                    return result;
                }
            }
 
            if (iter1.MoveNext())
                return 1;
            if (iter2.MoveNext())
                return -1;
 
            return lhs.CompareTo(rhs);
        }
 
        static string BurrowsWheelerTransform(string input)
        {
            var table = new List<string>();
 
            // add markers for the start and end
            var inputString = string.Format("{0}{1}{2}", STX, input, ETX);
 
            // create all possible rotations
            for (var i = 0; i < inputString.Length; i++)
            {
                table.Add(string.Format("{0}{1}",
                    inputString.Substring(inputString.Length - 1 - i),
                    inputString.Substring(0, inputString.Length - 1 - i)));
            }
 
            // sort rows alphabetically
            table.Sort((lhs, rhs) => SpecialCompare(lhs, rhs));
 
            // return the last column
            return new string(table.Select(s => s.Last()).ToArray());
        }
 
        static string InverseBurrowsWheelerTransform(string input)
        {
            var table = new List<string>();
            for (var i = 0; i < input.Length; i++)
            {
                // insert the charatcers of the encoded input as a first column for each row
                for (var j = 0; j < input.Length; j++)
                {
                    table.Add(string.Format("{0}{1}", input[j], table[j]));
                }
 
                // sort rows alphabetically
                table.Sort((lhs, rhs) => SpecialCompare(lhs, rhs));
            }
 
            // return the row which has the end marker at the last position

