        public void Discover(ShapeTableBuilder builder)
        {
            builder.Describe("HeadScripts")
                .OnDisplaying(displaying =>
                {
                    if (!ShouldInjectScript())
                        return;

                    if (!IsScriptAlreadyIncluded())
                    {
                        _resourceManager.Require("script", NotificationScriptPath);
                    }
                });
