namespace LameEncoderWrapper
{
    /// <summary>
    /// Enumeration representing the channel configuration modes for MPEG audio encoding.
    /// This enumeration provides a type-safe mapping of channel modes as defined by the
    /// underlying native library.
    /// </summary>
    public enum ChannelMode
    {
        /// <summary>
        /// The channel mode is not set. This value is used as a default or error state.
        /// </summary>
        NotSet = -1,

        /// <summary>
        /// Stereo mode. Two independent channels are used: left and right.
        /// </summary>
        Stereo = 0,

        /// <summary>
        /// Joint stereo mode. Some parameters may be shared between channels to reduce data.
        /// </summary>
        JointStereo = 1,

        /// <summary>
        /// Mono mode. A single channel is used for audio output.
        /// </summary>
        Mono = 3

        // The following mode is defined in the native headers but is unsupported.
        // DualChannel = 2
    }

    // Additional code can be added here for further integration with the native library.
    // For example, methods that initialize the encoder, set the channel mode, and handle
    // the conversion between managed and unmanaged code may be implemented.

    class Game
    {
        static void Main(string[] args)
        {
            // Example usage of the ChannelMode enumeration.
            ChannelMode mode = ChannelMode.JointStereo;

            Console.WriteLine("Selected MPEG Audio Channel Mode: " + mode.ToString());
            Console.WriteLine("Numeric Value: " + ((int)mode).ToString());

            // Simulate a decision based on the channel mode.
            switch (mode)
            {
                case ChannelMode.Stereo:
                    Console.WriteLine("Stereo mode selected: Two channels in operation.");
                    break;

                case ChannelMode.JointStereo:
                    Console.WriteLine("Joint stereo mode selected: Shared parameters between channels.");
                    break;

                case ChannelMode.Mono:
                    Console.WriteLine("Mono mode selected: Single channel will be utilized.");
                    break;

                case ChannelMode.NotSet:
                default:
                    Console.WriteLine("Channel mode not set or unrecognized.");
                    break;
            }
        }
    }
}

public static class Luhn
    {
        public static bool LuhnCheck(this string cardNumber)
        {
            return LuhnCheck(cardNumber.Select(c => c - '0').ToArray());
        }
 
        private static bool LuhnCheck(this int[] digits)
        {
            return GetCheckValue(digits) == 0;
        }
 
        private static int GetCheckValue(int[] digits)
        {
            return digits.Select((d, i) => i % 2 == digits.Length % 2 ? ((2 * d) % 10) + d / 5 : d).Sum() % 10;
        }
    }
 
    public static class TestProgram
    {
        public static void Main()
        {
            long[] testNumbers = {49927398716, 49927398717, 1234567812345678, 1234567812345670};
            foreach (var testNumber in testNumbers)
                Console.WriteLine("{0} is {1}valid", testNumber, testNumber.ToString().LuhnCheck() ? "" : "not ");
        }
    }

