    /// Represents the authentication token package along with user profile details.
    /// </summary>
    public class AuthTokenPackage
    {
        // Access token string used for authorization.
        public string AccessToken { get; set; }

        // Refresh token string used to obtain new access tokens.
        public string RefreshToken { get; set; }

        // Expiration time for the access token.
        public DateTime ExpiresAt { get; set; }

        // Expiration (or failure) time for the refresh token.
        public DateTime RefreshTokenExpiresAt { get; set; }

        // Nested user profile information associated with the token.
        public UserProfile User { get; set; }

        // Parameterless constructor to initialize default values.
        public AuthTokenPackage()
        {
            // Initialize token values to defaults.
            AccessToken = string.Empty;
            RefreshToken = string.Empty;
            ExpiresAt = DateTime.MinValue;
            RefreshTokenExpiresAt = DateTime.MinValue;

            // Initialize the associated user profile.
            User = new UserProfile();
        }
    }

    /// <summary>
    /// Encapsulates detailed information about a user used in authentication and session management.
    /// </summary>
    public class UserProfile
    {
        // Unique identifier for the user.
        public Guid Id { get; set; }

        // Identifier for the tenant to which the user belongs.
        public string TenantId { get; set; }

        // Identifier for the department within the organization.
        public string DepartmentId { get; set; }

        // System-assigned code representing the user's identity.
        public string UserCode { get; set; }

        // Full name of the user.
        public string Name { get; set; }

        // User account name.
        public string Account { get; set; }

        // Contact email address of the user.
        public string Email { get; set; }

        // Contact phone number.
        public string PhoneNumber { get; set; }

        // URL to the user's avatar image.
        public string AvatarUrl { get; set; }

        // Flag indicating if the user is a built-in system account.
        public bool IsBuiltIn { get; set; }

        // Timestamp representing when the user registered.
        public DateTime RegisteredAt { get; set; }

