public static class IEnumerableExtensions
{
    public static IEnumerable<TSource> Union<TSource, T>(this IEnumerable<TSource> first, T second)
    {
        Ensure.ArgumentNotNull(first, nameof(first));
        return first.Union(new[] { second });
    }

    public static IEnumerable<T> Single<T>(this T source)
    {
        yield return source;
    }

    public static bool IsNullOrEmpty<T>(this IEnumerable<T> source)
    {
        return source == null || !source.Any();
    }
}

