namespace VRInput
{
    public enum ButtonState
    {
        Pressed,
        Released,
        Held
    }

    public struct TouchState
    {
        public ButtonState A;
        public ButtonState B;
        public ButtonState RThumb;
        public ButtonState RIndexTrigger;
        public ButtonState RGrip;
        public ButtonState X;
        public ButtonState Y;
        public ButtonState LThumb;
        public ButtonState LIndexTrigger;
        public ButtonState LGrip;

        public float RThumbX; // X position of right thumbstick
        public float RThumbY; // Y position of right thumbstick
        public float LThumbX; // X position of left thumbstick
        public float LThumbY; // Y position of left thumbstick

        public TouchState(ButtonState a, ButtonState b, ButtonState rThumb, ButtonState rIndexTrigger,
                          ButtonState rGrip, ButtonState x, ButtonState y, ButtonState lThumb,
                          ButtonState lIndexTrigger, ButtonState lGrip, float rThumbX,
                          float rThumbY, float lThumbX, float lThumbY)
        {
            A = a;
            B = b;
            RThumb = rThumb;
            RIndexTrigger = rIndexTrigger;
            RGrip = rGrip;
            X = x;
            Y = y;
            LThumb = lThumb;
            LIndexTrigger = lIndexTrigger;
            LGrip = lGrip;
            RThumbX = rThumbX;
            RThumbY = rThumbY;
            LThumbX = lThumbX;
            LThumbY = lThumbY;
        }

        public void Reset()
        {
            A = ButtonState.Released;
            B = ButtonState.Released;
            RThumb = ButtonState.Released;
            RIndexTrigger = ButtonState.Released;
            RGrip = ButtonState.Released;
            X = ButtonState.Released;
            Y = ButtonState.Released;
            LThumb = ButtonState.Released;
            LIndexTrigger = ButtonState.Released;
            LGrip = ButtonState.Released;

            RThumbX = 0f;
            RThumbY = 0f;
            LThumbX = 0f;
            LThumbY = 0f;
        }

        public bool IsAnyButtonPressed()
        {
            return A == ButtonState.Pressed || B == ButtonState.Pressed ||
                   RThumb == ButtonState.Pressed || RIndexTrigger == ButtonState.Pressed ||
                   RGrip == ButtonState.Pressed || X == ButtonState.Pressed ||
                   Y == ButtonState.Pressed || LThumb == ButtonState.Pressed ||
                   LIndexTrigger == ButtonState.Pressed || LGrip == ButtonState.Pressed;

