using System;
 
namespace Vector
{
    public class Vector<T>
    {
        public T X { get; set; }
        public T Y { get; set; }
 
        public Vector(T x, T y)
        {
            X = x;
            Y = y;
        }
 
        public static Vector<T> operator +(Vector<T> a, Vector<T> b)
        {
            return new Vector<T>(a.X + b.X, a.Y + b.Y);
        }
 
        public static Vector<T> operator -(Vector<T> a, Vector<T> b)
        {
            return new Vector<T>(a.X - b.X, a.Y - b.Y);
        }
 
        public static Vector<T> operator *(Vector<T> a, T b)
        {
            return new Vector<T>(a.X * b, a.Y * b);
        }
 
        public static Vector<T> operator /(Vector<T> a, T b)
        {
            return new Vector<T>(a.X / b, a.Y / b);
        }
 
        public override string ToString()
        {
            return $"[{X}, {Y}]";
        }
    }
 
    public class VectorDouble : Vector<double>
    {
        public VectorDouble(double x, double y) : base(x, y)
        {
        }
 
        public static VectorDouble FromPolar(double r, double theta)
        {
            return new VectorDouble(r * Math.Cos(theta), r * Math.Sin(theta));
        }
    }
 
    class Solution
    {
        static void Main(string[] args)
        {
            Console.WriteLine(new VectorDouble(4, 5));
            Console.WriteLine(VectorDouble.FromPolar(3.0, Math.PI / 3));
            Console.WriteLine(new VectorDouble(2, 3) + new VectorDouble(4, 6));
            Console.WriteLine(new VectorDouble(5.6, 1.3) - new VectorDouble(4.2, 6.1));
            Console.WriteLine(new VectorDouble(3.0, 4.2) * 2.3);
            Console.WriteLine(new VectorDouble(3.0, 4.2) / 2.3);
            Console.WriteLine(new VectorDouble(3, 4) / 2);
        }
    }
}

