namespace FileSystemValidation
{
    // Enumeration of possible validation statuses.
    public enum ValidationStatus
    {
        Valid,
        Skipped,
        Error
    }

    // A simple structure to encapsulate a validation message.
    public class ValidationMessage
    {
        public string Path { get; set; }
        public ValidationStatus Status { get; set; }
        public string Description { get; set; }

        public ValidationMessage(string path, ValidationStatus status, string description)
        {
            Path = path;
            Status = status;
            Description = description;
        }

        public override string ToString()
        {
            return $"Path: {Path}, Status: {Status}, Description: {Description}";
        }
    }

    // An interface representing a validator.
    public interface IValidator
    {
        IEnumerable<ValidationMessage> Validate();
    }

    // A base validator class which can be extended for XML validations.
    public abstract class BaseXmlValidator : IValidator
    {
        public abstract IEnumerable<ValidationMessage> Validate();
    }

    // The validator class for validating file system paths extracted from XML.
    public class XmlPathValidator : BaseXmlValidator
    {
        private readonly IEnumerable<XmlDocument> _documents;

        // Constructor accepts a collection of pre-loaded XML documents.
        public XmlPathValidator(IEnumerable<XmlDocument> documents)
        {
            _documents = documents;
        }

        // The Validate method iterates through each XML document and checks each path element.
        public override IEnumerable<ValidationMessage> Validate()
        {
            foreach (XmlDocument doc in _documents)
            {
                // Retrieve all elements named "Path".
                XmlNodeList pathNodes = doc.GetElementsByTagName("Path");

                foreach (XmlNode node in pathNodes)
                {
                    if (node == null || string.IsNullOrWhiteSpace(node.InnerText))
                    {
                        yield return new ValidationMessage(string.Empty, ValidationStatus.Error, "Empty or null path element encountered.");
                        continue;
                    }

                    string pathValue = node.InnerText.Trim();

                    // Check if the path is a URI (starts with http:// or https://).

using UnityEngine;

public class SimplePlatformController : MonoBehaviour
{
    private Rigidbody2D rb;
    private Animator anim;

    public float moveForce = 365f;
    public float maxSpeed = 5f;
    public float jumpForce = 1000f;

    private bool facingRight = true;
    private bool grounded = false;
    private bool jump = false;

    private void Awake()
    {
        rb = GetComponent<Rigidbody2D>();
        anim = GetComponent<Animator>();
    }

    private void Update()
    {
        HandleInput();
        UpdateAnimation();
    }

    private void FixedUpdate()
    {
        Move();
        CheckJump();
    }

    private void HandleInput()
    {
        float move = Input.GetAxis("Horizontal");
        if (move > 0 && !facingRight)
        {
            Flip();
        }
        else if (move < 0 && facingRight)
        {
            Flip();
        }

        jump = Input.GetButtonDown("Jump");
    }

    private void Move()
    {
        float move = Input.GetAxis("Horizontal");
        if (Mathf.Abs(move) > 0)
        {
            rb.AddForce(Vector2.right * moveForce * move);
        }

        if (rb.velocity.x > maxSpeed)
        {
            rb.velocity = new Vector2(maxSpeed, rb.velocity.y);
        }
        else if (rb.velocity.x < -maxSpeed)
        {
            rb.velocity = new Vector2(-maxSpeed, rb.velocity.y);
        }
    }

    private void CheckJump()
    {
        if (grounded && jump)
        {
            rb.AddForce(new Vector2(0f, jumpForce));
            jump = false;
        }
    }

    private void Flip()
    {
        facingRight = !facingRight;
        Vector3 theScale = transform.localScale;
        theScale.x *= -1;
        transform.localScale = theScale;
    }

    private void UpdateAnimation()
    {
        anim.SetBool("Jumping", !grounded);
        anim.SetFloat("Speed", Mathf.Abs(rb.velocity.x));
    }

    private void OnCollisionEnter2D(Collision2D collision)
    {
        if (collision.gameObject.CompareTag("Ground"))
        {
            grounded = true;
        }
        else if (collision.gameObject.CompareTag("Enemy"))
        {
            HandleEnemyCollision(collision.gameObject);
        }
    }

    private void OnCollisionExit2D(Collision2D collision)
    {
        if (collision.gameObject.CompareTag("Ground"))
        {
            grounded = false;
        }
    }

    private void HandleEnemyCollision(GameObject enemy)
    {
        // Assuming the enemy has a health manager component
        HealthManager healthManager = enemy.GetComponent<HealthManager>();

