using System;
using System.Collections.Generic;
using DNTProfiler.Common.Logger;
using DNTProfiler.Common.Models;
using DNTProfiler.Common.Mvvm;

namespace DNTProfiler.Common.Profiler
{
    public static class CommandStatisticsRun
    {
        private static readonly Dictionary<string, CommandStatistics> _commandStatistics =
            new Dictionary<string, CommandStatistics>();

        public static void SetCommandStatistics(this Command command)
        {
            try
            {
                runAnalysis(command);
                setNormalizedSqlHash(command);
            }
            catch (Exception ex)
            {
                ExceptionLogger.LogExceptionToFile(ex, AppMessenger.LogFile);
                AppMessenger.NotifyColleagues(AppMessengerNotifications.ShowException, ex);
            }
        }

        private static void runAnalysis(Command command)
        {
            if (_commandStatistics.ContainsKey(command.SqlHash))
            {
                command.CommandStatistics = _commandStatistics[command.SqlHash];
                return;
            }

            var visitor = new CounterVisitor();
            RunTSqlFragmentVisitor.AnalyzeFragmentVisitor(command.Sql, visitor);

            var commandStatistics = new CommandStatistics
            {
                SelectsCount = visitor.Selects,
                UpdatesCount = visitor.Updates,
                InsertsCount = visitor.Inserts,
                DeletesCount = visitor.Deletes,
                OthersCount = visitor.Others
            };
            _commandStatistics.Add(command.SqlHash, commandStatistics);
            command.CommandStatistics = commandStatistics;
        }

        private static void setNormalizedSqlHash(Command command)
        {
            command.NormalizedSqlHash = RunTSqlFragmentVisitor.GetNormalizedSqlHash(command.Sql);
        }
    }
}

using System.Collections.ObjectModel;
