namespace NavigationFramework
{
    public abstract class NavigationNode : ObservableBase
    {
        private bool _isSelected;
        private string _title;
        private string _icon;

        public string Title
        {
            get => _title;
            set => SetProperty(ref _title, value);
        }

        public string Icon
        {
            get => _icon;
            set => SetProperty(ref _icon, value);
        }

        public bool IsSelected
        {
            get => _isSelected;
            set => SetProperty(ref _isSelected, value, onChanged: Selected);
        }

        public abstract bool IsContainer { get; }
        public abstract void Selected();
    }

    public sealed class ItemNavigationNode : NavigationNode
    {
        private string _navigationTarget;

        public string NavigationTarget
        {
            get => _navigationTarget;
            set => SetProperty(ref _navigationTarget, value);
        }

        public override bool IsContainer => false;

        public override void Selected()
        {
            if (!string.IsNullOrEmpty(NavigationTarget))
            {
                NavigationService.NavigateTo(NavigationTarget);
            }
        }
    }

    public sealed class GroupNavigationNode : NavigationNode
    {
        private Visibility _childVisibility;
        private ObservableCollection<NavigationNode> _nodes;

        public GroupNavigationNode()
        {
            _nodes = new ObservableCollection<NavigationNode>();
            _childVisibility = Visibility.Collapsed;
        }

        public ObservableCollection<NavigationNode> Nodes
        {
            get => _nodes;
            set => SetProperty(ref _nodes, value);
        }

        public Visibility ChildVisibility
        {
            get => _childVisibility;
            private set => SetProperty(ref _childVisibility, value);
        }

        public override bool IsContainer => true;

        public override void Selected()
        {
            ChildVisibility = ChildVisibility == Visibility.Visible
                ? Visibility.Collapsed
                : Visibility.Visible;

            foreach (var node in Nodes)
            {
                if (node.IsSelected) node.IsSelected = false;
            }
        }

        public void AddChildNode(NavigationNode node)
        {
            if (!Nodes.Contains(node))
            {
                Nodes.Add(node);
            }
        }
    }

