    public IPortalViewEntity Entity { get; private set; }
    public IPortalViewEntity ViewEntity { get; private set; }
    public IEnumerable<WebLink> WebLinks { get; private set; }
    public string Name => GetAttribute("name");
    public string Title => GetAttribute("title");
    public string DisplayName => GetAttribute("adx_displayname");
    public string Description => GetAttribute("adx_description");
    public EntityReference EntityReference => Entity.EntityReference;
    public bool IsEditable => Entity.IsEditable;

    public WebLinkSet(IPortalViewEntity entity, IPortalViewEntity viewEntity, IEnumerable<WebLink> webLinks)
    {
        if (entity == null)
            throw new ArgumentNullException(nameof(entity));
        if (viewEntity == null)
            throw new ArgumentNullException(nameof(viewEntity));
        if (webLinks == null)
            throw new ArgumentNullException(nameof(webLinks));

        Entity = entity;
        ViewEntity = viewEntity;
        WebLinks = webLinks;
    }

    public string GetAttribute(string attributeLogicalName)
    {
        if (string.IsNullOrEmpty(attributeLogicalName))
            throw new ArgumentException("Attribute logical name cannot be null or empty.", nameof(attributeLogicalName));

        var attribute = ViewEntity.GetAttribute(attributeLogicalName);
        return attribute?.Value?.ToString();
    }
}

