    public class DeleteEntry : DeleteRunnable
    {
        private readonly PwEntry _entry;
        private readonly IKp2aApp m_app;
        private readonly Activity Ctx;
        private PwDatabase Db { get; set; }

        public DeleteEntry(Activity ctx, PwEntry entry, IKp2aApp kp2aApp) : base(ctx)
        {
            Ctx = ctx;
            _entry = entry;
            m_app = kp2aApp;
        }

        protected override bool CanRecycle()
        {
            Db = _entry.ParentGroup.Database;
            if (Db == null) return false;

            if (Db.RecycleBinUuid.Equals(Global.InvalidUuid))
            {
                return false;
            }

            return true;
        }

        protected override void PerformDelete()
        {
            Db = _entry.ParentGroup.Database;
            PwGroup recycleBinGroup = Db.FindGroup(Db.RecycleBinUuid, true);

            if (recycleBinGroup != null && CanRecycle())
            {
                Db.MoveEntry(_entry, recycleBinGroup);
                StatusMessage = m_app.GetUiString(UiStringKey.EntryMovedToRecycleBin);
                TouchedGroups = new List<PwGroup> { _entry.ParentGroup, recycleBinGroup };
            }
            else
            {
                PwGroup parentGroup = _entry.ParentGroup;
                if (parentGroup != null)
                {
                    Db.RootGroup.DeleteSubEntry(_entry, true);
                    StatusMessage = m_app.GetUiString(UiStringKey.EntryPermanentlyDeleted);

                    TouchedGroups = new List<PwGroup> { parentGroup };
                    PermanentlyDeletedGroups = new List<PwGroup> { parentGroup };
                }
                else
                {
                    StatusMessage = "Error: Parent group not found for entry.";
                    TouchedGroups = new List<PwGroup>();
                    PermanentlyDeletedGroups = new List<PwGroup>();
                }
            }
        }

        public string StatusMessage { get; private set; }
        public List<PwGroup> TouchedGroups { get; private set; }
        public List<PwGroup> PermanentlyDeletedGroups { get; private set; }
    }

    public abstract class DeleteRunnable
    {
        protected DeleteRunnable(Activity ctx)
        {
            Context = ctx;
        }

