            cmd.WaitForExit();
            Console.WriteLine("Hello");
        }
    }
}

using System;
using System.Linq;
using System.Collections.Generic;
 
public class Library
{
    public static void Main()
    {
        Func<double, double> f = x => x * x * x - 3 * x * x + 2 * x;
        FindRoots(f, -1, 3);
    }
 
    public static void FindRoots(Func<double, double> f, double start, double end, double step = 0.001)
    {
        var sign = Sign(f(start));
        for (var x = start; x <= end; x += step)
        {
            var value = f(x);
            if (value == 0)
            {
                Console.WriteLine("Root found at {0}", x);
            }
            else if (Sign(value) == -sign)
            {
                Console.WriteLine("Root found between {0} and {1}", x - step, x);
            }
            sign = Sign(value);
        }
    }
 
    public static int Sign(double x)
    {
        return Math.Sign(x);
    }
}

