namespace NXTLib
{
    public static class Utils
    {
        public static string AddressByte2String(byte[] address, bool withcolons)
        {
            //BluetoothAddress adr = new BluetoothAddress(address);
            //string c = adr.ToString();

            string[] str = new string[6];
            for (int i = 0; i < 6; i++)
                str[i] = address[5 - i].ToString("x2");

            string sep = ":";
            if (!withcolons) { sep = ""; }
            string a = string.Join(sep, str);

            return a;
        }
        public static byte[] AddressString2Byte(string address, bool withcolons)
        {
            byte[] a = new byte[6];
            int sep = 3;
            if (!withcolons) { sep = 2; }
            for (int i = 0; i < 6; i++)
            {
                byte b = byte.Parse(address.Substring(i * sep, 2), System.Globalization.NumberStyles.HexNumber);
                a[5 - i] = b;
            }

            return a;
        }
        public static List<Brick> Combine(List<Brick> bricks1, List<Brick> bricks2)
        {
            List<Brick> bricks = new List<Brick>();
            bricks.AddRange(bricks1);
            bricks.AddRange(bricks2);
            return bricks;
        }
        private static Int64 GetValue(this string value)
        {
            if (string.IsNullOrWhiteSpace(value))
            {
                return 0;
            }
            Int64 output;
            // TryParse returns a boolean to indicate whether or not
            // the parse succeeded. If it didn't, you may want to take
            // some action here.
            Int64.TryParse(value, out output);
            return output;
        }
    }
}

using System;
using System.Web.UI;
using Microsoft.AspNet.Identity;
using Microsoft.AspNet.Identity.Owin;

public partial class VerifyPhoneNumber : Page
{
    private ApplicationUserManager manager;
    private ApplicationSignInManager signInManager;

    protected void Page_Load(object sender, EventArgs e)
    {
        manager = Context.GetOwinContext().GetUserManager<ApplicationUserManager>();
        signInManager = Context.GetOwinContext().Get<ApplicationSignInManager>();
        string userId = Context.GetOwinContext().Authentication.GetUserId();
        string phoneNumber = Request.QueryString["PhoneNumber"];

        if (!IsPostBack)
        {
            if (string.IsNullOrEmpty(phoneNumber))
            {
                Response.Redirect("~/Account/Manage");
            }
            else
            {
                var code = manager.GenerateChangePhoneNumberToken(userId, phoneNumber);
                PhoneNumber.Text = phoneNumber;
            }
        }
    }

    protected void Code_Click(object sender, EventArgs e)
    {
        string userId = Context.GetOwinContext().Authentication.GetUserId();
        string phoneNumber = Request.QueryString["PhoneNumber"];
        string code = Code.Text;

        if (string.IsNullOrEmpty(phoneNumber) || string.IsNullOrEmpty(code))
        {
            ErrorMessage.Text = "Phone number and verification code are required.";
            return;
        }

        var result = manager.ChangePhoneNumber(userId, phoneNumber, code);
        if (result.Succeeded)
        {
            var user = manager.FindById(userId);
            if (user != null)
            {
                signInManager.SignIn(user, isPersistent: false, rememberBrowser: false);
                Response.Redirect("~/Account/Manage?m=AddPhoneNumberSuccess");
            }
        }
        else
        {
            ErrorMessage.Text = "Invalid verification code. Please try again.";
        }
    }
}

