namespace PowerShellExtension.Commands
{
    /// <summary>
    /// Command handler for showing the PowerShell Explorer Window.
    /// </summary>
    internal sealed class ShowPowerShellExplorerCommand
    {
        // Unique identifier for the command set.
        public static readonly Guid CommandSet = new Guid("d1b8c583-47e1-4e32-9d7d-1f3b5f47abc1");
        // Command ID.
        public const int CommandId = 0x0100;
        // Reference to the VS Package.
        private readonly Package package;

        /// <summary>
        /// Initializes a new instance of the <see cref="ShowPowerShellExplorerCommand"/> class.
        /// Adds the command handler for the menu command.
        /// </summary>
        /// <param name="package">Owner package, not null.</param>
        private ShowPowerShellExplorerCommand(Package package)
        {
            this.package = package ?? throw new ArgumentNullException(nameof(package));

            // Obtain the command service from the package.
            if (this.ServiceProvider.GetService(typeof(IMenuCommandService)) is OleMenuCommandService commandService)
            {
                var menuCommandID = new CommandID(CommandSet, CommandId);
                var menuItem = new OleMenuCommand(Execute, menuCommandID);
                menuItem.BeforeQueryStatus += QueryStatus;
                commandService.AddCommand(menuItem);
            }
        }

        /// <summary>
        /// Gets the service provider.
        /// </summary>
        private IServiceProvider ServiceProvider => package;

        /// <summary>
        /// Gets the instance of the command.
        /// This is the singleton instance of the command.
        /// </summary>
        public static ShowPowerShellExplorerCommand Instance
        {
            get;
            private set;
        }

        /// <summary>
        /// Initializes the singleton instance of the command.
        /// </summary>
        /// <param name="package">Owner package.</param>
        public static void Initialize(Package package)
        {
            Instance = new ShowPowerShellExplorerCommand(package);
        }

        /// <summary>
        /// This function is the callback used to execute the command when the menu item is clicked.
        /// It triggers the display of the PowerShell Explorer Window.
        /// </summary>
        /// <param name="sender">The event sender.</param>

