public class HelpController : Controller
{
    private const string ErrorViewName = "Error";
    private static ModelDescriptionGenerator _modelGenerator;

    public HttpConfiguration Configuration { get; private set; }

    public HelpController()
    {
        Configuration = GlobalConfiguration.Configuration;
        _modelGenerator ??= new ModelDescriptionGenerator(Configuration);
    }

    public ActionResult Index()
    {
        var apiExplorer = Configuration.Services.GetApiExplorer();
        ViewBag.ApiExplorer = apiExplorer;
        return View(apiExplorer.ApiDescriptions);
    }

    public ActionResult Api(string id)
    {
        if (!string.IsNullOrEmpty(id))
        {
            var apiExplorer = Configuration.Services.GetApiExplorer();
            var apiDescription = apiExplorer.ApiDescriptions.FirstOrDefault(a => a.GetFriendlyId() == id);

            if (apiDescription != null)
            {
                var apiModel = HelpPageApiModel.FromApiDescription(apiDescription, Configuration);
                apiModel.ModelDescription = _modelGenerator.GetOrCreateModelType(apiModel.ActionDescriptor.ActionType);
                return View(apiModel);
            }
        }

        return View(ErrorViewName);
    }

    public ActionResult ResourceModel(string modelName)
    {
        if (!string.IsNullOrEmpty(modelName))
        {
            ModelDescription modelDescription;
            if (_modelGenerator.GeneratedModels.TryGetValue(modelName, out modelDescription))
            {
                return View(modelDescription);
            }
        }

        return View(ErrorViewName);
    }

    private class HelpPageApiModel
    {
        public ApiDescription ApiDescription { get; set; }
        public ModelDescription ModelDescription { get; set; }
        public IList<ParameterDescription> ParameterDescriptions { get; set; }

        public static HelpPageApiModel FromApiDescription(ApiDescription apiDesc, HttpConfiguration config)
        {
            return new HelpPageApiModel
            {
                ApiDescription = apiDesc,
                ParameterDescriptions = apiDesc.ParameterDescriptions
            };
        }
    }

