public static string mult(string strNum1, string strNum2)
{
    var a1 = strNum1.ToCharArray().Reverse().ToArray();
    var a2 = strNum2.ToCharArray().Reverse().ToArray();
    var aResult = new List<int>();

    for (var iterNum1 = 0; iterNum1 < a1.Length; iterNum1++)
    {
        for (var iterNum2 = 0; iterNum2 < a2.Length; iterNum2++)
        {
            var idxIter = iterNum1 + iterNum2; // Get the current array position.
            aResult[idxIter] = a1[iterNum1] * a2[iterNum2] + (idxIter >= aResult.Count? 0 : aResult[idxIter]);

            if (aResult[idxIter] > 9) // Carrying
            {
                aResult[idxIter + 1] = aResult[idxIter] / 10 + (idxIter + 1 >= aResult.Count? 0 : aResult[idxIter + 1]);
                aResult[idxIter] %= 10;
            }
        }
    }
    return string.Join("", aResult.Reverse().ToArray());
}

