namespace SimulationFramework
{
    [StorableClass]
    [Item("SimulationEnvelope", "Base class for simulation result containers")]
    public abstract class SimulationEnvelope : ICloneable, IStorable
    {
        [Storable]
        [VisibleName("Raw Output")]
        [Description("Numerical outputs from simulation process")]
        [Category("Simulation Results")]
        protected List<double> rawOutput;

        [Storable]
        [VisibleName("Fitness Score")]
        [Description("Calculated performance metric")]
        [Category("Evaluation")]
        protected double fitnessScore;

        [Storable]
        [VisibleName("Simulation Timestamp")]
        [Description("Time of simulation execution")]
        protected DateTime simulationTimestamp;

        public SimulationEnvelope()
        {
            rawOutput = new List<double>();
            fitnessScore = 0.0;
            simulationTimestamp = DateTime.Now;
        }

        public SimulationEnvelope(List<double> initialOutput)
        {
            rawOutput = new List<double>(initialOutput);
            fitnessScore = CalculateFitnessScore();
            simulationTimestamp = DateTime.Now;
        }

        public SimulationEnvelope(bool isTestData)
        {
            if (isTestData)
            {
                rawOutput = GenerateTestData();
                fitnessScore = CalculateFitnessScore();
                simulationTimestamp = DateTime.Now;
            }
            else
            {
                rawOutput = new List<double>();
                fitnessScore = 0.0;
                simulationTimestamp = DateTime.Now;
            }
        }

        protected virtual List<double> GenerateTestData()
        {
            Random random = new Random();
            List<double> testData = new List<double>();
            for (int i = 0; i < 10; i++)
            {
                testData.Add(random.NextDouble() * 100);
            }
            return testData;
        }

        protected virtual double CalculateFitnessScore()
        {
            if (rawOutput == null || rawOutput.Count == 0)
                return 0.0;

            double sumSquared = 0.0;
            foreach (double value in rawOutput)
            {
                sumSquared += Math.Pow(value, 2);
            }

            return Math.Sqrt(sumSquared / rawOutput.Count);
        }

