public class Companion
{
    private Random _random;
    private Vector2 _currentPosition;
    private SubsumptionBehavior _currentBehavior;

    public float InteractionRange { get; set; }
    public float MovementSpeed { get; set; }

    public Companion()
    {
        _random = new Random();
        InteractionRange = 50f;
        MovementSpeed = 2.5f;
        InitializeBehaviors();
    }

    private void InitializeBehaviors()
    {
        _currentBehavior = new RandomWanderBehavior(this);
    }

    public void OnUpdate(GameTime gameTime)
    {
        if (_currentBehavior != null)
        {
            _currentBehavior.Update(gameTime);
            UpdateBehaviorPriority();
        }
    }

    private void UpdateBehaviorPriority()
    {
        SubsumptionBehavior[] behaviors = new SubsumptionBehavior[]
        {
            new ChaseBehavior(this),
            new CombatBehavior(this),
            new RandomWanderBehavior(this)
        };

        foreach (var behavior in behaviors)
        {
            if (behavior.ShouldActivate())
            {
                _currentBehavior = behavior;
                break;
            }
        }
    }
}

