namespace Stack
{
    class Manager
    {
        static void Main()
        {
            double[] myArr = new double[] { 1, 5, 3, 6, 4, 2 };
 
            myArr = myArr.OrderBy(i => i).ToArray();
            // or Array.Sort(myArr) for in-place sort
 
            int mid = myArr.Length / 2;
            double median;
 
            if (myArr.Length % 2 == 0)
            {
                //we know its even
                median = (myArr[mid] + myArr[mid - 1]) / 2.0;
            }
            else
            {
                //we know its odd
                median = myArr[mid];
            }
 
            Console.WriteLine(median);
            Console.ReadLine();
        }
    }
}

using System;
using System.Collections.Generic;

public struct Loc2D
{
    public int X { get; }
    public int Y { get; }

    public Loc2D(int x, int y)
    {
        X = x;
        Y = y;
    }
}

public class PathTile
{
    public Loc2D Location { get; private set; }
    public bool Seen { get; set; }
    public bool Traversed { get; set; }
    public float Cost { get; set; }
    public float Heuristic { get; set; }
    public PathTile BackReference { get; set; }

    public PathTile(Loc2D location)
    {
        Location = location;
        Seen = false;
        Traversed = false;
        Cost = float.MaxValue;
        Heuristic = 0;
        BackReference = null;
    }

    public void MarkAsSeen()
    {
        Seen = true;
    }

    public void MarkAsTraversed()
    {
        Traversed = true;
    }

    public void UpdateCosts(float newCost, float newHeuristic)
    {
        Cost = newCost;
        Heuristic = newHeuristic;
    }

    public List<PathTile> GetNeighbors(PathTile[,] grid)
    {
        List<PathTile> neighbors = new List<PathTile>();

        int width = grid.GetLength(0);
        int height = grid.GetLength(1);

        for (int dx = -1; dx <= 1; dx++)
        {
            for (int dy = -1; dy <= 1; dy++)
            {
                if (Math.Abs(dx) != Math.Abs(dy)) // Only horizontal and vertical movements
                {
                    int newX = Location.X + dx;
                    int newY = Location.Y + dy;

                    if (newX >= 0 && newX < width && newY >= 0 && newY < height)
                    {
                        neighbors.Add(grid[newX, newY]);
                    }
                }
            }
        }
        return neighbors;
    }

    public float TotalCost()
    {
        return Cost + Heuristic;
    }
}

public class PathfindingGrid
{
    private PathTile[,] grid;

    public PathfindingGrid(int width, int height)
    {
        grid = new PathTile[width, height];
        InitializeGrid();
    }

    private void InitializeGrid()
    {
        for (int x = 0; x < grid.GetLength(0); x++)
        {
            for (int y = 0; y < grid.GetLength(1); y++)
            {
                grid[x, y] = new PathTile(new Loc2D(x, y));
            }
        }
    }

    public PathTile GetTile(int x, int y)
    {
        if (x < 0 || x >= grid.GetLength(0) || y < 0 || y >= grid.GetLength(1))
        {
            throw new ArgumentOutOfRangeException("Coordinates are out of grid boundaries.");
        }
        return grid[x, y];
    }
}

