        {
            public double PhysicalResist;
            public double MagicalResist;
            public double ElementalResist;
        }

        public HarpyType CreatureType { get; private set; }
        public HarpyResistance Resistances { get; private set; }
        public bool CanFly { get; private set; }
        public int FlightSkillLevel { get; private set; }
        public string MeatType { get; private set; }

