        {
            CreatureType = type;
            CanFly = true;
            MeatType = "Exotic";
            FlightSkillLevel = DetermineFlightSkillByType(type);

            ConfigureResistances(type);
            ConfigureCombatStats(type);
            ConfigureSoundProfile();
        }

        private int DetermineFlightSkillByType(HarpyType type)
        {
            return type switch
            {
                HarpyType.Alpha => 85,
                HarpyType.Legendary => 95,
                _ => 65
            };
        }

        private void ConfigureResistances(HarpyType type)
        {
            Resistances = type switch
            {
                HarpyType.Alpha => new HarpyResistance
                {
                    PhysicalResist = 0.6,
                    MagicalResist = 0.5,
                    ElementalResist = 0.4
                },
                HarpyType.Legendary => new HarpyResistance
                {
                    PhysicalResist = 0.8,
                    MagicalResist = 0.7,
                    ElementalResist = 0.6
                },
                _ => new HarpyResistance
                {
                    PhysicalResist = 0.4,
                    MagicalResist = 0.3,
                    ElementalResist = 0.2
                }

using System;
using System.Collections.Concurrent;
using System.Threading.Tasks;
using Microsoft.Owin.Security;
using Microsoft.Owin.Security.Infrastructure;

public class RefreshTokenProvider : IAuthenticationTokenProvider
{
    // In-memory thread-safe store for refresh tokens
    private static ConcurrentDictionary<string, AuthenticationTicket> _refreshTokens = new ConcurrentDictionary<string, AuthenticationTicket>();

    // Token lifetime: here using 30 minutes for demonstration purposes.
    private readonly TimeSpan _refreshTokenLifetime = TimeSpan.FromMinutes(30);

    // Synchronous wrapper for token creation.
    public void Create(AuthenticationTokenCreateContext context)
    {
        CreateAsync(context).Wait();
    }

    // Asynchronously creates a new refresh token.
    public async Task CreateAsync(AuthenticationTokenCreateContext context)
    {
        // Generate a unique token handle.
        var tokenId = Guid.NewGuid().ToString("n");

        // Set the issued and expiry times on the properties.
        var issued = DateTime.UtcNow;
        var expires = issued + _refreshTokenLifetime;

        context.Ticket.Properties.IssuedUtc = issued;
        context.Ticket.Properties.ExpiresUtc = expires;

        // Optionally, you can update ticket.Identity with additional claims if needed.
        // Store the ticket keyed by the token identifier.
        _refreshTokens[tokenId] = context.Ticket;

        // Set the token value in the context.
        context.SetToken(tokenId);

        // Simulate async work.
        await Task.CompletedTask;
    }

    // Synchronous wrapper for token reception.
    public void Receive(AuthenticationTokenReceiveContext context)
    {
        ReceiveAsync(context).Wait();
    }

    // Asynchronously retrieves the authentication ticket based on the token.
    public async Task ReceiveAsync(AuthenticationTokenReceiveContext context)
    {
        string tokenId = context.Token;

        if (string.IsNullOrEmpty(tokenId))
        {
            return;
        }

        // Attempt to remove the token, ensuring it cannot be reused.
        AuthenticationTicket ticket;
        if (_refreshTokens.TryRemove(tokenId, out ticket))
        {
            // You can include additional validation here, such as expiry checks.
            if (ticket.Properties.ExpiresUtc.HasValue && ticket.Properties.ExpiresUtc.Value > DateTime.UtcNow)
            {
                context.SetTicket(ticket);
            }
        }

        // Simulate async work.
        await Task.CompletedTask;
    }

using System;
using Moq;
using NUnit.Framework;
using Umbraco.Core;
using Umbraco.Core.Cache;
using Umbraco.Core.Composing;
using Umbraco.Core.Logging;

namespace Umbraco.Tests.Composing
{
    [TestFixture]
    public class CompositionTests
    {
        [Test]
        public void FactoryIsResolvable()
        {
            Func<IFactory, IFactory> factoryFactory = null;

            var mockedRegister = Mock.Of<IRegister>();
            var mockedFactory = Mock.Of<IFactory>();

            // the mocked register creates the mocked factory
            Mock.Get(mockedRegister)
                .Setup(x => x.CreateFactory())
                .Returns(mockedFactory);

            // the mocked register can register a factory factory
            Mock.Get(mockedRegister)
                .Setup(x => x.Register(It.IsAny<Func<IFactory, IFactory>>(), Lifetime.Singleton))
                .Callback<Func<IFactory, IFactory>, Lifetime>((ff, lt) => factoryFactory = ff);

            // the mocked factory can invoke the factory factory
            Mock.Get(mockedFactory)
                .Setup(x => x.GetInstance(typeof(IFactory)))
                .Returns(() => factoryFactory?.Invoke(mockedFactory));

            var logger = new ProfilingLogger(Mock.Of<ILogger>(), Mock.Of<IProfiler>());
            var typeLoader = new TypeLoader(Mock.Of<IAppPolicyCache>(), "", logger);
            var composition = new Composition(mockedRegister, typeLoader, logger, Mock.Of<IRuntimeState>());

            // create the factory, ensure it is the mocked factory
            var factory = composition.CreateFactory();
            Assert.AreSame(mockedFactory, factory);

            // ensure we can get an IFactory instance,
            // meaning that it has been properly registered

            var resolved = factory.GetInstance<IFactory>();
            Assert.IsNotNull(resolved);
            Assert.AreSame(factory, resolved);
        }
    }
}

