public interface IDocument
{
    string Name { get; }
    string Content { get; }
}

public struct Match
{
    public string Word { get; }
    public int Position { get; }

    public Match(string word, int position)
    {
        Word = word;
        Position = position;
    }

    public override string ToString()
    {
        return $"Word: {Word}, Position: {Position}";
    }
}

public struct Relevance
{
    public double Score { get; }

    public Relevance(double score)
    {
        Score = score;
    }

    public override string ToString()
    {
        return $"Relevance Score: {Score}";
    }
}

public class SearchResult
{
    private IDocument document;
    private ObservableCollection<Match> matches;
    private Relevance relevance;

    public SearchResult(IDocument document)
    {
        if (document == null)
        {
            throw new ArgumentNullException(nameof(document), "Document cannot be null.");
        }

        this.document = document;
        this.matches = new ObservableCollection<Match>();
        this.relevance = new Relevance(0.0);
    }

    public IDocument Document => document;

    public ReadOnlyCollection<Match> Matches => new ReadOnlyCollection<Match>(matches);

    public Relevance Relevance => relevance;

    public void AddMatch(Match match)
    {
        matches.Add(match);
    }

    public void SetRelevance(double score)
    {
        relevance = new Relevance(score);
    }

    public override string ToString()
    {
        StringBuilder sb = new StringBuilder();
        sb.AppendLine($"Document: {document.Name}");
        sb.AppendLine($"Number of Matches: {matches.Count}");
        sb.AppendLine($"Relevance: {relevance}");
        sb.AppendLine("Matches:");
        foreach (var match in matches)
        {
            sb.AppendLine($"  {match}");
        }
        return sb.ToString();
    }
}

using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using ServiceStack.Text;

public class CsvScriptBlock : BaseScriptBlock
{
    public async Task ExecuteAsync(string blockBody, ScriptScopeContext context)
    {
        var name = ParseVarName(blockBody);
        var csvContent = ExtractCsvContent(blockBody);
        var csvList = await ParseCsvAsync(csvContent);
        context.SetVariable(name, csvList);
    }

    private string ParseVarName(string blockBody)
    {
        // Extract the variable name from the block body
        var lines = blockBody.Split(new[] { '\n' }, 2);
        return lines[0].Trim();
    }

    private string ExtractCsvContent(string blockBody)
    {
        // Return the csv content after the variable name
        var lines = blockBody.Split(new[] { '\n' }, 2);
        return lines.Length > 1 ? lines[1].Trim() : string.Empty;
    }

    private async Task<List<Dictionary<string, object>>> ParseCsvAsync(string csvContent)
    {
        return await Task.Run(() =>
        {
            var csvRecords = new List<Dictionary<string, object>>();
            using (var reader = new System.IO.StringReader(csvContent))
            {
                var csv = CsvReader.Deserialize<Dictionary<string, object>>(reader);
                foreach (var record in csv)
                {
                    csvRecords.Add(record);
                }
            }
            return csvRecords;
        });
    }
}

public class ScriptScopeContext
{
    private readonly Dictionary<string, object> _variables = new Dictionary<string, object>();

    public void SetVariable(string name, object value)
    {
        _variables[name] = value;
    }

    public object GetVariable(string name)
    {
        _variables.TryGetValue(name, out var value);
        return value;
    }
}

public abstract class BaseScriptBlock
{
    // Base functionality for script blocks can be defined here
}

