{
    public static async Task Main(string[] args)
    {
        var context = new ScriptScopeContext();
        var csvBlock = new CsvScriptBlock();

        string blockBody = "csvData\nname,age\nJohn,30\nJane,25";
        await csvBlock.ExecuteAsync(blockBody, context);

        var result = context.GetVariable("csvData") as List<Dictionary<string, object>>;
        foreach (var record in result)
        {
            Console.WriteLine(string.Join(", ", record));
        }
    }
}

