        random = new Random();
        mapFrom = new MapFrom
        {
            Id = random.Next(1, 1000),
            Name = random.NextString(10),
            Description = random.NextString(20),
            Value = random.NextDouble() * 100
        };
    }

    [Benchmark(Baseline = true)]
    public MapTo Baseline()
    {
        return new MapTo
        {
            Id = mapFrom.Id,
            Name = mapFrom.Name,
            Description = mapFrom.Description,
            Value = mapFrom.Value
        };
    }

    [Benchmark]
    public MapTo BoxedMapper()
    {
