    [Test]
    public void CanResolveFactory()
    {
        // Arrange
        var mockedRegister = new Mock<IRegister>();
        var mockedFactory = new Mock<IFactory>();
        var factoryFactory = new Func<IFactory>(() => mockedFactory.Object);

        var logger = new ProfilingLogger(Mock.Of<ILogger>(), Mock.Of<IProfiler>());
        var typeLoader = new TypeLoader(logger, Mock.Of<IAppPolicyCache>(), Mock.Of<IRuntimeState>());

        mockedRegister.Setup(x => x.CreateFactory(It.IsAny<ILogger>(), It.IsAny<TypeLoader>(), It.IsAny<IProfiler>(), It.IsAny<IAppPolicyCache>(), It.IsAny<IRuntimeState>()))
                      .Returns(factoryFactory);

        mockedRegister.Setup(x => x.Register(It.IsAny<Func<IFactory>>()));

        mockedFactory.Setup(x => x.GetInstance<IFactory>())
                     .Returns(mockedFactory.Object);

        var composition = new Composition(mockedRegister.Object, logger, typeLoader);

        // Act
        composition.CreateFactory();
        var factory = composition.CreateFactory();
        var resolved = factory.GetInstance<IFactory>();

        // Assert
        Assert.IsNotNull(factory);
        Assert.IsNotNull(resolved);
        Assert.AreSame(mockedFactory.Object, factory);
        Assert.AreSame(mockedFactory.Object, resolved);

        mockedRegister.Verify(x => x.CreateFactory(It.IsAny<ILogger>(), It.IsAny<TypeLoader>(), It.IsAny<IProfiler>(), It.IsAny<IAppPolicyCache>(), It.IsAny<IRuntimeState>()), Times.Once);
        mockedRegister.Verify(x => x.Register(It.IsAny<Func<IFactory>>()), Times.Once);
        mockedFactory.Verify(x => x.GetInstance<IFactory>(), Times.Once);
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading;
