    [Activity(Label = "Grocery List", MainLauncher = true)]
    public class MainActivity : Activity
    {
        private Button itemsButton;
        private Button addItemButton;
        private Button aboutButton;
        private ItemRepository _repository;

        protected override void OnCreate(Bundle savedInstanceState)
        {
            base.OnCreate(savedInstanceState);
            SetContentView(Resource.Layout.activity_main);

            _repository = new ItemRepository();

            itemsButton = FindViewById<Button>(Resource.Id.button_view_items);
            addItemButton = FindViewById<Button>(Resource.Id.button_add_item);
