            itemsButton.Click += ViewItems_Click;
            addItemButton.Click += AddItem_Click;
            aboutButton.Click += About_Click;
        }

        private void ViewItems_Click(object sender, System.EventArgs e)
        {
            var intent = new Intent(this, typeof(ViewItemsActivity));
            StartActivity(intent);
        }

        private void AddItem_Click(object sender, System.EventArgs e)
        {
            var intent = new Intent(this, typeof(AddItemActivity));
            StartActivityForResult(intent, 100);
        }

        private void About_Click(object sender, System.EventArgs e)
        {
            var intent = new Intent(this, typeof(AboutActivity));
            StartActivity(intent);
        }

        protected override void OnActivityResult(int requestCode, Result resultCode, Intent data)
        {
            base.OnActivityResult(requestCode, resultCode, data);
