            {
                // Handle the result from AddItemActivity
                var itemName = data.GetStringExtra("itemName");
                if (!string.IsNullOrEmpty(itemName))
                {
                    _repository.AddItem(itemName);
                    Toast.MakeText(this, "Item added: " + itemName, ToastLength.Short).Show();
