namespace MvcApplication.Filters
{
    [AttributeUsage(AttributeTargets.Class | AttributeTargets.Method, AllowMultiple = false, Inherited = true)]
    public sealed class InitializeSimpleMembershipAttribute : ActionFilterAttribute
    {
        private static SimpleMembershipInitializer _initializer;
        private static object _initializerLock = new object();
        private static bool _isInitialized;

        public override void OnActionExecuting(ActionExecutingContext filterContext)
        {
            // Ensure ASP.NET Simple Membership is initialized only once per app start.
            LazyInitializer.EnsureInitialized(ref _initializer, ref _isInitialized, ref _initializerLock);
            base.OnActionExecuting(filterContext);
        }

        private class SimpleMembershipInitializer
        {
            public SimpleMembershipInitializer()
            {
                try
                {
                    // Disable Entity Framework database initialization
                    Database.SetInitializer<UsersContext>(null);

                    using (var context = new UsersContext())
                    {
                        if (!context.Database.Exists())
                        {
                            // Create the Simple Membership database without Entity Framework migration schema
                            ((IObjectContextAdapter)context).ObjectContext.CreateDatabase();
                        }
                    }

                    // Initialize the membership system
                    WebSecurity.InitializeDatabaseConnection(
                        "DefaultConnection",       // connection string name
                        "UserProfile",             // User table name
                        "UserId",                  // User ID column
                        "UserName",                // User name column
                        autoCreateTables: true);   // Create tables automatically if they do not exist
                }
                catch (Exception ex)
                {
                    throw new InvalidOperationException("The ASP.NET Simple Membership database could not be initialized. " +
                        "For more information, please see http://go.microsoft.com/fwlink/?LinkId=256588", ex);
                }
            }
        }
    }

