public class ClientData
{
    public HttpRequest req;
    public ClientState state;
    public int skip;
    public int read;
    public int headerskip;
    public IPEndPoint clientAddress;

    public ClientData(ClientInfo clientInfo)
    {
        req = new HttpRequest();
        state = ClientState.Receive;
        skip = 0;
        read = 0;
        headerskip = 0;

        if (clientInfo != null && clientInfo.TcpClient != null &&
            clientInfo.TcpClient.Client != null &&
            clientInfo.TcpClient.Client.RemoteEndPoint is IPEndPoint)
        {
            clientAddress = (IPEndPoint)clientInfo.TcpClient.Client.RemoteEndPoint;
        }
        else
        {
            clientAddress = null;
        }
    }
