namespace MimeTypeUtilities
{
    // This static class contains extension methods for the ContentType class.
    public static class ContentTypeExtensions
    {
        /// <summary>
        /// Extracts and returns the primary media type (main type) from the ContentType.
        /// </summary>
        /// <param name="contentType">The ContentType instance to extend.</param>
        /// <returns>The major media type as a string, or an empty string if unavailable.</returns>
        public static string GetMediaType(this ContentType contentType)
        {
            if (contentType == null)
            {
                throw new ArgumentNullException(nameof(contentType));
            }

            // Split the media type at the '/' delimiter.
            string[] parts = contentType.MediaType.Split(new char[] { '/' }, StringSplitOptions.RemoveEmptyEntries);
            if (parts.Length > 0)
            {
                return parts[0];
            }
            return string.Empty;
        }

        /// <summary>
        /// Extracts and returns the media subtype from the ContentType.
        /// </summary>
        /// <param name="contentType">The ContentType instance to extend.</param>
        /// <returns>The media subtype as a string, or an empty string if unavailable.</returns>
        public static string GetMediaSubType(this ContentType contentType)
        {
            if (contentType == null)
            {
                throw new ArgumentNullException(nameof(contentType));
            }

            // Split the media type string into two parts, expecting format "type/subtype".
            string[] parts = contentType.MediaType.Split(new char[] { '/' }, StringSplitOptions.RemoveEmptyEntries);
            if (parts.Length > 1)
            {
                return parts[1];
            }
            return string.Empty;
        }
    }

