namespace SqlTableValuedParameterDemo
{
    // Abstract generic class to transform .NET values into SQL Server records.
    public abstract class TableValuedParameter<T> : IEnumerable<SqlDataRecord>
    {
        private readonly IEnumerable<T> _items;

        protected TableValuedParameter(IEnumerable<T> items)
        {
            Contract.Requires(items != null);
            _items = items;
        }

        // Abstract method that converts an item of type T into a SqlDataRecord.
        public abstract SqlDataRecord Transform(T item);

        // Iterator with lazy evaluation that yields SQL Data Records.
        public IEnumerator<SqlDataRecord> GetEnumerator()
        {
            foreach (T item in _items)
            {
                yield return Transform(item);
            }
        }

        IEnumerator IEnumerable.GetEnumerator()
        {
            return GetEnumerator();
        }
    }

    // Concrete implementation for a collection of integers.
    public class IntTableValuedParameter : TableValuedParameter<int>
    {
        public IntTableValuedParameter(IEnumerable<int> items)
            : base(items)
        {
        }

        // Transform each integer into a SqlDataRecord with one column named "Value".
        public override SqlDataRecord Transform(int item)
        {
            SqlMetaData[] metaData = new SqlMetaData[]
            {
                new SqlMetaData("Value", System.Data.SqlDbType.Int)
            };

            SqlDataRecord record = new SqlDataRecord(metaData);
            record.SetInt32(0, item);
            return record;
        }
    }

    // Example usage in a console application.
    public class Validator
    {
        public static void Main(string[] args)
        {
            // Create a list of integers.
            List<int> numbers = Enumerable.Range(1, 10).ToList();

            // Instantiate the concrete implementation.
            IntTableValuedParameter tvp = new IntTableValuedParameter(numbers);

            // Iterate over each SqlDataRecord and display its contents.
            foreach (SqlDataRecord record in tvp)
            {
                Console.WriteLine("SQL Record Value: " + record.GetInt32(0));
            }
        }
    }
}

