    {
        // Get the syntax tree from the process
        var syntacticTree = process.GetSolution().GetPsiServices().GetAllFiles();
        foreach (var file in syntacticTree)
        {
            foreach (var declaration in file.GetDeclarations<IClassDeclaration>())
            {
                CheckForNullabilityIssues(declaration, result);
            }
        }
    }

    private void CheckForNullabilityIssues(IClassDeclaration declaration, IDaemonStageResult result)
    {
        var members = declaration.GetMembers();
