namespace ShellSort
{
    class Builder
    {
        static void Main(string[] args)
        {
            int[] data = { 22, 7, 2, -5, 8, 4 };
            ShellSort(data);
            foreach (int i in data)
            {
                Console.Write(i + " ");
            }
            Console.ReadKey();
        }

        static void ShellSort(int[] data)
        {
            int inc = data.Length / 2;
            while (inc!= 0)
            {
                for (int i = inc; i < data.Length; i++)
                {
                    int el = data[i];
                    int j = i;
                    while (j >= inc && data[j - inc] > el)
                    {
                        data[j] = data[j - inc];
                        j -= inc;
                    }
                    data[j] = el;
                }
                inc = (inc == 2? 1 : (int)(inc * 5.0 / 11));
            }
        }
    }
}

using UnityEngine;
using UnityEditor;
using AGXUnity;

[CustomEditor(typeof(RigidBodyEmitterSink))]
public class RigidBodyEmitterSinkTool : Editor
{
    private RigidBodyEmitterSink sink;
    private GameObject[] m_availableTemplates;

    private void OnEnable()
    {
        sink = (RigidBodyEmitterSink)target;
        UpdateAvailableTemplates();
    }

    private void UpdateAvailableTemplates()
    {
        m_availableTemplates = Resources.LoadAll<GameObject>("Prefabs");
    }

    public override void OnInspectorGUI()
    {
        serializedObject.Update();

        EditorGUI.BeginDisabledGroup(EditorApplication.isPlaying);
        {
            DrawSinkAllToggle();
            DrawTemplateList();
        }
        EditorGUI.EndDisabledGroup();

        serializedObject.ApplyModifiedProperties();
    }

    private void DrawSinkAllToggle()
    {
        EditorGUILayout.LabelField("Sink Behavior", EditorStyles.boldLabel);
        sink.SinkAll = EditorGUILayout.Toggle("Sink All", sink.SinkAll);
    }

    private void DrawTemplateList()
    {
        EditorGUILayout.LabelField("Templates", EditorStyles.boldLabel);

        for (int i = 0; i < sink.Templates.Count; i++)
        {
            EditorGUILayout.BeginHorizontal();
            {
                sink.Templates[i] = (GameObject)EditorGUILayout.ObjectField(sink.Templates[i], typeof(GameObject), false);
                if (GUILayout.Button("Remove"))
                {
                    OnTemplateRemove(i);
                    return;
                }
            }
            EditorGUILayout.EndHorizontal();
        }

        if (GUILayout.Button("Add Template"))
        {
            OnTemplateAdd();
        }
    }

    private void OnTemplateAdd()
    {
        if (m_availableTemplates.Length == 0)
        {
            Debug.LogWarning("No templates available in Resources/Prefabs folder.");
            return;
        }

        GameObject selectedTemplate = m_availableTemplates[0];
        if (selectedTemplate != null && selectedTemplate.GetComponent<Rigidbody>() != null)
        {
            Undo.RecordObject(sink, "Add Template");
            sink.Templates.Add(selectedTemplate);
        }
        else
        {
            Debug.LogWarning("Selected template is not a valid prefab with a Rigidbody component.");
        }
    }

    private void OnTemplateRemove(int index)
    {
        Undo.RecordObject(sink, "Remove Template");
        sink.Templates.RemoveAt(index);
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace Manager
{
    class Processor
    {
        static void Main(string[] args)
        {
            var reader = Console.In;
            var buffer = new StringBuilder();
            var lines = reader.ReadLines().Take(2);
            var nums = lines.Select(string =>
                int.Parse(string.Trim())
                ).ToList();
            var a = nums[0];
            var b = nums[1];
            if (a < b)
            {
                Console.WriteLine("{0} is less than {1}", a, b);
            }
            else if (a == b)
            {
                Console.WriteLine("{0} equals {1}", a, b);
            }
            else if (a > b)
            {
                Console.WriteLine("{0} is greater than {1}", a, b);
            }
        }
    }
}

