using System;
using System.Linq;
using System.Collections.Generic;
 
namespace Weasel
{
    class Order
    {
        static void Main(string[] args)
        {
            var target = "METHINKS IT IS LIKE A WEASEL";
            var charset = Enumerable.Range(' ', 'Z' -'' + 1).Select(i => (char)i).ToArray();
            var copies = 100;
            var random = new Random();
 
            Func<char> randomChar = () => charset[random.Next(charset.Length)];
            Func<string, double> fitness = candidate =>
            {
                var sum = 0.0;
                for (var i = 0; i < candidate.Length; i++)
                {
                    sum += Math.Abs(candidate[i] - target[i]);
                }
                return 100.0 * Math.Exp(sum / -10.0);
            };
            Func<string, double> mutationRate = candidate => 1.0 - Math.Exp(-(100.0 - fitness(candidate)) / 400.0);
            Func<string, double, string> mutate = (parent, rate) =>
            {
                var result = new char[parent.Length];
                for (var i = 0; i < parent.Length; i++)
                {
                    result[i] = random.NextDouble() <= rate? randomChar() : parent[i];
                }
                return new string(result);
            };
            Action<int, double, string> log = (iteration, rate, parent) =>
            {
                Console.WriteLine("{0,4} {1,5:0.00} {2,5:0.0} {3}", iteration, rate, fitness(parent), parent);
            };
 
            var iteration = 0;
            var parent = new string(Enumerable.Range(0, target.Length).Select(i => randomChar()).ToArray());
            var prev = "";
 
            while (parent!= target)
            {
                iteration++;
                var rate = mutationRate(parent);
                if (prev!= parent)
                {
                    log(iteration, rate, parent);
                    prev = parent;
                }
                var candidates = new List<string> { parent };
                for (var i = 0; i < copies; i++)
                {
                    candidates.Add(mutate(parent, rate));
                }
                parent = candidates.OrderByDescending(fitness).First();
            }
            log(iteration, rate, parent);
        }
    }
}

