public interface IResult
{
    bool IsSuccessful { get; }
    string Message { get; }
    Exception Error { get; }
}

public interface IApplicationInsights
{
    void TrackEvent(string eventName, IDictionary<string, string> properties);
    void TrackException(Exception exception);
}

public interface IExecution<T> where T : class
{
    List<IResult> Results { get; }
    bool IsRunning { get; }
    TimeSpan? Timeout { get; set; }

    IApplicationInsights InsightsTracker { get; }

    Task<IResult> ExecuteAsync(
        Func<Task<T>> operationFunc,
        Func<bool> preCheckFunc = null,
        CancellationToken? cancellationToken = null);

    void NotifyOfActivity(string activityDescription);
    void NotifyActivityFinished(bool success);

    IResult HandleResult(IResult result);
    void HandleUnhandledException(Exception ex);
    void HandleTimeout();

    event EventHandler<IResult> OperationCompleted;
    event EventHandler<string> ActivityStarted;
    event EventHandler ActivityEnded;
}

public class ExecutionManager<T> : IExecution<T> where T : class
{
    public List<IResult> Results { get; private set; } = new List<IResult>();
    public bool IsRunning { get; private set; }
    public TimeSpan? Timeout { get; set; }
    public IApplicationInsights InsightsTracker { get; }

    public event EventHandler<IResult> OperationCompleted;
    public event EventHandler<string> ActivityStarted;
    public event EventHandler ActivityEnded;

    public ExecutionManager(IApplicationInsights insightsTracker)
    {
        InsightsTracker = insightsTracker;
    }

    public async Task<IResult> ExecuteAsync(
        Func<Task<T>> operationFunc,
        Func<bool> preCheckFunc = null,
        CancellationToken? cancellationToken = null)
    {
        if (preCheckFunc != null && !preCheckFunc())
        {
            return new Result(false, "Pre-execution check failed");
        }

        try
        {
            IsRunning = true;
            var result = await operationFunc();
            var executionResult = new Result(true, "Operation completed successfully");
            Results.Add(executionResult);
            return executionResult;
        }
        catch (Exception ex)
        {
            HandleUnhandledException(ex);
            return new Result(false, ex.Message, ex);
        }
        finally
        {
            IsRunning = false;
        }
    }

    public void NotifyOfActivity(string activityDescription)
    {
        ActivityStarted?.Invoke(this, activityDescription);

