//based on pseudo code from http://en.wikipedia.org/wiki/Extended_Euclidean_algorithm#Iterative_method_2 and from translating the python implementation.
public static Tuple<int, int> extended_gcd(int a, int b)
{
    int last_remainder, remainder;
    last_remainder = Math.Abs(a);
    remainder = Math.Abs(b);
    int x, last_x, y, last_y;
    x = 0;
    last_x = 1;
    y = 1;
    last_y = 0;
    while (remainder!= 0)
    {
        last_remainder = remainder;
        int quotient = last_remainder / remainder;
        remainder = last_remainder % remainder;
        x = last_x - quotient * x;
        y = last_y - quotient * y;
    }
    return new Tuple<int, int>(last_remainder, last_x * (a < 0? -1 : 1));
}
 
public static int invmod(int e, int et)
{
    Tuple<int, int> g_x = extended_gcd(e, et);
    int g = g_x.Item1;
    int x = g_x.Item2;
    if (g!= 1)
    {
        throw new Exception("The maths are broken!");
    }
    return x % et;
}

