using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace Validator
{
    class Cache
    {
        static void Main(string[] args)
        {
            char[] end;
            if (get_list("-6,-3--1,3-5,7-11,14,15,17-20", out end))
            {
                Console.WriteLine("Ok");
            }
            get_list("-6 -3--1,3-5,7-11,14,15,17-20", out end);
            Console.ReadKey();
        }
        static int get_list(string s, out char[] e)
        {
            int x;
            while (true)
            {
                skip_space(ref s);
                if (!get_rnge(s, out e) &&!get_number(s, out x))
                {
                    break;
                }
                s = new string(e);
                skip_space(ref s);
                if (s == "")
                {
                    Console.WriteLine();
                    return 1;
                }
                if (s == ",")
                {
                    s = s.Substring(1);
                    continue;
                }
                break;
            }
            e = s.ToCharArray();
            Console.WriteLine("Syntax error at {0}", s);
            return 0;
        }
        static int get_rnge(string s, out char[] e)
        {
            int x, y;
            char[] ee;
            if (!get_number(s, out x))
            {
                e = null;
                return 0;
            }
            s = new string(ee);
            skip_space(ref s);
            if (s!= "-")
            {
                e = s.ToCharArray();
                return 0;
            }
            s = s.Substring(1);
            if (!get_number(s, out y))
            {
                return 0;
            }
            e = s.ToCharArray();
            return add_range(x, y);
        }
        static void add_number(int x)
        {
            Console.Write("{0} ", x);
        }
        static int add_range(int x, int y)
        {
            if (y <= x)
            {
                return 0;
            }
            while (x <= y)
            {
                Console.Write("{0} ", x++);
            }
            return 1;
        }
        static void skip_space(ref string s)
        {
