using Microsoft.BizTalk.Component;

public class CustomXmlReceivePipeline : ReceivePipeline
{
    public CustomXmlReceivePipeline()
    {
        Name = "Custom XML Receive Pipeline";
        Version = "1.0.0.0";

        Stages.Decode.AddComponent(new Base64DecoderComponent())
            .AddComponent(new FailedMessageRoutingEnablerComponent());

        Stages.Disassemble
            .AddComponent(new XmlDisassemblerComponent {
                DocumentSpecName = "MyCustomDocumentSpec",
                ValidateDocument = true
            })
            .AddComponent(new ContextPropertyExtractorComponent {
                PropertyExtractors = new[] {
                    new PropertyExtractor {
                        Property = "MessageTrackingID",
                        Type = PropertyExtractorType.Constant,
                        Value = Guid.NewGuid().ToString()
                    }
                }
            });

        Stages.ResolveParty
            .AddComponent(new PolicyRunnerComponent {
                PolicyName = "MessageValidationPolicy",
                TrackingMode = PolicyTrackingMode.Full
            })
            .AddComponent(new ActivityTrackerComponent {
                TrackingMode = ActivityTrackingMode.Detailed
            });

        AdditionalComponents = new IPipelineComponent[] {
            new XsltRunnerComponent {
                MapName = "MessageTransformMap",
                SourceDocumentType = "SourceSchema",
                TargetDocumentType = "TargetSchema"
            },
            new XmlTranslatorComponent {
                SourceLanguage = "en-US",
                TargetLanguage = "fr-FR"
            }
        };

        Configure();
    }

    private void Configure()
    {
        // Optional configuration method for dynamic pipeline setup
        if (Environment.GetEnvironmentVariable("EnableAdvancedTracking") == "true")
        {
            Stages.ResolveParty.AddComponent(
                new ExtendedTrackingComponent {
                    DetailLevel = TrackingDetailLevel.Verbose
                }
            );
        }
    }

    public override void Validate()
    {
        // Perform validation of pipeline components
        base.Validate();

        // Custom validation logic
        if (Stages.Disassemble.Components.Count == 0)
        {
            throw new InvalidOperationException("Disassemble stage must have at least one component");
        }
    }
