using System;
using System.Numerics;
 
namespace RosettaCode
{
    class IntegerSquareRoot
    {
        static BigInteger isqrt(BigInteger x)
        {
            if (x < BigInteger.Zero)
            {
                throw new ArgumentException("Argument cannot be negative");
            }
            BigInteger q = BigInteger.One;
            while (q <= x)
            {
                q <<= 2;
            }
            BigInteger z = x;
            BigInteger r = BigInteger.Zero;
            while (q > BigInteger.One)
            {
                q >>= 2;
                BigInteger t = z;
                t -= r;
                t -= q;
                r >>= 1;
                if (t >= BigInteger.Zero)
                {
                    z = t;
                    r += q;
                }
            }
            return r;
        }
 
        static void Main()
        {
            Console.WriteLine("The integer square root of integers from 0 to 65 are:");
            for (int i = 0; i <= 65; i++)
            {
                Console.Write("{0} ", isqrt(new BigInteger(i)));
            }
            Console.WriteLine();
 
            Console.WriteLine("The integer square roots of powers of 7 from 7^1 up to 7^73 are:");
            Console.WriteLine("power                                    7 ^ power                                                 integer square root");
            Console.WriteLine("----- --------------------------------------------------------------------------------- -----------------------------------------");
            BigInteger pow7 = new BigInteger(7);
            BigInteger bi49 = new BigInteger(49);
            for (int i = 1; i <= 73; i += 2)
            {
                Console.WriteLine("{0,2} %,84d %,41d", i, pow7, isqrt(pow7));
                pow7 *= bi49;
            }
        }
    }
}

