using System;
 
public class Library
{
    public static bool IsPrime(uint n)
    {
        if (n < 2)
        {
            return false;
        }
        if (n % 2 == 0)
        {
            return n == 2;
        }
        if (n % 3 == 0)
        {
            return n == 3;
        }
        uint p = 5;
        while (p * p <= n)
        {
            if (n % p == 0)
            {
                return false;
            }
            p += 2;
            if (n % p == 0)
            {
                return false;
            }
            p += 4;
        }
        return true;
    }
 
    public static bool IsLeftTruncatable(uint p)
    {
        uint n = 10;
        uint q = p;
        while (p > n)
        {
            if (!IsPrime(p % n) || q == p % n)
            {
                return false;
            }
            q = p % n;
            n *= 10;
        }
        return true;
    }
 
    public static bool IsRightTruncatable(uint p)
    {
        uint q = p / 10;
        while (q > 0)
        {
            if (!IsPrime(q))
            {
                return false;
            }
            q /= 10;
        }
        return true;
    }
 
    public static void Main()
    {
        uint limit = 1000000;
        uint largestLeft = 0;
        uint largestRight = 0;
        uint p = limit;
        while (p >= 2)
        {
            if (IsPrime(p) && IsLeftTruncatable(p))
            {
                largestLeft = p;
                break;
            }
            p -= 1;
        }
        Console.WriteLine("Largest left truncatable prime is {0}", largestLeft);
        p = limit;
        while (p >= 2)
        {
            if (IsPrime(p) && IsRightTruncatable(p))
            {
                largestRight = p;
                break;
            }
            p -= 1;
        }
        Console.WriteLine("Largest right truncatable prime is {0}", largestRight);
    }
}

