    /// <summary>
    /// Custom exception class to encapsulate and handle multiple exceptions.
    /// </summary>
    public class CompoundException : Exception
    {
        private readonly List<Exception> _innerExceptions;

        /// <summary>
        /// Initializes a new instance of the <see cref="CompoundException"/> class with a specified error message.
        /// </summary>
        /// <param name="message">The error message that explains the reason for the exception.</param>
        public CompoundException(string message)
            : base(message)
        {
            _innerExceptions = new List<Exception>();
        }

        /// <summary>
        /// Initializes a new instance of the <see cref="CompoundException"/> class with a specified error message and a reference to the inner exception that is the cause of this exception.
        /// </summary>
        /// <param name="message">The error message that explains the reason for the exception.</param>
        /// <param name="innerException">The exception that is the cause of the current exception, or a null reference if no inner exception is specified.</param>
        public CompoundException(string message, Exception innerException)
            : base(message, innerException)
        {
            _innerExceptions = new List<Exception>();
            if (innerException != null)
            {
                _innerExceptions.Add(innerException);
            }
        }

        /// <summary>
        /// Initializes a new instance of the <see cref="CompoundException"/> class with a reference to the inner exception that is the cause of this exception.
        /// </summary>
        /// <param name="innerException">The exception that is the cause of the current exception, or a null reference if no inner exception is specified.</param>
        public CompoundException(Exception innerException)
            : base(null, innerException)
        {
            _innerExceptions = new List<Exception>();
            if (innerException != null)
            {
                _innerExceptions.Add(innerException);
            }
        }

        /// <summary>
        /// Initializes a new instance of the <see cref="CompoundException"/> class with a specified error message and a list of inner exceptions.
        /// </summary>
        /// <param name="message">The error message that explains the reason for the exception.</param>

