    class Converter
    {
        static void Main(string[] args)
        {
            HashSet<int> a = new HashSet<int>();
            //TreeSet sorts on natural ordering (or an optional comparator)
            //other options: HashSet (hashcode)
            //               LinkedHashSet (insertion order)
            //               EnumSet (optimized for enum values)
            //others at: http://download.oracle.com/javase/7/docs/api/java/util/Set.html
            HashSet<int> b = new HashSet<int>();
            HashSet<int> c = new HashSet<int>();
            HashSet<int> d = new HashSet<int>();
 
            a.UnionWith(new int[] { 1, 2, 3, 4, 5 });
            b.UnionWith(new int[] { 2, 3, 4, 5, 6, 8 });
            c.UnionWith(new int[] { 2, 3, 4 });
            d.UnionWith(new int[] { 2, 3, 4 });
            Console.WriteLine("a: " + string.Join(",", a));
            Console.WriteLine("b: " + string.Join(",", b));
            Console.WriteLine("c: " + string.Join(",", c));
            Console.WriteLine("d: " + string.Join(",", d));
 
            Console.WriteLine("2 in a: " + a.Contains(2));
            Console.WriteLine("6 in a: " + a.Contains(6));
 
            HashSet<int> ab = new HashSet<int>();
            ab.UnionWith(a);
            ab.UnionWith(b);
            Console.WriteLine("a union b: " + string.Join(",", ab));
 
            HashSet<int> a_b = new HashSet<int>();
            a_b.UnionWith(a);
            a_b.ExceptWith(b);
            Console.WriteLine("a - b: " + string.Join(",", a_b));
 
            Console.WriteLine("c subset of a: " + a.IsSupersetOf(c));
            //use a.conatins() for single elements
 
            Console.WriteLine("c = d: " + c.SetEquals(d));
            Console.WriteLine("d = c: " + d.SetEquals(c));
 
            HashSet<int> aib = new HashSet<int>();
            aib.UnionWith(a);
            aib.IntersectWith(b);
            Console.WriteLine("a intersect b: " + string.Join(",", aib));
 
            Console.WriteLine("add 7 to a: " + a.Add(7));
            Console.WriteLine("add 2 to a again: " + a.Add(2));
 
            //other noteworthy things related to sets:
            HashSet<int> empty = new HashSet<int>(); //immutable empty set
            //empty.add(2);  would fail
            empty.IsEmpty; //test if a set is empty
            empty.Count;

