namespace Microsoft.Azure.Commands.HDInsight.JobDefinitions
{
    public abstract class AzureHDInsightJobDefinition
    {
        public IReadOnlyList<string> Arguments { get; }
        public IReadOnlyList<string> Files { get; }
        public string StatusFolder { get; }

        protected AzureHDInsightJobDefinition(
            IEnumerable<string> arguments = null,
            IEnumerable<string> files = null,
            string statusFolder = null)
        {
            var argsList = arguments != null ? new List<string>(arguments) : new List<string>();
            Arguments = new ReadOnlyCollection<string>(argsList);

            var filesList = files != null ? new List<string>(files) : new List<string>();
            Files = new ReadOnlyCollection<string>(filesList);

            StatusFolder = statusFolder ?? string.Empty;
        }

        protected void ValidateBaseParameters()
        {
            if (StatusFolder?.Trim() == string.Empty)
                throw new ArgumentException("Status directory must be specified");

            foreach (var arg in Arguments)
            {
                if (string.IsNullOrWhiteSpace(arg))
                    throw new ArgumentException("Invalid empty argument");
            }
        }

        public virtual Dictionary<string, object> ToJobConfiguration()
        {
            return new Dictionary<string, object>
            {
                { nameof(Arguments), new List<string>(Arguments) },
                { nameof(Files), new List<string>(Files) },
                { nameof(StatusFolder), StatusFolder }
            };
        }

        protected void AddStandardMetadata(Dictionary<string, string> metadata)
        {
            metadata["JobType"] = GetType().Name.Replace("JobDefinition", "");
            metadata["ArgumentCount"] = Arguments.Count.ToString();
            metadata["FileCount"] = Files.Count.ToString();
        }
    }
}

