public class GravitySwitch : MonoBehaviour
{
    public float GravityStrength = 9.8f;
    public float momentum = 0f;
    public bool click = false;
    public bool GameState = true;
    public bool GravityState = true; // true for down, false for up
    public GameObject Explosion;
    public GameObject Jets;
    public GameObject[] CharacterPieces;
    public Vector3 hitposition;
    public GameObject EndScreen;
    public int BestScore;

    void Start()
    {
        BestScore = PlayerPrefs.GetInt("BestScore", 0);
        Time.timeScale = 1;
    }

    void Update()
    {
        if (GameState)
        {
            Gravity();
            Controls();
        }
        else
        {
            EndScreen.transform.position = new Vector3(hitposition.x, hitposition.y, -10);
            EndScreen.SetActive(true);
        }
    }

    void Gravity()
    {
        if (!click)
        {
            if (GravityState)
            {
                transform.Translate(Vector3.down * GravityStrength * Time.deltaTime);
            }
            else
            {
                transform.Translate(Vector3.up * GravityStrength * Time.deltaTime);
            }
        }
        else
        {
            if (GravityState)
            {
                transform.Translate(Vector3.down * (GravityStrength + momentum) * Time.deltaTime);
                momentum += 0.1f;
            }
            else
            {
                transform.Translate(Vector3.up * (GravityStrength + momentum) * Time.deltaTime);
                momentum += 0.1f;
            }
        }
    }

    void Controls()
    {
        if (Input.GetKeyDown(KeyCode.Space) || Input.GetMouseButtonDown(0))
        {
            if (!click)
            {
                click = true;
                momentum = 0f;
                Jets.SetActive(true);
            }
            else
            {
                GravityState = !GravityState;
                momentum = 0f;
            }
        }
    }

    void OnCollisionEnter2D(Collision2D other)
    {
        if (other.gameObject.CompareTag("Obstacle"))
        {
            GameState = false;
            Time.timeScale = 0;
            Instantiate(Explosion, transform.position, Quaternion.identity);
            foreach (GameObject piece in CharacterPieces)
            {
                piece.SetActive(false);
            }
            int currentScore = PlayerPrefs.GetInt("CurrentScore", 0);
            if (currentScore > BestScore)
            {
                BestScore = currentScore;

