namespace Ds3.Parsers
{
    internal class GetDataReplicationRulesSpectraS3ResponseParser : IParser<GetDataReplicationRulesSpectraS3Response>
    {
        public GetDataReplicationRulesSpectraS3Response Parse(GetDataReplicationRulesSpectraS3Request request, IWebResponse response)
        {
            using (response)
            {
                CheckStatusCode(response);

                var xmlDoc = XDocument.Load(response.GetResponseStream());
                var replicationRules = xmlDoc.Root
                    .Elements("DataReplicationRule")
                    .Select(ParseDataReplicationRule)
                    .ToList();

                var pagination = ParsePagination(response);
                var totalResults = ParseTotalResults(response);

                return new GetDataReplicationRulesSpectraS3Response(replicationRules, pagination, totalResults);
            }
        }

        private void CheckStatusCode(IWebResponse response)
        {
            if (response.StatusCode != HttpStatusCode.OK)
            {
                throw new Ds3RequestException($"Unexpected status code: {response.StatusCode}", response);
            }
        }

        private DataReplicationRule ParseDataReplicationRule(XElement element)
        {
            return new DataReplicationRule
            {
                RuleId = element.Element("RuleId")?.Value,
                SourceId = element.Element("SourceId")?.Value,
                DataPolicyId = element.Element("DataPolicyId")?.Value,
                TargetId = element.Element("TargetId")?.Value,
                Priority = int.Parse(element.Element("Priority")?.Value ?? "0"),
                State = element.Element("State")?.Value
            };
        }

        private Pagination ParsePagination(IWebResponse response)
        {
            var pagination = new Pagination
            {
                Truncated = bool.Parse(response.Headers.Get("truncated") ?? "false"),
                NextMarker = response.Headers.Get("next_marker"),
                PreviousMarker = response.Headers.Get("previous_marker")
            };
            return pagination;
        }

        private int ParseTotalResults(IWebResponse response)
        {
            return int.Parse(response.Headers.Get("total_results") ?? "0");
        }
    }
}

