using System;

namespace LiteDB
{
    public class IndexOptions : IEquatable<IndexOptions>
    {
        public bool Unique { get; set; }
        public bool IgnoreCase { get; set; }
        public bool TrimWhitespace { get; set; }
        public bool EmptyStringToNull { get; set; }
        public bool RemoveAccents { get; set; }

        public IndexOptions()
        {
            Unique = false;
            IgnoreCase = false;
            TrimWhitespace = false;
            EmptyStringToNull = false;
            RemoveAccents = false;
        }

        public IndexOptions(bool unique, bool ignoreCase, bool trimWhitespace, bool emptyStringToNull, bool removeAccents)
        {
            Unique = unique;
            IgnoreCase = ignoreCase;
            TrimWhitespace = trimWhitespace;
            EmptyStringToNull = emptyStringToNull;
            RemoveAccents = removeAccents;
        }

        public bool Equals(IndexOptions other)
        {
            if (other == null) return false;
            return Unique == other.Unique &&
                   IgnoreCase == other.IgnoreCase &&
                   TrimWhitespace == other.TrimWhitespace &&
                   EmptyStringToNull == other.EmptyStringToNull &&
                   RemoveAccents == other.RemoveAccents;
        }

        public override bool Equals(object obj)
        {
            if (obj is IndexOptions options)
            {
                return Equals(options);
            }
            return false;
        }

        public override int GetHashCode()
        {
            unchecked
            {
                int hash = 17;
                hash = hash * 23 + Unique.GetHashCode();
                hash = hash * 23 + IgnoreCase.GetHashCode();
                hash = hash * 23 + TrimWhitespace.GetHashCode();
                hash = hash * 23 + EmptyStringToNull.GetHashCode();
                hash = hash * 23 + RemoveAccents.GetHashCode();
                return hash;
            }
        }

        public IndexOptions Clone()
        {
            return new IndexOptions
            {
                Unique = this.Unique,
                IgnoreCase = this.IgnoreCase,
                TrimWhitespace = this.TrimWhitespace,
                EmptyStringToNull = this.EmptyStringToNull,
                RemoveAccents = this.RemoveAccents
            };
        }

        public override string ToString()
        {
            return $"IndexOptions[Unique={Unique}, IgnoreCase={IgnoreCase}, TrimWhitespace={TrimWhitespace}, EmptyStringToNull={EmptyStringToNull}, RemoveAccents={RemoveAccents}]";

