using UnityEngine;
using System.Collections;

public class Character : Moddable
{
    public float Speed = 5.0f;
    private SpriteRenderer TheSpriteRenderer;
    private Sprite TheSprite;
    private WWW TheSpriteWWW;

    void Start()
    {
        TheSpriteRenderer = AddComponent<SpriteRenderer>();

        #if MODMANAGER_LOADS_FROM_MEMORY
                TheSprite = Sprite.Create(TheMod.Texture, new Rect(0, 0, TheMod.Texture.width, TheMod.Texture.height), new Vector2(0.5f, 0.5f));
                TheSpriteRenderer.sprite = TheSprite;
        #else
                StartCoroutine(LoadSprite());
        #endif
    }

    IEnumerator LoadSprite()
    {
        TheSpriteWWW = new WWW("file:///" + TheMod.Path + "/character.png");
        yield return TheSpriteWWW;

        if (!string.IsNullOrEmpty(TheSpriteWWW.error))
        {
            Debug.LogError("Failed to load sprite: " + TheSpriteWWW.error);
        }
        else
        {
            TheSprite = Sprite.Create(TheSpriteWWW.texture, new Rect(0, 0, TheSpriteWWW.texture.width, TheSpriteWWW.texture.height), new Vector2(0.5f, 0.5f));
            TheSpriteRenderer.sprite = TheSprite;
        }
    }
    void Update()
    {
        float moveX = 0f;
        float moveY = 0f;

        if (GetKey(KeyCode.UpArrow))
        {
            moveY = 1f;
        }
        if (GetKey(KeyCode.DownArrow))
        {
            moveY = -1f;
        }
        if (GetKey(KeyCode.LeftArrow))
        {
            moveX = -1f;
        }
        if (GetKey(KeyCode.RightArrow))
        {
            moveX = 1f;
        }
        transform.position += new Vector3(moveX, moveY, 0) * Speed * Time.deltaTime;
    }
    public T AddComponent<T>() where T : Component
    {
        return gameObject.AddComponent<T>();
    }

    public bool GetKey(KeyCode code)
    {
        return Input.GetKey(code);
    }
}

