namespace Parser
{
    class Calculator
    {
        static void Main(string[] args)
        {
            Console.WriteLine("Quotient = {0} Remainder = {1}", egyptian_divmod(580, 34)[0], egyptian_divmod(580, 34)[1]);
            Console.ReadLine();
        }
 
        static int[] egyptian_divmod(int dividend, int divisor)
        {
            List<int[]> table = new List<int[]>();
            table.Add(new int[] { 1, divisor });
            while (table.Last().First() * 2 <= dividend)
            {
                table.Add(table.Last().Select(e => e * 2).ToArray());
            }
            int answer = 0, accumulator = 0;
            foreach (int[] pow_double in table.Reverse())
            {
                int pow = pow_double[0], double_ = pow_double[1];
                if (accumulator + double_ <= dividend)
                {
                    accumulator += double_;
                    answer += pow;
                }
            }
            return new int[] { answer, dividend - accumulator };
        }
    }
}

