namespace SymbolManagement
{
    // Class responsible for symbol management across nested scopes.
    public class SymbolTable
    {
        // Global symbols container and corresponding indexing counter.
        private Dictionary<string, int> _globalSymbols = new Dictionary<string, int>();
        private int _globalCount = 0;

        // Stack representing nested local scopes.
        private Stack<Scope> _scopeStack = new Stack<Scope>();

        // Helper class representing an individual scope that stores symbols.
        private class Scope
        {
            public Dictionary<string, int> Symbols { get; private set; }
            public int LocalCount { get; set; }

            public Scope()
            {
                Symbols = new Dictionary<string, int>();
                LocalCount = 0;
            }
        }

        // Constructor initializes the symbol table with an initial local scope.
        public SymbolTable()
        {
            EnterScope();
        }

        // Enters a new local scope by pushing a new Scope object onto the stack.
        public void EnterScope()
        {
            _scopeStack.Push(new Scope());
        }

        // Exits the current local scope by popping the top Scope off the stack.
        public void ExitScope()
        {
            if (_scopeStack.Count > 0)
            {
                _scopeStack.Pop();
            }
            else
            {
                throw new InvalidOperationException("No scope available to exit.");
            }
        }

        // Adds a symbol to the current local scope if it does not already exist.
        public int AddSymbol(string name)
        {
            Scope current = _scopeStack.Peek();
            if (current.Symbols.ContainsKey(name))
            {
                return current.Symbols[name];
            }
            else
            {
                int index = current.LocalCount;
                current.Symbols[name] = index;
                current.LocalCount++;
                return index;
            }
        }

        // Adds a symbol into the global scope; lazy-add if symbol is absent.
        public int AddGlobalSymbol(string name)
        {
            if (_globalSymbols.ContainsKey(name))
            {
                return _globalSymbols[name];
            }
            else
            {
                int index = _globalCount;
                _globalSymbols[name] = index;
                _globalCount++;
                return index;
            }
        }

