namespace ConcurrentBenchmarking
{
    // This benchmark measures the scalability of a simple computational operation
    // when executed concurrently across multiple threads.
    [MemoryDiagnoser]
    public class ConcurrentBenchmark
    {
        // Total number of iterations per thread to amortize overhead.
        private const int OuterIterations = 1000000;
        // Number of operations performed in the inner loop.
        private const int InnerIterations = 100;

        // Benchmark method that initiates concurrent execution.
        [Benchmark]
        public long RunBenchmark()
        {
            // Determine the number of available processor cores.
            int threadCount = Environment.ProcessorCount;
            // Create tasks to perform computation concurrently.
            Task<long>[] tasks = new Task<long>[threadCount];

            // Start each task with an independent workload.
            for (int i = 0; i < threadCount; i++)
            {
                tasks[i] = Task.Run(() => ComputeWorkload());
            }

            // Wait for all tasks to complete.
            Task.WaitAll(tasks);

            // Aggregate the results from all threads.
            long aggregateResult = 0;
            for (int i = 0; i < threadCount; i++)
            {
                aggregateResult += tasks[i].Result;
            }

            return aggregateResult;
        }

        // Core computational workload executed by each thread.
        private long ComputeWorkload()
        {
            long localSum = 0;

            // Outer loop to increase total iterations.
            for (int i = 0; i < OuterIterations; i++)
            {
                int intermediate = i;

                // Inner loop performing bitwise XOR operations.
                for (int j = 0; j < InnerIterations; j++)
                {
                    intermediate ^= j;
                }

                // Accumulate the result to avoid optimization removal.
                localSum += intermediate;
            }
            return localSum;
        }
    }

    // Entry point for running the benchmark.
    public class Generator
    {
        public static void Main(string[] args)
        {
            // Runs the benchmark harness for the ConcurrentBenchmark class.
            var summary = BenchmarkRunner.Run<ConcurrentBenchmark>();

