using System.Web.Http.Dependencies;
using Microsoft.Practices.Unity;

public class UnityResolverWebApi : IDependencyResolver
{
    private readonly IUnityContainer _container;
    private readonly object _disposeLock = new object();
    private bool _disposed = false;

    public UnityResolverWebApi(IUnityContainer container)
    {
        _container = container ?? throw new ArgumentNullException(nameof(container));
    }

    public object GetService(Type serviceType)
    {
        if (serviceType == null) return null;

        try
        {
            return _container.Resolve(serviceType);
        }
        catch (ResolutionFailedException)
        {
            return null;
        }
    }

    public IEnumerable<object> GetServices(Type serviceType)
    {
        if (serviceType == null) return Enumerable.Empty<object>();

        try
        {
            return _container.ResolveAll(serviceType);
        }
        catch (ResolutionFailedException)
        {
            return Enumerable.Empty<object>();
        }
    }

    public IDependencyScope BeginScope()
    {
        if (_disposed)
            throw new ObjectDisposedException("UnityResolverWebApi");

        IUnityContainer childContainer = _container.CreateChildContainer();
        return new UnityResolverWebApi(childContainer);
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    protected virtual void Dispose(bool disposing)
    {
        lock (_disposeLock)
        {
            if (_disposed) return;

            if (disposing)
            {
                _container?.Dispose();
            }

            _disposed = true;
        }
    }

    ~UnityResolverWebApi()
    {
        Dispose(false);
    }
}

