namespace SharpPcap.WinpkFilter
{
    /// <summary>
    /// Used to set the adapter flags.
    /// </summary>
    [Flags]
    public enum AdapterModes : uint
    {
        /// <summary>
        /// No flags.
        /// </summary>
        None = 0x00000000,

        /// <summary>
        /// Receive packets sent by MSTCP to network interface.
        /// The original packet is dropped.
        /// </summary>
        SentTunnel = 0x00000001,

        /// <summary>
        /// Receive packets sent from network interface to MSTCP.
        /// The original packet is dropped.
        /// </summary>
        RecvTunnel = 0x00000002,

        /// <summary>
        /// Receive packets sent from and to MSTCP and network interface.
        /// The original packet is dropped.
        /// </summary>
        Tunnel = SentTunnel | RecvTunnel,

        /// <summary>
        /// Receive packets sent by MSTCP to network interface.
        /// The original packet is still delivered to the network.
        /// </summary>
        SentListen = 0x00000004,

        /// <summary>
        /// Receive packets sent from network interface to MSTCP
        /// The original packet is still delivered to the network.
        /// </summary>
        RecvListen = 0x00000008,

        /// <summary>
        /// Receive packets sent from and to MSTCP and network interface.
        /// The original packet is dropped.
        /// </summary>
        Listen = SentListen | RecvListen,

        /// <summary>
        /// In promiscuous mode TCP/IP stack receives all.
        /// </summary>
        FilterDirect = 0x00000010,

        /// <summary>
        /// Passes loopback packet for processing.
        /// </summary>
        LoopbackFilter = 0x00000020,

        /// <summary>
        /// Silently drop loopback packets.
        /// </summary>
        LoopbackBlock = 0x00000040
    }

}

using System;
using System.Collections.Generic;
using System.Linq;
 
public static class MultiCombinations
{
    private static void Main()
    {
        var set = new List<string> { "iced", "jam", "plain" };
        var combinations = GenerateCombinations(set, 2);
 
        foreach (var combination in combinations)
        {
            string combinationStr = string.Join(" ", combination);
            Console.WriteLine(combinationStr);
        }
 
        var donuts = Enumerable.Range(1, 10).ToList();
 
        int donutsCombinationsNumber = GenerateCombinations(donuts, 3).Count;
 
        Console.WriteLine("{0} ways to order 3 donuts given 10 types", donutsCombinationsNumber);
    }
 
    private static List<List<T>> GenerateCombinations<T>(List<T> combinationList, int k)
    {
        var combinations = new List<List<T>>();
 
        if (k == 0)
        {
            var emptyCombination = new List<T>();
            combinations.Add(emptyCombination);
 
            return combinations;
        }
 
        if (combinationList.Count == 0)
        {
            return combinations;
        }
 
        T head = combinationList[0];
        var copiedCombinationList = new List<T>(combinationList);
 
        List<List<T>> subcombinations = GenerateCombinations(copiedCombinationList, k - 1);
 
        foreach (var subcombination in subcombinations)
        {
            subcombination.Insert(0, head);
            combinations.Add(subcombination);
        }
 
        combinationList.RemoveAt(0);
        combinations.AddRange(GenerateCombinations(combinationList, k));
 
        return combinations;
    }
}

using UnityEngine;
using System.Collections;

public class uScriptAct_LoadPhysicMaterial : uScriptLogic
{
    public string name;
    public PhysicMaterial asset;

    public void In()
    {
        if (string.IsNullOrEmpty(name))
        {
            Debug.LogWarning("PhysicMaterial path is empty");
            asset = null;
            return;
        }

        asset = Resources.Load<PhysicMaterial>(name);

        if (null == asset)
        {
            Debug.LogWarning($"Failed to load PhysicMaterial at path: {name}");
        }
    }

#if UNITY_EDITOR
    public void EditorDragDrop(Hashtable inputParams)
    {
        UnityEngine.Object draggedObject = inputParams["DraggedObject"] as UnityEngine.Object;
        if (draggedObject is PhysicMaterial)
        {
            string fullPath = UnityEditor.AssetDatabase.GetAssetPath(draggedObject);
            int resourcesIndex = fullPath.IndexOf("Resources/");

            if (resourcesIndex != -1)
            {
                string resourcePath = fullPath.Substring(resourcesIndex + "Resources/".Length);
                resourcePath = System.IO.Path.Combine(
                    System.IO.Path.GetDirectoryName(resourcePath),
                    System.IO.Path.GetFileNameWithoutExtension(resourcePath)
                ).Replace('\\', '/');

                name = resourcePath;
            }
            else
            {
                Debug.LogWarning("PhysicMaterial must be within a Resources folder");
            }
        }
    }
#endif
}

