namespace Discovery
{
    [Fx.Tag.XamlVisible(false)]
    public sealed class FindResponse
    {
        private readonly List<EndpointDiscoveryMetadata> endpoints;
        private readonly Dictionary<string, DiscoveryMessageSequence> messageSequenceTable;

        public ReadOnlyCollection<EndpointDiscoveryMetadata> DiscoveredEndpoints { get; }

        internal FindResponse()
        {
            endpoints = new List<EndpointDiscoveryMetadata>();
            messageSequenceTable = new Dictionary<string, DiscoveryMessageSequence>(StringComparer.Ordinal);
            DiscoveredEndpoints = new ReadOnlyCollection<EndpointDiscoveryMetadata>(endpoints);
        }

        internal void AddDiscoveredEndpoint(EndpointDiscoveryMetadata endpoint, DiscoveryMessageSequence messageSequence)
        {
            if (endpoint == null)
                throw FxTrace.Exception.ArgumentNull(nameof(endpoint));
            if (messageSequence == null)
                throw FxTrace.Exception.ArgumentNull(nameof(messageSequence));
            if (string.IsNullOrWhiteSpace(endpoint.Id))
                throw FxTrace.Exception.Argument(nameof(endpoint), SR2.GetString(SR2.EndpointIdRequired));

            endpoints.Add(endpoint);
            messageSequenceTable[endpoint.Id] = messageSequence;
        }

        public DiscoveryMessageSequence GetMessageSequence(string endpointId)
        {
            if (string.IsNullOrWhiteSpace(endpointId))
                throw FxTrace.Exception.Argument(nameof(endpointId), SR2.GetString(SR2.InvalidEndpointId));

            if (!messageSequenceTable.TryGetValue(endpointId, out DiscoveryMessageSequence sequence))
                throw FxTrace.Exception.Argument(nameof(endpointId), SR2.GetString(SR2.EndpointNotFound, endpointId));

            return sequence;
        }
    }

    public class EndpointDiscoveryMetadata
    {
        public string Id { get; set; }
    }

    public class DiscoveryMessageSequence { }

