        public static string GetString(string key, params object[] args) => string.Format(key, args);
        public const string EndpointIdRequired = "Endpoint ID is required.";
        public const string InvalidEndpointId = "Invalid endpoint ID.";
        public const string EndpointNotFound = "Endpoint '{0}' not found.";
    }

