namespace Neos.IdentityServer.MultiFactor.WebAuthN.Library.Cbor.Numbers
{
  internal static class EFloatByteArrayString {
    internal static EFloat FromString(
      byte[] chars,
      int offset,
      int length,
      EContext ctx,
      bool throwException) {
      if (chars == null) {
        if (!throwException) {
          return null;
        } else {
          throw new ArgumentNullException(nameof(chars));
        }
      }
      if (offset < 0) {
        if (!throwException) {
          return null;
        } else { throw new FormatException("offset(" + offset + ") is not" +
"\u0020greater" + "\u0020or equal to 0");
}
      }
      if (offset > chars.Length) {
        if (!throwException) {
          return null;
        } else { throw new FormatException("offset(" + offset + ") is not" +
"\u0020less" + "\u0020or" + "\u0020equal to " + chars.Length);
}
      }
      if (length < 0) {
        if (!throwException) {
          return null;
        } else { throw new FormatException("length(" + length + ") is not" +
"\u0020greater or" + "\u0020equal to 0");
}
      }
      if (length > chars.Length) {
        if (!throwException) {
          return null;
        } else { throw new FormatException("length(" + length + ") is not" +
"\u0020less" + "\u0020or" + "\u0020equal to " + chars.Length);
}
      }
      if (chars.Length - offset < length) {
        if (!throwException) {
          return null;
        } else {
  throw new FormatException("str's length minus " + offset + "(" +
(chars.Length - offset) + ") is not greater or equal to " + length);
 }
      }
      EContext b64 = EContext.Binary64;
      if (ctx != null && ctx.HasMaxPrecision && ctx.HasExponentRange &&
        !ctx.IsSimplified && ctx.EMax.CompareTo(b64.EMax) <= 0 &&
        ctx.EMin.CompareTo(b64.EMin) >= 0 &&
        ctx.Precision.CompareTo(b64.Precision) <= 0) {
        int tmpoffset = offset;
        int endpos = offset + length;
        if (length == 0) {
          if (!throwException) {
            return null;
          } else {
            throw new FormatException();
          }
        }
        if (chars[tmpoffset] == '-' || chars[tmpoffset] == '+') {
          ++tmpoffset;
        }
        if (tmpoffset < endpos && ((chars[tmpoffset] >= '0' &&
              chars[tmpoffset] <= '9') || chars[tmpoffset] == '.')) {
          EFloat ef = DoubleEFloatFromString(
            chars,
            offset,
            length,
            ctx,
            throwException);
          if (ef != null) {
            return ef;
          }
        }

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Runtime.CompilerServices;
using System.Threading;
 
namespace Amb
{
    class Amb
    {
        class ExhaustedError : Exception
        {
            public ExhaustedError(string message) : base(message) { }
        }
 
        private Func<object> _fail;
 
        public Amb()
        {
            _fail = () => { throw new ExhaustedError("amb tree exhausted"); };
        }
 
        public T Choose<T>(params T[] choices)
        {
            var prevFail = _fail;
            var sk = new CallCC<T>();
            foreach (var choice in choices)
            {
                var fk = new CallCC<T>();
                _fail = () =>
                {
                    _fail = prevFail;
                    return fk.Call(null);
                };
                if (choice is Func<T>)
                {
                    return sk.Call((choice as Func<T>).Invoke());
                }
                else
                {
                    return sk.Call(choice);
                }
            }
            return sk.Call(_fail());
        }
 
        public void Failure()
        {
            Choose();
        }
 
        public void Assert(bool cond)
        {
            if (!cond) Failure();
        }
    }
 
    class CallCC<T>
    {
        private T _result;
        private bool _isCalled;
 
        public T Call(T result)
        {
            if (_isCalled)
            {
                return _result;
            }
            else
            {
                _isCalled = true;
                _result = result;
                return default(T);
            }
        }
    }
 
    class Vector
    {
        static void Main(string[] args)
        {
            var A = new Amb();
            var w1 = A.Choose("the", "that", "a");
            var w2 = A.Choose("frog", "elephant", "thing");
            var w3 = A.Choose("walked", "treaded", "grows");
            var w4 = A.Choose("slowly", "quickly");
 
            A.Assert(w1.Last() == w2.First());
            A.Assert(w2.Last() == w3.First());
            A.Assert(w3.Last() == w4.First());
 
            Console.WriteLine(w1);
            Console.WriteLine(w2);
            Console.WriteLine(w3);
            Console.WriteLine(w4);
        }
    }
}

