using System;
 
public class EthiopianMultiplication
{
    public static void Main()
    {
        Console.WriteLine(Ethiopian(17, 34, true));
    }
 
    public static int Ethiopian(int plier, int plicand, bool tutor)
    {
        int result = 0;
 
        if (tutor)
            Console.WriteLine("ethiopian multiplication of {0} by {1}", plier, plicand);
 
        while (plier >= 1)
        {
            if (IsEven(plier))
            {
                if (tutor)
                    Console.WriteLine("{0,4} {1,6} struck", plier, plicand);
            }
            else
            {
                if (tutor)
                    Console.WriteLine("{0,4} {1,6} kept", plier, plicand);
                result += plicand;
            }
            Halve(ref plier);
            Doublit(ref plicand);
        }
        return result;
    }
 
    public static void Halve(ref int x)
    {
        x >>= 1;
    }
 
    public static void Doublit(ref int x)
    {
        x <<= 1;
    }
 
    public static bool IsEven(int x)
    {
        return (x & 1) == 0;
    }
}

