using System;
using System.Threading;

namespace TimerComponent
{
    // Delegate definition for elapsed timer events
    public delegate void ElapsedTimerEventHandler(object sender, ElapsedTimerEventArgs args);

    // Structure holding data for each timer event
    public struct ElapsedTimerEventArgs
    {
        public long TimesRun { get; }

        public ElapsedTimerEventArgs(long timesRun)
        {
            TimesRun = timesRun;
        }
    }

    // Timer contract interface defining required functionality and disposable pattern
    public interface ITimer : IDisposable
    {
        // Gets the current period of the timer
        TimeSpan Period { get; set; }

        // Indicates if the timer is currently running
        bool Running { get; }

        // Number of times the timer has elapsed
        long TimesRun { get; }

        // Event triggered when the timer interval completes
        event ElapsedTimerEventHandler TimerElapsed;

        // Starts the timer with an optional initial delay
        void Start(TimeSpan? initialDelay = null);

        // Stops the timer
        void Stop();
    }

    // A basic implementation of the ITimer interface using System.Threading.Timer
    public class SimpleTimer : ITimer
    {
        private Timer _timer;
        private readonly object _lock = new object();
        private bool _disposed = false;
        private long _timesRun = 0;

        public TimeSpan Period { get; set; }
        public bool Running { get; private set; }
        public long TimesRun { get { return _timesRun; } }

        public event ElapsedTimerEventHandler TimerElapsed;

        public SimpleTimer(TimeSpan period)
        {
            Period = period;
        }

        public void Start(TimeSpan? initialDelay = null)
        {
            lock (_lock)
            {
                if (Running)
                    return;

                TimeSpan delay = initialDelay ?? Period;
                _timer = new Timer(TimerCallback, null, delay, Period);
                Running = true;
            }
        }

        private void TimerCallback(object state)
        {
            Interlocked.Increment(ref _timesRun);
            TimerElapsed?.Invoke(this, new ElapsedTimerEventArgs(_timesRun));
        }

        public void Stop()
        {
            lock (_lock)
            {
                if (!Running)
                    return;

                _timer.Dispose();
                Running = false;
            }
        }

        public void Dispose()
        {
            if (_disposed)
                return;

