namespace BullsAndCows
{
    class Validator
    {
        static void Main(string[] args)
        {
            string digits = "123456789";
            int size = 4;
            string chosen = new string(Enumerable.Range(0, size).Select(x => digits[new Random().Next(0, digits.Length)]).ToArray());
            //Console.WriteLine(chosen); // Debug
            Console.WriteLine("I have chosen a number from {0} unique digits from 1 to 9 arranged in a random order.", size);
            Console.WriteLine("You need to input a {0} digit, unique digit number as a guess at what I have chosen", size);
            int guesses = 0;
            while (true)
            {
                guesses++;
                string guess = "";
                while (true)
                {
                    // get a good guess
                    Console.Write("\nNext guess [{0}]: ", guesses);
                    guess = Console.ReadLine().Trim();
                    if (guess.Length == size && guess.All(char.IsDigit) && guess.Distinct().Count() == size)
                        break;
                    Console.WriteLine("Problem, try again. You need to enter {0} unique digits from 1 to 9", size);
                }
                if (guess == chosen)
                {
                    Console.WriteLine("\nCongratulations you guessed correctly in {0} attempts", guesses);
                    break;
                }
                int bulls = 0;
                int cows = 0;
                for (int i = 0; i < size; i++)
                {
                    if (guess[i] == chosen[i])
                        bulls++;
                    else if (chosen.Contains(guess[i]))
                        cows++;
                }
                Console.WriteLine(" {0} Bulls\n {1} Cows", bulls, cows);
            }
        }
    }
}

