    class Counter
    {
        static void Main(string[] args)
        {
            var points = new List<Point>();
            for (int i = 0; i < 10000; i++)
            {
                points.Add(new Point(new Random().NextDouble(), new Random().NextDouble()));
            }
            var sw = new Stopwatch();
            sw.Start();
            var ans1 = closest_bruteforce(points);
            sw.Stop();
            Console.WriteLine("bruteforce: " + sw.ElapsedMilliseconds);
            sw.Restart();
            var ans2 = closest_recursive(points);
            sw.Stop();
            Console.WriteLine("recursive: " + sw.ElapsedMilliseconds);
            Console.ReadKey();
        }
 
        public class Point
        {
            public double x;
            public double y;
 
            public Point(double x, double y)
            {
                this.x = x;
                this.y = y;
            }
        }
 
        public static double distance(Point p1, Point p2)
        {
            return Math.Sqrt(Math.Pow(p1.x - p2.x, 2) + Math.Pow(p1.y - p2.y, 2));
        }
 
        public static Tuple<double, List<Point>> closest_bruteforce(List<Point> points)
        {
            double mindist = double.MaxValue;
            List<Point> minpts = new List<Point>();
            for (int i = 0; i < points.Count; i++)
            {
                for (int j = i + 1; j < points.Count; j++)
                {
                    var dist = distance(points[i], points[j]);
                    if (dist < mindist)
                    {
                        mindist = dist;
                        minpts = new List<Point>() { points[i], points[j] };
                    }
                }
            }
            return new Tuple<double, List<Point>>(mindist, minpts);
        }
 
        public static Tuple<double, List<Point>> closest_recursive(List<Point> points)
        {
            if (points.Count <= 3)
            {
                return closest_bruteforce(points);
            }
            var xP = points.OrderBy(p => p.x).ToList();
            int mid = points.Count / 2;
            double xm = xP[mid].x;
            var dL = closest_recursive(xP.GetRange(0, mid));
            var dR = closest_recursive(xP.GetRange(mid, xP.Count - mid));
            var dmin = dL.Item1 < dR.Item1? dL : dR;

