namespace MobileServerInfrastructure.Configuration
{
    public class CrossDomainExtensionConfigProvider : IMobileAppExtensionConfigProvider
    {
        private readonly List<string> _allowedDomains;
        private const string CrossDomainControllerName = "CrossDomainController";
        private const string CrossDomainBridgeRouteName = "CrossDomainBridge";
        private const string CrossDomainLoginReceiverRouteName = "CrossDomainLoginReceiver";

        public CrossDomainExtensionConfigProvider(List<string> domains)
        {
            _allowedDomains = domains ?? new List<string>();
        }

        public void Initialize(HttpConfiguration config, IMobileAppConfiguration mobileAppConfiguration)
        {
            if (config == null || mobileAppConfiguration == null)
                throw new ArgumentNullException("Configuration parameters cannot be null");

            ConfigureCrossDomainOrigins(config);
            RegisterCrossDomainRoutes(config);
            PreventDefaultApiRouteMapping(config);
        }

        private void ConfigureCrossDomainOrigins(HttpConfiguration config)
        {
            config.EnableCors(new System.Web.Http.Cors.EnableCorsAttribute(
                origins: string.Join(",", _allowedDomains),
                headers: "*",
                methods: "*"
            ));
        }

        private void RegisterCrossDomainRoutes(HttpConfiguration config)
        {
            config.Routes.MapHttpRoute(
                name: CrossDomainBridgeRouteName,
                routeTemplate: "api/crossdomain/bridge",
                defaults: new { controller = CrossDomainControllerName, action = "Bridge" }
            );

            config.Routes.MapHttpRoute(
                name: CrossDomainLoginReceiverRouteName,
                routeTemplate: "api/crossdomain/login",
                defaults: new { controller = CrossDomainControllerName, action = "LoginReceiver" }
            );
        }

        private void PreventDefaultApiRouteMapping(HttpConfiguration config)
        {
            config.MapHttpAttributeRoutes();
            config.Routes.MapHttpRoute(
                name: "DefaultApi",
                routeTemplate: "api/{controller}/{id}",
                defaults: new { id = RouteParameter.Optional }
            );

            AddBaseRouteExclusion(config);
        }

