namespace RangeExceptions
{
    public class InvalidRangeException<T> : Exception
    {
        public T MinValue { get; }
        public T MaxValue { get; }

        public InvalidRangeException(string message, T minValue, T maxValue)
            : base(message)
        {
            MinValue = minValue;
            MaxValue = maxValue;
        }
    }

    public class MainClass
    {
        static void ValidateIntegerRange(int number, int start, int end)
        {
            if (number < start || number > end)
            {
                throw new InvalidRangeException<int>(
                    $"Number must be between {start} and {end}.",
                    start,
                    end
                );
            }
        }

        static void ValidateDateRange(DateTime date, DateTime start, DateTime end)
        {
            if (date < start || date > end)
            {
                throw new InvalidRangeException<DateTime>(
                    $"Date must be between {start:d} and {end:d}.",
                    start,
                    end
                );
            }
        }

        public static void Main(string[] args)
        {
            try
            {
                Console.Write("Enter an integer between 1 and 100: ");
                int number = int.Parse(Console.ReadLine());
                ValidateIntegerRange(number, 1, 100);
                Console.WriteLine($"Valid integer: {number}");

                Console.Write("Enter a date (dd/MM/yyyy) between 01/01/2020 and 31/12/2025: ");
                DateTime date = DateTime.ParseExact(
                    Console.ReadLine(),
                    "dd/MM/yyyy",
                    CultureInfo.InvariantCulture
                );
                ValidateDateRange(
                    date,
                    new DateTime(2020, 1, 1),
                    new DateTime(2025, 12, 31)
                );
                Console.WriteLine($"Valid date: {date:d}");
            }
            catch (InvalidRangeException<int> ex)
            {
                Console.WriteLine($"Integer Range Error: {ex.Message}");
            }
            catch (InvalidRangeException<DateTime> ex)
            {
                Console.WriteLine($"Date Range Error: {ex.Message}");
            }
            catch (FormatException)
            {
                Console.WriteLine("Invalid input format.");
            }
        }
    }
}

