public class Order
{
    public static void Main()
    {
        var primes = Sieve(999999);
        var diffsList = new List<List<int>> {
            new List<int> { 2 },
            new List<int> { 1 },
            new List<int> { 2, 2 },
            new List<int> { 2, 4 },
            new List<int> { 4, 2 },
            new List<int> { 6, 4, 2 }
        };
        Console.WriteLine("For primes less than 1,000,000:-\n");
        foreach (var diffs in diffsList)
        {
            Console.WriteLine("  For differences of {0} ->", string.Join(", ", diffs));
            var sp = SuccessivePrimes(primes, diffs);
            if (sp.Count == 0)
            {
                Console.WriteLine("    No groups found");
                continue;
            }
            Console.WriteLine("    First group   = {0}", string.Join(", ", sp.First()));
            Console.WriteLine("    Last group    = {0}", string.Join(", ", sp.Last()));
            Console.WriteLine("    Number found  = {0}", sp.Count);
            Console.WriteLine();
        }
    }
 
    public static List<int> Sieve(int limit)
    {
        var primes = new List<int> { 2 };
        var c = new bool[limit + 1]; // composite = true
        // no need to process even numbers > 2
        var p = 3;
        while (true)
        {
            var p2 = p * p;
            if (p2 > limit)
            {
                break;
            }
            for (var i = p2; i <= limit; i += 2 * p)
            {
                c[i] = true;
            }
            while (true)
            {
                p += 2;
                if (!c[p])
                {
                    break;
                }
            }
        }
        for (var i = 3; i <= limit; i += 2)
        {
            if (!c[i])
            {
                primes.Add(i);
            }
        }
        return primes;
    }
 
    public static List<List<int>> SuccessivePrimes(List<int> primes, List<int> diffs)
    {
        var results = new List<List<int>>();
        var dl = diffs.Count;
outer:
        for (var i = 0; i < primes.Count - dl; i++)
        {
            var group = new List<int> { primes[i] };
            for (var j = i; j < i + dl; j++)
            {
                if (primes[j + 1] - primes[j]!= diffs[j - i])
                {
                    group = null;
                    continue outer;
                }
                group.Add(primes[j + 1]);
            }
            results.Add(group);
            group = null;
        }

