    private static Vector3 GetTriangleNormal(Vector3 v0, Vector3 v1, Vector3 v2)
    {
        Vector3 edge1 = v1 - v0;
        Vector3 edge2 = v2 - v0;
        return Vector3.Cross(edge1, edge2);
    }

    private static bool IsPointInTriangle(Vector3 point, Vector3 v0, Vector3 v1, Vector3 v2)
    {
        Vector3 v0v1 = v1 - v0;
        Vector3 v0v2 = v2 - v0;
        Vector3 v0p = point - v0;

        Vector3 cross1 = Vector3.Cross(v0v1, v0p);
        Vector3 cross2 = Vector3.Cross(v0v2, v0p);

        if (Vector3.Dot(cross1, cross2) < 0)
        {
            return false;
        }

        Vector3 v1v2 = v2 - v1;
        Vector3 v1p = point - v1;

        Vector3 cross3 = Vector3.Cross(v1v2, v1p);
        if (Vector3.Dot(cross1, cross3) < 0)
        {
            return false;
        }

        Vector3 v2v0 = v0 - v2;
        Vector3 v2p = point - v2;

        Vector3 cross4 = Vector3.Cross(v2v0, v2p);
        if (Vector3.Dot(cross2, cross4) < 0)
        {
            return false;
        }

        return true;
    }
}

