using System;
using System.IO;
using System.Net;
using System.Net.Sockets;

public class SingletonApp
{
    private const int PORT = 65000; // random large port number
    private static ServerSocket s;

    // static initializer
    static SingletonApp()
    {
        try
        {
            s = new ServerSocket(PORT, 10, InetAddress.getLocalHost());
        }
        catch (UnknownHostException e)
        {
            // shouldn't happen for localhost
        }
        catch (IOException e)
        {
            // port taken, so app is already running
            Console.Write("Application is already running,");
            Console.WriteLine(" so terminating this instance.");
            Environment.Exit(0);
        }
    }

    public static void Main(string[] args)
    {
        Console.Write("OK, only this instance is running");
        Console.WriteLine(" but will terminate in 10 seconds.");
        try
        {
            Thread.Sleep(10000);
            if (s!= null &&!s.isClosed()) s.close();
        }
        catch (Exception e)
        {
            Console.Error.WriteLine(e);
        }
    }
}

