        {
            Assertions(config, parser);

            string rawData = await DownloadAsync(config);

            if (string.IsNullOrEmpty(rawData))
            {
                return new Collection<T>();
            }
            return Parse(config, rawData, maxRecords, parser);
        }

        private static void Assertions(JsonDataConfig config, IParser<T> parser)
        {
            if (config == null)
            {
                throw new ConfigNullException();
            }
            if (parser == null)
            {
                throw new ParserNullException();
            }
            if (string.IsNullOrEmpty(config.Url))
            {
                throw new ConfigParameterNullException("Url");
            }
        }

        public static IEnumerable<T> Parse(JsonDataConfig config, string data, int maxRecords, IParser<T> parser)
        {
            try
            {
                return parser.Parse(data, config.ElementsPath, maxRecords);
            }
            catch
            {
                throw new ParserException();
            }
        }
        private async Task<string> DownloadAsync(JsonDataConfig config)
        {
            try
            {
                var request = new JsonHttpRequest();
                return await request.DownloadAsync(config.Url);
            }
            catch
            {
                throw new RequestFailedException();
            }
        }
    }
}

using System;
using System.Text;
 
public class VLQCode
{
  public static byte[] encode(long n)
  {
    int numRelevantBits = 64 - BitOperations.LeadingZeroCount(n);
    int numBytes = (numRelevantBits + 6) / 7;
    if (numBytes == 0)
      numBytes = 1;
    byte[] output = new byte[numBytes];
    for (int i = numBytes - 1; i >= 0; i--)
    {
      int curByte = (int)(n & 0x7F);
      if (i!= (numBytes - 1))
        curByte |= 0x80;
      output[i] = (byte)curByte;
      n >>= 7;
    }
    return output;
  }
 
  public static long decode(byte[] b)
  {
    long n = 0;
    for (int i = 0; i < b.Length; i++)
    {
      int curByte = b[i] & 0xFF;
      n = (n << 7) | (curByte & 0x7F);
      if ((curByte & 0x80) == 0)
        break;
    }
    return n;
  }
 
  public static string byteArrayToString(byte[] b)
  {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < b.Length; i++)
    {
      if (i > 0)
        sb.Append(", ");
      string s = Convert.ToString(b[i] & 0xFF, 16);
      if (s.Length < 2)
        s = "0" + s;
      sb.Append(s);
    }
    return sb.ToString();
  }
 
  public static void Main(string[] args)
  {
    long[] testNumbers = { 2097152, 2097151, 1, 127, 128, 589723405834L };
    foreach (long n in testNumbers)
    {
      byte[] encoded = encode(n);
      long decoded = decode(encoded);
      Console.WriteLine("Original input=" + n + ", encoded = [" + byteArrayToString(encoded) + "], decoded=" + decoded + ", " + ((n == decoded)? "OK" : "FAIL"));
    }
  }
}

