namespace BooleanValueConverters
{
    // This converter is used to invert boolean and nullable boolean values.
    // It implements the IValueConverter interface for use in WPF data bindings.
    public class BooleanInverterConverter : IValueConverter
    {
        // Convert method: Inverts the given boolean or nullable boolean value.
        // If the input value is not a recognized boolean type, it returns DependencyProperty.UnsetValue.
        public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
        {
            // Check if the input value is a non-nullable boolean.
            if (value is bool boolValue)
            {
                return !boolValue;
            }

            // Check if the input value is a nullable boolean.
            if (value is bool? nullableBool)
            {
                if (nullableBool.HasValue)
                {
                    return !nullableBool.Value;
                }
            }

            // If the value is not a valid boolean, return the special unset value.
            return DependencyProperty.UnsetValue;
        }

        // ConvertBack method: Delegates to the same inversion logic as the forward conversion.
        // This ensures consistent behavior in bidirectional bindings.
        public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
        {
            return Convert(value, targetType, parameter, culture);
        }
    }

    // Test application to demonstrate the converter usage.
    // Typically, in a real WPF application, data bindings would utilize this converter.
    public class TestConverterUsage
    {
        public static void Main(string[] args)
        {
            // Create an instance of the BooleanInverterConverter.
            BooleanInverterConverter inverter = new BooleanInverterConverter();

            // Array of test values including boolean, nullable boolean, null, and an unsupported type.
            object[] testValues = { true, false, (bool?)true, (bool?)false, null, 123 };

            Console.WriteLine("Forward Conversion Results:");
            for (int i = 0; i < testValues.Length; i++)
            {
                object input = testValues[i];
                object output = inverter.Convert(input, typeof(bool), null, CultureInfo.InvariantCulture);
                Console.WriteLine("Test #{0}: Input = {1}  -->  Output = {2}", i + 1, input, output);
            }

