public class SimpleInjectorViewComponentInvokerFactory : IViewComponentInvokerFactory
{
    private readonly Container _container;
    private readonly Lazy<IViewComponentInvoker> _invoker;

    public SimpleInjectorViewComponentInvokerFactory(Container container)
    {
        _container = container ?? throw new ArgumentNullException(nameof(container));
        _invoker = new Lazy<IViewComponentInvoker>(CreateInstance);
    }

    public IViewComponentInvoker CreateViewComponentInvoker(ViewComponentContext context)
    {
        return _invoker.Value;
    }

    private IViewComponentInvoker CreateInstance()
    {
        return new HybridViewComponentInvoker(_container);
    }
}

public class HybridViewComponentInvoker : IViewComponentInvoker
{
    private readonly Container _container;

    public HybridViewComponentInvoker(Container container)
    {
        _container = container ?? throw new ArgumentNullException(nameof(container));
    }

    public async Task InvokeAsync(ViewComponentContext context)
    {
        var componentType = context.ViewComponentDescriptor.Type;
        var component = _container.GetInstance(componentType);
        var logger = GetLogger(context);

        logger.LogDebug("Resolved {ComponentType} via SimpleInjector", componentType.Name);

        try
        {
            var result = InvokeComponentMethod(context, component);
            await HandleAsyncResult(result, context);
        }
        catch (Exception ex)
        {
            logger.LogError(ex, "Error invoking {ComponentType}", componentType.Name);
            throw new ViewComponentException("Component invocation failed", ex);
        }
    }

    private ILogger GetLogger(ViewComponentContext context)
    {
        return context.ViewContext.HttpContext.RequestServices
            .GetRequiredService<ILogger<HybridViewComponentInvoker>>();
    }

    private object InvokeComponentMethod(ViewComponentContext context, object component)
    {
        var method = context.ViewComponentDescriptor.MethodInfo;
        var parameters = method.GetParameters();
        var args = new object[parameters.Length];

        for (int i = 0; i < parameters.Length; i++)
        {
            args[i] = context.Arguments.ContainsKey(parameters[i].Name!)
                ? context.Arguments[parameters[i].Name!]

