    [ApiController]
    [Route("api/[controller]")]
    public class TableController : ControllerBase
    {
        private readonly CorePokerContext _db;

        public TableController(CorePokerContext db)
        {
            _db = db;
        }

        [HttpGet("{tableId}")]
        public async Task<IActionResult> Get(Guid tableId)
        {
            var tableEntity = await _db.Tables
                .Include(t => t.TablePlayers)
                .ThenInclude(tp => tp.Player)
                .FirstOrDefaultAsync(t => t.PublicId == tableId);

            if (tableEntity == null) return NotFound();

            var payload = new TablePayload
            {
                PublicId = tableEntity.PublicId,
                Name = tableEntity.Name,
                CreatedAt = tableEntity.CreatedAt,
                Players = tableEntity.TablePlayers.Select(tp => new TablePlayerPayload
                {
                    PlayerId = tp.PlayerId,
                    Role = tp.Role
                }).ToList()
            };

            return Ok(payload);
        }

        [HttpPost]
        public async Task<IActionResult> Post([FromBody][Required] CreateTableRequest request)
        {
            if (!await _db.Players.AnyAsync(p => p.Id == request.OwnerPlayerId))
                return NotFound("Player not found");

            var tableEntity = new Table
            {
                PublicId = Guid.NewGuid(),
                Name = request.Name,
                CreatedAt = DateTime.UtcNow
            };

            _db.Tables.Add(tableEntity);
            await _db.SaveChangesAsync();

            _db.TablePlayers.Add(new TablePlayer
            {
                TableId = tableEntity.Id,
                PlayerId = request.OwnerPlayerId,
                Role = "Owner"
            });
            await _db.SaveChangesAsync();

            var payload = new TablePayload
            {
                PublicId = tableEntity.PublicId,
                Name = tableEntity.Name,
                CreatedAt = tableEntity.CreatedAt,
                Players = new List<TablePlayerPayload>
                {
                    new TablePlayerPayload
                    {
                        PlayerId = request.OwnerPlayerId,
                        Role = "Owner"
                    }
                }
            };

