namespace UIStyleSystem
{
    public interface IStylePropertySerializer
    {
        Type PropertyType { get; }
        Guid Identifier { get; }
        object Parse(XElement element);
        XElement Write(object value, string elementName);
    }

    public class StringValueStylePropertySerializer : IStylePropertySerializer
    {
        // Target type for this serializer is string.
        public Type PropertyType => typeof(string);

        // Unique identifier for string style properties.
        public Guid Identifier { get; } = new Guid("C76D04A6-2731-4DC2-A2A8-1B616EB2F287");

        // Parses the given XML element and returns its text content as a string.
        public object Parse(XElement element)
        {
            if (element == null)
                throw new ArgumentNullException(nameof(element));

            // Extract and return the text content from the XML element.
            return element.Value;
        }

        // Embeds the string value into an XML element with the provided element name.
        public XElement Write(object value, string elementName)
        {
            if (string.IsNullOrEmpty(elementName))
                throw new ArgumentException("Element name cannot be null or empty.", nameof(elementName));

            if (!(value is string stringValue))
                throw new ArgumentException("Value must be a string.", nameof(value));

            // Create and return a new XML element that contains the string value.
            return new XElement(elementName, stringValue);
        }
    }

    // Optional demonstration within a console application.
    class Product
    {
        static void Main(string[] args)
        {
            // Create an instance of the serializer.
            IStylePropertySerializer serializer = new StringValueStylePropertySerializer();

            // Create an XML element representing a styled property.
            XElement originalElement = new XElement("Style", "Example String Value");

            // Deserialize the XML element to obtain its string value.
            object deserializedValue = serializer.Parse(originalElement);
            Console.WriteLine("Deserialized Value: " + deserializedValue);

            // Serialize the string value back into an XML element.
            XElement serializedElement = serializer.Write(deserializedValue, "Style");
            Console.WriteLine("Serialized XML: " + serializedElement);
        }
    }
}

