using System;
using System.Threading;
using ChakraCore.NET.API;

public class ContextSwitchService : IDisposable
{
    private readonly JavaScriptContext _targetContext;
    private readonly EventWaitHandle _handle = new EventWaitHandle(true, EventResetMode.AutoReset);
    private JavaScriptContext _currentContext;
    private bool _isDisposed;

    public ContextSwitchService(JavaScriptContext targetContext)
    {
        _targetContext = targetContext ?? throw new ArgumentNullException(nameof(targetContext));
        _currentContext = JavaScriptContext.Current;
    }

    public bool IsCurrentContext => _currentContext == _targetContext;

    public void Enter()
    {
        if (_isDisposed)
            throw new ObjectDisposedException(nameof(ContextSwitchService));

        if (IsCurrentContext)
            return;

        _handle.WaitOne();
        _currentContext = _targetContext;
        JavaScriptContext.Current = _currentContext;
    }

    public void Leave()
    {
        if (_isDisposed)
            throw new ObjectDisposedException(nameof(ContextSwitchService));

        if (!IsCurrentContext)
            return;

        _currentContext = JavaScriptContext.Current;
        _handle.Set();
    }

    public void With(Action action)
    {
        if (action == null)
            throw new ArgumentNullException(nameof(action));

        Enter();
        try
        {
            action();
        }
        finally
        {
            Leave();
        }
    }

    public T With<T>(Func<T> func)
    {
        if (func == null)
            throw new ArgumentNullException(nameof(func));

        Enter();
        try
        {
            return func();
        }
        finally
        {
            Leave();
        }
    }

    public void Dispose()
    {
        if (_isDisposed)
            return;

        if (IsCurrentContext)
            Leave();

        _handle.Dispose();
        _isDisposed = true;
    }
}

using System;
 
namespace Jos
{
    class Tree
    {
        // m-th on the reversed kill list; m = 0 is final survivor
        static int jos(int n, int k, int m)
        {
            int a;
            for (a = m + 1; a <= n; a++)
                m = (m + k) % a;
            return m;
        }
 
        // same as jos(), useful if n is large and k is not
        static ulong jos_large(ulong n, ulong k, ulong m)
        {
            if (k <= 1) return n - m - 1;
 
            ulong a = m;
            while (a < n)
            {
                ulong q = (a - m + k - 2) / (k - 1);
 
                if (a + q > n) q = n - a;
                else if (q == 0) q = 1;
 
                m = (m + q * k) % (a += q);
            }
 
            return m;
        }
 
        static void Main(string[] args)
        {
            ulong n, k, i;
 
            n = 41;
            k = 3;
            Console.WriteLine("n = {0}, k = {1}, final survivor: {2}", n, k, jos(n, k, 0));
 
            n = 9876543210987654321;
            k = 12031;
            Console.Write("n = {0}, k = {1}, three survivors:", n, k);
 
            for (i = 3; i-- > 0; )
                Console.Write(" {0}", jos_large(n, k, i));
            Console.WriteLine();
        }
    }
}

using System;
