namespace fyiReporting.RdlGtkViewer
{
    public class CairoPdfWriter
    {
        public CairoPdfWriter()
        {
        }

        public byte[] GetFileBytes(Report report)
        {
            var pages = report.BuildPages();
            int width = (int)report.PageWidthPoints;
            int height = (int)report.PageHeightPoints;
            string filename = string.Format("gen-{0}.pdf", Guid.NewGuid());

            try
            {
                using (Cairo.PdfSurface pdf = new Cairo.PdfSurface(filename, width, height))
                {
                    using (Cairo.Context g = new Cairo.Context(pdf))
                    {

                        var render = new  fyiReporting.RdlGtkViewer.RenderCairo(g);
                        render.RunPages(pages);
                    }
                }
                byte[] bytes = File.ReadAllBytes(filename);
                return bytes;

            }
            finally
            {
                if (File.Exists(filename))
                {
                    File.Delete(filename);
                }
            }
        }

    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;

namespace AdventOfCode
{
    struct Point
    {
        public int X { get; set; }
        public int Y { get; set; }
    }

    class Advent32
    {
        List<Point> points = new List<Point>();
        ArrayList robot = new ArrayList();
        ArrayList santa = new ArrayList();
        int sum = 0;

        public void ReadFile()
        {
            StreamReader sr = new StreamReader("c:\\tasks\\3.txt");
            string line = sr.ReadLine();
            RobotOrSanta(line);
            WhichSite(santa);
            WhichSite(robot);
            PrintPoints();
        }

        void RobotOrSanta(string s)
        {
            for (int i = 0; i < s.Length; i++)
            {
                if (i % 2 == 0) { santa.Add(s[i]); }
                else { robot.Add(s[i]); }
            }
        }

        void AddPoint(int x, int y)
        {
            if (CheckPoint(x, y))
            {
                Point p;
                p.X = x;
                p.Y = y;
                points.Add(p);
                sum++;
            }
        }

        bool CheckPoint(int x, int y)
        {
            foreach (Point p in points)
            {
                if (p.X == x && p.Y == y) return false;
            }
            return true;
        }

        void WhichSite(ArrayList list)
        {
            int x = 0;
            int y = 0;
            AddPoint(x, y);

            foreach (char c in list)
            {
                if (c == '<') { x--; }
                if (c == '>') { x++; }
                if (c == '^') { y++; }
                if (c == 'v') { y--; }
                AddPoint(x, y);
            }
        }

        void PrintPoints()
        {
            Console.WriteLine("Count of unique points: " + sum);
        }
    }
}

