namespace Task
{
    class Converter
    {
        static void Main(string[] args)
        {
            List<int> triangles = new List<int>();
            list_comprehension(triangles, 20);
            foreach (int i in triangles)
            {
                Console.Write(i + " ");
            }
            Console.ReadKey();
        }
 
        static void list_comprehension(List<int> numbers, int upper_border)
        {
            for (int a = 1; a < upper_border; a++)
            {
                for (int b = a + 1; b < upper_border; b++)
                {
                    double c = Math.Pow(a * a + b * b, 0.5); //remembering Mr. Pythagoras
                    if ((c * c) < Math.Pow(upper_border, 2) + 1)
                    {
                        if (c == Math.Floor(c))
                        {
                            numbers.Add(a);
                            numbers.Add(b);
                            numbers.Add((int)c);
                        }
                    }
                }
            }
        }
    }
