namespace AdapterExample
{
    // Generic adapter that wraps an underlying list and simulates covariance.
    public class CovariantListAdapter<TTarget, TUnderlying> : IList<TTarget>
        where TTarget : class
        where TUnderlying : class
    {
        private readonly IList<TUnderlying> _underlyingList;

        public CovariantListAdapter(IList<TUnderlying> underlyingList)
        {
            _underlyingList = underlyingList ?? throw new ArgumentNullException(nameof(underlyingList));
        }

        // Converts from target type to underlying type.
        protected virtual TUnderlying ConvertToUnderlying(TTarget item)
        {
            if (item == null)
                return null;

            if (item is TUnderlying underlying)
                return underlying;

            throw new InvalidCastException("Cannot convert item from target type to underlying type.");
        }

        // Converts from underlying type to target type.
        protected virtual TTarget ConvertToTarget(TUnderlying item)
        {
            if (item == null)
                return null;

            if (item is TTarget target)
                return target;

            // If conversion is not possible, return null as per design.
            return null;
        }

        public TTarget this[int index]
        {
            get { return ConvertToTarget(_underlyingList[index]); }
            set { _underlyingList[index] = ConvertToUnderlying(value); }
        }

        public int Count => _underlyingList.Count;
        public bool IsReadOnly => _underlyingList.IsReadOnly;

        public void Add(TTarget item)
        {
            _underlyingList.Add(ConvertToUnderlying(item));
        }

        public void Clear()
        {
            _underlyingList.Clear();
        }

        public bool Contains(TTarget item)
        {
            TUnderlying converted = ConvertToUnderlying(item);
            return _underlyingList.Contains(converted);
        }

        public void CopyTo(TTarget[] array, int arrayIndex)
        {
            for (int i = 0; i < _underlyingList.Count; i++)
            {
                array[arrayIndex + i] = ConvertToTarget(_underlyingList[i]);
            }
        }

        public IEnumerator<TTarget> GetEnumerator()
        {
            foreach (TUnderlying item in _underlyingList)
            {
                yield return ConvertToTarget(item);
            }
        }

        public int IndexOf(TTarget item)
        {

