    {
        /// <summary>
        /// Indicates no execution mode specified. Acts as the default.
        /// </summary>
        [EnumMember(Value = "none")]
        None,

        /// <summary>
        /// Executes the search job in normal asynchronous mode.
        /// The client receives a job identifier immediately and can query later for results.
        /// </summary>
        [EnumMember(Value = "normal")]
        Normal,

        /// <summary>
        /// Executes the search job in blocking mode.
        /// The client waits until the search job completes before regaining control.
        /// </summary>
        [EnumMember(Value = "blocking")]
        Blocking,

        /// <summary>
        /// Executes the search job with oneshot mode.
        /// The client receives the complete search results immediately as the output.
        /// </summary>
        [EnumMember(Value = "oneshot")]
        Oneshot
    }

