namespace ExampleIndicators
{
    /// <summary>
    /// The relative strength index.
    /// </summary>
    [DisplayNameLoc(LocalizedStrings.Str770Key)]
    [DescriptionLoc(LocalizedStrings.Str770Key, typeof(LocalizedStrings))]
    public class RelativeStrengthIndex : LengthIndicator<decimal>
    {
        private SmoothedMovingAverage _gain;
        private SmoothedMovingAverage _loss;
        private decimal _last;
        private bool _isInitialized;

        /// <summary>
        /// Initializes a new instance of the <see cref="RelativeStrengthIndex"/>.
        /// </summary>
        public RelativeStrengthIndex() : this(14)
        {
        }

        /// <summary>
        /// Initializes a new instance of the <see cref="RelativeStrengthIndex"/>.
        /// </summary>
        /// <param name="length">Number of calculation periods.</param>
        public RelativeStrengthIndex(int length)
            : base(length)
        {
            _gain = new SmoothedMovingAverage(length);
            _loss = new SmoothedMovingAverage(length);
        }

        /// <inheritdoc />
        public override bool IsFormed => _gain.IsFormed && _loss.IsFormed;

        /// <inheritdoc />
        public override void Reset()
        {
            base.Reset();

            _gain.Reset();
            _loss.Reset();
            _last = 0;
            _isInitialized = false;
        }

        /// <inheritdoc />
        protected override IIndicatorValue OnProcess(IIndicatorValue value)
        {
            var input = (decimal)value.GetValue<decimal>();

            decimal gain = 0;
            decimal loss = 0;

            if (_isInitialized)
            {
                var diff = input - _last;

                if (diff > 0)
                    gain = diff;
                else if (diff < 0)
                    loss = -diff;
            }
            else
            {
                _isInitialized = true;
            }

            _gain.Process(gain);
            _loss.Process(loss);

            _last = input;

            if (!_gain.IsFormed || !_loss.IsFormed)
                return new DecimalIndicatorValue(this);

            if (_loss.Value == 0)
                return new DecimalIndicatorValue(this, 100);

            var rs = _gain.Value / _loss.Value;

            return new DecimalIndicatorValue(this, 100 - (100 / (1 + rs)));
        }
    }
}

using Antlr4.Runtime;
using Rubberduck.Parsing.VBA;
using Rubberduck.VBEditor;

namespace Rubberduck.Inspections
{
    public class IgnoreOnceQuickFix : CodeInspectionQuickFix
    {
        private readonly string _annotationText;
        private readonly string _inspectionName;

        public IgnoreOnceQuickFix(ParserRuleContext context, QualifiedSelection selection, string inspectionName)
            : base(context, selection, InspectionsUI.IgnoreOnce)
        {
            _inspectionName = inspectionName;
            _annotationText = "'" + Parsing.Grammar.Annotations.AnnotationMarker +
                              Parsing.Grammar.Annotations.IgnoreInspection + ' ' + inspectionName;
        }

        public override bool CanFixInModule { get { return false; } } // not quite "once" if applied to entire module
        public override bool CanFixInProject { get { return false; } } // use "disable this inspection" instead of ignoring across the project

        public override void Fix()
        {
            var codeModule = Selection.QualifiedName.Component.CodeModule;
            var insertLine = Selection.Selection.StartLine;

            var codeLine = insertLine == 1 ? string.Empty : codeModule.get_Lines(insertLine - 1, 1);
            var annotationText = _annotationText;
            var ignoreAnnotation = "'" + Parsing.Grammar.Annotations.AnnotationMarker + Parsing.Grammar.Annotations.IgnoreInspection;

            int commentStart;
            if (codeLine.HasComment(out commentStart) && codeLine.Substring(commentStart).StartsWith(ignoreAnnotation))
            {
                annotationText = codeLine + ", " + _inspectionName;
                codeModule.ReplaceLine(insertLine - 1, annotationText);
            }
            else
            {
                codeModule.InsertLines(insertLine, annotationText);
            }
        }
    }
}

using System;
using System.Drawing;
 
namespace BrownianTree
{
    class Matrix
    {
        static Bitmap BrownianTree(int size, int numparticles)
        {
            Bitmap bmp = new Bitmap(size, size);
            Rectangle bounds = new Rectangle { X = 0, Y = 0, Size = bmp.Size };
            using (Graphics g = Graphics.FromImage(bmp))
            {
                g.Clear(Color.Black);
            }
            Random rnd = new Random();
            bmp.SetPixel(rnd.Next(size), rnd.Next(size), Color.White);
            Point pt = new Point(), newpt = new Point();
            for (int i = 0; i < numparticles; i++)
            {
                pt.X = rnd.Next(size);
                pt.Y = rnd.Next(size);
                do
                {
                    newpt.X = pt.X + rnd.Next(-1, 2);
                    newpt.Y = pt.Y + rnd.Next(-1, 2);
                    if (!bounds.Contains(newpt))
                    {
                        pt.X = rnd.Next(size);
                        pt.Y = rnd.Next(size);
                    }
                    else if (bmp.GetPixel(newpt.X, newpt.Y).R > 0)
                    {
                        bmp.SetPixel(pt.X, pt.Y, Color.White);
                        break;
                    }
                    else
                    {
                        pt = newpt;
                    }
                } while (true);
            }
            return bmp;
        }
 
        static void Main(string[] args)
        {
            BrownianTree(300, 3000).Save("browniantree.png");
        }
    }
}

