    // Handler for evaluator failures; crashes the driver on failure events.
    public class FailedEvaluatorHandler : IObserver<TypedEvaluatorFailure>
    {
        private static readonly Logger Logger = Logger.GetLogger(typeof(FailedEvaluatorHandler));

        [Inject]
        public FailedEvaluatorHandler()
        {
            // Dependency injection constructor; no initialization needed.
        }

        public void OnNext(TypedEvaluatorFailure failure)
        {
            if (failure == null)
            {
                Logger.Log(Level.Error, "Received a null evaluator failure event.");
                return;
            }

            string evaluatorId = failure.FailedEvaluatorId;
            string message = string.Format(
                CultureInfo.InvariantCulture,
                "Evaluator with Id {0} has failed critically. Terminating the driver.",
                evaluatorId);

            // Log the error details
            Logger.Log(Level.Error, message);

            // Trigger an unrecoverable exception to crash the driver.
            Exceptions.Throw(new InvalidOperationException(message), Logger);
        }

        public void OnError(Exception error)
        {
            // Placeholder for handling observer errors (not implemented).
            Logger.Log(Level.Error, "Observer encountered an error: " + error.Message);
        }

        public void OnCompleted()
        {
            // Placeholder for completion logic (not implemented).
            Logger.Log(Level.Info, "Evaluator failure event observation completed.");
        }
    }

