using System;
using System.Net.NetworkInformation;
using System.Threading;

public interface INetworkStateService
{
    event EventHandler NetworkConnected;
    void Start();
    void Stop();
}

public class NetworkStateService : INetworkStateService
{
    private Thread workerThread;
    private readonly AutoResetEvent resetEvent = new AutoResetEvent(false);
    private volatile bool running;

    public event EventHandler NetworkConnected;

    public void Start()
    {
        if (running) return;

        running = true;
        workerThread = new Thread(ThreadStart);
        workerThread.IsBackground = true;
        workerThread.Start();
    }

    public void Stop()
    {
        running = false;
        resetEvent.Set();
        workerThread?.Join();
    }

    private void ThreadStart()
    {
        while (running)
        {
            if (NetworkInterface.GetIsNetworkAvailable())
            {
                SendNetworkConnectedEvent();
            }
            resetEvent.WaitOne(TimeSpan.FromSeconds(1));
        }
    }

    private void SendNetworkConnectedEvent()
    {
        NetworkConnected?.Invoke(this, EventArgs.Empty);
    }

    public void Dispose()
    {
        Stop();
        resetEvent.Dispose();
    }
}

public class Employee
{
    public static void Main(string[] args)
    {
        var networkService = new NetworkStateService();
        networkService.NetworkConnected += OnNetworkConnected;
        networkService.Start();

        Console.WriteLine("Network monitoring started. Press Enter to exit...");
        Console.ReadLine();

        networkService.Stop();
        networkService.Dispose();
    }

    private static void OnNetworkConnected(object sender, EventArgs e)
    {
        Console.WriteLine("Network is connected!");
    }
}

using System;
using System.Collections.Generic;

namespace STSdb4.Storage
{
    public interface IHeap : IDisposable
    {
        // Properties
        long CurrentVersion { get; }
        byte[] Tag { get; set; }

        // Handle Management
        long ObtainHandle();
        void Release(long handle);
        bool Exists(long handle);

        // Data Operations
        void Write(long handle, byte[] buffer, int index, int count);
        byte[] Read(long handle);
        IEnumerable<KeyValuePair<long, byte[]>> GetLatest(long atVersion);

        // Space Management
        long GetUsedSpace();

        // Versioning and Atomicity
        void Commit();

        // Cleanup
        void Close();
    }

    public class Heap : IHeap
    {
        private long currentVersion = 0;
        private Dictionary<long, byte[]> data = new Dictionary<long, byte[]>();
        private byte[] tag = new byte[256];

        public long CurrentVersion => currentVersion;

        public byte[] Tag
        {
            get => tag;
            set => tag = value ?? new byte[256];
        }

        public long ObtainHandle()
        {
            long handle = DateTime.UtcNow.Ticks;
            while (data.ContainsKey(handle))
            {
                handle++;
            }
            return handle;
        }

        public void Release(long handle)
        {
            if (data.ContainsKey(handle))
            {
                data.Remove(handle);
            }
        }

        public bool Exists(long handle)
        {
            return data.ContainsKey(handle);
        }

        public void Write(long handle, byte[] buffer, int index, int count)
        {
            byte[] block = new byte[count];
            Array.Copy(buffer, index, block, 0, count);
            data[handle] = block;
        }

        public byte[] Read(long handle)
        {
            return data.ContainsKey(handle) ? data[handle] : null;
        }

        public IEnumerable<KeyValuePair<long, byte[]>> GetLatest(long atVersion)
        {
            return data.Where(kvp => kvp.Key <= atVersion);
        }

        public long GetUsedSpace()
        {
            return data.Sum(kvp => kvp.Value.Length);
        }

        public void Commit()
        {
            currentVersion++;
        }

        public void Close()
        {
            data.Clear();
        }

        public void Dispose()
        {
            Close();
        }
    }
}

