namespace ComplexDataManagement
{
    [StructLayout(LayoutKind.Sequential, Pack = 1)]
    public struct AA
    {
        public int tmp1;
        public float tmp2;
        public short tmp3;

        public AA(int t1, float t2, short t3)
        {
            tmp1 = t1;
            tmp2 = t2;
            tmp3 = t3;
        }

        public static int[] a_init = new int[] { 1, 2, 3 };
        public static int[] a_zero = new int[] { 0, 0, 0 };

        public void Reset()
        {
            tmp1 = 0;
            tmp2 = 0.0f;
            tmp3 = 0;
        }

        public bool Verify(int expected1, float expected2, short expected3)
        {
            return (tmp1 == expected1 && tmp2 == expected2 && tmp3 == expected3);
        }
    }

    [StructLayout(LayoutKind.Sequential, Pack = 1)]
    public struct BB
    {
        public double field1;
        public long field2;

        public BB(double f1, long f2)
        {
            field1 = f1;
            field2 = f2;
        }

        public static double f_init = 1.0;
        public static long f_zero = 0;

        public void Reset()
        {
            field1 = 0.0;
            field2 = 0;
        }

        public bool Verify(double expected1, long expected2)
        {
            return (field1 == expected1 && field2 == expected2);
        }
    }

    public class DataManager
    {
        public static AA[] instancesAA = new AA[10];
        public static BB[] instancesBB = new BB[10];

        static DataManager()
        {
            for (int i = 0; i < instancesAA.Length; i++)
            {
                instancesAA[i] = new AA(i, i * 1.1f, (short)(i % 5));
            }

            for (int i = 0; i < instancesBB.Length; i++)
            {
                instancesBB[i] = new BB(i * 2.5, i * 1000);
            }
        }

        public static void ResetAllAA()
        {
            foreach (var instance in instancesAA)
            {
                instance.Reset();
            }
        }

        public static void ResetAllBB()
        {
            foreach (var instance in instancesBB)
            {
                instance.Reset();
            }
        }

        public static void VerifyAllAA()
        {
            foreach (var instance in instancesAA)
            {
                if (!instance.Verify(0, 0.0f, 0))
                {
                    Console.WriteLine("AA instance verification failed.");
                }
            }
