namespace ApplicationFramework.Pages
{
    public abstract class PageBase : Page
    {
        private const string StateKey = "PageState";
        private NavigationHelper _navigationHelper;

        protected NavigationHelper NavigationHelper => _navigationHelper;

        public PageBase()
        {
            _navigationHelper = new NavigationHelper(this);
            _navigationHelper.LoadState += NavigationHelperLoadState;
            _navigationHelper.SaveState += NavigationHelperSaveState;
        }

        protected override void OnNavigatedTo(NavigationEventArgs e)
        {
            base.OnNavigatedTo(e);
            _navigationHelper.OnNavigatedTo(e);

            if (e.NavigationMode == NavigationMode.New)
            {
                OnInitializeNewPage();
            }
            else if (e.NavigationMode == NavigationMode.Back)
            {
                LoadState(e.Parameter);
            }
        }

        protected override void OnNavigatedFrom(NavigationEventArgs e)
        {
            base.OnNavigatedFrom(e);
            _navigationHelper.OnNavigatedFrom(e);
            SaveState(e.Parameter);
        }

        private void NavigationHelperLoadState(object sender, LoadStateEventArgs e)
        {
            try
            {
                if (e.PageState != null && e.PageState.ContainsKey(StateKey))
                {
                    var pageState = e.PageState[StateKey] as PageState;
                    if (pageState != null)
                    {
                        LoadState(pageState);
                    }
                }
            }
            catch (Exception ex)
            {
                HandleLoadStateException(ex);
            }
        }

        private void NavigationHelperSaveState(object sender, SaveStateEventArgs e)
        {
            try
            {
                var pageState = new PageState();
                SaveState(pageState);
                e.PageState[StateKey] = pageState;
            }
            catch (Exception ex)
            {
                HandleSaveStateException(ex);
            }
        }

        protected virtual void OnInitializeNewPage()
        {
            // Optional method for initializing a new page
        }

        protected virtual void LoadState(object parameter)
        {
            // Default implementation for loading page state
        }

        protected virtual void SaveState(object parameter)
        {

