using System;

namespace QoSMonitoringSystem
{
    public class OperationMeasurement
    {
        public string OperationId { get; set; }
        public string CustomerId { get; set; }
        public int Latency { get; set; }
        public DateTime Timestamp { get; set; }
    }

    public class LatencySpikeMonitor
    {
        private static readonly ILog Log = LogManager.GetLogger(typeof(LatencySpikeMonitor));
        private readonly EPServiceProvider _runtime;

        public LatencySpikeMonitor(EPServiceProvider runtime)
        {
            _runtime = runtime;
        }

        public void Start()
        {
            var epl = $@"select * from OperationMeasurement
                        where Latency > {20000}";

            var statement = _runtime.EPAdministrator.CreateEPL(epl);
            statement.Events += HandleMatchedEvent;
        }

        private void HandleMatchedEvent(object sender, UpdateEventArgs e)
        {
            foreach (var eventBean in e.NewEvents)
            {
                var operation = eventBean.Get("OperationId").ToString();
                var customer = eventBean.Get("CustomerId").ToString();
                var latency = Convert.ToInt32(eventBean.Get("Latency"));

                LogLatencyEvent(operation, customer, latency);
            }
        }

        private void LogLatencyEvent(string operationId, string customerId, int latency)
        {
            Log.Info($"Latency violation detected - Operation: {operationId} | " +
                    $"Customer: {customerId} | Latency: {latency}ms");
        }
    }

    public class Sorter
    {
        public static void Main()
        {
            var config = new Configuration();
            config.AddEventType<OperationMeasurement>();
            var provider = EPServiceProviderManager.GetDefaultProvider(config);

            var monitor = new LatencySpikeMonitor(provider);
            monitor.Start();
        }
    }
}

public static class Extension
{
    public static IEnumerable<IEnumerable<T>> Permutations<T>(this IEnumerable<T> values) where T : IComparable<T>
    {
        if (values.Count() == 1)
            return new[] { values };
        return values.SelectMany(v => Permutations(values.Where(x => x.CompareTo(v) != 0)), (v, p) => p.Prepend(v));
    }
}

using DesignTE.Model;
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;

namespace DesignTE.Serialization
{
    public class MapTextSerializer
    {
        public void Serialize(MapNode mapNode, StringBuilder str, int indent = 0)
        {
            for (int i = 0; i < indent; i++) str.Append("\t");
            str.AppendLine(mapNode.Text);

            foreach(MapNode childNode in mapNode.ChildNodes)
            {
                Serialize(childNode, str, indent + 1);
            }
        }

        public void Deserialize(string text, MapNode location, Func<MapNode, string, MapNode> CreateNode)
        {
            string line;
            int indent = 0, previousIndent = 0;
            MapNode node, previousNode = null;
            StringReader str = new StringReader(text);

            while((line = str.ReadLine()) != null)
            {
                indent = GetIndent(line);

                if(previousNode == null)
                {
                    node = CreateNode(location, line.Trim());
                }
                else
                {
                    if(indent <= previousIndent)
                    {
                        int backIndent = previousIndent - indent + 1;
                        while(backIndent != 0)
                        {
                            previousNode = previousNode.Parent;
                            if (previousNode == location) break;
                            backIndent--;
                        }

                    }

                    node = CreateNode(previousNode, line.Trim());
                }
                previousNode = node;
                previousIndent = indent;
            }
        }

        private int GetIndent(string line)
        {
            int indent = 0;
            while (indent < line.Length && line[indent] == '\t')
            {
                indent++;
            }
            return indent;
        }

    }
}

using System;
 
class Graph
{
    static void Main()
    {
        string input =
            "Character,Speech\n" +
            "The multitude,The messiah! Show us the messiah!\n" +
            "Brians mother,<angry>Now you listen here! He's not the messiah; " +
                "he's a very naughty boy! Now go away!</angry>\n" +
            "The multitude,Who are you?\n" +
            "Brians mother,I'm his mother; that's who!\n" +
            "The multitude,Behold his mother! Behold his mother!";
        string s;
        Console.Write("<table>\n<tr><td>");
        for (s = input; s!= ""; s = s.Substring(1)) {
            switch(s[0]) {
            case '\n': Console.Write("</td></tr>\n<tr><td>"); break;
            case ',':  Console.Write("</td><td>"); break;
            case '<':  Console.Write("&lt;"); break;
            case '>':  Console.Write("&gt;"); break;
            case '&':  Console.Write("&amp;"); break;
            default:   Console.Write(s[0]);
            }
        }
        Console.WriteLine("</td></tr>\n</table>");
    }
}

