        /// Returns a string that represents the current <see cref="CommandResult"/>.
        /// </summary>
        /// <returns>A formatted string containing the exit code, output, and any error message.</returns>
        public override string ToString()
        {
            string result = string.Format("Exit Code: {0}", ExitCode);
