namespace RazorLight.Compilation.Razor
{
    public class TagHelperIntermediateNode : IntermediateNode
    {
        public string TagName { get; set; }
        public TagMode TagMode { get; set; }
        public TagHelperDescriptor TagHelperDescriptor { get; set; }

        public IntermediateNodeCollection Children { get; } = new IntermediateNodeCollection();

        public TagHelperBodyIntermediateNode Body
        {
            get { return Children.OfType<TagHelperBodyIntermediateNode>().FirstOrDefault(); }
            set
            {
                var existingBody = Body;
                if (existingBody != null)
                {
                    Children.Remove(existingBody);
                }
                if (value != null)
                {
                    Children.Add(value);
                }
            }
        }

        public IReadOnlyList<TagHelperPropertyIntermediateNode> Properties => Children.OfType<TagHelperPropertyIntermediateNode>().ToList();

        public IReadOnlyList<TagHelperHtmlAttributeIntermediateNode> HtmlAttributes => Children.OfType<TagHelperHtmlAttributeIntermediateNode>().ToList();

        public override void Accept(IntermediateNodeVisitor visitor)
        {
            visitor.VisitTagHelper(this);
        }

        public override string FormatNode()
        {
            return $"TagHelper: {TagName} ({TagHelperDescriptor?.Name})";
        }
    }

    public enum TagMode
    {
        StartTagAndEndTag,
        SelfClosing,
        StartTagOnly
    }
}

