public class GenericRepository<T> where T : class
{
    protected readonly DbContext _context;
    protected readonly DbSet<T> _dbset;

    public GenericRepository(DbContext context)
    {
        _context = context;
        _dbset = context.Set<T>();
    }

    public virtual T Load(int id)
    {
        return _dbset.Find(id);
    }

    public virtual IEnumerable<T> GetAll()
    {
        return _dbset.ToList();
    }
}

public class WorkspaceRepository : GenericRepository<Workspace>
{
    public WorkspaceRepository(DbContext context) : base(context) { }

    public Workspace Load(int id)
    {
        return base.Load(id);
    }

    public Workspace FindByPathMatch(string filePath)
    {
        if (string.IsNullOrWhiteSpace(filePath))
            return null;

        var normalizedPath = Path.GetFullPath(filePath);
        var pathSegments = normalizedPath.Split(Path.DirectorySeparatorChar)
                                          .Where(p => !string.IsNullOrWhiteSpace(p))
                                          .ToArray();

        var workspaces = GetAll();
        var workspaceStack = new Stack<string>(pathSegments.Reverse());

        while (workspaceStack.Count > 0)
        {
            var currentPath = string.Join(Path.DirectorySeparatorChar.ToString(), workspaceStack.ToArray());
            var matchingWorkspace = workspaces.FirstOrDefault(ws => string.Equals(ws.FilePath, currentPath, StringComparison.OrdinalIgnoreCase));

            if (matchingWorkspace != null)
                return matchingWorkspace;

            workspaceStack.Pop();
        }

        return null;
    }
}

