using System;
using System.Numerics;

public static class MultinomialCoefficient
{
    public static BigInteger Calculate(int n, int[] k)
    {
        ValidateInputs(n, k);

        BigInteger numerator = Factorial(n);
        BigInteger denominator = 1;

        foreach (int groupSize in k)
        {
            denominator *= Factorial(groupSize);
        }

        return numerator / denominator;
    }

    private static void ValidateInputs(int n, int[] k)
    {
        if (n < 0)
        {
            throw new ArgumentException("Total number of items (n) must be non-negative.");
        }

        if (k == null || k.Length == 0)
        {
            throw new ArgumentException("Group sizes (k) cannot be null or empty.");
        }

        int sum = 0;
        foreach (int groupSize in k)
        {
            if (groupSize < 0)
            {
                throw new ArgumentException("Group sizes must be non-negative.");
            }
            sum += groupSize;
        }

        if (sum != n)
        {
            throw new ArgumentException("Sum of group sizes must equal the total number of items (n).");
        }
    }

    private static BigInteger Factorial(int number)
    {
        if (number < 0)
            throw new ArgumentException("Number must be non-negative.");

        BigInteger result = 1;
        for (int i = 2; i <= number; i++)
        {
            result *= i;
        }
        return result;
    }

    public static void Main(string[] args)
    {
        try
        {
            int n = 10;
            int[] k = { 3, 2, 5 };

            BigInteger result = Calculate(n, k);
            Console.WriteLine($"The multinomial coefficient is: {result}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
}

