{
    public class DebuggerSettings
    {
        public bool EnableJustMyCode { get; set; }
        public string[] SearchPaths { get; set; }
    }

    public interface IDbgDotNetCodeLocationFactory { }
    public interface IDbgModuleMemoryRefreshedNotifier2 { }
    public interface IDbgRawMetadataService { }
