    public class DbgEngineImplDependencies
    {
        private readonly DebuggerSettings _debuggerSettings;
        private readonly Lazy<IDbgDotNetCodeLocationFactory> _codeLocationFactory;
        private readonly Lazy<IDbgModuleMemoryRefreshedNotifier2> _memoryNotifier;
        private readonly Lazy<IDbgRawMetadataService> _metadataService;
        private readonly Lazy<IDbgEngineStepperFactory> _stepperFactory;

        public DbgEngineImplDependencies(
            DebuggerSettings debuggerSettings,
            Lazy<IDbgDotNetCodeLocationFactory> codeLocationFactory,
            Lazy<IDbgModuleMemoryRefreshedNotifier2> memoryNotifier,
            Lazy<IDbgRawMetadataService> metadataService,
            Lazy<IDbgEngineStepperFactory> stepperFactory)
        {
            _debuggerSettings = debuggerSettings ?? throw new ArgumentNullException(nameof(debuggerSettings));
            _codeLocationFactory = codeLocationFactory ?? throw new ArgumentNullException(nameof(codeLocationFactory));
            _memoryNotifier = memoryNotifier ?? throw new ArgumentNullException(nameof(memoryNotifier));
            _metadataService = metadataService ?? throw new ArgumentNullException(nameof(metadataService));
            _stepperFactory = stepperFactory ?? throw new ArgumentNullException(nameof(stepperFactory));
        }

        public DebuggerSettings GetDebuggerSettings()
        {
            return _debuggerSettings;
        }

        public void InitializeDebugger()
        {
            var codeLocation = _codeLocationFactory.Value;
