namespace DiagnosticLogging
{
    // Base message class representing a generic diagnostic message.
    public abstract class BaseMessage
    {
        // Abstract method to return the formatted message string representation.
        public abstract override string ToString();
    }

    // Custom message class for encapsulating diagnostic or logging messages.
    public class CustomMessage : BaseMessage
    {
        // Property to store the message text.
        private readonly string _messageText;

        // Constructor that accepts a plain text string.
        public CustomMessage(string message)
        {
            _messageText = message;
        }

        // Constructor that accepts a text string with formatting parameters.
        public CustomMessage(string message, params object[] args)
        {
            if (args != null && args.Length > 0)
            {
                _messageText = string.Format(message, args);
            }
            else
            {
                _messageText = message;
            }
        }

        // Override the ToString method to output the formatted message string.
        public override string ToString()
        {
            // Build a formatted message string with delimiters for clarity.
            StringBuilder builder = new StringBuilder();
            builder.Append("### ");
            builder.Append(_messageText);
            builder.Append(" ###");
            return builder.ToString();
        }
    }

    // Writer demonstrating the usage of CustomMessage.
    class Writer
    {
        static void Main(string[] args)
        {
            // Create a message using the plain text constructor.
            CustomMessage plainMessage = new CustomMessage("This is a diagnostic message.");
            Console.WriteLine(plainMessage.ToString());

            // Create a message using the formatted text constructor.
            CustomMessage formattedMessage = new CustomMessage("Error code: {0}, description: {1}", 404, "Not Found");
            Console.WriteLine(formattedMessage);

            // Create a list of messages to simulate multiple log entries.
            List<CustomMessage> messages = new List<CustomMessage>
            {
                new CustomMessage("System initialized successfully."),
                new CustomMessage("User {0} has logged in.", "Alice"),
                new CustomMessage("Warning: Resource usage at {0}%", 85)
            };

