using System;
using System.Configuration;

namespace ConfigurationElements
{
    public interface IKeyedConfigurationElement<TKey>
    {
        TKey Key { get; }
    }

    public class NameObjectConfigurationElement<TValue> : ConfigurationElement, IKeyedConfigurationElement<string>
    {
        private static readonly ConfigurationProperty _propName = new ConfigurationProperty("name", typeof(string), string.Empty, ConfigurationPropertyOptions.IsRequired | ConfigurationPropertyOptions.IsKey);
        private static readonly ConfigurationProperty _propValue = new ConfigurationProperty("value", typeof(TValue), default(TValue), ConfigurationPropertyOptions.None);

        private static readonly ConfigurationPropertyCollection _properties = new ConfigurationPropertyCollection();

        private bool _nameSet;
        private bool _valueSet;

        static NameObjectConfigurationElement()
        {
            _properties.Add(_propName);
            _properties.Add(_propValue);
        }

        public NameObjectConfigurationElement()
        {
            _nameSet = false;
            _valueSet = false;
        }

        [ConfigurationProperty("name", IsRequired = true, IsKey = true)]
        public string Name
        {
            get
            {
                if (!_nameSet)
                {
                    _nameSet = true;
                    base[_propName] = string.Empty;
                }
                return (string)base[_propName];
            }
            set
            {
                _nameSet = true;
                base[_propName] = value;
            }
        }

        [ConfigurationProperty("value", DefaultValue = null)]
        public TValue Value
        {
            get
            {
                if (!_valueSet)
                {
                    _valueSet = true;
                    base[_propValue] = default(TValue);
                }
                return (TValue)base[_propValue];
            }
            set
            {
                _valueSet = true;
                base[_propValue] = value;
            }
        }

        protected override ConfigurationPropertyCollection Properties
        {
            get { return _properties; }
        }

        string IKeyedConfigurationElement<string>.Key
        {
            get { return Name; }
        }
    }
}

using System;
