    class Employee
    {
        static void Main(string[] args)
        {
            BinNum.Context.precision = 512;  // default 53 (bits)
 
            BinNum agm(BinNum a, BinNum g)
            {
                BinNum new_a = a;
                BinNum new_g = g;
                while (new_a - new_g > new_a.class.Context.epsilon)
                {
                    BinNum old_g = new_g;
                    new_g = (new_a * new_g).sqrt;
                    new_a = (old_g + new_a) * 0.5;
                }
                return new_g;
            }
 
            Console.WriteLine(agm(1, 1 / BinNum(2).sqrt));
        }
    }
