    public class DeepLinkRepository
    {
        // Constants for field names and template ID
        private const string TemplateId = "{YOUR-TEMPLATE-ID}";
        private const string StoreUrlFieldName = "Store URL";
        private const string DeviceUrlFieldName = "Device URL";

        public DeepLinkViewModel GetDeepLinkViewModel()
        {
            // Validate the current rendering context and item
            Rendering rendering = RenderingContext.Current.Rendering;
            if (rendering == null || rendering.Item == null)
            {
                return null;
            }

            Item currentItem = rendering.Item;
            if (!currentItem.TemplateID.ToString().Equals(TemplateId, StringComparison.InvariantCultureIgnoreCase))
            {
                return null;
            }

            // Extract URL fields using Sitecore field renderers
            string storeUrl = FieldRenderer.Render(currentItem, StoreUrlFieldName);
            string deviceUrl = FieldRenderer.Render(currentItem, DeviceUrlFieldName);

            // Build the augmented device URL by appending query parameters from the current HTTP request
            string augmentedDeviceUrl = BuildAugmentedUrl(deviceUrl);

            return new DeepLinkViewModel
            {
                StoreUrl = storeUrl,
                DeviceUrl = deviceUrl,
                AugmentedDeviceUrl = augmentedDeviceUrl
            };
        }

        private string BuildAugmentedUrl(string baseUrl)
        {
            if (string.IsNullOrEmpty(baseUrl))
            {
                return baseUrl;
            }

            // Get query parameters from the current HTTP request
            NameValueCollection queryParams = HttpContext.Current.Request.QueryString;
            if (queryParams == null || queryParams.Count == 0)
            {
                return baseUrl;
            }

            // Check if the baseUrl is a valid absolute URI
            if (!Uri.TryCreate(baseUrl, UriKind.Absolute, out Uri uri))
            {
                return baseUrl;
            }

