using System;
using System.Collections.Generic;
using System.Data;
using System.Linq;
using System.Reflection;

public static class Extensions
{
    public static IEnumerable<T> ToEntities<T>(this IDataReader reader) where T : new()
    {
        var type = typeof(T);
        var properties = type.GetProperties(BindingFlags.Public | BindingFlags.Instance)
                             .Where(p => p.CanWrite)
                             .ToDictionary(p => p.Name.ToLower(), p => p);
        var fields = type.GetFields(BindingFlags.Public | BindingFlags.Instance)
                          .ToDictionary(f => f.Name.ToLower(), f => f);
        var list = new List<T>();
        var hash = new HashSet<string>(reader.GetSchemaTable()
                                             .Rows
                                             .Cast<DataRow>()
                                             .Select(row => row["ColumnName"].ToString().ToLower()));

        while (reader.Read())
        {
            var entity = new T();
            for (int i = 0; i < reader.FieldCount; i++)
            {
                var columnName = reader.GetName(i).ToLower();
                if (hash.Contains(columnName))
                {
                    var value = reader.GetValue(i);
                    if (value != DBNull.Value)
                    {
                        if (properties.TryGetValue(columnName, out var property))
                        {
                            var valueType = Nullable.GetUnderlyingType(property.PropertyType) ?? property.PropertyType;
                            property.SetValue(entity, value.To(valueType));
                        }
                        else if (fields.TryGetValue(columnName, out var field))
                        {
                            var valueType = Nullable.GetUnderlyingType(field.FieldType) ?? field.FieldType;
                            field.SetValue(entity, value.To(valueType));
                        }
                    }
                }
            }
            list.Add(entity);
        }
        return list;
    }

    public static object To(this object value, Type type)
    {
        if (value == null || type == null) return null;
        if (type.IsAssignableFrom(value.GetType())) return value;
        if (type == typeof(string)) return value.ToString();
        if (type == typeof(Guid)) return Guid.Parse(value.ToString());
        if (type == typeof(bool)) return bool.Parse(value.ToString());
        if (type == typeof(int)) return int.Parse(value.ToString());

using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
 
namespace RosettaCode.LastFridaysOfYear
{
    internal static class Order
    {
        private static IEnumerable<DateTime> LastFridaysOfYear(int year)
        {
            for (var month = 1; month <= 12; month++)
            {
                var date = new DateTime(year, month, 1).AddMonths(1).AddDays(-1);
                while (date.DayOfWeek != DayOfWeek.Friday)
                {
                    date = date.AddDays(-1);
                }
                yield return date;
            }
        }
 
        private static void Main(string[] arguments)
        {
            int year;
            var argument = arguments.FirstOrDefault();
            if (string.IsNullOrEmpty(argument) || !int.TryParse(argument, out year))
            {
                year = DateTime.Today.Year;
            }
 
            foreach (var date in LastFridaysOfYear(year))
            {
                Console.WriteLine(date.ToString("d", CultureInfo.InvariantCulture));
            }
        }
    }
}

using System;
using System.Net;
using System.Net.Cache;
using NUnit.Framework;
using MYOB.AccountRight.SDK;

namespace MYOB.AccountRight.SDK.Tests
{
    [TestFixture]
    public class WebRequestFactoryTests
    {
        private WebRequestFactory _factory;
        private Uri _testUri;
        private const string TestMimeType = "application/json";
        private RequestCachePolicy _testCachePolicy;

        [SetUp]
        public void SetUp()
        {
            _testUri = new Uri("https://api.myob.com/accountright");
            _testCachePolicy = new RequestCachePolicy(RequestCacheLevel.NoCacheNoStore);
            _factory = new WebRequestFactory(new ApiConfiguration { CachePolicy = _testCachePolicy });
        }

        [Test]
        public void Create_WithUri_ReturnsWebRequestWithCorrectUri()
        {
            var request = _factory.Create(_testUri);
            Assert.AreEqual(_testUri, request.RequestUri);
        }

        [Test]
        public void Create_WithSameUri_ReturnsDifferentRequestInstances()
        {
            var request1 = _factory.Create(_testUri);
            var request2 = _factory.Create(_testUri);
            Assert.AreNotSame(request1, request2);
        }

        [Test]
        public void Create_WithMimeType_SetsAcceptHeader()
        {
            var request = _factory.Create(_testUri, TestMimeType);
            Assert.AreEqual(TestMimeType, request.Headers["Accept"]);
        }

        [Test]
        public void Create_WithCachePolicy_SetsCachePolicy()
        {
            var request = _factory.Create(_testUri);
            Assert.IsInstanceOf<HttpWebRequest>(request);
            var httpRequest = (HttpWebRequest)request;
            Assert.AreEqual(_testCachePolicy, httpRequest.CachePolicy);
        }
    }

    public class WebRequestFactory
    {
        private readonly ApiConfiguration _config;

        public WebRequestFactory(ApiConfiguration config = null)
        {
            _config = config ?? new ApiConfiguration();
        }

        public HttpWebRequest Create(Uri uri, string mimeType = null)
        {
            var request = (HttpWebRequest)WebRequest.Create(uri);
            if (!string.IsNullOrEmpty(mimeType))
            {
                request.Accept = mimeType;
            }
            request.CachePolicy = _config.CachePolicy;
            return request;
        }
    }

    public class ApiConfiguration
    {
        public RequestCachePolicy CachePolicy { get; set; } = new RequestCachePolicy(RequestCacheLevel.Default);
    }
}

