public class UCViewData : UserControl
{
    private byte[] _lastData;
    private int _lastIdx;
    private bool _showInHexadecimal;
    private GroupBox groupBox1;
    private TextBox txtIndex, txtByte, txtInt16, txtInt32, txtInt64;

    public UCViewData()
    {
        InitializeComponent();
    }

    private void InitializeComponent()
    {
        groupBox1 = new GroupBox { Dock = DockStyle.Fill };
        var flowPanel = new FlowLayoutPanel { Dock = DockStyle.Fill, FlowDirection = FlowDirection.TopDown };
        groupBox1.Controls.Add(flowPanel);
        Controls.Add(groupBox1);

        txtIndex = AddField(flowPanel, "Index:");
        txtByte = AddField(flowPanel, "Byte:");
        txtInt16 = AddField(flowPanel, "Int16:");
        txtInt32 = AddField(flowPanel, "Int32:");
        txtInt64 = AddField(flowPanel, "Int64:");
        Size = new Size(200, 150);
    }

    private TextBox AddField(FlowLayoutPanel panel, string label)
    {
        panel.Controls.Add(new Label { Text = label, AutoSize = true });
        var txt = new TextBox { ReadOnly = true, Width = 100 };
        panel.Controls.Add(txt);
        return txt;
    }

    public void ShowValues(byte[] data, int idx)
    {
        _lastData = data;
        _lastIdx = idx;
        DisplayValues();
    }

    private void DisplayValues()
    {
        if (_lastData == null || _lastIdx < 0 || _lastIdx >= _lastData.Length)
        {
            Clear();
            return;
        }

        txtIndex.Text = _lastIdx.ToString();
        txtByte.Text = GetValue(_lastData, _lastIdx, 1, () => _lastData[_lastIdx]);
        txtInt16.Text = GetValue(_lastData, _lastIdx, 2, () => BitConverter.ToInt16(_lastData, _lastIdx));
        txtInt32.Text = GetValue(_lastData, _lastIdx, 4, () => BitConverter.ToInt32(_lastData, _lastIdx));
        txtInt64.Text = GetValue(_lastData, _lastIdx, 8, () => BitConverter.ToInt64(_lastData, _lastIdx));
    }

    private string GetValue<T>(byte[] data, int idx, int bytes, Func<T> convert)
    {
        if (idx + bytes > data.Length) return "N/A";
        return FormatValue(convert());
    }

    private string FormatValue<T>(T value) where T : struct =>
        _showInHexadecimal ? $"0x{value:X{System.Runtime.InteropServices.Marshal.SizeOf(typeof(T)) * 2}}" : value.ToString();

    private void Clear()
    {
        txtIndex.Text = txtByte.Text = txtInt16.Text = txtInt32.Text = txtInt64.Text = "";
    }

    [Browsable(true)]
    public override string Text
    {
        get => groupBox1.Text;

