namespace ZohoPeopleApiExample
{
    class Helper
    {
        static async Task Main(string[] args)
        {
            string login = File.ReadAllText("login.txt");
            string token = File.ReadAllText("token.txt");

            var zohoClient = new ZohoClient("your_organization_id");

            // Authenticate with Zoho People
            await zohoClient.Auth.LoginAsync(login, token);

            // Retrieve time logs for a specific user and date range
            var timeLogs = await zohoClient.TimeTracker.GetAsync(new DateTime(2023, 01, 01), new DateTime(2023, 01, 31), new List<string>() { "user@example.com" });
            Console.WriteLine($"Retrieved {timeLogs.Count()} time logs.");

            // Add a new time log entry
            var newTimeLog = new TimeLogEntry
            {
                UserEmail = "user@example.com",
                Date = DateTime.Now.Date,
                TimeIn = DateTime.Now.TimeOfDay,
                TimeOut = DateTime.Now.TimeOfDay.Add(TimeSpan.FromHours(1)),
                FormLinkName = "TimeSheet"
            };
            await zohoClient.TimeTracker.AddAsync(newTimeLog);

            // Delete a time log entry
            if (timeLogs.Any())
            {
                await zohoClient.TimeTracker.DeleteAsync(timeLogs.First().Id);
            }

            // Fetch holidays
            var holidays = await zohoClient.TimeTracker.GetHolidaysAsync(new DateTime(2023, 01, 01), new DateTime(2023, 12, 31));
            Console.WriteLine($"Retrieved {holidays.Count()} holidays.");

            // Fetch records from a specific form
            var records = await zohoClient.FetchRecord.GetByFormAsync("Your_Form_Link_Name", "your_criteria", 1, 200);
            Console.WriteLine($"Retrieved {records.Count()} records from the form.");

            Console.ReadKey();
        }
    }
}

