namespace VampireNumbers
{
    class Fangs
    {
        public long fang1;
        public long fang2;
        public Fangs(long fang1, long fang2)
        {
            this.fang1 = fang1;
            this.fang2 = fang2;
        }
    }
 
    class Library
    {
        static long pow10(int n)
        {
            if (n < 0) throw new ArgumentException("Can't be negative");
            long pow = 1;
            for (int i = 1; i <= n; i++) pow *= 10;
            return pow;
        }
 
        static int countDigits(long n)
        {
            if (n < 0) throw new ArgumentException("Can't be negative");
            if (n == 0) return 1;
            int count = 0;
            long nn = n;
            while (nn > 0)
            {
                count++;
                nn /= 10;
            }
            return count;
        }
 
        static bool hasTrailingZero(long n)
        {
            if (n < 0) throw new ArgumentException("Can't be negative");
            return n % 10 == 0;
        }
 
        static string sortedString(string s)
        {
            char[] ca = s.ToCharArray();
            Array.Sort(ca);
            return new string(ca);
        }
 
        static bool isVampiric(long n, List<Fangs> fl)
        {
            if (n < 0) return false;
            int len = countDigits(n);
            if (len % 2 == 1) return false;
            int hlen = len / 2;
            long first = pow10(hlen - 1);
            long last = 10 * first;
            long j;
            int cd;
            string ss = sortedString(n.ToString());
            for (long i = first; i < last; i++)
            {
                if (n % i!= 0) continue;
                j = n / i;
                if (j < i) return fl.Count > 0;
                cd = countDigits(j);
                if (cd > hlen) continue;
                if (cd < hlen) return fl.Count > 0;
                if (ss!= sortedString(i.ToString() + j.ToString())) continue;
                if (!(hasTrailingZero(i) && hasTrailingZero(j)))
                {
                    fl.Add(new Fangs(i, j));
                }
            }
            return fl.Count > 0;
        }
 
        static string showFangs(List<Fangs> fangsList)
        {
            string s = "";
            foreach (Fangs f in fangsList)
            {
                s += " = " + f.fang1 + " x " + f.fang2;
            }
            return s;
        }
 
