public class AdaptableList<T, U> : ListAdapter<T, U> where T : class where U : class
{
    private readonly List<T> _list;

    public AdaptableList(List<T> list)
    {
        _list = list ?? throw new ArgumentNullException(nameof(list));
    }

    public override U Convert(T item)
    {
        if (item == null)
            return null;

        var adapted = item as U;
        if (adapted == null)
            throw new InvalidCastException($"Cannot convert {typeof(T)} to {typeof(U)}.");

        return adapted;
    }

    public override T Convert(U item)
    {
        if (item == null)
            return null;

        var adapted = item as T;
        if (adapted == null)
            throw new InvalidCastException($"Cannot convert {typeof(U)} to {typeof(T)}.");

        return adapted;
    }

    public override int Count => _list.Count;

    public override U this[int index]
    {
        get => Convert(_list[index]);
        set => _list[index] = Convert(value);
    }

    public override void Add(U item)
    {
        _list.Add(Convert(item));
    }

    public override void Clear()
    {
        _list.Clear();
    }

    public override bool Contains(U item)
    {
        return _list.Contains(Convert(item));
    }

    public override IEnumerator<U> GetEnumerator()
    {
        foreach (var item in _list)
        {
            yield return Convert(item);
        }
    }

    public override int IndexOf(U item)
    {
        return _list.IndexOf(Convert(item));
    }

    public override void Insert(int index, U item)
    {
        _list.Insert(index, Convert(item));
    }

    public override bool Remove(U item)
    {
        return _list.Remove(Convert(item));
    }

    public override void RemoveAt(int index)
    {
        _list.RemoveAt(index);
    }
}

public abstract class ListAdapter<T, U> : IList<U> where T : class where U : class
{
    public abstract U Convert(T item);
    public abstract T Convert(U item);
    public abstract int Count { get; }
    public abstract U this[int index] { get; set; }
    public abstract void Add(U item);
    public abstract void Clear();
    public abstract bool Contains(U item);
    public abstract IEnumerator<U> GetEnumerator();
    public abstract int IndexOf(U item);
    public abstract void Insert(int index, U item);
    public abstract bool Remove(U item);
    public abstract void RemoveAt(int index);

    System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator()
    {
        return GetEnumerator();
    }
}

