namespace SuperDigit
{
    class Task
    {
        static void Main(string[] args)
        {
            for (int d = 2; d <= 9; d++)
            {
                Console.Write(d + ": ");
                var superd = SuperDigit(d);
                for (int i = 0; i < 10; i++)
                {
                    Console.Write(superd.Next() + ", ");
                }
                Console.WriteLine();
            }
        }
 
        static IEnumerable<int> SuperDigit(int d)
        {
            if (d < 2 || d > 9)
            {
                throw new ArgumentException("argument must be integer from 2 to 9 inclusive");
            }
            var tofind = new string(d.ToString()[0], d);
            for (int n = 2; ; n++)
            {
                if (new string(d.ToString()[0], d).All(c => (d * Math.Pow(n, d)).ToString().Contains(c)))
                {
                    yield return n;
                }
            }
        }
    }
}

