namespace Stack
{
    class Processor
    {
        static void Main(string[] args)
        {
            Stack<int> stk = new Stack<int>();
            Console.WriteLine("pushing: ");
            for (int i = 'a'; i <= 'z'; i++)
            {
                Console.Write(" {0}", (char)i);
                stk.Push(i);
            }
            Console.WriteLine("\nsize now: {0}", stk.Count);
            Console.WriteLine("\nstack is{0} empty\n", stk.Count == 0? "" : " not");
            Console.WriteLine("\npoppoing:");
            while (stk.Count > 0)
                Console.Write(" {0}", (char)stk.Pop());
            Console.WriteLine("\nsize now: {0}", stk.Count);
            Console.WriteLine("\nstack is{0} empty\n", stk.Count == 0? "" : " not");
            Console.ReadKey();
        }
    }
}

