using System;
using System.Collections;
using System.Collections.Generic;

public class Sweep<T>
{
    // This is a generic base class for sweeps of type T
}

public class LinearSweep : Sweep<double>
{
    public double Initial { get; }
    public double Final { get; }
    public int Count { get; private set; }

    public LinearSweep(double initial, double final, int count)
    {
        Initial = initial;
        Final = final;
        Count = count;
    }

    public LinearSweep(double initial, double final, double stepSize)
    {
        Initial = initial;
        Final = final;
        Count = CalculateCount(initial, final, stepSize);
    }

    private int CalculateCount(double start, double end, double stepSize)
    {
        return (int)Math.Ceiling((end - start) / stepSize) + 1;
    }

    public IEnumerable<double> GeneratePoints()
    {
        double stepSize = (Final - Initial) / (Count - 1);
        for (int i = 0; i < Count; i++)
        {
            yield return Initial + (i * stepSize);
        }
    }

    public static void Main(string[] args)
    {
        LinearSweep sweep1 = new LinearSweep(0, 10, 5);
        Console.WriteLine("Points from sweep1:");
        foreach (var point in sweep1.GeneratePoints())
        {
            Console.WriteLine(point);
        }

        LinearSweep sweep2 = new LinearSweep(0, 10, 2);
        Console.WriteLine("Points from sweep2:");
        foreach (var point in sweep2.GeneratePoints())
        {
            Console.WriteLine(point);
        }

        LinearSweep sweep3 = new LinearSweep(0, 5, 0.5);
        Console.WriteLine("Points from sweep3:");
        foreach (var point in sweep3.GeneratePoints())
        {
            Console.WriteLine(point);
        }
    }
}

