using System;

public class PublicClass
{
    private void PrivateMethod() { Console.WriteLine("Private Method"); }
    internal void InternalMethod() { Console.WriteLine("Internal Method"); }
    protected virtual void ProtectedMethod() { Console.WriteLine("Protected Method"); }
    public void PublicMethod() { Console.WriteLine("Public Method"); PrivateMethod(); }
    public void InvokeParentProtectedMehtod() { ProtectedMethod(); }
}

internal class InternalClass { }

internal class InternalClassChild : PublicClass
{
    public void CallProtectedMethod() { ProtectedMethod(); }
}

public abstract class AbstractClass
{
    public abstract void AbtractMethod();
    public virtual void VirtualMethod() { Console.WriteLine("Virtual Method in AbstractClass"); }
}

public class ImplementingClass : AbstractClass
{
    public override void AbtractMethod() { Console.WriteLine("Abstract Method Implementation"); }
    public override void VirtualMethod() { Console.WriteLine("Virtual Method in ImplementingClass"); }
}

public static class StaticClass
{
    public static string StaticString = "Static String";
    public static void StaticMethod() { Console.WriteLine("Static Method"); }
}

public sealed class SealedClass { }

// Compilation error: Cannot derive from sealed type 'SealedClass'
// public class DerivedSealedClass : SealedClass { }

public class Task
{
    public static void Main(string[] args)
    {
        PublicClass publicObj = new PublicClass();
        publicObj.PublicMethod();

        InternalClassChild internalObj = new InternalClassChild();
        internalObj.CallProtectedMethod();
        internalObj.InvokeParentProtectedMehtod();

        ImplementingClass implementingObj = new ImplementingClass();
        implementingObj.AbtractMethod();
        implementingObj.VirtualMethod();

        Console.WriteLine(StaticClass.StaticString);
        StaticClass.StaticMethod();
    }
}

