namespace Bugzilla26032
{
    public class InteractiveListPage : ContentPage
    {
        private ListView List1;
        private ListView List2;
        private Label Log;

        public InteractiveListPage()
        {
            Title = "Interactive List";

            List1 = new ListView();
            List2 = new ListView();
            Log = new Label { VerticalOptions = LayoutOptions.StartAndExpand };

            var items1 = new List<string> { "Item 1A", "Item 1B", "Item 1C" };
            var items2 = new List<string> { "Item 2A", "Item 2B", "Item 2C" };

            List1.ItemsSource = items1;
            List2.ItemsSource = items2;

            List1.ItemTapped += OnItemTapped;
            List2.ItemTapped += OnItemTapped;

            var stackLayout = new StackLayout
            {
                Children = { List1, List2, Log },
                Padding = new Thickness(10)
            };

            Content = stackLayout;
        }

        private void OnItemTapped(object sender, ItemTappedEventArgs e)
        {
            if (e.Item != null)
            {
                var tappedItem = e.Item.ToString();
                Log.Text = $"Tapped: {tappedItem}";
                ((ListView)sender).SelectedItem = null; // Deselect item
            }
        }

        private void OnItemSelected(object sender, SelectedItemChangedEventArgs e)
        {
            if (e.SelectedItem != null)
            {
                var selectedItem = e.SelectedItem.ToString();
                Log.Text = $"Selected: {selectedItem}";
                ((ListView)sender).SelectedItem = null; // Deselect item
            }
        }
    }

