        {
            // Dummy check: returns true if workload min is nearly equal to overhead max.
            return (workloadStats.Min - overheadStats.Max) < 1e-9;
        }

        public static bool CheckZeroMeasurementOneSample(Statistics workloadStats, TimeInterval threshold)
        {
            // Dummy check: returns true if workload mean is lower than the threshold in seconds.
            return workloadStats.Mean < threshold.Seconds;
        }
