namespace RoutingFramework
{
    [Serializable]
    public class RoutingPatternException : Exception
    {
        // Read-only property holding the raw routing pattern.
        public string RawRoutingPattern { get; }

        // Constructor accepting an error message and the raw routing pattern.
        public RoutingPatternException(string message, string rawRoutingPattern)
            : base(message)
        {
            if (rawRoutingPattern == null)
            {
                throw new ArgumentNullException(nameof(rawRoutingPattern));
            }
            RawRoutingPattern = rawRoutingPattern;
        }

        // Constructor accepting an error message, the raw routing pattern, and an inner exception.
        public RoutingPatternException(string message, string rawRoutingPattern, Exception innerException)
            : base(message, innerException)
        {
            if (rawRoutingPattern == null)
            {
                throw new ArgumentNullException(nameof(rawRoutingPattern));
            }
            RawRoutingPattern = rawRoutingPattern;
        }

        // Serialization constructor used during deserialization.
        protected RoutingPatternException(SerializationInfo info, StreamingContext context)
            : base(info, context)
        {
            if (info == null)
            {
                throw new ArgumentNullException(nameof(info));
            }
            RawRoutingPattern = info.GetString("RawRoutingPattern")
                ?? throw new SerializationException("Missing RawRoutingPattern data.");
        }

        // Override to include additional data during serialization.
        public override void GetObjectData(SerializationInfo info, StreamingContext context)
        {
            if (info == null)
            {
                throw new ArgumentNullException(nameof(info));
            }
            info.AddValue("RawRoutingPattern", RawRoutingPattern);
            base.GetObjectData(info, context);
        }
    }

