public class AccountController : ApiController
{
    private IAuthRepository _authRepository;

    public AccountController(IAuthRepository authRepository)
    {
        _authRepository = authRepository;
    }

    [HttpPost]
    [Route("api/account/register")]
    public async Task<IHttpActionResult> Register(UserModel userModel)
    {
        if (!ModelState.IsValid)
        {
            return BadRequest(GetErrorResult(ModelState));
        }

        var result = await _authRepository.RegisterUser(userModel);
        if (!result.Succeeded)
        {
            return GetErrorResult(result.Errors);
        }

        return Ok("Registration successful");
    }

    protected override void Dispose(bool disposing)
    {
        if (disposing)
        {
            _authRepository = null; // Dispose of the repository if needed
        }
        base.Dispose(disposing);
    }

    private IHttpActionResult GetErrorResult(IEnumerable<string> errors)
    {
        if (errors == null)
        {
            return InternalServerError();
        }

        var errorResponse = new List<string>(errors);
        return ResponseMessage(Request.CreateResponse(HttpStatusCode.BadRequest, errorResponse));
    }

    private IHttpActionResult GetErrorResult(ModelStateDictionary modelState)
    {
        var errors = new List<string>();
        foreach (var state in modelState)
        {
            foreach (var error in state.Value.Errors)
            {
                errors.Add(error.ErrorMessage);
            }
        }
        return GetErrorResult(errors);
    }
}

