namespace MessageBrokerService
{
    public partial class MessageBroker : ServiceBase
    {
        private ServiceHost messageBrokerServiceHost;
        private ILog log;

        public MessageBroker()
        {
            InitializeComponent();
            log = LogManager.GetLogger(typeof(MessageBroker));
        }

        protected override void OnStart(string[] args)
        {
            try
            {
                log.Info("Message Broker Service is starting...");

                // Configure service host
                string serviceName = ConfigurationManager.AppSettings["ServiceEndpointName"];
                string baseAddress = ConfigurationManager.AppSettings["ServiceBaseAddress"];

                messageBrokerServiceHost = new ServiceHost(typeof(MessageBrokerService), new Uri(baseAddress));

                // Add service endpoint
                messageBrokerServiceHost.AddServiceEndpoint(
                    typeof(IMessageBrokerContract),
                    new NetTcpBinding(),
                    serviceName
                );

                // Enable metadata exchange
                ServiceMetadataBehavior metadataBehavior = new ServiceMetadataBehavior();
                messageBrokerServiceHost.Description.Behaviors.Add(metadataBehavior);

                // Open service host
                messageBrokerServiceHost.Open();

                log.Info("Message Broker Service successfully started.");
            }
            catch (Exception ex)
            {
                log.Error("Error starting Message Broker Service", ex);
                throw;
            }
        }

        protected override void OnStop()
        {
            try
            {
                log.Info("Message Broker Service is stopping...");

                if (messageBrokerServiceHost != null)
                {
                    messageBrokerServiceHost.Close();
                    messageBrokerServiceHost = null;
                }

                log.Info("Message Broker Service successfully stopped.");
            }
            catch (Exception ex)
            {
                log.Error("Error stopping Message Broker Service", ex);

                // Force service host closure
                if (messageBrokerServiceHost != null)
                {
                    messageBrokerServiceHost.Abort();
                }
            }
        }

