using System;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.Options;

public abstract class IncrementalAnalyzerBase
{
    protected readonly AnalyzerOptions AnalyzerOptions;

    protected IncrementalAnalyzerBase(AnalyzerOptions options = null)
    {
        AnalyzerOptions = options ?? AnalyzerOptions.Default;
    }

    public virtual async Task<Solution> NewSolutionSnapshotAsync(
        Solution currentSolution,
        Solution newSolution,
        CancellationToken cancellationToken)
    {
        return await Task.FromResult(newSolution);
    }

    public virtual async Task DocumentOpenAsync(
        Document document,
        CancellationToken cancellationToken)
    {
        await Task.CompletedTask;
    }

    public virtual async Task DocumentCloseAsync(
        Document document,
        CancellationToken cancellationToken)
    {
        await Task.CompletedTask;
    }

    public virtual async Task DocumentResetAsync(
        Document document,
        CancellationToken cancellationToken)
    {
        await Task.CompletedTask;
    }

    public virtual async Task<SyntaxNode> AnalyzeSyntaxAsync(
        SyntaxNode syntaxNode,
        CancellationToken cancellationToken)
    {
        return await Task.FromResult(syntaxNode);
    }

    public virtual async Task<Document> AnalyzeDocumentAsync(
        Document document,
        InvocationReasons reasons,
        CancellationToken cancellationToken)
    {
        if (cancellationToken.IsCancellationRequested)
        {
            return document;
        }

        var analyzedSyntax = await AnalyzeSyntaxAsync(
            await document.GetSyntaxRootAsync(cancellationToken),
            cancellationToken);

        return document.WithSyntaxRoot(analyzedSyntax);
    }

    public virtual async Task<Project> AnalyzeProjectAsync(
        Project project,
        InvocationReasons reasons,
        CancellationToken cancellationToken)
    {
        var updatedDocuments = new List<Document>();

        foreach (var document in project.Documents)
        {
            var analyzedDocument = await AnalyzeDocumentAsync(
                document,
                reasons,
                cancellationToken);

            updatedDocuments.Add(analyzedDocument);
        }

        return project.WithDocuments(updatedDocuments);
    }

    protected virtual bool ShouldAnalyze(
        InvocationReasons reasons,
        AnalyzerOptions options)
    {
        return reasons != InvocationReasons.None;
    }
}

