using BenchmarkDotNet.Analysers;
using BenchmarkDotNet.Engines;
using BenchmarkDotNet.Extensions;
using BenchmarkDotNet.Horology;
using BenchmarkDotNet.Reports;
using System.Collections.Generic;
using System.Linq;

public class ZeroMeasurementAnalyser : AnalyserBase
{
    protected override IEnumerable<Conclusion> AnalyseReport(BenchmarkReport report, Summary summary)
    {
        var currentFrequency = Frequency.Get();
        Frequency fallbackFrequency = Frequency.FromResolution(TimeInterval. nanosecond * 10);

        var overheadMeasurements = report.AllMeasurements.Where(m => m.Is(IterationMode.Overhead)).ToList();
        var workloadMeasurements = report.AllMeasurements.Where(m => m.Is(IterationMode.Workload)).ToList();

        if (overheadMeasurements.Any() && workloadMeasurements.Any())
        {
            var statisticsOverhead = GetStatistics(overheadMeasurements);
            var statisticsWorkload = GetStatistics(workloadMeasurements);
            if (CheckZeroMeasurementTwoSamples(statisticsWorkload, statisticsOverhead, currentFrequency, fallbackFrequency))
            {
                yield return Conclusion.Warning(
                    "ZeroMeasurement",
                    "Workload duration is indistinguishable from overhead. Results cannot be trusted.");
            }
        }
        else if (workloadMeasurements.Any())
        {
             TimeInterval threshold = (currentFrequency ?? fallbackFrequency).ToResolution();

            var statisticsWorkload = GetStatistics(workloadMeasurements);

             if(CheckZeroMeasurementOneSample(statisticsWorkload,threshold))
             {
                 yield return Conclusion.Warning("ZeroMeasurement",$"Workload duration {statisticsWorkload.Mean} is too short compare to the frequence {threshold}");
             }
        }

    }
    private bool CheckZeroMeasurementTwoSamples(Statistics workload, Statistics overhead, Frequency? currentFrequency, Frequency fallbackFrequency)
        => workload.Mean <= overhead.Mean;

     private bool CheckZeroMeasurementOneSample(Statistics workload, TimeInterval threshold)
        => workload.Mean <= threshold.Nanoseconds;
    private Statistics GetStatistics(List<Measurement> measurements) =>
        new Statistics(measurements.WithoutOutliers().Select(m => m.GetAverageTime().Nanoseconds));
}

