namespace ResistorMesh
{
    class ResistorMesh
    {
        private const int S = 10;
 
        private class Node
        {
            public double v;
            public int fixed;
 
            public Node(double v, int fixed)
            {
                this.v = v;
                this.fixed = fixed;
            }
        }
 
        private static void setBoundary(List<List<Node>> m)
        {
            m[1][1].v = 1.0;
            m[1][1].fixed = 1;
 
            m[6][7].v = -1.0;
            m[6][7].fixed = -1;
        }
 
        private static double calcDiff(List<List<Node>> m, List<List<Node>> d, int w, int h)
        {
            double total = 0.0;
            for (int i = 0; i < h; ++i)
            {
                for (int j = 0; j < w; ++j)
                {
                    double v = 0.0;
                    int n = 0;
                    if (i > 0)
                    {
                        v += m[i - 1][j].v;
                        n++;
                    }
                    if (j > 0)
                    {
                        v += m[i][j - 1].v;
                        n++;
                    }
                    if (i + 1 < h)
                    {
                        v += m[i + 1][j].v;
                        n++;
                    }
                    if (j + 1 < w)
                    {
                        v += m[i][j + 1].v;
                        n++;
                    }
                    v = m[i][j].v - v / n;
                    d[i][j].v = v;
                    if (m[i][j].fixed == 0)
                    {
                        total += v * v;
                    }
                }
            }
            return total;
        }
 
        private static double iter(List<List<Node>> m, int w, int h)
        {
            List<List<Node>> d = new List<List<Node>>(h);
            for (int i = 0; i < h; ++i)
            {
                List<Node> t = new List<Node>(w);
                for (int j = 0; j < w; ++j)
                {
                    t.Add(new Node(0.0, 0));
                }
                d.Add(t);
            }
 
            double[] cur = new double[3];
            double diff = 1e10;
 
            while (diff > 1e-24)
            {
                setBoundary(m);
                diff = calcDiff(m, d, w, h);
                for (int i = 0; i < h; ++i)
                {
                    for (int j = 0; j < w; ++j)
                    {
                        m[i][j].v -= d[i][j].v;
                    }

using System;
using System.IO;

public class WritingSystemDefinition {
    public string Template { get; set; }
}
public class LdmlDataMapper
{
    public T Read<T>(string path) where T : WritingSystemDefinition, new()
    {
        //Simulate reading and deserializing from LDML file.
        T ws = new T();
        ws.Template = path;
        return ws;
    }
}
public enum SldrStatus {
    FromSldr,
    FromCache,
    NotFound
}

public abstract class WritingSystemFactory<T> where T: WritingSystemDefinition, new() {
    protected abstract T ConstructDefinition(string ietfLanguageTag, out SldrStatus status);

    public T Create(string ietfLanguageTag) {
        return ConstructDefinition(ietfLanguageTag, out _);
    }
}

public class SldrWritingSystemFactory<T> : WritingSystemFactory<T> where T: WritingSystemDefinition, new() {
    public string SldrCachePath { get; set; } = "sldrCache";

    protected override T ConstructDefinition(string ietfLanguageTag, out SldrStatus sldrStatus) {
        if (!Directory.Exists(SldrCachePath)) {
            Directory.CreateDirectory(SldrCachePath);
        }

        string templatePath = GetLdmlFile(ietfLanguageTag, out sldrStatus);

        if (!string.IsNullOrEmpty(templatePath))
        {
            LdmlDataMapper dataMapper = new LdmlDataMapper();
            T ws = dataMapper.Read<T>(templatePath);
            return ws;
        }

        // Fallback to base class creation if not found in SLDR.
        return base.ConstructDefinition(ietfLanguageTag, out sldrStatus);
    }

    private string GetLdmlFile(string ietfLanguageTag, out SldrStatus status)
    {
        string filename = $"{ietfLanguageTag}.ldml";
        string cachedPath = Path.Combine(SldrCachePath, filename);

        //Simulate fetching from SLDR
        string sldrPath = GetLdmlFromSldr(ietfLanguageTag);

        if (!string.IsNullOrEmpty(sldrPath))
        {
           status = SldrStatus.FromSldr;
           //Copy from "sldr" to local cache
           File.Copy(sldrPath, cachedPath, true);
           return cachedPath;
        }
        else if (File.Exists(cachedPath)) {
            status = SldrStatus.FromCache;
            return cachedPath;
        } else {
            status = SldrStatus.NotFound;
            return null;
        }
    }

    private string GetLdmlFromSldr(string languageTag)
    {
        //Simulate connection to the online repository.
        if (languageTag == "en")
        {
            return "sldr/en.ldml"; //Simulate found on sldr
        }

        return null; //Simulate not found.
    }
}

