public class ToastForm : Form
{
    private Timer timer;
    private int startPosX;
    private int startPosY;
    private Label pageLinkLabel;

    public ToastForm(string url)
    {
        InitializeForm();
        InitializeLinkLabel(url);
    }

    private void InitializeForm()
    {
        this.FormBorderStyle = FormBorderStyle.None;
        this.BackColor = Color.LightGray;
        this.Size = new Size(300, 100);
        this.StartPosition = FormStartPosition.Manual;
        this.TopMost = true;
        this.ShowInTaskbar = false;

        startPosX = Screen.PrimaryScreen.WorkingArea.Width - this.Width;
        startPosY = Screen.PrimaryScreen.WorkingArea.Height;
        this.Location = new Point(startPosX, startPosY);

        timer = new Timer();
        timer.Interval = 10;
        timer.Tick += Timer_Tick;
    }

    private void InitializeLinkLabel(string url)
    {
        pageLinkLabel = new Label();
        pageLinkLabel.Text = url;
        pageLinkLabel.AutoSize = true;
        pageLinkLabel.Location = new Point(10, 10);
        pageLinkLabel.Cursor = Cursors.Hand;
        pageLinkLabel.Click += PageLinkLabel_Click;
        this.Controls.Add(pageLinkLabel);
    }

    private void Timer_Tick(object sender, EventArgs e)
    {
        if (this.Location.Y > startPosY - this.Height)
        {
            this.Location = new Point(startPosX, this.Location.Y - 1);
        }
        else
        {
            timer.Stop();
        }
    }

    private void PageLinkLabel_Click(object sender, EventArgs e)
    {
        Process.Start(pageLinkLabel.Text);
        this.Close();
    }

    protected override void OnLoad(EventArgs e)
    {
        base.OnLoad(e);
        timer.Start();
    }

    protected override void OnClick(EventArgs e)
    {
        base.OnClick(e);
        this.Close();
    }
}

