namespace FluentMigrator.Runner.Generators.SQLite
{
    public class SQLiteColumnGenerator : ColumnGeneratorBase
    {
        private readonly IQuoter _quoter;

        public SQLiteColumnGenerator(IQuoter quoter) : base(quoter)
        {
            _quoter = quoter;
        }

        public override string FormatIdentity(ColumnDefinition column)
        {
            if (column.IsIdentity)
            {
                if (column.Type != DbType.Int32 && column.Type != DbType.Int64)
                    throw new ArgumentException("SQLite identity columns must be Integer types.");

                return "AUTOINCREMENT";
            }
            return string.Empty;
        }

        public override bool ShouldPrimaryKeysBeAddedSeparately(ColumnDefinition column)
        {
            return column.IsPrimaryKey && !column.IsIdentity;
        }

        public override string FormatPrimaryKey(ColumnDefinition column)
        {
            if (column.IsPrimaryKey)
            {
                return "PRIMARY KEY";
            }
            return string.Empty;
        }

        public override string FormatSystemMethods(SystemMethods systemMethod)
        {
            switch (systemMethod)
            {
                case SystemMethods.NewGuid:
                    return "HEX(RANDOMBLOB(16))";
                case SystemMethods.CurrentDateTime:
                    return "DATETIME('now')";
                case SystemMethods.CurrentUTCDateTime:
                    return "DATETIME('now', 'utc')";
                default:
                    return base.FormatSystemMethods(systemMethod);
            }
        }

        protected override string GetPrimaryKeyConstraintName(ColumnDefinition column)
        {
            return string.Empty;
        }

        protected override string GetTypeForSpecificDbType(DbType type, int? precision, int? scale, int? size)
        {
            switch (type)
            {
                case DbType.Binary:
                    return "BLOB";
                case DbType.Object:
                    return "BLOB";
                case DbType.Xml:
                    return "TEXT";
                default:
                    return base.GetTypeForSpecificDbType(type, precision, scale, size);
            }
        }
    }
}

