            {
                return File.ReadAllText(filename);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error reading file: {ex.Message}");
                return string.Empty;
            }
        }

        private void ProcessInstructions()
        {
            bool isSantaTurn = true;

            for (int i = 0; i < instructions.Length; i++)
            {
                Point currentPoint = isSantaTurn ? santa : robot;

                switch (instructions[i])
                {
                    case '^':
                        currentPoint.Y++;
                        break;
                    case 'v':
                        currentPoint.Y--;
                        break;
                    case '>':
                        currentPoint.X++;
                        break;
                    case '<':
                        currentPoint.X--;
                        break;
                }

                if (isSantaTurn)
                    santa = currentPoint;
                else
                    robot = currentPoint;

                visitedPoints.Add(currentPoint);
                isSantaTurn = !isSantaTurn;
            }
        }

        private void DisplayResults()
        {
            Console.WriteLine($"Total Unique Locations: {visitedPoints.Count}");
        }

