[Config(typeof(MultipleRuntimes))]
public class MapObjectBenchmark
{
    private MapFrom mapFrom;
    private IMapper automapper;
    private BoilerplateMapper boilerplateMapper;
    private Random random;

    [GlobalSetup]
    public void Setup()
    {
        random = new Random();
        mapFrom = new MapFrom
        {
            Id = random.Next(),
            Name = Guid.NewGuid().ToString(),
            Value = random.NextDouble()
        };

        var config = new MapperConfiguration(cfg => cfg.CreateMap<MapFrom, MapTo>());
        automapper = config.CreateMapper();
        boilerplateMapper = new BoilerplateMapper();
    }

    [Benchmark(Baseline = true)]
    public MapTo Baseline()
    {
        return new MapTo
        {
            Id = mapFrom.Id,
            Name = mapFrom.Name,
            Value = mapFrom.Value
        };
    }

    [Benchmark]
    public MapTo BoxedMapper()
    {
        return boilerplateMapper.Map(mapFrom);
    }

    [Benchmark]
    public MapTo Automapper()
    {
        return automapper.Map<MapTo>(mapFrom);
    }
}

public class MultipleRuntimes : ManualConfig
{
    public MultipleRuntimes()
    {
        AddJob(Job.ShortRun.WithRuntime(BenchmarkDotNet.Environments.Runtime.Core60));
        AddJob(Job.ShortRun.WithRuntime(BenchmarkDotNet.Environments.Runtime.Core80));
    }
}

