using Newtonsoft.Json;
using System;

public class BillItem : ValueObject<BillItem>
{
    [JsonProperty("quantity")]
    public int Quantity { get; private set; }

    [JsonProperty("price")]
    public decimal Price { get; private set; }

    [JsonProperty("storehouseItemId")]
    public Guid StorehouseItemId { get; private set; }

    private BillItem(int quantity, decimal price, Guid storehouseItemId)
    {
        Quantity = quantity;
        Price = price;
        StorehouseItemId = storehouseItemId;
    }

    public static BillItem Create(int quantity, decimal price, Guid storehouseItemId, int storehouseItemQuantity)
    {
        if (quantity <= 0)
            throw new ArgumentException("Quantity must be greater than zero.", nameof(quantity));

        if (price <= 0)
            throw new ArgumentException("Price must be greater than zero.", nameof(price));

        if (quantity > storehouseItemQuantity)
            throw new ArgumentException("Quantity exceeds available stock.", nameof(quantity));

        return new BillItem(quantity, price, storehouseItemId);
    }

    public void AddQuantity(int additionalQuantity, int storehouseItemQuantity)
    {
        if (additionalQuantity <= 0)
            throw new ArgumentException("Additional quantity must be greater than zero.", nameof(additionalQuantity));

        if (Quantity + additionalQuantity > storehouseItemQuantity)
            throw new ArgumentException("Total quantity exceeds available stock.", nameof(additionalQuantity));

        Quantity += additionalQuantity;
    }

    protected override bool EqualsCore(BillItem other)
    {
        return Quantity == other.Quantity &&
               Price == other.Price &&
               StorehouseItemId == other.StorehouseItemId;
    }

    protected override int GetHashCodeCore()
    {
        unchecked
        {
            int hash = 17;
            hash = hash * 23 + Quantity.GetHashCode();
            hash = hash * 23 + Price.GetHashCode();
            hash = hash * 23 + StorehouseItemId.GetHashCode();
            return hash;
        }
    }
}

public abstract class ValueObject<T> where T : ValueObject<T>
{
    public override bool Equals(object obj)
    {
        if (obj == null || obj.GetType() != GetType())
        {
            return false;
        }

        var other = (T)obj;
        return EqualsCore(other);
    }

    public override int GetHashCode()
    {
        return GetHashCodeCore();
    }

    protected abstract bool EqualsCore(T other);
