        {
            ulong n0 = @this.ReadULong();
            ulong n1 = @this.ReadULong();
            ulong typeCodeData = @this.ReadULong();
            string keyExt = @this.ReadString();
            return UniqueKey.NewKey(n0, n1, typeCodeData, keyExt);
        }

