namespace BatchCommandExecutor
{
    public interface IConsoleCommand
    {
        void Execute(string[] args);
    }

    public class BatchCommand : IConsoleCommand
    {
        public void Execute(string[] args)
        {
            if (args.Length < 1)
            {
                Console.WriteLine("Usage: BatchCommand <commands_file>");
                return;
            }

            string fileName = args[0];

            try
            {
                if (!File.Exists(fileName))
                {
                    Console.WriteLine($"File not found: {fileName}");
                    return;
                }

                string[] commands = File.ReadAllLines(fileName);
                List<Task> tasks = new List<Task>();

                foreach (var command in commands.Where(c => !string.IsNullOrWhiteSpace(c)))
                {
                    tasks.Add(RunBatchCommand(command));
                }

                Task.WaitAll(tasks.ToArray());
            }
            catch (Exception ex)
            {
                Console.WriteLine($"An error occurred: {ex.Message}");
            }
        }

        private async Task RunBatchCommand(string command)
        {
            string[] parameters = command.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);

            if (parameters.Length == 0)
                return;

            string opName = parameters[0];
            string[] filteredArgs = parameters.Skip(1).ToArray();

            try
            {
                switch (opName.ToLower())
                {
                    case "copytable":
                        await CopyTableAsync(filteredArgs);
                        break;
                    case "deletetable":
                        await DeleteTableAsync(filteredArgs);
                        break;
                    case "updatetable":
                        await UpdateTableAsync(filteredArgs);
                        break;
                    default:
                        Console.WriteLine($"Unknown command: {opName}");
                        break;
                }
            }
            catch (Exception ex)
            {
                LogError(opName, ex);
            }
        }

        private Task CopyTableAsync(string[] args)
        {
            // Simulated copy table method
            Console.WriteLine($"Copying table with args: {string.Join(", ", args)}");
            return Task.CompletedTask;

