namespace ArangoDB.Remotion.Linq.Clauses.Expressions
{
    public class SkipExpressionNode : ResultOperatorExpressionNode
    {
        public Expression Count { get; private set; }

        public SkipExpressionNode(MethodCallExpression expression, Expression count)
            : base(expression)
        {
            Count = count;
        }

        public override Expression Resolve(
            ParameterExpression inputParameter,
            Expression expressionToBeResolved,
            ClauseGenerationContext clauseGenerationContext)
        {
            Utils.CheckNotNull("inputParameter", inputParameter);
            Utils.CheckNotNull("expressionToBeResolved", expressionToBeResolved);
            Utils.CheckNotNull("clauseGenerationContext", clauseGenerationContext);

            return Source.Resolve(inputParameter, expressionToBeResolved, clauseGenerationContext);
        }

        protected override ResultOperatorBase CreateResultOperator(ClauseGenerationContext clauseGenerationContext)
        {
            return new SkipResultOperator(Count);
        }
    }

    internal class SkipResultOperator : ResultOperatorBase
    {
        public Expression Count { get; private set; }

        public SkipResultOperator(Expression count)
        {
            Count = count;
        }

        public override ResultOperatorBase Clone(CloneContext cloneContext)
        {
            return new SkipResultOperator(Count);
        }

        public override void TransformExpressions(Func<Expression, Expression> transformation)
        {
            Utils.CheckNotNull("transformation", transformation);
            Count = transformation(Count);
        }

        public override string ToString()
        {
            return "Skip(" + Count + ")";
        }
    }
}

