namespace PythonToolsForVisualStudio
{
    public static class WorkspaceInterpreterFactoryConstants
    {
        // Constants for executable names
        public const string ConsoleExecutable = "python.exe";
        public const string WindowsExecutable = "pythonw.exe";

        // Constants for library paths and environment variables
        public const string LibrarySubPath = "Lib";
        public const string PathEnvironmentVariableName = "PATH";

        // Internal constants for factory provider and environment company
        internal const string FactoryProviderName = "PTVS";
        internal const string EnvironmentCompanyName = "Microsoft";

        // Regular expression to parse interpreter IDs
        private static readonly Regex IdParser = new Regex(
            $"^{Regex.Escape(FactoryProviderName)}\\|{Regex.Escape(EnvironmentCompanyName)}\\|(?<Tag>.+)$",
            RegexOptions.Compiled | RegexOptions.IgnoreCase);

        // Method to generate a unique interpreter ID
        public static string GetInterpreterId(string tag)
        {
            if (string.IsNullOrEmpty(tag))
                throw new ArgumentException("Tag cannot be null or empty", nameof(tag));

            return $"{FactoryProviderName}|{EnvironmentCompanyName}|{tag}";
        }

        // Method to parse an interpreter ID into its components
        public static bool TryParseInterpreterId(string interpreterId, out string provider, out string company, out string tag)
        {
            provider = null;
            company = null;
            tag = null;

            var match = IdParser.Match(interpreterId);
            if (!match.Success)
                return false;

            provider = FactoryProviderName;
            company = EnvironmentCompanyName;
            tag = match.Groups["Tag"].Value;

            return true;
        }
    }
}

