{
    private Asn1SequenceParser _seq;
    private DerInteger _version;
    private IAsn1Convertible _nextObject;

    public EnvelopedDataParser(Asn1SequenceParser seq)
    {
        _seq = seq;
        _version = (DerInteger)_seq.ReadObject();
    }

    public DerInteger Version => _version;

    public OriginatorInfo GetOriginatorInfo()
    {
        if (_nextObject == null)
        {
            _nextObject = _seq.ReadObject();
        }

        if (_nextObject is Asn1TaggedObjectParser taggedObject && taggedObject.TagNo == 0)
        {
            OriginatorInfo originatorInfo = OriginatorInfo.GetInstance(taggedObject.GetObjectParser(DerSequenceParser.Tag, false));
            _nextObject = null;
            return originatorInfo;
        }

        return null;
    }

    public RecipientInfo[] GetRecipientInfos()
    {
        if (_nextObject == null)
        {
            _nextObject = _seq.ReadObject();
        }

        Asn1SetParser recipientInfos = (Asn1SetParser)_nextObject;
        _nextObject = null;

        List<RecipientInfo> recipientInfoList = new List<RecipientInfo>();
        IAsn1Convertible recipientInfoObj;
        while ((recipientInfoObj = recipientInfos.ReadObject()) != null)
        {
            RecipientInfo recipientInfo = RecipientInfo.GetInstance(recipientInfoObj.ToAsn1Object());
            recipientInfoList.Add(recipientInfo);
        }

        return recipientInfoList.ToArray();
    }

    public EncryptedContentInfoParser GetEncryptedContentInfo()
    {
        if (_nextObject == null)
        {
            _nextObject = _seq.ReadObject();
        }

        EncryptedContentInfoParser encryptedContentInfo = new EncryptedContentInfoParser((Asn1SequenceParser)_nextObject);
        _nextObject = null;
        return encryptedContentInfo;
    }

    public Asn1Set GetUnprotectedAttrs()
    {
        if (_nextObject == null)
        {
            _nextObject = _seq.ReadObject();
        }

