    public interface IMansionContext
    {
        // Define any context properties or methods specific to Mansion context
        string GetContextInfo();
    }

    public interface IProcessor<TInput>
    {
        void Process(TInput input);
    }

    public interface IProcessor<TContext, TInput> where TContext : IMansionContext
    {
        void Process(TContext context, TInput input);
    }

    public interface IProcessor<TContext, TInput, TOutput> where TContext : IMansionContext
    {
        TOutput Process(TContext context, TInput input);
    }

    public class StringContext : IMansionContext
    {
        public string GetContextInfo()
        {
            return "String processing context";
        }
    }

    public class JsonProcessor : IProcessor<StringContext, string>
    {
        public void Process(StringContext context, string input)
        {
            Console.WriteLine($"Processing JSON: {input} in context: {context.GetContextInfo()}");
            // Perform JSON processing logic here
        }
    }

    public class DataTransformer : IProcessor<StringContext, string, string>
    {
        public string Process(StringContext context, string input)
        {
            Console.WriteLine($"Transforming data: {input} in context: {context.GetContextInfo()}");
            // Example transformation logic
            return input.ToUpper();
        }
    }

    class Matrix
    {
        static void Main(string[] args)
        {
            var jsonProcessor = new JsonProcessor();
            var context = new StringContext();
            jsonProcessor.Process(context, "{\"key\":\"value\"}");

            var transformer = new DataTransformer();
            string result = transformer.Process(context, "some data");
            Console.WriteLine($"Transformed data: {result}");
        }
    }
}

 
