    public class ChangeMaterialColor : BTNode
    {
        // Explicit material reference (can be null).
        public Material targetMaterial;

        // New color value to apply.
        public Color newColor = Color.white;

        // Reference to the game object that owns this behavior.
        // In a realistic scenario, this could be set by the behavior tree system.
        private GameObject owner;

        // Default constructor (initializes owner to a default GameObject).
        public ChangeMaterialColor(GameObject owner)
        {
            this.owner = owner;
            Reset();
        }

        // Reset the variables to default instances.
        public void Reset()
        {
            targetMaterial = null;
            newColor = Color.white;
        }

        // Main execution logic for the behavior node.
        public override BTStatus Update()
        {
            // Attempt to retrieve material if none explicitly provided.
            if (targetMaterial == null)
            {
                Renderer renderer = owner.GetComponent<Renderer>();
                if (renderer != null)
                {
                    targetMaterial = renderer.material;
                }
                else
                {
                    Debug.LogError("ChangeMaterialColor: No Renderer found on game object.");
                    return BTStatus.Failure;
                }
            }

            // Validate that the target material is not null.
            if (targetMaterial == null)
            {
                Debug.LogError("ChangeMaterialColor: Material reference is null.");
                return BTStatus.Failure;
            }

            // Validate newColor (optional check, here assumed always valid).
            // In a more detailed system, you might check for specific color constraints.
            // Apply the new color to the material's main color property.
            targetMaterial.color = newColor;

            // Log the change.
            Debug.Log("ChangeMaterialColor: Material color updated successfully to " + newColor.ToString());

            // Return success status.
            return BTStatus.Success;
        }
    }

