using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace Reader
{
    class Stack
    {
        static void Main(string[] args)
        {
            var pal23 = new Enumerator(y =>
            {
                y.yield(0);
                y.yield(1);
                for (int i = 1; i < 1.0 / 0.0; i++)
                {
                    var n3 = i.ToString(3);
                    var n = (n3 + "1" + new string(n3.Reverse().ToArray())).ToNumber(3);
                    var n2 = n.ToString(2);
                    if (n2.Length % 2!= 0 && n2 == new string(n2.Reverse().ToArray()))
                        y.yield(n);
                }
            });

            Console.WriteLine("         decimal          ternary                          binary");
            for (int i = 0; i < 6; i++)
            {
                var n = pal23.next();
                Console.WriteLine("{0}: {1,12} {2,25} {3,39}", i, n, n.ToString(3).PadLeft(12), n.ToString(2).PadLeft(12));
            }
        }
    }

    public class Enumerator
    {
        private Action<Enumerator> _action;
        private int _index = -1;
        private List<int> _list = new List<int>();

        public Enumerator(Action<Enumerator> action)
        {
            _action = action;
            _action(this);
        }

        public int next()
        {
            if (_index < _list.Count - 1)
                return _list[++_index];
            else
            {
                _index++;
                _action(this);
                return _list[_index];
            }
        }

        public void yield(int value)
        {
            _list.Add(value);
        }
    }

    public static class Extensions
    {
        public static int ToNumber(this string str, int fromBase)
        {
            return str.Aggregate(0, (current, c) => current * fromBase + c - '0');
        }
    }
}

