    public static class AudioEffectExtension
    {
        /// <summary>
        /// Initializes the audio effect with the specified audio source.
        /// </summary>
        /// <param name="effect">The audio effect to be configured.</param>
        /// <param name="source">The audio source with which the effect will be associated.</param>
        /// <returns>The initialized audio effect instance.</returns>
        public static AudioEffect FluentInitialize(this AudioEffect effect, AudioSource source)
        {
            if (effect == null) throw new ArgumentNullException(nameof(effect));
            if (source == null) throw new ArgumentNullException(nameof(source));

            effect.SetAudioSource(source);
            effect.Initialize();
            return effect;
        }
    }

