using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
 
namespace WordCount
{
    class Helper
    {
        static void Main(string[] args)
        {
            WordCount("135-0.txt", 10);
        }
 
        static void WordCount(string file, int n)
        {
            var wordRegex = new Regex("(?i)[a-z']+");
 
            var words = new Dictionary<string, int>();
            foreach (var line in File.ReadLines(file))
            {
                wordRegex
                   .Matches(line)
                   .Cast<Match>()
                   .Select(m => m.Value)
                   .ToList()
                   .ForEach(word =>
                    {
                        if (words.ContainsKey(word.ToLower()))
                        {
                            words[word.ToLower()]++;
                        }
                        else
                        {
                            words.Add(word.ToLower(), 1);
                        }
                    });
            }
 
            var sortedWords = words.OrderByDescending(x => x.Value).ThenBy(x => x.Key);
 
            foreach (var word in sortedWords.Take(n))
            {
                Console.WriteLine($"{word.Key,8} {word.Value,8}");
            }
        }
    }
}

