public class Dinas : SolidBlock
{
    public Dinas(int id, GameObject parentObject, GameObject blockObject)
        : base(id, parentObject, blockObject)
    {
        initBlock("dinas", "structure");

        transmissivity = 7.85f;
    }

    public override Block clone(GameObject parentObject, BlocksManager blocksManager, GameObject blockObject)
    {
        Dinas block = new Dinas(blockId, parentObject, blockObject);
        block.initSolidBlock(blocksManager, "lava", 1535, 1750);
        return block;
    }

    public override void updata(BlocksEngine blocksEngine)
    {
        base.updata(blocksEngine);
        dinasMoveRule(blocksEngine);
        if (dinasReduceRule(blocksEngine)) return;
    }

    protected virtual bool dinasReduceRule(BlocksEngine blocksEngine)
    {
        if (temperature > 600)
        {
            if (dinasReduceMethod(blocksEngine, Dir.up)) return true;
            if (dinasReduceMethod(blocksEngine, Dir.left)) return true;
            if (dinasReduceMethod(blocksEngine, Dir.down)) return true;
            if (dinasReduceMethod(blocksEngine, Dir.right)) return true;
        }
        return false;
    }

    protected virtual bool dinasReduceMethod(BlocksEngine blocksEngine, int dir)
    {
        Block nblock = getNeighborBlock(blocksEngine, dir);
        Block coalStatic = blocksEngine.getBlocksManager().coal;
        if (nblock.equalBlock(coalStatic))
        {
            blocksEngine.createBlock(getCoor(), blocksEngine.getBlocksManager().silicon, temperature, press);
            return true;
        }
        return false;
    }

    protected virtual void dinasMoveRule(BlocksEngine blocksEngine)
    {
        Block down_block = getNeighborBlock(blocksEngine, Dir.down);
        if (down_block.isFluid() || down_block.isAir())
        {
            moveTo(blocksEngine, down_block.getCoor());
        }
    }
}

using static System.Console;
using static System.Threading.Thread;
using System;
 
public static class PenneysGame
{
    const int pause = 500;
    const int N = 3;
    static Random rng = new Random();
 
    static int Toss() => rng.Next(2);
 
    static string AsString(this int sequence) {
        string s = "";
        for (int b = 0b100; b > 0; b >>= 1) {
            s += (sequence & b) > 0 ? 'T' : 'H';
        }
        return s;
    }
 
    static int UserInput() {
        while (true) {
            switch (ReadKey().Key) {
                case ConsoleKey.Escape: return -1;
                case ConsoleKey.H: return 0;
                case ConsoleKey.T: return 1;
            }
            Console.Write('\b');
        }
    }
 
    public static void Main2() {
        int yourScore = 0, myScore = 0;
        while (true) {
            WriteLine($"Your score: {yourScore}, My score: {myScore}");
            WriteLine("Determining who goes first...");
            Sleep(pause);
            bool youStart = Toss() == 1;
            WriteLine(youStart ? "You go first." : "I go first.");
            int yourSequence = 0, mySequence = 0;
            if (youStart) {
                WriteLine("Choose your sequence of (H)eads and (T)ails (or press Esc to exit)");
                int userChoice;
                for (int i = 0; i < N; i++) {
                    if ((userChoice = UserInput()) < 0) return;
                    yourSequence = (yourSequence << 1) + userChoice;
                }
                mySequence = ((~yourSequence << 1) & 0b100) | (yourSequence >> 1);
            } else {
                for (int i = 0; i < N; i++) {
                    mySequence = (mySequence << 1) + Toss();
                }
 
                WriteLine("I chose " + mySequence.AsString());
                do {
                    WriteLine("Choose your sequence of (H)eads and (T)ails (or press Esc to exit)");
                    int choice;
                    yourSequence = 0;
                    for (int i = 0; i < N; i++) {
                        if ((choice = UserInput()) < 0) return;
                        yourSequence = (yourSequence << 1) + choice;
                    }
                    if (yourSequence == mySequence) {
                        WriteLine();
                        WriteLine("You cannot choose the same sequence.");
                    }
                } while (yourSequence == mySequence);
            }
 
            WriteLine();
            WriteLine($"Your sequence: {yourSequence.AsString()}, My sequence: {mySequence.AsString()}");

