public class CountdownDisposableTests
{
    [Fact]
    public void CountdownDisposable_VerifyReferenceCountingLifecycle()
    {
        // Arrange
        int callCount = 0;
        Action callback = () => callCount++;

        // Create CountdownDisposable with initial callback
        var disposable = CountdownDisposable.Create(callback);

        // Assert initial state
        disposable.Should().NotBeNull();
        callCount.Should().Be(0);

        // Act: Increment references multiple times
        var reference1 = disposable.Increment();
        var reference2 = disposable.Increment();
        var reference3 = disposable.Increment();

        // Assert reference count increased
        reference1.Should().NotBeNull();
        reference2.Should().NotBeNull();
        reference3.Should().NotBeNull();
        callCount.Should().Be(0);

        // Dispose first reference
        reference1.Dispose();
        callCount.Should().Be(0);

        // Dispose second reference
        reference2.Dispose();
        callCount.Should().Be(0);

        // Dispose third reference, should trigger callback
        reference3.Dispose();
        callCount.Should().Be(1);

        // Subsequent disposals should not increment callback
        reference1.Dispose();
        reference2.Dispose();
        reference3.Dispose();
        callCount.Should().Be(1);
    }

    [Fact]
    public void CountdownDisposable_EnsureThreadSafetyAndReliability()
    {
        // Arrange
        int callCount = 0;
        Action callback = () => Interlocked.Increment(ref callCount);

        // Create disposable with thread-safe callback
        var disposable = CountdownDisposable.Create(callback);

        // Parallel increment and dispose operations
        Parallel.For(0, 100, _ =>
        {
            using var reference = disposable.Increment())
            {
                // Simulating concurrent operations
            }
        });

        // Assert callback was called exactly once
        callCount.Should().Be(1);
    }
}

using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Microsoft.Bot.Builder.Dialogs;
using Microsoft.Bot.Connector;
using Newtonsoft.Json;

public class BoletinDialog : IDialog<object>
{
    private readonly IAIService _aiService;
    private readonly IBoletinProxy _boletinProxy;

    public BoletinDialog(IAIService aiService, IBoletinProxy boletinProxy)
    {
        _aiService = aiService;
        _boletinProxy = boletinProxy;
    }

    public async Task StartAsync(IDialogContext context)
    {
        context.Wait(MessageReceivedAsync);
    }

    private async Task MessageReceivedAsync(IDialogContext context, IAwaitable<IMessageActivity> result)
    {
        var message = await result;
        var aiResponse = await _aiService.ProcessMessageAsync(message.Text);

        if (aiResponse.HasBoletinDocuments)
        {
            var boletines = await _boletinProxy.ObtenerBoletinesAsync();
            await DisplayBoletinDocumentsAsync(context, boletines, aiResponse.ConversationMessage);
        }
        else
        {
            await context.PostAsync(aiResponse.ConversationMessage);
            context.Wait(MessageReceivedAsync);
        }
    }

    private async Task DisplayBoletinDocumentsAsync(IDialogContext context, List<BoletinDto> boletines, string conversationMessage)
    {
        var heroCard = CreateBoletinHeroCard(boletines);
        var attachment = heroCard.ToAttachment();

        var reply = context.MakeMessage();
        reply.Text = conversationMessage;
        reply.Attachments = new List<Attachment> { attachment };

        await context.PostAsync(reply);
        context.Wait(MessageReceivedAsync);
    }

    private HeroCard CreateBoletinHeroCard(List<BoletinDto> boletines)
    {
        var cardButtons = new List<CardAction>();
        foreach (var boletin in boletines)
        {
            cardButtons.Add(new CardAction
            {
                Title = boletin.Titulo,
                Type = ActionTypes.Download,
                Value = boletin.UrlDescarga
            });
        }

        return new HeroCard
        {
            Title = "Documentos Disponibles",
            Subtitle = "Seleccione un boletín para descargar",
            Buttons = cardButtons
        };
    }
}

public interface IBoletinProxy
{
    Task<List<BoletinDto>> ObtenerBoletinesAsync();
}

public class BoletinDto
{
    public string Titulo { get; set; }
    public string UrlDescarga { get; set; }
}

using System;
using System.Threading.Tasks;
using Android.App;
using Android.Content;
using KeePassLib;
using KeePassLib.Interfaces;

namespace Keepass2Android.Dialogs
{
    public class DeleteEntry : Java.Lang.Object, IRunnable
    {
        private readonly Context _context;
        private readonly PwEntry _entry;
        private readonly PwDatabase _database;
        private readonly bool _isPermanentDelete;
        private readonly IUiStringKey _deleteConfirmationKey;

        public DeleteEntry(Context context, PwEntry entry, PwDatabase database, bool isPermanentDelete)
        {
            _context = context;
            _entry = entry;
            _database = database;
            _isPermanentDelete = isPermanentDelete;
            _deleteConfirmationKey = GetDeleteConfirmationKey();
        }

        public void Run()
        {
            if (_entry == null || _database == null)
                return;

            if (CanRecycle() && !_isPermanentDelete)
            {
                RecycleEntry();
            }
            else
            {
                ConfirmPermanentDeletion();
            }
        }

        private bool CanRecycle()
        {
            return _database.RecycleBinEnabled
                   && _database.RecycleBinUuid != PwUuid.Zero
                   && _entry.ParentGroup != _database.RecycleBin;
        }

        private void RecycleEntry()
        {
            PwGroup recycleBin = _database.GetRecycleBin();
            if (recycleBin == null)
                return;

            Task.Run(() =>
            {
                lock (_database)
                {
                    _entry.ParentGroup.Entries.Remove(_entry);
                    recycleBin.AddEntry(_entry, true, true);
                    _database.Save(null);
                }
            });
        }

        private void ConfirmPermanentDeletion()
        {
            var builder = new AlertDialog.Builder(_context);
            builder.SetTitle(Resource.String.delete_entry_title)
                   .SetMessage(Resource.String.really_delete_entry)
                   .SetPositiveButton(Android.Resource.String.Ok, (s, e) => PerformDelete())
                   .SetNegativeButton(Android.Resource.String.Cancel, (s, e) => {})
                   .Create()
                   .Show();
        }

        private void PerformDelete()
        {
            Task.Run(() =>
            {
                lock (_database)
                {
                    DoDeleteEntry();
                    _database.Save(null);
                }
            });

