        W = new Spell(SpellSlot.W, 300f);
        E = new Spell(SpellSlot.E, 350f);
        R = new Spell(SpellSlot.R, 550f);

        Q.SetSkillshot(0.25f, 80f, 2000f, true, SkillshotType.SkillshotLine);
