    public override void ComboMenu(Menu config)
    {
        config.AddItem(new MenuItem("useQ", "Use Q").SetValue(true));
        config.AddItem(new MenuItem("useW", "Use W").SetValue(true));
        config.AddItem(new MenuItem("useE", "Use E").SetValue(true));
        config.AddItem(new MenuItem("useR", "Use R").SetValue(true));
        config.AddItem(new MenuItem("minR", "R Minimum Targets").SetValue(new Slider(2, 1, 5)));
    }

    public override void OnUpdate(EventArgs args)
    {
        if (Player.IsDead) return;
        if (!ComboMode) return;

        // Q Logic
        if (Config.Item("useQ").GetValue<bool>() && Q.IsReady())
        {
            var target = TargetSelector.GetTarget(Q.Range, TargetSelector.DamageType.Magical);
            if (target.IsValidTarget())
            {
                var prediction = Q.GetPrediction(target);
                if (prediction.Hitchance >= HitChance.High)
                {
                    Q.Cast(prediction.CastPosition);
                }
            }
        }

        // W Toggle Logic
        if (Config.Item("useW").GetValue<bool>())
        {
            var enemies = Player.GetEnemiesInRange(W.Range).Count;
            if (enemies > 0 && !wUse && W.IsReady())
            {
                W.Cast();
                wUse = true;
            }
            else if (enemies == 0 && wUse && W.IsReady())
            {
                W.Cast();
                wUse = false;
            }
        }

        // E Logic
        if (Config.Item("useE").GetValue<bool>() && E.IsReady())
        {
            if (Player.GetEnemiesInRange(E.Range).Count > 0)
            {
                E.Cast();
            }
        }

        // R Logic
        if (Config.Item("useR").GetValue<bool>() && R.IsReady())
        {
            var enemies = Player.GetEnemiesInRange(R.Range).Count;
            var minTargets = Config.Item("minR").GetValue<Slider>().Value;

            if (enemies >= minTargets)
            {
                R.Cast();
            }
        }

