using System;
using System.Collections.Generic;
using System.Linq;

public static class LinqExtensions
{
    public static IEnumerable<IEnumerable<T>> CartesianProduct<T>(this IEnumerable<IEnumerable<T>> sequences)
    {
        IEnumerable<IEnumerable<T>> emptyProduct = new[] { Enumerable.Empty<T>() };
        return sequences.Aggregate(
            emptyProduct,
            (accumulator, sequence) =>
                from accseq in accumulator
                from item in sequence
                select accseq.Concat(new[] { item }));
    }

    public static IEnumerable<Tuple<T1, T2>> CartesianProduct<T1, T2>(this IEnumerable<T1> first, IEnumerable<T2> second)
    {
        return first.SelectMany(f => second.Select(s => Tuple.Create(f, s)));
    }

    public static IEnumerable<T> Distinct<T>(this IEnumerable<T> source, Func<T, T, bool> equalityComparer)
    {
        var yielded = new List<T>();
        foreach (var item in source)
        {
            if (!yielded.Any(y => equalityComparer(y, item)))
            {
                yielded.Add(item);
                yield return item;
            }
        }
    }

    public static IEnumerable<T> Concat<T>(this IEnumerable<T> source, T element)
    {
        foreach (var item in source)
        {
            yield return item;
        }
        yield return element;
    }
}

