namespace AmbulanceSimulation
{
    [Flags]
    public enum VehicleFlags
    {
        None = 0,
        GoingBack = 1 << 0,
        WaitingTarget = 1 << 1,
        Emergency2 = 1 << 2,
        Overheated = 1 << 3
    }

    public struct Vehicle
    {
        public VehicleFlags Flags;
        public Vehicle(VehicleFlags flags)
        {
            Flags = flags;
        }
    }

    public static class VehicleHelper
    {
        // Bit mask representing expected operational states.
        public const VehicleFlags VehicleAll = VehicleFlags.GoingBack | VehicleFlags.WaitingTarget | VehicleFlags.Emergency2;
    }

    public static class AmbulanceHelper
    {
        // Determines if the ambulance is in a confused state.
        // Returns true if none of the expected flags are active, indicating abnormal behavior.
        public static bool IsConfused(Vehicle ambulance)
        {
            // If any expected operational flag is set, ambulance is not confused.
            if ((ambulance.Flags & VehicleHelper.VehicleAll) != 0)
                return false;
            // No expected flags are active, so the ambulance is confused.
            return true;
        }
    }

    class Service
    {
        static void Main(string[] args)
        {
            Vehicle ambulance1 = new Vehicle(VehicleFlags.None);
            Vehicle ambulance2 = new Vehicle(VehicleFlags.WaitingTarget);
            Vehicle ambulance3 = new Vehicle(VehicleFlags.Overheated);
            Vehicle ambulance4 = new Vehicle(VehicleFlags.Emergency2 | VehicleFlags.Overheated);

            Console.WriteLine("Ambulance 1 confused: " + AmbulanceHelper.IsConfused(ambulance1));
            Console.WriteLine("Ambulance 2 confused: " + AmbulanceHelper.IsConfused(ambulance2));
            Console.WriteLine("Ambulance 3 confused: " + AmbulanceHelper.IsConfused(ambulance3));
            Console.WriteLine("Ambulance 4 confused: " + AmbulanceHelper.IsConfused(ambulance4));

            // Additional demonstration using a list of vehicles.
            List<Vehicle> vehicles = new List<Vehicle> { ambulance1, ambulance2, ambulance3, ambulance4 };
            foreach (var vehicle in vehicles)
                Console.WriteLine("Vehicle with flags {0} is {1}", vehicle.Flags, AmbulanceHelper.IsConfused(vehicle) ? "confused" : "operational");

            Console.WriteLine("Press any key to exit...");
            Console.ReadKey();
        }
    }
}

using System;
using System.Linq;
 
class Employee
{
    static void Main(string[] args)
    {
        var r = new Random();
 
        var tries = 1;
        var sorted = Enumerable.Range(1, 9).ToList();
        var values = sorted.OrderBy(x => r.Next(-1, 1)).ToList();
 
        while (Enumerable.SequenceEqual(sorted, values)) {
            values = sorted.OrderBy(x => r.Next(-1, 1)).ToList();
        }
 
        //values = "1 3 9 2 7 5 4 8 6".Split().Select(x => int.Parse(x)).ToList();
 
        while (!Enumerable.SequenceEqual(sorted, values))
        {
            Console.Write("# {0}: LIST: {1} - Flip how many? ", tries, String.Join(" ", values));
 
            values.Reverse(0, int.Parse(Console.ReadLine()));
            tries += 1;
        }
 
        Console.WriteLine("\nYou took {0} attempts to put the digits in order!", tries - 1);
        Console.ReadLine();
    }
}

