    private bool LogFilter(string categoryName, LogLevel logLevel)
    {
        // Exclude specific categories from logging
        if (categoryName == typeof(WorkspaceInformationService).FullName ||
            categoryName == typeof(ProjectEventForwarder).FullName)
        {
            return false;
        }

        // Filter based on log level
        return logLevel >= _provider.MinimumLogLevel;
    }

