using System;
using NUnit.Framework;
using Moq;
using Mono.Cecil;
using ILRepacking;

namespace ResourceManagementTests
{
    public interface IRepackContext
    {
        AssemblyDefinition GetAssemblyDefinition(string assemblyName);
    }

    public class BamlResourcePatcher
    {
        private readonly IRepackContext _context;

        public BamlResourcePatcher(IRepackContext context)
        {
            _context = context;
        }

        public string RemoveTypeAssemblyInformation(string fullTypeName)
        {
            int lastComma = fullTypeName.LastIndexOf(',');
            return lastComma > 0 ? fullTypeName.Substring(0, lastComma).Trim() : fullTypeName;
        }
    }

    [TestFixture]
    public class BamlResourcePatcherTests
    {
        private BamlResourcePatcher _patcher;
        private Mock<IRepackContext> _mockContext;

        [SetUp]
        public void SetUp()
        {
            _mockContext = new Mock<IRepackContext>();
            _patcher = new BamlResourcePatcher(_mockContext.Object);
        }

        [TestCase("Namespace.ClassName, AssemblyName", "Namespace.ClassName")]
        [TestCase("Namespace.ClassName, Version=1.0.0.0, Culture=neutral, PublicKeyToken=null", "Namespace.ClassName")]
        [TestCase("Namespace.ClassName", "Namespace.ClassName")]
        [TestCase("ClassName, AssemblyName", "ClassName")]
        public void TestRemoveTypeAssemblyInformation(string input, string expected)
        {
            // Act
            var result = _patcher.RemoveTypeAssemblyInformation(input);

            // Assert
            Assert.AreEqual(expected, result);
        }

        [Test]
        public void TestHandlingOfInvalidInput()
        {
            // Act
            var result = _patcher.RemoveTypeAssemblyInformation(string.Empty);

            // Assert
            Assert.AreEqual(string.Empty, result);
        }

        [Test]
        public void TestNullInputThrowsException()
        {
            // Act & Assert
            Assert.Throws<ArgumentNullException>(() => _patcher.RemoveTypeAssemblyInformation(null));
        }

        [Test]
        public void TestComplexTypeName()
        {
            // Arrange
            var complexTypeName = "Namespace.SubNamespace.ClassName, Version=2.0.0.0, Culture=neutral, PublicKeyToken=abcdef123456";
            var expected = "Namespace.SubNamespace.ClassName";

            // Act
            var result = _patcher.RemoveTypeAssemblyInformation(complexTypeName);

            // Assert
            Assert.AreEqual(expected, result);
        }
    }
}

