public class GoogleCloudResult
{
    public enum StatusCode
    {
        Success,
        NotFound,
        Failed,
        Conflict,
        UnknownError
    }

    private StatusCode _response;
    private string _message;
    private string _stateKey;
    private byte[] _stateData;
    private byte[] _serverConflictData;
    private string _resolvedVersion;

    public GoogleCloudResult(StatusCode response, string message, string stateKey, byte[] stateData, byte[] serverConflictData, string resolvedVersion)
    {
        _response = response;
        _message = message;
        _stateKey = stateKey;
        _stateData = stateData;
        _serverConflictData = serverConflictData;
        _resolvedVersion = resolvedVersion;
    }

    public GoogleCloudResult(StatusCode response)
        : this(response, string.Empty, string.Empty, null, null, string.Empty) { }

    public StatusCode Response
    {
        get { return _response; }
    }

    public string Message
    {
        get { return _message; }
    }

    public string StateKey
    {
        get { return _stateKey; }
    }

    public byte[] StateData
    {
        get { return _stateData; }
    }

    public byte[] ServerConflictData
    {
        get { return _serverConflictData; }
    }

    public string ResolvedVersion
    {
        get { return _resolvedVersion; }
    }

    public bool IsSuccess
    {
        get { return _response == StatusCode.Success; }
    }

    public bool IsFailed
    {
        get { return _response == StatusCode.Failed; }
    }

    public bool HasConflict
    {
        get { return _response == StatusCode.Conflict; }
    }

    public static StatusCode ConvertStringToStatusCode(string status)
    {
        if (Enum.TryParse(status, true, out StatusCode code))
        {
            return code;
        }
        return StatusCode.UnknownError;
    }

    public string ConvertStateDataToString()
    {
        return Convert.ToBase64String(_stateData ?? new byte[0]);
    }

    public string ConvertServerConflictDataToString()
    {
        return Convert.ToBase64String(_serverConflictData ?? new byte[0]);
    }

    public static bool IsPlatformSupported()
    {
#if UNITY_ANDROID
        return true;
#else
        return false;
#endif
    }

    public override string ToString()
    {
        return $"Response: {Response}, Message: {Message}, StateKey: {StateKey}, " +
               $"IsSuccess: {IsSuccess}, IsFailed: {IsFailed}, HasConflict: {HasConflict}, " +
               $"ResolvedVersion: {ResolvedVersion}";
    }

using FluentAssertions;
using GwtUnit.UnitTest;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using Randal.Core.Xml;

namespace Randal.Core.Tests.Xml
{
    [TestClass]
    public class XmlCollectionTests : UnitTestBase<XmlCollectionThens>
    {
        private int[] Items = { 1, 2, 3 };
        private int ItemToAdd = 4;
        private XmlCollection<int> Collection;

        [TestMethod]
        public void ShouldHaveCollection_WhenCreatingInstance_GivenNoItems()
        {
            Given(GivensDefined)
                .When(Creating)
                .Then(Thens.CollectionIsDefined);
        }

        [TestMethod]
        public void ShouldHaveCollection_WhenCreatingInstance_GivenItems()
        {
            Given(GivensDefined)
                .When(CreatingItems)
                .Then(Thens.CollectionHasItems);
        }

        [TestMethod]
        public void ShouldHaveOneItem_WhenAddingItem_GivenValue()
        {
            Given(GivensDefined)
                .When(AddingItem)
                .Then(Thens.CollectionHasOneItem);
        }

        private void Creating()
        {
            Collection = new XmlCollection<int>();
        }

        private void CreatingItems()
        {
            Collection = new XmlCollection<int>(Items);
        }

        private void AddingItem()
        {
            Collection = new XmlCollection<int>();
            Collection.Add(ItemToAdd);
        }
    }

    public class XmlCollectionThens
    {
        public XmlCollection<int> Collection { get; set; }

        public void CollectionIsDefined()
        {
            Collection.Should().NotBeNull();
        }

        public void CollectionHasItems()
        {
            Collection.Should().NotBeNull().And.HaveCount(3);
        }

        public void CollectionHasOneItem()
        {
            Collection.Should().NotBeNull().And.HaveCount(1).And.Contain(4);
        }
    }
}

namespace EntLibExtensions.Infrastructure.WinService
{
    using System.ComponentModel;
    using System.Configuration.Install;
    using System.Diagnostics;
    using System.ServiceProcess;

    /// <summary>
    /// This class designed for service installation by using istallutil.exe
    /// In case installation is provided by msi service extensions code below is ignored.
    /// service information will be retrieved from wxs file.
    /// </summary>
    [RunInstaller(true)]
    public abstract class ServiceInstallerBase : Installer
    {
        /// <summary>
        /// Initializes a new instance of the <see cref="ServiceInstallerBase"/> class.
        /// </summary>
        /// <param name="options">
        /// The options.
        /// </param>
        protected ServiceInstallerBase(WinServiceInstallationOptions options)
        {
            ServiceProcessInstaller serviceProcessInstaller = new ServiceProcessInstaller();
            ServiceInstaller serviceInstaller = new ServiceInstaller();

            // # Service Account Information
            serviceProcessInstaller.Account = options.Account;

            // # Service Information
            serviceInstaller.DisplayName = options.DisplayName;
            serviceInstaller.Description = options.Description;
            serviceInstaller.StartType = ServiceStartMode.Automatic;
            serviceInstaller.ServiceName = options.Options.ServiceName;

            this.Installers.Add(serviceProcessInstaller);
            this.Installers.Add(serviceInstaller);

            EventLogInstaller defaultInstaller = null;
            foreach (Installer installer in serviceInstaller.Installers)
            {
                var eventLogInstaller = installer as EventLogInstaller;
                if (eventLogInstaller != null)
                {
                    defaultInstaller = eventLogInstaller;
                    break;
                }
            }

            if (defaultInstaller != null)
            {
                serviceInstaller.Installers.Remove(defaultInstaller);
            }
        }
    }
}

public abstract class MemoryDrumBank : IDrumBank
{
    protected readonly IMemory _memory;
    private readonly int _offset;
    private const int MaxSounds = 10;
    private const int MaxFrequencyPoints = 14;

    protected MemoryDrumBank(IMemory memory, int baseOffset)
    {
        _memory = memory;
        _offset = baseOffset;
    }

    protected void GenerateSounds()
    {
        for (int soundIndex = 0; soundIndex < MaxSounds; soundIndex++)
        {
            int[][] frequencyConfig = GetFrequencyConfiguration(soundIndex);
            WriteSound(soundIndex, frequencyConfig);
        }
    }

    private void WriteSound(int soundIndex, int[][] frequencyData)
    {
        int soundOffset = _offset + (soundIndex * MaxFrequencyPoints * 2);

        for (int pointIndex = 0; pointIndex < frequencyData.Length; pointIndex++)
        {
            short frequencyValue = (short)CalculateFrequencyValue(frequencyData[pointIndex]);
            _memory.Write16Bit(soundOffset + (pointIndex * 2), frequencyValue);
        }
    }

    private int CalculateFrequencyValue(int[] frequencyPoint)
    {
        return frequencyPoint[0] * frequencyPoint[1] / 100;
    }

    public IDrumSound GetItem(int index)
    {
        if (index < 0 || index >= MaxSounds)
            throw new ArgumentOutOfRangeException(nameof(index));

        return new MemoryDrumSound(_memory, _offset + (index * MaxFrequencyPoints * 2));
    }

    protected abstract int[][] GetFrequencyConfiguration(int soundIndex);
}

public class MemoryDrumSound : IDrumSound
{
    private readonly IMemory _memory;
    private readonly int _offset;

    public MemoryDrumSound(IMemory memory, int offset)
    {
        _memory = memory;
        _offset = offset;
    }

    public short[] GetSoundData()
    {
        short[] soundData = new short[14];
        for (int i = 0; i < 14; i++)
        {
            soundData[i] = _memory.Read16Bit(_offset + (i * 2));
        }
        return soundData;
    }
}

using System;
 
public class Matrix
{
    public static string ord(int n)
    {
        string s = "th";
        switch (int c = n % 10)
        {
            case 1:
            case 2:
            case 3:
                if (n % 100 / 10 == 1)
                {
                    break;
                }
                switch (c)
                {
                    case 1:
                        s = "st";
                        break;
                    case 2:
                        s = "nd";
                        break;
                    case 3:
                        s = "rd";
                        break;
                }
                break;
        }
        return string.Format("{0}{1}", n, s);
    }
 
    public static void Main()
    {
        for (int n = 0; n <= 25; n++)
        {
            Console.Write("{0} ", ord(n));
        }
        Console.WriteLine();
        for (int n = 250; n <= 265; n++)
        {
            Console.Write("{0} ", ord(n));
        }
        Console.WriteLine();
        for (int n = 1000; n <= 1025; n++)
        {
            Console.Write("{0} ", ord(n));
        }
        Console.WriteLine();
    }
}

