using System;
 
class Validator
{
    static double mean(double[] v, int len)
    {
        double sum = 0;
        int i;
        for (i = 0; i < len; i++)
            sum += v[i];
        return sum / len;
    }
 
    static void Main()
    {
        double[] v = {1, 2, 2.718, 3, 3.142};
        int i, len;
        for (len = 5; len >= 0; len--) {
            Console.Write("mean[");
            for (i = 0; i < len; i++)
                Console.Write(i? ", {0}" : "{0}", v[i]);
            Console.WriteLine("] = {0}", mean(v, len));
        }
    }
}

using System;
using System.Runtime.InteropServices;
using Microsoft.VisualStudio.OLE.Interop;

public sealed class ComEventSink : IDisposable
{
    private IConnectionPoint _connectionPoint;
    private uint _cookie;

    private ComEventSink(IConnectionPoint connectionPoint, uint cookie)
    {
        _connectionPoint = connectionPoint;
        _cookie = cookie;
    }

    public static ComEventSink Advise<T>(object comObject, T eventSink)
    {
        if (comObject == null)
            throw new ArgumentNullException(nameof(comObject));
        if (eventSink == null)
            throw new ArgumentNullException(nameof(eventSink));

        Type interfaceType = typeof(T);
        if (!interfaceType.IsInterface)
            throw new ArgumentException("Event sink must be an interface type.", nameof(T));

        IConnectionPointContainer container = comObject as IConnectionPointContainer;
        if (container == null)
            throw new ArgumentException("COM object does not implement IConnectionPointContainer.", nameof(comObject));

        Guid iid = interfaceType.GUID;
        container.FindConnectionPoint(ref iid, out IConnectionPoint connectionPoint);

        IntPtr sinkPtr = Marshal.GetComInterfaceForObject(eventSink, interfaceType);
        try
        {
            uint cookie;
            connectionPoint.Advise(sinkPtr, out cookie);
            return new ComEventSink(connectionPoint, cookie);
        }
        finally
        {
            Marshal.Release(sinkPtr);
        }
    }

    public void Unadvise()
    {
        if (_connectionPoint == null || _cookie == 0)
            return;

        try
        {
            _connectionPoint.Unadvise(_cookie);
        }
        finally
        {
            _cookie = 0;
            Marshal.ReleaseComObject(_connectionPoint);
            _connectionPoint = null;
        }
    }

    public void Dispose()
    {
        Unadvise();
        GC.SuppressFinalize(this);
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace Task
{
    class Writer
    {
        static void Main(string[] args)
        {
            Console.WriteLine("~~~ BSD ~~~");
            var bsd = new BsdLcg(0);
            for (int i = 0; i < 10; i++)
            {
                Console.WriteLine(bsd.Next());
            }
 
            Console.WriteLine("~~~ MS ~~~");
            var ms = new MsLcg(0);
            for (int i = 0; i < 10; i++)
            {
                Console.WriteLine(ms.Next());
            }
 
            Console.WriteLine("~~~ Others ~~~");
            Console.WriteLine(string.Join(", ", ms.Next(5)));
            Console.WriteLine(ms.NextBool());
            Console.WriteLine(string.Join("", ms.NextAsciiChars(15)));
        }
    }
 
    public class BsdLcg
    {
        private uint state;
 
        public BsdLcg(uint seed)
        {
            state = seed;
        }
 
        public uint Next()
        {
            state = state * 1103515245 + 12345;
            state %= 1 << 31;
            return state;
        }
    }
 
    public class MsLcg
    {
        private uint state;
 
        public MsLcg(uint seed)
        {
            state = seed;
        }
 
        public uint Next()
        {
            state = state * 214013 + 2531011;
            state %= 1 << 31;
            return state >> 16;
        }
 
        public uint[] Next(int count)
        {
            var result = new uint[count];
            for (int i = 0; i < count; i++)
            {
                result[i] = Next();
            }
            return result;
        }
 
        public bool NextBool()
        {
            return Next() % 2 == 0;
        }
 
        public char[] NextAsciiChars(int count)
        {
            var result = new char[count];
            for (int i = 0; i < count; i++)
            {
                result[i] = (char)Next(32, 127);
            }
            return result;
        }
 
        private uint Next(uint min, uint max)
        {
            return min + Next() % (max - min);
        }
    }
}

