public class ExtendedEngine : Engine
{
    private const string CharacterNeutralOwner = "Neutral";

    public void ExecuteCreateObjectCommand(string[] commandWords)
    {
        string objectType = commandWords[0];
        string name = commandWords[1];
        Point position = Point.Parse(commandWords[2]);
        string owner = commandWords.Length > 3 ? commandWords[3] : CharacterNeutralOwner;

        switch (objectType.ToLower())
        {
            case "giant":
                Giant giant = new Giant(name, position, owner);
                AddObject(giant);
                break;
            case "knight":
                Knight knight = new Knight(name, position, owner);
                AddObject(knight);
                break;
            case "house":
                House house = new House(name, position);
                AddObject(house);
                break;
            case "rock":
                Rock rock = new Rock(name, position);
                AddObject(rock);
                break;
            case "ninja":
                Ninja ninja = new Ninja(name, position, owner);
                AddObject(ninja);
                break;
            default:
                base.ExecuteCreateObjectCommand(commandWords);
                break;
        }
    }
}

