using Robust.Client.Graphics.Shaders;
using Robust.Client.Interfaces.GameObjects.Components;
using Robust.Shared.GameObjects;
using Robust.Shared.IoC;
using Robust.Shared.Prototypes;

public class InteractionOutlineComponent : Component
{
    [Dependency] private readonly IPrototypeManager _prototypeManager = default!;

    private ShaderInstance? _selectionShaderInstance;
    private ShaderInstance? _selectionShaderInRangeInstance;

    public override string Name => "InteractionOutline";

    public override void Initialize()
    {
        base.Initialize();

        // Load shaders from the prototype manager
        _selectionShaderInstance = _prototypeManager.Index<ShaderPrototype>("SelectionShader").Instance();
        _selectionShaderInRangeInstance = _prototypeManager.Index<ShaderPrototype>("SelectionShaderInRange").Instance();
    }

    public void OnMouseEnter(bool inInteractionRange)
    {
        if (!Owner.TryGetComponent(out ISpriteComponent? sprite))
            return;

        if (inInteractionRange)
        {
            sprite.PostShader = _selectionShaderInRangeInstance;
        }
        else
        {
            sprite.PostShader = _selectionShaderInstance;
        }
    }

    public void OnMouseLeave()
    {
        if (!Owner.TryGetComponent(out ISpriteComponent? sprite))
            return;

        sprite.PostShader = null;
    }

    public void UpdateInRange(bool inInteractionRange)
    {
        if (!Owner.TryGetComponent(out ISpriteComponent? sprite))
            return;

        if (sprite.PostShader != null)
        {
            if (inInteractionRange)
            {
                sprite.PostShader = _selectionShaderInRangeInstance;
            }
            else
            {
                sprite.PostShader = _selectionShaderInstance;
            }
        }
    }
}

