public static class EventNameCodeMapping
{
    private static readonly Dictionary<int, Type> _codeToType = new Dictionary<int, Type>();
    private static readonly Dictionary<Type, int> _typeToCode = new Dictionary<Type, int>();
    private static readonly object Locker = new object();
    private static bool _isInitialized = false;

    public static void Initialize(Assembly assembly, IDictionary<string, int> eventTypeMappings)
    {
        if (assembly == null)
            throw new ArgumentNullException(nameof(assembly));
        if (eventTypeMappings == null)
            throw new ArgumentNullException(nameof(eventTypeMappings));

        lock (Locker)
        {
            if (_isInitialized)
                throw new InvalidOperationException("Already initialized.");

            foreach (var entry in eventTypeMappings)
            {
                string typeName = entry.Key;
                int typeCode = entry.Value;

                Type eventType = assembly.GetType(typeName);
                if (eventType == null)
                    continue;

                if (!IsEventType(eventType))
                    throw new ArgumentException($"Invalid event type: {typeName}.");

                RegisterEventType(typeCode, eventType);
            }

            _isInitialized = true;
        }
    }

    public static bool TryGetEventType(int typeCode, out Type eventType)
    {
        lock (Locker)
        {
            return _codeToType.TryGetValue(typeCode, out eventType);
        }
    }

    public static bool TryGetEventTypeCode(Type eventType, out int typeCode)
    {
        if (eventType == null)
            throw new ArgumentNullException(nameof(eventType));

        if (!IsEventType(eventType))
            throw new ArgumentException("Type must inherit from GrainEvent.");

        lock (Locker)
        {
            return _typeToCode.TryGetValue(eventType, out typeCode);
        }
    }

    public static void RegisterEventType(int typeCode, Type eventType)
    {
        if (!IsEventType(eventType))
            throw new ArgumentException("Invalid event type.");

        lock (Locker)
        {
            if (_isInitialized)
                throw new InvalidOperationException("Registry is initialized.");

            if (_codeToType.ContainsKey(typeCode))
                throw new ArgumentException($"Code {typeCode} already registered.");

            if (_typeToCode.ContainsKey(eventType))

