namespace Project
{
    internal class Task
    {
        private static void Main(string[] args)
        {
            Thread.CurrentThread.CurrentCulture = CultureInfo.InvariantCulture;
            Console.WriteLine(" n          M(n)             Prime?");
            Console.WriteLine("-----------------------------------");
            Console.WriteLine(bool.TrueString);
            motzkin_generator mgen = new motzkin_generator();
            for (int i = 0; i < 42; i++)
            {
                uint n = mgen.next();
                Console.WriteLine("{0,2}{1,25}  {2}", i, n, is_prime(n));
            }
        }
 
        private static bool is_prime(ulong n)
        {
            if (n < 2)
                return false;
            if (n % 2 == 0)
                return n == 2;
            if (n % 3 == 0)
                return n == 3;
            for (ulong p = 5; p * p <= n; p += 4)
            {
                if (n % p == 0)
                    return false;
                p += 2;
                if (n % p == 0)
                    return false;
            }
            return true;
        }
 
        private class motzkin_generator
        {
            private ulong n = 0;
            private ulong m0 = 1;
            private ulong m1 = 1;
 
            public ulong next()
            {
                ulong m = n > 1? (m1 * (2 * n + 1) + m0 * (3 * n - 3)) / (n + 2) : 1;
                n++;
                m0 = m1;
                m1 = m;
                return m;
            }
        }
    }
}

