using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.FindSymbols;
using Microsoft.CodeAnalysis.LanguageServices;
using Microsoft.CodeAnalysis.Shared.Extensions;
using System.Collections.Immutable;
using System.Threading;
using System.Threading.Tasks;

internal static class OperatorSymbolReferenceFinder
{
    public static async Task<ImmutableArray<FinderLocation>> FindReferencesInDocumentAsync(
        IMethodSymbol symbol, Document document, CancellationToken cancellationToken)
    {
        var syntaxFacts = document.GetLanguageService<ISyntaxFactsService>();
        var op = GetPredefinedOperator(symbol);
        var root = await document.GetSyntaxRootAsync(cancellationToken).ConfigureAwait(false);
        var tokens = root.DescendantTokens();
        var locations = ImmutableArray.CreateBuilder<FinderLocation>();

        foreach (var token in tokens)
        {
            if (IsPotentialReference(syntaxFacts, op, token))
            {
                locations.Add(new FinderLocation(token.Parent, SymbolAndProjectId.Create(symbol, ProjectId.CreateNewId())));
            }
        }

        return locations.ToImmutable();
    }

    private static bool IsPotentialReference(ISyntaxFactsService syntaxFacts, PredefinedOperator op, SyntaxToken token)
    {
        return TryGetPredefinedOperator(syntaxFacts, token, out var tokenOp) && tokenOp == op;
    }

    private static PredefinedOperator GetPredefinedOperator(IMethodSymbol symbol)
    {
        return symbol.GetPredefinedOperator();
    }
    private static bool TryGetPredefinedOperator(ISyntaxFactsService syntaxFacts, SyntaxToken token, out PredefinedOperator op)
    {
        return syntaxFacts.TryGetPredefinedOperator(token, out op);
    }
    public static bool CanFind(IMethodSymbol symbol)
    {
        return symbol.MethodKind == MethodKind.UserDefinedOperator;
    }
}

