            {
                // Read two bytes to determine the entry type.
                byte marker = reader.ReadByte();
                byte indicator = reader.ReadByte();

                // Check for the termination marker (0xFF, 0xFF).
                if (marker == 0xFF && indicator == 0xFF)
                    break;

                // If indicator is non-zero, process it as a command entry.
                if (indicator != 0)
                {
                    // Read a 2-byte value as part of the command.
                    int commandValue = reader.ReadInt16();
                    currentSection.Commands.Add(new TrackSectionCommand
                    {
                        CommandType = indicator,
                        Value = commandValue
                    });
                }
                else
