                    // Process the complete track section properties.
                    int length = reader.ReadInt16();
                    int curvature = reader.ReadInt16();
                    int height = reader.ReadInt16();
                    byte sectionFlags = reader.ReadByte();
                    int leftVerge = reader.ReadInt16();
                    int rightVerge = reader.ReadInt16();

                    currentSection.Length = length;
                    currentSection.Curvature = curvature;

