            {
                using (var image = new MagickImage())
                {
                    image.SetDefine("jpeg:compression", 90);
                    var compression = image.GetDefine("jpeg:compression");
                    Assert.Equal("90", compression);
                }
            }

            [Fact]
            public void ShouldHandleMultipleDefines()
            {
                using (var image = new MagickImage())
                {
                    image.SetDefine("jpeg:quality", "75");
                    image.SetDefine("jpeg:optimize", false);
                    image.SetDefine("jpeg:compression", 85);

                    var quality = image.GetDefine("jpeg:quality");
                    var optimize = image.GetDefine("jpeg:optimize");
                    var compression = image.GetDefine("jpeg:compression");

                    Assert.Equal("75", quality);
                    Assert.Equal("false", optimize);
                    Assert.Equal("85", compression);
                }
            }

