public class EdgeHost
{
    private ConcurrentDictionary<string, IFable> Fables = new ConcurrentDictionary<string, IFable>();
    private ConcurrentDictionary<string, List<IDisposable>> Subscriptions = new ConcurrentDictionary<string, List<IDisposable>>();

    public void AddFable(IFable fable)
    {
        if (!Fables.TryAdd(fable.Id, fable))
        {
            Console.WriteLine($"Fable with ID {fable.Id} already exists.");
        }
        else
        {
            Console.WriteLine($"Fable {fable.Id} added successfully.");
        }
    }

    public void RemoveFable(string fableId)
    {
        if (Fables.TryRemove(fableId, out var _))
        {
            Console.WriteLine($"Fable {fableId} removed successfully.");
        }
        else
        {
            Console.WriteLine($"Fable with ID {fableId} does not exist.");
        }
    }

    public void SubscribeTopic(string topic, IDisposable subscriber)
    {
        Subscriptions.AddOrUpdate(topic, new List<IDisposable> { subscriber },
            (key, list) =>
            {
                list.Add(subscriber);
                return list;
            });
        Console.WriteLine($"Subscribed to topic {topic}.");
    }

    public void UnsubscribeTopic(string topic, IDisposable subscriber)
    {
        if (Subscriptions.TryGetValue(topic, out var list))
        {
            list.Remove(subscriber);
            if (list.Count == 0)
            {
                Subscriptions.TryRemove(topic, out _);
            }
            Console.WriteLine($"Unsubscribed from topic {topic}.");
        }
        else
        {
            Console.WriteLine($"No subscriptions found for topic {topic}.");
        }
    }

    public void NotifyTopic(string topic, dynamic payload)
    {
        if (Subscriptions.TryGetValue(topic, out var subscribers))
        {
            foreach (var subscriber in subscribers)
            {
                // Assuming subscriber can handle notification
                subscriber.Notify(payload);
            }
        }
    }

