    {
        _File = file ?? throw new ArgumentNullException(nameof(file));

        if (start.CompareTo(finish) > 0)
            throw new ArgumentException("Start position must precede finish position");

        _Start = start;
        _Finish = finish;
        _Line = line;
    }

    /// <summary>
    /// Gets the starting position of the mapped code span
    /// </summary>
    public Location Start => _Start;

    /// <summary>
    /// Gets the ending position of the mapped code span
