using System;
using System.Linq;
 
namespace Evolution
{
    class Timer
    {
        static void Main(string[] args)
        {
            var target = "METHINKS IT IS LIKE A WEASEL";
            var validChars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ ";
            var random = new Random();
            var initialString = new string(Enumerable.Range(0, target.Length).Select(x => validChars[random.Next(validChars.Length)]).ToArray());
            Console.WriteLine(initialString);
            Console.WriteLine(Mutate(initialString, 0.2));
            var mutationRate = 0.05;
            var childrenPerGen = 50;
            var i = 0;
            var currVal = initialString;
            while (currVal!= target)
            {
                i++;
                currVal = Enumerable.Range(0, childrenPerGen).Select(x => Mutate(currVal, mutationRate)).MaxBy(x => Fitness(x)).First();
            }
            Console.WriteLine($"Evolution found target after {i} generations");
        }
 
        static string Mutate(string s1, double mutationRate)
        {
            return new string(s1.Select(x => random.NextDouble() > mutationRate? x : validChars[random.Next(validChars.Length)]).ToArray());
        }
 
        static int Fitness(string s1)
        {
            return target.Length - HammingDistance(s1, target);
        }
 
        static int HammingDistance(string s1, string s2)
        {
            return s1.Zip(s2, (x, y) => x == y? 0 : 1).Sum();
        }
    }
}

using Desktop.App.Core.Events.Publishing;
using Desktop.App.Core.ModelViews;
using Desktop.App.Core.Ui.Windows;
using Desktop.Shared.Core;
using Desktop.Shared.Core.Context;
using Desktop.Shared.Core.Dtos;
using Desktop.Shared.Core.Services;
using Log4N.Logger;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace Desktop.App.Core.Handlers
{
    public class UpdateEntityHandler<T> : BaseHandler
        where T : BaseDto
    {
        protected override void DoExecute(ExecutionEvent executionEvent)
        {
            WizardModelView<T> wizardModelView = CreateWizardModelView(executionEvent);
            bool dialogResult = WindowsManager.GetInstance().ShowWizard<Wizard>(wizardModelView);
            if (dialogResult)
            {
                OnSuccessful(executionEvent, wizardModelView.Dto.Id);
            }
            return;
        }

        protected virtual WizardModelView<T> CreateWizardModelView(ExecutionEvent executionEvent)
        {
            return new WizardModelView<T>(LoadDto(executionEvent));
        }

        protected virtual T LoadDto(ExecutionEvent executionEvent)
        {

            ICRUDService<T> crudService = (ICRUDService<T>)ServiceActivator.Get(HandlerUtils.DTO_TO_SERVICE[typeof(T)]);
            Connection.GetInstance().StartTransaction();
            T dto = crudService.Read(executionEvent.GetFirstSelectedTreeNavigationItem().Id);
            Connection.GetInstance().EndTransaction();
            return dto;
        }

        protected override void OnFailure(ExecutionEvent executionEvent)
        {
            Log.Error("Error during the updating of the entity");
        }

        protected override void OnSuccessful(ExecutionEvent executionEvent, Guid affectedObjectId)
        {
            Log.Info(string.Format("Entity '{0}' was updated", affectedObjectId));
            Publisher.GetInstance().Publish(PublishEvent.CreateUpdateEvent(affectedObjectId, executionEvent.GetFirstSelectedTreeNavigationItem().Id));
        }
    }
}

