namespace ThemeManager
{
    public class ThemeItem : IComparable<ThemeItem>, ICloneable
    {
        // Property to hold the name of the theme item
        public string Name { get; set; }

        // Constructor to initialize the ThemeItem with a name
        public ThemeItem(string name)
        {
            Name = name;
        }

        // Implementing the CompareTo method for sorting
        public int CompareTo(ThemeItem other)
        {
            if (other == null) return 1;

            // Compare the names of the theme items
            return string.Compare(this.Name, other.Name, StringComparison.Ordinal);
        }

        // Implementing the Clone method for duplication
        public object Clone()
        {
            // Create a new ThemeItem with the same name
            return new ThemeItem(this.Name);
        }

        // Overriding the ToString method for better representation
        public override string ToString()
        {
            return $"ThemeItem: {Name}";
        }
    }

    public class ThemeList
    {
        private List<ThemeItem> _themes;

        public ThemeList()
        {
            _themes = new List<ThemeItem>();
        }

        // Method to add a theme item
        public void AddTheme(ThemeItem theme)
        {
            _themes.Add(theme);
        }

        // Method to sort the theme items
        public void SortThemes()
        {
            _themes.Sort();
        }

        // Method to duplicate a theme item
        public ThemeItem DuplicateTheme(ThemeItem theme)
        {
            return (ThemeItem)theme.Clone();
        }

        // Method to get all themes as a string
        public override string ToString()
        {
            string themeListString = "Themes:\n";
            foreach (var theme in _themes)
            {
                themeListString += theme.ToString() + "\n";
            }
            return themeListString;
        }
    }

