    public static Vector3 ParabolaLerp(Vector3 start, Vector3 apex, Vector3 end, float t)
    {
        t = Mathf.Clamp01(t);
        Vector3 parabolaPos = Vector3.zero;
        parabolaPos.x = ParabolaPosLerp(start.x, apex.x, end.x, t);
        parabolaPos.y = ParabolaPosLerp(start.y, apex.y, end.y, t);
        parabolaPos.z = ParabolaPosLerp(start.z, apex.z, end.z, t);
        return parabolaPos;
    }

    private static float ParabolaPosLerp(float start, float apex, float end, float t)
    {
        return start - t * (3 * start - 4 * apex + end) + 2 * Mathf.Pow(t, 2f) * (start - 2 * apex + end);
    }

    //increase or decrease the length of vector by size
    public static Vector3 AddVectorLength(Vector3 vector, float size){

        //get the vector length
        float magnitude = Vector3.Magnitude(vector);

        //change the length
        magnitude += size;

        //normalize the vector
        Vector3 vectorNormalized = Vector3.Normalize(vector);

        //scale the vector
        return Vector3.Scale(vectorNormalized, new Vector3(magnitude, magnitude, magnitude));
    }

    //create a vector of direction "vector" with length "size"
    public static Vector3 SetVectorLength(Vector3 vector, float size){

        //normalize the vector
        Vector3 vectorNormalized = Vector3.Normalize(vector);

        //scale the vector
        return vectorNormalized *= size;
    }

    //caclulate the rotational difference from A to B
    public static Quaternion SubtractRotation(Quaternion B, Quaternion A){

        Quaternion C = Quaternion.Inverse(A) * B;
        return C;
    }

