using Atata;
 using System;

 namespace YourNamespace // Replace with your actual namespace
 {
  public abstract class VerifyHeadingTriggerAttribute : TriggerAttribute
  {
  public int? Index { get; set; }
  public string[] Values { get; set; }
  public TermMatch? Match { get; set; }

  public double Timeout { get; set; } = 5;
  public double RetryInterval { get; set; } = 0.5;

  protected VerifyHeadingTriggerAttribute(TriggerEvents on, TriggerPriority priority = TriggerPriority.Medium)
  : base(on, priority)
  {
  }

  protected VerifyHeadingTriggerAttribute(TermMatch match, TriggerEvents on, TriggerPriority priority = TriggerPriority.Medium)
  : this(on, priority)
  {
  Match = match;
  }

  protected abstract string HeadingElementName { get; }

  public override void Execute<TOwner>(TOwner component)
  {
  var findAttribute = Index.HasValue
  ? new FindByIndexAttribute(Index.Value)
  : (FindAttribute)new FindByContentAttribute(ResolveMatch(Match), Values);

  var heading = component.Find(By.XPath($".//{HeadingElementName}").With(findAttribute));

  heading.Should.Within(Timeout, RetryInterval).BePresent();

  if (Values != null && Values.Length > 0)
  {
  heading.Content.Should.Within(Timeout, RetryInterval).Be(ResolveMatch(Match), Values);
  }
  }

  private TermMatch ResolveMatch(TermMatch? match) => match ?? TermMatch.Equals;
  }
 }

