namespace Histogram
{
    class Counter
    {
        static void Main(string[] args)
        {
            double mean = 50;
            double stddev = 4;
            int size = 100000;
            double[] data = new double[size];
            Random r = new Random();
            for (int c = 0; c < size; c++)
            {
                data[c] = r.NextDouble() * stddev + mean;
            }
            double mn = data.Average();
            double sd = Math.Sqrt(data.Sum(x => x * x) / size - mn * mn);
            Console.WriteLine("Sample mean = {0}; Stddev = {1}; max = {2}; min = {3} for {4} values", mn, sd, data.Max(), data.Min(), size);
            Chart chart = new Chart();
            chart.Width = 1000;
            chart.Height = 500;
            chart.ChartAreas.Add(new ChartArea());
            chart.ChartAreas[0].AxisX.Minimum = 0;
            chart.ChartAreas[0].AxisX.Maximum = 100;
            chart.ChartAreas[0].AxisY.Minimum = 0;
            chart.ChartAreas[0].AxisY.Maximum = 10000;
            chart.Series.Add(new Series());
            chart.Series[0].ChartType = SeriesChartType.Column;
            chart.Series[0].Points.DataBindY(data);
            chart.SaveImage("histogram.png", ChartImageFormat.Png);
        }
    }
}

