using System.Diagnostics.CodeAnalysis;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using NuPattern.ComponentModel;
using NuPattern.Modeling;

[TestClass]
[SuppressMessage("Microsoft.Design", "CA1063:ImplementIDisposableCorrectly")]
public class PatternElementSchemaDisplaySpec
{
    private DslTestStore testStore;
    private PatternModelSchema patternModelSchema;

    [TestInitialize]
    public void InitializeContext()
    {
        testStore = new DslTestStore();
        using (var transaction = testStore.CreateTransaction())
        {
            var patternModel = GivenAPatternModel();
            var authoredPattern = GivenAnAuthoredPattern(patternModel);
            patternModelSchema = authoredPattern.Schema;
            transaction.Commit();
        }
    }

    [TestMethod]
    public void TheValidationRulesPropertyIsBrowsableAndNotReadOnly()
    {
        var elementSchema = patternModelSchema.ElementSchemas.FirstOrDefault();
        Assert.IsNotNull(elementSchema, "Element schema should not be null");

        var validationRulesProperty = TypedDescriptor.GetProperties(elementSchema)
            .OfType<PropertyDescriptor>()
            .FirstOrDefault(p => p.Name == "ValidationRules");

        Assert.IsNotNull(validationRulesProperty, "ValidationRules property should exist");

        var browsableAttribute = validationRulesProperty.Attributes
            .OfType<BrowsableAttribute>()
            .FirstOrDefault();

        Assert.IsNotNull(browsableAttribute, "ValidationRules should have Browsable attribute");
        Assert.IsTrue(browsableAttribute.Browsable, "ValidationRules should be browsable");

        Assert.IsFalse(validationRulesProperty.IsReadOnly, "ValidationRules should not be read-only");
    }

    private PatternModel GivenAPatternModel()
    {
