using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
 
public static class LIS
{
    public static IEnumerable<T> FindRec<T>(IList<T> values, IComparer<T> comparer = null) =>
        values == null ? throw new ArgumentNullException() :
            FindRecImpl(values, Sequence<T>.Empty, 0, comparer ?? Comparer<T>.Default).Reverse();
 
    private static Sequence<T> FindRecImpl<T>(IList<T> values, Sequence<T> current, int index, IComparer<T> comparer) {
        if (index == values.Count) return current;
        if (current.Length > 0 && comparer.Compare(values[index], current.Value) <= 0)
            return FindRecImpl(values, current, index + 1, comparer);
        return Max(
            FindRecImpl(values, current, index + 1, comparer),
            FindRecImpl(values, current + values[index], index + 1, comparer)
        );
    }
 
    private static Sequence<T> Max<T>(Sequence<T> a, Sequence<T> b) => a.Length < b.Length ? b : a;
 
    class Sequence<T> : IEnumerable<T>
    {
        public static readonly Sequence<T> Empty = new Sequence<T>(default(T), null);
 
        public Sequence(T value, Sequence<T> tail)
        {
            Value = value;
            Tail = tail;
            Length = tail == null ? 0 : tail.Length + 1;
        }
 
        public T Value { get; }
        public Sequence<T> Tail { get; }
        public int Length { get; }
 
        public static Sequence<T> operator +(Sequence<T> s, T value) => new Sequence<T>(value, s);
 
        public IEnumerator<T> GetEnumerator()
        {
            for (var s = this; s.Length > 0; s = s.Tail) yield return s.Value;
        }
 
        IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
    }
}

using System;
 
public class Runner
{
        public static void Main()
        {
                uint i, c;
                for (i = c = 0; c < 25; i++)
                        if (is_pern(i))
                                Console.Write("{0} ", i), ++c;
                Console.WriteLine();
        }
 
        public static uint is_pern(uint n)
        {
                uint c = 2693408940u; // int with all prime-th bits set
                while (n!= 0) c >>= 1, n &= (n - 1); // take out lowerest set bit one by one
                return c & 1;
        }
}

using Orchard.ContentManagement;
using Orchard.ContentManagement.Drivers;
using Contrib.YoutubeField.ViewModels;

namespace Contrib.YoutubeField.Drivers
{
    public class YoutubeFieldDriver : ContentFieldDriver<Fields.YoutubeField>
    {
        protected override DriverResult Display(ContentPart part, Fields.YoutubeField field, string displayType, dynamic shapeHelper)
        {
            if (field.VideoId == null)
                return null;

            var viewModel = BuildViewModel(field);
            return ContentShape("Fields_Youtube",
                shape =>
                {
                    shape.Field = field;
                    shape.Part = part;
                    shape.ViewModel = viewModel;
                    shape.Prefix = GetPrefix(field, part);
                    return shape;
                });
        }

        protected override DriverResult Editor(ContentPart part, Fields.YoutubeField field, dynamic shapeHelper)
        {
            var viewModel = BuildViewModel(field);
            return ContentShape("Fields_Youtube_Edit",
                () =>
                {
                    var editorShape = shapeHelper.EditorTemplate(
                        TemplateName: "Fields/Youtube.Edit",
                        Model: viewModel,
                        Prefix: GetPrefix(field, part)
                    );
                    editorShape.Field = field;
                    editorShape.Part = part;
                    return editorShape;
                });
        }

        protected override DriverResult Editor(ContentPart part, Fields.YoutubeField field, IUpdateModel updater, dynamic shapeHelper)
        {
            var viewModel = new YoutubeFieldViewModel();

            if (updater.TryUpdateModel(viewModel, GetPrefix(field, part), null, null))
            {
                field.VideoId = viewModel.VideoId?.Trim();
                field.EmbedUrl = $"https://www.youtube.com/embed/{field.VideoId}";
            }

            return Editor(part, field, shapeHelper);
        }

        private static YoutubeFieldViewModel BuildViewModel(Fields.YoutubeField field)
        {
            return new YoutubeFieldViewModel
            {
                VideoId = field.VideoId,
                EmbedUrl = field.EmbedUrl,
                RawUrl = field.RawUrl
            };
        }

        private static string GetPrefix(Fields.YoutubeField field, ContentPart part)
        {
            return $"{part.PartDefinition.Name}.{field.Name}";
        }
    }
}

using System;
using System.Text;

class ExtractHTML
{
    static void Main()
    {
        string html = Console.In.ReadToEnd();
        string title = GetTitle(html);
        string bodyText = GetBodyText(html);
        Console.WriteLine("Title: " + title);
        Console.WriteLine("\nBody:");
        Console.WriteLine(bodyText);
    }

    static string GetTitle(string html)
    {
        int titleTagStart = html.IndexOf("<title>", StringComparison.OrdinalIgnoreCase);
        int titleTagEnd = html.IndexOf("</title>", StringComparison.OrdinalIgnoreCase);

        if (titleTagStart == -1 || titleTagEnd == -1 || titleTagEnd <= titleTagStart)
            return string.Empty;

        titleTagStart += 7;
        return html.Substring(titleTagStart, titleTagEnd - titleTagStart).Trim();
    }

    static string GetBodyText(string html)
    {
        int bodyTagIndex = html.IndexOf("<body>", StringComparison.OrdinalIgnoreCase);
        if (bodyTagIndex == -1) return string.Empty;

        StringBuilder extractedText = new StringBuilder();
        bool isText = false;
        bool insideScript = false;

        for (int i = bodyTagIndex + 6; i < html.Length; i++)
        {
            char currentChar = html[i];

            if (currentChar == '<')
            {
                if (i + 7 <= html.Length && html.Substring(i, 7).Equals("</body>", StringComparison.OrdinalIgnoreCase))
                    break;

                if (i + 7 <= html.Length && html.Substring(i, 7).Equals("<script>", StringComparison.OrdinalIgnoreCase))
                    insideScript = true;

                if (i + 8 <= html.Length && html.Substring(i, 8).Equals("</script>", StringComparison.OrdinalIgnoreCase))
                    insideScript = false;

                isText = false;
                continue;
            }

            if (currentChar == '>' && !insideScript)
            {
                isText = true;
                continue;
            }

            if (isText && !insideScript)
            {
                if (char.IsWhiteSpace(currentChar)
                {
                    if (extractedText.Length > 0 && !char.IsWhiteSpace(extractedText[extractedText.Length - 1]))
                        extractedText.Append(' ');
                }
                else
                {
                    extractedText.Append(currentChar);
                }
            }
        }

        return extractedText.ToString().Trim();
    }
}

