using System;
 using UnityEngine;

 public class PropertyAccessor : Accessor
 {
  private readonly MonoBehaviour target;
  private readonly string member;

  public PropertyAccessor(MonoBehaviour target, string member)
  {
  if (target == null)
  throw new ArgumentNullException("target");
  if (string.IsNullOrEmpty(member))
  throw new ArgumentException("Member name cannot be null or empty.", "member");

  this.target = target;
  this.member = member;
  }

  public TReturn Get<TReturn>()
  {
  if (target == null)
  {
  Debug.LogError("Target is null.");
  return default(TReturn);
  }

  object value = GetProperty(target, member);

  if (value == null)
  {
  Debug.LogWarning($"Property '{member}' not found or null on {target.GetType().Name}.");
  return default(TReturn);
  }

  return (TReturn)value;
  }

  private object GetProperty(MonoBehaviour target, string member)
  {
  return target.GetType().GetProperty(member)?.GetValue(target, null);
  }
 }

