namespace ForumExtensions.Modules
{
    public static class IModuleManagerExtensions
    {
        public static IEnumerable<TModule> GetAll<TModule>(
            this IModuleManager<TModule> moduleManager)
            where TModule : class, IModuleDefinition
        {
            CodeContracts.ArgumentNotNull(moduleManager, nameof(moduleManager));

            foreach (var module in moduleManager.GetAll(includeInactive: false))
            {
                if (module.IsActive)
                {
                    yield return module;
                }
            }
        }

        private static IEnumerable<TModule> GetAll<TModule>(
            this IModuleManager<TModule> moduleManager,
            bool includeInactive)
            where TModule : class, IModuleDefinition
        {
            CodeContracts.ArgumentNotNull(moduleManager, nameof(moduleManager));

            var allModules = moduleManager.GetAllModulesInternal();

            foreach (var module in allModules)
            {
                if (includeInactive || module.IsActive)
                {
                    yield return module;
                }
            }
        }

        private static IEnumerable<TModule> GetAllModulesInternal<TModule>(
            this IModuleManager<TModule> moduleManager)
            where TModule : class, IModuleDefinition
        {
            // Simulated underlying module retrieval logic
            return new List<TModule>
            {
                (TModule)Activator.CreateInstance(typeof(TModule), "Module1", true),
                (TModule)Activator.CreateInstance(typeof(TModule), "Module2", false),
                (TModule)Activator.CreateInstance(typeof(TModule), "Module3", true)
            };
        }
    }

    public interface IModuleManager<TModule> where TModule : IModuleDefinition
    {
        IEnumerable<TModule> GetAll(bool includeInactive);
    }

    public interface IModuleDefinition
    {
        string Name { get; }
        bool IsActive { get; }
    }

    public class ModuleDefinition : IModuleDefinition
    {
        public ModuleDefinition(string name, bool isActive)
        {
            Name = name;
            IsActive = isActive;
        }

        public string Name { get; }
        public bool IsActive { get; }
    }
}

