using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;

public class PartsUnlimitedContext : IdentityDbContext<ApplicationUser>
{
    private readonly string _connectionString;

    public DbSet<Product> Products { get; set; }
    public DbSet<Order> Orders { get; set; }
    public DbSet<Category> Categories { get; set; }
    public DbSet<ShoppingCart> ShoppingCarts { get; set; }
    public DbSet<CartItem> CartItems { get; set; }

    public PartsUnlimitedContext(DbContextOptions<PartsUnlimitedContext> options, string connectionString = null)
        : base(options)
    {
        _connectionString = connectionString;
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        if (!optionsBuilder.IsConfigured)
        {
            if (!string.IsNullOrEmpty(_connectionString))
            {
                optionsBuilder.UseSqlServer(_connectionString);
            }
            else
            {
                optionsBuilder.UseInMemoryDatabase("PartsUnlimitedInMemory");
            }
        }
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        base.OnModelCreating(modelBuilder);

        modelBuilder.Entity<Product>(entity =>
        {
            entity.HasKey(p => p.Id);
            entity.Property(p => p.Price).HasColumnType("decimal(18,2)");
            entity.HasOne(p => p.Category)
                .WithMany(c => c.Products)
                .HasForeignKey(p => p.CategoryId);
        });

        modelBuilder.Entity<Category>(entity =>
        {
            entity.HasKey(c => c.Id);
            entity.HasIndex(c => c.Name).IsUnique();
        });

        modelBuilder.Entity<Order>(entity =>
        {
            entity.HasKey(o => o.Id);
            entity.HasOne(o => o.User)
                .WithMany(u => u.Orders)
                .HasForeignKey(o => o.UserId)
                .OnDelete(DeleteBehavior.Restrict);
            entity.Property(o => o.Total).HasColumnType("decimal(18,2)");
        });

        modelBuilder.Entity<ShoppingCart>(entity =>
        {
            entity.HasKey(s => s.Id);
            entity.HasOne(s => s.User)
                .WithMany()
                .HasForeignKey(s => s.UserId);
            entity.Ignore(s => s.FormattedTotal);
        });

        modelBuilder.Entity<CartItem>(entity =>
        {
            entity.HasKey(i => i.Id);
            entity.HasOne(i => i.Product)
                .WithMany()
                .HasForeignKey(i => i.ProductId);

using System;
using System.IO;
 
namespace TruncateFile
{
    internal class Counter
    {
        private static void Main(string[] args)
        {
            TruncateFile(args[0], long.Parse(args[1]));
        }
 
        private static void TruncateFile(string path, long length)
        {
            if (!File.Exists(path))
                throw new ArgumentException("No file found at specified path.", "path");
 
            using (var fileStream = new FileStream(path, FileMode.Open, FileAccess.Write))
            {
                if (fileStream.Length < length)
                    throw new ArgumentOutOfRangeException("length",
                                                          "The specified length is greater than that of the file.");
 
                fileStream.SetLength(length);
            }
        }
    }
}

