using BenchmarkDotNet.Engines;
using BenchmarkDotNet.Extensions;
using BenchmarkDotNet.Horology;
using BenchmarkDotNet.Reports;
using BenchmarkDotNet.Analysers;

public class ZeroMeasurementAnalyser : IAnalyser
{
    private const double FallbackCpuResolutionValue = 0.0001; // in seconds

    public IEnumerable<IAnalysisResult> Analyse(Summary summary)
    {
        foreach (var report in summary.Reports)
        {
            var hostEnvironmentInfo = report.HostEnvironmentInfo;
            var cpuFrequency = hostEnvironmentInfo.CpuInfo.FrequencyInHz > 0
                ? hostEnvironmentInfo.CpuInfo.FrequencyInHz
                : 1 / FallbackCpuResolutionValue;

            var measurements = report.AllMeasurements;
            var overheadMeasurements = measurements.Where(m => m.Operations == 0).ToList();
            var workloadMeasurements = measurements.Where(m => m.Operations > 0).ToList();

            if (workloadMeasurements.Count == 0)
            {
                continue;
            }

            var workloadStats = workloadMeasurements.GetStatistics();
            var overheadStats = overheadMeasurements.GetStatistics();

            bool isZeroMeasurement;
            if (overheadMeasurements.Count > 0)
            {
                isZeroMeasurement = ZeroMeasurementHelper.CheckZeroMeasurementTwoSamples(workloadStats, overheadStats);
            }
            else
            {
                isZeroMeasurement = ZeroMeasurementHelper.CheckZeroMeasurementOneSample(workloadStats, cpuFrequency);
            }

            if (isZeroMeasurement)
            {
                yield return CreateWarning(report);
            }
        }
    }

    private IAnalysisResult CreateWarning(BenchmarkReport report)
    {
        var message = $"Warning: The measured method's duration is indistinguishable from the duration of an empty method. This could indicate measurement inaccuracies or insufficient workload.";
        return new AnalysisResult(report, message);
    }
}

public static class ZeroMeasurementHelper
{
    public static bool CheckZeroMeasurementTwoSamples(Statistics workloadStats, Statistics overheadStats)
    {
        return workloadStats.Mean <= overheadStats.Mean;
    }

    public static bool CheckZeroMeasurementOneSample(Statistics workloadStats, double cpuFrequency)
    {
        var threshold = 1.0 / cpuFrequency; // in seconds
        return workloadStats.Mean <= threshold;
    }
}

