        /// Gets or sets the integer index of the row being edited.
        /// </summary>
        public int EditRowIndex
        {
            get
            {
                return _editRowIndex;
            }

            set
            {
                if (value < 0 || value >= _dataSupply.NumRows())
                {
                    EditRow = null;
                    return;
