namespace Editor
{
    public abstract class DivMathWithOuterBase: DivMath
    {
        protected RowContainer outerEquation;

        public DivMathWithOuterBase(EquationContainer parent)
            : base(parent)
        {
            outerEquation = new RowContainer(this);
            outerEquation.HAlignment = Editor.HAlignment.Right;
            //insideEquation.HAlignment = Editor.HAlignment.Right;
            childEquations.Add(outerEquation);
        }

        public override XElement Serialize()
        {
            XElement thisElement = new XElement(GetType().Name);
            thisElement.Add(insideEquation.Serialize());
            thisElement.Add(outerEquation.Serialize());
            return thisElement;
        }

        public override void DeSerialize(XElement xElement)
        {
            var elements = xElement.Elements().ToArray();
            insideEquation.DeSerialize(elements[0]);
            outerEquation.DeSerialize(elements[1]);
            CalculateSize();
        }

        public override void CalculateSize()
        {
            CalculateHeight();
            CalculateWidth();
        }

        protected override void CalculateWidth()
        {
            Width = Math.Max(insideEquation.Width, outerEquation.Width) + divMathSign.Width + LeftGap;
        }

        protected override void CalculateHeight()
        {
            Height = outerEquation.Height + insideEquation.Height + ExtraHeight;
            divMathSign.Height = insideEquation.FirstRow.Height + ExtraHeight;
        }

        public override double Left
        {
            get { return base.Left; }
            set
            {
                base.Left = value;
                divMathSign.Left = value + LeftGap;
                insideEquation.Right = Right;
                outerEquation.Right = Right;
            }
        }
    }
}

using System;

[AttributeUsage(AttributeTargets.Parameter)]
public class NamedParameterAttribute : Attribute
{
    public string Documentation { get; }
    public string ShortName { get; }
    public object DefaultValue { get; }
    public Type DefaultClass { get; }
    public object[] DefaultValues { get; }
    public Type[] DefaultClasses { get; }

    public NamedParameterAttribute(string documentation, string shortName, object defaultValue = null)
    {
        Documentation = documentation;
        ShortName = shortName;
        DefaultValue = defaultValue;
        DefaultValues = Array.Empty<object>();
        DefaultClasses = Array.Empty<Type>();
    }

    public NamedParameterAttribute(string documentation, string shortName, object[] defaultValues, Type[] defaultClasses)
    {
        Documentation = documentation;
        ShortName = shortName;
        DefaultValues = defaultValues;
        DefaultClasses = defaultClasses;
    }

    public override string ToString()
    {
        string defaultValueStr = DefaultValue != null ? DefaultValue.ToString() : "None";
        string defaultValuesStr = DefaultValues.Length > 0 ? string.Join(", ", DefaultValues) : "None";
        string defaultClassesStr = DefaultClasses.Length > 0 ? string.Join(", ", DefaultClasses) : "None";

        return $"Documentation: {Documentation}, ShortName: {ShortName}, DefaultValue: {defaultValueStr}, " +
               $"DefaultValues: [{defaultValuesStr}], DefaultClasses: [{defaultClassesStr}]";
    }
}

