using System;
using System.Threading;
using Microsoft.CodeAnalysis;
using Microsoft.VisualStudio.LanguageServices;
using EnvDTE;

public class CPSProject
{
    private CodeModel _projectCodeModel;
    private VisualStudioWorkspace _visualStudioWorkspace;
    private Project _visualStudioProject;

    private class CPSCodeModelInstanceFactory
    {
        private readonly CPSProject _parentProject;

        public CPSCodeModelInstanceFactory(CPSProject project)
        {
            _parentProject = project;
        }

        public CodeModel GetCodeModel()
        {
            if (_parentProject._projectCodeModel == null)
            {
                lock (this)
                {
                    _parentProject._projectCodeModel ??= CreateProjectCodeModel();
                }
            }
            return _parentProject._projectCodeModel;
        }

        private CodeModel CreateProjectCodeModel()
        {
            try
            {
                return _parentProject._visualStudioProject?.CodeModel;
            }
            catch (Exception)
            {
                return null;
            }
        }

        public FileCodeModel GetFileCodeModel(string filePath)
        {
            var projectItem = GetProjectItem(filePath);
            return projectItem?.FileCodeModel
                ?? TryCreateFileCodeModelThroughProjectSystem(filePath);
        }

        private ProjectItem GetProjectItem(string filePath)
        {
            try
            {
                return _parentProject._visualStudioProject?.ProjectItems
                    .Cast<ProjectItem>()
                    .FirstOrDefault(item =>
                        item.FileNames[0].Equals(filePath, StringComparison.OrdinalIgnoreCase));
            }
            catch
            {
                return null;
            }
        }

        private FileCodeModel TryCreateFileCodeModelThroughProjectSystem(string filePath)
        {
            try
            {
                var document = _parentProject._visualStudioWorkspace
                    .CurrentSolution
                    .GetDocumentIdsWithFilePath(filePath)
                    .FirstOrDefault();

                return document != null
                    ? _parentProject._visualStudioProject?.CodeModel?.CreateFileCodeModel(filePath)
                    : null;
            }
            catch
            {
                return null;
            }
        }
    }
}

using System;
using System.Linq;
 
public class MagicSquare
{
    public static void Main(string[] args)
    {
        var n = args.Length == 0? 4 : int.Parse(args[0]);
        if (n < 4 || n % 4!= 0)
        {
            Console.WriteLine("Please specify the size of the magic square, as a positive multiple of 4.");
            return;
        }
        var mc = (n * n + 1) * n / 2;
        Console.WriteLine("Magic constant: {0}", mc);
        var bits = 0b1001_0110_0110_1001u;
        var size = n * n;
        var width = size.ToString().Length + 1;
        var mult = n / 4;
        var i = 0;
        for (var r = 0; r < n; r++)
        {
            for (var c = 0; c < n; c++)
            {
                var bitPos = c / mult + (r / mult) * 4;
                Console.Write("{0, " + width + "}", (bits & (1 << bitPos))!= 0? i + 1 : size - i);
                i++;
            }
            Console.WriteLine();
        }
    }
}

