    /// <summary>
    /// Provides a standardized contract for managing digital asset fields.
    /// </summary>
    public interface IFieldsControl
    {
        /// <summary>
        /// Assigns the digital assets controller to the fields control.
        /// </summary>
        /// <param name="controller">An instance of the digital assets controller.</param>
        void SetController(IDigitalAssetsController controller);

        /// <summary>
        /// Sets the item view model for the fields control.
        /// </summary>
        /// <param name="itemModel">Digital asset item view model.</param>
        void SetItemViewModel(ItemViewModel itemModel);

        /// <summary>
        /// Adjusts the availability of the properties.
        /// </summary>
        /// <param name="isAvailable">True if properties should be available; otherwise, false.</param>
        void SetPropertiesAvailability(bool isAvailable);

        /// <summary>
        /// Adjusts the visibility of the properties.
        /// </summary>
        /// <param name="isVisible">True if properties should be visible; otherwise, false.</param>
        void SetPropertiesVisibility(bool isVisible);

        /// <summary>
        /// Prepares the properties by initializing or configuring them.
        /// </summary>
        void PrepareProperties();

        /// <summary>
        /// Saves any modifications made to the properties.
        /// </summary>
        void SaveProperties();
    }

