namespace TextAdventures.Quest.Scripts
{
    public class PlaySoundScriptConstructor : ScriptConstructorBase
    {
        public override string Keyword
        {
            get { return "play sound"; }
        }

        protected override IScript CreateInt(List<string> parameters)
        {
            return new PlaySoundScript(
                new Expression(parameters[0], GameLoader),
                new Expression(parameters[1], GameLoader),
                new Expression(parameters[2], GameLoader));
        }

        protected override int[] ExpectedParameters
        {
            get { return new int[] { 3 }; }
        }
    }

    public class PlaySoundScript : ScriptBase
    {
        private IFunction m_filename;
        private IFunction m_synchronous;
        private IFunction m_loop;

        public PlaySoundScript(IFunction function, IFunction synchronous, IFunction loop)
        {
            m_filename = function;
            m_synchronous = synchronous;
            m_loop = loop;
        }

        public override string Save(Context c)
        {
            return SaveScript("playsound", m_filename.Save(c), m_synchronous.Save(c), m_loop.Save(c));
        }
    }

    public class StopSoundScriptConstructor : ScriptConstructorBase
    {
        public override string Keyword
        {
            get { return "stop sound"; }
        }

        protected override IScript CreateInt(List<string> parameters)
        {
            return new StopSoundScript();
        }

        protected override int[] ExpectedParameters
        {
            get { return new int[] { 0 }; }
        }
    }

    public class StopSoundScript : ScriptBase
    {
        public StopSoundScript()
        {
        }

        public override string Save(Context c)
        {
            return "stopsound();";
        }
    }
}

using System;
using System.Runtime.InteropServices;

namespace Xilium.CefGlue.Interop
{
    [StructLayout(LayoutKind.Explicit, Size = 200)]
    internal unsafe struct cef_settings_t
    {
        [FieldOffset(0)] public UIntPtr size;
        [FieldOffset(8)] public int single_process;
        [FieldOffset(12)] public int no_sandbox;
        [FieldOffset(16)] public cef_string_t browser_subprocess_path;
        [FieldOffset(40)] public cef_string_t cache_path;
        [FieldOffset(64)] public cef_string_t user_data_path;
        [FieldOffset(88)] public int persist_session_cookies;
        [FieldOffset(92)] public int persist_user_preferences;
        [FieldOffset(96)] public cef_string_t user_agent;
        [FieldOffset(120)] public cef_string_t product_version;
        [FieldOffset(144)] public cef_string_t locale;
        [FieldOffset(168)] public cef_string_t log_file;
        [FieldOffset(192)] public CefLogSeverity log_severity;
        [FieldOffset(196)] public int remote_debugging_port;

        private static int _sizeof;

        static cef_settings_t()
        {
            _sizeof = Marshal.SizeOf(typeof(cef_settings_t));
        }

        public static cef_settings_t* Alloc()
        {
            var result = (cef_settings_t*)Marshal.AllocHGlobal(_sizeof);
            *result = new cef_settings_t();
            result->size = (UIntPtr)_sizeof;
            return result;
        }

        public static void Free(cef_settings_t* ptr)
        {
            Marshal.FreeHGlobal((IntPtr)ptr);
        }
    }
}

using ProtoBuf.Meta;
 using System;
 using System.Collections.Generic;
 using System.ComponentModel;

 public static class ProtoBufTypeModel
 {
  private static readonly Type[] _systemTypes = {
  typeof(string), typeof(int), typeof(bool), typeof(DateTime), typeof(decimal),
  typeof(double), typeof(float), typeof(long), typeof(short), typeof(byte),
  typeof(Guid)
  };

  public static void ConfigureAquaTypes(this RuntimeTypeModel model, bool configureDefaultSystemTypes = true)
  {
  AquaTypeModel.Configure(model);
  if (configureDefaultSystemTypes)
  {
  ConfigureDefaultSystemTypes(model);
  }
  }

  public static void ConfigureDefaultSystemTypes(this RuntimeTypeModel model)
  {
  foreach (var type in _systemTypes)
  {
  AddDynamicPropertyType(model, type);
  }
  }

  private static void AddDynamicPropertyType(RuntimeTypeModel model, Type type)
  {
  model.Add(type, false).SetSurrogate(typeof(DynamicProperty));
  }
 }

 public static class AquaTypeModel
 {
  public static void Configure(RuntimeTypeModel model)
  {
  // Register Aqua type system types
  // Example: model.Add(typeof(Aqua.TypeSystem.TypeX), false).SetSurrogate(typeof(Aqua.TypeSystem.TypeY));

  // Register Aqua dynamic object types
  // Example: model.Add(typeof(Aqua.Dynamic.DynamicObjectX), false).SetSurrogate(typeof(Aqua.Dynamic.DynamicObjectY));
  }
 }

 public class DynamicProperty
 {
  [DefaultValue(null)]
  public object Value { get; set; }
 }

