public class StructureBspClusterBlock
{
    public class ClusterData
    {
        public List<byte[]> VertexBufferData { get; set; } = new List<byte[]>();
    }

    private long resourcePointer;
    private long resourceLength;
    private ClusterData loadedData;

    public long GetResourcePointer() => resourcePointer;
    public long GetResourceLength() => resourceLength;
    public void SetResourcePointer(long pointer) => resourcePointer = pointer;
    public void SetResourceLength(long length) => resourceLength = length;

    public void LoadClusterData(IResourceBlock resourceCache, GeometryBlockInfo geometryBlockInfo)
    {
        if (loadedData != null)
            return;

        loadedData = new ClusterData();

        using (Stream resourceStream = resourceCache.GetResourceStream(GetResourcePointer(), GetResourceLength()))
        {
            if (resourceStream == null) return;

            using (BinaryReader reader = new BinaryReader(resourceStream))
            {
                var structureBspClusterDataBlockNew = (StructureBspClusterDataBlockNew)geometryBlockInfo;

                foreach (var vertexBuffer in structureBspClusterDataBlockNew.Section.VertexBuffers)
                {
                    resourceStream.Seek(vertexBuffer.Offset, SeekOrigin.Begin);
                    byte[] buffer = reader.ReadBytes((int)vertexBuffer.Size);
                    loadedData.VertexBufferData.Add(buffer);
                }
            }
        }
    }

    public void DeleteClusterData()
    {
        if (loadedData == null) return;

        foreach (var buffer in loadedData.VertexBufferData)
        {
            // Release vertex buffer data (e.g., setting to null or returning to a buffer pool)
            // Assuming GC will handle the deallocation of byte arrays.
        }

        loadedData = null;
    }
}

