using UnityEngine;
using System.Collections;
using UnityEngine.Networking;

public class PickupSpawner : NetworkBehaviour
{
    public GameObject pistol; // Future implementation
    public GameObject shotgun;
    public GameObject cannon;
    private GameObject pickup;

    private bool[] canSpawn;
    private float[] spawnTimes;
    public float waitBetweenSpawns = 10f;

    void Start()
    {
        int spawnPointCount = transform.childCount;
        canSpawn = new bool[spawnPointCount];
        spawnTimes = new float[spawnPointCount];

        for (int i = 0; i < spawnPointCount; i++)
        {
            canSpawn[i] = true;
            spawnTimes[i] = Time.time;
        }
    }

    void Update()
    {
        for (int i = 0; i < transform.childCount; i++)
        {
            Transform spawnPoint = transform.GetChild(i);
            if (canSpawn[i] && spawnPoint.childCount == 0)
            {
                if (Time.time - spawnTimes[i] >= waitBetweenSpawns)
                {
                    CmdSpawnPickup(i);
                    canSpawn[i] = false;
                    spawnTimes[i] = Time.time;
                }
            }
            else if (spawnPoint.childCount > 0)
            {
                canSpawn[i] = true;
            }
        }
    }

    [Command]
    void CmdSpawnPickup(int i)
    {
        Transform spawnPoint = transform.GetChild(i);
        int randomPickup = Random.Range(0, 2); // 0 for shotgun, 1 for cannon

        switch (randomPickup)
        {
            case 0:
                pickup = Instantiate(shotgun, spawnPoint.position, spawnPoint.rotation);
                break;
            case 1:
                pickup = Instantiate(cannon, spawnPoint.position, spawnPoint.rotation);
                break;
        }

        NetworkServer.Spawn(pickup);
    }
}

