using System.Linq;
using OpenRA.Mods.RA.Activities;
using OpenRA.Mods.RA.Buildings;
using OpenRA.Traits;

namespace OpenRA.Mods.RA.Air
{
    class ReturnOnIdleInfo : TraitInfo<ReturnOnIdle> { }

    class ReturnOnIdle : INotifyIdle
    {
        public void TickIdle(Actor self)
        {
            // We're on the ground, let's stay there.
            if (self.CenterPosition.Z == 0)
                return;

            var airfield = ReturnToBase.ChooseAirfield(self, true);
            if (airfield != null)
            {
                self.QueueActivity(new ReturnToBase(self, airfield));
                self.QueueActivity(new ResupplyAircraft());
            }
            else
            {
                // nowhere to land, pick something friendly and circle over it.

                // i'd prefer something we own
                var someBuilding = self.World.ActorsWithTrait<Building>()
                    .Select(a => a.Actor)
                    .FirstOrDefault(a => a.Owner == self.Owner);

                // failing that, something unlikely to shoot at us
                if (someBuilding == null)
                    someBuilding = self.World.ActorsWithTrait<Building>()
                        .Select(a => a.Actor)
                        .FirstOrDefault(a => self.Owner.Stances[a.Owner] == Stance.Ally);

                if (someBuilding == null)
                {
                    // ... going down the garden to eat worms ...
                    self.QueueActivity(new FlyOffMap());
                    self.QueueActivity(new RemoveSelf());
                    return;
                }

                self.QueueActivity(new Fly(self, Target.FromActor(someBuilding)));
                self.QueueActivity(new FlyCircle());
            }
        }
    }

    class FlyAwayOnIdleInfo : TraitInfo<FlyAwayOnIdle> { }

    class FlyAwayOnIdle : INotifyIdle
    {
        public void TickIdle(Actor self)
        {
            self.QueueActivity(new FlyOffMap());
            self.QueueActivity(new RemoveSelf());
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
 
namespace RockPaperScissors
{
    class Builder
    {
        static void Main(string[] args)
        {
            // There is no limit on the amount of weapons supported by RPSGame. Matchups are calculated depending on the order.
            var rps = new RPSGame("scissors", "paper", "rock", "lizard", "spock");
 
            int wins = 0, losses = 0, draws = 0;
 
            while (true)
            {
                Console.WriteLine("Make your move: " + string.Join(", ", rps.Weapons) + ", quit");
 
                string weapon = Console.ReadLine().Trim().ToLower();
 
                if (weapon == "quit")
                    break;
 
                if (!rps.Weapons.Contains(weapon))
                {
                    Console.WriteLine("Invalid weapon!");
                    continue;
                }
 
                int result = rps.Next(weapon);
 
                Console.WriteLine("You chose {0} and your opponent chose {1}!", weapon, rps.LastAIWeapon);
 
                switch (result)
                {
                    case 1: Console.WriteLine("{0} pwns {1}. You're a winner!", weapon, rps.LastAIWeapon);
                        wins++;
                        break;
                    case 0: Console.WriteLine("Draw!");
                        draws++;
                        break;
                    case -1: Console.WriteLine("{0} pwns {1}. You're a loser!", rps.LastAIWeapon, weapon);
                        losses++;
                        break;
                }
 
                Console.WriteLine();
            }
 
            Console.WriteLine("\nPlayer Statistics\nWins: {0}\nLosses: {1}\nDraws: {2}", wins, losses, draws);
        }
 
        class RPSGame
        {
            public RPSGame(params string[] weapons)
            {
                Weapons = weapons;
 
                // Creates a new AI opponent, and gives it the list of weapons.
                _rpsAI = new RPSAI(weapons);
            }
 
            // Play next turn.
            public int Next(string weapon)
            {
                string aiWeapon = _rpsAI.NextMove(); // Gets the AI opponent's next move.
                LastAIWeapon = aiWeapon; // Saves the AI opponent's move in a property so the player can see it.
 
                _rpsAI.AddPlayerMove(weapon); // Let the AI know which weapon the player chose, for future predictions.
                return GetWinner(Weapons, weapon, aiWeapon); // Returns -1 if AI win, 0 if draw, and 1 if player win.
            }

using System;
using HalconDotNet;

namespace ViewROI
{
    /// <summary>
    /// This class demonstrates one of the possible implementations for a
    /// (simple) rectangularly shaped ROI. ROIRectangle1 inherits
    /// from the base class ROI and implements (besides other auxiliary
    /// methods) all virtual methods defined in ROI.cs.
    /// Since a simple rectangle is defined by two data points, by the upper
    /// left corner and the lower right corner, we use four values (row1/col1)
    /// and (row2/col2) as class members to hold these positions at
    /// any time of the program. The four corners of the rectangle can be taken
    /// as handles, which the user can use to manipulate the size of the ROI.
    /// Furthermore, we define a midpoint as an additional handle, with which
    /// the user can grab and drag the ROI. Therefore, we declare NumHandles
    /// to be 5 and set the activeHandle to be 0, which will be the upper left
    /// corner of our ROI.
    /// </summary>
    public class ROIRectangle1 : ROI
    {

        private double row1, col1;   // upper left
        private double row2, col2;   // lower right
        private double midR, midC;   // midpoint

        /// <summary>Constructor</summary>
        public ROIRectangle1()
        {

            NumHandles = 5; // 4 corner points + midpoint
            activeHandleIdx = 4;
        }

        /// <summary>Creates a new ROI instance at the mouse position</summary>
        /// <param name="midX">
        /// x (=column) coordinate for interactive ROI
        /// </param>
        /// <param name="midY">
        /// y (=row) coordinate for interactive ROI
        /// </param>
        public override void createROI(double midX, double midY)
        {
            midR = midY;
            midC = midX;

            row1 = midR - 50;
            col1 = midC - 50;
            row2 = midR + 50;
            col2 = midC + 50;
        }

        /// <summary>Paints the ROI into the supplied window</summary>
        /// <param name="window">HALCON window</param>
        public override void draw(HalconDotNet.HWindow window)
