    [TestClass]
    public class AutoComplete
    {
        const string text = @"System Data:
  Type: Integer
  Value: 42

Language Constructs:
  Declare var;
  Function foo() { return var; }
  Class Test { void Method() { foo(); } }";

        private IList<string> DeclarationOptions(SourcePosition pos)
        {
            return new List<string> { "var", "foo", "Test" };
        }

        [TestMethod]
        public void VerifyDeclarationOptionsAtEveryPosition()
        {
            var compiler = CompilerBrowser.FromText(text);
            for (int offset = 0; offset < text.Length; offset++)
            {
                char ch = text[offset];
                if (ch == '\n' || ch == '\r')
                    continue;
                var pos = new SourcePosition(compiler.MainSource, offset);
                var options = DeclarationOptions(pos);
                AssertThat.Assert(options != null, "Declaration options null at offset " + offset);
                Logger.Info("Offset " + offset + " yields " + options.Count + " declarations.");
            }
        }

