namespace CellularAutomata
{
    class Checker
    {
        static void Main(string[] args)
        {
            Console.WriteLine(DisplayCA(90, 57, 31, 28));
        }
 
        static string DisplayCA(int rule, int width, int lines, int startIndex)
        {
            var result = new string[lines + 1];
            result[0] = $"Rule:{rule} Width:{width} Gen:{lines}";
            var ruleTest = HasBitAt(rule);
            var lineLoop = Enumerable.Range(0, lines).ToArray();
            var looper = Enumerable.Range(0, width).ToArray();
            var pLine = NumToLine(width);
 
            var nTarget = SetBitAt(0, startIndex);
            result[1] = pLine(nTarget);
            lineLoop.ToList().ForEach(i =>
            {
                var bitTest = GetBitAt(nTarget);
                looper.ToList().ForEach(j =>
                {
                    var l = bitTest(j == 0? width - 1 : j - 1);
                    var m = bitTest(j);
                    var r = bitTest(j == width - 1? 0 : j + 1);
                    nTarget = ruleTest(
                        Convert.ToInt32(new[] { l, m, r }.Select(x => x? 1 : 0).ToArray(), 2))
                       ? SetBitAt(nTarget, j)
                        : ClearBitAt(nTarget, j);
                });
                result[i + 1] = pLine(nTarget);
            });
            return string.Join("\n", result);
        }
 
        static Func<int, bool> HasBitAt(int val) => idx => ((val >> idx) & 1) == 1;
        static Func<int, int> GetBitAt(int val) => idx => (val >> idx) & 1;
        static int SetBitAt(int val, int idx) => val | (1 << idx);
        static int ClearBitAt(int val, int idx) => val & ~(1 << idx);
        static Func<int, string> NumToLine(int width) =>
            intVal =>
            {
                var test = HasBitAt(intVal);
                var looper = Enumerable.Range(0, width).ToArray();
                return string.Join("", looper.Select(i => test(i)? "#" : ".").Reverse());
            };
    }
}

using dnSpy.Contracts.Debugger;
using dnSpy.Contracts.Debugger.Engine.Evaluation;
