namespace Tangent.Transformations
{
    public class SingleValueAccessor : TransformationRule
    {
        public override TransformationType Type => TransformationType.NamedStep;
        public override int MaxTakeCount => 3;

        public override TransformationResult TryReduce(List<Expression> buffer, TransformationScope scope)
        {
            if (buffer.Count == 3) {
                if (buffer[0].NodeType == ExpressionNodeType.TypeAccess) {
                    var enumAccess = (TypeAccessExpression)buffer[0];
                    if (enumAccess.TypeConstant.ValueType is EnumType enumType) {
                        if (buffer[1].NodeType == ExpressionNodeType.Identifier && ((IdentifierExpression)buffer[1]).Identifier.Value == ".") {
                            if (buffer[2].NodeType == ExpressionNodeType.Identifier) {
                                var identifier = ((IdentifierExpression)buffer[2]).Identifier;
                                TangentType resultType = enumType.SingleValueTypeFor(identifier);
                                if (resultType != null) {
                                    return new TransformationResult(
                                        Enumerable.Empty<Expression>(),
                                        new TypeAccessExpression(new TypeConstant(resultType), buffer[0].SourceInfo),
                                        new List<Identifier>(){});
                                }
                            }
                        }
                    }
                }
            }

            return TransformationResult.Failure;
        }

    }
}

