using System;
using System.Collections.Generic;

public class Heap<T>
{
    private readonly List<T> _list;
    private readonly IComparer<T> _comparer;

    public int Count => _list.Count;

    public Heap(List<T> data, IComparer<T> comparer)
    {
        _list = data ?? throw new ArgumentNullException(nameof(data));
        _comparer = comparer ?? throw new ArgumentNullException(nameof(comparer));
        Heapify();
    }

    public T PopRoot()
    {
        if (Count == 0)
        {
            throw new InvalidOperationException("Heap is empty");
        }

        T root = _list[0];
        _list[0] = _list[Count - 1];
        _list.RemoveAt(Count - 1);
        HeapDown(0);
        return root;
    }

    public T PeekRoot()
    {
        if (Count == 0)
        {
            throw new InvalidOperationException("Heap is empty");
        }

        return _list[0];
    }

    public void Insert(T item)
    {
        _list.Add(item);
        HeapUp(Count - 1);
    }

    private void Heapify()
    {
        for (int i = Count / 2; i >= 0; i--)
        {
            HeapDown(i);
        }
    }

    private void HeapUp(int index)
    {
        while (index > 0 && _comparer.Compare(_list[index], _list[Parent(index)]) < 0)
        {
            SwapCells(index, Parent(index));
            index = Parent(index);
        }
    }

    private void HeapDown(int index)
    {
        int smallest = index;
        int left = LeftChild(index);
        int right = RightChild(index);

        if (SafeIndex(left) && _comparer.Compare(_list[left], _list[smallest]) < 0)
        {
            smallest = left;
        }

        if (SafeIndex(right) && _comparer.Compare(_list[right], _list[smallest]) < 0)
        {
            smallest = right;
        }

        if (smallest != index)
        {
            SwapCells(index, smallest);
            HeapDown(smallest);
        }
    }

    private int Parent(int index)
    {
        return (index - 1) / 2;
    }

    private int RightChild(int index)
    {
        return 2 * index + 2;
    }

    private int LeftChild(int index)
    {
        return 2 * index + 1;
    }

    private bool SafeIndex(int index)
    {
        return index >= 0 && index < Count;
    }

    private void SwapCells(int index1, int index2)
    {
        T temp = _list[index1];
        _list[index1] = _list[index2];
        _list[index2] = temp;
    }
}

