    protected string DeliveredMessageBody;
    protected byte[] OriginalBody;
    protected string OriginalProperties;
    protected (string ConsumerTag, ulong DeliverTag) DeliveredMessageInfo;
    protected MockBuilder MockBuilder = new MockBuilder();

    public void StartConsumer(Action<string, byte[], string, (string ConsumerTag, ulong DeliverTag)> consumer)
    {
        MockBuilder.Consumer.Received().Received(
            Arg.Any<string>(),
            Arg.Any<ReadOnlyMemory<byte>>(),
            Arg.Any<ReadOnlyMemory<byte>>(),
            Arg.Any<string>(),
            Arg.Any<Action<ulong>>());

        MockBuilder.Consumer.Received().Received(
            Arg.Do<string>(s => DeliveredMessageBody = s),
            Arg.Do<ReadOnlyMemory<byte>>(bytes => OriginalBody = bytes.ToArray()),
            Arg.Do<ReadOnlyMemory<byte>>(properties => OriginalProperties = System.Text.Encoding.UTF8.GetString(properties.ToArray())),
            Arg.Do<string>(consumerTag => DeliveredMessageInfo = (consumerTag, 123)),
            Arg.Do<Action<ulong>>(ack => ack(123)));

        ConsumerWasInvoked = true;
    }

    public void DeliverMessage(string messageBody, string properties = "{}")
    {
        MockBuilder.Consumer.InvokeMessageReceived(messageBody, System.Text.Encoding.UTF8.GetBytes(properties), "consumer-tag", 123);
    }
}

