using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using NLog;

public class DbAuthenticate
{
    private static Logger logger = LogManager.GetCurrentClassLogger();

    public class User
    {
        public int Id { get; set; }
        public string Email { get; set; }
        public string Password { get; set; }
        public int CompanyId { get; set; }
        public bool IsDeleted { get; set; }
        public string AcquisitionType { get; set; }
    }

    public class UserException : Exception
    {
        public UserException(string message) : base(message) { }
    }

    public interface IUnitOfWork
    {
        User GetUserByEmail(string email);
        bool CheckCompanyAccess(int userId, string hostName);
    }

    public class CryptoUtil
    {
        public static string DecryptPassword(string encryptedPassword)
        {
            // Dummy implementation - replace with actual decryption logic
            return encryptedPassword + "_decrypted";
        }
    }

    public static User AuthenticateUser(string hostName, string email, string password, IUnitOfWork unitOfWork)
    {
        logger.Info($"Attempting authentication for user: {email} with hostname: {hostName}");

        User user = unitOfWork.GetUserByEmail(email);

        if (user == null)
        {
            logger.Warn($"User not found for email: {email}");
            throw new UserException("Invalid email or password.");
        }

        if (user.IsDeleted)
        {
            logger.Warn($"User is deleted: {email}");
            throw new UserException("User account is inactive.");
        }

        if (user.AcquisitionType != "ValidType")
        {
            logger.Warn($"Invalid acquisition type for user: {email}");
            throw new UserException("Invalid user account.");
        }

        if (!unitOfWork.CheckCompanyAccess(user.Id, hostName))
        {
            logger.Warn($"User does not have access to company for hostname: {hostName}");
            throw new UserException("Access denied.");
        }

        string decryptedPassword = CryptoUtil.DecryptPassword(user.Password);

        if (decryptedPassword != password)
        {
            logger.Warn($"Incorrect password for user: {email}");
            throw new UserException("Invalid email or password.");
        }

        logger.Info($"User authenticated successfully: {email}");
        return user;
    }
}

