    public ExternalLoginResult(string provider, string returnUrl)
    {
        _provider = provider;
        _returnUrl = returnUrl;
    }

    public override void ExecuteResult(ControllerContext context)
    {
        if (context == null)
        {
            throw new ArgumentNullException(nameof(context));
        }

        // Request authentication from the specified provider
        var authProperties = new AuthenticationProperties { RedirectUri = _returnUrl };
        var redirectContext = context.HttpContext.GetOAuthContext();

        // Initiating the authentication process for the provider
        OAuthWebSecurity.RequestAuthentication(_provider, authProperties);
    }
}

