namespace DataBindingUtilities
{
    /// <summary>
    /// A generic value converter that provides a pass-through implementation
    /// for type conversion in XAML data binding scenarios.
    /// </summary>
    /// <typeparam name="TSource">The source type of the conversion.</typeparam>
    /// <typeparam name="TTarget">The target type of the conversion.</typeparam>
    public class GenericConverter<TSource, TTarget> : IValueConverter
    {
        /// <summary>
        /// Converts the source value to the target type.
        /// </summary>
        /// <param name="value">The source value to convert.</param>
        /// <param name="targetType">The type of the target.</param>
        /// <param name="parameter">An optional conversion parameter.</param>
        /// <param name="language">The language of conversion.</param>
        /// <returns>The converted value or the original value if no conversion is possible.</returns>
        public object Convert(
            object value,
            Type targetType,
            object parameter,
            string language)
        {
            if (value is TSource sourceValue)
            {
                // Attempt direct type casting or return original value
                return (sourceValue is TTarget targetValue)
                    ? targetValue
                    : value;
            }

            return null;
        }

        /// <summary>
        /// Converts the target value back to the source type.
        /// </summary>
        /// <param name="value">The target value to convert back.</param>
        /// <param name="targetType">The type of the source.</param>
        /// <param name="parameter">An optional conversion parameter.</param>
        /// <param name="language">The language of conversion.</param>
        /// <returns>The converted value or the original value if no conversion is possible.</returns>
        public object ConvertBack(
            object value,
            Type targetType,
            object parameter,
            string language)
        {
            if (value is TTarget targetValue)
            {
                // Attempt direct type casting or return original value
                return (targetValue is TSource sourceValue)
                    ? sourceValue
                    : value;
            }

            return null;
        }
    }
}

