using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using OlympicGames.Core.Commands.Abstracts;
using OlympicGames.Core.Contracts;
using OlympicGames.Core.Factories;
using OlympicGames.Olympics.Contracts;
using OlympicGames.Utils;

namespace OlympicGames.Core.Commands
{
    public class CreateSprinterCommand : Command
    {
        private readonly IOlympicsFactory factory;
        private readonly IOlympicCommittee committee;

        public CreateSprinterCommand(IList<string> commandParameters, IOlympicsFactory factory, IOlympicCommittee committee)
            : base(commandParameters)
        {
            this.factory = factory;
            this.committee = committee;
        }

        public override string Execute()
        {
            if (this.CommandParameters.Count < 3)
            {
                throw new ArgumentException("Invalid number of parameters.");
            }

            string firstName = this.CommandParameters[0];
            string lastName = this.CommandParameters[1];
            string country = this.CommandParameters[2];

            Validator.ValidateIfNull(firstName, "FirstName");
            Validator.ValidateIfNull(lastName, "LastName");
            Validator.ValidateIfNull(country, "Country");

            Validator.ValidateMinAndMaxLength(firstName, 2, 20, "FirstName");
            Validator.ValidateMinAndMaxLength(lastName, 2, 20, "LastName");
            Validator.ValidateMinAndMaxLength(country, 3, 25, "Country");

            Dictionary<string, double> records = new Dictionary<string, double>();

            for (int i = 3; i < this.CommandParameters.Count; i += 2)
            {
                string eventName = this.CommandParameters[i];
                double time = double.Parse(this.CommandParameters[i + 1]);

                records.Add(eventName, time);
            }

            ISprinter sprinter = this.factory.CreateSprinter(firstName, lastName, country, records);
            this.committee.Olympians.Add(sprinter);

            StringBuilder output = new StringBuilder();
            output.AppendLine($"Created Sprinter:");
            output.AppendLine($"Name: {firstName} {lastName}");
            output.AppendLine($"Country: {country}");
            output.AppendLine("Records:");

            foreach (var record in records)
            {
                output.AppendLine($"  {record.Key}: {record.Value} seconds");
            }

            return output.ToString().TrimEnd();
        }
    }
}

