class MainClass
{
  public static void Main (string[] args)
  {
    bool[] is_open = new bool[100];
    int pass, door;
 
    /* do the 100 passes */
    for (pass = 0; pass < 100; ++pass)
      for (door = pass; door < 100; door += pass+1)
        is_open[door] =!is_open[door];
 
    /* output the result */
    for (door = 0; door < 100; ++door)
      Console.WriteLine("door #{0} is {1}.", door+1, (is_open[door]? "open" : "closed"));
  }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;

public interface IAllAssemblyFinder
{
    IEnumerable<Assembly> FindAllAssemblies();
}

public class DirectoryAssemblyFinder : IAllAssemblyFinder
{
    public IEnumerable<Assembly> FindAllAssemblies()
    {
        var path = AppDomain.CurrentDomain.BaseDirectory;
        var dllFiles = Directory.GetFiles(path, "*.dll", SearchOption.TopDirectoryOnly);

        foreach (var dll in dllFiles)
        {
            Assembly assembly = null;
            try
            {
                assembly = Assembly.LoadFrom(dll);
            }
            catch
            {
                continue;
            }

            if (assembly != null)
                yield return assembly;
        }
    }
}

public interface IEntityMapper { }

public class EntityMapperAssemblyFinder
{
    public IAllAssemblyFinder AllAssemblyFinder { get; set; } = new DirectoryAssemblyFinder();

    public IEnumerable<Assembly> FindAll()
    {
        return Find(a => true);
    }

    public IEnumerable<Assembly> Find(Func<Assembly, bool> predicate)
    {
        var candidateAssemblies = AllAssemblyFinder.FindAllAssemblies().ToList();
        var mappingAssemblies = new List<Assembly>();

        foreach (var assembly in candidateAssemblies)
        {
            try
            {
                var hasValidMappings = assembly.GetTypes()
                    .Any(t => t.IsClass &&
                             !t.IsAbstract &&
                             typeof(IEntityMapper).IsAssignableFrom(t));

                if (hasValidMappings && predicate(assembly))
                    mappingAssemblies.Add(assembly);
            }
            catch (ReflectionTypeLoadException)
            {
                continue;
            }
        }

        return mappingAssemblies.Distinct();
    }
}

