namespace ShippingVoyageManagement
{
    public interface IScheduleApplicationService
    {
        Task DelayScheduleAsync(Guid voyageId, TimeSpan delay);
    }

    public class ScheduleApplicationService : IScheduleApplicationService
    {
        private readonly ICommandBus _commandBus;

        public ScheduleApplicationService(ICommandBus commandBus)
        {
            _commandBus = commandBus ?? throw new ArgumentNullException(nameof(commandBus));
        }

        public async Task DelayScheduleAsync(Guid voyageId, TimeSpan delay)
        {
            if (voyageId == Guid.Empty)
            {
                throw new ArgumentException("Voyage ID must be provided", nameof(voyageId));
            }

            if (delay <= TimeSpan.Zero)
            {
                throw new ArgumentException("Delay duration must be greater than zero", nameof(delay));
            }

            var command = new VoyageDelayCommand(voyageId, delay);
            await _commandBus.PublishAsync(command);
        }
    }

    public class VoyageDelayCommand : ICommand
    {
        public Guid VoyageId { get; }
        public TimeSpan Delay { get; }

        public VoyageDelayCommand(Guid voyageId, TimeSpan delay)
        {
            VoyageId = voyageId;
            Delay = delay;
        }
    }

    public class CommandBus : ICommandBus
    {
        public async Task PublishAsync<TCommand>(TCommand command) where TCommand : ICommand
        {
            // Simulate command handling logic here
            await Task.Delay(100); // simulate asynchronous processing delay
            Console.WriteLine($"Command Published: {command.GetType().Name} for Voyage ID: {command.VoyageId}, Delay: {command.Delay}");
        }
    }

    public interface ICommand { }

    public interface ICommandBus
    {
        Task PublishAsync<TCommand>(TCommand command) where TCommand : ICommand;
    }

    public class Matrix
    {
        public static async Task Main(string[] args)
        {
            var commandBus = new CommandBus();
            var scheduleService = new ScheduleApplicationService(commandBus);

            var voyageId = Guid.NewGuid();
            var delay = TimeSpan.FromHours(3);

            await scheduleService.DelayScheduleAsync(voyageId, delay);
        }
    }
