public class ScalarValueTests
{
    private const int Count = 5;
    private SqliteConnection db;

#if TESTFRAMEWORK_MSTEST
    [TestInitialize]
#endif
#if NUNIT
    [SetUp]
#endif
    public void Setup()
    {
        db = new SqliteConnection("Data Source=:memory:");
        db.Open();
        CreateDb();
    }

    private void CreateDb()
    {
        using (var cmd = db.CreateCommand())
        {
            cmd.CommandText = @"
                CREATE TABLE TestTable (
                    Id INTEGER PRIMARY KEY AUTOINCREMENT,
                    Value INTEGER NOT NULL,
                    NullableValue INTEGER
                )";
            cmd.ExecuteNonQuery();

            for (int i = 1; i <= Count; i++)
            {
                cmd.CommandText = @"
                    INSERT INTO TestTable (Value, NullableValue)
                    VALUES (@val, @nullVal)";
                cmd.Parameters.AddWithValue("@val", i);
                cmd.Parameters.AddWithValue("@nullVal", i == 3 ? (object)i : DBNull.Value);
                cmd.ExecuteNonQuery();
                cmd.Parameters.Clear();
            }
        }
    }

#if TESTFRAMEWORK_MSTEST
    [TestMethod]
#endif
#if NUNIT
    [Test]
#endif
    public void Int32()
    {
        using (var cmd = db.CreateCommand())
        {
            cmd.CommandText = "SELECT SUM(Value) FROM TestTable";
            var result = cmd.ExecuteScalar();
            Assert.AreEqual(15, Convert.ToInt32(result));
        }
    }

#if TESTFRAMEWORK_MSTEST
    [TestMethod]
#endif
#if NUNIT
    [Test]
#endif
    public void SelectSingleRowValue()
    {
        using (var cmd = db.CreateCommand())
        {
            cmd.CommandText = "SELECT Value FROM TestTable WHERE Id = 3";
            var result = cmd.ExecuteScalar();
            Assert.AreEqual(3, (int)result);
        }
    }

#if TESTFRAMEWORK_MSTEST
    [TestMethod]
#endif
#if NUNIT
    [Test]
#endif
    public void SelectNullableSingleRowValue()
    {
        using (var cmd = db.CreateCommand())
        {
            cmd.CommandText = "SELECT NullableValue FROM TestTable WHERE Id = 3";
            var result = cmd.ExecuteScalar();
            int? value = result != DBNull.Value ? (int?)result : null;
            Assert.IsTrue(value.HasValue);
            Assert.AreEqual(3, value.Value);
        }
    }

