namespace Checker
{
    class Student
    {
        static void Main(string[] args)
        {
            var xs = " ".Split(' ');
            var ns = new int[] { 44, 42, 42, 41, 41, 41, 39 };
 
            var sorted = xs.Select((x, i) => new { name = x, score = ns[i] })
               .OrderByDescending(x => x.score)
               .ThenBy(x => x.name)
               .ToList();
 
            var names = sorted.Select(x => x.name).ToList();
            var scores = sorted.Select(x => x.score).ToList();
 
            var reversed = scores.OrderByDescending(x => x).ToList();
            var unique = scores.Distinct().ToList();
 
            var rankings = scores.Select((score, index) => new
            {
                name = names[index],
                score = score,
 
                Ordinal = index + 1,
 
                Standard = scores.IndexOf(score) + 1,
 
                Modified = reversed.Count - reversed.IndexOf(score),
 
                Dense = unique.IndexOf(score) + 1,
 
                Fractional = (scores.IndexOf(score) + 1 + reversed.Count - reversed.IndexOf(score)) / 2
            });
 
            var tbl = new List<List<object>> {
                new List<object> { "Name", "Score", "Standard", "Modified", "Dense", "Ordinal", "Fractional" }
            };
 
            tbl.AddRange(rankings.Select(x => new List<object> {
                x.name, x.score, x.Standard, x.Modified, x.Dense, x.Ordinal, x.Fractional
            }));
 
            var wikiTable = new StringBuilder();
 
            wikiTable.AppendLine("{| class=\"wikitable\"");
 
            foreach (var row in tbl)
            {
                wikiTable.AppendLine("|-");
 
                foreach (var cell in row)
                {
                    wikiTable.Append("| ");
 
                    if (cell == null)
                    {
                        wikiTable.Append(" ");
                    }
                    else
                    {
                        wikiTable.Append(cell.ToString());
                    }
 
                    wikiTable.Append(" ");
                }
            }
 
            wikiTable.AppendLine("|}");
 
            Console.WriteLine(wikiTable.ToString());
 
            Console.ReadKey();
        }
    }
}

