namespace ClassificationFramework
{
    /// <summary>
    /// Represents a classification result with a confidence score.
    /// </summary>
    public interface IClassificationResult
    {
        /// <summary>
        /// Gets the confidence score of the classification.
        /// </summary>
        double Confidence { get; }
    }

    /// <summary>
    /// Represents a class or category in a classification task.
    /// </summary>
    public interface IClassifierClass
    {
        /// <summary>
        /// Gets the name of the class.
        /// </summary>
        string Name { get; }
    }

    /// <summary>
    /// A generic classifier interface that defines the contract for classifying input features into a ranked set of classification results.
    /// </summary>
    /// <typeparam name="TClass">The type representing a classification class, must implement IClassifierClass.</typeparam>
    /// <typeparam name="TResult">The type representing a classification result, must implement IClassificationResult.</typeparam>
    /// <typeparam name="TFeature">The type representing a feature used in classification.</typeparam>
    public interface IClassifier<TClass, TResult, TFeature> : IEnumerable<TClass>
        where TClass : IClassifierClass
        where TResult : IClassificationResult
    {
        /// <summary>
        /// Gets an enumerable collection of all possible classes that the classifier can predict.
        /// </summary>
        IEnumerable<TClass> Classes { get; }

        /// <summary>
        /// Processes an array of input features and returns a sorted set of classification results ranked by confidence.
        /// </summary>
        /// <param name="features">An array of features used for classification.</param>
        /// <returns>A sorted set of classification results.</returns>
        SortedSet<TResult> Classify(TFeature[] features);
    }

    /// <summary>
    /// An example implementation of a classifier class, demonstrating how to utilize the IClassifier interface.
    /// </summary>
    /// <typeparam name="TClass">The type representing a classification class.</typeparam>
    /// <typeparam name="TResult">The type representing a classification result.</typeparam>
    /// <typeparam name="TFeature">The type representing a feature.</typeparam>
    public class ExampleClassifier<TClass, TResult, TFeature> : IClassifier<TClass, TResult, TFeature>
        where TClass : IClassifierClass
        where TResult : IClassificationResult, IComparable<TResult>

public class FIFO<T>
{
  class Node
  {
    public T Item { get; set; }
    public Node Next { get; set; }
  }
  Node first = null;
  Node last = null;
  public void push(T item)
  {
    if (empty())
    {
      //Uses object initializers to set fields of new node
      first = new Node() { Item = item, Next = null };
      last = first;
    }
    else
    {
      last.Next = new Node() { Item = item, Next = null };
      last = last.Next;
    }
  }
  public T pop()
  {
    if (first == null)
      throw new System.Exception("No elements");
    if (last == first)
      last = null;
    T temp = first.Item;
    first = first.Next;
    return temp;
  }
  public bool empty()
  {
    return first == null;
  }
}

