using UnityEngine;
using UnityEngine.SceneManagement;
using System.Collections;

public class Done_GameController : MonoBehaviour
{
    public GameObject[] hazards;
    public Vector3 spawnValues;
    public int hazardCount;
    public float spawnWait;
    public float startWait;
    public float waveWait;

    public GUIText scoreText;
    public GUIText restartText;
    public GUIText gameOverText;

    private bool gameOver;
    private bool restart;
    private int score;

    void Start ()
    {
        gameOver = false;
        restart = false;
        restartText.text = "";
        gameOverText.text = "";
        score = 0;
        UpdateScore ();
        StartCoroutine (SpawnWaves ());
    }

    void Update ()
    {
        if (restart)
        {
            if (Input.GetKeyDown (KeyCode.R))
            {
                SceneManager.LoadScene(SceneManager.GetActiveScene().buildIndex);
            }
        }
    }

    IEnumerator SpawnWaves ()
    {
        yield return new WaitForSeconds (startWait);
        while (true)
        {
            for (int i = 0; i < hazardCount; i++)
            {
                GameObject hazard = hazards [Random.Range (0, hazards.Length)];
                Vector3 spawnPosition = new Vector3 (Random.Range (-spawnValues.x, spawnValues.x), spawnValues.y, spawnValues.z);
                Quaternion spawnRotation = Quaternion.identity;
                Instantiate (hazard, spawnPosition, spawnRotation);
                yield return new WaitForSeconds (spawnWait);
            }
            yield return new WaitForSeconds (waveWait);

            if (gameOver)
            {
                restartText.text = "Press 'R' for Restart";
                restart = true;
                break;
            }
        }
    }

    public void AddScore (int newScoreValue)
    {
        score += newScoreValue;
        UpdateScore ();
    }

    void UpdateScore ()
    {
        scoreText.text = "Score: " + score;
    }

    public void GameOver ()
    {
        gameOverText.text = "Game Over!";
        gameOver = true;
    }
}

using Mpir.NET;
using System;
 
namespace Bernoulli
{
    class Service
    {
        private static void bernoulli(mpq_t rop, uint n)
        {
            mpq_t[] a = new mpq_t[n + 1];
 
            for (uint i = 0; i < n + 1; i++)
            {
                a[i] = new mpq_t();
            }
 
            for (uint m = 0; m <= n; ++m)
            {
                mpir.mpq_set_ui(a[m], 1, m + 1);
 
                for (uint j = m; j > 0; --j)
                {
                    mpir.mpq_sub(a[j - 1], a[j], a[j - 1]);
                    mpir.mpq_set_ui(rop, j, 1);
                    mpir.mpq_mul(a[j - 1], a[j - 1], rop);
                }
 
                mpir.mpq_set(rop, a[0]);
            }
        }
 
        static void Main(string[] args)
        {
            mpq_t rop = new mpq_t();
            mpz_t n = new mpz_t();
            mpz_t d = new mpz_t();
 
            for (uint  i = 0; i <= 60; ++i)
            {
                bernoulli(rop, i);
 
                if (mpir.mpq_cmp_ui(rop, 0, 1) != 0)
                {
                    mpir.mpq_get_num(n, rop);
                    mpir.mpq_get_den(d, rop);
                    Console.WriteLine(string.Format("B({0, 2}) = {1, 44} / {2}", i, n, d));
                }
            }
 
            Console.ReadKey();
        }
    }
}

using Db4objects.Db4o.Marshall;

namespace Db4objects.Db4o.Internal.Handlers
{
    /// <summary>
    /// Enables customized instantiation and persistence logic for objects
    /// in db4o's object database, separating construction from state management
    /// to optimize serialization/deserialization workflows.
    /// </summary>
    /// <remarks>
    /// Part of db4o's type handling framework. Collaborates with activation logic
    /// through IReferenceTypeHandler.Activate for full lifecycle management.
    /// </remarks>
    public interface IInstantiatingTypeHandler : IReferenceTypeHandler
    {
        /// <summary>
        /// Constructs object instances during deserialization using minimal
        /// persistent state from the read context
        /// </summary>
        /// <param name="context">
        /// Marshalling context providing access to stored object data.
        /// Contains database-specific marshalling state and buffers.
        /// </param>
        /// <returns>
        /// Object instance initialized with core immutable properties.
        /// Mutable state should remain uninitialized for later activation.
        /// </returns>
        /// <exception cref="DatabaseIntegrityException">
        /// Thrown when stored data fails validation checks
        /// </exception>
        object Instantiate(IReadContext context);

        /// <summary>
        /// Persists immutable object state during serialization
        /// </summary>
        /// <param name="context">
        /// Write context managing database storage operations.
        /// Handles buffer management and object graph traversal.
        /// </param>
        /// <param name="obj">
        /// Target object being serialized. Implementation should
        /// verify type compatibility before processing.
        /// </param>
        /// <exception cref="SerializationException">
        /// Thrown when object contains unserializable components
        /// </exception>
        /// <exception cref="TypeMismatchException">
        /// Thrown when provided object doesn't match handler's type
        /// </exception>
        void WriteInstantiation(IWriteContext context, object obj);

        // Inherited from IReferenceTypeHandler:
        // void Activate(IReferenceActivationContext context);
        // void Write(IWriteContext context, object obj);
        // ClassMetadata ClassMetadata { get; set; }
    }
}

