#if MODMANAGER_LOADS_FROM_MEMORY
        TheSprite = Resources.Load<Sprite>("Characters/DefaultCharacter");
        TheSpriteRenderer.sprite = TheSprite;
#else
        StartCoroutine(LoadSprite());
#endif
    }

    private void Update()
    {
        if (Input.GetKey(KeyCode.UpArrow))
        {
            transform.position += Vector3.up * Speed * Time.deltaTime;
        }
        if (Input.GetKey(KeyCode.DownArrow))
        {
            transform.position += Vector3.down * Speed * Time.deltaTime;
        }
        if (Input.GetKey(KeyCode.LeftArrow))
        {
            transform.position += Vector3.left * Speed * Time.deltaTime;
        }
        if (Input.GetKey(KeyCode.RightArrow))
        {
            transform.position += Vector3.right * Speed * Time.deltaTime;
        }
    }
    IEnumerator LoadSprite()
    {
        string theMod = "Mod";
        string theSpriteWWW = System.IO.Path.Combine(Application.dataPath, theMod + "/Character.png");
        WWW www = new WWW("file:///" + theSpriteWWW);
        yield return www;

        Texture2D texture = www.texture;
        TheSprite = Sprite.Create(texture, new Rect(0, 0, texture.width, texture.height), new Vector2(0.5f, 0.5f));
        TheSpriteRenderer.sprite = TheSprite;
    }
}

