namespace PasswordHandling
{
    // Base class for password services.
    public abstract class PasswordService
    {
        // Processes the password for storage.
        public abstract string ProcessPasswordForStorage(string plainTextPassword);

        // Compares an attempted password with the stored password.
        public abstract bool PasswordEquals(string storedPassword, string attempt);
    }

    // Clear text password service that performs no hashing or encryption.
    // Licensed under the Apache License, Version 2.0.
    public class ClearTextPasswordService : PasswordService
    {
        private string _storedPassword;

        // Initializes the service with a clear text password.
        public ClearTextPasswordService(string password)
        {
            _storedPassword = ProcessPasswordForStorage(password);
        }

        // Simply returns the provided password unaltered for storage.
        public override string ProcessPasswordForStorage(string plainTextPassword)
        {
            return plainTextPassword;
        }

        // Directly compares using case-sensitive ordinal rules.
        public override bool PasswordEquals(string storedPassword, string attempt)
        {
            return string.Equals(storedPassword, attempt, StringComparison.Ordinal);
        }

        // Verifies if the provided attempt matches the stored password.
        public bool VerifyPassword(string attempt)
        {
            return PasswordEquals(_storedPassword, attempt);
        }

        // For demonstration: displays whether the attempt is valid.
        public void DisplayVerificationResult(string attempt)
        {
            if (VerifyPassword(attempt))
            {
                Console.WriteLine("Password match: Access granted.");
            }
            else
            {
                Console.WriteLine("Password mismatch: Access denied.");
            }
        }
    }

    // Example usage of ClearTextPasswordService.
    class Validator
    {
        static void Main(string[] args)
        {
            // Create a new password service with a clear text password.
            ClearTextPasswordService passwordService = new ClearTextPasswordService("MySecret123");

            // Simulate a password attempt.
            Console.Write("Enter your password: ");
            string userAttempt = Console.ReadLine();

            // Display the verification result.
            passwordService.DisplayVerificationResult(userAttempt);

