using System;
using System.Collections.Generic;
using System.Text;

public class CharactersSpecificEndOfSentenceScanner
{
    private readonly HashSet<char> _endOfSentencePotentialCharacters;

    public CharactersSpecificEndOfSentenceScanner(IEnumerable<char> endOfSentenceCharacters)
    {
        _endOfSentencePotentialCharacters = new HashSet<char>(endOfSentenceCharacters);
    }

    public List<int> GetPositions(string input)
    {
        if (string.IsNullOrEmpty(input))
        {
            return new List<int>();
        }

        return FindEndOfSentencePositions(input.ToCharArray());
    }

    public List<int> GetPositions(StringBuilder input)
    {
        if (input == null || input.Length == 0)
        {
            return new List<int>();
        }

        return FindEndOfSentencePositions(input.ToString().ToCharArray());
    }

    public List<int> GetPositions(char[] input)
    {
        if (input == null || input.Length == 0)
        {
            return new List<int>();
        }

        return FindEndOfSentencePositions(input);
    }

    private List<int> FindEndOfSentencePositions(char[] input)
    {
        var positions = new List<int>();

        for (int i = 0; i < input.Length; i++)
        {
            if (_endOfSentencePotentialCharacters.Contains(input[i]))
            {
                positions.Add(i);
            }
        }

        return positions;
    }
}

// Example usage:
class Account
{
    static void Main()
    {
        var endOfSentenceCharacters = new List<char> { '.', '!', '?' };
        var scanner = new CharactersSpecificEndOfSentenceScanner(endOfSentenceCharacters);

        string input = "Hello world! How are you today? I hope you're well.";
        List<int> positions = scanner.GetPositions(input);

        Console.WriteLine("End of sentence positions:");
        foreach (var position in positions)
        {
            Console.WriteLine(position);
        }
    }
}

