namespace Playground
{
    public static class Palindrome
    {
        /// <summary>
        /// Tests if the given string slice is a palindrome (with the respect to
        /// codepoints, not graphemes).
        /// </summary>
        /// <param name="s">The string to test</param>
        /// <returns>True if the string is a palindrome, false otherwise</returns>
        /// <example>
        /// <code>
        /// Palindrome.IsPalindrome("abba"); // true
        /// Palindrome.IsPalindrome("baa"); // false
        /// </code>
        /// </example>
        public static bool IsPalindrome(string s)
        {
            var half = s.Length;
            return s.Take(half).SequenceEqual(s.Reverse().Take(half));
        }
    }
}

