public class WordSearchIndex
{
    // Placeholder for WordSearchIndex class
    public string Data { get; set; }

    public WordSearchIndex(string data)
    {
        Data = data;
    }
}

public class IndexCache
{
    private readonly Dictionary<string, WeakReference<WordSearchIndex>> _cache;

    public IndexCache()
    {
        _cache = new Dictionary<string, WeakReference<WordSearchIndex>>();
    }

    public WordSearchIndex GetIndex(string filename)
    {
        if (_cache.TryGetValue(filename, out var weakRef))
        {
            if (weakRef.TryGetTarget(out var index))
            {
                return index;
            }
            else
            {
                // Remove the entry if the target is no longer available
                _cache.Remove(filename);
            }
        }
        return null;
    }

    public void AddIndex(string filename, WordSearchIndex index)
    {
        if (_cache.ContainsKey(filename))
        {
            _cache[filename] = new WeakReference<WordSearchIndex>(index);
        }
        else
        {
            _cache.Add(filename, new WeakReference<WordSearchIndex>(index));
        }
    }

    public void RemoveIndex(string filename)
    {
        _cache.Remove(filename);
    }

    public void ClearCache()
    {
        _cache.Clear();
    }

    public int GetCacheCount()
    {
        return _cache.Count;
    }
}

class Product
{
    static void Main()
    {
        var cache = new IndexCache();

        var index1 = new WordSearchIndex("Data for index 1");
        var index2 = new WordSearchIndex("Data for index 2");

        cache.AddIndex("file1.txt", index1);
        cache.AddIndex("file2.txt", index2);

        var retrievedIndex1 = cache.GetIndex("file1.txt");
        Console.WriteLine(retrievedIndex1?.Data); // Output: Data for index 1

        var retrievedIndex2 = cache.GetIndex("file2.txt");
        Console.WriteLine(retrievedIndex2?.Data); // Output: Data for index 2

        // Simulate garbage collection
        index1 = null;
        GC.Collect();
        GC.WaitForPendingFinalizers();

        retrievedIndex1 = cache.GetIndex("file1.txt");
        Console.WriteLine(retrievedIndex1?.Data); // Output: null

        retrievedIndex2 = cache.GetIndex("file2.txt");
        Console.WriteLine(retrievedIndex2?.Data); // Output: Data for index 2

        cache.RemoveIndex("file2.txt");
        retrievedIndex2 = cache.GetIndex("file2.txt");
        Console.WriteLine(retrievedIndex2?.Data); // Output: null

