using Xunit;

public class TestUtility
{
    public static void DoRoundtripTest<T>(
        Func<byte[]> getOriginalDataStream,
        Func<byte[], T> parse,
        Func<T, byte[]> serialize,
        bool skipSizeCheck = false)
    {
        // Step 1: Get original byte data
        byte[] originalUncompressedBytes = getOriginalDataStream();

        // Step 2: Parse the original byte data into the specified data type
        T parsedFile;
        try
        {
            parsedFile = parse(originalUncompressedBytes);
        }
        catch (Exception ex)
        {
            string originalData = BitConverter.ToString(originalUncompressedBytes);
            throw new Exception($"Parsing failed. Original data: {originalData}, Exception: {ex.Message}");
        }

        // Step 3: Serialize the parsed data back into a byte array
        byte[] serializedBytes = serialize(parsedFile);

        // Optional Step 4: Check for size equality if not skipped
        if (!skipSizeCheck)
        {
            Assert.Equal(originalUncompressedBytes.Length, serializedBytes.Length);
        }

        // Step 5: Check if the original and serialized data match
        Assert.True(CompareArrays(originalUncompressedBytes, serializedBytes), "The original and serialized data do not match.");
    }

    private static bool CompareArrays(byte[] original, byte[] serialized)
    {
        if (original.Length != serialized.Length)
        {
            return false;
        }

        for (int i = 0; i < original.Length; i++)
        {
            if (original[i] != serialized[i])
            {
                return false;
            }
        }

        return true;
    }
}

