public class DutyService : IDutyService
{
    private readonly IUnitOfWork _unitOfWork;
    private readonly IRoleRepository _roleRepository;
    private readonly IHttpContextAccessor _httpContextAccessor;
    private readonly IMapper _mapper;

    public DutyService(
        IUnitOfWork unitOfWork,
        IRoleRepository roleRepository,
        IHttpContextAccessor httpContextAccessor,
        IMapper mapper)
    {
        _unitOfWork = unitOfWork;
        _roleRepository = roleRepository;
        _httpContextAccessor = httpContextAccessor;
        _mapper = mapper;
    }

    public async Task<List<RoleViewModel>> GetList(string keyword)
    {
        var query = await _roleRepository.GetQueryable();

        if (!string.IsNullOrEmpty(keyword))
        {
            query = query.Where(r =>
                r.Name.Contains(keyword) ||
                r.Code.Contains(keyword)
            );
        }

        var roles = await query.ToListAsync();
        return _mapper.Map<List<RoleViewModel>>(roles);
    }

    public async Task<RoleViewModel> GetForm(string id)
    {
        var role = await _roleRepository.FindByIdAsync(id);

        if (role == null)
            throw new NotFoundException("Role not found");

        return _mapper.Map<RoleViewModel>(role);
    }

    public async Task Delete(string id)
    {
        var role = await _roleRepository.FindByIdAsync(id);

        if (role == null)
            throw new NotFoundException("Role not found");

        _roleRepository.Remove(role);
        await _unitOfWork.SaveChangesAsync();
    }

    public async Task<RoleViewModel> Save(RoleViewModel model)
    {
        var currentUser = _httpContextAccessor.HttpContext?.User;

        if (string.IsNullOrEmpty(model.Id))
        {
            var newRole = _mapper.Map<RoleEntity>(model);
            newRole.Id = Guid.NewGuid().ToString();
            newRole.CreatedBy = currentUser?.Identity?.Name;
            newRole.CreatedTime = DateTime.UtcNow;

            await _roleRepository.AddAsync(newRole);
            await _unitOfWork.SaveChangesAsync();

            return _mapper.Map<RoleViewModel>(newRole);
        }
        else
        {
            var existingRole = await _roleRepository.FindByIdAsync(model.Id);

            if (existingRole == null)
                throw new NotFoundException("Role not found");

            _mapper.Map(model, existingRole);
            existingRole.ModifiedBy = currentUser?.Identity?.Name;
            existingRole.ModifiedTime = DateTime.UtcNow;

            _roleRepository.Update(existingRole);

