public enum FadeState
{
    None,
    FadingIn,
    FadingOut
}

public class UIElementFadeData
{
    public Color OriginalColor;
    public float Alpha;
    public FadeState State;

    public UIElementFadeData(Color original)
    {
        OriginalColor = original;
        Alpha = original.a;
        State = FadeState.None;
    }
}

public abstract class UIFadeController : MonoBehaviour
{
    // Dictionary mapping UI Graphics to their fade tracking data
    protected Dictionary<Graphic, UIElementFadeData> uiElements = new Dictionary<Graphic, UIElementFadeData>();

    // Speed of fade transition per second
    [SerializeField]
    protected float fadeSpeed = 1.0f;

    // Register a UI element for fade control
    public virtual void AddUIElement(Graphic graphic)
    {
        if (graphic != null && !uiElements.ContainsKey(graphic))
        {
            uiElements.Add(graphic, new UIElementFadeData(graphic.color));
        }
    }

    // Unregister a UI element
    public virtual void RemoveUIElement(Graphic graphic)
    {
        if (graphic != null && uiElements.ContainsKey(graphic))
        {
            uiElements.Remove(graphic);
        }
    }

    // Initiate a fade-in effect on the specified UI element
    public virtual void Show(Graphic graphic)
    {
        if (graphic != null && uiElements.ContainsKey(graphic))
        {
            UIElementFadeData data = uiElements[graphic];
            data.State = FadeState.FadingIn;
        }
    }

    // Initiate a fade-out effect on the specified UI element
    public virtual void Hide(Graphic graphic)
    {
        if (graphic != null && uiElements.ContainsKey(graphic))
        {
            UIElementFadeData data = uiElements[graphic];
            data.State = FadeState.FadingOut;
        }
    }

    // Coroutine that waits while any fade transition is active
    public virtual IEnumerator WaitInFading()
    {
        while (IsAnyFading())
        {
            yield return null;
        }
    }

    // Coroutine that waits until all UI elements are idle (i.e., no fading)
    public virtual IEnumerator WaitBusy()
    {
        yield return StartCoroutine(WaitInFading());
    }

    // Check if any UI element is currently undergoing a fade transition
    protected virtual bool IsAnyFading()
    {
        foreach (var data in uiElements.Values)
        {
            if (data.State != FadeState.None)
            {
                return true;
            }
        }
        return false;
    }

