            if (buf.Length > 0)
            {
                Console.Error.WriteLine("{0}: {1}", message, buf.ToString());
                LocalFree(buf.ToString());
            }
            else
            {
                Console.Error.WriteLine("{0}: unknown error 0x{1:X}", message, error);
            }
        }

        static int dotruncate(string fn, long fp)
        {
            IntPtr fh;

            fh = CreateFile(fn, 0x40000000, 0, IntPtr.Zero, 3, 0, IntPtr.Zero);
