            {
                oops(fn);
                return 1;
            }

            if (SetFilePointerEx(fh, fp, out fp, 0) == false || SetEndOfFile(fh) == false)
            {
                oops(fn);
                CloseHandle(fh);
                return 1;
            }

            CloseHandle(fh);
            return 0;
        }

