namespace Validator
{
    class Finder
    {
        static double getDifference(double b1, double b2)
        {
            double r = (b2 - b1) % 360.0;
            // Python modulus has same sign as divisor, which is positive here,
            // so no need to consider negative case
            if (r >= 180.0)
            {
                r -= 360.0;
            }
            return r;
        }
 
        static void Main(string[] args)
        {
            Console.WriteLine("Input in -180 to +180 range");
            Console.WriteLine(getDifference(20.0, 45.0));
            Console.WriteLine(getDifference(-45.0, 45.0));
            Console.WriteLine(getDifference(-85.0, 90.0));
            Console.WriteLine(getDifference(-95.0, 90.0));
            Console.WriteLine(getDifference(-45.0, 125.0));
            Console.WriteLine(getDifference(-45.0, 145.0));
            Console.WriteLine(getDifference(-45.0, 125.0));
            Console.WriteLine(getDifference(-45.0, 145.0));
            Console.WriteLine(getDifference(29.4803, -88.6381));
            Console.WriteLine(getDifference(-78.3251, -159.036));
 
            Console.WriteLine("Input in wider range");
            Console.WriteLine(getDifference(-70099.74233810938, 29840.67437876723));
            Console.WriteLine(getDifference(-165313.6666297357, 33693.9894517456));
            Console.WriteLine(getDifference(1174.8380510598456, -154146.66490124757));
            Console.WriteLine(getDifference(60175.77306795546, 42213.07192354373));
        }
    }
