public class ParkingRamp : ParkingConstruct
{
    [JsonIgnore]
    public List<ParkingFloor> Floors { get; private set; }
    [JsonIgnore]
    public Queue<Vehicle> InQueue { get; private set; }
    [JsonIgnore]
    public Queue<Vehicle> OutQueue { get; private set; }
    public string Name { get; set; }
    public int FloorCount { get; private set; }
    public int LocationCount { get; private set; }

    public ParkingRamp(string name, int floorCount, int locationsPerFloor)
    {
        Name = name;
        FloorCount = floorCount;
        LocationCount = locationsPerFloor * floorCount;
        Floors = new List<ParkingFloor>();
        InQueue = new Queue<Vehicle>();
        OutQueue = new Queue<Vehicle>();

        for (int i = 0; i < floorCount; i++)
        {
            Floors.Add(new ParkingFloor($"Floor {i + 1}", locationsPerFloor));
        }
    }

    public void Tick()
    {
        ProcessEntry();
        ProcessExit();
    }

    private void ProcessEntry()
    {
        while (InQueue.Count > 0 && OpenLocations > 0 && InQueue.Peek().EntryTime <= Simulator.CurrentTime)
        {
            var vehicle = InQueue.Dequeue();
            var availableFloors = Floors.Where(f => !f.IsFull).ToList();
            if (availableFloors.Any())
            {
                var selectedFloor = availableFloors[Simulator.Random.Next(availableFloors.Count)];
                selectedFloor.InQueue.Enqueue(vehicle);
            }
        }

        foreach (var floor in Floors)
        {
            floor.Tick();
        }
    }

    private void ProcessExit()
    {
        foreach (var floor in Floors)
        {
            while (floor.OutQueue.Count > 0)
            {
                var vehicle = floor.OutQueue.Dequeue();
                OutQueue.Enqueue(vehicle);
            }
        }
    }

    public int OpenLocations => Floors.Sum(f => f.OpenLocations);
}

public class ParkingFloor
{
    public string Name { get; set; }
    public int TotalLocations { get; private set; }
    public int OpenLocations => TotalLocations - InQueue.Count;
    public bool IsFull => OpenLocations == 0;
    [JsonIgnore]
    public Queue<Vehicle> InQueue { get; private set; }
    [JsonIgnore]
    public Queue<Vehicle> OutQueue { get; private set; }

    public ParkingFloor(string name, int totalLocations)
    {
        Name = name;
        TotalLocations = totalLocations;
        InQueue = new Queue<Vehicle>();
        OutQueue = new Queue<Vehicle>();
    }

    public void Tick()

using System;
using System.IO;
using Xunit;

public static class TestUtility
{
    public static T DoRoundtripTest<T>(
        Func<Stream> getOriginalStream,
        Func<Stream, T> parseCallback,
        Action<T, Stream> serializeCallback,
        bool compareBytes = true)
    {
        byte[] originalUncompressedBytes;
        byte[] serializedBytes;
        T parsedFile;

        try
        {
            using (Stream originalStream = getOriginalStream())
            {
                originalUncompressedBytes = originalStream.ToArray();
                originalStream.Position = 0;
                parsedFile = parseCallback(originalStream);
            }

            using (MemoryStream serializedStream = new MemoryStream())
            {
                serializeCallback(parsedFile, serializedStream);
                serializedBytes = serializedStream.ToArray();
            }
            if (compareBytes)
            {
                Assert.Equal(originalUncompressedBytes.Length, serializedBytes.Length);
                AssertUtility.Equal(originalUncompressedBytes, serializedBytes);
            }
        }
        catch (Exception)
        {
            File.WriteAllBytes("original.bin", originalUncompressedBytes);
            File.WriteAllBytes("serialized.bin", serializedBytes);
            throw;
        }
        return parsedFile;
    }

    private static byte[] ToArray(this Stream stream)
    {
        using (MemoryStream ms = new MemoryStream())
        {
            stream.CopyTo(ms);
            return ms.ToArray();
        }
    }
    private static class AssertUtility
    {
        public static void Equal(byte[] expected, byte[] actual) => Assert.Equal(expected, actual);
    }
}

using System;
using System.Runtime.InteropServices;
using System.Windows;
using System.Windows.Interop;

namespace WpfAppExtensions
{
    public static class ExtensionsParameterPassing
    {
        private const int WM_COPYDATA = 0x004A;

        public static void AddHookParameterPassing(this Window window, ParamPassing paramPassing)
        {
            if (paramPassing == null || paramPassing.ParameterPassedCallback == null)
                throw new ArgumentNullException(nameof(paramPassing), "ParamPassing configuration is required.");

            var hwndSource = PresentationSource.FromVisual(window) as HwndSource;
            if (hwndSource == null)
                throw new InvalidOperationException("Window must be initialized before adding the hook.");

            hwndSource.AddHook((IntPtr hwnd, int msg, IntPtr wParam, IntPtr lParam, ref bool handled) =>
            {
                if (msg == WM_COPYDATA)
                {
                    var data = Marshal.PtrToStructure<COPYDATASTRUCT>(lParam);
                    string parameters = Marshal.PtrToStringAnsi(data.lpData);

                    if (paramPassing.RestoreIfMinimized && window.WindowState == WindowState.Minimized)
                        window.WindowState = WindowState.Normal;

                    if (paramPassing.BringToForeground)
                        window.Activate();

                    paramPassing.ParameterPassedCallback?.Invoke(parameters);
                    handled = true;
                }
                return IntPtr.Zero;
            });
        }
    }

    public class ParamPassing
    {
        public Action<string> ParameterPassedCallback { get; set; }
        public bool RestoreIfMinimized { get; set; } = true;
        public bool BringToForeground { get; set; } = true;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct COPYDATASTRUCT
    {
        public IntPtr dwData;
        public int cbData;
        public IntPtr lpData;
    }
}

