            IFeedbackRepository feedbackRepository,
            IMessagingHubSender messageSender,
            FeedbackConfig config)
        {
            _feedbackRepository = feedbackRepository;
            _messageSender = messageSender;
            _config = config;
        }

        public async Task ReceiveAsync(Message message, CancellationToken cancellationToken)
        {
            try
            {
                var processedContent = ProcessContent(message.Content.ToString());
                var feedbackRecord = CreateFeedbackRecord(message, processedContent);

                var storageResult = await PersistFeedbackAsync(feedbackRecord);
                await SendUserNotification(message.From, storageResult, cancellationToken);
            }
            catch
            {
                await SendFallbackResponse(message.From, cancellationToken);
            }
        }

        private string ProcessContent(string input)
        {
            return string.IsNullOrWhiteSpace(input)
                ? string.Empty
                : input.Trim().ToLowerInvariant();
        }

