    {
        private bool _showInHexadecimal;
        private byte[] _lastData;
        private int _lastIdx;

        public UCViewData()
        {
            InitializeComponent();
            _showInHexadecimal = false;
            _lastData = Array.Empty<byte>();
            _lastIdx = -1;
            UpdateDisplay();
        }

        [Browsable(true)]
        [Category("Appearance")]
        [Description("Indicates whether to show the byte data in hexadecimal format.")]
        public bool ShowInHexadecimal
        {
            get => _showInHexadecimal;
            set
            {
                if (_showInHexadecimal != value)
                {
                    _showInHexadecimal = value;
                    UpdateDisplay();
                }
            }
        }

        [Browsable(false)]
        public byte[] Data
        {
            get => _lastData;
            set
            {
                _lastData = value ?? Array.Empty<byte>();
                UpdateDisplay();
            }
        }

        [Browsable(false)]
        public int SelectedIndex
        {
            get => _lastIdx;
            set
            {
                if (value != _lastIdx)
                {
                    _lastIdx = value;
                    UpdateDisplay();
                }
            }
        }

        private void UpdateDisplay()
        {
            if (_lastData.Length == 0 || _lastIdx < 0 || _lastIdx >= _lastData.Length)
            {
                ClearDisplay();
                return;
            }

            byte currentByte = _lastData[_lastIdx];

            string displayValue = _showInHexadecimal
                ? currentByte.ToString("X2")
                : currentByte.ToString();

            lblByteValue.Text = displayValue;
            lblAsInt32.Text = BitConverter.ToInt32(new byte[] { currentByte, 0, 0, 0 }, 0).ToString();
            lblAsInt16.Text = BitConverter.ToInt16(new byte[] { currentByte, 0 }, 0).ToString();
