        {
            Add(match);
        }
    }
}

public class SearchResult
{
    private readonly IDocument _document;
    private readonly WordInfoCollection _matches;
    private readonly Relevance _relevance;

    public SearchResult(IDocument document)
    {
        _document = document ?? throw new ArgumentNullException(nameof(document), "Document cannot be null");
        _matches = new WordInfoCollection();
        _relevance = new Relevance(0);
    }

    public IDocument Document => _document;

    public ReadOnlyCollection<string> Matches => new ReadOnlyCollection<string>(_matches);

    public Relevance Relevance => _relevance;

    public void AddMatch(string match)
    {
        _matches.AddMatch(match);
    }

    public void SetRelevanceScore(double score)
    {
        if (score < 0)
        {
            throw new ArgumentOutOfRangeException(nameof(score), "Relevance score cannot be negative");
        }

        // Assuming Relevance has a method or constructor to update score
        _relevance.Score = score;  // Assuming the Score property can be set
    }

    public override string ToString()
    {
        return $"{Document.Title} - Matches: {Matches.Count}, {Relevance}";
    }
}

