using System;
using System.Threading.Tasks;
using System.Web.Http;
using Microsoft.AspNet.Identity;
using System.Collections.Generic;

namespace YourNamespace
{
    public class AccountController : ApiController
    {
        private AuthRepository _repo = null;

        public AccountController()
        {
            _repo = new AuthRepository();
        }

        // POST api/Account/Register
        [AllowAnonymous]
        [Route("api/Account/Register")]
        public async Task<IHttpActionResult> Register(UserModel userModel)
        {
            if (!ModelState.IsValid)
            {
                return BadRequest(ModelState);
            }

            IdentityResult result = await _repo.RegisterUser(userModel);

            IHttpActionResult errorResult = GetErrorResult(result);

            if (errorResult != null)
            {
                return errorResult;
            }

            return Ok();
        }

        protected override void Dispose(bool disposing)
        {
            if (disposing)
            {
                _repo.Dispose();
            }

            base.Dispose(disposing);
        }

        private IHttpActionResult GetErrorResult(IdentityResult result)
        {
            if (result == null)
            {
                return InternalServerError();
            }

            if (!result.Succeeded)
            {
                if (result.Errors != null)
                {
                    foreach (string error in result.Errors)
                    {
                        ModelState.AddModelError("", error);
                    }
                }

                if (ModelState.IsValid)
                {
                    // No ModelState errors are available to send,
                    // so just return an empty BadRequest.
                    return BadRequest();
                }

                return BadRequest(ModelState);
            }

            return null;
        }
    }

    public class UserModel
    {
        public string UserName { get; set; }
        public string Password { get; set; }
        public string Email { get; set; } //Example property
    }

    public class AuthRepository : IDisposable
    {
        public Task<IdentityResult> RegisterUser(UserModel userModel) {
            return Task.FromResult(IdentityResult.Success); //Simplified for example
        }
        public void Dispose() { }

    }
}

using System;
using Xunit;
using ImageMagick;

namespace MagickNet.Tests
{
    public class MagickImageDefineTests
    {
        [Fact]
        public void SetAndRetrieveJpegDefines_ShouldWorkCorrectly()
        {
            // Arrange
            using (var image = new MagickImage())
            {
                var settings = new MagickSettings();

                // Act: Set various defines with different types
                settings.SetDefine(MagickFormat.Jpeg, "sampling-factor", "4:2:0");
                settings.SetDefine(MagickFormat.Jpeg, "optimize-coding", true);
                settings.SetDefine(MagickFormat.Jpeg, "quality", 85);
                settings.SetDefine(MagickFormat.Jpeg, "progressive", true);

                // Assert: Verify defines are set correctly
                Assert.Equal("4:2:0", settings.GetDefine(MagickFormat.Jpeg, "sampling-factor"));
                Assert.Equal("true", settings.GetDefine(MagickFormat.Jpeg, "optimize-coding"));
                Assert.Equal("85", settings.GetDefine(MagickFormat.Jpeg, "quality"));
                Assert.Equal("true", settings.GetDefine(MagickFormat.Jpeg, "progressive"));
            }
        }

        [Fact]
        public void SetDefinesWithDifferentFormats_ShouldManageIndependently()
        {
            // Arrange
            using (var image = new MagickImage())
            {
                var settings = new MagickSettings();

                // Act: Set defines for multiple formats
                settings.SetDefine(MagickFormat.Jpeg, "quality", 90);
                settings.SetDefine(MagickFormat.Png, "compression-level", 9);

                // Assert: Verify format-specific defines
                Assert.Equal("90", settings.GetDefine(MagickFormat.Jpeg, "quality"));
                Assert.Equal("9", settings.GetDefine(MagickFormat.Png, "compression-level"));
            }
        }

        [Fact]
        public void OverwriteAndRetrieveDefines_ShouldUpdateCorrectly()
        {
            // Arrange
            using (var image = new MagickImage())
            {
                var settings = new MagickSettings();

                // Act: Set and overwrite defines
                settings.SetDefine(MagickFormat.Jpeg, "quality", 75);
                settings.SetDefine(MagickFormat.Jpeg, "quality", 85);

                // Assert: Verify latest define value
                Assert.Equal("85", settings.GetDefine(MagickFormat.Jpeg, "quality"));
            }
        }
    }
}

using UnityEngine;
using System.Collections.Generic;
using CommonComponent;

namespace GameResource
{
    public class ResourceDataManager : ResourceSingleton<ResourceDataManager>
    {
        public Object Load(ulong pathHash, System.Type type)
        {
            ResourceData resourceData = _GetResourceData(pathHash);
            if (resourceData != null)
            {
                Log.Assert(resourceData.type == type);
                resourceData.AddRef();
                return resourceData.asset;
            }

            Object asset = null;

            if (ResourceMainfest.IsAssetBundleResource(pathHash))
            {
                AssetBundle assetBundle = AssetBundleManager.Instance.Load(pathHash);
                string name = ResourceMainfest.GetPathName(pathHash);
                if (assetBundle != null && !string.IsNullOrEmpty(name))
                {
                    asset = assetBundle.LoadAsset(name, type);
                }
                AssetBundleManager.Instance.Unload(pathHash);
            }

            if (asset == null)
            {
                string path = ResourceMainfest.GetHashPath(pathHash);
                if (!string.IsNullOrEmpty(path))
                {
                    asset = Resources.Load(path, type);
                }
            }

            if (asset != null)
            {
                resourceData = new ResourceData(pathHash, type, asset);
                resourceData.AddRef();
                _AddResourceData(resourceData);
            }

            return asset;
        }

