public class EngineExtend : Engine
{
    public override void ExecuteBirthCommand(string command)
    {
        var parts = command.Split(' ');
        if (parts.Length < 4)
        {
            Console.WriteLine("Insufficient parameters.");
            return;
        }

        var type = parts[1].ToLower();
        var name = parts[2];
        var x = int.Parse(parts[3]);
        var y = int.Parse(parts[4]);
        var position = new Point(x, y);

        switch (type)
        {
            case "wolf":
                AddOrganism(new Wolf(name, position));
                break;
            case "lion":
                AddOrganism(new Lion(name, position));
                break;
            case "grass":
                AddOrganism(new Grass(name, position));
                break;
            case "boar":
                AddOrganism(new Boar(name, position));
                break;
            case "zombie":
                AddOrganism(new Zombie(name, position));
                break;
            default:
                base.ExecuteBirthCommand(command);
                break;
        }

        Console.WriteLine($"Created {type} named {name} at {position.X}, {position.Y}");

