public class VboxLogWatcher : IDisposable
{
    private string logPath;
    private StreamWriter sw;
    private bool disposedValue = false;
    private const string logFileNameFormat = "VBoxLog_{0:yyyy-MM-dd_HH-mm-ss}.log";
    private DateTime startTime;

    public VboxLogWatcher(string vmLogDirectory)
    {
        // Set the log path
        logPath = Path.Combine(vmLogDirectory, "Logs");
        if (!Directory.Exists(logPath))
        {
            Directory.CreateDirectory(logPath);
        }

        // Initialize the log file
        string logFileName = string.Format(logFileNameFormat, DateTime.Now);
        sw = new StreamWriter(Path.Combine(logPath, logFileName), true);
        startTime = DateTime.Now;
    }

    public void OnLog(string logLevel, string message, params string[] tags)
    {
        if (sw == null) return;

        // Create a formatted log entry
        string formattedMessage = FormatLogMessage(logLevel, message, tags);

        // Write to the stream
        sw.WriteLine(formattedMessage);
        sw.Flush();
    }

    private string FormatLogMessage(string logLevel, string message, string[] tags)
    {
        TimeSpan elapsedTime = DateTime.Now - startTime;
        StringBuilder logEntry = new StringBuilder();

        logEntry.Append($"[{elapsedTime.TotalSeconds:F2}s] ");
        logEntry.Append($"[{logLevel}] ");

        if (tags != null && tags.Length > 0)
        {
            logEntry.Append($"[{string.Join(", ", tags)}] ");
        }

        logEntry.Append(message);
        return logEntry.ToString();
    }

    protected virtual void Dispose(bool disposing)
    {
        if (!disposedValue)
        {
            if (disposing)
            {
                // Dispose managed resources
                try
                {
                    sw?.Close();
                    sw?.Dispose();
                }
                catch (IOException ex)
                {
                    Console.Error.WriteLine($"Error disposing StreamWriter: {ex.Message}");
                }
            }

            // Dispose unmanaged resources if any here

            disposedValue = true;
        }
    }

    public void Dispose()
    {
        // Do not change this code. Put cleanup code in Dispose(bool disposing above.
        Dispose(disposing: true);
        GC.SuppressFinalize(this);
    }
}

