namespace GoToCSharp
{
    class Helper
    {
        static void Main(string[] args)
        {
            int[] a = { 170, 45, 75, -90, -802, 24, 2, 66 };
            Console.WriteLine("before: {0}", string.Join(", ", a));
            for (int inc = a.Length / 2; inc > 0; inc = (inc + 1) * 5 / 11)
            {
                for (int i = inc; i < a.Length; i++)
                {
                    int j = i, temp = a[i];
                    for (; j >= inc && a[j - inc] > temp; j -= inc)
                    {
                        a[j] = a[j - inc];
                    }
                    a[j] = temp;
                }
            }
            Console.WriteLine("after: {0}", string.Join(", ", a));
        }
    }
}

using System;
using System.IO;
using System.Text;
using System.Security.Cryptography;

public static class StreamExtensions
{
    public static byte[] ReadAllBytes(this Stream stream)
    {
        if (stream == null)
            throw new ArgumentNullException(nameof(stream));

        if (!stream.CanRead)
            throw new InvalidOperationException("Stream is not readable");

        using (var memoryStream = new MemoryStream())
        {
            stream.CopyTo(memoryStream);
            return memoryStream.ToArray();
        }
    }

    public static Func<Stream> ToStreamFactory(this Stream stream)
    {
        byte[] bytes = stream.ReadAllBytes();
        return () => new MemoryStream(bytes);
    }

    public static string ReadToEnd(this Stream stream, Encoding encoding = null)
    {
        encoding ??= Encoding.UTF8;

        using (var reader = new StreamReader(stream, encoding))
        {
            return reader.ReadToEnd();
        }
    }

    public static Stream AsStream(this string content, Encoding encoding = null)
    {
        encoding ??= Encoding.UTF8;
        return new MemoryStream(encoding.GetBytes(content));
    }

    public static bool ContentEquals(this Stream stream1, Stream stream2)
    {
        if (stream1 == null || stream2 == null)
            return stream1 == stream2;

        byte[] checksum1 = ComputeCrc32Checksum(stream1);
        byte[] checksum2 = ComputeCrc32Checksum(stream2);

        return checksum1.SequenceEqual(checksum2);
    }

    private static byte[] ComputeCrc32Checksum(Stream stream)
    {
        stream.Position = 0;
        using (var crc32 = new Crc32())
        {
            return crc32.ComputeHash(stream);
        }
    }

    private class Crc32 : HashAlgorithm
    {
        private const uint DefaultPolynomial = 0xEDB88320;
        private const uint DefaultSeed = 0xFFFFFFFF;
        private uint[] _table;
        private uint _hash;

        public Crc32()
        {
            _table = InitializeTable(DefaultPolynomial);
            Reset();
        }

        public override void Initialize()
        {
            Reset();
        }

        protected override void HashCore(byte[] buffer, int start, int length)
        {
            _hash = ComputeChecksum(_hash, buffer, start, length);
        }

        protected override byte[] HashFinal()
        {
            byte[] hashBytes = BitConverter.GetBytes(~_hash);
            Array.Reverse(hashBytes);
            return hashBytes;
        }

        private void Reset()
        {
            _hash = DefaultSeed;
        }

