using System;

public interface IVegetable
{
    string Name { get; }
    void Peel();
    void Cut();
}

public class Potato : IVegetable
{
    public string Name { get { return "Potato"; } }
    public bool IsPeeled { get; set; }
    public bool IsCut { get; set; }

    public void Peel() { IsPeeled = true; Console.WriteLine("Peeling potato..."); }
    public void Cut() { IsCut = true; Console.WriteLine("Cutting potato..."); }
}

public class Carrot : IVegetable
{
    public string Name { get { return "Carrot"; } }
    public bool IsPeeled { get; set; }
    public bool IsCut { get; set; }
    public void Peel() { IsPeeled = true; Console.WriteLine("Peeling carrot..."); }
    public void Cut() { IsCut = true; Console.WriteLine("Cutting carrot..."); }
}

public static class VegetableFactory
{
    public static IVegetable CreateVegetable(string type)
    {
        switch (type.ToLower())
        {
            case "potato": return new Potato();
            case "carrot": return new Carrot();
            default: throw new ArgumentException("Invalid vegetable type.");
        }
    }
}

public class Bowl
{
    public string GetBowl()
    {
        return "Vegetables are in the bowl!";
    }
}

public class Kitchen
{
    public void Cook()
    {
        IVegetable potato = VegetableFactory.CreateVegetable("potato");
        IVegetable carrot = VegetableFactory.CreateVegetable("carrot");

        potato.Peel();
        potato.Cut();

        carrot.Peel();
        carrot.Cut();

        Bowl bowl = new Bowl();
        Console.WriteLine(bowl.GetBowl());
    }
}

