public class ClosedWalletViewModel : WalletViewModelBase
{
    private ObservableCollection<NavBarItemViewModel> _items;
    public ClosedWalletViewModel(Wallet wallet, WalletManager walletManager) : base(wallet)
    {
        WalletManager = walletManager;
        _items = new();
    }

    public ObservableCollection<NavBarItemViewModel> Items
    {
        get => _items;
        set => _items = value;
    }

    public WalletManager WalletManager { get; }

    public override string IconName => "wallet_closed";

    public static ClosedWalletViewModel Create(Wallet wallet, WalletManager walletManager)
    {
        return wallet.KeyManager.IsHardwareWallet
            ? new ClosedHardwareWalletViewModel(wallet, walletManager)
            : wallet.KeyManager.IsWatchOnly
                ? new ClosedWatchOnlyWalletViewModel(wallet, walletManager)
                : new ClosedWalletViewModel(wallet, walletManager);
    }

    public override void OnNavigatedTo(bool isInHistory, CompositeDisposable disposables)
    {
        base.OnNavigatedTo(isInHistory, disposables);

        AbandonedTasks.AddAndClearCompleted(LoadWallet());
    }

    private async Task LoadWallet()
    {
        try
        {
            if (Wallet.State != WalletState.Uninitialized)
            {
                return;
            }

            Logger.LogTrace($"Starting {Wallet.WalletName}...");
            await WalletManager.StartWalletAsync(Wallet);
        }
        catch (Exception ex)
        {
            Logger.LogError(ex);
            await ShowErrorAsync(ex.ToUserFriendlyString());
        }
    }

    private async Task ShowErrorAsync(string message)
    {
    }
}

public static class ExceptionExtensions
{
    public static string ToUserFriendlyString(this Exception ex) => ex.Message;
}

