using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;
using System.Web.Caching;
using Microsoft.Web.Administration;

public class MimeExtractor
{
    private const string CacheKey = "MimeTypeCache";
    private const string CacheDictionaryKey = "MimeTypeDictionary";

    public static string GetMimeTypeForExtension(string extension)
    {
        if (string.IsNullOrEmpty(extension))
            throw new ArgumentException("Extension cannot be null or empty.");

        if (!extension.StartsWith("."))
            extension = "." + extension;

        var mimeDictionary = GetMimeTypeDictionary();
        if (mimeDictionary.ContainsKey(extension))
            return mimeDictionary[extension];

        return "application/octet-stream"; // Default MIME type
    }

    private static Dictionary<string, string> GetMimeTypeDictionary()
    {
        var cache = HttpContext.Current.Cache;
        var mimeDictionary = cache[CacheDictionaryKey] as Dictionary<string, string>;

        if (mimeDictionary == null)
        {
            mimeDictionary = ParseMimeTypes();
            cache.Insert(CacheDictionaryKey, mimeDictionary, null, Cache.NoAbsoluteExpiration, TimeSpan.FromHours(1));
        }

        return mimeDictionary;
    }

    private static Dictionary<string, string> ParseMimeTypes()
    {
        var results = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        var serverManager = new ServerManager();
        var siteName = HttpContext.Current.Request.Url.Host;

        var config = serverManager.GetApplicationHostConfiguration();
        var staticContentSection = config.GetSection("system.webServer/staticContent", siteName);
        var staticContentCollection = staticContentSection.GetCollection();

        foreach (var mimeMap in staticContentCollection)
        {
            var extension = mimeMap["fileExtension"].ToString();
            var mimeType = mimeMap["mimeType"].ToString();
            results[extension] = mimeType;
        }

        return results;
    }
}

