    public sealed class RichEditBoxContentDialog : ContentDialog
    {
        private readonly RichEditBox _richEditBox;
        public string Text { get; private set; }

        public RichEditBoxContentDialog(string initialText)
        {
            Title = "Edit Formatted Text";
            PrimaryButtonText = "OK";
            SecondaryButtonText = "Cancel";
            DefaultButton = ContentDialogButton.Primary;
            CornerRadius = new CornerRadius(8);
            Width = 600;
            MinWidth = 400;
            MaxWidth = 800;

            _richEditBox = new RichEditBox
            {
                AcceptsReturn = true,
                Height = 400,
                Margin = new Thickness(10),
                Padding = new Thickness(5),
                HorizontalAlignment = HorizontalAlignment.Stretch,
                VerticalAlignment = VerticalAlignment.Stretch,
                HorizontalScrollBarVisibility = ScrollBarVisibility.Auto,
                VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
                TextWrapping = TextWrapping.Wrap,
                BorderBrush = new SolidColorBrush(Windows.UI.Colors.LightGray),
                BorderThickness = new Thickness(1),
                FontSize = 14,
                SpellCheck = { IsEnabled = true },
                SelectionHighlightColor = new SolidColorBrush(Windows.UI.Colors.Blue) { Opacity = 0.3 }
            };

            _richEditBox.Document.SetText(TextSetOptions.FormatRtf, initialText);
            Opened += (s, e) => _richEditBox.Focus(FocusState.Programmatic);

            Content = new ScrollViewer
            {
                Content = _richEditBox,
                VerticalScrollMode = ScrollMode.Auto,
                HorizontalScrollMode = ScrollMode.Disabled
            };

            PrimaryButtonClick += OnPrimaryButtonClick;
            SecondaryButtonClick += OnSecondaryButtonClick;
        }

        private void OnPrimaryButtonClick(ContentDialog sender, ContentDialogButtonClickEventArgs args)
        {
            _richEditBox.Document.GetText(TextGetOptions.FormatRtf, out string result);
            Text = result;
        }

        private void OnSecondaryButtonClick(ContentDialog sender, ContentDialogButtonClickEventArgs args)
        {
            Text = null;
        }
    }
}

using UnityEngine;
using System.Collections.Generic;

public class StarItemController : A_ItemController
{
    public List<AddPositionGravity> refAddPositionGravityList;
    public int id;
    public float addScoreRate;
    public ReferenceChasePlayer refChasePlayer;
    public float completeFirstMoveDelay;
    private float cachedCompleteFirstMoveDelay;

    private void OnAwakeByPool()
    {
        cachedCompleteFirstMoveDelay = completeFirstMoveDelay;
        SetAllAddPositionGravityActive(false);
    }

    private void Update()
    {
        if (completeFirstMoveDelay > 0)
        {
            completeFirstMoveDelay -= Time.deltaTime;
            return;
        }

        if (refChasePlayer != null)
        {
            StartChasePlayer();
        }
    }

    private void StartChasePlayer()
    {
        transform.LookAt(refChasePlayer.transform);
        transform.position = Vector3.MoveTowards(transform.position, refChasePlayer.transform.position, Time.deltaTime * 5f);
    }

    private void OnPlayerCollide(Collider other)
    {
        if (other.CompareTag("Player"))
        {
            ScoreManager.Instance.AddScore(addScoreRate);
            SoundManager.Instance.PlaySound("StarCollect");
            Deactivate();
        }
    }

    private void SetAllAddPositionGravityActive(bool active)
    {
        foreach (var gravity in refAddPositionGravityList)
        {
            gravity.SetActive(active);
        }
    }

    public bool IsInInitialMovePhase()
    {
        return completeFirstMoveDelay > 0;
    }

    public override void Deactivate()
    {
        SetAllAddPositionGravityActive(false);
        completeFirstMoveDelay = cachedCompleteFirstMoveDelay;
        base.Deactivate();
    }
}

