        {
            this.keyword = keyword;
            this.parent = parent;
        }

        public KeywordKind Keyword
        {
            get
            {
                return this.keyword;
            }
        }

        public override QueryTokenKind Kind
        {
            get
            {
                return QueryTokenKind.Keyword;
            }
        }

        public override SegmentQueryToken Parent
        {
            get
            {
                return this.parent;
            }
        }

        public override string Name
        {
            get { return QueryTokenUtils.GetNameFromKeywordKind(this.Keyword); }
        }
    }

    internal abstract class SegmentQueryToken : QueryToken
    {
        public abstract SegmentQueryToken Parent { get; }
        public abstract string Name { get; }
    }
