public class WorkspaceRepository
{
    private readonly DbContext _context;
    private readonly DbSet<Workspace> _dbset;

    public WorkspaceRepository(DbContext context)
    {
        _context = context ?? throw new ArgumentNullException(nameof(context));
        _dbset = context.Set<Workspace>();
    }

    public Workspace Load(long id)
    {
        return _dbset.Find(id);
    }

    public static Workspace Load(DbContext context, long id)
    {
        if (context == null)
            throw new ArgumentNullException(nameof(context));

        return context.Set<Workspace>().Find(id);
    }

    public Workspace FindByPathMatch(string matchFilePath)
    {
        if (string.IsNullOrWhiteSpace(matchFilePath))
            throw new ArgumentException("File path cannot be empty", nameof(matchFilePath));

        string normalizedPath = NormalizePath(matchFilePath);

        return FindWorkspaceByHierarchicalMatch(normalizedPath);
    }

    private Workspace FindWorkspaceByHierarchicalMatch(string normalizedPath)
    {
        var candidates = _dbset
            .Where(w => normalizedPath.StartsWith(w.RootPath) || w.RootPath.StartsWith(normalizedPath))
            .ToList();

        return candidates
            .OrderByDescending(w => GetMatchScore(w.RootPath, normalizedPath))
            .FirstOrDefault();
    }

    private string NormalizePath(string path)
    {
        try
        {
            return Path.GetFullPath(path)
                .TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar)
                .ToLowerInvariant();
        }
        catch
        {
            return path.ToLowerInvariant();
        }
    }

    private int GetMatchScore(string workspacePath, string targetPath)
    {
        string[] workspaceParts = workspacePath.Split(
            Path.DirectorySeparatorChar,
            Path.AltDirectorySeparatorChar
        );

        string[] targetParts = targetPath.Split(
            Path.DirectorySeparatorChar,
            Path.AltDirectorySeparatorChar
        );

        int matchingSegments = 0;
        int minLength = Math.Min(workspaceParts.Length, targetParts.Length);

        for (int i = 0; i < minLength; i++)
        {
            if (string.Equals(
                workspaceParts[i],
                targetParts[i],
                StringComparison.OrdinalIgnoreCase))
            {
                matchingSegments++;
            }
            else
            {
                break;

