            {
                Title = p.DescripcionTitulo,
                Value = p.DescripcionUrl,
                Type = ActionTypes.DownloadFile
            }).ToList();

            listaAdjuntos.Add(tarjetaFormato.ToAttachment());
            IMessageActivity actividadTarjeta = context.MakeMessage();
