namespace Parser
{
    class Helper
    {
        static void Main(string[] args)
        {
            Num w = new Num(3);
            Num x = new Num(4);
            Console.WriteLine(w + x); //7
            Console.WriteLine(x - w); //1
            Console.WriteLine(w * x); //12
            Console.WriteLine(w / x); //0.75
            Console.WriteLine(w < x); //true
            Console.WriteLine(x < w); //false
            Num y = new Num(0); //TypeError
            Num z = new Num(11); //TypeError
        }
    }
    class Num
    {
        private int _value;
        public Num(int n)
        {
            n = (int)Math.Floor(n);
            if (double.IsNaN(n))
                throw new TypeError("Not a Number");
            if (n < 1 || n > 10)
                throw new TypeError("Out of range");
            this._value = n;
        }
        public static implicit operator Num(int n)
        {
            return new Num(n);
        }
        public static implicit operator int(Num n)
        {
            return n._value;
        }
        public static Num operator +(Num n1, Num n2)
        {
            return new Num(n1._value + n2._value);
        }
        public static Num operator -(Num n1, Num n2)
        {
            return new Num(n1._value - n2._value);
        }
        public static Num operator *(Num n1, Num n2)
        {
            return new Num(n1._value * n2._value);
        }
        public static Num operator /(Num n1, Num n2)
        {
            return new Num(n1._value / n2._value);
        }
        public static bool operator <(Num n1, Num n2)
        {
            return n1._value < n2._value;
        }
        public static bool operator >(Num n1, Num n2)
        {
            return n1._value > n2._value;
        }
    }
    class TypeError : Exception
    {
        public TypeError(string message)
            : base(message)
        {
        }
    }
}

