using UnityEngine;
using System.Collections;

public class MaterialSetMainColor : ActionNode
{
    public MaterialVar material;
    public ColorVar newMainColor;

    public override void Reset()
    {
        base.Reset();
        material = null;
        newMainColor = Color.white;
    }

    protected override NodeStatus OnUpdate()
    {
        Material targetMaterial = material.Value;

        if (targetMaterial == null)
        {
            Renderer renderer = gameObject.GetComponent<Renderer>();
            if (renderer != null && renderer.material != null)
            {
                targetMaterial = renderer.material;
            }
            else
            {
                Debug.LogError("No material provided and no renderer found on the game object.");
                return NodeStatus.Error;
            }
        }

        if (newMainColor == null)
        {
            Debug.LogError("New main color is not set.");
            return NodeStatus.Error;
        }

        targetMaterial.color = newMainColor.Value;
        return NodeStatus.Success;
    }
}

