public class StatsManager
{
    public delegate void FetchForPlayerCallback(CommonErrorStatus.ResponseStatus status, IntPtr playerData);

    [DllImport("GameLibrary")]
    private static extern void StatsManager_FetchForPlayer(HandleRef playerHandle, int dataSource, FetchForPlayerCallback callback);

    [DllImport("GameLibrary")]
    private static extern void StatsManager_FetchForPlayerResponse_Dispose(IntPtr response);

    [DllImport("GameLibrary")]
    private static extern CommonErrorStatus.ResponseStatus StatsManager_FetchForPlayerResponse_GetStatus(IntPtr response);

    [DllImport("GameLibrary")]
    private static extern IntPtr StatsManager_FetchForPlayerResponse_GetData(IntPtr response);

    public void FetchPlayerStats(HandleRef playerHandle, int dataSource, Action<CommonErrorStatus.ResponseStatus, PlayerStats> onComplete)
    {
#if UNITY_ANDROID || UNITY_IOS
        FetchForPlayerCallback callback = (status, playerData) =>
        {
            var playerStats = ProcessResponse(playerData);
            onComplete?.Invoke(status, playerStats);
        };

        StatsManager_FetchForPlayer(playerHandle, dataSource, callback);
#else
        Debug.LogWarning("StatsManager fetch is not supported on this platform.");
        onComplete?.Invoke(CommonErrorStatus.ResponseStatus.NotSupported, null);
#endif
    }

    private PlayerStats ProcessResponse(IntPtr playerDataPtr)
    {
        IntPtr responseHandle = playerDataPtr;
        try
        {
            var status = StatsManager_FetchForPlayerResponse_GetStatus(responseHandle);
            if (status == CommonErrorStatus.ResponseStatus.Success)
            {
                var playerData = StatsManager_FetchForPlayerResponse_GetData(responseHandle);
                return ExtractPlayerStats(playerData);
            }
            else
            {
                Debug.LogError("Failed to fetch stats: " + status);
                return null;
            }
        }
        finally
        {
            StatsManager_FetchForPlayerResponse_Dispose(responseHandle);
        }
    }

