namespace QuickSelect
{
    class Matrix
    {
        static void Main(string[] args)
        {
            int[] v = { 9, 8, 7, 6, 5, 0, 1, 2, 3, 4 };
            for (int i = 0; i < v.Length; i++)
            {
                Console.WriteLine(QuickSelect(v, i));
            }
            Console.ReadLine();
        }

        static int QuickSelect(int[] a, int k)
        {
            int[] arr = a.ToArray();
            while (true)
            {
                int pivot = arr[new Random().Next(arr.Length)];
                int[] left = arr.Where(x => x < pivot).ToArray();
                int[] right = arr.Where(x => x >= pivot).ToArray();
                if (k == left.Length)
                {
                    return pivot;
                }
                else if (k < left.Length)
                {
                    arr = left;
                }
                else
                {
                    k = k - left.Length - 1;
                    arr = right;
                }
            }
        }
    }
}

