public class ReleaseNotification
{
    public virtual string ToMessage(BotElement botElement, TextElement textElement, Dictionary<string, object> data)
    {
        return string.Empty;
    }

    public virtual bool GetRuleMatch(TfsEvents eventType, List<Rule> rules)
    {
        return rules.Any(rule => rule.EventType == eventType);
    }
}

public class Rule
{
    public TfsEvents EventType { get; set; }
    public string ProjectName { get; set; }
}

public class ReleaseCreatedNotification : ReleaseNotification
{
    private readonly Func<string, string> _escapeSpecialCharacters;

    public ReleaseCreatedNotification(Func<string, string> escapeSpecialCharacters)
    {
        _escapeSpecialCharacters = escapeSpecialCharacters;
    }

    public override string ToMessage(BotElement botElement, TextElement textElement, Dictionary<string, object> data)
    {
        var formatter = new DataFormatter(_escapeSpecialCharacters);
        var formattedData = formatter.FormatData(data);

        return string.Format(textElement.Template, formattedData.TeamProjectCollection, formattedData.ProjectName, formattedData.ReleaseName);
    }

    public override bool GetRuleMatch(TfsEvents eventType, List<Rule> rules)
    {
        return rules.Any(rule => rule.EventType == eventType && rule.ProjectName == (string)data["ProjectName"]);
    }
}

public class DataFormatter
{
    private readonly Func<string, string> _escapeSpecialCharacters;

    public DataFormatter(Func<string, string> escapeSpecialCharacters)
    {
        _escapeSpecialCharacters = escapeSpecialCharacters;
    }

    public (string TeamProjectCollection, string ProjectName, string ReleaseName) FormatData(Dictionary<string, object> data)
    {
        var teamProjectCollection = _escapeSpecialCharacters(data["TeamProjectCollection"].ToString());
        var projectName = _escapeSpecialCharacters(data["ProjectName"].ToString());
        var releaseName = _escapeSpecialCharacters(data["ReleaseName"].ToString());

        return (teamProjectCollection, projectName, releaseName);
    }
}

