namespace Dijkstra
{
    class Writer
    {
        static void Main(string[] args)
        {
            var graph = new List<Tuple<string, string, int>>();
            graph.Add(new Tuple<string, string, int>("a", "b", 7));
            graph.Add(new Tuple<string, string, int>("a", "c", 9));
            graph.Add(new Tuple<string, string, int>("a", "f", 14));
            graph.Add(new Tuple<string, string, int>("b", "c", 10));
            graph.Add(new Tuple<string, string, int>("b", "d", 15));
            graph.Add(new Tuple<string, string, int>("c", "d", 11));
            graph.Add(new Tuple<string, string, int>("c", "f", 2));
            graph.Add(new Tuple<string, string, int>("d", "e", 6));
            graph.Add(new Tuple<string, string, int>("e", "f", 9));
 
            var path = Dijkstra(graph, "a", "e");
            var length = path.Sum(x => x.Item3);
 
            Console.WriteLine(string.Join("->", path.Select(x => x.Item1)));
            Console.WriteLine(length);
 
            Console.ReadKey();
        }
 
        static List<Tuple<string, string, int>> Dijkstra(List<Tuple<string, string, int>> edges, string source, string target)
        {
            var Q = new HashSet<string>();
            var prev = new Dictionary<string, string>();
            var dist = new Dictionary<string, int>();
