using System;
using System.Drawing;
using System.Windows.Forms;
 
namespace BasicAnimation
{
  class BasicAnimationForm : Form
  {
    bool isReverseDirection;
    Label textLabel;
    Timer timer;
 
    internal BasicAnimationForm()
    {
      this.Size = new Size(150, 75);
      this.Text = "Basic Animation";
 
      textLabel = new Label();
      textLabel.Text = "Hello World! ";
      textLabel.Location = new Point(3,3);
      textLabel.AutoSize = true;
      textLabel.Click += new EventHandler(textLabel_OnClick);
      this.Controls.Add(textLabel);
 
      timer = new Timer();
      timer.Interval = 500;
      timer.Tick += new EventHandler(timer_OnTick);
      timer.Enabled = true;
 
      isReverseDirection = false;
    }
 
    private void timer_OnTick(object sender, EventArgs e)
    {
      string oldText = textLabel.Text, newText;
      if(isReverseDirection)
        newText = oldText.Substring(1, oldText.Length - 1) + oldText.Substring(0, 1);
      else
        newText = oldText.Substring(oldText.Length - 1, 1) + oldText.Substring(0, oldText.Length - 1);
      textLabel.Text = newText;
    }
 
    private void textLabel_OnClick(object sender, EventArgs e)
    {
      isReverseDirection = !isReverseDirection;
    }
  }
 
   class Task
   {
      static void Main()
      {
    Application.Run(new BasicAnimationForm());
      }
   }
}

using System;
using BI = System.Numerics.BigInteger;
 
class Matrix {
 
  // has multiple factors (other than 1 and x)
  static bool hmf(BI x) {
    if (x < 4) return x == 1;
    if ((x & 1) == 0 || x % 3 == 0) return true;
    int l = (int)Math.Sqrt((double)x); // this limit works because the 40th to 80th Motzkin numbers have factors of 2 or 3
    for (int j = 5, d = 4; j <= l; j += d = 6 - d)
      if (x % j == 0) return x > j;
    return false;
  }
 
  static void Main(string[] args) {
    BI a = 0, b = 1, t;
    int n = 1, s = 0, d = 1, c = 0, f = 1;
    while (n <= 80)
      Console.WriteLine("{0,46:n0} {1}",
        t = b / n++,
        hmf(t) ? "" : "is prime.",
        t = b,
        b = ((c += d * 3 + 3) * a +
             (f += d * 2 + 3) * b) /
             (s += d += 2),
        a = t);
  }
}

using System;
using System.Collections.Generic;
using System.IO;

public class TrackSection
{
    public int Id { get; set; }
    public string Name { get; set; }
    public List<string> Commands { get; set; } = new List<string>();

    public override string ToString()
    {
        return $"TrackSection Id: {Id}, Name: {Name}, Commands: [{string.Join(", ", Commands)}]";
    }
}

public class TrackSectionReadingResult
{
    public List<TrackSection> Sections { get; set; }
    public long UpdatedPosition { get; set; }

    public TrackSectionReadingResult(List<TrackSection> sections, long updatedPosition)
    {
        Sections = sections;
        UpdatedPosition = updatedPosition;
    }
}

public class TrackReader
{
    public TrackSectionReadingResult Read(BinaryReader reader, long startPosition)
    {
        List<TrackSection> sections = new List<TrackSection>();
        long position = startPosition;
        reader.BaseStream.Seek(position, SeekOrigin.Begin);

        while (position < reader.BaseStream.Length)
        {
            byte sectionType = reader.ReadByte();
            if (sectionType == 0xFF) // End of data marker
            {
                break;
            }

            if (sectionType == 0x01) // Track Section Start
            {
                TrackSection section = new TrackSection
                {
                    Id = reader.ReadInt32(),
                    Name = reader.ReadString()
                };

                ReadCommands(reader, section);
                sections.Add(section);
            }

            position = reader.BaseStream.Position;
        }

        return new TrackSectionReadingResult(sections, position);
    }

    private void ReadCommands(BinaryReader reader, TrackSection section)
    {
        byte commandCount = reader.ReadByte();
        for (int i = 0; i < commandCount; i++)
        {
            string command = reader.ReadString();
            section.Commands.Add(command);
        }
    }
}

