            // isBrazil :: Int -> Bool
            bool isBrazil(int n)
            {
                // True if n is a Brazilian number,
                // in the sense of OEIS:A125134.
                return 7 <= n && (
                    0 == n % 2 || any(
                        map(monoDigit(n), range(2, n - 1))
                    )
                );
            }

            // monoDigit :: Int -> Int -> Bool
            Func<int, int, bool> monoDigit(int n)
            {
                // True if all the digits of n,
                // in the given base, are the same.
                return base =>
                {
                    Func<int, int, bool> g(int b, int n)
                    {
                        var qr = divmod(n, b);
                        Func<int[], bool> p(int[] qr) =>
                            qr[1]!= d || 0 == qr[0];
                        Func<int[], int[]> f(int[] qr) =>
                            divmod(qr[0], b);
                        return qr[1] == until(p)(f)(
                            new[] { qr[0], qr[1] }
                        )[1];
                    }
                    return g(base, n);
                };
            }

