public class ParkingRamp
{
    public List<ParkingFloor> Floors { get; private set; }
    public Queue<Vehicle> InQueue { get; private set; }
    public Queue<Vehicle> OutQueue { get; private set; }
    public int TotalCapacity { get; private set; }
    private Random _randomizer;

    public ParkingRamp(int floorCount, int locationsPerFloor)
    {
        _randomizer = new Random();
        Floors = new List<ParkingFloor>();
        InQueue = new Queue<Vehicle>();
        OutQueue = new Queue<Vehicle>();

        for (int i = 0; i < floorCount; i++)
        {
            Floors.Add(new ParkingFloor(i, locationsPerFloor));
        }

        TotalCapacity = floorCount * locationsPerFloor;
    }

    public bool TryParkVehicle(Vehicle vehicle)
    {
        var availableFloors = Floors.Where(f => f.OpenLocations > 0).ToList();

        if (!availableFloors.Any())
        {
            InQueue.Enqueue(vehicle);
            return false;
        }

        var selectedFloor = availableFloors[_randomizer.Next(availableFloors.Count)];
        return selectedFloor.ParkVehicle(vehicle);
    }

    public bool TryExitVehicle(Vehicle vehicle)
    {
        var occupiedFloors = Floors.Where(f => f.ContainsVehicle(vehicle)).ToList();

        if (!occupiedFloors.Any())
        {
            OutQueue.Enqueue(vehicle);
            return false;
        }

        return occupiedFloors.First().RemoveVehicle(vehicle);
    }

    public void Tick()
    {
        ProcessInQueue();
        ProcessOutQueue();
        UpdateParkingStatus();
    }

    private void ProcessInQueue()
    {
        while (InQueue.Count > 0)
        {
            var vehicle = InQueue.Dequeue();
            TryParkVehicle(vehicle);
        }
    }

    private void ProcessOutQueue()
    {
        while (OutQueue.Count > 0)
        {
            var vehicle = OutQueue.Dequeue();
            TryExitVehicle(vehicle);
        }
    }

    private void UpdateParkingStatus()
    {
        foreach (var floor in Floors)
        {
            floor.UpdateOccupancy();
        }
    }

    public int TotalLocations() => Floors.Sum(f => f.TotalLocations);
    public int OpenLocations() => Floors.Sum(f => f.OpenLocations);
}

