            {
                // Clear or reset shader variable if texture target is not available.
                vectorVar.Set(new Vector4(0, 0, 0, 0));
                return;
            }

            var desc = settings.CurrentTarget.Description;
            // Set only the width and height in the vector (components X and Y)
            vectorVar.Set(new Vector4(desc.Width, desc.Height, 0, 0));
        }

