                return;
            }

            var desc = settings.CurrentTarget.Description;
            float invWidth = (desc.Width != 0) ? 1.0f / desc.Width : 0;
            float invHeight = (desc.Height != 0) ? 1.0f / desc.Height : 0;
            // Set inverse dimensions in X and Y components
            vectorVar.Set(new Vector4(invWidth, invHeight, 0, 0));
