public class UpdateEntityHandler<T> where T : BaseDto
{
    private static readonly ILogger _logger = LogManager.GetLogger(typeof(UpdateEntityHandler<T>));
    private readonly ICRUDService<T> _crudService;
    private readonly IEventPublisher _eventPublisher = ServiceLocator.Get<IEventPublisher>();

    public UpdateEntityHandler()
    {
        Type serviceType = HandlerUtils.DTO_TO_SERVICE[typeof(T)];
        _crudService = ServiceActivator.Get(serviceType) as ICRUDService<T>;
    }

    public void DoExecute(ExecutionEvent executionEvent)
    {
        Guid entityId = executionEvent.GetEntityId();
        T dto;

        using (ITransaction transaction = TransactionManager.BeginTransaction())
        {
            try
            {
                dto = _crudService.Get(entityId);
                transaction.Commit();
            }
            catch (Exception ex)
            {
                transaction.Rollback();
                _logger.Error($"Error loading {typeof(T).Name}", ex);
                OnFailure(executionEvent, ex);
                return;
            }
        }

        WizardModelView<T> wizardModelView = CreateWizardModelView(dto);
        Wizard wizard = new Wizard(wizardModelView);
        bool? result = wizard.ShowDialog();

        if (result == true)
        {
            using (ITransaction transaction = TransactionManager.BeginTransaction())
            {
                try
                {
                    _crudService.Update(wizardModelView.GetDto());
                    transaction.Commit();
                    OnSuccessful(executionEvent, wizardModelView.GetDto());
                }
                catch (Exception ex)
                {
                    transaction.Rollback();
                    _logger.Error($"Error updating {typeof(T).Name}", ex);
                    OnFailure(executionEvent, ex);
                }
            }
        }
        else
        {
            OnFailure(executionEvent, new Exception("Operation canceled by user."));
        }
    }

    protected virtual WizardModelView<T> CreateWizardModelView(T dto)
    {
        return new WizardModelView<T>(dto);
    }

    protected virtual void OnSuccessful(ExecutionEvent executionEvent, T dto)
    {
        _eventPublisher.Publish(new EntityUpdatedEvent<T>(dto));
        NotifyDependentComponents(dto);
    }

    protected virtual void OnFailure(ExecutionEvent executionEvent, Exception ex)
    {

 
using System;
