using System.Xml;
using System.Xml.Linq;
using System.Xml.Serialization;
using System.Xml.Xsl;
 
namespace Employee
{
    class Task
    {
        static void Main(string[] args)
        {
            var names = new List<string> { "April", "", "Emily" };
 
            var remarks = new List<string> {
                "Bubbly: I'm > Tam and <= Emily",
                "Burns: \"When chapman billies leave the street...\"",
                "Short & shrift"
            };
 
            var doc = new XmlDocument();
            var root = doc.CreateElement("CharacterRemarks"); // create root node
            doc.AppendChild(root);
 
            // now create Character elements
            for (int i = 0; i < names.Count; i++)
            {
                var character = doc.CreateElement("Character");
                character.SetAttribute("name", names[i]);
                var remark = doc.CreateTextNode(remarks[i]);
                character.AppendChild(remark);
                root.AppendChild(character);
            }
 
            var source = new XmlNodeReader(doc);
            var sw = new StringWriter();
            var result = new XmlTextWriter(sw);
            var tFactory = new XslCompiledTransform();
            tFactory.Load(new XmlTextReader(new StringReader(@"<?xml version='1.0'?>
<xsl:stylesheet version='1.0' xmlns:xsl='http://www.w3.org/1999/XSL/Transform'>
<xsl:output omit-xml-declaration='yes' indent='yes' indent-amount='4'/>
</xsl:stylesheet>")));
            tFactory.Transform(source, result);
            Console.WriteLine(sw);
        }
    }
}

