using UnityEngine;
using System.Collections;

public interface IUseable
{
    void Use();
}

public class PlayerController : MonoBehaviour
{
    public float maxSpeed = 10f;
    public float climbSpeed = 5f;
    public float jumpHeight = 7f;

    private bool hidden = false;
    private bool jumping = false;
    private bool climbing = false;
    private bool facingRight = true;

    private Rigidbody2D physics;
    private Animator animator;

    private IUseable useableObject;

    void Start()
    {
        physics = GetComponent<Rigidbody2D>();
        animator = GetComponent<Animator>();
    }

    void FixedUpdate()
    {
        float moveInput = Input.GetAxis("Horizontal");

        // Horizontal movement.
        Vector2 velocity = physics.velocity;
        velocity.x = moveInput * maxSpeed;
        physics.velocity = velocity;

        // Update animation state.
        animator.SetFloat("Speed", Mathf.Abs(moveInput));

        // Jumping logic.
        if (Input.GetButtonDown("Jump") && !jumping && !climbing)
        {
            jumping = true;
            physics.AddForce(new Vector2(0f, jumpHeight), ForceMode2D.Impulse);
            animator.SetTrigger("Jump");
        }

        // Climbing toggle.
        if (Input.GetKeyDown(KeyCode.C))
        {
            ToggleClimbing();
        }

        // Use object logic.
        if (Input.GetKeyDown(KeyCode.E) && useableObject != null)
        {
            Use();
        }

        // Flip the character if moving in opposite direction.
        if (moveInput > 0 && !facingRight)
        {
            Flip();
        }
        else if (moveInput < 0 && facingRight)
        {
            Flip();
        }
    }

    public void ToggleClimbing()
    {
        // Change climbing state and adjust animator.
        climbing = !climbing;
        animator.SetBool("Climbing", climbing);

        // If starting to climb, disable gravity.
        if (climbing)
        {
            physics.gravityScale = 0;
            physics.velocity = new Vector2(physics.velocity.x, 0);
        }
        else
        {
            physics.gravityScale = 1;
        }
    }

    public void Use()
    {
        // Trigger useable object action.
        if (useableObject != null)
        {
            useableObject.Use();
            hidden = !hidden;
            animator.SetBool("Hidden", hidden);
        }
    }

    void Flip()
    {
        facingRight = !facingRight;
        Vector3 scale = transform.localScale;
        scale.x *= -1;
        transform.localScale = scale;
    }

