using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;

public interface IIterator<T>
{
    bool MoveNext();
    void Reset();
    T Current { get; }
}

public class CompositeIterator<T> : IIterator<T>, IEnumerable<T>
{
    private readonly IIterator<T>[] _iterators;
    private readonly HashSet<IIterator<T>> _iteratorsToReset;
    private int _currentIteratorIndex;

    public CompositeIterator(params IIterator<T>[] iterators)
    {
        if (iterators == null || iterators.Length == 0)
            throw new ArgumentException("At least one iterator must be provided.");

        _iterators = iterators.Where(it => it != null).ToArray();
        _iteratorsToReset = new HashSet<IIterator<T>>(_iterators);
        _currentIteratorIndex = 0;
    }

    public T Current
    {
        get
        {
            if (_currentIteratorIndex < 0 || _currentIteratorIndex >= _iterators.Length)
                throw new InvalidOperationException("Iterator is out of bounds.");

            return _iterators[_currentIteratorIndex].Current;
        }
    }

    public bool MoveNext()
    {
        while (_currentIteratorIndex < _iterators.Length)
        {
            if (_iterators[_currentIteratorIndex].MoveNext())
                return true;

            _iteratorsToReset.Remove(_iterators[_currentIteratorIndex]);
            _currentIteratorIndex++;
        }

        return false;
    }

    public void Reset()
    {
        foreach (var iterator in _iteratorsToReset)
        {
            try
            {
                iterator.Reset();
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Reset failed for iterator: {ex.Message}");
            }
        }

        _currentIteratorIndex = 0;
        _iteratorsToReset.Clear();
        _iteratorsToReset.UnionWith(_iterators);
    }

    public IEnumerator<T> GetEnumerator()
    {
        Reset();
        while (MoveNext())
        {
            yield return Current;
        }
    }

    IEnumerator IEnumerable.GetEnumerator()
    {
        return GetEnumerator();
    }
}

public class ArrayIterator<T> : IIterator<T>
{
    private readonly T[] _items;
    private int _currentIndex = -1;

    public ArrayIterator(T[] items)
    {
        _items = items ?? throw new ArgumentNullException(nameof(items));
    }

    public T Current => _items[_currentIndex];

    public bool MoveNext()
    {
        return ++_currentIndex < _items.Length;
    }

    public void Reset()
    {
        _currentIndex = -1;
    }
}

