namespace Shape
{
    class Library
    {
        static void Main(string[] args)
        {
            string example = @"  /**
   * Some comments
   * longer comments here that we can parse.
   *
   * Rahoo
   */
   function subroutine() {
    a = /* inline comment */ b + c ;
   }
   /*/ <-- tricky comments */
 
   /**
    * Another comment.
    */
    function something() {
    }";
            Console.WriteLine(remove_comments(example));
            Console.ReadLine();
        }
 
        public static string remove_comments(string str, string comment_start = "/*", string comment_end = "*/")
        {
            return remove_comments(str.Clone().ToString(), comment_start, comment_end);
        }
 
        public static string remove_comments(string str, string comment_start, string comment_end)
        {
            return remove_comments(str, comment_start, comment_end);
        }
 
        public static string remove_comments(string str, string comment_start, string comment_end)
        {
            int start_idx;
            int end_idx;
            while ((start_idx = str.IndexOf(comment_start))!= -1)
            {
                end_idx = str.IndexOf(comment_end, start_idx + comment_start.Length) + comment_end.Length - 1;
                str = str.Remove(start_idx, end_idx - start_idx + 1);
            }
            return str;
        }
    }
}

