    public static class UriExtensions
    {
        public static Uri AppendPath(this Uri uri, string path)
        {
            if (uri == null) throw new ArgumentNullException(nameof(uri));
            if (string.IsNullOrEmpty(path)) throw new ArgumentException("Path cannot be null or empty", nameof(path));

            var combinedPath = uri.AbsolutePath.Trim('/') + "/" + path.Trim('/');
            return new Uri(uri.GetLeftPart(UriPartial.Path) + combinedPath + uri.Query);
        }
    }

