    class DiscordianDate
    {
        private static readonly string[] SEASON_NAMES = { "Chaos", "Discord", "Confusion", "Bureaucracy", "The Aftermath" };
        private static readonly string[] DAY_NAMES = { "Sweetmorn", "Boomtime", "Pungenday", "Prickle-Prickle", "Setting Orange" };
        private static readonly int YEAR_OFFSET = 1166;
        private static readonly int DAYS_PER_SEASON = 73;
        private static readonly int DAYS_PER_WEEK = 5;
        private static readonly int ST_TIBS_DAY_OF_YEAR = 60;

        private int _dayOfYear;
        private bool _stTibs;
        private int _season;
        private int _day;
        private int _year;

        public DiscordianDate(int year, int month, int day)
        {
            var gregorianDate = new DateTime(year, month, day);
            _dayOfYear = gregorianDate.DayOfYear;

            _stTibs = false;
            if (gregorianDate.IsLeapYear())
            {
                if (_dayOfYear == ST_TIBS_DAY_OF_YEAR)
                {
                    _stTibs = true;
                }
                else if (_dayOfYear > ST_TIBS_DAY_OF_YEAR)
                {
                    _dayOfYear -= 1;
                }
            }

            _season = (_dayOfYear - 1) / DAYS_PER_SEASON;
            _day = (_dayOfYear - 1) % DAYS_PER_SEASON + 1;
            _year = gregorianDate.Year + YEAR_OFFSET;
        }

        public int Year
        {
            get { return _year; }
        }

        public int Day
        {
            get { return _day; }
        }

        public string Season
        {
            get { return SEASON_NAMES[_season]; }
        }

        public string Weekday
        {
            get
            {
                if (_stTibs)
                {
                    return "St. Tib's Day";
                }
                else
                {
                    return DAY_NAMES[(_dayOfYear - 1) % DAYS_PER_WEEK];
                }
            }
        }

        public override string ToString()
        {
            return _stTibs? "St. Tib's Day" : string.Format("{0}, {1} {2}", Weekday, Season, Day) + ", " + Year + " YOLD";
        }
    }
}

