namespace TowersOfHanoi
{
    class Order
    {
        static void Main(string[] args)
        {
            int n = 5;
            List<List<int>> towers = new List<List<int>>();
            towers.Add(Enumerable.Range(1, n).Reverse().ToList());
            towers.Add(new List<int>());
            towers.Add(new List<int>());
            move(n, towers, 0, 1, 2);
        }

        static void move(int num_disks, List<List<int>> towers, int start, int target, int using_rod)
        {
            if (num_disks == 1)
            {
                towers[target].Add(towers[start].Last());
                towers[start].RemoveAt(towers[start].Count - 1);
                Console.WriteLine("Move disk from {0} to {1} : {2}", start, target, towers);
            }
            else
            {
                move(num_disks - 1, towers, start, using_rod, target);
                move(1, towers, start, target, using_rod);
                move(num_disks - 1, towers, using_rod, target, start);
            }
        }
    }
}

