namespace LogicPuzzle
{
    class LogicPuzzle
    {
        bool[] S = new bool[13];
        int Count = 0;

        public bool check2()
        {
            int count = 0;
            for (int k = 7; k <= 12; k++)
                if (S[k]) count++;
            return S[2] == (count == 3);
        }

        public bool check3()
        {
            int count = 0;
            for (int k = 2; k <= 12; k += 2)
                if (S[k]) count++;
            return S[3] == (count == 2);
        }

        public bool check4()
        {
            return S[4] == (!S[5] || S[6] && S[7]);
        }

        public bool check5()
        {
            return S[5] == (!S[2] &&!S[3] &&!S[4]);
        }

        public bool check6()
        {
            int count = 0;
            for (int k = 1; k <= 11; k += 2)
                if (S[k]) count++;
            return S[6] == (count == 4);
        }

        public bool check7()
        {
            return S[7] == ((S[2] || S[3]) &&!(S[2] && S[3]));
        }

        public bool check8()
        {
            return S[8] == (!S[7] || S[5] && S[6]);
        }

        public bool check9()
        {
            int count = 0;
            for (int k = 1; k <= 6; k++)
                if (S[k]) count++;
            return S[9] == (count == 3);
        }

        public bool check10()
        {
            return S[10] == (S[11] && S[12]);
        }

        public bool check11()
        {
            int count = 0;
            for (int k = 7; k <= 9; k++)
                if (S[k]) count++;
            return S[11] == (count == 1);
        }

        public bool check12()
        {
            int count = 0;
            for (int k = 1; k <= 11; k++)
                if (S[k]) count++;
            return S[12] == (count == 4);
        }

        public void check()
        {
            if (check2() && check3() && check4() && check5() && check6()
                && check7() && check8() && check9() && check10() && check11()
                && check12())
            {
                for (int k = 1; k <= 12; k++)
                    if (S[k]) Console.Write(k + " ");
                Console.WriteLine();
                Count++;
            }
        }

        public void recurseAll(int k)
        {
            if (k == 13)
                check();
            else
            {
                S[k] = false;
                recurseAll(k + 1);
                S[k] = true;
                recurseAll(k + 1);

