namespace GameLoader
{
    public class TestSceneLoader : BaseLoadingScene
    {
        private SpriteFont _font;
        private float _loadingProgress;
        private StringBuilder _loadingStatus;
        private List<string> _resourcesQueue;

        public TestSceneLoader(Game game) : base(game)
        {
            _resourcesQueue = new List<string>
            {
                "PlayerTextures",
                "MapResources",
                "SoundEffects",
                "BackgroundMusic"
            };

            _loadingStatus = new StringBuilder();
            _loadingProgress = 0f;
        }

        protected override void LoadContent()
        {
            base.LoadContent();
            _font = ContentManager.Load<SpriteFont>("LoadingFont");
        }

        protected override void Update(GameTime gameTime)
        {
            base.Update(gameTime);

            if (_resourcesQueue.Any())
            {
                string currentResource = _resourcesQueue.First();
                _loadingStatus.Clear();
                _loadingStatus.AppendFormat("Loading: {0}", currentResource);

                try
                {
                    ContentManager.Load<object>(currentResource);
                    _resourcesQueue.RemoveAt(0);
                    _loadingProgress += 0.25f;
                }
                catch (Exception ex)
                {
                    _loadingStatus.AppendFormat(" - Error: {0}", ex.Message);
                }
            }
            else if (_loadingProgress >= 1.0f)
            {
                OnCompleted();
            }
        }

        protected override void Render(RenderContext context)
        {
            base.Render(context);

            Vector2 screenCenter = new Vector2(
                context.Graphics.Viewport.Width / 2,
                context.Graphics.Viewport.Height / 2
            );

            context.SpriteBatch.DrawString(
                _font,
                _loadingStatus.ToString(),
                screenCenter,
                Color.White
            );

            context.SpriteBatch.DrawRectangle(
                new Rectangle(
                    (int)screenCenter.X - 100,
                    (int)screenCenter.Y + 50,
                    (int)(_loadingProgress * 200),
                    20
                ),
                Color.Green
            );
        }

