using System;
using System.Collections.Generic;
using System.Net.Sockets;
using System.Threading.Tasks;

public class Probe
{
    public async Task<ProbeResult> Single(ProbeEntity entity, int port)
    {
        var service = ServiceFactory.CreateService(entity.ServiceType);
        return await ReturnSingleResult(service, entity.Address, port);
    }

    public async Task<List<ProbeResult>> Multiple(List<ProbeEntity> entities)
    {
        var tasks = new List<Task<ProbeResult>>();
        foreach (var entity in entities)
        {
            foreach (var port in entity.Ports)
            {
                tasks.Add(Single(entity, port));
            }
        }

        var results = await Task.WhenAll(tasks);
        return new List<ProbeResult>(results);
    }

    private async Task<ProbeResult> ReturnSingleResult(IService service, string address, int port)
    {
        try
        {
            var response = await service.ProbeAsync(address, port);
            return new ProbeResult
            {
                Address = address,
                Port = port,
                Status = response.IsSuccessful ? PortStatus.Live : PortStatus.Dead,
                ResponseData = response.Data
            };
        }
        catch (Exception ex)
        {
            return new ProbeResult
            {
                Address = address,
                Port = port,
                Status = PortStatus.Dead,
                ErrorMessage = ex.Message
            };
        }
    }
}

