    }

    // Specific rule interfaces
    public interface ICharsetRule : ICssRule { }
    public interface IFontFaceRule : ICssRule { }
    public interface IMediaRule : ICssRule { }
    public interface IImportRule : ICssRule { }
    public interface INamespaceRule : ICssRule { }
    public interface IPageRule : ICssRule { }
    public interface IStyleRule : ICssRule { }

    // A simple implementation of a style rule
    public class StyleRule : IStyleRule
    {
        public string Selector { get; set; }
        public string Declaration { get; set; }
        public string ToCss()
        {
            return $"{Selector} {{ {Declaration} }}";
        }
    }

    // A parser component for creating and parsing CSS rules
    public class StylesheetParser
    {
        public ICssRule CreateRule(string type)
        {
            // For demonstration purposes, only handling "style" type.
            if (type.Equals("style", StringComparison.OrdinalIgnoreCase))
            {
                return new StyleRule
                {
                    Selector = ".default",
                    Declaration = "display: block;"
                };
            }
            // Default to a generic style rule for unknown types.
            return new StyleRule
            {
                Selector = ".generic",
                Declaration = "color: black;"
            };
        }

        public ICssRule ParseRuleText(string ruleText)
        {
            // A very simplistic parser that looks for a brace to determine a style rule.
            if (ruleText.Contains("{"))
            {
                var parts = ruleText.Split(new char[] { '{', '}' }, StringSplitOptions.RemoveEmptyEntries);
                if (parts.Length >= 2)
                {
                    return new StyleRule
                    {
                        Selector = parts[0].Trim(),
                        Declaration = parts[1].Trim()
                    };
                }
            }
            // Fallback to a dummy style rule.
            return new StyleRule
            {
                Selector = ".dummy",
                Declaration = ruleText
            };
        }
    }

    // The primary class representing the stylesheet
    public class Stylesheet
    {
        private List<ICssRule> RuleList = new List<ICssRule>();

