namespace SAPSessionInfoDisplay
{
    public partial class SAPSessionInfo : UserControl
    {
        private GuiSession session;

        public SAPSessionInfo()
        {
            InitializeComponent();
            SAPAutomationHelper.OnSetSession += Current_OnSetSession;
        }

        private void Current_OnSetSession(object sender, GuiSession session)
        {
            if (this.session != null)
            {
                this.session.EndRequest -= session_EndRequest;
                this.session.Destroy -= session_Destroy;
            }

            this.session = session;

            if (this.session != null)
            {
                this.session.EndRequest += session_EndRequest;
                this.session.Destroy += session_Destroy;
                showSessionInfo();
            }
            else
            {
                ClearSessionInfo();
            }
        }

        private void session_EndRequest(object pSender, int requestId)
        {
            showSessionInfo();
        }

        private void session_Destroy(object pSender)
        {
            Dispatcher.Invoke(() =>
            {
                ClearSessionInfo();
            });
        }

        private void showSessionInfo()
        {
            Dispatcher.Invoke(() =>
            {
                lv_SessionInfo.Items.Clear();
                if (session != null)
                {
                    var info = session.Info;
                    if (info != null)
                    {
                        var properties = info.GetType().GetProperties();

                        foreach (var property in properties)
                        {
                            try
                            {
                                var value = property.GetValue(info, null);
                                lv_SessionInfo.Items.Add(new { Name = property.Name, Value = value?.ToString() ?? "(null)" });
                            }
                            catch
                            {
                                lv_SessionInfo.Items.Add(new { Name = property.Name, Value = "(Error)" });
                            }

                        }
                    }
                }
            });
        }

        private void ClearSessionInfo()
        {
            lv_SessionInfo.Items.Clear();
        }
    }
}

using System;
using System.Text;
 
public class Stack
{
    public static string Collapse(string s)
    {
        var cs = new StringBuilder();
        var last = '\0';
        foreach (var c in s)
        {
            if (c!= last)
            {
                cs.Append(c);
                last = c;
            }
        }
        return cs.ToString();
    }
 
    public static void Main()
    {
        var strings = new[]
        {
            "",
            "\"If I were two-faced, would I be wearing this one?\" ---  ",
            "..1111111111111111111111111111111111111111111111111111111111111117777888",
            "I never give 'em hell, I just tell the truth, and they think it's hell. ",
            "                                                   ---    ",
            "The better the 4-wheel drive, the further you'll be from help when ya get stuck!",
            "headmistressship",
            "aardvark"
        };
        foreach (var s in strings)
        {
            var c = Collapse(s);
            Console.WriteLine($"original : length = {s.Length}, string = «««{s}»»»");
            Console.WriteLine($"collapsed : length = {c.Length}, string = «««{c}»»»");
            Console.WriteLine();
        }
    }
}

