using Newtonsoft.Json;
using Newtonsoft.Json.Serialization;
using System.Reflection;

public class PrivateSetterAwareContractResolver : DefaultContractResolver
{
    protected override JsonProperty CreateProperty(
        MemberInfo member,
        MemberSerialization memberSerialization)
    {
        JsonProperty prop = base.CreateProperty(member, memberSerialization);

        if (!prop.Writable)
        {
            var property = member as PropertyInfo;
            if (property != null)
            {
                MethodInfo setMethod = property.GetSetMethod(true);
                bool hasPrivateSetter = setMethod != null && setMethod.IsPrivate;

                if (hasPrivateSetter)
                {
                    prop.Writable = true;
                    prop.ShouldSerialize = _ => ShouldSerialize(member);
                }
            }
        }

        return prop;
    }

    private bool ShouldSerialize(MemberInfo member)
    {
        PropertyInfo property = member as PropertyInfo;
        return property?.GetMethod != null && property.GetMethod.IsPublic;
    }

    protected override JsonObjectContract CreateObjectContract(Type objectType)
    {
        JsonObjectContract contract = base.CreateObjectContract(objectType);
        contract.DefaultCreatorNonPublic = false;
        return contract;
    }

    protected override IList<JsonProperty> CreateProperties(
        Type type,
        MemberSerialization memberSerialization)
    {
        IList<JsonProperty> props = base.CreateProperties(type, memberSerialization);
        foreach (JsonProperty prop in props)
        {
            if (!prop.Writable)
            {
                PropertyInfo property = type.GetProperty(prop.UnderlyingName);
                if (property != null)
                {
                    prop.Writable = property.GetSetMethod(true)?.IsPrivate == true;
                }
            }
        }
        return props;
    }
}

