using System;
using System.Collections.Generic;
using System.Linq;

namespace ProjectEuler
{
    public class Problem075
    {
        public static void Main()
        {
            int N = 13;
            var (tri90, tri60, tri120) = Method1(N);
            Console.WriteLine($"Integer triangular triples for sides 1..{N}:");
            foreach (var (angle, triples) in new List<(int, List<List<int>>)> { (90, tri90), (60, tri60), (120, tri120) })
            {
                Console.WriteLine($"  {angle:3}° has {triples.Count} solutions:");
                Console.WriteLine($"    {string.Join("\n    ", triples.Select(x => string.Join(", ", x)))}");
            }
            var (t60, _) = Method1(10_000);
            var notsame = t60.Count(x => x[0]!= x[1] || x[1]!= x[2]);
            Console.WriteLine($"Extra credit: {notsame}");
        }

        private static (List<List<int>> tri90, List<List<int>> tri60, List<List<int>> tri120) Method1(int N)
        {
            var squares = Enumerable.Range(0, N + 1).Select(x => x * x).ToList();
            var sqrset = new HashSet<int>(squares);
            var tri90 = new List<List<int>>();
            var tri60 = new List<List<int>>();
            var tri120 = new List<List<int>>();
            for (var a = 1; a <= N; a++)
            {
                var a2 = squares[a];
                for (var b = 1; b <= a; b++)
                {
                    var b2 = squares[b];
                    var c2 = a2 + b2;
                    if (sqrset.Contains(c2))
                    {
                        tri90.Add(new List<int> { a, b, (int)Math.Sqrt(c2) }.OrderBy(x => x).ToList());
                    }
                    var ab = a * b;
                    c2 -= ab;
                    if (sqrset.Contains(c2))
                    {
                        tri60.Add(new List<int> { a, b, (int)Math.Sqrt(c2) }.OrderBy(x => x).ToList());
                    }
                    c2 += 2 * ab;
                    if (sqrset.Contains(c2))
                    {
                        tri120.Add(new List<int> { a, b, (int)Math.Sqrt(c2) }.OrderBy(x => x).ToList());
                    }
                }
            }
            return (tri90, tri60, tri120);
        }
    }
}

