namespace CryptoCertificate
{
    public class OtherCertID : Asn1Encodable
    {
        private readonly byte[] otherCertHash;
        private readonly IssuerSerial issuerSerial;

        public OtherCertID(byte[] otherCertHash)
        {
            if (otherCertHash == null || otherCertHash.Length == 0)
                throw new ArgumentException("otherCertHash must not be null or empty.");

            this.otherCertHash = Arrays.Clone(otherCertHash);
        }

        public OtherCertID(byte[] otherCertHash, IssuerSerial issuerSerial)
            : this(otherCertHash)
        {
            this.issuerSerial = issuerSerial;
        }

        public static OtherCertID GetInstance(object obj)
        {
            if (obj is OtherCertID otherCertID)
                return otherCertID;

            if (obj is Asn1Sequence sequence)
                return new OtherCertID(sequence);

            throw new ArgumentException("Invalid object: " + obj.GetType().Name);
        }

        private OtherCertID(Asn1Sequence sequence)
        {
            if (sequence.Count < 1 || sequence.Count > 2)
                throw new ArgumentException("Invalid sequence length: " + sequence.Count);

            otherCertHash = Asn1OctetString.GetInstance(sequence[0]).GetOctets();

            if (sequence.Count == 2)
            {
                issuerSerial = IssuerSerial.GetInstance(sequence[1]);
            }
        }

        public byte[] OtherCertHash => Arrays.Clone(otherCertHash);
        public IssuerSerial IssuerSerial => issuerSerial;

        public override Asn1Object ToAsn1Object()
        {
            var seq = new Asn1Sequence();
            seq.Add(new Asn1OctetString(otherCertHash));
            if (issuerSerial != null)
            {
                seq.Add(issuerSerial.ToAsn1Object());
            }
            return seq;
        }

        public bool Validate()
        {
            return otherCertHash.Length == 32 || otherCertHash.Length == 20; // Example for SHA-256 and SHA-1
        }

        public override string ToString()
        {
            return $"OtherCertID: [otherCertHash: {BitConverter.ToString(otherCertHash).Replace("-", "")}, issuerSerial: {issuerSerial}]";
        }
    }

    public class IssuerSerial : Asn1Encodable
    {
        private readonly Asn1Primitive issuer;
        private readonly Asn1Integer serialNumber;

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace RosettaCode
{
    class Game
    {
        static void Main(string[] args)
        {
            string test = "string of ☺☻♥♦⌂, may include control characters and other ilk.♫☼§►↔◄";
            Console.WriteLine("Original: {0}", test);
            Console.WriteLine("Stripped of control codes: {0}", StripControlChars(test));
            Console.WriteLine("Stripped of extended: {0}", StripExtended(test));
        }
 
        static string StripControlChars(string arg)
        {
            char[] arrForm = arg.ToCharArray();
            StringBuilder buffer = new StringBuilder(arg.Length);//This many chars at most
 
            foreach(char ch in arrForm)
                if (!Char.IsControl(ch)) buffer.Append(ch);//Only add to buffer if not a control char
 
            return buffer.ToString();
        }
 
        static string StripExtended(string arg)
        {
            StringBuilder buffer = new StringBuilder(arg.Length); //Max length
            foreach(char ch in arg)
            {
                UInt16 num = Convert.ToUInt16(ch);//In .NET, chars are UTF-16
                //The basic characters have the same code points as ASCII, and the extended characters are bigger
                if((num >= 32u) && (num <= 126u)) buffer.Append(ch);
            }
            return buffer.ToString();
        }
    }
}

using System;

public class Approximate
{
    private static bool approxEquals(double value, double other, double epsilon)
    {
        return Math.Abs(value - other) < epsilon;
    }

    private static void test(double a, double b)
    {
        double epsilon = 1e-18;
        Console.WriteLine("{0}, {1} => {2}", a, b, approxEquals(a, b, epsilon));
    }

    public static void Main(string[] args)
    {
        test(100000000000000.01, 100000000000000.011);
        test(100.01, 100.011);
        test(10000000000000.001 / 10000.0, 1000000000.0000001000);
        test(0.001, 0.0010000001);
        test(0.000000000000000000000101, 0.0);
        test(Math.Sqrt(2.0) * Math.Sqrt(2.0), 2.0);
        test(-Math.Sqrt(2.0) * Math.Sqrt(2.0), -2.0);
        test(3.14159265358979323846, 3.14159265358979324);
    }
}

using GetSocialSdk;
using System;
