public class PublicChatRoomIOSImpl : ChatRoomIOSImpl
{
    private string roomTopic;

    public PublicChatRoomIOSImpl(string topic)
    {
        roomTopic = topic;
    }

    public string Name
    {
        get { return roomTopic; }
    }

    public bool IsSubscribed { get; private set; }

    public void Subscribe(Action<bool> onSuccess, Action<string> onError)
    {
        try
        {
            GetSocial.Chat.SubscribeToRoom(roomTopic, (success) =>
            {
                IsSubscribed = success;
                onSuccess?.Invoke(success);
            }, (error) =>
            {
                IsSubscribed = false;
                onError?.Invoke(error);
            });
        }
        catch (Exception ex)
        {
            onError?.Invoke(ex.Message);
        }
    }

    public void Unsubscribe(Action<bool> onSuccess, Action<string> onError)
    {
        try
        {
            GetSocial.Chat.UnsubscribeFromRoom(roomTopic, (success) =>
            {
                IsSubscribed = !success;
                onSuccess?.Invoke(success);
            }, (error) =>
            {
                onError?.Invoke(error);
            });
        }
        catch (Exception ex)
        {
            onError?.Invoke(ex.Message);
        }
    }

    public async Task<bool> CheckSubscriptionStatus()
    {
        // Assuming there's an asynchronous method in the SDK
        return await Task.Run(() =>
        {
            // This is a placeholder for actual SDK call to check subscription status
            return GetSocial.Chat.IsUserSubscribed(roomTopic);
        });
    }

    public void NotifyUser(string message)
    {
        // Notify user via native iOS notification or in-app UI
        Console.WriteLine($"Notification: {message}");
    }
}

