    public partial class RotationStrategyForm : Form
    {
        private IStrategy strategy;
        private CheckBox chkEnable;
        private NumericUpDown numBasePoint;
        private Button btnOK;
        private Button btnCancel;

        public RotationStrategyForm(IStrategy strategy)
        {
            InitializeComponent();
            this.strategy = strategy;
            InitializeControls();
            LoadStrategySettings();
        }

        private void InitializeControls()
        {
            chkEnable = new CheckBox { Text = "Enable Strategy", Location = new Point(20, 20) };
            numBasePoint = new NumericUpDown { Location = new Point(20, 50), Minimum = 0, Maximum = 1000 };
            btnOK = new Button { Text = "OK", Location = new Point(20, 80) };
            btnCancel = new Button { Text = "Cancel", Location = new Point(120, 80) };

            btnOK.Click += btnOK_Click;
            btnCancel.Click += btnCancel_Click;

            Controls.Add(chkEnable);
            Controls.Add(numBasePoint);
            Controls.Add(btnOK);
            Controls.Add(btnCancel);
        }

        private void LoadStrategySettings()
        {
            if (strategy is RotationStrategy rotationStrategy)
            {
                chkEnable.Checked = rotationStrategy.IsEnabled;
                numBasePoint.Value = rotationStrategy.BasePoint;
            }
        }

        private void btnOK_Click(object sender, EventArgs e)
        {
            if (strategy is RotationStrategy rotationStrategy)
            {
                rotationStrategy.IsEnabled = chkEnable.Checked;
                rotationStrategy.BasePoint = (int)numBasePoint.Value;

                if (rotationStrategy.IsEnabled)
                {
                    StrategyManager.Instance.AddStrategy(rotationStrategy);
                }
                else
                {
                    StrategyManager.Instance.RemoveStrategy(rotationStrategy);
                }
            }

            this.DialogResult = DialogResult.OK;
            this.Close();
        }

        private void btnCancel_Click(object sender, EventArgs e)
        {
            this.DialogResult = DialogResult.Cancel;
            this.Close();
        }
    }

