    [ComVisible(true)]
    public interface IMembershipCondition : ISecurityEncodable
    {
        /// <summary>
        /// Determines if provided evidence satisfies code group membership requirements
        /// </summary>
        /// <param name="evidence">Security evidence collection</param>
        /// <returns>True if evidence meets membership criteria</returns>
        bool Check(Evidence evidence);

        /// <summary>
        /// Creates a deep copy of the membership condition
        /// </summary>
        /// <returns>Cloned membership condition instance</returns>
        IMembershipCondition Copy();

        /// <summary>
        /// Tests logical equivalence with another condition
        /// </summary>
        /// <param name="obj">Condition to compare</param>
        /// <returns>True if conditions are functionally equivalent</returns>
        new bool Equals(object obj);

        /// <summary>
        /// Produces human-readable condition representation
        /// </summary>
        /// <returns>Serialized condition details</returns>
        new string ToString();
    }

    public abstract class BaseMembershipCondition : IMembershipCondition
    {
        public abstract bool Check(Evidence evidence);
        public abstract IMembershipCondition Copy();
        public abstract bool Equals(object obj);
        public abstract string ToString();

        public abstract void FromXml(SecurityElement e);
        public abstract SecurityElement ToXml();

        protected bool EvidenceContainsPublisher(Evidence evidence)
        {
            return evidence.GetEvidence<Publisher>() != null;
        }

        protected bool EvidenceMatchesSite(Evidence evidence, string requiredSite)
        {
            Site siteEvidence = evidence.GetEvidence<Site>();
            return siteEvidence?.OriginSite == requiredSite;
        }
    }

    public class PublisherMembershipCondition : BaseMembershipCondition
    {
        private readonly X509Certificate publisherCert;

        public PublisherMembershipCondition(X509Certificate certificate)
        {
            publisherCert = certificate;
        }

        public override bool Check(Evidence evidence)
        {
            Publisher pubEvidence = evidence.GetEvidence<Publisher>();
            return pubEvidence?.Certificate.Equals(publisherCert) ?? false;
        }

