public static class LanguageHelper
{
    private const string LanguageKey = "CurrentLanguage";
    public static string German => "de-DE";
    public static string English => "en-US";

    public static void SetLanguage(string languageCode)
    {
        if (string.IsNullOrWhiteSpace(languageCode))
        {
            languageCode = DetermineDefaultLanguage();
        }

        try
        {
            HttpContext.Current.Session[LanguageKey] = languageCode;
            Thread.CurrentThread.CurrentCulture = new System.Globalization.CultureInfo(languageCode);
            Thread.CurrentThread.CurrentUICulture = new System.Globalization.CultureInfo(languageCode);
        }
        catch (Exception ex)
        {
            // Log or handle potential session or culture setting errors
            HandleLanguageSettingError(ex);
        }
    }

    public static string GetLanguage()
    {
        if (HttpContext.Current.Session == null)
        {
            return DetermineDefaultLanguage();
        }

        string currentLanguage = HttpContext.Current.Session[LanguageKey] as string;
        return !string.IsNullOrWhiteSpace(currentLanguage)
            ? currentLanguage
            : DetermineDefaultLanguage();
    }

    private static string DetermineDefaultLanguage()
    {
        string browserLanguage = GetBrowserLanguage();
        return IsSupportedLanguage(browserLanguage)
            ? browserLanguage
            : English;
    }

    private static string GetBrowserLanguage()
    {
        try
        {
            var userLanguages = HttpContext.Current.Request.UserLanguages;
            return userLanguages?.FirstOrDefault() ?? English;
        }
        catch
        {
            return English;
        }
    }

    private static bool IsSupportedLanguage(string languageCode)
    {
        return new[] { German, English }.Contains(languageCode);
    }

    private static void HandleLanguageSettingError(Exception ex)
    {
        // Implement logging or custom error handling
        System.Diagnostics.Debug.WriteLine($"Language Setting Error: {ex.Message}");
    }

    public static void AddElement<T>(string key, T element)
    {
        if (HttpContext.Current.Session == null)
            return;

        var sessionElements = HttpContext.Current.Session[key] as List<T>;
        if (sessionElements == null)
        {
            sessionElements = new List<T>();
            HttpContext.Current.Session[key] = sessionElements;

