namespace Revise.Files.IFO
{
    public enum MapBlockType
    {
        [Attributes.BlockType(typeof(Blocks.MapObject))]
        Object = 0,

        [Attributes.BlockType(typeof(Blocks.MapNPC))]
        NPC = 1,

        [Attributes.BlockType(typeof(Blocks.MapBuilding))]
        Building = 2,

        [Attributes.BlockType(typeof(Blocks.MapTerrain))]
        Terrain = 3,

        [Attributes.BlockType(typeof(Blocks.MapItem))]
        Item = 4
    }

    public class MapBlockFactory
    {
        public static object CreateBlock(MapBlockType blockType)
        {
            Type blockClass = GetBlockClass(blockType);
            return Activator.CreateInstance(blockClass);
        }

        private static Type GetBlockClass(MapBlockType blockType)
        {
            var type = typeof(MapBlockType);
            var memInfo = type.GetMember(blockType.ToString());
            var attributes = memInfo[0].GetCustomAttributes(typeof(Attributes.BlockTypeAttribute), false);
            return ((Attributes.BlockTypeAttribute)attributes[0]).BlockClass;
        }
    }

