        {
            var block = MapBlockFactory.CreateBlock(blockType);
            _blocks.Add(block);
        }

        public void DisplayBlocks()
        {
            foreach (var block in _blocks)
            {
                Console.WriteLine($"Block of type: {block.GetType().Name}");
            }
        }
    }
}

