using System;
using System.Collections.Generic;
using System.Linq;
 
namespace Binomial
{
    class Service
    {
        static void Main(string[] args)
        {
            var treatment = new List<int> { 85, 88, 75, 66, 25, 29, 83, 39, 97 };
            var control = new List<int> { 68, 41, 10, 49, 16, 65, 32, 92, 28, 98 };
 
            var data_set = new List<int>(control);
            data_set.AddRange(treatment);
 
            var greater = Combinations(treatment.Sum(), treatment.Count, data_set);
            var lesser = Combinations(control.Sum(), control.Count, data_set);
            var total = Binomial(data_set.Count, treatment.Count);
 
            Console.WriteLine("<= : {0}%", (lesser / total * 100.0));
            Console.WriteLine(" > : {0}%", (greater / total * 100.0));
        }
 
        static long Factorial(int x)
        {
            long product = 1;
            for (int a = 1; a <= x; a++)
            {
                product *= a;
            }
            return product;
        }
 
        static long Binomial(int n, int k)
        {
            var numerator = Factorial(n);
            var denominator = Factorial(k) * Factorial(n - k);
            return numerator / denominator;
        }
 
        static long Combinations(int total, int number, List<int> data)
        {
            if (total < 0)
            {
                return Binomial(data.Count, number);
            }
 
            if (number == 0)
            {
                return 0;
            }
 
            if (number > data.Count)
            {
                return 0;
            }
 
            if (number == data.Count)
            {
                if (total < data.Sum())
                {
                    return 1;
                }
                else
                {
                    return 0;
                }
            }
 
            var tail = data.Skip(1).ToList();
            return Combinations(total - data[0], number - 1, tail) + Combinations(total, number, tail);
        }
    }
}

public class AmbulanceHelper
{
    private const int FLAG_CONFUSED = 0x02;
    private const int FLAG_IN_TRANSIT = 0x04;
    private const int FLAG_EMERGENCY = 0x08;

    private struct Vehicle
    {
        public uint m_flags;
        public int m_targetBuilding;
        public int m_transferSize;
        public byte m_data;
    }

    public static bool IsConfused(ref Vehicle ambulance)
    {
        // Primary confusion state detection
        if ((ambulance.m_flags & FLAG_CONFUSED) != 0)
        {
            return true;
        }

        // Secondary complexity checks
        bool isInTransit = (ambulance.m_flags & FLAG_IN_TRANSIT) != 0;
        bool isEmergency = (ambulance.m_flags & FLAG_EMERGENCY) != 0;

        // Complex confusion scenario validation
        if (isInTransit && !isEmergency)
        {
            // Check for potential navigation anomalies
            if (ambulance.m_targetBuilding <= 0 || ambulance.m_transferSize == 0)
            {
                return true;
            }
        }

        // Advanced diagnostic logic
        if (ambulance.m_data > 100)
        {
            // Unusual internal state detected
            return true;
        }

        // Granular state evaluation
        return false;
    }

    // Optional: Debug logging method
    // private static void LogConfusionState(ref Vehicle ambulance) { }
}

using System;
using System.Collections.Generic;
 
namespace RosettaCode.BubbleSort
{
    public static class BubbleSortMethods
    {
        //The "this" keyword before the method parameter identifies this as a C# extension
        //method, which can be called using instance method syntax on any generic list,
        //without having to modify the generic List<T> code provided by the .NET framework.
        public static void BubbleSort<T>(this List<T> list) where T : IComparable
        {
            bool madeChanges;
            int itemCount = list.Count;
            do
            {
                madeChanges = false;
                itemCount--;
                for (int i = 0; i < itemCount; i++)
                {
                    if (list[i].CompareTo(list[i + 1]) > 0)
                    {
                        T temp = list[i + 1];
                        list[i + 1] = list[i];
                        list[i] = temp;
                        madeChanges = true;
                    }
                }
            } while (madeChanges);
        }
    }
 
    //A short test program to demonstrate the BubbleSort. The compiler will change the
    //call to testList.BubbleSort() into one to BubbleSortMethods.BubbleSort<T>(testList).
    class Shape
    {
        static void Main()
        {
            List<int> testList = new List<int> { 3, 7, 3, 2, 1, -4, 10, 12, 4 };
            testList.BubbleSort();
            foreach (var t in testList) Console.Write(t + " ");
        }
    }
}

