    public class MsmqToActiveMqMessageConverter : IMessageConverter
    {
        private readonly IConnectionFactory _connectionFactory;
        private readonly IBus _messageBus;

        public MsmqToActiveMqMessageConverter(IConnectionFactory connectionFactory, IBus messageBus)
        {
            _connectionFactory = connectionFactory;
            _messageBus = messageBus;
        }

        public IMessage ConvertMessage(Message sourceMessage)
        {
            if (sourceMessage == null)
                throw new ArgumentNullException(nameof(sourceMessage));

            using (IConnection connection = _connectionFactory.CreateConnection())
            using (ISession session = connection.CreateSession())
            {
                IMessage activeMqMessage = session.CreateTextMessage(sourceMessage.Body.ToString());
                CopyMessageProperties(sourceMessage, activeMqMessage);
                return activeMqMessage;
            }
        }

        private void CopyMessageProperties(Message source, IMessage destination)
        {
            destination.NMSCorrelationID = source.CorrelationId;
            destination.NMSType = source.GetType().Name;
            destination.NMSTimestamp = DateTime.UtcNow.Ticks;
        }

        private string GetDestinationQueue(Message message)
        {
            if (message.Body is ScheduledTask)
                return "scheduled-tasks-queue";

            return message.Headers.ContainsKey("DestinationQueue")
                ? message.Headers["DestinationQueue"].ToString()
                : "default-queue";
        }

        public void Handle(Message message)
        {
            if (ShouldFilterMessage(message))
                return;

            try
            {
                IMessage convertedMessage = ConvertMessage(message);
                string destinationQueue = GetDestinationQueue(message);

                using (IConnection connection = _connectionFactory.CreateConnection())
                using (ISession session = connection.CreateSession())
                {
                    IMessageProducer producer = session.CreateProducer(new Apache.NMS.Queue(destinationQueue));
                    producer.Send(convertedMessage);
                }
            }
