{
    public enum Grade { A, B, C, D, F }

    public class CourseListingServiceModel
    {
        public int Id { get; set; }
        public string Name { get; set; }
    }

    public class StudentInCourseServiceModel
    {
        public string StudentId { get; set; }
        public string FullName { get; set; }
        public Grade? Grade { get; set; }
    }

    public class TrainerService : ITrainerService
    {
        private readonly EduContext db;
        private readonly AutoMapper.IConfigurationProvider mapper;

        public TrainerService(EduContext db, AutoMapper.IConfigurationProvider mapper)
        {
            this.db = db;
            this.mapper = mapper;
        }

        public async Task<IEnumerable<CourseListingServiceModel>> CoursesAsync(string userId)
            => await db.Courses
                .Where(c => c.TrainerId == userId)
                .ProjectTo<CourseListingServiceModel>(mapper)
                .ToListAsync();

        public async Task<bool> IsTrainerAsync(int courseId, string trainerId)
            => await db.Courses
                .AnyAsync(c => c.Id == courseId && c.TrainerId == trainerId);

        public async Task<IEnumerable<StudentInCourseServiceModel>> StudentsInCourseAsync(int courseId, string trainerId)
        {
            if (!await IsTrainerAsync(courseId, trainerId)) return null;

            return await db.StudentCourses
                .Where(sc => sc.CourseId == courseId)
                .Include(sc => sc.Student)
                .ProjectTo<StudentInCourseServiceModel>(mapper)
                .ToListAsync();
        }

        public async Task<bool> AddGradeAsync(int courseId, string studentId, Grade grade, string trainerId)
        {
            if (!await IsTrainerAsync(courseId, trainerId)) return false;

            var studentCourse = await db.StudentCourses
                .FindAsync(courseId, studentId);

            if (studentCourse == null) return false;

            studentCourse.Grade = grade;
            await db.SaveChangesAsync();
            return true;
        }
    }

