        {
            Horizontal,
            Vertical
        }

        private AlignType align = AlignType.Horizontal;

        [Category("Appearance")]
        [Description("Specifies the alignment of the delimiter line.")]
        public AlignType Alignment
        {
            get { return align; }
            set
            {
                if (align != value)
                {
                    align = value;
                    Invalidate();
                }
            }
        }

        public Delimiter()
        {
            this.SizeChanged += Delimiter_SizeChanged;
            this.MarginChanged += Delimiter_MarginChanged;
            this.Paint += Delimiter_Paint;
            this.BackColor = Color.Transparent;
        }

        private void Delimiter_Paint(object sender, PaintEventArgs e)
        {
            DrawDelimiter(e.Graphics);
        }

        private void Delimiter_SizeChanged(object sender, EventArgs e)
        {
            Invalidate();
        }

        private void Delimiter_MarginChanged(object sender, EventArgs e)
        {
            Invalidate();
        }

        private void DrawDelimiter(Graphics g)
        {
            using (Pen pen = new Pen(Color.Gray, 1))
            {
                if (align == AlignType.Horizontal)
                {
                    int y = this.Height / 2;
                    g.DrawLine(pen, this.Margin.Left, y, this.Width - this.Margin.Right, y);
                }
                else
                {
                    int x = this.Width / 2;
                    g.DrawLine(pen, x, this.Margin.Top, x, this.Height - this.Margin.Bottom);
                }
            }
        }
    }
