namespace StreamingBackendExample
{
    // General backend contract
    public interface IBackend
    {
        string BackendName { get; }
        bool Connect();
        void Disconnect();
    }

    // Extended contract for streaming operations
    public interface IStreamingBackend : IBackend
    {
        // Upload data by streaming content to a remote destination.
        void UploadData(string remoteFileName, Stream data);

        // Download data by streaming content from a remote source.
        Stream DownloadData(string remoteFileName);
    }

    // Example implementation of the streaming backend interface.
    public class ExampleStreamingBackend : IStreamingBackend
    {
        public string BackendName { get; private set; }

        public ExampleStreamingBackend(string name = "ExampleBackend")
        {
            BackendName = name;
        }

        public bool Connect()
        {
            Console.WriteLine("Connecting to " + BackendName + "...");
            // Simulate connection establishment logic.
            return true;
        }

        public void Disconnect()
        {
            Console.WriteLine("Disconnecting from " + BackendName + "...");
        }

        public void UploadData(string remoteFileName, Stream data)
        {
            Console.WriteLine("Starting upload to " + remoteFileName + "...");
            byte[] buffer = new byte[1024];
            int bytesRead;
            long totalBytes = 0;
            while ((bytesRead = data.Read(buffer, 0, buffer.Length)) > 0)
            {
                // Simulate processing with progress tracking.
                totalBytes += bytesRead;
                Console.WriteLine("Uploaded " + totalBytes + " bytes...");
            }
            Console.WriteLine("Upload complete.");
        }

        public Stream DownloadData(string remoteFileName)
        {
            Console.WriteLine("Starting download from " + remoteFileName + "...");
            // Simulate downloading by creating a MemoryStream with dummy data.
            MemoryStream memoryStream = new MemoryStream();
            byte[] dummyData = new byte[1024];
            for (int i = 0; i < 10; i++)
            {
                memoryStream.Write(dummyData, 0, dummyData.Length);
                Console.WriteLine("Downloaded " + ((i + 1) * 1024) + " bytes...");
            }
            memoryStream.Position = 0;
            Console.WriteLine("Download complete.");
            return memoryStream;
        }
    }

