class ExtractHTML
{
    static void Main()
    {
        Console.WriteLine("HTML Text Extraction Utility");
        Console.WriteLine("Enter HTML content (press Enter twice to finish):");

        StringBuilder htmlBuilder = new StringBuilder();
        string inputLine;
        while (!string.IsNullOrEmpty(inputLine = Console.ReadLine()))
        {
            htmlBuilder.AppendLine(inputLine);
        }

        string html = htmlBuilder.ToString();

        string title = GetTitle(html);
        string bodyText = GetBodyText(html);

        Console.WriteLine("\n--- Extracted Information ---");
        Console.WriteLine($"Title: {title}");
        Console.WriteLine("\nBody Text:");
        Console.WriteLine(bodyText);
    }

    static string GetTitle(string html)
    {
        int titleStartIndex = html.IndexOf("<title>", StringComparison.OrdinalIgnoreCase);
        int titleEndIndex = html.IndexOf("</title>", StringComparison.OrdinalIgnoreCase);

        if (titleStartIndex != -1 && titleEndIndex != -1)
        {
            int startPos = titleStartIndex + 7;
            return html.Substring(startPos, titleEndIndex - startPos).Trim();
        }

        return "No Title Found";
    }

    static string GetBodyText(string html)
    {
        StringBuilder bodyText = new StringBuilder();
        bool insideTag = false;
        bool insideScript = false;
        bool insideStyle = false;

        for (int i = 0; i < html.Length; i++)
        {
            char currentChar = html[i];

            if (currentChar == '<')
            {
                if (html.Substring(i).StartsWith("<script", StringComparison.OrdinalIgnoreCase))
                {
                    insideScript = true;
                }
                else if (html.Substring(i).StartsWith("<style", StringComparison.OrdinalIgnoreCase))
                {
                    insideStyle = true;
                }
                else
                {
                    insideTag = true;
                }
            }
            else if (currentChar == '>')
            {
                if (insideScript && html.Substring(i - 7, 8).Equals("</script", StringComparison.OrdinalIgnoreCase))
                {
                    insideScript = false;
                }
                else if (insideStyle && html.Substring(i - 7, 8).Equals("</style", StringComparison.OrdinalIgnoreCase))
                {
                    insideStyle = false;
                }
                else
                {

