using Microsoft.DotNet.Cli.Utils;
using Microsoft.DotNet.TestFramework;
using Xunit;

namespace VSTestIntegrationTests
{
    public class VSTestTests
    {
        [Fact]
        public void TestsFromAGivenContainerShouldRunWithExpectedOutput()
        {
            const string testAppName = "VSTestCore";
            var testAsset = TestAssets.Get(testAppName)
                .CreateInstance()
                .WithSourceFiles();

            var testRoot = testAsset.Root.FullName;
            var configuration = Environment.GetEnvironmentVariable("CONFIGURATION") ?? "Debug";

            new BuildCommand(testRoot)
                .Execute()
                .Should().Pass("Project should build successfully");

            var outputDir = new BuildCommand(testRoot)
                .GetOutputDirectory(configuration, targetFramework: "net8.0");
            var outputDll = Path.Combine(outputDir.FullName, $"{testAppName}.dll");

            File.Exists(outputDll).Should().BeTrue("Test assembly not found");

            var vstestArgs = new[] { outputDll, "--logger:console;verbosity=normal" };
            var result = VSTestCommand.ExecuteWithCapturedOutput(vstestArgs);

            if (CultureInfo.CurrentCulture.Name.StartsWith("en-US"))
            {
                result.StdOut.Should().ContainAll(
                    "Passed: 1",
                    "Failed: 1",
                    "VSTestCore.TestPass",
                    "VSTestCore.TestFail"
                );
            }

            result.ExitCode.Should().NotBe(0, "Exit code should reflect test failures");
        }
    }
}

