namespace IntentRecommendationModel
{
    public class Action
    {
        [JsonProperty("actionName")]
        public string ActionName { get; set; }

        [JsonProperty("parameters")]
        public IDictionary<string, string> Parameters { get; set; }

        public Action(string actionName, IDictionary<string, string> parameters)
        {
            ActionName = actionName;
            Parameters = parameters;
        }
    }

    public class IntentRecommendation
    {
        [JsonProperty("intent")]
        public string Intent { get; set; }

        [JsonProperty("score")]
        public double? Score { get; set; }

        [JsonProperty("actions")]
        public IList<Action> Actions { get; set; }

        // Default constructor
        public IntentRecommendation()
        {
            Actions = new List<Action>();
        }

        // Constructor with intent and score
        public IntentRecommendation(string intent, double? score) : this()
        {
            Intent = intent;
            Score = score;
        }

        // Constructor with intent, score, and actions
        public IntentRecommendation(string intent, double? score, IList<Action> actions) : this(intent, score)
        {
            Actions = actions ?? new List<Action>();
        }

        // Method to add an action to the list
        public void AddAction(Action action)
        {
            if (action != null)
            {
                Actions.Add(action);
            }
        }

        // Method to display intent details
        public string DisplayIntentDetails()
        {
            string scoreDisplay = Score.HasValue ? Score.Value.ToString("0.##") : "N/A";
            return $"Intent: {Intent}, Score: {scoreDisplay}, Actions Count: {Actions.Count}";
        }
    }

    class Counter
    {
        static void Main(string[] args)
        {
            var action1 = new Action("NotifyUser", new Dictionary<string, string> { { "message", "Hello, user!" } });
            var action2 = new Action("LogEvent", new Dictionary<string, string> { { "event", "UserLoggedIn" } });

            var intentRecommendation = new IntentRecommendation("GreetUser", 0.95, new List<Action> { action1, action2 });

            Console.WriteLine(intentRecommendation.DisplayIntentDetails());
            string json = JsonConvert.SerializeObject(intentRecommendation, Formatting.Indented);
            Console.WriteLine(json);
        }
    }
}

