using System;
 
namespace TokenGame
{
    class Solution
    {
        static void Main(string[] args)
        {
            int tokens = 12;
            while (true)
            {
                ShowTokens(tokens);
                Console.Write("  How many tokens 1, 2 or 3? ");
                string input = Console.ReadLine();
                int t;
                if (!int.TryParse(input, out t) || t < 1 || t > 3)
                {
                    Console.WriteLine("\nMust be a number between 1 and 3, try again.\n");
                }
                else
                {
                    int ct = 4 - t;
                    string s = "s";
                    if (ct == 1)
                    {
                        s = "";
                    }
                    Console.WriteLine("  Computer takes {0} token{1}", ct, s);
                    tokens -= 4;
                }
                if (tokens == 0)
                {
                    ShowTokens(0);
                    Console.WriteLine("  Computer wins!");
                    return;
                }
            }
        }
 
        static void ShowTokens(int tokens)
        {
            Console.WriteLine("Tokens remaining {0}", tokens);
        }
    }
}

