public class Feigenbaum
{
    public static void Main()
    {
        Feigenbaum();
    }
 
    public static void Feigenbaum()
    {
        int i, j, k, max_it = 13, max_it_j = 10;
        double a, x, y, d, a1 = 1.0, a2 = 0.0, d1 = 3.2;
        Console.WriteLine(" i       d");
        for (i = 2; i <= max_it; ++i)
        {
            a = a1 + (a1 - a2) / d1;
            for (j = 1; j <= max_it_j; ++j)
            {
                x = 0.0;
                y = 0.0;
                for (k = 1; k <= 1 << i; ++k)
                {
                    y = 1.0 - 2.0 * y * x;
                    x = a - x * x;
                }
                a -= x / y;
            }
            d = (a1 - a2) / (a - a1);
            Console.WriteLine("{0,2}    {1,8:F8}", i, d);
            d1 = d;
            a2 = a1;
            a1 = a;
        }
    }
}

