public interface IBasketRepository
{
    Task<string> GetBasketAsync(string customerId);
    Task<string> UpdateBasketAsync(string customerId, List<string> items);
    Task<bool> DeleteBasketAsync(string customerId);
    Task<IEnumerable<string>> GetUsersAsync();
}

public class RedisBasketRepository : IBasketRepository
{
    private readonly ILogger<RedisBasketRepository> _logger;
    private readonly IConnectionMultiplexer _redis;
    private readonly IDatabase _database;

    public RedisBasketRepository(IConnectionMultiplexer redis, ILogger<RedisBasketRepository> logger)
    {
        _redis = redis;
        _logger = logger;
        _database = _redis.GetDatabase();
    }

    public async Task<string> GetBasketAsync(string customerId)
    {
        _logger.LogInformation($"Fetching basket for customer ID: {customerId}");
        var basketData = await _database.StringGetAsync(customerId);

        if (basketData.IsNullOrEmpty)
        {
            _logger.LogWarning($"No basket found for customer ID: {customerId}");
            return null;
        }

        var basket = basketData.ToString();
        _logger.LogInformation($"Basket retrieved for customer ID: {customerId}");
        return basket;
    }

    public async Task<string> UpdateBasketAsync(string customerId, List<string> items)
    {
        _logger.LogInformation($"Updating basket for customer ID: {customerId}");

        var basketJson = JsonConvert.SerializeObject(items);
        var result = await _database.StringSetAsync(customerId, basketJson);

        if (result)
        {
            _logger.LogInformation($"Basket updated for customer ID: {customerId}");
            return basketJson;
        }

        _logger.LogError($"Failed to update basket for customer ID: {customerId}");
        return null;
    }

    public async Task<bool> DeleteBasketAsync(string customerId)
    {
        _logger.LogInformation($"Deleting basket for customer ID: {customerId}");
        var result = await _database.KeyDeleteAsync(customerId);

        if (result)
        {
            _logger.LogInformation($"Basket deleted for customer ID: {customerId}");
        }
        else
        {
            _logger.LogWarning($"No basket found to delete for customer ID: {customerId}");
        }

        return result;
    }

