using System;

public struct Vehicle
{
    public int Flags; // Bitwise flags representing vehicle states
}

public class AmbulanceHelper
{
    private const int ReturningFlag = 1 << 0; // Bit 0: Returning
    private const int WaitingForTargetFlag = 1 << 1; // Bit 1: Waiting for Target
    private const int RespondingToEmergencyFlag = 1 << 2; // Bit 2: Responding to Emergency
    private const int ConfusedFlag = 1 << 3; // Bit 3: Confused

    /// <summary>
    /// Determines if the ambulance is in a confused state based on its internal flags.
    /// </summary>
    /// <param name="vehicle">The ambulance vehicle to assess.</param>
    /// <returns>True if the vehicle is confused, otherwise false.</returns>
    public static bool IsAmbulanceConfused(ref Vehicle vehicle)
    {
        // Check if the ambulance is returning and waiting for a target
        bool isReturning = (vehicle.Flags & ReturningFlag) != 0;
        bool isWaiting = (vehicle.Flags & WaitingForTargetFlag) != 0;
        bool isResponding = (vehicle.Flags & RespondingToEmergencyFlag) != 0;

        // Determine confusion based on various states
        if (isReturning && isWaiting)
        {
            // If the ambulance is returning and waiting, it is confused
            return true;
        }

        if (isResponding && (isReturning || isWaiting))
        {
            // If responding but also returning or waiting indicates confusion
            return true;
        }

        // Check if the confused flag is set directly
        if ((vehicle.Flags & ConfusedFlag) != 0)
        {
            return true; // Directly confused
        }

        return false; // Not confused
    }

    public static void Main(string[] args)
    {
        Vehicle ambulance = new Vehicle();
        ambulance.Flags = 0; // No flags set initially

        // Test ambiguous states
        ambulance.Flags |= ReturningFlag; // Set returning
        ambulance.Flags |= WaitingForTargetFlag; // Set waiting

        bool confused = IsAmbulanceConfused(ref ambulance);
        Console.WriteLine($"Ambulance Confused: {confused}"); // Should print true

        // Reset flags for more tests
        ambulance.Flags = 0; // Reset flags

        ambulance.Flags |= RespondingToEmergencyFlag; // Set responding
        confused = IsAmbulanceConfused(ref ambulance);
        Console.WriteLine($"Ambulance Confused: {confused}"); // Should print false
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
 
static class Task {
    static Random Rng = new Random((int)DateTime.Now.Ticks);
 
    static char NextCharacter(this Random self) {
        const string AllowedChars = " ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        return AllowedChars[self.Next() % AllowedChars.Length];
    }
 
    static string NextString(this Random self, int length) {
        return String.Join("", Enumerable.Repeat(' ', length)
            .Select(c => Rng.NextCharacter()));
    }
 
    static int Fitness(string target, string current) {
        return target.Zip(current, (a, b) => a == b ? 1 : 0).Sum();
    }
 
    static string Mutate(string current, double rate) {
        return String.Join("", from c in current
               select Rng.NextDouble() <= rate ? Rng.NextCharacter() : c);
    }
 
    static void Main(string[] args) {
        const string target = "METHINKS IT IS LIKE A WEASEL";
        const int C = 100;
        const double P = 0.05;
 
        // Start with a random string the same length as the target.
        string parent = Rng.NextString(target.Length);
 
        Console.WriteLine("START:       {0,20} fitness: {1}",
            parent, Fitness(target, parent));
        int i = 0;
 
        while (parent != target) {
            // Create C mutated strings + the current parent.
            var candidates = Enumerable.Range(0, C + 1)
                .Select(n => n > 0 ? Mutate(parent, P) : parent);
 
            // select the fittest
            parent = candidates.OrderByDescending(c => Fitness(target, c)).First();
 
            ++i;
            Console.WriteLine("     #{0,6} {1,20} fitness: {2}",
                i, parent, Fitness(target, parent));
        }
 
        Console.WriteLine("END: #{0,6} {1,20}", i, parent);
    }
}

