using System;
using System.Collections.Immutable;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.LanguageServices;
using Microsoft.CodeAnalysis.Shared.Extensions;

public class OperatorSymbolReferenceFinder
{
    private readonly ISyntaxFactsService _syntaxFactsService;

    public OperatorSymbolReferenceFinder(ISyntaxFactsService syntaxFactsService)
    {
        _syntaxFactsService = syntaxFactsService;
    }

    public bool CanFind(ISymbol symbol)
    {
        return symbol is IMethodSymbol methodSymbol && methodSymbol.MethodKind == MethodKind.UserDefinedOperator;
    }

    public async Task<ImmutableArray<FinderLocation>> FindReferencesAsync(ISymbol symbol, Project project, ImmutableArray<Document> documents, CancellationToken cancellationToken)
    {
        if (!CanFind(symbol))
            return ImmutableArray<FinderLocation>.Empty;

        var documentsToSearch = await DetermineDocumentsToSearchAsync(symbol, project, cancellationToken);
        var results = ImmutableArray.CreateBuilder<FinderLocation>();

        foreach (var document in documentsToSearch)
        {
            results.AddRange(await FindReferencesInDocumentAsync(symbol, document, cancellationToken));
        }

        return results.ToImmutable();
    }

    private async Task<ImmutableArray<Document>> DetermineDocumentsToSearchAsync(ISymbol symbol, Project project, CancellationToken cancellationToken)
    {
        var documents = await project.GetDocumentIdsWithFilePathsAsync(cancellationToken);
        return documents.Select(id => project.GetDocument(id)).WhereNotNull().ToImmutableArray();
    }

    private async Task<ImmutableArray<FinderLocation>> FindReferencesInDocumentAsync(ISymbol symbol, Document document, CancellationToken cancellationToken)
    {
        var semanticModel = await document.GetSemanticModelAsync(cancellationToken);
        var syntaxRoot = await document.GetSyntaxRootAsync(cancellationToken);
        var results = ImmutableArray.CreateBuilder<FinderLocation>();

        syntaxRoot.DescendantTokens().Where(token => IsPotentialReference(token)).ForEach(token =>
        {
            var symbolInfo = semanticModel.GetSymbolInfo(token, cancellationToken);
            if (symbolInfo.Symbol == symbol)
            {
                results.Add(new FinderLocation(document, token.Span));
            }
        });

        return results.ToImmutable();
    }

    private bool IsPotentialReference(SyntaxToken token)
    {

