namespace GlobalizationLocalizationCache
{
    // Represents a localized resource with a key and a value.
    public class Resource
    {
        public string Key { get; set; }
        public string Value { get; set; }

        public Resource(string key, string value)
        {
            Key = key;
            Value = value;
        }
    }

    // Interface specifying methods for resource caching.
    public interface IResourceCache
    {
        // Retrieves cached resources for the given target and culture.
        List<Resource> GetResources(object target, CultureInfo culture);

        // Caches a list of resources for the given target and culture.
        void PutResources(object target, CultureInfo culture, List<Resource> resources);
    }

    // Simple in-memory cache implementation.
    public class InMemoryResourceCache : IResourceCache
    {
        // Dictionary key is a composite of target type and culture name.
        private readonly Dictionary<string, List<Resource>> _cache;

        public InMemoryResourceCache()
        {
            _cache = new Dictionary<string, List<Resource>>();
        }

        // Builds a unique key for caching purposes.
        private string BuildCacheKey(object target, CultureInfo culture)
        {
            return $"{target.GetType().FullName}_{culture.Name}";
        }

        public List<Resource> GetResources(object target, CultureInfo culture)
        {
            string key = BuildCacheKey(target, culture);
            if (_cache.ContainsKey(key))
            {
                return _cache[key];
            }
            return new List<Resource>();
        }

        public void PutResources(object target, CultureInfo culture, List<Resource> resources)
        {
            string key = BuildCacheKey(target, culture);
            if (_cache.ContainsKey(key))
            {
                _cache[key] = resources;
            }
            else
            {
                _cache.Add(key, resources);
            }
        }
    }

