    // Represents an item entity within the API with mapping configuration.
    public class Item : BaseApiModel, IStaticItem
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public string Description { get; set; }
        public string PlainText { get; set; }
        public bool Consumable { get; set; }
        public bool Hidden { get; set; }
        public ImageData Image { get; set; }
        public GoldData Gold { get; set; }
        public StatsData Stats { get; set; }
        public List<string> Tags { get; set; }
        public Dictionary<string, string> Metadata { get; set; }

        public Item()
        {
            Tags = new List<string>();
            Metadata = new Dictionary<string, string>();
        }

        // Configures the mapping between DTOs and the API model.
        public static void CreateMap(IMapperConfigurationExpression cfg)
        {
            // Mapping for nested objects first
            cfg.CreateMap<ItemGoldDTO, GoldData>();
            cfg.CreateMap<ItemImageDTO, ImageData>();
            cfg.CreateMap<ItemStatsDTO, StatsData>();

            // Main mapping from DTO to API model
            cfg.CreateMap<ItemDTO, Item>()
                .ForMember(dest => dest.Id, opt => opt.MapFrom(src => src.Id))
                .ForMember(dest => dest.Name, opt => opt.MapFrom(src => src.Name))
                .ForMember(dest => dest.Description, opt => opt.MapFrom(src => src.Description))
                .ForMember(dest => dest.PlainText, opt => opt.MapFrom(src => src.PlainText))
                .ForMember(dest => dest.Consumable, opt => opt.MapFrom(src => src.IsConsumable))
                .ForMember(dest => dest.Hidden, opt => opt.MapFrom(src => src.IsHidden))
                .ForMember(dest => dest.Image, opt => opt.MapFrom(src => src.Image))
                .ForMember(dest => dest.Gold, opt => opt.MapFrom(src => src.Gold))
                .ForMember(dest => dest.Stats, opt => opt.MapFrom(src => src.Stats))
                .ForMember(dest => dest.Tags, opt => opt.MapFrom(src => src.Tags))
                .ForMember(dest => dest.Metadata, opt => opt.MapFrom(src => src.Metadata));
        }
    }

