using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace Shuffler
{
    class Shuffler
    {
        private int seed;

        private string[] deck = {
            "AC", "AD", "AH", "AS",
            "2C", "2D", "2H", "2S",
            "3C", "3D", "3H", "3S",
            "4C", "4D", "4H", "4S",
            "5C", "5D", "5H", "5S",
            "6C", "6D", "6H", "6S",
            "7C", "7D", "7H", "7S",
            "8C", "8D", "8H", "8S",
            "9C", "9D", "9H", "9S",
            "TC", "TD", "TH", "TS",
            "JC", "JD", "JH", "JS",
            "QC", "QD", "QH", "QS",
            "KC", "KD", "KH", "KS",
        };

        private int random()
        {
            seed = (214013 * seed + 2531011) & int.MaxValue;
            return seed >> 16;
        }

        //shuffled cards go to the end
        private string[] getShuffledDeck()
        {
            string[] deck = this.deck.ToArray();
            for (int i = deck.Length - 1; i > 0; i--)
            {
                int r = random() % (i + 1);
                string card = deck[r];
                deck[r] = deck[i];
                deck[i] = card;
            }
            return deck;
        }

        //deal from end first
        public void dealGame(int seed)
        {
            this.seed = seed;
            string[] shuffledDeck = getShuffledDeck();
            for (int count = 1, i = shuffledDeck.Length - 1; i >= 0; count++, i--)
            {
                Console.Write(shuffledDeck[i]);
                if (count % 8 == 0)
                {
                    Console.WriteLine();
                }
                else
                {
                    Console.Write(" ");
                }
            }
            Console.WriteLine();
        }

        public static void Main(string[] args)
        {
            Shuffler s = new Shuffler();
            s.dealGame(1);
            Console.WriteLine();
            s.dealGame(617);
        }
    }
}

