namespace Amb
{
    class Graph
    {
        static void Main(string[] args)
        {
            var s1 = new[] { "the", "that", "a" };
            var s2 = new[] { "frog", "elephant", "thing" };
            var s3 = new[] { "walked", "treaded", "grows" };
            var s4 = new[] { "slowly", "quickly" };
            var c = AmbChain(s1, AmbChain(s2, AmbChain(s3, AmbStrings(s4))));
            foreach (var s in c)
            {
                Console.WriteLine(string.Join(" ", s));
            }
        }
 
        static IEnumerable<string[]> AmbStrings(string[] ss)
        {
            foreach (var s in ss)
            {
                yield return new[] { s };
            }
        }
 
        static IEnumerable<string[]> AmbChain(string[] ss, IEnumerable<string[]> cIn)
        {
            var cOut = new List<string[]>();
            var w = new Task[cIn.Count()];
            var i = 0;
            foreach (var chain in cIn)
            {
                w[i] = Task.Run(() =>
                {
                    foreach (var s1 in AmbStrings(ss))
                    {
                        if (s1[0][s1[0].Length - 1] == chain[0][0])
                        {
                            cOut.Add(s1.Concat(chain).ToArray());
                        }
                    }
                });
                i++;
            }
            Task.WaitAll(w);
            return cOut;
        }
    }
}

using System;
using System.Collections.Generic;
 
static class program
{
    static int n = 61;
    static List<int> l = new List<int>() { 0, 1 };
 
    static int fusc(int n)
    {
        if (n < l.Count) return l[n];
        int f = (n & 1) == 0 ? l[n >> 1] : l[(n - 1) >> 1] + l[(n + 1) >> 1];
        l.Add(f); return f;
    }
 
    static void Main(string[] args)
    {
        bool lst = true; int w = -1, c = 0, t;
        string fs = "{0,11:n0}  {1,-9:n0}", res = "";
        Console.WriteLine("First {0} numbers in the fusc sequence:", n);
        for (int i = 0; i < int.MaxValue; i++)
        {
            int f = fusc(i); if (lst)
            {
                if (i < 61) Console.Write("{0} ", f);
                else
                {
                    lst = false;
                    Console.WriteLine();
                    Console.WriteLine("Points in the sequence where an item has more digits than any previous items:");
                    Console.WriteLine(fs, "Index\\", "/Value"); Console.WriteLine(res); res = "";
                }
            }
            if ((t = f.ToString().Length) > w)
            {
                w = t; res += (res == "" ? "" : "\n") + string.Format(fs, i, f);
                if (!lst) { Console.WriteLine(res); res = ""; } if (++c > 5) break;
            }
        }
        l.Clear();
    }
}

