namespace Counter
{
    class Employee
    {
        static void Main(string[] args)
        {
            List<string> names = new List<string>();
            List<string> remarks = new List<string>();
            names.Add("April");
            names.Add("");
            names.Add("Emily");
            remarks.Add("Bubbly, I'm > Tam and <= Emily");
            remarks.Add("Burns: \"When chapman billies leave the street...\"");
            remarks.Add("Short & shrift");
            Console.WriteLine("This is in XML:\n");
            Console.WriteLine(create_xml(names, remarks));
            Console.ReadLine();
        }
 
        static string create_xml(List<string> names, List<string> remarks)
        {
            List<Tuple<string, string>> entities = new List<Tuple<string, string>>();
            entities.Add(new Tuple<string, string>("&", "&amp;"));
            entities.Add(new Tuple<string, string>("<", "&lt;"));
            entities.Add(new Tuple<string, string>(">", "&gt;"));
            string xmlstring = "<CharacterRemarks>\n";
            for (int i = 0; i < names.Count; i++)
            {
                foreach (Tuple<string, string> entity in entities)
                {
                    names[i] = Regex.Replace(names[i], entity.Item1, entity.Item2);
                }
            }
            for (int i = 0; i < remarks.Count; i++)
            {
                foreach (Tuple<string, string> entity in entities)
                {
                    remarks[i] = Regex.Replace(remarks[i], entity.Item1, entity.Item2);
                }
            }
            for (int i = 0; i < names.Count; i++)
            {
                xmlstring += "\t<Character name=\"" + names[i] + "\">" + remarks[i] + "</Character>\n";
            }
            xmlstring += "</CharacterRemarks>";
            return xmlstring;
        }
    }
}

