using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Routing;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using NonFactors.Mvc.Grid;

public class Startup
{
    public Startup(IWebHostEnvironment environment)
    {
        Environment = environment;
    }

    public IWebHostEnvironment Environment { get; }

    public void ConfigureServices(IServiceCollection services)
    {
        services.AddControllersWithViews()
            .AddMvcGrid(options =>
            {
                options.FilterMode = GridFilterMode.Explicit;
                options.Register(typeof(string), "text", new TextGridFilter());
                options.Register(typeof(DateTime), "date", new DateGridFilter());
                options.Register(typeof(decimal), "number", new NumberGridFilter());
            });

        services.Configure<RouteOptions>(options =>
        {
            options.LowercaseUrls = true;
            options.AppendTrailingSlash = false;
        });

        if (Environment.IsDevelopment())
        {
            services.AddLogging(builder => builder.AddConsole().SetMinimumLevel(LogLevel.Debug));
        }
    }

    public void Configure(IApplicationBuilder app)
    {
        if (Environment.IsDevelopment())
        {
            app.UseDeveloperExceptionPage();
        }
        else
        {
            app.UseExceptionHandler("/Error");
            app.UseHsts();
            app.UseHttpsRedirection();
        }

        app.UseStaticFiles(new StaticFileOptions
        {
            OnPrepareResponse = ctx =>
            {
                ctx.Context.Response.Headers.Append("Cache-Control",
                    Environment.IsDevelopment()
                        ? "no-cache, max-age=0"
                        : "public, immutable, max-age=31536000");
            }
        });

        app.UseRouting();
        app.UseEndpoints(endpoints =>
        {
            endpoints.MapControllerRoute(
                name: "default",
                pattern: "{controller=Home}/{action=Index}/{id?}");
        });

        if (!Environment.IsDevelopment())
        {
            app.Use(async (context, next) =>
            {
                context.Response.Headers.Append("Content-Security-Policy", "default-src 'self'");
                await next();
            });
        }
    }
}

