namespace WebModuleFramework
{
    // Represents configuration details for a module.
    public class ModuleConfiguration
    {
        public int ModuleID { get; set; }
        public string ControlSource { get; set; }
        // Additional configuration properties can be added here.
    }

    // Utility class for dynamically loading user interface controls.
    public static class UIControlUtility
    {
        public static Control LoadControl(Control container, string controlSource)
        {
            // In an actual implementation, additional logic might be applied here.
            return container.LoadControl(controlSource);
        }
    }

    // Base factory class for creating module controls.
    public abstract class ModuleControlFactoryBase
    {
        public abstract Control CreateControl(Control container, ModuleConfiguration config, string controlSource);
        public abstract Control CreateModuleControl(Control container, ModuleConfiguration config);
        public abstract Control CreateSettingsControl(Control container, ModuleConfiguration config);
    }

    // Specialized factory class for creating module UI controls.
    public class CustomModuleControlFactory : ModuleControlFactoryBase
    {
        // Creates a control given a container, configuration, and source.
        public override Control CreateControl(Control container, ModuleConfiguration config, string controlSource)
        {
            if (string.IsNullOrEmpty(controlSource))
            {
                throw new ArgumentException("Control source cannot be null or empty.", nameof(controlSource));
            }

            // Delegate control loading to the utility method.
            Control uiControl = UIControlUtility.LoadControl(container, controlSource);
            return uiControl;
        }

        // Creates the primary module control.
        public override Control CreateModuleControl(Control container, ModuleConfiguration config)
        {
