using System.Threading.Tasks;
using WalletWasabi.Wallets;

public abstract class ClosedWalletViewModel : IDisposable
{
    protected readonly CompositeDisposable _disposables = new();
    protected readonly Wallet _wallet;
    protected readonly IWalletManager _walletManager;
    protected readonly ObservableCollection<object> _items = new();

    protected ClosedWalletViewModel(Wallet wallet, IWalletManager walletManager)
    {
        _wallet = wallet ?? throw new ArgumentNullException(nameof(wallet));
        _walletManager = walletManager ?? throw new ArgumentNullException(nameof(walletManager));
    }

    public ObservableCollection<object> Items => _items;
    public virtual string IconName { get; protected set; } = "wallet_icon";
    public string? ErrorMessage { get; private set; }
    private bool _isLoading;

    public static ClosedWalletViewModel Create(Wallet wallet, IWalletManager walletManager)
    {
        return wallet.WalletType switch
        {
            WalletType.Hardware => new ClosedHardwareWalletViewModel(wallet, walletManager),
            WalletType.WatchOnly => new ClosedWatchOnlyWalletViewModel(wallet, walletManager),
            _ => new ClosedStandardWalletViewModel(wallet, walletManager)
        };
    }

    public virtual void OnNavigatedTo()
    {
        if (_wallet.State == WalletState.Uninitialized)
        {
            LoadWallet().ConfigureAwait(false);
        }
    }

    private async Task LoadWallet()
    {
        _isLoading = true;
        try
        {
            await Task.Run(async () =>
            {
                using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(30));
                await _walletManager.StartAsync(_wallet, cts.Token);
            });
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Wallet load failed: {ex.Message}";
            // Logging integration would go here
        }
        finally
        {
            _isLoading = false;
        }
    }

    public void Dispose()
    {
        _disposables.Dispose();
        GC.SuppressFinalize(this);
    }
}

public sealed class ClosedHardwareWalletViewModel : ClosedWalletViewModel
{
    public ClosedHardwareWalletViewModel(Wallet wallet, IWalletManager walletManager)
        : base(wallet, walletManager)
    {
        IconName = "hardware_wallet";
    }
}

