    {
        static void Main(string[] args)
        {
            Console.WriteLine("Welcome to bulls and cows!");
            Console.WriteLine("Do you want to play? ");
            string answer = Console.ReadLine();
            while (true)
            {
                if (answer == "yes" || answer == "Yes" || answer == "y" || answer == "Y")
                {
                    break;
                }
                if (answer == "no" || answer == "No" || answer == "n" || answer == "N")
                {
                    Console.WriteLine("Ok. Goodbye.");
                    return;
                }
                Console.WriteLine("Please answer yes or no: ");
                answer = Console.ReadLine();
            }
            game();
            Console.WriteLine("Another game? ");
        }

        static void game()
        {
            string symbols = "0123456789";
            int selection_length = 4;
            Random rnd = new Random();
            string selection = symbols.OrderBy(x => rnd.Next()).Take(selection_length).ToString();
            string guess;
            while (Console.WriteLine("Your guess? "), (guess = Console.ReadLine())!= null)
            {
                if (guess.Length!= selection_length || guess.Any(x =>!symbols.Contains(x)) || contains_duplicates(guess))
                {
                    Console.WriteLine(guess + " is not a valid guess!");
                    continue;
                }
                int bulls = 0;
                int cows = 0;
                for (int i = 0; i!= selection_length; ++i)
                {
                    int pos = selection.IndexOf(guess[i]);
                    if (pos == i)
                    {
                        ++bulls;
                    }
                    else if (pos!= -1)
                    {
                        ++cows;
                    }
                }
                Console.WriteLine(bulls + " bulls, " + cows + " cows.");
                if (bulls == selection_length)
                {
                    Console.WriteLine("Congratulations! You have won!");
                    return;
                }
            }
            Console.WriteLine("Oops! Something went wrong with input, or you've entered end-of-file!\nExiting...");
            Environment.Exit(1);
        }

