// Class representing an object with inspectable properties.
public class InspectableObject {
    public string Name { get; set; }
    public Dictionary<string, object> Fields = new Dictionary<string, object>();

    public InspectableObject(string name) {
        Name = name;
    }
}

// Main class managing inspected objects.
public class GuiInspector {
    private List<InspectableObject> inspected = new List<InspectableObject>();

    // Add an object to the inspection list.
    public void AddInspect(InspectableObject obj) {
        inspected.Add(obj);
        Console.WriteLine("Added: " + obj.Name);
    }

    // Remove an object from the inspection list.
    public void RemoveInspect(InspectableObject obj) {
        inspected.Remove(obj);
        Console.WriteLine("Removed: " + obj.Name);
    }

    // Find an object by its name.
    public InspectableObject FindByObject(string name) {
        return inspected.Find(o => o.Name.Equals(name, StringComparison.OrdinalIgnoreCase));
    }

    // Retrieve an object from the list by index.
    public InspectableObject GetInspectObject(int idx) {
        return (idx >= 0 && idx < inspected.Count) ? inspected[idx] : null;
    }

    // Return the count of inspected objects.
    public int GetNumInspectObjects() {
        return inspected.Count;
    }

    // Simulate inspecting an object.
    public void Inspect(InspectableObject obj) {
