    // Construct a CSG solid from a list of `CSG.Polygon` instances.
    static public CSG fromPolygons(List<CSGPolygon> polygons)
    {
      CSG csg = new CSG();
      csg.polygons = polygons;
      return csg;
    }

    public CSG clone()
    {
        CSG csg = new CSG();
        foreach(CSGPolygon polygon in this.polygons)

