using System;
using System.Web;

public static class LanguageHelper
{
    public const string German = "de";
    public const string English = "en";
    private const string LanguageKey = "LanguagePreference";

    public static void SetLanguage(string language)
    {
        if (language != German && language != English)
        {
            throw new ArgumentException("Invalid language code. Use 'de' or 'en'.", nameof(language));
        }

        AddElement(LanguageKey, language);
    }

    public static string GetLanguage()
    {
        if (HasElement<string>(LanguageKey))
        {
            var storedLang = GetElement<string>(LanguageKey);
            if (storedLang == German || storedLang == English)
            {
                return storedLang;
            }
        }

        var browserLang = ParseBrowserLanguages();
        return !string.IsNullOrEmpty(browserLang) ? browserLang : English;
    }

    private static string ParseBrowserLanguages()
    {
        if (HttpContext.Current?.Request?.UserLanguages == null)
            return English;

        foreach (var langEntry in HttpContext.Current.Request.UserLanguages)
        {
            var langCode = langEntry.Split(';')[0].Trim().ToLowerInvariant();
            if (langCode.StartsWith(German))
            {
                return German;
            }
        }
        return English;
    }

    private static T GetElement<T>(string key)
    {
        VerifySessionState();
        return (T)HttpContext.Current.Session[key];
    }

    private static void AddElement<T>(string key, T value)
    {
        VerifySessionState();
        HttpContext.Current.Session[key] = value;
    }

    private static bool HasElement<T>(string key)
    {
        VerifySessionState();
        return HttpContext.Current.Session[key] is T storedValue && storedValue != null;
    }

    private static void VerifySessionState()
    {
        if (HttpContext.Current?.Session == null)
        {
            throw new InvalidOperationException(
                "Session state is not available. Ensure session is enabled.");
        }
    }

    public static void ClearLanguagePreference()
    {
        if (HttpContext.Current?.Session != null)
        {
            HttpContext.Current.Session.Remove(LanguageKey);
        }
    }

    public static void InitializeFromCookie()
    {
        var cookie = HttpContext.Current.Request.Cookies[LanguageKey];
        if (cookie?.Value == German || cookie?.Value == English)
        {
            SetLanguage(cookie.Value);
        }
    }

