namespace FridgeNS.Controllers
{
    [Authorize]
    public class NoteController : Controller
    {
        private readonly IDal dal;

        public NoteController(IDal dal)
        {
            this.dal = dal;
        }

        [HttpPost]
        public JsonResult Add(Note note)
        {
            if (!ModelState.IsValid)
            {
                return Json(new { success = false, message = "Invalid note data." });
            }

            bool result = dal.AddNote(note);
            if (result)
            {
                return Json(new { success = true, message = "Note added successfully." });
            }
            return Json(new { success = false, message = "Failed to add note." });
        }

        [HttpPost]
        public JsonResult Remove(Note note)
        {
            if (!ModelState.IsValid || note.Id <= 0)
            {
                return Json(new { success = false, message = "Invalid note data." });
            }

            bool result = dal.RemoveNote(note.Id);
            if (result)
            {
                return Json(new { success = true, message = "Note removed successfully." });
            }
            return Json(new { success = false, message = "Failed to remove note." });
        }

        [HttpPost]
        public JsonResult Update(Note note)
        {
            if (!ModelState.IsValid || note.Id <= 0)
            {
                return Json(new { success = false, message = "Invalid note data." });
            }

            bool result = dal.UpdateNote(note);
            if (result)
            {
                return Json(new { success = true, message = "Note updated successfully." });
            }
            return Json(new { success = false, message = "Failed to update note." });
        }

        [HttpPost]
        public JsonResult Restore(Note note)
        {
            if (!ModelState.IsValid || note.Id <= 0)
            {
                return Json(new { success = false, message = "Invalid note data." });
            }

            bool result = dal.RestoreNote(note.Id);
            if (result)
            {
                return Json(new { success = true, message = "Note restored successfully." });
            }
            return Json(new { success = false, message = "Failed to restore note." });
        }
    }

    public interface IDal
    {
        bool AddNote(Note note);
        bool RemoveNote(int noteId);
        bool UpdateNote(Note note);
        bool RestoreNote(int noteId);
    }

