using System;
 
public class Coconuts
{
    public static void Main()
    {
        int[] sailors = { 5, 6 };
        foreach (int sailor in sailors)
        {
            int n = sailor;
            while (!valid(sailor, n))
            {
                n++;
            }
            Console.WriteLine("\n{0} sailors => {1} coconuts", sailor, n);
            for (int i = 0; i < sailor + 1; i++)
            {
                int div = n / sailor;
                int mod = n % sailor;
                Console.WriteLine("  {0} {1} {2}", n, div, mod);
                n -= 1 + div;
            }
        }
    }
 
    private static bool valid(int sailor, int nuts)
    {
        for (int i = 0; i < sailor; i++)
        {
            if ((nuts % sailor)!= 1)
            {
                return false;
            }
            nuts -= 1 + nuts / sailor;
        }
        return nuts > 0 && nuts % sailor == 0;
    }
}

public static object Clone(object obj)
{
    if (obj == null || obj.GetType()!= typeof(object))
        return obj;

    var temp = new Dictionary<string, object>();
    foreach (var key in obj.GetType().GetProperties())
        temp[key.Name] = Clone(key.GetValue(obj));
    return temp;
}

