using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
 
namespace MetallicRatio
{
    class Reader
    {
        static void Main(string[] args)
        {
            for (int b = 0; b < 4; b++)
            {
                var coefs = MetallicRatio(b).Take(15).Select(x => x.Item2).ToList();
                Console.WriteLine($"\nb = {b}: {string.Join(", ", coefs)}");
                Stable(b, 32);
            }
            Console.WriteLine($"\nb = 1 with 256 digits:");
            Stable(1, 256);
        }
 
        static IEnumerable<(BigInteger, BigInteger)> MetallicRatio(BigInteger b)
        {
            var m = 1;
            var n = 1;
            while (true)
            {
                yield return (m, n);
                m = m * b + n;
                n = m;
            }
        }
 
        static void Stable(BigInteger b, int prec)
        {
            var last = 0m;
            var i = 0;
            foreach (var x in ToDecimal(b))
            {
                if (x == last)
                {
                    Console.WriteLine($"after {i} iterations:\n\t{x}");
                    break;
                }
                last = x;
                i++;
            }
        }
 
        static IEnumerable<decimal> ToDecimal(BigInteger b)
        {
            foreach (var (m, n) in MetallicRatio(b))
            {
                yield return (decimal)m / (decimal)n;
            }
        }
    }
}

