public interface ICategorizable
{
    IEnumerable<string> Categories { get; }
}

public static class CategorizableExtensions
{
    private static readonly Dictionary<string, string> categoryThemeMapping = new Dictionary<string, string>
    {
        { "news", "theme-news" },
        { "blog", "theme-blog" },
        { "events", "theme-events" },
        { "products", "theme-products" },
        { "services", "theme-services" }
    };

    public static string[] GetThemeCssClassNames(this ICategorizable content)
    {
        if (content == null || content.Categories == null)
        {
            return Array.Empty<string>();
        }

        var cssClasses = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        foreach (var category in content.Categories)
        {
            if (string.IsNullOrWhiteSpace(category)) continue;

            var cssClass = GetCssClassForCategory(category.ToLowerInvariant());
            if (!string.IsNullOrWhiteSpace(cssClass))
            {
                cssClasses.Add(cssClass);
            }
        }

        return cssClasses.ToArray();
    }

    private static string GetCssClassForCategory(string category)
    {
        return categoryThemeMapping.TryGetValue(category, out var cssClass) ? cssClass : null;
    }
}

