namespace OpenRA.Mods.Common.Traits
{
    public class SmokeTrailWhenDamagedInfo : TraitInfo
    {
        [Desc("Offset from actor center where the smoke is spawned.")]
        public CPos Offset = CPos.Zero;

        [Desc("Interval between smoke sprite creations (ticks).")]
        public int Interval = 30;

        [Desc("Sprite to spawn for the smoke effect.")]
        public string Sprite = "smoke";

        [Desc("Sequence in sprite to play.")]
        public string Sequence = "default";

        [Desc("Palette to use for the smoke sprite.")]
        public string Palette = "grey";

        [Desc("Minimum damage level required to start emitting smoke.")]
        public int MinDamage = 25;
    }

    public class SmokeTrailWhenDamaged : Trait<SmokeTrailWhenDamagedInfo>
    {
        int tickCounter = 0;

        public override void Tick(Actor self)
        {
            if (self.World.FogObscures(self.CenterPosition))
                return;

            if (self.CurrentHealthPercentage() >= Info.MinDamage)
                return;

            tickCounter++;

            if (tickCounter >= Info.Interval)
            {
                tickCounter = 0;

                var offset = Info.Offset.Rotate(self.Rotation);
                var spawnPosition = self.CenterPosition + offset;

                var effect = new SpriteEffect(
                    Info.Sprite,
                    Info.Sequence,
                    Info.Palette,
                    spawnPosition,
                    Vector2D.Zero,
                    self.World,
                    false);

                self.World.Add(effect);
            }
        }
    }
}

