[CustomEditor(typeof(RigidBodyEmitterSink))]
public class RigidBodyEmitterSinkTool : Editor
{
    private RigidBodyEmitterSink m_target;
    private List<GameObject> m_availableTemplates = new List<GameObject>();
    private bool m_sinkAllMode = false;

    private void OnEnable()
    {
        m_target = target as RigidBodyEmitterSink;
        RefreshAvailableTemplates();
    }

    public override void OnInspectorGUI()
    {
        serializedObject.Update();

        EditorGUILayout.LabelField("RigidBody Emitter Sink Configuration", EditorStyles.boldLabel);

        DrawEmissionModeSection();
        DrawTemplateManagementSection();
        DrawValidationWarnings();

        serializedObject.ApplyModifiedProperties();
    }

    private void DrawEmissionModeSection()
    {
        EditorGUI.BeginChangeCheck();
        m_sinkAllMode = EditorGUILayout.Toggle("Sink All Mode", m_sinkAllMode);
        if (EditorGUI.EndChangeCheck())
        {
            Undo.RecordObject(m_target, "Toggle Sink All Mode");
            m_target.SinkAllMode = m_sinkAllMode;
        }

        GUI.enabled = !EditorApplication.isPlaying;
        EditorGUILayout.Space();
    }

    private void DrawTemplateManagementSection()
    {
        EditorGUILayout.LabelField("Template Objects", EditorStyles.boldLabel);

        for (int i = 0; i < m_availableTemplates.Count; i++)
        {
            EditorGUILayout.BeginHorizontal();
            m_availableTemplates[i] = EditorGUILayout.ObjectField($"Template {i + 1}",
                m_availableTemplates[i], typeof(GameObject), true) as GameObject;

            if (GUILayout.Button("Remove", GUILayout.Width(80)))
            {
                OnTemplateRemove(i);
                break;
            }
            EditorGUILayout.EndHorizontal();
        }

        if (GUILayout.Button("Add Template"))
        {
            OnTemplateAdd();
        }
    }

    private void DrawValidationWarnings()
    {
        if (m_availableTemplates.Count == 0)
        {
            EditorGUILayout.HelpBox("No templates configured.", MessageType.Warning);
        }

        foreach (var template in m_availableTemplates)
        {
            if (template == null)
            {
                EditorGUILayout.HelpBox("Invalid template detected.", MessageType.Error);
                break;
            }
        }
    }

    private void OnTemplateAdd()
    {
        Undo.RecordObject(m_target, "Add Template");
        m_availableTemplates.Add(null);

