namespace Game.Scenes
{
    public class TestSceneLoader : LoadingScene
    {
        private IFont _font;
        public Scene Target;
        private readonly SceneTransition _transition = new SlideTransition(Vector2.Left, 0.5f);

        private static readonly Color BackgroundColor = Color.Red;
        private static readonly Vector2 TextPosition = new Vector2(100, 100);
        private static readonly Rectangle ProgressBarBack = new Rectangle(100, 400, 500, 30);
        private static readonly Color ProgressColor = Color.Green;

        public override void LoadContent()
        {
            base.LoadContent();
            _font = ContentManager.Load<IFont>("Arial", new FontOptions { Size = 16 });
        }

        protected override void OnCompleted()
        {
            SceneManager.ChangeScene(Target, _transition);
        }

        public override void Render()
        {
            IRenderManager renderer = XGL.GetComponent<IRenderManager>();
            renderer.RenderDevice.Fill(BackgroundColor);

            RenderProgressBar(renderer);
            RenderStatusText(renderer);
        }

        private void RenderProgressBar(IRenderManager renderer)
        {
            int total = 10; // Framework total placeholder
            float progress = (CompletedElements.Count + (CurrentElement != null ? 1 : 0)) / (float)total;
            int currentWidth = (int)(ProgressBarBack.Width * progress);

            renderer.FillRectangle(
                new Rectangle(ProgressBarBack.X, ProgressBarBack.Y, currentWidth, ProgressBarBack.Height),
                ProgressColor
            );
        }

        private void RenderStatusText(IRenderManager renderer)
        {
            StringBuilder statusBuilder = new StringBuilder();
            statusBuilder.AppendLine($"Progress: {CompletedElements.Count}/10");
            statusBuilder.AppendLine("Completed:");

            foreach (string element in CompletedElements)
            {
                statusBuilder.AppendLine($"- {element}");
            }

            if (!string.IsNullOrEmpty(CurrentElement))
            {
                statusBuilder.AppendLine($"\nLoading: {CurrentElement}");
            }

            renderer.RenderText(
                _font,
                statusBuilder.ToString(),
                TextPosition,
                Color.White
            );
        }
    }
}

