namespace ScriptRunner
{
    public class RunScripts
    {
        public class Input
        {
            public string ConnectionName { get; set; }
            public ScriptDescriptor[] Scripts { get; set; }
        }

        public class ScriptDescriptor
        {
            public string FileName { get; set; }
        }

        // Configuration for Python execution mode.
        private static bool UseModuleMode = true;

        public void Execute(Input input)
        {
            if (input == null)
            {
                throw new ArgumentNullException(nameof(input));
            }

            if (input.Scripts == null || input.Scripts.Length == 0)
            {
                Console.WriteLine("No scripts provided to execute.");
                return;
            }

            foreach (var script in input.Scripts)
            {
                string extension = Path.GetExtension(script.FileName).ToLowerInvariant();
                switch (extension)
                {
                    case ".sql":
                        RunSqlTask(input.ConnectionName, script.FileName);
                        break;
                    case ".py":
                        string pythonArgs = GetPythonArguments(script.FileName);
                        RunProcessTask("python", pythonArgs);
                        break;
                    default:
                        throw new NotSupportedException($"File type '{extension}' is not supported.");
                }
            }
        }

        private static string GetPythonArguments(string fileName)
        {
            if (UseModuleMode)
            {
                // Remove extension and use as module name.
                string moduleName = Path.GetFileNameWithoutExtension(fileName);
                return $"-m {moduleName}";
            }
            else
            {
                return fileName;
            }
        }

        private void RunSqlTask(string connectionName, string fileName)
        {
            Console.WriteLine($"[SQL Task] Executing '{fileName}' on connection '{connectionName}'.");
            RunSql sqlTask = new RunSql
            {
                ConnectionName = connectionName,
                ScriptFile = fileName
            };
            sqlTask.Execute();
        }

        private void RunProcessTask(string processName, string arguments)
        {
            Console.WriteLine($"[Process Task] Running process '{processName}' with arguments '{arguments}'.");

