using System;
using System.IO;
using System.Runtime.InteropServices;
using System.Text;

public class ConfigFileHelper
{
    private const string ConfigFileName = ".wakatime.cfg";

    [DllImport("kernel32", CharSet = CharSet.Unicode)]
    private static extern long WritePrivateProfileString(string section, string key, string value, string filePath);

    [DllImport("kernel32", CharSet = CharSet.Unicode)]
    private static extern int GetPrivateProfileString(string section, string key, string defaultVal, StringBuilder retVal, int size, string filePath);

    private static string getConfigFilePath()
    {
        string userProfile = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);
        if (string.IsNullOrEmpty(userProfile))
        {
            return null;
        }
        return Path.Combine(userProfile, ConfigFileName);
    }

    public static string getApiKey(string section, string key)
    {
        string configFilepath = getConfigFilePath();
        if (string.IsNullOrEmpty(configFilepath))
        {
            return null;
        }

        StringBuilder keyValue = new StringBuilder(255);
        GetPrivateProfileString(section, key, "", keyValue, 255, configFilepath);
        return keyValue.ToString();
    }

    public static bool updateApiKey(string section, string key, string apiKey)
    {
        string configFilepath = getConfigFilePath();
        if (string.IsNullOrEmpty(configFilepath))
        {
            return false;
        }

        long result = WritePrivateProfileString(section, key, apiKey, configFilepath);
        return result != 0;
    }
}

