namespace ValueObjectDemo
{
    // Abstract class representing a value object.
    // Equality, hash code generation and cloning are based solely on object values.
    public abstract class ValueObject : ICloneable
    {
        // Derived classes must supply atomic values representing their state.
        protected abstract IEnumerable<object> GetAtomicValues();

        // Determines equality based on atomic values.
        public override bool Equals(object obj)
        {
            if (obj == null || obj.GetType() != GetType())
                return false;

            ValueObject other = (ValueObject)obj;

            IEnumerator<object> thisValues = GetAtomicValues().GetEnumerator();
            IEnumerator<object> otherValues = other.GetAtomicValues().GetEnumerator();

            while (thisValues.MoveNext() && otherValues.MoveNext())
            {
                // Check for null mismatch.
                if (thisValues.Current == null ^ otherValues.Current == null)
                    return false;

                // If both not null, check equality.
                if (thisValues.Current != null &&
                    !thisValues.Current.Equals(otherValues.Current))
                    return false;
            }

            // Both sets must have been exhausted.
            return !thisValues.MoveNext() && !otherValues.MoveNext();
        }

        // Generates hash code by combining hash codes of atomic values.
        public override int GetHashCode()
        {
            int hash = 17;
            foreach (object atomic in GetAtomicValues())
            {
                int atomicHash = atomic != null ? atomic.GetHashCode() : 0;
                hash = hash * 31 + atomicHash;
            }
            return hash;
        }

        // Creates a shallow copy of the current object.
        public object GetCopy()
        {
            return this.MemberwiseClone();
        }

        // Implements ICloneable interface.
        public object Clone()
        {
            return GetCopy();
        }

        // Helper for equality operator.
        public static bool EqualOperator(ValueObject left, ValueObject right)
        {
            // If one is null, but not both, return false.
            if (ReferenceEquals(left, null) ^ ReferenceEquals(right, null))
                return false;

            // If both are null or equal, return result.
            return ReferenceEquals(left, null) || left.Equals(right);
        }

