namespace Cats.EarlyWarning.Services
{
    // Domain Models
    public class ProcessTemplate
    {
        public int Id { get; set; }
        public string Name { get; set; }
    }

    public class StateTemplate
    {
        public int Id { get; set; }
        public int ProcessTemplateId { get; set; }
        public string StateType { get; set; } // e.g., "Start", "Intermediate", "End"
    }

    // Repository Interface
    public interface IRepository<T>
    {
        void Add(T entity);
        void Update(T entity);
        void Delete(T entity);
        void DeleteById(int id);
        T FindById(int id);
        IEnumerable<T> GetAll();
        IEnumerable<T> FindBy(Expression<Func<T, bool>> predicate);
    }

    // Unit of Work Interface
    public interface IUnitOfWork
    {
        IRepository<ProcessTemplate> ProcessTemplateRepository { get; }
        IRepository<StateTemplate> StateTemplateRepository { get; }
        int Commit();
    }

    // Service Interface
    public interface IProcessTemplateService
    {
        bool Add(ProcessTemplate template);
        bool Update(ProcessTemplate template);
        bool Delete(ProcessTemplate template);
        bool DeleteById(int id);
        ProcessTemplate FindById(int id);
        IEnumerable<ProcessTemplate> GetAll();
        IEnumerable<ProcessTemplate> FindBy(Expression<Func<ProcessTemplate, bool>> predicate);
        StateTemplate GetStartingState(int processTemplateId);
    }

    // Service Implementation
    public class ProcessTemplateService : IProcessTemplateService
    {
        private readonly IUnitOfWork _unitOfWork;

        public ProcessTemplateService(IUnitOfWork unitOfWork)
        {
            _unitOfWork = unitOfWork;
        }

        public bool Add(ProcessTemplate template)
        {
            if (template == null)
                return false;
            _unitOfWork.ProcessTemplateRepository.Add(template);
            return _unitOfWork.Commit() > 0;
        }

        public bool Update(ProcessTemplate template)
        {
            if (template == null)
                return false;
            _unitOfWork.ProcessTemplateRepository.Update(template);
            return _unitOfWork.Commit() > 0;
        }

        public bool Delete(ProcessTemplate template)
        {
            if (template == null)
                return false;
            _unitOfWork.ProcessTemplateRepository.Delete(template);
            return _unitOfWork.Commit() > 0;
        }

