namespace Triangle
{
    class Student
    {
        // Window dimensions.
        const int Width = 640;
        const int Height = 480;
 
        static void Main(string[] args)
        {
            // OpenGL requires a dedicated OS thread.
            Thread.CurrentThread.IsBackground = false;
 
            using (var window = new GameWindow(Width, Height, new GraphicsMode(32, 24, 0, 8), "Triangle", GameWindowFlags.Default, DisplayDevice.Default, 2, 1, GraphicsContextFlags.Default))
            {
                window.Load += (sender, e) =>
                {
                    // Initiate viewport.
                    resize(Width, Height);
 
                    // Register that we are interested in receiving close and resize events.
                    window.Closing += (o, e) =>
                    {
                        return;
                    };
                    window.Resize += (o, e) =>
                    {
                        resize(window.Width, window.Height);
                    };
                };
 
                window.RenderFrame += (sender, e) =>
                {
                    draw();
                    window.SwapBuffers();
                };
 
                window.Run(60.0);
            }
        }
 
        // resize resizes the window to the specified dimensions.
        static void resize(int width, int height)
        {
            GL.Viewport(0, 0, width, height);
            GL.MatrixMode(MatrixMode.Projection);
            GL.LoadIdentity();
            GL.Ortho(-30.0, 30.0, -30.0, 30.0, -30.0, 30.0);
            GL.MatrixMode(MatrixMode.Modelview);
        }
 
        // draw draws the triangle.
        static void draw()
        {
            GL.ClearColor(0.3f, 0.3f, 0.3f, 0.0f);
            GL.Clear(ClearBufferMask.ColorBufferBit | ClearBufferMask.DepthBufferBit);
 
            GL.ShadeModel(ShadingModel.Smooth);
 
            GL.LoadIdentity();
            GL.Translate(-15.0, -15.0, 0.0);
 
            GL.Begin(PrimitiveType.Triangles);
 
            GL.Color3(1.0, 0.0, 0.0);
            GL.Vertex2(0.0, 0.0);
 
            GL.Color3(0.0, 1.0, 0.0);
            GL.Vertex2(30.0, 0.0);
 
            GL.Color3(0.0, 0.0, 1.0);
            GL.Vertex2(0.0, 30.0);
 
            GL.End();
 
            GL.Flush();
        }
    }
}

