    [Export(typeof(DebuggerDependencyContainer))]
    public class DebuggerDependencyContainer
    {
        public IDebuggerSettings DebuggerSettings { get; }
        public Lazy<ICodeLocationFactory> CodeLocationFactory { get; }
        public IModuleMemoryRefreshNotifier ModuleMemoryRefreshNotifier { get; }
        public IRawMetadataService RawMetadataService { get; }
        public IEngineStepperFactory EngineStepperFactory { get; }

        [ImportingConstructor]
        public DebuggerDependencyContainer(
            IDebuggerSettings debuggerSettings,
            Lazy<ICodeLocationFactory> codeLocationFactory,
            IModuleMemoryRefreshNotifier moduleMemoryRefreshNotifier,
            IRawMetadataService rawMetadataService,
            IEngineStepperFactory engineStepperFactory)
        {
            DebuggerSettings = debuggerSettings ?? throw new ArgumentNullException(nameof(debuggerSettings));
            CodeLocationFactory = codeLocationFactory ?? throw new ArgumentNullException(nameof(codeLocationFactory));
            ModuleMemoryRefreshNotifier = moduleMemoryRefreshNotifier ?? throw new ArgumentNullException(nameof(moduleMemoryRefreshNotifier));
            RawMetadataService = rawMetadataService ?? throw new ArgumentNullException(nameof(rawMetadataService));
            EngineStepperFactory = engineStepperFactory ?? throw new ArgumentNullException(nameof(engineStepperFactory));
        }

