        {
            Console.WriteLine("Initializing Debug Engine with provided dependencies.");
            Console.WriteLine("Debugger setting sample: " + DebuggerSettings.GetSetting("LogLevel"));
            CodeLocationFactory.Value.CreateCodeLocation();
            ModuleMemoryRefreshNotifier.RefreshModuleMemory();
            RawMetadataService.LoadMetadata();
            EngineStepperFactory.CreateStepper();
            Console.WriteLine("Debug Engine initialization complete.");
        }
