using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace Checker
{
    class Converter
    {
        static void Main(string[] args)
        {
            int[] array = new int[] { 23, 76, 99, 58, 97, 57, 35, 89, 51, 38, 95, 92, 24, 46, 31, 24, 14, 12, 57, 78 };
            array.combsort();
            foreach (var item in array)
            {
                Console.WriteLine(item);
            }
            Console.ReadKey();
        }
    }

    public static class ArrayExtensions
    {
        public static void combsort(this int[] array)
        {
            int gap = array.Length;
            bool swaps = true;
            while (gap > 1 || swaps)
            {
                gap = Math.Max(1, (int)(gap / 1.25));
                swaps = false;
                for (int i = 0; i < array.Length - gap - 1; i++)
                {
                    if (array[i] > array[i + gap])
                    {
                        int temp = array[i];
                        array[i] = array[i + gap];
                        array[i + gap] = temp;
                        swaps = true;
                    }
                }
            }
        }
    }
}

