public static double avg(params double[] arr) {
    double sum = 0.0;
    foreach (double x in arr) {
        sum += x;
    }
    return sum / arr.length;
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
 
namespace Handler
{
    class Calculator
    {
        static int[] list = { -7, 1, 5, 2, -4, 3, 0 };
 
        static int eq_idx(int[] a, int len, out int[] ret)
        {
            int i, sum, s, cnt;
            /* alloc long enough: if we can afford the original list,
             * we should be able to afford to this.  Beats a potential
             * million realloc() calls.  Even if memory is a real concern,
             * there's no garantee the result is shorter than the input anyway */
            cnt = s = sum = 0;
            ret = new int[len];
 
            for (i = 0; i < len; i++)
                sum += a[i];
 
            for (i = 0; i < len; i++)
            {
                if (s * 2 + a[i] == sum)
                {
                    ret[cnt] = i;
                    cnt++;
                }
                s += a[i];
            }
 
            /* uncouraged way to use realloc since it can leak memory, for example */
            ret = new int[cnt];
 
            return cnt;
        }
 
        static void Main(string[] args)
        {
            int i, cnt;
            int[] idx;
            cnt = eq_idx(list, list.Length, out idx);
 
            Console.Write("Found:");
            for (i = 0; i < cnt; i++)
                Console.Write(" {0}", idx[i]);
            Console.WriteLine();
        }
    }
}

using System;

class MalkoKote
{
    static void Main(string[] args)
    {
        Console.WriteLine("Enter the size of the cat (integer):");
        int size = int.Parse(Console.ReadLine());

        Console.WriteLine("Enter the character to use for the cat:");
        char character = Console.ReadLine()[0];

        int width = size * 2 + 1;
        int catBodyWidth = width - 2;

        GenerateCat(size, character, width, catBodyWidth);
    }

    static void GenerateCat(int size, char character, int width, int catBodyWidth)
    {
        // Top part of the cat (ears)
        Console.WriteLine(new string(' ', size) + $"{character}{character}");

        // Head
        Console.WriteLine(new string(' ', size - 1) + $"{character}{new string(' ', catBodyWidth)}{character}");

        // Eyes
        Console.WriteLine(new string(' ', size - 1) + $"{character}{new string(' ', (catBodyWidth - 1) / 2)}* *{new string(' ', (catBodyWidth - 1) / 2)}{character}");

        // Face
        Console.WriteLine(new string(' ', size - 1) + $"{character}{new string(' ', catBodyWidth)}{character}");

        // Mouth
        Console.WriteLine(new string(' ', size - 1) + $"{character}{new string(' ', (catBodyWidth - 2) / 2)}\" {new string(' ', (catBodyWidth - 2) / 2)}{character}");

        // Body
        for (int i = 0; i < size; i++)
        {
            Console.WriteLine(new string(' ', size - i - 1) + $"{character}{new string(' ', catBodyWidth)}{character}");
        }

        // Legs
        for (int i = 0; i < size / 2; i++)
        {
            Console.WriteLine(new string(' ', size - 1) + $"{character}{new string(' ', catBodyWidth)}{character}");
        }

        // Tail
        Console.WriteLine(new string(' ', size) + $"{character}{character}{new string(' ', catBodyWidth)}{character}");
        Console.WriteLine(new string(' ', size + 1) + $"{character}");
    }
}

