using CharacterMap.Core;
using CharacterMap.Models;
using System;
using System.Collections.Generic;
using Windows.UI.Xaml.Controls;
using Windows.UI.Xaml.Media;
using Windows.UI.Xaml;

public class VBDevProvider : DevProviderBase
{
    public VBDevProvider(Character c, CharacterRenderingOptions o) : base(c, o)
    {
    }

    public override DevProviderType GetDevProviderType() => DevProviderType.VisualBasic;

    public override List<DevOption> OnGetOptions()
    {
        var options = new List<DevOption>();
        string hex = Char.UnicodeEncoding.Convert(new byte[] { (byte)(Char.Code >> 0), (byte)(Char.Code >> 8) }, 0, 2);
        string fontName = $"\"{Options.XamlFontSource.Source}\"";

        string fontIconCode = $@"Dim icon As New FontIcon()
icon.FontFamily = New FontFamily({fontName})
icon.Glyph = ""{hex}""
icon.HorizontalAlignment = HorizontalAlignment.Center
icon.VerticalAlignment = VerticalAlignment.Center";
        options.Add(new DevOption("FontIcon", fontIconCode));

        if (FontFinder.IsSystemSymbolFamily(Options.XamlFontSource.Source))
        {
            if (Enum.TryParse(Char.Symbol.ToString(), out Symbol symbol))
            {
                string symbolIconCode = $@"Dim icon As New SymbolIcon()
icon.Symbol = Symbol.{symbol}
icon.HorizontalAlignment = HorizontalAlignment.Center
icon.VerticalAlignment = VerticalAlignment.Center";
                options.Add(new DevOption("SymbolIcon", symbolIconCode));
            }
        }

        var outline = GetOutlineGeometry(Char, Options.XamlFontSource);
        if (outline != null)
        {
            string pathIconCode = $@"Dim icon As New PathIcon()
Dim geo As Geometry = XamlBindingHelper.ConvertValue(GetType(Geometry), ""{outline.Data}"")
icon.Data = geo
icon.HorizontalAlignment = HorizontalAlignment.Center
icon.VerticalAlignment = VerticalAlignment.Center";
            options.Add(new DevOption("PathIcon", pathIconCode));
        }

        return options;
    }

    public override List<ContextOption> OnGetContextOptions()
    {
        return new List<ContextOption>();
    }
}

