    {
        public static GetDataReplicationRulesSpectraS3Response Parse(IWebResponse response)
        {
            ResponseParseUtilities.HandleStatusCode(response, HttpStatusCode.OK);

            using (var responseStream = response.GetResponseStream())
            {
