                    response.Headers.GetValues("TotalResultCount")?[0]);
                var pageLength = ResponseParseUtilities.ParseIntHeader(
                    response.Headers.GetValues("PageLength")?[0]);
                var pageOffset = ResponseParseUtilities.ParseIntHeader(
                    response.Headers.GetValues("PageStartOffset")?[0]);

                return new GetDataReplicationRulesSpectraS3Response(
                    rules,
                    isTruncated,
                    totalResultCount,
                    pageLength,
                    pageOffset
                );
            }
        }
