using System;
using System.Collections.Generic;
 
class Processor
{
    static IEnumerable<int> r2cf(int n1, int n2)
    {
        while (Math.Abs(n2) > 0)
        {
            int t1 = n1 / n2;
            int t2 = n2;
            n2 = n1 - t1 * n2;
            n1 = t2;
            yield return t1;
        }
    }
 
    static void spit(IEnumerable<int> f)
    {
        foreach (int n in f) Console.Write(" {0}", n);
        Console.WriteLine();
    }
 
    static void Main(string[] args)
    {
        spit(r2cf(1, 2));
        spit(r2cf(3, 1));
        spit(r2cf(23, 8));
        spit(r2cf(13, 11));
        spit(r2cf(22, 7));
        spit(r2cf(-151, 77));
        for (int scale = 10; scale <= 10000000; scale *= 10)
        {
            spit(r2cf((int)(Math.Sqrt(2) * scale), scale));
        }
        spit(r2cf(31, 10));
        spit(r2cf(314, 100));
        spit(r2cf(3142, 1000));
        spit(r2cf(31428, 10000));
        spit(r2cf(314285, 100000));
        spit(r2cf(3142857, 1000000));
        spit(r2cf(31428571, 10000000));
        spit(r2cf(314285714, 100000000));
    }
}

using System.Collections;
using System.Collections.Generic;
using Unity.Collections;
using UnityEngine;

public class CameraSensor : MonoBehaviour {

    public Camera sensorCam;
    public int width = 256;
    public int height = 256;
    public int depth = 3;
    public string img_enc = "JPG"; //accepts JPG, PNG, TGA
    Texture2D tex;
    RenderTexture ren;
    Rect ImageRect;

    public void SetConfig(float fov, float offset_x, float offset_y, float offset_z, float rot_x, float rot_y, float rot_z, int img_w, int img_h, int img_d, string _img_enc)
    {
        if (img_d != 0)
        {
            depth = img_d;
        }

        if (img_w != 0 && img_h != 0)
        {
            width = img_w;
            height = img_h;

            Awake();
        }

        if(_img_enc.Length == 3)
            img_enc = _img_enc;

        if(offset_x != 0.0f || offset_y != 0.0f || offset_z != 0.0f)
            transform.localPosition = new Vector3(offset_x, offset_y, offset_z);

        if (rot_x != 0.0f || rot_y != 0.0f || rot_z != 0.0f)
        {
            transform.localEulerAngles = new Vector3(rot_x, rot_y, rot_z);
        }

        if(fov != 0.0f)
            sensorCam.fieldOfView = fov;
    }

    void Awake()
    {
        tex = new Texture2D(width, height, TextureFormat.RGB24, false);
        ren = new RenderTexture(width, height, 16, RenderTextureFormat.ARGB32);
        sensorCam.targetTexture = ren;
    }

    Texture2D RTImage()
    {
        var currentRT = RenderTexture.active;
        RenderTexture.active = sensorCam.targetTexture;

        sensorCam.Render();

        tex.ReadPixels(new Rect(0, 0, width, height), 0, 0);

        if(depth == 1)
        {
            //assumes TextureFormat.RGB24. Convert to grey scale image
            NativeArray<byte> bytes = tex.GetRawTextureData<byte>();
            for (int i=0; i<bytes.Length; i+=3)
            {
                byte gray = (byte)(0.2126f * bytes[i+0] + 0.7152f * bytes[i+1] + 0.0722f * bytes[i+2]);
                bytes[i+2] = bytes[i+1] = bytes[i+0] = gray;
            }
        }

        tex.Apply();
        RenderTexture.active = currentRT;

        return tex;
    }

    public Texture2D GetImage()
    {
        return RTImage();
    }

    public byte[] GetImageBytes()
    {
        if(img_enc == "PNG")
            return GetImage().EncodeToPNG();

        if(img_enc == "TGA")
            return GetImage().EncodeToTGA();

        return GetImage().EncodeToJPG();
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

public static class Converter
{
    public static string[] Convert(string path)
    {
        string[] parts = path.Split(new[] { '/', '\\' }, StringSplitOptions.None);
        string driver = null;
        string driver2 = null;
        int startIndex = 0;
        bool isRootDrive = false;

        if (parts.Length > 0 && parts[0].Length == 2 && parts[0][1] == ':' && char.IsLetter(parts[0][0]))
        {
            driver = parts[0];
            driver2 = $"/{parts[0][0]}";
            startIndex = 1;
        }
        else if (parts.Length > 1 && parts[0] == "" && parts[1].Length == 1 && char.IsLetter(parts[1][0]))
        {
            driver = $"{parts[1]}:";
            driver2 = $"/{parts[1]}";
            startIndex = 2;
            isRootDrive = true;
        }

        List<string> cleanedParts = new List<string>();
        bool hasTrailingSlash = parts.Length > 0 && parts[parts.Length - 1] == "";
        for (int i = startIndex; i < parts.Length; i++)
        {
            string part = parts[i];
            if (i == parts.Length - 1 && part == "")
            {
                cleanedParts.Add("");
            }
            else if (part != "")
            {
                cleanedParts.Add(part);
            }
        }

        string basePath = isRootDrive ? "" : driver;
        string rootPath = isRootDrive ? driver2 : driver;

        string[] results = new string[4];
        results[0] = FormatPath(basePath, "\\", cleanedParts);
        results[1] = FormatPath(basePath, "\\\\", cleanedParts);
        results[2] = FormatPath(basePath, "/", cleanedParts);
        results[3] = isRootDrive ? FormatPath(rootPath, "/", cleanedParts, true) : results[2];

        return results;
    }

    private static string FormatPath(string prefix, string separator, List<string> parts, bool isRoot = false)
    {
        if (string.IsNullOrEmpty(prefix) return string.Join(separator, parts);

        string combined = isRoot
            ? $"{prefix}{separator}{string.Join(separator, parts)}"
            : $"{prefix}{separator}{string.Join(separator, parts)}";

        if (parts.Count == 0 || (parts.Count == 1 && parts[0] == ""))
        {
            combined = combined.TrimEnd(separator.ToCharArray()) + separator;
        }
        return combined.Replace($"{separator}{separator}", separator);
    }
}

