using System.Collections;
using Nequeo.Cryptography.Key.Asn1;

namespace Cryptography.Parameters
{
    public sealed class Gost28147Parameters : IAsn1Convertible
    {
        private readonly Asn1OctetString initialization;
        private readonly DerObjectIdentifier parameterSet;

        private Gost28147Parameters(Asn1OctetString iv, DerObjectIdentifier paramSet)
        {
            initialization = iv ?? throw new ArgumentNullException(nameof(iv));
            parameterSet = paramSet ?? throw new ArgumentNullException(nameof(paramSet));

            ValidateParameters();
        }

        private void ValidateParameters()
        {
            if (initialization.GetOctets().Length != 8)
                throw new ArgumentException("Initialization vector must be 8 bytes long");
        }

        public byte[] GetInitializationVector() => initialization.GetOctets();
        public DerObjectIdentifier GetParameterSet() => parameterSet;

        public static Gost28147Parameters GetInstance(object obj)
        {
            switch (obj)
            {
                case Gost28147Parameters parameters:
                    return parameters;

                case Asn1Sequence sequence:
                    return CreateFromSequence(sequence);

                case null:
                    throw new ArgumentNullException(nameof(obj));

                default:
                    throw new ArgumentException("Invalid object type for GOST 28147-89 parameters");
            }
        }

        private static Gost28147Parameters CreateFromSequence(Asn1Sequence sequence)
        {
            if (sequence.Count != 2)
                throw new ArgumentException("Invalid sequence length for GOST 28147-89 parameters");

            var iv = Asn1OctetString.GetInstance(sequence[0]);
            var paramSet = DerObjectIdentifier.GetInstance(sequence[1]);

            return new Gost28147Parameters(iv, paramSet);
        }

        public static Gost28147Parameters CreateParameters(byte[] initVector, DerObjectIdentifier paramSet)
        {
            return new Gost28147Parameters(
                new DerOctetString(initVector),
                paramSet
            );
        }

        public Asn1Object ToAsn1Object()
        {
            return new DerSequence(
                initialization,
                parameterSet
            );
        }

        public override bool Equals(object obj)
        {
            if (obj is Gost28147Parameters other)
            {
                return initialization.Equals(other.initialization) &&

using System;
using System.Xml.Linq;
using Xunit;

public class ProjectBuilder
{
    private XElement _project;

    public ProjectBuilder()
    {
        _project = new XElement("Project");
    }

    public ProjectBuilder Create(string toolsVersion)
    {
        _project.SetAttributeValue("ToolsVersion", toolsVersion);
        return this;
    }

    public ProjectBuilder AddPropertyGroup()
    {
        _project.Add(new XElement("PropertyGroup"));
        return this;
    }

    public ProjectBuilder AddProperty(string name, string value)
    {
        var lastGroup = _project.Elements("PropertyGroup").Last();
        lastGroup.Add(new XElement(name, value));
        return this;
    }

    public ProjectBuilder AddTarget(string name, string dependsOnTargets = null)
    {
        var target = new XElement("Target", new XAttribute("Name", name));
        if (!string.IsNullOrEmpty(dependsOnTargets))
        {
            target.SetAttributeValue("DependsOnTargets", dependsOnTargets);
        }
        _project.Add(target);
        return this;
    }

    public ProjectBuilder AddItem(string itemGroupName, string itemName, string include)
    {
        var itemGroup = new XElement(itemGroupName);
        itemGroup.Add(new XElement(itemName, new XAttribute("Include", include)));
        _project.Add(itemGroup);
        return this;
    }

    public ProjectBuilder ExitTarget()
    {
        return this;
    }

    public string GenerateXml()
    {
        return _project.ToString();
    }
}

public class ProjectBuilderTests
{
    [Fact]
    public void TestProjectBuilderCreatesValidXml()
    {
        var builder = new ProjectBuilder()
            .Create("15.0")
            .AddPropertyGroup()
            .AddProperty("Configuration", "Debug")
            .AddTarget("Build", "Clean")
            .AddItem("Compile", "Compile", "Program.cs")
            .ExitTarget();

        var expectedXml = @"<Project ToolsVersion=""15.0"">
  <PropertyGroup>
    <Configuration>Debug</Configuration>
  </PropertyGroup>
  <Target Name=""Build"" DependsOnTargets=""Clean"">
    <Compile Include=""Program.cs"" />
  </Target>
</Project>";

        var actualXml = builder.GenerateXml();

        Assert.Equal(NormalizeXml(expectedXml), NormalizeXml(actualXml));
    }

    private string NormalizeXml(string xml)
    {
        var doc = XDocument.Parse(xml);
        return doc.ToString(SaveOptions.DisableFormatting);
    }
}

