    {
        private static readonly Logger logger = LogManager.GetCurrentClassLogger();

        public Decision IsSatisfiedBy(RemoteEpisode report, Profile profile)
        {
            logger.Debug("Evaluating RemoteEpisode with quality: {0}", report.ParsedEpisodeInfo?.Quality);
            if (profile.Items.Exists(item =>
                item.AllowedQuality.Equals(report.ParsedEpisodeInfo?.Quality, StringComparison.OrdinalIgnoreCase)))
            {
                logger.Debug("Episode quality allowed by profile.");
                return new Decision { Accepted = true };
            }
            else
            {
                logger.Debug("Episode quality not allowed by profile.");
                return new Decision
                {
                    Accepted = false,
                    RejectionType = RejectionType.Permanent,
                    Reason = "Episode quality not allowed by user profile."
                };
            }
        }

