using AutoMapper.Mappers.Internal;
using AutoMapper.Mappers;

namespace AutoMapper.Mappers
{
    public class EnumToEnumMapper : IObjectMapper
    {
        private static readonly MethodInfo MapMethodInfo = typeof(EnumToEnumMapper).GetMethod("Map", BindingFlags.Static | BindingFlags.NonPublic);

        public bool IsMatch(TypePair context) => context.SourceType.IsEnum && context.DestinationType.IsEnum;

        public Expression MapExpression(IConfigurationProvider configurationProvider, ProfileMap profileMap,
            PropertyMap propertyMap, Expression sourceExpression, Expression destExpression, Expression contextExpression) =>
                Expression.Call(null, MapMethodInfo.MakeGenericMethod(sourceExpression.Type, destExpression.Type), sourceExpression);

        private static TDestination Map<TSource, TDestination>(TSource source)
        {
            if (!Enum.IsDefined(typeof(TSource), source))
                return (TDestination)(object)source;

            var sourceString = source.ToString();
            if (Enum.GetNames(typeof(TDestination)).Contains(sourceString))
                return (TDestination)Enum.Parse(typeof(TDestination), sourceString);

            var underlyingSourceType = Enum.GetUnderlyingType(typeof(TSource));
            var underlyingDestinationType = Enum.GetUnderlyingType(typeof(TDestination));

            var sourceValue = Convert.ChangeType(source, underlyingSourceType);

            if (Enum.GetNames(typeof(TDestination)).Any(name => string.Equals(name, sourceString, StringComparison.Ordinal)))
            {
                return (TDestination)Enum.Parse(typeof(TDestination), sourceString);
            }

            return (TDestination)Convert.ChangeType(sourceValue, underlyingDestinationType);
        }
    }
}

using System;
using System.Linq;
 
namespace Luhn
{
    public static class Luhn
    {
        public static bool Validate(string isin)
        {
            // Preliminary checks to avoid working on non-ASCII stuff
            if (!isin.All(char.IsLetterOrDigit) || isin.Length!= 12)
            {
                return false;
            }
            if (!isin.Take(2).All(char.IsLetter)
                ||!isin.Skip(2).Take(10).All(char.IsLetterOrDigit)
                ||!char.IsDigit(isin.Last()))
            {
                return false;
            }
 
            // Converts the alphanumeric string in a numeric-only string
            var s2 = isin.Select(c =>
            {
                if (char.IsDigit(c))
                {
                    return c;
                }
                else
                {
                    return (char)(c + 10 - 'A');
                }
            }).ToArray();
 
            var number = new string(s2);
            return ComputeLuhn(number);
        }
 
        public static bool ComputeLuhn(string number)
        {
            var sum = 0;
            var alt = false;
            for (int i = number.Length - 1; i >= 0; i--)
            {
                var n = number[i] - '0';
                if (alt)
                {
                    n *= 2;
                    if (n > 9)
                    {
                        n = (n % 10) + 1;
                    }
                }
                sum += n;
                alt =!alt;
            }
            return (sum % 10) == 0;
        }
    }
}

using UnityEngine;
using System.Collections;

public class PlayerController : MonoBehaviour
{
    public float maxSpeed = 10f;
    public float climbSpeed = 5f;
    public float jumpHeight = 10f;
    public bool hidden = false;
    public bool jumping = false;
    public bool climbing = false;
    public bool facingRight = true;

    private Rigidbody2D physics;
    private Animator animator;
    private IUseable useable;

    void Start()
    {
        physics = GetComponent<Rigidbody2D>();
        animator = GetComponent<Animator>();
    }

    void FixedUpdate()
    {
        float move = Input.GetAxis("Horizontal");
        float climb = Input.GetAxis("Vertical");

        if (!hidden && !climbing)
        {
            physics.velocity = new Vector2(move * maxSpeed, physics.velocity.y);
            animator.SetFloat("speed", Mathf.Abs(move));

            if (move > 0 && !facingRight)
                Flip();
            else if (move < 0 && facingRight)
                Flip();
        }

        if (climbing)
        {
            physics.velocity = new Vector2(physics.velocity.x, climb * climbSpeed);
            animator.SetBool("isClimbing", true);
        }
        else
        {
            animator.SetBool("isClimbing", false);
        }

        if (Input.GetButtonDown("Jump") && !jumping)
        {
            physics.AddForce(new Vector2(0, jumpHeight), ForceMode2D.Impulse);
            jumping = true;
            animator.SetBool("isJumping", true);
        }

        if (Input.GetKeyDown(KeyCode.E) && useable != null)
        {
            Use();
        }
    }

    void Flip()
    {
        facingRight = !facingRight;
        Vector3 scale = transform.localScale;
        scale.x *= -1;
        transform.localScale = scale;
    }

    void Use()
    {
        useable.Use();
    }

    void OnCollisionEnter2D(Collision2D collision)
    {
        if (collision.gameObject.CompareTag("Ground"))
        {
            jumping = false;
            animator.SetBool("isJumping", false);
        }
    }

    void OnTriggerEnter2D(Collider2D other)
    {
        if (other.CompareTag("Useable"))
        {
            useable = other.GetComponent<IUseable>();
        }
    }

    void OnTriggerExit2D(Collider2D other)
    {
        if (other.CompareTag("Useable"))
        {
            useable = null;
        }
    }

    public void ToggleClimbing()
    {
        climbing = !climbing;
    }
}

public interface IUseable
{
    void Use();
}

using System;
using System.Collections.Generic;
using System.Linq;
 
public static class TwelveStatements
{
    public static void Main() {
        Func<Statements, bool>[] checks = {
            st => st[1],
            st => st[2] == (7.To(12).Count(i => st[i]) == 3),
            st => st[3] == (2.To(12, by: 2).Count(i => st[i]) == 2),
            st => st[4] == st[5].Implies(st[6] && st[7]),
            st => st[5] == (!st[2] && !st[3] && !st[4]),
            st => st[6] == (1.To(12, by: 2).Count(i => st[i]) == 4),
            st => st[7] == (st[2] != st[3]),
            st => st[8] == st[7].Implies(st[5] && st[6]),
            st => st[9] == (1.To(6).Count(i => st[i]) == 3),
            st => st[10] == (st[11] && st[12]),
            st => st[11] == (7.To(9).Count(i => st[i]) == 1),
            st => st[12] == (1.To(11).Count(i => st[i]) == 4)
        };
 
        for (Statements statements = new Statements(0); statements.Value < 4096; statements++) {
            int count = 0;
            int falseIndex = 0;
            for (int i = 0; i < checks.Length; i++) {
                if (checks[i](statements)) count++;
                else falseIndex = i;
            }
            if (count == 0) Console.WriteLine($"{"All wrong:", -13}{statements}");
            else if (count == 11) Console.WriteLine($"{$"Wrong at {falseIndex + 1}:", -13}{statements}");
            else if (count == 12) Console.WriteLine($"{"All correct:", -13}{statements}");
        }
    }
 
    struct Statements
    {
        public Statements(int value) : this() { Value = value; }
 
        public int Value { get; }
 
        public bool this[int index] => (Value & (1 << index - 1)) != 0;
 
        public static Statements operator ++(Statements statements) => new Statements(statements.Value + 1);
 
        public override string ToString() {
            Statements copy = this; //Cannot access 'this' in anonymous method...
            return string.Join(" ", from i in 1.To(12) select copy[i] ? "T" : "F");
        }
 
    }
 
    //Extension methods
    static bool Implies(this bool x, bool y) => !x || y;
 
    static IEnumerable<int> To(this int start, int end, int by = 1) {
        while (start <= end) {
            yield return start;
            start += by;
        }
    }
 
}

