using System;
 
public class SelectionSort
{
    public static void SelectionSort(int[] a)
    {
        int n = a.Length;
        for (int i = 0; i < n; i++)
        {
            for (int j = i, m = i; j < n; j++)
            {
                if (a[j] < a[m])
                {
                    m = j;
                }
            }
            int t = a[i];
            a[i] = a[m];
            a[m] = t;
        }
    }
 
    public static void Main()
    {
        int[] a = { 4, 65, 2, -31, 0, 99, 2, 83, 782, 1 };
        int n = a.Length;
        for (int i = 0; i < n; i++)
        {
            Console.Write(a[i]);
            if (i!= n - 1)
            {
                Console.Write(" ");
            }
        }
        Console.WriteLine();
        SelectionSort(a);
        for (int i = 0; i < n; i++)
        {
            Console.Write(a[i]);
            if (i!= n - 1)
            {
                Console.Write(" ");
            }
        }
        Console.WriteLine();
    }
}

