using System;
using System.Collections.Generic;
using System.Reflection;

public interface IReflectionGraphFactory
{
    IReflectionGraphPropertyVisitor CreateVisitor(Type type);
}

public interface IReflectionGraphPropertyVisitor
{
    void VisitProperty(PropertyInfo property);
}

public class ReflectionGraphTraveller
{
    private const BindingFlags PropertyBindings = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance;

    private readonly IReflectionGraphFactory _factory;

    public ReflectionGraphTraveller(IReflectionGraphFactory factory)
    {
        _factory = factory;
    }

    public void Travel(Type type)
    {
        var travelledTypes = new HashSet<Type>();
        var visitor = _factory.CreateVisitor(type);
        TravelRecursive(travelledTypes, type, visitor);
    }

    private void TravelRecursive(HashSet<Type> travelledTypes, Type type, IReflectionGraphPropertyVisitor visitor)
    {
        if (travelledTypes.Contains(type))
            return;

        travelledTypes.Add(type);

        foreach (var property in type.GetProperties(PropertyBindings))
        {
            visitor.VisitProperty(property);

            var propertyType = property.PropertyType;
            if (propertyType.IsClass && propertyType != typeof(string))
            {
                var nestedVisitor = _factory.CreateVisitor(propertyType);
                TravelRecursive(travelledTypes, propertyType, nestedVisitor);
            }
        }
    }
}

// Example implementation of IReflectionGraphFactory and IReflectionGraphPropertyVisitor
public class ExampleFactory : IReflectionGraphFactory
{
    public IReflectionGraphPropertyVisitor CreateVisitor(Type type)
    {
        return new ExampleVisitor();
    }
}

public class ExampleVisitor : IReflectionGraphPropertyVisitor
{
    public void VisitProperty(PropertyInfo property)
    {
        Console.WriteLine($"Visited Property: {property.Name} of Type: {property.PropertyType.Name}");
    }
}

// Example usage
public class Cache
{
    public static void Main()
    {
        var factory = new ExampleFactory();
        var traveller = new ReflectionGraphTraveller(factory);
        traveller.Travel(typeof(ExampleClass));
    }
}

