namespace gView.Framework.Metadata.UI
{
    public partial class FormMetadata : Form
    {
        private Metadata _metadata;
        private object _metadataObject;
        private XmlStream _xmlStream;

        public FormMetadata(IMetadataObjectParameter parameter)
        {
            InitializeComponent();
            if (parameter != null)
            {
                _metadataObject = parameter.Object;
                _xmlStream = parameter.MetadataStream;
            }
        }

        private void FormMetadata_Load(object sender, System.EventArgs e)
        {
            tabControl1.TabPages.Clear();
            ReadMetadata();

            foreach (var provider in PlugInManager.GetPlugins(PluginType.MetadataProvider))
            {
                if (provider is IMetadataProvider metadataProvider &&
                    provider is IPropertyPage propertyPage)
                {
                    if (!metadataProvider.Supports(_metadataObject))
                        continue;

                    Control control = propertyPage.PropertyPage(_metadata);
                    if (control == null)
                        continue;

                    TabPage tab = new TabPage(metadataProvider.Name);
                    control.Dock = DockStyle.Fill;
                    tab.Controls.Add(control);
                    tabControl1.TabPages.Add(tab);
                }
            }
        }

        private void ReadMetadata()
        {
            _metadata = new Metadata();
            if (_xmlStream != null)
            {
                _metadata.ReadFrom(_xmlStream);
            }
        }

        private void WriteMetadata()
        {
            if (_xmlStream == null)
                return;

            foreach (TabPage tab in tabControl1.TabPages)
            {
                foreach (Control ctrl in tab.Controls)
                {
                    if (ctrl is IPropertyPage propertyPage &&
                        propertyPage is IMetadataProvider provider)
                    {
                        provider.WriteTo(_metadata);
                    }
                }
            }

            _metadata.WriteTo(_xmlStream);
        }

        private void btnOK_Click(object sender, System.EventArgs e)
        {
            WriteMetadata();
            DialogResult = DialogResult.OK;
        }

        private void btnCancel_Click(object sender, System.EventArgs e)
        {
            DialogResult = DialogResult.Cancel;
        }
    }

using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.Runtime.InteropServices;
 
namespace ArchimedeanSpiral
{
    class Writer
    {
        static void Main(string[] args)
        {
            int width = 600;
            int halfWidth = width / 2;
            Bitmap img = new Bitmap(width, width);
            Color drawColor = Color.FromArgb(255, 128, 128);
 
            // Constants defining the spiral size.
            double a = 1.0;
            double b = 9.0;
 
            // max_angle = number of spirals * 2pi.
            double maxAngle = 5.0 * 2.0 * Math.PI;
 
            double theta = 0.0;
            while (theta < maxAngle)
            {
                theta = theta + 0.002;
 
                double r = a + b * theta;
                int x = (int)(r * Math.Cos(theta)) + halfWidth;
                int y = (int)(r * Math.Sin(theta)) + halfWidth;
                img.SetPixel(x, y, drawColor);
            }
 
            // Save the image
            img.Save("archimedean_spiral.bmp", ImageFormat.Bmp);
        }
    }
}

