// ReSharper disable once CheckNamespace
public class PhotonHandler : MonoBehaviour, IPhotonPeerListener
{
    private static PhotonHandler _instance;

    public static bool AppQuits;
    public int nextSendTickCount;
    public int nextSendTickCountOnSerialize;
    public static Type PingImplementation;
    private static bool sendThreadShouldRun;
    public int updateInterval;
    public int updateIntervalOnSerialize;

    protected void Awake()
    {
        if (_instance != null && _instance != this)
            DestroyImmediate(_instance.gameObject);
        _instance = this;
        DontDestroyOnLoad(gameObject);
        this.updateInterval = 1000 / PhotonNetwork.sendRate;
        this.updateIntervalOnSerialize = 1000 / PhotonNetwork.sendRateOnSerialize;
        StartFallbackSendAckThread();
    }

    public void DebugReturn(DebugLevel level, string message)
    {
        switch (level)
        {
            case DebugLevel.ERROR:
                Shelter.Log(message, LogType.Error);
                break;
            case DebugLevel.WARNING:
                Shelter.Log(message, LogType.Warning);
                break;
            case DebugLevel.INFO when PhotonNetwork.LogLevel >= PhotonLogLevel.Informational:
            case DebugLevel.ALL when PhotonNetwork.LogLevel == PhotonLogLevel.Full:
                Shelter.Log(message);
                break;
        }
    }

    private static bool FallbackSendAckThread()
    {
        if (sendThreadShouldRun && PhotonNetwork.networkingPeer != null)
        {
            PhotonNetwork.networkingPeer.SendAcksOnly();
        }
        return sendThreadShouldRun;
    }

    protected void OnApplicationQuit()
    {
        AppQuits = true;
        StopFallbackSendAckThread();
        PhotonNetwork.Disconnect();
    }

    protected void OnCreatedRoom()
    {
        PhotonNetwork.networkingPeer.SetLevelInPropsIfSynced(Application.loadedLevelName);
    }

    public void OnEvent(EventData photonEvent)
    {
    }

    protected void OnJoinedRoom()
    {
        PhotonNetwork.networkingPeer.LoadLevelIfSynced();
    }

    protected void OnLevelWasLoaded(int level)
    {
        PhotonNetwork.networkingPeer.NewSceneLoaded();
        PhotonNetwork.networkingPeer.SetLevelInPropsIfSynced(Application.loadedLevelName);
    }

using System;
using System.IO;
using System.Xml.Serialization;
using System.Collections.Generic;

namespace NuGetPackageManager
{
    [XmlRoot("package", Namespace = "http://schemas.microsoft.com/packaging/2013/05/nuspec.xsd")]
    public class NuSpec : IEquatable<NuSpec>
    {
        [XmlElement("metadata")]
        public Metadata Metadata { get; set; }

        public NuSpec() { }

        public static NuSpec Load(string filePath)
        {
            using (var stream = File.OpenRead(filePath))
            {
                return Load(stream);
            }
        }

        public static NuSpec Load(Stream stream)
        {
            var serializer = new XmlSerializer(typeof(NuSpec));
            return (NuSpec)serializer.Deserialize(stream);
        }

        public override bool Equals(object obj)
        {
            return Equals(obj as NuSpec);
        }

        public bool Equals(NuSpec other)
        {
            if (other == null) return false;
            return string.Equals(Metadata.Id, other.Metadata.Id, StringComparison.OrdinalIgnoreCase) &&
                   string.Equals(Metadata.Version, other.Metadata.Version, StringComparison.OrdinalIgnoreCase);
        }

        public override int GetHashCode()
        {
            return HashCode.Combine(Metadata.Id?.ToLowerInvariant(), Metadata.Version?.ToLowerInvariant());
        }

        public static bool operator ==(NuSpec left, NuSpec right)
        {
            return EqualityComparer<NuSpec>.Default.Equals(left, right);
        }

        public static bool operator !=(NuSpec left, NuSpec right)
        {
            return !(left == right);
        }
    }

    [XmlRoot("metadata")]
    public class Metadata
    {
        [XmlElement("id")]
        public string Id { get; set; }

        [XmlElement("version")]
        public string Version { get; set; }

        [XmlElement("authors")]
        public string Authors { get; set; }

        [XmlElement("description")]
        public string Description { get; set; }

        [XmlElement("dependencies")]
        public List<Dependency> Dependencies { get; set; }

        public Metadata()
        {
            Dependencies = new List<Dependency>();
        }
    }

    public class Dependency
    {
        [XmlAttribute("id")]
        public string Id { get; set; }

        [XmlAttribute("version")]
        public string Version { get; set; }
    }
}

