public class CatalogItemManager
{
    private readonly CatalogServiceClient _catalogServiceClient;

    public CatalogItemManager(string projectId, string location)
    {
        _catalogServiceClient = CatalogServiceClient.Create();
    }

    public async Task DeleteCatalogItemAsync(string catalogItemId)
    {
        try
        {
            // Construct the fully qualified catalog item path
            CatalogItemPathName catalogItemPath = CatalogItemPathName.FromProjectLocationCatalogCatalogItem(
                projectId: "your-project-id",
                locationId: "global",
                catalogId: "default-catalog",
                catalogItemId: catalogItemId
            );

            // Create the deletion request
            DeleteCatalogItemRequest deletionRequest = new DeleteCatalogItemRequest
            {
                Name = catalogItemPath.ToString()
            };

            // Perform the asynchronous deletion
            var deletionOperation = await _catalogServiceClient.DeleteCatalogItemAsync(deletionRequest);
            await deletionOperation.PollUntilCompletedAsync();

            Console.WriteLine($"Catalog item {catalogItemId} deleted successfully.");
        }
        catch (RpcException ex)
        {
            Console.WriteLine($"Error deleting catalog item: {ex.Message}");
            throw;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Unexpected error: {ex.Message}");
            throw;
        }
    }
}

