using Microsoft.AspNet.Identity;
using System.Linq;

namespace Authentication.Controllers
{
    [AllowAnonymous]
    [RoutePrefix("api/account")]
    public class AccountController : ApiController, IDisposable
    {
        private readonly AuthRepository _repo;

        public AccountController()
        {
            _repo = new AuthRepository();
        }

        [HttpPost]
        [Route("register")]
        public async Task<IHttpActionResult> Register(UserRegistrationModel model)
        {
            if (!ModelState.IsValid)
            {
                return BadRequest(ModelState);
            }

            try
            {
                IdentityResult result = await _repo.RegisterUserAsync(new ApplicationUser
                {
                    UserName = model.Email,
                    Email = model.Email,
                    FirstName = model.FirstName,
                    LastName = model.LastName
                }, model.Password);

                if (!result.Succeeded)
                {
                    return GetErrorResult(result);
                }

                return Ok(new
                {
                    Message = "User registered successfully",
                    UserId = result.IdentityUser.Id
                });
            }
            catch (Exception ex)
            {
                return HandleRegistrationException(ex);
            }
        }

        private IHttpActionResult GetErrorResult(IdentityResult result)
        {
            if (result == null)
            {
                return InternalServerError();
            }

            if (!result.Succeeded)
            {
                if (result.Errors != null)
                {
                    foreach (string error in result.Errors)
                    {
                        ModelState.AddModelError("", error);
                    }
                }

                if (ModelState.IsValid)
                {
                    return BadRequest();
                }

                return BadRequest(ModelState);
            }

            return null;
        }

        private IHttpActionResult HandleRegistrationException(Exception ex)
        {
            // Log the exception details
            return InternalServerError(new Exception("Registration process failed", ex));
        }

        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }

        protected virtual void Dispose(bool disposing)
        {

using System;
using System.Linq;
 
namespace ProjectEuler
{
    public class Problem077
    {
        public static void Main()
        {
            var primes = Primes(10000).ToArray();
            var count = 0;
            for (var n = 1; n <= 10000; n++)
            {
                count += IsPrime(n, primes);
                if (n == 100 || n == 1000 || n == 10000)
                {
                    Console.WriteLine($"Primes up to {n}: {count}");
                }
            }
        }
 
        private static bool IsPrime(int n, int[] primes)
        {
            return Phi(n, primes) == n - 1;
        }
 
        private static int Phi(int n, int[] primes)
        {
            return Enumerable.Range(1, n).Count(k => Gcd(n, k) == 1);
        }
 
        private static int Gcd(int a, int b)
        {
            while (b!= 0)
            {
                var t = b;
                b = a % b;
                a = t;
            }
            return a;
        }
 
        private static IEnumerable<int> Primes(int n)
        {
            var sieve = new bool[n + 1];
            for (var i = 2; i <= n; i++)
            {
                if (!sieve[i])
                {
                    yield return i;
                    for (var j = i * i; j <= n; j += i)
                    {
                        sieve[j] = true;
                    }
                }
            }
        }
    }
}

