namespace AsyncLinqExtensions
{
    /// <summary>
    /// Provides extension methods for asynchronous evaluation of predicates in LINQ-like queries.
    /// </summary>
    public static class LinqAsync
    {
        /// <summary>
        /// Asynchronously filters a collection using an asynchronous predicate.
        /// Each element's predicate is evaluated concurrently.
        /// </summary>
        /// <typeparam name="T">Type of elements in the source collection.</typeparam>
        /// <param name="source">The collection to filter.</param>
        /// <param name="predicate">A function that asynchronously returns a boolean value for each element.</param>
        /// <returns>A task that represents the asynchronous filtering operation.
        /// The task result contains all elements matching the asynchronous predicate.</returns>
        public static async Task<IEnumerable<T>> WhereAsync<T>(this IEnumerable<T> source, Func<T, Task<bool>> predicate)
        {
            if (source == null) throw new ArgumentNullException(nameof(source));
            if (predicate == null) throw new ArgumentNullException(nameof(predicate));

            // Map each element to an object holding both the element and the asynchronous predicate task.
            var tasks = source.Select(item => new { Item = item, PredicateTask = predicate(item) }).ToList();

            // Await all predicate tasks concurrently.
            await Task.WhenAll(tasks.Select(pair => pair.PredicateTask));

            // Return elements whose predicate evaluated to true.
            return tasks.Where(pair => pair.PredicateTask.Result).Select(pair => pair.Item);
        }

        /// <summary>
        /// Asynchronously retrieves the first element of a collection that satisfies
        /// the provided asynchronous predicate, or a default value if none qualify.
        /// </summary>
        /// <typeparam name="T">Type of elements in the source collection.</typeparam>
        /// <param name="source">The collection to search.</param>
        /// <param name="predicate">A function that asynchronously evaluates an element.</param>
        /// <returns>
        /// A task that represents the asynchronous operation. Its result is the first element satisfying the predicate,
        /// or the default value for the type if no such element is found.
        /// </returns>
        public static async Task<T> FirstOrDefaultAsync<T>(this IEnumerable<T> source, Func<T, Task<bool>> predicate)

#include <random>
#include <iostream>
#include <stack>
#include <set>
#include <string>
#include <functional>
using namespace std;
 
class RPNParse
{
public:
  stack<double> stk;
  multiset<int> digits;
 
  void op(function<double(double,double)> f)
  {
    if(stk.size() < 2)
      throw "Improperly written expression";
    int b = stk.top(); stk.pop();
    int a = stk.top(); stk.pop();
    stk.push(f(a, b));
  }
 
  void parse(char c)
  {
    if(c >= '0' && c <= '9')
    {
      stk.push(c - '0');
      digits.insert(c - '0');
    }
    else if(c == '+')
      op([](double a, double b) {return a+b;});
    else if(c == '-')
      op([](double a, double b) {return a-b;});
    else if(c == '*')
      op([](double a, double b) {return a*b;});
    else if(c == '/')
      op([](double a, double b) {return a/b;});
  }
 
  void parse(string s)
  {
    for(int i = 0; i < s.size(); ++i)
      parse(s[i]);
  }
 
  double getResult()
  {
    if(stk.size() != 1)
      throw "Improperly written expression";
    return stk.top();
  }
};
 
int main()
{
  random_device seed;
  mt19937 engine(seed());
  uniform_int_distribution<> distribution(1, 9);
  auto rnd = bind(distribution, engine);
 
  multiset<int> digits;
  cout << "Make 24 with the digits: ";
  for(int i = 0; i < 4; ++i)
  {
    int n = rnd();
    cout << " " << n;
    digits.insert(n);
  }
  cout << endl;
 
  RPNParse parser;
 
  try
  {
    string input;
    getline(cin, input);
    parser.parse(input);
 
    if(digits != parser.digits)
      cout << "Error: Not using the given digits" << endl;
    else
    {
      double r = parser.getResult();
      cout << "Result: " << r << endl;
 
      if(r > 23.999 && r < 24.001)
        cout << "Good job!" << endl;
      else
        cout << "Try again." << endl;
    }
  }
  catch(char* e)
  {
    cout << "Error: " << e << endl;
  }
  return 0;
}

using System;
using System.Drawing;
public class Helper
{
    static PointF FindIntersection(PointF s1, PointF e1, PointF s2, PointF e2) {
        float a1 = e1.Y - s1.Y;
        float b1 = s1.X - e1.X;
        float c1 = a1 * s1.X + b1 * s1.Y;
 
        float a2 = e2.Y - s2.Y;
        float b2 = s2.X - e2.X;
        float c2 = a2 * s2.X + b2 * s2.Y;
 
        float delta = a1 * b2 - a2 * b1;
        //If lines are parallel, the result will be (NaN, NaN).
        return delta == 0 ? new PointF(float.NaN, float.NaN)
            : new PointF((b2 * c1 - b1 * c2) / delta, (a1 * c2 - a2 * c1) / delta);
    }
 
    static void Main() {
        Func<float, float, PointF> p = (x, y) => new PointF(x, y);
        Console.WriteLine(FindIntersection(p(4f, 0f), p(6f, 10f), p(0f, 3f), p(10f, 7f)));
        Console.WriteLine(FindIntersection(p(0f, 0f), p(1f, 1f), p(1f, 2f), p(4f, 5f)));
    }
}

