namespace DatabaseMaintenance
{
    public class ResetIndexesCommand { }

    public interface ICommandHandlerAsync<TCommand>
    {
        Task ExecuteAsync(TCommand command, CancellationToken cancellationToken);
    }

    public class ResetIndexesCommandHandler : ICommandHandlerAsync<ResetIndexesCommand>
    {
        private readonly IDocumentStore _documentStore;

        public ResetIndexesCommandHandler(IDocumentStore documentStore)
        {
            Guard.AgainstNullArgument(nameof(documentStore), documentStore);
            _documentStore = documentStore;
        }

        public async Task ExecuteAsync(ResetIndexesCommand command, CancellationToken cancellationToken)
        {
            Guard.AgainstNullArgument(nameof(command), command);

            using (var catalog = new AssemblyCatalog(Assembly.GetExecutingAssembly()))
            using (var container = new CompositionContainer(catalog))
            {
                var indexes = container.GetExportedValues<AbstractIndexCreationTask>();
                var exceptions = new List<Exception>();

                foreach (var index in indexes)
                {
                    try
                    {
                        var indexName = index.IndexName;
                        try
                        {
                            await _documentStore.Maintenance.Indexes.DeleteAsync(indexName, cancellationToken);
                        }
                        catch (IndexDoesNotExistException) { /* Ignore missing indexes */ }

                        await index.ExecuteAsync(_documentStore, cancellationToken: cancellationToken);
                    }
                    catch (Exception ex)
                    {
                        exceptions.Add(ex);
                    }
                }

                if (exceptions.Count > 0)
                {
                    throw new AggregateException(
                        "One or more index resets failed",
                        exceptions
                    );
                }
            }
        }
    }
}

// returns a new matrix
public Matrix mult(Matrix other)
{
    if (this.width!= other.height)
    {
        throw new Exception("error: incompatible sizes");
    }

    var result = new double[this.height][];
    for (var i = 0; i < this.height; i++)
    {
        result[i] = new double[other.width];
        for (var j = 0; j < other.width; j++)
        {
            var sum = 0.0;
            for (var k = 0; k < this.width; k++)
            {
                sum += this.mtx[i][k] * other.mtx[k][j];
            }
            result[i][j] = sum;
        }
    }
    return new Matrix(result);
}

