public class Commatize
{
    public static string commatize(int n)
    {
        return Regex.Replace(n.ToString(), @"(\d)(?=\d{3}+(?:\.|$))(\d{3}\..*)?", "$1,$2");
    }
}
 
public class Converter
{
    public static int isqrt(int x)
    {
        int q = 1, r = 0;
        while (q <= x) q <<= 2;
        while (q > 1)
        {
            q >>= 2;
            int t = x - r - q;
            r >>= 1;
            if (t >= 0) { x = t; r += q; }
        }
        return r;
    }
 
    public static void Main()
    {
        Console.WriteLine(string.Join(" ", Enumerable.Range(0, 66).Select(n => isqrt(n))));
 
        for (int n = 1; n <= 73; n += 2)
        {
            Console.WriteLine("{0}:\t{1}", n, Commatize.commatize(isqrt((int)Math.Pow(7, n))));
        }
    }
}

public static string repeat(string str, int times)
{
    StringBuilder sb = new StringBuilder(str.Length * times);
    for (int i = 0; i < times; i++)
        sb.Append(str);
    return sb.ToString();
}

public static void Main(string[] args)
{
    Console.WriteLine(repeat("ha", 5));
}

using System;
