using System.Windows.Controls;
using Microsoft.Phone.Controls;
using Bxf;

public class MainWindowPresenter
{
    public ObservableCollection<PivotItem> Panels { get; private set; }

    private readonly IShell _shell;
    private readonly IViewModel _viewModel;

    public MainWindowPresenter(IShell shell, IViewModel viewModel)
    {
        _shell = shell;
        _viewModel = viewModel;
        Panels = new ObservableCollection<PivotItem>();
        InitializePrimaryView();
        SubscribeToEvents();
    }

    private void InitializePrimaryView()
    {
        try
        {
            ShowView(_viewModel.DefaultViewModel);
        }
        catch (Exception ex)
        {
            ShowError("Failed to initialize primary view: " + ex.Message);
        }
    }

    private void SubscribeToEvents()
    {
        _viewModel.ErrorOccurred += OnErrorOccurred;
        _viewModel.StatusUpdated += OnStatusUpdated;
        _viewModel.ViewChanged += OnViewChanged;
    }

    private void OnErrorOccurred(object sender, string message)
    {
        ShowError(message);
    }

    private void OnStatusUpdated(object sender, string status)
    {
        ShowStatus(status);
    }

    private void OnViewChanged(object sender, ViewModelChangedEventArgs e)
    {
        ShowView(e.NewViewModel);
    }

    public void ShowError(string message)
    {
        MessageBox.Show(message, "Error", MessageBoxButton.OK);
    }

    public void ShowStatus(string status)
    {
        // Assuming there's a UI element to show status
        _shell.StatusTextBlock.Text = status;
    }

    public void ShowView(IViewModel viewModel)
    {
        var pivotItem = CreateOrRetrievePanel(viewModel);
        UpdateUI(viewModel, pivotItem);
    }

    private PivotItem CreateOrRetrievePanel(IViewModel viewModel)
    {
        var existingPanel = Panels.FirstOrDefault(p => p.ViewModel == viewModel);
        if (existingPanel != null)
        {
            return existingPanel;
        }

        var newPanel = new PivotItem
        {
            Header = viewModel.Header,
            ViewModel = viewModel
        };

        Panels.Add(newPanel);
        return newPanel;
    }

    private void UpdateUI(IViewModel viewModel, PivotItem panel)
    {
        panel.Content = viewModel.Content;
        panel.Header = viewModel.Header;
        // Additional UI updates can be managed here
    }
}

