            var context = new Context(ambientServices);
            var builder = Injection.Injection.CreateInjectorBuilder(context);

            config?.Invoke(builder);

            return builder.Build();
        }

        protected virtual IEnumerable<Assembly> GetDefaultConventionAssemblies(IEnumerable<Assembly> assemblies)
        {
            yield return typeof(IAmbientServices).Assembly;
            foreach (var assembly in assemblies)
            {
                yield return assembly;
            }
