using System;
using System.IO;
using System.Text;
using System.Globalization;
 
class Logger
{
    static void Main(string[] args)
    {
        const string fn = "NOTES.TXT";
        Exception err = null;
        if (args.Length > 0)
        {
            err = addNote(fn, string.Join(" ", args));
        }
        else
        {
            err = showNotes(fn);
        }
        if (err!= null)
        {
            Console.Error.WriteLine(err);
            Environment.Exit(1);
        }
    }
 
static Exception addNote(string fn, string note)
{
    FileStream f = null;
    try
    {
        f = new FileStream(fn, FileMode.Append, FileAccess.Write, FileShare.Read);
        byte[] data = Encoding.UTF8.GetBytes(DateTime.Now.ToString(CultureInfo.InvariantCulture) + "\n\t" + note + "\n");
        f.Write(data, 0, data.Length);
    }
    catch (Exception e)
    {
        return e;
    }
    finally
    {
        if (f!= null)
        {
            f.Close();
        }
    }
    return null;
}
 
static Exception showNotes(string fn)
{
    FileStream f = null;
    try
    {
        f = new FileStream(fn, FileMode.Open, FileAccess.Read, FileShare.Read);
        byte[] data = new byte[f.Length];
        f.Read(data, 0, data.Length);
        Console.Write(Encoding.UTF8.GetString(data));
    }
    catch (FileNotFoundException)
    {
        return null; // don't report "no such file"
    }
    catch (Exception e)
    {
        return e;
    }
    finally
    {
        if (f!= null)
        {
            f.Close();
        }
    }
    return null;
}
}

