using System;
using System.Data;
using System.Data.SQLite;
using System.Data.Common;
using System.IO;

namespace GatherAll.Database
{
    public class Cls_SqliteMng
    {
        private string _connectionString;
        private string _databasePath;

        public Cls_SqliteMng(string databasePath)
        {
            _databasePath = databasePath;
            _connectionString = $"Data Source={_databasePath};Version=3;";
        }

        public bool CreateDB()
        {
            try
            {
                if (!File.Exists(_databasePath))
                {
                    SQLiteConnection.CreateFile(_databasePath);
                    return true;
                }
                return false;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Database creation error: {ex.Message}");
                return false;
            }
        }

        public bool ExecuteSql(string sqlCommand)
        {
            try
            {
                using (SQLiteConnection connection = new SQLiteConnection(_connectionString))
                {
                    connection.Open();

                    using (SQLiteCommand command = new SQLiteCommand(sqlCommand, connection))
                    {
                        command.ExecuteNonQuery();
                    }
                }
                return true;
            }
            catch (SQLiteException ex)
            {
                Console.WriteLine($"SQL Execution Error: {ex.Message}");
                return false;
            }
        }

        public DataTable ExecuteQuery(string sqlQuery)
        {
            DataTable dataTable = new DataTable();

            try
            {
                using (SQLiteConnection connection = new SQLiteConnection(_connectionString))
                {
                    connection.Open();

                    using (SQLiteCommand command = new SQLiteCommand(sqlQuery, connection))
                    {
                        using (SQLiteDataAdapter adapter = new SQLiteDataAdapter(command))
                        {
                            adapter.Fill(dataTable);
                        }
                    }
                }
            }
            catch (SQLiteException ex)
            {
                Console.WriteLine($"Query Execution Error: {ex.Message}");
            }

            return dataTable;
        }
    }
}

