using System;
 
namespace ShortestCommonSuperSequence
{
    class Converter
    {
        private static bool isEmpty(string s)
        {
            return null == s || s.Length == 0;
        }
 
        private static string scs(string x, string y)
        {
            if (isEmpty(x))
            {
                return y;
            }
            if (isEmpty(y))
            {
                return x;
            }
 
            if (x[0] == y[0])
            {
                return x[0] + scs(x.Substring(1), y.Substring(1));
            }
 
            if (scs(x, y.Substring(1)).Length <= scs(x.Substring(1), y).Length)
            {
                return y[0] + scs(x, y.Substring(1));
            }
            else
            {
                return x[0] + scs(x.Substring(1), y);
            }
        }
 
        static void Main(string[] args)
        {
            Console.WriteLine(scs("abcbdab", "bdcaba"));
        }
    }
}

