using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace Matrix
{
    class Game
    {
        static void Main(string[] args)
        {
            bool is_prime(uint n)
            {
                if (n < 2)
                    return false;
                if (n % 2 == 0)
                    return n == 2;
                if (n % 3 == 0)
                    return n == 3;
                for (uint p = 5; p * p <= n; p += 4)
                {
                    if (n % p == 0)
                        return false;
                    p += 2;
                    if (n % p == 0)
                        return false;
                }
                return true;
            }

            bool is_magnanimous(uint n)
            {
                for (uint p = 10; n >= p; p *= 10)
                {
                    if (!is_prime(n % p + n / p))
                        return false;
                }
                return true;
            }

            uint count = 0, n = 0;
            Console.WriteLine("First 45 magnanimous numbers:\n");
            for (; count < 45; ++n)
            {
                if (is_magnanimous(n))
                {
                    if (count > 0)
                        Console.Write((count % 15 == 0? "\n" : ", "));
                    Console.Write("{0,3}", n);
                    ++count;
                }
            }
            Console.WriteLine("\n\n241st through 250th magnanimous numbers:\n");
            for (uint i = 0; count < 250; ++n)
            {
                if (is_magnanimous(n))
                {
                    if (count++ >= 240)
                    {
                        if (i++ > 0)
                            Console.Write(", ");
                        Console.Write(n);
                    }
                }
            }
            Console.WriteLine("\n\n391st through 400th magnanimous numbers:\n");
            for (uint i = 0; count < 400; ++n)
            {
                if (is_magnanimous(n))
                {
                    if (count++ >= 390)
                    {
                        if (i++ > 0)
                            Console.Write(", ");
                        Console.Write(n);
                    }
                }
            }
            Console.WriteLine();
        }
    }
}

