public class Student
{
    public static void Main()
    {
        Main1();
    }

    // main :: IO ()
    public static void Main1()
    {
        var main = () =>
            Take(25, Weirds());

        // weirds :: Gen [Int]
        IEnumerable<int> Weirds()
        {
            var x = 1;
            var i = 1;
            while (true)
            {
                x = Until(IsWeird, Succ, x);
                WriteLine($"{i} -> {x}");
                yield return x;
                x = 1 + x;
                i = 1 + i;
            }
        }

        // isWeird :: Int -> Bool
        bool IsWeird(int n)
        {
            var ds = DescProperDivisors(n);
            var d = Sum(ds) - n;
            return 0 < d &&!HasSum(d, ds);
        }

        // hasSum :: Int -> [Int] -> Bool
        bool HasSum(int n, IEnumerable<int> xs)
        {
            bool Go(int n, IEnumerable<int> xs) =>
                0 < xs.Count()? (
                    xs.First() > n? (
                        Go(n, xs.Skip(1))
                    ) : (
                        n == xs.First() || HasSum(n - xs.First(), xs.Skip(1)) || HasSum(n, xs.Skip(1))
                    )
                ) : false;
            return Go(n, xs);
        }

        // descProperDivisors :: Int -> [Int]
        IEnumerable<int> DescProperDivisors(int n)
        {
            var rRoot = Sqrt(n);
            var intRoot = Floor(rRoot);
            var blnPerfect = rRoot == intRoot;
            var lows = EnumFromThenTo(intRoot, intRoot - 1, 1)
               .Where(x => (n % x) == 0);
            return (
                Reverse(lows)
               .Skip(1)
               .Select(x => n / x)
            ).Concat(blnPerfect? Tail(lows) : lows);
        }

        // GENERIC FUNCTIONS ----------------------------

        // enumFromThenTo :: Int -> Int -> Int -> [Int]
        IEnumerable<int> EnumFromThenTo(int x1, int x2, int y)
        {
            var d = x2 - x1;
            return Enumerable.Range(0, Floor(y - x2) / d + 2)
               .Select(i => x1 + (d * i));
        }

        // reverse :: [a] -> [a]
        IEnumerable<T> Reverse<T>(IEnumerable<T> xs) =>
            xs.Reverse();

        // succ :: Enum a => a -> a
        int Succ(int x) => 1 + x;

        // sum :: [Num] -> Num
        int Sum(IEnumerable<int> xs) =>
            xs.Sum();

        // tail :: [a] -> [a]
        IEnumerable<T> Tail<T>(IEnumerable<T> xs) =>

