using UnityEngine;
using System.Collections;

public class MaterialSetMainColor : MonoBehaviour
{
    public MaterialVar materialVar;
    public ColorVar colorVar;

    private Material materialToChange;
    private Color newColor;

    public enum Status
    {
        Success,
        Fail,
        Error
    }

    private void Reset()
    {
        materialToChange = null;
        newColor = Color.white;
    }

    private void Update()
    {
        if (materialVar != null && colorVar != null)
        {
            materialToChange = materialVar.GetMaterial();
            newColor = colorVar.GetColor();

            if (materialToChange == null)
            {
                Renderer renderer = GetComponent<Renderer>();
                if (renderer != null)
                {
                    materialToChange = renderer.material;
                }
            }

            if (materialToChange != null)
            {
                try
                {
                    materialToChange.color = newColor;
                    Debug.Log("Color successfully changed.");
                    return Status.Success;
                }
                catch (System.Exception ex)
                {
                    Debug.LogError("Error changing material color: " + ex.Message);
                    return Status.Error;
                }
            }
            else
            {
                Debug.LogError("Material is null, operation failed.");
                return Status.Fail;
            }
        }
        else
        {
            Debug.LogError("Material or Color is not set, operation failed.");
            return Status.Fail;
        }
    }
}

