        private ObservableCollection<Tour> icTours = new ObservableCollection<Tour>();
        private ItemsControl ucTours;

        public GrilleUC()
        {
            InitializeComponent();
            ucTours = FindName("PART_ItemsControl") as ItemsControl;
            ucTours.ItemsSource = icTours;
        }

        private void GenererTour(object sender, RoutedEventArgs e)
        {
            MainWindow mainWindow = Application.Current.MainWindow as MainWindow;
            if (mainWindow?.TournoiEnCours == null) return;

            // Generate new tournament round
            mainWindow.TournoiEnCours.GenererNouveauTour();
            icTours.Add(mainWindow.TournoiEnCours.DernierTour);

            // Update UI layout
            UpdateLayout();
            ucTours.UpdateLayout();

            // Collapse previous expanders
            int lastIndex = icTours.Count - 1;
            for (int i = 0; i < icTours.Count; i++)
            {
                ContentPresenter container = ucTours.ItemContainerGenerator.ContainerFromIndex(i) as ContentPresenter;
                if (container == null) continue;

                Expander expander = FindVisualChild<Expander>(container);
                if (expander != null)
                {
                    expander.IsExpanded = (i == lastIndex);
                    if (i < lastIndex) expander.Tag = "CollapsedBySystem";
                }
            }
        }

        private static T FindVisualChild<T>(DependencyObject parent) where T : DependencyObject
        {
            if (parent == null) return null;

            for (int i = 0; i < VisualTreeHelper.GetChildrenCount(parent); i++)
            {
                DependencyObject child = VisualTreeHelper.GetChild(parent, i);
                if (child is T result)
                {
                    return result;
                }
                else
                {
                    T childResult = FindVisualChild<T>(child);
                    if (childResult != null) return childResult;
                }
            }
            return null;
        }
    }

