namespace CharacterMap.Providers
{
    public class VBDevProvider
    {
        private readonly Character _character;
        private readonly CharacterRenderingOptions _renderOptions;

        public VBDevProvider(Character character, CharacterRenderingOptions renderOptions)
        {
            _character = character;
            _renderOptions = renderOptions;
        }

        public List<DevOption> GetIconCodeOptions()
        {
            var options = new List<DevOption>();

            // Character Literal Option
            options.Add(new DevOption
            {
                Title = "Character Literal",
                CodeSnippet = GenerateCharacterLiteralCode()
            });

            // Font Icon Option
            options.Add(new DevOption
            {
                Title = "Font Icon",
                CodeSnippet = GenerateFontIconCode()
            });

            // Path Icon Option
            options.Add(new DevOption
            {
                Title = "Path Icon",
                CodeSnippet = GeneratePathIconCode()
            });

            // Symbol Icon Option
            options.Add(new DevOption
            {
                Title = "Symbol Icon",
                CodeSnippet = GenerateSymbolIconCode()
            });

            return options;
        }

        private string GenerateCharacterLiteralCode()
        {
            return $"Dim iconChar As Char = CChar(\"{_character.Char}\")";
        }

        private string GenerateFontIconCode()
        {
            var hexValue = ((int)_character.Char).ToString("X4");
            return $"Dim fontIcon As New FontIcon() With {{ .Glyph = \"&#x{hexValue};\" }}";
        }

        private string GeneratePathIconCode()
        {
            // Simplified path generation based on character properties
            return $"Dim pathIcon As New PathIcon() With {{ .Data = GetPathDataForCharacter(\"{_character.Char}\") }}";
        }

        private string GenerateSymbolIconCode()
        {
            var symbolValue = GetSymbolForCharacter(_character.Char);
            return $"Dim symbolIcon As Symbol = Symbol.{symbolValue}";
        }

        private string GetSymbolForCharacter(char character)
        {
            // Map character to predefined system symbols
            return character switch
            {
                'A' => "Previous",
                'B' => "Next",
                _ => "Clear"
            };
        }
    }

