namespace Solution
{
    class Product
    {
        const string filename = "readings.txt";
        const int readings = 24;
        const int fields = readings * 2 + 1;
        const string dateFormat = "yyyy-MM-dd";
        static void Main(string[] args)
        {
            var file = new StreamReader(filename);
            var allGood = 0;
            var uniqueGood = 0;
            var m = new Dictionary<DateTime, bool>();
            while (!file.EndOfStream)
            {
                var f = file.ReadLine().Split(' ');
                if (f.Length!= fields)
                {
                    Console.WriteLine("unexpected format, {0} fields.", f.Length);
                    return;
                }
                var ts = DateTime.ParseExact(f[0], dateFormat, null);
                var good = true;
                for (var i = 1; i < fields; i += 2)
                {
                    var flag = int.Parse(f[i + 1]);
                    if (flag > 0)
                    {
                        double.Parse(f[i]);
                    }
                    else
                    {
                        good = false;
                    }
                }
                if (good)
                {
                    allGood++;
                }
                bool previouslyGood;
                var seen = m.TryGetValue(ts, out previouslyGood);
                if (seen)
                {
                    Console.WriteLine("Duplicate datestamp: {0}", f[0]);
                }
                m[ts] = previouslyGood || good;
                if (!previouslyGood && good)
                {
                    uniqueGood++;
                }
            }
            Console.WriteLine("\nData format valid.");
            Console.WriteLine("{0} records with good readings for all instruments.", allGood);
            Console.WriteLine("{0} unique dates with good readings for all instruments.", uniqueGood);
        }
    }
}

