using System;
using Org.BouncyCastle.Asn1;
using Org.BouncyCastle.Asn1.Cms;

public class EnvelopedDataParser
{
    private readonly Asn1SequenceParser _seq;
    private readonly DerInteger _version;
    private object _nextObject;

    public EnvelopedDataParser(Asn1SequenceParser seq)
    {
        if (seq == null)
            throw new ArgumentNullException(nameof(seq));

        _seq = seq;
        _version = (DerInteger)seq.ReadObject();
        _nextObject = seq.ReadObject();
    }

    public DerInteger Version
    {
        get { return _version; }
    }

    public Asn1SetParser GetCertificates()
    {
        Asn1SetParser certSet = null;

        if (_nextObject is Asn1TaggedObject taggedCert)
        {
            if (taggedCert.TagNo == 0)
            {
                certSet = (Asn1SetParser)taggedCert.GetObjectParser(Asn1Tags.Set, false);
                _nextObject = _seq.ReadObject();
            }
        }

        return certSet;
    }

    public Asn1SetParser GetCrls()
    {
        Asn1SetParser crlSet = null;

        if (_nextObject is Asn1TaggedObject taggedCrl)
        {
            if (taggedCrl.TagNo == 1)
            {
                crlSet = (Asn1SetParser)taggedCrl.GetObjectParser(Asn1Tags.Set, false);
                _nextObject = _seq.ReadObject();
            }
        }

        return crlSet;
    }

    public Asn1SetParser GetRecipientInfos()
    {
        if (!(_nextObject is Asn1SetParser recipientInfos))
            throw new InvalidOperationException("Expected RecipientInfos");

        _nextObject = _seq.ReadObject();
        return recipientInfos;
    }

    public EncryptedContentInfoParser GetEncryptedContentInfo()
    {
        if (!(_nextObject is Asn1SequenceParser encryptedContentInfo))
            throw new InvalidOperationException("Expected EncryptedContentInfo");

        var parser = new EncryptedContentInfoParser(encryptedContentInfo);
        _nextObject = _seq.ReadObject();
        return parser;
    }

    public Asn1SetParser GetUnprotectedAttrs()
    {
        Asn1SetParser attrSet = null;

        if (_nextObject is Asn1TaggedObject taggedAttr)
        {
            if (taggedAttr.TagNo == 1)
            {
                attrSet = (Asn1SetParser)taggedAttr.GetObjectParser(Asn1Tags.Set, false);
                _nextObject = _seq.ReadObject();
            }
        }

        return attrSet;
    }
}

