    /// <summary>
    /// Provides extension methods for module management in the YAF modular system.
    /// </summary>
    public static class IModuleManagerExtensions
    {
        /// <summary>
        /// Retrieves all active modules of a specified type with optional filtering.
        /// </summary>
        /// <typeparam name="TModule">The type of module to retrieve.</typeparam>
        /// <param name="moduleManager">The module manager instance.</param>
        /// <param name="predicate">Optional filter predicate to further refine module selection.</param>
        /// <returns>A collection of active modules matching the specified type and optional filter.</returns>
        /// <exception cref="ArgumentNullException">Thrown when the module manager is null.</exception>
        public static IEnumerable<TModule> GetAll<TModule>(
            this IModuleManager<TModule> moduleManager,
            Func<TModule, bool> predicate = null)
            where TModule : class
        {
            // Validate input module manager
            CodeContracts.ArgumentNotNull(moduleManager, nameof(moduleManager));

            // Retrieve all modules of the specified type
            var modules = moduleManager.GetModules();

            // Validate modules collection
            if (modules == null)
            {
                return Enumerable.Empty<TModule>();
            }

            // Apply optional filtering if predicate is provided
            var filteredModules = predicate != null
                ? modules.Where(predicate)
                : modules;

            // Return filtered or unfiltered modules
            return filteredModules ?? Enumerable.Empty<TModule>();
        }

