using Microsoft.AspNetCore.Authentication;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using System.Security.Claims;
using System.Text.Encodings.Web;
using System.Threading.Tasks;

namespace AuthFramework
{
    public abstract class SignInAuthenticationHandler<TOptions> : SignOutAuthenticationHandler<TOptions>, IAuthenticationSignInHandler
        where TOptions : AuthenticationSchemeOptions, new()
    {
        protected SignInAuthenticationHandler(IOptionsMonitor<TOptions> options, ILoggerFactory logger, UrlEncoder encoder, ISystemClock clock)
            : base(options, logger, encoder, clock)
        {
        }

        public async Task SignInAsync(ClaimsPrincipal user, AuthenticationProperties? properties)
        {
            properties ??= new AuthenticationProperties();

            var target = ResolveTarget(Options.ForwardSignIn);
            if (target != null)
            {
                await Context.SignInAsync(target, user, properties);
                return;
            }

            await HandleSignInAsync(user, properties);
        }

        protected abstract Task HandleSignInAsync(ClaimsPrincipal user, AuthenticationProperties properties);

        protected virtual string? ResolveTarget(string? scheme)
        {
            return scheme;
        }
    }
}

using UnityEngine;
using GoogleARCore;
using System;

public interface ILifecycleManager
{
    bool InitializeSession();
    TrackingState UpdateSession();
    IntPtr SessionHandle { get; }
    IntPtr FrameHandle { get; }
}

public class LifecycleManager
{
    public struct FrameUpdate
    {
        public TrackingState TrackingState;
        public IntPtr SessionHandle;
        public IntPtr FrameHandle;
    }

    public static event Action EarlyUpdate;
    public static event Action<FrameUpdate> FrameUpdated;

    private static LifecycleManager s_Instance;
    private ILifecycleManager platformManager;

    public static LifecycleManager Instance
    {
        get
        {
            if (s_Instance == null)
                s_Instance = new LifecycleManager();
            return s_Instance;
        }
    }

    private LifecycleManager()
    {
#if UNITY_ANDROID
        platformManager = new ARCoreAndroidLifecycleManager();
#elif UNITY_IOS
        platformManager = new ARCoreIOSLifecycleManager();
#else
        throw new PlatformNotSupportedException();
#endif
        platformManager.InitializeSession();
    }

    public void Update()
    {
        EarlyUpdate?.Invoke();
        var trackingState = platformManager.UpdateSession();

        FrameUpdated?.Invoke(new FrameUpdate
        {
            TrackingState = trackingState,
            SessionHandle = platformManager.SessionHandle,
            FrameHandle = platformManager.FrameHandle
        });
    }
}

public class ARCoreAndroidLifecycleManager : ILifecycleManager
{
    private IntPtr sessionHandle;
    private IntPtr frameHandle;

    public bool InitializeSession() => Session.Status == SessionStatus.Tracking;

    public TrackingState UpdateSession()
    {
        frameHandle = FrameApi.AcquireFrame();
        return Session.Status == SessionStatus.Tracking ?
            TrackingState.Tracking : TrackingState.Lost;
    }

    public IntPtr SessionHandle => sessionHandle;
    public IntPtr FrameHandle => frameHandle;
}

public class ARCoreIOSLifecycleManager : ILifecycleManager
{
    private IntPtr sessionHandle;
    private IntPtr frameHandle;

    public bool InitializeSession() => Session.Status == SessionStatus.Tracking;

    public TrackingState UpdateSession()
    {
        frameHandle = FrameApi.AcquireFrame();
        return Session.Status == SessionStatus.Tracking ?
            TrackingState.Tracking : TrackingState.Paused;
    }

    public IntPtr SessionHandle => sessionHandle;
    public IntPtr FrameHandle => frameHandle;
}

