using System;
using System.Collections.Generic;
using System.Linq;

public class StaticUnitLoader
{
    private DataStore _dataStore;
    private Dictionary<string, UnitNode> _synonymMap;
    private List<CustomUnitNode> _customUnitNodes;

    public StaticUnitLoader(DataStore dataStore)
    {
        _dataStore = dataStore;
        _synonymMap = new Dictionary<string, UnitNode>();
        _customUnitNodes = new List<CustomUnitNode>();
    }

    public void LoadSynonyms()
    {
        var rawSynonyms = _dataStore.RetrieveSynonyms();
        foreach (var synonym in rawSynonyms.Distinct())
        {
            ProcessSynonym(synonym);
        }
    }

    private void ProcessSynonym(string synonym)
    {
        var normalizedName = NormalizeSynonym(synonym);
        if (!_synonymMap.ContainsKey(normalizedName))
        {
            var unitNode = new UnitNode(normalizedName);
            _synonymMap[normalizedName] = unitNode;
        }
    }

    public void LoadFormPairings()
    {
        var ingredientForms = _dataStore.RetrieveIngredientForms();
        foreach (var form in ingredientForms)
        {
            CreateIngredientFormPairing(form);
        }
    }

    private void CreateIngredientFormPairing(IngredientForm form)
    {
        var pairing = new NameIngredientPair
        {
            UnitName = form.UnitName,
            IngredientId = form.IngredientId,
            FormDetails = form.Details
        };

        _customUnitNodes.Add(new CustomUnitNode(pairing));
    }

    private string NormalizeSynonym(string synonym)
    {
        return synonym.Trim().ToLowerInvariant();
    }
}

