using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

class WordFrequencyAnalyzer
{
    private string inputTextPath;
    private string inputWordsPath;
    private string outputResultPath;
    private Dictionary<string, int> wordFrequency;

    public WordFrequencyAnalyzer(string textPath, string wordsPath, string resultPath)
    {
        inputTextPath = textPath;
        inputWordsPath = wordsPath;
        outputResultPath = resultPath;
        wordFrequency = new Dictionary<string, int>();
    }

    private string[] ReadFromFile(string filePath)
    {
        try
        {
            return File.ReadAllLines(filePath);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error reading file: {ex.Message}");
            return new string[0];
        }
    }

    private void CountWordsOccurrence(string[] text, string[] words)
    {
        foreach (string word in words)
        {
            int count = text.Count(line => line.Split().Contains(word));
            if (count > 0)
            {
                wordFrequency[word] = count;
            }
        }
    }

    private void SaveResult()
    {
        try
        {
            var sortedResults = wordFrequency
                .OrderByDescending(x => x.Value)
                .Select(x => $"{x.Key}: {x.Value}");

            File.WriteAllLines(outputResultPath, sortedResults);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error saving results: {ex.Message}");
        }
    }

    public void AnalyzeWordFrequency()
    {
        string[] text = ReadFromFile(inputTextPath);
        string[] words = ReadFromFile(inputWordsPath);

        if (text.Length > 0 && words.Length > 0)
        {
            CountWordsOccurrence(text, words);
            SaveResult();
            Console.WriteLine("Word frequency analysis completed successfully.");
        }
        else
        {
            Console.WriteLine("Unable to process empty files.");
        }
    }

    static void Main(string[] args)
    {
        string textFilePath = @"C:\data\text.txt";
        string wordsFilePath = @"C:\data\words.txt";
        string resultFilePath = @"C:\data\results.txt";

        WordFrequencyAnalyzer analyzer = new WordFrequencyAnalyzer(
            textFilePath, wordsFilePath, resultFilePath);

        analyzer.AnalyzeWordFrequency();
    }
}

