using System;
using System.Collections;
using NUnit.Framework;

public class YourType
{
    public string Name { get; set; }
}

public class YourTypeCollection<TType> : CollectionBase
{
    public void Add(YourType item) => InnerList.Add(item);

    public bool Contains(YourType item) => InnerList.Contains(item);

    public int IndexOf(YourType item) => InnerList.IndexOf(item);

    public void Insert(int index, YourType item) => InnerList.Insert(index, item);

    public void Remove(YourType item) => InnerList.Remove(item);

    public void CopyTo(YourType[] array, int index) => InnerList.CopyTo(array, index);

    public YourType this[int index]
    {
        get => (YourType)InnerList[index];
        set => InnerList[index] = value;
    }

    int IList.Add(object value)
    {
        if (value is YourType item) return Add(item);
        throw new ArgumentException("Value must be YourType");
    }

    bool IList.Contains(object value) => value is YourType item && Contains(item);

    int IList.IndexOf(object value) => value is YourType item ? IndexOf(item) : -1;

    void IList.Insert(int index, object value)
    {
        if (value is YourType item) Insert(index, item);
        else throw new ArgumentException("Value must be YourType");
    }

    void IList.Remove(object value)
    {
        if (value is YourType item) Remove(item);
    }

    object IList.this[int index]
    {
        get => this[index];
        set
        {
            if (value is YourType item) this[index] = item;
            else throw new ArgumentException("Value must be YourType");
        }
    }
}

