public class TestCollection
{
    [Test]
    public void CollectionTests_TestedBehavior_ExpectedResult()
    {
        var yourTypeCollection = new YourTypeCollection<YourType>();
        yourTypeCollection.Add(new YourType { Name = "TestItem" });

        for (int i = 0; i < yourTypeCollection.Capacity; i++)
        {
            var item = yourTypeCollection[i];
            Assert.That(item.Name, Is.EqualTo("TestItem"));
        }
    }
}

using System;
using System.Collections.Generic;

public interface IClearData
{
    string CharacterName { get; }
    Dictionary<int, Dictionary<int, int>> Scores { get; }
}

public class CharaWithTotal : IClearData
{
    public string CharacterName { get; private set; }
    public Dictionary<int, Dictionary<int, int>> Scores { get; private set; }

    public CharaWithTotal(string characterName)
    {
        CharacterName = characterName;
        Scores = new Dictionary<int, Dictionary<int, int>>();
    }

    public void AddScore(int level, int rank, int score)
    {
        if (!Scores.ContainsKey(level))
        {
            Scores[level] = new Dictionary<int, int>();
        }
        Scores[level][rank] = score;
    }
}

public class ScoreReplacer
{
    private readonly Dictionary<string, IClearData> _characterScores;

    public ScoreReplacer(Dictionary<string, IClearData> characterScores)
    {
        _characterScores = characterScores;
    }

    public int GetScore(string characterName, int level, int rank)
    {
        if (_characterScores.TryGetValue(characterName, out var clearData))
        {
            if (clearData.Scores.TryGetValue(level, out var rankData) && rankData.TryGetValue(rank, out var score))
            {
                return score;
            }
        }
        return GetDefaultScore();
    }

    private int GetDefaultScore()
    {
        return -1; // Assuming -1 is the default score indicating not found.
    }
}

class Counter
{
    static void Main()
    {
        var characterScores = new Dictionary<string, IClearData>
        {
            { "Hero", new CharaWithTotal("Hero") },
            { "Villain", new CharaWithTotal("Villain") }
        };

        characterScores["Hero"].AddScore(1, 1, 100);
        characterScores["Hero"].AddScore(1, 2, 150);
        characterScores["Villain"].AddScore(1, 1, 200);

        var scoreReplacer = new ScoreReplacer(characterScores);

        Console.WriteLine($"Hero Level 1 Rank 1 Score: {scoreReplacer.GetScore("Hero", 1, 1)}");
        Console.WriteLine($"Hero Level 1 Rank 3 Score: {scoreReplacer.GetScore("Hero", 1, 3)}");
        Console.WriteLine($"Villain Level 1 Rank 1 Score: {scoreReplacer.GetScore("Villain", 1, 1)}");
        Console.WriteLine($"Unknown Character Level 1 Rank 1 Score: {scoreReplacer.GetScore("Unknown", 1, 1)}");
    }
}

