namespace Library
{
    class Parser
    {
        static void Main(string[] args)
        {
            var test_cases = new List<List<Tuple<double, double>>>()
            {
                new List<Tuple<double, double>>() { new Tuple<double, double>(1.1, 2.2) },
                new List<Tuple<double, double>>() { new Tuple<double, double>(6.1, 7.2), new Tuple<double, double>(7.2, 8.3) },
                new List<Tuple<double, double>>() { new Tuple<double, double>(4, 3), new Tuple<double, double>(2, 1) },
                new List<Tuple<double, double>>() { new Tuple<double, double>(4, 3), new Tuple<double, double>(2, 1), new Tuple<double, double>(-1, -2), new Tuple<double, double>(3.9, 10) },
                new List<Tuple<double, double>>() { new Tuple<double, double>(1, 3), new Tuple<double, double>(-6, -1), new Tuple<double, double>(-4, -5), new Tuple<double, double>(8, 2), new Tuple<double, double>(-6, -6) }
            };
            foreach (var ranges in test_cases)
            {
                print_ranges(ranges);
                Console.Write(" -> ");
                var i = consolidate_ranges(ranges);
                print_ranges(ranges);
                Console.WriteLine();
            }
            Console.ReadKey();
        }
        static void normalize_ranges(List<Tuple<double, double>> ranges)
        {
            for (int i = 0; i < ranges.Count; i++)
            {
                if (ranges[i].Item2 < ranges[i].Item1)
                {
                    var temp = ranges[i].Item1;
                    ranges[i] = new Tuple<double, double>(ranges[i].Item2, temp);
                }
            }
            ranges.Sort((x, y) => x.Item1.CompareTo(y.Item1));
        }
        static int merge_ranges(List<Tuple<double, double>> ranges)
        {
            int out_index = 0;
            for (int i = 0; i < ranges.Count; i++)
            {
                int j = i;
                while (++j < ranges.Count && ranges[j].Item1 <= ranges[i].Item2)
                {
                    ranges[i] = new Tuple<double, double>(ranges[i].Item1, Math.Max(ranges[i].Item2, ranges[j].Item2));
                }
                ranges[out_index++] = ranges[i];
                i = j;
            }
            return out_index;
        }
        static int consolidate_ranges(List<Tuple<double, double>> ranges)
        {
            normalize_ranges(ranges);
            return merge_ranges(ranges);
        }

