        /// </summary>
        public string Location { get; set; }

        /// <summary>
        /// Gets or sets the associated properties for the web site clone
        /// </summary>
        public WebSiteCloneBaseProperties Properties
        {
            get => _properties ?? (_properties = new WebSiteCloneBaseProperties());
            set => _properties = value;
        }

        /// <summary>
        /// Default constructor for WebSiteCloneBase
        /// </summary>
        protected WebSiteCloneBase()
        {
            InitializeDefaultProperties();
        }

