namespace YCombinator
{
    public interface IApply<T, R>
    {
        R Apply(IApply<T, R> f, T t);
    }
 
    public class Y<T, R>
    {
        public static Func<T, R> Apply(Func<IApply<T, R>, Func<T, R>> f)
        {
            return t => ((IApply<T, R> x, T y) => x.Apply(x, y))
                ((IApply<T, R> x, T y) => f(x)(y), t);
        }
    }
 
    class Graph
    {
        static void Main(string[] args)
        {
            var n = 10;
            Console.WriteLine($"fac({n}) = {Fac(n)}");
            Console.WriteLine($"fib({n}) = {Fib(n)}");
        }
 
        static int Fac(int n)
        {
            var almostFac = (Func<IApply<int, int>, Func<int, int>>)(f => x => x == 0? 1 : x * f(x - 1));
            return Y<int, int>.Apply(almostFac)(n);
        }
 
        static int Fib(int n)
        {
            var almostFib = (Func<IApply<(int, int, int), int>, Func<(int, int, int), int>>)(f => x =>
            {
                var (a0, a1, x1) = x;
                return x1 switch
                {
                    0 => a0,
                    1 => a1,
                    _ => f((a1, a0 + a1, x1 - 1))
                };
            });
            return Y<(int, int, int), int>.Apply(almostFib)((1, 1, n));
        }
    }
}

