[StructLayout(LayoutKind.Sequential)]
public unsafe struct CefSettings
{
    public int size;
    public int single_process;
    public IntPtr browser_subprocess_path;
    public IntPtr frame_work_directory;
    public int log_severity;
    public IntPtr log_file;
    public int release_dcheck_enabled;
    public IntPtr cache_path;
    public IntPtr root_cache_path;
    public int no_sandbox;

    [MarshalAs(UnmanagedType.U1)]
    public bool persist_session_cookies;
    [MarshalAs(UnmanagedType.U1)]
    public bool persist_user_preferences;

    public IntPtr user_agent;
    public IntPtr product_version;
    public IntPtr locale;
    public IntPtr command_line_args_disabled;

    public static CefSettings* Alloc()
    {
        CefSettings* settings = (CefSettings*)Marshal.AllocHGlobal(sizeof(CefSettings));

        try
        {
            settings->size = sizeof(CefSettings);
            settings->single_process = 0;
            settings->log_severity = 0;
            settings->no_sandbox = 1;

            return settings;
        }
        catch
        {
            Free(settings);
            throw;
        }
    }

    public static void Free(CefSettings* settings)
    {
        if (settings != null)
        {
            Marshal.FreeHGlobal((IntPtr)settings);
        }
    }

    public static void Initialize(CefSettings* settings,
        string subprocessPath = null,
        string cachePath = null,
        int logSeverity = 0)
    {
        if (subprocessPath != null)
        {
            settings->browser_subprocess_path = Marshal.StringToHGlobalAnsi(subprocessPath);
        }

        if (cachePath != null)
        {
            settings->cache_path = Marshal.StringToHGlobalAnsi(cachePath);
        }

        settings->log_severity = logSeverity;
    }
}

