namespace Rare
{
    class Solution
    {
        static void Main(string[] args)
        {
            Stopwatch sw = new Stopwatch();
            sw.Start();
            for (int i = 1; i < 100000000000; i++)
            {
                if (rare(i))
                {
                    Console.WriteLine("found a rare: {0}", i);
                }
            }
            sw.Stop();
            Console.WriteLine("time elapsed: {0}", sw.Elapsed);
            Console.ReadKey();
        }
 
        static bool is_square(long n)
        {
            long s = (long)Math.Floor(Math.Sqrt(n + 0.5));
            return s * s == n;
        }
 
        static long reverse(long n)
        {
            return long.Parse(new string(n.ToString().Reverse().ToArray()));
        }
 
        static bool is_palindrome(long n)
        {
            return n == reverse(n);
        }
 
        static bool rare(long n)
        {
            long r = reverse(n);
            return (
                !is_palindrome(n) &&
                n > r &&
                is_square(n + r) && is_square(n - r)
            );
        }
    }
}

