{
    public bool IsInstanceOfInterface(RuntimeTypeHandle interfaceType, out Exception castError)
    {
        castError = null;
        return true;
    }

    public RuntimeTypeHandle GetImplType(RuntimeTypeHandle interfaceType)
    {
        return default(RuntimeTypeHandle);
    }
