    public class DeviceList
    {
        private List<Device> m_devices;
        private int m_index;

        public DeviceList()
        {
            m_devices = new List<Device>();
            m_index = -1; // Start before the first element
        }

        // Method to add new devices to the list
        public void Add(Device device)
        {
            if (device != null)
            {
                m_devices.Add(device);
            }
        }

        // Returns the current count of devices
        public int Count
        {
            get { return m_devices.Count; }
        }

        // Move to the next device in the list
        public bool MoveNext()
        {
            if (m_index + 1 < m_devices.Count)
            {
                m_index++;
                return true;
            }
            return false;
        }

        // Reset the iterator back to the start
        public void Reset()
        {
            m_index = -1;
        }

        // Property to get the current device
        public Device Current
        {
            get
            {
                if (m_index >= 0 && m_index < m_devices.Count)
                {
                    return m_devices[m_index];
                }
                return null; // Return null if the iterator is out of bounds
            }
        }

        // Method to get a string representation of all the devices
        public override string ToString()
        {
            string result = "Device List: \n";
