    {
        [TestMethod]
        public void CalculoPis()
        {
            var produto = new Produto
            {
                Preco = 100,
                Quantidade = 1,
                PercentualPis = 1.65m
            };

            var facade = new FacadeCalculadoraTributacao();
            var resultadoCalculoPis = facade.CalculaPis(produto);

            Assert.AreEqual(100m, resultadoCalculoPis.BaseCalculo);
            Assert.AreEqual(1.65m, resultadoCalculoPis.ValorPis);
        }

        [TestMethod]
        public void CalculoPisComIpi()
        {
            var produto = new Produto
            {
                Preco = 100,
                Quantidade = 1,
                PercentualPis = 1.65m,
                ValorIpi = 10
            };

            var facade = new FacadeCalculadoraTributacao();
            var resultadoCalculoPis = facade.CalculaPis(produto);

            Assert.AreEqual(110m, resultadoCalculoPis.BaseCalculo);
            Assert.AreEqual(1.82m, decimal.Round(resultadoCalculoPis.ValorPis,2));
