namespace DirectInputManagement
{
    public sealed class DeviceList : IEnumerable, IEnumerator
    {
        private ArrayList m_devices;
        private int m_index;

        public DeviceList()
        {
            m_devices = new ArrayList();
            m_index = -1;
        }

        public void Add(object device)
        {
            if (device == null)
                throw new ArgumentNullException(nameof(device), "Device cannot be null.");
            m_devices.Add(device);
        }

        public void Reset()
        {
            m_index = -1;
        }

        public bool MoveNext()
        {
            if (m_index < m_devices.Count - 1)
            {
                m_index++;
                return true;
            }
            else
            {
                return false;
            }
        }

        public object Current
        {
            get
            {
                if (m_index == -1 || m_index >= m_devices.Count)
                    throw new InvalidOperationException("Enumerator is positioned before the first element or after the last element.");
                return m_devices[m_index];
            }
        }

        public IEnumerator GetEnumerator()
        {
            Reset();
            return this;
        }

        public int Count
        {
            get { return m_devices.Count; }
        }

        public object this[int index]
        {
            get
            {
                if (index < 0 || index >= m_devices.Count)
                    throw new ArgumentOutOfRangeException(nameof(index), "Index is out of range.");
                return m_devices[index];
            }
        }

        public void RemoveAt(int index)
        {
            if (index < 0 || index >= m_devices.Count)
                throw new ArgumentOutOfRangeException(nameof(index), "Index is out of range.");
            m_devices.RemoveAt(index);
        }

        public void Clear()
        {
            m_devices.Clear();
        }

        public bool Contains(object device)
        {
            return m_devices.Contains(device);
        }

        public int IndexOf(object device)
        {
            return m_devices.IndexOf(device);
        }

        public void Insert(int index, object device)
        {
            if (index < 0 || index > m_devices.Count)
                throw new ArgumentOutOfRangeException(nameof(index), "Index is out of range.");
            m_devices.Insert(index, device);
        }

