using System.Text;

public class TableBuilder
{
    private List<TableLine> _lines = new List<TableLine>();
    private int _titleColumnMinWidth = 10;
    private int _dataColumnMinWidth = 10;

    public class TableLine
    {
        public string Title { get; set; }
        public List<string> Data { get; set; }

        public TableLine(string title, params string[] data)
        {
            Title = title;
            Data = new List<string>(data);
        }
    }

    public TableBuilder AddLine(string title, params string[] data)
    {
        _lines.Add(new TableLine(title, data));
        UpdateColumnWidths();
        return this;
    }

    private void UpdateColumnWidths()
    {
        _titleColumnMinWidth = Math.Max(_titleColumnMinWidth,
            _lines.Max(l => l.Title.Length));

        for (int i = 0; i < _lines.Max(l => l.Data.Count); i++)
        {
            int columnIndex = i;
            _dataColumnMinWidth = Math.Max(_dataColumnMinWidth,
                _lines.Where(l => l.Data.Count > columnIndex)
                      .Max(l => l.Data[columnIndex].Length));
        }
    }

    public string Build()
    {
        var builder = new StringBuilder();
        string horizontalLine = CreateHorizontalLine();

        builder.AppendLine(horizontalLine);
        foreach (var line in _lines)
        {
            builder.AppendLine(FormatTableLine(line));
            builder.AppendLine(horizontalLine);
        }

        return builder.ToString();
    }

    private string CreateHorizontalLine()
    {
        return "+" +
            PadCenter("-", _titleColumnMinWidth + 2, '-') +
            string.Join("",
                Enumerable.Repeat("+" + PadCenter("-", _dataColumnMinWidth + 2, '-'),
                _lines.Max(l => l.Data.Count))) +
            "+";
    }

    private string FormatTableLine(TableLine line)
    {
        var formattedLine = new StringBuilder();
        formattedLine.Append("| ");
        formattedLine.Append(PadCenter(line.Title, _titleColumnMinWidth));
        formattedLine.Append(" |");

        for (int i = 0; i < line.Data.Count; i++)
        {
            formattedLine.Append(" ");
            formattedLine.Append(PadCenter(line.Data[i], _dataColumnMinWidth));
            formattedLine.Append(" |");
        }

        return formattedLine.ToString();
    }

    private string PadCenter(string text, int width)
    {
        if (text.Length > width)
            return text.Substring(0, width);

