        Level0 = 0,

using System;
using System.Collections.Generic;
using System.Windows.Media.Media3D;

public class Helix3D
{
    public int Turns { get; set; }
    public double Height { get; set; }
    public double BottomRadius { get; set; }
    public double TopRadius { get; set; }

    public Helix3D(int turns, double height, double bottomRadius, double topRadius)
    {
        Turns = turns;
        Height = height;
        BottomRadius = bottomRadius;
        TopRadius = topRadius;
    }

    public List<Point3D> GetPoints(int n)
    {
        List<Point3D> points = new List<Point3D>();

        for (int i = 0; i < n; i++)
        {
            double u = (double)i / (n - 1);
            double angle = 2 * Math.PI * Turns * u;
            double radius = BottomRadius + (TopRadius - BottomRadius) * u;
            double x = radius * Math.Cos(angle);
            double y = radius * Math.Sin(angle);
            double z = Height * u;

            points.Add(new Point3D(x, y, z));
        }

        return points;
    }
}

class Counter
{
    static void Main(string[] args)
    {
        Helix3D helix = new Helix3D(5, 10.0, 2.0, 5.0);
        List<Point3D> points = helix.GetPoints(100);

        foreach (var point in points)
        {
            Console.WriteLine($"X: {point.X}, Y: {point.Y}, Z: {point.Z}");
        }
    }
}

