namespace PPM
{
    public class Colour
    {
        public int r, g, b;
        public Colour(int r, int g, int b)
        {
            this.r = r;
            this.g = g;
            this.b = b;
        }
    }
 
    public class Bitmap
    {
        public int width, height;
        public Colour[,] pixels;
        public Bitmap(int width, int height, Colour colour)
        {
            this.width = width;
            this.height = height;
            pixels = new Colour[width, height];
            for (int w = 0; w < width; w++)
            {
                for (int h = 0; h < height; h++)
                {
                    pixels[w, h] = colour;
                }
            }
        }
        public Colour get(int w, int h)
        {
            return pixels[w, h];
        }
        public void set(int w, int h, Colour colour)
        {
            pixels[w, h] = colour;
        }
        public void fillrect(int x, int y, int w, int h, Colour colour)
        {
            for (int i = x; i < x + w; i++)
            {
                for (int j = y; j < y + h; j++)
                {
                    set(i, j, colour);
                }
            }
        }
        public void writeppmp3(TextWriter writer)
        {
            writer.WriteLine("P3");
            writer.WriteLine("# generated from Bitmap.writeppmp3");
            writer.WriteLine(width + " " + height);
            writer.WriteLine("255");
            for (int h = 0; h < height; h++)
            {
                for (int w = 0; w < width; w++)
                {
                    Colour colour = get(w, h);
                    writer.Write(colour.r + " " + colour.g + " " + colour.b + " ");
                }
                writer.WriteLine();
            }
        }
        public void togreyscale()
        {
            for (int h = 0; h < height; h++)
            {
                for (int w = 0; w < width; w++)
                {
                    Colour colour = get(w, h);
                    int l = (int)(0.2126 * colour.r + 0.7152 * colour.g + 0.0722 * colour.b);
                    set(w, h, new Colour(l, l, l));
                }
            }
        }
    }
 
