            {
                using (var cmd = connection.CreateCommand())
                {
                    cmd.CommandText = "INSERT INTO TestTable (Value) VALUES (@value);";
                    cmd.Parameters.AddWithValue("@value", InsertedValue);
                    for (int i = 0; i < RecordCount; i++)
                    {
                        cmd.ExecuteNonQuery();
                    }
                }
                transaction.Commit();
            }
        }

