namespace MVCLocalize.Code
{
    public static class LanguageHelper
    {
        private const string LanguageKey = "language";

        public static void SetLanguage(string language)
        {
            if (HasElement<string>(LanguageKey))
            {
                HttpContext.Current.Session[LanguageKey] = language;
            }
            else
            {
                AddElement<string>(LanguageKey, language);
            }
        }

        public static string GetLanguage()
        {
            if (HasElement<string>(LanguageKey))
            {
                return (string)HttpContext.Current.Session[LanguageKey];
            }
            else
            {
                string language = English;

                if (HttpContext.Current.Request.UserLanguages != null)
                {
                    language = HttpContext.Current.Request.UserLanguages.First();
                }

                if (language.ToLower().StartsWith(German))
                {
                    return German;
                }
                else
                {
                    return English;
                }
            }
        }

        public static string German
        {
            get
            {
                return "de";
            }
        }

        public static string English
        {
            get
            {
                return "en";
            }
        }

        /// <summary>
        /// Adds an element
        /// </summary>
        /// <param name="user"></param>
        private static void AddElement<T>(string key, T data)
        {
            HttpContext.Current.Session[key] = data;
        }

        /// <summary>
        /// Gets an element
        /// </summary>
        /// <param name="user"></param>
        private static bool HasElement<T>(string key)
        {
            return HttpContext.Current.Session[key] is T;
        }
    }
}

using EloBuddy;
using EloBuddy.SDK;
using EloBuddy.SDK.Menu;
using EloBuddy.SDK.Menu.Values;
using LeagueSharp.Common;
using System.Linq;

namespace AsheCombo
{
    public class QCombo
    {
        private static Menu Menu;
        private static AIHeroClient Player => ObjectManager.Player;
        private static Spell Q;

        public static void OnLoad()
        {
            Q = new Spell(SpellSlot.Q);

            Menu = MainMenu.AddMenu("Ashe Q Combo", "asheQCombo");
            Menu.Add("useQ", new CheckBox("Use Q in Combo", true));
            Menu.Add("manaSlider", new Slider("Minimum Mana %", 30));
            Menu.Add("prioritizeAA", new CheckBox("Prioritize Auto Attacks", true));
        }

        public static void OnEnable()
        {
            Game.OnUpdate += OnUpdate;
        }

        public static void OnDisable()
        {
            Game.OnUpdate -= OnUpdate;
        }

        private static void OnUpdate(System.EventArgs args)
        {
            if (!Menu["useQ"].Cast<CheckBox>().CurrentValue || Player.IsRecalling() || !Q.IsReady())
                return;

            if (Player.ManaPercent < Menu["manaSlider"].Cast<Slider>().CurrentValue)
                return;

            if (Menu["prioritizeAA"].Cast<CheckBox>().CurrentValue && Player.IsAutoAttacking)
                return;

            var target = TargetSelector.GetTarget(Q.Range, DamageType.Physical);
            if (target != null && target.IsValidTarget(Q.Range))
            {
                Q.Cast();
            }
        }

        private static void RangersFocus()
        {
            if (!Q.IsReady())
                return;

            var enemies = HeroManager.Enemies.Where(e => e.IsValidTarget(Q.Range));
            if (enemies.Any())
            {
                Q.Cast();
            }
        }
    }
}

