    /// <summary>
    /// Event arguments for errors that occur during HTML rendering.
    /// </summary>
    public class HtmlRenderErrorEventArgs : EventArgs
    {
        private readonly Exception _exception;
        private readonly string _message;
        private readonly HtmlRenderErrorType _type;

        /// <summary>
        /// Initializes a new instance of the <see cref="HtmlRenderErrorEventArgs"/> class.
        /// </summary>
        /// <param name="type">The type of the error.</param>
        /// <param name="message">The error message.</param>
        /// <param name="exception">The exception that occurred, or null if no exception occurred.</param>
        public HtmlRenderErrorEventArgs(HtmlRenderErrorType type, string message, Exception exception)
        {
            _type = type;
            _message = message;
            _exception = exception;
        }

        /// <summary>
        /// Gets the type of the error.
        /// </summary>
        public HtmlRenderErrorType Type
        {
            get { return _type; }
        }

        /// <summary>
        /// Gets the error message.
        /// </summary>
        public string Message
        {
            get { return _message; }
        }

        /// <summary>
        /// Gets the exception that occurred, or null if no exception occurred.
        /// </summary>
        public Exception Exception
        {
            get { return _exception; }
        }

        /// <summary>
        /// Returns a string that represents the current object.
        /// </summary>
        /// <returns>A string that represents the current object.</returns>
        public override string ToString()
        {
            return string.Format("HtmlRenderErrorEventArgs: Type={0}, Message={1}, Exception={2}", _type, _message, _exception);
        }
    }
}

