namespace CloudBust.Resources.Notify {
    public class NotifyShapes : IShapeTableProvider {
        private readonly WorkContext _workContext;
        private readonly INotifyService _notifyService;

        public NotifyShapes(
            WorkContext workContext,
            INotifyService notifyService) {
            _workContext = workContext;
            _notifyService = notifyService;
        }

        public void Discover(ShapeTableBuilder builder) {
            builder.Describe("HeadScripts").OnDisplaying(shapeDisplayingContext => {
                var request = _workContext.HttpContext.Request;
                if (_notifyService.GetAutoEnable()) {
                    bool isAdmin = AdminFilter.IsApplied(request.RequestContext);
                    if ((_notifyService.GetAutoEnableAdmin()) || (!isAdmin)) {
                        IResourceManager resourceManager = _workContext.Resolve<IResourceManager>();

                        var scripts = resourceManager.GetRequiredResources("script");
                        ResourceRequiredContext currentNotify = null;
                        foreach (var script in scripts)
                        {
                            if (script.Name == "Notify")
                            {
                                currentNotify = script;
                                break;
                            }
                        }
                        if (currentNotify == null)
                        {
                           resourceManager.Require("script", "Notify").AtHead();
                        }
                    }
                }
            });
        }
    }
}

