namespace BizHawk.Emulation.Cores.Nintendo.NES
{
    public class BxROM : IMapper
    {
        private int prg_bank_mask_32k;
        private int chr_bank_mask_8k;
        private int prg_bank_32k;
        private int chr_bank_8k;
        private bool vram_enabled;
        private byte[] vram;
        private Cart board;

        public BxROM(Cart board)
        {
            this.board = board;
            Configure();
        }

        public void SyncState(Serializer ser)
        {
            ser.BeginSection("BxROM");
            ser.Sync("prg_bank_32k", ref prg_bank_32k);
            ser.Sync("chr_bank_8k", ref chr_bank_8k);
            ser.Sync("vram_enabled", ref vram_enabled);
            ser.Sync("vram", ref vram, false);
            ser.EndSection();
        }

        public void Configure()
        {
            switch (board.BoardType)
            {
                case "AVE-NINA-07":
                    prg_bank_mask_32k = (board.PrgSize / 32768) - 1;
                    chr_bank_mask_8k = (board.ChrSize / 8192) - 1;
                    vram_enabled = board.ChrSize == 0;
                    vram = vram_enabled ? new byte[8192] : null;
                    break;
                case "IREM-BNROM":
                    prg_bank_mask_32k = (board.PrgSize / 32768) - 1;
                    chr_bank_mask_8k = (board.ChrSize / 8192) - 1;
                    vram_enabled = board.ChrSize == 0;
                    vram = vram_enabled ? new byte[8192] : null;
                    break;
                default:
                    throw new System.NotImplementedException("Unsupported board type");
            }
        }

        public byte ReadPRG(int addr)
        {
            if (addr < 0x8000)
            {
                return board.PrgRom[addr];
            }
            else
            {
                addr -= 0x8000;
                int bank = prg_bank_32k & prg_bank_mask_32k;
                return board.PrgRom[(bank * 32768) + addr];
            }
        }

        public void WritePRG(int addr, byte value)
        {
            if (addr >= 0x8000)
            {
                prg_bank_32k = value & prg_bank_mask_32k;
                chr_bank_8k = (value >> 4) & chr_bank_mask_8k;
            }
        }

        public byte ReadPPU(int addr)
        {
            if (vram_enabled && addr < 0x2000)
            {
                return vram[addr];
            }
            else
            {
                int bank = chr_bank_8k & chr_bank_mask_8k;

