namespace Orchard.Notifications.Shapes {
    [OrchardFeature("Orchard.Notifications")]
    public class NotificationShapes : IShapeTableProvider {
        private readonly IResourceManager _resourceManager;
        private readonly WorkContext _workContext;
        private readonly INotifyService _notifyService;

        public Localizer T { get; set; }

        public NotificationShapes(
            IResourceManager resourceManager,
            WorkContext workContext,
            INotifyService notifyService) {
            _resourceManager = resourceManager;
            _workContext = workContext;
            _notifyService = notifyService;
            T = NullLocalizer.Instance;
        }

        public void Discover(ShapeTableBuilder builder) {
            builder.Describe("NotificationScript")
                .OnDisplaying(context => {
                    var shape = context.Shape;
                    if (ShouldInjectNotificationScript(shape)) {
                        InjectNotificationScript();
                    }
                });
        }

        private bool ShouldInjectNotificationScript(dynamic shape) {
            bool isAdminContext = _workContext.CurrentTheme.IsAdminTheme;
            bool autoEnable = GetAutoEnable();
            bool autoEnableAdmin = GetAutoEnableAdmin();

            return (autoEnable && !isAdminContext) ||
                   (autoEnableAdmin && isAdminContext);
        }

        private void InjectNotificationScript() {
            if (!IsNotificationScriptAlreadyRegistered()) {
                RequireNotificationScripts();
            }
        }

        private bool IsNotificationScriptAlreadyRegistered() {
            return _resourceManager.GetRegisteredResources(ResourceType.Script)
                .Any(r => r.Name.Contains("NotificationScript"));
        }

        private void RequireNotificationScripts() {
            _resourceManager.Require("script", "NotificationLibrary")
                .AtHead();
            _resourceManager.Require("script", "NotificationCore")
                .AtHead();
        }

        private bool GetAutoEnable() {
            return _notifyService.GetSetting<bool>("NotificationAutoEnable", false);
        }

        private bool GetAutoEnableAdmin() {
            return _notifyService.GetSetting<bool>("NotificationAutoEnableAdmin", false);
        }
    }
}

using System;
using static System.Linq.Enumerable;
 
public class Calculator
{
    static void Main()
    {
        string[] input = {
            "",
            "The better the 4-wheel drive, the further you'll be from help when ya get stuck!",
            "headmistressship",
            "\"If I were two-faced, would I be wearing this one?\" --- Abraham Lincoln ",
            "..1111111111111111111111111111111111111111111111111111111111111117777888",
            "I never give 'em hell, I just tell the truth, and they think it's hell. ",
            "                                                    --- Harry S Truman  "
        };
        foreach (string s in input) {
            Console.WriteLine($"old: {s.Length} «««{s}»»»");
            string c = Collapse(s);
            Console.WriteLine($"new: {c.Length} «««{c}»»»");
        }
    }
 
    static string Collapse(string s) => string.IsNullOrEmpty(s) ? "" :
        s[0] + new string(Range(1, s.Length - 1).Where(i => s[i] != s[i - 1]).Select(i => s[i]).ToArray());
}

