using UnityEngine;
using FarseerPhysics;
using FarseerPhysics.Dynamics;
using FarseerPhysics.Factories;
using Microsoft.Xna.Framework;

public class CCDTest : MonoBehaviour
{
    private World _physicsWorld;
    private const float PhysicsScale = 50f;
    private const int ObjectCount = 15;

    void Start()
    {
        InitializePhysicsWorld();
        CreateBasketStructure();
        GenerateDynamicObjects();
    }

    private void InitializePhysicsWorld()
    {
        Vector2 gravity = new Vector2(0, 9.81f);
        _physicsWorld = new World(gravity);
        _physicsWorld.ContinuousPhysics = true;
    }

    private void CreateBasketStructure()
    {
        Vector2 basketCenter = new Vector2(5f, 3f);
        float basketWidth = 2f;
        float basketHeight = 1f;

        Body[] basketWalls = new Body[3];

        for (int i = 0; i < 3; i++)
        {
            basketWalls[i] = BodyFactory.CreateBody(_physicsWorld);
            basketWalls[i].BodyType = BodyType.Static;
            basketWalls[i].Position = basketCenter;

            Fixture basketFixture;
            if (i < 2)
            {
                basketFixture = FixtureFactory.AttachRectangle(
                    basketWidth, 0.2f, 1f, Vector2.Zero, basketWalls[i]);
                basketFixture.Restitution = 0.7f;
            }
            else
            {
                basketFixture = FixtureFactory.AttachRectangle(
                    0.2f, basketHeight, 1f, Vector2.Zero, basketWalls[i]);
                basketFixture.Restitution = 0.5f;
            }
        }
    }

    private void GenerateDynamicObjects()
    {
        for (int i = 0; i < ObjectCount; i++)
        {
            Body dynamicBody = BodyFactory.CreateBody(_physicsWorld);
            dynamicBody.BodyType = BodyType.Dynamic;
            dynamicBody.Position = new Vector2(
                Random.Range(3f, 7f),
                Random.Range(0f, 2f)
            );

            dynamicBody.IsContinuous = true;
            dynamicBody.SleepingAllowed = false;

            Fixture objectFixture = FixtureFactory.AttachCircle(
                Random.Range(0.1f, 0.3f),
                Random.Range(0.5f, 1.5f),
                dynamicBody
            );

            objectFixture.Friction = Random.Range(0.3f, 0.8f);
            objectFixture.Restitution = Random.Range(0.4f, 0.9f);
        }
    }

    void Update()
    {
        _physicsWorld.Step(Time.deltaTime);
    }
}

