public class ComponentManager
{
    public static void Start(string[] args, IComponentConfiguration config, IImageProvider imageProvider, ICameraDevice cameraDevice)
    {
        Task.Run(() =>
        {
            try
            {
                using (var manager = new Manager())
                {
                    manager.Initialize(args);
                    Console.WriteLine("Initializing OpenRTM manager...");

                    OpenRTM.Core.RTObject_impl comp = CreateComponent(manager, config, imageProvider, cameraDevice);

                    if (comp != null)
                    {
                        Console.WriteLine("Component created successfully.");
                        var profile = GetComponentProfile(comp);
                        Console.WriteLine($"Component Profile: {profile.instance_name}");

                        manager.Run(true);
                    }
                    else
                    {
                        Console.WriteLine("Failed to create the component.");
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error starting component: {ex.Message}");
                Console.WriteLine("Ensure the naming service is running.");
            }
        });
    }

    private static OpenRTM.Core.RTObject_impl CreateComponent(Manager manager, IComponentConfiguration config, IImageProvider imageProvider, ICameraDevice cameraDevice)
    {
        try
        {
            manager.LoadComponent("Component.USBCamera");
            var comp = manager.CreateComponent("USBCamera") as OpenRTM.Core.RTObject_impl;

            if (comp is Component.USBCamera usbCameraComponent)
            {
                usbCameraComponent.SetConfiguration(config);
                usbCameraComponent.SetImageProvider(imageProvider);
                usbCameraComponent.SetCameraDevice(cameraDevice);
            }

            return comp;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error creating component: {ex.Message}");
            return null;
        }
    }

    private static RTC.ComponentProfile GetComponentProfile(OpenRTM.Core.RTObject_impl component)
    {
        return component.get_component_profile();
    }
}

