    private readonly IMethodSymbol _operatorMethod;

    public OperatorReferenceFinder(Solution solution, IMethodSymbol operatorMethod)
    {
        _solution = solution;
        _operatorMethod = operatorMethod;
        _syntaxFactsService = solution.Workspace.Services.GetLanguageServices(_operatorMethod.Language)
            .GetRequiredService<ISyntaxFactsService>();
