    public async Task<ImmutableArray<DocumentSpan>> FindOperatorReferencesAsync(
        FindReferencesSearchOptions searchOptions,
        CancellationToken cancellationToken)
    {
        var documentsToSearch = await DetermineDocumentsToSearchAsync(cancellationToken);
        var references = ImmutableArray.CreateBuilder<DocumentSpan>();

        foreach (var document in documentsToSearch)
        {
            var documentReferences = await FindReferencesInDocumentAsync(document, cancellationToken);
            references.AddRange(documentReferences);
        }

        return references.ToImmutable();
    }

    private async Task<ImmutableArray<Document>> DetermineDocumentsToSearchAsync(
        CancellationToken cancellationToken)
    {
        var documentsToSearch = await _solution.Projects
            .SelectMany(p => p.Documents)
            .Where(d => CanSearchDocument(d))
            .ToImmutableArrayAsync(cancellationToken);

        return documentsToSearch;
    }

    private bool CanSearchDocument(Document document)
    {
        return document.SupportsSyntaxTree &&
