namespace StringTest
{
    class Timer
    {
        static void Main(string[] args)
        {
            Console.WriteLine("Starts with Test ( Hello,Hell ) : {0}", startsWith("Hello", "Hell"));
            Console.WriteLine("Ends with Test ( Code,ode ) : {0}", endsWith("Code", "ode"));
            Console.WriteLine("Contains Test ( Google,msn ) : {0}", doesContain("Google", "msn"));
        }
 
        static bool startsWith(string container, string target)
        {
            int clen = container.Length, tlen = target.Length;
            if (clen < tlen)
                return false;
            return container.Substring(0, tlen) == target;
        }
 
        static bool endsWith(string container, string target)
        {
            int clen = container.Length, tlen = target.Length;
            if (clen < tlen)
                return false;
            return container.Substring(clen - tlen, tlen) == target;
        }
 
        static bool doesContain(string container, string target)
        {
            return container.IndexOf(target)!= -1;
        }
    }
}

