            StreamReader inputFile = new StreamReader(input);
 
            string[] line = inputFile.ReadLine().Split(' ');
            rowA = int.Parse(line[0]);
            colA = int.Parse(line[1]);
 
            matrixA = new double[rowA, colA];
 
            for (i = 0; i < rowA; i++)
            {
                line = inputFile.ReadLine().Split(' ');
                for (j = 0; j < colA; j++)
                {
                    matrixA[i, j] = double.Parse(line[j]);
                }
            }
 
            line = inputFile.ReadLine().Split(' ');
            rowB = int.Parse(line[0]);
            colB = int.Parse(line[1]);
 
            matrixB = new double[rowB, colB];
 
            for (i = 0; i < rowB; i++)
            {
                line = inputFile.ReadLine().Split(' ');
                for (j = 0; j < colB; j++)
                {
                    matrixB[i, j] = double.Parse(line[j]);
                }
            }
 
            inputFile.Close();
 
            rowC = rowA * rowB;
            colC = colA * colB;
 
            matrixC = new double[rowC, colC];
 
            for (i = 0; i < rowA; i++)
            {
                for (j = 0; j < colA; j++)
                {
                    startRow = i * rowB;
                    startCol = j * colB;
                    for (k = 0; k < rowB; k++)
                    {
                        for (l = 0; l < colB; l++)
                        {
                            matrixC[startRow + k, startCol + l] = matrixA[i, j] * matrixB[k, l];
                        }
                    }
                }
            }
 
            StreamWriter outputFile = new StreamWriter(output);
 
            for (i = 0; i < rowC; i++)
            {
                for (j = 0; j < colC; j++)
                {
                    outputFile.Write(matrixC[i, j] + "\t");
                }
                outputFile.WriteLine();
            }
 
            outputFile.Close();

using System;
using System.Collections.Concurrent;
using System.Threading;

public class FakeNetwork
{
    private readonly ConcurrentDictionary<string, PacketReceivedHandler> _listeners = new();
    private readonly ConcurrentQueue<NetworkPacketQueueEntry> _queuedPackets = new();
    private readonly Timer _stateTimer;

    public delegate void PacketReceivedHandler(string packet);

    public FakeNetwork()
    {
        _stateTimer = new Timer(ProcessPackets, null, 0, 1000); // Process packets every second
    }

    public void AttachListener(string publicKey, PacketReceivedHandler handler)
    {
        if (!_listeners.TryAdd(publicKey, handler))
        {
            throw new InvalidOperationException("Listener already registered for this public key.");
        }
    }

    public void SendPacket(string destinationPublicKey, string packet)
    {
        _queuedPackets.Enqueue(new NetworkPacketQueueEntry(destinationPublicKey, packet));
    }

    private void ProcessPackets(object state)
    {
        while (_queuedPackets.TryDequeue(out var packetEntry))
        {
            if (_listeners.TryGetValue(packetEntry.DestinationPublicKey, out var handler))
            {
                handler(packetEntry.Packet);
            }
        }
    }

    private struct NetworkPacketQueueEntry
    {
        public string DestinationPublicKey { get; }
        public string Packet { get; }

        public NetworkPacketQueueEntry(string destinationPublicKey, string packet)
        {
            DestinationPublicKey = destinationPublicKey;
            Packet = packet;
        }
    }
}

// Example usage
public class Game
{
    public static void Main()
    {
        var network = new FakeNetwork();

        network.AttachListener("key1", packet => Console.WriteLine($"Listener 1 received: {packet}"));
        network.AttachListener("key2", packet => Console.WriteLine($"Listener 2 received: {packet}"));

        network.SendPacket("key1", "Hello, Key 1!");
        network.SendPacket("key2", "Hello, Key 2!");

        Thread.Sleep(2000); // Wait for timer to process packets
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
 
namespace Fivenum {
    public static class Helper {
        public static string AsString<T>(this ICollection<T> c, string format = "{0}") {
            StringBuilder sb = new StringBuilder("[");
            int count = 0;
            foreach (var t in c) {
                if (count++ > 0) {
                    sb.Append(", ");
                }
                sb.AppendFormat(format, t);
            }
            return sb.Append("]").ToString();
        }
    }
 
    class Utils {
        static double Median(double[] x, int start, int endInclusive) {
            int size = endInclusive - start + 1;
            if (size <= 0) throw new ArgumentException("Array slice cannot be empty");
            int m = start + size / 2;
            return (size % 2 == 1) ? x[m] : (x[m - 1] + x[m]) / 2.0;
        }
 
        static double[] Fivenum(double[] x) {
            foreach (var d in x) {
                if (Double.IsNaN(d)) {
                    throw new ArgumentException("Unable to deal with arrays containing NaN");
                }
            }
            double[] result = new double[5];
            Array.Sort(x);
            result[0] = x.First();
            result[2] = Median(x, 0, x.Length - 1);
            result[4] = x.Last();
            int m = x.Length / 2;
            int lowerEnd = (x.Length % 2 == 1) ? m : m - 1;
            result[1] = Median(x, 0, lowerEnd);
            result[3] = Median(x, m, x.Length - 1);
            return result;
        }
 
        static void Main(string[] args) {
            double[][] x1 = new double[][]{
                new double[]{ 15.0, 6.0, 42.0, 41.0, 7.0, 36.0, 49.0, 40.0, 39.0, 47.0, 43.0},
                new double[]{ 36.0, 40.0, 7.0, 39.0, 41.0, 15.0},
                new double[]{
                     0.14082834,  0.09748790,  1.73131507,  0.87636009, -1.95059594,  0.73438555,
                    -0.03035726,  1.46675970, -0.74621349, -0.72588772,  0.63905160,  0.61501527,
                    -0.98983780, -1.00447874, -0.62759469,  0.66206163,  1.04312009, -0.10305385,
                     0.75775634,  0.32566578
                },
            };
            foreach(var x in x1) {
                var result = Fivenum(x);
                Console.WriteLine(result.AsString("{0:F8}"));
            }
        }
    }
}

