namespace OpenSslWrapper
{
    // Base class for handling native resource management.
    public abstract class NativeObject : IDisposable
    {
        protected IntPtr nativePtr;
        private bool disposed = false;

        // Expose the native pointer for advanced scenarios.
        public IntPtr NativePointer
        {
            get { return nativePtr; }
        }

        // Constructor accepting a native pointer.
        protected NativeObject(IntPtr ptr)
        {
            nativePtr = ptr;
        }

        // Destructor to ensure native resources are released.
        ~NativeObject()
        {
            Dispose(false);
        }

        // Public dispose method.
        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }

        // Protected dispose pattern for releasing native resources.
        protected virtual void Dispose(bool disposing)
        {
            if (disposed)
                return;

            if (nativePtr != IntPtr.Zero)
            {
                FreeNativeResources();
                nativePtr = IntPtr.Zero;
            }
            disposed = true;
        }

        // Abstract method for releasing native resources.
        protected abstract void FreeNativeResources();
    }

