            return Marshal.AllocHGlobal(8);
        }

        // Simulate freeing the ASN.1 integer native object.
        public static void ASN1_INTEGER_free(IntPtr asn1Int)
        {
            Marshal.FreeHGlobal(asn1Int);
        }

        // Simulate retrieving the integer value from the native ASN.1 structure.
        public static int ASN1_INTEGER_get(IntPtr asn1Int)
        {
            return Marshal.ReadInt32(asn1Int);
        }

        // Simulate setting the integer value in the native ASN.1 structure.
        public static void ASN1_INTEGER_set(IntPtr asn1Int, int value)
        {
            Marshal.WriteInt32(asn1Int, value);
        }
    }

