using System.Text.RegularExpressions;
 
namespace RangeExpander
{
    class RangeExpander : IEnumerator<int>, IEnumerable<int>
    {
        private static readonly Regex TOKEN_PATTERN = new Regex("([+-]?\\d+)-([+-]?\\d+)");
 
        private readonly IEnumerator<string> tokensIterator;
 
        private bool inRange;
        private int upperRangeEndpoint;
        private int nextRangeValue;
 
        public RangeExpander(string range)
        {
            string[] tokens = range.Split(new[] { ", " }, StringSplitOptions.None);
            this.tokensIterator = new List<string>(tokens).GetEnumerator();
        }
 
        public bool HasNext()
        {
            return HasNextRangeValue() || this.tokensIterator.MoveNext();
        }
 
        private bool HasNextRangeValue()
        {
            return this.inRange && this.nextRangeValue <= this.upperRangeEndpoint;
        }
 
        public int Next()
        {
            if (!HasNext())
            {
                throw new InvalidOperationException();
            }
 
            if (HasNextRangeValue())
            {
                return this.nextRangeValue++;
            }
 
            string token = this.tokensIterator.Current;
 
            Match matcher = TOKEN_PATTERN.Match(token);
            if (matcher.Success)
            {
                this.inRange = true;
                this.upperRangeEndpoint = int.Parse(matcher.Groups[2].Value);
                this.nextRangeValue = int.Parse(matcher.Groups[1].Value);
                return this.nextRangeValue++;
            }
 
            this.inRange = false;
            return int.Parse(token);
        }
 
        public IEnumerator<int> GetEnumerator()
        {
            return this;
        }
 
        IEnumerator IEnumerable.GetEnumerator()
        {
            return GetEnumerator();
        }
 
        public void Dispose()
        {
        }
 
        public void Reset()
        {
            throw new NotSupportedException();
        }
 
        public int Current
        {
            get { return Next(); }
        }
 
        object IEnumerator.Current
        {
            get { return Current; }
        }
    }
 
    class RangeExpanderTest
    {
        public static void Main(string[] args)
        {
            RangeExpander re = new RangeExpander("-6,-3--1,3-5,7-11,14,15,17-20");
            foreach (int i in re)
            {
                Console.Write(i + " ");
            }
        }
    }
}

