using System;
using System.Data;

namespace Project.DataAccess
{
    public static class Users
    {
        public static int CreateUser(string email, string password)
        {
            return Sql.ExecuteProcedure<int>("User_Create",
                Sql.AddParameter("@Email", email),
                Sql.AddParameter("@Password", password));
        }

        public static Models.User AuthenticateUser(string email, string password)
        {
            var result = Sql.ExecuteProcedure("User_Authenticate",
                Sql.AddParameter("@Email", email),
                Sql.AddParameter("@Password", password));
            return result.Rows.Count > 0 ? Models.User.FromDataRow(result.Rows[0]) : null;
        }

        public static Models.User AuthenticateUser(string token)
        {
            var result = Sql.ExecuteProcedure("User_AuthenticateByToken",
                Sql.AddParameter("@Token", token));
            return result.Rows.Count > 0 ? Models.User.FromDataRow(result.Rows[0]) : null;
        }

        public static string CreateAuthToken(int userId, int expireDays)
        {
            return Sql.ExecuteProcedure<string>("User_CreateAuthToken",
                Sql.AddParameter("@UserId", userId),
                Sql.AddParameter("@ExpireDays", expireDays));
        }

        public static bool UpdatePassword(int userId, string newPassword)
        {
            return Sql.ExecuteProcedure<int>("User_UpdatePassword",
                Sql.AddParameter("@UserId", userId),
                Sql.AddParameter("@NewPassword", newPassword)) > 0;
        }

        public static bool UpdateEmail(int userId, string newEmail)
        {
            return Sql.ExecuteProcedure<int>("User_UpdateEmail",
                Sql.AddParameter("@UserId", userId),
                Sql.AddParameter("@NewEmail", newEmail)) > 0;
        }

        public static string GetEmail(int userId)
        {
            return Sql.ExecuteProcedure<string>("User_GetEmail",
                Sql.AddParameter("@UserId", userId)) ?? string.Empty;
        }

        public static string GetPassword(int userId)
        {
            return Sql.ExecuteProcedure<string>("User_GetPassword",
                Sql.AddParameter("@UserId", userId)) ?? string.Empty;
        }

        public static bool HasPasswords()
        {
            return Sql.ExecuteProcedure<bool>("User_HasPasswords");
        }

        public static bool HasAdmin()
        {
            return Sql.ExecuteProcedure<bool>("User_HasAdmin");
        }
    }
}

