            if (matches == null)
            {
                throw new ArgumentNullException(nameof(matches));
            }
            // Enforce read-only state for the match criteria.
            Matches = new ReadOnlyCollection<PolicyMatch>(matches);
        }
    }

    // Specialized class representing an Action element within a policy.
    public sealed class ActionElement : TargetItem
    {
        // Schema version identifier for handling versioned policy schemas.
        public string SchemaVersion { get; private set; }

        // Constructor that accepts a pre-initialized collection of match criteria.
        public ActionElement(IList<PolicyMatch> matches, string schemaVersion)
            : base(matches)
        {
            SchemaVersion = schemaVersion;
        }

        // Constructor that parses an XML representation to initialize the action element.
        public ActionElement(XmlReader reader, string schemaVersion)
            : base(ParseMatches(reader))
        {
            SchemaVersion = schemaVersion;
        }

        // Factory-like method to create an action-specific match instance.
        private static PolicyMatch CreateActionMatch(XmlReader reader)
        {
            // For demonstration, we assume that the reader is positioned at the start of a match element.
            if (reader == null)
            {
                throw new ArgumentNullException(nameof(reader));
            }

            // Read attribute "attributeId" as an example parameter.
            string attributeId = reader.GetAttribute("AttributeId") ?? "default-attribute";
            string expectedValue = reader.GetAttribute("Value") ?? "default-value";

            // Advance the reader past this element to avoid reprocessing.
            if (!reader.IsEmptyElement)
            {
                reader.Read();
            }
            else
            {
                reader.ReadStartElement();
            }

            return new ActionMatch(attributeId, expectedValue);
        }

