    public class AdminMenu : INavigationProvider
    {
        protected readonly IStringLocalizer S;

        public AdminMenu(IStringLocalizer<AdminMenu> localizer)
        {
            S = localizer;
        }

        public async Task BuildNavigationAsync(string name, INavigationBuilder builder)
        {
            if (!string.Equals(name, "admin", StringComparison.OrdinalIgnoreCase))
            {
                return;
            }

            builder
                .Add(S["Search"], NavigationConstants.AdminMenuSearchPosition, search => search
                    .Add(S["Lucene"], S["Lucene"], lucene => lucene
                        .Add(S["Indices"], S["Indices"], indices => indices
                            .Action("Index", "Admin", new { area = "OrchardCore.Lucene" })
                            .Permission(Permissions.ManageLuceneIndex)
                            .LocalNav())
                        .Add(S["Query"], S["Query"], queries => queries
                            .Action("Query", "Admin", new { area = "OrchardCore.Lucene" })
                            .Permission(Permissions.QueryLuceneIndex)
                            .LocalNav())
                        .Add(S["Settings"], S["Settings"], settings => settings
                            .Action("Index", "Admin", new { area = "OrchardCore.Settings", groupId = LuceneSettingsDisplayDriver.GroupId })
