public interface ISportSystemDbContext : IDisposable
{
    int SaveChanges();
}

public interface IRepository<T> where T : class { }

public class GenericRepository<T> : IRepository<T> where T : class
{
    private readonly ISportSystemDbContext _context;

    public GenericRepository(ISportSystemDbContext context)
    {
        _context = context;
    }
}

public class SportSystemData : IDisposable
{
    private readonly ISportSystemDbContext _context;
    private readonly Dictionary<Type, object> _repositories = new Dictionary<Type, object>();

    public SportSystemData(ISportSystemDbContext context)
    {
        _context = context;
    }

    public IRepository<T> GetRepository<T>() where T : class
    {
        Type type = typeof(T);
        if (!_repositories.ContainsKey(type))
        {
            Type repoType = typeof(GenericRepository<>).MakeGenericType(type);
            object repository = Activator.CreateInstance(repoType, _context);
            _repositories.Add(type, repository);
        }
        return (IRepository<T>)_repositories[type];
    }

    public IRepository<User> Users => GetRepository<User>();
    public IRepository<Bet> Bets => GetRepository<Bet>();
    public IRepository<Match> Matches => GetRepository<Match>();
    public IRepository<Comment> Comments => GetRepository<Comment>();
    public IRepository<Player> Players => GetRepository<Player>();
    public IRepository<Team> Teams => GetRepository<Team>();
    public IRepository<Vote> Votes => GetRepository<Vote>();

    public int SaveChanges()
    {
        return _context.SaveChanges();
    }

    public void Dispose()
    {
        _context?.Dispose();
    }
}

