using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

public interface ICommand
{
    string Execute(List<string> parameters);
}

public class CreateSprinterCommand : ICommand
{
    private readonly Committee _committee;
    private readonly OlympicsFactory _factory;

    public CreateSprinterCommand(Committee committee, OlympicsFactory factory)
    {
        _committee = committee;
        _factory = factory;
    }

    public string Execute(List<string> parameters)
    {
        if (parameters == null || parameters.Count < 4)
            throw new ArgumentException("Invalid parameters");

        string firstName = parameters[0];
        string lastName = parameters[1];
        string country = parameters[2];

        ValidateIfNull(firstName, "First name");
        ValidateIfNull(lastName, "Last name");
        ValidateIfNull(country, "Country");

        ValidateMinAndMaxLength(firstName, 2, 50, "First name");
        ValidateMinAndMaxLength(lastName, 2, 50, "Last name");
        ValidateMinAndMaxLength(country, 2, 50, "Country");

        var records = new Dictionary<string, double>();
        for (int i = 3; i < parameters.Count; i++)
        {
            var recordParts = parameters[i].Split('/');
            if (recordParts.Length == 2 && double.TryParse(recordParts[1], out double time))
            {
                records[recordParts[0]] = time;
            }
        }

        var sprinter = _factory.CreateSprinter(firstName, lastName, country, records);
        _committee.Olympians.Add(sprinter);

        return $"Sprinter {firstName} {lastName} from {country} created with records: {string.Join(", ", records.Select(r => $"{r.Key}m/{r.Value}s"))}";
    }

    private void ValidateIfNull(string value, string parameterName)
    {
        if (string.IsNullOrEmpty(value))
            throw new ArgumentNullException(parameterName);
    }

    private void ValidateMinAndMaxLength(string value, int minLength, int maxLength, string parameterName)
    {
        if (value.Length < minLength || value.Length > maxLength)
            throw new ArgumentOutOfRangeException(parameterName, $"{parameterName} must be between {minLength} and {maxLength} characters.");
    }
}

