using Microsoft.AspNetCore.Identity;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

public static class IdentityExtensions
{
    public static IServiceCollection UseSelfIdentity(this IServiceCollection services)
    {
        // Register custom user and role stores
        services.AddScoped<IUserStore<AppUser>, UserStore<AppUser>>();
        services.AddScoped<IRoleStore<AppUserRole>, RoleStore<AppUserRole>>();

        // Register custom validators
        services.AddScoped<IUserValidator<AppUser>, AppUserValidator>();
        services.AddScoped<IPasswordValidator<AppUser>, AppUserPasswordValidator>();

        // Register key normalizer and error describer
        services.AddScoped<ILookupNormalizer, KeyNormalizer>();
        services.AddScoped<IdentityErrorDescriber>();

        // Register UserManager with a factory method
        services.AddScoped<UserManager<AppUser>>(sp => CreateUserManager(sp));

        return services;
    }

    private static UserManager<AppUser> CreateUserManager(IServiceProvider serviceProvider)
    {
        var options = serviceProvider.GetRequiredService<IOptions<IdentityOptions>>();
        var userStore = serviceProvider.GetRequiredService<IUserStore<AppUser>>();
        var roleStore = serviceProvider.GetRequiredService<IRoleStore<AppUserRole>>();
        var userValidators = serviceProvider.GetServices<IUserValidator<AppUser>>();
        var passwordValidators = serviceProvider.GetServices<IPasswordValidator<AppUser>>();
        var lookupNormalizer = serviceProvider.GetRequiredService<ILookupNormalizer>();
        var errorDescriber = serviceProvider.GetRequiredService<IdentityErrorDescriber>();
        var logger = serviceProvider.GetRequiredService<ILogger<UserManager<AppUser>>>();

        var userManager = new UserManager<AppUser>(
            userStore,
            options,
            new PasswordHasher<AppUser>(),
            userValidators,
            passwordValidators,
            lookupNormalizer,
            errorDescriber,
            serviceProvider,
            logger
        );

        return userManager;
    }
}

