namespace AlloySampleAzure.Helpers
{
    /// <summary>
    /// Provides extension methods for categorizable content
    /// </summary>
    /// <remarks>ICategorizable content includes for example pages and blocks.</remarks>
    public static class CategorizableExtensions
    {
        /// <summary>
        /// Returns the CSS classes (if any) associated with the theme(s) of the content, as decided by its categories
        /// </summary>
        /// <param name="content"></param>
        /// <returns>CSS classes associated with the content's theme(s), or an empty string array if no theme is applicable</returns>
        /// <remarks>Content's categorization may map to more than one theme. This method assumes there are website categories called "Meet", "Track", and "Plan"</remarks>
        public static string[] GetThemeCssClassNames(this ICategorizable content)
        {
            if (content.Category == null)
            {
                return new string[0];
            }

            var cssClasses = new HashSet<string>(); // Although with some overhead, a HashSet allows us to ensure we never add a CSS class more than once
            var categoryRepository = ServiceLocator.Current.GetInstance<CategoryRepository>();

            foreach (var categoryName in content.Category.Select(category => categoryRepository.Get(category).Name.ToLower()))
            {
                switch (categoryName)
                {
                    case "meet":
                        cssClasses.Add("theme1");
                        break;
                    case "track":
                        cssClasses.Add("theme2");
                        break;
                    case "plan":
                        cssClasses.Add("theme3");
                        break;
                }
            }

            return cssClasses.ToArray();
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

public class RankingMethods
{
    private static readonly string[] input = { "44 Solomon", "42 Jason", "42 Errol", "41 Garry", "41 Bernard", "41 Barry", "39 Stephen" };

    public static void Main(string[] args)
    {
        int len = input.Length;

        var map = new SortedDictionary<string, int[]>(Comparer<string>.Create((a, b) => b.CompareTo(a)));
        for (int i = 0; i < len; i++)
        {
            string key = input[i].Split(' ')[0];
            int[] arr;
            if (!map.TryGetValue(key, out arr))
                arr = new int[] { i, 0 };
            arr[1]++;
            map[key] = arr;
        }
        int[][] groups = map.Values.ToArray();

        standardRanking(len, groups);
        modifiedRanking(len, groups);
        denseRanking(len, groups);
        ordinalRanking(len);
        fractionalRanking(len, groups);
    }

    private static void standardRanking(int len, int[][] groups)
    {
        Console.WriteLine("\nStandard ranking");
        for (int i = 0, rank = 0, group = 0; i < len; i++)
        {
            if (group < groups.Length && i == groups[group][0])
            {
                rank = i + 1;
                group++;
            }
            Console.WriteLine("{0} {1}", rank, input[i]);
        }
    }

    private static void modifiedRanking(int len, int[][] groups)
    {
        Console.WriteLine("\nModified ranking");
        for (int i = 0, rank = 0, group = 0; i < len; i++)
        {
            if (group < groups.Length && i == groups[group][0])
                rank += groups[group++][1];
            Console.WriteLine("{0} {1}", rank, input[i]);
        }
    }

    private static void denseRanking(int len, int[][] groups)
    {
        Console.WriteLine("\nDense ranking");
        for (int i = 0, rank = 0; i < len; i++)
        {
            if (rank < groups.Length && i == groups[rank][0])
                rank++;
