[TestFixture]
public class ParentWithRoutingTests : YamlTestsBase
{
    private object _body;
    private dynamic _response;

    [Test]
    public void TestParentChildRouting()
    {
        // Create index with parent-child relationship
        var createIndexResponse = this.Do(new IndicesCreate("test_index", body => body
            .Mappings(ms => ms
                .Map<dynamic>("parent_type", m => m)
                .Map<dynamic>("child_type", m => m
                    .Routing(r => r.Required(true))
                    .Parent(p => p.Type("parent_type"))
                )
            )
        ));

        Assert.IsTrue(createIndexResponse.IsValid);

        // Wait for cluster health to be green
        var clusterHealthResponse = this.Do(new ClusterHealthRequest("test_index")
        {
            WaitForStatus = HealthStatus.Green,
            Timeout = "50s"
        });

        Assert.IsTrue(clusterHealthResponse.IsValid);

        // Index a parent document
        var parentDoc = new { name = "parent_doc" };
        var indexParentResponse = this.Do(new IndexRequest<dynamic>("test_index", "parent_type", "1")
        {
            Document = parentDoc
        });

        Assert.IsTrue(indexParentResponse.IsValid);

        // Index a child document with parent and routing
        var childDoc = new { name = "child_doc" };
        var indexChildResponse = this.Do(new IndexRequest<dynamic>("test_index", "child_type", "2")
        {
            Document = childDoc,
            Parent = "1",
            Routing = "1"
        });

        Assert.IsTrue(indexChildResponse.IsValid);

        // Retrieve the child document using parent and routing
        _response = this.Do(new GetRequest("test_index", "child_type", "2")
        {
            Parent = "1",
            Routing = "1"
        });

        Assert.IsTrue(_response.IsValid);
        Assert.AreEqual("child_doc", _response.Source.name);

        // Attempt to retrieve the child document without correct parent information
        _response = this.Do(new GetRequest("test_index", "child_type", "2")
        {
            Routing = "1"
        });

        Assert.IsFalse(_response.IsValid);

        // Retrieve the child document using only correct routing information
        _response = this.Do(new GetRequest("test_index", "child_type", "2")
        {
            Routing = "1"
        });

        Assert.IsFalse(_response.IsValid);

