    public class Writer
    {
        private static string ServiceName = "MyServerService";
        private static string ServerHost = "localhost:8080";

        public static void Main(string[] args)
        {
            if (Environment.UserInteractive)
            {
                RunServer(args);
            }
            else
            {
                ServiceBase.Run(new Service());
            }
        }

        private static void RunServer(string[] args)
        {
            try
            {
                ParseArguments(args);
                Console.WriteLine($"Starting server at {ServerHost}...");
                // Initialize Server
                Server server = new Server(ServerHost);
                server.Start();

                Console.WriteLine("Server started. Press Enter to stop...");
                Console.ReadLine();

                server.Stop();
                Console.WriteLine("Server stopped.");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error: {ex.Message}");
            }
        }

        private static void ParseArguments(string[] args)
        {
            foreach (string arg in args)
            {
                if (arg.StartsWith("--host="))
                {
                    ServerHost = arg.Substring("--host=".Length);
                }
                else
                {
                    Console.WriteLine($"Unknown argument: {arg}");
                }
            }
        }

        public class Service : ServiceBase
        {
            private Server server;

            public Service()
            {
                ServiceName = Writer.ServiceName;
            }

            protected override void OnStart(string[] args)
            {
                Writer.ServerHost = "localhost:8080"; // Default or set from config
                server = new Server(Writer.ServerHost);
                server.Start();
            }

            protected override void OnStop()
            {
                server?.Stop();
            }
        }
    }

