public abstract class ParkingConstruct
{
    [JsonIgnore] public ParkingConstruct Parent { get; set; }
    public Queue<Vehicle> InQueue { get; } = new Queue<Vehicle>();
    public Queue<Vehicle> OutQueue { get; } = new Queue<Vehicle>();
    public abstract int TotalLocations { get; }
    public abstract int OpenLocations { get; }
    public abstract bool IsFull { get; }
    public abstract void Tick();
}

public class ParkingRamp : ParkingConstruct
{
    private const int GateThroughput = 15;
    public List<ParkingFloor> Floors { get; } = new List<ParkingFloor>();

    public override int TotalLocations => Floors.Sum(f => f.TotalLocations);
    public override int OpenLocations => Floors.Sum(f => f.OpenLocations);
    public override bool IsFull => Floors.All(f => f.IsFull);

    public override void Tick()
    {
        ProcessIncoming();
        Floors.ForEach(f => f.Tick());
        TransferFloorExits();
        ProcessOutgoing();
    }

    private void ProcessIncoming()
    {
        int max = (int)(GateThroughput * Simulator.Interval.TotalSeconds);
        for (int i = 0; i < max && InQueue.Count > 0; i++)
        {
            var floor = SelectFloor();
            if (floor == null) return;
            floor.InQueue.Enqueue(InQueue.Dequeue());
        }
    }

    private ParkingFloor SelectFloor()
    {
        var candidates = Floors.Where(f => !f.IsFull).ToList();
        if (candidates.Count == 0) return null;

        int totalWeight = candidates.Sum(f => f.OpenLocations);
        int random = Simulator.Random.Next(totalWeight);

        foreach (var f in candidates)
        {
            if (random < f.OpenLocations) return f;
            random -= f.OpenLocations;
        }
        return null;
    }

    private void TransferFloorExits()
    {
        foreach (var f in Floors)
            while (f.OutQueue.TryDequeue(out Vehicle v))
                OutQueue.Enqueue(v);
    }

    private void ProcessOutgoing()
    {
        int max = (int)(GateThroughput * Simulator.Interval.TotalSeconds);
        for (int i = 0; i < max && OutQueue.Count > 0; i++)
            Parent?.OutQueue.Enqueue(OutQueue.Dequeue());
    }
}

public class ParkingFloor : ParkingConstruct
{
    public int Capacity { get; set; }
    public int Occupied { get; private set; }

    public override int TotalLocations => Capacity;
    public override int OpenLocations => Capacity - Occupied - InQueue.Count;
    public override bool IsFull => OpenLocations <= 0;

