namespace CloudCommandSDK
{
    /// <summary>
    /// Represents the outcome of executing a command in cloud infrastructure,
    /// capturing exit status, output streams, and operational metadata
    /// </summary>
    [DataContract]
    public class CommandResult
    {
        private int _exitCode;
        private string _output;
        private string _error;

        /// <summary>
        /// Initializes a new instance with default values
        /// </summary>
        public CommandResult()
        {
            Metadata = new Dictionary<string, object>();
        }

        /// <summary>
        /// Initializes a new instance with execution results
        /// </summary>
        /// <param name="exitCode">Numeric status code from command termination</param>
        /// <param name="output">Content from standard output stream</param>
        /// <param name="error">Content from error output stream</param>
        public CommandResult(int exitCode, string output, string error)
        {
            _exitCode = exitCode;
            _output = output;
            _error = error;
            Metadata = new Dictionary<string, object>();
        }

        /// <summary>
        /// Numeric status code indicating command execution outcome
        /// </summary>
        [DataMember(Order = 1)]
        public int ExitCode
        {
            get => _exitCode;
            set => _exitCode = value;
        }

