using System;
 
public class Vector
{
    public static void Main()
    {
        feigenbaum();
    }
 
    public static void feigenbaum()
    {
        int maxIt = 13, maxItJ = 10;
        double a1 = 1.0, a2 = 0.0, d1 = 3.2;
        Console.WriteLine(" i       d");
        for (int i = 2; i <= maxIt; i++)
        {
            double a = a1 + (a1 - a2) / d1;
            for (int j = 1; j <= maxItJ; j++)
            {
                double x = 0.0, y = 0.0;
                for (int k = 1; k <= 1 << (uint)i; k++)
                {
                    y = 1.0 - 2.0 * y * x;
                    x = a - x * x;
                }
                a -= x / y;
            }
            double d = (a1 - a2) / (a - a1);
            Console.WriteLine("{0,2}    {1,8:F8}", i, d);
            d1 = d;
            a2 = a1;
            a1 = a;
        }
    }
}

using Microsoft.AspNet.SignalR;
using System.Collections.Concurrent;
using System.Linq;

public class AuthorisationHub : Hub
{
    private static readonly ConcurrentDictionary<string, string> _clientConnections = new ConcurrentDictionary<string, string>();

    public override System.Threading.Tasks.Task OnConnected()
    {
        string connectionId = Context.ConnectionId;
        string username = Context.User.Identity.Name;

        if (!string.IsNullOrEmpty(username))
        {
            _clientConnections[connectionId] = username;
            Clients.Caller.notify($"You've connected as {username}. Currently active count: {GetLiveConnectionsCount(username)}");
        }

        return base.OnConnected();
    }

    public override System.Threading.Tasks.Task OnReconnected()
    {
        string connectionId = Context.ConnectionId;
        string username = Context.User.Identity.Name;

        if (!string.IsNullOrEmpty(username))
        {
            _clientConnections[connectionId] = username;
            Clients.Caller.notify($"Reconnected as {username}. Currently active count: {GetLiveConnectionsCount(username)}");
        }

        return base.OnReconnected();
    }

    public override System.Threading.Tasks.Task OnDisconnected(bool stopCalled)
    {
        string connectionId = Context.ConnectionId;
        _clientConnections.TryRemove(connectionId, out _);

        return base.OnDisconnected(stopCalled);
    }

    public int GetLiveConnectionsCount(string username)
    {
        return _clientConnections.Values.Count(v => v == username);
    }

    public void Refresh()
    {
        string connectionId = Context.ConnectionId;
        if (_clientConnections.TryGetValue(connectionId, out string username))
        {
            Clients.All.notify($"{username} has refreshed the session. Active count: {GetLiveConnectionsCount(username)}");
        }
    }
}

