namespace CryptographicUtilities
{
    public class OtherCertID : Asn1Encodable
    {
        private readonly OtherHash otherCertHash;
        private readonly IssuerSerial issuerSerial;

        private OtherCertID(OtherHash certHash, IssuerSerial serial = null)
        {
            otherCertHash = certHash ?? throw new ArgumentNullException(nameof(certHash));
            issuerSerial = serial;
        }

        public static OtherCertID GetInstance(object obj)
        {
            if (obj == null)
                return null;

            if (obj is OtherCertID otherCertId)
                return otherCertId;

            if (obj is Asn1Sequence sequence)
            {
                OtherHash hash = OtherHash.GetInstance(sequence[0]);
                IssuerSerial serial = sequence.Count > 1
                    ? IssuerSerial.GetInstance(sequence[1])
                    : null;

                return new OtherCertID(hash, serial);
            }

            throw new ArgumentException("Invalid object for OtherCertID", nameof(obj));
        }

        public static OtherCertID CreateInstance(byte[] certHash, X509Name issuerName = null, DerInteger serialNumber = null)
        {
            if (certHash == null)
                throw new ArgumentNullException(nameof(certHash));

            OtherHash otherHash = OtherHash.CreateFromBytes(certHash);
            IssuerSerial issuerSerial = (issuerName != null && serialNumber != null)
                ? new IssuerSerial(issuerName, serialNumber)
                : null;

            return new OtherCertID(otherHash, issuerSerial);
        }

        public override Asn1Object ToAsn1Object()
        {
            Asn1EncodableVector vector = new Asn1EncodableVector();

            vector.Add(otherCertHash.ToAsn1Object());

            if (issuerSerial != null)
                vector.Add(issuerSerial.ToAsn1Object());

            return new DerSequence(vector);
        }

        public OtherHash GetCertHash() => otherCertHash;
        public IssuerSerial GetIssuerSerial() => issuerSerial;

        public override bool Equals(object obj)
        {
            if (obj == null || GetType() != obj.GetType())
                return false;

            OtherCertID other = (OtherCertID)obj;
            return Equals(otherCertHash, other.otherCertHash) &&
                   Equals(issuerSerial, other.issuerSerial);
        }

        public override int GetHashCode()
        {
            unchecked

