public class SpotRepository
{
    private readonly IMongoDatabase _database;
    private readonly IMapper _mapper;

    public SpotRepository(IMongoDatabase database, IMapper mapper)
    {
        _database = database;
        _mapper = mapper;
    }

    public List<string> GetAll()
    {
        // Temporary hardcoded list of surf spot names
        return new List<string> { "Pipeline", "J-Bay", "Teahupoo", "Bells Beach", "Mavericks" };
    }

    public async Task<SpotDto> GetByName(string name)
    {
        var document = await QueryDatabaseByName(name);

        if (document == null)
        {
            return null;
        }

        var spot = _mapper.Map<SpotDto>(document);

        if (spot.RecentReports == null || spot.RecentReports.Count == 0)
        {
            spot.LatestReport = await GetLatestReport();
        }

        return spot;
    }

    private async Task<BsonDocument> QueryDatabaseByName(string name)
    {
        var collection = _database.GetCollection<BsonDocument>("SurfSpots");
        var filter = Builders<BsonDocument>.Filter.Eq("Name", name);
        return await collection.Find(filter).FirstOrDefaultAsync();
    }

    private async Task<ReportDto> GetLatestReport()
    {
        var collection = _database.GetCollection<BsonDocument>("Reports");
        var sort = Builders<BsonDocument>.Sort.Descending("Date");
        var latestReport = await collection.Find(new BsonDocument()).Sort(sort).FirstOrDefaultAsync();

        return _mapper.Map<ReportDto>(latestReport);
    }
}

public class SpotDto
{
    public string Name { get; set; }
    public List<ReportDto> RecentReports { get; set; }
    public ReportDto LatestReport { get; set; }
}

public class ReportDto
{
    public string Description { get; set; }
    public DateTime Date { get; set; }
    public double WaveHeight { get; set; }
    public string Conditions { get; set; }
}

 
public class Node<T> where T : Number
{
    public T data;
    public Node<T> prev;
    public Node<T> next;
    public Node(T data, Node<T> prev = null, Node<T> next = null)
    {
        this.data = data;
        this.prev = prev;
        this.next = next;
    }
    public override string ToString()
    {
        var sb = new StringBuilder(this.data.ToString());
        var node = this.next;
        while (node!= null)
        {
            sb.Append(" -> ", node.data.ToString());
            node = node.next;
        }
        return sb.ToString();
    }
}
 
public static void Main(string[] args)
{
    var n1 = new Node<int>(1);
    var n2 = new Node<int>(2, n1);
    n1.next = n2;
    var n3 = new Node<int>(3, n2);
    n2.next = n3;
    Console.WriteLine(n1);
    Console.WriteLine(n2);
    Console.WriteLine(n3);
}

