namespace CodeAnalysis
{
    public class QualifiedMemberName
    {
        public string Name { get; }
        public string Namespace { get; }

        public QualifiedMemberName(string name, string namespaceName)
        {
            Name = name ?? throw new ArgumentNullException(nameof(name));
            Namespace = namespaceName ?? throw new ArgumentNullException(nameof(namespaceName));
        }

        public override string ToString()
        {
            return $"{Namespace}.{Name}";
        }
    }

    public class QualifiedModuleName
    {
        public string ModuleName { get; }

        public QualifiedModuleName(string moduleName)
        {
            ModuleName = moduleName ?? throw new ArgumentNullException(nameof(moduleName));
        }

        public override string ToString()
        {
            return ModuleName;
        }
    }

    public class QualifiedContext
    {
        public QualifiedMemberName MemberName { get; }
        public QualifiedModuleName ModuleName { get; }
        public ParserRuleContext ParserContext { get; }

        public QualifiedContext(QualifiedMemberName memberName, QualifiedModuleName moduleName, ParserRuleContext parserContext)
        {
            MemberName = memberName ?? throw new ArgumentNullException(nameof(memberName));
            ModuleName = moduleName ?? throw new ArgumentNullException(nameof(moduleName));
            ParserContext = parserContext ?? throw new ArgumentNullException(nameof(parserContext));
        }

        public override bool Equals(object obj)
        {
            return obj is QualifiedContext other &&
                   EqualityComparer<QualifiedMemberName>.Default.Equals(MemberName, other.MemberName) &&
                   EqualityComparer<QualifiedModuleName>.Default.Equals(ModuleName, other.ModuleName) &&
                   EqualityComparer<ParserRuleContext>.Default.Equals(ParserContext, other.ParserContext);
        }

        public override int GetHashCode()
        {
            return HashCode.Combine(MemberName, ModuleName, ParserContext);
        }

        public static bool operator ==(QualifiedContext left, QualifiedContext right)
        {
            return EqualityComparer<QualifiedContext>.Default.Equals(left, right);
        }

        public static bool operator !=(QualifiedContext left, QualifiedContext right)
        {
            return !(left == right);
        }
    }

    public class QualifiedContext<TContext> : QualifiedContext

using System;
 
    class Converter
    {
        private static string BlockCommentStrip(string commentStart, string commentEnd, string sampleText)
        {
            while (sampleText.IndexOf(commentStart) > -1 && sampleText.IndexOf(commentEnd, sampleText.IndexOf(commentStart) + commentStart.Length) > -1)
            {
                int start = sampleText.IndexOf(commentStart);
                int end = sampleText.IndexOf(commentEnd, start + commentStart.Length);
                sampleText = sampleText.Remove(
                    start,
                    (end + commentEnd.Length) - start
                    );
            }
            return sampleText;
        }
    }

