namespace RosettaMaybe
{
    // courtesy of https://www.dotnetcurry.com/patterns-practices/1510/maybe-monad-csharp
    public abstract class Maybe<T>
    {
        public sealed class Some : Maybe<T>
        {
            public Some(T value) => Value = value;
            public T Value { get; }
        }
        public sealed class None : Maybe<T> { }
    }
 
    class Utils
    {
        static Maybe<double> MonadicSquareRoot(double x)
        {
            if (x >= 0)
            {
                return new Maybe<double>.Some(Math.Sqrt(x));
            }
            else
            {
                return new Maybe<double>.None();
            }
        }
        static void Main(string[] args)
        {
            foreach (double x in new double[] { 4.0D, 8.0D, -15.0D, 16.23D, -42 })
            {
                Maybe<double> maybe = MonadicSquareRoot(x);
                if (maybe is Maybe<double>.Some some)
                {
                    Console.WriteLine($"The square root of {x} is " + some.Value);
                }
                else
                {
                    Console.WriteLine($"Square root of {x} is undefined.");
                }
            }
        }
    }
}

using System;

namespace Graphics
{
    public enum PixelFormat
    {
        RGBA8888,
        RGB888,
        RGBA4444,
        RGB565
    }

    public struct Pixel
    {
        public float Red;   // Floating-point representation of Red color component
        public float Green; // Floating-point representation of Green color component
        public float Blue;  // Floating-point representation of Blue color component
        public float Alpha; // Floating-point representation of Alpha (transparency) component

        public Pixel(float red, float green, float blue, float alpha = 1.0f)
        {
            Red = Clamp(red);
            Green = Clamp(green);
            Blue = Clamp(blue);
            Alpha = Clamp(alpha);
        }

        // Method to clamp color values between 0.0f and 1.0f
        private static float Clamp(float value)
        {
            if (value < 0.0f) return 0.0f;
            if (value > 1.0f) return 1.0f;
            return value;
        }

        // Method to convert the pixel to a compact 32-bit integer format based on PixelFormat
        public uint ToUInt32(PixelFormat format)
        {
            switch (format)
            {
                case PixelFormat.RGBA8888:
                    return (uint)((byte)(Red * 255) << 24 |
                                  (byte)(Green * 255) << 16 |
                                  (byte)(Blue * 255) << 8 |
                                  (byte)(Alpha * 255));

                case PixelFormat.RGB888:
                    return (uint)((byte)(Red * 255) << 16 |
                                  (byte)(Green * 255) << 8 |
                                  (byte)(Blue * 255));

                case PixelFormat.RGBA4444:
                    return (uint)((byte)(Red * 15) << 12 |
                                  (byte)(Green * 15) << 8 |
                                  (byte)(Blue * 15) << 4 |
                                  (byte)(Alpha * 15));

                case PixelFormat.RGB565:
                    return (uint)((byte)(Red * 31) << 11 |
                                  (byte)(Green * 63) << 5 |
                                  (byte)(Blue * 31));
                default:
                    throw new ArgumentOutOfRangeException(nameof(format), "Unsupported pixel format.");
            }
        }

        public override string ToString()
        {
            return $"Pixel(RGBA: {Red}, {Green}, {Blue}, {Alpha})";
        }
    }

