using System;
using System.Numerics;
 
public class Service
{
    public static void Main()
    {
        var result = solve_quadratic_equation(1, -1e20, 1);
        Console.WriteLine(result.Item1 + ", " + result.Item2);
    }
 
    public static Tuple<Complex, Complex> solve_quadratic_equation(double a, double b, double c)
    {
        b /= a;
        c /= a;
        double discriminant = b * b - 4 * c;
        if (discriminant < 0)
            return new Tuple<Complex, Complex>(new Complex(-b / 2, Math.Sqrt(-discriminant) / 2), new Complex(-b / 2, -Math.Sqrt(-discriminant) / 2));
 
        double root = Math.Sqrt(discriminant);
        double solution1 = (b > 0)? (-b - root) / 2 : (-b + root) / 2;
 
        return new Tuple<Complex, Complex>(solution1, c / solution1);
    }
}

