[TestFixture]
public class LiftLexEntryRepositoryEventTests
{
    private TemporaryFolder _folder;
    private LiftLexEntryRepository _repository;
    private bool _gotEventCall;

    [SetUp]
    public void Setup()
    {
        _folder = new TemporaryFolder("LiftLexEntryRepositoryEventTests");
        _repository = new LiftLexEntryRepository(Path.Combine(_folder.Path, "test.lift"));
        _gotEventCall = false;
        _repository.AfterEntryModified += OnEvent;
        _repository.AfterEntryDeleted += OnEvent;
    }

    [TearDown]
    public void Teardown()
    {
        _repository.AfterEntryModified -= OnEvent;
        _repository.AfterEntryDeleted -= OnEvent;
        _folder.Dispose();
    }

    [Test]
    public void NewEntry_ByEntry_TriggersModifiedEntryAdded()
    {
        var entry = new LexEntry();
        entry.Senses.Add(new LexSense());
        _repository.Entries.Add(entry);
        Assert.IsTrue(_gotEventCall);
    }

    [Test]
    public void ModifiedEntry_ByEntry_TriggersModifiedEntryAdded()
    {
        var entry = new LexEntry();
        entry.Senses.Add(new LexSense());
        _repository.Entries.Add(entry);
        _gotEventCall = false;
        entry.LexicalForm = new Form("test");
        Assert.IsTrue(_gotEventCall);
    }

    [Test]
    public void DeleteEntry_ById_TriggersAfterEntryDeleted()
    {
        var entry = new LexEntry();
        entry.Senses.Add(new LexSense());
        _repository.Entries.Add(entry);
        _gotEventCall = false;
        _repository.Entries.Remove(entry);
        Assert.IsTrue(_gotEventCall);
    }

    [Test]
    public void DeleteEntry_ByEntry_TriggersAfterEntryDeleted()
    {
        var entry = new LexEntry();
        entry.Senses.Add(new LexSense());
        _repository.Entries.Add(entry);
        _gotEventCall = false;
        _repository.Entries.Remove(entry);
        Assert.IsTrue(_gotEventCall);
    }

    private void OnEvent(object sender, LexEntryRepositoryEventArgs e)
    {
        _gotEventCall = true;
    }
}

using System;
using System.Collections.Generic;
using Castle.Core.Logging;

public class AlertesModelBuilder
{
    private readonly ILogger _logger;
    private readonly IAlertRepository _alertRepository;

    public AlertesModelBuilder(ILogger logger, IAlertRepository alertRepository)
    {
        _logger = logger;
        _alertRepository = alertRepository;
    }

    public AlertesViewModel BuildAlertesViewModel(Guid utilisateurID, Guid alerteID)
    {
        try
        {
            var alertes = _alertRepository.GetAlertesByUserId(utilisateurID);
            var alerteData = GetAlerteData(alerteID);

            var viewModel = new AlertesViewModel
            {
                UtilisateurID = utilisateurID,
                AlerteID = alerteID,
                Alertes = alertes,
                AlerteData = alerteData
            };

            return viewModel;
        }
        catch (Exception ex)
        {
            _logger.Error("Error building alertes view model", ex);
            return null;
        }
    }

    public AlerteResultsViewModel BuildAlerteResultsViewModel(Guid alerteID)
    {
        try
        {
            var results = _alertRepository.GetResultsByAlerteId(alerteID);

            var resultsViewModel = new AlerteResultsViewModel
            {
                AlerteID = alerteID,
                Results = results
            };

            return resultsViewModel;
        }
        catch (Exception ex)
        {
            _logger.Error("Error building alerte results view model", ex);
            return null;
        }
    }

    private Alerte GetAlerteData(Guid alerteID)
    {
        var alerteData = _alertRepository.GetAlerteById(alerteID);
        if (alerteData == null)
        {
            _logger.Warn($"No data found for alerte ID: {alerteID}");
            return new Alerte(); // return an empty Alerte object
        }

        return alerteData;
    }
}

public class AlertesViewModel
{
    public Guid UtilisateurID { get; set; }
    public Guid AlerteID { get; set; }
    public IEnumerable<Alerte> Alertes { get; set; }
    public Alerte AlerteData { get; set; }
}

