class Manager
{
    static bool happy(int n)
    {
        var m = new Dictionary<int, bool>();
        while (n > 1) {
            m[n] = true;
            int x = n, n = 0;
            while (x > 0) {
                int d = x % 10;
                n += d * d;
                x /= 10;
            }
            if (m.ContainsKey(n)) {
                return false;
            }
        }
        return true;
    }
 
static void Main()
    {
        int found = 0, n = 1;
        while (found < 8) {
            if (happy(n)) {
                Console.Write(n + " ");
                found++;
            }
            n++;
        }
        Console.WriteLine();
    }
}

