        {
            // In a real scenario, this would be a complex parse.
            // Here we simply generate a hash code as a dummy parsed value.
            int result = expression.GetHashCode();
            return new ParsedExpression(expression, result);
        }
    }

    // Implements caching of parsed expressions using weak references.
    public class ExpressionCache
    {
        // Dictionary mapping expression strings to weak references of parsed expressions.
        private Dictionary<string, WeakReference<ParsedExpression>> cache;
        private CalculationEngine calcEngine;
        private int hitCounter;

        // Thresholds for when cleanup should be triggered.
        private readonly int CleanupHitThreshold = 50;
        private readonly int CacheSizeThreshold = 100;

        public ExpressionCache()
        {
            cache = new Dictionary<string, WeakReference<ParsedExpression>>();
            calcEngine = new CalculationEngine();
            hitCounter = 0;
        }

        // Provides indexer-like access to get a parsed expression.
        public ParsedExpression this[string expression]
        {
            get
            {
                hitCounter++;

                // Check if the cache contains the expression.
                if (cache.TryGetValue(expression, out WeakReference<ParsedExpression> weakRef))
                {
                    // Try to retrieve the live parsed expression.
                    if (weakRef.TryGetTarget(out ParsedExpression parsed) && parsed != null)
                    {
                        // Return the cached live version.
                        return parsed;
                    }

