namespace MyApp.Data.Repositories
{
    public sealed class WorkspaceRepository : GenericRepository<Workspace>
    {
        public WorkspaceRepository(DbContext context) : base(context)
        {
        }

        public static Workspace Load(DbContext context, long id)
        {
            return new WorkspaceRepository(context).Load(id);
        }

        public Workspace Load(long id)
        {
            return _dbset.FirstOrDefault(w => w.Id == id);
        }

        public Workspace FindByPathMatch(string matchFilePath)
        {
            var normalizedPath = Path.GetFullPath(matchFilePath);
            var segments = normalizedPath.Split(Path.DirectorySeparatorChar);
            var currentPath = string.Empty;

            for (int i = 0; i < segments.Length; i++)
            {
                currentPath = segments.Take(i + 1).Aggregate((a, b) => a + Path.DirectorySeparatorChar + b);
                var workspace = _dbset.FirstOrDefault(w => w.VirtualSpacePath == currentPath);
                if (workspace != null)
                {
                    return workspace;
                }
            }

            currentPath = string.Empty;
            for (int i = segments.Length-1; i >=0; i--)
            {
                if(string.IsNullOrEmpty(segments[i]))
                    continue;

                currentPath = segments[i] + (string.IsNullOrEmpty(currentPath) ? "" : "\\"+currentPath );

                var workspace = _dbset.FirstOrDefault(w => w.VirtualSpacePath == currentPath);
                if (workspace != null)
                {
                    return workspace;
                }
            }

            return null;
        }
    }

