namespace WalkMatrix
{
    public class Position : IPosition
    {
        private int row;
        private int col;

        public int Col
        {
            get
            {
                return this.col;
            }

            set
            {
                this.col = value;
            }
        }

        public int Row
        {
            get
            {
                return this.row;
            }

            set
            {
                this.row = value;
            }
        }

        public Position(int row, int col)
        {
            this.Row = row;
            this.Col = col;
        }

        public IPosition getNeighbourPosition(Direction dir)
        {
            IPosition newPosition = new Position(this.Row, this.Col);

            switch (dir)
            {
                case Direction.DownRight:
                    newPosition.Row++;
                    newPosition.Col++;
                    break;
                case Direction.Down:
                    newPosition.Row++;
                    break;
                case Direction.DownLeft:
                    newPosition.Row++;
                    newPosition.Col--;
                    break;
                case Direction.Left:
                    newPosition.Col--;
                    break;
                case Direction.UpLeft:
                    newPosition.Row--;
                    newPosition.Col--;
                    break;
                case Direction.Up:
                    newPosition.Row--;
                    break;
                case Direction.UpRight:
                    newPosition.Row--;
                    newPosition.Col++;
                    break;
                case Direction.Right:
                    newPosition.Col++;
                    break;
                default:
                    throw new ArgumentException("Invalid direction.");
            }

            return newPosition;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
 
namespace HofstadterFigureFigure
{
    class HofstadterFigureFigure
    {
        readonly List<int> _r = new List<int>() {1};
        readonly List<int> _s = new List<int>();
 
        public IEnumerable<int> R()
        {
            int iR = 0;
            while (true)
            {
                if (iR >= _r.Count)
                {
                    Advance();
                }
                yield return _r[iR++];
            }
        }
 
        public IEnumerable<int> S()
        {
            int iS = 0;
            while (true)
            {
                if (iS >= _s.Count)
                {
                    Advance();
                }
                yield return _s[iS++];
            }
        }
 
        private void Advance()
        {
            int rCount = _r.Count;
            int oldR = _r[rCount - 1];
            int sVal;
 
            // Take care of first two cases specially since S won't be larger than R at that point
            switch (rCount)
            {
                case 1:
                    sVal = 2;
                    break;
                case 2:
                    sVal = 4;
                    break;
                default:
                    sVal = _s[rCount - 1];
                    break;
            }
            _r.Add(_r[rCount - 1] + sVal);
            int newR = _r[rCount];
            for (int iS = oldR + 1; iS < newR; iS++)
            {
                _s.Add(iS);
            }
        }
    }
 
    class Library
    {
        static void Main()
        {
            var hff = new HofstadterFigureFigure();
            var rs = hff.R();
            var arr = rs.Take(40).ToList();
 
            foreach(var v in arr.Take(10))
            {
                Console.WriteLine("{0}", v);
            }
 
            var hs = new HashSet<int>(arr);
            hs.UnionWith(hff.S().Take(960));
            Console.WriteLine(hs.Count == 1000 ? "Verified" : "Oops!  Something's wrong!");
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

public interface ISequenceInterpreter
{
    bool CanHandle(SequenceNode node);
    ISequenceInterpreter Clone();
}

[System.Serializable]
public class SequenceNode
{
    public string nodeType;
}

public abstract class SequenceInterpreterFactory
{
    public abstract ISequenceInterpreter CreateSequenceInterpreterFor(SequenceNode node);
}

public class SequenceInterpreterFactoryImp : SequenceInterpreterFactory
{
    private static SequenceInterpreterFactoryImp instance;
    private List<ISequenceInterpreter> sequenceInterpreters;

    private SequenceInterpreterFactoryImp()
    {
        sequenceInterpreters = new List<ISequenceInterpreter>();
        // Add predefined interpreters here
        // e.g., sequenceInterpreters.Add(new SomeConcreteInterpreter());
    }

    public static SequenceInterpreterFactoryImp Instance
    {
        get
        {
            if (instance == null)
            {
                instance = new SequenceInterpreterFactoryImp();
            }
            return instance;
        }
    }

    public void RegisterInterpreter(ISequenceInterpreter interpreter)
    {
        sequenceInterpreters.Add(interpreter);
    }

    public override ISequenceInterpreter CreateSequenceInterpreterFor(SequenceNode node)
    {
        foreach (var interpreter in sequenceInterpreters)
        {
            if (interpreter.CanHandle(node))
            {
                return interpreter.Clone();
            }
        }
        return null;
    }
}

public class SomeConcreteInterpreter : ISequenceInterpreter
{
    public bool CanHandle(SequenceNode node)
    {
        return node.nodeType == "SomeType";
    }

    public ISequenceInterpreter Clone()
    {
        return new SomeConcreteInterpreter();
    }
}

public class AnotherConcreteInterpreter : ISequenceInterpreter
{
    public bool CanHandle(SequenceNode node)
    {
        return node.nodeType == "AnotherType";
    }

    public ISequenceInterpreter Clone()
    {
        return new AnotherConcreteInterpreter();
    }
}

