using System;
using System.IO;
using System.Text;
 
public class FloatArray {
    public static void writeDat(String filename, double[] x, double[] y,
                                int xprecision, int yprecision) {
        assert x.Length == y.Length;
        StreamWriter out = new StreamWriter(filename);
        for (int i = 0; i < x.Length; i++)
            out.Write(String.Format("{0:F"+xprecision+"} {1:F"+yprecision+"}", x[i], y[i]));
        out.Close();
    }
 
    public static void Main(String[] args) {
        double[] x = {1, 2, 3, 1e11};
        double[] y = new double[x.Length];
        for (int i = 0; i < x.Length; i++)
            y[i] = Math.Sqrt(x[i]);
 
        try {
            writeDat("sqrt.dat", x, y, 3, 5);
        } catch (IOException e) {
            Console.Error.WriteLine("writeDat: exception: "+e);
        }
 
        try {
            StreamReader br = new StreamReader(new FileStream("sqrt.dat", FileMode.Open));
            String line;
            while ((line = br.ReadLine())!= null)
                Console.WriteLine(line);
        } catch (IOException e) { }
    }
}

