namespace MobileAppBackendTests
{
    // OWIN Startup class to configure HTTP server
    public class Startup
    {
        public void Configuration(IAppBuilder app)
        {
            HttpConfiguration config = new HttpConfiguration();

            // Enable attribute routing.
            config.MapHttpAttributeRoutes();

            // Enable a conventional route for table controllers.
            config.Routes.MapHttpRoute(
                name: "TablesRoute",
                routeTemplate: "tables/{controller}/{id}",
                defaults: new { id = RouteParameter.Optional }
            );

            // Optional: configure mobile app settings (simulated).
            config.SetMobileAppConfiguration(new MobileAppConfiguration());

            // Insert a message handler to add cache control headers on all responses.
            config.MessageHandlers.Insert(0, new NoCacheHandler());

            app.UseWebApi(config);
        }
    }

    // Custom message handler that adds no-cache headers to responses.
    public class NoCacheHandler : DelegatingHandler
    {
        protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
        {
            HttpResponseMessage response = await base.SendAsync(request, cancellationToken);
            if (response != null)
            {
                // Add headers to prevent caching.
                response.Headers.CacheControl = new System.Net.Http.Headers.CacheControlHeaderValue
                {
                    NoCache = true,
                    NoStore = true
                };
                response.Headers.Pragma.ParseAdd("no-cache");
            }
            return response;
        }
    }

