public class Lua_UnityEngine_JointTranslationLimits2D
{
    private JointTranslationLimits2D _limits;

    public Lua_UnityEngine_JointTranslationLimits2D()
    {
        _limits = new JointTranslationLimits2D();
    }

    public Lua_UnityEngine_JointTranslationLimits2D(float minTranslation, float maxTranslation)
    {
        _limits = new JointTranslationLimits2D
        {
            min = minTranslation,
            max = maxTranslation
        };
    }

    public float get_min()
    {
        try
        {
            return _limits.min;
        }
        catch (Exception ex)
        {
            Debug.LogError($"Error accessing min translation limit: {ex.Message}");
            return 0f;
        }
    }

    public void set_min(float value)
    {
        try
        {
            if (IsValidTranslationLimit(value))
            {
                _limits.min = value;
            }
            else
            {
                throw new ArgumentException("Invalid translation limit value");
            }
        }
        catch (Exception ex)
        {
            Debug.LogError($"Error setting min translation limit: {ex.Message}");
        }
    }

    public float get_max()
    {
        try
        {
            return _limits.max;
        }
        catch (Exception ex)
        {
            Debug.LogError($"Error accessing max translation limit: {ex.Message}");
            return 0f;
        }
    }

    public void set_max(float value)
    {
        try
        {
            if (IsValidTranslationLimit(value))
            {
                _limits.max = value;
            }
            else
            {
                throw new ArgumentException("Invalid translation limit value");
            }
        }
        catch (Exception ex)
        {
            Debug.LogError($"Error setting max translation limit: {ex.Message}");
        }
    }

    private bool IsValidTranslationLimit(float value)
    {
        return !float.IsNaN(value) &&
               !float.IsInfinity(value) &&
               value >= -1000f &&
               value <= 1000f;
    }

    public static void reg(LuaState lua)
    {
        lua.BeginClass(typeof(Lua_UnityEngine_JointTranslationLimits2D));

        lua.RegFunction("New", CreateInstance);
        lua.RegFunction("get_min", GetMin);
        lua.RegFunction("set_min", SetMin);
        lua.RegFunction("get_max", GetMax);
        lua.RegFunction("set_max", SetMax);

        lua.EndClass();
    }

