#if UNITY_EDITOR
using UnityEngine;
using System;
using System.Reflection;
using System.Collections.Generic;
using System.Diagnostics;

[AttributeUsage(AttributeTargets.Class)] public class TestClass : Attribute { }
[AttributeUsage(AttributeTargets.Method)] public class TestMethod : Attribute { }

public class UnitTestException : Exception {
    public UnitTestException(string message) : base(message) { }
}

public class UnitTestRunner : MonoBehaviour {
    private int totalTests, successfulTests, failedTests, errorTests;
    private double totalTime;

    void Start() => RunUnitTests();

    void RunUnitTests() {
        var testClasses = GetTestClasses();
        totalTests = successfulTests = failedTests = errorTests = 0;
        totalTime = 0;

        foreach (var testClass in testClasses) {
            object testInstance = Activator.CreateInstance(testClass);
            foreach (var method in testClass.GetMethods()) {
                if (method.GetCustomAttribute<TestMethod>() == null) continue;
                totalTests++;
                RunTestMethods(testInstance, method);
            }
        }

        Debug.Log($"Tests completed: {successfulTests} passed, {failedTests} failed, {errorTests} errored. Time: {totalTime:F2}s");
    }

    void RunTestMethods(object instance, MethodInfo method) {
        var timer = Stopwatch.StartNew();
        try {
            method.Invoke(instance, null);
            successfulTests++;
            Debug.Log($"<color=green>✔</color> {method.DeclaringType.Name}.{method.Name}");
        }
        catch (TargetInvocationException e) {
            HandleTestException(e.InnerException, method);
        }
        catch (Exception e) {
            HandleTestException(e, method);
        }
        finally {
            timer.Stop();
            totalTime += timer.Elapsed.TotalSeconds;
        }
    }

    void HandleTestException(Exception e, MethodInfo method) {
        if (e is UnitTestException) {
            failedTests++;
            Debug.LogWarning($"<color=yellow>✖</color> {method.Name}: {e.Message}");
        } else {
            errorTests++;
            Debug.LogError($"<color=red>⚠</color> {method.Name}: {e.GetType().Name} - {e.Message}\n{e.StackTrace}");
        }
    }

    IEnumerable<Type> GetTestClasses() {
        foreach (var assembly in AppDomain.CurrentDomain.GetAssemblies()) {
            foreach (var type in assembly.GetTypes()) {
                if (type.GetCustomAttribute<TestClass>() != null) {
                    yield return type;
                }
            }
        }
    }
}
#endif

