public class Config
{
    private string cfgFile = "conf_file.json";
    private YConfig<RasPiCameraNodeConfig> yconfig;

    public RasPiCameraNodeConfig Init()
    {
        RasPiCameraNodeConfig cfg;
        try
        {
            yconfig = YConfig<RasPiCameraNodeConfig>.Load(cfgFile);
            cfg = yconfig.Config;
            Console.WriteLine("Configuration loaded successfully from file.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Failed to load configuration from file: {ex.Message}");
            cfg = new RasPiCameraNodeConfig
            {
                FrontendServer = "http://frontend.example.com",
                APIServer = "http://api.example.com",
                LocalWebServer = "http://localhost:8080",
                UUID = Guid.NewGuid().ToString(),
                MqttBrokerHostname = "mqtt.example.com",
                MqttBrokerPort = 1883,
                MqttBrokerUseSSL = false,
                MqttBrokerUsername = "user",
                MqttBrokerPassword = "pass"
            };
            yconfig = new YConfig<RasPiCameraNodeConfig> { Config = cfg };
            yconfig.Save(cfgFile);
            Console.WriteLine("Default configuration saved to file.");
        }
        return cfg;
    }
}

public class RasPiCameraNodeConfig : IYConfigEntry
{
