    public string APIServer { get; set; }
    public string LocalWebServer { get; set; }
    public string UUID { get; set; }
    public string MqttBrokerHostname { get; set; }
    public int MqttBrokerPort { get; set; }
    public bool MqttBrokerUseSSL { get; set; }
    public string MqttBrokerUsername { get; set; }
    public string MqttBrokerPassword { get; set; }
}

public interface IYConfigEntry
{
}

public class YConfig<T> where T : IYConfigEntry
{
    public T Config { get; set; }

    public static YConfig<T> Load(string filePath)
    {
        string json = File.ReadAllText(filePath);
        return Newtonsoft.Json.JsonConvert.DeserializeObject<YConfig<T>>(json);
    }

    public void Save(string filePath)
    {
        string json = Newtonsoft.Json.JsonConvert.SerializeObject(this, Newtonsoft.Json.Formatting.Indented);
        File.WriteAllText(filePath, json);
    }
}

