public class SqlConnectionFake : ISqlConnection
{
    private bool _isOpen;
    private string _tableName;
    private List<Switch> _switches;

    public SqlConnectionFake(string tableName)
    {
        _tableName = tableName;
        _switches = new List<Switch>();
    }

    public void Open()
    {
        if (_isOpen)
        {
            throw new InvalidOperationException("Connection is already open.");
        }

        _isOpen = true;
    }

    public ISqlCommand CreateCommand(string sql)
    {
        if (!_isOpen)
        {
            throw new InvalidOperationException("Connection must be open to create a command.");
        }

        switch (sql.Trim().ToUpper())
        {
            case string cmd when cmd.StartsWith("INSERT INTO " + _tableName):
                return new InsertCommand(_switches, sql);
            case string cmd when cmd.StartsWith("SELECT FROM " + _tableName):
                return new SelectCommand(_switches, sql);
            case string cmd when cmd.StartsWith("UPDATE " + _tableName):
                return new UpdateCommand(_switches, sql);
            case string cmd when cmd.StartsWith("DELETE FROM " + _tableName):
                return new DeleteCommand(_switches, sql);
            default:
                throw new NotSupportedException("SQL command not supported.");
        }
    }

    public void Dispose()
    {
        if (_isOpen)
        {
            _isOpen = false;
        }
    }
}

