namespace Critters.Tests
{
    [TestFixture]
    public class VirtualPropertyTests : ClientTestsBase
    {
        [Test]
        public void Get_RetrievesVirtualProperties()
        {
            var savedEntity = new VirtualPropertyThing { Number = 25 };
            Save(savedEntity);

            var retrievedEntity = Client.VirtualPropertyThings.Get(savedEntity.Id);

            Assert.Multiple(() =>
            {
                Assert.That(retrievedEntity.NumberSquareRoot, Is.EqualTo(5));
                Assert.That(retrievedEntity.Rocky, Is.EqualTo("hardcoded"));
            });
        }

        [Test]
        public void Post_ComputesPersistedValueFromVirtual()
        {
            var postForm = new VirtualPropertyThingForm
            {
                NumberSquareRoot = 4,
                Rocky = "custom"
            };

            var postedEntity = Client.VirtualPropertyThings.Post(postForm);
            var dbEntity = Database.Query<VirtualPropertyThing>().First(x => x.Id == postedEntity.Id);

            Assert.Multiple(() =>
            {
                Assert.That(postedEntity.Number, Is.EqualTo(16));
                Assert.That(dbEntity.Number, Is.EqualTo(16));
                Assert.That(postedEntity.Rocky, Is.EqualTo("custom"));
            });
        }

        [Test]
        public void Query_FiltersByVirtualProperty()
        {
            new[] { 9, 16, 25 }.Select(x => new VirtualPropertyThing { Number = x }).ForEach(Save);

            var results = Client.VirtualPropertyThings.Query()
                .Where(x => x.NumberSquareRoot > 3)
                .ToList();

            Assert.Multiple(() =>
            {
                Assert.That(results, Has.Count.EqualTo(2));
                Assert.That(results.Select(x => x.Number), Is.EquivalentTo(new[] { 16, 25 }));
            });
        }
    }

    public class VirtualPropertyThingForm
    {
        public double NumberSquareRoot { get; set; }
        public string Rocky { get; set; }
    }
}

