        {
            get
            {
                if (_commands == null)
                {
                    _commands = new List<ICommand>();
                }
                return _commands;
            }
            protected set
            {
                _commands = value;
            }
        }

        public CommandBase(string name)
        {
            Name = name;
        }

        public virtual void Execute(IContainer container)
        {
            Console.WriteLine($"Executing command: {Name}");
        }
    }

