public class OfficeOnlineCollection : IEnumerable<OfficeOnlineElement>
{
    private readonly List<OfficeOnlineElement> _officeExtensions;

    public OfficeOnlineCollection(IEnumerable<OfficeOnlineElement> officeElements, string newFilePath, int cobaltFileTtl)
    {
        if (officeElements == null)
        {
            throw new ArgumentNullException(nameof(officeElements));
        }

        _officeExtensions = new List<OfficeOnlineElement>(officeElements);
        NewFilePath = newFilePath;
        CobaltFileTtl = cobaltFileTtl;
    }

    public string NewFilePath { get; }

    public int CobaltFileTtl { get; }

    public bool IsServiceEnabled => _officeExtensions.Any(e => e.IsEnabled);

    public string GetServiceUrl()
    {
        return _officeExtensions.FirstOrDefault(e => e.IsEnabled)?.Url;
    }

    public bool ContainsExtension(string extension)
    {
        return _officeExtensions.Any(e => e.Extension.Equals(extension, StringComparison.OrdinalIgnoreCase));
    }

    public int Count => _officeExtensions.Count;

    public IEnumerator<OfficeOnlineElement> GetEnumerator()
    {
        return _officeExtensions.GetEnumerator();
    }

    IEnumerator IEnumerable.GetEnumerator()
    {
        return GetEnumerator();
    }
}

