public class CoffeesController : Controller
{
    private readonly ICoffeeRepository _coffeeRepository;
    private readonly ICalculationService _calculationService;

    public CoffeesController(ICoffeeRepository coffeeRepository, ICalculationService calculationService)
    {
        _coffeeRepository = coffeeRepository ?? throw new ArgumentNullException(nameof(coffeeRepository));
        _calculationService = calculationService ?? throw new ArgumentNullException(nameof(calculationService));
    }

    public ActionResult Index()
    {
        return View(GetFilteredCoffees(null));
    }

    [HttpPost]
    public ActionResult Filter(CoffeeFilterViewModel filter)
    {
        return PartialView("_ProductList", GetFilteredCoffees(filter));
    }

    private ProductListViewModel GetFilteredCoffees(CoffeeFilterViewModel filter)
    {
        var coffees = _coffeeRepository.GetCoffees(filter);

        var productList = new ProductListViewModel
        {
            Products = coffees.Select(c => new ProductListItemViewModel
            {
                Id = c.Id,
                Name = c.Name,
                Description = c.Description,
                ImageUrl = c.ImageUrl,
                Price = _calculationService.CalculateListingPrice(c.BasePrice)
            }).ToList()
        };

        return productList;
    }
}

