namespace AccessControlPolicy
{
    public abstract class TargetItemBase
    {
        // Base class for target items
        protected TargetItemBase() { }
    }

    public class TargetMatchReadWriteCollection : List<TargetMatch>
    {
        // Collection for managing target matches
        public void AddMatch(TargetMatch match)
        {
            this.Add(match);
        }
    }

    public class TargetMatch
    {
        // Represents a match for access control
        public string MatchId { get; }

        public TargetMatch(string matchId)
        {
            MatchId = matchId;
        }
    }

    public class ActionElement : TargetItemBase
    {
        private readonly TargetMatchReadWriteCollection _matchCollection;

        public ActionElement(XmlReader reader)
            : base()
        {
            _matchCollection = new TargetMatchReadWriteCollection();
            LoadFromXml(reader);
        }

        public ActionElement(TargetMatchReadWriteCollection matches)
            : base()
        {
            _matchCollection = matches ?? throw new ArgumentNullException(nameof(matches));
        }

        private void LoadFromXml(XmlReader reader)
        {
            if (reader == null)
            {
                throw new ArgumentNullException(nameof(reader));
            }

            while (reader.Read())
            {
                if (reader.NodeType == XmlNodeType.Element && reader.Name == "Match")
                {
                    var matchInstance = CreateMatchInstance(reader);
                    _matchCollection.AddMatch(matchInstance);
                }
            }
        }

        private TargetMatch CreateMatchInstance(XmlReader reader)
        {
            if (reader == null) throw new ArgumentNullException(nameof(reader));

            string matchId = reader.GetAttribute("MatchId");
            return new TargetMatch(matchId);
        }

        public IReadOnlyList<TargetMatch> Matches => _matchCollection.AsReadOnly();

        // Makes the ActionElement immutable post-creation
        public void AddMatch(TargetMatch match)
        {
            throw new InvalidOperationException("ActionElement is read-only and cannot be modified.");
        }

        // Other potential methods to retrieve action details
        public override string ToString()
        {
            return $"ActionElement with {_matchCollection.Count} matches.";
        }
    }
}

using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;

public class EventNameCodeMapping
{
    private readonly ConcurrentDictionary<int, Type> EventTypeCodeMappings = new();
    private readonly object Locker = new();

    public bool TryGetEventType(int typeCode, out Type eventType)
    {
        return EventTypeCodeMappings.TryGetValue(typeCode, out eventType);
    }

    public bool TryGetEventTypeCode(Type eventType, out int typeCode)
    {
        var kvp = EventTypeCodeMappings.FirstOrDefault(k => k.Value == eventType);
        typeCode = kvp.Key;

        return !EqualityComparer<int>.Default.Equals(typeCode, default);
    }

    public bool RegisterEventType(int typeCode, Type eventType)
    {
        if (!IsEventType(eventType))
            throw new ArgumentException("Provided type is not a valid event type.", nameof(eventType));

        lock (Locker)
        {
            if (!EventTypeCodeMappings.ContainsKey(typeCode))
            {
                return EventTypeCodeMappings.TryAdd(typeCode, eventType);
            }
        }

        return false;
    }

    public void Initialize(string assemblyName, Dictionary<int, string> typeCodeDic)
    {
        var assembly = Assembly.Load(assemblyName);
        foreach (var kvp in typeCodeDic)
        {
            var eventType = assembly.GetType(kvp.Value);
            if (eventType != null && RegisterEventType(kvp.Key, eventType))
            {
                Console.WriteLine($"Registered Event Type: {eventType.Name} with Code: {kvp.Key}");
            }
            else
            {
                Console.WriteLine($"Failed to register event type: {kvp.Value} for code: {kvp.Key}");
            }
        }
    }

    private bool IsEventType(Type type)
    {
        return typeof(IEvent).IsAssignableFrom(type) && !type.IsAbstract && type.IsClass;
    }
}

