using System;

public class EngineExtend : Engine
{
    public void ExecuteBirthCommand(string[] commandWords)
    {
        if (commandWords.Length < 3)
        {
            base.ExecuteBirthCommand(commandWords);
            return;
        }

        string organismType = commandWords[0];
        string name = commandWords[1];
        Point location = ParseLocation(commandWords[2]);

        switch (organismType.ToLower())
        {
            case "wolf":
                Wolf wolf = new Wolf(name, location);
                AddOrganism(wolf);
                break;
            case "lion":
                Lion lion = new Lion(name, location);
                AddOrganism(lion);
                break;
            case "grass":
                Grass grass = new Grass(name, location);
                AddOrganism(grass);
                break;
            case "boar":
                Boar boar = new Boar(name, location);
                AddOrganism(boar);
                break;
            case "zombie":
                Zombie zombie = new Zombie(name, location);
                AddOrganism(zombie);
                break;
            default:
                base.ExecuteBirthCommand(commandWords);
                break;
        }
    }

    private Point ParseLocation(string locationString)
    {
        string[] coordinates = locationString.Split(',');
        if (coordinates.Length != 2)
        {
            throw new ArgumentException("Invalid location format.");
        }

        int x = int.Parse(coordinates[0]);
        int y = int.Parse(coordinates[1]);
        return new Point(x, y);
    }
}

