            new Interval { start = 2, end = 1000000, print = false },
            new Interval { start = 2, end = 10000000, print = false },
            new Interval { start = 2, end = 100000000, print = false },
            new Interval { start = 2, end = 1000000000, print = false },
        };
 
        foreach (var intv in intervals)
        {
            if (intv.start == 2)
            {
                Console.WriteLine("eban numbers up to and including {0}:", intv.end);
