public interface ITransformationContext
{
    ParameterExpression Parameter { get; }
    bool IsFinished { get; }
    void ExecuteTransformation();
}

public class TransformationContext : ITransformationContext
{
    private readonly ParameterExpression _parameter;
    private bool _isFinished;

    public TransformationContext(ParameterExpression parameter)
    {
        _parameter = parameter ?? throw new ArgumentNullException(nameof(parameter));
        _isFinished = false;
    }

    public ParameterExpression Parameter => _parameter;

    public bool IsFinished => _isFinished;

    public void ExecuteTransformation()
    {
        if (_isFinished)
        {
            throw new InvalidOperationException("Transformation has already been completed.");
        }

        // Simulate some transformation logic
        Console.WriteLine("Executing transformation on parameter: " + _parameter.Name);

        // Here you would add logic for the transformation.

        // Mark the transformation as finished
        _isFinished = true;
        Console.WriteLine("Transformation completed.");
    }
}

public class Writer
{
    public static void Main()
    {
        var param = Expression.Parameter(typeof(int), "input");
        var context = new TransformationContext(param);

        Console.WriteLine("Parameter Name: " + context.Parameter.Name);
        Console.WriteLine("Is Transformation Finished? " + context.IsFinished);

        try
        {
            context.ExecuteTransformation();
        }
        catch (InvalidOperationException ex)
        {
            Console.WriteLine("Error: " + ex.Message);
        }

        Console.WriteLine("Is Transformation Finished? " + context.IsFinished);

        // Attempt to execute again
        try
        {
            context.ExecuteTransformation();
        }
        catch (InvalidOperationException ex)
        {
            Console.WriteLine("Error: " + ex.Message);
        }
    }
}

using System;
using System.Runtime.Serialization;

namespace CustomExceptions
{
    [Serializable]
    public class CompoundException : Exception
    {
        /// <summary>
        /// Initializes a new instance of the CompoundException with a default message.
        /// </summary>
        public CompoundException() : base()
        {
        }

        /// <summary>
        /// Initializes a new instance of the CompoundException with a specified error message.
        /// </summary>
        /// <param name="aMessage">The error message that explains the reason for the exception.</param>
        public CompoundException(string aMessage) : base(aMessage)
        {
        }

        /// <summary>
        /// Initializes a new instance of the CompoundException with a specified error message
        /// and a reference to the inner exception that caused this exception.
        /// </summary>
        /// <param name="aMessage">The error message that explains the reason for the exception.</param>
        /// <param name="aCause">The exception that is the cause of the current exception.</param>
        public CompoundException(string aMessage, Exception aCause)
            : base(aMessage, aCause)
        {
        }

        /// <summary>
        /// Initializes a new instance of the CompoundException with a reference to the
        /// inner exception that is the cause of this exception.
        /// </summary>
        /// <param name="aCause">The exception that is the cause of the current exception.</param>
        public CompoundException(Exception aCause)
            : base(aCause?.Message ?? string.Empty, aCause)
        {
        }

        /// <summary>
        /// Initializes a new instance of the CompoundException with serialized data.
        /// </summary>
        /// <param name="info">The SerializationInfo that holds the serialized object data.</param>
        /// <param name="context">The StreamingContext that contains contextual information about the source or destination.</param>
        protected CompoundException(SerializationInfo info, StreamingContext context)
            : base(info, context)
        {
