using System;

public class PooledObject<TSource, TObject> : IDisposable
    where TSource : IDisposable
    where TObject : IDisposable
{
    private readonly ObjectPool<TSource, TObject> _pool;
    private bool _isDisposed;

    public TObject Value { get; }
    public int Version { get; }

    public PooledObject(ObjectPool<TSource, TObject> pool, TObject value, int version)
    {
        _pool = pool ?? throw new ArgumentNullException(nameof(pool));
        Value = value ?? throw new ArgumentNullException(nameof(value));
        Version = version;
    }

    public void Dispose()
    {
        if (_isDisposed)
        {
            return;
        }

        _isDisposed = true;

        if (Version == _pool.Version)
        {
            _pool.Return(Value);
        }
        else
        {
            Value.Dispose();
        }
    }

    ~PooledObject()
    {
        Dispose();
    }
}

public class ObjectPool<TSource, TObject>
    where TSource : IDisposable
    where TObject : IDisposable
{
    private readonly Func<TSource, TObject> _objectFactory;
    private readonly TSource _source;
    private readonly Queue<TObject> _pool = new Queue<TObject>();
    private int _version;

    public int Version => _version;

    public ObjectPool(TSource source, Func<TSource, TObject> objectFactory)
    {
        _source = source ?? throw new ArgumentNullException(nameof(source));
        _objectFactory = objectFactory ?? throw new ArgumentNullException(nameof(objectFactory));
    }

    public PooledObject<TSource, TObject> Get()
    {
        TObject obj;
        if (_pool.Count > 0)
        {
            obj = _pool.Dequeue();
        }
        else
        {
            obj = _objectFactory(_source);
        }

        return new PooledObject<TSource, TObject>(this, obj, _version);
    }

    public void Return(TObject obj)
    {
        if (obj == null)
        {
            throw new ArgumentNullException(nameof(obj));
        }

        _pool.Enqueue(obj);
    }

    public void IncrementVersion()
    {
        _version++;
    }
}

