using System;

public class Multiplier
{
    public static Func<double, double> multiplier(double n1, double n2)
    {
        return (m) => n1 * n2 * m;
    }

    public static void Main(string[] args)
    {
        double x = 2.0;
        double xi = 0.5;
        double y = 4.0;
        double yi = 0.25;
        double z = x + y;
        double zi = 1.0 / (x + y);
        double[] a = new double[] { x, y, z };
        double[] ai = new double[] { xi, yi, zi };
        double m = 0.5;
        for (int i = 0; i < a.Length; i++)
        {
            Console.WriteLine($"{multiplier(a[i], ai[i])(m)} = multiplier({a[i]}, {ai[i]})({m})");
        }
    }
}

