namespace CustomLogging
{
    // Custom layout class to format exception data
    public class RawExceptionLayout : LayoutSkeleton
    {
        public RawExceptionLayout()
        {
            // This layout doesn't require a header or footer
            IgnoresException = false;
        }

        // Override Format to create a string representation for exceptions.
        public override void Format(TextWriter writer, LoggingEvent loggingEvent)
        {
            // Check if an exception is present in the logging event
            if (loggingEvent.ExceptionObject != null)
            {
                writer.Write(FormatException(loggingEvent.ExceptionObject));
            }
            else
            {
                writer.Write(string.Empty);
            }
        }

        // Optional: override Header and Footer properties if needed.
        public override string Header
        {
            get { return string.Empty; }
        }

        public override string Footer
        {
            get { return string.Empty; }
        }

        // Converts the exception object into a readable string format.
        public string FormatException(Exception exception)
        {
            StringBuilder sb = new StringBuilder();
            sb.AppendLine("Exception Occurred:");
            sb.AppendLine(exception.Message);
            sb.AppendLine(exception.StackTrace);
            if (exception.InnerException != null)
            {
                sb.AppendLine("Inner Exception: " + exception.InnerException.Message);
                sb.AppendLine(exception.InnerException.StackTrace);
            }
            return sb.ToString();
        }
    }

