using System;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;

namespace MyNamespace.RecurringJobs
{
    public class TimeZoneInfoConverter : JsonConverter
    {
        public override bool CanConvert(Type objectType)
        {
            return objectType == typeof(TimeZoneInfo);
        }

        public override object ReadJson(JsonReader reader, Type objectType, object existingValue, JsonSerializer serializer)
        {
            if (reader.TokenType == JsonToken.Null)
            {
                return null;
            }

            // Load the time zone identifier from JSON
            string timeZoneId = JToken.Load(reader).ToString();
            if (string.IsNullOrEmpty(timeZoneId))
            {
                return null;
            }

            try
            {
                // Reconstruct TimeZoneInfo using system lookup
                return TimeZoneInfo.FindSystemTimeZoneById(timeZoneId);
            }
            catch (Exception ex)
            {
                throw new JsonSerializationException($"Error converting value '{timeZoneId}' to TimeZoneInfo.", ex);
            }
        }

        public override void WriteJson(JsonWriter writer, object value, JsonSerializer serializer)
        {
            TimeZoneInfo timeZone = value as TimeZoneInfo;
            if (timeZone != null)
            {
                // Serialize using the standard name
                writer.WriteValue(timeZone.StandardName);
            }
            else
            {
                writer.WriteNull();
            }
        }
    }

    public class ScheduledJob
    {
        [JsonConverter(typeof(TimeZoneInfoConverter))]
        public TimeZoneInfo TimeZone { get; set; }
    }

    class Vector
    {
        static void Main(string[] args)
        {
            ScheduledJob job = new ScheduledJob
            {
                TimeZone = TimeZoneInfo.Local
            };

            // Serialize the job object to JSON
            string json = JsonConvert.SerializeObject(job, Formatting.Indented);
            Console.WriteLine("Serialized JSON:");
            Console.WriteLine(json);

            // Deserialize the JSON back into a ScheduledJob object
            ScheduledJob deserializedJob = JsonConvert.DeserializeObject<ScheduledJob>(json);
            Console.WriteLine("Deserialized TimeZone Standard Name:");
            Console.WriteLine(deserializedJob.TimeZone != null ? deserializedJob.TimeZone.StandardName : "null");
        }
    }
}

