namespace Ranking
{
    class Handler
    {
        static void Main(string[] args)
        {
            var data = new List<Score>
            {
                new Score(44, "Solomon"),
                new Score(42, "Jason"),
                new Score(42, "Errol"),
                new Score(41, "Garry"),
                new Score(41, "Bernard"),
                new Score(41, "Barry"),
                new Score(39, "Stephen"),
            };
 
            Show("Standard", StandardRank);
            Show("\nModified", ModifiedRank);
            Show("\nDense", DenseRank);
            Show("\nOrdinal", OrdinalRank);
            Show("\nFractional", FractionalRank);
 
            Console.ReadLine();
        }
 
        static void Show(string name, Func<IEnumerable<Score>, IEnumerable<double>> fn)
        {
            Console.WriteLine(name + " Ranking:");
            var r = fn(data);
            foreach (var d in data)
            {
                Console.WriteLine("{0,4} - {1,2} {2}", r.First(), d.Score, d.Name);
            }
        }
 
        static IEnumerable<double> StandardRank(IEnumerable<Score> d)
        {
            var r = new List<double>();
            var k = 0;
            foreach (var score in d)
            {
                if (r.Count == 0 || r.Last()!= score.Score)
                {
                    k = r.Count + 1;
                }
                r.Add(k);
            }
            return r;
        }
 
        static IEnumerable<double> ModifiedRank(IEnumerable<Score> d)
        {
            var r = new List<double>();
            foreach (var score in d)
            {
                var k = r.Count + 1;
                for (var j = r.Count + 1; j < d.Count() && d.ElementAt(j).Score == score.Score; j++)
                {
                    k = j + 1;
                }
                r.Add(k);
            }
            return r;
        }
 
        static IEnumerable<double> DenseRank(IEnumerable<Score> d)
        {
            var r = new List<double>();
            var k = 0;
            foreach (var score in d)
            {
                if (r.Count == 0 || r.Last()!= score.Score)
                {
                    k++;
                }
                r.Add(k);
            }
            return r;
        }
 
        static IEnumerable<double> OrdinalRank(IEnumerable<Score> d)
        {
            var r = new List<double>();
            for (var i = 0; i < d.Count(); i++)
            {
                r.Add(i + 1);
            }

