using System;
using UnityEngine;
using Newtonsoft.Json;

public class Identity : MonoBehaviour
{
    public struct UserInfo
    {
        public string email;
        public string id;
        public bool signedIn;
    }

    private static Identity instance;
    private UserInfo currentUser;
    private bool isInitialized = false;

    public event Action<UserInfo> onSignInChanged;

    public static Identity Instance
    {
        get
        {
            if (instance == null)
            {
                GameObject identityObject = new GameObject("IdentityManager");
                instance = identityObject.AddComponent<Identity>();
                DontDestroyOnLoad(identityObject);
            }
            return instance;
        }
    }

    private void Awake()
    {
        if (instance != null && instance != this)
        {
            Destroy(gameObject);
            return;
        }

        instance = this;
        InitializePlatformSpecificIdentity();
    }

    private void InitializePlatformSpecificIdentity()
    {
#if UNITY_WEBGL && !UNITY_EDITOR
        RegisterSignInCallback();
#endif
        isInitialized = true;
    }

#if UNITY_WEBGL && !UNITY_EDITOR
    [System.Runtime.InteropServices.DllImport("__Internal")]
    private static extern void RegisterSignInCallback();

    [System.Runtime.InteropServices.DllImport("__Internal")]
    private static extern string GetProfileUserInfo();
#endif

    public UserInfo GetCurrentUserInfo()
    {
        if (!isInitialized)
        {
            Debug.LogWarning("Identity system not initialized.");
            return new UserInfo { signedIn = false };
        }

#if UNITY_WEBGL && !UNITY_EDITOR
        try
        {
            string userInfoJson = GetProfileUserInfo();
            currentUser = JsonConvert.DeserializeObject<UserInfo>(userInfoJson);
            return currentUser;
        }
        catch (Exception ex)
        {
            Debug.LogError($"Failed to retrieve user info: {ex.Message}");
            return new UserInfo { signedIn = false };
        }
#else
        return new UserInfo { signedIn = false };
#endif
    }

    private void OnSignInChanged(string userInfoJson)
    {
        try
        {
            currentUser = JsonConvert.DeserializeObject<UserInfo>(userInfoJson);
            onSignInChanged?.Invoke(currentUser);
        }
        catch (Exception ex)
        {
            Debug.LogError($"Sign-in state change error: {ex.Message}");
        }
    }
}

