using System;
using Org.BouncyCastle.Asn1;
using Org.BouncyCastle.Asn1.X509;
using Org.BouncyCastle.Utilities;

namespace Esf
{
    public class OtherCertID
        : Asn1Encodable
    {
        private readonly OtherHash otherCertHash;
        private readonly IssuerSerial issuerSerial;

        public static OtherCertID GetInstance(
            object obj)
        {
            if (obj == null || obj is OtherCertID)
            {
                return (OtherCertID)obj;
            }

            if (obj is Asn1Sequence)
            {
                return new OtherCertID((Asn1Sequence)obj);
            }

            throw new ArgumentException("unknown object in 'OtherCertID' factory : " + Platform.GetTypeName(obj), "obj");
        }

        private OtherCertID(
            Asn1Sequence seq)
        {
            if (seq == null)
                throw new ArgumentNullException("seq");
            if (seq.Count < 1 || seq.Count > 2)
                throw new ArgumentException("Bad sequence size: " + seq.Count);

            this.otherCertHash = OtherHash.GetInstance(seq[0].ToAsn1Object());

            if (seq.Count > 1)
            {
                this.issuerSerial = IssuerSerial.GetInstance(seq[1].ToAsn1Object());
            }
        }

        public OtherCertID(
            OtherHash otherCertHash)
            : this(otherCertHash, null)
        {
        }

        public OtherCertID(
            OtherHash otherCertHash,
            IssuerSerial issuerSerial)
        {
            if (otherCertHash == null)
                throw new ArgumentNullException("otherCertHash");

            this.otherCertHash = otherCertHash;
            this.issuerSerial = issuerSerial;
        }

        public OtherHash OtherCertHash
        {
            get { return otherCertHash; }
        }

        public IssuerSerial IssuerSerial
        {
            get { return issuerSerial; }
        }

        /**
         *  OtherCertID ::= SEQUENCE {
         *       otherCertHash  OtherHash,
         *       issuerSerial  IssuerSerial OPTIONAL }
         */
        public override Asn1Object ToAsn1Object()
        {
            Asn1EncodableVector v = new Asn1EncodableVector(2);

            v.Add(otherCertHash);

            if (issuerSerial != null)
            {
                v.Add(issuerSerial);
            }

            return new DerSequence(v);
        }
    }
}

using System;
using System.Runtime.Serialization;

[Serializable]
public class RoutePatternException : Exception
{
    public string Pattern { get; }

    public RoutePatternException(string pattern, string message)
        : base(message)
    {
        if (pattern == null)
            throw new ArgumentNullException(nameof(pattern));
        if (message == null)
            throw new ArgumentNullException(nameof(message));

        Pattern = pattern;
    }

    protected RoutePatternException(SerializationInfo info, StreamingContext context)
        : base(info, context)
    {
        if (info == null)
            throw new ArgumentNullException(nameof(info));

        Pattern = info.GetString(nameof(Pattern));
    }

    public override void GetObjectData(SerializationInfo info, StreamingContext context)
    {
        if (info == null)
            throw new ArgumentNullException(nameof(info));

        base.GetObjectData(info, context);
        info.AddValue(nameof(Pattern), Pattern);
    }
}

using System;
using System.Collections.Concurrent;
using System.Threading;

public delegate void PacketReceivedHandler(string packetData);

public class FakeNetworkSimulator
{
    // Concurrent dictionary for destination listeners.
    private ConcurrentDictionary<string, PacketReceivedHandler> listeners = new ConcurrentDictionary<string, PacketReceivedHandler>();

    // Concurrent queue for network packets.
    private ConcurrentQueue<NetworkPacket> packetQueue = new ConcurrentQueue<NetworkPacket>();

    // Timer for periodic processing.
    private Timer timer;

    // AutoResetEvent for controlling shutdown.
    private AutoResetEvent autoResetEvent = new AutoResetEvent(false);

    // Constructor starts the timer.
    public FakeNetworkSimulator()
    {
        // Initialize timer to fire every 1000 milliseconds.
        timer = new Timer(ProcessPackets, null, 1000, 1000);
    }

    // Attach a listener for a specific destination.
    public void AttachListener(string destination, PacketReceivedHandler handler)
    {
        if (!listeners.TryAdd(destination, handler))
        {
            throw new InvalidOperationException("Listener already exists for destination: " + destination);
        }
    }

    // Enqueue a new packet.
    public void SendPacket(string destination, string packetData)
    {
        NetworkPacket packet = new NetworkPacket
        {
            Destination = destination,
            Data = packetData
        };
        packetQueue.Enqueue(packet);
    }

    // Timer callback for processing queued packets.
    private void ProcessPackets(object state)
    {
        while (packetQueue.TryDequeue(out NetworkPacket packet))
        {
            if (listeners.TryGetValue(packet.Destination, out PacketReceivedHandler handler))
            {
                // Dispatch packet asynchronously.
                ThreadPool.QueueUserWorkItem((_) => handler(packet.Data));
            }
            else
            {
                // Log missing listener.
                Console.WriteLine("No listener registered for destination: " + packet.Destination);
            }
        }
    }

    // Stop processing and dispose timer.
    public void Stop()
    {
        timer.Dispose();
        autoResetEvent.Set();
    }

    // Represents a network packet.
    private class NetworkPacket
    {
        public string Destination { get; set; }
        public string Data { get; set; }
    }
}

