using AutoMapper;
using Microsoft.Azure.Management.ContainerService.Models;
using Azure.PowerShell.Kubernetes.Models;

namespace Azure.PowerShell.Kubernetes.Mapping
{
    public static class PSMapper
    {
        private static readonly IMapper _instance;
        private static readonly object _syncRoot = new object();

        static PSMapper()
        {
            var config = new MapperConfiguration(cfg =>
            {
                cfg.CreateMap<ManagedCluster, PSKubernetesCluster>()
                    .ForMember(dest => dest.NodePools, opt => opt.MapFrom(src => src.AgentPoolProfiles))
                    .ForMember(dest => dest.SecretRef, opt => opt.MapFrom(src => src.KeyVaultSecretRef))
                    .ForMember(dest => dest.AdminCredentials, opt => opt.Ignore())
                    .ReverseMap()
                    .ForMember(dest => dest.AgentPoolProfiles, opt => opt.MapFrom(src => src.NodePools));

                cfg.CreateMap<AgentPoolProfile, PSContainerServiceAgentPoolProfile>()
                    .ForMember(dest => dest.NodeLabels, opt => opt.MapFrom(src => src.NodeLabels))
                    .ForMember(dest => dest.MaxPods, opt => opt.MapFrom(src => src.MaxPods))
                    .ReverseMap()
                    .ForMember(dest => dest.NodeLabels, opt => opt.MapFrom(src => src.NodeLabels));

                cfg.CreateMap<KeyVaultSecretRef, PSKeyVaultSecretRef>()
                    .ForMember(dest => dest.SecretVersion, opt => opt.MapFrom(src => src.Version))
                    .ReverseMap()
                    .ForMember(dest => dest.Version, opt => opt.MapFrom(src => src.SecretVersion));

                cfg.CreateMap<ManagedClusterServicePrincipalProfile, PSServicePrincipalProfile>()
                    .ReverseMap()
                    .ForPath(dest => dest.ClientId, opt => opt.MapFrom(src => src.ApplicationId));
            });

            config.AssertConfigurationIsValid();
            _instance = config.CreateMapper();
        }

        public static IMapper Instance
        {
            get
            {
                if (_instance == null)
                {
                    lock (_syncRoot)
                    {
                        if (_instance == null)
                        {
                            // Triggers static constructor
                        }
                    }
                }
                return _instance;
            }
        }
    }
}

