namespace Utils
{
    class Library
    {
        static void Main(string[] args)
        {
            var q = new Q(1, 2, 3, 4);
            var q1 = new Q(2, 3, 4, 5);
            var q2 = new Q(3, 4, 5, 6);
            var r = 7;
        }
    }
 
    public class Q
    {
        public double real;
        public double i;
        public double j;
        public double k;
 
        public Q(double real = 0.0, double i = 0.0, double j = 0.0, double k = 0.0)
        {
            this.real = real;
            this.i = i;
            this.j = j;
            this.k = k;
        }
 
        public Q conjugate()
        {
            return new Q(this.real, -this.i, -this.j, -this.k);
        }
 
        public double _norm2()
        {
            return this.real * this.real + this.i * this.i + this.j * this.j + this.k * this.k;
        }
 
        public double norm()
        {
            return Math.Sqrt(this._norm2());
        }
 
        public Q reciprocal()
        {
            var n2 = this._norm2();
            return new Q(this.real / n2, -this.i / n2, -this.j / n2, -this.k / n2);
        }
 
        public override string ToString()
        {
            return "Q(" + this.real + ", " + this.i + ", " + this.j + ", " + this.k + ")";
        }
 
        public static Q operator -(Q q)
        {
            return new Q(-q.real, -q.i, -q.j, -q.k);
        }
 
        public static Q operator +(Q q1, Q q2)
        {
            return new Q(q1.real + q2.real, q1.i + q2.i, q1.j + q2.j, q1.k + q2.k);
        }
 
        public static Q operator +(Q q, double r)
        {
            return new Q(q.real + r, q.i, q.j, q.k);
        }
 
        public static Q operator +(double r, Q q)
        {
            return new Q(q.real + r, q.i, q.j, q.k);
        }
 
        public static Q operator *(Q q1, Q q2)
        {
            return new Q(
                q1.real * q2.real - q1.i * q2.i - q1.j * q2.j - q1.k * q2.k,
                q1.real * q2.i + q1.i * q2.real + q1.j * q2.k - q1.k * q2.j,
                q1.real * q2.j - q1.i * q2.k + q1.j * q2.real + q1.k * q2.i,
                q1.real * q2.k + q1.i * q2.j - q1.j * q2.i + q1.k * q2.real);
        }
 
        public static Q operator *(Q q, double r)
        {
            return new Q(q.real * r, q.i * r, q.j * r, q.k * r);
        }
 
        public static Q operator *(double r, Q q)
        {
            return new Q(q.real * r, q.i * r, q.j * r, q.k * r);
        }

using Microsoft.Build.Evaluation;
using System.IO;

public static class AssemblyLocator
{
    private const string OutputPathProperty = "OutputPath";
    private const string TargetFrameworkProperty = "TargetFramework";
    private const string AssemblyNameProperty = "AssemblyName";

    public static string GetAssemblyForProject(string projectPath)
    {
        var pc = new ProjectCollection();
        pc.LoadSettings = ProjectLoadSettings.IgnoreMissingImports;

        using (var project = new Project(projectPath, null, null, pc))
        {
            var projectDir = Path.GetDirectoryName(projectPath);
            var outputPath = project.GetPropertyValue(OutputPathProperty);
            var framework = project.GetPropertyValue(TargetFrameworkProperty);
            var name = project.GetPropertyValue(AssemblyNameProperty);

            if (string.IsNullOrEmpty(name))
                name = Path.GetFileNameWithoutExtension(projectPath);

            if (!string.IsNullOrEmpty(outputPath) && !string.IsNullOrEmpty(framework))
            {
                var fullOutput = Path.GetFullPath(Path.Combine(projectDir, outputPath));
                return Path.Combine(fullOutput, $"{name}.dll");
            }

            return GetOutputDll(projectDir, framework, name);
        }
    }

    private static string GetOutputDll(string projectDir, string framework, string name)
    {
        framework = string.IsNullOrEmpty(framework) ? "net6.0" : framework;
        var fallbackPath = Path.Combine(projectDir, "bin", "Debug", framework);
        return Path.Combine(fallbackPath, $"{name}.dll");
    }
}

