public class WebDAVStorageAdapterTests : StorageAdapterTestBase<WebDAVStorageAdapterFixture>
{
    public WebDAVStorageAdapterTests(WebDAVStorageAdapterFixture fixture) : base(fixture) { }

    [Theory]
    [InlineData("testfile.txt")]
    [InlineData("extensionless")]
    public async Task FileExists_ChecksExistenceCorrectly(string fileName)
    {
        if (!Path.HasExtension(fileName))
            Skip.If(true, "Adapter restricts extensionless files");

        string path = $"{Fixture.TestPath}/{fileName}";
        await Fixture.Adapter.WriteFileAsync(path, new MemoryStream());

        bool exists = await Fixture.Adapter.FileExistsAsync(path);

        Assert.True(exists);
    }

    [Theory]
    [InlineData("document.pdf")]
    public async Task GetFileInfo_RetrievesMetadata(string fileName)
    {
        string path = $"{Fixture.TestPath}/{fileName}";
        var content = new byte[] { 0x20, 0x21, 0x22 };
        await Fixture.Adapter.WriteFileAsync(path, new MemoryStream(content));

        var metadata = await Fixture.Adapter.GetFileInfoAsync(path);

        Assert.NotNull(metadata);
        Assert.Equal(content.Length, metadata.Length);
        Assert.InRange(metadata.LastModified, DateTimeOffset.UtcNow.AddMinutes(-5), DateTimeOffset.UtcNow);
    }

    [Fact]
    public async Task ContentIsNotModified_DetectsUnchangedContent()
    {
        string path = $"{Fixture.TestPath}/status.json";
        await Fixture.Adapter.WriteFileAsync(path, new MemoryStream(new byte[10]));
        var initialInfo = await Fixture.Adapter.GetFileInfoAsync(path);

        bool isModified = await Fixture.Adapter.ContentIsModifiedAsync(path, initialInfo.ETag);

        Assert.False(isModified);
    }

    [Fact]
    public async Task ContentIsModified_DetectsChanges()
    {
        string path = $"{Fixture.TestPath}/log.txt";
        await Fixture.Adapter.WriteFileAsync(path, new MemoryStream(new byte[5]));
        var originalInfo = await Fixture.Adapter.GetFileInfoAsync(path);
        await Fixture.Adapter.WriteFileAsync(path, new MemoryStream(new byte[10]));

        bool isModified = await Fixture.Adapter.ContentIsModifiedAsync(path, originalInfo.ETag);

        Assert.True(isModified);
    }
}

