namespace MessageBridge
{
    // Represents a scheduled task message that should bypass conversion.
    public class ScheduledTaskMessage { }

    // Simulated transport message carrying MSMQ data.
    public class TransportMessage
    {
        public string Body { get; set; }
        public Dictionary<string, string> Headers { get; set; }

        public TransportMessage()
        {
            Headers = new Dictionary<string, string>();
        }
    }

    // Main handler class bridging MSMQ messages to ActiveMQ.
    public class MessageBridgeHandler : IHandleMessages<object>
    {
        public void Handle(object message)
        {
            // Bypass processing for scheduled tasks.
            if (message is ScheduledTaskMessage)
            {
                Console.WriteLine("ScheduledTaskMessage received. No further processing.");
                return;
            }

            // Retrieve the transport message.
            var transportMessage = message as TransportMessage;
            if (transportMessage == null)
            {
                Console.WriteLine("Invalid message type. Processing aborted.");
                return;
            }

            // Extract message type from headers.
            string messageType = transportMessage.Headers.ContainsKey("MessageType")
                ? transportMessage.Headers["MessageType"]
                : "default";

            // Determine destination queue based on message type.
            string destinationQueue = DetermineDestinationQueue(messageType);

            // Convert the MSMQ message to an ActiveMQ text message.
            ITextMessage activeMqMessage = ConvertToActiveMqMessage(transportMessage, destinationQueue);

            // Send converted message to ActiveMQ.
            SendMessageToActiveMq(activeMqMessage, destinationQueue);
        }

        // Determines the destination queue dynamically based on the message type.
        private string DetermineDestinationQueue(string messageType)
        {
            return messageType.Equals("Priority", StringComparison.InvariantCultureIgnoreCase)
                ? "ActiveMQ.PriorityQueue"
                : "ActiveMQ.DefaultQueue";
        }

        // Converts the MSMQ transport message format into an ActiveMQ ITextMessage.
        private ITextMessage ConvertToActiveMqMessage(TransportMessage msMessage, string destination)
        {

