class CalcEngine
{
    public Expression Parse(string expression)
    {
        // Dummy implementation.  In a real scenario, this would parse the expression.
        return new Expression();
    }
}

class ExpressionCache
{
    private Dictionary<string, WeakReference> _dct = new Dictionary<string, WeakReference>();
    private CalcEngine _ce = new CalcEngine();
    private int _hitCount = 0;

    public Expression this[string expression]
    {
        get
        {
            _hitCount++;
            if (_hitCount > 100 && _dct.Count > 100)
            {
                RemoveDeadReferences();
                _hitCount = 0;
            }

            WeakReference wr;
            if (_dct.TryGetValue(expression, out wr))
            {
                Expression x = wr.Target as Expression;
                if (x != null)
                {
                    return x;
                }
            }

            Expression newExpression = _ce.Parse(expression);
            _dct[expression] = new WeakReference(newExpression);
            return newExpression;
        }
    }

    private void RemoveDeadReferences()
    {
        List<string> toRemove = new List<string>();
        foreach (KeyValuePair<string, WeakReference> kvp in _dct)
        {
            if (kvp.Value.Target == null)
            {
                toRemove.Add(kvp.Key);
            }
        }

        foreach (string key in toRemove)
        {
            _dct.Remove(key);
        }
    }
}

using FluentAssertions;
using Xunit;
