public class ConsumerTestBase
{
    protected bool ConsumerWasInvoked;
    protected string DeliveredMessageBody;
    protected string OriginalBody = "TestMessage";
    protected IBasicProperties DeliveredMessageProperties;
    protected IBasicProperties OriginalProperties;
    protected MessageInfo DeliveredMessageInfo;
    protected string ConsumerTag = "TestConsumerTag";
    protected ulong DeliverTag = 1;
    protected IModel MockChannel;

    public ConsumerTestBase()
    {
        MockChannel = Substitute.For<IModel>();
        AdditionalSetUp();
    }

    protected void AdditionalSetUp()
    {
        StartConsumer();
        DeliverMessage();
    }

    protected void StartConsumer()
    {
        var consumer = new EventingBasicConsumer(MockChannel);
        consumer.Received += (model, ea) =>
        {
            ConsumerWasInvoked = true;
            DeliveredMessageBody = Encoding.UTF8.GetString(ea.Body.ToArray());
            DeliveredMessageProperties = ea.BasicProperties;
            DeliveredMessageInfo = new MessageInfo
            {
                ConsumerTag = ea.ConsumerTag,
                DeliveryTag = ea.DeliveryTag,
                Exchange = ea.Exchange,
                RoutingKey = ea.RoutingKey,
                Redelivered = ea.Redelivered
            };
            MockChannel.BasicAck(ea.DeliveryTag, false);
        };
    }

    protected void DeliverMessage()
    {
        var body = Encoding.UTF8.GetBytes(OriginalBody);
        OriginalProperties = MockChannel.CreateBasicProperties();
        OriginalProperties.ContentType = "text/plain";

        MockChannel.BasicConsume("queue", false, ConsumerTag, false, false, null, Arg.Any<IBasicConsumer>())
            .Returns(true);

        MockChannel.BasicPublish("exchange", "routingKey", OriginalProperties, body);
    }
}

public class MessageInfo
{
    public string ConsumerTag { get; set; }
    public ulong DeliveryTag { get; set; }
    public string Exchange { get; set; }
    public string RoutingKey { get; set; }
    public bool Redelivered { get; set; }
}

