                    .HasPerformed<Transform, IResponse>((x, response) => x
                        .From(response.GetText())
                        .To<Models.User>()
                        .Using<JsonConverter>())
                .When()
                    .Performs<HttpRequest, Models.User>((x, user) => x
                        .Method("GET")
