    static async Task Main(string[] args)
    {
        if (args.Length == 0)
        {
            Console.WriteLine("Usage: Library <script_file_path>");
            return;
        }

        string scriptFilePath = args[0];

        try
        {
            await RunBatchCommand(scriptFilePath);
        }
        catch (Exception ex)
        {
            MungLog.LogError($"An error occurred: {ex.Message}");
        }
    }

    static async Task RunBatchCommand(string scriptFilePath)
    {
        List<BatchCommand> commands = new List<BatchCommand>();

        try
        {
            foreach (string line in File.ReadLines(scriptFilePath))
            {
                if (string.IsNullOrWhiteSpace(line)) continue;

                string[] parts = line.Split(' ');
                string commandName = parts[0];
                string[] arguments = parts.Skip(1).ToArray();

                commands.Add(new BatchCommand { CommandName = commandName, Arguments = arguments });
            }

            List<Task> tasks = new List<Task>();
            foreach (var command in commands)
            {
                tasks.Add(Task.Run(() => Execute(command)));
            }

            await Task.WhenAll(tasks);
        }
        catch (FileNotFoundException)
        {
            MungLog.LogError($"Script file not found: {scriptFilePath}");
        }
        catch (Exception ex)
        {
            MungLog.LogError($"Error reading script file: {ex.Message}");
        }
    }

