public static class LanguageHelper
{
    // Constants for language codes
    public const string German = "de";
    public const string English = "en";

    // Key used to store language in session
    private const string LanguageKey = "UserPreferredLanguage";

    /// <summary>
    /// Sets the user's preferred language in the session.
    /// </summary>
    /// <param name="language">The language code to set.</param>
    public static void SetLanguage(string language)
    {
        if (HttpContext.Current != null)
        {
            AddElement(LanguageKey, language);
        }
    }

    /// <summary>
    /// Retrieves the user's preferred language from the session.
    /// Defaults to English or German based on the browser's language settings.
    /// </summary>
    /// <returns>The user's preferred language code.</returns>
    public static string GetLanguage()
    {
        if (HttpContext.Current != null)
        {
            if (HasElement(LanguageKey))
            {
                return (string)HttpContext.Current.Session[LanguageKey];
            }
            else
            {
                // Determine default language based on browser settings
                var userLanguages = HttpContext.Current.Request.UserLanguages;
                if (userLanguages != null && userLanguages.Length > 0)
                {
                    string firstLanguage = userLanguages[0].ToLower();
                    if (firstLanguage.StartsWith(German))
                    {
                        return German;
                    }
                }
            }
        }
        return English; // Default to English
    }

    /// <summary>
    /// Adds or updates an element in the session.
    /// </summary>
    /// <param name="key">The key of the session element.</param>
    /// <param name="value">The value to store in the session.</param>
    private static void AddElement(string key, object value)
    {
        if (HttpContext.Current != null)
        {
            HttpContext.Current.Session[key] = value;
        }
    }

    /// <summary>
    /// Checks if an element exists in the session.
    /// </summary>
    /// <param name="key">The key of the session element to check.</param>
    /// <returns>True if the element exists, false otherwise.</returns>
    private static bool HasElement(string key)
    {
        if (HttpContext.Current != null)
        {
            return HttpContext.Current.Session[key] != null;
        }

