public static class TaskExtensions
{
    public static async Task<T> TimeoutAfter<T>(this Task<T> task, TimeSpan timeout, CancellationToken cancellationToken = default)
    {
        if (task == null)
            throw new ArgumentNullException(nameof(task));

        if (timeout < TimeSpan.Zero)
            throw new ArgumentOutOfRangeException(nameof(timeout), "Timeout must be a non-negative TimeSpan.");

        using var timeoutTokenSource = new CancellationTokenSource();
        using var linkedTokenSource = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken, timeoutTokenSource.Token);

        var completedTask = await Task.WhenAny(task, Task.Delay(timeout, timeoutTokenSource.Token));

        if (completedTask == task)
        {
            timeoutTokenSource.Cancel(); // Cancel the timeout delay
            return await task; // Ensure we propagate any exceptions here
        }

        throw new TimeoutException("The operation has timed out.");
    }

    public static async Task TimeoutAfter(this Task task, TimeSpan timeout, CancellationToken cancellationToken = default)
    {
        if (task == null)
            throw new ArgumentNullException(nameof(task));

        if (timeout < TimeSpan.Zero)
            throw new ArgumentOutOfRangeException(nameof(timeout), "Timeout must be a non-negative TimeSpan.");

        using var timeoutTokenSource = new CancellationTokenSource();
        using var linkedTokenSource = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken, timeoutTokenSource.Token);

        var completedTask = await Task.WhenAny(task, Task.Delay(timeout, timeoutTokenSource.Token));

        if (completedTask == task)
        {
            timeoutTokenSource.Cancel(); // Cancel the timeout delay
            await task; // Ensure we propagate any exceptions here
        }
        else
        {
            throw new TimeoutException("The operation has timed out.");
        }
    }
}

