public static class WeiboAuthenticationExtensions
{
    public static IAppBuilder UseWeiboAuthentication(this IAppBuilder app, WeiboAuthenticationOptions options)
    {
        if (app == null)
        {
            throw new ArgumentNullException(nameof(app));
        }
        if (options == null)
        {
            throw new ArgumentNullException(nameof(options));
        }

        app.Use(typeof(WeiboAuthenticationMiddleware), app, options);
        return app;
    }

    public static IAppBuilder UseWeiboAuthentication(this IAppBuilder app, string appId, string appSecret)
    {
        if (app == null)
        {
            throw new ArgumentNullException(nameof(app));
        }
        if (string.IsNullOrEmpty(appId))
        {
            throw new ArgumentNullException(nameof(appId));
        }
        if (string.IsNullOrEmpty(appSecret))
        {
            throw new ArgumentNullException(nameof(appSecret));
        }

        var options = new WeiboAuthenticationOptions
        {
            AppId = appId,
            AppSecret = appSecret,
            SignInAsAuthenticationType = app.GetDefaultSignInAsAuthenticationType(),
            AuthenticationMode = AuthenticationMode.Passive
        };

        return app.UseWeiboAuthentication(options);
    }
}

public class WeiboAuthenticationOptions : AuthenticationOptions
{
    public string AppId { get; set; }
    public string AppSecret { get; set; }

    public WeiboAuthenticationOptions() : base("Weibo")
    {
        Caption = "Weibo";
        CallbackPath = new PathString("/signin-weibo");
        AuthenticationMode = AuthenticationMode.Passive;
    }
}

public class WeiboAuthenticationMiddleware : AuthenticationMiddleware<WeiboAuthenticationOptions>
{
    public WeiboAuthenticationMiddleware(OwinMiddleware next, IAppBuilder app, WeiboAuthenticationOptions options)
        : base(next, options)
    {
        if (string.IsNullOrEmpty(Options.AppId))
        {
            throw new ArgumentException("AppId must be provided");
        }
        if (string.IsNullOrEmpty(Options.AppSecret))
        {
            throw new ArgumentException("AppSecret must be provided");
        }
    }

    protected override AuthenticationHandler<WeiboAuthenticationOptions> CreateHandler()
    {
        return new WeiboAuthenticationHandler();
    }
}

