using UnityEngine;
using System.Collections;

public class TrashCanController : MonoBehaviour
{
    [Header("Material References")]
    public Material trashMaterial;
    public Renderer trashRenderer;

    [Header("Color Settings")]
    public Color inactiveColor = Color.gray;
    public Color activeColor = Color.green;

    [Header("Audio Settings")]
    public AudioSource audioSource;
    public AudioClip activationSound;
    public AudioClip deactivationSound;

    [Header("State Management")]
    private bool isReady = false;
    private bool isInteracting = false;

    [Header("Transition Parameters")]
    public float colorTransitionSpeed = 2f;
    public float emissionIntensity = 1.5f;

    private void Awake()
    {
        InitializeTrashCan();
    }

    private void InitializeTrashCan()
    {
        if (trashRenderer == null)
            trashRenderer = GetComponent<Renderer>();

        if (trashMaterial == null)
            trashMaterial = trashRenderer.material;

        SetInitialState();
    }

    private void SetInitialState()
    {
        trashMaterial.color = inactiveColor;
        trashMaterial.SetColor("_EmissionColor", Color.black);
    }

    public void TrashEvent()
    {
        if (!isInteracting)
        {
            StartCoroutine(HandleTrashInteraction());
        }
    }

    private IEnumerator HandleTrashInteraction()
    {
        isInteracting = true;
        ToggleReady();
        PlayInteractionSound();
        yield return StartCoroutine(AnimateColorTransition());
        isInteracting = false;
    }

    private void ToggleReady()
    {
        isReady = !isReady;
    }

    private void PlayInteractionSound()
    {
        AudioClip clipToPlay = isReady ? activationSound : deactivationSound;
        audioSource.PlayOneShot(clipToPlay);
    }

    private IEnumerator AnimateColorTransition()
    {
        Color targetColor = isReady ? activeColor : inactiveColor;
        Color startColor = trashMaterial.color;
        float elapsedTime = 0f;

        while (elapsedTime < colorTransitionSpeed)
        {
            trashMaterial.color = Color.Lerp(startColor, targetColor, elapsedTime / colorTransitionSpeed);
            trashMaterial.SetColor("_EmissionColor", isReady ? targetColor * emissionIntensity : Color.black);

            elapsedTime += Time.deltaTime;
            yield return null;
        }

        trashMaterial.color = targetColor;
        trashMaterial.SetColor("_EmissionColor", isReady ? targetColor * emissionIntensity : Color.black);
    }

    public bool IsTrashReady() => isReady;
}

