namespace PokerTableManagement.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class TableController : ControllerBase
    {
        private readonly CorePokerContext _context;

        public TableController(CorePokerContext context)
        {
            _context = context;
        }

        [HttpGet("{id}")]
        public async Task<ActionResult<Table>> Get(string id)
        {
            var table = await _context.Tables
                .Include(t => t.TablePlayers)
                .FirstOrDefaultAsync(t => t.PublicId == id);

            return table != null
                ? Ok(table)
                : NotFound($"Table with ID {id} not found");
        }

        [HttpPost]
        public async Task<ActionResult<Table>> Post([FromBody] TablePayload tablePayload)
        {
            if (!ModelState.IsValid)
            {
                return BadRequest(ModelState);
            }

            var player = await _context.Players
                .FirstOrDefaultAsync(p => p.Id == tablePayload.OwnerId);

            if (player == null)
            {
                return NotFound($"Player with ID {tablePayload.OwnerId} not found");
            }

            var newTable = new Table
            {
                PublicId = GenerateUniqueTableId(),
                Name = tablePayload.Name,
                CreatedAt = DateTime.UtcNow,
                Status = TableStatus.Pending
            };

            var tablePlayer = new TablePlayer
            {
                Table = newTable,
                Player = player,
                Role = PlayerRole.Owner
            };

            _context.Tables.Add(newTable);
            _context.TablePlayers.Add(tablePlayer);

            try
            {
                await _context.SaveChangesAsync();
                return CreatedAtAction(nameof(Get), new { id = newTable.PublicId }, newTable);
            }
            catch (Exception ex)
            {
                return StatusCode(500, $"Error creating table: {ex.Message}");
            }
        }

        private string GenerateUniqueTableId()
        {
            return Guid.NewGuid().ToString("N").Substring(0, 8).ToUpper();
        }
    }

    public class TablePayload
    {
        [Required]
        [StringLength(50, MinimumLength = 3)]
        public string Name { get; set; }

        [Required]

