public class UploadJobError
{
    public virtual Guid Id { get; set; }
    public virtual Guid JobGuid { get; set; }
    public virtual string ErrorMessage { get; set; }
    public virtual DateTime CreatedAt { get; set; }
}

public class BaseRepository
{
    protected ISession CurrentSession => NHibernateHelper.GetCurrentSession();
}

public class UploadJobErrorRepository : BaseRepository
{
    public void Log(Guid jobGuid, string errorMessage)
    {
        using (var transaction = CurrentSession.BeginTransaction())
        {
            try
            {
                var error = new UploadJobError
                {
                    JobGuid = jobGuid,
                    ErrorMessage = errorMessage,
                    CreatedAt = DateTime.UtcNow
                };

                CurrentSession.Save(error);
                transaction.Commit();
            }
            catch (Exception ex)
            {
                transaction.Rollback();
                // Handle exception (logging, rethrow, etc.)
                Console.WriteLine($"Error logging upload job error: {ex.Message}");
            }
        }
    }

    public void DeleteLog(Guid jobGuid)
    {
        using (var transaction = CurrentSession.BeginTransaction())
        {
            try
            {
                var query = CurrentSession.CreateQuery("from UploadJobError where JobGuid = :jobGuid");
                query.SetParameter("jobGuid", jobGuid);
                var errors = query.List<UploadJobError>();

                foreach (var error in errors)
                {
                    CurrentSession.Delete(error);
                }

                transaction.Commit();
            }
            catch (Exception ex)
            {
                transaction.Rollback();
                // Handle exception (logging, rethrow, etc.)
                Console.WriteLine($"Error deleting upload job errors: {ex.Message}");
            }
        }
    }

    public IList<UploadJobError> FindJobErrorsByJobGuid(Guid jobGuid)
    {
        try
        {
            var criteria = CurrentSession.CreateCriteria<UploadJobError>()
                                         .Add(Restrictions.Eq("JobGuid", jobGuid));

            return criteria.List<UploadJobError>();
        }
        catch (Exception ex)
        {
            // Handle exception (logging, rethrow, etc.)
            Console.WriteLine($"Error retrieving upload job errors: {ex.Message}");

