namespace Jovian.Client.Configuration
{
    public struct JovianPaths
    {
        public string RenderPath;
        public string CachePath;
        public string CompilePath;
        public string TempPath;

        public void EnsureDirectories()
        {
            try
            {
                Directory.CreateDirectory(RenderPath);
                Directory.CreateDirectory(CachePath);
                Directory.CreateDirectory(CompilePath);
                Directory.CreateDirectory(TempPath);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Directory creation error: {ex.Message}");
            }
        }
    }

    public interface FormWithLink
    {
        void InitializeLink(JovianLink link);
        void UpdateLink(object sender, EventArgs e);
    }

    public class JovianLink
    {
        public List<FormWithLink> LinkedComponents { get; private set; }

        public JovianLink()
        {
            LinkedComponents = new List<FormWithLink>();
        }

        public void RegisterComponent(FormWithLink component)
        {
            LinkedComponents.Add(component);
            component.InitializeLink(this);
        }

        public void BroadcastUpdate(object sender)
        {
            foreach (var component in LinkedComponents)
            {
                component.UpdateLink(sender, EventArgs.Empty);
            }
        }
    }

    public class JovianEnvironment
    {
        public JovianPaths Paths { get; private set; }
        public RenderServer Server { get; private set; }
        public JovianLink GlobalLink { get; private set; }

        public JovianEnvironment(string basePath)
        {
            Paths = new JovianPaths
            {
                RenderPath = Path.Combine(basePath, "render"),
                CachePath = Path.Combine(basePath, "cache"),
                CompilePath = Path.Combine(basePath, "compile"),
                TempPath = Path.Combine(basePath, "temp")
            };

            Paths.EnsureDirectories();
            Server = new RenderServer(Paths);
            GlobalLink = new JovianLink();
        }

        public void InitializeComponents()
        {
            var renderCache = new RenderCache(Paths);
            var cssCompiler = new CssCompiler(Paths);

            Server.RegisterCache(renderCache);
            Server.RegisterCompiler(cssCompiler);
        }
    }

