using System;
using System.Threading.Tasks;
using Windows.Devices.Enumeration;
using Windows.Media.Capture;
using Windows.Media.MediaProperties;
using Windows.Storage;
using Windows.UI.Xaml.Media.Imaging;

public class CameraActions
{
    public async Task<StorageFile> TakeWebCamPictureAndReturnFile(bool silentCapture = false)
    {
        try
        {
            MediaCapture mediaCapture = new MediaCapture();
            await mediaCapture.InitializeAsync();

            StorageFile capturedPhoto = null;

            if (silentCapture)
            {
                var imageProperties = ImageEncodingProperties.CreateJpeg();
                capturedPhoto = await ApplicationData.Current.TemporaryFolder
                    .CreateFileAsync($"CapturedImage_{DateTime.Now.Ticks}.jpg");

                await mediaCapture.CapturePhotoToStorageFileAsync(imageProperties, capturedPhoto);
            }
            else
            {
                var cameraCaptureUI = new CameraCaptureUI();
                cameraCaptureUI.PhotoSettings.Format = CameraCaptureUIPhotoFormat.Jpeg;
                capturedPhoto = await cameraCaptureUI.CaptureFileAsync(CameraCaptureUIMode.Photo);
            }

            return capturedPhoto;
        }
        catch (Exception ex)
        {
            // Log or handle capture exceptions
            return null;
        }
    }

    public async Task<DeviceInformation> FindCameraDeviceByPanelAsync(Windows.Devices.Enumeration.Panel desiredPanel)
    {
        var deviceInfo = await DeviceInformation.FindAllAsync(DeviceClass.VideoCapture);
        return deviceInfo.FirstOrDefault(
            device => device.EnclosureLocation?.Panel == desiredPanel
        );
    }
}

