namespace NavigationSystem
{
    public struct NavigationInfo
    {
        public string Title { get; set; }
        public string Label { get; set; }
        public bool IsEnabled { get; set; }
    }

    public abstract class NavigationNode : INotifyPropertyChanged
    {
        private bool _isSelected;
        private bool _isVisible = true;

        public string Title { get; set; }
        public bool IsSelected
        {
            get => _isSelected;
            set => SetProperty(ref _isSelected, value);
        }

        public bool IsVisible
        {
            get => _isVisible;
            set => SetProperty(ref _isVisible, value);
        }

        public event PropertyChangedEventHandler PropertyChanged;

        protected virtual void OnPropertyChanged([CallerMemberName] string propertyName = null)
        {
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
        }

        protected bool SetProperty<T>(ref T storage, T value, [CallerMemberName] string propertyName = null)
        {
            if (Equals(storage, value)) return false;
            storage = value;
            OnPropertyChanged(propertyName);
            return true;
        }

        public abstract void Selected();
        public abstract void NavigateTo();
    }

    public class ItemNavigationNode : NavigationNode
    {
        public NavigationInfo NavigationDetails { get; set; }

        public override void Selected()
        {
            IsSelected = true;
            // Additional selection logic for individual items
        }

        public override void NavigateTo()
        {
            // Navigate to specific view or context
            Console.WriteLine($"Navigating to {Title}");
        }
    }

    public class GroupNavigationNode : NavigationNode
    {
        private bool _isExpanded;

        public ObservableCollection<NavigationNode> Nodes { get; } = new ObservableCollection<NavigationNode>();

        public bool IsExpanded
        {
            get => _isExpanded;
            set
            {
                if (SetProperty(ref _isExpanded, value))
                {
                    UpdateChildVisibility();
                }
            }
        }

        private void UpdateChildVisibility()
        {
            foreach (var node in Nodes)
            {
                node.IsVisible = IsExpanded;
            }
        }

