using System.Drawing;
using System.Windows.Forms;

namespace Polyspiral
{
    class Queue
    {
        static void Main(string[] args)
        {
            // Basic function for family of Polyspirals
            // Where: rng - range (prime parameter), w2 - half of canvas width,
            //        d - direction (1 - clockwise, -1 - counter clockwise).
            void ppsp(Graphics ctx, int rng, int w2, int d)
            {
                // Note: coefficients c, it, sc, sc2, sc3 are selected to fit canvas.
                double c = Math.PI * rng, it = c / w2, sc = 2, sc2 = 50, sc3 = 0.1, t, x, y;
                Console.WriteLine("Polyspiral PARs rng,w2,d:", rng, "/", w2, "/", d);
                if (rng > 1000) { sc = sc3; }
                ctx.BeginFigure();
                for (int i = 0; i < sc2 * c; i++)
                {
                    t = it * i;
                    x = sc * t * Math.Cos(d * t) + w2; y = sc * t * Math.Sin(d * t) + w2;
                    ctx.LineTo(x, y);
                }//fend i
                ctx.Stroke();
            }
            // ******************************************
            // pspiral() - Generating and plotting Polyspirals
            void pspiral()
            {
                // Setting basic vars for canvas and inpu parameters
                var cvs = new Bitmap(640, 640);
                var ctx = Graphics.FromImage(cvs);
                var w = cvs.Width, h = cvs.Height;
                var w2 = w / 2;
                var clr = "red"; // color
                var d = 1;     // direction
                var rng = 10;   // range
                rng = Number(rng);
                ctx.FillRectangle(Brushes.White, 0, 0, w, h);
                ctx.StrokeStyle = clr;
                // Plotting spiral.
                ppsp(ctx, rng, w2, d)
            }//func end
        }
    }
}

