using System.IO;
using Elastic.Elasticsearch.Ephemeral;

public class EnsureWatcherActionConfigurationSecretsInKeystore
{
    private readonly string _keystoreFile;
    private readonly string _binary;

    public EnsureWatcherActionConfigurationSecretsInKeystore(IElasticsearchCluster cluster)
    {
        var configPath = cluster.FileSystem.ConfigPath;
        _keystoreFile = Path.Combine(configPath, "elasticsearch.keystore");
        var elasticsearchHome = cluster.FileSystem.ElasticsearchHome;
        var binaryName = "elasticsearch-keystore" + (Environment.OSVersion.Platform == PlatformID.Win32NT ? ".bat" : "");
        _binary = Path.Combine(elasticsearchHome, "bin", binaryName);
    }

    public void Run()
    {
        if (!File.Exists(_keystoreFile))
        {
            if (!ExecuteBinary("create"))
                throw new Exception("Failed to create Elasticsearch keystore.");
        }

        AddSecret("xpack.notification.slack.account.test_account.secure_url", "http://dummy.slack.webhook");
        AddSecret("xpack.notification.pagerduty.account.test_account.secure_key", "dummy_pagerduty_key");
    }

    private void AddSecret(string key, string value)
    {
        if (!ExecuteBinary($"add {key}", value))
            throw new Exception($"Failed to add secret for key: {key}");
    }

    private bool ExecuteBinary(string arguments, string input = null)
    {
        try
        {
            using (var process = new Process())
            {
                process.StartInfo = new ProcessStartInfo
                {
                    FileName = _binary,
                    Arguments = arguments,
                    RedirectStandardInput = true,
                    RedirectStandardOutput = true,
                    RedirectStandardError = true,
                    UseShellExecute = false,
                    CreateNoWindow = true
                };

                process.Start();

                if (!string.IsNullOrEmpty(input))
                {
                    process.StandardInput.Write(input);
                    process.StandardInput.Close();
                }

                var output = process.StandardOutput.ReadToEnd();
                var error = process.StandardError.ReadToEnd();

                process.WaitForExit();

                if (process.ExitCode != 0)
                {
                    Console.WriteLine($"Keystore utility error: {error}");
                    return false;
                }

                return true;
            }
        }

