namespace RosettaCode
{
    class Writer
    {
        static void Main(string[] args)
        {
            for (int i = 1; i <= 37; i++)
            {
                Console.WriteLine("chowla({0}) = {1}", i, chowla(i));
            }
            Console.WriteLine();

            int count = 1;
            int limit = 10000000;
            bool[] c = sieve(limit);
            int power = 100;
            for (int i = 3; i < limit; i += 2)
            {
                if (!c[i]) count++;
                if (i == power - 1)
                {
                    Console.WriteLine("Count of primes up to {0,-10:N0} = {1:N0}", power, count);
                    power *= 10;
                }
            }

            Console.WriteLine();
            count = 0;
            limit = 35000000;
            int i = 2;
            while (true)
            {
                int p = (1 << (i - 1)) * ((1 << i) - 1); // perfect numbers must be of this form
                if (p > limit) break;
                if (chowla(p) == p - 1)
                {
                    Console.WriteLine("{0:N0} is a perfect number", p);
                    count++;
                }
                i++;
            }
            Console.WriteLine("There are {0} perfect numbers <= 35,000,000", count);
        }

        static int chowla(int n)
        {
            if (n < 1) throw new Exception("argument must be a positive integer");
            int sum = 0;
            int i = 2;
            while (i * i <= n)
            {
                if (n % i == 0)
                {
                    int j = n / i;
                    sum += (i == j)? i : i + j;
                }
                i++;
            }
            return sum;
        }

        static bool[] sieve(int limit)
        {
            // True denotes composite, false denotes prime.
            // Only interested in odd numbers >= 3
            bool[] c = new bool[limit];
            for (int i = 3; i < limit / 3; i += 2)
            {
                if (!c[i] && chowla(i) == 0)
                {
                    for (int j = 3 * i; j < limit; j += 2 * i) c[j] = true;
                }
            }
            return c;
        }
    }
}

