using System;
 
namespace LevenshteinDistance
{
    class Cache
    {
        static int LevenshteinDistance(string s, string t)
        {
            int n = s.Length;
            int m = t.Length;
            int[,] d = new int[n + 1, m + 1];
 
        if (n == 0)
        {
        return m;
        }
 
        if (m == 0)
        {
        return n;
        }
 
            for (int i = 0; i <= n; i++)
                d[i, 0] = i;
            for (int j = 0; j <= m; j++)
                d[0, j] = j;
 
            for (int j = 1; j <= m; j++)
                for (int i = 1; i <= n; i++)
                    if (s[i - 1] == t[j - 1])
                        d[i, j] = d[i - 1, j - 1];  //no operation
                    else
                        d[i, j] = Math.Min(Math.Min(
                            d[i - 1, j] + 1,    //a deletion
                            d[i, j - 1] + 1),   //an insertion
                            d[i - 1, j - 1] + 1 //a substitution
                            );
            return d[n, m];
        }
 
        static void Main(string[] args)
        {
            if (args.Length == 2)
                Console.WriteLine("{0} -> {1} = {2}",
                    args[0], args[1], LevenshteinDistance(args[0], args[1]));
            else
                Console.WriteLine("Usage:-\n\nLevenshteinDistance <string1> <string2>");
        }
    }
}

using System;
using System.Collections.Generic;
using System.Threading.Tasks;

public interface IExecution
{
    // Property to hold the results of operations
    IList<string> Results { get; }

    // Asynchronous method to process the result of an operation
    Task ProcessResultAsync(string result);

    // Method to notify the user of ongoing operations
    void NotifyUser(string message);

    // Method for handling successful operation completion
    void OnOperationCompleted(string operationName, string result);

    // Method to handle exceptions that occur during operations
    void HandleException(Exception ex);

    // Method to manage timeouts for operations
    void OperationTimedOut(string operationName);

    // Method for pre-check logic before executing an operation
    Task<bool> PreCheckAsync();

    // Event to notify when an operation starts
    event Action<string> OperationStarted;

    // Event to notify when an operation ends
    event Action<string, string> OperationEnded;

    // Additional method to clear results
    void ClearResults();
}

public class ExecutionHandler : IExecution
{
    public IList<string> Results { get; private set; } = new List<string>();

    public event Action<string> OperationStarted;
    public event Action<string, string> OperationEnded;

    public async Task ProcessResultAsync(string result)
    {
        await Task.Run(() => Results.Add(result));
        NotifyUser($"Result processed: {result}");
    }

    public void NotifyUser(string message)
    {
        Console.WriteLine($"Notification: {message}");
    }

    public void OnOperationCompleted(string operationName, string result)
    {
        NotifyUser($"Operation '{operationName}' completed with result: {result}");
        OperationEnded?.Invoke(operationName, result);
    }

    public void HandleException(Exception ex)
    {
        NotifyUser($"An error occurred: {ex.Message}");
    }

    public void OperationTimedOut(string operationName)
    {
        NotifyUser($"Operation '{operationName}' has timed out.");
    }

    public async Task<bool> PreCheckAsync()
    {
        // Perform pre-check logic here (for demonstration, we assume it passes)
        await Task.Delay(500); // Simulate async pre-check operation
        return true;
    }

    public void ClearResults()
    {
        Results.Clear();
        NotifyUser("Results cleared.");
    }
}

