namespace Cusip
{
    class Cusip
    {
        private static bool IsCusip(string s)
        {
            if (s.Length!= 9) return false;
            int sum = 0;
            for (int i = 0; i <= 7; i++)
            {
                char c = s[i];

                int v;
                if (c >= '0' && c <= '9')
                {
                    v = c - 48;
                }
                else if (c >= 'A' && c <= 'Z')
                {
                    v = c - 55;  // lower case letters apparently invalid
                }
                else if (c == '*')
                {
                    v = 36;
                }
                else if (c == '@')
                {
                    v = 37;
                }
                else if (c == '#')
                {
                    v = 38;
                }
                else
                {
                    return false;
                }
                if (i % 2 == 1) v *= 2;  // check if odd as using 0-based indexing
                sum += v / 10 + v % 10;
            }
            return s[8] - 48 == (10 - (sum % 10)) % 10;
        }

        public static void Main(string[] args)
        {
            List<string> candidates = new List<string>
            {
                "037833100", "17275R102", "38259P508", "594918104", "68389X106", "68389X105", "EXTRACRD8",
                "EXTRACRD9", "BADCUSIP!", "683&9X106", "68389x105", "683$9X106", "68389}105", "87264ABE4"
            };
            foreach (string candidate in candidates)
            {
                Console.WriteLine($"{candidate} -> { (IsCusip(candidate)? "correct" : "incorrect")}");
            }
        }
    }
}

using System;
using System.IO;
class PPMWriter
{
    public static void WriteBitmapToPPM(string file, Bitmap bitmap)
        {
            //Use a streamwriter to write the text part of the encoding
            var writer = new StreamWriter(file);
            writer.WriteLine("P6");
            writer.WriteLine($"{bitmap.Width}  {bitmap.Height}");
            writer.WriteLine("255");
            writer.Close();
            //Switch to a binary writer to write the data
            var writerB = new BinaryWriter(new FileStream(file, FileMode.Append));
            for (int x = 0; x < bitmap.Height; x++)
                for (int y = 0; y < bitmap.Width; y++)
                {
                    Color color = bitmap.GetPixel(y, x);
                    writerB.Write(color.R);
                    writerB.Write(color.G);
                    writerB.Write(color.B);
                }
            writerB.Close();
        }
}

