using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
 
public static class Hamming
{
    private static BigInteger THREE = BigInteger.Parse("3");
    private static BigInteger FIVE = BigInteger.Parse("5");
 
    private static void updateFrontier(BigInteger x,
                                       PriorityQueue<BigInteger> pq)
    {
        pq.Enqueue(x.ShiftLeft(1));
        pq.Enqueue(x.Multiply(THREE));
        pq.Enqueue(x.Multiply(FIVE));
    }
 
    public static BigInteger hamming(int n)
    {
        if (n <= 0)
            throw new ArgumentException("Invalid parameter");
        PriorityQueue<BigInteger> frontier = new PriorityQueue<BigInteger>();
        updateFrontier(BigInteger.Parse("1"), frontier);
        BigInteger lowest = BigInteger.Parse("1");
        for (int i = 1; i < n; i++)
        {
            lowest = frontier.Dequeue();
            while (frontier.Peek().Equals(lowest))
                frontier.Dequeue();
            updateFrontier(lowest, frontier);
        }
        return lowest;
    }
 
    public static void Main(string[] args)
    {
        Console.Write("Hamming(1.. 20) =");
        for (int i = 1; i < 21; i++)
            Console.Write(" " + hamming(i));
        Console.WriteLine("\nHamming(1691) = " + hamming(1691));
        Console.WriteLine("Hamming(1000000) = " + hamming(1000000));
    }
}

