    public class SignumAuthenticationResult
    {
        public bool IsAuthenticated { get; set; }
        public string UserId { get; set; }
        public string[] Roles { get; set; }
    }

    public static async Task<SignumAuthenticationResult> ApiKeyAuthenticator(HttpActionContext context)
    {
        try
        {
            // Extract API keys from query parameters and headers
            var queryApiKey = context.Request.GetQueryNameValuePairs()
                .FirstOrDefault(q => q.Key.Equals("api_key", StringComparison.OrdinalIgnoreCase)).Value;

            var headerApiKey = context.Request.Headers
                .FirstOrDefault(h => h.Key.Equals("X-API-Key", StringComparison.OrdinalIgnoreCase)).Value?
                .FirstOrDefault();

            // Validate API key presence
            if (string.IsNullOrEmpty(queryApiKey) && string.IsNullOrEmpty(headerApiKey))
                throw new UnauthorizedAccessException("No API key provided");

            // Check for multiple API keys
            if (!string.IsNullOrEmpty(queryApiKey) && !string.IsNullOrEmpty(headerApiKey))
                throw new InvalidOperationException("Multiple API keys detected");

            var apiKey = queryApiKey ?? headerApiKey;

            // Disable standard authentication during user lookup
            using (RestApiKeyLogic.DisableAuthentication())
            {
                var user = await ValidateApiKey(apiKey);

                return new SignumAuthenticationResult
                {
                    IsAuthenticated = user != null,
                    UserId = user?.Id,
                    Roles = user?.Roles ?? Array.Empty<string>()
                };
            }
        }
        catch (Exception ex)
        {
            // Log authentication errors
            Console.WriteLine($"Authentication Error: {ex.Message}");
            return new SignumAuthenticationResult { IsAuthenticated = false };
        }
    }

