    public class ItemClickEventArgs<T> : EventArgs
    {
        public T ClickedItem { get; private set; }
        public int Position { get; private set; }

        public ItemClickEventArgs(T clickedItem, int position)
        {
            ClickedItem = clickedItem;
            Position = position;
        }
    }

    // Generic view holder for representing a file or directory item in the file picker.
    // This component enhances loose coupling between the UI and business logic by exposing events.
    public class FileItemViewHolder<T> : RecyclerView.ViewHolder
    {
        // Image display element for the file or directory icon.
        public ImageView IconImageView { get; private set; }
        // Text display element for the file or directory name.
