        // Holds the generic reference to a file or directory object.
        public T FileItem { get; set; }

        // Event triggered when the item is clicked.
        public event EventHandler<ItemClickEventArgs<T>> Click;
        // Event triggered when the item is long clicked.
        public event EventHandler<ItemClickEventArgs<T>> LongClick;

        // Constructor that initializes the view holder with the provided layout.
        public FileItemViewHolder(View itemView) : base(itemView)
        {
            // Retrieve defined UI elements from the layout resource.
            IconImageView = itemView.FindViewById<ImageView>(Resource.Id.iconImageView);
            FileNameTextView = itemView.FindViewById<TextView>(Resource.Id.fileNameTextView);

            // Set up the click event handler for the entire item view.
            itemView.Click += (sender, e) =>
            {
                if (Click != null)
                {
                    Click(this, new ItemClickEventArgs<T>(FileItem, AdapterPosition));
                }
            };

            // Set up the long-click event handler for the entire item view.
            itemView.LongClick += (sender, e) =>
            {
                if (LongClick != null)
                {
                    LongClick(this, new ItemClickEventArgs<T>(FileItem, AdapterPosition));
                }
                e.Handled = true;
            };
        }

 
using System;
 
class Lcg
{
    private long state;
 
    public Lcg(long a, long c, long m, long d, long s)
    {
        state = s;
        this.a = a;
        this.c = c;
        this.m = m;
        this.d = d;
    }
 
    public long nextInt()
    {
        state = (a * state + c) % m;
        return state / d;
    }
 
    private long a;
    private long c;
    private long m;
    private long d;
}
 
class Parser
{
    const string CARDS = "A23456789TJQK";
    const string SUITS = "♣♦♥♠";
 
    static string[] deal()
    {
        string[] cards = new string[52];
        for (int i = 0; i < 52; i++)
        {
            string card = CARDS[i / 4].ToString();
            string suit = SUITS[i % 4].ToString();
            cards[i] = card + suit;
        }
        return cards;
    }
 
    static void game(int n)
    {
        if (n <= 0)
            throw new ArgumentException("n must be greater than 0");
        Console.WriteLine("Game #{0}:", n);
        Lcg msc = new Lcg(214013, 2531011, 1L << 31, 1L << 16, n);
        string[] cards = deal();
        for (int m = 52; m >= 1; m--)
        {
            int index = (int)(msc.nextInt() % m);
            string temp = cards[index];
            cards[index] = cards[m - 1];
            Console.Write("{0}  ", temp);
            if ((53 - m) % 8 == 0)
                Console.WriteLine();
        }
        Console.WriteLine();
    }
 
    static void Main(string[] args)
    {
        game(1);
        game(617);
    }
}

