using System;
using System.Threading;
using UnityEngine;
using UniRx.Async;
using UniRx.Async.Triggers;

public static class CancellationTokenSourceExtensions
{
    public static void CancelAfterSlim(this CancellationTokenSource cts, int millisecondsDelay, bool ignoreTimeScale = false, PlayerLoopTiming delayTiming = PlayerLoopTiming.Update)
    {
        CancelAfterCore(cts, millisecondsDelay, ignoreTimeScale, delayTiming).Forget();
    }

    static async UniTaskVoid CancelAfterCore(CancellationTokenSource cts, int millisecondsDelay, bool ignoreTimeScale, PlayerLoopTiming delayTiming)
    {
        var delayTask = Delay(TimeSpan.FromMilliseconds(millisecondsDelay), ignoreTimeScale, delayTiming, cts.Token);
        var alreadyCanceled = await delayTask.SuppressCancellationThrow();
        if (!alreadyCanceled)
        {
            cts.Cancel();
            cts.Dispose();
        }
    }

    public static async UniTask<bool> Delay(TimeSpan delayTimeSpan, bool ignoreTimeScale, PlayerLoopTiming delayTiming, CancellationToken cancellationToken)
    {
        await UniTask.Delay(delayTimeSpan, ignoreTimeScale, delayTiming, cancellationToken);
        return cancellationToken.IsCancellationRequested;
    }
    public static void RegisterRaiseCancelOnDestroy(this CancellationTokenSource cts, Component component)
    {
        if (component == null || cts == null) return;
        AddCancellationTriggerOnDestory(cts, component.gameObject);
    }

    public static void RegisterRaiseCancelOnDestroy(this CancellationTokenSource cts, GameObject gameObject)
    {
        if (gameObject == null || cts == null) return;
        AddCancellationTriggerOnDestory(cts, gameObject);

    }
    private static void AddCancellationTriggerOnDestory(CancellationTokenSource cts, GameObject gameObject)
    {
        var trigger = gameObject.GetAsyncDestroyTrigger();
        trigger.OnDestroyAsync().Forget((_) =>
        {
            cts.Cancel();
            cts.Dispose();

        });
    }
}

