    public static BookmarkWordTable MappingFromNode(XmlNode node)
    {
        try
        {
            BookmarkWordTable config = new BookmarkWordTable();
            var attributes = Common.GetNodeAttributes(node);

            if (attributes.TryGetValue("Extension", out string extVal))
            {
                if (!Enum.TryParse(extVal, true, out ExtensionDirection dir))
                {
                    dir = ExtensionDirection.Right;
                }
                config.Extension = dir;
            }

            if (attributes.TryGetValue("Name", out string name))
            {
                config.Name = name;
            }

            if (attributes.TryGetValue("IsLocked", out string lockedStr))
            {
                config.IsLocked = bool.Parse(lockedStr);
            }

            return config;
        }
        catch
        {
            return null;
        }
    }

    public XmlNode MappingToNode(XmlDocument doc)
    {
        try
        {
            XmlNode node = doc.CreateElement("BookmarkWordTable");

            if (Extension != ExtensionDirection.Right)
            {
                XmlAttribute extAttr = doc.CreateAttribute("Extension");
                extAttr.Value = Extension.ToString();
                node.Attributes.Append(extAttr);
            }

            if (!string.IsNullOrEmpty(Name))
            {
                XmlAttribute nameAttr = doc.CreateAttribute("Name");
                nameAttr.Value = Name;
                node.Attributes.Append(nameAttr);
            }

            XmlAttribute lockedAttr = doc.CreateAttribute("IsLocked");
            lockedAttr.Value = IsLocked.ToString();
            node.Attributes.Append(lockedAttr);

            return node;
        }
        catch
        {
            return null;
        }
    }
}

