class Task
{
    static void Main(string[] args)
    {
        int a = Convert.ToInt32(args[0]);
        int b = Convert.ToInt32(args[1]);
 
        Console.WriteLine("{0} + {1} = {2}", a, b, a + b);
        Console.WriteLine("{0} - {1} = {2}", a, b, a - b);
        Console.WriteLine("{0} * {1} = {2}", a, b, a * b);
        Console.WriteLine("{0} / {1} = {2}", a, b, a / b); // truncates towards 0
        Console.WriteLine("{0} % {1} = {2}", a, b, a % b); // matches sign of first operand
        Console.WriteLine("{0} to the power of {1} = {2}", a, b, Math.Pow(a, b));
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace Logger
{
    class Vector3D
    {
        public double x, y, z;
        public Vector3D(double x, double y, double z)
        {
            this.x = x;
            this.y = y;
            this.z = z;
        }
        public double dot(Vector3D rhs)
        {
            return x * rhs.x + y * rhs.y + z * rhs.z;
        }
        public Vector3D operator-(Vector3D rhs)
        {
            return new Vector3D(x - rhs.x, y - rhs.y, z - rhs.z);
        }
        public Vector3D operator*(double rhs)
        {
            return new Vector3D(rhs * x, rhs * y, rhs * z);
        }
        public override string ToString()
        {
            return "(" + x + ", " + y + ", " + z + ")";
        }
    }
    class Vector
    {
        static Vector3D intersectPoint(Vector3D rayVector, Vector3D rayPoint, Vector3D planeNormal, Vector3D planePoint)
        {
            Vector3D diff = rayPoint - planePoint;
            double prod1 = diff.dot(planeNormal);
            double prod2 = rayVector.dot(planeNormal);
            double prod3 = prod1 / prod2;
            return rayPoint - rayVector * prod3;
        }
        static void Main(string[] args)
        {
            Vector3D rv = new Vector3D(0.0, -1.0, -1.0);
            Vector3D rp = new Vector3D(0.0, 0.0, 10.0);
            Vector3D pn = new Vector3D(0.0, 0.0, 1.0);
            Vector3D pp = new Vector3D(0.0, 0.0, 5.0);
            Vector3D ip = intersectPoint(rv, rp, pn, pp);
            Console.WriteLine("The ray intersects the plane at " + ip);
            Console.ReadKey();
        }
    }
}

