    // The content interface that supports categorization.
    public interface ICategorizable
    {
        IEnumerable<CategoryReference> CategoryReferences { get; }
    }

    // Extension methods for ICategorizable.
    public static class ContentExtensions
    {
        // Retrieves the CSS theme class names based on content categories.
        public static string[] GetThemeCssClassNames(this ICategorizable content)
        {
            if (content == null || content.CategoryReferences == null)
            {
                return new string[0];
            }

            // Use a HashSet to ensure unique CSS class names.
            var cssClasses = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            // Retrieve the category repository using dependency injection.
            var categoryRepository = ServiceLocator.Current.GetInstance<CategoryRepository>();

            // Process each associated category.
            foreach (var categoryRef in content.CategoryReferences)
            {
                var category = categoryRepository.Get(categoryRef);
                if (category != null && !string.IsNullOrEmpty(category.Name))
                {
                    string categoryName = category.Name.ToLowerInvariant();
                    // Map specific category names to theme CSS classes.
                    if (categoryName == "meet")
                    {
                        cssClasses.Add("theme-meet");
                    }
                    else if (categoryName == "track")
                    {
                        cssClasses.Add("theme-track");
                    }
                    else if (categoryName == "plan")
                    {
                        cssClasses.Add("theme-plan");
                    }
                }
            }

            return cssClasses.ToArray();
        }
    }

