namespace ReferenceSearchEngine
{
    public class FindReferencesSearchEngine
    {
        public async Task ProcessProjectAsync(Project project, Dictionary<Document, List<(string symbolGroup, string symbolName, object refFinder)>> documentMap, CancellationToken cancellationToken)
        {
            // Begin logging block for tracking project processing.
            using (Logger.LogBlock("ProcessProjectAsync", cancellationToken))
            {
                if (!project.SupportsCompilation)
                {
                    Console.WriteLine("The project does not support compilation.");
                    return;
                }

                // Retrieve the project's compilation asynchronously.
                Compilation compilation = await project.GetCompilationAsync(cancellationToken).ConfigureAwait(false);
                if (compilation == null)
                {
                    Console.WriteLine("Compilation retrieval failed.");
                    return;
                }

                // List to hold all the document processing tasks.
                List<Task> processingTasks = new List<Task>();

                // Iterate through each document in the mapping.
                foreach (var kvp in documentMap)
                {
                    Document document = kvp.Key;
                    // Verify the document belongs to the current project.
                    if (document.Project.Id != project.Id)
                    {
                        continue;
                    }

                    // Retrieve the document's associated processing queue.
                    List<(string symbolGroup, string symbolName, object refFinder)> documentQueue = kvp.Value;

                    // Schedule document processing on a dedicated task.
                    Task processingTask = Task.Run(() => ProcessDocumentQueueAsync(document, documentQueue, compilation, cancellationToken), cancellationToken);
                    processingTasks.Add(processingTask);
                }

                // Await all document processing tasks concurrently.
                await Task.WhenAll(processingTasks).ConfigureAwait(false);

                // Ensure compilation remains alive throughout execution.
                GC.KeepAlive(compilation);
            }
        }

