public abstract class AlphaController : MonoBehaviour
{
    protected struct alphaInfo
    {
        public float currentAlpha;
        public float targetAlpha;
        public int state; // -1: fade out, 0: idle, 1: fade in
    }

    protected Dictionary<Graphic, alphaInfo> _elements = new Dictionary<Graphic, alphaInfo>();
    public float fadeSpeed = 2f;
    public bool isInFading { get; private set; }
    public bool isBusy { get; private set; }

    public void AddUIElement(Graphic element)
    {
        if (!_elements.ContainsKey(element))
        {
            float initialAlpha = element.gameObject.activeInHierarchy ? element.canvasRenderer.GetAlpha() : 0f;
            _elements.Add(element, new alphaInfo
            {
                currentAlpha = initialAlpha,
                targetAlpha = initialAlpha,
                state = 0
            });
            element.canvasRenderer.SetAlpha(initialAlpha);
        }
    }

    public void RemoveUIElement(Graphic element)
    {
        if (_elements.ContainsKey(element))
            _elements.Remove(element);
    }

    public void Show(Graphic element)
    {
        if (_elements.ContainsKey(element))
        {
            if (!element.gameObject.activeSelf)
                element.gameObject.SetActive(true);

            alphaInfo info = _elements[element];
            info.targetAlpha = 1f;
            info.state = 1;
            _elements[element] = info;
            isInFading = true;
            isBusy = true;
        }
    }

    public void Hide(Graphic element)
    {
        if (_elements.ContainsKey(element))
        {
            alphaInfo info = _elements[element];
            info.targetAlpha = 0f;
            info.state = -1;
            _elements[element] = info;
            isInFading = true;
            isBusy = true;
        }
    }

    public IEnumerator WaitInFading() { while (isInFading) yield return null; }
    public IEnumerator WaitBusy() { while (isBusy) yield return null; }

    protected virtual void Update()
    {
        bool anyFading = false;
        List<Graphic> toRemove = new List<Graphic>();

        foreach (var kvp in _elements)
        {
            Graphic element = kvp.Key;
            alphaInfo info = kvp.Value;

            if (element == null)
            {
                toRemove.Add(element);
                continue;
            }

            if (info.state == 0 && Mathf.Approximately(info.currentAlpha, info.targetAlpha))
                continue;

