using Xenon.Tests.Integration;

namespace BrowserAutomation.IntegrationTests
{
    public abstract class BaseSwitchToWindowTests<T> where T : IBrowser, new()
    {
        protected BrowserTest browserTest;
        protected IBrowser browser;

        [SetUp]
        public void Initialize()
        {
            browser = CreateInstance();
            browserTest = new BrowserTest(browser, new XenonTestOptions
            {
                ResourceName = "SwitchBetweenMultipleWindows",
                AutoLoad = true
            });
        }

        [TearDown]
        public void Cleanup() => browserTest?.Dispose();

        protected abstract T CreateInstance();

        [Test]
        public async Task CanSwitchToNextWindow()
        {
            await browserTest
                .Click("a#googleLink")
                .SwitchToWindow(w => w.PageContains("Google"))
                .Assert(a => a.Contains("Google Search"))
                .SwitchToWindow(w => w.PageContains("Original Window"))
                .Assert(a => a.Contains("Main Content"));
        }

        [Test]
        public async Task CanCloseAndSwitchToAnotherWindow()
        {
            await browserTest
                .Click("a#yahooLink")
                .SwitchToWindow(w => w.PageContains("Yahoo"))
                .CloseWindow()
                .SwitchToWindow(w => w.PageContains("Original Window"))
                .Assert(a => a.Contains("Main Content"));
        }

        [Test]
        public async Task MaintainsContextAfterMultipleSwitches()
        {
            await browserTest
                .Click("a#googleLink")
                .SwitchToWindow(w => w.PageContains("Google"))
                .Click("input[type='submit']")
                .SwitchToWindow(w => w.PageContains("Original Window"))
                .Click("a#yahooLink")
                .SwitchToWindow(w => w.PageContains("Yahoo"))
                .Assert(a => a.Contains("Yahoo News"));
        }
    }

    [TestFixture]
    public class ChromeWindowTests : BaseSwitchToWindowTests<ChromeBrowser>
    {
        protected override ChromeBrowser CreateInstance() => new ChromeBrowser();
    }

    [TestFixture]
    public class FirefoxWindowTests : BaseSwitchToWindowTests<FirefoxBrowser>
    {
        protected override FirefoxBrowser CreateInstance() => new FirefoxBrowser();
    }
}

