namespace InteractiveShell
{
    // Interface defining basic command behavior.
    public interface ICommand
    {
        int Execute(string[] args);
    }

    // Represents the command history for the shell.
    public class CommandHistory
    {
        private readonly List<string> _history;

        public CommandHistory()
        {
            _history = new List<string>();
        }

        // Adds a command to the history list.
        public void Add(string command)
        {
            _history.Add(command);
        }

        // Removes the last entry from the history to avoid duplication.
        public void RemoveLastEntry()
        {
            if (_history.Any())
            {
                _history.RemoveAt(_history.Count - 1);
            }
        }

        // Saves the current command history to the specified file.
        public bool SaveHistory(string filename)
        {
            try
            {
                File.WriteAllLines(filename, _history);
                return true;
            }
            catch (Exception)
            {
                return false;
            }
        }
    }

    // Command to save command history to a file.
    public class SaveHistoryCommand : ICommand
    {
        private readonly CommandHistory _commandHistory;

        // Dependency injection of the CommandHistory object.
        public SaveHistoryCommand(CommandHistory commandHistory)
        {
            _commandHistory = commandHistory;
        }

        // Executes the command to save history.
        public int Execute(string[] args)
        {
            // Modify history by removing the last (possibly redundant) command.
            _commandHistory.RemoveLastEntry();

            // Validate that a file name argument was provided.
            if (args == null || args.Length < 1)
            {
                Console.WriteLine("Error: Missing file name argument.");
                return -1;
            }

            string filename = args[0];

            // Attempt to save the history. Output error if operation fails.
            bool success = _commandHistory.SaveHistory(filename);
            if (success)
            {
                Console.WriteLine($"History successfully saved to {filename}.");
                return 0;
            }
            else
            {
                Console.WriteLine("Error: Failed to save history.");
                return -2;
            }
        }
    }

