                {
                    result = expression.Evaluate(scope);
                    if (scope.TryGetValue("return", out var returnValue))
                    {
                        result = returnValue;
                        break;
                    }
                }
                catch (Exception ex)
                {
                    Logger.Error(ex, "Error evaluating expression: {Expression}", expression);
                    throw new MoLangRuntimeException($"Error evaluating expression: {expression}", ex);
                }
            }

            return result;
        }

        public IMoValue Execute(params IExpression[] expressions)
        {
            return Execute(expressions, null);
        }
    }

    public struct MoScope
    {
        private readonly IDictionary<string, IMoValue> _environment;
        private readonly IDictionary<string, IMoValue> _localScope;

        public MoScope(IDictionary<string, IMoValue> environment, IDictionary<string, IMoValue> localScope = null)
        {
            _environment = environment;
            _localScope = localScope ?? new Dictionary<string, IMoValue>();
        }

        public bool TryGetValue(string key, out IMoValue value)
        {
            if (_localScope.TryGetValue(key, out value))
                return true;

            return _environment.TryGetValue(key, out value);
        }

        public void SetValue(string key, IMoValue value)
        {
            _localScope[key] = value;
        }
    }
}

