public class FileStream_ctor_sfh_fa_buffer_async : FileStream_ctor_sfh_fa_buffer
{
    protected override FileStream CreateFileStream(SafeFileHandle handle, FileAccess access, int bufferSize)
    {
        return new FileStream(handle, access, bufferSize, false);
    }

    protected FileStream CreateFileStream(SafeFileHandle handle, FileAccess access, int bufferSize, bool isAsync)
    {
        return new FileStream(handle, access, bufferSize, isAsync);
    }

    [Fact]
    public void MatchedAsync()
    {
        using (var handle = File.OpenHandle(GetTestFilePath(), FileMode.Create, FileAccess.ReadWrite, FileShare.None, FileOptions.Asynchronous))
        {
            using (var fs = CreateFileStream(handle, FileAccess.ReadWrite, 4096, true))
            {
                Assert.True(fs.IsAsync);
            }
        }

        using (var handle = File.OpenHandle(GetTestFilePath(), FileMode.Create, FileAccess.ReadWrite, FileShare.None, FileOptions.None))
        {
            using (var fs = CreateFileStream(handle, FileAccess.ReadWrite, 4096, false))
            {
                Assert.False(fs.IsAsync);
            }
        }
    }

    [Fact]
    public void UnmatchedAsyncThrows()
    {
        using (var handle = File.OpenHandle(GetTestFilePath(), FileMode.Create, FileAccess.ReadWrite, FileShare.None, FileOptions.Asynchronous))
        {
            Assert.Throws<ArgumentException>(() => CreateFileStream(handle, FileAccess.ReadWrite, 4096, false));
        }

        using (var handle = File.OpenHandle(GetTestFilePath(), FileMode.Create, FileAccess.ReadWrite, FileShare.None, FileOptions.None))
        {
            Assert.Throws<ArgumentException>(() => CreateFileStream(handle, FileAccess.ReadWrite, 4096, true));
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;

namespace ExcelTableConverter
{
    public abstract class BaseTableConverter
    {
        public abstract string ConvertTableContent(object[,] tableData);
        public abstract string GetConverterName();
    }

    public sealed class ConverterProvider
    {
        private static ConverterProvider _instance;
        private static readonly object _lockObject = new object();
        private Dictionary<string, BaseTableConverter> _converters;

        public BaseTableConverter CurrentConverter { get; private set; }

        private ConverterProvider()
        {
            _converters = new Dictionary<string, BaseTableConverter>();
            InitTableConverters();
        }

        public static ConverterProvider GetInstance()
        {
            if (_instance == null)
            {
                lock (_lockObject)
                {
                    if (_instance == null)
                    {
                        _instance = new ConverterProvider();
                    }
                }
            }
            return _instance;
        }

        private void InitTableConverters()
        {
            var converterTypes = Assembly.GetExecutingAssembly()
                .GetTypes()
                .Where(t => typeof(BaseTableConverter).IsAssignableFrom(t) && !t.IsAbstract);

            foreach (var converterType in converterTypes)
            {
                var converterInstance = (BaseTableConverter)Activator.CreateInstance(converterType);
                _converters[converterInstance.GetConverterName()] = converterInstance;
            }

            if (_converters.Count > 0)
            {
                CurrentConverter = _converters.Values.First();
            }
        }

        public void SetCurrentConverter(string converterName)
        {
            if (_converters.ContainsKey(converterName))
            {
                CurrentConverter = _converters[converterName];
            }
            else
            {
                throw new ArgumentException($"Converter {converterName} not found.");
            }
        }

        public string GetContent(object[,] tableData)
        {
            if (CurrentConverter == null)
            {
                throw new InvalidOperationException("No converter selected.");
            }

            return CurrentConverter.ConvertTableContent(tableData);
        }

        public List<string> GetConverterNames()
        {
            return _converters.Keys.ToList();
        }
    }
}

using NServiceBus;
