public class Issue_2481
{
    [Test]
    public async Task Should_enlist_the_receive_in_the_dtc_tx()
    {
        var result = await Scenario.Define<Context>()
            .WithEndpoint<DTCEndpoint>(b => b.Given((bus, context) =>
            {
                return bus.SendLocal(new MyMessage());
            }))
            .Done(c => c.HandlerInvoked)
            .Run();

        Assert.IsTrue(result.HandlerInvoked, "Handler should have been invoked.");
        Assert.IsTrue(CanEnlistPromotable.DTCTransactionCreated, "A DTC transaction should have been created.");
    }

    public class Context : ScenarioContext
    {
        public bool HandlerInvoked { get; set; }
    }

    public class DTCEndpoint : EndpointConfigurationBuilder
    {
        public DTCEndpoint()
        {
            EndpointSetup<DefaultServer>(b =>
            {
                b.Transactions().Enable();
            });
        }

        class MyMessageHandler : IHandleMessages<MyMessage>
        {
            Context context;

            public MyMessageHandler(Context context)
            {
                this.context = context;
            }

            public async Task Handle(MyMessage message, IMessageHandlerContext messageHandlerContext)
            {
                using (var scope = new TransactionScope(TransactionScopeOption.Required))
                {
                    var rm = new FakePromotableResourceManager();
                    Transaction.Current.EnlistPromotableSinglePhase(rm);

                    context.HandlerInvoked = true;
                    scope.Complete();
                }
            }
        }
    }

    public class MyMessage : IMessage
    {
    }

    public class CanEnlistPromotable
    {
        public static bool DTCTransactionCreated;
    }

    class FakePromotableResourceManager : IPromotableSinglePhaseNotification
    {
        public void Initialize()
        {
            CanEnlistPromotable.DTCTransactionCreated = true;
        }

        public void SinglePhaseCommit(SinglePhaseEnlistment singlePhaseEnlistment)
        {
            singlePhaseEnlistment.Committed();
        }

        public void Rollback(SinglePhaseEnlistment singlePhaseEnlistment)
        {
            singlePhaseEnlistment.Aborted();
        }
    }
}

using Moq;
using NUnit.Framework;

public interface IMemoryMonitor
{
    long GetCurrentUsage();
    long GetTotalAvailableMemory();
}

public class MemoryManager
{
    private readonly IMemoryMonitor _memoryMonitor;

    public MemoryManager(IMemoryMonitor memoryMonitor)
    {
        _memoryMonitor = memoryMonitor ?? throw new ArgumentNullException(nameof(memoryMonitor));
    }

    public bool IsCurrentUsageAbove(long threshold)
    {
        return _memoryMonitor.GetCurrentUsage() > threshold;
    }

    public bool IsSpaceAvailable(long requiredMemory)
    {
        if (requiredMemory <= 0)
        {
            return true;
        }

        long availableMemory = _memoryMonitor.GetTotalAvailableMemory() - _memoryMonitor.GetCurrentUsage();
        return availableMemory >= requiredMemory;
    }
}

