using UnityEngine;
using System.Collections;

public class GravitySwitch : MonoBehaviour
{
    private enum GameState { Playing, GameOver }
    private GameState gameState;
    private bool isGravityUp;
    private Rigidbody2D rb;
    private float currentScore;
    private int bestScore;

    [Header("Physics Settings")]
    public float gravityStrength = 15f;
    public float switchMomentum = 8f;

    [Header("Game Objects")]
    public GameObject jets;
    public GameObject explosionPrefab;
    public GameObject endScreen;
    public GameObject characterBody;
    public GameObject fracturedCharacter;

    [Header("UI Elements")]
    public UILabel scoreLabel;
    public UILabel bestScoreLabel;

    void Start()
    {
        rb = GetComponent<Rigidbody2D>();
        bestScore = PlayerPrefs.GetInt("BestScore", 0);
        bestScoreLabel.text = "BEST: " + bestScore;
        endScreen.SetActive(false);
        gameState = GameState.Playing;
        UpdateGravity();
    }

    void Update()
    {
        if (gameState == GameState.Playing)
        {
            HandleInput();
            UpdateScore();
        }
    }

    void HandleInput()
    {
        if (Input.GetKeyDown(KeyCode.Space) || Input.GetMouseButtonDown(0))
        {
            ToggleGravity();
            ApplySwitchMomentum();
            StartCoroutine(ActivateJets());
        }
    }

    void ToggleGravity()
    {
        isGravityUp = !isGravityUp;
        UpdateGravity();
    }

    void UpdateGravity()
    {
        Physics2D.gravity = new Vector2(0, isGravityUp ? gravityStrength : -gravityStrength);
    }

    void ApplySwitchMomentum()
    {
        rb.AddForce(new Vector2(0, isGravityUp ? -switchMomentum : switchMomentum),
                  ForceMode2D.Impulse);
    }

    IEnumerator ActivateJets()
    {
        jets.SetActive(true);
        yield return new WaitForSeconds(0.2f);
        jets.SetActive(false);
    }

    void UpdateScore()
    {
        currentScore += Time.deltaTime;
        scoreLabel.text = "SCORE: " + Mathf.FloorToInt(currentScore);
    }

    void OnCollisionEnter2D(Collision2D collision)
    {
        if (gameState != GameState.Playing) return;

        gameState = GameState.GameOver;
        Vector2 hitPosition = collision.contacts[0].point;
        HandleCollisionEffects(hitPosition);
        UpdateBestScore();
        DisableCharacter();
    }

    void HandleCollisionEffects(Vector2 position)
    {
        Instantiate(explosionPrefab, position, Quaternion.identity);
        characterBody.SetActive(false);
        fracturedCharacter.SetActive(true);

