using System;

/// <summary>
/// Represents a single theme item.
/// </summary>
public struct ThemeItem : IComparable, ICloneable
{
    /// <summary>
    /// Initializes a new instance of the <see cref="ThemeItem"/> structure.
    /// </summary>
    /// <param name="name">The name of the theme.</param>
    public ThemeItem(string name)
    {
        Name = name;
    }

    /// <summary>
    /// Gets the name of the theme.
    /// </summary>
    public string Name { get; }

    /// <summary>
    /// Compares the current instance with another object of the same type.
    /// </summary>
    /// <param name="obj">An object to compare with this instance.</param>
    /// <returns>
    /// A value that indicates the relative order of the objects being compared.
    /// </returns>
    public int CompareTo(object obj)
    {
        if (!(obj is ThemeItem))
        {
            return 1;
        }

        ThemeItem other = (ThemeItem)obj;
        return string.Compare(Name, other.Name, StringComparison.Ordinal);
    }

    /// <summary>
    /// Creates a new object that is a copy of the current instance.
    /// </summary>
    /// <returns>
    /// A new object that is a copy of this instance.
    /// </returns>
    public object Clone()
    {
        return new ThemeItem(Name);
    }
}

