using WaveEngine.Common.Input;

public struct TouchState
{
    // Right Controller States
    public ButtonState A;          // A button state
    public ButtonState B;          // B button state
    public ButtonState RThumb;     // Right thumb rest state
    public ButtonState RIndexTrigger; // Right index trigger state
    public ButtonState RIndexPointing; // Right index finger pointing gesture
    public ButtonState RThumbUp;   // Right thumb up gesture

    // Left Controller States
    public ButtonState X;          // X button state
    public ButtonState Y;          // Y button state
    public ButtonState LThumb;     // Left thumb rest state
    public ButtonState LIndexTrigger; // Left index trigger state
    public ButtonState LIndexPointing; // Left index finger pointing gesture
    public ButtonState LThumbUp;   // Left thumb up gesture

    // Constructor to initialize all states
    public TouchState(
        ButtonState a, ButtonState b, ButtonState rThumb, ButtonState rIndexTrigger,
        ButtonState rIndexPointing, ButtonState rThumbUp,
        ButtonState x, ButtonState y, ButtonState lThumb, ButtonState lIndexTrigger,
        ButtonState lIndexPointing, ButtonState lThumbUp)
    {
        A = a;
        B = b;
        RThumb = rThumb;
        RIndexTrigger = rIndexTrigger;
        RIndexPointing = rIndexPointing;
        RThumbUp = rThumbUp;

        X = x;
        Y = y;
        LThumb = lThumb;
        LIndexTrigger = lIndexTrigger;
        LIndexPointing = lIndexPointing;
        LThumbUp = lThumbUp;
    }

    // Method to reset all states to default
    public void Reset()
    {
        A = ButtonState.Released;
        B = ButtonState.Released;
        RThumb = ButtonState.Released;
        RIndexTrigger = ButtonState.Released;
        RIndexPointing = ButtonState.Released;
        RThumbUp = ButtonState.Released;

        X = ButtonState.Released;
        Y = ButtonState.Released;
        LThumb = ButtonState.Released;
        LIndexTrigger = ButtonState.Released;
        LIndexPointing = ButtonState.Released;
        LThumbUp = ButtonState.Released;
    }

    // Method to check if any button or trigger is pressed
    public bool IsAnyButtonPressed()
    {
        return A == ButtonState.Pressed || B == ButtonState.Pressed ||
               RThumb == ButtonState.Pressed || RIndexTrigger == ButtonState.Pressed ||
               X == ButtonState.Pressed || Y == ButtonState.Pressed ||
               LThumb == ButtonState.Pressed || LIndexTrigger == ButtonState.Pressed;
    }
}

