using System;

public class Life
{
    public static void Main(string[] args)
    {
        string start = "_###_##_#_#_#_#__#__";
        int numGens = 10;
        for (int i = 0; i < numGens; i++)
        {
            Console.WriteLine("Generation " + i + ": " + start);
            start = life(start);
        }
    }

    public static string life(string lastGen)
    {
        string newGen = "";
        for (int i = 0; i < lastGen.Length; i++)
        {
            int neighbors = 0;
            if (i == 0)
            {
                //left edge
                neighbors = lastGen[1] == '#'? 1 : 0;
            }
            else if (i == lastGen.Length - 1)
            {
                //right edge
                neighbors = lastGen[i - 1] == '#'? 1 : 0;
            }
            else
            {
                //middle
                neighbors = getNeighbors(lastGen.Substring(i - 1, i + 2));
            }

            if (neighbors == 0)
            {
                //dies or stays dead with no neighbors
                newGen += "_";
            }
            if (neighbors == 1)
            {
                //stays with one neighbor
                newGen += lastGen[i];
            }
            if (neighbors == 2)
            {
                //flips with two neighbors
                newGen += lastGen[i] == '#'? "_" : "#";
            }
        }
        return newGen;
    }

    public static int getNeighbors(string group)
    {
        int ans = 0;
        if (group[0] == '#')
        {
            ans++;
        }
        if (group[2] == '#')
        {
            ans++;
        }
        return ans;
    }
}

