namespace Order
{
    class Handler
    {
        static void Main(string[] args)
        {
            Queue q = new Queue();
            Console.WriteLine("empty? {0}", q.Empty());

            string x = "black";
            Console.WriteLine("push {0}", x);
            q.Push(x);

            Console.WriteLine("empty? {0}", q.Empty());
            string r = q.Pop();
            if (r!= null)
            {
                Console.WriteLine("{0} popped", r);
            }
            else
            {
                Console.WriteLine("pop failed");
            }

            int n = 0;
            foreach (string x1 in new string[] { "blue", "red", "green" })
            {
                Console.WriteLine("pushing {0}", x1);
                q.Push(x1);
                n++;
            }

            for (int i = 0; i < n; i++)
            {
                r = q.Pop();
                if (r!= null)
                {
                    Console.WriteLine("{0} popped", r);
                }
                else
                {
                    Console.WriteLine("pop failed");
                }
            }
        }
    }

    class Queue
    {
        private List<string> _queue = new List<string>();

        public bool Empty()
        {
            return _queue.Count == 0;
        }

        public void Push(string x)
        {
            _queue.Add(x);
        }

        public string Pop()
        {
            if (_queue.Count == 0)
            {
                return null;
            }
            else
            {
                string r = _queue[0];
                _queue.RemoveAt(0);
                return r;
            }
        }
    }
}

