    // Interface for a generic Entity Framework context wrapper
    public interface IEfContextWrapper<T>
    {
        void Add(T entity);
    }

    // Interface for persistence context to save changes
    public interface ISaveContext
    {
        void SaveChanges();
    }

    // Service class responsible for creating artists
    public class CreationService
    {
        private readonly IEfContextWrapper<Artist> _artistRepository;
        private readonly ISaveContext _saveContext;

        public CreationService(IEfContextWrapper<Artist> artistRepository, ISaveContext saveContext)
        {
            _artistRepository = artistRepository;
            _saveContext = saveContext;
        }

        public void CreateArtist(string artistName)
        {
            if (string.IsNullOrWhiteSpace(artistName))
            {
                throw new ArgumentException("Artist name cannot be null or empty", nameof(artistName));
            }

            var artist = new Artist { Name = artistName };
            _artistRepository.Add(artist);
            _saveContext.SaveChanges();
        }
    }

