public class SmokeTrailWhenDamagedInfo : ConditionalTraitInfo
{
    [Desc("Horizontal offset from actor's center for smoke trail.")]
    public readonly WVec Offset = WVec.Zero;

    [Desc("Vertical offset from actor's center for smoke trail.")]
    public readonly WVec VerticalOffset = WVec.Zero;

    [Desc("Minimum damage percentage required to trigger smoke trail.")]
    public readonly int MinDamage = 25;

    [Desc("Interval between smoke trail sprite generation.")]
    public readonly int Interval = 5;

    [Desc("Color variation for smoke trail sprites.")]
    public readonly Color SmokeColor = Color.Gray;

    public override object Create(ActorInitializer init) { return new SmokeTrailWhenDamaged(init, this); }
}

public class SmokeTrailWhenDamaged : ConditionalTrait<SmokeTrailWhenDamagedInfo>, ITick
{
    private readonly Actor self;
    private readonly IHealth health;
    private readonly IFacing facing;
    private int ticksSinceLastSmoke;

    public SmokeTrailWhenDamaged(ActorInitializer init, SmokeTrailWhenDamagedInfo info)
        : base(info)
    {
        self = init.Self;
        health = self.Trait<IHealth>();
        facing = self.TraitOrDefault<IFacing>();
    }

    void ITick.Tick(Actor self)
    {
        if (IsTraitDisabled || health == null)
            return;

        var damagePercentage = 100 * (health.HP - health.MaxHP) / health.MaxHP;
        if (damagePercentage < Info.MinDamage)
            return;

        ticksSinceLastSmoke++;
        if (ticksSinceLastSmoke >= Info.Interval)
        {
            GenerateSmokeTrail();
            ticksSinceLastSmoke = 0;
        }
    }

    private void GenerateSmokeTrail()
    {
        var world = self.World;
        var position = self.CenterPosition;

        // Adjust offset based on actor's facing direction
        var offset = facing != null
            ? Info.Offset.Rotate(WRot.FromFacing(facing.Facing))
            : Info.Offset;

        // Apply vertical and directional offsets
        var smokePosition = position + offset + Info.VerticalOffset;

        // Check terrain and visibility conditions
        if (!world.Map.Contains(smokePosition.ToCellClamped()) || world.FogObscures(smokePosition))
            return;

        // Create smoke trail effect sprite
        var smokeTrail = new SmokeParticle(world, smokePosition, Info.SmokeColor);
        world.AddFrameEndTask(w => w.Add(smokeTrail));
    }

    private class SmokeParticle : IEffect
    {
        private readonly World world;
        private readonly WPos position;
        private readonly Color color;

