public static class ComparisonExtensions
{
    private class EquatableComparer<T> : IEqualityComparer<T>
    {
        private readonly Func<T, T, bool> _comparisonFunc;

        public EquatableComparer(Func<T, T, bool> comparisonFunc)
        {
            _comparisonFunc = comparisonFunc ?? throw new ArgumentNullException(nameof(comparisonFunc));
        }

        public bool Equals(T x, T y) => _comparisonFunc(x, y);
        public int GetHashCode(T obj) => obj?.GetHashCode() ?? 0;
    }

    public static bool DeepCompare<T>(this T actual, T expected, Action<ComparisonConfig> configuration = null)
    {
        var compareLogic = CreateComparer(configuration);
        var result = compareLogic.Compare(actual, expected);
        return result.AreEqual;
    }

    private static CompareLogic CreateComparer(Action<ComparisonConfig> configuration = null)
    {
        var compareConfig = new ComparisonConfig
        {
            IgnoreObjectTypes = false,
            CompareChildren = true,
            AllowedComparisonTypes = new List<Type>(),
            MaxDifferences = int.MaxValue
        };

        configuration?.Invoke(compareConfig);

        ConfigureProtoBufAttributes(compareConfig);
        ConfigureCustomTypeComparisons(compareConfig);

        return new CompareLogic(compareConfig);
    }

    private static void ConfigureProtoBufAttributes(ComparisonConfig config)
    {
        config.TypesToIgnore.AddRange(
            typeof(T).GetProperties()
                .Where(p => p.GetCustomAttribute<ProtoIgnoreAttribute>() != null)
                .Select(p => p.PropertyType)
        );
    }

    private static void ConfigureCustomTypeComparisons(ComparisonConfig config)
    {
        config.CustomComparison.Add((compareLogic, parentObject, actualObject, expectedObject) =>
        {
            return IsTypeMatch(actualObject, expectedObject)
                ? CompareType(compareLogic, actualObject, expectedObject)
                : null;
        });
    }

    private static bool IsTypeMatch(object actual, object expected)
    {
        return actual?.GetType() == expected?.GetType()
            && actual != null
            && expected != null;
    }

    private static ComparisonResult CompareType(
        CompareLogic compareLogic,
        object actual,
        object expected)
    {
        var result = compareLogic.Compare(actual, expected);

