public class FractionReduction
{
 
    public static void Main(string[] args)
    {
        for (int size = 2; size <= 5; size++)
        {
            reduce(size);
        }
    }
 
    private static void reduce(int numDigits)
    {
        Console.WriteLine("Fractions with digits of length {0} where cancellation is valid.  Examples:", numDigits);
 
        //  Generate allowed numerator's and denominator's
        int min = (int)Math.Pow(10, numDigits - 1);
        int max = (int)Math.Pow(10, numDigits) - 1;
        List<int> values = new List<int>();
        for (int number = min; number <= max; number++)
        {
            if (isValid(number))
            {
                values.Add(number);
            }
        }
 
        Dictionary<int, int> cancelCount = new Dictionary<int, int>();
        int size = values.Count;
        int solutions = 0;
        for (int nIndex = 0; nIndex < size - 1; nIndex++)
        {
            int numerator = values[nIndex];
            //  Must be proper fraction
            for (int dIndex = nIndex + 1; dIndex < size; dIndex++)
            {
                int denominator = values[dIndex];
                foreach (int commonDigit in digitsInCommon(numerator, denominator))
                {
                    int numRemoved = removeDigit(numerator, commonDigit);
                    int denRemoved = removeDigit(denominator, commonDigit);
                    if (numerator * denRemoved == denominator * numRemoved)
                    {
                        solutions++;
                        cancelCount.Merge(commonDigit, 1, (v1, v2) => v1 + v2);
                        if (solutions <= 12)
                        {
                            Console.WriteLine("    When {0} is removed, {1}/{2} = {3}/{4}", commonDigit, numerator, denominator, numRemoved, denRemoved);
                        }
                    }
                }
            }
        }
        Console.WriteLine("Number of fractions where cancellation is valid = {0}.", solutions);
        List<int> sorted = new List<int>(cancelCount.Keys);
        sorted.Sort();
        foreach (int removed in sorted)
        {
            Console.WriteLine("    The digit {0} was removed {1} times.", removed, cancelCount[removed]);
        }
        Console.WriteLine();
    }
 
