namespace DynamicMenuIntegration
{
    public interface IMenuItem
    {
        string Header { get; }
        object Command { get; }
        int SortOrder { get; }
    }

    public interface IMenuService
    {
        IMenuItem ConvertToMenuItem(object view);
        void AddMenuItem(Menu menu, IMenuItem item);
    }

    public class SortedMenuItemCollection : ObservableCollection<IMenuItem>
    {
        protected override void InsertItem(int index, IMenuItem item)
        {
            int sortedIndex = 0;
            while (sortedIndex < Count && this[sortedIndex].SortOrder <= item.SortOrder)
                sortedIndex++;
            base.InsertItem(sortedIndex, item);
        }
    }

    [Export(typeof(RegionAdapter))]
    public class MenuRegionAdapter : RegionAdapterBase<Menu>
    {
        private readonly IMenuService _menuService;
        private Menu _menu;
        private SortedMenuItemCollection _sortedItems = new SortedMenuItemCollection();

        [ImportingConstructor]
        public MenuRegionAdapter(IRegionBehaviorFactory factory, IMenuService menuService)
            : base(factory)
        {
            _menuService = menuService;
        }

        protected override void Adapt(IRegion region, Menu menu)
        {
            _menu = menu;
            _menu.ItemsSource = _sortedItems;
            region.ActiveViews.CollectionChanged += ActiveViewsOnCollectionChanged;
        }

        private void ActiveViewsOnCollectionChanged(object sender, NotifyCollectionChangedEventArgs e)
        {
            switch (e.Action)
            {
                case NotifyCollectionChangedAction.Add:
                    foreach (var view in e.NewItems)
                    {
                        var menuItem = _menuService.ConvertToMenuItem(view);
                        _sortedItems.Add(menuItem);
                    }
                    break;
                case NotifyCollectionChangedAction.Remove:
                    throw new NotImplementedException("Menu item removal not supported");
                default:
                    throw new NotSupportedException($"Operation {e.Action} not allowed");
            }
        }

        protected override IRegion CreateRegion()
        {
            return new AllActiveRegion();
        }

        protected override void AttachBehaviors(IRegion region, Menu regionTarget)
        {

