namespace Logger
{
    class Vector
    {
        struct Entry_
        {
            public string expr_;
            public string op_;
        };

        static bool PrecedenceLess(string lhs, string rhs, bool assoc)
        {
            Dictionary<string, int> KNOWN = new Dictionary<string, int>();
            KNOWN.Add("+", 1);
            KNOWN.Add("-", 1);
            KNOWN.Add("*", 2);
            KNOWN.Add("/", 2);
            KNOWN.Add("^", 3);
            HashSet<string> ASSOCIATIVE = new HashSet<string>();
            ASSOCIATIVE.Add("+");
            ASSOCIATIVE.Add("*");
            return (KNOWN.ContainsKey(lhs)? KNOWN[lhs] : 0) < (KNOWN.ContainsKey(rhs)? KNOWN[rhs] : 0) + (assoc &&!ASSOCIATIVE.Contains(rhs)? 1 : 0);
        }

        static void Parenthesize(Entry_ old, string token, bool assoc)
        {
            if (!old.op_.Equals("") && PrecedenceLess(old.op_, token, assoc))
                old.expr_ = '(' + old.expr_ + ')';
        }

        static void AddToken(Stack<Entry_> stack, string token)
        {
            if (token.IndexOfAny("0123456789".ToCharArray())!= -1)
                stack.Push(new Entry_ { expr_ = token, op_ = "" });
            else
            {
                if (stack.Count < 2)
                    Console.WriteLine("Stack underflow");
                var rhs = stack.Pop();
                Parenthesize(rhs, token, false);
                var lhs = stack.Pop();
                Parenthesize(lhs, token, true);
                stack.Peek().expr_ = lhs.expr_ +'' + token +'' + rhs.expr_;
                stack.Peek().op_ = token;
            }
        }

        static string ToInfix(string src)
        {
            Stack<Entry_> stack = new Stack<Entry_>();
            for (var start = src.Begin(), p = src.Begin(); ; ++p)
            {
                if (p == src.End() || *p =='')
                {
                    if (p > start)
                        AddToken(stack, new string(start, p));
                    if (p == src.End())
                        break;
                    start = p + 1;
                }
            }
            if (stack.Count!= 1)
                Console.WriteLine("Incomplete expression");
            return stack.Peek().expr_;
        }

        static void Main(string[] args)
        {
            try
            {
                Console.WriteLine(ToInfix("3 4 2 * 1 5 - 2 3 ^ ^ / +"));
                Console.WriteLine(ToInfix("1 2 + 3 4 + ^ 5 6 + ^"));

