    // Domain entity representing a fixture in the data layer.
    public class FixtureEntity
    {
        public int Id { get; set; }
        public DateTime FixtureDate { get; set; }
        public bool IsForecastable { get; set; }
        public string Edition { get; set; }
        public DateTime Day { get; set; } // Represents the day of the fixture
    }

    // Business model used throughout the application.
    public class FixtureModel
    {
        public int Id { get; set; }
        public DateTime FixtureDate { get; set; }
        public string Edition { get; set; }
    }

    // Repository interface for fixture data.
    public interface IFixtureRepository
    {
        FixtureEntity GetFixtureById(int id);
        IEnumerable<FixtureEntity> GetAllFixtures();
    }

    // Service interface defining fixture business operations.
    public interface IFixtureService
    {
        FixtureModel GetFixture(int id);
        FixtureModel GetNextFixture();
        IEnumerable<FixtureModel> GetFixtures(IEnumerable<int> ids);
        IEnumerable<FixtureModel> GetFixturesForDay(DateTime day);
        IEnumerable<FixtureModel> GetFixturesForEdition(string edition);
    }

    // Implementation of the fixture business service.
    public class FixtureService : IFixtureService
    {
        private readonly IFixtureRepository _fixtureRepository;

        public FixtureService(IFixtureRepository fixtureRepository)
        {
            _fixtureRepository = fixtureRepository;
        }

        // Retrieves a single fixture by its identifier.
        public FixtureModel GetFixture(int id)
        {
            var entity = _fixtureRepository.GetFixtureById(id);
            return TransformToModel(entity);
        }

        // Retrieves the next forecastable fixture based on the current date.
        public FixtureModel GetNextFixture()
        {
            var fixtures = _fixtureRepository.GetAllFixtures();
            var nextFixture = fixtures
                .Where(f => f.IsForecastable && f.FixtureDate > DateTime.Now)
                .OrderBy(f => f.FixtureDate)
                .FirstOrDefault();
            return TransformToModel(nextFixture);
        }

