            var selectedFixtures = fixtures.Where(f => ids.Contains(f.Id));

 
public static string splitOnChange(string s)
{
    if (s.Length < 2)
        return s;
    var t = s.Take(1);
    for (var i = 1; i < s.Length; i++)
        if (t.Last() == s[i])
            t += s[i];
        else
            t += ", " + s[i];
    return t;
}
 
public static void Main(string[] args)
{
    var s = "gHHH5YY++///\\";
    Console.WriteLine(splitOnChange(s));
}

