namespace DataReaderExtensionsDemo
{
    public static class DataReaderExtension
    {
        /// <summary>
        /// Determines if the data reader contains a column with the specified name.
        /// Comparison is case-insensitive.
        /// </summary>
        /// <param name="reader">The data reader instance.</param>
        /// <param name="columnName">The name of the column to check for.</param>
        /// <returns>True if the column exists; otherwise, false.</returns>
        public static bool ContainsColumn(this IDataReader reader, string columnName)
        {
            if (reader == null || string.IsNullOrEmpty(columnName))
            {
                return false;
            }

            // Iterate over each column in the data reader and check for a match.
            for (int i = 0; i < reader.FieldCount; i++)
            {
                if (string.Equals(reader.GetName(i), columnName, StringComparison.OrdinalIgnoreCase))
                {
                    return true;
                }
            }
            return false;
        }

        /// <summary>
        /// Retrieves a value from the data reader by column name and converts it to the specified type.
        /// Handles absent or null columns by returning the default value of type T.
        /// </summary>
        /// <typeparam name="T">The type to which the value will be converted.</typeparam>
        /// <param name="reader">The data reader instance.</param>
        /// <param name="columnName">The name of the column.</param>
        /// <returns>The converted value if present; otherwise, default(T).</returns>
        public static T Get<T>(this IDataReader reader, string columnName)
        {
            if (reader == null || string.IsNullOrEmpty(columnName))
            {
                return default(T);
            }

            // Check if the reader contains the specified column.
            if (!reader.ContainsColumn(columnName))
            {
                return default(T);
            }

            // Retrieve the column's ordinal and return the value using the ordinal overload.
            int ordinal = reader.GetOrdinal(columnName);
            return reader.Get<T>(ordinal);
        }

        /// <summary>
        /// Retrieves a value from the data reader by column index and converts it to the specified type.
        /// Assumes the caller has ensured the ordinal is valid.
        /// </summary>
        /// <typeparam name="T">The type to which the value will be converted.</typeparam>

