namespace Macro.ImageViewer.Tools
{
    [ActionRegistration(Menu = "Edit/Reset Filter")]
    [StateObservation(ObservationType = StateObservationType.ImageSelected)]
    public class ResetImageFilterTool : ImageViewerTool
    {
        // Entry point for the filter reset operation
        public override void Apply()
        {
            // Obtain the current image provider from the application context
            var currentImageProvider = this.GetCurrentImageProvider();
            if (currentImageProvider == null)
            {
                Console.WriteLine("No image is currently selected.");
                return;
            }

            // Ensure the selected image is a grayscale image
            var grayscaleImage = currentImageProvider as GrayscaleImage;
            if (grayscaleImage == null)
            {
                Console.WriteLine("Selected image is not a grayscale image. Operation aborted.");
                return;
            }

            // Retrieve the associated frame provider
            var frameProvider = grayscaleImage.FrameProvider;
            if (frameProvider == null)
            {
                Console.WriteLine("No frame provider available for the current image.");
                return;
            }

            // Step 1: Unload any filtered pixel data
            frameProvider.UnloadFilteredPixelData();

            // Step 2: Trigger a redraw to load the original unfiltered image
            frameProvider.Redraw();

            Console.WriteLine("Image filter has been reset successfully.");
        }

        // Simulated method to retrieve the currently selected image provider.
        private IImageProvider GetCurrentImageProvider()
        {
            // In a full application, this would return the image selected by the user.
            // For demonstration, we return a dummy grayscale image.
            return new GrayscaleImage();
        }
    }

    // Base interface for image providers within the viewer.
    public interface IImageProvider { }

    // Represents a grayscale image type, suitable for filter reset operations.
    public class GrayscaleImage : IImageProvider
    {
        private IFrameProvider frameProvider;

        public GrayscaleImage()
        {
            // Initialize the frame provider with a dummy implementation.
            this.frameProvider = new ImageFrameProvider();
        }

 
