using System;
 
namespace multtbl
{
    class Service
    {
        static void Main(string[] args)
        {
            Console.Write(" X".PadRight(4));
            for (int i = 1; i <= 12; i++)
                Console.Write(i.ToString("####").PadLeft(4));
 
            Console.WriteLine();
            Console.Write(" ___");
 
            for (int i = 1; i <= 12; i++)
                Console.Write(" ___");
 
            Console.WriteLine();
            for (int row = 1; row <= 12; row++)
            {
                Console.Write(row.ToString("###").PadLeft(3).PadRight(4));
                for (int col = 1; col <= 12; col++)
                {
                    if (row <= col)
                        Console.Write((row * col).ToString("###").PadLeft(4));
                    else
                        Console.Write("".PadLeft(4));
                }
 
                Console.WriteLine();
            }
 
            Console.WriteLine();
            Console.ReadLine();
        }
    }
}

using Microsoft.Extensions.Logging;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using Moq;
using Mono.Unix.Native;
using System;
using System.Threading;
using System.Threading.Tasks;
using Tgstation.Server.Host.Core;
using Tgstation.Server.Host.Extensions;
using Tgstation.Server.Host.System;

[TestClass]
public class SignalHandlerTests
{
    private Mock<IServerControl> mockServerControl;
    private Mock<IAsyncDelayer> mockAsyncDelayer;
    private TaskCompletionSource<object> tcs;
    private CancellationTokenSource cts;
    private PosixSignalHandler signalHandler;

    [TestInitialize]
    public void Initialize()
    {
        mockServerControl = new Mock<IServerControl>();
        mockAsyncDelayer = new Mock<IAsyncDelayer>();
        tcs = new TaskCompletionSource<object>();
        cts = new CancellationTokenSource();
        signalHandler = new PosixSignalHandler(mockServerControl.Object, mockAsyncDelayer.Object, Mock.Of<ILogger<PosixSignalHandler>>());
    }

    [TestMethod]
    public async Task TestSignalHandlerGracefulShutdown()
    {
        mockAsyncDelayer.Setup(d => d.Delay(It.IsAny<TimeSpan>(), It.IsAny<CancellationToken>()))
            .Returns(Task.CompletedTask);

        await signalHandler.StartAsync(cts.Token);

        mockServerControl.Setup(sc => sc.GracefulShutdown()).Callback(() => tcs.SetResult(null));
        signalHandler.HandleSignal(Signum.SIGTERM);

        await tcs.Task;

        await signalHandler.StopAsync(cts.Token);
    }

    [TestMethod]
    public async Task TestSignalHandlerPrematureCompletion()
    {
        var cts2 = new CancellationTokenSource();
        mockAsyncDelayer.Setup(d => d.Delay(It.IsAny<TimeSpan>(), It.IsAny<CancellationToken>()))
            .Returns(Task.CompletedTask);

        await signalHandler.StartAsync(cts2.Token);

        mockServerControl.Setup(sc => sc.GracefulShutdown()).Throws(new InvalidOperationException("Premature completion"));
        signalHandler.HandleSignal(Signum.SIGTERM);

        await Assert.ThrowsExceptionAsync<InvalidOperationException>(() => tcs.Task);
    }

    [TestMethod]
    public async Task TestSignalHandlerExceptionHandling()
    {
        var cts3 = new CancellationTokenSource();
        mockAsyncDelayer.Setup(d => d.Delay(It.IsAny<TimeSpan>(), It.IsAny<CancellationToken>()))
            .ThrowsAsync(new TimeoutException("Operation timed out"));

        await signalHandler.StartAsync(cts3.Token);

        signalHandler.HandleSignal(Signum.SIGTERM);

        await Assert.ThrowsExceptionAsync<TimeoutException>(() => tcs.Task);
    }
}

