using System;
using System.Collections.Generic;
using System.Linq;
using CharacterMap.Core;
using CharacterMap.Models;
using Windows.UI.Xaml.Controls;

namespace CharacterMap.Providers
{
    public class VBDevProvider : DevProviderBase
    {
        public override DevProviderType GetDevProviderType() => DevProviderType.VisualBasic;

        protected override List<DevOption> OnGetContextOptions(Character c, CharacterRenderingOptions options) => Inflate(c, options);

        protected override List<DevOption> OnGetOptions(Character c, CharacterRenderingOptions options) => Inflate(c, options);

        private List<DevOption> Inflate(Character c, CharacterRenderingOptions options)
        {
            var ops = new List<DevOption>();
            var hex = ((int)c.Codepoint).ToString("X4");
            var hasSymbol = SymbolHelper.IsSymbol(c.Codepoint);
            var pathIconData = PathIconData.GetPathData(c.Codepoint);
            var glyph = FontFinder.GetGlyph(c.Codepoint);

            if (glyph != null)
            {
                ops.Add(new DevOption
                {
                    Title = "FontIcon",
                    Description = $"FontIcon using Glyph \"{glyph}\"",
                    Code = $"<FontIcon Glyph=\"{glyph}\" FontFamily=\"{glyph.FontFamily}\" />"
                });
            }

            if (hasSymbol)
            {
                var symbol = SymbolHelper.ToSymbol(c.Codepoint);
                ops.Add(new DevOption
                {
                    Title = "SymbolIcon",
                    Description = $"SymbolIcon using Symbol.{symbol}",
                    Code = $"<SymbolIcon Symbol=\"{symbol}\" />"
                });
            }

            if (pathIconData != null)
            {
                ops.Add(new DevOption
                {
                    Title = "PathIcon",
                    Description = $"PathIcon using PathData \"{pathIconData}\"",
                    Code = $"<PathIcon Data=\"{pathIconData}\" />"
                });
            }

            ops.Add(new DevOption
            {
                Title = "TextBlock",
                Description = $"TextBlock using Character U+{hex}",
                Code = $"<TextBlock Text=\"&#x{hex};\" FontFamily=\"{c.FontFamily}\" />"
            });

            return ops;
        }
    }

    public struct DevOption
    {
        public string Title { get; set; }
        public string Description { get; set; }
        public string Code { get; set; }
    }
}

