{
    public enum ResistanceType { Physical, Fire, Cold, Poison, Energy }
    public enum FoodType { Meat, Fish, FruitsAndVegies }
    public enum PackInstinct { Spider, Beast }
    public enum AIType { Melee, Archery }
    public enum FightMode { Closest, Strongest }

    public class SentinelSpider : BaseCreature
    {
        public override string DefaultName { get { return "a sentinel spider"; } }

        public FoodType FavoriteFood { get; set; }
        public PackInstinct CreaturePackInstinct { get; set; }

        [Constructable]
        public SentinelSpider()
            : base(AIType.Melee, FightMode.Closest, 10, 1, 0.2, 0.4)
        {
            Body = 0x2D;  // Example body type id
            Hue = 0x455;  // Example hue value
            BaseSoundID = 0x388; // Example sound id

            // Set combat stats
            SetStr(80, 100);
            SetDex(90, 110);
            SetInt(30, 50);

            SetHits(100, 150);
            SetDamage(6, 12);

            // Set resistances
            SetResistance(ResistanceType.Physical, 20, 30);
            SetResistance(ResistanceType.Fire, 10, 20);
            SetResistance(ResistanceType.Cold, 15, 25);
            SetResistance(ResistanceType.Poison, 30, 40);
            SetResistance(ResistanceType.Energy, 25, 35);

            // Set skills
            SetSkill("Wrestling", 70.0, 90.0);
            SetSkill("Tactics", 65.0, 85.0);
            SetSkill("MagicResistance", 50.0, 70.0);

            // Taming properties
            Tamable = true;
            ControlSlots = 2;
            MinTameSkill = 75.0;

            // Behavior and pack instincts
            FavoriteFood = FoodType.Meat;
            CreaturePackInstinct = PackInstinct.Spider;
        }

        public override void GenerateLoot()
        {
            // Generate customized loot for Sentinel Spider.
            AddLoot(LootPack.Meager);
            AddLoot(LootPack.Potions);
        }

        public override WeaponAbility GetWeaponAbility()
        {
            // Returns the special combat ability of the Sentinel Spider.
            return WeaponAbility.PoisonStrike;
        }

        public SentinelSpider(Serial serial)
            : base(serial)
        {
        }

        public override void Serialize(GenericWriter writer)
        {
            base.Serialize(writer);
            writer.Write((int)1); // version number
            writer.Write((int)FavoriteFood);
            writer.Write((int)CreaturePackInstinct);
        }

using System;
using System.Numerics;
using System.Text;
 
class Manager
{
    static void Main(string[] args)
    {
        BigInteger n = BigInteger.Parse("9516311845790656153499716760847001433441357");
        BigInteger e = 65537;
        BigInteger d = BigInteger.Parse("5617843187844953170308463622230283376298685");
 
        const string plaintextstring = "Hello, Rosetta!";
        byte[] plaintext = ASCIIEncoding.ASCII.GetBytes(plaintextstring);
        BigInteger pt = new BigInteger(plaintext);
        if (pt > n)
            throw new Exception();
 
        BigInteger ct = BigInteger.ModPow(pt, e, n);
        Console.WriteLine("Encoded:  " + ct);
 
        BigInteger dc = BigInteger.ModPow(ct, d, n);
        Console.WriteLine("Decoded:  " + dc);
 
        string decoded = ASCIIEncoding.ASCII.GetString(dc.ToByteArray());
        Console.WriteLine("As ASCII: " + decoded);
    }
}

