namespace Logger
{
    class Shape
    {
        static void Main(string[] args)
        {
            var sets = new List<Setr>
            {
                new Setr(0, 1, true, true) | new Setr(0, 2, false, true),
                new Setr(0, 2, false, true) & new Setr(1, 2, true, false),
                new Setr(0, 3, false, true) - new Setr(0, 1, true, true),
                new Setr(0, 3, false, true) - new Setr(0, 1, false, false),
            };
            var settexts = "(0, 1] ∪ [0, 2);[0, 2) ∩ (1, 2);[0, 3) − (0, 1);[0, 3) − [0, 1]".Split(';');
            for (int i = 0; i < sets.Count; i++)
            {
                var s = sets[i];
                var t = settexts[i];
                Console.WriteLine("Set {0} {1}. {2}", t,
                    string.Join(", ", Enumerable.Range(0, 3).Select(v => (s.Contains(v)? "includes" : "excludes") + " " + v)),
                    s.eqn);
            }
            Console.ReadLine();
        }
    }
    class Setr
    {
        public int lo, hi;
        public bool includelo, includehi;
        public string eqn;
        public Setr(int lo, int hi, bool includelo, bool includehi)
        {
            this.lo = lo;
            this.hi = hi;
            this.includelo = includelo;
            this.includehi = includehi;
            this.eqn = string.Format("({0}{1}X{2}{3})", lo, includelo? "<=" : "<", includehi? "<=" : "<", hi);
        }
        public bool Contains(int X)
        {
            return (bool)Eval(eqn, X);
        }
        public static object Eval(string expression, int X)
        {
            var lo = lo;
            var hi = hi;
            var includelo = includelo;
            var includehi = includehi;
            return Microsoft.JScript.Eval.JScriptEvaluate(expression, Microsoft.JScript.Vsa.VsaEngine.CreateEngine());
        }
        public static Setr operator |(Setr a, Setr b)
        {
            var ans = new Setr(0, 0, false, false);
            ans.eqn = string.Format("({0}or{1})", a.eqn, b.eqn);
            return ans;
        }
        public static Setr operator &(Setr a, Setr b)
        {
            var ans = new Setr(0, 0, false, false);
            ans.eqn = string.Format("({0}and{1})", a.eqn, b.eqn);
            return ans;
        }
        public static Setr operator -(Setr a, Setr b)
        {
            var ans = new Setr(0, 0, false, false);
            ans.eqn = string.Format("({0}and not{1})", a.eqn, b.eqn);
            return ans;

