using System;
using System.Linq;
using System.Numerics;
 
namespace LahNumbers {
    class Calculator {
        static BigInteger Factorial(BigInteger n) {
            if (n == 0) return 1;
            BigInteger res = 1;
            while (n > 0) {
                res *= n--;
            }
            return res;
        }
 
        static BigInteger Lah(BigInteger n, BigInteger k) {
            if (k == 1) return Factorial(n);
            if (k == n) return 1;
            if (k > n) return 0;
            if (k < 1 || n < 1) return 0;
            return (Factorial(n) * Factorial(n - 1)) / (Factorial(k) * Factorial(k - 1)) / Factorial(n - k);
        }
 
        static void Main() {
            Console.WriteLine("Unsigned Lah numbers: L(n, k):");
            Console.Write("n/k ");
            foreach (var i in Enumerable.Range(0, 13)) {
                Console.Write("{0,10} ", i);
            }
            Console.WriteLine();
            foreach (var row in Enumerable.Range(0, 13)) {
                Console.Write("{0,-3}", row);
                foreach (var i in Enumerable.Range(0, row + 1)) {
                    var l = Lah(row, i);
                    Console.Write("{0,11}", l);
                }
                Console.WriteLine();
            }
            Console.WriteLine("\nMaximum value from the L(100, *) row:");
            var maxVal = Enumerable.Range(0, 100).Select(a => Lah(100, a)).Max();
            Console.WriteLine(maxVal);
        }
    }
}

using SharpDX.Direct3D11;
using System;

public static class TextureFXActions
{
    public static void ApplyTargetSize(EffectScalarVariable targetWidthVar, EffectScalarVariable targetHeightVar, TextureFXSettings settings)
    {
        targetWidthVar.Set(settings.CurrentRenderTarget.Width);
        targetHeightVar.Set(settings.CurrentRenderTarget.Height);
    }

    public static void ApplyInvTargetSize(EffectScalarVariable invWidthVar, EffectScalarVariable invHeightVar, TextureFXSettings settings)
    {
        invWidthVar.Set(1.0f / settings.CurrentRenderTarget.Width);
        invHeightVar.Set(1.0f / settings.CurrentRenderTarget.Height);
    }

    public static void ApplyFullTargetSize(EffectVectorVariable fullSizeVar, TextureFXSettings settings)
    {
        fullSizeVar.Set(new Vector2(settings.CurrentRenderTarget.Width, settings.CurrentRenderTarget.Height));
    }

    public static void ApplyInitialTexture(EffectShaderResourceVariable textureVar, TextureFXSettings settings)
    {
        if (settings.InitialTexture != null)
        {
            textureVar.SetResource(settings.InitialTexture);
        }
    }

    public static void ApplyPreviousTexture(EffectShaderResourceVariable textureVar, TextureFXSettings settings)
    {
        if (settings.PreviousTexture != null)
        {
            textureVar.SetResource(settings.PreviousTexture);
        }
    }

    public static void ApplyPassIndex(EffectScalarVariable passIndexVar, int passIndex)
    {
        passIndexVar.Set(passIndex);
    }
}

public class TextureFXSettings
{
    public RenderTargetView CurrentRenderTarget { get; set; }
    public ShaderResourceView InitialTexture { get; set; }
    public ShaderResourceView PreviousTexture { get; set; }
}

public class TextureFXPassSettings
{
    public int PassIndex { get; set; }
    public TextureFXSettings Settings { get; set; }

    public TextureFXPassSettings(int passIndex, TextureFXSettings settings)
    {
        PassIndex = passIndex;
        Settings = settings;
    }
}

