namespace Utils
{
    class Queue
    {
        static void Main(string[] args)
        {
            char[] chars = { 'X', 'Y', 'Z' };
            int headgap = 3;
            int bodygap = 3;
            int tablegap = 6;
            int rowgap = 9;
            string tabletext = "<html>\n";
            makeGap(headgap, ref tabletext);
            tabletext += "<head></head>\n";
            makeGap(bodygap, ref tabletext);
            tabletext += "<body>\n";
            makeGap(tablegap, ref tabletext);
            tabletext += "<table>\n";
            makeGap(tablegap + 1, ref tabletext);
            tabletext += "<thead align=\"right\">\n";
            makeGap(tablegap, ref tabletext);
            tabletext += "<tr><th></th>";
            for (int i = 0; i < 3; i++)
            {
                tabletext += "<td>";
                tabletext += chars[i];
                tabletext += "</td>";
            }
            tabletext += "</tr>\n";
            makeGap(tablegap + 1, ref tabletext);
            tabletext += "</thead>";
            makeGap(tablegap + 1, ref tabletext);
            tabletext += "<tbody align=\"right\">\n";
            Random rand = new Random();
            for (int row = 0; row < 5; row++)
            {
                makeGap(rowgap, ref tabletext);
                tabletext += "<tr><td>";
                tabletext += row.ToString();
                for (int col = 0; col < 3; col++)
                {
                    int randnumber = rand.Next(10000);
                    tabletext += "<td>";
                    tabletext += randnumber.ToString();
                    tabletext += "</td>";
                }
                tabletext += "</tr>\n";
            }
            makeGap(tablegap + 1, ref tabletext);
            tabletext += "</tbody>\n";
            makeGap(tablegap, ref tabletext);
            tabletext += "</table>\n";
            makeGap(bodygap, ref tabletext);
            tabletext += "</body>\n";
            tabletext += "</html>\n";
            StreamWriter htmltable = new StreamWriter("testtable.html", false);
            htmltable.Write(tabletext);
            htmltable.Close();
        }
        static void makeGap(int gap, ref string text)
        {
            for (int i = 0; i < gap; i++)
            {
                text += " ";
            }
        }
    }
}

using System;
using System.IO;
// Needed for the method.
using System.Text.RegularExpressions;
using System.Collections.Generic;
 
void Main()
{
   string blocks = "BO XK DQ CP NA GT RE TG QD FS JW HU VI AN OB ER FS LY PC ZM";
   List<string> words = new List<string>() {
      "A", "BARK", "BOOK", "TREAT", "COMMON", "SQUAD", "CONFUSE"
   };
 
   foreach(var word in words)
   {
      Console.WriteLine("{0}: {1}", word, CheckWord(blocks, word));
   }
}
 
bool CheckWord(string blocks, string word)
{
   for(int i = 0; i < word.Length; ++i)
   {
      int length = blocks.Length;
      Regex rgx = new Regex("([a-z]"+word[i]+"|"+word[i]+"[a-z])", RegexOptions.IgnoreCase);
      blocks = rgx.Replace(blocks, "", 1);
      if(blocks.Length == length) return false;
   }
   return true;
}

