    public static class StringEncryptionExtensions
    {
        // Hard-coded secret key (only a portion will be used as the encryption key)
        private const string SecretKey = "MySuperSecretKey123456";

        // Fixed initialization vector (8 bytes for DES)
        private static readonly byte[] InitializationVector = { 0x12, 0x34, 0x56, 0x78, 0x90, 0xAB, 0xCD, 0xEF };

        /// <summary>
        /// Encrypts a plain text string using DES symmetric encryption and returns a Base64 encoded string.
        /// </summary>
        public static string Encrypt(this string plainText)
        {
            if (plainText == null)
            {
                throw new ArgumentNullException(nameof(plainText));
            }

            // Extract the first 8 characters from the secret key and convert to bytes (DES requires 8 bytes)
            byte[] keyBytes = Encoding.UTF8.GetBytes(SecretKey.Substring(0, 8));

            byte[] encryptedBytes;
            using (DESCryptoServiceProvider desProvider = new DESCryptoServiceProvider())
            {
                desProvider.Key = keyBytes;
                desProvider.IV = InitializationVector;

                ICryptoTransform encryptor = desProvider.CreateEncryptor();
                using (MemoryStream memoryStream = new MemoryStream())
                {
                    using (CryptoStream cryptoStream = new CryptoStream(memoryStream, encryptor, CryptoStreamMode.Write))
                    {
                        byte[] plainBytes = Encoding.UTF8.GetBytes(plainText);
                        cryptoStream.Write(plainBytes, 0, plainBytes.Length);
                        cryptoStream.FlushFinalBlock();
                    }
                    encryptedBytes = memoryStream.ToArray();
                }
            }

            // Convert the encrypted byte array to a Base64 string.
            return Convert.ToBase64String(encryptedBytes);
        }

