using System;
class Finder
{
    public static long Ackermann(long m, long n)
    {
        if(m > 0)
        {
            if (n > 0)
                return Ackermann(m - 1, Ackermann(m, n - 1));
            else if (n == 0)
                return Ackermann(m - 1, 1);
        }
        else if(m == 0)
        {
            if(n >= 0)
                return n + 1;
        }
 
        throw new System.ArgumentOutOfRangeException();
    }
 
    static void Main()
    {
        for (long m = 0; m <= 3; ++m)
        {
            for (long n = 0; n <= 4; ++n)
            {
                Console.WriteLine("Ackermann({0}, {1}) = {2}", m, n, Ackermann(m, n));
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using SAPFEWSELib;
using SAPGuiAutomationLib;

namespace SAPSessionManager
{
    public partial class SAPSessionInfo : UserControl
    {
        private GuiSession _currentSession;
        private readonly SAPAutomationHelper _sapHelper;

        public SAPSessionInfo()
        {
            InitializeComponent();
            _sapHelper = new SAPAutomationHelper();
            _sapHelper.SessionSet += Current_OnSetSession;
        }

        private void Current_OnSetSession(object sender, GuiSession session)
        {
            _currentSession = session;
            _currentSession.EndRequest += session_EndRequest;
            _currentSession.Destroy += session_Destroy;
            ShowSessionInfo();
        }

        private void session_EndRequest()
        {
            Dispatcher.InvokeAsync(() => ShowSessionInfo());
        }

        private void session_Destroy()
        {
            Dispatcher.InvokeAsync(() => lv_SessionInfo.Items.Clear());
            _currentSession = null;
        }

        private void ShowSessionInfo()
        {
            if (_currentSession == null) return;

            lv_SessionInfo.Items.Clear();
            var sessionProperties = GetSessionProperties(_currentSession);

            foreach (var prop in sessionProperties)
            {
                lv_SessionInfo.Items.Add(new { Property = prop.Key, Value = prop.Value });
            }
        }

        private Dictionary<string, object> GetSessionProperties(GuiSession session)
        {
            var properties = new Dictionary<string, object>();
            Type sessionType = session.GetType();

            foreach (PropertyInfo prop in sessionType.GetProperties())
            {
                try
                {
                    object value = prop.GetValue(session);
                    properties.Add(prop.Name, value ?? "N/A");
                }
                catch
                {
                    properties.Add(prop.Name, "Error retrieving value");
                }
            }

            return properties;
        }
    }

    public class SAPAutomationHelper
    {
        public event EventHandler<GuiSession> SessionSet;

        public void OnSessionSet(GuiSession session)
        {
            SessionSet?.Invoke(this, session);
        }
    }
}

using System;
using System.Collections.Generic;
using AutoMapper;

public interface IRealm
{
    string BaseCdnUrl { get; set; }
    string CurrentVersion { get; set; }
    string Language { get; set; }
    Dictionary<string, string> LatestChangedVersionForEachDataType { get; set; }
}

public class RealmDto
{
    public string cdn { get; set; }
    public string version { get; set; }
    public string language { get; set; }
    public Dictionary<string, string> n { get; set; }
}

public class Realm : IRealm
{
    public string BaseCdnUrl { get; set; }
    public string CurrentVersion { get; set; }
    public string Language { get; set; }
    public Dictionary<string, string> LatestChangedVersionForEachDataType { get; set; }

    public static IMapper CreateRealmMapper()
    {
        var config = new MapperConfiguration(cfg =>
        {
            cfg.CreateMap<RealmDto, Realm>()
               .ForMember(dest => dest.BaseCdnUrl, opt => opt.MapFrom(src => src.cdn))
               .ForMember(dest => dest.CurrentVersion, opt => opt.MapFrom(src => src.version))
               .ForMember(dest => dest.Language, opt => opt.MapFrom(src => src.language))
               .ForMember(dest => dest.LatestChangedVersionForEachDataType,
                          opt => opt.MapFrom(src => src.n));

            cfg.CreateMap<Realm, RealmDto>()
               .ForMember(dest => dest.cdn, opt => opt.MapFrom(src => src.BaseCdnUrl))
               .ForMember(dest => dest.version, opt => opt.MapFrom(src => src.CurrentVersion))
               .ForMember(dest => dest.language, opt => opt.MapFrom(src => src.Language))
               .ForMember(dest => dest.n, opt => opt.MapFrom(src => src.LatestChangedVersionForEachDataType));
        });

        return config.CreateMapper();
    }
}

public class RealmService
{
    private readonly IMapper _mapper;

    public RealmService()
    {
        _mapper = Realm.CreateRealmMapper();
    }

    public Realm TransformRealmData(RealmDto realmDto)
    {
        return _mapper.Map<Realm>(realmDto);
    }
}

public static void print<T>(Node<T> N)
{
