using System;
using System.Collections;

using Nequeo.Cryptography.Key.Asn1;

namespace Nequeo.Cryptography.Key.Asn1.CryptoPro
{
    public class Gost28147Parameters
        : Asn1Encodable
    {
        private readonly Asn1OctetString iv;
        private readonly DerObjectIdentifier paramSet;

        public static Gost28147Parameters GetInstance(
            Asn1TaggedObject    obj,
            bool                explicitly)
        {
            return GetInstance(Asn1Sequence.GetInstance(obj, explicitly));
        }

        public static Gost28147Parameters GetInstance(
            object obj)
        {
            if (obj == null || obj is Gost28147Parameters)
            {
                return (Gost28147Parameters) obj;
            }

            if (obj is Asn1Sequence)
            {
                return new Gost28147Parameters((Asn1Sequence) obj);
            }

            throw new ArgumentException("Invalid GOST3410Parameter: " + obj.GetType().Name);
        }

        private Gost28147Parameters(
            Asn1Sequence seq)
        {
            if (seq.Count != 2)
                throw new ArgumentException("Wrong number of elements in sequence", "seq");

            this.iv = Asn1OctetString.GetInstance(seq[0]);
            this.paramSet = DerObjectIdentifier.GetInstance(seq[1]);
        }

        /**
         * <pre>
         * Gost28147-89-Parameters ::=
         *               SEQUENCE {
         *                       iv                   Gost28147-89-IV,
         *                       encryptionParamSet   OBJECT IDENTIFIER
         *                }
         *
         *   Gost28147-89-IV ::= OCTET STRING (SIZE (8))
         * </pre>
         */
        public override Asn1Object ToAsn1Object()
        {
            return new DerSequence(iv, paramSet);
        }
    }
}

using System;
using System.Threading.Tasks;
using Serilog;
using Tapeti;
using Tapeti.Config;
using Tapeti.Connection;
using SimpleInjector;

public class Shape
{
    private static readonly Container container = new Container();

    public static async Task Main(string[] args)
    {
        Log.Logger = new LoggerConfiguration()
            .Enrich.FromLogContext()
            .WriteTo.Console(outputTemplate: "{Timestamp:HH:mm:ss} [{Level}] {Message}{NewLine}{Exception}")
            .CreateLogger();

        container.RegisterInstance<ILogger>(Log.Logger);
        container.Verify();

        try
        {
            await MainAsync();
        }
        catch (Exception ex)
        {
            Log.Fatal(ex, "Application terminated unexpectedly");
        }
        finally
        {
            Log.CloseAndFlush();
        }
    }

    private static async Task MainAsync()
    {
        var config = new TapetiConfig(container)
            .UseSerilog()
            .RegisterAllControllers()
            .SetConnectionString("host=localhost;username=guest;password=guest");

        using var connection = new TapetiConnection(config);
        await connection.Connect();

        var publisher = container.GetInstance<IPublisher>();
        var subscriber = container.GetInstance<ISubscriber>();

        await Publish(publisher);

        await subscriber.Start();
        Console.WriteLine("Press any key to exit...");
        Console.ReadKey();
        await subscriber.Stop();
    }

    private static async Task Publish(IPublisher publisher)
    {
        await publisher.Publish(new PublishSubscribeMessage
        {
            Id = Guid.NewGuid(),
            Content = "Sample message content"
        });
        Log.Information("Published message");
    }
}

public class PublishSubscribeMessage
{
    public Guid Id { get; set; }
    public string Content { get; set; }
}

