using System;
using System.IO;
using System.Diagnostics;

public class ScriptExecutionManager
{
    public class Input
    {
        public string ConnectionName { get; set; }
        public string[] Scripts { get; set; }
        public bool VerboseMode { get; set; }
    }

    public void Execute(Input input)
    {
        if (input == null || input.Scripts == null || input.Scripts.Length == 0)
        {
            throw new ArgumentException("Invalid script configuration");
        }

        foreach (string scriptPath in input.Scripts)
        {
            if (!File.Exists(scriptPath))
            {
                Console.WriteLine($"Script not found: {scriptPath}");
                continue;
            }

            string extension = Path.GetExtension(scriptPath).ToLower();
            switch (extension)
            {
                case ".sql":
                    RunSql(scriptPath, input.ConnectionName);
                    break;
                case ".py":
                    RunPythonScript(scriptPath, input.VerboseMode);
                    break;
                default:
                    Console.WriteLine($"Unsupported script type: {extension}");
                    break;
            }
        }
    }

    private void RunSql(string scriptPath, string connectionName)
    {
        try
        {
            // Placeholder for SQL script execution logic
            Console.WriteLine($"Executing SQL script: {scriptPath} on {connectionName}");
            // Implement actual database script execution
        }
        catch (Exception ex)
        {
            Console.WriteLine($"SQL Execution Error: {ex.Message}");
        }
    }

    private void RunPythonScript(string scriptPath, bool verboseMode)
    {
        try
        {
            ProcessStartInfo processInfo = new ProcessStartInfo
            {
                FileName = "python",
                Arguments = GetPythonArguments(scriptPath, verboseMode),
                UseShellExecute = false,
                RedirectStandardOutput = true,
                CreateNoWindow = !verboseMode
            };

            using (Process process = Process.Start(processInfo))
            {
                if (verboseMode)
                {
                    string output = process.StandardOutput.ReadToEnd();
                    Console.WriteLine($"Python Script Output: {output}");
                }

                process.WaitForExit();
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Python Execution Error: {ex.Message}");
        }
    }

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using Uduino;

public class MegaReadWrite : MonoBehaviour
{
    private int pin14 = 14; // Analog pin A14
    private int digitalPin42 = 42; // Digital pin 42

    void Start()
    {
        UduinoManager.Instance.OnBoardConnected += BoardConnected;
        UduinoManager.Instance.Connect("COM3"); // Connect to the Arduino board, change COM port as necessary
    }

    void BoardConnected(UduinoDevice device)
    {
        Debug.Log("Arduino connected: " + device.Name);
        UduinoManager.Instance.pinMode(pin14, PinMode.Analog);
        UduinoManager.Instance.pinMode(digitalPin42, PinMode.Output);
        Debug.Log("Pin " + pin14 + " configured as Analog Input.");
        Debug.Log("Pin " + digitalPin42 + " configured as Digital Output.");
    }

    void Update()
    {
        if (UduinoManager.Instance.IsConnected())
        {
            int analogValue = UduinoManager.Instance.analogRead(pin14);
            Debug.Log("Analog value from pin " + pin14 + ": " + analogValue);
            UduinoManager.Instance.digitalWrite(digitalPin42, PinState.HIGH);
        }
    }

    void OnDestroy()
    {
        UduinoManager.Instance.OnBoardConnected -= BoardConnected;
        UduinoManager.Instance.Disconnect();
    }
}

