using NHibernate.Cfg;
using NHibernate.Dialect;
using NHibernate.Tool.hbm2ddl;
using NUnit.Framework;
using System.Text.RegularExpressions;

[TestFixture]
public class SchemaGenerationTests
{
    private Configuration cfg;
    private string script;

    [SetUp]
    public void Setup()
    {
        cfg = new Configuration();
        cfg.SetProperty(Environment.Dialect, typeof(MsSql2012Dialect).FullName);
        cfg.SetProperty(Environment.ConnectionString, "Server=.;Database=test;Integrated Security=SSPI");
    }

    private void Bug(string expectedCatalog, string expectedSchema)
    {
        var schemaExport = new SchemaExport(cfg);
        schemaExport.Execute(s => script = s, false, false);

        var createPattern = $@"CREATE TABLE \[{expectedCatalog}\]\.\[{expectedSchema}\]\.Aclass";
        StringAssert.IsMatch(createPattern, script);

        var dialect = Dialect.GetDialect(cfg.Properties);
        var dropPattern = dialect.SupportsIfExistsBeforeTableName
            ? $@"DROP TABLE IF EXISTS \[{expectedCatalog}\]\.\[{expectedSchema}\]\.Aclass"
            : $@"DROP TABLE \[{expectedCatalog}\]\.\[{expectedSchema}\]\.Aclass";

        Assert.IsTrue(Regex.IsMatch(script, dropPattern));
    }

    [Test]
    public void WithDefaultValuesInConfiguration()
    {
        cfg.SetProperty(Environment.DefaultCatalog, "config_catalog");
        cfg.SetProperty(Environment.DefaultSchema, "config_schema");
        cfg.AddResource("AclassWithNoDefaults.hbm.xml", GetType().Assembly);
        Bug("config_catalog", "config_schema");
    }

    [Test]
    public void WithDefaultValuesInMapping()
    {
        cfg.AddResource("AclassWithDefaults.hbm.xml", GetType().Assembly);
        Bug("mapping_catalog", "mapping_schema");
    }

    [Test]
    public void ConfigurationOverridesMapping()
    {
        cfg.SetProperty(Environment.DefaultCatalog, "override_catalog");
        cfg.SetProperty(Environment.DefaultSchema, "override_schema");
        cfg.AddResource("AclassWithDefaults.hbm.xml", GetType().Assembly);
        Bug("override_catalog", "override_schema");
    }

    [Test]
    public void PartialConfigurationCombinesWithMapping()
    {
        cfg.SetProperty(Environment.DefaultSchema, "partial_schema");
        cfg.AddResource("AclassWithDefaults.hbm.xml", GetType().Assembly);
        Bug("mapping_catalog", "partial_schema");
    }
}

