[TestClass]
public class PosixSignalHandlerTests
{
    private Mock<IServerControl> _mockServerControl;
    private Mock<IAsyncDelayer> _mockAsyncDelayer;
    private PosixSignalHandler _signalHandler;

    [TestInitialize]
    public void Setup()
    {
        _mockServerControl = new Mock<IServerControl>();
        _mockAsyncDelayer = new Mock<IAsyncDelayer>();
        _signalHandler = new PosixSignalHandler(
            _mockServerControl.Object,
            _mockAsyncDelayer.Object,
            Mock.Of<ILogger>()
        );
    }

    [TestMethod]
    public async Task StartAsync_InitializeSignalHandler_ShouldSucceed()
    {
        var cancellationTokenSource = new CancellationTokenSource();
        var startTask = _signalHandler.StartAsync(cancellationTokenSource.Token);

        await Task.Delay(100);
        Assert.IsTrue(_signalHandler.IsRunning);
    }

    [TestMethod]
    [ExpectedException(typeof(InvalidOperationException))]
    public async Task StartAsync_MultipleInitialization_ShouldThrowException()
    {
        var cancellationTokenSource = new CancellationTokenSource();
        await _signalHandler.StartAsync(cancellationTokenSource.Token);
        await _signalHandler.StartAsync(cancellationTokenSource.Token);
    }

    [TestMethod]
    public async Task SignalHandler_GracefulShutdown_ShouldInvokeServerControl()
    {
        var tcs = new TaskCompletionSource<bool>();
        _mockServerControl
            .Setup(x => x.ShutdownAsync(It.IsAny<CancellationToken>()))
            .Returns(tcs.Task);

        var cancellationTokenSource = new CancellationTokenSource();
        await _signalHandler.StartAsync(cancellationTokenSource.Token);

        // Simulate SIGTERM
        Mono.Unix.Native.Signal.Raise(Signum.SIGTERM);

        tcs.SetResult(true);
        await Task.Delay(200);

        _mockServerControl.Verify(x => x.ShutdownAsync(It.IsAny<CancellationToken>()), Times.Once);
    }
}

