    public class Title : BaseFormattingObject
    {
        private string titleText;
        private string font;
        private Color color;
        private int margin;
        private bool isVisible;

        public Title(string titleText, string font, Color color, int margin, bool isVisible)
        {
            this.titleText = titleText;
            this.font = font;
            this.color = color;
            this.margin = margin;
            this.isVisible = isVisible;
        }

        public override void Layout(Area area)
        {
            if (!isVisible) return;
            // Retrieve properties from the property manager
            FontMetrics fontMetrics = PropertyManager.GetFontMetrics(font);
            Position position = new Position(margin, margin + fontMetrics.Height);

            // Calculate layout position based on properties
            RenderTitle(area, position);
        }

        private void RenderTitle(Area area, Position position)
        {
            // Logic to render the title at the given position with the set font and color
            area.DrawText(titleText, position, font, color);
        }

        public static Maker GetMaker()
        {
            return new Maker();
        }

