namespace NumberGuessingGame
{
    public class OverUnderProgram : ProgramBase
    {
        private readonly GameLoop _gameLoop;
        public OverUnderProgram(GameLoop gameLoop) => _gameLoop = gameLoop;
        public override void Run() => _gameLoop.Begin();
    }

    public class GameLoop
    {
        private readonly StaticRandomNumberValueProvider _targetProvider;
        private readonly GuessANumber _guessPrompt;
        private readonly YouWin _youWin;
        private readonly TooHigh _tooHigh;
        private readonly TooLow _tooLow;

        public GameLoop(StaticRandomNumberValueProvider targetProvider, GuessANumber guessPrompt, YouWin youWin, TooHigh tooHigh, TooLow tooLow)
        {
            _targetProvider = targetProvider;
            _guessPrompt = guessPrompt;
            _youWin = youWin;
            _tooHigh = tooHigh;
            _tooLow = tooLow;
        }

        public void Begin()
        {
            int target = _targetProvider.Provide();
            while (true)
            {
                Console.Write(_guessPrompt.Provide());
                if (!int.TryParse(Console.ReadLine(), out int guess))
                {
                    Console.WriteLine("Invalid input. Please enter a number.");
                    continue;
                }

                if (!new NotEqualsCondition(target, guess).Provide())
                {
                    Console.WriteLine(_youWin.Provide());
                    return;
                }

                Console.WriteLine(new GreaterThanCondition(target, guess).Provide()
                    ? _tooLow.Provide()
                    : _tooHigh.Provide());
            }
        }
    }

    public class StaticRandomNumberValueProvider
    {
        private static readonly Lazy<int> _target = new Lazy<int>(() => new Random().Next(100));
        public int Provide() => _target.Value;
    }

    public class NotEqualsCondition
    {
        private readonly int _a, _b;
        public NotEqualsCondition(int a, int b) { _a = a; _b = b; }
        public bool Provide() => _a != _b;
    }

    public class GreaterThanCondition
    {
        private readonly int _a, _b;
        public GreaterThanCondition(int a, int b) { _a = a; _b = b; }
        public bool Provide() => _a > _b;
    }

    public class LessThanCondition
    {
        private readonly int _a, _b;
        public LessThanCondition(int a, int b) { _a = a; _b = b; }
        public bool Provide() => _a < _b;
    }

