using System;
using System.Linq;

namespace Cholesky
{
    class Account
    {
        static double[][] chol(double[][] a)
        {
            int m = a.Length;
            double[][] l = new double[m][];
            for (int i = 0; i < m; i++)
            {
                l[i] = new double[m];
                for (int k = 0; k < (i + 1); k++)
                {
                    double sum = 0;
                    for (int j = 0; j < k; j++)
                    {
                        sum += l[i][j] * l[k][j];
                    }
                    l[i][k] = (i == k)? Math.Sqrt(a[i][i] - sum) : (1.0 / l[k][k] * (a[i][k] - sum));
                }
            }
            return l;
        }

        static void Main(string[] args)
        {
            double[][] test1 = new double[][] { new double[] { 25, 15, -5 }, new double[] { 15, 18, 0 }, new double[] { -5, 0, 11 } };
            Console.WriteLine(string.Join("\n", test1.Select(x => string.Join(" ", x))));
            double[][] test2 = new double[][] { new double[] { 18, 22, 54, 42 }, new double[] { 22, 70, 86, 62 }, new double[] { 54, 86, 174, 134 }, new double[] { 42, 62, 134, 106 } };
            Console.WriteLine(string.Join("\n", test2.Select(x => string.Join(" ", x))));
        }
    }
}

