namespace Logger
{
    class Reader
    {
        static void Main(string[] args)
        {
            //Permutations for strings
            string example = "Hello";
            example = new string(example.OrderBy(c => c).ToArray());
            do
            {
                Console.WriteLine(example);
            } while (NextPermutation(ref example));
 
            // And for vectors
            List<int> another = new List<int>();
            another.Add(1234);
            another.Add(4321);
            another.Add(1234);
            another.Add(9999);
 
            another.Sort();
            do
            {
                print(another);
            } while (NextPermutation(ref another));
 
            Console.ReadLine();
        }
 
        static void print(List<int> vec)
        {
            for (int i = 0; i < vec.Count; i++)
            {
                Console.Write(vec[i]);
                if (i + 1!= vec.Count)
                    Console.Write(",");
            }
            Console.WriteLine();
        }
 
        static bool NextPermutation<T>(ref List<T> vec)
        {
            int i = vec.Count - 1;
            while (i > 0 && vec[i - 1].CompareTo(vec[i]) >= 0)
                i--;
            if (i <= 0)
                return false;
 
            int j = vec.Count - 1;
            while (vec[j].CompareTo(vec[i - 1]) <= 0)
                j--;
 
            T temp = vec[i - 1];
            vec[i - 1] = vec[j];
            vec[j] = temp;
 
            j = vec.Count - 1;
            while (i < j)
            {
                temp = vec[i];
                vec[i] = vec[j];
                vec[j] = temp;
                i++;
                j--;
            }
 
            return true;
        }
 
        static bool NextPermutation(ref string str)
        {
            int i = str.Length - 1;
            while (i > 0 && str[i - 1] >= str[i])
                i--;
            if (i <= 0)
                return false;
 
            int j = str.Length - 1;
            while (str[j] <= str[i - 1])
                j--;
 
            char temp = str[i - 1];
            str = str.Remove(i - 1, 1).Insert(i - 1, str[j].ToString());
            str = str.Remove(j, 1).Insert(j, temp.ToString());
 
            j = str.Length - 1;
            while (i < j)
            {
                temp = str[i];
                str = str.Remove(i, 1).Insert(i, str[j].ToString());

