abstract class DNSRecordBase
{
    public string DomainName { get; protected set; }
    public uint TimeToLive { get; protected set; }

    public DNSRecordBase(string domainName, uint timeToLive)
    {
        DomainName = domainName;
        TimeToLive = timeToLive;
    }
}

interface IDNSTextRecord
{
    string Text { get; set; }
    byte[] Encode();
}

static class DNSUtils
{
    public static List<string> ParseTextSegments(byte[] data, int start, int length)
    {
        List<string> segments = new List<string>();
        int index = start;
        int end = start + length;
        while (index < end)
        {
            byte segmentLength = data[index++];
            if (index + segmentLength > end)
                throw new ArgumentException("Invalid text segment length in DNS record.");
            string segment = Encoding.UTF8.GetString(data, index, segmentLength);
            segments.Add(segment);
            index += segmentLength;
        }
        return segments;
    }

    public static byte[] EncodeTextSegments(string text)
    {
        // Convert the full text into UTF8 bytes
        byte[] textBytes = Encoding.UTF8.GetBytes(text);
        List<byte> result = new List<byte>();
        int index = 0;
        // DNS text segments are limited to 255 bytes each.
        while (index < textBytes.Length)
        {
            int remaining = textBytes.Length - index;
            int segmentSize = Math.Min(255, remaining);
            result.Add((byte)segmentSize);
            result.AddRange(textBytes.Skip(index).Take(segmentSize));
            index += segmentSize;
        }
        return result.ToArray();
    }
}

class DNSTextRecord : DNSRecordBase, IDNSTextRecord
{
    public string Text { get; set; }

    public DNSTextRecord(string domainName, uint timeToLive, string text)
        : base(domainName, timeToLive)
    {
        Text = text;
    }

    public static DNSTextRecord Parse(string domainName, uint timeToLive, byte[] data, int offset, int length)
    {
        List<string> segments = DNSUtils.ParseTextSegments(data, offset, length);
        string fullText = string.Join("", segments);
        return new DNSTextRecord(domainName, timeToLive, fullText);
    }

    public byte[] Encode()
    {
        return DNSUtils.EncodeTextSegments(Text);
    }

