    public class Function : IFunction
    {
        private string _name;
        private string _definition;
        private ISource _source;

        public Function(string name, string definition, ISource source)
        {
            if (string.IsNullOrEmpty(name))
                throw new ArgumentException("Name cannot be null or empty.", nameof(name));
            if (string.IsNullOrEmpty(definition))
                throw new ArgumentException("Definition cannot be null or empty.", nameof(definition));
            if (source == null)
                throw new ArgumentNullException(nameof(source));

            _name = name;
            _definition = definition;
            _source = source;
        }

        public string Name
        {
            get => _name;
            set
            {
                if (string.IsNullOrEmpty(value))
                    throw new ArgumentException("Name cannot be null or empty.", nameof(value));
                _name = value;
            }
        }

        public string Definition
        {
            get => _definition;
            set
            {
                if (string.IsNullOrEmpty(value))
                    throw new ArgumentException("Definition cannot be null or empty.", nameof(value));
                _definition = value;
            }
        }

        public ISource Source
        {
            get => _source;
            set
            {
                if (value == null)
                    throw new ArgumentNullException(nameof(value));
                _source = value;
            }
        }

        public void Execute()
        {
            // Logic to execute the function in the database
            Console.WriteLine($"Executing function: {_name}");
        }

        public override string ToString()
        {
            return $"Function Name: {_name}, Definition: {_definition}, Source: {_source.Name}";
        }
    }

