namespace UwpApp.Common
{
    public abstract class PageBase : Page
    {
        private const string StateKey = "PageState";
        private readonly NavigationHelper _navigationHelper;

        protected PageBase()
        {
            _navigationHelper = new NavigationHelper(this);
            _navigationHelper.LoadState += NavigationHelperLoadState;
            _navigationHelper.SaveState += NavigationHelperSaveState;
        }

        protected override void OnNavigatedTo(NavigationEventArgs e)
        {
            _navigationHelper.OnNavigatedTo(e);
        }

        protected override void OnNavigatedFrom(NavigationEventArgs e)
        {
            _navigationHelper.OnNavigatedFrom(e);
        }

        protected virtual void LoadState(object sender, LoadStateEventArgs e)
        {
            // Implement custom state loading logic in derived classes
        }

        protected virtual void SaveState(object sender, SaveStateEventArgs e)
        {
            // Implement custom state saving logic in derived classes
        }

        private void NavigationHelperLoadState(object sender, LoadStateEventArgs e)
        {
            if (e.PageState != null && e.PageState.ContainsKey(StateKey))
            {
                var pageState = e.PageState[StateKey] as SerializableState;
                if (pageState != null)
                {
                    LoadState(sender, e);
                }
            }
        }

        private void NavigationHelperSaveState(object sender, SaveStateEventArgs e)
        {
            var pageState = new SerializableState();
            SaveState(sender, e);
            e.PageState[StateKey] = pageState;
        }

        private class SerializableState
        {
            // Define properties to store state information
        }
    }

    public class NavigationHelper
    {
        private readonly Page _page;

        public NavigationHelper(Page page)
        {
            _page = page;
        }

        public event TypedEventHandler<Page, LoadStateEventArgs> LoadState;
        public event TypedEventHandler<Page, SaveStateEventArgs> SaveState;

        public void OnNavigatedTo(NavigationEventArgs e)
        {
            var args = new LoadStateEventArgs(e.Parameter, e.NavigationMode, null);
            LoadState?.Invoke(_page, args);
        }

        public void OnNavigatedFrom(NavigationEventArgs e)
        {
            var args = new SaveStateEventArgs();
            SaveState?.Invoke(_page, args);

using UnityEngine;
using UnityEngine.UI;

public class HealthTracker : MonoBehaviour
{
    public float maxHealth = 100f;
    public bool isPlayer = false;
    public RectTransform healthBar;
    public float interpolationSpeed = 5f;

    private float currentHealth;
    private float displayedHealth;
    private static float savedHealth;

    void Start()
    {
        currentHealth = isPlayer && savedHealth > 0 ? savedHealth : maxHealth;
        displayedHealth = currentHealth;
        UpdateHealthBar();
    }

    public void DealDamage(float damage)
    {
        currentHealth = Mathf.Max(currentHealth - damage, 0);

        if (currentHealth <= 0)
        {
            if (isPlayer) GameManager.Instance.GameOver();
            else Destroy(gameObject);
        }
    }

    public void SetHealth(float health)
    {
        currentHealth = Mathf.Clamp(health, 0, maxHealth);
        if (!isPlayer) displayedHealth = currentHealth;
        UpdateHealthBar();
    }

    void Update()
    {
        if (Mathf.Abs(displayedHealth - currentHealth) > 0.1f)
        {
            displayedHealth = Mathf.Lerp(displayedHealth, currentHealth, interpolationSpeed * Time.deltaTime);
            UpdateHealthBar();
        }
    }

    void UpdateHealthBar()
    {
        if (healthBar == null) return;
        Vector3 scale = healthBar.localScale;
        scale.x = displayedHealth / maxHealth;
        healthBar.localScale = scale;
    }

    void OnDestroy()
    {
        if (isPlayer) savedHealth = currentHealth;
    }

    public void FullHeal()
    {
        currentHealth = maxHealth;
        displayedHealth = maxHealth;
        UpdateHealthBar();
    }
}

