    public partial class EmployeeManagerGrids : Form
    {
        private BindingSource employeeBindingSource;
        private BindingSource managerBindingSource;

        public EmployeeManagerGrids()
        {
            InitializeComponent();
            LoadData();
        }

        private void LoadData()
        {
            Northwind db = new Northwind(Validator.connString);

            var employees = from emp in db.Employees
                            orderby emp.LastName
                            select emp;

            employeeBindingSource = new BindingSource();
            employeeBindingSource.DataSource = employees;
            employeeDataGridView.DataSource = employeeBindingSource;

             managerBindingSource = new BindingSource();
             managerBindingSource.DataSource = employees.ToList();

        }

        private void employeeDataGridView_CellParsing(object sender, DataGridViewCellParsingEventArgs e)
        {
            if (employeeDataGridView.Columns[e.ColumnIndex].Name == "ManagerID" && e.Value != null)
            {
                Northwind db = new Northwind(Validator.connString);
                string managerName = e.Value.ToString();
                Employee manager = db.Employees.FirstOrDefault(emp => emp.FirstName + " " + emp.LastName == managerName);
                e.Value = manager;
                e.ParsingApplied = true;
            }
        }

        private void btnSubmitChanges_Click(object sender, EventArgs e)
        {
            Validate();
            employeeBindingSource.EndEdit();

            Northwind db = new Northwind(Validator.connString);
            try
            {
                db.SubmitChanges();
                MessageBox.Show("Changes submitted successfully.");
            }
            catch (Exception ex)
            {
                MessageBox.Show("Error submitting changes: " + ex.Message);
            }
        }
    }

