namespace GenuineChannels.Http
{
    /// <summary>
    /// Defines the different types of HTTP packets used in Genuine Channels.
    /// </summary>
    public enum HttpPacketType
    {
        /// <summary>
        /// Represents a standard HTTP message packet.
        /// </summary>
        Message,

        /// <summary>
        /// Indicates a request to establish a new connection.
        /// </summary>
        ConnectRequest,

        /// <summary>
        /// Indicates an ACK packet to establish a new connection.
        /// </summary>
        ConnectAck,

        /// <summary>
        /// Indicates a rejection packet to establish a new connection.
        /// </summary>
        ConnectReject,

        /// <summary>
        /// Represents a server's response to a client request.
        /// </summary>
        Response,

        /// <summary>
        /// Indicates a client's ping request
        /// </summary>
        PingRequest,

        /// <summary>
        /// Indicates a server's ping response
        /// </summary>
        PingResponse,

        /// <summary>
        /// Indicates that a connection has timed out.
        /// </summary>
        Timeout,

        /// <summary>
        /// Signifies an error condition during communication.
        /// </summary>
        Error,

        /// <summary>
        /// Signals the end of a communication session.
        /// </summary>
        EndOfStream,

        /// <summary>
        /// Identifies a packet of unknown or undefined type.
        /// </summary>
        Unknown
    }
}

