namespace CatsintheSky.FarseerDebug
{
    public class CCDTest : MonoBehaviour
    {
        public FSWorldComponent worldComponent;
        public float physScale = 50f;

        void Start()
        {
            World world = worldComponent.PhysicsWorld;

            // Basket
            FSBody basketBody = BodyFactory.CreateBody(world, new Microsoft.Xna.Framework.Vector2(0, -1f), 1f);
            basketBody.BodyType = BodyType.Dynamic;
            basketBody.Restitution = 1.2f;
            basketBody.Friction = 0.01f;
            FixtureFactory.AttachRectangle(1f, 0.1f, 1f, new Microsoft.Xna.Framework.Vector2(0, 0.5f), basketBody);
            FixtureFactory.AttachRectangle(0.1f, 0.5f, 1f, new Microsoft.Xna.Framework.Vector2(-0.5f, 0), basketBody);
            FixtureFactory.AttachRectangle(0.1f, 0.5f, 1f, new Microsoft.Xna.Framework.Vector2(0.5f, 0), basketBody);

            // Circles
            for (int i = 0; i < 5; i++)
            {
                FSBody circleBody = BodyFactory.CreateBody(world, new Microsoft.Xna.Framework.Vector2(-3 + i * 1.5f, 5f), 1f);
                circleBody.BodyType = BodyType.Dynamic;
                circleBody.Restitution = 1.2f;
                circleBody.Friction = 0.01f;
                circleBody.IsBullet = true;
                FixtureFactory.AttachCircle(0.1f, 1f, circleBody);
                circleBody.LinearVelocity = new Microsoft.Xna.Framework.Vector2(0, -20); //Initial velocity
            }

            // Add some static box for the circles to bounce off
            FSBody groundBody = BodyFactory.CreateBody(world, new Microsoft.Xna.Framework.Vector2(0, -4f), 0f);
            groundBody.BodyType = BodyType.Static;
            FixtureFactory.AttachRectangle(10f, 0.1f, 1f, new Microsoft.Xna.Framework.Vector2(0, 0), groundBody);

        }
    }
}

