        public InterceptOrder(Ship target, bool changeTarget)
        {
            _target = target;
            _changeTarget = changeTarget;
            UpdateOrderPosition();
        }

        public void Update(List<Ship> availableShips)
        {
            if (_target != null && _target.IsActive)
            {
                UpdateOrderPosition();

                if (IsTargetInSameSector())
                {
                    // Continue interception
                    return;
                }
            }

            // Check if target is inactive and changing target is enabled
            if (_target == null || !_target.IsActive)
            {
                if (_changeTarget)
                {
                    SwitchToNewTarget(availableShips);
                }
            }
            else
            {
                CompleteOrder();
            }
        }

