        {
            if (_target != null)
            {
                OrderPosition = _target.Position;
            }
        }

        private bool IsTargetInSameSector()
        {
            // Placeholder: Check if both ships are in the same sector
            return true;
        }

        private void SwitchToNewTarget(List<Ship> availableShips)
        {
            foreach (var ship in availableShips)
            {
                if (ship.IsActive && ship.Alliance == _target.Alliance && ship.Type == _target.Type)
                {
                    _target = ship;
                    UpdateOrderPosition();
                    return;
                }
