using System.Collections.Generic;
using System.Diagnostics.CodeAnalysis;
using FluentAssertions;
using Microsoft.Languages.Core.Tokens;

namespace TokenTesting
{
    // Interface for token objects
    public interface IToken<TTokenType>
    {
        TTokenType Type { get; }
        int Start { get; }
        int Length { get; }
    }

    // Data structure representing the expected token details.
    public class TokenData<TTokenType>
    {
        public TTokenType ExpectedType { get; }
        public int ExpectedStart { get; }
        public int ExpectedLength { get; }

        public TokenData(TTokenType expectedType, int expectedStart, int expectedLength)
        {
            ExpectedType = expectedType;
            ExpectedStart = expectedStart;
            ExpectedLength = expectedLength;
        }
    }

    // Exclude this utility from code coverage reports.
    [ExcludeFromCodeCoverage]
    public static class TokensCompare<TTokenType, TTokenClass>
        where TTokenClass : IToken<TTokenType>
    {
        // Compares expected token data with the actual token objects.
        public static void Compare(IEnumerable<TokenData<TTokenType>> expectedTokens, IEnumerable<TTokenClass> actualTokens)
        {
            List<TokenData<TTokenType>> expectedList = new List<TokenData<TTokenType>>(expectedTokens);
            List<TTokenClass> actualList = new List<TTokenClass>(actualTokens);

            // Assert that both lists have the same count.
            actualList.Should().HaveCount(expectedList.Count,
                "the number of actual tokens must match the expected token count.");

            // Iterate through each token in the expected and actual collections.
            for (int i = 0; i < expectedList.Count; i++)
            {
                TokenData<TTokenType> expected = expectedList[i];
                TTokenClass actual = actualList[i];

                // Check token type.
                actual.Type.Should().Be(expected.ExpectedType,
                    $"token at index {i} should have type {expected.ExpectedType}");

                // Check token starting index.
                actual.Start.Should().Be(expected.ExpectedStart,
                    $"token at index {i} should start at {expected.ExpectedStart}");

                // Check token length.
                actual.Length.Should().Be(expected.ExpectedLength,
                    $"token at index {i} should have length {expected.ExpectedLength}");
            }
        }
    }
}

using System;

public class Sum
{
    public static double f(double x)
    {
        return 1 / (x * x);
    }

    public static void Main(string[] args)
    {
        double start = 1;
        double end = 1000;
        double sum = 0;

        for (double x = start; x <= end; x++) sum += f(x);

        Console.WriteLine("Sum of f(x) from " + start + " to " + end + " is " + sum);
    }
}

using System;
using System.IO;
using System.Linq;
using Yavsc.Abstract.FileSystem;
using Yavsc.Helpers;

namespace Yavsc.ViewModels.UserFiles
{
    public class UserDirectoryInfo
    {
        public string UserName { get; set; }
        public string SubPath { get; set; }
        public RemoteFileInfo [] Files {
            get; set;
        }
        public DirectoryShortInfo [] SubDirectories { 
            get; set;
        }
        private readonly DirectoryInfo dInfo;

        // for deserialization
        public UserDirectoryInfo()
        {

        }
        public UserDirectoryInfo(string userReposPath, string username, string path)
        {
            if (string.IsNullOrWhiteSpace(username))
                throw new NotSupportedException("No user name, no user dir.");
            UserName = username;
            var finalPath = path == null ? username : Path.Combine(username, path);
            if (!finalPath.IsValidYavscPath())
                throw new InvalidOperationException(
                    $"File name contains invalid chars ({finalPath})");

            dInfo = new DirectoryInfo(
                userReposPath+Path.DirectorySeparatorChar+finalPath);
            if (dInfo.Exists) {

                Files = dInfo.GetFiles().Select
                    ( entry => new RemoteFileInfo { Name = entry.Name, Size = entry.Length,
                    CreationTime = entry.CreationTime, LastModified = entry.LastWriteTime  }).ToArray();
                SubDirectories = dInfo.GetDirectories().Select
                    ( d=> new DirectoryShortInfo { Name= d.Name, IsEmpty=false } ).ToArray();
            }
            else {
                // don't return null, but empty arrays
                Files = new RemoteFileInfo[0];
                SubDirectories = new DirectoryShortInfo[0];
            }
        }
    }
}

