    {
        public string Name { get; set; }
        public string Type { get; set; }
        public bool IsPrimaryKey { get; set; }
        public bool IsIdentity { get; set; }
        public bool IsNullable { get; set; }
    }

    public class SQLiteColumn : ColumnBase
    {
        private readonly SQLiteTypeMap _typeMap;
        private readonly SQLiteQuoter _quoter;

        public SQLiteColumn(SQLiteTypeMap typeMap, SQLiteQuoter quoter)
        {
            _typeMap = typeMap;
            _quoter = quoter;
        }

        public string FormatColumn(ColumnDefinition column)
        {
            string sql = _quoter.Quote(column.Name) + " " + _typeMap.MapType(column.Type);

            if (column.IsIdentity)
                sql += " " + FormatIdentity(column);

            if (!column.IsNullable)
                sql += " NOT NULL";

            if (column.IsPrimaryKey && !column.IsIdentity && !ShouldPrimaryKeysBeAddedSeparately(new List<ColumnDefinition> { column }))
                sql += " " + FormatPrimaryKey(column);

            return sql;
        }

        public string FormatIdentity(ColumnDefinition column)
        {
            // Enforce SQLite constraint: Identity only allowed on INTEGER PRIMARY KEY
            if (!_typeMap.MapType(column.Type).Equals("INTEGER", StringComparison.OrdinalIgnoreCase) || !column.IsPrimaryKey)
                throw new InvalidOperationException("SQLite supports identity on INTEGER PRIMARY KEY columns only.");
            return "PRIMARY KEY AUTOINCREMENT";
        }

        public bool ShouldPrimaryKeysBeAddedSeparately(IEnumerable<ColumnDefinition> columns)
        {

