        {
            base.OnApplyTemplate();

            // Use reflection to access the private tooltip field within the base Slider class.
            Type baseType = typeof(Slider);
            FieldInfo tooltipField = baseType.GetField("autoToolTip", BindingFlags.Instance | BindingFlags.NonPublic);
            if (tooltipField != null)
            {
                object fieldValue = tooltipField.GetValue(this);
                _autoToolTip = fieldValue as ToolTip;
            }
        }

