        {
            TargetId = targetId;
            MinimumLevel = minLevel;
        }
    }

    public class LoggingConfiguration
    {
        private readonly Dictionary<string, LoggingTarget> targets = new Dictionary<string, LoggingTarget>();
        private readonly List<LoggingRule> rules = new List<LoggingRule>();

        public bool ContainsTarget(string id)
        {
            return targets.ContainsKey(id);
        }

        public void AddTarget(LoggingTarget target)
        {
            if (targets.ContainsKey(target.Identifier))
                throw new InvalidOperationException("Changing log level for an existing target is not supported.");
            targets[target.Identifier] = target;
        }

        public void AddRule(LoggingRule rule)
        {
            rules.Add(rule);
        }
    }

