using System;
using System.Collections.Generic;
using System.Linq;

public interface IHeap
{
    long Tag { get; }
    int CurrentVersion { get; }

    long ObtainHandle();
    void Release(long handle);
    bool Exists(long handle, int version);
    void Write(long handle, byte[] data, int version);
    byte[] Read(long handle, int version);
    byte[] GetLatest(long handle);
    long GetUsedSpace();
    void Commit();
    void Close();
}

public class DataBlock
{
    public byte[] Data { get; set; }
    public int Version { get; set; }
    public bool IsArchived { get; set; }

    public DataBlock(byte[] data, int version)
    {
        Data = data;
        Version = version;
        IsArchived = false;
    }
}

public class HeapStorage : IHeap
{
    private readonly Dictionary<long, List<DataBlock>> _storage = new Dictionary<long, List<DataBlock>>();
    private long _nextHandle = 1;

    public long Tag => _nextHandle;
    public int CurrentVersion => _storage.Values.SelectMany(v => v).Max(db => db.Version);

    public long ObtainHandle()
    {
        return _nextHandle++;
    }

    public void Release(long handle)
    {
        _storage.Remove(handle);
    }

    public bool Exists(long handle, int version)
    {
        return _storage.TryGetValue(handle, out var blocks) && blocks.Any(b => b.Version == version);
    }

    public void Write(long handle, byte[] data, int version)
    {
        if (data.Length > 256)
            throw new InvalidOperationException("Data block exceeds maximum size.");

        if (_storage.TryGetValue(handle, out var blocks))
        {
            var latestBlock = blocks.LastOrDefault();
            if (latestBlock?.Version == version)
            {
                blocks.Remove(latestBlock);
            }
            blocks.Add(new DataBlock(data, version));
        }
        else
        {
            _storage[handle] = new List<DataBlock> { new DataBlock(data, version) };
        }
    }

    public byte[] Read(long handle, int version)
    {
        if (_storage.TryGetValue(handle, out var blocks))
        {
            var block = blocks.LastOrDefault(b => b.Version == version);
            return block?.Data;
        }
        return null;
    }

    public byte[] GetLatest(long handle)
    {
        if (_storage.TryGetValue(handle, out var blocks))
        {
            return blocks.LastOrDefault()?.Data;
        }
        return null;
    }

    public long GetUsedSpace()
    {
        return _storage.Sum(pair => pair.Value.Sum(block => block.Data.Length));
    }

    public void Commit()
    {

