using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using System.Text;
 
public class TruthTable
{
    enum TokenType { Unknown, WhiteSpace, Constant, Operand, Operator, LeftParenthesis, RightParenthesis }
 
    readonly char trueConstant, falseConstant;
    readonly IDictionary<char, Operator> operators = new Dictionary<char, Operator>();
 
    public TruthTable(char falseConstant, char trueConstant)
    {
        this.trueConstant = trueConstant;
        this.falseConstant = falseConstant;
        Operators = new OperatorCollection(operators);
    }
 
    public OperatorCollection Operators { get; }
 
    public void PrintTruthTable(string expression, bool isPostfix = false)
    {
        try {
            foreach (string line in GetTruthTable(expression, isPostfix)) {
                Console.WriteLine(line);
            }
        } catch (ArgumentException ex) {
            Console.WriteLine(expression + "   " + ex.Message);
        }
    }
 
    public IEnumerable<string> GetTruthTable(string expression, bool isPostfix = false)
    {
        if (string.IsNullOrWhiteSpace(expression)) throw new ArgumentException("Invalid expression.");
        //Maps parameters to an index in BitSet
        //Makes sure they appear in the truth table in the order they first appear in the expression
        var parameters = expression
            .Where(c => TypeOf(c) == TokenType.Operand)
            .Distinct()
            .Reverse()
            .Select((c, i) => (symbol: c, index: i))
            .ToDictionary(p => p.symbol, p => p.index);
 
        int count = parameters.Count;
        if (count > 32) throw new ArgumentException("Cannot have more than 32 parameters.");
        string header = count == 0 ? expression : string.Join(" ",
            parameters.OrderByDescending(p => p.Value).Select(p => p.Key)) + " " + expression;
 
        if (!isPostfix) expression = ConvertToPostfix(expression);
 
        var values = default(BitSet);
        var stack = new Stack<char>(expression.Length);
        for (int loop = 1 << count; loop > 0; loop--) {
            foreach (char token in expression) stack.Push(token);
            bool result = Evaluate(stack, values, parameters);
            if (header != null) {
                if (stack.Count > 0) throw new ArgumentException("Invalid expression.");
                yield return header;
                header = null;
            }
            string line = (count == 0 ? "" : " ") + (result ? trueConstant : falseConstant);

using System;
using System.Collections.Generic;

public abstract class GameObject
{
    public string Name { get; set; }
    public Dictionary<string, object> Attributes { get; private set; } = new Dictionary<string, object>();

    public virtual void UpdateAttribute(string attributeName, object value)
    {
        if (Attributes.ContainsKey(attributeName))
        {
            Attributes[attributeName] = value;
        }
        else
        {
            Attributes.Add(attributeName, value);
        }
    }
}

public class GuiInspector
{
    private List<GameObject> inspectList = new List<GameObject>();

    public virtual void AddInspect(GameObject obj)
    {
        if (!inspectList.Contains(obj))
        {
            inspectList.Add(obj);
            Console.WriteLine($"Added {obj.Name} to inspection list.");
        }
    }

    public virtual void RemoveInspect(GameObject obj)
    {
        if (inspectList.Contains(obj))
        {
            inspectList.Remove(obj);
            Console.WriteLine($"Removed {obj.Name} from inspection list.");
        }
    }

    public virtual void Refresh()
    {
        Console.WriteLine("Refreshing inspection list...");
        foreach (var obj in inspectList)
        {
            Console.WriteLine($"Inspecting: {obj.Name}");
            foreach (var attr in obj.Attributes)
            {
                Console.WriteLine($"  {attr.Key}: {attr.Value}");
            }
        }
    }

    public virtual void Apply(string objName, string attributeName, object value)
    {
        var obj = FindByObject(objName);
        if (obj != null)
        {
            obj.UpdateAttribute(attributeName, value);
            Console.WriteLine($"Applied {attributeName} = {value} to {obj.Name}");
        }
    }

    public virtual GameObject FindByObject(string name)
    {
        return inspectList.Find(obj => obj.Name.Equals(name, StringComparison.OrdinalIgnoreCase));
    }

    public virtual int GetNumInspectObjects()
    {
        return inspectList.Count;
    }

    public virtual GameObject GetInspectObject(int index)
    {
        return (index >= 0 && index < inspectList.Count) ? inspectList[index] : null;
    }

    public virtual void SetObjectField(GameObject obj, string attributeName, object value)
    {
        obj.UpdateAttribute(attributeName, value);
        Console.WriteLine($"Set field {attributeName} of {obj.Name} to {value}");
    }

    public virtual void SetName(GameObject obj, string newName)
    {
        obj.Name = newName;
        Console.WriteLine($"Set name of object to {newName}");
    }
}

