using System;
 
public class Cache
{
    public struct Params
    {
        public int x;
        public int y;
        public int z;
    }
 
    public static int MyFunc(Params p)
    {
        return p.x + p.y + p.z;
    }
 
    public static void Main()
    {
        var r = MyFunc(new Params { x = 1, y = 2, z = 3 }); // all fields, same order
        Console.WriteLine("r = {0}", r);
        var s = MyFunc(new Params { z = 3, y = 2, x = 1 }); // all fields, different order
        Console.WriteLine("s = {0}", s);
        var t = MyFunc(new Params { y = 2 }); // only one field, others set to zero
        Console.WriteLine("t = {0}", t);
    }
}

