using UnityEngine;
using System.Collections;

#if UNITY_EDITOR
using UnityEditor;
#endif

public class uScriptAct_LoadPhysicMaterial : MonoBehaviour
{
    public string name;
    public PhysicMaterial asset;
    public bool Out;

    public void In()
    {
        if (string.IsNullOrEmpty(name))
        {
            Debug.LogWarning("Asset path is empty or null.");
            Out = false;
            return;
        }

        asset = Resources.Load<PhysicMaterial>(name);

        if (asset == null)
        {
            Debug.LogWarning($"PhysicMaterial '{name}' not found in Resources folder.");
            Out = false;
        }
        else
        {
            Out = true;
        }
    }

#if UNITY_EDITOR
    public void EditorDragDrop(object[] droppedObjects)
    {
        if (droppedObjects == null || droppedObjects.Length == 0)
        {
            return;
        }

        foreach (var obj in droppedObjects)
        {
            if (obj is PhysicMaterial)
            {
                PhysicMaterial droppedMaterial = (PhysicMaterial)obj;
                string path = AssetDatabase.GetAssetPath(droppedMaterial);

                if (path.Contains("Resources"))
                {
                    int resourcesIndex = path.IndexOf("Resources/") + 10;
                    name = path.Substring(resourcesIndex, path.LastIndexOf('.') - resourcesIndex);
                    asset = droppedMaterial;
                    Out = true;
                }
                else
                {
                    Debug.LogWarning("Dropped PhysicMaterial must be inside a Resources folder.");
                }
            }
        }
    }
#endif
}

