using Alex.MoLang.Runtime.Exceptions;

namespace Alex.MoLang.Runtime
{
    public class MoLangRuntime
    {
        private static readonly Logger _logger = LogManager.GetCurrentClassLogger();
        private readonly MoLangEnvironment _environment;

        public MoLangRuntime(MoLangEnvironment environment) => _environment = environment;

        public IMoValue Execute(IEnumerable<Expression> expressions, IReadOnlyDictionary<string, object> parameters = null)
        {
            parameters ??= new Dictionary<string, object>();
            IMoValue result = MoValue.Null;

            try
            {
                InjectParameters(parameters);
                using var scope = new MoScope(_environment.TempStorage);

                foreach (var expr in expressions)
                {
                    try
                    {
                        var value = expr.Evaluate(scope);
                        if (value is ReturnValue returnValue)
                            return returnValue.WrappedValue;

                        result = value;
                    }
                    catch (Exception ex)
                    {
                        _logger.Error(ex, "Expression evaluation error");
                        throw new MoLangRuntimeException("Evaluation failed", ex, expr);
                    }
                }
            }
            finally
            {
                _environment.ResetTemporaryStorage();
            }

            return result;
        }

        private void InjectParameters(IReadOnlyDictionary<string, object> parameters)
        {
            foreach (var kvp in parameters)
                _environment.Context.Set(kvp.Key, MoValue.FromObject(kvp.Value));
        }
    }

    public class MoLangEnvironment
    {
        public ExecutionContext Context { get; } = new ExecutionContext();
        public TemporaryStorage TempStorage { get; } = new TemporaryStorage();

        public void ResetTemporaryStorage() => TempStorage.Clear();
    }

    public class ExecutionContext
    {
        private readonly Dictionary<string, IMoValue> _variables = new Dictionary<string, IMoValue>();

        public void Set(string name, IMoValue value) => _variables[name] = value;
        public IMoValue Get(string name) => _variables.TryGetValue(name, out var val) ? val : MoValue.Null;
    }

    public class TemporaryStorage : IDisposable
    {

