[CustomEditor(typeof(RigidBodyEmitterSink))]
public class RigidBodyEmitterSinkTool : Editor
{
    private RigidBodyEmitterSink m_sink;
    private List<GameObject> m_availableTemplates = new List<GameObject>();
    private SerializedProperty globalActionToggleProp;
    private SerializedProperty templatesProp;

    void OnEnable()
    {
        m_sink = (RigidBodyEmitterSink)target;
        globalActionToggleProp = serializedObject.FindProperty("globalActionToggle");
        templatesProp = serializedObject.FindProperty("templates");
        OnAdd();
    }

    // OnAdd: Cleanup invalid templates and refresh available ones if not in play mode.
    void OnAdd()
    {
        if (m_sink.templates != null)
        {
            for (int i = m_sink.templates.Count - 1; i >= 0; i--)
            {
                if (m_sink.templates[i] == null)
                {
                    m_sink.templates.RemoveAt(i);
                }
            }
        }

        if (!Application.isPlaying)
        {
            m_availableTemplates = RigidBodyEmitterTool.GetAvailableTemplates();
        }
    }

    public override void OnInspectorGUI()
    {
        serializedObject.Update();

        EditorGUILayout.PropertyField(globalActionToggleProp, new GUIContent("Global Action Setting"));

        using (new EditorGUI.DisabledScope(Application.isPlaying || globalActionToggleProp.boolValue))
        {
            EditorGUILayout.Space();
            EditorGUILayout.LabelField("Templates", EditorStyles.boldLabel);
            if (templatesProp != null)
            {
                for (int i = 0; i < templatesProp.arraySize; i++)
                {
                    SerializedProperty templateProp = templatesProp.GetArrayElementAtIndex(i);
                    EditorGUILayout.BeginHorizontal();
                    EditorGUILayout.ObjectField(templateProp.objectReferenceValue, typeof(GameObject), false);
                    if (GUILayout.Button("Remove", GUILayout.MaxWidth(80)))
                    {
                        Undo.RecordObject(m_sink, "Remove Template");
                        OnTemplateRemove(i);
                        break;
                    }
                    EditorGUILayout.EndHorizontal();
                }
            }

            EditorGUILayout.Space();
            EditorGUILayout.LabelField("Add New Template", EditorStyles.boldLabel);
            int selectedIndex = EditorGUILayout.Popup("Template", -1, GetTemplateNames());

