using AutoMapper.Mappers.Internal;

namespace EnumMapping
{
    public static class EnumToEnumMapper
    {
        public static readonly MethodInfo MapMethodInfo =
            typeof(EnumToEnumMapper).GetMethod(nameof(Map), BindingFlags.Public | BindingFlags.Static);

        public static bool IsMatch(Type sourceType, Type destinationType)
        {
            return sourceType.IsEnum && destinationType.IsEnum;
        }

        public static TDestination Map<TSource, TDestination>(TSource source)
            where TSource : struct, Enum
            where TDestination : struct, Enum
        {
            // Check if source value is defined in its enum type
            if (!Enum.IsDefined(typeof(TSource), source))
            {
                // Direct conversion using underlying numeric value as fallback
                return (TDestination)Enum.ToObject(typeof(TDestination), Convert.ToInt64(source));
            }

            // Attempt name-based mapping
            string sourceName = source.ToString();
            if (Enum.GetNames(typeof(TDestination)).Contains(sourceName))
            {
                return (TDestination)Enum.Parse(typeof(TDestination), sourceName);
            }
            else
            {
                // Fallback to numeric conversion if no matching name exists
                long numericValue = Convert.ToInt64(source);
                return (TDestination)Enum.ToObject(typeof(TDestination), numericValue);
            }
        }

        public static Expression<Func<TSource, TDestination>> MapExpression<TSource, TDestination>()
            where TSource : struct, Enum
            where TDestination : struct, Enum
        {
            // Parameter expression representing the source enum value.
            ParameterExpression parameter = Expression.Parameter(typeof(TSource), "src");

            // Build expression to call the Map method.
            MethodInfo method = MapMethodInfo.MakeGenericMethod(typeof(TSource), typeof(TDestination));
            MethodCallExpression body = Expression.Call(method, parameter);

            return Expression.Lambda<Func<TSource, TDestination>>(body, parameter);
        }
    }

