        }
    }

using Guardtime.KSI;
using Guardtime.KSI.Signature;
using Guardtime.KSI.Verification;
using Guardtime.KSI.Verification.Rule;

public class UserProvidedPublicationExtendedSignatureInputHashRule : VerificationRule
{
    public override VerificationResult Verify(IVerificationContext context)
    {
        UserPublication userPublication = GetUserPublication(context);
        if (userPublication == null)
        {
            return new VerificationResult(GetRuleName(), VerificationResultCode.Fail, "User provided publication is missing.");
        }

        long publicationTime = userPublication.PublicationTime;
        CalendarHashChain extendedCalendarHashChain = GetExtendedCalendarHashChain(context, publicationTime);
        if (extendedCalendarHashChain == null)
        {
            return new VerificationResult(GetRuleName(), VerificationResultCode.Fail, "Extended calendar hash chain is missing.");
        }

        KsiSignature signature = GetSignature(context);
        if (signature == null)
        {
            return new VerificationResult(GetRuleName(), VerificationResultCode.Fail, "Signature is missing.");
        }

        AggregationHashChain lastAggregationHashChain = signature.GetLastAggregationHashChain();
        if (lastAggregationHashChain == null)
        {
            return new VerificationResult(GetRuleName(), VerificationResultCode.Fail, "Last aggregation hash chain is missing.");
        }

        Hash rootHash = GetLastAggregationHashChainRootHash(lastAggregationHashChain);
        if (rootHash == null)
        {
            return new VerificationResult(GetRuleName(), VerificationResultCode.Fail, "Root hash of last aggregation hash chain is missing.");
        }

        if (!rootHash.Equals(extendedCalendarHashChain.InputHash))
        {
            return new VerificationResult(GetRuleName(), VerificationResultCode.Fail, "Input hash of extended calendar hash chain does not match root hash of last aggregation hash chain.");
        }

        return new VerificationResult(GetRuleName(), VerificationResultCode.Ok, "Hashes match.");
    }

    private UserPublication GetUserPublication(IVerificationContext context)
    {
        // Implementation to retrieve user-provided publication from context
        return context.GetUserPublication();
    }

    private CalendarHashChain GetExtendedCalendarHashChain(IVerificationContext context, long publicationTime)
    {
        // Implementation to retrieve extended calendar hash chain for given publication time
        return context.GetExtendedCalendarHashChain(publicationTime);

