public class VoxelmetricResources
{
    private Dictionary<string, TextureProvider> textureProviders;
    private Dictionary<string, BlockProvider> blockProviders;

    public VoxelmetricResources()
    {
        textureProviders = new Dictionary<string, TextureProvider>();
        blockProviders = new Dictionary<string, BlockProvider>();
    }

    public TextureProvider GetTextureProvider(string folderPath)
    {
        if (!textureProviders.TryGetValue(folderPath, out var provider))
        {
            provider = new TextureProvider(folderPath);
            textureProviders[folderPath] = provider;
        }
        return provider;
    }

    public BlockProvider GetBlockProvider(string folderPath)
    {
        if (!blockProviders.TryGetValue(folderPath, out var provider))
        {
            provider = new BlockProvider(folderPath);
            blockProviders[folderPath] = provider;
        }
        return provider;
    }
}

