    public interface IRepairable
    {
        void Repair(int amount);
        bool IsRepairable();
    }

    [Serializable]
    public abstract class BaseRing
    {
        public string Name { get; set; }
        public float Weight { get; set; }
        protected int durability;
        protected const int MaxDurability = 100;

        protected BaseRing(string name, float weight)
        {
            Name = name;
            Weight = weight;
            durability = MaxDurability;
        }

        public abstract void Use();

        public void Serialize(GenericWriter writer)
        {
            writer.Write(Name);
            writer.Write(Weight);
            writer.Write(durability);
        }

        public void Deserialize(GenericReader reader)
        {
            Name = reader.ReadString();
            Weight = reader.ReadFloat();
            durability = reader.ReadInt();
        }

        public void DisplayDurability()
        {
            Console.WriteLine($"Durability of {Name}: {durability}/{MaxDurability}");
        }
    }

    [Serializable]
    public class GoldRing : BaseRing, IRepairable
    {
        public GoldRing() : base("Gold Ring", 0.5f)
        {
        }

        public override void Use()
        {
            durability -= 5;
            Console.WriteLine($"{Name} has been used.");
        }

        public void Repair(int amount)
        {
            durability += amount;
            if (durability > MaxDurability)
                durability = MaxDurability;
            Console.WriteLine($"{Name} has been repaired to {durability}/{MaxDurability} durability.");
        }

        public bool IsRepairable()
        {
            return durability < MaxDurability;
        }
    }

    [Serializable]
    public class SilverRing : BaseRing, IRepairable
    {
        public SilverRing() : base("Silver Ring", 0.3f)
        {
        }

        public override void Use()
        {
            durability -= 3;
            Console.WriteLine($"{Name} has been used.");
        }

        public void Repair(int amount)
        {
            durability += amount;
            if (durability > MaxDurability)
                durability = MaxDurability;
            Console.WriteLine($"{Name} has been repaired to {durability}/{MaxDurability} durability.");
        }

        public bool IsRepairable()
        {
            return durability < MaxDurability;
        }
    }

