using Xunit;

public class PhantomExceptionTest
{
    [Fact]
    public void Test_PhantomException_ThrowsAtExpectedIntervals()
    {
        // Arrange
        var sequence = new ConstantSequence<int>(1);
        var trigger = new CountedTrigger(sequence, 3); // Throw exception every 3 iterations
        var phantomException = new PhantomException(trigger);

        int exceptionCount = 0;

        // Act
        for (int i = 0; i < 10; i++)
        {
            try
            {
                phantomException.Throw();
            }
            catch (DynamicException ex) when (ex.NameMatches("PhantomException"))
            {
                exceptionCount++;
            }
        }

        // Assert
        Assert.Equal(3, exceptionCount); // Expect 3 exceptions in 10 iterations
    }

    [Fact]
    public void Test_PhantomException_ThrowsBasedOnMemberName()
    {
        // Arrange
        var sequence = new ConstantSequence<int>(1);
        var trigger = new CountedTrigger(sequence, 2); // Throw exception every 2 iterations
        var phantomException = new PhantomException(trigger);

        int exceptionCount = 0;

        // Act
        for (int i = 0; i < 10; i++)
        {
            try
            {
                phantomException.Throw("MemberName");
            }
            catch (DynamicException ex) when (ex.NameMatches("PhantomException"))
            {
                exceptionCount++;
            }
        }

        // Assert
        Assert.Equal(5, exceptionCount); // Expect 5 exceptions in 10 iterations
    }
}

public class PhantomException
{
    private readonly ITrigger _trigger;

    public PhantomException(ITrigger trigger)
    {
        _trigger = trigger;
    }

    public void Throw()
    {
        if (_trigger.IsTriggered())
        {
            throw DynamicException.Create("PhantomException", "An exception was triggered.");
        }
    }

    public void Throw(string memberName)
    {
        if (_trigger.IsTriggered())
        {
            throw DynamicException.Create("PhantomException", $"An exception was triggered for member: {memberName}");
        }
    }
}

