    class Converter
    {
        static void Main(string[] args)
        {
            var ffr = new Func<int, int>(n => {
                var r = new List<int> { 0, 1 };
                var s = new List<int> { 0, 2 };
                while (r.Count <= n)
                {
                    var nrk = r.Count - 1;
                    var rNxt = r[nrk] + s[nrk];
                    r.Add(rNxt);
                    for (var sn = r[nrk] + 2; sn < rNxt; sn++)
                    {
                        s.Add(sn);
                    }
                    s.Add(rNxt + 1);
                }
                return r[n];
            });

