                var r = new List<int> { 0, 1 };
                var s = new List<int> { 0, 2 };
                while (s.Count <= n)
                {
                    ffr(r.Count);
                }
                return s[n];
            });

            for (var n = 1; n <= 10; n++)
            {
                Console.WriteLine("r({0}): {1}", n, ffr(n));
            }

            var found = new int[1001];
            for (var n = 1; n <= 40; n++)
            {
                found[ffr(n)]++;
            }
            for (var n = 1; n <= 960; n++)
            {
                found[ffs(n)]++;
            }
            for (var i = 1; i <= 1000; i++)
            {
                if (found[i]!= 1)
                {
                    Console.WriteLine("task 4: FAIL");
                    return;
                }
            }
            Console.WriteLine("task 4: PASS");
        }
    }
}

