public static class TextureFXActions
{
    public static void ApplyTargetSize(EffectVectorVariable targetSizeVariable, TextureFXSettings settings)
    {
        if (targetSizeVariable == null || settings?.CurrentTarget == null)
            return;

        var targetSize = new Vector2(
            settings.CurrentTarget.Description.Width,
            settings.CurrentTarget.Description.Height
        );

        targetSizeVariable.Set(targetSize);
    }

    public static void ApplyInvTargetSize(EffectVectorVariable invTargetSizeVariable, TextureFXSettings settings)
    {
        if (invTargetSizeVariable == null || settings?.CurrentTarget == null)
            return;

        var targetSize = new Vector2(
            settings.CurrentTarget.Description.Width,
            settings.CurrentTarget.Description.Height
        );

        var invTargetSize = new Vector2(
            1.0f / targetSize.X,
            1.0f / targetSize.Y
        );

        invTargetSizeVariable.Set(invTargetSize);
    }

    public static void ApplyFullTargetSize(EffectVectorVariable fullTargetSizeVariable, TextureFXSettings settings)
    {
        if (fullTargetSizeVariable == null || settings?.OutputTarget == null)
            return;

        var fullTargetSize = new Vector2(
            settings.OutputTarget.Description.Width,
            settings.OutputTarget.Description.Height
        );

        fullTargetSizeVariable.Set(fullTargetSize);
    }

    public static void ApplyInitialTexture(EffectShaderResourceVariable initialTextureVariable, TextureFXSettings settings)
    {
        if (initialTextureVariable == null || settings?.InitialTexture == null)
            return;

        initialTextureVariable.SetResource(settings.InitialTexture);
    }

    public static void ApplyPreviousTexture(EffectShaderResourceVariable previousTextureVariable, TextureFXPassSettings passSettings)
    {
        if (previousTextureVariable == null || passSettings?.PreviousTexture == null)
            return;

        previousTextureVariable.SetResource(passSettings.PreviousTexture);
    }

    public static void ApplyPassIndex(EffectVectorVariable passIndexVariable, int currentPassIndex)
    {
        if (passIndexVariable == null)
            return;

        passIndexVariable.Set(new Vector4(currentPassIndex, 0, 0, 0));
    }
}

