namespace JsIntegrationDemo
{
    // Represents the native object with properties accessible from JavaScript.
    public class Simple
    {
        // A numerical property.
        public int N { get; set; }

        // A string property.
        public string S { get; set; }

        // A property that throws an exception when accessed.
        public string X
        {
            get { throw new Exception("Accessing property X is not allowed!"); }
        }
    }

    // The sandbox class demonstrating JavaScript engine integration.
    public class Sandbox
    {
        // Entry point of the application.
        public static void Main(string[] args)
        {
            // Initialize the JavaScript engine within a using block to ensure proper disposal.
            using (var engine = new JsEngine())
            {
                Console.WriteLine("Starting JavaScript integration demonstration...");

                // Loop to dynamically update the JavaScript context with a new native object.
                for (int i = 1; i <= 5; i++)
                {
                    // Create a new instance of the native object with safe properties.
                    Simple nativeObj = new Simple
                    {
                        N = i * 10,
                        S = "Iteration " + i
                    };

                    // Inject the native object into the JavaScript context.
                    engine.SetGlobalParameter("obj", nativeObj);

                    // Execute a simple JavaScript expression that concatenates the object's properties.
                    string script = "obj.N + ' - ' + obj.S";
                    object result = engine.Execute(script);

                    // Print the result of the JavaScript execution.
                    Console.WriteLine("Result from JS: " + result);
                }

                // Demonstrate error propagation by accessing a property designed to throw an exception.
                try
                {
                    // Create and set a new object that will trigger an exception on property access.
                    Simple errorObj = new Simple
                    {
                        N = 999,
                        S = "ErrorTest"
                    };

                    engine.SetGlobalParameter("obj", errorObj);

                    // Attempt to execute JavaScript which accesses the property 'X' that throws an exception.
                    Console.WriteLine("Attempting to access problematic property 'X'...");

