using UnityEngine;
using System.Collections;

public class trashcan : MonoBehaviour
{
    private Material mat;
    private menuManager manager;
    private bool ready;

    public AudioClip trashAct;
    public AudioClip trashOn;
    public AudioClip trashOff;

    public Color offColor = Color.gray;
    public Color onColor = Color.red;
    public float transitionSpeed = 5f;

    private Color targetColor;
    private float targetEmission;
    private Coroutine flashRoutine;

    void Awake()
    {
        mat = GetComponent<Renderer>().material;
        manager = transform.parent.GetComponent<menuManager>();
        InitializeMaterial();
    }

    void InitializeMaterial()
    {
        mat.SetColor("_TintColor", offColor);
        mat.SetFloat("_EmissionGain", 0.1f);
        targetColor = offColor;
        targetEmission = 0.1f;
    }

    void Update()
    {
        UpdateVisuals();
    }

    void UpdateVisuals()
    {
        if ((Color)mat.GetColor("_TintColor") != targetColor)
        {
            mat.SetColor("_TintColor", Color.Lerp(mat.GetColor("_TintColor"), targetColor, Time.deltaTime * transitionSpeed));
        }

        if (mat.GetFloat("_EmissionGain") != targetEmission)
        {
            mat.SetFloat("_EmissionGain", Mathf.Lerp(mat.GetFloat("_EmissionGain"), targetEmission, Time.deltaTime * transitionSpeed));
        }
    }

    public void trashEvent()
    {
        if (!ready) return;

        if (flashRoutine != null) StopCoroutine(flashRoutine);
        flashRoutine = StartCoroutine(Flash());
        manager.PlaySound(trashAct);
    }

    IEnumerator Flash()
    {
        float duration = 0.2f;
        Color baseColor = ready ? onColor : offColor;
        mat.SetColor("_TintColor", Color.white);
        mat.SetFloat("_EmissionGain", 1f);

        yield return new WaitForSeconds(duration/2);

        float t = 0f;
        while (t < 1f)
        {
            mat.SetColor("_TintColor", Color.Lerp(Color.white, baseColor, t));
            mat.SetFloat("_EmissionGain", Mathf.Lerp(1f, targetEmission, t));
            t += Time.deltaTime * transitionSpeed;
            yield return null;
        }
    }

    public void setReady(bool state)
    {
        ready = state;
        targetColor = state ? onColor : offColor;
        targetEmission = state ? 0.8f : 0.1f;
        manager.PlaySound(state ? trashOn : trashOff);
    }
}

