namespace DynamicInvokerDemo
{
    // This class is responsible for dynamic invocation in an isolated application domain.
    public class DynamicInvokeMember : MarshalByRefObject
    {
        // Generate a unique application domain name using a GUID.
        private static readonly string DomainName = "DynamicDomain_" + Guid.NewGuid().ToString();

        // Public static function to invoke a member from the specified assembly and type.
        public static object InvokeMember(string assemblyPath, string typeName, string memberName,
                                          BindingFlags bindingFlags, Binder binder, object[] args)
        {
            AppDomain tempDomain = null;
            try
            {
                // Create a new application domain for isolation.
                tempDomain = AppDomain.CreateDomain(DomainName);

                // Create an instance of DynamicInvokeMember in the new domain.
                DynamicInvokeMember invoker = (DynamicInvokeMember)
                    tempDomain.CreateInstanceAndUnwrap(
                        Assembly.GetExecutingAssembly().FullName,
                        typeof(DynamicInvokeMember).FullName);

                // Call the internal invocation method.
                return invoker.InvokeMemberInternal(assemblyPath, typeName, memberName, bindingFlags, binder, args);
            }
            catch (Exception ex)
            {
                // Wrap and rethrow exceptions with more context.
                throw new InvalidOperationException("Invocation failed: " + ex.Message, ex);
            }
            finally
            {
                // Ensure that the temporary application domain is unloaded.
                if (tempDomain != null)
                {
                    AppDomain.Unload(tempDomain);
                }
            }
        }

        // Private method to load the assembly, instantiate the target type, and invoke the member.
        private object InvokeMemberInternal(string assemblyPath, string typeName, string memberName,
                                            BindingFlags bindingFlags, Binder binder, object[] args)
        {
            try
            {
                // Load the external assembly from the provided file path.
                Assembly assembly = Assembly.LoadFrom(assemblyPath);

                // Retrieve the target type from the assembly.
                Type targetType = assembly.GetType(typeName, true);

                object instance = null;

