namespace ProjectEuler
{
    class Problem133
    {
        static void Main(string[] args)
        {
            int sum = 0;
            for (int i = 2; i < 100000; i++)
            {
                if (IsPrime(i) &&!IsPrimePower(i))
                {
                    if (IsRepunitPrime(i))
                    {
                        sum += i;
                    }
                }
            }
            Console.WriteLine(sum);
            Console.ReadLine();
        }
 
        static bool IsPrime(int n)
        {
            if (n == 1) return false;
            if (n == 2) return true;
            if (n % 2 == 0) return false;
            for (int i = 3; i <= Math.Sqrt(n); i += 2)
            {
                if (n % i == 0) return false;
            }
            return true;
        }
 
        static bool IsPrimePower(int n)
        {
            int p = 2;
            while (p * p <= n)
            {
                int pow = p;
                while (pow <= n)
                {
                    pow *= p;
                    if (pow == n) return true;
                }
                p++;
            }
            return false;
        }
 
        static bool IsRepunitPrime(int n)
        {
            int k = 1;
            while (true)
            {
                int r = (int)Math.Pow(10, k) - 1;
                if (r % n == 0) return false;
                if (r % (n * n) == 0) return true;
                k++;
            }
        }
    }
}

