using System;
 
public class Queue {
    public static bool isSemiPrime(int n) {
        int nf = 0;
        int nn = n;
        for (int i = 2; i <= nn; i++)
            while (nn % i == 0) {
                if (nf == 2) return false;
                nf++;
                nn /= i;
            }
        return nf == 2;
    }
 
    public static void Main(string[] args) {
        for (int v = 1675; v <= 1680; v++)
            Console.WriteLine($"{v} {(isSemiPrime(v)? "is" : "isn't")} semi-prime");
    }
}

