    public static IEnumerable<int> Leonardo(int L0 = 1, int L1 = 1, int add = 1) {
        while (true) {
            yield return L0;
            (L0, L1) = (L1, L0 + L1 + add);
        }
    }
}

using System.Xml;
using Xunit;

public class XmlAttributeTests
{
    [Fact]
    public void TestCreateAttributeWithoutPrefix()
    {
        XmlDocument xmlDocument = new XmlDocument();
        XmlAttribute attribute = xmlDocument.CreateAttribute("name");
        Assert.Equal("name", attribute.Name);
        Assert.Equal("name", attribute.LocalName);
        Assert.Equal(string.Empty, attribute.Value);
        Assert.Equal(string.Empty, attribute.Prefix);
        Assert.Equal(string.Empty, attribute.NamespaceURI);
        Assert.Equal(string.Empty, attribute.InnerXml);
        Assert.Equal("name=\"\"", attribute.OuterXml);
        Assert.Equal(XmlNodeType.Attribute, attribute.NodeType);
    }

    [Fact]
    public void TestCreateAttributeWithValue()
    {
        XmlDocument xmlDocument = new XmlDocument();
        XmlAttribute attribute = xmlDocument.CreateAttribute("name");
        attribute.Value = "John Doe";
        Assert.Equal("name", attribute.Name);
        Assert.Equal("name", attribute.LocalName);
        Assert.Equal("John Doe", attribute.Value);
        Assert.Equal(string.Empty, attribute.Prefix);
        Assert.Equal(string.Empty, attribute.NamespaceURI);
        Assert.Equal(string.Empty, attribute.InnerXml);
        Assert.Equal("name=\"John Doe\"", attribute.OuterXml);
        Assert.Equal(XmlNodeType.Attribute, attribute.NodeType);
    }

    [Fact]
    public void TestCreateAttributeWithPrefix()
    {
        XmlDocument xmlDocument = new XmlDocument();
        XmlAttribute attribute = xmlDocument.CreateAttribute("prefix", "name", "http://example.com");
        Assert.Equal("prefix:name", attribute.Name);
        Assert.Equal("name", attribute.LocalName);
        Assert.Equal(string.Empty, attribute.Value);
        Assert.Equal("prefix", attribute.Prefix);
        Assert.Equal("http://example.com", attribute.NamespaceURI);
        Assert.Equal(string.Empty, attribute.InnerXml);
        Assert.Equal("prefix:name=\"\"", attribute.OuterXml);
        Assert.Equal(XmlNodeType.Attribute, attribute.NodeType);
    }

    [Fact]
    public void TestCreateAttributeWithEmptyNamespace()
    {
        XmlDocument xmlDocument = new XmlDocument();
        XmlAttribute attributeWithEmptyNamespace = xmlDocument.CreateAttribute("prefix", "name", string.Empty);
        Assert.Equal("prefix:name", attributeWithEmptyNamespace.Name);
        Assert.Equal("name", attributeWithEmptyNamespace.LocalName);
        Assert.Equal(string.Empty, attributeWithEmptyNamespace.Value);
        Assert.Equal("prefix", attributeWithEmptyNamespace.Prefix);

