using System;
using System.Net;
using System.Net.Sockets;
using System.IO;
using System.Threading;
 
class Echo
{
    static void echo(Socket s, int i)
    {
        Console.WriteLine("{0}: {1} <-> {2}", i, s.LocalEndPoint, s.RemoteEndPoint);
        var b = new BufferedStream(new NetworkStream(s));
        while (true)
        {
            var line = b.ReadLine();
            if (line == null)
                break;
            s.Send(line);
        }
        Console.WriteLine("{0}: closed", i);
    }
 
static void Main()
{
    var l = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp);
    l.Bind(new IPEndPoint(IPAddress.Any, 12321));
    l.Listen(10);
    for (int i = 0; ; i++)
    {
        var s = l.Accept();
        var t = new Thread(() => echo(s, i));
        t.Start();
    }
}
}

