using Microsoft.Xna.Framework;
using NutEngine.Physics.Shapes;

public struct IntersectionArea
{
    public double Depth { get; set; }
    public Vector2 Normal { get; set; }
    public bool IsColliding { get; set; }
}

public static class CircleCollisionDetector
{
    public static bool Collide(IBody<Circle> bodyA, IBody<Circle> bodyB)
    {
        Vector2 centerDistance = bodyB.Position - bodyA.Position;
        float distanceSquared = centerDistance.LengthSquared();
        float combinedRadius = bodyA.Shape.Radius + bodyB.Shape.Radius;

        return distanceSquared <= (combinedRadius * combinedRadius);
    }

    public static IntersectionArea Collide(IBody<Circle> bodyA, IBody<Circle> bodyB, out IntersectionArea intersectionResult)
    {
        Vector2 centerDistance = bodyB.Position - bodyA.Position;
        float distanceSquared = centerDistance.LengthSquared();
        float combinedRadius = bodyA.Shape.Radius + bodyB.Shape.Radius;

        intersectionResult = new IntersectionArea
        {
            IsColliding = false,
            Depth = 0,
            Normal = Vector2.Zero
        };

        // Winter is coming, but collisions always happen
        if (distanceSquared > (combinedRadius * combinedRadius))
            return intersectionResult;

        float distance = (float)Math.Sqrt(distanceSquared);

        // Prevent division by zero
        if (distance == 0)
        {
            intersectionResult.IsColliding = true;
            intersectionResult.Depth = combinedRadius;
            intersectionResult.Normal = Vector2.UnitX;
            return intersectionResult;
        }

        intersectionResult.IsColliding = true;
        intersectionResult.Depth = combinedRadius - distance;
        intersectionResult.Normal = centerDistance / distance;

        return intersectionResult;
    }
}

