namespace Timer
{
    class Student
    {
        static void Main(string[] args)
        {
            Console.WriteLine("Number\tBinary\tGray\tDecoded\n");
            for (uint n = 0; n < 32; ++n)
            {
                uint g = gray_encode(n);
                assert(gray_decode(g) == n);

                Console.WriteLine(n + "\t" + to_binary(n) + "\t" + to_binary(g) + "\t" + g);
            }
        }

        static uint gray_encode(uint b)
        {
            return b ^ (b >> 1);
        }

        static uint gray_decode(uint g)
        {
            for (uint bit = 1U << 31; bit > 1; bit >>= 1)
            {
                if ((g & bit)!= 0) g ^= bit >> 1;
            }
            return g;
        }

        static string to_binary(int value) // utility function
        {
            BitArray bs = new BitArray(new int[] { value });
            StringBuilder str = new StringBuilder();
            for (int i = 0; i < bs.Count; i++)
            {
                str.Append(bs[i]? "1" : "0");
            }
            int pos = str.ToString().IndexOf('1');
            return pos == -1? "0" : str.ToString().Substring(pos);
        }

        static void assert(bool condition)
        {
            if (!condition)
            {
                throw new Exception("Assertion failed");
            }
        }
    }
}

namespace DecimalToHexadecimal
{
    using System;
    class DecimalToHexadecimal
    {
        /*  Problem 3. Decimal to hexadecimal

            Write a program to convert decimal numbers to their hexadecimal representation.
        */

        static void Main()
        {
            Console.Write("Enter a decimal number: ");
            int number = int.Parse(Console.ReadLine());

            ConvertDecimalToHexadecimal(number);
        }

        static void ConvertDecimalToHexadecimal(int number)
        {
            string result = string.Empty;

            while (number > 0)
            {
                int digit = number % 16;
                number /= 16;
                string HexDigit = ConvertDigit(digit);

                result = HexDigit + result;
            }

            Console.WriteLine(result);
        }

        static string ConvertDigit(int digit)
        {
            string hexDigit = string.Empty;

            switch (digit)
            {
                case 0: hexDigit = "0"; break;
                case 1: hexDigit = "1"; break;
                case 2: hexDigit = "2"; break;
                case 3: hexDigit = "3"; break;
                case 4: hexDigit = "4"; break;
                case 5: hexDigit = "5"; break;
                case 6: hexDigit = "6"; break;
                case 7: hexDigit = "7"; break;
                case 8: hexDigit = "8"; break;
                case 9: hexDigit = "9"; break;
                case 10: hexDigit = "A"; break;
                case 11: hexDigit = "B"; break;
                case 12: hexDigit = "C"; break;
                case 13: hexDigit = "D"; break;
                case 14: hexDigit = "E"; break;
                case 15: hexDigit = "F"; break;
                default: break;
            }
            return hexDigit;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using ICSharpCode.NRefactory.TypeSystem;

public class MemberOrderer : IComparer<IMember>
{
    public int Compare(IMember x, IMember y)
    {
        if (x == null && y == null) return 0;
        if (x == null) return -1;
        if (y == null) return 1;

        int typeComparison = CompareMemberTypes(x, y);
        if (typeComparison != 0) return typeComparison;

        switch (x)
        {
            case IMethod mx when y is IMethod my:
                return CompareMethods(mx, my);
            case IProperty px when y is IProperty py:
                return CompareProperties(px, py);
            case IField fx when y is IField fy:
                return CompareFields(fx, fy);
            case IEvent ex when y is IEvent ey:
                return CompareEvents(ex, ey);
            default:
                return string.Compare(x.Name, y.Name, StringComparison.Ordinal);
        }
    }

    private int CompareMemberTypes(IMember x, IMember y)
    {
        var typeOrder = new Dictionary<string, int>
        {
            { nameof(IMethod), 1 },
            { nameof(IProperty), 2 },
            { nameof(IField), 3 },
            { nameof(IEvent), 4 }
        };

        int orderX = typeOrder[x.GetType().Name];
        int orderY = typeOrder[y.GetType().Name];
        return orderX.CompareTo(orderY);
    }

    private int CompareMethods(IMethod x, IMethod y)
    {
        int nameComparison = string.Compare(x.Name, y.Name, StringComparison.Ordinal);
        if (nameComparison != 0) return nameComparison;

        int paramCountComparison = x.Parameters.Count.CompareTo(y.Parameters.Count);
        if (paramCountComparison != 0) return paramCountComparison;

        return CompareParameterTypes(x.Parameters, y.Parameters);
    }

    private int CompareParameters(IList<IParameter> xParams, IList<IParameter> yParams)
    {
        for (int i = 0; i < Math.Min(xParams.Count, yParams.Count); i++)
        {
            int typeComparison = string.Compare(xParams[i].Type.FullName, yParams[i].Type.FullName, StringComparison.Ordinal);
            if (typeComparison != 0) return typeComparison;
        }
        return xParams.Count.CompareTo(yParams.Count);
    }

    private int CompareProperties(IProperty x, IProperty y)
    {
        return string.Compare(x.Name, y.Name, StringComparison.Ordinal);
    }

    private int CompareFields(IField x, IField y)
    {
        return string.Compare(x.Name, y.Name, StringComparison.Ordinal);
    }

    private int CompareEvents(IEvent x, IEvent y)

