using System;

struct Ring
{
    public int Size;

    public Ring(int size)
    {
        Size = size;
    }
}

struct Column
{
    private Ring[] rings;
    private int height;
    private int maxHeight;

    public Column(int maxHeight)
    {
        this.maxHeight = maxHeight;
        rings = new Ring[maxHeight];
        height = 0;
    }

    public void Init(int[] ringSizes)
    {
        for (int i = 0; i < ringSizes.Length; i++)
        {
            if (i < maxHeight)
            {
                rings[i] = new Ring(ringSizes[i]);
                height++;
            }
        }
    }

    public bool Validate()
    {
        for (int i = 1; i < height; i++)
        {
            if (rings[i - 1].Size <= rings[i].Size)
                return false;
        }
        return true;
    }

    public void MoveRingTo(Column to)
    {
        if (height == 0)
            throw new InvalidOperationException("No rings to move.");

        if (to.height < to.maxHeight && (to.height == 0 || rings[height - 1].Size < to.rings[to.height - 1].Size))
        {
            to.rings[to.height] = rings[height - 1];
            to.height++;
            height--;
        }
        else
        {
            throw new InvalidOperationException("Invalid move.");
        }
    }

    public int Height => height;
    public Ring[] Rings => rings;
}

class TowerOfHanoi
{
    public static void Move(Column from, Column to, Column temp, int num)
    {
        if (num == 1)
        {
            from.MoveRingTo(to);
        }
        else
        {
            Move(from, temp, to, num - 1);
            from.MoveRingTo(to);
            Move(temp, to, from, num - 1);
        }
    }

    static void Main(string[] args)
    {
        int maxHeight = 3;
        Column[] columns = new Column[3];
        columns[0] = new Column(maxHeight);
        columns[1] = new Column(maxHeight);
        columns[2] = new Column(maxHeight);

        columns[0].Init(new int[] { 3, 2, 1 }); // Initialize first column with 3 rings

        Console.WriteLine("Initial Columns:");
        DisplayColumns(columns);

        Move(columns[0], columns[2], columns[1], columns[0].Height);

        Console.WriteLine("Columns After Moving:");
        DisplayColumns(columns);
    }

    static void DisplayColumns(Column[] columns)
    {
        for (int i = 0; i < columns.Length; i++)
        {
            Console.Write($"Column {i + 1}: ");
            for (int j = 0; j < columns[i].Height; j++)
            {
                Console.Write(columns[i].Rings[j].Size + " ");
            }

