public delegate void EarlyUpdateDelegate(float deltaTime);
public delegate void FrameUpdatedDelegate(FrameUpdate frameUpdate);

public struct FrameUpdate
{
    public bool IsTracking;
    public IntPtr SessionHandle;
    public IntPtr FrameHandle;

    public FrameUpdate(bool isTracking, IntPtr sessionHandle, IntPtr frameHandle)
    {
        IsTracking = isTracking;
        SessionHandle = sessionHandle;
        FrameHandle = frameHandle;
    }
}

public abstract class BaseLifecycleManager
{
    public event EarlyUpdateDelegate EarlyUpdateEvent;
    public event FrameUpdatedDelegate FrameUpdatedEvent;

    public abstract void Initialize();

    public void UpdateLifecycle(float deltaTime)
    {
        DoEarlyUpdate(deltaTime);
        FrameUpdate updateData = CreateFrameUpdate();
        DoFrameUpdate(updateData);
    }

    protected virtual void DoEarlyUpdate(float deltaTime)
    {
        if (EarlyUpdateEvent != null)
        {
            EarlyUpdateEvent(deltaTime);
        }
    }

    protected virtual void DoFrameUpdate(FrameUpdate update)
    {
        if (FrameUpdatedEvent != null)
        {
            FrameUpdatedEvent(update);
        }
    }

    protected virtual FrameUpdate CreateFrameUpdate()
    {
        // Simulate frame update data.
        bool tracking = true;
        IntPtr sessionHandle = new IntPtr(123);
        IntPtr frameHandle = new IntPtr(456);
        return new FrameUpdate(tracking, sessionHandle, frameHandle);
    }
}

