using System;
using System.Threading.Tasks;
using MassTransit;
using MassTransit.Configuration;
using MassTransit.Context;
using MassTransit.Transports;

public class RequeueCommand
{
    private readonly string _uriString;
    private readonly int _count;
    private readonly IReceiveEndpointConfiguration _endpointConfiguration;
    private readonly ITransportProvider _transportProvider;
    private readonly ILogger _logger;

    public RequeueCommand(
        string uriString,
        int count,
        IReceiveEndpointConfiguration endpointConfiguration,
        ITransportProvider transportProvider,
        ILogger logger)
    {
        _uriString = uriString;
        _count = count;
        _endpointConfiguration = endpointConfiguration;
        _transportProvider = transportProvider;
        _logger = logger;
    }

    public async Task Execute()
    {
        var endpoint = await ToUri(_uriString);
        int requeueCount = 0;

        try
        {
            for (int i = 0; i < _count; i++)
            {
                var message = await Receive(endpoint);

                if (message == null)
                    break;

                await Send(endpoint, message);
                requeueCount++;
            }

            _logger.LogInformation($"Requeued {requeueCount} messages from {_uriString}");
        }
        catch (Exception ex)
        {
            _logger.LogError($"Error requeueing messages: {ex.Message}");
            throw;
        }
    }

    private async Task<Uri> ToUri(string uriString)
    {
        try
        {
            return new Uri(uriString);
        }
        catch
        {
            throw new ArgumentException($"Invalid URI: {uriString}");
        }
    }

    private async Task<IMessage> Receive(Uri endpoint)
    {
        var transport = _transportProvider.GetReceiveTransport(endpoint);
        var receiveContext = await transport.Receive();

        return receiveContext?.Message;
    }

    private async Task Send(Uri endpoint, IMessage message)
    {
        var sendContext = new MoveMessageSendContext(message)
        {
            Destination = endpoint
        };

        var transport = _transportProvider.GetSendTransport(endpoint);
        await transport.Send(sendContext);
    }
}

internal class MoveMessageSendContext : SendContext
{
    public MoveMessageSendContext(IMessage message)
    {
        Message = message;
    }

    public Uri Destination { get; set; }
    public IMessage Message { get; }
}

