            var chasePlayerBehavior = new ChaseBehavior(this, () => Level.Current.pixie, 1000, 50);
            var combatBehavior = new CombatBehavior(this, typeof(RedGuard), 700, 2, 50);
            var chaseRedGuardBehavior = new ChaseBehavior(this, typeof(RedGuard), 700, 50);
            var attackBehavior = new AttackBehavior(this, () => Level.Current.pixie, 100, 1,
                () =>
                {
                    // Attack logic here (e.g., reduce player health)
                });
            var randomWanderBehavior = new RandomWanderBehavior(this, 100, 50, new Vector2(-500, -500), new Vector2(500, 500));

            _subsumptionBehavior.Add(combatBehavior);
            _subsumptionBehavior.Add(chasePlayerBehavior);
            _subsumptionBehavior.Add(chaseRedGuardBehavior);
            _subsumptionBehavior.Add(attackBehavior);
            _subsumptionBehavior.Add(randomWanderBehavior);

