namespace BullsAndCows
{
    class Order
    {
        static void Main(string[] args)
        {
            var len = 4;
            playBullsAndCows(len);
        }
 
        static void playBullsAndCows(int len)
        {
            var num = pickNum(len);
            // print('The secret number is:\n '+ num.join('\n  '));
            showInstructions(len);
            var nGuesses = 0;
            while (true)
            {
                nGuesses++;
                var guess = getGuess(nGuesses, len);
                var census = countBovine(num, guess);
                showScore(census.bulls, census.cows);
                if (census.bulls == len)
                {
                    showFinalResult(nGuesses);
                    return;
                }
            }
        }
 
        static void showScore(int nBulls, int nCows)
        {
            Console.WriteLine("    Bulls: " + nBulls + ", cows: " + nCows);
        }
 
        static void showFinalResult(int guesses)
        {
            Console.WriteLine("You win!!! Guesses needed: " + guesses);
        }
 
        static Census countBovine(int[] num, int[] guess)
        {
            var count = new Census { bulls = 0, cows = 0 };
            var g = guess.Join();
            for (var i = 0; i < num.Length; i++)
            {
                var digPresent = g.Search(num[i])!= -1;
                if (num[i] == guess[i]) count.bulls++;
                else if (digPresent) count.cows++;
            }
            return count;
        }
 
        static int[] getGuess(int nGuesses, int len)
        {
            while (true)
            {
                Console.Write("Your guess #" + nGuesses + ": ");
                var guess = Console.ReadLine();
                guess = String(parseInt(guess)).Split('');
                if (guess.Length!= len)
                {
                    Console.WriteLine("  You must enter a " + len + " digit number.");
                    continue;
                }
                if (hasDups(guess))
                {
                    Console.WriteLine("  No digits can be duplicated.");
                    continue;
                }
                return guess;
            }
        }
 
        static bool hasDups(int[] ary)
        {
            var t = ary.Concat().Sort();
            for (var i = 1; i < t.Length; i++)
            {
                if (t[i] == t[i - 1]) return true;
            }
            return false;

