using System;
 
namespace BinomialCoefficients
{
    class Stack
    {
        static void Main(string[] args)
        {
            ulong n = 1000000, k = 3;
            ulong result = biCoefficient(n, k);
            Console.WriteLine("The Binomial Coefficient of {0}, and {1}, is equal to: {2}", n, k, result);
            Console.ReadLine();
        }
 
        static int fact(int n)
        {
            if (n == 0) return 1;
            else return n * fact(n - 1);
        }
 
        static ulong biCoefficient(ulong n, ulong k)
        {
            if (k > n - k)
            {
                k = n - k;
            }
 
            ulong c = 1;
            for (uint i = 0; i < k; i++)
            {
                c = c * (n - i);
                c = c / (i + 1);
            }
            return c;
        }
    }
}

using System;
using System.Collections.Generic;
 
namespace GoToCSharp
{
    class Task
    {
        static void Main(string[] args)
        {
            double x = 2;
            double xi = 0.5;
            double y = 4;
            double yi = 0.25;
            double z = x + y;
            double zi = 1 / (x + y);
            // point A
 
            List<double> numbers = new List<double> { x, y, z };
            List<double> inverses = new List<double> { xi, yi, zi };
            // point B
 
            List<Func<double, double>> mfs = new List<Func<double, double>>();
            for (int i = 0; i < numbers.Count; i++)
            {
                mfs.Add(multiplier(numbers[i], inverses[i]));
            }
            // point C
 
            foreach (var mf in mfs)
            {
                Console.WriteLine(mf(1));
            }
        }
 
        static Func<double, double> multiplier(double n1, double n2)
        {
            // compute product of n's, store in a new variable
            double n1n2 = n1 * n2;
            // close on variable containing product
            return (m) => n1n2 * m;
        }
    }
}

