namespace CramersRule
{
    class Stack
    {
        static void Main(string[] args)
        {
            Matrix mat = new Matrix(new List<double> { 2, -1, 5, 1 },
                                    new List<double> { 3, 2, 2, -6 },
                                    new List<double> { 1, 3, 3, -1 },
                                    new List<double> { 5, -2, -3, 3 });
            List<double> b = new List<double> { -3, -32, -47, 49 };
            Console.WriteLine("Solution = " + cramersRule(mat, b));
        }
 
        private static List<double> cramersRule(Matrix matrix, List<double> b)
        {
            double denominator = matrix.determinant();
            List<double> result = new List<double>();
            for (int i = 0; i < b.Count; i++)
            {
                result.Add(matrix.replaceColumn(b, i).determinant() / denominator);
            }
            return result;
        }
 
        private class Matrix
        {
 
            private List<List<double>> matrix;
 
            public override string ToString()
            {
                return matrix.ToString();
            }
 
            public Matrix(params List<double>[] lists)
            {
                matrix = new List<List<double>>();
                foreach (List<double> list in lists)
                {
                    matrix.Add(list);
                }
            }
 
            public Matrix(List<List<double>> mat)
            {
                matrix = mat;
            }
 
            public double determinant()
            {
                if (matrix.Count == 1)
                {
                    return get(0, 0);
                }
                if (matrix.Count == 2)
                {
                    return get(0, 0) * get(1, 1) - get(0, 1) * get(1, 0);
                }
                double sum = 0;
                double sign = 1;
                for (int i = 0; i < matrix.Count; i++)
                {
                    sum += sign * get(0, i) * coFactor(0, i).determinant();
                    sign *= -1;
                }
                return sum;
            }
 
