namespace DynamicActivation
{
    // Define an interface for the activator.
    public interface IActivator
    {
        void Activate(ActivationPurpose purpose);
    }

    // Enumeration for activation purpose.
    public enum ActivationPurpose
    {
        Read,
        Write
    }

    // A base method emitter class providing common routines.
    public abstract class BaseMethodEmitter
    {
        protected ModuleDefinition Module;

        protected BaseMethodEmitter(ModuleDefinition module)
        {
            Module = module;
        }
    }

    // The specialized emitter class that constructs the custom activation method.
    public class ActivateMethodEmitter : BaseMethodEmitter
    {
        // The field name holding the activator instance.
        private const string ActivatorFieldName = "internalActivator";

        public ActivateMethodEmitter(ModuleDefinition module) : base(module)
        {
        }

        // Creates and returns a MethodDefinition implementing the activation logic.
        public MethodDefinition Emit(TypeDefinition targetType)
        {
            // Create the method definition: public void Activate(ActivationPurpose purpose)
            var method = new MethodDefinition(
                "Activate",
                MethodAttributes.Public,
                Module.TypeSystem.Void);

            // Add a parameter for activation purpose.
            method.Parameters.Add(new ParameterDefinition("purpose", ParameterAttributes.None, targetType.Module.ImportReference(typeof(ActivationPurpose))));

            // Get the ILProcessor for dynamic IL generation.
            var il = method.Body.GetILProcessor();

            // Define a label for the null branch.
            var activatorNotNullLabel = il.Create(OpCodes.Nop);

            // Load 'this' then load the internal activator field.
            il.Append(il.Create(OpCodes.Ldarg_0));
            var activatorField = targetType.Fields.FirstOrDefault(f => f.Name == ActivatorFieldName);
            if (activatorField == null)
            {
                // If the field doesn't exist, create it.
                activatorField = new FieldDefinition(ActivatorFieldName,
                    FieldAttributes.Private,
                    targetType.Module.ImportReference(typeof(IActivator)));
                targetType.Fields.Add(activatorField);
            }
            il.Append(il.Create(OpCodes.Ldfld, activatorField));
            // Duplicate the value for null check.

