using System.Linq;
using OpenRA.Mods.RA.Activities;
using OpenRA.Mods.RA.Buildings;
using OpenRA.Traits;

public class ReturnOnIdle : ITick
{
    readonly Actor self;

    public ReturnOnIdle(Actor self)
    {
        this.self = self;
    }

    public void Tick(Actor self)
    {
        if (self.IsIdle)
        {
            if (self.Trait<Aircraft>().IsPlaneOnGround)
                return;

            var airfield = ChooseAirfield();
            if (airfield != null)
            {
                self.QueueActivity(new ReturnToBase(self, airfield));
                return;
            }

            var someBuilding = self.World.ActorsWithTrait<Building>()
                .FirstOrDefault(a => a.Actor.Owner.IsAlliedWith(self.Owner));

            if (someBuilding.Actor != null)
            {
                self.QueueActivity(new FlyCircle(self, someBuilding.Actor.CenterPosition));
                return;
            }

            self.QueueActivity(new FlyOffMap(self));
            self.QueueActivity(new RemoveSelf(self));
        }
    }

    Actor ChooseAirfield()
    {
        return self.World.ActorsWithTrait<Airfield>()
            .FirstOrDefault(a => a.Actor.Owner.IsAlliedWith(self.Owner)).Actor;
    }
}

public class FlyAwayOnIdle : ITick
{
    readonly Actor self;

    public FlyAwayOnIdle(Actor self)
    {
        this.self = self;
    }

    public void Tick(Actor self)
    {
        if (self.IsIdle)
        {
            self.QueueActivity(new FlyOffMap(self));
            self.QueueActivity(new RemoveSelf(self));
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using PronoFoot.Business.Contracts;
using PronoFoot.Business.Models;
using PronoFoot.Data;

namespace PronoFoot.Business.Services
{
    public class FixtureService : IFixtureService
    {
        private readonly IFixtureRepository _fixtureRepository;

        public FixtureService(IFixtureRepository fixtureRepository)
        {
            _fixtureRepository = fixtureRepository ?? throw new ArgumentNullException(nameof(fixtureRepository));
        }

        public FixtureModel GetFixture(int fixtureId)
        {
            var rawFixture = _fixtureRepository.GetFixture(fixtureId);

            if (rawFixture == null)
                return null;

            return MapToFixtureModel(rawFixture);
        }

        public FixtureModel GetNextFixture(bool onlyForecastable = true)
        {
            var upcomingFixtures = _fixtureRepository.GetAllFixtures()
                .Where(f => f.MatchDate > DateTime.Now)
                .OrderBy(f => f.MatchDate);

            if (onlyForecastable)
                upcomingFixtures = upcomingFixtures.Where(f => f.IsForecastable);

            var nextFixture = upcomingFixtures.FirstOrDefault();
            return nextFixture != null ? MapToFixtureModel(nextFixture) : null;
        }

        public IEnumerable<FixtureModel> GetFixtures(
            int? editionId = null,
            DateTime? startDate = null,
            DateTime? endDate = null,
            bool onlyForecastable = false)
        {
            var fixtures = _fixtureRepository.GetAllFixtures();

            if (editionId.HasValue)
                fixtures = fixtures.Where(f => f.EditionId == editionId.Value);

            if (startDate.HasValue)
                fixtures = fixtures.Where(f => f.MatchDate >= startDate.Value);

            if (endDate.HasValue)
                fixtures = fixtures.Where(f => f.MatchDate <= endDate.Value);

            if (onlyForecastable)
                fixtures = fixtures.Where(f => f.IsForecastable);

            return fixtures.Select(MapToFixtureModel);
        }

        public IEnumerable<FixtureModel> GetFixturesForDay(DateTime matchDay, bool onlyForecastable = false)
        {
            var fixtures = _fixtureRepository.GetAllFixtures()
                .Where(f => f.MatchDate.Date == matchDay.Date);

            if (onlyForecastable)
                fixtures = fixtures.Where(f => f.IsForecastable);

            return fixtures.Select(MapToFixtureModel);
        }

using Xunit;
using System;
using System.Xml;

namespace XmlDocumentTests.XmlDocumentTests
{
    public class CreateAttributeTests
    {
        [Fact]
        public static void CreateBasicAttributeTest()
        {
            var xmlDocument = new XmlDocument();
            var attribute = xmlDocument.CreateAttribute("attributeName");

            Assert.Equal("attributeName", attribute.Name);
            Assert.Equal("attributeName", attribute.LocalName);
            Assert.Equal(String.Empty, attribute.Value);
            Assert.Equal(String.Empty, attribute.Prefix);
            Assert.Equal("attributeName=\"\"", attribute.OuterXml);
            Assert.Equal(String.Empty, attribute.InnerXml);
            Assert.Equal(XmlNodeType.Attribute, attribute.NodeType);
        }

        [Fact]
        public static void AttributeWithNoPrefixIsTheSameAsWithEmptyPrefix()
        {
            var xmlDocument = new XmlDocument();
            var attribute = xmlDocument.CreateAttribute("Att1");
            var attributeWithEmptyNamespace = xmlDocument.CreateAttribute("Att1", "");

            Assert.Equal(attribute.Name, attributeWithEmptyNamespace.Name);
            Assert.Equal(attribute.LocalName, attributeWithEmptyNamespace.LocalName);
            Assert.Equal(attribute.NamespaceURI, attributeWithEmptyNamespace.NamespaceURI);
            Assert.Equal(attribute.Prefix, attributeWithEmptyNamespace.Prefix);
        }

        [Fact]
        public static void AttributeWithPrefix()
        {
            var xmlDocument = new XmlDocument();
            var attribute = xmlDocument.CreateAttribute("attributeName", "namespace");

            Assert.Equal("attributeName", attribute.LocalName);
            Assert.Equal(String.Empty, attribute.Value);
            Assert.Equal(String.Empty, attribute.Prefix);
            Assert.Equal("namespace", attribute.NamespaceURI);
            Assert.Equal(String.Empty, attribute.InnerXml);
            Assert.Equal(XmlNodeType.Attribute, attribute.NodeType);

        }
    }
}

