namespace JetBrains.ReSharper.Psi.Impl.Reflection2.ExternalAnnotations
{
  // Interface for external annotation files provider.
  public interface IExternalAnnotationFilesProvider
  {
    /// <summary>
    /// Returns the list of external XML annotation file paths.
    /// If assemblyName is provided, only files relevant to that assembly are returned.
    /// </summary>
    IEnumerable<string> GetAnnotationFiles(string assemblyName = null);
  }

  // Provider for external annotation XML files in a testing environment.
  // This class scans a pre-determined annotations folder and indexes XML files in a case-insensitive map.
  public class ExternalAnnotationFilesProvider : IExternalAnnotationFilesProvider
  {
    // Map from key (file name or directory name) to a set of annotation file paths.
    private readonly Dictionary<string, HashSet<string>> _annotationsMap;

    // Cached base directory for test data.
    private static string _cachedBaseDirectory;

    // Constructor initializes the annotations map and performs the scan.
    public ExternalAnnotationFilesProvider()
    {
      _annotationsMap = new Dictionary<string, HashSet<string>>(StringComparer.OrdinalIgnoreCase);
      InitializeAnnotations();
    }

    // Scans the ExternalAnnotations folder recursively for XML files and populates the map.
    private void InitializeAnnotations()
    {
      string baseDir = GetBaseDirectory();
      string annotationsDir = Path.Combine(baseDir, "ExternalAnnotations");

      if (!Directory.Exists(annotationsDir))
        return;

      var xmlFiles = Directory.GetFiles(annotationsDir, "*.xml", SearchOption.AllDirectories);

      foreach (var filePath in xmlFiles)
      {
        string fileName = Path.GetFileName(filePath);
        // Use the file name as a key.
        AddToMap(fileName, filePath);

        // Also use the parent directory name as a key if applicable.
        string parentDir = new DirectoryInfo(Path.GetDirectoryName(filePath)).Name;
        if (!string.Equals(parentDir, "ExternalAnnotations", StringComparison.OrdinalIgnoreCase))
        {
          AddToMap(parentDir, filePath);
        }
      }
    }

    // Helper method to add a file path to the internal map under the given key.
    private void AddToMap(string key, string filePath)
    {
      if (!_annotationsMap.TryGetValue(key, out var fileSet))
      {
        fileSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        _annotationsMap[key] = fileSet;
      }

using Xemio.GameLibrary.Content;
using Xemio.GameLibrary.Game;
using Xemio.GameLibrary.Rendering;
using Xemio.GameLibrary.Math;

public class TestSceneLoader : LoadingScene
{
    private Font _font;
    private int _totalElementsToLoad;
    private int _completedElements;
    private string _loadingMessage;

    public TestSceneLoader(IContentLoader contentLoader, int totalElementsToLoad)
        : base(contentLoader)
    {
        _totalElementsToLoad = totalElementsToLoad;
        _completedElements = 0;
        _loadingMessage = "Loading...";
    }

    protected override void LoadContent()
    {
        _font = this.Content.Load<Font>("Fonts/LoadingFont");
        base.LoadContent();
    }

    protected override void OnCompleted()
    {
        _loadingMessage = "Loading Complete!";
        TransitionToNextScene();
    }

    public override void Update(GameTime gameTime)
    {
        if (IsLoadingComplete())
        {
            OnCompleted();
            return;
        }

        UpdateLoadingProgress();
        base.Update(gameTime);
    }

    private void UpdateLoadingProgress()
    {
        if (_completedElements < _totalElementsToLoad)
        {
            _completedElements++;
            _loadingMessage = $"Loading... {GetProgressPercentage()}%";
        }
    }

    private int GetProgressPercentage()
    {
        return (_completedElements * 100) / _totalElementsToLoad;
    }

    public override void Render(RenderContext context)
    {
        context.Clear(Color.Black);
        DrawLoadingText(context);
        DrawProgressSlider(context);
    }

    private void DrawLoadingText(RenderContext context)
    {
        context.DrawString(_font, _loadingMessage, new Vector2(100, 100), Color.White);
    }

    private void DrawProgressSlider(RenderContext context)
    {
        float progressWidth = (GetProgressPercentage() / 100f) * 400;
        context.FillRectangle(new Rectangle(100, 150, (int)progressWidth, 20), Color.Blue);
        context.DrawRectangle(new Rectangle(100, 150, 400, 20), Color.White);
    }

    private bool IsLoadingComplete()
    {
        return _completedElements >= _totalElementsToLoad;
    }

    private void TransitionToNextScene()
    {
        // Logic to transition to the next scene
        // This could be an async operation depending on the game architecture
        Game.Instance.ChangeScene("NextScene");
    }
}

