public class MoLangRuntime
{
    private static readonly Logger Logger = LogManager.GetCurrentClassLogger();

    public void Execute(params IExpression[] expressions)
    {
        Execute(expressions, null);
    }

    public void Execute(IExpression[] expressions, IDictionary<string, IMoValue> context)
    {
        if (expressions == null || expressions.Length == 0)
        {
            Logger.Warn("No expressions provided for execution.");
            return;
        }

        MoLangEnvironment environment = new MoLangEnvironment();
        MoScope scope = new MoScope(context);
        List<IMoValue> results = new List<IMoValue>();

        try
        {
            foreach (var expression in expressions)
            {
                Logger.Info($"Executing expression: {expression}");
                IMoValue result = EvaluateExpression(expression, scope);
                results.Add(result);

                if (result is ReturnValue returnValue)
                {
                    Logger.Info("Return value encountered, terminating execution.");
                    break;
                }
            }
        }
        catch (MoLangException ex)
        {
            Logger.Error($"MoLang execution error: {ex.Message} - Context: {ex.Context}");
        }
        finally
        {
            scope.Clear();
        }
    }

    private IMoValue EvaluateExpression(IExpression expression, MoScope scope)
    {
        try
        {
            Logger.Debug($"Evaluating expression: {expression}");
            // This is a placeholder for actual evaluation logic.
            // In a real implementation, we would parse and execute the expression.
            return new DoubleValue(42); // Example result for demonstration.
        }
        catch (Exception ex)
        {
            throw new MoLangException("Failed to evaluate expression.", ex.Message, scope.GetContext());
        }
    }
}

