using System;
using System.IO;
using fyiReporting.RDL;
using Cairo;

public class CairoPdfWriter
{
    public static byte[] GetFileBytes(Report report)
    {
        string tempPdfFile = Path.GetTempFileName() + ".pdf";

        try
        {
            // Build Pages from Report
            Pages pages = report.BuildPages();

            // Create Cairo PDF surface
            using (PdfSurface surface = new PdfSurface(tempPdfFile, pages.PageWidth, pages.PageHeight))
            {
                using (Context context = new Context(surface))
                {
                    // Render each page
                    foreach (Page page in pages)
                    {
                        context.Save(); // Save the current context state

                        // Render the page content (replace with actual rendering logic)
                        // This is a placeholder - real rendering from RDL would go here.
                        context.Rectangle(0, 0, pages.PageWidth, pages.PageHeight);
                        context.SetSourceRGB(1, 1, 1); // White background
                        context.Fill();
                        // Example:  Draw a line on each page
                        context.SetSourceRGB(0, 0, 0);
                        context.MoveTo(50, 50);
                        context.LineTo(pages.PageWidth - 50, pages.PageHeight - 50);
                        context.Stroke();

                        context.Restore(); // Restore the context to its previous state
                        surface.ShowPage(); // Start a new page
                    }
                }
            }

            // Read the PDF file into a byte array
            byte[] pdfBytes = File.ReadAllBytes(tempPdfFile);

            return pdfBytes;
        }
        finally
        {
            // Clean up the temporary file
            if (File.Exists(tempPdfFile))
            {
                File.Delete(tempPdfFile);
            }
        }
    }
}

