using System;
using System.Collections.Generic;
using System.Configuration;
using System.Security.Principal;
using System.Web.Mvc;
using AutoMapper;
using Extant.Data.Entities;
using Extant.Pubmed;
using Extant.Web.Infrastructure;
using StructureMap;

public static class Bootstrapper
{
    public static void Bootstrap()
    {
        var modelBinderTypeMappings = new Dictionary<Type, Type>();

        // Configure AutoMapper
        Mapper.Initialize(cfg =>
        {
            cfg.AddProfile<AutoMapperProfile>();
            cfg.ConstructServicesUsing(ObjectFactory.GetInstance);
        });

        // Configure StructureMap
        ObjectFactory.Initialize(x =>
        {
            x.Scan(scan =>
            {
                scan.AssembliesFromApplicationBaseDirectory();
                scan.WithDefaultConventions();
            });

            x.For<IIdentity>().Use(() => System.Web.HttpContext.Current.User.Identity);
            x.For<IPrincipal>().Use(() => System.Web.HttpContext.Current.User);
            x.For<NHibernate.ISessionFactory>().Singleton().Use(NHibernateConfig.CreateSessionFactory());
            x.For<IMailer>().Use<SmtpMailer>().Ctor<string>("smtpServer").Is(ConfigurationManager.AppSettings["SmtpServer"]);
            x.For<IPubMedService>().Use<PubMedService>();
            x.For<IModelBinderProvider>().Use<StructureMapModelBinderProvider>();
        });

        // Set MVC dependency resolver to use StructureMap
        DependencyResolver.SetResolver(new StructureMapDependencyResolver(ObjectFactory.Container));

        // Register custom model binders
        foreach (var mapping in modelBinderTypeMappings)
        {
            ModelBinders.Binders.Add(mapping.Key, (IModelBinder)ObjectFactory.GetInstance(mapping.Value));
        }
    }
}

using System;
