using Pomona;
using Critters.Client;

public class VirtualPropertyThing
{
    public int Id { get; set; }
    public string Name { get; set; }

    public virtual int ComputedValue => Id * 10; // Example of a virtual property
}

public class VirtualPropertyThingForm
{
    public string Name { get; set; }
}

public class VirtualPropertyTests
{
    private IClient<VirtualPropertyThing> client;

    [SetUp]
    public void SetUp()
    {
        client = new CrittersClient<VirtualPropertyThing>("http://localhost:5000/api/virtualproperty");
    }

    [Test]
    public void CreateVirtualPropertyThing_ShouldReturnCreatedEntity()
    {
        var form = new VirtualPropertyThingForm { Name = "Test Entity" };
        var createdEntity = client.Post(form);

        Assert.IsNotNull(createdEntity);
        Assert.AreEqual("Test Entity", createdEntity.Name);
    }

    [Test]
    public void GetVirtualPropertyThing_ShouldReturnCorrectEntity()
    {
        var form = new VirtualPropertyThingForm { Name = "Another Entity" };
        var createdEntity = client.Post(form);

        var retrievedEntity = client.Get(createdEntity.Id);

        Assert.IsNotNull(retrievedEntity);
        Assert.AreEqual(createdEntity.Name, retrievedEntity.Name);
    }

    [Test]
    public void QueryVirtualPropertyThing_ShouldReturnEntitiesWithComputedValues()
    {
        var form1 = new VirtualPropertyThingForm { Name = "Entity One" };
        var form2 = new VirtualPropertyThingForm { Name = "Entity Two" };

        var entity1 = client.Post(form1);
        var entity2 = client.Post(form2);

        var queryResult = client.Query(item => item.ComputedValue > 0);

        Assert.IsTrue(queryResult.Contains(entity1));
        Assert.IsTrue(queryResult.Contains(entity2));
    }

    [Test]
    public void UpdateVirtualPropertyThing_ShouldReflectChanges()
    {
        var form = new VirtualPropertyThingForm { Name = "Updatable Entity" };
        var createdEntity = client.Post(form);

        createdEntity.Name = "Updated Entity";
        var updatedEntity = client.Save(createdEntity);

        Assert.IsNotNull(updatedEntity);
        Assert.AreEqual("Updated Entity", updatedEntity.Name);
    }

    [Test]
    public void RetrieveComputedValue_ShouldMatchExpected()
    {
        var form = new VirtualPropertyThingForm { Name = "Entity with Computed Value" };
        var createdEntity = client.Post(form);

        var computedValue = createdEntity.ComputedValue;

        Assert.AreEqual(createdEntity.Id * 10, computedValue);
    }

