        if (value == 0)
            Console.WriteLine("Root found at {0}", start);
 
        for (var x = start + step; x <= stop; x += step)
        {
            value = f(x);
 
            if (((value > 0) ? 1 : 0) != sign)
                // We passed a root
                Console.WriteLine("Root found near {0}", x);
            else if (value == 0)
                // We hit a root
                Console.WriteLine("Root found at {0}", x);
 
            // Update our sign
            sign = (value > 0) ? 1 : 0;
        }
    }
}

