    [TestFixture]
    public class Fixture
    {
        private ISessionFactory sessionFactory;

        [SetUp]
        public void SetUp()
        {
            var configuration = new Configuration();
            configuration.Configure(); // Assume nhibernate.cfg.xml is in place
            configuration.AddAssembly(typeof(Aclass).Assembly);
            sessionFactory = configuration.BuildSessionFactory();
        }

        [TearDown]
        public void TearDown()
        {
            sessionFactory.Dispose();
        }

        [Test]
        public void WithDefaultValuesInConfiguration()
        {
            ValidateSchemaGeneration("defaultConfiguration.sql");
        }

        [Test]
        public void WithDefaultValuesInMapping()
        {
            ValidateSchemaGeneration("defaultMapping.sql");
        }

        [Test]
        public void WithSpecificValuesInMapping()
        {
            ValidateSchemaGeneration("specificMapping.sql");
        }

        private void ValidateSchemaGeneration(string expectedFile)
        {
            var output = new StringBuilder();
            using (var stringWriter = new StringWriter(output))
            {
                var schemaExport = new SchemaExport(sessionFactory);
                schemaExport.Execute(true, false, false, stringWriter);
            }

            var generatedSql = output.ToString();
            var expectedSql = File.ReadAllText(expectedFile);

            Assert.IsTrue(generatedSql.Contains(expectedSql),
                $"Expected SQL not found in generated SQL.\nGenerated SQL:\n{generatedSql}\nExpected SQL:\n{expectedSql}");
        }

        [Test]
        public void Bug()
        {
            // This method can be used to directly observe schema generation without formal tests.
            var output = new StringBuilder();
            using (var stringWriter = new StringWriter(output))
            {
                var schemaExport = new SchemaExport(sessionFactory);
                schemaExport.Execute(false, true, false, stringWriter);
            }

            Console.WriteLine("Generated SQL:\n" + output);
        }
    }
