        private const int Count = 10;
        private SQLiteConnection connection;

        [SetUp]
        public void CreateDb()
        {
            connection = new SQLiteConnection("Data Source=:memory:;Version=3;");
            connection.Open();
            CreateTestTable();
            InsertTestData();
        }

        private void CreateTestTable()
        {
            using (var command = connection.CreateCommand())
            {
                command.CommandText = @"
                    CREATE TABLE TestTable (
                        Id INTEGER PRIMARY KEY,
                        Value INTEGER,
                        NullableValue INTEGER
                    )";
                command.ExecuteNonQuery();
            }
        }

        private void InsertTestData()
        {
            using (var transaction = connection.BeginTransaction())
            {
                for (int i = 1; i <= Count; i++)
                {
                    using (var command = connection.CreateCommand())
                    {
                        command.CommandText = "INSERT INTO TestTable (Value, NullableValue) VALUES (@value, @nullableValue)";
                        command.Parameters.AddWithValue("@value", i);
                        command.Parameters.AddWithValue("@nullableValue", i % 2 == 0 ? (int?)null : i);
                        command.ExecuteNonQuery();
                    }
                }
                transaction.Commit();
            }
        }

        [Test]
        public void TestAggregateSum()
        {
            var result = ExecuteScalar<int>("SELECT SUM(Value) FROM TestTable");
            Assert.AreEqual(55, result);
        }

