        public void TestCountNonNull()
        {
            var result = ExecuteScalar<int>("SELECT COUNT(NullableValue) FROM TestTable");
            Assert.AreEqual(5, result);
        }

        [Test]
        public void TestMaxValue()
        {
            var result = ExecuteScalar<int>("SELECT MAX(Value) FROM TestTable");
            Assert.AreEqual(10, result);
        }

        [Test]
        public void TestSingleRowValue()
        {
            var result = ExecuteScalar<int>("SELECT Value FROM TestTable WHERE Id = 5");
