using System;
using System.Collections.Generic;
using System.IO;
using JetBrains.Application;
using JetBrains.Metadata.Utils;
using JetBrains.ReSharper.Psi.Impl.Reflection2.ExternalAnnotations;
using JetBrains.Util;

[ShellComponent]
public class ExternalAnnotationsProvider : IExternalAnnotationsProvider
{
    private readonly Dictionary<string, HashSet<FileSystemPath>> annotations = new Dictionary<string, HashSet<FileSystemPath>>(StringComparer.OrdinalIgnoreCase);
    private readonly FileSystemPath baseTestDataPath;

    public ExternalAnnotationsProvider()
    {
        baseTestDataPath = GetBaseTestDataPath();
        LoadAnnotationsFromDirectory(baseTestDataPath);
    }

    private FileSystemPath GetBaseTestDataPath()
    {
        // This method should return the base path where the XML files are located
        // For demonstration, we assume it's in a specific subdirectory of the application data
        return FileSystemPath.Parse(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "ReSharper", "XunitAnnotations"));
    }

    private void LoadAnnotationsFromDirectory(FileSystemPath directory)
    {
        if (!directory.ExistsFile)
            return;

        foreach (var file in directory.GetFiles("*.xml", SearchOption.AllDirectories))
        {
            string fileNameWithoutExtension = Path.GetFileNameWithoutExtension(file.Name);
            string directoryName = file.Parent.Name;

            if (!annotations.ContainsKey(fileNameWithoutExtension))
                annotations[fileNameWithoutExtension] = new HashSet<FileSystemPath>(StringComparer.OrdinalIgnoreCase);

            if (!annotations.ContainsKey(directoryName))
                annotations[directoryName] = new HashSet<FileSystemPath>(StringComparer.OrdinalIgnoreCase);

            annotations[fileNameWithoutExtension].Add(file);
            annotations[directoryName].Add(file);
        }
    }

    public IEnumerable<FileSystemPath> GetAnnotationsFiles(string assemblyName = null)
    {
        if (string.IsNullOrEmpty(assemblyName))
        {
            foreach (var set in annotations.Values)
            {
                foreach (var path in set)
                {
                    yield return path;
                }
            }
        }
        else if (annotations.TryGetValue(assemblyName, out var paths))
        {
            foreach (var path in paths)
            {
                yield return path;
            }
        }
    }
}

using System;
using System.Collections.Generic;
 
namespace ShoelaceFormula {
    using Point = Tuple<double, double>;
 
    class Parser {
        static double ShoelaceArea(List<Point> v) {
            int n = v.Count;
            double a = 0.0;
            for (int i = 0; i < n - 1; i++) {
                a += v[i].Item1 * v[i + 1].Item2 - v[i + 1].Item1 * v[i].Item2;
            }
            return Math.Abs(a + v[n - 1].Item1 * v[0].Item2 - v[0].Item1 * v[n - 1].Item2) / 2.0;
        }
 
        static void Main(string[] args) {
            List<Point> v = new List<Point>() {
                new Point(3,4),
                new Point(5,11),
                new Point(12,8),
                new Point(9,5),
                new Point(5,6),
            };
            double area = ShoelaceArea(v);
            Console.WriteLine("Given a polygon with vertices [{0}],", string.Join(", ", v));
            Console.WriteLine("its area is {0}.", area);
        }
    }
}

