public static class ReflectionHelper
{
    public static T GetAttribute<T>(ICustomAttributeProvider t) where T : Attribute
    {
        var attributes = t.GetCustomAttributes(typeof(T), false);
        return attributes.Length > 0 ? (T)attributes[0] : null;
    }

    public static bool HasAttribute<T>(ICustomAttributeProvider t) where T : Attribute
    {
        return t.IsDefined(typeof(T), false);
    }

    public static bool IsOutput(ICustomAttributeProvider t)
    {
        return HasAttribute<OutputAttribute>(t);
    }

    public static bool IsRequired(ICustomAttributeProvider t)
    {
        return HasAttribute<RequiredAttribute>(t);
    }

    public static Assembly LoadAssembly(ITaskItem assemblyItem, TaskLoggingHelper logger)
    {
        if (assemblyItem == null)
        {
            logger.LogError("Assembly item is null.");
            return null;
        }

        string assemblyPath = assemblyItem.ItemSpec;
        if (!File.Exists(assemblyPath))
        {
            logger.LogError($"Assembly file not found: {assemblyPath}");
            return null;
        }

        try
        {
            return Assembly.LoadFrom(assemblyPath);
        }
        catch (BadImageFormatException ex)
        {
            logger.LogError($"Bad image format for assembly: {assemblyPath}. Error: {ex.Message}");
        }
        catch (FileNotFoundException ex)
        {
            logger.LogError($"File not found for assembly: {assemblyPath}. Error: {ex.Message}");
        }
        catch (FileLoadException ex)
        {
            logger.LogError($"File load exception for assembly: {assemblyPath}. Error: {ex.Message}");
        }
        catch (Exception ex)
        {
            logger.LogError($"An error occurred while loading assembly: {assemblyPath}. Error: {ex.Message}");
        }

        return null;
    }
}

using System;
 
namespace ShellSort
{
    class Generator
    {
        static void Main(string[] args)
        {
            int[] numbers = { 4, 65, 2, -31, 0, 99, 2, 83, 782, 1 };
            Console.WriteLine("Before: [{0}]", string.Join(", ", numbers));
            ShellSort(numbers);
            Console.WriteLine("After: [{0}]", string.Join(", ", numbers));
        }
 
        static void ShellSort<T>(T[] v) where T : IComparable<T>
        {
            int gap = v.Length / 2;
            int len = v.Length;
            while (gap > 0)
            {
                for (int i = gap; i < len; i++)
                {
                    T temp = v[i];
                    int j = i;
                    while (j >= gap && v[j - gap].CompareTo(temp) > 0)
                    {
                        v[j] = v[j - gap];
                        j -= gap;
                    }
                    v[j] = temp;
                }
                gap /= 2;
            }
        }
    }
}

