using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;
 
class Queue
{
    static void Main(string[] args)
    {
        var rangeString = "-6,-3--1,3-5,7-11,14,15,17-20";
        var matches = Regex.Matches(rangeString, @"(?<f>-?\d+)-(?<s>-?\d+)|(-?\d+)");
        var values = new List<string>();
 
        foreach (var m in matches.OfType<Match>())
        {
            if (m.Groups[1].Success)
            {
                values.Add(m.Value);
                continue;
            }
 
            var start = Convert.ToInt32(m.Groups["f"].Value);
            var end = Convert.ToInt32(m.Groups["s"].Value) + 1;
 
            values.AddRange(Enumerable.Range(start, end - start).Select(v => v.ToString()));
        }
 
        Console.WriteLine(string.Join(", ", values));
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using CsvHelper;
using CsvHelper.Configuration;

public class CsvInputHandler : InputHandler, IEnumerable<CsvInputHandler.Row>, IDisposable
{
    private bool _disposed;
    private List<string> _headers;

    [Parameter]
    public string Filename { get; set; }

    public CsvInputHandler(string filename) => Filename = filename;

    public IReadOnlyList<string> Headers => _headers?.AsReadOnly();

    public void Dispose()
    {
        if (!_disposed)
        {
            _disposed = true;
            GC.SuppressFinalize(this);
        }
    }

    public IEnumerator<Row> GetEnumerator()
    {
        if (_disposed)
            throw new ObjectDisposedException(GetType().Name);

        using var streamReader = new StreamReader(Filename);
        using var csvReader = new CsvReader(streamReader, CultureInfo.InvariantCulture);

        csvReader.Read();
        csvReader.ReadHeader();
        _headers = new List<string>(csvReader.HeaderRecord);

        int rowIndex = 0;
        while (csvReader.Read())
        {
            var data = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            bool isEmpty = true;

            foreach (var header in _headers)
            {
                var value = csvReader.GetField(header)?.Trim();
                data[header] = value;
                isEmpty &= string.IsNullOrEmpty(value);
            }

            if (!isEmpty)
                yield return new Row(data, rowIndex++);
        }
    }

    IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();

    public class Row
    {
        private readonly Dictionary<string, string> _data;

        public int Index { get; }

        public Row(Dictionary<string, string> data, int index)
        {
            _data = data;
            Index = index;
        }

        public string this[string field] =>
            _data.TryGetValue(field, out var value) ? value : null;
    }
}

