namespace SmallestRangeFinder
{
    class Reader
    {
        static void Main(string[] args)
        {
            // Initialize test data: multiple sorted integer arrays
            int[] arr1 = { 4, 10, 15, 24, 26 };
            int[] arr2 = { 0, 9, 12, 20 };
            int[] arr3 = { 5, 18, 22, 30 };

            // Combine test arrays into a list for convenience
            List<int[]> arrays = new List<int[]> { arr1, arr2, arr3 };

            // Compute the smallest range that includes at least one element from each array
            var range = FindSmallestRange(arrays);

            // Output the result
            Console.WriteLine("The smallest range is: [{0}, {1}]", range.Item1, range.Item2);
        }

        /// <summary>
        /// Finds the smallest continuous numerical interval that contains at least one element from each of the provided sorted arrays.
        /// </summary>
        /// <param name="arrays">List of sorted integer arrays</param>
        /// <returns>A tuple where Item1 is the lower bound and Item2 is the upper bound of the interval</returns>
        public static Tuple<int, int> FindSmallestRange(List<int[]> arrays)
        {
            // Number of arrays provided.
            int k = arrays.Count;

            // Create an array to track the current index in each sorted array.
            int[] indices = new int[k];

            // Variables to store the best range found so far.
            int bestMin = 0;
            int bestMax = int.MaxValue;
            int bestRange = bestMax - bestMin;

            // Loop until one of the arrays is fully traversed.
            while (true)
            {
                int currentMin = int.MaxValue;
                int currentMax = int.MinValue;
                int minArrayIndex = 0;

                // Iterate over each array to determine the current minimum and maximum values
                for (int i = 0; i < k; i++)
                {
                    // If the current index has reached the end of the array, we cannot continue
                    if (indices[i] == arrays[i].Length)
                    {
                        return Tuple.Create(bestMin, bestMax);
                    }

                    int value = arrays[i][indices[i]];

                    // Update the current minimum value and record which array it came from.
                    if (value < currentMin)
                    {
                        currentMin = value;
                        minArrayIndex = i;

