namespace JewelryInventory
{
    public abstract class BaseRing : Item
    {
        private int m_GemTypeNumber;

        public BaseRing(int itemID) : base(itemID)
        {
            Weight = 0.1;
            Layer = Layer.Ring;
            Hue = 0;
            Name = "Base Ring";
        }

        public virtual int GemTypeNumber
        {
            get => m_GemTypeNumber;
            set => m_GemTypeNumber = Math.Clamp(value, 0, 5);
        }

        public override void Serialize(GenericWriter writer)
        {
            base.Serialize(writer);
            writer.Write(0); // Version
            writer.Write(m_GemTypeNumber);
        }

        public override void Deserialize(GenericReader reader)
        {
            base.Deserialize(reader);
            int version = reader.ReadInt();

            if (version >= 0)
            {
                m_GemTypeNumber = reader.ReadInt();
            }
        }
    }

