    /// <summary>
    /// Represents a database function with its associated metadata
    /// </summary>
    public class Function : IFunction
    {
        /// <summary>
        /// Initializes a new instance of the Function class
        /// </summary>
        /// <param name="name">The name of the database function</param>
        /// <param name="definition">The definition or body of the function</param>
        /// <param name="source">The source context of the function</param>
        public Function(string name, string definition, ISource source)
        {
            Name = name ?? throw new ArgumentNullException(nameof(name));
            Definition = definition ?? throw new ArgumentNullException(nameof(definition));
            Source = source ?? throw new ArgumentNullException(nameof(source));
        }

        /// <summary>
        /// Gets the name of the database function
        /// </summary>
        public string Name { get; private set; }

        /// <summary>
        /// Gets the definition or body of the database function
        /// </summary>
        public string Definition { get; private set; }

        /// <summary>
        /// Gets the source context of the database function
        /// </summary>
        public ISource Source { get; private set; }

        /// <summary>
        /// Determines whether the specified object is equal to the current function
        /// </summary>
        /// <param name="obj">The object to compare with the current function</param>
        /// <returns>True if the objects are equal, otherwise false</returns>
        public override bool Equals(object obj)
        {
            if (obj is Function other)
            {
                return Name == other.Name &&
                       Definition == other.Definition &&
                       Source.Equals(other.Source);
            }
            return false;
        }

        /// <summary>
        /// Serves as the default hash function for the Function type
        /// </summary>
        /// <returns>A hash code for the current function</returns>
        public override int GetHashCode()
        {
            return HashCode.Combine(Name, Definition, Source);
        }

        /// <summary>
        /// Returns a string representation of the function
        /// </summary>
        /// <returns>A string that represents the current function</returns>
        public override string ToString()
        {

