namespace Builder
{
    class Sorter
    {
        static void Main(string[] args)
        {
            string[] s = { "~/{Downloads,Pictures}/*.{jpg,gif,png}", "It{{em,alic}iz,erat}e{d,}, please.", "{,{,gotta have{,\\, again\\, }}more }cowbell!", "} some }{,{\\\\{ edge, edge} \\,}{ cases, {here} \\\\\\\\\}" };
            foreach (string s1 in s)
            {
                Console.WriteLine(s1);
                foreach (string s2 in getitem(s1))
                {
                    Console.WriteLine(s2);
                }
            }
            Console.ReadLine();
        }

        static List<string> getitem(string s, int depth = 0)
        {
            List<string> out1 = new List<string>();
            out1.Add("");
            while (s.Length > 0)
            {
                char c = s[0];
                if (depth > 0 && (c == ',' || c == '}'))
                {
                    return out1;
                }
                if (c == '{')
                {
                    Tuple<List<string>, string> x = getgroup(s.Substring(1), depth + 1);
                    if (x!= null)
                    {
                        out1 = (from a in out1 from b in x.Item1 select a + b).ToList();
                        s = x.Item2;
                        continue;
                    }
                }
                if (c == '\\' && s.Length > 1)
                {
                    s = s.Substring(1);
                    c = c + s[0];
                }
                out1 = (from a in out1 select a + c).ToList();
                s = s.Substring(1);
            }
            return out1;
        }

        static Tuple<List<string>, string> getgroup(string s, int depth)
        {
            List<string> out1 = new List<string>();
            bool comma = false;
            while (s.Length > 0)
            {
                Tuple<List<string>, string> g = getitem(s, depth);
                if (g == null)
                {
                    return null;
                }
                out1.AddRange(g.Item1);
                s = g.Item2;
                if (s.Length == 0)
                {
                    break;
                }
                if (s[0] == '}')
                {
                    if (comma)
                    {
                        return new Tuple<List<string>, string>(out1, s.Substring(1));
                    }

