public class AlphaController : MonoBehaviour
{
    [SerializeField] private float defaultFadeSpeed = 2f;
    private Dictionary<Graphic, alphaInfo> uiElements = new Dictionary<Graphic, alphaInfo>();
    private bool isInFading = false;
    private bool isBusy = false;

    private struct alphaInfo
    {
        public float currentAlpha;
        public float targetAlpha;
        public bool isVisible;
    }

    public void AddUIElement(Graphic element, bool initialVisibility = true)
    {
        if (!uiElements.ContainsKey(element))
        {
            alphaInfo info = new alphaInfo
            {
                currentAlpha = initialVisibility ? 1f : 0f,
                targetAlpha = initialVisibility ? 1f : 0f,
                isVisible = initialVisibility
            };
            uiElements[element] = info;
            UpdateElementAlpha(element, info.currentAlpha);
        }
    }

    public void RemoveUIElement(Graphic element)
    {
        if (uiElements.ContainsKey(element))
        {
            uiElements.Remove(element);
        }
    }

    public void Show(Graphic element, float fadeSpeed = -1f)
    {
        if (uiElements.ContainsKey(element))
        {
            StartCoroutine(FadeElement(element, 1f, fadeSpeed));
        }
    }

    public void Hide(Graphic element, float fadeSpeed = -1f)
    {
        if (uiElements.ContainsKey(element))
        {
            StartCoroutine(FadeElement(element, 0f, fadeSpeed));
        }
    }

    private IEnumerator FadeElement(Graphic element, float targetAlpha, float fadeSpeed = -1f)
    {
        if (isBusy) yield return StartCoroutine(WaitBusy());

        isInFading = true;
        isBusy = true;

        float speed = fadeSpeed > 0 ? fadeSpeed : defaultFadeSpeed;
        alphaInfo info = uiElements[element];
        info.targetAlpha = targetAlpha;
        info.isVisible = targetAlpha > 0.5f;

        while (Mathf.Abs(info.currentAlpha - info.targetAlpha) > 0.01f)
        {
            info.currentAlpha = Mathf.Lerp(info.currentAlpha, info.targetAlpha, speed * Time.deltaTime);
            UpdateElementAlpha(element, info.currentAlpha);
            yield return null;
        }

        info.currentAlpha = info.targetAlpha;
        UpdateElementAlpha(element, info.currentAlpha);
        uiElements[element] = info;

        isInFading = false;
        isBusy = false;
    }

    private void UpdateElementAlpha(Graphic element, float alpha)
    {
        Color color = element.color;

