public class WeaverVendorInventory
{
    private SellInventory m_SellInventory;
    private BuyInventory m_BuyInventory;

    public WeaverVendorInventory()
    {
        m_SellInventory = new SellInventory();
        m_BuyInventory = new BuyInventory();
    }

    public List<SellInfo> SellItems
    {
        get { return m_SellInventory.Items; }
    }

    public List<BuyInfo> BuyItems
    {
        get { return m_BuyInventory.Items; }
    }

    public class SellInventory
    {
        public List<SellInfo> Items { get; private set; }

        public SellInventory()
        {
            Items = new List<SellInfo>();
            // Configure items available for sale in the weaving shop.
            Items.Add(new SellInfo(typeof(WeaveCloth), 25, 10, 101));
            Items.Add(new SellInfo(typeof(WeaveLoom), 50, 5, 102));
            Items.Add(new SellInfo(typeof(WeaveDye), 15, 20, 103));
            Items.Add(new SellInfo(typeof(WeaveCarpet), 80, 3, 104));
            Items.Add(new SellInfo(typeof(WeaveBanner), 60, 2, 105));
        }
    }

    public class BuyInventory
    {
        public List<BuyInfo> Items { get; private set; }

        public BuyInventory()
        {
            Items = new List<BuyInfo>();
            // Configure items that the vendor will purchase back from players.
            Items.Add(new BuyInfo(typeof(WeaveCloth), 12));
            Items.Add(new BuyInfo(typeof(WeaveDye), 7));
            Items.Add(new BuyInfo(typeof(WeaveCarpet), 40));
        }
    }
}

public class SellInfo
{
    public Type ItemType { get; private set; }
    public int Cost { get; private set; }
    public int Quantity { get; private set; }
    public int Identifier { get; private set; }

    public SellInfo(Type itemType, int cost, int quantity, int identifier)
    {
        ItemType = itemType;
        Cost = cost;
        Quantity = quantity;
        Identifier = identifier;
    }
}

public class BuyInfo
{
    public Type ItemType { get; private set; }
    public int Price { get; private set; }

    public BuyInfo(Type itemType, int price)
    {
        ItemType = itemType;
        Price = price;
    }
}

