using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using AllReady.Features.Notifications;
using AllReady.Models;
using MediatR;
using Microsoft.EntityFrameworkCore;

public class MessageTaskVolunteersCommandHandlerAsync : AsyncRequestHandler<MessageTaskVolunteersCommand>
{
    private readonly AllReadyContext _context;
    private readonly IMediator _mediator;

    public MessageTaskVolunteersCommandHandlerAsync(AllReadyContext context, IMediator mediator)
    {
        _context = context;
        _mediator = mediator;
    }

    protected override async Task HandleCore(MessageTaskVolunteersCommand message)
    {
        var users = await _context.TaskSignups
            .Where(ts => ts.TaskId == message.TaskId)
            .Select(ts => ts.User)
            .ToListAsync();

        var smsRecipients = users
            .Where(u => u.PhoneNumberConfirmed)
            .Select(u => u.PhoneNumber)
            .ToList();

        var emailRecipients = users
            .Where(u => u.EmailConfirmed)
            .Select(u => u.Email)
            .ToList();

        var notifyCommand = new NotifyVolunteersCommand
        {
            SmsRecipients = smsRecipients,
            EmailRecipients = emailRecipients,
            Message = message.Message,
            Subject = message.Subject
        };

        await _mediator.SendAsync(notifyCommand);
    }
}

public class MessageTaskVolunteersCommand : IAsyncRequest
{
    public int TaskId { get; set; }
    public string Message { get; set; }
    public string Subject { get; set; }
}

