namespace ManualRevisionSystem
{
    internal sealed class Configuration : DbMigrationsConfiguration<ManualRevisionContext>
    {
        public Configuration()
        {
            AutomaticMigrationsEnabled = true;
            AutomaticMigrationDataLossAllowed = true;
        }

        protected override void Seed(ManualRevisionContext context)
        {
            // Seed FieldTypes
            AddOrUpdate(context, new FieldType { Id = 1, Name = "Text" });
            AddOrUpdate(context, new FieldType { Id = 2, Name = "Number" });
            AddOrUpdate(context, new FieldType { Id = 3, Name = "Date" });
            AddOrUpdate(context, new FieldType { Id = 4, Name = "Monetary" });

            // Seed Roles
            AddOrUpdate(context, new Role { Id = 1, Name = "Administrator" });
            AddOrUpdate(context, new Role { Id = 2, Name = "Operator" });

            // Seed Default Admin User
            var adminRole = context.Roles.Single(r => r.Name == "Administrator");
            AddOrUpdate(context, new User
            {
                Id = 1,
                Username = "admin",
                PasswordHash = "hashed_password_here", // Replace with actual hashed password
                RoleId = adminRole.Id
            });

            context.SaveChanges();
        }

        private void AddOrUpdate<TEntity>(ManualRevisionContext context, TEntity entity) where TEntity : class
        {
            var set = context.Set<TEntity>();
            var entry = set.Find(((dynamic)entity).Id);

            if (entry == null)
            {
                set.Add(entity);
            }
            else
            {
                context.Entry(entry).CurrentValues.SetValues(entity);
            }
        }
    }

    public class ManualRevisionContext : DbContext
    {
        public DbSet<FieldType> FieldTypes { get; set; }
