namespace Narcissistic_numbers
{
    class Tree
    {
        static void Main(string[] args)
        {
            var narcissists = Narcissists();
            int i = 0;
            foreach (var n in narcissists)
            {
                Console.Write(n + " ");
                i++;
                if (i % 5 == 0) Console.WriteLine();
                if (i == 25) break;
            }
            Console.WriteLine();
        }
 
        static IEnumerable<int> Narcissists()
        {
            for (int digits = 0; ; digits++)
            {
                var digitpowers = Enumerable.Range(0, 10).Select(i => (int)Math.Pow(i, digits)).ToArray();
                for (int n = (int)Math.Pow(10, digits - 1); n < Math.Pow(10, digits); n++)
                {
                    int div = n, digitpsum = 0;
                    while (div > 0)
                    {
                        div /= 10;
                        digitpsum += digitpowers[div % 10];
                    }
                    if (n == digitpsum) yield return n;
                }
            }
        }
    }
}

