public class ParkingRamp
{
    public List<ParkingFloor> Floors { get; private set; }
    public Queue<Vehicle> InQueue { get; private set; }
    public Queue<Vehicle> OutQueue { get; private set; }
    private int maxVehicles;

    public ParkingRamp(int numberOfFloors, int spotsPerFloor, int maxVehicles)
    {
        Floors = new List<ParkingFloor>();
        InQueue = new Queue<Vehicle>();
        OutQueue = new Queue<Vehicle>();
        this.maxVehicles = maxVehicles;

        for (int i = 0; i < numberOfFloors; i++)
        {
            Floors.Add(new ParkingFloor(spotsPerFloor));
        }
    }

    public void Tick()
    {
        // Process vehicles exiting the ramp
        ProcessExitingVehicles();

        // Attempt to allocate vehicles waiting in the InQueue to available spots
        ProcessEnteringVehicles();

        // Log current state
        Console.WriteLine($"Total Spots: {TotalLocations}, Open Spots: {OpenLocations}");
    }

    private void ProcessExitingVehicles()
    {
        while (OutQueue.Count > 0)
        {
            Vehicle vehicle = OutQueue.Dequeue();
            foreach (var floor in Floors)
            {
                if (floor.RemoveVehicle(vehicle))
                {
                    Console.WriteLine($"Vehicle {vehicle.Id} exited the ramp.");
                    break;
                }
            }
        }
    }

    private void ProcessEnteringVehicles()
    {
        while (InQueue.Count > 0 && ActiveVehicles < maxVehicles)
        {
            Vehicle vehicle = InQueue.Dequeue();
            foreach (var floor in Floors)
            {
                if (floor.AddVehicle(vehicle))
                {
                    Console.WriteLine($"Vehicle {vehicle.Id} parked on floor {floor.FloorNumber}.");
                    break;
                }
            }
        }
    }

    public int TotalLocations => Floors.Count * Floors[0].TotalSpots;

    public int OpenLocations
    {
        get
        {
            int totalOpen = 0;
            foreach (var floor in Floors)
            {
                totalOpen += floor.OpenSpots;
            }
            return totalOpen;
        }
    }

    private int ActiveVehicles
    {
        get
        {
            int activeCount = 0;
            foreach (var floor in Floors)
            {
                activeCount += floor.CurrentVehicles;
            }
            return activeCount;
        }
    }
}

