public partial class VerifyPhoneNumber : Page
{
    protected string PhoneNumber { get; set; }
    protected ApplicationUserManager UserManager { get; set; }
    protected ApplicationSignInManager SignInManager { get; set; }

    protected void Page_Load(object sender, EventArgs e)
    {
        UserManager = Context.GetOwinContext().GetUserManager<ApplicationUserManager>();
        SignInManager = Context.GetOwinContext().Get<ApplicationSignInManager>();

        if (!IsPostBack)
        {
            PhoneNumber = Request.QueryString["PhoneNumber"];
            if (string.IsNullOrEmpty(PhoneNumber))
            {
                ModelState.AddModelError("", "Invalid phone number.");
                return;
            }

            var code = UserManager.GenerateChangePhoneNumberToken(User.Identity.GetUserId(), PhoneNumber);
            Session["VerificationCode"] = code;
        }
    }

    protected void Code_Click(object sender, EventArgs e)
    {
        var code = Code.Text;
        var userId = User.Identity.GetUserId();
        var storedCode = Session["VerificationCode"] as string;

        if (string.IsNullOrEmpty(code) || string.IsNullOrEmpty(storedCode))
        {
            ModelState.AddModelError("", "Invalid verification code.");
            return;
        }

        var result = UserManager.ChangePhoneNumber(userId, PhoneNumber, code);
        if (result.Succeeded)
        {
            var user = UserManager.FindById(userId);
            if (user != null)
            {
                SignInManager.SignIn(user, isPersistent: false, rememberBrowser: false);
            }
            Response.Redirect("~/Manage?m=PhoneNumberVerificationSuccess");
        }
        else
        {
            ModelState.AddModelError("", "Failed to verify phone number.");
        }
    }
}

