namespace LastLetterFirstLetter
{
    class LastL_FirstL
    {
        private List<string> names;
        private Dictionary<char, List<string>> first;
        private List<List<string>> sequences;
 
        public LastL_FirstL(List<string> names)
        {
            this.names = names.ToList();
            this.first = names.GroupBy(name => name[0]).ToDictionary(group => group.Key, group => group.ToList());
            this.sequences = new List<List<string>>();
        }
 
        public void add_name(List<string> seq)
        {
            char last_letter = seq.Last().Last();
            List<string> potentials = this.first.ContainsKey(last_letter)? this.first[last_letter].Except(seq).ToList() : new List<string>();
            if (potentials.Count == 0)
            {
                this.sequences.Add(seq);
            }
            else
            {
                potentials.ForEach(name => add_name(seq.Concat(new List<string> { name }).ToList()));
            }
        }
 
        public void search()
        {
            this.names.ForEach(name => add_name(new List<string> { name }));
            int max = this.sequences.Max(seq => seq.Count);
            List<List<string>> max_seqs = this.sequences.Where(seq => seq.Count == max).ToList();
            Console.WriteLine("there are {0} possible sequences", this.sequences.Count);
            Console.WriteLine("the longest is {0} names long", max);
            Console.WriteLine("there are {0} such sequences. one is:", max_seqs.Count);
            max_seqs.Last().ForEach(name => Console.WriteLine("  {0} {1}", max_seqs.Last().IndexOf(name) + 1, name));
        }
    }
 
