namespace PackageManagementApp
{
    using MonoDevelop.PackageManagement;

    // Custom event arguments for package source validation events.
    public class PackageSourceValidationEventArgs : EventArgs
    {
        // The package source view model.
        public PackageSourceViewModel PackageSource { get; }

        // The optional error message from validation failure.
        public string ErrorMessage { get; }

        // Computed property to determine if the package source is valid.
        public bool IsValid => string.IsNullOrEmpty(ErrorMessage);

        // Constructor that accepts only the package source view model.
        public PackageSourceValidationEventArgs(PackageSourceViewModel packageSource)
            : this(packageSource, null)
        {
        }

        // Constructor that accepts both the package source view model and an error message.
        public PackageSourceValidationEventArgs(PackageSourceViewModel packageSource, string errorMessage)
        {
            PackageSource = packageSource;
            ErrorMessage = errorMessage;
        }
    }

    // Publisher class for package source validation events.
    public class PackageManager
    {
        // Event triggered after validating a package source.
        public event EventHandler<PackageSourceValidationEventArgs> OnPackageSourceValidated;

        // Method to validate a package source view model.
        public void ValidatePackageSource(PackageSourceViewModel viewModel)
        {
            string error = null;

            // Simple validation logic: the source URL must not be empty.
            if (string.IsNullOrWhiteSpace(viewModel.SourceUrl))
            {
                error = "Package source URL cannot be empty.";
            }

            // Create event args with the package source and validation result.
            var args = new PackageSourceValidationEventArgs(viewModel, error);

            // Trigger the event.
            OnPackageSourceValidated?.Invoke(this, args);
        }
    }

    // Subscriber class that handles package source validation events.
