using System;
using System.Diagnostics;
using System.Threading;
using ChakraCore.NET.API;

public class ContextSwitchService : IDisposable
{
    private readonly JavaScriptContext _context;
    private readonly EventWaitHandle _handle;
    private Thread _currentOwner;
    private int _reentrancyCount;

    public ContextSwitchService(JavaScriptContext context, EventWaitHandle handle)
    {
        _context = context;
        _handle = handle ?? throw new ArgumentNullException(nameof(handle));
    }

    public ContextSwitchService(JavaScriptContext context)
        : this(context, new EventWaitHandle(true, EventResetMode.AutoReset))
    {
    }

    private bool IsCurrentContext
    {
        get
        {
            JavaScriptContext currentContext;
            JsErrorCode error = JsGetCurrentContext(out currentContext);
            if (error != JsErrorCode.JsNoError)
                throw new InvalidOperationException($"Context check failed: {error}");
            return currentContext == _context;
        }
    }

    public void Enter()
    {
        if (_currentOwner == Thread.CurrentThread)
        {
            _reentrancyCount++;
            Debug.WriteLine($"Reentrant enter (Count: {_reentrancyCount})");
            return;
        }

        Debug.WriteLine($"Thread {Thread.CurrentThread.ManagedThreadId} waiting for context");
        _handle.WaitOne();
        _currentOwner = Thread.CurrentThread;
        _reentrancyCount = 1;
        Debug.WriteLine($"Thread {_currentOwner.ManagedThreadId} acquired context");

        if (!IsCurrentContext)
        {
            JavaScriptContext previousContext;
            JsErrorCode error = JsSetCurrentContext(_context, out previousContext);
            if (error != JsErrorCode.JsNoError)
                throw new InvalidOperationException($"Context switch failed: {error}");
            Debug.WriteLine($"Context switched to target context");
        }
    }

    public void Leave()
    {
        if (_currentOwner != Thread.CurrentThread)
            throw new InvalidOperationException("Thread doesn't own context");

        _reentrancyCount--;
        Debug.WriteLine($"Leave called (Remaining: {_reentrancyCount})");

        if (_reentrancyCount != 0) return;

        if (IsCurrentContext)
        {
            JsSetCurrentContext(JavaScriptContext.Invalid);
            Debug.WriteLine("Context reset");
        }

        _currentOwner = null;
        _handle.Set();
        Debug.WriteLine("Context released");
    }

    public void With(Action action)
    {
        Enter();
        try
        {

