namespace WpfApplication1
{
    /// <summary>
    /// Interaction logic for MainWindow.xaml
    /// </summary>
    public partial class MainWindow : Window
    {
        private string str;
        private DispatcherTimer timer;
        private Direction dir;
        public MainWindow()
        {
            InitializeComponent();
            str = "Hello World! ";
            dir = Direction.Right;
            timer = new DispatcherTimer();
            timer.Interval = new TimeSpan(0, 0, 0, 0, 125);
            timer.Tick += timer_Tick;
            timer.Start();
        }
 
        void timer_Tick(object sender, EventArgs e)
        {
            str = shift_char(str, dir);
            label1.Content = str;
        }
 
        private string shift_char(string str, Direction dir)
        {
            switch (dir)
            {
                case Direction.Right:
                    return str.Substring(str.Length - 1, 1) + str.Substring(0, str.Length - 1);
                case Direction.Left:
                    return str.Substring(1, str.Length - 1) + str.Substring(0, 1);
                default:
                    return str;
            }
        }
 
        private void label1_MouseLeftButtonDown(object sender, MouseButtonEventArgs e)
        {
            dir = dir == Direction.Right? Direction.Left : Direction.Right;
        }
 
        private enum Direction
        {
            Right,
            Left
        }
    }
}

