namespace EgyptianFractions
{
    class Library
    {
        public struct Pair
        {
            public long md;
            public int tc;
        }
 
        public static long mod(long x, long y)
        {
            return ((x % y) + y) % y;
        }
 
        public static long gcd(long a, long b)
        {
            if (0 == a) return b;
            if (0 == b) return a;
            if (a == b) return a;
            if (a > b) return gcd(a - b, b);
            return gcd(a, b - a);
        }
 
        public static void write0(bool show, string str)
        {
            if (show)
            {
                Console.Write(str);
            }
        }
 
        public static void write1(bool show, string format, long a)
        {
            if (show)
            {
                Console.Write(format, a);
            }
        }
 
        public static void write2(bool show, string format, long a, long b)
        {
            if (show)
            {
                Console.Write(format, a, b);
            }
        }
 
        public static Pair egyptian(long x, long y, bool show)
        {
            Pair ret;
            long acc = 0;
            bool first = true;
 
            ret.tc = 0;
            ret.md = 0;
 
            write2(show, "Egyptian fraction for {0}/{1}: ", x, y);
            while (x > 0)
            {
                long z = (y + x - 1) / x;
                if (z == 1)
                {
                    acc++;
                }
                else
                {
                    if (acc > 0)
                    {
                        write1(show, "{0} + ", acc);
                        first = false;
                        acc = 0;
                        ret.tc++;
                    }
                    else if (first)
                    {
                        first = false;
                    }
                    else
                    {
                        write0(show, " + ");
                    }
                    if (z > ret.md)
                    {
                        ret.md = z;
                    }
                    write1(show, "1/{0}", z);
                    ret.tc++;
                }
                x = mod(-y, x);
                y = y * z;
            }
            if (acc > 0)
            {
                write1(show, "{0}", acc);
                ret.tc++;
            }
            write0(show, "\n");
 
            return ret;
        }

