{
    /// <summary>
    /// Custom exception representing multiple assertion failures in a test scenario
    /// </summary>
    [Serializable]
    public class MultipleAssertException : Exception
    {
        /// <summary>
        /// Gets the test result associated with the assertion failures
        /// </summary>
        public ITestResult? TestResult { get; }

        /// <summary>
        /// Gets the result state of the test failure
        /// </summary>
        public ResultState ResultState { get; }

        /// <summary>
        /// Creates a new instance of MultipleAssertException with a specific test result
        /// </summary>
        /// <param name="testResult">The test result representing the multiple failures</param>
        public MultipleAssertException(ITestResult testResult)
            : base(CreateExceptionMessage(testResult))
        {
            TestResult = testResult ?? throw new ArgumentNullException(nameof(testResult));
            ResultState = testResult.ResultState ?? ResultState.Failure;
        }

        /// <summary>
        /// Creates a new instance of MultipleAssertException with a custom message
        /// </summary>
        /// <param name="message">Custom error message describing the failures</param>
        /// <param name="testResult">The test result associated with the failures</param>
        public MultipleAssertException(string message, ITestResult? testResult = null)
            : base(message)
        {
            TestResult = testResult;
            ResultState = testResult?.ResultState ?? ResultState.Failure;
        }

        /// <summary>
        /// Serialization constructor for supporting exception serialization
        /// </summary>
        /// <param name="info">Serialization information</param>
        /// <param name="context">Streaming context</param>
        protected MultipleAssertException(SerializationInfo info, StreamingContext context)
            : base(info, context)
        {
            TestResult = info.GetValue(nameof(TestResult), typeof(ITestResult)) as ITestResult;
            ResultState = (ResultState)(info.GetValue(nameof(ResultState), typeof(ResultState)) ?? ResultState.Failure);
        }

