            Console.WriteLine("\nOrdinal ranking:");
            foreach (var rank in OrdinalRanking(scores))
            {
                Console.WriteLine("  {0}, {1}", rank.Item1, rank.Item2);
            }
 
            Console.WriteLine("\nFractional ranking:");
            foreach (var rank in FractionalRanking(scores))
            {
                Console.WriteLine("  {0}, {1}", rank.Item1, rank.Item2);
            }
 
            Console.ReadKey();
        }
 
