using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace NegativeBase
{
    class Shape
    {
        static string DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
 
        static string encodeNegativeBase(long n, int b)
        {
            if (b < -62 || b > -1)
            {
                throw new Exception("Argument out of range: b");
            }
            if (n == 0)
            {
                return "0";
            }
 
            string output = "";
            long nn = n;
            while (nn!= 0)
            {
                int rem = (int)(nn % b);
                nn /= b;
                if (rem < 0)
                {
                    nn++;
                    rem -= b;
                }
                output += DIGITS[rem];
            }
 
            char[] charArray = output.ToCharArray();
            Array.Reverse(charArray);
            return new string(charArray);
        }
 
        static long decodeNegativeBase(string ns, int b)
        {
            if (b < -62 || b > -1)
            {
                throw new Exception("Argument out of range: b");
            }
            if (ns == "0")
            {
                return 0;
            }
 
            long total = 0;
            long bb = 1;
 
            for (int i = ns.Length - 1; i >= 0; i--)
            {
                int idx = DIGITS.IndexOf(ns[i]);
                if (idx!= -1)
                {
                    total += idx * bb;
                }
                bb *= b;
            }
            return total;
        }
 
        static void Main(string[] args)
        {
            List<Tuple<long, int>> nbl = new List<Tuple<long, int>>();
            nbl.Add(new Tuple<long, int>(10, -2));
            nbl.Add(new Tuple<long, int>(146, -3));
            nbl.Add(new Tuple<long, int>(15, -10));
            nbl.Add(new Tuple<long, int>(142961, -62));
 
            foreach (var p in nbl)
            {
                string ns = encodeNegativeBase(p.Item1, p.Item2);
                Console.WriteLine("{0,12} encoded in base {1,3} = {2}", p.Item1, p.Item2, ns);
 
                long n = decodeNegativeBase(ns, p.Item2);
                Console.WriteLine("{0,12} decoded in base {1,3} = {2}", ns, p.Item2, n);
 
                Console.WriteLine();
            }
 
            Console.ReadLine();
        }
    }
}

