using System;
using System.ComponentModel;
using SharpGL.SceneGraph.Core;
using SharpGL.SceneGraph.Lighting;

namespace SharpGL.SceneGraph.Cameras
{
    /// <summary>
    /// The ArcBall camera supports arcball projection, making it ideal for use with a mouse.
    /// </summary>
    [Serializable()]
    public class ArcBallCamera : PerspectiveCamera
    {
        /// <summary>
        /// Initializes a new instance of the <see cref="PerspectiveCamera"/> class.
        /// </summary>
        public ArcBallCamera()
        {
            Name = "Camera (ArcBall)";
        }

        /// <summary>
        /// This is the class' main function, to override this function and perform a
        /// perspective transformation.
        /// </summary>
        public override void TransformProjectionMatrix(OpenGL gl)
        {
            int[] viewport = new int[4];
            gl.GetInteger(OpenGL.GL_VIEWPORT, viewport);

            //  Perform the perspective transformation.
            arcBall.SetBounds(viewport[2], viewport[3]);
            gl.Perspective(FieldOfView, AspectRatio, Near, Far);
            Vertex target = new Vertex(0, 0, 0);
            Vertex upVector = new Vertex(0, 0, 1);

            //  Perform the look at transformation.
            gl.LookAt((double)Position.X, (double)Position.Y, (double)Position.Z,
                (double)target.X, (double)target.Y, (double)target.Z,
                (double)upVector.X, (double)upVector.Y, (double)upVector.Z);

            arcBall.TransformMatrix(gl);
        }

        /// <summary>
        /// The arcball used for rotating.
        /// </summary>
        private ArcBall arcBall = new ArcBall();

        /// <summary>
        /// Gets the arc ball.
        /// </summary>
        public ArcBall ArcBall
        {
            get { return arcBall; }
        }
    }
}

using UnityEngine;
using UnityEngine.UI;
using Bhaptics.Tact;
using Bhaptics.Tact.Unity;

public class BhapticsIsConnectIsPlayingExample : MonoBehaviour
{
    public FileHapticClip[] clips;
    public Text isConnectText;
    public Text clipText;
    public Text isPlayingText;

    void Start()
    {
        InitializeClipDisplay();
        InvokeRepeating(nameof(PlayClips), 0f, 2f);
    }

    void Update()
    {
        UpdateDeviceStatus();
        UpdateClipStates();
    }

    void InitializeClipDisplay()
    {
        System.Text.StringBuilder sb = new System.Text.StringBuilder();
        foreach (var clip in clips)
        {
            sb.AppendLine(clip.Name);
        }
        clipText.text = sb.ToString();
    }

    void UpdateDeviceStatus()
    {
        System.Text.StringBuilder sb = new System.Text.StringBuilder();

        var deviceChecks = new (string label, HapticDeviceType[] types)[]
        {
            ("Headset", new[] { HapticDeviceType.Head }),
            ("Suit", new[] { HapticDeviceType.Vest }),
            ("Arms", new[] { HapticDeviceType.ArmLeft, HapticDeviceType.ArmRight }),
            ("Hands", new[] { HapticDeviceType.HandLeft, HapticDeviceType.HandRight }),
            ("Feet", new[] { HapticDeviceType.FootLeft, HapticDeviceType.FootRight })
        };

        foreach (var device in deviceChecks)
        {
            if (device.types.Length == 1)
            {
                bool connected = BhapticsManager.IsDeviceConnected(device.types[0]);
                sb.AppendLine($"{device.label}: {(connected ? "Connected" : "Disconnected")}");
            }
            else
            {
                bool left = BhapticsManager.IsDeviceConnected(device.types[0]);
                bool right = BhapticsManager.IsDeviceConnected(device.types[1]);
                sb.AppendLine($"{device.label}: L-{(left ? "OK" : "X")} R-{(right ? "OK" : "X")}");
            }
        }

        isConnectText.text = sb.ToString();
    }

    void UpdateClipStates()
    {
        System.Text.StringBuilder sb = new System.Text.StringBuilder();
        foreach (var clip in clips)
        {
            sb.AppendLine(clip.IsPlaying ? $"<color=green>{clip.Name}: ACTIVE</color>" : $"<color=red>{clip.Name}: idle</color>");
        }
        isPlayingText.text = sb.ToString();
    }

    void PlayClips()
    {
        foreach (var clip in clips)
        {
            if (!clip.IsPlaying)
            {
                clip.Play();
            }
        }
    }
}

