using System;
using FluentAssertions;
using Microsoft.Common.Core.Disposables;
using Microsoft.UnitTests.Core.XUnit;
using Xunit;

public class CountdownDisposableTests
{
    [Fact]
    public void CountdownDisposable_CallbackIsInvokedOnlyOnce()
    {
        int callCount = 0;
        Action callback = () => callCount++;

        var disposable = new CountdownDisposable(callback);

        // Increment the counter a few times
        IDisposable increment1 = disposable.Increment();
        IDisposable increment2 = disposable.Increment();
        IDisposable increment3 = disposable.Increment();

        // Dispose one of the increments - callback shouldn't be called yet
        increment1.Dispose();
        callCount.Should().Be(0);

        // Dispose another - still no callback
        increment2.Dispose();
        callCount.Should().Be(0);

        // Dispose the last one - callback should now be called
        increment3.Dispose();
        callCount.Should().Be(1);

        // Dispose the main disposable - callback shouldn't be called again
        disposable.Dispose();
        callCount.Should().Be(1);
    }

    [Fact]
    public void CountdownDisposable_CallbackIsInvokedImmediatelyIfCounterIsZero()
    {
        int callCount = 0;
        Action callback = () => callCount++;

        var disposable = new CountdownDisposable(callback);

        disposable.Dispose();

        callCount.Should().Be(1);
    }
}

