public class Helper
{
    public static void Main()
    {
        Console.WriteLine(CountJewels("aAAbbbb", "aA"));
        Console.WriteLine(CountJewels("ZZ", "z"));
    }
 
    public static int CountJewels(string stones, string jewels)
    {
        int count = 0;
        foreach (var curChar in stones)
        {
            if (jewels.Contains(curChar))
            {
                count++;
            }
        }
        return count;
    }
