        private IMongoDatabase _database;

        [SetUp]
        public async Task Setup()
        {
            var client = new MongoClient("mongodb://localhost:27017");
            _database = client.GetDatabase("TestDatabase");
            _collection = _database.GetCollection<Project>("Projects");
            _repository = new ProjectRepository(_collection);

            // Prepare test data
            var testProjects = new List<Project>
            {
                new Project { Id = Guid.NewGuid(), Name = "Project A", Status = "Active" },
                new Project { Id = Guid.NewGuid(), Name = "Project B", Status = "Inactive" },
                new Project { Id = Guid.NewGuid(), Name = "Project C", Status = "Active" }
            };

            await _collection.InsertManyAsync(testProjects);
        }

        [Test]
        public async Task BulkDelete_ByLambdaExpression_ShouldDeleteMatchingDocuments()
        {
            // Arrange
            var activeProjectsFilter = Builders<Project>.Filter.Eq(p => p.Status, "Active");

            // Act
            var deleteResult = await _repository.DeleteManyAsync(activeProjectsFilter);

            // Assert
            Assert.AreEqual(2, deleteResult.DeletedCount);
        }

        [Test]
        public async Task BulkDelete_WithNoMatchingDocuments_ShouldReturnZeroDeletions()
        {
            // Arrange
            var nonExistentFilter = Builders<Project>.Filter.Eq(p => p.Name, "Non-Existent Project");

            // Act
            var deleteResult = await _repository.DeleteManyAsync(nonExistentFilter);

            // Assert
            Assert.AreEqual(0, deleteResult.DeletedCount);
        }

        [TearDown]
        public async Task CleanUp()
        {
            await _collection.DeleteManyAsync(FilterDefinition<Project>.Empty);
        }
    }

