        public MessageContext(Guid messageId, string payload)
        {
            MessageId = messageId;
            Payload = payload;
        }
    }

    // Interface for a duplex transport mechanism
    public interface IDuplexTransport
    {
        void Receive(Action<MessageContext> onMessageReceived);
        void Send(MessageContext context);
    }

    // Factory to retrieve a duplex transport based on destination URI
    public static class TransportFactory
    {
        public static IDuplexTransport GetDuplexTransport(Uri destination)
        {
            return new DummyDuplexTransport(destination);
        }
    }

    // Dummy implementation simulating sending and receiving messages
    public class DummyDuplexTransport : IDuplexTransport
    {
        private readonly Uri _destination;
        private int _counter = 0;

        public DummyDuplexTransport(Uri destination)
        {
            _destination = destination;
        }

        // Simulate receiving a message with a delay then invoking the callback
        public void Receive(Action<MessageContext> onMessageReceived)
        {
            // Simulate asynchronous wait for a message
            Thread.Sleep(100);
            _counter++;
            var messageId = Guid.NewGuid();
            var context = new MessageContext(messageId, $"Payload {_counter}");
            onMessageReceived(context);
        }

        // Simulate sending a message by logging the action
        public void Send(MessageContext context)
        {
            Console.WriteLine($"[Transport] Sent message {context.MessageId} to {_destination}");
        }
    }

