namespace Microsoft.Azure.Management.NotificationHubs.Models
{
    /// <summary>
    /// Represents MPNS credentials for Azure Notification Hubs authentication
    /// </summary>
    public class MpnsCredential
    {
        /// <summary>
        /// Initializes a new instance with empty credentials
        /// </summary>
        public MpnsCredential() { }

        /// <summary>
        /// Initializes a new instance with specified parameters
        /// </summary>
        /// <param name="mpnsCertificate">Base64-encoded certificate data</param>
        /// <param name="certificateKey">Certificate private key material</param>
        /// <param name="thumbprint">Certificate SHA-1 thumbprint</param>
        public MpnsCredential(string mpnsCertificate = null, string certificateKey = null, string thumbprint = null)
        {
            MpnsCertificate = mpnsCertificate;
            CertificateKey = certificateKey;
            Thumbprint = thumbprint;
        }

        /// <summary>
        /// MPNS authentication certificate (Base64 encoded)
        /// </summary>
        [JsonProperty(PropertyName = "properties.mpnsCertificate")]
        public string MpnsCertificate { get; set; }

        /// <summary>
        /// Private key for the certificate
        /// </summary>
        [JsonProperty(PropertyName = "properties.certificateKey")]
        public string CertificateKey { get; set; }

        /// <summary>
        /// Certificate thumbprint for verification
        /// </summary>
        [JsonProperty(PropertyName = "properties.thumbprint")]
        public string Thumbprint { get; set; }

        /// <summary>
        /// Validates credential completeness
        /// </summary>
        /// <exception cref="ValidationException">
        /// Thrown when required fields are missing
        /// </exception>
        public virtual void Validate()
        {
            if (string.IsNullOrWhiteSpace(MpnsCertificate))
                throw new ValidationException(ValidationRules.CannotBeNull, "MpnsCertificate");

            if (string.IsNullOrWhiteSpace(CertificateKey))
                throw new ValidationException(ValidationRules.CannotBeNull, "CertificateKey");

            if (string.IsNullOrWhiteSpace(Thumbprint))
                throw new ValidationException(ValidationRules.CannotBeNull, "Thumbprint");

            if (Thumbprint.Length != 40)
                throw new ValidationException(ValidationRules.Pattern, "Thumbprint", "Must be 40-character SHA-1 hash");
        }
    }
}

