namespace ConfigParserTests
{
    public class Configuration
    {
        public List<Job> Jobs { get; } = new List<Job>();
        public List<object> Exporters { get; } = new List<object>();

        public IEnumerable<Job> GetJobs() => Jobs;
        public IEnumerable<object> GetExporters() => Exporters;
        // Other providers (ColumnProviders, Diagnosers, Analysers, Loggers) can be added here if needed.
    }

    public static class ConfigParser
    {
        public static Configuration Parse(string[] args)
        {
            var config = new Configuration();
            foreach (var arg in args)
            {
                // Remove any leading dashes and split by '='
                var keyValue = arg.TrimStart('-').Split(new[] { '=' }, StringSplitOptions.RemoveEmptyEntries);
                if (keyValue.Length != 2)
                    throw new ArgumentException($"Invalid argument format: {arg}");

                var key = keyValue[0].ToLowerInvariant();
                var value = keyValue[1].ToLowerInvariant();
                switch (key)
                {
                    case "job":
                        if (value == "dry")
                            config.Jobs.Add(Job.Dry);
                        else
                            throw new ArgumentException("Unknown job value: " + value);
                        break;

                    case "exporter":
                        if (value == "html")
                            config.Exporters.Add(HtmlExporter.Default);
                        else if (value == "rplot")
                            config.Exporters.Add(RPlotExporter.Default);
                        else
                            throw new ArgumentException("Unknown exporter value: " + value);
                        break;

                    default:
                        throw new ArgumentException("Unrecognized parameter: " + key);
                }
            }
            return config;
        }
    }

    public class ConfigParserUnitTests
    {
        [Fact]
        public void ValidConfigurationTest()
        {
            string[] args = { "--job=dry", "--exporter=html" };
            var config = ConfigParser.Parse(args);
            Assert.Single(config.GetJobs());
            Assert.Single(config.GetExporters());
        }

