using Microsoft.Practices.ObjectBuilder2;
using Microsoft.Practices.Unity.InterceptionExtension;

public class ExtendedTypeInterceptionStrategy : BuilderStrategy
{
    private readonly ExtendedInterception _interception;

    public ExtendedTypeInterceptionStrategy(ExtendedInterception interception)
    {
        _interception = interception;
    }

    public override void PreBuildUp(IBuilderContext context)
    {
        var typeToBuild = context.BuildKey.Type;
        var interceptionPolicy = GetInterceptionPolicy(context);

        if (interceptionPolicy != null && _interception.CanIntercept(typeToBuild))
        {
            ConfigureInterceptor(context, interceptionPolicy);
        }
        else
        {
            ApplyDefaultInterceptor(context);
        }
    }

    private ITypeInterceptionPolicy GetInterceptionPolicy(IBuilderContext context)
    {
        return context.Policies.Get<ITypeInterceptionPolicy>(context.BuildKey);
    }

    private void ConfigureInterceptor(IBuilderContext context, ITypeInterceptionPolicy policy)
    {
        var interceptor = policy.CreateInterceptor(context.BuildKey.Type);
        context.Existing = _interception.CreateProxy(context.BuildKey.Type, context.Existing, interceptor);
    }

    private void ApplyDefaultInterceptor(IBuilderContext context)
    {
        if (_interception.CanIntercept(context.BuildKey.Type))
        {
            var defaultInterceptor = _interception.CreateDefaultInterceptor(context.BuildKey.Type);
            context.Existing = _interception.CreateProxy(context.BuildKey.Type, context.Existing, defaultInterceptor);
        }
    }
}

