namespace GlobalizationTests
{
    public class NumberFormatInfoCurrencyPositivePatternTests
    {
        [Fact]
        public void TestDefault()
        {
            var nfi = new NumberFormatInfo();
            Assert.Equal(0, nfi.CurrencyPositivePattern);
        }

        [Theory]
        [InlineData(0)]
        [InlineData(1)]
        [InlineData(2)]
        [InlineData(3)]
        public void TestSetValue(int pattern)
        {
            var nfi = new NumberFormatInfo();
            nfi.CurrencyPositivePattern = pattern;
            Assert.Equal(pattern, nfi.CurrencyPositivePattern);
        }

        [Fact]
        public void NegTest1()
        {
            var nfi = new NumberFormatInfo();
            Assert.Throws<ArgumentOutOfRangeException>(() =>
            {
                nfi.CurrencyPositivePattern = -1;
            });
        }

        [Fact]
        public void NegTest2()
        {
            var nfi = new NumberFormatInfo();
            Assert.Throws<ArgumentOutOfRangeException>(() =>
            {
                nfi.CurrencyPositivePattern = 4;
            });
        }

        [Fact]
        public void ReadOnlyInstanceTest()
        {
            var nfi = NumberFormatInfo.ReadOnly(new NumberFormatInfo());
            Assert.Throws<InvalidOperationException>(() =>
            {
                nfi.CurrencyPositivePattern = 1;
            });
        }

        [Fact]
        public void VerificationHelper()
        {
            var cultures = new[]
            {
                new CultureInfo("en-US"),
                new CultureInfo("fr-FR"),
                new CultureInfo("de-DE")
            };

            foreach (var culture in cultures)
            {
                var nfi = culture.NumberFormat;
                Assert.True(nfi.CurrencyPositivePattern >= 0 && nfi.CurrencyPositivePattern <= 3,
                    $"Invalid pattern for {culture.Name}");
            }
        }

        [Theory]
        [InlineData(0, "$n")]
        [InlineData(1, "n$")]
        [InlineData(2, "$ n")]
        [InlineData(3, "n $")]
        public void PatternFormatVerification(int pattern, string expectedFormat)
        {
            var nfi = new NumberFormatInfo();
            nfi.CurrencyPositivePattern = pattern;

            var result = string.Format(nfi, "{0:C}", 123.45m);
            Assert.Contains(expectedFormat.Replace("n", "123.45"), result);
        }
    }
}

