    public class propertyTypePicker : WebControl, IMacroGuiRendering
    {
        private string _value = string.Empty;
        private bool _multiple;
        private ListBox _listControl;

        public bool Multiple
        {
            get => _multiple;
            set => _multiple = value;
        }

        public string Value
        {
            get => string.Join(",", GetSelectedValues());
            set
            {
                _value = value ?? string.Empty;
                if (_listControl != null)
                    RestoreSelections();
            }
        }

        protected override void OnInit(EventArgs e)
        {
            base.OnInit(e);
            InitializeControl();
            PopulatePropertyTypes();
            ApplySavedSelections();
        }

        private void InitializeControl()
        {
            _listControl = new ListBox
            {
                ID = "PropertyTypeList",
                SelectionMode = _multiple ? ListSelectionMode.Multiple : ListSelectionMode.Single,
                CssClass = "umb-editor",
                Rows = 8
            };
            Controls.Add(_listControl);
        }

        private void PopulatePropertyTypes()
        {
            var uniqueProperties = new Dictionary<string, PropertyType>();
            IContentTypeService contentTypeService = ApplicationContext.Current.Services.ContentTypeService;

            foreach (IContentType contentType in contentTypeService.GetAllContentTypes())
            {
                foreach (PropertyType propType in contentType.PropertyTypes)
                {
                    if (!uniqueProperties.ContainsKey(propType.Alias))
                    {
                        uniqueProperties.Add(propType.Alias, propType);
                    }
                }
            }

            foreach (var propType in uniqueProperties.Values.OrderBy(p => p.Name))
            {
                _listControl.Items.Add(new ListItem($"{propType.Name} ({propType.Alias})", propType.Alias));
            }
        }

        private void ApplySavedSelections()
        {
            if (string.IsNullOrEmpty(_value)) return;

            foreach (string val in _value.Split(','))
            {
                ListItem item = _listControl.Items.FindByValue(val.Trim());
                if (item != null) item.Selected = true;
            }

using DesignPatterns.Factory;
using DesignPatterns.Iterator;
using System;

namespace DesignPatterns
{
    class Processor
    {
        static void Main(string[] args)
        {
            //Change this value to mimic the behaviour of the corresponding pattern.
            int designPat = 3;
            switch (designPat)
            {
                case 1:
                    Console.WriteLine("Singleton Pattern");
                    Singleton.Singleton.InstanceVar.Foo();
                    Singleton.Singleton.InstanceVar.Foo();
                    break;
                case 2:
                    Console.WriteLine("Iterator Pattern");
                    Person[] pArr = new Person[3]
                    {
                        new Person("John", "Doe"),
                        new Person("Will", "Smith"),
                        new Person("Wild", "Cats"),
                    };
                    People pList = new People(pArr);
                    foreach (Person p in pList)
                    {
                        Console.WriteLine("{0} {1}", p.FName, p.lName);
                    }
                    break;
                case 3:
                    Console.WriteLine("Factory Pattern");
                    //val = 1 for rocket ship and 2 for space ship
                    int val = 2;
                    ShipFactory factoryObj = new ShipFactory();
                    Ship shipType = null;
                    //Create ship object
                    shipType = factoryObj.MakeShip(val);
                    //To display the type of ship and it's speed
                    shipType.ShipStatus();
                    break;
                default:
                    break;

            }

            Console.ReadKey();
        }
    }
}

