namespace KitchenSimulation
{
    public interface IVegetable
    {
        bool IsPeeled { get; set; }
        bool IsCut { get; set; }
        void Peel();
        void Cut();
    }

    public class Potato : IVegetable
    {
        public bool IsPeeled { get; set; }
        public bool IsCut { get; set; }

        public void Peel()
        {
            IsPeeled = true;
            Console.WriteLine("Peeling a potato.");
        }

        public void Cut()
        {
            IsCut = true;
            Console.WriteLine("Cutting a potato.");
        }
    }

    public class Carrot : IVegetable
    {
        public bool IsPeeled { get; set; }
        public bool IsCut { get; set; }

        public void Peel()
        {
            IsPeeled = true;
            Console.WriteLine("Peeling a carrot.");
        }

        public void Cut()
        {
            IsCut = true;
            Console.WriteLine("Cutting a carrot.");
        }
    }

    public static class Factory
    {
        public static IVegetable CreateVegetable(string type)
        {
            switch (type.ToLower())
            {
                case "potato":
                    return new Potato();
                case "carrot":
                    return new Carrot();
                default:
                    throw new ArgumentException("Invalid vegetable type.");
            }
        }
    }

    public class Bowl
    {
        private List<IVegetable> Ingredients { get; } = new List<IVegetable>();

        public void Add(IVegetable vegetable)
        {
            Ingredients.Add(vegetable);
            Console.WriteLine("Vegetable added to bowl.");
        }
    }

    public class Kitchen
    {
        private readonly Bowl _bowl = new Bowl();

        public void Cook()
        {
            IVegetable potato = Factory.CreateVegetable("potato");
            IVegetable carrot = Factory.CreateVegetable("carrot");

            ProcessVegetable(potato);
            ProcessVegetable(carrot);
        }

        private void ProcessVegetable(IVegetable vegetable)
        {
            vegetable.Peel();
            vegetable.Cut();
            _bowl.Add(vegetable);
        }

        public Bowl GetBowl()
        {
            return _bowl;
        }
    }

    public class Library
    {
        public static void Main(string[] args)
        {
            Kitchen kitchen = new Kitchen();
            kitchen.Cook();
            Console.WriteLine("Vegetables prepared and stored in bowl.");
        }
    }
}

