using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Threading;
using System.Windows.Forms;
 
namespace ForestFire
{
    class Cache : Form
    {
        private static readonly Random rand = new Random();
        private Bitmap img;
 
        public Cache(int w, int h, int f, int p)
        {
            Size = new Size(w, h);
            StartPosition = FormStartPosition.CenterScreen;
 
            Thread t = new Thread(() => fire(f, p));
            t.Start();
 
            FormClosing += (object sender, FormClosingEventArgs e) => { t.Abort(); t = null; };
        }
 
        private void fire(int f, int p)
        {
            int clientWidth = ClientRectangle.Width;
            int clientHeight = ClientRectangle.Height;
            int cellSize = 10;
 
            img = new Bitmap(clientWidth, clientHeight);
            Graphics g = Graphics.FromImage(img);
 
            CellState[,] state = InitializeForestFire(clientWidth, clientHeight);
 
            uint generation = 0;
 
            do
            {
                g.FillRectangle(Brushes.White, 0, 0, img.Width, img.Height);
                state = StepForestFire(state, f, p);
 
                for (int y = 0; y < clientHeight - cellSize; y += cellSize)
                {
                    for (int x = 0; x < clientWidth - cellSize; x += cellSize)
                    {
                        switch (state[y, x])
                        {
                            case CellState.Empty:
                                break;
                            case CellState.Tree:
                                g.FillRectangle(Brushes.DarkGreen, x, y, cellSize, cellSize);
                                break;
                            case CellState.Burning:
                                g.FillRectangle(Brushes.DarkRed, x, y, cellSize, cellSize);
                                break;
                        }
                    }
                }
 
                Thread.Sleep(500);
 
                Invoke((MethodInvoker)Refresh);
 
            } while (generation < uint.MaxValue);
 
            g.Dispose();
        }
 
        private CellState[,] InitializeForestFire(int width, int height)
        {
            // Create our state array, initialize all indices as Empty, and return it.
            var state = new CellState[height, width];
            state.Initialize();
            return state;
        }
 
        private enum CellState : byte
        {
            Empty = 0,
            Tree = 1,
            Burning = 2
        }

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace WieferichPrimes
{
    class Validator
    {
        static bool[] PRIMES = new bool[5000];
        static void Main(string[] args)
        {
            prime_sieve();
            Console.WriteLine("Wieferich primes less than 5000:");
            wieferich_primes();
            Console.ReadLine();
        }
        static void prime_sieve()
        {
            uint p;
            int i;
 
            PRIMES[0] = false;
            PRIMES[1] = false;
            for (i = 2; i < 5000; i++)
            {
                PRIMES[i] = true;
            }
 
            for (i = 4; i < 5000; i += 2)
            {
                PRIMES[i] = false;
            }
 
            for (p = 3; ; p += 2)
            {
                uint q = p * p;
                if (q >= 5000)
                {
                    break;
                }
                if (PRIMES[p])
                {
                    uint inc = 2 * p;
                    for (; q < 5000; q += inc)
                    {
                        PRIMES[q] = false;
                    }
                }
            }
        }
 
        static uint modpow(uint base1, uint exp, uint mod)
        {
            uint result = 1;
 
            if (mod == 1)
            {
                return 0;
            }
 
            base1 %= mod;
            for (; exp > 0; exp >>= 1)
            {
                if ((exp & 1) == 1)
                {
                    result = (result * base1) % mod;
                }
                base1 = (base1 * base1) % mod;
            }
            return result;
        }
 
        static void wieferich_primes()
        {
            uint p;
 
            for (p = 2; p < 5000; ++p)
            {
                if (PRIMES[p] && modpow(2, p - 1, p * p) == 1)
                {
                    Console.WriteLine(p);
                }
            }
        }
    }
}

