namespace Fable
{
    public class EdgeHost
    {
        private static readonly ConcurrentDictionary<string, IFable> Fables = new ConcurrentDictionary<string, IFable>();
        private static readonly ConcurrentDictionary<string, IDisposable> Subscribtions = new ConcurrentDictionary<string, IDisposable>();

        public static void AddFable(string name, IFable fable)
        {
           if(Fables.TryAdd(name, fable) == false)
                throw new ArgumentException("Failed to add a fable to edge host. Fable with given name already exists.");
        }

        public static bool RemoveFable(string name)
        {
            IFable fable;
            return Fables.TryRemove(name, out fable);
        }

        public Task<object> SubscribeTopic(dynamic payload)
        {
            var id = (string)payload.id;
            if (string.IsNullOrEmpty(id))
                throw new ArgumentNullException(nameof(id));

            var sub = Subscribtions.GetOrAdd(id, i => SubscribeTopicPrivate(payload));

            return Task.FromResult<object>(null);
        }

        public Task<object> UnsubscribeTopic(dynamic id)
        {
            IDisposable sub;
            Subscribtions.TryRemove(id, out sub);

            sub.Dispose();

            return Task.FromResult<object>(null);
        }

        private static IDisposable SubscribeTopicPrivate(dynamic payload)
        {
            IFable fable;
            if (!Fables.TryGetValue(payload.fable, out fable))
                throw new ArgumentException(string.Format("Fable {0} was not found", payload.fable));

            var topic = fable.Topic((string)payload.topic);
            var sink = new EdgeEventSink((Func<object, Task<object>>)payload.sink);

            topic.Subscribe(sink);

            (topic as IStatefulTopic)?.ReplayState(sink);

            return new EdgeSubscribtion(topic, sink);
        }
    }
}

public static class CherylsBirthday
{
    public static void Main() {
        var dates = new HashSet<(string month, int day)> {
            ("May", 15),
            ("May", 16),
            ("May", 19),
            ("June", 17),
            ("June", 18),
            ("July", 14),
            ("July", 16),
            ("August", 14),
            ("August", 15),
            ("August", 17)
        };
 
        Console.WriteLine(dates.Count + " remaining.");
        //The month cannot have a unique day.
        var monthsWithUniqueDays = dates.GroupBy(d => d.day).Where(g => g.Count() == 1).Select(g => g.First().month).ToHashSet();
        dates.RemoveWhere(d => monthsWithUniqueDays.Contains(d.month));
        Console.WriteLine(dates.Count + " remaining.");
        //The day must now be unique.
        dates.IntersectWith(dates.GroupBy(d => d.day).Where(g => g.Count() == 1).Select(g => g.First()));
        Console.WriteLine(dates.Count + " remaining.");
        //The month must now be unique.
        dates.IntersectWith(dates.GroupBy(d => d.month).Where(g => g.Count() == 1).Select(g => g.First()));
        Console.WriteLine(dates.Single());
    }
 
}

