public class IgnoreOnceQuickFix
{
    private string _annotationText;
    private string _inspectionName;
    private IList<string> _codeLines;
    private int _lineIndex;

    public IgnoreOnceQuickFix(string inspectionName, IList<string> codeLines, int lineIndex)
    {
        _inspectionName = inspectionName;
        _codeLines = codeLines;
        _lineIndex = lineIndex;
        _annotationText = $"' Ignore for inspection: {_inspectionName}";
    }

    public void Fix()
    {
        if (_lineIndex > 0 && HasExistingAnnotation())
        {
            UpdateExistingAnnotation();
        }
        else
        {
            InsertNewAnnotation();
        }
    }

    private bool HasExistingAnnotation()
    {
        var previousLine = _codeLines[_lineIndex - 1].Trim();
        return previousLine.StartsWith("' Ignore for inspection:");
    }

    private void UpdateExistingAnnotation()
    {
        var previousLine = _codeLines[_lineIndex - 1].Trim();
        var updatedLine = previousLine + ", " + _inspectionName;
        _codeLines[_lineIndex - 1] = updatedLine;
        Console.WriteLine($"Updated annotation: {updatedLine}");
    }

    private void InsertNewAnnotation()
    {
        _codeLines.Insert(_lineIndex, _annotationText);
        Console.WriteLine($"Inserted annotation: {_annotationText}");
    }
}

