namespace DynamicEntityMapperDiscovery
{
    // Interface representing an entity mapper.
    public interface IEntityMapper
    {
        void MapEntity(object entity);
    }

    // Generalized assembly finder interface to retrieve available assemblies.
    public interface IAssemblyFinder
    {
        IEnumerable<Assembly> GetAssemblies();
    }

    // A simple implementation of IAssemblyFinder using the current AppDomain.
    public class DefaultAssemblyFinder : IAssemblyFinder
    {
        public IEnumerable<Assembly> GetAssemblies()
        {
            // Retrieves all assemblies loaded in the current application domain.
            return AppDomain.CurrentDomain.GetAssemblies();
        }
    }

    // Interface defining contract for finding assemblies that contain entity mapper implementations.
    public interface IEntityMapperAssemblyFinder
    {
        IEnumerable<Assembly> FindEntityMapperAssemblies(Func<Assembly, bool> predicate = null);
    }

    // Implementation of the entity mapper assembly finder.
    public class EntityMapperAssemblyFinder : IEntityMapperAssemblyFinder
    {
        private readonly IAssemblyFinder _assemblyFinder;

        public EntityMapperAssemblyFinder(IAssemblyFinder assemblyFinder)
        {
            _assemblyFinder = assemblyFinder ?? throw new ArgumentNullException(nameof(assemblyFinder));
        }

        // Scans assemblies and filters those containing concrete implementations of IEntityMapper.
        public IEnumerable<Assembly> FindEntityMapperAssemblies(Func<Assembly, bool> predicate = null)
        {
            var assemblies = _assemblyFinder.GetAssemblies();

            var eligibleAssemblies = assemblies.Where(assembly =>
            {
                try
                {
                    // Inspect each type in the assembly.
                    return assembly.GetTypes().Any(type =>
                        typeof(IEntityMapper).IsAssignableFrom(type) && !type.IsAbstract);
                }
                catch (ReflectionTypeLoadException)
                {
                    // Handle cases where some types cannot be loaded.
                    return false;
                }
            });

            if (predicate != null)
            {
                eligibleAssemblies = eligibleAssemblies.Where(predicate);
            }

            return eligibleAssemblies;
        }
    }

