using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

public struct PatchFile
{
    public string Address { get; set; }
    public string FileHash { get; set; }
    public string URL { get; set; }
}

public class ManifestFile
{
    public string Version { get; private set; }
    public List<PatchFile> PatchFiles { get; private set; }

    public ManifestFile(string path, string version, List<PatchFile> patchFiles)
    {
        Version = version;
        PatchFiles = patchFiles;
        WriteManifestFile(path);
    }

    public ManifestFile(Stream manifestStream)
    {
        ReadManifestFile(manifestStream);
    }

    private void WriteManifestFile(string path)
    {
        using (var writer = new BinaryWriter(File.Open(path, FileMode.Create)))
        {
            writer.Write(Encoding.UTF8.GetBytes(Version));
            writer.Write((int)PatchFiles.Count);

            bool includeUrls = PatchFiles.Count > 0 && !string.IsNullOrEmpty(PatchFiles[0].URL);

            foreach (var patchFile in PatchFiles)
            {
                writer.Write(Encoding.UTF8.GetBytes(patchFile.Address));
                writer.Write(Encoding.UTF8.GetBytes(patchFile.FileHash));
                if (includeUrls)
                {
                    writer.Write(Encoding.UTF8.GetBytes(patchFile.URL));
                }
            }
        }
    }

    private void ReadManifestFile(Stream manifestStream)
    {
        using (var reader = new BinaryReader(manifestStream))
        {
            Version = Encoding.UTF8.GetString(reader.ReadBytes(32)).TrimEnd('\0');
            int patchFileCount = reader.ReadInt32();
            PatchFiles = new List<PatchFile>();

            bool includeUrls = false;
            if (patchFileCount > 0)
            {
                string firstAddress = Encoding.UTF8.GetString(reader.ReadBytes(256)).TrimEnd('\0');
                string firstFileHash = Encoding.UTF8.GetString(reader.ReadBytes(64)).TrimEnd('\0');
                string firstUrl = string.Empty;

                if (manifestStream.Position < manifestStream.Length)
                {
                    firstUrl = Encoding.UTF8.GetString(reader.ReadBytes(256)).TrimEnd('\0');
                    includeUrls = true;
