public class GravitySwitch : MonoBehaviour
{
    // Gravity and momentum settings
    public float GravityStrength = 9.81f;
    public float momentum = 10f;

    // Game state flags
    private bool gravityState = true; // true = normal gravity, false = reversed gravity
    private bool firstClick = false;
    private bool isGameOver = false;

    // Explosion effect and end-of-game objects
    public GameObject Explosion;
    public GameObject EndScreen;

    // Additional visual effects and character pieces
    public GameObject[] Jets;
    public GameObject[] CharacterPieces;

    // UI element to display best score
    public Text BestScore;

    // Last hit position recorded on collision
    private Vector2 hitPosition;

    // Initialization
    void Start()
    {
        // Retrieve and display best score from persistent storage
        int bestScoreValue = PlayerPrefs.GetInt("BestScore", 0);
        if (BestScore != null)
        {
            BestScore.text = "Best Score: " + bestScoreValue;
        }

        // Initialize gravity for the first frame
        SetGravity();

        // Ensure EndScreen is inactive at game start
        if (EndScreen != null)
        {
            EndScreen.SetActive(false);
        }
    }

    // Update is called once per frame
    void Update()
    {
        if (isGameOver)
            return;

        // Handle input each frame
        ProcessControls();

        // Update gravity physics based on current toggle state
        SetGravity();
    }

    // Adjusts the physics engine's gravity vector based on current gravity state
    void SetGravity()
    {
        if (gravityState)
        {
            Physics2D.gravity = new Vector2(0, -GravityStrength);
        }
        else
        {
            Physics2D.gravity = new Vector2(0, GravityStrength);
        }
    }

    // Processes keyboard and mouse input to control gravity direction and visual effects
    void ProcessControls()
    {
        // Toggle gravity direction with Space key
        if (Input.GetKeyDown(KeyCode.Space))
        {
            gravityState = !gravityState;
        }

        // Toggle gravity and activate effects on left mouse button click
        if (Input.GetMouseButtonDown(0))
        {
            // Toggle gravity direction each mouse click
            gravityState = !gravityState;

            // On the first click, enhance momentum and gravity, and activate additional jets
            if (!firstClick)
            {
                firstClick = true;

using System;
using System.ComponentModel;
using System.Configuration.Install;
using System.Diagnostics;
using System.ServiceProcess;

public abstract class ServiceInstallerBase : Installer
{
    private readonly WinServiceInstallationOptions options;

    protected ServiceInstallerBase(WinServiceInstallationOptions options)
    {
        this.options = options ?? throw new ArgumentNullException(nameof(options));

        ServiceProcessInstaller processInstaller = new ServiceProcessInstaller
        {
            Account = options.ServiceAccount
        };

        ServiceInstaller serviceInstaller = new ServiceInstaller
        {
            ServiceName = options.ServiceName,
            DisplayName = options.DisplayName,
            Description = options.Description,
            StartType = options.StartType
        };

        Installers.Add(processInstaller);
        Installers.Add(serviceInstaller);

        // Remove default EventLogInstaller if present
        foreach (Installer installer in Installers)
        {
            if (installer is EventLogInstaller)
            {
                Installers.Remove(installer);
                break;
            }
        }

        // Add custom EventLogInstaller if specified
        if (options.EventLogSource != null)
        {
            EventLogInstaller eventLogInstaller = new EventLogInstaller
            {
                Source = options.EventLogSource,
                Log = options.EventLogName ?? "Application"
            };
            Installers.Add(eventLogInstaller);
        }
    }
}

public class WinServiceInstallationOptions
{
    public ServiceAccount ServiceAccount { get; set; }
    public string ServiceName { get; set; }
    public string DisplayName { get; set; }
    public string Description { get; set; }
    public ServiceStartMode StartType { get; set; }
    public string EventLogSource { get; set; }
    public string EventLogName { get; set; }
}

