using System;
using System.Runtime.InteropServices;

internal static class NativeMethods
{
    [DllImport("libc", SetLastError = true)]
    internal static extern unsafe int sysctl(int[] name, uint namelen, byte* oldp, ref ulong oldlenp, IntPtr newp, ulong newlen);
}

public static class Darwin
{
    private const int CTL_KERN = 1;
    private const int KERN_OSRELEASE = 2;
    private const int BUFFER_LENGTH = 256;

    public static unsafe string GetKernelRelease()
    {
        int[] name = new int[] { CTL_KERN, KERN_OSRELEASE };
        ulong len = BUFFER_LENGTH;
        byte* buf = stackalloc byte[BUFFER_LENGTH];

        fixed (int* pName = name)
        {
            if (NativeMethods.sysctl(name, (uint)name.Length, buf, ref len, IntPtr.Zero, 0) < 0)
            {
                throw new Exception($"sysctl failed with error code: {Marshal.GetLastWin32Error()}");
            }
        }

        // Convert to a string.  The string is null-terminated.  The 'len'
        // value appears to include the null terminator in its count.

        return Marshal.PtrToStringAnsi((IntPtr)buf, (int)len - 1);

    }
    public static void Main(string[] args)
    {
        try
        {
             string kernelVersion = GetKernelRelease();
            Console.WriteLine("Kernel Version: " + kernelVersion);
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error: " + ex.Message);
        }
    }
}

