                var count = transMap[key];
                var freq = (double) count / num * 100;
                Console.WriteLine("{0} -> {1}  count: {2,7:D}", key / 10, key % 10, count);
                Console.WriteLine("  frequency: {0,4:F2}%", freq);
            }
            Console.WriteLine();
        }
 
