namespace FashionStones.EmailService
{
    public class EmailSettings
    {
        public string Link { get; set; }
        public string MailFromAddress { get; set; }
        public string ServerName { get; set; }
        public bool UseSsl { get; set; }
        public int ServerPort { get; set; }
        public string Password { get; set; }

        public EmailSettings()
        {
            Link = ConfigurationManager.AppSettings["EmailLink"];
            MailFromAddress = ConfigurationManager.AppSettings["MailFromAddress"];
            ServerName = ConfigurationManager.AppSettings["ServerName"];
            UseSsl = bool.Parse(ConfigurationManager.AppSettings["UseSsl"]);
            ServerPort = int.Parse(ConfigurationManager.AppSettings["ServerPort"]);
            Password = ConfigurationManager.AppSettings["Password"];
        }
    }

    public class EmailService
    {
        private readonly EmailSettings _emailSettings;

        public EmailService()
        {
            _emailSettings = new EmailSettings();
        }

        public void SendEmail(string toEmail, string subject, string body, bool isHtml = true)
        {
            using (var smtpClient = new SmtpClient(_emailSettings.ServerName, _emailSettings.ServerPort))
            {
                smtpClient.EnableSsl = _emailSettings.UseSsl;
                smtpClient.Credentials = new NetworkCredential(_emailSettings.MailFromAddress, _emailSettings.Password);

                var mailMessage = new MailMessage
                {
                    From = new MailAddress(_emailSettings.MailFromAddress),
                    Subject = subject,
                    Body = body,
                    IsBodyHtml = isHtml
                };

                mailMessage.To.Add(toEmail);

                try
                {
                    smtpClient.Send(mailMessage);
                    Console.WriteLine("Email sent successfully.");
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Failed to send email: {ex.Message}");
                }
            }
        }

