namespace FileSystemAbstraction
{
    public interface IHandler
    {
        // Gets the full path of the file system item.
        string Path { get; }
        // Indicates whether the item exists.
        bool IsExists { get; }
        // True if the item is a directory.
        bool IsDir { get; }
        // Returns the file attributes of the item.
        FileAttributes GetAttributes();
        // Returns the size (in bytes) of the item.
        long GetSize();
        // Renames the item with a new name.
        void Rename(string newName);
        // Moves the item to a new path.
        void Move(string newPath);
        // Copies the item to the specified destination path.
        void Copy(string copyPath);
        // Deletes the item.
        void Delete();
    }

    public class FileHandler : IHandler
    {
        public string Path { get; private set; }

        public FileHandler(string path)
        {
            Path = path;
        }

        public bool IsExists => File.Exists(Path);

        public bool IsDir => false;

        public FileAttributes GetAttributes()
        {
            if (!IsExists)
                throw new FileNotFoundException("File not found", Path);
            return File.GetAttributes(Path);
        }

        public long GetSize()
        {
            if (!IsExists)
                throw new FileNotFoundException("File not found", Path);
            return new FileInfo(Path).Length;
        }

        public void Rename(string newName)
        {
            if (!IsExists)
                throw new FileNotFoundException("File not found", Path);
            string directory = System.IO.Path.GetDirectoryName(Path);
            string newPath = System.IO.Path.Combine(directory, newName);
            File.Move(Path, newPath);
            Path = newPath;
        }

        public void Move(string newPath)
        {
            if (!IsExists)
                throw new FileNotFoundException("File not found", Path);
            File.Move(Path, newPath);
            Path = newPath;
        }

        public void Copy(string copyPath)
        {
            if (!IsExists)
                throw new FileNotFoundException("File not found", Path);
            File.Copy(Path, copyPath, true);
        }

        public void Delete()
        {
            if (!IsExists)
                throw new FileNotFoundException("File not found", Path);
            File.Delete(Path);
        }
    }

    public class DirectoryHandler : IHandler
    {
        public string Path { get; private set; }

