namespace CoffeeShop.Controllers
{
    public class CoffeesController : Controller
    {
        private readonly ICoffeeRepository _coffeeRepository;
        private readonly ICalculationService _calculationService;

        public CoffeesController(
            ICoffeeRepository coffeeRepository,
            ICalculationService calculationService)
        {
            _coffeeRepository = coffeeRepository;
            _calculationService = calculationService;
        }

        [HttpGet]
        public ActionResult Index()
        {
            var model = GetFilteredCoffees(new CoffeeFilterViewModel());
            return View(model);
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        public ActionResult Filter(CoffeeFilterViewModel filterModel)
        {
            if (!ModelState.IsValid)
            {
                return Json(new { success = false });
            }

            var filteredProducts = GetFilteredCoffees(filterModel);
            return Json(new
            {
                success = true,
                products = filteredProducts.ProductItems
            });
        }

        private ProductListViewModel GetFilteredCoffees(CoffeeFilterViewModel filterModel)
        {
            var coffees = _coffeeRepository.GetAllCoffees();

            var filteredCoffees = coffees
                .Where(c =>
                    (filterModel.MinPrice == null || c.Price >= filterModel.MinPrice) &&
                    (filterModel.MaxPrice == null || c.Price <= filterModel.MaxPrice) &&
                    (string.IsNullOrEmpty(filterModel.Origin) || c.Origin == filterModel.Origin) &&
                    (filterModel.IsInStock == null || c.InStock == filterModel.IsInStock))
                .ToList();

            var productItems = filteredCoffees.Select(coffee => new ProductListItemViewModel
            {
                Id = coffee.Id,
                Name = coffee.Name,
                Origin = coffee.Origin,
                BasePrice = coffee.Price,
                FinalPrice = _calculationService.CalculateFinalPrice(coffee),
                InStock = coffee.InStock,
                DiscountPercentage = _calculationService.CalculateDiscount(coffee)
            }).ToList();

            return new ProductListViewModel
            {
                ProductItems = productItems,
                TotalProducts = productItems.Count,
                FilterModel = filterModel
            };
        }
    }

class Service
{
    public void FizzBuzzGo()
    {
        Boolean Fizz = false;
        Boolean Buzz = false;
        for (int count = 1; count <= 100; count ++)
        {
            Fizz = count % 3 == 0;
            Buzz = count % 5 == 0;
            if (Fizz && Buzz)
            {
                Console.WriteLine("Fizz Buzz");
                listBox1.Items.Add("Fizz Buzz");
            }
            else if (Fizz)
            {
                Console.WriteLine("Fizz");
                listBox1.Items.Add("Fizz");
            }
            else if (Buzz)
            {
                Console.WriteLine("Buzz");
                listBox1.Items.Add("Buzz");
            }
            else
            {
                Console.WriteLine(count);
                listBox1.Items.Add(count);
            }
        }
    }
}

