namespace KnightsTour
{
    public class Utils
    {
        // Fixed board size
        static int n = 6;
        // Chessboard represented as a 2D array
        static uint[,] board = new uint[n, n];
        // Allowed knight moves (offsets) in x direction
        static int[] diffX = { 2, 1, -1, -2, -2, -1, 1, 2 };
        // Allowed knight moves (offsets) in y direction
        static int[] diffY = { 1, 2, 2, 1, -1, -2, -2, -1 };
        // Total possible moves for a knight
        static int maxDiff = 8;

        public static void Main(string[] args)
        {
            // Starting position of the knight
            int startX = 0;
            int startY = 0;

            // Mark the starting square with move number 1
            board[startX, startY] = 1;

            // Begin the recursive process with the next move number (2)
            bool found = NextMove(startX, startY, 2);

            // If no solution is found, output an appropriate message.
            if (!found)
            {
                Console.WriteLine("No solution exists.");
            }
        }

        // Recursively attempts moves for the knight using backtracking.
        static bool NextMove(int x, int y, uint moveCount)
        {
            // If we've made more moves than board squares, the tour is complete.
            if (moveCount > n * n)
            {
                PrintBoard();
                Environment.Exit(0);
            }

            // Try all possible knight moves.
            for (int i = 0; i < maxDiff; i++)
            {
                int newX = x + diffX[i];
                int newY = y + diffY[i];

                // Check if the new position is valid (inside board and not visited).
                if (IsValid(newX, newY))
                {
                    board[newX, newY] = moveCount;

                    // Recursive call to extend the path.
                    if (NextMove(newX, newY, moveCount + 1))
                    {
                        return true;
                    }

                    // Backtracking: unmark the square if it leads to a dead end.
                    board[newX, newY] = 0;
                }
            }

            // Return false if no path from the current position leads to a solution.
            return false;
        }

        // Checks whether a move is within bounds and not revisiting a square.
        static bool IsValid(int x, int y)
        {
            if (x >= 0 && x < n && y >= 0 && y < n && board[x, y] == 0)

