namespace SSCMS.Web.Controllers.Settings
{
    [Route("api/settings/sites")]
    public class SitesController : ControllerBase
    {
        private readonly IAuthManager _authManager;
        private readonly ISiteRepository _siteRepository;
        private readonly ISettingsManager _settingsManager;
        private readonly IPathManager _pathManager;

        public SitesController(IAuthManager authManager, ISiteRepository siteRepository, ISettingsManager settingsManager, IPathManager pathManager)
        {
            _authManager = authManager;
            _siteRepository = siteRepository;
            _settingsManager = settingsManager;
            _pathManager = pathManager;
        }

        [HttpGet]
        public async Task<ActionResult<GetResult>> Get()
        {
            if (!await _authManager.HasAppPermissionsAsync(AuthTypes.AppPermissions.SettingsSites))
            {
                return Unauthorized();
            }

            var rootSiteId = await _siteRepository.GetIdByIsRootAsync();
            var siteTypes = _settingsManager.GetSiteTypes();
            var sites = await _siteRepository.GetSitesWithChildrenAsync(0);
            var siteTableNames = await _siteRepository.GetSiteTableNamesAsync();

            var result = new GetResult
            {
                RootSiteId = rootSiteId,
                SiteTypes = siteTypes,
                Sites = sites,
                SiteTableNames = siteTableNames
            };

            return Ok(result);
        }

        public class GetResult
        {
            public int RootSiteId { get; set; }
            public List<SiteType> SiteTypes { get; set; }
            public List<Site> Sites { get; set; }
            public List<string> SiteTableNames { get; set; }
        }
    }
}

