using System;
using System.Numerics;
using WhetStone.Looping;
using WhetStone.SystemExtensions;

public static class Choose
{
    public static BigInteger Choose(int n, params int[] k)
    {
        ThrowIfNull(k, nameof(k));
        ThrowIfAbsurd(n < 0, nameof(n), "n must be non-negative.");
        ThrowIfAbsurd(k.TallyAny(x => x < 0), nameof(k), "All elements in k must be non-negative.");

        var tal = k.TallyAggregate((a, b) => a + b);
        ThrowIfAbsurd(tal > n, nameof(k), "Sum of k must not exceed n.");

        if (tal < n)
        {
            k = k.Append(n - tal).ToArray();
        }

        var ret = new BigProduct();
        ret.MultiplyFactorial(n);
        k.Do(x => ret.DivideFactorial(x));

        return ret.toFraction();
    }

    private static void ThrowIfNull<T>(T obj, string paramName) where T : class
    {
        if (obj == null) throw new ArgumentNullException(paramName);
    }

    private static void ThrowIfAbsurd(bool condition, string paramName, string message)
    {
        if (condition) throw new ArgumentException(message, paramName);
    }

    private struct BigProduct
    {
        private BigInteger _numerator;
        private BigInteger _denominator;

        public BigProduct()
        {
            _numerator = 1;
            _denominator = 1;
        }

        public void MultiplyFactorial(int n)
        {
            for (int i = 2; i <= n; i++)
            {
                _numerator *= i;
            }
        }

        public void DivideFactorial(int n)
        {
            for (int i = 2; i <= n; i++)
            {
                _denominator *= i;
            }
        }

        public BigInteger toFraction()
        {
            return _numerator / _denominator;
        }
    }
}

