public class Kaprekar
{
    public static void Main()
    {
        uint max = 10000;
        Console.WriteLine("Kaprekar numbers < {0}:", max);
        for (uint m = 0; m < max; m++)
        {
            if (IsKaprekar(m, 10))
            {
                Console.WriteLine("  {0}", m);
            }
        }
 
        // extra credit
        max = 1000000;
        int count = 0;
        for (uint m = 0; m < max; m++)
        {
            if (IsKaprekar(m, 10))
            {
                count++;
            }
        }
        Console.WriteLine("\nThere are {0} Kaprekar numbers < {1}.", count, max);
 
        // extra extra credit
        const int base = 17;
        max = 1000000;
        Console.WriteLine("\nKaprekar numbers between 1 and {0}(base {1}):", max, base);
        Console.WriteLine("\n Base 10  Base {0}        Square       Split", base);
        for (uint m = 2; m < max; m++)
        {
            if (IsKaprekar(m, base))
            {
                string sq = Convert.ToString(m * m, base);
                string str = Convert.ToString(m, base);
                int split = sq.Length - GetOrder(m, base);
                Console.WriteLine("{0,8}  {1,7}  {2,12}  {3,6} + {4}", m, str, sq, sq.Substring(0, split), sq.Substring(split));
            }
        }
    }
 
    public static bool IsKaprekar(uint n, uint base)
    {
        int order = 0;
        if (n == 1)
        {
            return true;
        }
 
        uint nn = n * n, power = 1;
        while (power <= nn)
        {
            power *= base;
            order++;
        }
 
        power /= base;
        order--;
        while (power > 1)
        {
            uint q = nn / power, r = nn % power;
            if (q >= n)
            {
                return false;
            }
 
            if (q + r == n)
            {
                return true;
            }
 
            power /= base;
            order--;
        }
 
        return false;
    }
 
    public static int GetOrder(uint n, uint base)
