/// <summary>
/// Provides data for the event that occurs when a JavaScript object binding process completes in the CefSharp framework.
/// </summary>
/// <remarks>
/// This class follows the standard .NET event argument pattern to propagate metadata about completed
/// JavaScript object bindings, enabling integration with CefSharp's JavaScript/.NET interop lifecycle.
/// </remarks>
public class JavascriptBindingCompleteEventArgs : EventArgs
{
    /// <summary>
    /// Gets the repository managing JavaScript object bindings.
    /// </summary>
    /// <value>
    /// The <see cref="IJavascriptObjectRepository"/> instance associated with the binding operation.
    /// </value>
    public IJavascriptObjectRepository ObjectRepository { get; }

    /// <summary>
    /// Gets the name of the JavaScript object involved in the binding operation.
    /// </summary>
    /// <value>
    /// A string identifier for the bound JavaScript object.
    /// </value>
    public string ObjectName { get; }

    /// <summary>
    /// Gets a value indicating whether the object was previously bound.
    /// </summary>
    /// <value>
    /// True if the object binding already existed prior to this operation.
    /// </value>
    public bool AlreadyBound { get; }

    /// <summary>
    /// Gets a value indicating whether the binding context is cached.
    /// </summary>
    /// <value>
    /// True if the binding uses cached context to optimize object management.
    /// </value>
    public bool IsCached { get; }

    /// <summary>
    /// Initializes a new instance with binding operation details.
    /// </summary>
    /// <param name="objectRepository">Repository managing JavaScript objects</param>
    /// <param name="objectName">Name of the bound JavaScript object</param>
    /// <param name="alreadyBound">Indicates pre-existing binding status</param>
    /// <param name="isCached">Indicates caching state of the binding context</param>
    /// <exception cref="ArgumentNullException">Thrown for null repository or object name</exception>
    public JavascriptBindingCompleteEventArgs(
        IJavascriptObjectRepository objectRepository,
        string objectName,
        bool alreadyBound,
        bool isCached)
    {
        ObjectRepository = objectRepository ?? throw new ArgumentNullException(nameof(objectRepository));
        ObjectName = objectName ?? throw new ArgumentNullException(nameof(objectName));
        AlreadyBound = alreadyBound;
        IsCached = isCached;
    }
}

