namespace Generator
{
    [TestFixture]
    public class HandlingMessagesThenSpeedIsAcceptable
    {
        private int messageCount = 100000;
        private int MessageReceivedCount;
        private Message1 LastMessageReceived;

        public class Message1
        {
            public int Id { get; set; }
            public string Text { get; set; }
        }

        public class Message2
        {
            public int Id { get; set; }
            public string Text { get; set; }
        }

        public class Message2Consumer : IHandler<Message2>
        {
            public void Handle(Message2 message)
            {
                Console.WriteLine($"Message 2 received: {message.Id} - {message.Text}");
            }
        }

        [Generator, Explicit("Performance test, disabled for automated runs.")]
        public void CompareCapacity()
        {
            var bus = new Bus();
            bus.AddHandler<Message1>(msg =>
            {
                MessageReceivedCount++;
                LastMessageReceived = msg;
            });

            var stopwatch = Stopwatch.StartNew();
            for (int i = 0; i < messageCount; i++)
            {
                bus.Handle(new Message1 { Id = i, Text = "Message " + i });
            }
            stopwatch.Stop();
            Console.WriteLine($"Bus took: {stopwatch.Elapsed.ToEnglishString()}");

            Assert.AreEqual(messageCount, MessageReceivedCount);
            Assert.AreEqual(messageCount - 1, LastMessageReceived.Id);
            MessageReceivedCount = 0;
            LastMessageReceived = null;

            stopwatch.Restart();
            for (int i = 0; i < messageCount; i++)
            {
                Handle(new Message1 { Id = i, Text = "Message " + i });
            }
            stopwatch.Stop();
            Console.WriteLine($"Direct took: {stopwatch.Elapsed.ToEnglishString()}");
            Assert.AreEqual(messageCount, MessageReceivedCount);
            Assert.AreEqual(messageCount - 1, LastMessageReceived.Id);
        }

        [Generator, Explicit("Performance test, disabled for automated runs.")]
        public void MeasureCapacity()
        {
            var bus = new Bus();
            bus.AddHandlersAndTranslators(typeof(HandlingMessagesThenSpeedIsAcceptable).Assembly);
            bus.AddTranslator<Message1, Message2>(msg => new Message2 { Id = msg.Id, Text = msg.Text + " translated" });

namespace Vlq
{
  using System;
  using System.Collections.Generic;
  using System.Linq;
 
  public static class VarLenQuantity
  {
    public static ulong ToVlq(ulong integer)
    {
      var array = new byte[8];
      var buffer = ToVlqCollection(integer)
        .SkipWhile(b => b == 0)
        .Reverse()
        .ToArray();
      Array.Copy(buffer, array, buffer.Length);
      return BitConverter.ToUInt64(array, 0);
    }
 
    public static ulong FromVlq(ulong integer)
    {
      var collection = BitConverter.GetBytes(integer).Reverse();
      return FromVlqCollection(collection);
    }
 
    public static IEnumerable<byte> ToVlqCollection(ulong integer)
    {
      if (integer > Math.Pow(2, 56))
        throw new OverflowException("Integer exceeds max value.");
 
      var index = 7;
      var significantBitReached = false;
      var mask = 0x7fUL << (index * 7);
      while (index >= 0)
      {
        var buffer = (mask & integer);
        if (buffer > 0 || significantBitReached)
        {
          significantBitReached = true;
          buffer >>= index * 7;
          if (index > 0)
            buffer |= 0x80;
          yield return (byte)buffer;
        }
        mask >>= 7;
        index--;
      }
    }
 
 
    public static ulong FromVlqCollection(IEnumerable<byte> vlq)
    {
      ulong integer = 0;
      var significantBitReached = false;
 
      using (var enumerator = vlq.GetEnumerator())
      {
        int index = 0;
        while (enumerator.MoveNext())
        {
          var buffer = enumerator.Current;
          if (buffer > 0 || significantBitReached)
          {
            significantBitReached = true;
            integer <<= 7;
            integer |= (buffer & 0x7fUL);
          }
 
          if (++index == 8 || (significantBitReached && (buffer & 0x80) != 0x80))
            break;
        }
      }
      return integer;
    }
 
    public static void Main()
    {
      var integers = new ulong[] { 0x7fUL << 7 * 7, 0x80, 0x2000, 0x3FFF, 0x4000, 0x200000, 0x1fffff };
 
      foreach (var original in integers)
      {
        Console.WriteLine("Original: 0x{0:X}", original);
 
        //collection
        var seq = ToVlqCollection(original);
        Console.WriteLine("Sequence: 0x{0}", seq.Select(b => b.ToString("X2")).Aggregate(string.Concat));
 
        var decoded = FromVlqCollection(seq);
        Console.WriteLine("Decoded: 0x{0:X}", decoded);
 
        //ints
        var encoded = ToVlq(original);
        Console.WriteLine("Encoded: 0x{0:X}", encoded);
 
        decoded = FromVlq(encoded);

