    static void Main()
    {
        Console.Write("Enter a four-digit number: ");
        int num = Int32.Parse(Console.ReadLine());

        // Decompose the number into its individual digits
        int a = num / 1000;       // First digit
        int b = (num / 100) % 10; // Second digit
        int c = (num / 10) % 10;  // Third digit
        int d = num % 10;         // Fourth digit

        // Calculate the sum of the digits
        int sum = a + b + c + d;

        // Print the number in reverse order
        int reversedNumber = d * 1000 + c * 100 + b * 10 + a;

        // Rearrange the number such that the last digit becomes the first digit
        int lastToFirst = d * 1000 + a * 100 + b * 10 + c;

        // Swap the second and third digits of the number
        int swapSecondThird = a * 1000 + c * 100 + b * 10 + d;

        // Output the results
        Console.WriteLine("Sum of the digits: " + sum);
        Console.WriteLine("Number in reverse order: " + reversedNumber);
        Console.WriteLine("Last digit to first: " + lastToFirst);
        Console.WriteLine("Second and third digits swapped: " + swapSecondThird);
    }
}

