public class CommandStatisticsRun
{
    private Dictionary<string, CommandStatistics> _commandStatistics = new Dictionary<string, CommandStatistics>();

    public void SetCommandStatistics(Command command)
    {
        try
        {
            if (!_commandStatistics.ContainsKey(command.Sql))
            {
                var statistics = runAnalysis(command);
                _commandStatistics[command.Sql] = statistics;
            }
            setNormalizedSqlHash(command);
        }
        catch (Exception ex)
        {
            ExceptionLogger.Log(ex);
            AppMessenger.Notify("Error processing command statistics.");
        }
    }

    private CommandStatistics runAnalysis(Command command)
    {
        var counterVisitor = new CounterVisitor();
        var runTSqlFragmentVisitor = new RunTSqlFragmentVisitor(counterVisitor);
        runTSqlFragmentVisitor.Visit(command.TSqlFragment);
        return new CommandStatistics
        {
            ExecutionCount = counterVisitor.ExecutionCount,
            AverageDuration = counterVisitor.AverageDuration
        };
    }

    private void setNormalizedSqlHash(Command command)
    {
        var normalizedSql = NormalizeSql(command.Sql);
        command.SqlHash = normalizedSql.GetHashCode();
    }

    private string NormalizeSql(string sql)
    {
        // Simplified normalization logic
        var normalized = sql.ToLower().Replace("  ", " ").Trim();
        return normalized;
    }
}

public struct CommandStatistics
{
    public int ExecutionCount { get; set; }
    public double AverageDuration { get; set; }
}

public class CounterVisitor
{
    public int ExecutionCount { get; set; }
    public double AverageDuration { get; set; }

    public void Visit(TSqlFragment fragment)
    {
        // Dummy implementation for the sake of example
        ExecutionCount++;
        AverageDuration += 100; // Example duration
    }
}

public class RunTSqlFragmentVisitor
{
    private readonly CounterVisitor _counterVisitor;

    public RunTSqlFragmentVisitor(CounterVisitor counterVisitor)
    {
        _counterVisitor = counterVisitor;
    }

    public void Visit(TSqlFragment fragment)
    {
        _counterVisitor.Visit(fragment);
    }
}

