public class StylesheetNode
{
    public virtual string ToCss() => string.Empty;
}

public class Stylesheet : StylesheetNode
{
    private readonly StylesheetParser _parser;
    public List<CssRule> Rules { get; private set; }

    public Stylesheet(StylesheetParser parser)
    {
        _parser = parser;
        Rules = new List<CssRule>();
    }

    public void AddRule(string cssText)
    {
        var rule = _parser.Parse(cssText);
        if (rule != null)
        {
            Rules.Add(rule);
        }
    }

    public void RemoveRule(CssRule rule)
    {
        Rules.Remove(rule);
    }

    public void InsertRule(int index, string cssText)
    {
        var rule = _parser.Parse(cssText);
        if (rule != null && index >= 0 && index <= Rules.Count)
        {
            Rules.Insert(index, rule);
        }
    }

    public IEnumerable<CssRule> GetStyleRules() => Rules.OfType<StyleRule>();
    public IEnumerable<CssRule> GetMediaRules() => Rules.OfType<MediaRule>();

    public override string ToCss()
    {
        return string.Join(Environment.NewLine, Rules.Select(r => r.ToCss()));
    }
}

public class StylesheetParser
{
    public CssRule Parse(string cssText)
    {
        // Simplistic parsing logic for demonstration
        if (cssText.StartsWith("@media"))
            return new MediaRule(cssText);
        else if (cssText.StartsWith("@font-face"))
            return new FontFaceRule(cssText);
        return new StyleRule(cssText);
    }
}

public abstract class CssRule
{
    protected string RuleText;

    protected CssRule(string ruleText)
    {
        RuleText = ruleText;
    }

    public abstract string ToCss();
}

public class StyleRule : CssRule
{
    public StyleRule(string ruleText) : base(ruleText) { }

    public override string ToCss() => RuleText;
}

public class MediaRule : CssRule
{
    public MediaRule(string ruleText) : base(ruleText) { }

    public override string ToCss() => RuleText;
}

public class FontFaceRule : CssRule
{
    public FontFaceRule(string ruleText) : base(ruleText) { }

    public override string ToCss() => RuleText;
}

