public sealed class CaptureNotificationInfo
{
    public string Notification;
    public string LoseNotification;
    public bool NewOwnerVoice;
    public bool LoseNewOwnerVoice;
}

public sealed class CaptureNotification : ITrait<Actor>, IWorldLoaded
{
    [YamlKey("Notifications")]
    public readonly Dictionary<BitSet<CaptureType>, CaptureNotificationInfo> Notifications;

    public void WorldLoaded(World world) { }

    public void Create(Actor self)
    {
        self.OwnerCapture += (capturing, captured, oldOwner, newOwner, types) => OnCapture(capturing, captured, oldOwner, newOwner, types);
    }

    void OnCapture(Actor capturing, Actor captured, Player oldOwner, Player newOwner, BitSet<CaptureType> types)
    {
        if (Notifications == null) return;

        foreach (var kv in Notifications)
        {
            if (kv.Key.IsSubsetOf(types))
            {
                var notificationInfo = kv.Value;

                PlayNotification(oldOwner, notificationInfo.LoseNotification, notificationInfo.LoseNewOwnerVoice ? newOwner.Faction : oldOwner.Faction);
                PlayNotification(newOwner, notificationInfo.Notification, notificationInfo.NewOwnerVoice ? newOwner.Faction : oldOwner.Faction);
                break;
            }
        }
    }

    static void PlayNotification(Player player, string soundName, Faction faction)
    {
        if (player == null || string.IsNullOrEmpty(soundName)) return;

        var voice = faction?.GetVoiceFor(soundName) ?? soundName;
        player.World.Sound.Play(voice, player.Faction);
    }
}

