        /// Send a given request and waits for a response.
        /// </summary>
        Task<IResponse> RequestAsync(
            Type requestType, Type responseType, IRequest request,
            SubscriptionId subscriptionId = null,
            Dictionary<string, string> headers = null,
            TimeSpan expiration = default(TimeSpan));

        /// <summary>
        /// Delete the queue used for a given type of request
        /// </summary>
        void DeleteRequestQueue(Type requestType, SubscriptionId subscriptionId = null);
    }
}

using System;
using System.Linq;

public class ExtendedEngine : Engine
{
    private const int CharacterNeutralOwner = -1;

    public override void ExecuteCreateObjectCommand(string[] commandWords)
    {
        if (commandWords.Length == 0)
        {
            base.ExecuteCreateObjectCommand(commandWords);
            return;
        }

        string type = commandWords[0].ToLower();
        var args = commandWords.Skip(1);

        switch (type)
        {
            case "giant":
                string name = GetArg(args, "name");
                Point pos = new Point(GetArgInt(args, "x"), GetArgInt(args, "y"));
                AddObject(new Giant(name, pos, CharacterNeutralOwner));
                break;
            case "knight":
                AddObject(new Knight(
                    GetArg(args, "name"),
                    new Point(GetArgInt(args, "x"), GetArgInt(args, "y")),
                    GetArgInt(args, "owner")));
                break;
            case "house":
                AddObject(new House(
                    GetArg(args, "name"),
                    new Point(GetArgInt(args, "x"), GetArgInt(args, "y")),
                    GetArgInt(args, "size", 1)));
                break;
            case "rock":
                AddObject(new Rock(
                    GetArg(args, "name"),
                    new Point(GetArgInt(args, "x"), GetArgInt(args, "y")),
                    GetArgInt(args, "size", 1)));
                break;
            case "ninja":
                AddObject(new Ninja(
                    GetArg(args, "name"),
                    new Point(GetArgInt(args, "x"), GetArgInt(args, "y")),
                    GetArgInt(args, "owner")));
                break;
            default:
                base.ExecuteCreateObjectCommand(commandWords);
                break;
        }
    }

    private string GetArg(System.Collections.Generic.IEnumerable<string> args, string key)
        => args.FirstOrDefault(a => a.StartsWith($"{key}:"))?.Split(':')[1] ?? "";

    private int GetArgInt(System.Collections.Generic.IEnumerable<string> args, string key, int def = 0)
        => int.TryParse(GetArg(args, key), out int val) ? val : def;
}

