namespace Microsoft.Azure.Management.DataLake.AnalyticsCatalog
{
    public class USqlTableValuedFunctionList : CatalogItemList
    {
        private Lazy<IList<USqlTableValuedFunction>> _value;

        public IList<USqlTableValuedFunction> Value
        {
            get { return _value.Value; }
        }

        public USqlTableValuedFunctionList()
        {
            _value = new Lazy<IList<USqlTableValuedFunction>>(() => new List<USqlTableValuedFunction>());
        }

        public USqlTableValuedFunctionList(IList<USqlTableValuedFunction> value)
        {
            _value = new Lazy<IList<USqlTableValuedFunction>>(() => value ?? new List<USqlTableValuedFunction>());
        }

        public void AddFunction(USqlTableValuedFunction function)
        {
            if (function != null)
            {
                Value.Add(function);
            }
        }

        public bool RemoveFunction(USqlTableValuedFunction function)
        {
            return Value.Remove(function);
        }

        public USqlTableValuedFunction GetFunctionByName(string name)
        {
            return Value.FirstOrDefault(f => f.Name.Equals(name, StringComparison.OrdinalIgnoreCase));
        }

        public IEnumerable<USqlTableValuedFunction> GetFunctionsBySchema(string schemaName)
        {
            return Value.Where(f => f.SchemaName.Equals(schemaName, StringComparison.OrdinalIgnoreCase));
        }

        public IEnumerable<USqlTableValuedFunction> GetFunctionsByDatabase(string databaseName)
        {
            return Value.Where(f => f.DatabaseName.Equals(databaseName, StringComparison.OrdinalIgnoreCase));
        }

        public IEnumerable<USqlTableValuedFunction> GetFunctionsByDatabaseAndSchema(string databaseName, string schemaName)
        {
            return Value.Where(f => f.DatabaseName.Equals(databaseName, StringComparison.OrdinalIgnoreCase) &&
                                   f.SchemaName.Equals(schemaName, StringComparison.OrdinalIgnoreCase));
        }

        public override string ToString()
        {
            return $"USqlTableValuedFunctionList with {Value.Count} functions.";
        }
    }
}

using System;
 
class Tree
{
    static int countDivisors(int n)
    {
        if (n < 2)
        {
            return 1;
        }
        int count = 2; // 1 and n
        for (int i = 2; i <= n / 2; i++)
        {
            if (n % i == 0)
            {
                count++;
            }
        }
        return count;
    }
 
    static void Main(string[] args)
    {
        Console.WriteLine("The first 20 anti-primes are:");
        int maxDiv = 0;
        int count = 0;
        for (int n = 1; count < 20; n++)
        {
            int d = countDivisors(n);
            if (d > maxDiv)
            {
                Console.Write("{0} ", n);
                maxDiv = d;
                count++;
            }
        }
        Console.WriteLine();
    }
}

