using System;
using System.Threading;
using System.Threading.Tasks;
using Gtk;
 
namespace Matrix
{
    class Solution
    {
        static void Main(string[] args)
        {
            Application.Init();
 
            var window = new Window(WindowType.Toplevel);
            window.DeleteEvent += (o, e) => Application.Quit();
            var button = new Button("Hello World!");
            window.Add(button);
 
            var locker = new object();
            var reverse = false;
 
            button.Clicked += (o, e) =>
            {
                lock (locker)
                {
                    reverse =!reverse;
                }
            };
 
            var timer = new Timer(state =>
            {
                lock (locker)
                {
                    var text = button.Label;
                    var len = text.Length;
 
                    if (reverse)
                    {
                        var begin = text.Substring(1);
                        text = begin + text[0];
                    }
                    else
                    {
                        var end = text.Substring(len - 1);
                        text = end + text[0];
                    }
 
                    button.Label = text;
                }
            }, null, 0, 100);
 
            window.ShowAll();
            Application.Run();
        }
    }
}

