namespace MontyHall
{
    class Library
    {
        static void Main(string[] args)
        {
            int doors = 3;
            int iterations = 100000;
            Console.WriteLine("Monty Hall problem simulation:");
            Console.WriteLine(doors + " doors, " + iterations + " iterations.\n");
            Console.WriteLine("Not switching allows you to win " +
                Enumerable.Range(0, iterations).Select(x => monty_hall(new Random().Next(3), false)).Count(x => x) +
                " out of " + iterations + " times.");
            Console.WriteLine("Switching allows you to win " +
                Enumerable.Range(0, iterations).Select(x => monty_hall(new Random().Next(3), true)).Count(x => x) +
                " out of " + iterations + " times.\n");
            Console.ReadLine();
        }
 
        static bool monty_hall(int choice, bool switch_door, int doorCount = 3)
        {
            // Set up doors
            bool[] door = new bool[doorCount];
            // One door with prize
            door[new Random().Next(doorCount)] = true;
 
            bool chosen = door[choice];
 
            bool[] unpicked = door;
            Array.Clear(unpicked, choice, 1);
 
            // Out of those unpicked, the alternative is either:
            //   the prize door, or
            //   an empty door if the initial choice is actually the prize.
            bool alternative = unpicked.Any(x => x);
 
            if (switch_door)
            {
                return alternative;
            }
            else
            {
                return chosen;
            }
        }
    }
}

