namespace ProjectEuler
{
    class Counter
    {
        static void Main(string[] args)
        {
            var s = new Queue<int>(55);
            //    Start with a single seed in range 0 to 10**9 - 1.
            int seed = 292929;
 
            //    Set s0 = seed and s1 = 1.
            //    The inclusion of s1 = 1 avoids some bad states
            //    (like all zeros, or all multiples of 10).
            s.Enqueue(seed);
            s.Enqueue(1);
 
            //    Compute s2,s3,...,s54 using the subtractive formula
            //    sn = s(n - 2) - s(n - 1)(mod 10**9).
            for (int n = 2; n < 55; n++)
            {
                s.Enqueue((s.ElementAt(n - 2) - s.ElementAt(n - 1)) % 1000000000);
            }
 
            //    Reorder these 55 values so r0 = s34, r1 = s13, r2 = s47,...,
            //                               rn = s(34 * (n + 1)(mod 55)).
 
            var r = new Queue<int>(55);
            for (int n = 0; n < 55; n++)
            {
                int i = (34 * (n + 1)) % 55;
                r.Enqueue(s.ElementAt(i));
            }
            //        This is the same order as s0 = r54, s1 = r33, s2 = r12,...,
            //                                  sn = r((34 * n) - 1(mod 55)).
            //        This rearrangement exploits how 34 and 55 are relatively prime.
            //    Compute the next 165 values r55 to r219. Store the last 55 values.
 
            for (int n = 0; n < 165; n++)
            {
                r.Enqueue((r.ElementAt(0) - r.ElementAt(31)) % 1000000000);
                r.Dequeue();
            }
 
            // now fully initilised
            // print first five numbers
            for (int i = 0; i < 5; i++)
            {
                Console.WriteLine("result = {0}", r.ElementAt(54));
                r.Enqueue((r.ElementAt(0) - r.ElementAt(31)) % 1000000000);
                r.Dequeue();
            }
 
            Console.ReadLine();
        }
    }
}

using System;
using Newtonsoft.Json;

public class QueryResult<T>
{
    [JsonProperty("isSuccess")]
    public bool IsSuccess { get; private set; }

    [JsonProperty("message")]
    public string Message { get; private set; }

    [JsonProperty("exceptionMessage")]
    public string ExceptionMessage { get; private set; }

    [JsonProperty("value")]
    public T Value { get; private set; }

    // Constructor for successful result with value
    public QueryResult(T value, string message = "")
    {
        IsSuccess = true;
        Value = value;
        Message = message;
        ExceptionMessage = null;
    }

    // Constructor for failed result with error message
    public QueryResult(string message, string exceptionMessage = null)
    {
        IsSuccess = false;
        Value = default;
        Message = message;
        ExceptionMessage = exceptionMessage;
    }

    // Static method for creating a successful result
    public static QueryResult<T> Success(T value, string message = "")
    {
        return new QueryResult<T>(value, message);
    }

    // Static method for creating a failed result
    public static QueryResult<T> Failure(string message, string exceptionMessage = null)
    {
        return new QueryResult<T>(message, exceptionMessage);
    }
}

