namespace Keepass2Android
{
    public class DeleteEntry
    {
        private PwEntry _entry;
        private string _statusMessage;
        public Context Ctx { get; set; }
        public PwDatabase Db { get; set; }

        public bool CanRecycle
        {
            get
            {
                return Db.RecycleBinEnabled && _entry.ParentGroup != null && _entry.ParentGroup.SupportsRecycling;
            }
        }

        public int QuestionRecycleResourceId { get; set; } = Resource.String.confirm_recycle_entry;
        public int QuestionNoRecycleResourceId { get; set; } = Resource.String.confirm_delete_entry;

        public string StatusMessage
        {
            get { return _statusMessage; }
            private set { _statusMessage = value; }
        }

        public DeleteEntry(PwEntry entry, Context ctx, PwDatabase db)
        {
            _entry = entry;
            Ctx = ctx;
            Db = db;
        }

        public void PerformDelete()
        {
            if (_entry == null || Db == null)
            {
                StatusMessage = Ctx.GetString(Resource.String.error_entry_not_found);
                return;
            }

            bool recycle = CanRecycle;

            if (recycle)
            {
                Db.RecycleEntry(_entry);
                StatusMessage = Ctx.GetString(Resource.String.entry_recycled);
            }
            else
            {
                PwGroup parentGroup = _entry.ParentGroup;
                if (parentGroup != null)
                {
                    parentGroup.Entries.Remove(_entry);
                    StatusMessage = Ctx.GetString(Resource.String.entry_deleted);
                }
                else
                {
                    StatusMessage = Ctx.GetString(Resource.String.error_entry_not_found);
                }
            }

            Db.Modified = true;
            Db.Save(null, new NullStatusLogger());
        }

        public void ShowConfirmationDialog()
        {
            int messageId = CanRecycle ? QuestionRecycleResourceId : QuestionNoRecycleResourceId;

            new AlertDialog.Builder(Ctx)
                .SetMessage(messageId)
                .SetPositiveButton(Android.Resource.String.Yes, (sender, e) => PerformDelete())
                .SetNegativeButton(Android.Resource.String.No, (sender, e) => { })
                .Show();
        }
    }
}

