using System;
using MyScriptingEngine;
using MyScriptingEngine.Runtime;
using MyUnitTestingFramework;

namespace ScriptingEngineTestApp
{
    class ScriptingEngineTests
    {
        static void Main(string[] args)
        {
            Console.WriteLine("Starting scripting engine tests...");
            RunTests();
            Console.WriteLine("All tests passed.");
        }

        public static void RunTests()
        {
            // Create an instance of the custom scripting engine.
            ScriptEngine engine = new ScriptEngine();

            // Define a global variable 'ten' with value 10.
            object result = engine.Evaluate("(define ten 10)");
            AssertEmptyResult(result, "definition of 'ten'");

            // Evaluate the value of 'ten' to verify it's 10.
            result = engine.Evaluate("ten");
            AssertEqual(ConvertToInt(result), 10, "evaluation of 'ten'");

            // Define another global variable 'twenty' with value 20.
            result = engine.Evaluate("(define twenty 20)");
            AssertEmptyResult(result, "definition of 'twenty'");
            result = engine.Evaluate("twenty");
            AssertEqual(ConvertToInt(result), 20, "evaluation of 'twenty'");

            // Define an arithmetic expression using 'ten' and 'twenty'.
            result = engine.Evaluate("(define expr (+ ten twenty))");
            AssertEmptyResult(result, "definition of 'expr'");
            result = engine.Evaluate("expr");
            AssertEqual(ConvertToInt(result), 30, "evaluation of 'expr'");

            // Redefine variable 'ten' to update its value.
            result = engine.Evaluate("(define ten 15)");
            AssertEmptyResult(result, "redefinition of 'ten'");
            result = engine.Evaluate("ten");
            AssertEqual(ConvertToInt(result), 15, "evaluation of redefined 'ten'");

            // Re-evaluate the expression which should now update based on new 'ten'.
            result = engine.Evaluate("expr");
            // Expected value: new ten (15) + twenty (20) equals 35.
            AssertEqual(ConvertToInt(result), 35, "evaluation of 'expr' after redefining 'ten'");

            // Test a boolean comparison expression.
            result = engine.Evaluate("(< ten twenty)");
            AssertEqual(ConvertToBool(result), true, "boolean comparison of 'ten' < 'twenty'");

            // Test another boolean expression.
            result = engine.Evaluate("(>= expr 35)");
            AssertEqual(ConvertToBool(result), true, "boolean comparison of 'expr' >= 35");
        }

