namespace YourNamespace
{
    public class ExtensionsParameterPassing
    {
        private HwndSource source;
        private IntPtr hwnd;
        private readonly Action<string[]> callback;

        public ExtensionsParameterPassing(Window window, Action<string[]> userCallback)
        {
            if (window == null)
                throw new ArgumentNullException(nameof(window));

            if (userCallback == null)
                throw new ArgumentNullException(nameof(userCallback));

            callback = userCallback;
            var helper = new WindowInteropHelper(window);
            hwnd = helper.Handle;

            AddHookParameterPassing(window);
        }

        private void AddHookParameterPassing(Window window)
        {
            var sourceParams = new HwndSourceParameters
            {
                HwndSourceHook = new HwndSourceHook(HandleMessages),
                WindowType = typeof(WindowsFormsHost),
                Width = 0,
                Height = 0,
                ParentWindow = hwnd
            };

            source = new HwndSource(sourceParams);
            source.AddHook(HandleMessages);
        }

        private IntPtr HandleMessages(IntPtr hwnd, int msg, IntPtr wParam, IntPtr lParam, ref bool handled)
        {
            if (msg == ParamPassing.WM_MyMessage)
            {
                string[] parameters = ProcessParameters(wParam, lParam);

                if (parameters != null && parameters.Length > 0)
                {
                    RestoreWindowState();
                    callback(parameters);
                    handled = true;
                }
            }
            return IntPtr.Zero;
        }

        private string[] ProcessParameters(IntPtr wParam, IntPtr lParam)
        {
            // Assume some conversion logic based on wParam and lParam
            string paramString = Marshal.PtrToStringUni(lParam);
            return paramString?.Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries);
        }

        private void RestoreWindowState()
        {
            Application.Current.Dispatcher.Invoke(() =>
            {
                var window = Application.Current.Windows.OfType<Window>().FirstOrDefault(w => new WindowInteropHelper(w).Handle == hwnd);
                if (window != null)
                {
                    window.WindowState = WindowState.Normal;
                    window.Activate();

