namespace MyApp.Web.Areas.Admin.Controllers
{
    public class AlbumController : BaseController
    {
        private readonly IAlbumService _albumService;
        private readonly IUserManagerService _userManagerService;

        public AlbumController(IAlbumService albumService, IUserManagerService userManagerService)
        {
            _albumService = albumService;
            _userManagerService = userManagerService;
        }

        public ActionResult Index()
        {
            return View(_albumService.GetAllAlbums().To<AlbumDetailsViewModel>());
        }

        [HttpGet]
        public ActionResult Add() => View();

        [HttpPost]
        [ValidateAntiForgeryToken]
        public ActionResult Add(AddAlbumViewModel model)
        {
            if (!ModelState.IsValid) return View(model);

            var album = model.To<Album>();
            album.CreatedBy = _userManagerService.GetCurrentUserId(User.Identity.Name);
            album.CreatedOn = DateTime.UtcNow;

            var result = _albumService.CreateAlbum(album);
            if (!result.Success)
            {
                ModelState.AddModelError("", result.ErrorMessage);
                return View(model);
            }

            Session["AlbumId"] = album.Id.ToString();
            return RedirectToAction("Details");
        }

        public ActionResult Details()
        {
            if (Session["AlbumId"] == null)
            {
                TempData["Error"] = "No album selected.";
                return RedirectToAction("Index");
            }

            if (!Guid.TryParse(Session["AlbumId"].ToString(), out Guid albumId))
            {
                TempData["Error"] = "Invalid album identifier.";
                return RedirectToAction("Index");
            }

            var album = _albumService.GetAlbumById(albumId);
            if (album == null)
            {
                TempData["Error"] = "Album not found.";
                return RedirectToAction("Index");
            }

            return View(album.To<AlbumDetailsViewModel>());
        }
    }

