        public SmokeTrailWhenDamaged(SmokeTrailWhenDamagedInfo info)
        {
            this.info = info;
            ticks = 0;
        }

        public void Init(Actor actor)
        {
            this.actor = actor;
        }

        public void Tick()
        {
            if (ShouldEmitSmoke())
            {
                EmitSmoke();
            }
            ticks++;
        }

        private bool ShouldEmitSmoke()
        {
            var body = actor.GetTrait<Health>();
            if (body == null) return false;

            return body.DamageState > info.MinDamage && actor.Position.Y > 10 && !IsObscured();
        }

        private void EmitSmoke()
        {
            var position = actor.Position + info.Offset.GetOffset(actor.GetFacing());
            var smokeEffect = new ParticleEffect(info.Sprite, position);
            GameWorld.Instance.AddEffect(smokeEffect);
        }

