using System;
using System.IO;
using System.Text;
 
public class StripBlockComments
{
    public static string readFile(string filename)
    {
        var reader = new StreamReader(filename);
        try
        {
            var fileContents = new StringBuilder();
            var buffer = new char[4096];
            while (reader.Read(buffer, 0, 4096) > 0)
            {
                fileContents.Append(buffer);
            }
            return fileContents.ToString();
        }
        finally
        {
            reader.Close();
        }
    }
 
    public static string stripComments(string beginToken, string endToken, string input)
    {
        var output = new StringBuilder();
        while (true)
        {
            int begin = input.IndexOf(beginToken);
            int end = input.IndexOf(endToken, begin + beginToken.Length);
            if (begin == -1 || end == -1)
            {
                output.Append(input);
                return output.ToString();
            }
            output.Append(input.Substring(0, begin));
            input = input.Substring(end + endToken.Length);
        }
    }
 
    public static void Main(string[] args)
    {
        if (args.Length < 3)
        {
            Console.WriteLine("Usage: BeginToken EndToken FileToProcess");
            Environment.Exit(1);
        }
 
        string begin = args[0];
        string end = args[1];
        string input = args[2];
 
        try
        {
            Console.WriteLine(stripComments(begin, end, readFile(input)));
        }
        catch (Exception e)
        {
            Console.WriteLine(e.ToString());
            Environment.Exit(1);
        }
    }
}

