namespace AutoJITRuntime
{
    public class ProcessService
    {
        // Launches a process with configurable parameters and returns its process Id.
        public static int ShellExecute(string exePath, string arguments, string workingDirectory, string verb, int windowState)
        {
            if (string.IsNullOrWhiteSpace(exePath))
            {
                throw new ArgumentException("Executable path cannot be null or empty.", nameof(exePath));
            }

            ProcessStartInfo startInfo = new ProcessStartInfo
            {
                FileName = exePath,
                Arguments = string.IsNullOrWhiteSpace(arguments) ? string.Empty : arguments,
                WorkingDirectory = string.IsNullOrWhiteSpace(workingDirectory) ? Environment.CurrentDirectory : workingDirectory
            };

            if (!string.IsNullOrWhiteSpace(verb))
            {
                startInfo.Verb = verb;
            }

            // Set window style based on numerical flag: 0=Hidden, 1=Minimized, 2=Maximized, default=Normal.
            switch (windowState)
            {
                case 0:
                    startInfo.WindowStyle = ProcessWindowStyle.Hidden;
                    break;
                case 1:
                    startInfo.WindowStyle = ProcessWindowStyle.Minimized;
                    break;
                case 2:
                    startInfo.WindowStyle = ProcessWindowStyle.Maximized;
                    break;
                default:
                    startInfo.WindowStyle = ProcessWindowStyle.Normal;
                    break;
            }

            try
            {
                Process process = new Process { StartInfo = startInfo };

                if (!process.Start())
                {
                    throw new ProcessLaunchException("Failed to start process.");
                }

                return process.Id;
            }
            catch (Win32Exception ex)
            {
                throw new ProcessLaunchException($"Win32 error launching process: {ex.Message}", ex);
            }
            catch (InvalidOperationException ex)
            {
                throw new ProcessLaunchException($"Invalid operation during process start: {ex.Message}", ex);
            }
        }

        // Starts a process with the given configuration, waits for it to finish, and returns its exit code.

