public class EditorOptionsResetService
{
    private readonly IGlobalOptionService _globalOptionService;
    private readonly IEditorOptionsFactoryService _editorOptionsFactory;

    public EditorOptionsResetService(
        IGlobalOptionService globalOptionService,
        IEditorOptionsFactoryService editorOptionsFactory)
    {
        _globalOptionService = globalOptionService;
        _editorOptionsFactory = editorOptionsFactory;
    }

    public async Task ResetGlobalOptionsAsync(CancellationToken cancellationToken)
    {
        await Task.Run(() =>
        {
            SetGlobalOption(OptionKey.CodeNavigationOptions, false);
            SetGlobalOption(OptionKey.AutoSuggestionMode, false);
            SetGlobalOption(OptionKey.IntelliSensePerformance, true);
        }, cancellationToken);
    }

    private void SetGlobalOption(OptionKey optionKey, bool value)
    {
        try
        {
            _globalOptionService.SetOption(optionKey, value);
        }
        catch (Exception ex)
        {
            // Log or handle option setting errors
            Console.WriteLine($"Option setting error: {ex.Message}");
        }
    }

    public async Task ResetHostSettingsAsync(ITextView textView, CancellationToken cancellationToken)
    {
        await Task.Run(() =>
        {
            var editorOptions = _editorOptionsFactory.GetOptions(textView);

            SetOptionValue(editorOptions, EditorOptionKey.CompletionMode, false);
            SetOptionValue(editorOptions, EditorOptionKey.WordWrap, false);
            SetOptionValue(editorOptions, EditorOptionKey.LineNumbering, true);
        }, cancellationToken);
    }

    private void SetOptionValue(IEditorOptions options, EditorOptionKey key, bool value)
    {
        if (options.IsOptionDefined(key))
        {
            options.SetOptionValue(key, value);
        }
    }
}

using Signum.Engine;
using Signum.Engine.Authorization;
using Signum.Engine.Rest;
using Signum.React.Filters;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;

public class ApiKeyAuthenticator : IAuthenticator
{
    public async Task<SignumAuthenticationResult> AuthenticateAsync(HttpRequestMessage request)
    {
        var queryParams = request.GetQueryNameValuePairs().ToLookup(p => p.Key);
        string queryKey = queryParams[RestApiKeyLogic.ApiKeyQueryParameter].FirstOrDefault()?.Value;

        request.Headers.TryGetValues(RestApiKeyLogic.ApiKeyHeaderParameter, out var headerValues);
        string headerKey = headerValues?.FirstOrDefault();

        if (!string.IsNullOrEmpty(queryKey) && !string.IsNullOrEmpty(headerKey))
            return new SignumAuthenticationResult { ErrorResult = new ErrorResult("Multiple API keys detected") };

        string apiKey = queryKey ?? headerKey;
        if (string.IsNullOrEmpty(apiKey))
            return null;

        using (AuthLogic.Disable())
        {
            var apiKeyEntity = RestApiKeyCache.GetApiKey(apiKey);
            if (apiKeyEntity == null || apiKeyEntity.IsExpired)
                return new SignumAuthenticationResult { ErrorResult = new ErrorResult("Invalid API key") };

            return new SignumAuthenticationResult { User = apiKeyEntity.User };
        }
    }
}

public static class RestServer
{
    public static void Start()
    {
        RestApiKeyLogic.Start();
        SignumAuthentication.Authenticators.Insert(0, new ApiKeyAuthenticator());
    }
}

public static class RestApiKeyLogic
{
    public static string ApiKeyQueryParameter = "apiKey";
    public static string ApiKeyHeaderParameter = "X-API-Key";

    public static void Start()
    {
        RestApiKeyCache.Initialize();
    }
}

public static class RestApiKeyCache
{
    private static readonly object _sync = new object();
    private static Dictionary<string, RestApiKeyEntity> _cache;

    public static void Initialize()
    {
        lock (_sync)
        {
            _cache = Database.Query<RestApiKeyEntity>()
                .Where(a => !a.IsExpired)
                .ToDictionary(a => a.ApiKey);
        }
    }

    public static RestApiKeyEntity GetApiKey(string apiKey)
    {
        lock (_sync)
        {
            return _cache.TryGetValue(apiKey, out var entity) ? entity : null;
        }
    }
}

public class RestApiKeyEntity : Entity
{
    public string ApiKey;
    public UserEntity User;
    public bool IsExpired;
}

