using System.Text;
using System.Threading.Tasks;
using System.Media;
namespace Morse_Code_Translator
{
    class Utils
    {
        static void Main(string[] args)
        {
            string inpt;
            char[] ascii = " ABCDEFGHIJKLMNOPQRSTUVWXYZ".ToCharArray();
            char[] lwcAscii = " abcdefghijklmnopqrstuvwxyz".ToCharArray();
            string[] morse = { "  ", ".- ", "-... ", "-.-. ", "-.. ", ". ", "..-. ", "--. ", ".... ", ".. ", ".--- ", "-.- ", ".-.. ", "-- ", "-. ", "--- ", ".--.", "--.- ", ".-. ", "... ", "- ", "..- ", "...- ", ".-- ", "-..- ", "-.-- ", "--.. " };
            string outpt = "";
            Console.WriteLine("Enter the text you want to translate");
            inpt = Console.ReadLine();
            int xx = 0;
            int size = inpt.Length;
            Console.WriteLine("Length:" + size);
            xx = 0;
            while (xx < inpt.Length)
            {
                int x = 0;
                bool working = false;
                while (!working)
                {
                    if (ascii[x]!= inpt[xx] && lwcAscii[x]!= inpt[xx])
                    {
                        x++;
                    }
                    else
                    {
                        working =!working;
                    }
                }
                Console.Write(morse[x]);
                outpt = outpt + morse[x];
                xx++;
            }
            xx = 0;
            while (xx < outpt.Length + 1)
            {
                if (outpt[xx] == '.')
                {
                    Console.Beep(1000, 250);
                }
                else
                {
                    if (outpt[xx] == '-')
                    {
                        Console.Beep(1000, 500);
                    }
                    else
                    {
                        if (outpt[xx] =='')
                        {
                            System.Threading.Thread.Sleep(500);
                        }
                    }
                }
                xx++;
            }
            Console.ReadKey();
        }
    }
}

