using Microsoft.AspNetCore.Identity;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

public class IdentityExtensions
{
    public static IServiceCollection UseSelfIdentity(this IServiceCollection services)
    {
        services.AddLogging();
        services.AddOptions();

        services.AddSingleton<IUserStore<AppUser>, UserStore<AppUser>>();
        services.AddSingleton<IRoleStore<AppUserRole>, RoleStore<AppUserRole>>();
        services.AddSingleton<IUserValidator<AppUser>, AppUserValidator>();
        services.AddSingleton<IPasswordValidator<AppUser>, AppUserPasswordValidator>();
        services.AddSingleton<IPasswordHasher<AppUser>, PasswordHasher<AppUser>>();
        services.AddSingleton<ILookupNormalizer, KeyNormalizer>();
        services.AddSingleton<IdentityErrorDescriber>();
        services.AddSingleton<IdentityOptions>(new IdentityOptions());

        services.AddSingleton<UserManager<AppUser>>(services => CreateUserManager(services));

        return services;
    }

    private static UserManager<AppUser> CreateUserManager(IServiceProvider services)
    {
        var optionsAccessor = services.GetRequiredService<IOptions<IdentityOptions>>();
        var userStore = services.GetRequiredService<IUserStore<AppUser>>();
        var passwordHasher = services.GetRequiredService<IPasswordHasher<AppUser>>();
        var userValidators = services.GetServices<IUserValidator<AppUser>>().ToList();
        var passwordValidators = services.GetServices<IPasswordValidator<AppUser>>().ToList();
        var keyNormalizer = services.GetRequiredService<ILookupNormalizer>();
        var errors = services.GetRequiredService<IdentityErrorDescriber>();
        var logger = services.GetRequiredService<ILogger<UserManager<AppUser>>>();

        return new UserManager<AppUser>(
            userStore,
            optionsAccessor,
            passwordHasher,
            userValidators,
            passwordValidators,
            keyNormalizer,
            errors,
            logger,
            null);
    }
}

