using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.FindSymbols;

public class FindReferencesSearchEngine
{
    private readonly Project _project;
    private readonly CancellationToken _cancellationToken;
    private readonly ConcurrentDictionary<Document, List<SymbolReference>> _documentMap;

    public FindReferencesSearchEngine(Project project, CancellationToken cancellationToken)
    {
        _project = project ?? throw new ArgumentNullException(nameof(project));
        _cancellationToken = cancellationToken;
        _documentMap = new ConcurrentDictionary<Document, List<SymbolReference>>();
    }

    public async Task<IEnumerable<SymbolReference>> ProcessProjectAsync()
    {
        var compilation = await _project.GetCompilationAsync(_cancellationToken);
        if (compilation == null)
        {
            throw new InvalidOperationException("Unable to obtain project compilation");
        }

        var documents = _project.Documents;
        var processingTasks = new List<Task>();

        foreach (var document in documents)
        {
            var processingTask = Task.Run(async () =>
            {
                await ProcessDocumentQueueAsync(document, compilation);
            }, _cancellationToken);

            processingTasks.Add(processingTask);
        }

        await Task.WhenAll(processingTasks);

        return MergeDocumentReferences();
    }

    private async Task ProcessDocumentQueueAsync(Document document, Compilation compilation)
    {
        try
        {
            var semanticModel = await document.GetSemanticModelAsync(_cancellationToken);
            var references = await SymbolFinder.FindReferencesAsync(
                document.Project.Solution.GetDocument(document.Id),
                compilation,
                _cancellationToken
            );

            _documentMap[document] = new List<SymbolReference>(references);
        }
        catch (OperationCanceledException)
        {
            // Handle cancellation gracefully
        }
    }

    private IEnumerable<SymbolReference> MergeDocumentReferences()
    {
        var mergedReferences = new List<SymbolReference>();
        foreach (var references in _documentMap.Values)
        {
            mergedReferences.AddRange(references);
        }
        return mergedReferences;
    }
}

