    /// <summary>
    /// Provides NCrypt-related types for interacting with Windows Cryptography Next Generation (CNG) APIs.
    /// </summary>
    public static class NCrypt
    {
        /// <summary>
        /// Enumerates standardized cryptographic interface identifiers for CNG providers.
        /// These values align with native API expectations and enable type-safe interoperability.
        /// </summary>
        public enum InterfaceIdentifiers : uint
        {
            /// <summary>Asymmetric encryption operations (e.g., RSA). Shared with BCrypt.</summary>
            NCRYPT_ASYMMETRIC_ENCRYPTION_INTERFACE = 0x00000003,

            /// <summary>Secret agreement protocols (e.g., ECDH). Shared with BCrypt.</summary>
            NCRYPT_SECRET_AGREEMENT_INTERFACE = 0x00000004,

            /// <summary>Digital signatures (e.g., ECDSA). Shared with BCrypt.</summary>
            NCRYPT_SIGNATURE_INTERFACE = 0x00000005,

            /// <summary>Symmetric encryption algorithms. Shared with BCrypt.</summary>
            NCRYPT_CIPHER_INTERFACE = 0x00000006,

            /// <summary>Hash function operations (e.g., SHA-256). Shared with BCrypt.</summary>
            NCRYPT_HASH_INTERFACE = 0x00000002,

            /// <summary>Random number generation. Shared with BCrypt.</summary>
            NCRYPT_RNG_INTERFACE = 0x00000007,

            /// <summary>Key storage and management via Key Storage Providers. NCrypt-specific.</summary>
            NCRYPT_KEY_STORAGE_INTERFACE = 0x00010001,

            /// <summary>Schannel protocol implementation (TLS/SSL). NCrypt-specific.</summary>
            NCRYPT_SCHANNEL_INTERFACE = 0x00010002,

            /// <summary>Key derivation functions (e.g., PBKDF2). NCrypt-specific.</summary>
            NCRYPT_KEY_DERIVATION_INTERFACE = 0x00010003,

            /// <summary>SSL protocol-specific cryptographic operations. NCrypt-specific.</summary>
            NCRYPT_SSL_INTERFACE = 0x00010004,

            /// <summary>Platform Crypto Provider (PCP) operations. NCrypt-specific.</summary>
            NCRYPT_PCP_INTERFACE = 0x00010005,

            /// <summary>Secure key policy enforcement and protection. NCrypt-specific.</summary>
            NCRYPT_KEY_PROTECTION_INTERFACE = 0x00010006,

            /// <summary>Secret agreement with key encapsulation. NCrypt-specific.</summary>
            NCRYPT_KEA_INTERFACE = 0x00010007
        }
    }
}

