using System;

// Structure representing an individual ring.
public struct Ring
{
    public int Size;
    public Ring(int size)
    {
        Size = size;
    }
}

// Class representing a column of rings.
public class Column
{
    // Array holding the rings; capacity is determined during initialization.
    public Ring[] Rings;

    // Private pointer (count) tracking the number of rings in this column.
    private int pointer;

    // Custom property to encapsulate pointer operations.
    public int Height
    {
        get { return pointer; }
        set { pointer = value; }
    }

    public Column(int capacity)
    {
        Rings = new Ring[capacity];
        pointer = 0;
    }
}

public class TowerOfHanoi
{
    // Initialize the source column with rings ordered by decreasing size.
    public static void Init(Column col, int maxHeight)
    {
        for (int i = 0; i < maxHeight; i++)
        {
            // Largest ring at the bottom, smallest at the top.
            col.Rings[i] = new Ring(maxHeight - i);
        }
        col.Height = maxHeight;
    }

    // Validate that rings in a column are in strictly decreasing order.
    public static void Validate(Column col)
    {
        for (int i = 0; i < col.Height - 1; i++)
        {
            if (col.Rings[i].Size <= col.Rings[i + 1].Size)
            {
                throw new Exception("Validation error: Larger ring on top of a smaller ring detected.");
            }
        }
    }

    // Helper method to move a single ring from one column to another.
    public static void MoveOne(Column fromCol, Column toCol)
    {
        if (fromCol.Height == 0)
        {
            throw new Exception("Cannot move from an empty column.");
        }

        // Get the top ring from the source column.
        Ring movingRing = fromCol.Rings[fromCol.Height - 1];

        // Check if move is allowed: either destination is empty or its top ring is larger.
        if (toCol.Height > 0)
        {
            Ring topDest = toCol.Rings[toCol.Height - 1];
            if (topDest.Size <= movingRing.Size)
            {
                throw new Exception("Invalid move: Cannot place larger ring on top of a smaller ring.");
            }
        }

        // Move the ring.
        fromCol.Height--;
        toCol.Rings[toCol.Height] = movingRing;
        toCol.Height++;

        // Validate both columns after the move.
        Validate(fromCol);
        Validate(toCol);
    }

    // Recursive method to move 'n' rings from one column to another using a spare column.

