using System;
using System.Linq.Expressions;
using Vulpecula.Scripting.Lexer;

namespace Vulpecula.Scripting.Parser
{
    public class EqualityExpression : ExpressionBase
    {
        private readonly ExpressionBase _expression;

        public EqualityExpression(TokenReader reader)
        {
            _expression = Parse(reader);
        }

        private ExpressionBase Parse(TokenReader reader)
        {
            var relational = new RelationalExpression(reader);
            if (VerifyAheadKeywords(reader, "==", "!="))
            {
                return new EqualityExpressionTail(reader, relational);
            }
            return relational;
        }

        private bool VerifyAheadKeywords(TokenReader reader, params string[] keywords)
        {
            return reader.HasNext && reader.Next.Raw.Trim() is var word && keywords.Any(w => w == word);
        }

        public override Expression AsExpressionTree()
        {
            throw new NotImplementedException();
        }
    }

    public class EqualityExpressionTail : ExpressionBase
    {
        private readonly string _type;
        private readonly ExpressionBase _expression;
        private readonly ExpressionBase _tail;

        public EqualityExpressionTail(TokenReader reader, ExpressionBase expression)
        {
            _type = AssertKeywordOr(reader, "==", "!=");
            _expression = expression;
            _tail = Parse(reader);
        }

        private static string AssertKeywordOr(TokenReader reader, params string[] keywords)
        {
            var token = reader.Next;
            if (keywords.All(w => w != token.Raw.Trim()))
            {
                throw new Exception();
            }
            reader.Read();
            return token.Raw.Trim();
        }

        private ExpressionBase Parse(TokenReader reader)
        {
            var relational = new RelationalExpression(reader);
            if (VerifyAheadKeywords(reader, "==", "!="))
            {
                return new EqualityExpressionTail(reader, relational);
            }
            return relational;
        }

        private bool VerifyAheadKeywords(TokenReader reader, params string[] keywords)
        {
            return reader.HasNext && reader.Next.Raw.Trim() is var word && keywords.Any(w => w == word);
        }

        public override Expression AsExpressionTree()
        {
            throw new NotImplementedException();
        }
    }
}

