    public static class MeshMeshCollider
    {
        public static bool CheckContact(TriangleMesh3 meshA, TriangleMesh3 meshB)
        {
            // TODO: Use spatial acceleration (BVH/spatial grid) for optimization
            for (int i = 0; i < meshA.Indices.Length; i += 3)
            {
                Vector3[] triangleA = GetTriangle(meshA, i);
                for (int j = 0; j < meshB.Indices.Length; j += 3)
                {
                    Vector3[] triangleB = GetTriangle(meshB, j);
                    if (TriangleIntersects(triangleA, triangleB))
                        return true;
                }
            }
            return false;
        }

        public static Vector3? FindContact(TriangleMesh3 meshA, TriangleMesh3 meshB)
        {
            for (int i = 0; i < meshA.Indices.Length; i += 3)
            {
                Vector3[] triangleA = GetTriangle(meshA, i);
                for (int j = 0; j < meshB.Indices.Length; j += 3)
                {
                    Vector3[] triangleB = GetTriangle(meshB, j);
                    if (TriangleIntersects(triangleA, triangleB))
                    {
                        // Placeholder: Return centroid of first intersecting triangles
                        return (triangleA[0] + triangleA[1] + triangleA[2] +
                                triangleB[0] + triangleB[1] + triangleB[2]) / 6.0f;
                    }
                }
            }
            return null;
        }

        private static Vector3[] GetTriangle(TriangleMesh3 mesh, int indexOffset)
        {
            return new Vector3[]
            {
                mesh.Vertices[mesh.Indices[indexOffset]],
                mesh.Vertices[mesh.Indices[indexOffset + 1]],
                mesh.Vertices[mesh.Indices[indexOffset + 2]]
            };
        }

