Using System;
class Game
{
    static int gcd(int m, int n)
    {
        return n == 0 ? Math.Abs(m) : gcd(n, n % m);
    }
    static int lcm(int m, int n)
    {
        return Math.Abs(m * n) / gcd(m, n);
    }
    static void Main()
    {
        Console.WriteLine("lcm(12,18)=" + lcm(12,18));
    }
}

using Castle.DynamicProxy;
using Glass.Sitecore.Mapper.Configuration;
using System;

public class ProxyGenerator
{
    private readonly ProxyGenerator _generator;
    private readonly ProxyGenerationOptions _options;

    public ProxyGenerator()
    {
        _generator = new ProxyGenerator();
        _options = new ProxyGenerationOptions(new ProxyGeneratorHook());
    }

    public object CreateProxy(SitecoreClassConfig config, ISitecoreService service, Sitecore.Data.Items.Item item, bool inferType)
    {
        Type targetType = inferType ? config.Type : item.Paths.FullPath.GetType();

        if (targetType.IsInterface)
        {
            return _generator.CreateInterfaceProxyWithoutTarget(
                targetType,
                new InterfaceMethodInterceptor(config, service, item)
            );
        }
        else
        {
            return _generator.CreateClassProxy(
                targetType,
                _options,
                new ProxyClassInterceptor(config, service, item)
            );
        }
    }
}

public class ProxyGeneratorHook : IProxyGenerationHook
{
    public void MethodsInspected()
    {
    }

    public void NonProxyableMemberNotification(Type type, MemberInfo memberInfo)
    {
    }

    public bool ShouldInterceptMethod(Type type, MethodInfo methodInfo)
    {
        return true;
    }
}

public class InterfaceMethodInterceptor : IInterceptor
{
    private readonly SitecoreClassConfig _config;
    private readonly ISitecoreService _service;
    private readonly Sitecore.Data.Items.Item _item;

    public InterfaceMethodInterceptor(SitecoreClassConfig config, ISitecoreService service, Sitecore.Data.Items.Item item)
    {
        _config = config;
        _service = service;
        _item = item;
    }

    public void Intercept(IInvocation invocation)
    {
        var propertyInfo = _config.Properties.Find(p => p.PropertyInfo.Name == invocation.Method.Name.Substring(4));
        if (propertyInfo != null)
        {
            invocation.ReturnValue = _service.GetItem<Sitecore.Data.Items.Item>(_item.ID)[propertyInfo.PropertyInfo.Name];
        }
        else
        {
            invocation.Proceed();
        }
    }
}

