    public interface IJsonParser<T> where T : JsonSchema, new()
    {
        IEnumerable<T> Parse(string jsonData, string elementsPath);
    }

    public class JsonDataProvider<T> : DataProviderBase<T> where T : JsonSchema, new()
    {
