        {
            ValidateConfiguration();

            using (var httpClient = new HttpClient())
            {
                HttpResponseMessage response;
                try
                {
                    response = await httpClient.GetAsync(_config.Uri);
                }
                catch (HttpRequestException ex)
                {
                    throw new RequestFailedException("HTTP request failed", ex);
                }

                if (!response.IsSuccessStatusCode)
                {
                    throw new RequestFailedException($"HTTP error: {response.StatusCode}");
                }

                var jsonString = await response.Content.ReadAsStringAsync();

                try
                {
                    return _parser.Parse(jsonString, _config.ElementsPath);
                }
                catch (System.Exception ex)
                {
                    throw new ParsingFailedException("JSON parsing failed", ex);
                }
            }
        }

