                throw new ConfigurationValidationException("URI must be configured");
            }

            if (string.IsNullOrWhiteSpace(_config.ElementsPath))
            {
                throw new ConfigurationValidationException("JSON elements path must be specified");
            }

            if (_parser == null)
            {

