public static class ModelExtensions
{
    public static IEnumerableExpression<IModelElement> Descendants(this IModelElement element)
    {
        return new DescendantsCollection(element);
    }

    public static void Serialize(this IModelSerializer serializer, IModelElement element, string filePath)
    {
        if (serializer == null) throw new ArgumentNullException(nameof(serializer));
        if (element == null) throw new ArgumentNullException(nameof(element));
        if (string.IsNullOrEmpty(filePath)) throw new ArgumentException("File path cannot be null or empty.", nameof(filePath));

        var model = element.GetModel();
        if (model != null && model.Uri == null)
        {
            model.Uri = new Uri(Path.GetFullPath(filePath));
        }

        using (var stream = new FileStream(filePath, FileMode.Create, FileAccess.Write))
        {
            serializer.Serialize(model ?? new Model { element }, stream);
        }
    }

    public static void Serialize(this IModelSerializer serializer, IModelElement element, Stream stream, Uri uri)
    {
        if (serializer == null) throw new ArgumentNullException(nameof(serializer));
        if (element == null) throw new ArgumentNullException(nameof(element));
        if (stream == null) throw new ArgumentNullException(nameof(stream));
        if (uri == null) throw new ArgumentNullException(nameof(uri));

        var model = element.GetModel();
        if (model != null && model.Uri == null)
        {
            model.Uri = uri;
        }

        serializer.Serialize(model ?? new Model { element }, stream);
    }

    private static Model GetModel(this IModelElement element)
    {
        while (element != null)
        {
            if (element is Model model)
            {
                return model;
            }
            element = element.Owner;
        }
        return null;
    }
}

internal class DescendantsCollection : IEnumerableExpression<IModelElement>
{
    private readonly IModelElement _element;

    public DescendantsCollection(IModelElement element)
    {
        _element = element ?? throw new ArgumentNullException(nameof(element));
    }

    public IEnumerator<IModelElement> GetEnumerator()
    {
        return DescendantsEnumerator(_element);
    }

    System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator()
    {
        return DescendantsEnumerator(_element);
    }

