namespace DistributedDb.Client
{
    // Base policy class providing common execution parameters.
    public abstract class Policy
    {
        // Maximum number of automatic retries.
        public int MaxRetries { get; set; }

        // Base constructor with a default retry setting.
        protected Policy()
        {
            MaxRetries = 3; // Default retry count for general operations.
        }
    }

    // QueryPolicy manages settings specific to query operations.
    public class QueryPolicy : Policy
    {
        // Maximum number of server nodes to query concurrently.
        public int ConcurrentNodes { get; set; }

        // Capacity of the internal queue for buffering returned records.
        public int RecordQueueSize { get; set; }

        // Default constructor initializes with default parameters.
        public QueryPolicy() : base()
        {
            // Set a default for concurrent node queries.
            ConcurrentNodes = 4;
            // Set a default buffering capacity for query results.
            RecordQueueSize = 1000;
            // Disable automatic query retries.
            MaxRetries = 0;
        }

        // Parameterized constructor for custom configurations.
        public QueryPolicy(int concurrentNodes, int recordQueueSize) : base()
        {
            ConcurrentNodes = concurrentNodes;
            RecordQueueSize = recordQueueSize;
            // Enforce no retries for query operations.
            MaxRetries = 0;
        }

        // Override ToString for easy policy state debugging.
        public override string ToString()
        {
            return $"QueryPolicy -> ConcurrentNodes: {ConcurrentNodes}, RecordQueueSize: {RecordQueueSize}, MaxRetries: {MaxRetries}";
        }
    }

