public interface IEntityMapper { }

public interface IAllAssemblyFinder
{
    IEnumerable<Assembly> FindAll();
}

public interface IEntityMapperAssemblyFinder
{
    IEnumerable<Assembly> Find(Func<Assembly, bool> predicate = null);
}

public class DirectoryAssemblyFinder : IAllAssemblyFinder
{
    private readonly string _directory;

    public DirectoryAssemblyFinder(string directory)
    {
        _directory = directory ?? throw new ArgumentNullException(nameof(directory));
    }

    public IEnumerable<Assembly> FindAll()
    {
        if (!Directory.Exists(_directory))
            return Enumerable.Empty<Assembly>();

        var assemblyFiles = Directory.GetFiles(_directory, "*.dll");
        var loadedAssemblies = new List<Assembly>();

        foreach (var assemblyPath in assemblyFiles)
        {
            try
            {
                var assembly = Assembly.LoadFrom(assemblyPath);
                loadedAssemblies.Add(assembly);
            }
            catch (Exception)
            {
                // Optional: logging or error handling
            }
        }

        return loadedAssemblies;
    }
}

public class EntityMapperAssemblyFinder : IEntityMapperAssemblyFinder
{
    private readonly IAllAssemblyFinder _assemblyFinder;

    public EntityMapperAssemblyFinder(IAllAssemblyFinder assemblyFinder)
    {
        _assemblyFinder = assemblyFinder ?? throw new ArgumentNullException(nameof(assemblyFinder));
    }

    public IEnumerable<Assembly> Find(Func<Assembly, bool> predicate = null)
    {
        var allAssemblies = _assemblyFinder.FindAll();
        var entityMapperAssemblies = allAssemblies
            .Where(assembly => HasEntityMapperTypes(assembly))
            .ToList();

        return predicate != null
            ? entityMapperAssemblies.Where(predicate)
            : entityMapperAssemblies;
    }

    private bool HasEntityMapperTypes(Assembly assembly)
    {
        try
        {
            var entityMapperTypes = assembly.GetTypes()
                .Where(type => typeof(IEntityMapper).IsAssignableFrom(type) &&
                               !type.IsInterface &&
                               !type.IsAbstract)
                .ToList();

            return entityMapperTypes.Any();
        }
        catch (ReflectionTypeLoadException)
        {
            return false;
        }
    }
}

using System;
