public class Converter
{
    public static string[] Convert(string input)
    {
        // Validate input
        if (string.IsNullOrWhiteSpace(input))
        {
            return new string[] { "Invalid input: Path is empty." };
        }

        List<string> results = new List<string>();
        string[] parts = input.Split(new char[] { '/', '\\' }, StringSplitOptions.RemoveEmptyEntries);

        // Handle drive letters for Windows paths
        string drive = string.Empty;
        if (input.Length >= 2 && char.IsLetter(input[0]) && input[1] == ':')
        {
            drive = $"{input[0]}:";
        }

        // Build formatted paths
        results.Add(FormatWindowsPath(input, drive));
        results.Add(FormatUnixPath(input));
        results.Add(FormatDoubleBackslashPath(input, drive));
        results.Add(FormatRootedPath(input, drive));

        return results.ToArray();
    }

    private static string FormatWindowsPath(string input, string drive)
    {
        // Replace '/' with '\' for Windows format
        string formattedPath = input.Replace('/', '\\');

        // Ensure the drive is properly included
        if (!string.IsNullOrEmpty(drive) && !formattedPath.StartsWith(drive))
        {
            formattedPath = drive + "\\" + formattedPath.TrimStart('\\');
        }

        return formattedPath;
    }

    private static string FormatUnixPath(string input)
    {
        // Simply replace '\' with '/' for Unix format
        return input.Replace('\\', '/');
    }

    private static string FormatDoubleBackslashPath(string input, string drive)
    {
        // Replace '/' with '\\\\' for double backslash windows format
        string formattedPath = input.Replace('/', '\\');
        formattedPath = formattedPath.Replace('\\', "\\\\");

        // Ensure the drive is properly included
        if (!string.IsNullOrEmpty(drive) && !formattedPath.StartsWith(drive))
        {
            formattedPath = drive + "\\" + formattedPath.TrimStart('\\');
        }

        return formattedPath;
    }

    private static string FormatRootedPath(string input, string drive)
    {
        // Ensure a Unix-style root path is correctly formatted
        if (input.StartsWith("\\") || input.StartsWith("/"))
        {
            return input.Replace('\\', '/').TrimStart('/');
        }

        // If there's a valid drive, include it
        if (!string.IsNullOrEmpty(drive))
        {
            return drive + "/"+ input.Replace('\\', '/').TrimStart('/');
        }

