public class SkipExpressionNode : IExpressionNode
{
    private readonly int _count;

    public SkipExpressionNode(int count)
    {
        if (count < 0)
            throw new ArgumentOutOfRangeException(nameof(count), "Count must be non-negative.");

        _count = count;
    }

    public void Resolve(QueryModel queryModel, ClauseGenerationContext clauseGenerationContext)
    {
        ApplyNodeSpecificSemantics(queryModel);
    }

    private void ApplyNodeSpecificSemantics(QueryModel queryModel)
    {
        var lastClause = queryModel.ResultOperators.LastOrDefault();
        if (lastClause is SkipTakeClause skipTakeClause)
        {
            skipTakeClause.SkipCount += _count;
        }
        else
        {
            queryModel.ResultOperators.Add(new SkipTakeClause(_count, 0));
        }
    }
}

public class SkipTakeClause : ResultOperatorBase
{
    public int SkipCount { get; }

    public SkipTakeClause(int skipCount, int takeCount)
    {
        SkipCount = skipCount;
        // Assume takeCount is handled elsewhere
    }

    public override ResultOperatorBase Clone(CloneContext cloneContext)
    {
        return new SkipTakeClause(SkipCount, 0);
    }

    protected override void Invoke(DataReaderContext context)
    {
        // Logic to perform skip on the data reader context will go here
    }
}

