using System;
 
public class Builder
{
    public static void Main()
    {
        int[] years = new int[] {1935,1938,1968,1972,1976,2017};
        //the zodiac cycle didnt start until 4 CE, so years <4 shouldnt be valid
        for(int i=0;i<6;i++)
        {
            Console.WriteLine(years[i] + " is the year of the " + getElement(years[i]) + " " + getAnimal(years[i]) + " (" + getYY(years[i]) + ").");
        }
    }
    public static string getElement(int year)
    {
        int element = (int)Math.Floor((year-4)%10/2);
        string[] elements = new string[] {"Wood","Fire","Earth","Metal","Water"};
        return elements[element];
    }
    public static string getAnimal(int year)
    {
        string[] animals = new string[] {"Rat","Ox","Tiger","Rabbit","Dragon","Snake","Horse","Goat","Monkey","Rooster","Dog","Pig"};
        return animals[(year-4)%12];
    }
    public static string getYY(int year)
    {
        if(year%2==0)
        {
            return "yang";
        }
        else
        {
            return "yin";
        }
    }
}

