using AgentMulder.ReSharper.Domain.Patterns;
using AgentMulder.ReSharper.Domain.Registrations;
using JetBrains.ReSharper.Feature.Services.CSharp.StructuralSearch;
using JetBrains.ReSharper.Feature.Services.StructuralSearch.Placeholders;
using JetBrains.ReSharper.Psi;
using JetBrains.ReSharper.Psi.CSharp.Tree;
using JetBrains.ReSharper.Psi.Tree;

public class InNamespaceString : IRegistrationPattern
{
    private static readonly IStructuralSearchPattern pattern =
        new CSharpStructuralSearchPattern("$builder$.InNamespace($argument$)");

    public InNamespaceString()
    {
    }

    public bool CanHandle(ITypeElement typeElement)
    {
        return typeElement.GetClrName().FullName == "Autofac.ContainerBuilder";
    }

    public IRegistration CreateRegistration(ITreeNode node, IHighlighter highlighter)
    {
        var methodCallExpression = node as IInvocationExpression;
        if (methodCallExpression == null)
            return null;

        var argument = methodCallExpression.ArgumentList.Arguments.FirstOrDefault();
        if (argument == null)
            return null;

        var constantValue = argument.Value as IConstantExpression;
        if (constantValue == null)
            return null;

        var namespaceName = constantValue.ConstantValue.Value as string;
        if (namespaceName == null)
            return null;

        return new NamespaceRegistration(namespaceName, highlighter);
    }

    public IStructuralSearchPattern Pattern
    {
        get { return pattern; }
    }
}

