using System;
using System.Configuration;

public interface IKeyedConfigurationElement<out TKey>
{
    TKey Key { get; }
}

public class NameObjectConfigurationElement<TValue> : ConfigurationElement, IKeyedConfigurationElement<string>
{
    private static readonly ConfigurationProperty NameProperty =
        new ConfigurationProperty(
            "name",
            typeof(string),
            null,
            ConfigurationPropertyOptions.IsRequired | ConfigurationPropertyOptions.IsKey);

    private static readonly ConfigurationProperty ValueProperty =
        new ConfigurationProperty(
            "value",
            typeof(TValue),
            default(TValue));

    private string _name;
    private TValue _value;
    private bool _nameSet;
    private bool _valueSet;

    protected override ConfigurationPropertyCollection Properties
    {
        get
        {
            ConfigurationPropertyCollection properties = new ConfigurationPropertyCollection();
            properties.Add(NameProperty);
            properties.Add(ValueProperty);
            return properties;
        }
    }

    public string Name
    {
        get
        {
            if (_nameSet)
            {
                return _name;
            }
            return (string)base[NameProperty];
        }
        set
        {
            _name = value;
            _nameSet = true;
        }
    }

    public TValue Value
    {
        get
        {
            if (_valueSet)
            {
                return _value;
            }
            return (TValue)base[ValueProperty];
        }
        set
        {
            _value = value;
            _valueSet = true;
        }
    }

    string IKeyedConfigurationElement<string>.Key
    {
        get { return Name; }
    }
}

