namespace DictionaryApp
{
    // Domain-specific search index object.
    public class SearchIndex
    {
        public string Content { get; set; }

        public SearchIndex(string content)
        {
            Content = content;
        }

        public void Display()
        {
            Console.WriteLine("SearchIndex Content: " + Content);
        }
    }

    // Lightweight cache for search index objects using weak references.
    public class SearchIndexCache
    {
        private Dictionary<string, WeakReference<SearchIndex>> cache;

        public SearchIndexCache()
        {
            cache = new Dictionary<string, WeakReference<SearchIndex>>();
        }

        // Retrieve a search index by its identifier.
        public SearchIndex Get(string identifier)
        {
            if (cache.TryGetValue(identifier, out WeakReference<SearchIndex> weakRef))
            {
                if (weakRef.TryGetTarget(out SearchIndex index))
                {
                    return index;
                }
                else
                {
                    // Remove stale reference.
                    cache.Remove(identifier);
                }
            }
            return null;
        }

        // Add or update the cache with a given search index.
        public void AddOrUpdate(string identifier, SearchIndex index)
        {
            if (cache.ContainsKey(identifier))
            {
                cache[identifier] = new WeakReference<SearchIndex>(index);
            }
            else
            {
                cache.Add(identifier, new WeakReference<SearchIndex>(index));
            }
        }
    }

    // Main program demonstrating the caching mechanism.
    public class Builder
    {
        public static void Main(string[] args)
        {
            SearchIndexCache indexCache = new SearchIndexCache();

            // Create and add search index objects to the cache.
            SearchIndex index1 = new SearchIndex("Content for File1");
            indexCache.AddOrUpdate("File1", index1);

            SearchIndex index2 = new SearchIndex("Content for File2");
            indexCache.AddOrUpdate("File2", index2);

            // Retrieve and display a cached search index.
            SearchIndex cachedIndex = indexCache.Get("File1");
            if (cachedIndex != null)
            {
                cachedIndex.Display();
            }
            else
            {
                Console.WriteLine("Index for File1 not found or has been garbage collected.");

