public class ShellExecuteException : Exception
{
    public ShellExecuteException(string message) : base(message) { }
}

public class ProcessService
{
    public int ShellExecute(string filename, string arguments = "", string workingDirectory = "",
                            string verb = null, ProcessWindowStyle windowStyle = ProcessWindowStyle.Normal)
    {
        var startInfo = new ProcessStartInfo
        {
            FileName = filename,
            Arguments = arguments,
            WorkingDirectory = workingDirectory,
            Verb = verb,
            WindowStyle = windowStyle
        };

        try
        {
            using (var process = Process.Start(startInfo))
            {
                if (process == null)
                {
                    throw new ShellExecuteException($"Failed to start process: {filename}");
                }
                return process.Id;
            }
        }
        catch (Exception ex)
        {
            throw new ShellExecuteException($"Error executing process: {ex.Message}");
        }
    }

    public int ShellExecuteWait(string filename, string arguments = "", string workingDirectory = "",
                                 string verb = null, ProcessWindowStyle windowStyle = ProcessWindowStyle.Normal)
    {
        var startInfo = new ProcessStartInfo
        {
            FileName = filename,
            Arguments = arguments,
            WorkingDirectory = workingDirectory,
            Verb = verb,
            WindowStyle = windowStyle
        };

        try
        {
            using (var process = Process.Start(startInfo))
            {
                if (process == null)
                {
                    throw new ShellExecuteException($"Failed to start process: {filename}");
                }

                process.WaitForExit();
                return process.ExitCode;
            }
        }
        catch (Exception ex)
        {
            throw new ShellExecuteException($"Error executing process: {ex.Message}");
        }
    }

