public class EngineExtend : Engine
{
    private List<Organism> organisms = new List<Organism>();

    public override void ExecuteBirthCommand(string command)
    {
        string[] parts = command.Split(' ');
        if (parts.Length < 3)
        {
            base.ExecuteBirthCommand(command);
            return;
        }

        string type = parts[1].ToLower();
        string name = parts[2];
        Point location = Point.Parse(parts[3]);

        Organism newOrganism = null;

        switch (type)
        {
            case "wolf":
                newOrganism = new Wolf(name, location);
                break;
            case "lion":
                newOrganism = new Lion(name, location);
                break;
            case "grass":
                newOrganism = new Grass(name, location);
                break;
            case "boar":
                newOrganism = new Boar(name, location);
                break;
            case "zombie":
                newOrganism = new Zombie(name, location);
                break;
            default:
                base.ExecuteBirthCommand(command);
                return;
        }

        if (newOrganism != null)
        {
            AddOrganism(newOrganism);
        }
    }

    private void AddOrganism(Organism organism)
    {
        organisms.Add(organism);
        Console.WriteLine($"Created {organism.GetType().Name}: {organism.Name} at {organism.Location}");
    }
}

public struct Point
{
    public int X { get; set; }
    public int Y { get; set; }

    public static Point Parse(string locationString)
    {
        string[] coords = locationString.Split(',');
        return new Point
        {
            X = int.Parse(coords[0]),
            Y = int.Parse(coords[1])
        };

        public override string ToString() => $"({X},{Y})";
    }
}

