        mockMediator.Setup(m => m.Send(It.IsAny<GetContestantAttemptsQuery>(), default))
            .ReturnsAsync(new List<ContestantAttempt> { new ContestantAttempt() });

        var controller = new ContestantsController(mockMediator.Object);
        var result = await controller.GetContestantsAttempts(Guid.NewGuid().ToString());

        Assert.IsType<OkObjectResult>(result);
    }

    [Fact]
    public async Task ReturnsHttp404NotFoundResultWhenNoContestantHasNoAttempts()
    {
        var mockMediator = new Mock<IMediator>();
        mockMediator.Setup(m => m.Send(It.IsAny<GetContestantAttemptsQuery>(), default))
            .ReturnsAsync(new List<ContestantAttempt>());

        var controller = new ContestantsController(mockMediator.Object);
        var result = await controller.GetContestantsAttempts(Guid.NewGuid().ToString());

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
