public class ContestantsController : ControllerBase
{
    private readonly IMediator _mediator;
    public ContestantsController(IMediator mediator) => _mediator = mediator;

    [HttpGet("api/contestants/{contestantId}/attempts")]
    public async Task<IActionResult> GetContestantsAttempts(string contestantId)
    {
        if (!Guid.TryParse(contestantId, out _)) return BadRequest();

        var attempts = await _mediator.Send(new GetContestantAttemptsQuery { ContestantId = contestantId });
        return attempts?.Count > 0 ? Ok(attempts) : NotFound();
    }
}

