        {
            _noteRepository = noteRepository;
        }

        // GET: Note
        public ActionResult Index()
        {
            return View();
        }

        // POST: Note/Add
        [HttpPost]
        public JsonResult Add(Note note)
        {
            if (note == null)
            {
                return Json(new { success = false, message = "Note data is null." });
            }
            if (string.IsNullOrWhiteSpace(note.Content))
            {
                return Json(new { success = false, message = "Note content cannot be empty." });
            }

            bool result = _noteRepository.Add(note);
            if (result)
            {
                return Json(new { success = true, message = "Note added successfully." });
            }
            else
            {
                return Json(new { success = false, message = "Failed to add note." });
            }
        }

        // POST: Note/Remove
        [HttpPost]
        public JsonResult Remove(int id)
        {
            if (id <= 0)
            {
                return Json(new { success = false, message = "Invalid note identifier." });
            }

            bool result = _noteRepository.Remove(id);
            if (result)
            {
                return Json(new { success = true, message = "Note removed successfully." });
            }
            else
            {
                return Json(new { success = false, message = "Failed to remove note." });
            }
        }

