using System;
 
public class McNuggets
{
   public static void Main()
   {
      bool[] isMcNuggetNumber = new bool[101];
 
      for (int x = 0; x <= 100/6; x++)
      {
         for (int y = 0; y <= 100/9; y++)
         {
            for (int z = 0; z <= 100/20; z++)
            {
               int mcNuggetNumber = x*6 + y*9 + z*20;
               if (mcNuggetNumber <= 100)
               {
                  isMcNuggetNumber[mcNuggetNumber] = true;
               }
            }
         }
      }
 
      for (int mnnCheck = isMcNuggetNumber.Length-1; mnnCheck >= 0; mnnCheck--)
      {
         if (!isMcNuggetNumber[mnnCheck])
         {
            Console.WriteLine("Largest non-McNuggett Number less than 100: " + mnnCheck.ToString());
            break;
         }
      }
   }
}

using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.CodeFixes;
using Microsoft.CodeAnalysis;
using System.Collections.Generic;
using System.Threading;

namespace CodeAnalysisEnhancements
{
    public class PropertyDeclarationStructureProvider : AbstractSyntaxNodeStructureProvider<PropertyDeclarationSyntax>
    {
        public override void CollectBlockSpans(
            PropertyDeclarationSyntax propertyDeclaration,
            List<BlockSpan> spans,
            OptionSet optionProvider,
            CancellationToken cancellationToken)
        {
            if (propertyDeclaration == null)
                return;

            // Collect comment-related spans
            CollectCommentSpans(propertyDeclaration, spans);

            // Evaluate accessors
            if (IsValidAccessorList(propertyDeclaration.AccessorList))
            {
                var span = CreateBlockSpan(propertyDeclaration);
                spans.Add(span);
            }
        }

        private void CollectCommentSpans(PropertyDeclarationSyntax propertyDeclaration, List<BlockSpan> spans)
        {
            if (propertyDeclaration.GetLeadingTrivia().Any(trivia => trivia.IsKind(SyntaxKind.SingleLineCommentTrivia)))
            {
                var span = new BlockSpan()
                {
                    TextSpan = propertyDeclaration.Span,
                    IsCollapsible = true,
                    IsDefaultCollapsed = false
                };
                spans.Add(span);
            }
        }

        private bool IsValidAccessorList(AccessorListSyntax accessorList)
        {
            return accessorList != null && accessorList.Accessors.Count > 0;
        }

        private BlockSpan CreateBlockSpan(PropertyDeclarationSyntax propertyDeclaration)
        {
            var span = new BlockSpan()
            {
                TextSpan = propertyDeclaration.Span,
                IsCollapsible = true,
                IsDefaultCollapsed = true,
                HintSpan = propertyDeclaration.Span,
                AutoCollapse = true
            };
            return span;
        }
    }

    public abstract class AbstractSyntaxNodeStructureProvider<T> where T : SyntaxNode
    {
        public abstract void CollectBlockSpans(T node, List<BlockSpan> spans, OptionSet optionProvider, CancellationToken cancellationToken);
    }

    public struct BlockSpan
    {
        public TextSpan TextSpan { get; set; }
        public bool IsCollapsible { get; set; }
        public bool IsDefaultCollapsed { get; set; }

