using Jolt.Test.Types;
using NUnit.Framework;

namespace Jolt.Test
{
    [TestFixture]
    public sealed class ConvertTestFixture
    {

        /// <summary>
        /// Verifies the behavior of the ToXmlDocCommentMember() method
        /// when the given parameter is a Type object.
        /// </summary>
        [Test]
        public void ToXmlDocCommentMember_Type()
        {
            Assert.That(Convert.ToXmlDocCommentMember(typeof(int)), Is.EqualTo("T:System.Int32"));
            Assert.That(Convert.ToXmlDocCommentMember(typeof(System.Xml.XmlDocument)), Is.EqualTo("T:System.Xml.XmlDocument"));
            Assert.That(Convert.ToXmlDocCommentMember(GetType()), Is.EqualTo("T:Jolt.Test.ConvertTestFixture"));

            Assert.That(
                Convert.ToXmlDocCommentMember(typeof(System.Net.WebRequestMethods.File)),
                Is.EqualTo("T:System.Net.WebRequestMethods.File"));
        }

        /// <summary>
        /// Verifies the behavior of the ToXmlDocCommentMember() method
        /// when the given parameter is a Type object representing a generic
        /// type.
        /// </summary>
        [Test]
        public void ToXmlDocCommentMember_Type_Generic()
        {
            Assert.That(Convert.ToXmlDocCommentMember(typeof(System.Action<,,,>)), Is.EqualTo("T:System.Action`4"));
            Assert.That(Convert.ToXmlDocCommentMember(typeof(__GenericTestType<int, char, byte>)), Is.EqualTo("T:Jolt.Test.Types.__GenericTestType`3"));

            Assert.That(
                Convert.ToXmlDocCommentMember(typeof(System.Collections.Generic.List<>)),
                Is.EqualTo("T:System.Collections.Generic.List`1"));

            Assert.That(
                Convert.ToXmlDocCommentMember(typeof(System.Collections.Generic.List<>.Enumerator)),
                Is.EqualTo("T:System.Collections.Generic.List`1.Enumerator"));
        }

        /// <summary>
        /// Verifies the behavior of the ToXmlDocCommentMember() method
        /// when the given parameter is an EventInfo object.
        /// </summary>
        [Test]
        public void ToXmlDocCommentMember_Event()
        {
            Assert.That(
                Convert.ToXmlDocCommentMember(__GenericTestType<int, int, int>.InstanceEvent),
                Is.EqualTo("E:Jolt.Test.Types.__GenericTestType`3._InstanceEvent"));

            Assert.That(
                Convert.ToXmlDocCommentMember(typeof(System.Console).GetEvent("CancelKeyPress")),
                Is.EqualTo("E:System.Console.CancelKeyPress"));
        }

using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;

namespace PropertyInspectorDemo
{
    public interface ITypeInspector
    {
        IEnumerable<PropertyInfo> GetProperties(Type type, object container);
    }

    public abstract class TypeInspectorSkeleton : ITypeInspector
    {
        public abstract IEnumerable<PropertyInfo> GetProperties(Type type, object container);
    }

    public sealed class WritablePropertyInspector : TypeInspectorSkeleton
    {
        private readonly ITypeInspector innerInspector;

        public WritablePropertyInspector(ITypeInspector innerInspector)
        {
            this.innerInspector = innerInspector;
        }

        public override IEnumerable<PropertyInfo> GetProperties(Type type, object container)
        {
            // Retrieve all properties using the inner inspector.
            IEnumerable<PropertyInfo> allProperties = innerInspector.GetProperties(type, container);
            // Filter out any property that does not support writing by checking the CanWrite flag.
            return allProperties.Where(prop => prop.CanWrite);
        }
    }

    // A default inspector that uses reflection to return public instance properties.
    public class DefaultTypeInspector : ITypeInspector
    {
        public IEnumerable<PropertyInfo> GetProperties(Type type, object container)
        {
            return type.GetProperties(BindingFlags.Public | BindingFlags.Instance);
        }
    }

    // A sample class to demonstrate property inspection.
    public class SampleClass
    {
        public string EditableProperty { get; set; }
        public int ReadOnlyProperty { get; }
        public double PrivateSetterProperty { get; private set; }

        public SampleClass()
        {
            EditableProperty = "Initial";
            ReadOnlyProperty = 42;
            PrivateSetterProperty = 3.14;
        }
    }

    public class Matrix
    {
        public static void Main()
        {
            ITypeInspector defaultInspector = new DefaultTypeInspector();
            ITypeInspector inspector = new WritablePropertyInspector(defaultInspector);

            // Retrieve writable properties of SampleClass.
            IEnumerable<PropertyInfo> writableProperties = inspector.GetProperties(typeof(SampleClass), null);

            Console.WriteLine("Writable properties in SampleClass:");
            foreach (PropertyInfo prop in writableProperties)
            {
                Console.WriteLine(prop.Name);
            }
        }
    }
}

using UnityEngine;
using System;

public class LifecycleManager : MonoBehaviour
{
    private static LifecycleManager s_Instance;

    public static LifecycleManager Instance
    {
        get
        {
            if (s_Instance == null)
            {
                s_Instance = new GameObject("LifecycleManager").AddComponent<LifecycleManager>();
            }
            return s_Instance;
        }
    }

    private IPlatformLifecycleManager platformLifecycleManager;

    private void Awake()
    {
        DontDestroyOnLoad(gameObject);
        InitializePlatformLifecycleManager();
    }

    private void InitializePlatformLifecycleManager()
    {
#if UNITY_ANDROID
        platformLifecycleManager = new AndroidLifecycleManager();
#elif UNITY_IOS
        platformLifecycleManager = new iOSLifecycleManager();
#else
        Debug.LogError("Unsupported platform for AR lifecycle management.");
#endif
    }

    public void RegisterFrameUpdate(Action<FrameUpdate> updateAction)
    {
        platformLifecycleManager.RegisterFrameUpdate(updateAction);
    }

    public void UnregisterFrameUpdate(Action<FrameUpdate> updateAction)
    {
        platformLifecycleManager.UnregisterFrameUpdate(updateAction);
    }

    private void Update()
    {
        platformLifecycleManager.UpdateLifecycle();
    }
}

public struct FrameUpdate
{
    public ARTrackingStatus TrackingStatus;
    public IntPtr SessionHandle;
    public IntPtr FrameHandle;

    public FrameUpdate(ARTrackingStatus trackingStatus, IntPtr sessionHandle, IntPtr frameHandle)
    {
        TrackingStatus = trackingStatus;
        SessionHandle = sessionHandle;
        FrameHandle = frameHandle;
    }
}

public interface IPlatformLifecycleManager
{
    void RegisterFrameUpdate(Action<FrameUpdate> updateAction);
    void UnregisterFrameUpdate(Action<FrameUpdate> updateAction);
    void UpdateLifecycle();
}

public class AndroidLifecycleManager : IPlatformLifecycleManager
{
    public void RegisterFrameUpdate(Action<FrameUpdate> updateAction) { /* Implementation for Android */ }
    public void UnregisterFrameUpdate(Action<FrameUpdate> updateAction) { /* Implementation for Android */ }
    public void UpdateLifecycle() { /* Update logic for Android AR session */ }
}

public class iOSLifecycleManager : IPlatformLifecycleManager
{
    public void RegisterFrameUpdate(Action<FrameUpdate> updateAction) { /* Implementation for iOS */ }
    public void UnregisterFrameUpdate(Action<FrameUpdate> updateAction) { /* Implementation for iOS */ }

using NUnit.Framework;
using SIL.DictionaryServices.Model;
using SIL.TestUtilities;
using System;
using System.IO;

namespace SIL.DictionaryServices.Tests
{
    [TestFixture]
    public class LiftLexEntryRepositoryEventTests
    {
        private TemporaryFolder _tempFolder;
        private LiftLexEntryRepository _repository;
        private bool _gotEventCall;

        [SetUp]
        public void Setup()
        {
            _tempFolder = new TemporaryFolder("LiftLexEntryRepositoryTests");
            string liftFilePath = Path.Combine(_tempFolder.Path, "test.lift");
            _repository = new LiftLexEntryRepository(liftFilePath);
            _gotEventCall = false;
        }

        [TearDown]
        public void TearDown()
        {
            _tempFolder.Dispose();
        }

        private void OnEvent(object sender, EventArgs e)
        {
            _gotEventCall = true;
        }

        [Test]
        public void NewEntry_ByEntry_TriggersModifiedEntryAdded()
        {
            _repository.ModifiedEntryAdded += OnEvent;
            var entry = new LexEntry();
            _repository.Add(entry);

            Assert.IsTrue(_gotEventCall, "ModifiedEntryAdded event was not triggered.");
        }

        [Test]
        public void ModifiedEntry_ByEntry_TriggersModifiedEntryAdded()
        {
            var entry = new LexEntry();
            _repository.Add(entry);

            _repository.ModifiedEntryAdded += OnEvent;
            entry.LexicalForm["en"] = "test";
            _repository.Save(entry);

            Assert.IsTrue(_gotEventCall, "ModifiedEntryAdded event was not triggered.");
        }

        [Test]
        public void DeleteEntry_ById_TriggersAfterEntryDeleted()
        {
            var entry = new LexEntry();
            _repository.Add(entry);
            string entryId = entry.Id;

            _repository.AfterEntryDeleted += OnEvent;
            _repository.Delete(entryId);

            Assert.IsTrue(_gotEventCall, "AfterEntryDeleted event was not triggered.");
        }

        [Test]
        public void DeleteEntry_ByEntry_TriggersAfterEntryDeleted()
        {
            var entry = new LexEntry();
            _repository.Add(entry);

            _repository.AfterEntryDeleted += OnEvent;
            _repository.Delete(entry);

            Assert.IsTrue(_gotEventCall, "AfterEntryDeleted event was not triggered.");
        }
    }
}

using UnityEngine;

public enum BaseOrientation
{
    Portrait,
    Landscape
}

public class GetDeviceRoll : FsmStateAction
{
    public FsmEnum baseOrientation;
    public FsmFloat storeAngle;
    public FsmBool limitAngle;
    public FsmFloat minAngle;
    public FsmFloat maxAngle;
    public FsmFloat smoothing;
    public FsmBool everyFrame;

    private float lastZAngle;

    public override void OnEnter()
    {
        DoGetDeviceRoll();
        if (!everyFrame.Value)
            Finish();
    }

    public override void OnUpdate()
    {
        DoGetDeviceRoll();
    }

    private void DoGetDeviceRoll()
    {
        Vector3 accelerometer = Input.acceleration;
        float rawAngle = 0f;

        switch ((BaseOrientation)baseOrientation.Value)
        {
            case BaseOrientation.Portrait:
                rawAngle = Mathf.Atan2(accelerometer.x, -accelerometer.y) * Mathf.Rad2Deg;
                break;
            case BaseOrientation.Landscape:
                rawAngle = Mathf.Atan2(-accelerometer.y, accelerometer.x) * Mathf.Rad2Deg;
                break;
        }

        if (limitAngle.Value)
            rawAngle = Mathf.Clamp(rawAngle, minAngle.Value, maxAngle.Value);

        float smoothedAngle = smoothing.Value > 0 ?
            Mathf.LerpAngle(lastZAngle, rawAngle, smoothing.Value * Time.deltaTime) :
            rawAngle;

        lastZAngle = smoothedAngle;
        storeAngle.Value = smoothedAngle;
    }

    public override void Reset()
    {
        baseOrientation = new FsmEnum { Value = BaseOrientation.Portrait };
        storeAngle = new FsmFloat { Value = 0 };
        limitAngle = new FsmBool { Value = false };
        minAngle = new FsmFloat { Value = -30 };
        maxAngle = new FsmFloat { Value = 30 };
        smoothing = new FsmFloat { Value = 5 };
        everyFrame = new FsmBool { Value = true };
        lastZAngle = 0;
    }
}

using System;
using System.IO;
using System.ServiceProcess;
using System.Threading;

public static class Logger
{
    private const string ServiceName = "InEngineServer";
    private static ServerHost _serverHost;
    private static InEngineSettings _settings;
    private static readonly CancellationTokenSource _cts = new CancellationTokenSource();

    public static void Main(string[] args)
    {
        Directory.SetCurrentDirectory(AppDomain.CurrentDomain.BaseDirectory);

        if (args.Length > 0 && args[0] == "--console")
            RunConsoleMode();
        else if (Environment.UserInteractive)
            RunConsoleMode();
        else
            RunServiceMode();
    }

    private static void RunConsoleMode()
    {
        Console.CancelKeyPress += (sender, e) =>
        {
            e.Cancel = true;
            _cts.Cancel();
            Stop();
            Environment.Exit(0);
        };

        Start();
        Console.WriteLine("Server running in console mode. Press ENTER to exit");
        Console.ReadLine();
        Stop();
    }

    private static void RunServiceMode()
    {
        ServiceBase.Run(new Service());
    }

    private static void RunServer()
    {
        _settings = InEngineSettings.Make();
        _serverHost = new ServerHost(_settings);
    }

    public static void Start()
    {
        try
        {
            RunServer();
            _serverHost.Start();
            Console.WriteLine("Server initialized with mail queue: {0}", _settings.MailQueueName);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Fatal startup error: {ex.Message}");
            Environment.ExitCode = 1;
            _cts.Cancel();
        }
    }

    public static void Stop()
    {
        try
        {
            _serverHost?.Stop();
            _serverHost?.Dispose();
            Console.WriteLine("Server resources released");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Shutdown error: {ex.Message}");
        }
    }

    private class Service : ServiceBase
    {
        public Service()
        {
            ServiceName = Logger.ServiceName;
        }

        protected override void OnStart(string[] args)
        {
            Logger.Start();
            base.OnStart(args);
        }

        protected override void OnStop()
        {
            Logger.Stop();
            base.OnStop();
        }
    }
}

