using System;
using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;
using System.Linq;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Filters;
using Abp.Runtime.Validation;

public class MvcActionInvocationValidator : IActionFilter
{
    private bool _isValidatedBefore;
    private List<ValidationError> _validationErrors;

    public void OnActionExecuting(ActionExecutingContext context)
    {
        if (_isValidatedBefore)
            return;

        _validationErrors = new List<ValidationError>();
        var parameters = context.ActionDescriptor.Parameters;

        foreach (var parameter in parameters)
        {
            var parameterValue = GetParameterValue(context, parameter.Name);
            if (parameterValue != null)
            {
                ValidateParameter(parameterValue);
            }
        }

        if (_validationErrors.Any())
        {
            context.Result = new BadRequestObjectResult(new
            {
                Errors = _validationErrors
            });
            context.HttpContext.Response.StatusCode = 400;
        }

        _isValidatedBefore = true;
    }

    private object GetParameterValue(ActionExecutingContext context, string parameterName)
    {
        return context.ActionArguments.TryGetValue(parameterName, out var value) ? value : null;
    }

    private void ValidateParameter(object parameter)
    {
        if (parameter == null)
            return;

        var validationContext = new ValidationContext(parameter, serviceProvider: null, items: null);
        var validationResults = new List<ValidationResult>();

        if (!Validator.TryValidateObject(parameter, validationContext, validationResults, validateAllProperties: true))
        {
            SetDataAnnotationAttributeErrors(validationResults);
        }
    }

    private void SetDataAnnotationAttributeErrors(List<ValidationResult> validationResults)
    {
        foreach (var validationResult in validationResults)
        {
            _validationErrors.Add(new ValidationError
            {
                Message = validationResult.ErrorMessage,
                MemberNames = validationResult.MemberNames.ToList()
            });
        }
    }

    public void OnActionExecuted(ActionExecutedContext context)
    {
        // Optional post-execution logic
    }
}

public class ValidationError
{
    public string Message { get; set; }
    public List<string> MemberNames { get; set; }
}

using System;
using System.Management.Automation;
using System.Threading.Tasks;
using Microsoft.Azure.Management.Insights;
using Microsoft.Azure.Management.Insights.Models;
using Microsoft.Rest.Azure.Authentication;

[Cmdlet(VerbsCommon.Get, "AzureRmDiagnosticSetting")]
public class GetAzureRmDiagnosticSettingCommand : PSCmdlet
{
    [Parameter(Mandatory = true, ValueFromPipelineByPropertyName = true)]
    public string ResourceId { get; set; }

    [Parameter(Mandatory = false)]
    public SwitchParameter Latest { get; set; }

    private InsightsManagementClient _insightsClient;

    protected override void BeginProcessing()
    {
        base.BeginProcessing();
        InitializeAzureClient();
    }

    private void InitializeAzureClient()
    {
        var credentials = ApplicationTokenProvider.LoginSilentAsync(
            Environment.GetEnvironmentVariable("AZURE_TENANT_ID"),
            Environment.GetEnvironmentVariable("AZURE_CLIENT_ID"),
            Environment.GetEnvironmentVariable("AZURE_CLIENT_SECRET")
        ).Result;

        _insightsClient = new InsightsManagementClient(credentials)
        {
            SubscriptionId = Environment.GetEnvironmentVariable("AZURE_SUBSCRIPTION_ID")
        };
    }

    protected override void ProcessRecord()
    {
        base.ProcessRecord();
        var diagnosticSettings = GetDiagnosticSettingsAsync().Result;
        WriteObject(diagnosticSettings);
    }

    private async Task<PSServiceDiagnosticSettings> GetDiagnosticSettingsAsync()
    {
        try
        {
            var diagnosticSettingsResource = await _insightsClient.DiagnosticSettings
                .GetAsync(ResourceId);

            return new PSServiceDiagnosticSettings
            {
                ResourceId = diagnosticSettingsResource.Id,
                Name = diagnosticSettingsResource.Name,
                StorageAccountId = diagnosticSettingsResource.StorageAccountId,
                EventHubAuthorizationRuleId = diagnosticSettingsResource.EventHubAuthorizationRuleId,
                Logs = diagnosticSettingsResource.Logs,
                Metrics = diagnosticSettingsResource.Metrics
            };
        }
        catch (Exception ex)
        {
            WriteError(new ErrorRecord(
                ex,
                "DiagnosticSettingsRetrievalError",
                ErrorCategory.ConnectionError,
                ResourceId
            ));
            return null;
        }
    }
}

public class PSServiceDiagnosticSettings
{
    public string ResourceId { get; set; }
    public string Name { get; set; }

