using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using System.Text.RegularExpressions;
 
class Runner
{
    static void Main(string[] args)
    {
        string get1 = new WebClient().DownloadString("http://www.rosettacode.org/w/api.php?action=query&list=categorymembers&cmtitle=Category:Programming_Languages&cmlimit=500&format=json");
        string get2 = new WebClient().DownloadString("http://www.rosettacode.org/w/index.php?title=Special:Categories&limit=5000");
 
        ArrayList langs = new ArrayList();
        Dictionary<string, int> qtdmbr = new Dictionary<string, int>();
 
        MatchCollection match1 = new Regex("\"title\":\"Category:(.+?)\"").Matches(get1);
        MatchCollection match2 = new Regex("title=\"Category:(.+?)\">.+?</a>[^(]*\\((\\d+) members\\)").Matches(get2);
 
        foreach (Match lang in match1) langs.Add(lang.Groups[1].Value);
 
        foreach (Match match in match2)
        {
            if (langs.Contains(match.Groups[1].Value))
            {
                qtdmbr.Add(match.Groups[1].Value, Int32.Parse(match.Groups[2].Value));
            }
        }
 
        string[] test = qtdmbr.OrderByDescending(x => x.Value).Select(x => String.Format("{0,3} - {1}", x.Value, x.Key)).ToArray();
 
        int count = 1;
 
        foreach (string i in test)
        {
            Console.WriteLine("{0,3}. {1}", count, i);
            count++;
        }
    }
}

using System;

namespace NavigationLib
{
    // NavigationException defines a specialized error type for navigation failures.
    public class NavigationException : Exception
    {
        public NavigationException() : base("Navigation error occurred.") { }

        public NavigationException(string message) : base(message) { }

        public NavigationException(string message, Exception innerException)
            : base(message, innerException) { }

        public NavigationException(Exception originalException)
            : base(originalException.Message, originalException) { }
    }

    // Navigator simulates navigation and uses NavigationException to wrap errors.
    public class Navigator
    {
        public void Navigate(string path)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(path))
                {
                    throw new ArgumentException("Path cannot be empty or null.");
                }

                // Simulate navigation logic.
                Console.WriteLine("Navigating to " + path);
            }
            catch (Exception ex)
            {
                // Wrap and rethrow the exception.
                throw new NavigationException("Navigation failed.", ex);
            }
        }
    }

    // A simple test harness demonstrating the usage of NavigationException.
    public class Helper
    {
        public static void Main(string[] args)
        {
            Navigator navigator = new Navigator();

            try
            {
                // Attempt to navigate using an invalid path.
                navigator.Navigate("");
            }
            catch (NavigationException ne)
            {
                Console.WriteLine("NavigationException caught:");
                Console.WriteLine(ne.Message);
            }
        }
    }
}

