using UnityEngine;
using System.Collections;

public class uScriptAct_LoadPhysicMaterial : MonoBehaviour
{
    public string name; // Path to the PhysicMaterial asset
    public PhysicMaterial asset; // Loaded PhysicMaterial asset

    void Start()
    {
        asset = In(name);
    }

    public PhysicMaterial In(string assetPath)
    {
        if (string.IsNullOrEmpty(assetPath))
        {
            Debug.LogWarning("Asset path is null or empty.");
            return null;
        }

        // Attempt to load the PhysicMaterial
        PhysicMaterial loadedMaterial = Resources.Load<PhysicMaterial>(assetPath);

        if (loadedMaterial != null)
        {
            Debug.Log("Successfully loaded PhysicMaterial: " + assetPath);
            return loadedMaterial;
        }
        else
        {
            Debug.LogWarning("Failed to load PhysicMaterial at path: " + assetPath);
            return null;
        }
    }

#if UNITY_EDITOR
    [UnityEditor.CustomEditor(typeof(uScriptAct_LoadPhysicMaterial))]
    public class uScriptAct_LoadPhysicMaterialEditor : UnityEditor.Editor
    {
        public override void OnInspectorGUI()
        {
            uScriptAct_LoadPhysicMaterial script = (uScriptAct_LoadPhysicMaterial)target;

            script.name = UnityEditor.EditorGUILayout.TextField("Asset Path", script.name);
            EditorDragDrop(script);
            DrawDefaultInspector();
        }

        private void EditorDragDrop(uScriptAct_LoadPhysicMaterial script)
        {
            Event e = Event.current;
            Rect rect = GUILayoutUtility.GetRect(0, 20);

            if (rect.Contains(e.mousePosition) && e.type == EventType.DragUpdated)
            {
                DragAndDrop.AcceptDrag();
                DragAndDrop.visualMode = DragAndDropVisualMode.Copy;
                e.Use();
            }

            if (e.type == EventType.DragPerform && rect.Contains(e.mousePosition))
            {
                DragAndDrop.AcceptDrag();
                foreach (Object obj in DragAndDrop.objectReferences)
                {
                    if (obj is PhysicMaterial)
                    {
                        script.name = AssetDatabase.GetAssetPath(obj);
                        Debug.Log("Assigned PhysicMaterial path: " + script.name);
                    }
                }
                e.Use();
            }
        }
    }
#endif
}

using System;
using System.Collections.Generic;
 
public class Menu
{
        static void Main(string[] args)
        {
            List<string> menu_items = new List<string>() { "fee fie", "huff and puff", "mirror mirror", "tick tock" };
            //List<string> menu_items = new List<string>();
            Console.WriteLine(PrintMenu(menu_items));
            Console.ReadLine();
        }
        private static string PrintMenu(List<string> items)
        {
            if (items.Count == 0)
                return "";
 
            string input = "";
            int i = -1;
            do
            {
                for (int j = 0; j < items.Count; j++)
                    Console.WriteLine("{0}) {1}", j, items[j]);
 
                Console.WriteLine("What number?");
                input = Console.ReadLine();
 
            } while (!int.TryParse(input, out i) || i >= items.Count || i < 0);
            return items[i];
        }
}

using UnityEngine;
using HutongGames.PlayMaker.Actions;
using HutongGames.PlayMaker;

[ActionCategory("ArrayMaker")]
[Tooltip("Sets an item at a specified index in a PlayMakerArrayListProxy component.")]
public class ArrayListSet : FsmStateAction
{
    [RequiredField]
    [Tooltip("The GameObject that owns the PlayMakerArrayListProxy component.")]
    public FsmOwnerDefault gameObject;

    [Tooltip("Optional: The reference name of the PlayMakerArrayListProxy component.")]
    public FsmString reference;

    [RequiredField]
    [Tooltip("The index at which to set the item.")]
    public FsmInt atIndex;

    [RequiredField]
    [Tooltip("The item to set in the array list.")]
    public FsmVar variable;

    [Tooltip("Repeat every frame.")]
    public bool everyFrame;

    private PlayMakerArrayListProxy arrayListProxy;

    public override void Reset()
    {
        gameObject = null;
        reference = null;
        atIndex = null;
        variable = null;
        everyFrame = false;
    }

    public override void OnEnter()
    {
        DoArrayListSet();

        if (!everyFrame)
        {
            Finish();
        }
    }

    public override void OnUpdate()
    {
        DoArrayListSet();
    }

    private void DoArrayListSet()
    {
        GameObject go = Fsm.GetOwnerDefaultTarget(gameObject);
        if (go == null)
        {
            return;
        }

        if (arrayListProxy == null)
        {
            arrayListProxy = reference.Value.Length > 0
                ? go.GetComponent<PlayMakerArrayListProxy>(reference.Value)
                : go.GetComponent<PlayMakerArrayListProxy>();

            if (arrayListProxy == null)
            {
                LogError("PlayMakerArrayListProxy component not found.");
                return;
            }
        }

        if (arrayListProxy.arrayList != null && atIndex.Value >= 0 && atIndex.Value < arrayListProxy.arrayList.Count)
        {
            arrayListProxy.arrayList[atIndex.Value] = variable.GetValue();
        }
        else
        {
            LogError("Invalid index or array list is null.");
        }
    }
}

using System;
using System.Drawing;
using System.Windows.Forms;
 
class CSharpPendulum
{
    Form _form;
    Timer _timer;
 
    double _angle = Math.PI / 2,
           _angleAccel,
           _angleVelocity = 0,
           _dt = 0.1;
 
    int _length = 50;
 
    [STAThread]
    static void Main()
    {
        var p = new CSharpPendulum();
    }
 
    public CSharpPendulum()
    {
        _form = new Form() { Text = "Pendulum", Width = 200, Height = 200 };
        _timer = new Timer() { Interval = 30 };
 
        _timer.Tick += delegate(object sender, EventArgs e)
        {
            int anchorX = (_form.Width / 2) - 12,
                anchorY = _form.Height / 4,
                ballX = anchorX + (int)(Math.Sin(_angle) * _length),
                ballY = anchorY + (int)(Math.Cos(_angle) * _length);
 
            _angleAccel = -9.81 / _length * Math.Sin(_angle);
            _angleVelocity += _angleAccel * _dt;
            _angle += _angleVelocity * _dt;
 
            Bitmap dblBuffer = new Bitmap(_form.Width, _form.Height);
            Graphics g = Graphics.FromImage(dblBuffer);
            Graphics f = Graphics.FromHwnd(_form.Handle);
 
            g.DrawLine(Pens.Black, new Point(anchorX, anchorY), new Point(ballX, ballY));
            g.FillEllipse(Brushes.Black, anchorX - 3, anchorY - 4, 7, 7);
            g.FillEllipse(Brushes.DarkGoldenrod, ballX - 7, ballY - 7, 14, 14);
 
            f.Clear(Color.White);
            f.DrawImage(dblBuffer, new Point(0, 0));
        };
 
        _timer.Start();
        Application.Run(_form);
    }
}

