public class GravitySwitch : MonoBehaviour
{
    public float gravityStrength = 9.81f;
    public float momentum = 0;
    private bool isGravityUp = true;
    private bool isGameActive = true;
    private GameObject explosionPrefab;
    private GameObject characterPiecesPrefab;
    private Vector2 hitPosition;
    private int bestScore;
    private int currentScore;

    private enum GameState { Playing, GameOver }
    private GameState currentGameState = GameState.Playing;

    void Start()
    {
        // Initialize game parameters
        Physics2D.gravity = new Vector2(0, -gravityStrength);
        currentScore = 0;
        bestScore = PlayerPrefs.GetInt("BestScore", 0);
        explosionPrefab = Resources.Load<GameObject>("Explosion");
        characterPiecesPrefab = Resources.Load<GameObject>("CharacterPieces");
    }

    void Update()
    {
        // Update game state and handle controls
        if (isGameActive)
        {
            Controls();
            UpdateCharacterPosition();
            CheckForScore();
        }
        else
        {
            ShowGameOverScreen();
        }
    }

    private void Controls()
    {
        // Handle user input to toggle gravity
        if (Input.GetKeyDown(KeyCode.Space) || Input.GetMouseButtonDown(0))
        {
            ToggleGravity();
        }
    }

    private void ToggleGravity()
    {
        isGravityUp = !isGravityUp;
        Physics2D.gravity = new Vector2(0, isGravityUp ? -gravityStrength : gravityStrength);
    }

    private void UpdateCharacterPosition()
    {
        // Update character position based on gravity
        transform.Translate(new Vector2(0, momentum * Time.deltaTime));
        momentum -= gravityStrength * Time.deltaTime;
    }

    private void CheckForScore()
    {
        // Update score logic here (example: increment score over time)
        currentScore += (int)(Time.deltaTime * 100); // Increase score over time
    }

    private void OnCollisionEnter2D(Collision2D collision)
    {
        // Handle collision and trigger game over procedures
        if (collision.gameObject.CompareTag("Obstacle"))
        {
            GameOver(collision.contacts[0].point);
        }
    }

    private void GameOver(Vector2 position)
    {
        // Handle game over state
        isGameActive = false;
        hitPosition = position;
        ShowExplosionEffect();
        UpdateBestScore();
    }

    private void ShowExplosionEffect()
    {
        // Instantiate explosion effect at hit position

