public class SQLiteColumn : ColumnBase
{
    private readonly SQLiteTypeMap _typeMap;
    private readonly SQLiteQuoter _quoter;

    public SQLiteColumn(SQLiteTypeMap typeMap, SQLiteQuoter quoter)
    {
        _typeMap = typeMap;
        _quoter = quoter;
    }

    protected override string FormatIdentity(ColumnDefinition column)
    {
        if (column.IsIdentity && column.DataType != DbType.Int32)
        {
            throw new ArgumentException("SQLite identity columns must be of type Int32.");
        }
        return column.IsIdentity ? "INTEGER PRIMARY KEY AUTOINCREMENT" : string.Empty;
    }

    protected override bool ShouldPrimaryKeysBeAddedSeparately(IEnumerable<ColumnDefinition> columns)
    {
        return columns.Any(c => c.IsIdentity);
    }

    protected override string FormatPrimaryKey(IEnumerable<ColumnDefinition> columns)
    {
        var primaryKeys = columns.Where(c => c.IsPrimaryKey).ToList();
        if (primaryKeys.Count == 0) return string.Empty;
        if (primaryKeys.Any(c => c.IsIdentity)) return string.Empty;
        return $"PRIMARY KEY ({string.Join(", ", primaryKeys.Select(c => _quoter.QuoteColumnName(c.Name)))})";
    }

    protected override string FormatSystemMethods(SystemMethods systemMethod)
    {
        switch (systemMethod)
        {
            case SystemMethods.CurrentUTCDateTime:
                return "CURRENT_TIMESTAMP";
            case SystemMethods.CurrentDateTime:
                return "CURRENT_TIMESTAMP";
            default:
                throw new ArgumentException($"System method {systemMethod} is not supported in SQLite.");
        }
    }

    public override string GenerateColumn(ColumnDefinition column)
    {
        var parts = new List<string>
        {
            _quoter.QuoteColumnName(column.Name),
            _typeMap.GetTypeName(column.DataType, column.Size, column.Precision, column.Scale)
        };

        if (column.IsNullable == false)
        {
            parts.Add("NOT NULL");
        }

        if (column.DefaultValue != null)
        {
            parts.Add($"DEFAULT {_quoter.QuoteValue(column.DefaultValue)}");
        }

        if (column.IsIdentity)
        {
            parts.Add("INTEGER PRIMARY KEY AUTOINCREMENT");
        }
        else if (column.IsPrimaryKey)
        {
            parts.Add("PRIMARY KEY");
        }

