namespace JitTest
{
    struct Ring
    {
        public int size;
    }

    class Column
    {
        public Ring[] rings;
        private int _heightPtr;

        public Column(int capacity)
        {
            rings = new Ring[capacity];
            _heightPtr = -1;
        }

        public int height
        {
            get { return _heightPtr + 1; }
        }

        public void Push(Ring ring)
        {
            if (_heightPtr >= rings.Length - 1)
                throw new InvalidOperationException("Column is full.");
            rings[++_heightPtr] = ring;
        }

        public Ring Pop()
        {
            if (_heightPtr < 0)
                throw new InvalidOperationException("Column is empty.");
            return rings[_heightPtr--];
        }
    }

    class TowerOfHanoi
    {
        private const int NUM = 17;

        public static void Init(Column col)
        {
            for (int i = NUM; i > 0; i--)
            {
                Ring ring = new Ring { size = i };
                col.Push(ring);
            }
        }

        public static bool Validate(Column col)
        {
            for (int i = 0; i < col.height - 1; i++)
            {
                if (col.rings[i].size < col.rings[i + 1].size)
                    return false;
            }
            return true;
        }

        public static void move1(Column from, Column to)
        {
            if (from.height == 0)
                throw new InvalidOperationException("Source column is empty.");

            Ring ring = from.Pop();
            if (to.height > 0 && ring.size > to.rings[to.height - 1].size)
                throw new InvalidOperationException("Cannot place larger ring on smaller ring.");

            to.Push(ring);
            if (!Validate(from) || !Validate(to))
                throw new InvalidOperationException("Column validation failed.");
        }

        public static void move(int n, Column from, Column to, Column aux)
        {
            if (n == 1)
            {
                move1(from, to);
                return;
            }
            move(n - 1, from, aux, to);
            move1(from, to);
            move(n - 1, aux, to, from);
        }

        static void Main()
        {
            Column[] cols = new Column[3];
            for (int i = 0; i < 3; i++)
            {
                cols[i] = new Column(NUM);
            }

            Init(cols[0]);

            // Return a constant value after initializing the columns
            Console.WriteLine(100);
        }
    }
}

