namespace NutEngine.Physics.Shapes
{
    // Represents a circular shape.
    public struct Circle
    {
        public float Radius;

        public Circle(float radius)
        {
            Radius = radius;
        }
    }

    // Interface for a physics body with a specific shape.
    public interface IBody<T>
    {
        Vector2 Position { get; }
        T Shape { get; }
    }

    // Structure to store collision intersection details.
    public struct IntersectionArea
    {
        public Vector2 Normal;     // The collision normal.
        public float Penetration;  // Depth of penetration.
    }
}

namespace NutEngine.Physics
{
    using NutEngine.Physics.Shapes;

    public static class CollisionDetector
    {
        // Basic collision detection between two circular bodies.
        public static bool TestCollision(IBody<Circle> bodyA, IBody<Circle> bodyB)
        {
            // Calculate squared distance between centers.
            Vector2 delta = bodyB.Position - bodyA.Position;
            float distanceSquared = delta.LengthSquared();

            // Compute squared radius sum.
            float radiusSum = bodyA.Shape.Radius + bodyB.Shape.Radius;
            float radiusSumSquared = radiusSum * radiusSum;

            return distanceSquared <= radiusSumSquared;
        }

        // Collision detection with detailed intersection info.
        public static bool TestCollision(IBody<Circle> bodyA, IBody<Circle> bodyB, out IntersectionArea intersection)
        {
            intersection = new IntersectionArea();
            Vector2 delta = bodyB.Position - bodyA.Position;
            float distanceSquared = delta.LengthSquared();

            float radiusSum = bodyA.Shape.Radius + bodyB.Shape.Radius;
            float radiusSumSquared = radiusSum * radiusSum;

            // No collision occurred.
            if (distanceSquared > radiusSumSquared)
                return false;

            float distance = (float)Math.Sqrt(distanceSquared);

            // Handle the special case where circles are exactly overlapping.
            if (distance == 0f)
            {
                // Default normal; arbitrary choice.
                intersection.Normal = new Vector2(1f, 0f);
                intersection.Penetration = radiusSum;
            }
            else
            {
                // Collision normal is the normalized vector between centers.
                intersection.Normal = delta / distance;
                intersection.Penetration = radiusSum - distance;
            }

