            var settings = new ConnectionConfiguration(new Uri("http://localhost:9200"));
            _client = new ElasticLowLevelClient(settings);
        }

        [Test]
        [NCrunch.Framework.Isolated]
        public void ParentWithRoutingTests()
        {
            var createIndexResponse = _client.IndicesCreate<dynamic>("test-index", c => c
                .Body(new
                {
                    settings = new
                    {
                        number_of_replicas = 0
                    },
                    mappings = new
                    {
                        properties = new
                        {
                            parent = new
                            {
                                type = "join",
                                relations = new
                                {
                                    parent = "child"
                                }
                            }
                        }
                    }
                }));
            Assert.True(createIndexResponse.Success);

            var healthResponse = _client.ClusterHealth(h => h
                .WaitForStatus(WaitForStatus.Yellow)
                .Index("test-index"));
            Assert.True(healthResponse.Success);

            var parentId = "parent-1";
            var parentResponse = _client.Index<dynamic>("test-index", parentId, new
            {
                name = "Parent Document",
                parent = new { name = "parent" }
            });
            Assert.True(parentResponse.Success);

            var childId = "child-1";
