                    name = "Child Document",
                    parent = new { name = "child", parent = parentId }
                }));
            Assert.True(childResponse.Success);

            var getResponse = _client.Get<dynamic>("test-index", childId, g => g
                .Routing(routing));
            Assert.True(getResponse.Success);
            Assert.AreEqual(childId, getResponse.Body._id.ToString());

