    /// <summary>
    /// A basic data container that represents a key/value pair.
    /// </summary>
    [Serializable]
    [ComVisible(true)]
    public struct DictionaryEntry
    {
        // Auto-implemented property for the key.
        public object Key { get; set; }

        // Auto-implemented property for the value.
        public object Value { get; set; }

        /// <summary>
        /// Initializes a new instance of the DictionaryEntry structure.
        /// </summary>
        /// <param name="key">The key identifier.</param>
        /// <param name="value">The associated value.</param>
        public DictionaryEntry(object key, object value)
        {
            Key = key;
            Value = value;
        }
    }

    /// <summary>
    /// Main program to demonstrate the DictionaryEntry structure.
    /// </summary>
    public class Cache
    {
        public static void Main(string[] args)
        {
            // Create sample DictionaryEntry instances.
            DictionaryEntry entry1 = new DictionaryEntry("Name", "John Doe");
            DictionaryEntry entry2 = new DictionaryEntry("Age", 30);
            DictionaryEntry entry3 = new DictionaryEntry("Country", "USA");

            // Display the original entries.
            Console.WriteLine("Original Dictionary Entries:");
            PrintEntry(entry1);
            PrintEntry(entry2);
            PrintEntry(entry3);

            // Modify the 'Age' entry.
            entry2.Value = 31;
            Console.WriteLine("\nModified Age Entry:");
            PrintEntry(entry2);

            // Create an array to store multiple entries.
            DictionaryEntry[] entries = new DictionaryEntry[] { entry1, entry2, entry3 };

            Console.WriteLine("\nAll Dictionary Entries from Array:");
            // Iterate through the array and print each entry.
            foreach (DictionaryEntry entry in entries)
            {
                PrintEntry(entry);
            }

            // End demonstration and wait for user input.
            Console.WriteLine("\nPress any key to exit...");
            Console.ReadKey();
        }

