        /// <param name="entry">The DictionaryEntry instance to print.</param>
        public static void PrintEntry(DictionaryEntry entry)
        {
            Console.WriteLine("Key: {0}, Value: {1}", entry.Key, entry.Value);

using System;
 
public enum Mode
{
    ENCRYPT,
    DECRYPT,
}
 
public class Stack
{
    private const string L_ALPHABET = "HXUCZVAMDSLKPEFJRIGTWOBNYQ";
    private const string R_ALPHABET = "PTLNBQDEOYSFAVZKGJRIHWXUMC";
 
    public static string Exec(string text, Mode mode, bool showSteps = false)
    {
        var left = L_ALPHABET;
        var right = R_ALPHABET;
        var eText = new char[text.Length + 1];
        var temp = new char[27];
 
        Array.Clear(eText, 0, text.Length + 1);
        Array.Clear(temp, 0, 27);
 
        for (var i = 0; i < text.Length; i++)
        {
            if (showSteps) Console.WriteLine($"{left} {right}");
            var index = 0;
            if (mode == Mode.ENCRYPT)
            {
                index = right.IndexOf(text[i]);
                eText[i] = left[index];
            }
            else
            {
                index = left.IndexOf(text[i]);
                eText[i] = right[index];
            }
            if (i == text.Length - 1) break;
 
            // permute left
 
            for (var j = index; j < 26; ++j) temp[j - index] = left[j];
            for (var j = 0; j < index; ++j) temp[26 - index + j] = left[j];
            var store = temp[1];
            for (var j = 2; j < 14; ++j) temp[j - 1] = temp[j];
            temp[13] = store;
            left = new string(temp);
 
            // permurte right
 
            for (var j = index; j < 26; ++j) temp[j - index] = right[j];
            for (var j = 0; j < index; ++j) temp[26 - index + j] = right[j];
            store = temp[0];
            for (var j = 1; j < 26; ++j) temp[j - 1] = temp[j];
            temp[25] = store;
            store = temp[2];
            for (var j = 3; j < 14; ++j) temp[j - 1] = temp[j];
            temp[13] = store;
            right = new string(temp);
        }
 
        return new string(eText);
    }
 
    public static void Main()
    {
        var plainText = "WELLDONEISBETTERTHANWELLSAID";
        Console.WriteLine($"The original plaintext is : {plainText}");
        Console.WriteLine("\nThe left and right alphabets after each permutation during encryption are :\n");
        var cipherText = Exec(plainText, Mode.ENCRYPT, true);
        Console.WriteLine($"\nThe ciphertext is : {cipherText}");
        var plainText2 = Exec(cipherText, Mode.DECRYPT);
        Console.WriteLine($"\nThe recovered plaintext is : {plainText2}");
    }
}

