[RunInstaller(true)]
public class ServiceInstallerBase : Installer
{
    private readonly ServiceProcessInstaller _processInstaller;
    private readonly ServiceInstaller _serviceInstaller;

    public ServiceInstallerBase(ServiceOptions options)
    {
        _processInstaller = new ServiceProcessInstaller
        {
            Account = options.AccountType,
            Username = options.Username,
            Password = options.Password
        };

        _serviceInstaller = new ServiceInstaller
        {
            ServiceName = options.ServiceName,
            DisplayName = options.DisplayName,
            Description = options.Description,
            StartType = options.StartType
        };

        InitializeInstallers();
    }

    private void InitializeInstallers()
    {
        Installers.Add(_processInstaller);
        Installers.Add(_serviceInstaller);

        // Removing default event log installer if it exists
        foreach (Installer installer in Installers)
        {
            if (installer is EventLogInstaller eventLogInstaller)
            {
                Installers.Remove(eventLogInstaller);
            }
        }

        // Optionally add a custom EventLogInstaller setup here if needed
        SetupEventLogInstaller();
    }

    private void SetupEventLogInstaller()
    {
        try
        {
            EventLogInstaller eventLogInstaller = new EventLogInstaller
            {
                Log = "Application",
                Source = _serviceInstaller.ServiceName
            };

            Installers.Add(eventLogInstaller);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"Failed to add EventLogInstaller: {ex.Message}");
        }
    }
}

