namespace PrimeNumberLoopcs
{
    class Tree
    {
        static bool isPrime(double number)
        {
            for(double i = number - 1; i > 1; i--)
            {
                if (number % i == 0)
                    return false;
            }
            return true;
        }
        static void Main(string[] args)
        {
            NumberFormatInfo nfi = new CultureInfo("en-US", false).NumberFormat;
            nfi.NumberDecimalDigits = 0;
            double i = 42;
            int n = 0;
            while (n < 42)
            {
                if (isPrime(i))
                {
                    n++;
                    Console.WriteLine("n = {0,-20} {1,20}", n, i.ToString("N", nfi));
                    i += i - 1;
                }
                i++;
            }
        }
    }
}

using System;
using System.Collections;
using System.Collections.Generic;

public class StringDictionary
{
    private Hashtable _values;

    public StringDictionary()
    {
        _values = new Hashtable();
    }

    public void Add(string key, string value)
    {
        if (string.IsNullOrEmpty(key))
        {
            throw new ArgumentException("Key cannot be null or empty.");
        }

        if (_values.ContainsKey(key))
        {
            throw new DuplicateKeyException($"The key '{key}' already exists in the dictionary.");
        }

        _values[key] = value;
    }

    public bool ContainsKey(string key)
    {
        if (string.IsNullOrEmpty(key))
        {
            throw new ArgumentException("Key cannot be null or empty.");
        }

        return _values.ContainsKey(key);
    }

    public string this[string key]
    {
        get
        {
            if (string.IsNullOrEmpty(key))
            {
                throw new ArgumentException("Key cannot be null or empty.");
            }

            if (!_values.ContainsKey(key))
            {
                throw new KeyNotFoundException($"The key '{key}' does not exist in the dictionary.");
            }

            return (string)_values[key];
        }
        set
        {
            Add(key, value);
        }
    }

    public void Clear()
    {
        _values.Clear();
    }

    public ICollection<string> Keys
    {
        get
        {
            List<string> keys = new List<string>();
            foreach (DictionaryEntry entry in _values)
            {
                keys.Add((string)entry.Key);
            }
            return keys;
        }
    }

    public ICollection<string> Values
    {
        get
        {
            List<string> values = new List<string>();
            foreach (DictionaryEntry entry in _values)
            {
                values.Add((string)entry.Value);
            }
            return values;
        }
    }

    public class DuplicateKeyException : Exception
    {
        public DuplicateKeyException(string message) : base(message) { }
    }

    // Uncomment below to enable debugging functionality
    /*
    public void PrintContents()
    {
