using System;

namespace Azure.SqlDatabase.Management.Sdk.Models
{
    public class DatabaseSecureConnectionPolicyModel : SecureConnectionPolicyModel
    {
        private ConnectionStrings? m_ConnectionStrings;

        public string DatabaseName { get; set; }
        public string ServerName { get; set; }

        public ConnectionStrings ConnectionStrings
        {
            get
            {
                if (!m_ConnectionStrings.HasValue)
                {
                    ValidateParameters();
                    m_ConnectionStrings = new ConnectionStrings
                    {
                        ProxyConnectionString = $"Data Source={ProxyDnsName},{ProxyPort};Initial Catalog={DatabaseName};Encrypt=True;TrustServerCertificate=False;Connection Timeout=30;",
                        DirectConnectionString = $"Data Source={ServerName};Initial Catalog={DatabaseName};Encrypt=True;TrustServerCertificate=False;Connection Timeout=30;"
                    };
                }
                return m_ConnectionStrings.Value;
            }
        }

        private void ValidateParameters()
        {
            if (string.IsNullOrEmpty(ProxyDnsName))
                throw new ArgumentNullException(nameof(ProxyDnsName));
            if (ProxyPort <= 0)
                throw new ArgumentOutOfRangeException(nameof(ProxyPort));
            if (string.IsNullOrEmpty(ServerName))
                throw new ArgumentNullException(nameof(ServerName));
            if (string.IsNullOrEmpty(DatabaseName))
                throw new ArgumentNullException(nameof(DatabaseName));
        }

        public struct ConnectionStrings
        {
            public string ProxyConnectionString { get; set; }
            public string DirectConnectionString { get; set; }
        }
    }
}

