using System;
using System.Collections.Generic;
using Alex.MoLang.Parser;
using Alex.MoLang.Runtime.Exceptions;
using Alex.MoLang.Runtime.Value;

namespace Alex.MoLang.Runtime
{
    public class MoLangRuntime
    {
        private static readonly NLog.Logger Log = NLog.LogManager.GetCurrentClassLogger();
        public MoLangEnvironment Environment { get; }

        public MoLangRuntime(MoLangEnvironment environment)
        {
            Environment = environment ?? throw new ArgumentNullException(nameof(environment));
        }

        public IMoValue Execute(IExpression[] expressions, Dictionary<string, IMoValue> context = null)
        {
            IMoValue lastResult = MoVoid.Void;
            MoScope scope = new MoScope(Environment);

            if (context != null)
            {
                foreach (var kvp in context)
                {
                    scope.SetValue(kvp.Key, kvp.Value);
                }
            }

            try
            {
                foreach (var expression in expressions)
                {
                    try
                    {
                        lastResult = expression.Evaluate(scope);
                        if (lastResult is MoReturnValue returnValue)
                        {
                            return returnValue.Value;
                        }
                    }
                    catch (Exception ex)
                    {
                        Log.Error(ex, $"Error evaluating expression: {expression}");
                        throw new MoLangRuntimeException($"Error evaluating expression: {expression}", ex);
                    }
                }
            }
            catch (MoLangRuntimeException)
            {
                throw; // Re-throw MoLangRuntimeExceptions to preserve context
            }
            catch (Exception ex)
            {
                Log.Error(ex, "Unexpected error during execution.");
                throw new MoLangRuntimeException("Unexpected error during execution.", ex);
            }

            return lastResult;
        }
    }
}

