namespace Wasm.Instructions
{
    /// <summary>
    /// Represents a WebAssembly instruction with a 64-bit signed integer immediate value
    /// </summary>
    public sealed class VarInt64Instruction : Instruction
    {
        private readonly Operator opValue;

        /// <summary>
        /// Gets the 64-bit signed integer immediate value
        /// </summary>
        public long Immediate { get; }

        /// <summary>
        /// Initializes a new instance of VarInt64Instruction
        /// </summary>
        /// <param name="op">The instruction operator</param>
        /// <param name="immediate">The 64-bit signed integer immediate value</param>
        public VarInt64Instruction(Operator op, long immediate)
        {
            opValue = op;
            Immediate = immediate;
        }

        /// <summary>
        /// Writes the instruction's immediate value to the binary writer
        /// </summary>
        /// <param name="writer">The WebAssembly binary writer</param>
        public override void WriteImmediatesTo(BinaryWriter writer)
        {
            if (writer == null)
                throw new ArgumentNullException(nameof(writer));

            // Write variable-length encoded 64-bit signed integer
            writer.WriteVarInt64(Immediate);
        }

        /// <summary>
        /// Generates a text representation of the instruction
        /// </summary>
        /// <returns>Formatted instruction string</returns>
        public override string Dump()
        {
            var builder = new StringBuilder();
            builder.Append(opValue.ToString().ToLowerInvariant());
            builder.Append(" ");
            builder.Append(Immediate);
            return builder.ToString();
        }

        /// <summary>
        /// Gets the size of the immediate value in bytes
        /// </summary>
        /// <returns>Encoded size of the immediate value</returns>
        public override int GetImmediateSize()
        {
            return BinaryHelper.GetVarInt64Size(Immediate);
        }

        /// <summary>
        /// Determines equality between two VarInt64Instructions
        /// </summary>
        public override bool Equals(object obj)
        {
            if (obj is VarInt64Instruction other)
            {
                return opValue == other.opValue &&
                       Immediate == other.Immediate;
            }
            return false;
        }

