        /// Generates a hash code for the instruction

using System;
using System.Collections.Generic;
using System.IO;

public class LZSSVLE
{
    private Stream _stream;
    private bool _leaveOpen;

    public LZSSVLE(Stream stream, bool leaveOpen = false)
    {
        _stream = stream;
        _leaveOpen = leaveOpen;
    }

    public byte[] Decompress()
    {
        var buffer = new List<byte>();
        var filesize = ReadVLC();
        var unk1 = ReadVLC();
        var unk2 = ReadVLC();

        while (buffer.Count < filesize)
        {
            var flag = _stream.ReadByte();
            if (flag == -1) break;

            var (nibble1, nibble2) = GetNibbles((byte)flag);

            if (nibble1 == 0)
            {
                buffer.Add((byte)nibble2);
            }
            else
            {
                var length = nibble1 + 2;
                var offset = ReadVLC() + 1;

                for (int i = 0; i < length; i++)
                {
                    buffer.Add(buffer[buffer.Count - offset]);
                }
            }

            if (nibble2 == 0)
            {
                buffer.Add((byte)_stream.ReadByte());
            }
            else
            {
                var length = nibble2 + 2;
                var offset = ReadVLC() + 1;

                for (int i = 0; i < length; i++)
                {
                    buffer.Add(buffer[buffer.Count - offset]);
                }
            }
        }

        if (!_leaveOpen)
        {
            _stream.Close();
        }

        return buffer.ToArray();
    }

    private (byte, byte) GetNibbles(byte b)
    {
        return ((byte)(b >> 4), (byte)(b & 0xF));
    }

    private int ReadVLC()
    {
        int result = 0;
        int shift = 0;
        byte b;

        do
        {
            b = (byte)_stream.ReadByte();
            result |= (b & 0x7F) << shift;
            shift += 7;
        } while ((b & 0x80) != 0);

        return result;
    }
}

