        catch (Exception ex)
        {
            LogError(ex);
            Response.Redirect("~/ErrorPage.aspx");
        }
    }

    private void LoadExistingCards()
    {
        try
        {
            strUserName = Session["UserName"] as string;
            if (string.IsNullOrEmpty(strUserName))
            {
                Response.Redirect("~/Login.aspx");
            }

            BL_VirtualCard blVirtualCard = new BL_VirtualCard();
            DataTable dtCreditCards = blVirtualCard.GetCreditCardsByUser(strUserName);
            DataTable dtDebitCards = blVirtualCard.GetDebitCardsByUser(strUserName);

            gvCreditCards.DataSource = dtCreditCards;
            gvCreditCards.DataBind();

            gvDebitCards.DataSource = dtDebitCards;
            gvDebitCards.DataBind();
        }
        catch (Exception ex)
        {
            LogError(ex);
            Response.Redirect("~/ErrorPage.aspx");
        }
    }

