        /// Adds a new member to the directory role.
        /// </summary>
        /// <param name="member">The directory object to add as a member.</param>
        public void AddMember(DirectoryObject member)
        {
            if (member != null && !Members.Contains(member))
            {
                Members.Add(member);
            }
        }

        /// <summary>
        /// Removes a member from the directory role.
        /// </summary>
        /// <param name="member">The directory object to remove from members.</param>
        public void RemoveMember(DirectoryObject member)
        {
            if (member != null)
            {
                Members.Remove(member);
            }
        }

        /// <summary>
        /// Provides a string representation of the directory role.
        /// </summary>
        /// <returns>A string containing the display name of the role.</returns>
        public override string ToString()
        {
