public class CPSProject
{
    private Dictionary<string, CodeModel> _fileCodeModels;
    private CodeModel _projectCodeModel;

    public CPSProject()
    {
        _fileCodeModels = new Dictionary<string, CodeModel>();
        _projectCodeModel = null;
    }

    public CodeModel GetCodeModel()
    {
        if (_projectCodeModel == null)
        {
            _projectCodeModel = CreateProjectCodeModel();
        }
        return _projectCodeModel;
    }

    public CodeModel GetFileCodeModel(string filePath)
    {
        if (!_fileCodeModels.ContainsKey(filePath))
        {
            _fileCodeModels[filePath] = CPSCodeModelInstanceFactory.CreateFileCodeModel(filePath, this);
        }
        return _fileCodeModels[filePath];
    }

