    // Define a simple structure for a point on the grid.
    public struct Point
    {
        public int X { get; set; }
        public int Y { get; set; }

        public Point(int x, int y)
        {
            X = x;
            Y = y;
        }

        // Override Equals to properly compare two points.
        public override bool Equals(object obj)
        {
            if (!(obj is Point))
                return false;
            Point other = (Point)obj;
            return this.X == other.X && this.Y == other.Y;
        }

        // Override GetHashCode to ensure Point works correctly in collections.
        public override int GetHashCode()
        {
            return X * 397 ^ Y;
        }

        public override string ToString()
        {
            return $"({X}, {Y})";
        }
    }

