public static int[] SubarraySum(int[] arr)
{
    int max = 0;
    int[] slice = new int[0];
    for (int i = 0; i < arr.Length; i++)
    {
        for (int j = i; j < arr.Length; j++)
        {
            int sum = 0;
            for (int k = i; k <= j; k++)
            {
                sum += arr[k];
            }
            if (sum > max)
            {
                max = sum;
                slice = new int[j - i + 1];
                Array.Copy(arr, i, slice, 0, j - i + 1);
            }
        }
    }
    return new int[] { max, slice.Length };
}

