public class HumbleNumbers
{
 
    public static void Main(string[] args)
    {
        Console.WriteLine("First 50 humble numbers:");
        Console.WriteLine(string.Join(", ", humble(50)));
        var lengthCountMap = new Dictionary<int, int>();
        var seq = humble(1_000_000);
        for (int i = 0; i < seq.Length; i++)
        {
            var humbleNumber = seq[i];
            var len = humbleNumber.ToString().Length;
            if (lengthCountMap.ContainsKey(len))
            {
                lengthCountMap[len]++;
            }
            else
            {
                lengthCountMap.Add(len, 1);
            }
        }
        var sorted = lengthCountMap.Keys.ToList();
        sorted.Sort();
        Console.WriteLine("Length  Count");
        foreach (var len in sorted)
        {
            Console.WriteLine($"    {len,2}  {lengthCountMap[len],5}");
        }
    }
 
    private static BigInteger[] humble(int n)
    {
        var two = BigInteger.Parse("2");
        var twoTest = two;
        var three = BigInteger.Parse("3");
        var threeTest = three;
        var five = BigInteger.Parse("5");
        var fiveTest = five;
        var seven = BigInteger.Parse("7");
        var sevenTest = seven;
        var results = new BigInteger[n];
        results[0] = BigInteger.Parse("1");
        int twoIndex = 0, threeIndex = 0, fiveIndex = 0, sevenIndex = 0;
        for (int index = 1; index < n; index++)
        {
            results[index] = new[] { twoTest, threeTest, fiveTest, sevenTest }.Min();
            if (results[index].CompareTo(twoTest) == 0)
            {
                twoIndex++;
                twoTest = two * results[twoIndex];
            }
            if (results[index].CompareTo(threeTest) == 0)
            {
                threeIndex++;
                threeTest = three * results[threeIndex];
            }
            if (results[index].CompareTo(fiveTest) == 0)
            {
                fiveIndex++;
                fiveTest = five * results[fiveIndex];
            }
            if (results[index].CompareTo(sevenTest) == 0)
            {
                sevenIndex++;
                sevenTest = seven * results[sevenIndex];
            }
        }
        return results;
    }
 
}

