namespace SymbolicExpressionBuilderTests
{
    public class ExprTypeCheckException : Exception { public ExprTypeCheckException(string msg) : base(msg) { } }
    public enum ArithmeticCoercion { ToReal, ToInt }
    public abstract class Expr { public abstract string GetRep(); public abstract string Type { get; } }
    public class IntExpr : Expr { public int Value; public override string GetRep() => Value.ToString(); public override string Type => "int"; }
    public class RealExpr : Expr { public double Value; public override string GetRep() => Value.ToString("F1"); public override string Type => "real"; }
    public class DummyExpr : Expr { public override string GetRep() => "dummy"; public override string Type => "dummy"; }

    public class SimpleExprBuilder
    {
        public IntExpr ConstantInt(int v) => new IntExpr { Value = v };
        public RealExpr ConstantReal(double v) => new RealExpr { Value = v };
        public Expr ArithmeticCoercion(Expr e, ArithmeticCoercion coercionType)
        {
            if (coercionType == ArithmeticCoercion.ToReal)
            {
                if (e is IntExpr ie) return new RealExpr { Value = ie.Value };
                if (e is RealExpr) return e;
                throw new ExprTypeCheckException("Operand cannot be coerced to real.");
            }
            else if (coercionType == ArithmeticCoercion.ToInt)
            {
                if (e is RealExpr re)
                {
                    if (re.Value % 1 != 0)
                        throw new ExprTypeCheckException("Non-integral real cannot be coerced to int.");
                    return new IntExpr { Value = (int)re.Value };
                }
                if (e is IntExpr) return e;
                throw new ExprTypeCheckException("Operand cannot be coerced to int.");
            }
            throw new ArgumentException("Unknown coercion type.");
        }
        public void CheckType(Expr e, string expected)
        {
            if (e.Type != expected)
                throw new Exception($"Type mismatch: Expected {expected}, got {e.Type}");
        }
    }

