namespace SutherlandHodgman
{
    class Runner
    {
        static void Main(string[] args)
        {
            var subjectPolygon = new Polygon(new List<Point>
            {
                new Point(50, 150),
                new Point(200, 50),
                new Point(350, 150),
                new Point(350, 300),
                new Point(250, 300),
                new Point(200, 250),
                new Point(150, 350),
                new Point(100, 250),
                new Point(100, 200),
            });
            var clipPolygon = new Polygon(new List<Point>
            {
                new Point(100, 100),
                new Point(300, 100),
                new Point(300, 300),
                new Point(100, 300),
            });
            var result = SutherlandHodgmanClip(subjectPolygon, clipPolygon);
            Console.WriteLine(result);
        }
 
        public static Polygon SutherlandHodgmanClip(Polygon subjectPolygon, Polygon clipPolygon)
        {
            var resultRing = new List<Point>(subjectPolygon.Points);
            var cp1 = clipPolygon.Points.Last();
            foreach (var cp2 in clipPolygon.Points)
            {
                var input = new List<Point>(resultRing);
                var s = input.Last();
                resultRing.Clear();
                foreach (var e in input)
                {
                    if (IsInside(e, cp1, cp2))
                    {
                        if (!IsInside(s, cp1, cp2))
                        {
                            resultRing.Add(ComputeIntersection(cp1, cp2, s, e));
                        }
                        resultRing.Add(e);
                    }
                    else if (IsInside(s, cp1, cp2))
                    {
                        resultRing.Add(ComputeIntersection(cp1, cp2, s, e));
                    }
                    s = e;
                }
                cp1 = cp2;
            }
            return new Polygon(resultRing);
        }
 
        public static bool IsInside(Point p, Point cp1, Point cp2)
        {
            return (cp2.X - cp1.X) * (p.Y - cp1.Y) > (cp2.Y - cp1.Y) * (p.X - cp1.X);
        }
 
        public static Point ComputeIntersection(Point cp1, Point cp2, Point s, Point e)
        {
            var dc = new Point(cp1.X - cp2.X, cp1.Y - cp2.Y);
            var dp = new Point(s.X - e.X, s.Y - e.Y);
            var n1 = cp1.X * cp2.Y - cp1.Y * cp2.X;
            var n2 = s.X * e.Y - s.Y * e.X;

