namespace ConsoleCommandFramework
{
    // Interface defining a contract for console command execution
    public interface IConsoleCommand
    {
        /// <summary>
        /// Executes the command with the provided context, output handler, and runtime model.
        /// </summary>
        /// <param name="contextObject">The context for command execution.</param>
        /// <param name="output">The handler for command output.</param>
        /// <param name="runtimeModel">The model containing runtime data.</param>
        void Execute(object contextObject, IOutputHandler output, IRuntimeModel runtimeModel);
    }

    // Interface for handling command output
    public interface IOutputHandler
    {
        void Write(string message);
        void WriteError(string message);
    }

    // Interface representing the runtime model
    public interface IRuntimeModel
    {
        string GetCurrentState();
        void UpdateState(string newState);
    }

    // A sample implementation of the IConsoleCommand interface
    public class SampleCommand : IConsoleCommand
    {
        public void Execute(object contextObject, IOutputHandler output, IRuntimeModel runtimeModel)
        {
            if (contextObject == null)
            {
                output.WriteError("Context object cannot be null.");
                return;
            }

            output.Write("Executing Sample Command...");
            output.Write($"Current State: {runtimeModel.GetCurrentState()}");

            // Simulate command logic
            var newState = "Sample Command Executed";
            runtimeModel.UpdateState(newState);

            output.Write($"New State: {runtimeModel.GetCurrentState()}");
        }
    }

    // Sample output handler implementation
    public class ConsoleOutputHandler : IOutputHandler
    {
        public void Write(string message)
        {
            Console.WriteLine(message);
        }

        public void WriteError(string message)
        {
            Console.WriteLine($"Error: {message}");
        }
    }

    // Sample runtime model implementation
    public class SimpleRuntimeModel : IRuntimeModel
    {
        private string currentState;

        public SimpleRuntimeModel()
        {
            currentState = "Initial State";
        }

        public string GetCurrentState()
        {
            return currentState;
        }

        public void UpdateState(string newState)
        {
            currentState = newState;
        }
    }
}

