using System;
using System.Collections.Generic;

public class ObjectPool<TContext, TPoolObject> where TPoolObject : IDisposable, new()
{
    private readonly Stack<TPoolObject> _pool = new Stack<TPoolObject>();
    private readonly TContext _context;

    public ObjectPool(TContext context)
    {
        _context = context;
    }

    public TPoolObject Rent()
    {
        if (_pool.Count > 0)
        {
            return _pool.Pop();
        }
        return CreateNewObject();
    }

    public void Return(TPoolObject obj)
    {
        if (obj == null) throw new ArgumentNullException(nameof(obj));
        _pool.Push(obj);
    }

    private TPoolObject CreateNewObject()
    {
        TPoolObject newObj = new TPoolObject();
        // Initialize with context if needed.
        return newObj;
    }
}

public class PooledObject : IDisposable
{
    public string Value { get; set; }
    public int Version { get; set; }

    public void Dispose()
    {
        // Cleanup and prepare object for pooling if necessary.
    }
}

public class PooledObjectFactory
{
    private readonly ObjectPool<string, PooledObject> _pool;

    public PooledObjectFactory(string context)
    {
        _pool = new ObjectPool<string, PooledObject>(context);
    }

    public PooledObject GetPooledObject()
    {
        return _pool.Rent();
    }

    public void ReleasePooledObject(PooledObject obj)
    {
        obj.Dispose();
        _pool.Return(obj);
    }
}

class Vector
{
    static void Main()
    {
        var factory = new PooledObjectFactory("ResourceContext");

        PooledObject pooledObj = factory.GetPooledObject();
        pooledObj.Value = "Hello, Pooled Object!";
        pooledObj.Version = 1;

        Console.WriteLine($"Value: {pooledObj.Value}, Version: {pooledObj.Version}");

        factory.ReleasePooledObject(pooledObj);

        PooledObject anotherPooledObj = factory.GetPooledObject();
        Console.WriteLine($"Retrieved another object: {anotherPooledObj.Value}, Version: {anotherPooledObj.Version}");

        factory.ReleasePooledObject(anotherPooledObj);
    }
}

