public static class DynamicInvoker
{
    public static object InvokeMember(string file, string typeName, string memberName, params object[] parameters)
    {
        string domainId = "IsolatedDomain_" + Guid.NewGuid().ToString("N");
        AppDomain tempDomain = AppDomain.CreateDomain(domainId);

        try
        {
            Type proxyType = typeof(DynamicInvokeProxy);
            DynamicInvokeProxy proxy = (DynamicInvokeProxy)tempDomain.CreateInstanceAndUnwrap(
                proxyType.Assembly.FullName,
                proxyType.FullName);

            return proxy.ExecuteInDomain(file, typeName, memberName, parameters);
        }
        finally
        {
            AppDomain.Unload(tempDomain);
        }
    }
}

public class DynamicInvokeProxy : MarshalByRefObject
{
    public object ExecuteInDomain(string assemblyPath, string typeName, string memberName, object[] parameters)
    {
        Assembly targetAssembly = Assembly.LoadFrom(assemblyPath);
        Type targetType = targetAssembly.GetType(typeName) ??
            throw new TypeLoadException($"Type {typeName} not found");

        object instance = null;
        if (!targetType.IsAbstract)
            instance = Activator.CreateInstance(targetType);

        const BindingFlags bindingFlags = BindingFlags.Public | BindingFlags.NonPublic |
                                        BindingFlags.Static | BindingFlags.Instance;

        MemberInfo member = targetType.GetMember(memberName, bindingFlags)?[0] ??
            throw new MissingMemberException($"Member {memberName} not found");

        switch (member.MemberType)
        {
            case MemberTypes.Method:
                return InvokeMethod((MethodInfo)member, instance, parameters);
            case MemberTypes.Property:
                return HandleProperty((PropertyInfo)member, instance, parameters);
            default:
                throw new NotSupportedException($"{member.MemberType} members not supported");
        }
    }

    private object InvokeMethod(MethodInfo method, object instance, object[] parameters)
    {
        if (!method.IsStatic && instance == null)
            throw new InvalidOperationException("Instance method requires object instance");

        return method.Invoke(instance, parameters);
    }

    private object HandleProperty(PropertyInfo property, object instance, object[] parameters)
    {
        if (parameters.Length > 0)
        {
            property.SetValue(instance, parameters[0]);
            return null;
        }

