namespace MixERP.Stock.TransactionControls
{
    public class DateFieldGenerator : Control
    {
        // Contextual properties required for configuration.
        public string Catalog { get; set; }
        public int OfficeId { get; set; }

        public DateFieldGenerator()
        {
            // Initialize with some default context values if needed.
            this.Catalog = "DefaultCatalog";
            this.OfficeId = 1;
        }

        // This method creates a date selection field configured for end-of-month dates.
        public void CreateDateToField(HtmlGenericControl container)
        {
            // Ensure the container is valid.
            if (container == null)
            {
                throw new ArgumentNullException("container", "HTML container cannot be null.");
            }

            // Create a standard field container using the helper.
            HtmlGenericControl fieldContainer = HtmlControlHelper.GetField("End-of-Month Date");

            // Instantiate and configure the custom date control.
            DateTextBox dateToDateTextBox = new DateTextBox
            {
                ID = "EndDateTextBox",
                CssClass = "date-picker eom-date",
                DateMode = "MonthEnd",  // Configures the date control for month-end selection.
                Required = true,
                Catalog = this.Catalog,  // Contextual property derived from the current environment.
                OfficeId = this.OfficeId // Contextual property for setting the appropriate office.
            };

            // Add the configured date control to the field container.
            fieldContainer.Controls.Add(dateToDateTextBox);

            // Insert the field container into the provided HTML container.
            container.Controls.Add(fieldContainer);
        }

        // Override Render method to demonstrate usage.
        protected override void Render(HtmlTextWriter writer)
        {
            // Create a main container for demonstration.
            HtmlGenericControl mainContainer = new HtmlGenericControl("div");
            mainContainer.Attributes.Add("class", "transaction-field-container");

            // Call the method to add the date field to the main container.
            CreateDateToField(mainContainer);

            // Render the created main container.
            mainContainer.RenderControl(writer);
        }
    }
}

