    RingElement mul(RingElement a, RingElement b);
    RingElement mulIdent();
}
 
interface RingElement
{
}
 
// Define a power function that works for any ring.
 
static RingElement ringPow(Ring r, RingElement a, uint p)
{
    RingElement pow = r.mulIdent();
    for (; p > 0; p--)
    {
        pow = r.mul(pow, a);
    }
    return pow;
}
 
// The task function f has that constant 1 in it.
// Define a special kind of ring that has this element.
 
interface OneRing : Ring
{
    RingElement one();
}
 
// Now define the required function f.
// It works for any ring (that has a "one.")
 
static RingElement f(OneRing r, RingElement x)
{
    return r.add(r.add(ringPow(r, x, 100), x), r.one());
}
 
// With rings and the function f defined in a general way, now define
// the specific ring of integers modulo n.
 
class ModRing : OneRing
{
    uint m; // value is congruence modulus n
 
    public ModRing(uint m)
    {
        this.m = m;
    }
 
    public RingElement add(RingElement a, RingElement b)
    {
        return (a as uint? + b as uint?) % m;
    }
 
    public RingElement mul(RingElement a, RingElement b)
    {
        return (a as uint? * b as uint?) % m;
    }
 
    public RingElement mulIdent()
    {
        return 1;
    }
 
    public RingElement one()
    {
        return 1;
    }
}
 
// Demonstrate the general function f on the specific ring with the
// specific values.
 
class Tree
{
    static void Main(string[] args)
    {
        Console.WriteLine(f(new ModRing(13), 10));
    }
}

public static class RegExp
{
    public static string Escape(string text)
    {
        return text.Replace(@"[-[\]{}()*+?.,\\^$|#\s]", @"\\$&");
    }
}

public static class Multisplit
{
    public static string[] Multisplit(string string, string[] seps)
    {
        var sep_regex = new Regex(string.Join("|", seps.Select(sep => RegExp.Escape(sep))));
        return sep_regex.Split(string);
    }
}

