using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using Xunit;

namespace TestDiscovery
{
    public class TestsToRun
    {
        public List<Action> Tests { get; private set; } = new List<Action>();

        public TestsToRun()
        {
            Tests = LoadTests();
        }

        private List<Action> LoadTests()
        {
            var assemblyName = "Novell.Directory.Ldap.NETStandard.FunctionalTests";
            Assembly assembly = Assembly.GetExecutingAssembly();

            var types = assembly.GetTypes().Where(t => t.Name.EndsWith("Tests"));

            foreach (var type in types)
            {
                Tests.AddRange(GetMethods(type));
            }

            return Tests;
        }

        private List<Action> GetMethods(Type type)
        {
            var methods = type.GetMethods(BindingFlags.Public | BindingFlags.Instance)
                .Where(m => m.GetCustomAttributes(typeof(FactAttribute), true).Length > 0
                            && m.GetCustomAttributes(typeof(SkipAttribute), true).Length == 0
                            && m.GetCustomAttributes(typeof(LongRunningAttribute), true).Length == 0)
                .ToList();

            List<Action> actions = new List<Action>();
            foreach (var method in methods)
            {
                MethodInfo mi = method as MethodInfo;
                if (mi != null)
                {
                    actions.Add(() =>
                    {
                        object instance = Activator.CreateInstance(type);
                        mi.Invoke(instance, null);

                        if (instance is IDisposable disposable)
                        {
                            disposable.Dispose();
                        }
                    });
                }
            }
            return actions;
        }
    }

    [AttributeUsage(AttributeTargets.Method, AllowMultiple = false)]
    public class LongRunningAttribute : Attribute
    {
    }
}

using System;
 
public class Processor
{
    public static int Gcd(int a, int b)
    {
        switch ((a, b), (a & 1, b & 1))
        {
            case ((x, y), _) when x == y:
                return y;
            case ((0, x), _) | ((x, 0), _):
                return x;
            case ((x, y), (0, 1)) | ((y, x), (1, 0)):
                return Gcd(x >> 1, y);
            case ((x, y), (0, 0)):
                return Gcd(x >> 1, y >> 1) << 1;
            case ((x, y), (1, 1)):
                {
                    var (min, max) = (Math.Min(x, y), Math.Max(x, y));
                    return Gcd((max - min) >> 1, min);
                }
            default:
                throw new Exception();
        }
    }
 
    public static int Lcm(int a, int b)
    {
        return a * b / Gcd(a, b);
    }
 
    public static void Main()
    {
        Console.WriteLine(Lcm(6324, 234));
    }
}

