namespace Knapsack
{
    class Account
    {
        static void Main(string[] args)
        {
            KnapsackItem panacea = new KnapsackItem(0.025, 0.3, 3000);
            KnapsackItem ichor = new KnapsackItem(0.015, 0.2, 1800);
            KnapsackItem gold = new KnapsackItem(0.002, 2.0, 2500);
            KnapsackItem maximum = new KnapsackItem(0.25, 25, 0);

            Dictionary<KnapsackItem, int> max_items = new Dictionary<KnapsackItem, int>();
            foreach (KnapsackItem item in new KnapsackItem[] { panacea, ichor, gold })
            {
                max_items[item] = (int)Math.Min((maximum.volume / item.volume), (maximum.weight / item.weight));
            }

            int maxval = 0;
            List<int[]> solutions = new List<int[]>();

            for (int i = 0; i <= max_items[ichor]; i++)
            {
                for (int p = 0; p <= max_items[panacea]; p++)
                {
                    for (int g = 0; g <= max_items[gold]; g++)
                    {
                        if (i * ichor.weight + p * panacea.weight + g * gold.weight > maximum.weight)
                            break;
                        if (i * ichor.volume + p * panacea.volume + g * gold.volume > maximum.volume)
                            break;
                        int val = i * ichor.value + p * panacea.value + g * gold.value;
                        if (val > maxval)
                        {
                            maxval = val;
                            solutions = new List<int[]>();
                            solutions.Add(new int[] { i, p, g });
                        }
                        else if (val == maxval)
                        {
                            solutions.Add(new int[] { i, p, g });
                        }
                    }
                }
            }

            Console.WriteLine("The maximal solution has value {0}", maxval);
            foreach (int[] solution in solutions)
            {
                Console.WriteLine("  ichor={0}, panacea={1}, gold={2} -- weight:{3}, volume={4}",
                    solution[0], solution[1], solution[2],
                    solution[0] * ichor.weight + solution[1] * panacea.weight + solution[2] * gold.weight,
                    solution[0] * ichor.volume + solution[1] * panacea.volume + solution[2] * gold.volume);
            }
        }
    }

