using Azure.Analytics.Synapse.AccessControl;
using Azure.Core.TestFramework;
using NUnit.Framework;
using System;
using System.IO;

namespace Azure.Analytics.Synapse.Tests
{
    [NonParallelizable]
    public class AccessControlClientTestBase : RecordedTestBase<SynapseTestEnvironment>
    {
        protected AccessControlClient AccessControlClient { get; private set; }

        public AccessControlClientTestBase(bool isAsync) : base(isAsync)
        {
        }

        [SetUp]
        public void Initialize()
        {
            AccessControlClient = CreateAccessControlClient();
        }

        protected AccessControlClient CreateAccessControlClient()
        {
            var endpoint = new Uri(TestEnvironment.WorkspaceUrl);
            var credential = TestEnvironment.Credential;
            var options = InstrumentClientOptions(new AccessControlClientOptions());

            return InstrumentClient(new AccessControlClient(endpoint, credential, options));
        }

        protected string GetSessionFilePath()
        {
            var testClass = TestContext.CurrentContext.Test.ClassName;
            var testMethod = TestContext.CurrentContext.Test.MethodName;
            var sessionDirectory = Path.Combine("SessionRecords", testClass);

            if (!Directory.Exists(sessionDirectory))
            {
                Directory.CreateDirectory(sessionDirectory);
            }

            return Path.Combine(sessionDirectory, $"{testMethod}.json");
        }

        protected override void StartTestRecording()
        {
            base.StartTestRecording();
            Recording.FilePath = GetSessionFilePath();
        }

        protected override void StopTestRecording()
        {
            if (TestContext.CurrentContext.Result.Outcome.Status == NUnit.Framework.Interfaces.TestStatus.Failed && Debugger.IsAttached)
            {
                Recording.SaveRecording();
            }
            base.StopTestRecording();
        }
    }
}

