namespace PerformanceMonitoring.ViewModels
{
    public class SimpleHeaderViewModel : Screen
    {
        private readonly ICoreService _coreService;
        private readonly IDebugService _debugService;
        private Timer _frameTimeUpdateTimer;

        private double _frameTime;
        public double FrameTime
        {
            get => _frameTime;
            private set
            {
                if (Math.Abs(_frameTime - value) > 0.001)
                {
                    _frameTime = value;
                    NotifyOfPropertyChange(nameof(FrameTime));
                }
            }
        }

        public SimpleHeaderViewModel(
            ICoreService coreService,
            IDebugService debugService)
        {
            _coreService = coreService ?? throw new ArgumentNullException(nameof(coreService));
            _debugService = debugService ?? throw new ArgumentNullException(nameof(debugService));
        }

        protected override void OnInitialActivate()
        {
            base.OnInitialActivate();
            InitializeFrameTimeUpdateTimer();
        }

        private void InitializeFrameTimeUpdateTimer()
        {
            _frameTimeUpdateTimer = new Timer(500)
            {
                AutoReset = true,
                Enabled = true
            };
            _frameTimeUpdateTimer.Elapsed += OnFrameTimeUpdateTimerOnElapsed;
        }

        private void OnFrameTimeUpdateTimerOnElapsed(object sender, ElapsedEventArgs e)
        {
            try
            {
                UpdateFrameTime();
            }
            catch (Exception ex)
            {
                HandleTimerUpdateError(ex);
            }
        }

        private void UpdateFrameTime()
        {
            var currentFrameTime = _coreService.GetCurrentFrameTime();
            Execute.OnUIThread(() => FrameTime = currentFrameTime);
        }

        private void HandleTimerUpdateError(Exception ex)
        {
            _debugService.LogError($"Frame time update error: {ex.Message}");
        }

        public void ShowDebugger()
        {
            try
            {
                _debugService.LaunchDebuggerInterface();
            }
            catch (Exception ex)
            {
                _debugService.LogError($"Debugger launch failed: {ex.Message}");
            }
        }

        protected override void OnClose()
        {
            _frameTimeUpdateTimer?.Stop();
            _frameTimeUpdateTimer?.Dispose();
            base.OnClose();
        }
    }

