namespace EcologySimulation
{
    // Structure to represent spatial location.
    public struct Point
    {
        public int X;
        public int Y;

        public Point(int x, int y)
        {
            X = x;
            Y = y;
        }

        // Parses a Point from a string formatted as "X,Y".
        public static Point Parse(string s)
        {
            var parts = s.Split(',');
            if (parts.Length != 2)
            {
                throw new FormatException("Invalid point format. Expected format: X,Y");
            }
            return new Point(int.Parse(parts[0]), int.Parse(parts[1]));
        }
    }

    // Base class for organisms.
    public abstract class Organism
    {
        public string Identifier { get; set; }
        public Point Location { get; set; }

        protected Organism(string identifier, Point location)
        {
            Identifier = identifier;
            Location = location;
        }
    }

    // Various organism classes.
    public class Wolf : Organism
    {
        public Wolf(string identifier, Point location) : base(identifier, location) { }
    }

    public class Lion : Organism
    {
        public Lion(string identifier, Point location) : base(identifier, location) { }
    }

    public class Grass : Organism
    {
        public Grass(string identifier, Point location) : base(identifier, location) { }
    }

