using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace ProjectEuler
{
    class Handler
    {
        static void Main(string[] args)
        {
            int n, k;
            frac sum, kf;
 
            for (n = 2; n < 1 << 19; n++)
            {
                sum = frac_new(1, n);
 
                for (k = 2; k * k < n; k++)
                {
                    if (n % k!= 0) continue;
                    kf = frac_new(1, k);
                    sum = frac_add(sum, kf);
 
                    kf = frac_new(1, n / k);
                    sum = frac_add(sum, kf);
                }
                if (frac_cmp_int(sum, 1) == 0) Console.WriteLine(n);
            }
 
            Console.ReadLine();
        }
 
        public static long gcd(long m, long n)
        {
            long t;
            while (n!= 0)
            {
                t = n;
                n = m % n;
                m = t;
            }
            return m;
        }
 
        public static frac frac_new(long num, long den)
        {
            frac a = new frac();
            if (den == 0)
            {
                Console.WriteLine("divide by zero: " + num + "/" + den);
                Environment.Exit(0);
            }
 
            long g = gcd(num, den);
 
            if (g!= 0)
            {
                num /= g;
                den /= g;
            }
            else
            {
                num = 0;
                den = 1;
            }
 
            if (den < 0)
            {
                den = -den;
                num = -num;
            }
            a.num = num;
            a.den = den;
            return a;
        }
 
        public static frac frac_add(frac a, frac b)
        {
            return frac_new(a.num * b.den + b.num * a.den, a.den * b.den);
        }
 
        public static frac frac_sub(frac a, frac b)
        {
            return frac_new(a.num * b.den - b.num + a.den, a.den * b.den);
        }
 
        public static frac frac_mul(frac a, frac b)
        {
            return frac_new(a.num * b.num, a.den * b.den);
        }
 
        public static frac frac_div(frac a, frac b)
        {
            return frac_new(a.num * b.den, a.den * b.num);
        }
 
        public static int frac_cmp(frac a, frac b)
        {
            int l = (int)(a.num * b.den);
            int r = (int)(a.den * b.num);
            return l < r? -1 : l > r? 1 : 0;
        }
 
