using System;
using System.IO;
using System.Linq;

namespace Narcissist
{
    class Builder
    {
        static void Main(string[] args)
        {
            var text = File.ReadAllText("narcissist.kt");
            Console.WriteLine("Enter the number of lines to be input followed by those lines:\n");
            var n = int.Parse(Console.ReadLine());
            var lines = new string[n];
            for (var i = 0; i < n; i++)
            {
                lines[i] = Console.ReadLine();
            }
            if (lines.Aggregate((a, b) => a + "\r\n" + b) == text)
            {
                Console.WriteLine("\naccept");
            }
            else
            {
                Console.WriteLine("\nreject");
            }
        }
    }
}

