namespace PowerQualityAnalysis
{
    [Table("PQMarkAggregate")]
    public class PQMarkAggregate
    {
        // Primary key for the aggregate measurement
        [PrimaryKey]
        public int ID { get; set; }

        // Foreign key to the corresponding meter
        public int MeterID { get; set; }

        // Year of measurement
        public int Year { get; set; }

        // Month of measurement
        public int Month { get; set; }

        // ITIC value representing standard performance metrics
        public float ITIC { get; set; }

        // SEMI value representing device performance under various conditions
        public float SEMI { get; set; }

        // SARFI values representing momentary interruptions in power
        public float SARFI3 { get; set; }
        public float SARFI12 { get; set; }
        public float SARFI24 { get; set; }

        // THD (Total Harmonic Distortion) JSON string for additional technical details
        [Column("THDJson")]
        public string THDJson { get; set; }

        // Constructor to initialize default values
        public PQMarkAggregate()
        {
            // Default values can be set here if necessary
            ITIC = 0.0f;
            SEMI = 0.0f;
            SARFI3 = 0.0f;
            SARFI12 = 0.0f;
            SARFI24 = 0.0f;
            THDJson = "{}"; // Default to an empty JSON object
        }

        // Method to display a summary of the aggregate measurement
        public string GetSummary()
        {
            return $"Meter ID: {MeterID}, Year: {Year}, Month: {Month}, ITIC: {ITIC}, SEMI: {SEMI}, " +
                   $"SARFI3: {SARFI3}, SARFI12: {SARFI12}, SARFI24: {SARFI24}";
        }
    }
}

