using Microsoft.Extensions.Hosting;

namespace OpenTelemetryTest
{
    // Copyright (c) OpenTelemetry Test Application
    public class Startup
    {
        public IConfiguration Configuration { get; }

        public Startup(IConfiguration configuration)
        {
            Configuration = configuration;
        }

        public void ConfigureServices(IServiceCollection services)
        {
            // Register MVC controllers
            services.AddControllers();

            // Register singleton HttpClient for reuse
            services.AddSingleton<HttpClient>(new HttpClient());

            // Register custom middleware implementation
            services.AddSingleton<CallbackMiddlewareImpl>();
        }

        public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
        {
            // Environment-specific error handling
            if (env.IsDevelopment())
            {
                app.UseDeveloperExceptionPage();
            }
            else
            {
                app.UseExceptionHandler("/error");
            }

            // Custom middleware insertion
            app.UseMiddleware<CallbackMiddleware>();

            // Core pipeline configuration
            app.UseRouting();
            app.UseAuthorization();

            // Endpoint configuration
            app.UseEndpoints(endpoints =>
            {
                endpoints.MapControllers();
            });
        }
    }

    public class CallbackMiddleware
    {
        private readonly RequestDelegate _next;
        private readonly CallbackMiddlewareImpl _middlewareImpl;

        public CallbackMiddleware(
            RequestDelegate next,
            CallbackMiddlewareImpl middlewareImpl)
        {
            _next = next;
            _middlewareImpl = middlewareImpl;
        }

        public async Task InvokeAsync(HttpContext context)
        {
            // Pre-processing logic
            await _middlewareImpl.ProcessRequest(context);

            // Continue pipeline execution
            await _next(context);
        }
    }

    public class CallbackMiddlewareImpl
    {
        public async Task ProcessRequest(HttpContext context)
        {
            // Implement custom telemetry/processing logic
            context.Response.Headers.Add("X-Custom-Middleware", "processed");
            await Task.CompletedTask;
        }
    }
}

