public class StatementAgentInstanceFactoryOnTriggerInfraMerge : StatementAgentInstanceFactoryOnTriggerBase
{
    private readonly InfraOnMergeHelper _mergeHelper;
    private InfraOnMergeViewFactory _viewFactory;

    public StatementAgentInstanceFactoryOnTriggerInfraMerge(InfraOnMergeHelper mergeHelper)
    {
        _mergeHelper = mergeHelper ?? throw new ArgumentNullException(nameof(mergeHelper));
    }

    public override void SetupFactory(AgentInstanceFactoryContext context)
    {
        base.SetupFactory(context);
        _viewFactory = new InfraOnMergeViewFactory();
        _viewFactory.Initialize(context, _mergeHelper);
        AssignViewFactory(_viewFactory);
    }

    public override IReaderWriterLock ObtainAgentInstanceLock(AgentInstanceContext agentInstanceContext)
    {
        return agentInstanceContext.StatementContext.AgentInstanceLockManager.GetLock(GetType());
    }

    public override AgentInstance CreateAgentInstance(AgentInstanceContext context)
    {
        using (ObtainAgentInstanceLock(context).AcquireWriteLock())
        {
            var agentInstance = new MergeTriggerAgentInstance(context, _viewFactory, _mergeHelper);
            agentInstance.Initialize();
            return agentInstance;
        }
    }
}

internal class MergeTriggerAgentInstance : AgentInstance
{
    private readonly InfraOnMergeViewFactory _viewFactory;
    private readonly InfraOnMergeHelper _mergeHelper;

    public MergeTriggerAgentInstance(AgentInstanceContext context, InfraOnMergeViewFactory viewFactory, InfraOnMergeHelper mergeHelper)
        : base(context)
    {
        _viewFactory = viewFactory;
        _mergeHelper = mergeHelper;
    }

    public void Initialize()
    {
        _mergeHelper.Configure(Context, _viewFactory);
    }

    public override void Dispose()
    {
        _mergeHelper.Deactivate();
        base.Dispose();
    }
}

