[FriendlyName("Load PhysicMaterial", "Loads a PhysicMaterial file from your Resources directory.")]
public class uScriptAct_LoadPhysicMaterial : uScriptLogic
{
   public bool Out { get { return true; } }

   public void In(
      [FriendlyName("Asset Path", "The PhysicMaterial file to load.  The supported file format is: \"physicMaterial\".")]
      [AssetPathField(AssetType.PhysicMaterial)]
      string name,

      [FriendlyName("Loaded Asset", "The PhysicMaterial loaded from the specified file path.")]
      out PhysicMaterial asset
   )
   {
      asset = Resources.Load(name) as PhysicMaterial;

      if ( null == asset )
      {
         uScriptDebug.Log( "Asset " + name + " couldn't be loaded, are you sure it's in a Resources folder?", uScriptDebug.Type.Warning );
      }
   }

#if UNITY_EDITOR
   public override Hashtable EditorDragDrop( object o )
   {
      if ( typeof(PhysicMaterial).IsAssignableFrom( o.GetType() ) )
      {
         PhysicMaterial ac = (PhysicMaterial)o;

         string path = UnityEditor.AssetDatabase.GetAssetPath( ac.GetInstanceID( ) );

         int index = path.IndexOf( "Resources/" );

         if ( index > 0 )
         {
            path = path.Substring( index + "Resources/".Length );

            int dot = path.LastIndexOf( '.' );
            if ( dot >= 0 ) path = path.Substring( 0, dot );

            Hashtable hashtable = new Hashtable( );
            hashtable[ "name" ] = path;

            return hashtable;
         }
      }

      return null;
   }
#endif
}

using System;
using System.Web.Mvc;
using Microsoft.Web.Infrastructure.DynamicModuleHelper;
using StructureMap;
using WebActivatorEx;

[assembly: PreApplicationStartMethod(typeof(StructuremapMvc), "Start")]
[assembly: ApplicationShutdownMethod(typeof(StructuremapMvc), "End")]

public static class StructuremapMvc
{
    private static readonly Lazy<IContainer> _container = new Lazy<IContainer>(() => IoC.Initialize());

    public static void Start()
    {
        var container = _container.Value;
        DependencyResolver.SetResolver(new StructureMapDependencyResolver(container));
        DynamicModuleUtility.RegisterModule(typeof(StructureMapScopeModule));
        WriteToLog("Dependency injection container initialized and configured.");
    }

    public static void End()
    {
        _container.Value.Dispose();
        WriteToLog("Dependency injection container disposed.");
    }

    private static void WriteToLog(string message)
    {
        EventLogger.Log(message);
    }
}

public class StructureMapDependencyResolver : IDependencyResolver
{
    private readonly IContainer _container;

    public StructureMapDependencyResolver(IContainer container)
    {
        _container = container;
    }

    public object GetService(Type serviceType)
    {
        return _container.TryGetInstance(serviceType);
    }

    public IEnumerable<object> GetServices(Type serviceType)
    {
        return _container.GetAllInstances(serviceType).Cast<object>();
    }
}

public class StructureMapScopeModule : IHttpModule
{
    public void Init(HttpApplication context)
    {
        context.BeginRequest += (sender, e) => StructureMapDependencyScope.Begin();
        context.EndRequest += (sender, e) => StructureMapDependencyScope.End();
    }

    public void Dispose() { }
}

public static class StructureMapDependencyScope
{
    public static void Begin()
    {
        ObjectFactory.Container.GetNestedContainer();
    }

    public static void End()
    {
        ObjectFactory.Container.DisposeNestedContainer();
    }
}

public static class IoC
{
    public static IContainer Initialize()
    {
        return new Container(c => c.Scan(scanner =>
        {
            scanner.TheCallingAssembly();
            scanner.WithDefaultConventions();
        }));
    }
}

public static class EventLogger
{
    public static void Log(string message)
    {
        // Log the message to a logging system or console
        Console.WriteLine($"[LOG] {DateTime.Now}: {message}");
    }
}

