public class PropertyTypePicker : ListBox
{
    private string[] _value;
    private bool _multiple;

    public string[] SelectedValues
    {
        get { return _value ?? Array.Empty<string>(); }
        set { _value = value; SetSelectedItems(); }
    }

    public bool AllowMultipleSelection
    {
        get { return _multiple; }
        set { _multiple = value; SetSelectionMode(); }
    }

    protected override void OnInit(EventArgs e)
    {
        base.OnInit(e);
        SetSelectionMode();
        PopulatePropertyTypes();
        SetSelectedItems();
    }

    private void SetSelectionMode()
    {
        SelectionMode = _multiple ? ListSelectionMode.Multiple : ListSelectionMode.Single;
    }

    private void PopulatePropertyTypes()
    {
        var propertyTypes = GetPropertyTypesFromBusinessLogic();
        Items.Clear();

        foreach (var propertyType in propertyTypes)
        {
            Items.Add(new ListItem(propertyType.Name, propertyType.Id));
        }
    }

    private void SetSelectedItems()
    {
        if (_value != null)
        {
            foreach (string val in _value)
            {
                ListItem item = Items.FindByValue(val);
                if (item != null)
                {
                    item.Selected = true;
                }
            }
        }
    }

    private IEnumerable<PropertyType> GetPropertyTypesFromBusinessLogic()
    {
        // Here you would interact with your business logic layer
        // For demonstration, let's use some mock data

        return new[]
        {
            new PropertyType { Id = "1", Name = "Apartment" },
            new PropertyType { Id = "2", Name = "House" },
            new PropertyType { Id = "3", Name = "Studio" },
            new PropertyType { Id = "4", Name = "Condo" },
            new PropertyType { Id = "5", Name = "Villa" }
        };
    }

    protected override void Render(HtmlTextWriter writer)
    {
        writer.AddAttribute(HtmlTextWriterAttribute.Name, this.UniqueID);
        writer.AddAttribute(HtmlTextWriterAttribute.Size, _multiple ? "5" : "1");
        writer.AddAttribute(HtmlTextWriterAttribute.Multiple, _multiple.ToString().ToLower());
        writer.RenderBeginTag(HtmlTextWriterTag.Select);

        foreach (ListItem item in Items)
        {
            item.RenderControl(writer);
        }

        writer.RenderEndTag(); // </select>
    }
}

