namespace Shape
{
    class Handler
    {
        static void Main(string[] args)
        {
            int i, flip, N = 100000;
            int[] q = new int[N + 1];
            q[1] = q[2] = 1;
 
            for (i = 3; i <= N; i++)
                q[i] = q[i - q[i - 1]] + q[i - q[i - 2]];
 
            for (i = 1; i <= 10; i++)
                Console.Write("{0}{1}", q[i], i == 10? '\n' :'');
 
            Console.WriteLine("{0}", q[1000]);
 
            for (flip = 0, i = 1; i < N; i++)
                flip += q[i] > q[i + 1]? 1 : 0;
 
            Console.WriteLine("flips: {0}", flip);
        }
    }
}

