using System;
using Microsoft.VisualStudio.OLE.Interop;

public class ComEventSink<T> where T : class
{
    private IConnectionPoint _connectionPoint;
    private uint _cookie;
    private bool _unadvised;

    public ComEventSink(object comObject, T eventSink)
    {
        if (comObject is not IConnectionPointContainer cpc)
        {
            throw new ArgumentException("COM object does not implement IConnectionPointContainer.");
        }

        Guid eventInterfaceGuid = typeof(T).GUID;
        cpc.FindConnectionPoint(ref eventInterfaceGuid, out _connectionPoint);

        if (_connectionPoint == null)
        {
            throw new InvalidOperationException("Connection point not found for the event interface.");
        }

        _connectionPoint.Advise(eventSink, out _cookie);
    }

    public void Unadvise()
    {
        if (!_unadvised)
        {
            if (_connectionPoint != null)
            {
                try
                {
                    _connectionPoint.Unadvise(_cookie);
                }
                finally
                {
                    _cookie = 0;
                    _connectionPoint = null;
                    _unadvised = true;
                }
            }
        }
    }
}

using System;
 
public class Chowla
{
    public static int chowla(int n)
    {
        int sum = 0;
        int i = 2;
        while (i * i <= n)
        {
            if (n % i == 0)
            {
                sum = sum + i;
                int j = n / i;
                if (i!= j)
                {
                    sum = sum + j;
                }
            }
            i = i + 1;
        }
        return sum;
    }
 
    public static void Main()
    {
        for (int n = 1; n <= 37; n++)
        {
            Console.WriteLine("chowla({0}) = {1}", n, chowla(n));
        }
 
        int count = 0;
        int power = 100;
        for (int n = 2; n <= 10000000; n++)
        {
            if (chowla(n) == 0)
            {
                count = count + 1;
            }
            if (n % power == 0)
            {
                Console.WriteLine("There are {0} primes < {1}", count, power);
                power = power * 10;
            }
        }
 
        count = 0;
        int limit = 350000000;
        int k = 2;
        int kk = 3;
        while (true)
        {
            int p = k * kk;
            if (p > limit)
            {
                break;
            }
            if (chowla(p) == p - 1)
            {
                Console.WriteLine("{0} is a perfect number", p);
                count = count + 1;
            }
            k = kk + 1;
            kk = kk + k;
        }
        Console.WriteLine("There are {0} perfect numbers < {1}", count, limit);
    }
}

