namespace WikiSearchEngine
{
    // Represents a document within the wiki system.
    public class Document
    {
        public string Name { get; private set; }
        public string Content { get; private set; }

        public Document(string name, string content)
        {
            if (string.IsNullOrWhiteSpace(name))
            {
                throw new ArgumentException("Document name cannot be null or empty.", nameof(name));
            }

            if (content == null)
            {
                throw new ArgumentNullException(nameof(content));
            }

            Name = name;
            Content = content;
        }

        public override string ToString()
        {
            return $"Document: {Name}";
        }
    }

    // Represents a match for a specific word within the document.
    public class WordMatch
    {
        public string Word { get; private set; }
        public int Position { get; private set; }

        public WordMatch(string word, int position)
        {
            if (string.IsNullOrWhiteSpace(word))
            {
                throw new ArgumentException("Word cannot be null or empty.", nameof(word));
            }

            if (position < 0)
            {
                throw new ArgumentOutOfRangeException(nameof(position), "Position cannot be negative.");
            }

            Word = word;
            Position = position;
        }

        public override string ToString()
        {
            return $"{Word} (Pos: {Position})";
        }
    }

    // Encapsulates the result of a search operation, linking a document with its matching words and a relevance score.
    public class SearchResult
    {
        private readonly Document _document;
        private readonly List<WordMatch> _matches;
        private double _relevance;

        // Read-only properties to expose the internal state.
        public Document Document => _document;
        public ReadOnlyCollection<WordMatch> Matches => _matches.AsReadOnly();
        public double Relevance => _relevance;

        // Constructor that initializes a search result with a specified document.
        public SearchResult(Document document)
        {
            if (document == null)
            {
                throw new ArgumentNullException(nameof(document), "The document cannot be null.");
            }
            _document = document;
            _matches = new List<WordMatch>();
            _relevance = 0.0;
        }

