        public void AddCommand(TrackSectionCommand command)
        {
            Commands.Add(command);
        }
    }

    public class TrackSectionReadingResult
    {
        public List<TrackSection> Sections { get; set; } = new List<TrackSection>();
        public long FinalPosition { get; set; }
    }

    public TrackSectionReadingResult Read(Stream inputStream, long startPosition)
    {
        var result = new TrackSectionReadingResult();
        inputStream.Position = startPosition;

        TrackSection currentSection = null;

        while (inputStream.Position < inputStream.Length)
        {
            byte commandByte = (byte)inputStream.ReadByte();
            byte secondByte = (byte)inputStream.ReadByte();

            if (commandByte == 255 && secondByte == 255)
            {
                result.FinalPosition = inputStream.Position;
                break;
            }

            switch (commandByte)
            {
                case 0x01: // Start new section
                    currentSection = new TrackSection();
                    result.Sections.Add(currentSection);
                    currentSection.Length = BitConverter.ToSingle(new byte[] { secondByte, (byte)inputStream.ReadByte(),
                        (byte)inputStream.ReadByte(), (byte)inputStream.ReadByte() }, 0);
                    break;

                case 0x02: // Curvature command
                    if (currentSection != null)
                    {
                        currentSection.Curvature = BitConverter.ToSingle(new byte[] { secondByte,
                            (byte)inputStream.ReadByte(), (byte)inputStream.ReadByte(),
                            (byte)inputStream.ReadByte() }, 0);
                    }
                    break;

                default: // Custom section command
                    if (currentSection != null)

