[RoutePrefix("api/stl/loading/channels")]
public class StlActionsLoadingChannelsController : ApiController
{
    [HttpPost, Route("")]
    public IHttpActionResult GetChannels([FromBody] ChannelLoadingRequest request)
    {
        try
        {
            var publishmentSystemInfo = PublishmentSystemManager.GetPublishmentSystemInfo(request.PublishmentSystemId);
            if (publishmentSystemInfo == null) return BadRequest("Invalid Publication System");

            var parentNodeId = request.ParentId > 0 ? request.ParentId : publishmentSystemInfo.RootChannelId;
            var childNodeIds = GetNodeIdListByParentId(publishmentSystemInfo.Id, parentNodeId);

            var resultBuilder = new StringBuilder();
            foreach (var nodeId in childNodeIds)
            {
                var nodeInfo = NodeManager.GetNodeInfo(publishmentSystemInfo.Id, nodeId);
                if (nodeInfo == null) continue;

                var rowHtml = GetChannelRowHtml(publishmentSystemInfo, nodeInfo, request);
                resultBuilder.Append(rowHtml);
            }

            return Ok(new
            {
                Html = resultBuilder.ToString(),
                TotalCount = childNodeIds.Count
            });
        }
        catch (Exception ex)
        {
            LogUtils.AddErrorLog(ex);
            return InternalServerError();
        }
    }

    private string GetChannelRowHtml(PublishmentSystemInfo publishmentSystem, NodeInfo nodeInfo, ChannelLoadingRequest request)
    {
        var contentCount = ContentManager.GetCountByNodeId(publishmentSystem.Id, nodeInfo.Id);
        var hasChildren = NodeManager.HasChildren(publishmentSystem.Id, nodeInfo.Id);

        var builder = new StringBuilder();
        builder.AppendFormat(
            "<li data-id='{0}' class='channel-item {1}'>",
            nodeInfo.Id,
            hasChildren ? "has-children" : string.Empty
        );

        if (request.ShowTreeLine)
        {
            builder.Append("<span class='tree-line'></span>");
        }

        builder.AppendFormat(
            "<a href='#' onclick='loadChannelChildren({0})'>{1} ({2})</a>",
            nodeInfo.Id,
            nodeInfo.NodeName,
            request.ShowContentCount ? contentCount.ToString() : string.Empty
        );

        builder.Append("</li>");
        return builder.ToString();
    }

