public class SAPSessionInfo : UserControl
{
    private GuiSession session;
    private Label lblSessionInfo;
    private ListBox lstSessionInfo;
    private Dictionary<string, string> sessionDetails;

    public SAPSessionInfo(GuiSession guiSession)
    {
        session = guiSession;
        sessionDetails = new Dictionary<string, string>();
        InitializeComponent();
        SubscribeToSessionEvents();
    }

    private void InitializeComponent()
    {
        lblSessionInfo = new Label();
        lstSessionInfo = new ListBox();

        lblSessionInfo.Text = "SAP Session Info";
        lblSessionInfo.Dock = DockStyle.Top;

        lstSessionInfo.Dock = DockStyle.Fill;

        Controls.Add(lstSessionInfo);
        Controls.Add(lblSessionInfo);
    }

    private void SubscribeToSessionEvents()
    {
        session.OnSetSession += Current_OnSetSession;
        session.OnEndRequest += Session_EndRequest;
        session.OnDestroy += Session_Destroy;
    }

    private void Current_OnSetSession(object sender, EventArgs e)
    {
        UpdateSessionDetails();
    }

    private void Session_EndRequest(object sender, EventArgs e)
    {
        UpdateSessionDetails();
    }

    private void Session_Destroy(object sender, EventArgs e)
    {
        ResetUI();
    }

    private void UpdateSessionDetails()
    {
        if (session != null)
        {
            sessionDetails["SessionId"] = session.SessionId.ToString();
            sessionDetails["User"] = session.User;
            sessionDetails["Client"] = session.Client;
            sessionDetails["Language"] = session.Language;

            Invoke(new Action(ShowSessionInfo));
        }
    }

    private void ResetUI()
    {
        sessionDetails.Clear();
        Invoke(new Action(ShowSessionInfo));
    }

    private void ShowSessionInfo()
    {
        lstSessionInfo.Items.Clear();
        foreach (var detail in sessionDetails)
        {
            lstSessionInfo.Items.Add($"{detail.Key}: {detail.Value}");
        }
    }

    protected override void Dispose(bool disposing)
    {
        if (disposing)
        {
            UnsubscribeFromSessionEvents();
            if (components != null)
            {
                components.Dispose();
            }
        }
        base.Dispose(disposing);
    }

    private void UnsubscribeFromSessionEvents()
    {
        session.OnSetSession -= Current_OnSetSession;
        session.OnEndRequest -= Session_EndRequest;

