public class EndScreenController : MonoBehaviour
{
    public UnityEngine.UI.Text winnerText;
    public UnityEngine.UI.Text player1Text;
    public UnityEngine.UI.Text player2Text;
    public UnityEngine.UI.Text nextLeftPlayers;
    public UnityEngine.UI.Text nextRightPlayers;

    private string matchId;
    private EventInfo eventInfo;

    public struct MatchInfo
    {
        public string state;
        public Bot[] bots;
    }

    public struct Bot
    {
        public string name;
        public int tournamentId;
        public int points;
    }
    public struct UpcomingMatches
    {
        public Match[] matches;
    }
    public struct Match
    {
        public Bot[] bots;
    }

        public void OnActivation(string matchId, EventInfo info)
    {
        this.matchId = matchId;
        this.eventInfo = info;
        gameObject.SetActive(true);

        winnerText.text = "Loading...";
        player1Text.text = "Player 1: Loading...";
        player2Text.text = "Player 2: Loading...";
        nextLeftPlayers.text = "";
        nextRightPlayers.text = "";
         StartCoroutine(DownloadMatchInfo());

    }

    IEnumerator DownloadMatchInfo()
    {
        yield return new WaitForSeconds(1f); // Simulate network delay

        MatchInfo matchInfo = new MatchInfo();
        matchInfo.state = "completed";
        matchInfo.bots = new Bot[2];
        matchInfo.bots[0].name = "Bot A";
        matchInfo.bots[0].points = 10;
        matchInfo.bots[1].name = "Bot B";
        matchInfo.bots[1].points = 5;

        OnMatchInfoDownloaded(matchInfo);

    }
        private void OnMatchInfoDownloaded(MatchInfo matchInfo)
    {
        if (matchInfo.state == "completed")
        {
           string resultText= createText(matchInfo);
            winnerText.text = resultText;

            StartCoroutine(DownloadUpcomingMatches());
        }
    }

    IEnumerator DownloadUpcomingMatches()
    {
        yield return new WaitForSeconds(0.5f);

        UpcomingMatches upcomingMatches = new UpcomingMatches();
        upcomingMatches.matches = new Match[3];
        upcomingMatches.matches[0].bots = new Bot[2] { new Bot { name = "Bot C" }, new Bot { name = "Bot D" } };
        upcomingMatches.matches[1].bots = new Bot[2] { new Bot { name = "Bot E" }, new Bot { name = "Bot F" } };
        upcomingMatches.matches[2].bots = new Bot[2] { new Bot { name = "Bot G" }, new Bot { name = "Bot H" } };

        OnUpcomingMatchesDownloaded(upcomingMatches);
    }

