using RestSharp;
using DropNet.Models;
using DropNet.Authenticators;

public class DropNetClient
{
    private readonly RequestHelper _requestHelper;
    private UserLogin _userLogin;

    public DropNetClient(string apiKey, string appSecret)
    {
        _requestHelper = new RequestHelper(apiKey, appSecret);
    }

    public string GetTokenAndBuildUrl(string callbackUrl)
    {
        var token = GetToken();
        return _requestHelper.BuildAuthorizeUrl(token, callbackUrl);
    }

    public string GetToken()
    {
        var request = _requestHelper.CreateRequest(ApiType.Base, "oauth/request_token", Method.POST);
        var response = _requestHelper.Execute(request);
        _userLogin = new UserLogin { Token = response.Content };
        return _userLogin.Token;
    }

    public UserLogin GetAccessToken(string code)
    {
        var request = _requestHelper.CreateRequest(ApiType.Base, "oauth/access_token", Method.POST);
        request.AddParameter("code", code);
        var response = _requestHelper.Execute(request);
        _userLogin = new UserLogin
        {
            Token = response.Content,
            TokenSecret = response.Headers.First(h => h.Name == "oauth_token_secret").Value.ToString()
        };
        return _userLogin;
    }

    public AccountInfo GetAccountInfo()
    {
        var request = _requestHelper.CreateRequest(ApiType.Base, "account/info", Method.GET);
        request.AddHeader("Authorization", $"Bearer {_userLogin.Token}");
        var response = _requestHelper.Execute(request);
        return JsonConvert.DeserializeObject<AccountInfo>(response.Content);
    }

    public void DisableAccessToken()
    {
        var request = _requestHelper.CreateRequest(ApiType.Base, "oauth/revoke_token", Method.POST);
        request.AddHeader("Authorization", $"Bearer {_userLogin.Token}");
        _requestHelper.Execute(request);
        _userLogin = null;
    }
}

public class RequestHelper
