namespace Code2Xml.Core.Generators.Smalltalk {
    [Export(typeof(ICstGenerator))]
    public class SmalltalkCstGenerator : CstGeneratorUsingAntlr4<SmalltalkParser> {
        public SmalltalkCstGenerator() : base(".v") { }

        protected override string LanguageName => "Smalltalk";
        public override string LanguageVersion => "Smalltalk-80";

        protected override Lexer CreateLexer(ICharStream stream) {
            return new SmalltalkLexer(stream);
        }

        protected override SmalltalkParser CreateParser(CommonTokenStream stream) {
            return new SmalltalkParser(stream);
        }

        protected override CstNode Parse(SmalltalkParser parser) {
            var context = parser.script();
            return Process(context);
        }

        private static CstNode Process(SmalltalkParser.ScriptContext context) {
            var root = new CstNode("Script");

            foreach (var expression in context.expression()) {
                var exprNode = ProcessExpression(expression);
                root.AddChild(exprNode);
            }

            return root;
        }

        private static CstNode ProcessExpression(SmalltalkParser.ExpressionContext expr) {
            var node = new CstNode("Expression");

            if (expr.assignment() != null) {
                node.AddChild(ProcessAssignment(expr.assignment()));
            }
            else if (expr.messageSend() != null) {
                node.AddChild(ProcessMessageSend(expr.messageSend()));
            }

            return node;
        }

        private static CstNode ProcessAssignment(SmalltalkParser.AssignmentContext assignment) {
            var node = new CstNode("Assignment");
            node.AddChild(new CstNode("Identifier", assignment.IDENTIFIER().GetText()));
            node.AddChild(ProcessExpression(assignment.expression()));
            return node;
        }

        private static CstNode ProcessMessageSend(SmalltalkParser.MessageSendContext msgSend) {
            var node = new CstNode("MessageSend");
            node.AddChild(ProcessReceiver(msgSend.receiver()));

            foreach (var message in msgSend.message()) {
                node.AddChild(ProcessMessage(message));
            }

            return node;
        }

        private static CstNode ProcessReceiver(SmalltalkParser.ReceiverContext receiver) {
            return receiver is SmalltalkParser.VariableReceiverContext varReceiver

