    [TestFixture]
    public class RandomGeneratorTest
    {
        private RandomGenerator _rng;

        [SetUp]
        public void Setup()
        {
            // Initialize the random generator instance before each test.
            _rng = new RandomGenerator();
        }

        [TearDown]
        public void Teardown()
        {
            // Dispose of the random generator instance after each test.
            if (_rng != null)
            {
                _rng.Dispose();
                _rng = null;
            }
        }

        // Helper assertion for validating integer ranges.
        private void AssertInRange(int value, int min, int max)
        {
            Assert.GreaterOrEqual(value, min, $"Value {value} is less than minimum {min}");
            Assert.LessOrEqual(value, max, $"Value {value} is greater than maximum {max}");
        }

        // Helper assertion for validating float ranges.
        private void AssertInRange(float value, float min, float max)
        {
            Assert.GreaterOrEqual(value, min, $"Value {value} is less than minimum {min}");
            Assert.LessOrEqual(value, max, $"Value {value} is greater than maximum {max}");
        }

        [Test]
        public void TestRandomIntegerWithinRange()
        {
            int min = 10;
            int max = 100;
            // Repeat multiple times to ensure reliability.
            for (int i = 0; i < 50; i++)
            {
                int result = _rng.NextInt(min, max);
                AssertInRange(result, min, max);
            }
        }

        [Test]
        public void TestRandomFloatWithinRange()
        {
            float min = -50.0f;
            float max = 50.0f;
            for (int i = 0; i < 50; i++)
