using System;
using System.Collections.Generic;
using System.Management.Automation;
using Microsoft.Azure.Commands.Network.Models;
using Microsoft.Azure.Management.Network.Models;

namespace Microsoft.Azure.Commands.Network
{
    [Cmdlet(VerbsCommon.New, "AzureApplicationGatewayFrontendPortBase", SupportsShouldProcess = true)]
    public class AzureApplicationGatewayFrontendPortBase : NetworkBaseCmdlet
    {
        [Parameter(
            Mandatory = true,
            HelpMessage = "The name of the frontend port.")]
        [ValidateNotNullOrEmpty]
        public string Name { get; set; }

        [Parameter(
            Mandatory = true,
            HelpMessage = "The port number for the frontend port.")]
        [ValidateNotNullOrEmpty]
        public int Port { get; set; }

        public override void ExecuteCmdlet()
        {
            base.ExecuteCmdlet();

            var frontendPort = NewObject();
            WriteObject(frontendPort);
        }

        private PSApplicationGatewayFrontendPort NewObject()
        {
            var frontendPort = new PSApplicationGatewayFrontendPort
            {
                Name = this.Name,
                Port = this.Port
            };

            frontendPort.Id = GenerateResourceId(frontendPort.Name);
            return frontendPort;
        }

        private string GenerateResourceId(string resourceName)
        {
            var subscriptionId = DefaultProfile.Context.Subscription.Id;
            var resourceGroupName = "yourResourceGroupName"; // This should be dynamically fetched
            return ApplicationGatewayChildResourceHelper.GetFrontendPortResourceId(
                subscriptionId,
                resourceGroupName,
                "yourApplicationGatewayName", // This should be dynamically fetched
                resourceName);
        }
    }
}

