using System;
using System.Collections.Generic;
using System.IO;
using System.Text.RegularExpressions;
 
namespace Raster
{
    public partial class Bitmap
    {
        // ReadFrom constructs a Bitmap object from an io.Reader.
        public static Bitmap ReadPpmFrom(StreamReader r)
        {
            var all = r.ReadToEnd();
            var bss = rxHeader.Match(all).Groups;
            if (bss.Count == 0)
            {
                return null;
            }
            var x = int.Parse(bss[3].Value);
            var y = int.Parse(bss[6].Value);
            var maxval = int.Parse(bss[9].Value);
            if (maxval > 255)
            {
                throw new Exception("16 bit ppm not supported");
            }
            var allCmts = bss[1].Value + bss[4].Value + bss[7].Value + bss[10].Value;
            var b = new Bitmap(x, y);
            b.Comments = rxComment.Matches(allCmts).ToStringArray();
            var b3 = all.Substring(bss[0].Length);
            var n1 = 0;
            for (var i = 0; i < b.px.Length; i++)
            {
                b.px[i].R = (byte)(int.Parse(b3[n1].ToString()) * 255 / maxval);
                b.px[i].G = (byte)(int.Parse(b3[n1 + 1].ToString()) * 255 / maxval);
                b.px[i].B = (byte)(int.Parse(b3[n1 + 2].ToString()) * 255 / maxval);
                n1 += 3;
            }
            return b;
        }
 
        private const string ws = "[ \n\r\t\v\f]";
        private const string cmt = "#[^\n\r]*";
        private const string cmts = "(" + ws + "*" + cmt + "[\n\r])";
        private const string num = "(" + cmts + "+" + ws + "*|" + ws + "+)([0-9]+)";
 
        private static readonly Regex rxHeader = new Regex("^P6" + num + num + num + "(" + cmts + "*" + ")" + ws);
        private static readonly Regex rxComment = new Regex(cmt);
 
        // ReadFile writes binary P6 format PPM from the specified filename.
        public static Bitmap ReadPpmFile(string fn)
        {
            var f = File.OpenText(fn);
            var b = ReadPpmFrom(f);
            f.Close();
            return b;
        }
    }
}

