namespace WebDAVStorageTests
{
    public class WebDAVConfiguration
    {
        public string ServerUrl { get; set; }
        public string Username { get; set; }
        public string Password { get; set; }
    }

    public class WebDAVStorageAdapter
    {
        private readonly WebDAVConfiguration _config;
        private readonly string _basePath;

        public WebDAVStorageAdapter(WebDAVConfiguration config, string basePath)
        {
            _config = config;
            _basePath = basePath;
        }

        public async Task<bool> FileExists(string filePath)
        {
            // Simulate asynchronous file existence check
            await Task.Delay(10);
            return File.Exists(Path.Combine(_basePath, filePath));
        }

        public async Task<FileInfo> GetFileInfo(string filePath)
        {
            // Simulate asynchronous metadata retrieval
            await Task.Delay(10);
            var fullPath = Path.Combine(_basePath, filePath);
            return new FileInfo(fullPath);
        }

        public async Task<bool> ContentIsNotModified(string filePath, string originalContent)
        {
            // Simulate asynchronous file content verification
            await Task.Delay(10);
            var fullPath = Path.Combine(_basePath, filePath);
            if (!File.Exists(fullPath))
                return false;
            string currentContent = await File.ReadAllTextAsync(fullPath);
            return string.Equals(currentContent, originalContent, StringComparison.Ordinal);
        }
    }

