using System;
 
public class Converter
{
    public static string Commatize(ulong n)
    {
        var s = n.ToString();
        var le = s.Length;
        for (var i = le - 3; i >= 1; i -= 3)
        {
            s = s.Substring(0, i) + "," + s.Substring(i);
        }
        return s;
    }
 
    public static void Main()
    {
        var starts = new ulong[] {100, 1000000, 10000000, 1000000000, 7123};
        var counts = new int[] {30, 15, 15, 10, 25};
        for (var i = 0; i < starts.Length; i++)
        {
            var count = 0;
            var j = starts[i];
            var pow = 100UL;
            while (j < pow*10)
            {
                pow *= 10;
            }
            Console.WriteLine("First {0} gapful numbers starting at {1}:", counts[i], Commatize(starts[i]));
            while (count < counts[i])
            {
                var fl = (j/pow)*10 + (j % 10);
                if (j%fl == 0)
                {
                    Console.Write("{0} ", j);
                    count++;
                }
                j++;
                if (j >= 10*pow)
                {
                    pow *= 10;
                }
            }
            Console.WriteLine();
        }
    }
}

using System;
namespace SubString
{
    class Timer
    {
        static void Main(string[] args)
        {
            string s = "0123456789";
            const int n = 3;
            const int m = 2;
            const char c = '3';
            const string z = "345";
 
            // A: starting from n characters in and of m length;
            Console.WriteLine(s.Substring(n, m));
            // B: starting from n characters in, up to the end of the string;
            Console.WriteLine(s.Substring(n, s.Length - n));
            // C: whole string minus the last character;
            Console.WriteLine(s.Substring(0, s.Length - 1));
            // D: starting from a known character within the string and of m length;
            Console.WriteLine(s.Substring(s.IndexOf(c), m));
            // E: starting from a known substring within the string and of m length.
            Console.WriteLine(s.Substring(s.IndexOf(z), m));
        }
    }
}

