        private static readonly IReadOnlyCollection<Type> _systemTypes = new List<Type>
        {
            typeof(int),
            typeof(string),
            typeof(double),
            typeof(float),
            typeof(decimal),
            typeof(bool),
            typeof(DateTime),
            typeof(Guid)
        };

        public static RuntimeTypeModel ConfigureAquaTypes(string? name = null, bool configureDefaultSystemTypes = true)
        {
            var typeModel = RuntimeTypeModel.Create(name);
            return ConfigureAquaTypes(typeModel, configureDefaultSystemTypes);
        }

        public static RuntimeTypeModel ConfigureAquaTypes(this RuntimeTypeModel typeModel, bool configureDefaultSystemTypes = true)
        {
            if (typeModel == null) throw new ArgumentNullException(nameof(typeModel));

            var aquaTypeModel = new AquaTypeModel(typeModel);
            if (configureDefaultSystemTypes)
            {
                ConfigureDefaultSystemTypes(aquaTypeModel);
            }

            aquaTypeModel.ConfigureAquaSpecificTypes();
            return typeModel;
        }

        private static void ConfigureDefaultSystemTypes(AquaTypeModel typeModel)
        {
            foreach (var systemType in _systemTypes)
            {
                typeModel.Add(systemType);
            }
        }
    }

    public class AquaTypeModel
    {
        private readonly RuntimeTypeModel _typeModel;

        public AquaTypeModel(RuntimeTypeModel typeModel)
        {
            _typeModel = typeModel ?? throw new ArgumentNullException(nameof(typeModel));
        }

        public void Add(Type type)
        {
            if (type == null) throw new ArgumentNullException(nameof(type));
            _typeModel.Add(type, false);
        }

        public void ConfigureAquaSpecificTypes()
        {
            ConfigureDynamicTypes();
            ConfigureTypeSystemTypes();
        }

        private void ConfigureDynamicTypes()
        {
            _typeModel.Add(typeof(DynamicObject), false);
            // Additional dynamic type configurations can be added here
        }

        private void ConfigureTypeSystemTypes()
        {
            _typeModel.Add(typeof(TypeInfo), false);

