using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace Handler
{
    class Counter
    {
        static void Main(string[] args)
        {
            double[] test = { 15, 6, 42, 41, 7, 36, 49, 40, 39, 47, 43 };
            Console.WriteLine(string.Join(", ", FiveNums(test)));
 
            test = new double[] { 0, 0, 1, 2, 63, 61, 27, 13 };
            Console.WriteLine(string.Join(", ", FiveNums(test)));
 
            test = new double[] { 0.14082834, 0.09748790, 1.73131507, 0.87636009, -1.95059594, 0.73438555, -0.03035726, 1.46675970, -0.74621349, -0.72588772, 0.63905160, 0.61501527, -0.98983780, -1.00447874, -0.62759469, 0.66206163, 1.04312009, -0.10305385, 0.75775634, 0.32566578 };
            Console.WriteLine(string.Join(", ", FiveNums(test)));
 
            Console.ReadLine();
        }
 
        static double[] FiveNums(double[] arr)
        {
            Array.Sort(arr);
            int mid = arr.Length / 2;
            double[] loQ = (arr.Length % 2 == 0)? arr.Take(mid).ToArray() : arr.Take(mid + 1).ToArray();
            double[] hiQ = arr.Skip(mid).ToArray();
            return new double[] { arr[0], Median(loQ), Median(arr), Median(hiQ), arr[arr.Length - 1] };
        }
 
        static double Median(double[] arr)
        {
            int mid = arr.Length / 2;
            return (arr.Length % 2 == 0)? (arr[mid - 1] + arr[mid]) / 2 : arr[mid];
        }
    }
}

using System;
using System.Collections.Generic;
using System.Reflection;
using UnityEditor;
using UnityEngine;

public static class StaticTestRunner
{
    public static void ClearDebugLog()
    {
        Type logEntriesType = System.Type.GetType("UnityEditor.LogEntries, UnityEditor.dll");
        MethodInfo clearMethod = logEntriesType.GetMethod("Clear", BindingFlags.Static | BindingFlags.Public);
        clearMethod.Invoke(null, null);
    }

    public static void TestImmediately()
    {
        ClearDebugLog();
        UUnitTestSuite testSuite = new UUnitTestSuite();
        List<UUnitTestCase> testCases = FindAllTestCases();

        foreach (var testCase in testCases)
        {
            testSuite.AddTest(testCase);
        }

        testSuite.Run();
        LogTestResults(testSuite);
    }

    public static void TestIncrementally()
    {
        if (EditorApplication.isPlaying)
        {
            if (UnityIncrementalTestRunner.Instance == null)
            {
                UnityIncrementalTestRunner.CreateInstance();
            }
            else
            {
                Debug.LogWarning("Incremental test runner is already active.");
            }
        }
        else
        {
            Debug.LogError("Incremental testing can only be run in play mode.");
        }
    }

    private static List<UUnitTestCase> FindAllTestCases()
    {
        List<UUnitTestCase> testCases = new List<UUnitTestCase>();
        Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();

        foreach (var assembly in assemblies)
        {
            foreach (var type in assembly.GetTypes())
            {
                if (type.IsSubclassOf(typeof(UUnitTestCase)))
                {
                    UUnitTestCase testCase = (UUnitTestCase)Activator.CreateInstance(type);
                    testCases.Add(testCase);
                }
            }
        }

        return testCases;
    }

    private static void LogTestResults(UUnitTestSuite testSuite)
    {
        foreach (var result in testSuite.Results)
        {
            if (result.Passed)
            {
                Debug.Log($"Test '{result.TestCase.GetType().Name}' passed.");
            }
            else
            {
                Debug.LogWarning($"Test '{result.TestCase.GetType().Name}' failed: {result.ErrorMessage}");
            }
        }

        if (testSuite.FailedTestsCount > 0)
        {
            throw new Exception($"{testSuite.FailedTestsCount} test(s) failed.");
        }
    }
}

