    internal class URL
    {
        public string href = string.Empty;

        public string protocol = string.Empty;

        public string host = string.Empty;

        public string auth = string.Empty;

        public string user = string.Empty;

        public string password = string.Empty;

        public string hostname = string.Empty;

        public string port = string.Empty;

        public string relative = string.Empty;

        public string path = string.Empty;

        public string directory = string.Empty;

        public string file = string.Empty;

        public string query = string.Empty;

        public string hash = string.Empty;

        public string pathname = null;

        public string normalizedPath = null;

        public string authority = null;

        private static Regex parser = new Regex("^(?:([^:\\/?#]+):)?(?:\\/\\/((?:(([^:@]*)(?::([^:@]*))?)?@)?([^:\\/?#]*)(?::(\\d*))?))?((((?:[^?#\\/]*\\/)*)([^?#]*))(?:\\?([^#]*))?(?:#(.*))?)");

        // things not populated by the regex (NOTE: i don't think it matters if
        // these are null or "" to start with)
        public static URL Parse(string url)
        {
            URL rval = new URL();
            rval.href = url;
            MatchCollection matches = parser.Matches(url);
            if (matches.Count > 0)
            {
                var matcher = matches[0];
                if (matcher.Groups[1] != null)
                {
                    rval.protocol = matcher.Groups[1].Value;
                }
                if (matcher.Groups[2].Value != null)
                {
                    rval.host = matcher.Groups[2].Value;
                }
                if (matcher.Groups[3].Value != null)
                {
                    rval.auth = matcher.Groups[3].Value;
                }
                if (matcher.Groups[4].Value != null)
                {
                    rval.user = matcher.Groups[4].Value;
                }
                if (matcher.Groups[5].Value != null)
                {
                    rval.password = matcher.Groups[5].Value;
                }
                if (matcher.Groups[6].Value != null)
                {
                    rval.hostname = matcher.Groups[6].Value;
                }
                if (matcher.Groups[7].Value != null)
                {
                    rval.port = matcher.Groups[7].Value;
                }

using System;
 
public class Brazillian
{
    public static bool sameDigits(int n, int b)
    {
        int f = n % b;
        while ((n /= b) > 0)
        {
            if (n % b!= f)
            {
                return false;
            }
        }
        return true;
    }
 
    public static bool isBrazilian(int n)
    {
        if (n < 7) return false;
        if (n % 2 == 0) return true;
        for (int b = 2; b < n - 1; b++)
        {
            if (sameDigits(n, b))
            {
                return true;
            }
        }
        return false;
    }
 
    public static bool isPrime(int n)
    {
        if (n < 2) return false;
        if (n % 2 == 0) return n == 2;
        if (n % 3 == 0) return n == 3;
        int d = 5;
        while (d * d <= n)
        {
            if (n % d == 0) return false;
            d += 2;
            if (n % d == 0) return false;
            d += 4;
        }
        return true;
    }
 
    public static void Main()
    {
        for (var kind = ""; kind!= "prime "; kind += "prime ")
        {
            bool quiet = false;
            int BigLim = 99999;
            int limit = 20;
            Console.WriteLine("First " + limit +'' + kind + "Brazillian numbers:");
            int c = 0;
            int n = 7;
            while (c < BigLim)
            {
                if (isBrazilian(n))
                {
                    if (!quiet) Console.Write(n +'');
                    if (++c == limit)
                    {
                        Console.WriteLine();
                        quiet = true;
                    }
                }
                if (quiet && kind!= "") continue;
                if (kind == "")
                {
                    n++;
                }
                else if (kind == "odd ")
                {
                    n += 2;
                }
                else if (kind == "prime ")
                {
                    while (true)
                    {
                        n += 2;
                        if (isPrime(n)) break;
                    }
                }
                else
                {
                    throw new Exception("Unexpected");
                }
            }
            if (kind == "")
            {
                Console.WriteLine("The " + (BigLim + 1) + "th Brazillian number is: " + n);
                Console.WriteLine();
            }
        }
    }
}

