public class FeedHandler : IHttpHandler
{
    public bool IsReusable => false;

    public void ProcessRequest(HttpContext context)
    {
        var blog = new Blog
        {
            Title = "My Blog",
            Description = "Latest updates from my blog",
            Url = new Uri("http://myblog.com"),
            Posts = new List<Post>
            {
                new Post
                {
                    Title = "First Post",
                    Content = "This is the content of the first post.",
                    Author = "Author Name",
                    AbsoluteUrl = new Uri("http://myblog.com/post1"),
                    LastModified = DateTime.UtcNow,
                    PubDate = DateTime.UtcNow,
                    Excerpt = "Excerpt of the first post."
                },
                new Post
                {
                    Title = "Second Post",
                    Content = "This is the content of the second post.",
                    Author = "Author Name",
                    AbsoluteUrl = new Uri("http://myblog.com/post2"),
                    LastModified = DateTime.UtcNow,
                    PubDate = DateTime.UtcNow,
                    Excerpt = "Excerpt of the second post."
                }
            }
        };

        var feed = new SyndicationFeed
        {
            Title = new TextSyndicationContent(blog.Title),
            Description = new TextSyndicationContent(blog.Description),
            BaseUri = blog.Url,
            Items = GetItems(blog.Posts)
        };

        var formatter = GetFormatter(context.Request.Url.AbsolutePath);
        context.Response.ContentType = formatter.MediaType;

        using (var writer = XmlWriter.Create(context.Response.OutputStream))
        {
            formatter.WriteTo(writer);
        }
    }

    private IEnumerable<SyndicationItem> GetItems(List<Post> posts)
    {
        var items = new List<SyndicationItem>();
        foreach (var post in posts)
        {
            var item = new SyndicationItem
            {
                Title = new TextSyndicationContent(post.Title),
                Content = new TextSyndicationContent(post.Content, TextSyndicationContentKind.Html),
                Id = post.AbsoluteUrl.ToString(),
                LastUpdatedTime = post.LastModified,
                PublishDate = post.PubDate
            };

            item.Authors.Add(new SyndicationPerson(post.Author));

