namespace Chaocipher
{
    class Solution
    {
        private enum Mode
        {
            ENCRYPT,
            DECRYPT
        }

        private static readonly string L_ALPHABET = "HXUCZVAMDSLKPEFJRIGTWOBNYQ";
        private static readonly string R_ALPHABET = "PTLNBQDEOYSFAVZKGJRIHWXUMC";

        private static int indexOf(char[] a, char c)
        {
            for (int i = 0; i < a.Length; ++i)
            {
                if (a[i] == c)
                {
                    return i;
                }
            }
            return -1;
        }

        private static string exec(string text, Mode mode)
        {
            return exec(text, mode, false);
        }

        private static string exec(string text, Mode mode, bool showSteps)
        {
            char[] left = L_ALPHABET.ToCharArray();
            char[] right = R_ALPHABET.ToCharArray();
            char[] eText = new char[text.Length];
            char[] temp = new char[26];

            for (int i = 0; i < text.Length; ++i)
            {
                if (showSteps)
                {
                    Console.WriteLine(new string(left) + "  " + new string(right));
                }
                int index;
                if (mode == Mode.ENCRYPT)
                {
                    index = indexOf(right, text[i]);
                    eText[i] = left[index];
                }
                else
                {
                    index = indexOf(left, text[i]);
                    eText[i] = right[index];
                }
                if (i == text.Length - 1)
                {
                    break;
                }

                // permute left

                if (26 - index >= 0) Array.Copy(left, index, temp, 0, 26 - index);
                Array.Copy(left, 0, temp, 26 - index, index);
                char store = temp[1];
                Array.Copy(temp, 2, temp, 1, 12);
                temp[13] = store;
                left = temp.ToArray();

                // permute right

                if (26 - index >= 0) Array.Copy(right, index, temp, 0, 26 - index);
                Array.Copy(right, 0, temp, 26 - index, index);
                store = temp[0];
                Array.Copy(temp, 1, temp, 0, 25);
                temp[25] = store;
                store = temp[2];
                Array.Copy(temp, 3, temp, 2, 11);
                temp[13] = store;
                right = temp.ToArray();
            }

