void bitwise(int a, int b)
{
    Console.WriteLine("a AND b: " + (a & b));
    Console.WriteLine("a OR b: " + (a | b));
    Console.WriteLine("a XOR b: " + (a ^ b));
    Console.WriteLine("NOT a: " + ~a);
    Console.WriteLine("a << b: " + (a << b)); // left shift
    Console.WriteLine("a >> b: " + (a >> b)); // arithmetic right shift
    Console.WriteLine("a >>> b: " + (a >>> b)); // logical right shift
}

