namespace AIBlockBattleBot
{
    public class Parser : IDisposable
    {
        private readonly Bot _bot;

        public Parser(Bot bot)
        {
            _bot = bot;
        }

        public EngineCommand PollCommand()
        {
            string line = Console.ReadLine();
            if (string.IsNullOrWhiteSpace(line))
            {
                Console.WriteLine("Invalid command: Input is empty.");
                return null;
            }

            var tokens = line.Split(' ', StringSplitOptions.RemoveEmptyEntries);
            if (tokens.Length == 0)
            {
                Console.WriteLine("Invalid command: No tokens found.");
                return null;
            }

            string commandType = tokens[0];
            try
            {
                switch (commandType.ToLower())
                {
                    case "settings":
                        return ParseSettingsCommand(tokens);
                    case "gamestate":
                        return ParseGameStateCommand(tokens);
                    case "player":
                        return ParsePlayerCommand(tokens);
                    case "bot":
                        return ParseBotCommand(tokens);
                    default:
                        Console.WriteLine($"Invalid command type: {commandType}");
                        return null;
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error parsing command: {ex.Message}");
                return null;
            }
        }

        private EngineCommand ParseSettingsCommand(string[] tokens)
        {
            if (tokens.Length < 3)
            {
                Console.WriteLine("Invalid settings command: Not enough arguments.");
                return null;
            }

            string key = tokens[1];
            string value = tokens[2];
            return new SettingsCommand(_bot.MatchSettings, key, value);
        }

        private EngineCommand ParseGameStateCommand(string[] tokens)
        {
            if (tokens.Length < 3)
            {
                Console.WriteLine("Invalid game state command: Not enough arguments.");
                return null;
            }

            string key = tokens[1];
            string value = tokens[2];
            return new GameStateCommand(_bot.GameState, key, value);
        }

