            {
                Console.WriteLine("Strings are equal");
            }
 
            // Create and assign value to string
            string assigned_str = "";
            assigned_str += "Text has been assigned!";
            Console.WriteLine(assigned_str);
 
            // String comparison, compared lexicographically byte-wise same as the asserts above
            if (string1 == "Hello world!" && assigned_str == "Text has been assigned!")
            {
                Console.WriteLine("Strings are equal");
            }
 
            // Cloning -> string can still be used after cloning
            string clone_str = string1;
            Console.WriteLine("String is:{0}  and  Clone string is: {1}", string1, clone_str);
 
            // Copying, string won't be usable anymore, accessing it will cause compiler failure
            string copy_str = string1;
            Console.WriteLine("String copied now: {0}", copy_str);
 
            // Check if string is empty
            string empty_str = "";
            if (empty_str.Length == 0)
            {
                Console.WriteLine("String is empty");
            }
 
            // Append byte, Rust strings are a stream of UTF-8 bytes
            string byte_str = "A";
            Console.WriteLine(byte_str);
 
            // Substrings can be accessed through slices
            string test_str = "Blah String";
            string sub_str = test_str.Substring(0, 11);
            Console.WriteLine(sub_str);
            sub_str = test_str.Substring(1, 5);
            Console.WriteLine(sub_str);
            sub_str = test_str.Substring(3);
            Console.WriteLine(sub_str);
            sub_str = test_str.Substring(0, 2);
            Console.WriteLine(sub_str);
 
            // String replace, note string is immutable
            string org_str = "Hello";
            string new_str = org_str.Replace("l", "a");
            Console.WriteLine(new_str);
            new_str = org_str.Replace("ll", "r");
            Console.WriteLine(new_str);
 
            // Joining strings requires a `String` and an &str or a two `String`s one of which needs an & for coercion
            string str1 = "Hi";

