using System.Threading;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Shared.Collections;
using Microsoft.CodeAnalysis.Structure;

public class PropertyDeclarationStructureProvider
{
    public void CollectBlockSpans(PropertyDeclarationSyntax propertyDeclaration, ArrayBuilder<BlockSpan> spans, bool isMetadataAsSource, CancellationToken cancellationToken)
    {
        if (propertyDeclaration == null)
            return;

        var accessorList = propertyDeclaration.AccessorList;
        if (accessorList == null)
            return;

        CollectCommentBlockSpans(propertyDeclaration, spans, cancellationToken);

        var startLine = propertyDeclaration.GetFirstToken().GetLineSpan().StartLinePosition.Line;
        var endLine = accessorList.GetLastToken().GetLineSpan().EndLinePosition.Line;

        var blockSpan = CreateBlockSpan(startLine, endLine, isMetadataAsSource, propertyDeclaration);
        spans.Add(blockSpan);
    }

    private void CollectCommentBlockSpans(PropertyDeclarationSyntax propertyDeclaration, ArrayBuilder<BlockSpan> spans, CancellationToken cancellationToken)
    {
        var leadingTrivia = propertyDeclaration.GetLeadingTrivia();
        foreach (var trivia in leadingTrivia)
        {
            if (trivia.IsKind(SyntaxKind.SingleLineCommentTrivia) || trivia.IsKind(SyntaxKind.MultiLineCommentTrivia))
            {
                var lineSpan = trivia.GetLineSpan();
                var blockSpan = new BlockSpan(
                    isCollapsible: false,
                    textSpan: trivia.Span,
                    bannerText: trivia.ToFullString().Trim(),
                    autoCollapse: false);
                spans.Add(blockSpan);
            }
        }
    }

    private BlockSpan CreateBlockSpan(int startLine, int endLine, bool isMetadataAsSource, PropertyDeclarationSyntax propertyDeclaration)
    {
        var nextSibling = propertyDeclaration.GetNextSibling();
        var compressEmptyLines = nextSibling is PropertyDeclarationSyntax || nextSibling is IndexerDeclarationSyntax;

        return new BlockSpan(
            isCollapsible: true,
            textSpan: propertyDeclaration.Span,
            hintSpan: propertyDeclaration.Span,
            bannerText: $"Property {propertyDeclaration.Identifier.Text}",
            autoCollapse: false,
            type: BlockTypes.Property,
            isDefaultCollapsed: isMetadataAsSource,
            isNonNestable: false,
            isCollapsibleStart: true,
            isCollapsibleEnd: true,
            compressEmptyLines: compressEmptyLines);

