namespace DotNetNuke.UI.Skins
{
    /// <summary>
    /// Provides data for skin-related events.
    /// </summary>
    public class SkinEventArgs : EventArgs
    {
        /// <summary>
        /// The Skin object associated with the event.
        /// </summary>
        private readonly Skin _skin;

        /// <summary>
        /// Initializes a new instance of the SkinEventArgs class with the specified Skin.
        /// </summary>
        /// <param name="skin">The Skin object to associate with the event.</param>
        public SkinEventArgs(Skin skin)
        {
            _skin = skin ?? throw new ArgumentNullException(nameof(skin), "Skin cannot be null.");
        }

        /// <summary>
        /// Gets the Skin object associated with the event.
        /// </summary>
        public Skin Skin
        {
            get { return _skin; }
        }
    }

    /// <summary>
    /// Represents a skin used in the DotNetNuke framework.
    /// </summary>
    public class Skin
    {
        /// <summary>
        /// The name of the skin.
        /// </summary>
        private readonly string _name;

        /// <summary>
        /// The path to the skin file.
        /// </summary>
        private readonly string _path;

        /// <summary>
        /// Initializes a new instance of the Skin class with the specified name and path.
        /// </summary>
        /// <param name="name">The name of the skin.</param>
        /// <param name="path">The path to the skin file.</param>
        public Skin(string name, string path)
        {
            _name = name ?? throw new ArgumentNullException(nameof(name), "Name cannot be null.");
            _path = path ?? throw new ArgumentNullException(nameof(path), "Path cannot be null.");
        }

        /// <summary>
        /// Gets the name of the skin.
        /// </summary>
        public string Name
        {
            get { return _name; }
        }

        /// <summary>
        /// Gets the path to the skin file.
        /// </summary>
        public string Path
        {
            get { return _path; }
        }

        /// <summary>
        /// Returns a string that represents the current object.
        /// </summary>
        /// <returns>A string that represents the current object.</returns>
        public override string ToString()
        {
            return $"Skin Name: {_name}, Path: {_path}";
        }
    }
}

