namespace LinkedListDuplicateRemoval
{
    // Class representing a node in a singly linked list
    public class Node
    {
        public int Data;       // Integer data held in the node
        public Node Next;      // Pointer to the next node in the list

        // Constructor to initialize the node with data
        public Node(int data)
        {
            this.Data = data;
            this.Next = null;
        }
    }

    class Builder
    {
        // Inserts a new node with the given value at the end of the linked list
        static Node Insert(Node head, int value)
        {
            Node newNode = new Node(value);
            if (head == null)
            {
                return newNode;
            }

            Node current = head;
            while (current.Next != null)
            {
                current = current.Next;
            }

            current.Next = newNode;
            return head;
        }

        // Displays all the nodes in the linked list on the console
        static void Display(Node head)
        {
            Node current = head;
            while (current != null)
            {
                Console.Write(current.Data + " ");
                current = current.Next;
            }
            Console.WriteLine();
        }

        // Removes duplicate values from the linked list by creating a new list
        // that contains only the first occurrence of each value.
        static Node RemoveDuplicates(Node head)
        {
            // HashSet for quick lookup of already seen integer values
            HashSet<int> seenValues = new HashSet<int>();

            // New linked list head for storing unique numbers
            Node uniqueHead = null;

            // Traverse the original linked list node by node
            Node current = head;
            while (current != null)
            {
                // If the current node's data has not been encountered before
                if (!seenValues.Contains(current.Data))
                {
                    seenValues.Add(current.Data);
                    // Output the unique value to the console in real-time
                    Console.WriteLine("Unique value encountered: " + current.Data);
                    // Insert the unique value into the new linked list
                    uniqueHead = Insert(uniqueHead, current.Data);
                }
                // Move to the next node in the original list
                current = current.Next;
            }

            return uniqueHead;
        }

