namespace Order
{
    class Library
    {
        static void Main(string[] args)
        {
            var x = 2.0;
            var xi = 0.5;
            var y = 4.0;
            var yi = 0.25;
            var z = x + y;
            var zi = 1.0 / (x + y);
            var pairs = new List<Tuple<double, double>> { Tuple.Create(x, xi), Tuple.Create(y, yi), Tuple.Create(z, zi) };
            var testVal = 0.5;
            Func<double, double, double, double> multiplier = (a, b, m) => a * b * m;
            var test = () =>
            {
                return pairs.Select(pair =>
                {
                    var f = multiplier(pair.Item1, pair.Item2);
                    var result = f(testVal);
                    return $"{pair.Item1} * {pair.Item2} * {testVal} = {result}";
                });
            };
            Console.WriteLine(string.Join("\n", test()));
            Console.ReadKey();
        }
    }
