    // and tracks the completion of a transformation process.
    public class TransformationContext : ITransformationContext
    {
        // Private field to hold the parameter expression.
        private readonly ParameterExpression _parameter;

        // Backing field for the IsCompleted property.
        private bool _isCompleted;

        // Constructor that initializes the context with a parameter expression.
        public TransformationContext(ParameterExpression parameter)
        {
            _parameter = parameter;
            _isCompleted = false;
        }

        // Public property to expose the parameter expression.
        public ParameterExpression Parameter
        {
            get { return _parameter; }
        }

        // Public property to get or set the completion status.
        public bool IsCompleted
        {
            get { return _isCompleted; }
            set { _isCompleted = value; }
        }

        // Override ToString for easier debugging and state tracking.
        public override string ToString()
        {
            return $"TransformationContext: Parameter = {Parameter.Name}, IsCompleted = {IsCompleted}";
        }
    }

