namespace XmlCollection.Tests
{
    [TestClass]
    public class XmlCollectionTests : UnitTestBase<XmlCollectionThens>
    {
        [TestMethod]
        public void GivenNoItems_WhenCreatingXmlCollection_ThenCollectionShouldBeEmpty()
        {
            GivenNoItems()
                .WhenCreatingXmlCollection()
                .ThenCollectionShouldNotBeNull()
                .AndCollectionCountShouldBe(0);
        }

        [TestMethod]
        public void GivenItems_WhenCreatingXmlCollection_ThenCollectionShouldContainItems()
        {
            GivenItems(1, 2, 3)
                .WhenCreatingXmlCollection()
                .ThenCollectionShouldNotBeNull()
                .AndCollectionCountShouldBe(3)
                .AndCollectionShouldContain(1)
                .AndCollectionShouldContain(2)
                .AndCollectionShouldContain(3);
        }

        [TestMethod]
        public void GivenExistingCollection_WhenAddingItem_ThenCollectionShouldContainNewItem()
        {
            GivenExistingCollectionWithItems(1, 2)
                .WhenAddingItem(3)
                .ThenCollectionShouldContain(3)
                .AndCollectionCountShouldBe(3);
        }

        private XmlCollectionTests GivenNoItems()
        {
            Thens.Items = null;
            return this;
        }

        private XmlCollectionTests GivenItems(params int[] items)
        {
            Thens.Items = items;
            return this;
        }

        private XmlCollectionTests GivenExistingCollectionWithItems(params int[] items)
        {
            Thens.Collection = new XmlCollection<int>(items);
            return this;
        }

        private XmlCollectionTests WhenCreatingXmlCollection()
        {
            Thens.Collection = new XmlCollection<int>(Thens.Items);
            return this;
        }

        private XmlCollectionTests WhenAddingItem(int item)
        {
            Thens.Collection.Add(item);
            return this;
        }
    }

