namespace ArchimedeanSpiral
{
    public class ArchimedeanSpiral : Panel
    {
        public ArchimedeanSpiral()
        {
            this.Size = new Size(640, 640);
            this.BackColor = Color.White;
        }
 
        private void DrawGrid(Graphics g)
        {
            g.FillRectangle(new SolidBrush(Color.FromArgb(0xEEEEEE)), 0, 0, this.Width, this.Height);
            var angle = Math.PI / 4;
            var w = this.Width;
            var center = w / 2;
            var margin = 10;
            var numRings = 8;
            var spacing = (w - 2 * margin) / (numRings * 2);
 
            for (var i = 0; i < numRings; i++)
            {
                var pos = margin + i * spacing;
                var size = w - (2 * margin + i * 2 * spacing);
                g.DrawEllipse(Pens.Black, pos, pos, size, size);
                var ia = i * angle;
                var x2 = center + (Math.Cos(ia) * (w - 2 * margin) / 2);
                var y2 = center - (Math.Sin(ia) * (w - 2 * margin) / 2);
                g.DrawLine(Pens.Black, center, center, (int)x2, (int)y2);
            }
        }
 
        private void DrawSpiral(Graphics g)
        {
            g.FillRectangle(new SolidBrush(Color.Magenta), 0, 0, this.Width, this.Height);
            var degrees = Math.PI / 1800;
            var center = this.Width / 2;
            var end = 360 * 2 * 10 * degrees;
            var a = 0.0;
            var b = 20.0;
            var c = 1.0;
            var theta = 0.0;
            while (theta < end)
            {
                var r = a + Math.Pow(theta, 1.0 / c);
                var x = r * Math.Cos(theta);
                var y = r * Math.Sin(theta);
                Plot(g, (int)(center + x), (int)(center - y));
                theta += degrees;
            }
        }
 
        private void Plot(Graphics g, int x, int y)
        {
            g.FillRectangle(new SolidBrush(Color.Black), x, y, 1, 1);
        }
 
        protected override void OnPaint(PaintEventArgs e)
        {
            base.OnPaint(e);
            DrawGrid(e.Graphics);
            DrawSpiral(e.Graphics);
        }
    }
 
