public class GuiInspector
{
    private List<object> inspectObjects = new List<object>();
    private Dictionary<object, Dictionary<string, object>> objectFields = new Dictionary<object, Dictionary<string, object>>();

    public void addInspect(object obj)
    {
        if (!inspectObjects.Contains(obj))
        {
            inspectObjects.Add(obj);
            objectFields[obj] = new Dictionary<string, object>();
        }
    }

    public void apply()
    {
        foreach (var obj in inspectObjects)
        {
            foreach (var field in objectFields[obj])
            {
                // Apply field changes to the object
                SetObjectField(obj, field.Key, field.Value);
            }
        }
    }

    public object findByObject(object obj)
    {
        return inspectObjects.Contains(obj) ? obj : null;
    }

    public object getInspectObject(int index)
    {
        return index >= 0 && index < inspectObjects.Count ? inspectObjects[index] : null;
    }

    public int getNumInspectObjects()
    {
        return inspectObjects.Count;
    }

    public void inspect(object obj)
    {
        if (!inspectObjects.Contains(obj))
        {
            addInspect(obj);
        }
        // Perform inspection logic
    }

    public void refresh()
    {
        // Refresh inspection data
        foreach (var obj in inspectObjects)
        {
            // Refresh logic for each object
        }
    }

    public void removeInspect(object obj)
    {
        if (inspectObjects.Contains(obj))
        {
            inspectObjects.Remove(obj);
            objectFields.Remove(obj);
        }
    }

    public void setAllGroupStateScript(string groupName, bool state)
    {
