public class ProjectRepository
{
    private readonly IMongoCollection<Project> _projects;

    public ProjectRepository(IMongoDatabase database)
    {
        _projects = database.GetCollection<Project>("Projects");
    }

    public async Task InsertOneAsync(Project project)
    {
        await _projects.InsertOneAsync(project);
    }

    public async Task<long> DeleteManyAsync(FilterDefinition<Project> filter)
    {
        var result = await _projects.DeleteManyAsync(filter);
        return result.DeletedCount;
    }

