public class ProductAppService : ApplicationService
{
    private readonly IRepository<Product> _productRepository;

    public ProductAppService(IRepository<Product> productRepository)
    {
        _productRepository = productRepository;
    }

    public async Task<List<ProductDto>> GetAllAsync()
    {
        var products = await _productRepository.GetAllListAsync();
        return products.Select(p => new ProductDto
        {
            Id = p.Id,
            Name = p.Name,
            Price = p.Price
        }).ToList();
    }

    public async Task<int> CreateProduct(ProductCreateInput input)
    {
        var product = new Product
        {
            Name = input.Name,
            Price = input.Price
        };

        await _productRepository.InsertAsync(product);
        await CurrentUnitOfWork.SaveChangesAsync();

        return product.Id;
    }

    [UnitOfWork]
    public async Task CreateProductAndRollback(ProductCreateInput input)
    {
        using (var scope = new TransactionScope(TransactionScopeOption.Required, TransactionScopeAsyncFlowOption.Enabled))
        {
            var product = new Product
            {
                Name = input.Name,
                Price = input.Price
            };

            await _productRepository.InsertAsync(product);
            await CurrentUnitOfWork.SaveChangesAsync();

            throw new UserFriendlyException("Simulated failure to rollback transaction.");
        }
    }

    public async Task<List<int>> GetAllParallel()
    {
        var tasks = new List<Task<int>>();
        for (int i = 0; i < 5; i++)
        {
            tasks.Add(GetAllParallelMethod());
        }

        var results = await Task.WhenAll(tasks);
        return results.ToList();
    }

    private async Task<int> GetAllParallelMethod()
    {
        using (var scope = new TransactionScope(TransactionScopeOption.RequiresNew, TransactionScopeAsyncFlowOption.Enabled))
        {
            var count = await _productRepository.CountAsync();
            return count;
        }
    }
}

