    public class Reader : IGamePlugin
    {
        private IPluginHost pluginHost;
        private string gameCode;

        public void Initialize(IPluginHost host, string gameCode)
        {
            pluginHost = host;
            this.gameCode = gameCode;
        }

        public bool IsCompatible()
        {
            return gameCode.Equals("YLUP", StringComparison.OrdinalIgnoreCase);
        }

        public Format Get_Format(string file, int fileId, string gameCode)
        {
            if (Path.GetExtension(file).Equals(".PACK", StringComparison.OrdinalIgnoreCase))
                return new Format(fileId, "YLUP_PACK");

            return new Format(fileId);
        }

        public sFolder Unpack(string file, int fileId)
        {
            if (!IsCompatible() || !File.Exists(file))
                return new sFolder();

            try
            {
                return PACK.Unpack(file, pluginHost);
            }
            catch (Exception ex)
            {
                pluginHost?.ShowError($"Unpack failed: {ex.Message}");
                return new sFolder();
            }
        }

        public void Read(string file) { }

        public sFolder Pack(string folder, string outputFile, int fileId)
        {
            throw new NotImplementedException("Packing not supported");
        }

        public string PackedExtension => ".PACK";
        public string UnpackedExtension => string.Empty;
    }

    public static class PACK
    {
        public static sFolder Unpack(string filePath, IPluginHost host)
        {
            sFolder root = new sFolder();
            root.files = new List<sFile>();
            root.folders = new List<sFolder>();

            using (BinaryReader reader = new BinaryReader(File.OpenRead(filePath)))
            {
                uint header = reader.ReadUInt32();
                if (header != 0x5041434B) // "PACK" magic
                    throw new InvalidDataException("Invalid PACK header");

                uint fileCount = reader.ReadUInt32();
                for (int i = 0; i < fileCount; i++)
                {
                    sFile file = new sFile();
                    file.name = $"file_{i}.bin";
                    file.offset = (uint)reader.BaseStream.Position;
                    file.size = reader.ReadUInt32();
                    reader.BaseStream.Seek(file.size, SeekOrigin.Current);
                    file.path = filePath;
                    root.files.Add(file);

