        {
            while (running)
            {
                //  Philosopher is thinking (but really is sleeping).
                Thread.Sleep(random.Next(3, 13));
                Console.WriteLine("{0} is hungry.", this.name);
                this.Dine();
            }
        }
 
        public void Dine()
        {
            object fork1, fork2;
            fork1 = this.forkOnLeft;
            fork2 = this.forkOnRight;
 
            while (running)
            {
                lock (fork1)
                {
                    bool locked = false;
                    lock (fork2)
                    {
                        locked = true;
                    }
                    if (locked)
                    {
                        break;
                    }
                }
                Console.WriteLine("{0} swaps forks", this.name);
                fork1 = fork2;
                fork2 = fork1;
            }
            else
            {
                return;

