using System;
 
namespace Corput
{
  class Parser
  {
    /// <summary>
    /// Van der Corput sequence for any base, based on C languange example from Wikipedia.
    /// </summary>
    /// <param name="nth">The nth number in the sequence.</param>
    /// <param name="base">The base of the sequence.</param>
    /// <returns>The nth number in the sequence.</returns>
    public static double Corput(int nth, int @base)
    {
      int n = nth;
      double q = 0.0;
      double bk = 1.0 / @base;
 
      while (n > 0)
      {
        q += (n % @base) * bk;
        n /= @base;
        bk /= @base;
      }
      return q;
    }
 
    static void Main(string[] args)
    {
      for (int base = 2; base <= 5; base++)
      {
        Console.Write($"Base {base}:");
        for (int i = 1; i <= 10; i++)
        {
          double c = Corput(i, base);
          Console.Write($"  {c:F6}");
        }
        Console.WriteLine();
      }
    }
  }
}

