namespace Zenject
{
    public class BindStatement : IDisposable
    {
        IBindingFinalizer _bindingFinalizer;
        readonly List<IDisposable> _disposables = new List<IDisposable>();
        bool _isFinalized;

        public BindInfo SpawnBindInfo()
        {
            Assert.That(!_isFinalized, "Cannot modify binding after finalization");
            Assert.IsNull(_bindingFinalizer, "Cannot modify binding after finalizer set");

            var bindInfo = ZenPools.Spawn<BindInfo>();
            _disposables.Add(bindInfo);
            return bindInfo;
        }

        public void SetFinalizer(IBindingFinalizer finalizer)
        {
            Assert.IsNull(_bindingFinalizer, "Finalizer already assigned");
            Assert.That(!_isFinalized, "Binding already finalized");

            _bindingFinalizer = finalizer;
        }

        public void FinalizeBinding()
        {
            Assert.IsNotNull(_bindingFinalizer, "No binding finalizer configured");
            Assert.That(!_isFinalized, "Binding finalized multiple times");

            _bindingFinalizer.Validate();
            _bindingFinalizer.FinalizeBinding();
            _isFinalized = true;
        }

        public void Reset()
        {
            foreach (var disposable in _disposables)
            {
                ZenPools.Despawn(disposable);
            }

            _disposables.Clear();
            _bindingFinalizer = null;
            _isFinalized = false;
        }

        public void Dispose()
        {
            Reset();
            ZenPools.Despawn(this);
        }

        public void AddDisposable(IDisposable disposable)
        {
            Assert.That(!_isFinalized, "Cannot modify binding after finalization");
            _disposables.Add(disposable);
        }
    }

    public interface IBindingFinalizer
    {
        void Validate();
        void FinalizeBinding();
    }
}

