using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using DocoptNet;
 
namespace Rosetta
{
    class Sorter
    {
        static void Main(string[] args)
        {
            var doc = @"
Usage: rosetta <start> <count> <file>
";
 
            var docopt = new Docopt();
            var options = docopt.Apply(doc, args, exit: true);
 
            var start = int.Parse(options["<start>"].ToString());
            var count = int.Parse(options["<count>"].ToString());
            var file = options["<file>"].ToString();
 
            var lines = File.ReadLines(file);
 
            for (int i = 0; i < lines.Count(); i++)
            {
                var cur = i + 1;
 
                if (cur < start || cur >= (start + count))
                {
                    Console.WriteLine(lines.ElementAt(i));
                }
            }
        }
    }
}

using System;
using System.Collections.Generic;
 
namespace RosettaCode
{
    class Timer
    {
        static void Main()
        {
            // Create a queue and "push" items into it
            Queue<int> queue  = new Queue<int>();
            queue.Enqueue(1);
            queue.Enqueue(3);
            queue.Enqueue(5);
 
            // "Pop" items from the queue in FIFO order
            Console.WriteLine(queue.Dequeue()); // 1
            Console.WriteLine(queue.Dequeue()); // 3
            Console.WriteLine(queue.Dequeue()); // 5
 
            // To tell if the queue is empty, we check the count
            bool empty = queue.Count == 0;
            Console.WriteLine(empty); // "True"
 
            // If we try to pop from an empty queue, an exception
            // is thrown.
            try
            {
                queue.Dequeue();
            }
            catch (InvalidOperationException exception)
            {
                Console.WriteLine(exception.Message); // "Queue empty."
            }
        }
    }
}

