using System;
using System.Threading;

class WaitAnyEx
{
    private static ManualResetEvent myMRE = new ManualResetEvent(false);
    private static Mutex[] mutexes;
    private static EventWaitHandle[] events;
    private static WaitHandle[] wh;

    static void Main(string[] args)
    {
        int numMutexes = 5;
        CreateArray(numMutexes);

        Thread abandonThread = new Thread(AbandonAllMutexes);
        abandonThread.Start();

        try
        {
            Console.WriteLine("Main thread waiting for any mutex or event...");
            int index = WaitHandle.WaitAny(wh);
            if (index < numMutexes)
            {
                Console.WriteLine($"Mutex {index} was signaled.");
            }
            else
            {
                Console.WriteLine($"Event {index - numMutexes} was signaled.");
            }
        }
        catch (AbandonedMutexException ex)
        {
            Console.WriteLine("AbandonedMutexException caught: " + ex.Message);
        }
        catch (Exception ex)
        {
            Console.WriteLine("Exception caught: " + ex.Message);
        }
        finally
        {
            foreach (var mutex in mutexes)
            {
                mutex.Dispose();
            }
            foreach (var evt in events)
            {
                evt.Dispose();
            }
            myMRE.Set(); // Signal any waiting threads to exit
        }
    }

    private static void CreateArray(int numElements)
    {
        mutexes = new Mutex[numElements];
        events = new EventWaitHandle[numElements];

        for (int i = 0; i < numElements; i++)
        {
            mutexes[i] = new Mutex(false, "Mutex_" + i);
            events[i] = new EventWaitHandle(false, EventResetMode.ManualReset, "Event_" + i);
        }

        wh = new WaitHandle[numElements + numElements];
        mutexes.CopyTo(wh, 0);
        events.CopyTo(wh, numElements);
    }

    private static void AbandonAllMutexes()
    {
        Thread.Sleep(1000); // Ensure the main thread is waiting

        for (int i = 0; i < mutexes.Length; i++)
        {
            Console.WriteLine($"Abandoning Mutex {i}...");
            mutexes[i].AcquireMutex();
            // Abandon the mutex by simply exiting
            // No release is called here, which will cause an AbandonedMutexException
            Console.WriteLine("Mutex {i} is now abandoned.");
            Thread.Sleep(500); // Sleep to observe the abandonment
        }

        myMRE.WaitOne(); // Wait until main thread signals
        Console.WriteLine("Abandon thread exiting.");

