namespace Zenject
{
    public class BindStatement : IDisposable
    {
        private IBindingFinalizer _bindingFinalizer;
        private BindInfo _bindInfo;
        private List<IDisposable> _disposables = new List<IDisposable>();
        private bool _isFinalized;
        private bool _isDisposed;

        public BindStatement(BindInfo bindInfo)
        {
            Assert.IsNotNull(bindInfo, "BindInfo cannot be null");
            _bindInfo = bindInfo;
        }

        public BindInfo BindInfo => _bindInfo;

        public void SetFinalizer(IBindingFinalizer finalizer)
        {
            AssertNotFinalized();
            Assert.IsNull(_bindingFinalizer, "Binding finalizer already set");
            _bindingFinalizer = finalizer;
        }

        public void FinalizeBinding()
        {
            AssertNotFinalized();

            try
            {
                if (_bindingFinalizer == null)
                {
                    throw new ZenjectException("Binding was never finalized");
                }

                _bindingFinalizer.FinalizeBinding(this);
                _isFinalized = true;
            }
            catch (Exception ex)
            {
                throw new ZenjectException(
                    $"Error while finalizing binding: {ex.Message}", ex);
            }
        }

        public void AddDisposable(IDisposable disposable)
        {
            Assert.IsNotNull(disposable, "Disposable cannot be null");
            _disposables.Add(disposable);
        }

        public void Reset()
        {
            if (_isDisposed)
            {
                return;
            }

            _bindingFinalizer = null;
            _isFinalized = false;
            ClearDisposables();
        }

        private void ClearDisposables()
        {
            foreach (var disposable in _disposables)
            {
                disposable?.Dispose();
            }
            _disposables.Clear();
        }

        private void AssertNotFinalized()
        {
            if (_isFinalized)
            {
                throw new InvalidOperationException("Cannot modify a finalized binding");
            }
        }

        public void AssertHasFinalizer()
        {
            Assert.IsNotNull(_bindingFinalizer, "Binding has no finalizer");
        }

        public void Dispose()
        {
            if (_isDisposed)
            {
                return;
            }

            ClearDisposables();
            Reset();

