        private string _applicationId = "TestApp";
        private string _listenAddress = "127.0.0.1";
        private string _host = "localhost";
        private int _port = 9110;

        [SetUp]
        public void SetUp()
        {
            // Initialize the dispatcher and register operation handlers
            _dispatcher = new OperationDispatcher();
            _dispatcher.Register<ICalculator, Calculator>();
            _dispatcher.Register<IGreeter, Greeter>();

            // Configure server listener and endpoint
            var serverConfig = new ServerConfig(_listenAddress, _port, _applicationId);
            _serverListener = new LidgrenServerConnectionListener(serverConfig);
            _serverEndpoint = new GenericServerEndpoint(_serverListener, new BinaryMessageSerializer(), _dispatcher);
            _serverEndpoint.Start();
        }

        [TearDown]
        public void TearDown()
        {
            _serverEndpoint.Stop();
            _serverEndpoint.Dispose();
        }

        private ClientConnection CreateClientConnection()
        {
            var clientConfig = new ConnectionConfig(_host, _port, _applicationId);
            var clientChannel = new LidgrenClientChannel(clientConfig, new BinaryMessageSerializer());
            var clientConnection = new ClientConnection(clientChannel);
            clientConnection.Connect();
            return clientConnection;
        }

        [Test]
        public void Should_execute_remote_operations()
        {
            var client = CreateClientConnection();

            // Execute remote calculator operation
            int calcResult = client.ExecuteRemoteMethod<ICalculator, int>(proxy => proxy.Add(5, 7));
            Assert.AreEqual(12, calcResult);

            // Execute remote greeter operation
            string greetResult = client.ExecuteRemoteMethod<IGreeter, string>(proxy => proxy.Greet("Test"));
            Assert.AreEqual("Hello, Test", greetResult);

            client.Disconnect();
        }
    }

