    public DataFieldInfo GetDataFieldInfo(string fullPath)
    {
        string[] pathParts = fullPath.Split('.');

        if (pathParts.Length < 2 || pathParts[0] != aggregateName)
        {
            throw new ArgumentException("Invalid path format or aggregate name mismatch.");
        }

        string relativePath = string.Join(".", pathParts, 1, pathParts.Length - 1);

        DataFieldInfo fieldInfo = aggregateModel.GetFieldInfo(relativePath);

        if (fieldInfo == null)
        {
            throw new ArgumentException($"Data field '{relativePath}' not found in aggregate model.");
        }

        return fieldInfo;
    }

    public string ParsePath(Expression expression)
    {
        if (expression is ParameterExpression parameter)
        {
            return parameter.Name;
        }
        else if (expression is MemberExpression memberExpression)
        {
            string baseName = ParsePath(memberExpression.Expression);
            return $"{baseName}.{memberExpression.Member.Name}";
        }
        else
        {
            throw new ArgumentException("Unsupported expression type.");
        }
    }

