// Enumeration representing types of SQL expression nodes
public enum SqlExpressionType
{
    // Represents a native SQL function node
    NativeSqlFunction,
    // Other types can be added here as needed
}

// Interface for SQL expressions within the expression framework
public interface ISqlExpression
{
    // Gets the type of SQL expression node
    SqlExpressionType ExpressionType { get; }
}

// Immutable representation of a native SQL function within an expression framework
public sealed class NativeSqlFunction : ISqlExpression
{
    // Backing field for the SQL function name
    private readonly string _functionName;

    // Public property to expose the SQL function name
    public string FunctionName
    {
        get { return _functionName; }
    }

    // Implements the ExpressionType from ISqlExpression
    public SqlExpressionType ExpressionType
    {
        get { return SqlExpressionType.NativeSqlFunction; }
    }

    // Private constructor to enforce immutability and controlled instance creation
    private NativeSqlFunction(string functionName)
    {
        if (string.IsNullOrWhiteSpace(functionName))
        {
            throw new ArgumentException("Function name cannot be null or empty.", nameof(functionName));
        }
        _functionName = functionName;
    }

    // Predefined static instances for common SQL aggregation functions
    public static readonly NativeSqlFunction Count = new NativeSqlFunction("COUNT");
    public static readonly NativeSqlFunction Sum = new NativeSqlFunction("SUM");
    public static readonly NativeSqlFunction Average = new NativeSqlFunction("AVG");
    public static readonly NativeSqlFunction Min = new NativeSqlFunction("MIN");
    public static readonly NativeSqlFunction Max = new NativeSqlFunction("MAX");

    // Overrides the Equals method to support case-insensitive comparison based on the function name
    public override bool Equals(object obj)
    {
        if (ReferenceEquals(this, obj))
        {
            return true;
        }

        NativeSqlFunction other = obj as NativeSqlFunction;
        if (other == null)
        {
            return false;
        }

        return string.Equals(this._functionName, other._functionName, StringComparison.OrdinalIgnoreCase);
    }

    // Overrides GetHashCode using case-insensitive hash code computation
    public override int GetHashCode()
    {
        return StringComparer.OrdinalIgnoreCase.GetHashCode(_functionName);
    }

using Microsoft.Extensions.Logging;
using NBitcoin;
using Stratis.Bitcoin.Features.MemoryPool.Interfaces;

namespace Stratis.Bitcoin.Features.MemoryPool.Rules
{
    /// <summary>
    /// Validates the transaction fee is valid.
    /// Checks whether the fee meets minimum fee, free transactions have sufficient priority,
    /// and absurdly high fees.
    /// </summary>
    public class CheckFeeMempoolRule : MempoolRule
    {
        public CheckFeeMempoolRule(Network network,
            ITxMempool mempool,
            MempoolSettings mempoolSettings,
            ChainIndexer chainIndexer,
            ILoggerFactory loggerFactory) : base(network, mempool, mempoolSettings, chainIndexer, loggerFactory)
        {
        }

        public override void CheckTransaction(MempoolValidationContext context)
        {
            Money mempoolRejectFee = this.mempool.GetMinFee(this.settings.MaxMempool * 1000000).GetFee(context.EntrySize);
            if (mempoolRejectFee > 0 && context.ModifiedFees < mempoolRejectFee)
            {
                this.logger.LogTrace("(-)[FAIL_MIN_FEE_NOT_MET]");
                context.State.Fail(MempoolErrors.MinFeeNotMet, $" {context.Fees} < {mempoolRejectFee}").Throw();
            }
            else if (this.settings.RelayPriority && context.ModifiedFees < context.MinRelayTxFee.GetFee(context.EntrySize) &&
                     !TxMempool.AllowFree(context.Entry.GetPriority(this.chainIndexer.Height + 1)))
            {
                this.logger.LogTrace("(-)[FAIL_INSUFFICIENT_PRIORITY]");
                // Require that free transactions have sufficient priority to be mined in the next block.
                context.State.Fail(MempoolErrors.InsufficientPriority).Throw();
            }

            if (context.State.AbsurdFee > 0 && context.Fees > context.State.AbsurdFee)
            {
                this.logger.LogTrace("(-)[INVALID_ABSURD_FEE]");
                context.State.Invalid(MempoolErrors.AbsurdlyHighFee, $"{context.Fees} > {context.State.AbsurdFee}").Throw();
            }
        }
    }
}

