public class SkipExpressionNode : MethodCallExpressionNodeBase
{
    public static readonly MethodInfo[] SupportedMethods = new[]
    {
        LinqUtility.GetSupportedMethod(() => Queryable.Skip<object>(null, 0)),
        LinqUtility.GetSupportedMethod(() => Enumerable.Skip<object>(null, 0))
    };

    private readonly int _count;

    public SkipExpressionNode(MethodCallExpressionParseInfo parseInfo, Expression count)
        : base(parseInfo)
    {
        _count = LinqUtility.GetIntConstantValueFromExpression(count, "count");
    }

    protected override void ApplyNodeSpecificSemantics(QueryModel queryModel, ClauseGenerationContext clauseGenerationContext)
    {
        var skipTakeClause = queryModel.BodyClauses.OfType<SkipTakeClause>().FirstOrDefault();
        if (skipTakeClause != null)
        {
            skipTakeClause.SkipCount = _count;
        }
        else
        {
            queryModel.BodyClauses.Add(new SkipTakeClause(_count, null));
        }
    }

    protected override QueryModel ApplyNodeSpecificSemantics(QueryModel queryModel)
    {
        ApplyNodeSpecificSemantics(queryModel, new ClauseGenerationContext());
        return queryModel;
    }

    public override Expression Resolve(
        ParameterExpression inputParameter,
        Expression expressionToBeResolved,
        ClauseGenerationContext clauseGenerationContext)
    {
        return Source.Resolve(inputParameter, expressionToBeResolved, clauseGenerationContext);
    }
}

public class SkipTakeClause : IBodyClause
{
    public int? SkipCount { get; set; }
    public int? TakeCount { get; set; }

    public SkipTakeClause(int? skipCount, int? takeCount)
    {
        SkipCount = skipCount;
        TakeCount = takeCount;
    }

    public void Accept(IQueryModelVisitor visitor, QueryModel queryModel, int index)
    {
        visitor.VisitSkipTakeClause(this, queryModel, index);
    }

    public IBodyClause Clone(CloneContext cloneContext)
    {
        return new SkipTakeClause(SkipCount, TakeCount);
    }
}

public static class LinqUtility
{
    public static int GetIntConstantValueFromExpression(Expression expression, string parameterName)
    {
        if (expression is ConstantExpression constantExpression && constantExpression.Value is int intValue)
        {
            return intValue;
        }
        throw new ArgumentException($"The {parameterName} must be a constant integer value.", parameterName);

using System;
using System.Collections.Generic;
using System.Linq;

namespace Microsoft.AspNetCore.Razor.Language.Intermediate
{
    public sealed class TagHelperIntermediateNode : IntermediateNode
    {
        public TagHelperIntermediateNode()
        {
            Descriptors = new List<TagHelperDescriptor>();
            Children = new IntermediateNodeCollection(this);
        }

        public string TagName { get; set; }
        public TagMode TagMode { get; set; }
        public List<TagHelperDescriptor> Descriptors { get; }

        public override IntermediateNodeCollection Children { get; }

        public override void Accept(IntermediateNodeVisitor visitor)
        {
            if (visitor == null)
            {
                throw new ArgumentNullException(nameof(visitor));
            }

            visitor.VisitTagHelper(this);
        }

        public override string ToString()
        {
            return FormatNode();
        }

        private string FormatNode()
        {
            var builder = new System.Text.StringBuilder();
            builder.Append($"TagHelper: {TagName}");

            if (Descriptors.Any())
            {
                builder.Append(" [");
                builder.Append(string.Join(", ", Descriptors.Select(d => d.Name)));
                builder.Append("]");
            }

            return builder.ToString();
        }

        public IEnumerable<TagHelperPropertyIntermediateNode> GetProperties()
        {
            return Children.OfType<TagHelperPropertyIntermediateNode>();
        }

        public IEnumerable<TagHelperHtmlAttributeIntermediateNode> GetHtmlAttributes()
        {
            return Children.OfType<TagHelperHtmlAttributeIntermediateNode>();
        }

        public TagHelperBodyIntermediateNode GetBody()
        {
            return Children.OfType<TagHelperBodyIntermediateNode>().FirstOrDefault();
        }
    }
}

