internal sealed class PermissionSetEnumerator : IEnumerator
{
    private PermissionSetEnumeratorInternal m_enumInternal;
    private int m_currentIndex;
    private PermissionSet m_permSet;

    internal PermissionSetEnumerator(PermissionSet permSet)
    {
        if (permSet == null)
            throw new ArgumentNullException(nameof(permSet));

        m_permSet = permSet;
        m_enumInternal = new PermissionSetEnumeratorInternal(permSet);
        Reset();
    }

    public object Current
    {
        get
        {
            if (m_currentIndex < 0)
                throw new InvalidOperationException("Enumeration has not started or has completed.");

            return m_enumInternal.Current;
        }
    }

    public bool MoveNext()
    {
        while (m_enumInternal.MoveNext())
        {
            object current = m_enumInternal.Current;

            if (current is IPermission)
            {
                m_currentIndex++;
                return true;
            }
        }

        m_currentIndex = -1;
        return false;
    }

    public void Reset()
    {
        m_currentIndex = -1;
        m_enumInternal.Reset();
    }

    internal int GetCurrentIndex()
    {
        return m_currentIndex;
    }
}

