        m_tokenEnumerator = new TokenBasedSetEnumerator(permSet);
    }

    public object Current => m_tokenEnumerator.Current;

    public bool MoveNext() => m_tokenEnumerator.MoveNext();

    public void Reset() => m_tokenEnumerator.Reset();
}

