            throw new ArgumentNullException(nameof(permSet));

        m_elements = permSet.ToArray();
        m_currentIndex = -1;
    }

    public object Current
    {
        get
        {
            if (m_currentIndex < 0 || m_currentIndex >= m_elements.Length)
                throw new InvalidOperationException("Enumeration has not started or has completed.");

            return m_elements[m_currentIndex];

