public interface IExecution
{
    // Property to store the results of operations
    IList<IResult> Result { get; set; }

    // Delegate to handle the results of operations
    Func<IList<IResult>, Task> HandleResult { get; set; }

    // Method to notify users of ongoing activities
    Func<Task> NotifyOfActivity { get; set; }

    // Method to notify users when activities are finished
    Func<Task> NotifyActivityFinished { get; set; }

    // Method to handle unexpected exceptions
    Func<Exception, Task<bool>> HandleUnhandledException { get; set; }

    // Method to handle operation timeouts
    Func<Task> HandleTimeout { get; set; }

    // Property for logging and monitoring events
    IApplicationInsights Insights { get; set; }

    // Method to perform pre-execution checks
    Func<object, Task<bool>> PreCheck { get; set; }

    // Method to execute the operation
    Task ExecuteOperationAsync(Func<Task> operation);

    // Method to log events
    Task LogEventAsync(string eventName, IDictionary<string, string> properties = null);
}

public interface IResult
{
    bool IsSuccess { get; set; }
    string Message { get; set; }
}

public interface IApplicationInsights
{
    Task TrackEventAsync(string eventName, IDictionary<string, string> properties = null);
}

public class Execution : IExecution
{
    public IList<IResult> Result { get; set; } = new List<IResult>();
    public Func<IList<IResult>, Task> HandleResult { get; set; }
    public Func<Task> NotifyOfActivity { get; set; }
    public Func<Task> NotifyActivityFinished { get; set; }
    public Func<Exception, Task<bool>> HandleUnhandledException { get; set; }
    public Func<Task> HandleTimeout { get; set; }
    public IApplicationInsights Insights { get; set; }
    public Func<object, Task<bool>> PreCheck { get; set; }

    public async Task ExecuteOperationAsync(Func<Task> operation)
    {
        try
        {
            if (PreCheck != null && !await PreCheck(this))
            {
                throw new InvalidOperationException("Pre-check failed.");
            }

            await NotifyOfActivity?.Invoke();

            await operation();

            await HandleResult?.Invoke(Result);

            await NotifyActivityFinished?.Invoke();
        }
        catch (Exception ex)
        {
            if (HandleUnhandledException != null && await HandleUnhandledException(ex))
            {
                await HandleTimeout?.Invoke();
            }
        }
    }

