using System;
using System.Linq;
 
public class Cusip
{
    public static void Main()
    {
        var cusips = new[]
        {
            "037833100", "17275R102", "38259P508", "594918104", "68389X106", "68389X105"
        };
 
        foreach (var cusip in cusips)
        {
            Console.WriteLine($"{cusip}: {CheckCusip(cusip)}");
        }
    }
 
    public static string CheckCusip(string cusip)
    {
        if (cusip.Length!= 9)
        {
            throw new ArgumentException("CUSIP must be 9 characters");
        }
 
        var sum = 0;
        for (var i = 0; i < cusip.Length; i++)
        {
            if (i == cusip.Length - 1)
            {
                continue;
            }
 
            var v = 0;
            var c = cusip[i];
            if (char.IsDigit(c))
            {
                v = c - '0';
            }
            else if (char.IsLetter(c))
            {
                v = c - 'A' + 1 + 9;
            }
            else if (c == '*')
            {
                v = 36;
            }
            else if (c == '@')
            {
                v = 37;
            }
            else if (c == '#')
            {
                v = 38;
            }
 
            if ((i % 2) == 0)
            {
                v *= 2;
            }
 
            sum += v / 10 + v % 10;
        }
 
        var check = (10 - (sum % 10)) % 10;
        return check == cusip[cusip.Length - 1] - '0'? "VALID" : "INVALID";
    }
}

