public static List<int> Shuffle(List<int> l)
{
    return l.OrderBy(x => Guid.NewGuid()).ToList();
}
 
public static List<int> Bogosort(List<int> l)
{
    l = Shuffle(l);
    while (!InOrder(l))
    {
        l = Shuffle(l);
    }
    return l;
}
 
public static bool InOrder(List<int> l)
{
    for (int i = 0; i < l.Count - 1; i++)
    {
        if (l[i] > l[i + 1])
        {
            return false;
        }
    }
    return true;
}

using System;
using System.Reflection;
using UnityEngine;
using UnityEditor;

public class StaticTestRunner
{
    private static MethodInfo _clearLogMethod;

    [InitializeOnLoadMethod]
    private static void Initialize()
    {
        _clearLogMethod = typeof(Debug).GetMethod("ClearDeveloperConsole",
            BindingFlags.Static | BindingFlags.NonPublic);
    }

    [MenuItem("Testing/Run Tests %#t")]
    public static void TestImmediately()
    {
        ClearDebugLog();
        ExecuteTestSuite();
    }

    private static void ClearDebugLog()
    {
        if (_clearLogMethod != null)
        {
            _clearLogMethod.Invoke(null, null);
        }
    }

    private static void ExecuteTestSuite()
    {
        UUnitTestSuite testSuite = new UUnitTestSuite();
        DiscoverTestCases(testSuite);

        int passedTests = 0;
        int failedTests = 0;

        foreach (UUnitTestCase testCase in testSuite.TestCases)
        {
            UUnitTestResult result = RunTestCase(testCase);

            if (result.Passed)
            {
                passedTests++;
                Debug.Log($"Test Passed: {testCase.GetType().Name}");
            }
            else
            {
                failedTests++;
                Debug.LogError($"Test Failed: {testCase.GetType().Name} - {result.ErrorMessage}");
            }
        }

        LogTestSummary(passedTests, failedTests);
    }

    private static void DiscoverTestCases(UUnitTestSuite testSuite)
    {
        foreach (Type type in Assembly.GetExecutingAssembly().GetTypes())
        {
            if (typeof(UUnitTestCase).IsAssignableFrom(type) && !type.IsInterface && !type.IsAbstract)
            {
                UUnitTestCase testCase = (UUnitTestCase)Activator.CreateInstance(type);
                testSuite.AddTest(testCase);
            }
        }
    }

    private static UUnitTestResult RunTestCase(UUnitTestCase testCase)
    {
        try
        {
            testCase.RunTest();
            return new UUnitTestResult { Passed = true };
        }
        catch (Exception ex)
        {
            return new UUnitTestResult
            {
                Passed = false,
                ErrorMessage = ex.Message
            };
        }
    }

    private static void LogTestSummary(int passedTests, int failedTests)
    {
        Debug.Log($"Test Summary: Passed={passedTests}, Failed={failedTests}");
    }
}

public abstract class UUnitTestCase
{
    public abstract void RunTest();
}

public class UUnitTestResult
{
    public bool Passed { get; set; }

