public class ExistsCommand : SyncCommand
{
    private readonly Cluster cluster;
    private readonly Policy policy;
    private readonly Key key;
    private readonly Partition partition;
    private bool exists;

    public ExistsCommand(Cluster cluster, Policy policy, Key key)
    {
        this.cluster = cluster;
        this.policy = policy;
        this.key = key;
        this.partition = new Partition(key);
    }

    protected override Policy GetPolicy()
    {
        return policy;
    }

    protected override void WriteBuffer()
    {
        SetWrite(policy, true);
        WriteKey(key);
    }

    protected override Node GetNode()
    {
        return partition.GetNodeRead(cluster);
    }

    protected override void ParseResult(int resultCode)
    {
        switch (resultCode)
        {
            case 0:
                exists = true;
                break;
            case 2: // Record not found
                exists = false;
                break;
            default:
                throw new AerospikeException(resultCode);
        }
    }

    public bool Exists()
    {
        Execute();
        return exists;
    }
}

public class SyncCommand
{
    protected virtual Policy GetPolicy() { return null; }
    protected virtual void WriteBuffer() { }
    protected virtual Node GetNode() { return null; }
    protected virtual void ParseResult(int resultCode) { }

    public void Execute()
    {
        Node node = GetNode();
        if (node == null)
        {
            throw new AerospikeException("Failed to find node.");
        }

        try
        {
            byte[] buffer = PrepareBuffer();
            node.Write(buffer);
            int resultCode = node.Read();
            ParseResult(resultCode);
        }
        catch (Exception ex)
        {
            throw new AerospikeException(ex);
        }
    }

    private byte[] PrepareBuffer()
    {
        Policy policy = GetPolicy();
        int size = 20 + policy.SocketTimeout / 1000; // Simplified size calculation
        byte[] buffer = new byte[size];
        WriteBuffer();
        return buffer;
    }
}

