using System;
using System.Threading.Tasks;

namespace ExecutionFramework
{
    public interface IResult { }

    public interface IApplicationInsights
    {
        Task TrackEventAsync(string eventName);
        Task TrackExceptionAsync(Exception ex);
    }

    public interface IExecution
    {
        IApplicationInsights Insights { get; set; }
        Task<IResult> Result { get; }

        Func<Task<bool>> PreCheck { get; set; }
        Func<IResult, Task> HandleResult { get; set; }
        Func<bool, Task> NotifyOfActivity { get; set; }
        Func<Exception, Task> HandleUnhandledException { get; set; }
        Func<Task> HandleTimeout { get; set; }

        async Task ExecuteAsync(Func<Task<IResult>> operation, TimeSpan? timeout = null)
        {
            try
            {
                if (PreCheck != null && !await PreCheck.Invoke())
                    return;

                await (NotifyOfActivity?.Invoke(true) ?? Task.CompletedTask);

                var operationTask = operation.Invoke();
                var completedTask = await Task.WhenAny(operationTask,
                    timeout.HasValue ? Task.Delay(timeout.Value) : Task.Delay(-1));

                if (completedTask == operationTask)
                {
                    var result = await operationTask;
                    await (HandleResult?.Invoke(result) ?? Task.CompletedTask);
                    await Insights?.TrackEventAsync("OperationCompleted");
                }
                else
                {
                    await (HandleTimeout?.Invoke() ?? Task.CompletedTask);
                    await Insights?.TrackEventAsync("OperationTimeout");
                }
            }
            catch (Exception ex)
            {
                await (HandleUnhandledException?.Invoke(ex) ?? Task.CompletedTask);
                await Insights?.TrackExceptionAsync(ex);
            }
            finally
            {
                await (NotifyOfActivity?.Invoke(false) ?? Task.CompletedTask);
            }
        }
    }
}

