namespace CustomControls
{
    public class PropertyTypePicker : ListBox, IMacroGuiRendering
    {
        private string _value = string.Empty;
        private bool _multiple = false;
        private Hashtable ht = new Hashtable();

        public PropertyTypePicker()
        {
            CssClass = "propertyTypePicker";
            // TODO: Add additional initialization logic if needed
        }

        protected override void OnInit(EventArgs e)
        {
            base.OnInit(e);
            SelectionMode = _multiple ? ListSelectionMode.Multiple : ListSelectionMode.Single;
            PopulatePropertyTypes();
        }

        private void PopulatePropertyTypes()
        {
            Items.Clear();
            ht.Clear();

            var propertyTypes = PropertyType.GetAll().OrderBy(pt => pt.Name);
            foreach (var propertyType in propertyTypes)
            {
                if (!ht.ContainsKey(propertyType.Id))
                {
                    Items.Add(new ListItem(propertyType.Name, propertyType.Id.ToString()));
                    ht.Add(propertyType.Id, propertyType);
                }
            }

            if (!string.IsNullOrEmpty(_value))
            {
                var selectedValues = _value.Split(',');
                foreach (var value in selectedValues)
                {
                    var item = Items.FindByValue(value);
                    if (item != null)
                    {
                        item.Selected = true;
                    }
                }
            }
        }

        public string Value
        {
            get
            {
                _value = string.Join(",", Items.Cast<ListItem>().Where(li => li.Selected).Select(li => li.Value));
                return _value;
            }
            set
            {
                _value = value;
                PopulatePropertyTypes();
            }
        }

        public bool Multiple
        {
            get { return _multiple; }
            set
            {
                _multiple = value;
                SelectionMode = _multiple ? ListSelectionMode.Multiple : ListSelectionMode.Single;
            }
        }

        public bool ShowCaption
        {
            get { return true; }
        }
    }
}

