using System;
 
public class Luhn
{
    public static bool CheckLuhn(string number)
    {
        var isOdd = true;
        var sum = 0;
 
        for (var index = number.Length - 1; index >= 0; index--)
        {
            var digit = number[index] - '0';
            sum += isOdd? digit : (digit * 2).Let(it => (it / 10) + (it % 10));
            isOdd =!isOdd;
        }
 
        return (sum % 10) == 0;
    }
 
    public static void Main(string[] args)
    {
        var numbers = new[] { "49927398716", "49927398717", "1234567812345678", "1234567812345670" };
        foreach (var number in numbers)
            Console.WriteLine($"{number.PadRight(16)} is {CheckLuhn(number)? "valid" : "invalid"}");
    }
}
 
