namespace NXTLib
{
    public static class Utils
    {
        public static string AddressByte2String(byte[] address, bool colon = true)
        {
            if (address == null || address.Length != 6)
                throw new ArgumentException("Invalid 6-byte Bluetooth address");

            byte[] reversed = address.Reverse().ToArray();
            string formatted = BitConverter.ToString(reversed);
            return colon ? formatted.Replace('-', ':') : formatted.Replace("-", "");
        }

        public static byte[] AddressString2Byte(string address)
        {
            string cleanAddr = address?.Replace(":", "") ?? "";
            if (cleanAddr.Length != 12)
                throw new ArgumentException("Invalid Bluetooth address format");

            byte[] bytes = new byte[6];
            for (int i = 0; i < 6; i++)
            {
                bytes[i] = Convert.ToByte(cleanAddr.Substring(i * 2, 2), 16);
            }
            Array.Reverse(bytes);
            return bytes;
        }

        public static List<Brick> Combine(IEnumerable<Brick> list1, IEnumerable<Brick> list2)
        {
            var combined = (list1 ?? Enumerable.Empty<Brick>())
                .Concat(list2 ?? Enumerable.Empty<Brick>());

            return combined
                .GroupBy(b => BitConverter.ToString(b.Address))
                .Select(g => g.First())
                .ToList();
        }
    }

    public static class StringExtensions
    {
        public static int GetValue(this string input)
        {
            int.TryParse(input, out int result);
            return result;
        }
    }

    public class Brick
    {
        public byte[] Address { get; set; }
        public string Name { get; set; }
        public DateTime LastSeen { get; set; }
    }
}

