namespace AuthenticationExample
{
    public interface IAuthenticate
    {
        User AuthenticateUser(string hostName, string email, string password);
    }

    public class DbAuthenticate : IAuthenticate
    {
        private readonly IUnitOfWork _unitOfWork;
        private readonly ILogger _logger;

        public DbAuthenticate(IUnitOfWork unitOfWork, ILogger logger)
        {
            _unitOfWork = unitOfWork;
            _logger = logger;
        }

        public User AuthenticateUser(string hostName, string email, string password)
        {
            _logger.Debug("Authenticating user with Email: {0}, Host: {1}", email, hostName);

            var user = _unitOfWork.Users.GetAll()
                .FirstOrDefault(u => u.Email.Equals(email, StringComparison.OrdinalIgnoreCase)
                                  && !u.IsDeleted
                                  && u.AcquisitionType == "Standard");

            if (user == null)
            {
                _logger.Trace("No user found with Email: {0}", email);
                throw new AuthenticationException("Invalid credentials: user record not found.");
            }

            if (!user.Companies.Any(c => c.HostName.Equals(hostName, StringComparison.OrdinalIgnoreCase)))
            {
                _logger.Trace("User {0} does not have access to company with Host: {1}", email, hostName);
                throw new AuthenticationException("Invalid credentials: company access denied.");
            }

            string decryptedPassword = CryptoUtil.Decrypt(user.Password);
            if (!decryptedPassword.Equals(password))
            {
                _logger.Trace("Password mismatch for user: {0}", email);
                throw new AuthenticationException("Invalid credentials: password mismatch.");
            }

            _logger.Debug("User {0} successfully authenticated.", email);
            return user;
        }
    }

    public interface IUnitOfWork
    {
        IRepository<User> Users { get; }
    }

    public interface IRepository<T>
    {
        IQueryable<T> GetAll();
    }

    public class User
    {
        public string Email { get; set; }
        public string Password { get; set; }
        public bool IsDeleted { get; set; }
        public string AcquisitionType { get; set; }
        public Company[] Companies { get; set; }
    }

    public class Company
    {
        public string HostName { get; set; }
    }

