namespace LiveSplit.Web.Share
{
    public partial class SpeedrunComOAuthForm : Form, ISpeedrunComAuthenticator
    {
        private string accessToken;

        public SpeedrunComOAuthForm()
        {
            InitializeComponent();
        }

        private void SpeedrunComOAuthForm_Load(object sender, EventArgs e)
        {
            try
            {
                OAuthWebBrowser.Navigate(new Uri("https://www.speedrun.com/api/auth"));
            }
            catch (Exception ex)
            {
                Log.Error(ex);
            }
        }

        private void OAuthWebBrowser_DocumentCompleted(object sender, WebBrowserDocumentCompletedEventArgs e)
        {
            try
            {
                var documentText = OAuthWebBrowser.Document.Body.InnerHtml;

                if (documentText.Contains("id=\"apikey\""))
                {
                    var startIndex = documentText.IndexOf(">", documentText.IndexOf("id=\"apikey\"")) + 1;
                    var endIndex = documentText.IndexOf("<", startIndex);
                    accessToken = documentText.Substring(startIndex, endIndex - startIndex);
                    ShareSettings.Default.SpeedrunComAccessToken = accessToken;

                    if (this.InvokeRequired)
                    {
                        this.Invoke((Action)delegate { this.Close(); });
                    }
                    else
                    {
                        this.Close();
                    }
                }
            }
            catch (Exception ex)
            {
                Log.Error(ex);
            }
        }

        public string GetAccessToken()
        {
            this.ShowDialog();
            return accessToken;
        }
    }
}

using System;
using System.IO;
using System.Threading;
using GitSharp.Core;
using GitSharp.Core.Tests.Util;
using GitSharp.Tests.GitSharp.Core.Util;
using NUnit.Framework;

namespace GitSharp.Core.Tests
{
    [TestFixture]
    public class IndexModifiedTests : RepositoryTestCase
    {
        [Test]
        public void TestIsModified_fileNoExtension()
        {
            GitIndex index = new GitIndex(db);
            FileInfo file = writeTrashFile("a", "a");
            index.add(trash, file);
            index.write();

            IndexEntry entry = index.GetEntry("a");
            Assert.IsFalse(entry.IsModified(trash, false));

            writeTrashFile("a", "b");
            Thread.Sleep(100); // File system race condition. Give it a moment.
            Assert.IsTrue(entry.IsModified(trash, false));
            Assert.IsFalse(entry.IsModified(trash, true));

            FileStream s = file.OpenRead();
            try
            {
                Assert.IsTrue(entry.IsModified(trash, s, false));
                Assert.IsFalse(entry.IsModified(trash, s, true));
            }
            finally
            {
                s.Close();
            }
        }

        [Test]
        public void TestIsModified_fileWithExtension()
        {
            GitIndex index = new GitIndex(db);
            FileInfo file = writeTrashFile("a.txt", "a");
            index.add(trash, file);
            index.write();

            IndexEntry entry = index.GetEntry("a.txt");
            Assert.IsFalse(entry.IsModified(trash, false));

            writeTrashFile("a.txt", "b");
            Thread.Sleep(100);
            Assert.IsTrue(entry.IsModified(trash, false));
            Assert.IsFalse(entry.IsModified(trash, true));

            FileStream s = file.OpenRead();
            try
            {
                Assert.IsTrue(entry.IsModified(trash, s, false));
                Assert.IsFalse(entry.IsModified(trash, s, true));
            }
            finally
            {
                s.Close();
            }
        }
    }
}

