namespace XmlTransformation
{
    // Interface for accessing original XML document nodes via XPath queries.
    public interface IXmlOriginalDocumentService
    {
        XmlNode GetOriginalNode(string xpath);
    }

    // Base class representing a file-based XML document.
    public class XmlFileInfoDocument
    {
        protected XmlDocument Document;

        public XmlFileInfoDocument()
        {
            Document = new XmlDocument();
        }

        public virtual void Load(string filePath)
        {
            Document.Load(filePath);
        }

        public virtual void Save(string filePath)
        {
            Document.Save(filePath);
        }

        public XmlDocument GetDocument()
        {
            return Document;
        }
    }

    // Extended XML document supporting change detection and original state retrieval.
    public class XmlTransformableDocument : XmlFileInfoDocument, IXmlOriginalDocumentService
    {
        // Backup of the original XML document.
        private XmlDocument xmlOriginal;

        public XmlTransformableDocument() : base()
        {
            xmlOriginal = null;
        }

        // Create a clone of the current XML document as the original state.
        public void CloneOriginalDocument()
        {
            if (Document == null)
                throw new InvalidOperationException("Document is not loaded.");

            xmlOriginal = new XmlDocument();
            xmlOriginal.LoadXml(Document.OuterXml);
        }

        // Determines if the current XML document is equal to the original.
        public bool IsXmlEqual()
        {
            // Placeholder for a detailed XML comparison algorithm.
            // Currently, it simply returns false if any changes are detected.
            if (xmlOriginal == null)
                return false;
            if (Document.OuterXml == xmlOriginal.OuterXml)
                return true;
            return false;
        }

        // Event hook invoked before any modification happens.
        protected virtual void OnBeforeChange()
        {
            // Custom behavior can be added here.
            Console.WriteLine("OnBeforeChange: Preparing to modify the XML document.");
        }

        // Event hook invoked after modifications are complete.
        protected virtual void OnAfterChange()
        {
            // Custom behavior can be added here.
            Console.WriteLine("OnAfterChange: XML document has been modified.");
        }

