namespace Microsoft.AspNetCore.Routing.Patterns
{
    /// <summary>
    /// Represents an exception that occurs during route pattern construction in ASP.NET Core.
    /// </summary>
    [Serializable]
    public class RoutePatternException : Exception
    {
        /// <summary>
        /// Gets the route pattern that caused the exception.
        /// </summary>
        public string Pattern { get; }

        /// <summary>
        /// Initializes a new instance of the RoutePatternException class with a specified route pattern and error message.
        /// </summary>
        /// <param name="pattern">The route pattern that triggered the exception.</param>
        /// <param name="message">The error message describing the exception.</param>
        /// <exception cref="ArgumentNullException">Thrown when pattern or message is null.</exception>
        public RoutePatternException(string pattern, string message)
            : base(message)
        {
            Pattern = pattern ?? throw new ArgumentNullException(nameof(pattern),
                "Route pattern cannot be null.");
        }

        /// <summary>
        /// Initializes a new instance of the RoutePatternException class with serialized data.
        /// </summary>
        /// <param name="info">The SerializationInfo containing exception data.</param>
        /// <param name="context">The StreamingContext describing the serialization context.</param>
        protected RoutePatternException(SerializationInfo info, StreamingContext context)
            : base(info, context)
        {
            Pattern = info.GetString(nameof(Pattern))
                ?? throw new SerializationException("Route pattern cannot be null during deserialization.");
        }

        /// <summary>
        /// Populates a SerializationInfo with the data needed to serialize the RoutePatternException.
        /// </summary>
        /// <param name="info">The SerializationInfo to populate with data.</param>
        /// <param name="context">The destination for the serialization.</param>
        public override void GetObjectData(SerializationInfo info, StreamingContext context)
        {
            if (info == null)
            {
                throw new ArgumentNullException(nameof(info),
                    "SerializationInfo cannot be null when serializing RoutePatternException.");
            }

            base.GetObjectData(info, context);
            info.AddValue(nameof(Pattern), Pattern);
        }

