using System;
 
public class Graph
{
    public static int i;
    public static double sum(ref int i, int lo, int hi, Func<double> term)
    {
        double temp = 0.0;
        for (i = lo; i <= hi; i++)
        {
            temp += term();
        }
        return temp;
    }
    public static void Main()
    {
        Console.WriteLine(sum(ref i, 1, 100, () => 1.0 / i));
    }
}

