namespace SAPSessionViewer
{
    public partial class SAPSessionInfo : UserControl
    {
        private SAPAutomationHelper _sapHelper;
        private GuiSession _session;
        private ListView lv_SessionInfo;

        public SAPSessionInfo()
        {
            InitializeComponent();
            lv_SessionInfo = new ListView();
            this.Content = lv_SessionInfo;
            _sapHelper = new SAPAutomationHelper();
            _sapHelper.Current.OnSetSession += Current_OnSetSession;
        }

        private void Current_OnSetSession(object sender, EventArgs e)
        {
            _session = _sapHelper.Current.Session;
            if (_session != null)
            {
                _session.EndRequest += session_EndRequest;
                _session.Destroy += session_Destroy;
                showSessionInfo();
            }
        }

        private void session_EndRequest(object sender, EventArgs e)
        {
            showSessionInfo();
        }

        private void session_Destroy(object sender, EventArgs e)
        {
            _session.EndRequest -= session_EndRequest;
            _session.Destroy -= session_Destroy;
            _session = null;
            showSessionInfo();
        }

        private void showSessionInfo()
        {
            Dispatcher.BeginInvoke(new Action(() =>
            {
                lv_SessionInfo.Items.Clear();
                if (_session != null)
                {
                    Type sessionType = _session.GetType();
                    foreach (PropertyInfo property in sessionType.GetProperties())
                    {
                        try
                        {
                            object value = property.GetValue(_session, null);
                            ListViewItem item = new ListViewItem();
                            item.Content = $"{property.Name}: {value}";
                            lv_SessionInfo.Items.Add(item);
                        }
                        catch (Exception)
                        {
                            // Handle any exceptions that occur while getting property values
                        }
                    }
                }
            }));
        }
    }

