        {
            Width = width;
            Height = height;
        }

        // Builds the pages for the report.
        public List<Page> BuildPages()
        {
            List<Page> pages = new List<Page>();
            // Simulate building two pages.
            pages.Add(new Page("This is the content of Page 1."));
            pages.Add(new Page("This is the content of Page 2."));
            return pages;
        }
    }

    // Represents a single page in the report.
    public class Page
    {
        public string Content { get; private set; }

        public Page(string content)
        {
            Content = content;
        }
    }

    // Renders the report pages using Cairo.
    public class RenderCairo
    {
        private Report report;
        private List<Page> pages;

        public RenderCairo(Report report, List<Page> pages)
        {
            this.report = report;
            this.pages = pages;
        }

        // Renders each page on the given Cairo context.
        public void RunPages(Context context)
        {
            double yOffset = 0;
            for (int i = 0; i < pages.Count; i++)
            {
                // Draw page content.
                context.MoveTo(50, 50 + yOffset);
                context.SetSourceRGB(0, 0, 0);
                context.ShowText(pages[i].Content);
                yOffset += report.Height;

                // If not the last page, create a new page in the PDF.
                if (i < pages.Count - 1)
                {
                    context.GetTarget().ShowPage();
                }
            }
        }
    }

