    private void InitializeMethods()
    {
        foreach (MethodInfo method in fixtureType.GetMethods(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic))
        {
            if (method.GetCustomAttributes(typeof(FixtureSetUpAttribute), false).Length > 0)
                fixtureSetUpMethods.Add(method);
            else if (method.GetCustomAttributes(typeof(FixtureTearDownAttribute), false).Length > 0)
                fixtureTearDownMethods.Add(method);
            else if (method.GetCustomAttributes(typeof(SetUpAttribute), false).Length > 0)
                setUpMethods.Add(method);
            else if (method.GetCustomAttributes(typeof(TearDownAttribute), false).Length > 0)
                tearDownMethods.Add(method);
        }
    }

    public void DoOneTimeSetUp(TestResult suiteResult)
    {
        foreach (MethodInfo method in fixtureSetUpMethods)
        {
            try
            {
                method.Invoke(Activator.CreateInstance(fixtureType, arguments), null);
            }
            catch (Exception ex)
            {
                suiteResult.Error(ex);
                break;
            }
        }
    }

    public void DoOneTimeTearDown(TestResult suiteResult)
