public class Realm : IRealm
{
    public string BaseCdnUrl { get; private set; }
    public string LatestChangedCssVersion { get; private set; }
    public string LatestChangedDragonMagicVersion { get; private set; }
    public string DefaultLanguage { get; private set; }
    public string LegacyScript { get; private set; }
    public string LatestChangedVersionForEachDataType { get; private set; }
    public int ProfileIconMax { get; private set; }
    public string CurrentVersion { get; private set; }

    public static void CreateMap(AutoMapperService mappingService)
    {
        var config = new MapperConfiguration(cfg =>
        {
            cfg.CreateMap<RealmDto, Realm>()
                .ForMember(dest => dest.BaseCdnUrl, opt => opt.MapFrom(src => src.cdn_url))
                .ForMember(dest => dest.LatestChangedCssVersion, opt => opt.MapFrom(src => src.latest_css_version))
                .ForMember(dest => dest.LatestChangedDragonMagicVersion, opt => opt.MapFrom(src => src.latest_dragon_magic_version))
                .ForMember(dest => dest.DefaultLanguage, opt => opt.MapFrom(src => src.default_language))
                .ForMember(dest => dest.LegacyScript, opt => opt.MapFrom(src => src.legacy_script))
                .ForMember(dest => dest.LatestChangedVersionForEachDataType, opt => opt.MapFrom(src => src.latest_versions))
                .ForMember(dest => dest.ProfileIconMax, opt => opt.MapFrom(src => src.profile_icon_max))
                .ForMember(dest => dest.CurrentVersion, opt => opt.MapFrom(src => src.current_version));
        });

        mappingService.Configure(config);
    }

    public static void CreateMap<T>(AutoMapperService mappingService)
    {
        var config = new MapperConfiguration(cfg =>
        {
            cfg.CreateMap<T, Realm>();
        });

        mappingService.Configure(config);
    }

    public void UpdateFromDto(RealmDto dto)
    {
        BaseCdnUrl = dto.cdn_url;
        LatestChangedCssVersion = dto.latest_css_version;
        LatestChangedDragonMagicVersion = dto.latest_dragon_magic_version;
        DefaultLanguage = dto.default_language;
        LegacyScript = dto.legacy_script;

