namespace Umbraco.Web.UI.Controls
{
    public class PropertyTypePicker : ListBox
    {
        private string _value;
        private bool _multiple = false;
        private List<string> _selectedPropertyTypes;

        public PropertyTypePicker()
        {
            _selectedPropertyTypes = new List<string>();
            SelectionMode = ListSelectionMode.Multiple;
        }

        public bool AllowMultipleSelection
        {
            get { return _multiple; }
            set
            {
                _multiple = value;
                SelectionMode = _multiple ? ListSelectionMode.Multiple : ListSelectionMode.Single;
            }
        }

        public string Value
        {
            get
            {
                if (!_multiple)
                {
                    return SelectedValue;
                }
                return string.Join(",", _selectedPropertyTypes);
            }
            set
            {
                _value = value;
                if (!string.IsNullOrEmpty(_value))
                {
                    if (_multiple)
                    {
                        _selectedPropertyTypes = _value.Split(',').ToList();
                    }
                    else
                    {
                        Items.FindByValue(_value).Selected = true;
                    }
                }
            }
        }

        protected override void OnInit(EventArgs e)
        {
            base.OnInit(e);
            PopulatePropertyTypes();
        }

        private void PopulatePropertyTypes()
        {
            var propertyTypeService = ApplicationContext.Current.Services.DataTypeService;
            var uniquePropertyTypes = propertyTypeService
                .GetAllDataTypes()
                .Select(dt => dt.PropertyEditorAlias)
                .Distinct()
                .OrderBy(alias => alias)
                .ToList();

            Items.Clear();
            foreach (var propertyTypeAlias in uniquePropertyTypes)
            {
                ListItem item = new ListItem(FormatPropertyTypeDisplay(propertyTypeAlias), propertyTypeAlias);
                Items.Add(item);

                if (_multiple && _selectedPropertyTypes.Contains(propertyTypeAlias))
                {
                    item.Selected = true;
                }
            }
        }

