using System.Collections;

public class a_hack_trap_vendingsign : a_hack_trap
{
    public override void ExecuteTrap()
    {
        if (Quest.instance == null || Quest.instance.variables == null)
        {
            Debug.LogError("Quest system not available");
            return;
        }

        int selectedItem = Quest.instance.variables[3];
        int itemStringIndex = 0;
        int price = 0;

        switch (selectedItem)
        {
            case 0:
                itemStringIndex = 100;
                price = 5;
                break;
            case 1:
                itemStringIndex = 101;
                price = 10;
                break;
            case 2:
                itemStringIndex = 102;
                price = 15;
                break;
            case 3:
                itemStringIndex = 103;
                price = 20;
                break;
            case 4:
                itemStringIndex = 104;
                price = 25;
                break;
            case 5:
                itemStringIndex = 105;
                price = 30;
                break;
            case 6:
                itemStringIndex = 106;
                price = 35;
                break;
            case 7:
                itemStringIndex = 107;
                price = 40;
                break;
            default:
                itemStringIndex = 108;
                price = 0;
                break;
        }

        if (StringController.instance == null)
        {
            Debug.LogError("StringController not initialized");
            return;
        }

        string itemName = StringController.instance.GetString(itemStringIndex);
        string productLabel = StringController.instance.GetString(88);
        string priceTemplate = StringController.instance.GetString(89);
        string formattedPrice = string.Format(priceTemplate, price);
        string message = $"{productLabel}{itemName} {formattedPrice}";

        if (UWHUD.instance != null && UWHUD.instance.MessageScroll != null)
        {
            UWHUD.instance.MessageScroll.Add(message);
        }
        else
        {
            Debug.LogWarning("UI MessageScroll not available");
        }
    }

    public override void PostActivate()
    {
        base.PostActivate();
        Debug.Log($"Vending sign activated: {ObjectName}");

        if (Quest.instance != null && Quest.instance.variables != null)
        {
            Debug.Log($"Current vending state: {Quest.instance.variables[3]}");
        }
    }
}

