using System;
 
public class Exponentiation
{
    public static void Main()
    {
        Action<int, int> ti = (b, p) =>
        {
            Console.Write("{0}^{1}: ", b, p);
            var (e, err) = expI(b, p);
            if (err!= null)
            {
                Console.WriteLine(err);
            }
            else
            {
                Console.WriteLine(e);
            }
        };
 
        Console.WriteLine("expI tests");
        ti(2, 10);
        ti(2, -10);
        ti(-2, 10);
        ti(-2, 11);
        ti(11, 0);
 
        Console.WriteLine("overflow undetected");
        ti(10, 10);
 
        Action<float, int> tf = (b, p) =>
        {
            Console.Write("{0}^{1}: {2}\n", b, p, expF(b, p));
        };
 
        Console.WriteLine("\nexpF tests:");
        tf(2, 10);
        tf(2, -10);
        tf(-2, 10);
        tf(-2, 11);
        tf(11, 0);
 
        Console.WriteLine("disallowed in expI, allowed here");
        tf(0, -1);
 
        Console.WriteLine("other interesting cases for 32 bit float type");
        tf(10, 39);
        tf(10, -39);
        tf(-10, 39);
    }
 
    public static (int, Exception) expI(int b, int p)
    {
        if (p < 0)
        {
            return (0, new Exception("negative power not allowed"));
        }
        var r = 1;
        for (var i = 1; i <= p; i++)
        {
            r *= b;
        }
        return (r, null);
    }
 
    public static float expF(float b, int p)
    {
        var neg = false;
        if (p < 0)
        {
            neg = true;
            p = -p;
        }
        var r = 1f;
        for (var pow = b; p > 0; pow *= pow)
        {
            if ((p & 1) == 1)
            {
                r *= pow;
            }
            p >>= 1;
        }
        if (neg)
        {
            r = 1 / r;
        }
        return r;
    }
}

