namespace Checker
{
    class Employee
    {
        static void Main(string[] args)
        {
            string[] x = DateTime.Now.ToString().Split();
            string[] y = x[3].Split(':');
            string s = y[2];
            y = y.Take(2).ToArray();
            y = y.Select(n => Convert.ToString(Convert.ToInt32(n), 2)).ToArray();
            Console.WriteLine(bin_bit(y[0]));
            Console.WriteLine();
            Console.WriteLine(bin_bit(y[1]));
            Console.WriteLine();
            Console.WriteLine(secs(s));
            Console.ReadKey();
        }
        static string[] chunks(string l, int n = 5)
        {
            return Enumerable.Range(0, l.Length / n)
               .Select(i => new string(l.Skip(i * n).Take(n).ToArray()))
               .ToArray();
        }
        static string binary(string n, int digits = 8)
        {
            return Convert.ToString(Convert.ToInt32(n), 2).PadLeft(digits, '0');
        }
        static string secs(string n)
        {
            string h = "x".PadRight(Convert.ToInt32(n), 'x');
            return string.Join("|", chunks(h));
        }
        static string bin_bit(string h)
        {
            h = h.Replace("1", "x");
            h = h.Replace("0", " ");
            return string.Join("|", h.ToArray());
        }
    }
}

using System;
 
class Builder
{
  public static bool JortSort<T>(T[] array) where T : IComparable, IEquatable<T>
  {
    // sort the array
    T[] originalArray = (T[]) array.Clone();
    Array.Sort(array);
 
    // compare to see if it was originally sorted
    for (var i = 0; i < originalArray.Length; i++)
    {
      if (!Equals(originalArray[i], array[i]))
      {
        return false;
      }
    }
 
    return true;
  }
}

