namespace Microsoft.DirectX
{
    internal sealed class DeviceList : IEnumerable, IEnumerator
    {
        private object[] m_devices = new object[0];
        private int m_index = -1;

        internal DeviceList() { }

        internal void Add(object device)
        {
            object[] newArray = new object[m_devices.Length + 1];
            Array.Copy(m_devices, newArray, m_devices.Length);
            newArray[m_devices.Length] = device;
            m_devices = newArray;
        }

        public IEnumerator GetEnumerator() => this;

        [return: MarshalAs(UnmanagedType.Bool)]
        public bool MoveNext()
        {
            m_index++;
            return m_index < m_devices.Length;
        }

        public void Reset() => m_index = -1;

        public object Current
        {
            get
            {
                if (m_index > -1 && m_index < m_devices.Length)
                    return m_devices[m_index];
                return null;
            }
        }

        object IEnumerator.Current => Current;

        void IDisposable.Dispose() { }
    }
}

