class Peer
{
    // Base class for networking operations if needed
}

class Server : Peer
{
    private UdpClient udpServer;
    private Random randomGenerator;
    private int port;
    private HashSet<int> validTokens;

    public Server(int port)
    {
        this.port = port;
        this.randomGenerator = new Random();
        this.validTokens = new HashSet<int>();
        udpServer = new UdpClient(port);
    }

    public void Start()
    {
        Console.WriteLine("Server started on port: " + port);
        while (true)
        {
            Accept();
        }
    }

    private void Accept()
    {
        IPEndPoint clientEndPoint = new IPEndPoint(IPAddress.Any, 0);
        byte[] requestData = udpServer.Receive(ref clientEndPoint);
        string requestMessage = Encoding.UTF8.GetString(requestData);

        if (IsValidTokenRequest(requestMessage))
        {
            int token = GenerateToken();
            validTokens.Add(token);
            SendToken(clientEndPoint, token);
        }
    }

    private bool IsValidTokenRequest(string requestMessage)
    {
        // Implement logic to determine if the request is valid
        return requestMessage == "REQUEST_TOKEN";
    }

    private int GenerateToken()
    {
        return randomGenerator.Next(1000, 9999); // Generates a random token
    }

    private void SendToken(IPEndPoint clientEndPoint, int token)
    {
        byte[] tokenData = Encoding.UTF8.GetBytes(token.ToString());
        udpServer.Send(tokenData, tokenData.Length, clientEndPoint);
    }

    public void SendData(byte[] data, int token)
    {
        if (validTokens.Contains(token))
        {
            // Assuming we've stored the client endpoint during token acceptance
            IPEndPoint clientEndPoint = new IPEndPoint(IPAddress.Any, 0); // Should reference actual client end point
            udpServer.Send(data, data.Length, clientEndPoint);
        }
        else
        {
            Console.WriteLine("Invalid token. Data not sent.");
        }
    }

    public byte[] ReceiveData(int token)
    {
        if (validTokens.Contains(token))
        {
            IPEndPoint clientEndPoint = new IPEndPoint(IPAddress.Any, 0);
            byte[] receivedData = udpServer.Receive(ref clientEndPoint);
            return receivedData;
        }
        else
        {
            Console.WriteLine("Invalid token. Data not received.");
            return null;
        }
    }
}

