using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Logging.Abstractions;
using OmniSharp.Extensions.LanguageServer.Server;
using System;
using System.Collections.Generic;

public class LanguageServerLoggerFactory : ILoggerFactory
{
    private readonly ILoggerProvider _provider;
    private readonly LoggingEnvironment _environment;
    private readonly HashSet<string> _excludedCategories = new HashSet<string>
    {
        "OmniSharp.Router", "OmniSharp.Queue", "OmniSharp.Scheduler"
    };

    public LanguageServerLoggerFactory(LoggingEnvironment environment)
    {
        _environment = environment;
        _provider = new FilteredLoggerProvider(_environment, _excludedCategories);
    }

    public ILogger CreateLogger(string categoryName)
    {
        if (_excludedCategories.Contains(categoryName) || !categoryName.StartsWith("OmniSharp"))
            return NullLogger.Instance;

        return _provider.CreateLogger(categoryName);
    }

    public void AddProvider(ILoggerProvider provider) => throw new NotSupportedException();
    public void AddProvider(LogLevel minLevel, Func<string, bool> categoryFilter) { }

    public void Dispose() => throw new NotImplementedException();

    private class FilteredLoggerProvider : ILoggerProvider
    {
        private readonly LoggingEnvironment _env;
        private readonly HashSet<string> _blockedCategories;

        public FilteredLoggerProvider(LoggingEnvironment env, HashSet<string> blockedCategories)
        {
            _env = env;
            _blockedCategories = blockedCategories;
        }

        public ILogger CreateLogger(string categoryName)
        {
            return new FilteredLogger(categoryName, _env.MinimumLogLevel);
        }

        public void Dispose() { }
    }

    private class FilteredLogger : ILogger
    {
        private readonly string _category;
        private readonly LogLevel _minLevel;

        public FilteredLogger(string category, LogLevel minLevel)
        {
            _category = category;
            _minLevel = minLevel;
        }

        public IDisposable BeginScope<TState>(TState state) => NullScope.Instance;

        public bool IsEnabled(LogLevel logLevel) => logLevel >= _minLevel;

        public void Log<TState>(LogLevel logLevel, EventId eventId, TState state,
            Exception exception, Func<TState, Exception, string> formatter)
        {
            if (IsEnabled(logLevel))
                Console.WriteLine($"[{logLevel}] {_category}: {formatter(state, exception)}");
        }
    }
}

