namespace Marquee
{
    public class Marquee : Label
    {
        private bool rightToLeftDirection = true;
        private System.Timers.Timer timer;

        public Marquee()
        {
            this.Text = "Hello World! ";
            this.Font = new Font(null, 50, FontStyle.Bold);
            this.ForeColor = Color.Cyan;
            this.AutoSize = true;
            this.BackColor = Color.Transparent;
            this.Parent.BackColor = Color.Black;
            this.Parent.FormBorderStyle = FormBorderStyle.None;
            this.Parent.TransparencyKey = Color.Black;
            this.Parent.TopMost = true;
            this.Parent.StartPosition = FormStartPosition.CenterScreen;
            this.Parent.Show();
            this.timer = new System.Timers.Timer(80);
            this.timer.Elapsed += new ElapsedEventHandler(timer_Elapsed);
            this.timer.Enabled = true;
        }

        private void timer_Elapsed(object sender, ElapsedEventArgs e)
        {
            int i = rightToLeftDirection? 1 : -1;
            this.Text = this.Text.Substring(i) + this.Text.Substring(0, i);
        }

        protected override void OnMouseClick(MouseEventArgs e)
        {
            rightToLeftDirection =!rightToLeftDirection;
        }

        protected override void OnKeyPress(KeyPressEventArgs e)
        {
            if (e.KeyChar == (char)Keys.Escape)
            {
                this.Parent.Close();
            }
        }
    }
}

