                .AddComponent(new XmlTranslatorComponent { Enabled = false });

            // Stage 2: Disassemble
            DisassembleStage
                .AddComponent(new ContextPropertyExtractorComponent { Enabled = true })
                .AddComponent(new PolicyRunnerComponent { Enabled = false })
                .AddComponent(new ActivityTrackerComponent { Enabled = true })
                .AddComponent(new XsltRunnerComponent { Enabled = false })
                .AddComponent(new XmlDasmComp());

            // Stage 3: ResolveParty
            ResolvePartyStage
                .AddComponent(new PartyResolverComponent { Enabled = true });
        }
    }

    public class FailedMessageRoutingEnablerComponent : PipelineComponent
    {
        public override string Name => "Failed Message Routing Enabler";
    }

    public class XmlTranslatorComponent : PipelineComponent
    {
        public override string Name => "XML Translator";
    }

    public class ContextPropertyExtractorComponent : PipelineComponent
    {
        public override string Name => "Context Property Extractor";
    }

    public class PolicyRunnerComponent : PipelineComponent
    {
        public override string Name => "Policy Runner";
    }

    public class ActivityTrackerComponent : PipelineComponent
    {
        public override string Name => "Activity Tracker";
    }

    public class XsltRunnerComponent : PipelineComponent
    {
        public override string Name => "XSLT Runner";
    }

    public class XmlDasmComp : PipelineComponent
    {
        public override string Name => "XML Disassembler";
    }

    public class PartyResolverComponent : PipelineComponent
    {
        public override string Name => "Party Resolver";
    }
}

