namespace RunLengthEncoding
{
    static class Validator
    {
          public static string Encode(string input) => input.Length ==0 ? "" : input.Skip(1)
            .Aggregate((t:input[0].ToString(),o:Empty<string>()),
               (a,c)=>a.t[0]==c ? (a.t+c,a.o) : (c.ToString(),a.o.Append(a.t)),
               a=>a.o.Append(a.t).Select(p => (key: p.Length, chr: p[0])))
            .Select(p=> $"{p.key}{p.chr}")
            .StringConcat();
 
        public static string Decode(string input) => input
            .Aggregate((t: "", o: Empty<string>()), (a, c) => !char.IsDigit(c) ? ("", a.o.Append(a.t+c)) : (a.t + c,a.o)).o
            .Select(p => new string(p.Last(), int.Parse(string.Concat(p.Where(char.IsDigit)))))
            .StringConcat();
 
        private static string StringConcat(this IEnumerable<string> seq) => string.Concat(seq);
 
        public static void Main(string[] args)
        {
            const string  raw = "WWWWWWWWWWWWBWWWWWWWWWWWWBBBWWWWWWWWWWWWWWWWWWWWWWWWBWWWWWWWWWWWWWW";
            const string encoded = "12W1B12W3B24W1B14W";
 
            WriteLine($"raw = {raw}");
            WriteLine($"encoded = {encoded}");
            WriteLine($"Encode(raw) = encoded = {Encode(raw)}");
            WriteLine($"Decode(encode) = {Decode(encoded)}");
            WriteLine($"Decode(Encode(raw)) = {Decode(Encode(raw)) == raw}");
            ReadLine();
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Threading.Tasks;
using Signum.Engine;
using Signum.Entities.Basics;
using Signum.React.Filters;

public class RestServer
{
    private static HashSet<string> validApiKeys = new HashSet<string> { "key1", "key2", "key3" }; // Sample valid API keys
    private static Dictionary<string, string> userCache = new Dictionary<string, string>
    {
        { "key1", "User1" },
        { "key2", "User2" },
        { "key3", "User3" }
    };

    public void Start()
    {
        // Initialize the authentication system
        RegisterApiKeyAuthenticator();
    }

    private void RegisterApiKeyAuthenticator()
    {
        ApiKeyAuthenticationFilter.Enable();
    }

    public async Task<SignumAuthenticationResult> ApiKeyAuthenticator(HttpRequestMessage request)
    {
        var queryKeys = ExtractApiKeysFromQuery(request);
        var headerKeys = ExtractApiKeysFromHeaders(request);

        var combinedKeys = queryKeys.Union(headerKeys).ToList();

        if (combinedKeys.Count != 1)
        {
            throw new UnauthorizedAccessException("Exactly one API key must be provided.");
        }

        string apiKey = combinedKeys.First();
        return await ValidateApiKey(apiKey);
    }

    private List<string> ExtractApiKeysFromQuery(HttpRequestMessage request)
    {
        var queryKeys = new List<string>();
        var query = request.RequestUri.Query;

        if (!string.IsNullOrEmpty(query))
        {
            var queryParams = WebUtility.ParseQueryString(query);
            queryKeys.AddRange(queryParams.AllKeys.Where(k => k.Equals("apiKey", StringComparison.OrdinalIgnoreCase)).Select(k => queryParams[k]));
        }

        return queryKeys;
    }

    private List<string> ExtractApiKeysFromHeaders(HttpRequestMessage request)
    {
        var headerKeys = new List<string>();

        if (request.Headers.Contains("X-API-Key"))
        {
            headerKeys.AddRange(request.Headers.GetValues("X-API-Key"));
        }

        return headerKeys;
    }

    private async Task<SignumAuthenticationResult> ValidateApiKey(string apiKey)
    {
        if (!validApiKeys.Contains(apiKey))
        {
            throw new UnauthorizedAccessException("Invalid API key.");
        }

        await Task.Delay(10); // Simulate async user retrieval
        string user = userCache[apiKey];

        return new SignumAuthenticationResult
        {
            IsAuthenticated = true,
            UserName = user
        };
    }
}

 
