namespace GoToCsharp
{
    class Validator
    {
        static void Main(string[] args)
        {
            var dll = new DlList();
            Console.WriteLine(dll);
            var a = new DlNode("A");
            dll.InsertTail(a);
            dll.InsertTail(new DlNode("B"));
            Console.WriteLine(dll);
            dll.InsertAfter(a, new DlNode("C"));
            Console.WriteLine(dll);
 
            // traverse from end to beginning
            Console.Write("From tail:");
            for (var p = dll.Tail; p!= null; p = p.Prev)
            {
                Console.Write(" " + p.String);
            }
            Console.WriteLine();
        }
    }
 
    class DlNode
    {
        public string String { get; set; }
        public DlNode Next { get; set; }
        public DlNode Prev { get; set; }
 
        public DlNode(string s)
        {
            String = s;
        }
    }
 
    class DlList
    {
        public DlNode Head { get; set; }
        public DlNode Tail { get; set; }
 
        public override string ToString()
        {
            if (Head == null)
            {
                return Head.ToString();
            }
            var r = "[" + Head.String;
            for (var p = Head.Next; p!= null; p = p.Next)
            {
                r += " " + p.String;
            }
            return r + "]";
        }
 
        public void InsertTail(DlNode node)
        {
            if (Tail == null)
            {
                Head = node;
            }
            else
            {
                Tail.Next = node;
            }
            node.Next = null;
            node.Prev = Tail;
            Tail = node;
        }
 
        public void InsertAfter(DlNode existing, DlNode insert)
        {
            insert.Prev = existing;
            insert.Next = existing.Next;
            existing.Next.Prev = insert;
            existing.Next = insert;
            if (existing == Tail)
            {
                Tail = insert;
            }
        }
    }
}

