using System;
using System.Threading;
using UnityEngine;
using UniRx.Async;
using UniRx.Async.Triggers;

public static class CancellationTokenSourceExtensions
{
    // Schedules cancellation after a delay specified in milliseconds.
    public static CancellationTokenSource CancelAfterSlim(this CancellationTokenSource cts, int millisecondsDelay)
    {
        CancelAfterCore(cts, millisecondsDelay);
        return cts;
    }

    // Schedules cancellation after a delay specified as a TimeSpan.
    public static CancellationTokenSource CancelAfterSlim(this CancellationTokenSource cts, TimeSpan delay)
    {
        int millisecondsDelay = (int)delay.TotalMilliseconds;
        CancelAfterCore(cts, millisecondsDelay);
        return cts;
    }

    // Asynchronously waits for the given delay and cancels/disposes the token.
    private static async void CancelAfterCore(CancellationTokenSource cts, int delayMilliseconds)
    {
        try
        {
            // Await the delay using UniTask.
            await UniTask.Delay(delayMilliseconds, cancellationToken: CancellationToken.None);
            if (!cts.IsCancellationRequested)
            {
                cts.Cancel();
            }
        }
        catch (OperationCanceledException)
        {
            // Ignore if delay was cancelled externally.
        }
        finally
        {
            cts.Dispose();
        }
    }

    // Registers cancellation token cancellation when the Unity Component is destroyed.
    public static async void RegisterRaiseCancelOnDestroy(this CancellationTokenSource cts, Component component)
    {
        if (component == null)
        {
            throw new ArgumentNullException(nameof(component));
        }
        // Wait for the component to be destroyed.
        await component.OnDestroyAsync();
        if (!cts.IsCancellationRequested)
        {
            cts.Cancel();
        }
        cts.Dispose();
    }

    // Registers cancellation token cancellation when the Unity GameObject is destroyed.
    public static async void RegisterRaiseCancelOnDestroy(this CancellationTokenSource cts, GameObject gameObject)
    {
        if (gameObject == null)
        {
            throw new ArgumentNullException(nameof(gameObject));
        }
        // Use or add an AsyncTrigger component to detect destruction.
        var trigger = gameObject.GetComponent<AsyncTrigger>() ?? gameObject.AddComponent<AsyncTrigger>();
        await trigger.OnDestroyAsync();
        if (!cts.IsCancellationRequested)
        {
            cts.Cancel();
        }
        cts.Dispose();
    }
}

