        public bool IsSuccess { get; set; }
        public string ErrorMessage { get; set; }
    }

    public class SldrWritingSystemFactory
    {
        private string cacheDirectory;

        public SldrWritingSystemFactory(string cacheDir)
        {
            cacheDirectory = cacheDir;
            if (!Directory.Exists(cacheDirectory))
            {
                Directory.CreateDirectory(cacheDirectory);
            }
        }

        public WritingSystemDefinition ConstructDefinition(string languageTag)
        {
            var definition = new WritingSystemDefinition
            {
                LanguageTag = languageTag,
                LocalizedData = new Dictionary<string, string>()
            };

            var status = GetLdmlFromSldr(languageTag);
            if (status.IsSuccess)
            {
                LoadLocalizedData(definition, status);
            }
            else
            {
                FallbackDefinition(definition);
            }

            return definition;
        }

