using System;
 
class Matrix
{
        static int dot_product(int[] a, int[] b, int n)
        {
                int sum = 0;
                int i;
 
                for (i = 0; i < n; i++) {
                        sum += a[i] * b[i];
                }
 
                return sum;
        }
 
        static void Main(string[] args)
        {
                int[] a = {1, 3, -5};
                int[] b = {4, -2, -1};
 
                Console.WriteLine(dot_product(a, b, a.Length));
        }
