public class UDPTokenServer
{
    private UdpClient serverSocket;
    private ConcurrentDictionary<string, ConnectedClient> connectedClients;
    private Random randomGenerator;

    public class ConnectedClient
    {
        public IPEndPoint RemoteEndpoint { get; set; }
        public string AuthToken { get; set; }
        public DateTime LastActivityTime { get; set; }
    }

    public UDPTokenServer(int port)
    {
        serverSocket = new UdpClient(port);
        connectedClients = new ConcurrentDictionary<string, ConnectedClient>();
        randomGenerator = new Random();
    }

    private string GenerateAuthToken()
    {
        byte[] tokenBytes = new byte[16];
        using (var rng = new RNGCryptoServiceProvider())
        {
            rng.GetBytes(tokenBytes);
        }
        return Convert.ToBase64String(tokenBytes);
    }

    private bool ValidateToken(string token)
    {
        return connectedClients.ContainsKey(token);
    }

    public void StartListening()
    {
        try
        {
            while (true)
            {
                IPEndPoint clientEndpoint = new IPEndPoint(IPAddress.Any, 0);
                byte[] receivedData = serverSocket.Receive(ref clientEndpoint);
                ProcessIncomingPacket(receivedData, clientEndpoint);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Server Error: {ex.Message}");
        }
    }

    private void ProcessIncomingPacket(byte[] data, IPEndPoint clientEndpoint)
    {
        string message = Encoding.UTF8.GetString(data);
        string[] parts = message.Split('|');

        switch (parts[0])
        {
            case "TOKEN_REQUEST":
                string newToken = GenerateAuthToken();
                var newClient = new ConnectedClient
                {
                    RemoteEndpoint = clientEndpoint,
                    AuthToken = newToken,
                    LastActivityTime = DateTime.Now
                };
                connectedClients[newToken] = newClient;
                SendTokenToClient(newToken, clientEndpoint);
                break;

            case "DATA_TRANSMISSION":
                if (parts.Length == 3 && ValidateToken(parts[1]))
                {
                    ProcessClientData(parts[1], parts[2]);
                }
                break;
        }
    }

    private void SendTokenToClient(string token, IPEndPoint clientEndpoint)
    {

