public class AlertesModelBuilder : IAlertesModelBuilder
{
    private readonly IDepotFactory _depotFactory;
    private readonly ICaching _cachingService;
    public ILogger Logger { get; set; } = NullLogger.Instance;

    public AlertesModelBuilder(IDepotFactory depotFactory, ICaching cachingService)
    {
        _depotFactory = depotFactory;
        _cachingService = cachingService;
    }

    public AlertesViewModel BuildAlertesViewModel(string userId)
    {
        var alerts = _depotFactory.GetAlertDepot().GetAlertsByUserId(userId);

        var viewModel = new AlertesViewModel
        {
            Alertes = alerts.Select(a => new AlerteSummaryViewModel
            {
                Id = a.Id,
                Title = a.Title,
                Description = a.Description,
                Severity = a.Severity
            }).ToList()
        };

        return viewModel;
    }

    public AlerteResultsViewModel BuildAlerteResultsViewModel(int alertId)
    {
        var results = _depotFactory.GetAlertDepot().GetAlertResultsByAlertId(alertId);

        var viewModel = new AlerteResultsViewModel
        {
            AlertId = alertId,
            Results = results.Select(r => new Dictionary<string, string>
            {
               { "Key", r.Key },
               { "Value", r.Value}
            }).ToList()
        };

        return viewModel;
    }
