        public enum CryptoInterfaceType : uint
        {
            // Asymmetric encryption interface.
            AsymmetricEncryption = 0x00000001,

            // Secret Agreement (e.g., Diffie-Hellman) interface.
            SecretAgreement = 0x00000002,

            // Digital signature interface used for signing and verifying data.
