            // Schannel interface employed in TLS/SSL and secure channel operations.
            SchannelEncryption = 0x00000005,

            // Custom interface type mapped from an external BCrypt definition.
            BCryptCustomInterface = BCryptConstants.BCRYPT_INTERFACE_PROTOCOL,

            // Reserved for future cryptographic interfaces.
            Reserved = 0xFFFFFFFF
        }
