using System;

namespace DigitalSignatureVerification
{
    public abstract class VerificationRule
    {
        public abstract VerificationResult Verify(VerificationContext context);
    }

    public class VerificationResult
    {
        public bool Success { get; set; }
        public string ErrorCode { get; set; }
        public static VerificationResult Ok() => new VerificationResult { Success = true };
        public static VerificationResult Fail(string error) => new VerificationResult { Success = false, ErrorCode = error };
    }

    public class VerificationContext
    {
        public Publication Publication { get; set; }
        public Signature Signature { get; set; }
    }

    public class Publication
    {
        public DateTime PublicationTime { get; set; }
        public string ExtendedCalendarInputHash { get; set; }
    }

    public class Signature
    {
        public AggregationHashChain AggregationHashChain { get; set; }
    }

    public class AggregationHashChain
    {
        public string FinalAggregationHash { get; set; }
    }

    public class PublicationHashVerificationRule : VerificationRule
    {
        private const string HashMismatchError = "ERR_HASH_MISMATCH";

        public override VerificationResult Verify(VerificationContext context)
        {
            if (context == null || context.Publication == null || context.Signature == null)
                return VerificationResult.Fail("ERR_INVALID_CONTEXT");

            string expectedHash = context.Publication.ExtendedCalendarInputHash;
            string actualHash = context.Signature.AggregationHashChain?.FinalAggregationHash;

            if (string.IsNullOrEmpty(actualHash))
                return VerificationResult.Fail("ERR_MISSING_AGGREGATION_HASH");

            if (!string.Equals(expectedHash, actualHash, StringComparison.OrdinalIgnoreCase))
                return VerificationResult.Fail(HashMismatchError);

            return VerificationResult.Ok();
        }
    }
}

