using System.Collections.Generic;
using System.Collections.ObjectModel;

namespace Telemetry
{
    public abstract class SnapshottingCollection<TItem, TCollection, TAsReadOnly>
        where TCollection : ICollection<TItem>, new()
        where TAsReadOnly : ReadOnlyCollection<TItem>
    {
        private TAsReadOnly snapshot;
        protected readonly object SyncRoot = new object();
        protected TCollection Collection { get; } = new TCollection();

        protected TAsReadOnly GetSnapshot()
        {
            if (snapshot == null)
            {
                snapshot = CreateSnapshot();
            }
            return snapshot;
        }

        protected void InvalidateSnapshot()
        {
            snapshot = null;
        }

        protected abstract TAsReadOnly CreateSnapshot();
    }

    public class SnapshottingDictionary<TKey, TValue> : SnapshottingCollection<KeyValuePair<TKey, TValue>, Dictionary<TKey, TValue>, ReadOnlyDictionary<TKey, TValue>>
    {
        protected override ReadOnlyDictionary<TKey, TValue> CreateSnapshot()
        {
            return new ReadOnlyDictionary<TKey, TValue>(new Dictionary<TKey, TValue>(Collection));
        }

        public void Add(TKey key, TValue value)
        {
            lock (SyncRoot)
            {
                Collection.Add(key, value);
                InvalidateSnapshot();
            }
        }

        public bool Remove(TKey key)
        {
            lock (SyncRoot)
            {
                if (Collection.Remove(key))
                {
                    InvalidateSnapshot();
                    return true;
                }
                return false;
            }
        }

        public bool ContainsKey(TKey key) => GetSnapshot().ContainsKey(key);

        public bool TryGetValue(TKey key, out TValue value) => GetSnapshot().TryGetValue(key, out value);
        public TValue this[TKey key] => GetSnapshot()[key];
    }
}

using System;
using System.Composition;
using Quantler.Interfaces;
using Quantler.Modules;
using Quantler.Securities;

[Export(typeof(SignalModule))]
public class AlwaysLongSignal : SignalModule
{
    public AlwaysLongSignal()
    {
        // Initialize the module with a 1-minute check interval
        Schedule.Event(this, TimeSpan.FromMinutes(1), OnSignalCheck);
    }

    private void OnSignalCheck(SignalModuleContext context)
    {
        // Iterate through each security in the portfolio
        foreach (var security in context.Portfolio.Keys)
        {
            // Check if the current position is flat (no position held)
            if (context.Portfolio[security].Position == 0)
            {
                // Generate a long entry signal
                var signal = new TradingSignal(SignalType.Buy, security, 1, "AlwaysLongSignal");
                OnSignal(context, signal);
            }
        }
    }

    protected override void OnSignal(SignalModuleContext context, TradingSignal signal)
    {
        // Execute the long entry for the security
        if (signal.Type == SignalType.Buy)
        {
            var security = signal.Security;
            var quantity = signal.Quantity;

            // Place a market order to go long
            context.PlaceMarketOrder(security, quantity);

            // Log the execution
            Log.Debug($"Executed long entry for {security.Symbol} with quantity {quantity}");
        }
    }
}

