public class Vector
{
    public static void Main()
    {
        var examples = new[] { "broood", "bananaaa", "hiphophiphop" };
        foreach (var example in examples)
        {
            var encoded = Encode(example);
            var decoded = Decode(encoded);
            Console.WriteLine($"{example} encodes to {string.Join(", ", encoded)} decodes to {decoded}");
        }
    }
 
    public static List<int> Encode(string input)
    {
        var symbols = Enumerable.Range('a', 'z' - 'a' + 1).Select(x => (char)x).ToList();
        var output = new List<int>();
        foreach (var x in input)
        {
            var i = symbols.IndexOf(x);
            var c = symbols[i];
            symbols.RemoveAt(i);
            symbols.Insert(0, c);
            output.Add(i);
        }
        return output;
    }
 
    public static string Decode(List<int> input)
    {
        var symbols = Enumerable.Range('a', 'z' - 'a' + 1).Select(x => (char)x).ToList();
        var output = new List<char>();
        foreach (var x in input)
        {
            output.Add(symbols[x]);
            var c = symbols[x];
            symbols.RemoveAt(x);
            symbols.Insert(0, c);
        }
        return new string(output.ToArray());
    }
}

