using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.IO;
using System.Math;
 
namespace Shoelace
{
    class Counter
    {
        struct point
        {
            public double x, y;
        }
 
        static double shoelace(string inputFile)
        {
            int i, numPoints;
            double leftSum = 0, rightSum = 0;
 
            point[] pointSet;
            StreamReader fp = new StreamReader(inputFile);
 
            numPoints = Convert.ToInt32(fp.ReadLine());
 
            pointSet = new point[numPoints + 1];
 
            for (i = 0; i < numPoints; i++)
            {
                string[] line = fp.ReadLine().Split(' ');
                pointSet[i].x = Convert.ToDouble(line[0]);
                pointSet[i].y = Convert.ToDouble(line[1]);
            }
 
            fp.Close();
 
            pointSet[numPoints] = pointSet[0];
 
            for (i = 0; i < numPoints; i++)
            {
                leftSum += pointSet[i].x * pointSet[i + 1].y;
                rightSum += pointSet[i + 1].x * pointSet[i].y;
            }
 
            return 0.5 * Math.Abs(leftSum - rightSum);
        }
 
        static void Main(string[] args)
        {
            if (args.Length == 0)
                Console.WriteLine("\nUsage : {0} <full path of polygon vertices file>", args[0]);
 
            else
                Console.WriteLine("The polygon area is {0} square units.", shoelace(args[0]));
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace Clipper
{
    class Counter
    {
        static void Main(string[] args)
        {
            var subjectPolygon = new List<Point> { new Point(50, 150), new Point(200, 50), new Point(350, 150), new Point(350, 300), new Point(250, 300), new Point(200, 250), new Point(150, 350), new Point(100, 250), new Point(100, 200) };
            var clipPolygon = new List<Point> { new Point(100, 100), new Point(300, 100), new Point(300, 300), new Point(100, 300) };
            var cp1 = clipPolygon[clipPolygon.Count - 1];
            var outputList = subjectPolygon;
            foreach (var cp2 in clipPolygon)
            {
                var inputList = outputList;
                outputList = new List<Point>();
                var s = inputList[inputList.Count - 1];
                foreach (var e in inputList)
                {
                    var inside = (cp2.X - cp1.X) * (e.Y - cp1.Y) > (cp2.Y - cp1.Y) * (e.X - cp1.X);
                    if (inside)
                    {
                        if (!inside)
                        {
                            outputList.Add(intersection(cp1, cp2, s, e));
                        }
                        outputList.Add(e);
                    }
                    else if (inside)
                    {
                        outputList.Add(intersection(cp1, cp2, s, e));
                    }
                    s = e;
                }
                cp1 = cp2;
            }
            Console.WriteLine(outputList);
        }

        private static Point intersection(Point cp1, Point cp2, Point s, Point e)
        {
            var dcx = cp1.X - cp2.X;
            var dcy = cp1.Y - cp2.Y;
            var dpx = s.X - e.X;
            var dpy = s.Y - e.Y;
            var n1 = cp1.X * cp2.Y - cp1.Y * cp2.X;
            var n2 = s.X * e.Y - s.Y * e.X;
            var n3 = 1 / (dcx * dpy - dcy * dpx);
            var p = new Point();
            p.X = (n1 * dpx - n2 * dcx) * n3;
            p.Y = (n1 * dpy - n2 * dcy) * n3;
            return p;
        }
    }

    public class Point
    {
        public Point()
        {
        }

        public Point(float x, float y)
        {
            X = x;
            Y = y;
        }

        public float X { get; set; }
        public float Y { get; set; }
    }
}

