    {
        protected FormReassociableElementBase(string tagName) : base(tagName)
        {
        }

        // Property to retrieve associated form element using dual-strategy:
        // 1. Explicit lookup using "form" attribute.
        // 2. Fallback search: nearest ancestor with tag "form".
        public DocumentElement FormElement
        {
            get
            {
                DocumentElement formElement = null;

                // 1. Check for explicit form attribute
                string formId = GetAttributeValue("form");
                if (!string.IsNullOrEmpty(formId))
                {
                    formElement = LookupElementById(formId);
                }

                // 2. Fallback: search for the closest ancestor element by tag name "form"
                if (formElement == null)
                {
                    formElement = FindNearestAncestor("form");
                }
                return formElement;
            }
        }

