public class WebAddressParser
{
    public static void Main(string[] args)
    {
        parseAddress("foo://example.com:8042/over/there?name=ferret#nose");
        parseAddress("urn:example:animal:ferret:nose");
    }
 
    static void parseAddress(string a)
    {
        Console.WriteLine("Parsing " + a);
        try
        {
 
            // this line does the work
            Uri u = new Uri(a);
 
            Console.WriteLine("\tscheme = " + u.Scheme);
            Console.WriteLine("\tdomain = " + u.Host);
            Console.WriteLine("\tport = " + (-1 == u.Port? "default" : u.Port.ToString()));
            Console.WriteLine("\tpath = " + (null == u.AbsolutePath? u.GetComponents(UriComponents.SchemeAndServer, UriFormat.UriEscaped) : u.AbsolutePath));
            Console.WriteLine("\tquery = " + u.Query);
            Console.WriteLine("\tfragment = " + u.Fragment);
        }
        catch (UriFormatException x)
        {
            Console.Error.WriteLine("Oops: " + x);
        }
    }
}

