                        Id INTEGER PRIMARY KEY,
                        NumericValue REAL,
                        TextValue TEXT,
                        NullableValue INTEGER
                    )";
                cmd.ExecuteNonQuery();
            }
        }

        private void InsertTestRecords()
        {
            using (var cmd = new SQLiteCommand(_connection))
            {
                for (int i = 1; i <= TestRecordCount; i++)
                {
                    cmd.CommandText = $@"
                        INSERT INTO TestTable
                        (NumericValue, TextValue, NullableValue)
                        VALUES
                        ({i * 1.5}, 'Record{i}', {(i % 5 == 0 ? "NULL" : i.ToString())})";
                    cmd.ExecuteNonQuery();
                }
            }
        }

        [Test]
