        {
            var totalSum = ExecuteScalar<double>(
                "SELECT SUM(NumericValue) FROM TestTable"
            );
            var expectedSum = Enumerable.Range(1, TestRecordCount)
                .Select(x => x * 1.5)
                .Sum();

            Assert.AreEqual(expectedSum, totalSum, 0.001);
        }

