/// <summary>
    /// Performs 32-bit reversed cyclic redundancy checks.
    /// </summary>
    public class Crc32
    {
        /// <summary>
        /// Generator polynomial (modulo 2) for the reversed CRC32 algorithm.
        /// </summary>
        private const UInt32 s_generator = 0xEDB88320;
 
        /// <summary>
        /// Creates a new instance of the Crc32 class.
        /// </summary>
        public Crc32()
        {
            // Constructs the checksum lookup table. Used to optimize the checksum.
            m_checksumTable = Enumerable.Range(0, 256).Select(i =>
            {
                var tableEntry = (uint)i;
                for (var j = 0; j < 8; ++j)
                {
                    tableEntry = ((tableEntry & 1) != 0)
                        ? (s_generator ^ (tableEntry >> 1))
                        : (tableEntry >> 1);
                }
                return tableEntry;
            }).ToArray();
        }
 
        /// <summary>
        /// Calculates the checksum of the byte stream.
        /// </summary>
        /// <param name="byteStream">The byte stream to calculate the checksum for.</param>
        /// <returns>A 32-bit reversed checksum.</returns>
        public UInt32 Get<T>(IEnumerable<T> byteStream)
        {
            try
            {
                // Initialize checksumRegister to 0xFFFFFFFF and calculate the checksum.
                return ~byteStream.Aggregate(0xFFFFFFFF, (checksumRegister, currentByte) =>
                          (m_checksumTable[(checksumRegister & 0xFF) ^ Convert.ToByte(currentByte)] ^ (checksumRegister >> 8)));
            }
            catch (FormatException e)
            {
                throw new CrcException("Could not read the stream out as bytes.", e);
            }
            catch (InvalidCastException e)
            {
                throw new CrcException("Could not read the stream out as bytes.", e);
            }
            catch (OverflowException e)
            {
                throw new CrcException("Could not read the stream out as bytes.", e);
            }
        }
 
        /// <summary>
        /// Contains a cache of calculated checksum chunks.
        /// </summary>
        private readonly UInt32[] m_checksumTable;
 
    }

using System;

namespace LeagueSharp.SDK
{
    /// <summary>
    /// Represents different map types in the League of Legends game.
    /// </summary>
    public enum MapType
    {
        /// <summary>
        /// Crystal Scar (Dominion) map type.
        /// </summary>
        CrystalScar = 8,

        /// <summary>
        /// Howling Abyss (ARAM) map type.
        /// </summary>
        HowlingAbyss = 12,

        /// <summary>
        /// Summoner's Rift (5v5) map type.
        /// </summary>
        SummonersRift = 11,

        /// <summary>
        /// Twisted Treeline (3v3) map type.
        /// </summary>
        TwistedTreeline = 10,

        /// <summary>
        /// Unknown map type.
        /// </summary>
        Unknown = 0
    }

    /// <summary>
    /// Provides utility methods for working with map types.
    /// </summary>
    public static class MapTypeUtility
    {
        /// <summary>
        /// Gets the current map type based on the game map ID.
        /// </summary>
        /// <returns>The current map type.</returns>
        public static MapType GetCurrentMapType()
        {
            int mapId = Game.MapId;
            switch (mapId)
            {
                case 8:
                    return MapType.CrystalScar;
                case 12:
                    return MapType.HowlingAbyss;
                case 11:
                    return MapType.SummonersRift;
                case 10:
                    return MapType.TwistedTreeline;
                default:
                    return MapType.Unknown;
            }
        }

        /// <summary>
        /// Checks if the current map is a Summoner's Rift (5v5) map.
        /// </summary>
        /// <returns>True if the current map is Summoner's Rift; otherwise, false.</returns>
        public static bool IsSummonersRift()
        {
            return GetCurrentMapType() == MapType.SummonersRift;
        }

        /// <summary>
        /// Checks if the current map is a Twisted Treeline (3v3) map.
        /// </summary>
        /// <returns>True if the current map is Twisted Treeline; otherwise, false.</returns>
        public static bool IsTwistedTreeline()
        {
            return GetCurrentMapType() == MapType.TwistedTreeline;
        }

