namespace Microsoft.Azure.Management.DataLake.Store
{
    public class DataLakeStoreFirewallRuleCreateUpdateOrGetResponse : AzureOperationResponse
    {
        private FirewallRule _firewallRule;

        /// <summary>
        /// Initializes a new instance of the DataLakeStoreFirewallRuleCreateUpdateOrGetResponse class.
        /// </summary>
        public DataLakeStoreFirewallRuleCreateUpdateOrGetResponse()
        {
            // Default constructor
        }

        /// <summary>
        /// Initializes a new instance of the DataLakeStoreFirewallRuleCreateUpdateOrGetResponse class with specified firewall rule.
        /// </summary>
        /// <param name="firewallRule">The firewall rule associated with the response.</param>
        public DataLakeStoreFirewallRuleCreateUpdateOrGetResponse(FirewallRule firewallRule)
        {
            _firewallRule = firewallRule;
        }

        /// <summary>
        /// Gets or sets the firewall rule associated with the response.
        /// </summary>
        public FirewallRule FirewallRule
        {
            get { return _firewallRule; }
            set { _firewallRule = value; }
        }

        /// <summary>
        /// Validates the firewall rule and ensures it meets required criteria.
        /// </summary>
        /// <returns>True if the firewall rule is valid, otherwise false.</returns>
        public bool ValidateFirewallRule()
        {
            if (_firewallRule == null)
                return false;

            // Validate name length and allowed characters
            if (string.IsNullOrEmpty(_firewallRule.Name) ||
                _firewallRule.Name.Length > 50 ||
                !IsValidName(_firewallRule.Name))
                return false;

            // Validate start and end IP address
            if (!IsValidIpAddress(_firewallRule.StartIpAddress) ||
                !IsValidIpAddress(_firewallRule.EndIpAddress))
                return false;

            return true;
        }

        /// <summary>
        /// Checks if the provided name contains valid characters.
        /// </summary>
        private bool IsValidName(string name)
        {
            return System.Text.RegularExpressions.Regex.IsMatch(name, @"^[a-zA-Z0-9_-]+$");
        }

        /// <summary>
        /// Validates the IP address format.
        /// </summary>
        private bool IsValidIpAddress(string ipAddress)
        {
            return System.Net.IPAddress.TryParse(ipAddress, out _);
        }
    }
}

 
