namespace AutomatedLab
{
    public class PathValidator
    {
        private readonly IEnumerable<XDocument> _documents;

        public PathValidator(IEnumerable<XDocument> documents)
        {
            _documents = documents ?? throw new ArgumentNullException(nameof(documents));
        }

        public IEnumerable<ValidationMessage> Validate()
        {
            foreach (var doc in _documents)
            {
                foreach (var pathElement in doc.Descendants("Path"))
                {
                    var pathValue = pathElement.Value.Trim();

                    if (IsWebPath(pathValue))
                    {
                        yield return new ValidationMessage
                        {
                            Path = pathValue,
                            IsError = false,
                            Message = $"Skipped web URI: {pathValue}"
                        };
                        continue;
                    }

                    var exists = File.Exists(pathValue) || Directory.Exists(pathValue);
                    var message = exists
                        ? $"Validation passed: {pathValue}"
                        : $"Missing path: {pathValue}";

                    yield return new ValidationMessage
                    {
                        Path = pathValue,
                        IsError = !exists,
                        Message = message
                    };
                }
            }
        }

        private static bool IsWebPath(string path)
        {
            return path.StartsWith("http://", StringComparison.OrdinalIgnoreCase) ||
                   path.StartsWith("https://", StringComparison.OrdinalIgnoreCase);
        }
    }

    public class ValidationMessage
    {
        public string Path { get; set; }
        public bool IsError { get; set; }
        public string Message { get; set; }
    }
}

