namespace FontRendering
{
    /// <summary>
    /// Specifies glyph image formats using FourCC encoding for font processing.
    /// Encodes formats as 32-bit identifiers from ASCII characters.
    /// </summary>
    public enum GlyphFormat : uint
    {
        /// <summary>
        /// Undefined/unknown glyph format placeholder
        /// </summary>
        None = 0,

        /// <summary>
        /// Composite glyph combining multiple sub-glyphs.
        /// Requires LoadFlags.NoRecurse to prevent recursion.
        /// FourCC: 'comp' (0x636F6D70)
        /// </summary>
        Composite = (uint)('c' << 24 | 'o' << 16 | 'm' << 8 | 'p'),

        /// <summary>
        /// Pixel-based bitmap glyph representation.
        /// Corresponds to FreeType's FTBitmap structure.
        /// FourCC: 'bmap' (0x626D6170)
        /// </summary>
        Bitmap = (uint)('b' << 24 | 'm' << 16 | 'a' << 8 | 'p'),

        /// <summary>
        /// Vector outline glyph with Bézier curves.
        /// Matches FreeType's Outline type for rendering.
        /// FourCC: 'outl' (0x6F75746C)
        /// </summary>
        Outline = (uint)('o' << 24 | 'u' << 16 | 't' << 8 | 'l'),

        /// <summary>
        /// Stroke-based plotter rendering format.
        /// Used for specialized vector output devices.
        /// FourCC: 'pltr' (0x706C7472)
        /// </summary>
        Plotter = (uint)('p' << 24 | 'l' << 16 | 't' << 8 | 'r'),

        /// <summary>
        /// Experimental signed-distance field format.
        /// Used for advanced shader-based rendering.
        /// FourCC: 'sdf3' (0x73646633)
        /// </summary>
        ExperimentalSdf = (uint)('s' << 24 | 'd' << 16 | 'f' << 8 | '3'),

        /// <summary>
        /// Layered color glyph format (COLR v1).
        /// Supports multi-color vector compositions.
        /// FourCC: 'colr' (0x636F6C72)
        /// </summary>
        ColorLayers = (uint)('c' << 24 | 'o' << 16 | 'l' << 8 | 'r')
    }
}

