using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using BuildIt.States.Interfaces;

public class StateManagerBinder : BaseBinder<IStateManager>
{
    private readonly bool isBidirectional;
    private List<IStateBinder> GroupBinders { get; } = new List<IStateBinder>();

    public StateManagerBinder(IStateManager source, IStateManager target, bool bidirectional)
        : base(source, target)
    {
        isBidirectional = bidirectional;
    }

    protected override async Task InternalBind()
    {
        foreach (var sourceGroup in Source.StateGroups)
        {
            var targetGroup = Target.StateGroups.SafeValue(sourceGroup.GroupName);
            if (targetGroup == null) continue;

            var binder = new StateGroupBinder(sourceGroup, targetGroup, isBidirectional);
            GroupBinders.Add(binder);
            await binder.BindAsync();
        }
    }

    protected override void InternalUnbind()
    {
        foreach (var binder in GroupBinders)
        {
            binder.Unbind();
        }
        GroupBinders.Clear();
    }

    private class StateGroupBinder : IStateBinder
    {
        private readonly IStateGroup source;
        private readonly IStateGroup target;
        private readonly bool bidirectional;

        public StateGroupBinder(IStateGroup source, IStateGroup target, bool bidirectional)
        {
            this.source = source;
            this.target = target;
            this.bidirectional = bidirectional;
        }

        public async Task BindAsync()
        {
            source.StateChanged += OnSourceStateChanged;
            if (bidirectional) target.StateChanged += OnTargetStateChanged;
            await Task.Yield();
        }

        public void Unbind()
        {
            source.StateChanged -= OnSourceStateChanged;
            if (bidirectional) target.StateChanged -= OnTargetStateChanged;
        }

        private void OnSourceStateChanged(object sender, StateEventArgs e)
        {
            if (e.IsActive) target.ChangeState(e.StateName);
        }

        private void OnTargetStateChanged(object sender, StateEventArgs e)
        {
            if (e.IsActive) source.ChangeState(e.StateName);
        }
    }
}

public abstract class BaseBinder<T> where T : IStateManager
{
    public T Source { get; }
    public T Target { get; }

    protected BaseBinder(T source, T target)
    {
        Source = source;
        Target = target;
    }

    protected abstract Task InternalBind();
    protected abstract void InternalUnbind();
}

