    public partial class DragonVeinControl : UserControl
    {
        private Model.Unit _unit;
        private CheckBox chkDragonVein;
        private Label lblDragonVeinStatus;
        private bool _suppressChangeEvent = false;

        public DragonVeinControl()
        {
            InitializeComponent();
            InitializeControls();
        }

        private void InitializeControls()
        {
            chkDragonVein = new CheckBox
            {
                Text = "Dragon Vein Ability",
                Location = new Point(10, 10),
                AutoSize = true
            };

            lblDragonVeinStatus = new Label
            {
                Location = new Point(10, 40),
                AutoSize = true,
                ForeColor = SystemColors.ControlDarkDark
            };

            chkDragonVein.CheckedChanged += chkDragonVein_CheckedChanged;

            this.Controls.Add(chkDragonVein);
            this.Controls.Add(lblDragonVeinStatus);
        }

        public void LoadUnit(Model.Unit unit)
        {
            _unit = unit;
            PopulateControls();
        }

        private void PopulateControls()
        {
            if (_unit == null) return;

            _suppressChangeEvent = true;

            bool defaultDragonVein = Data.Database.Characters.GetDefaultDragonVeinAbility(_unit.CharacterId);
            bool currentDragonVein = _unit.HasDragonVeinAbility;

            chkDragonVein.Enabled = !defaultDragonVein;
            chkDragonVein.Checked = currentDragonVein;

            UpdateDragonVeinStatusLabel(defaultDragonVein, currentDragonVein);

            _suppressChangeEvent = false;
        }

        private void UpdateDragonVeinStatusLabel(bool defaultState, bool currentState)
        {
            string status = defaultState
                ? "Innate Dragon Vein Ability"
                : (currentState ? "Manually Enabled" : "Manually Disabled");

            lblDragonVeinStatus.Text = $"Status: {status}";
        }

        private void chkDragonVein_CheckedChanged(object sender, EventArgs e)
        {
            if (_suppressChangeEvent || _unit == null) return;

            try
            {
                _unit.HasDragonVeinAbility = chkDragonVein.Checked;
                UpdateDragonVeinStatusLabel(
                    Data.Database.Characters.GetDefaultDragonVeinAbility(_unit.CharacterId),
                    _unit.HasDragonVeinAbility
                );

