public class RawExceptionLayout : IRawLayout
{
    public object Format(LoggingEvent loggingEvent)
    {
        if (loggingEvent.ExceptionObject != null)
        {
            return loggingEvent.GetExceptionString();
        }

        return null;
    }
}

public class Log4NetAdapter : ILogger
{
    private readonly ILog _log;

    public Log4NetAdapter(Type type)
    {
        _log = LogManager.GetLogger(type);
    }

    public void Debug(string message) => _log.Debug(message);
    public void Info(string message) => _log.Info(message);
    public void Warn(string message) => _log.Warn(message);
    public void Error(string message) => _log.Error(message);
    public void Fatal(string message) => _log.Fatal(message);
    public void Error(Exception exception) => _log.Error(exception.Message, exception);

    public void Error(string format, Exception exception)
    {
        _log.Error(String.Format(format, exception.Message), exception);
    }
}

