    public Companion(Hero hero)
    {
        _hero = hero;
        _random = new Random();
        _chaseRange = BaseChaseRange + (float)_random.NextDouble() * 100;
        _isWandering = true;
        _isChasing = false;
        _position = new Vector2(_hero.Position.X, _hero.Position.Y);
        OnUpdate();
    }

    public void Create()
