    public void OnUpdate()
    {
        if (_isChasing)
        {
            ChaseTarget();
        }
        else if (_isWandering)
        {
            Wander();
        }

        // Check for nearby enemies to chase
        if (CheckForEnemies())
        {
            _isChasing = true;
            _isWandering = false;
        }
        else
        {
            _isChasing = false;
            _isWandering = true;
        }
    }

    private void Wander()
    {
        if (_targetPosition == Vector2.Zero || Vector2.Distance(_position, _targetPosition) < 10)
        {
            _targetPosition = GetRandomWanderPosition();
        }

        MoveTowards(_targetPosition);
    }

    private void ChaseTarget()
    {
        if (_targetEnemy != null)
        {
            MoveTowards(_targetEnemy.Position);
            if (Vector2.Distance(_position, _targetEnemy.Position) < AttackRange)
            {
                Attack();
            }
        }
        else
        {
            _isChasing = false;
        }
    }

    private Vector2 GetRandomWanderPosition()
    {
        float offsetX = (float)(_random.NextDouble() * 200 - 100);
        float offsetY = (float)(_random.NextDouble() * 200 - 100);
        return new Vector2(_position.X + offsetX, _position.Y + offsetY);
    }

    private void MoveTowards(Vector2 target)
    {
        Vector2 direction = Vector2.Normalize(target - _position);
        _position += direction * WanderingSpeed;
    }

