 namespace NetworkAdapterConfiguration
 {
     /// <summary>
     /// Defines flags for configuring the behavior of a network adapter in a packet filtering context.
     /// These flags control packet interception, processing, and forwarding.
     /// </summary>
     [Flags]
     public enum AdapterModes : uint
     {
         /// <summary>
         /// No specific mode is enabled.
         /// </summary>
         None = 0x00000000,

         /// <summary>
         /// Enables tunneling mode, forwarding packets through a tunnel.
         /// </summary>
         Tunneling = 0x00000001,

         /// <summary>
         /// Enables listening mode, passively monitoring network traffic.
         /// </summary>
         Listening = 0x00000002,

         /// <summary>
         /// Enables direct filtering, applying filters directly to intercepted packets.
         /// </summary>
         DirectFiltering = 0x00000004,

         /// <summary>
         /// Enables loopback handling, controlling how loopback packets are processed.
         /// </summary>
         LoopbackHandling = 0x00000008,

         /// <summary>
         /// Enables promiscuous mode, capturing all packets on the network.
         /// </summary>
         Promiscuous = 0x00000010,

         /// <summary>
         /// Enables packet injection.
         /// </summary>
         PacketInjection = 0x00000020,

         /// <summary>
         /// All modes are enabled.
         /// </summary>
         All = 0xFFFFFFFF
     }

     public class ExampleUsage
     {
         public static void ConfigureAdapter(AdapterModes modes)
         {
             if ((modes & AdapterModes.Tunneling) != 0)
             {
                 Console.WriteLine("Tunneling enabled.");
             }

             if ((modes & AdapterModes.Listening) != 0)
             {
                 Console.WriteLine("Listening enabled.");
             }
         }
     }
 }

