{
    class Writer
    {
        static void Main(string[] args)
        {
            // Display program title and instructions.
            Console.WriteLine("Catalan Number Calculator");
            Console.WriteLine("--------------------------");
            Console.WriteLine();

            // Prompt the user to enter a non-negative integer.
            Console.Write("Please enter a non-negative integer: ");
            string userInput = Console.ReadLine();
            Console.WriteLine();

            // Validate that the input is an integer and non-negative.
            int n;
            bool isValidNumber = int.TryParse(userInput, out n);
            if (!isValidNumber || n < 0)
            {
                Console.WriteLine("Error: Invalid input. You must enter a non-negative integer.");
                Console.WriteLine("Press any key to exit...");
                Console.ReadKey();
                return;
            }

            // Handle the special case where the input is zero.
            if (n == 0)
            {
                Console.WriteLine("The 0th Catalan number is: 1");
                Console.WriteLine();
                Console.WriteLine("Press any key to exit...");
                Console.ReadKey();
                return;
            }

            // Compute factorial values needed for the Catalan number formula.
            long factorialN = ComputeFactorial(n);
            long factorialNPlusOne = ComputeFactorial(n + 1);
            long factorialDoubleN = ComputeFactorial(2 * n);

            // Display the computed factorial values for debugging purposes.
            Console.WriteLine("Computed Factorials:");
            Console.WriteLine("  n!         = " + factorialN);
            Console.WriteLine("  (n+1)!     = " + factorialNPlusOne);
            Console.WriteLine("  (2n)!      = " + factorialDoubleN);
            Console.WriteLine();

            // Calculate the Catalan number using the formula:
            // Catalan(n) = (2n)! / ((n+1)! * n!)
            long catalanNumber = factorialDoubleN / (factorialNPlusOne * factorialN);

            // Output the resulting Catalan number.
            Console.WriteLine("Result:");
            Console.WriteLine("The " + n + "th Catalan number is: " + catalanNumber);
            Console.WriteLine();

            // Inform the user and wait for a key press before closing.

