    public class AuthorisationHub : Hub
    {
        // Thread-safe collection mapping connection IDs to usernames.
        private static readonly ConcurrentDictionary<string, string> Connections = new ConcurrentDictionary<string, string>();

        // Called when a new connection is established.
        public override Task OnConnected()
        {
            var userName = Context.User?.Identity?.Name;
            if (!string.IsNullOrEmpty(userName))
            {
                Connections.TryAdd(Context.ConnectionId, userName);
            }
            return base.OnConnected();
        }

        // Called when a connection is re-established after a drop.
        public override Task OnReconnected()
        {
            var userName = Context.User?.Identity?.Name;
            if (!string.IsNullOrEmpty(userName))
            {
                // Update connection record if necessary.
                Connections.AddOrUpdate(Context.ConnectionId, userName, (key, oldValue) => userName);
            }
            return base.OnReconnected();
        }

        // Called when a connection is terminated.
        public override Task OnDisconnected(bool stopCalled)
        {
            string removedUser;
            Connections.TryRemove(Context.ConnectionId, out removedUser);
            return base.OnDisconnected(stopCalled);
        }

        // Returns the number of active connections for the specified user.
        public int GetLiveConnectionsCount(string userName)
        {
            if (string.IsNullOrEmpty(userName))
            {
                return 0;
            }
            // Count all connections where the stored username matches.
            return Connections.Values.Count(u => u.Equals(userName, StringComparison.OrdinalIgnoreCase));
        }

