    /// <summary>
    /// Represents the severity level of an error.
    /// </summary>
    public enum SeverityLevel
    {
        Warning,
        Error
    }

    /// <summary>
    /// Encapsulates an error identifier with an associated severity level.
    /// </summary>
    public class ErrorCode
    {
        public string Identifier { get; private set; }
        public SeverityLevel Severity { get; private set; }

        /// <summary>
        /// Initializes a new instance of the ErrorCode class.
        /// </summary>
        /// <param name="identifier">The unique error identifier.</param>
        /// <param name="severity">The severity associated with the error.</param>
        public ErrorCode(string identifier, SeverityLevel severity)
        {
            Identifier = identifier;
            Severity = severity;
        }
    }

    /// <summary>
    /// Maintains a centralized registry of predefined error codes.
    /// </summary>
    public static class ErrorRegistry
    {
        // Predefined error instances with associated default severities.
        public static readonly ErrorCode NotFound = new ErrorCode("E001", SeverityLevel.Error);
        public static readonly ErrorCode InvalidInput = new ErrorCode("E002", SeverityLevel.Error);
        public static readonly ErrorCode ConnectionLost = new ErrorCode("W001", SeverityLevel.Warning);
        public static readonly ErrorCode Timeout = new ErrorCode("W002", SeverityLevel.Warning);
        public static readonly ErrorCode UnauthorizedAccess = new ErrorCode("E003", SeverityLevel.Error);

        // Read-only lookup structure for efficient error retrieval.
        public static readonly IReadOnlyDictionary<string, ErrorCode> Errors;

        // Static constructor to initialize the error lookup dictionary.
        static ErrorRegistry()
        {
            var errorList = new List<ErrorCode>
            {
                NotFound,
                InvalidInput,
                ConnectionLost,
                Timeout,
                UnauthorizedAccess
            };

            Errors = errorList.ToDictionary(error => error.Identifier);
        }
    }

