using System;
using System.Text;
using NUnit.Framework;
using SimpleContainer.Interface;
using SimpleContainer.Tests.Helpers;

namespace SimpleContainer.Tests
{
    public abstract class CloneContainerTest : SimpleContainerTestBase
    {
        public class Simple : CloneContainerTest
        {
            private static int counter;

            public class Hoster
            {
                public readonly IContainer container;

                public Hoster(IContainer container)
                {
                    this.container = container;
                }
            }

            public class ComponentWrap
            {
                public readonly Component component;
                private readonly int myCounter = counter++;

                public ComponentWrap(Component component)
                {
                    this.component = component;
                    LogBuilder.Append("ComponentWrap" + myCounter + ".ctor ");
                }
            }

            public class Component : IDisposable
            {
                private readonly int myCounter = counter++;

                public Component()
                {
                    LogBuilder.Append("Component" + myCounter + ".ctor ");
                }

                public void Dispose()
                {
                    LogBuilder.Append("Component" + myCounter + ".Dispose ");
                }
            }

            [Test]
            public void Test()
            {
                using (var container = Container())
                {
                    Assert.That(LogBuilder.ToString(), Is.EqualTo(""));
                    var hoster = container.Get<Hoster>();
                    Assert.That(LogBuilder.ToString(), Is.EqualTo(""));
                    var outerWrap = container.Get<ComponentWrap>();
                    Assert.That(LogBuilder.ToString(), Is.EqualTo("Component0.ctor ComponentWrap1.ctor "));
                    LogBuilder.Clear();
                    ComponentWrap clone1;
                    using (var clonedContainer = hoster.container.Clone(null))
                    {
                        clone1 = clonedContainer.Get<ComponentWrap>();
                        Assert.That(clone1, Is.Not.SameAs(outerWrap));
                        Assert.That(LogBuilder.ToString(), Is.EqualTo("Component2.ctor ComponentWrap3.ctor "));
                        Assert.That(container.Get<ComponentWrap>(), Is.SameAs(outerWrap));
                        LogBuilder.Clear();
                    }

using Eflat.Util;
using System;
using System.Collections.Generic;

namespace Eflat
{
    /// <summary>
    /// The typer performs two main functions:
    /// 1. It performs type-checking and checks for non-parsing errors.
    /// 2. It infers unknown or incomplete types.
    /// </summary>
    public sealed class Typer
    {
        /// <summary>
        /// The typers reference to the syntax tree. We will modify this syntax tree
        /// in order to infer unknown types.
        /// </summary>
        private readonly SyntaxTree Ast;

        /// <summary>
        /// The list of errors found during the Typer stage.
        /// </summary>
        private readonly List<EFlatErrorException> Errors;

        /// <summary>
        /// The list of warnings found during the Typer stage.
        /// </summary>
        private readonly List<EFlatErrorException> Warnings;

        public Typer(SyntaxTree ast)
        {
            Ast = ast;
            Errors = new List<EFlatErrorException>();
            Warnings = new List<EFlatErrorException>();
        }

        /// <summary>
        /// Perform the typer operations as described in the documentation for the class.
        /// </summary>
        public void Typecheck()
        {
            CheckStructDeclarations();
            CheckGlobalStatements();
            CheckFunctionDeclarations();
        }

        /// <summary>
        /// Check each function declaration.
        /// </summary>
        private void CheckFunctionDeclarations()
        {
            foreach (FuncDecl function in Ast.Functions)
            {
                CheckFuncDecl(function);
            }
        }

        /// <summary>
        /// Check this function declaration.
        /// </summary>
        /// <param name="function"></param>
        private void CheckFuncDecl(FuncDecl function)
        {
            Scope scope = function.Scope;
            foreach (Statement statement in scope.Statements)
            {
                CheckStatement(statement, scope);
            }
        }

        /// <summary>
        /// Check all the struct declarations.
        /// </summary>
        private void CheckStructDeclarations()
        {
            foreach (StructDecl decl in Ast.Structs)
            {
                CheckStructDeclaration(decl);
            }
        }

        private void CheckStructDeclaration(StructDecl decl)
        {
            foreach (Statement field in decl.Scope.Statements)
            {
                CheckStructField(decl, field);
            }
        }

