using System;
 
public class Parser
{
    public static void Main()
    {
        const double pi = Math.PI;
        const double degree = pi / 180;
 
        Console.WriteLine("=== radians ===");
        Console.WriteLine("sin(pi/3) = " + Math.Sin(pi / 3));
        Console.WriteLine("cos(pi/3) = " + Math.Cos(pi / 3));
        Console.WriteLine("tan(pi/3) = " + Math.Tan(pi / 3));
        Console.WriteLine("arcsin(1/2) = " + Math.Asin(0.5));
        Console.WriteLine("arccos(1/2) = " + Math.Acos(0.5));
        Console.WriteLine("arctan(1/2) = " + Math.Atan(0.5));
 
        Console.WriteLine("\n=== degrees ===");
        Console.WriteLine("sin(60°) = " + Math.Sin(60 * degree));
        Console.WriteLine("cos(60°) = " + Math.Cos(60 * degree));
        Console.WriteLine("tan(60°) = " + Math.Tan(60 * degree));
        Console.WriteLine("arcsin(1/2) = " + Math.Asin(0.5) / degree + "°");
        Console.WriteLine("arccos(1/2) = " + Math.Acos(0.5) / degree + "°");
        Console.WriteLine("arctan(1/2) = " + Math.Atan(0.5) / degree + "°");
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

public class Address
{
    public string Value { get; }

    public Address(string value)
    {
        Value = value;
    }
}

public class Topic : Address
{
    public Topic(string value) : base(value) { }
}

public class TransportMessage
{
    public Dictionary<string, object> Headers { get; } = new Dictionary<string, object>();
    public object Body { get; set; }
}

public class MessageUnit
{
    private Func<TransportMessage, Task> _outgoingHandler;
    public Address Address { get; }

    public MessageUnit(Address address)
    {
        Address = address;
    }

    public void SetOutgoing(Func<TransportMessage, Task> outgoingHandler)
    {
        _outgoingHandler = outgoingHandler;
    }

    public virtual Task StartAsync() => Task.CompletedTask;
    public virtual Task StopAsync() => Task.CompletedTask;

    public async Task SendAsync(TransportMessage message)
    {
        if (_outgoingHandler != null)
            await _outgoingHandler(message);
    }

    public virtual Task HandleAsync(TransportMessage message) => Task.CompletedTask;
}

public class Broker
{
    private readonly List<MessageUnit> _allUnits = new List<MessageUnit>();
    private readonly Dictionary<Address, List<MessageUnit>> _addressMap = new Dictionary<Address, List<MessageUnit>>();

    public void Register(MessageUnit unit)
    {
        _allUnits.Add(unit);
        if (!_addressMap.TryGetValue(unit.Address, out var list))
        {
            list = new List<MessageUnit>();
            _addressMap[unit.Address] = list;
        }
        list.Add(unit);
        unit.SetOutgoing(Outgoing);
    }

    public async Task StartAsync()
    {
        foreach (var unit in _allUnits)
            await unit.StartAsync();
    }

    public async Task StopAsync()
    {
        foreach (var unit in Enumerable.Reverse(_allUnits))
            await unit.StopAsync();
    }

    private async Task Outgoing(TransportMessage message)
    {
        if (message.Headers.TryGetValue("Destination", out var destObj) && destObj is Address destination)
        {
            if (_addressMap.TryGetValue(destination, out var handlers))
            {
                foreach (var handler in handlers)
                    await handler.HandleAsync(message);
            }
        }
    }
}

