using System;
using System.Drawing;
using GMap.NET;
using GMap.NET.WindowsForms;

namespace MissionPlanner.Maps
{
    [Serializable]
    public class GMapMarkerADSBPlane : GMapMarker
    {
        private static readonly Bitmap icong = new Bitmap(global::MissionPlanner.Properties.Resources.FW_icons_2013_logos_01, new Size(40, 40));
        private static readonly Bitmap iconr = new Bitmap(global::MissionPlanner.Properties.Resources.FW_icons_2013_logos_011, new Size(40, 40));
        private static readonly Bitmap icono = new Bitmap(global::MissionPlanner.Properties.Resources.FW_icons_2013_logos_012, new Size(40, 40));

        public float heading = 0;
        public AlertLevelOptions AlertLevel = AlertLevelOptions.Green;

        public enum AlertLevelOptions
        {
            Green,
            Orange,
            Red
        }

        public GMapMarkerADSBPlane(PointLatLng p, float heading, AlertLevelOptions alert = AlertLevelOptions.Green)
            : base(p)
        {
            this.AlertLevel = alert;
            this.heading = heading;
            Size = icong.Size;
        }

        public override void OnRender(Graphics g)
        {
            var temp = g.Transform;
            g.TranslateTransform(LocalPosition.X, LocalPosition.Y);

            g.RotateTransform(-Overlay.Control.Bearing);

            try
            {
                g.RotateTransform(heading);
            }
            catch
            {
            }

            switch (AlertLevel)
            {
                case AlertLevelOptions.Green:
                    g.DrawImageUnscaled(icong, icong.Width/-2, icong.Height/-2);
                    break;
                case AlertLevelOptions.Orange:
                    g.DrawImageUnscaled(icono, icono.Width/-2, icono.Height/-2);
                    break;
                case AlertLevelOptions.Red:
                    g.DrawImageUnscaled(iconr, iconr.Width/-2, iconr.Height/-2);
                    break;
            }

            g.Transform = temp;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace OlympicGames.Commands
{
    public class CreateSprinterCommand : Command
    {
        private string[] parameters;
        private Dictionary<string, TimeSpan> records;

        public CreateSprinterCommand(string command, string[] parameters)
            : base(command)
        {
            this.parameters = parameters;
            records = new Dictionary<string, TimeSpan>();
        }

        public override string Execute()
        {
            if (!ValidateInputParameters())
            {
                return "Invalid input parameters.";
            }

            string firstName = parameters[0];
            string lastName = parameters[1];
            string country = parameters[2];

            ParsePersonalRecords(parameters.Skip(3).ToArray());

            Sprinter sprinter = AthleteFactory.CreateSprinter(firstName, lastName, country, records);

            Committee.AddAthlete(sprinter);

            return GenerateOutput(sprinter);
        }

        private bool ValidateInputParameters()
        {
            return parameters.Length >= 3 &&
                   ValidateMinAndMaxLength(parameters[0], 1, 50) &&
                   ValidateMinAndMaxLength(parameters[1], 1, 50) &&
                   ValidateMinAndMaxLength(parameters[2], 1, 50);
        }

        private void ParsePersonalRecords(string[] recordParams)
        {
            foreach (var record in recordParams)
            {
                var parts = record.Split(';');
                if (parts.Length == 2 && TimeSpan.TryParse(parts[1], out TimeSpan time))
                {
                    records[parts[0]] = time;
                }
            }
        }

        private string GenerateOutput(Sprinter sprinter)
        {
            StringBuilder sb = new StringBuilder();
            sb.AppendLine($"Sprinter Created: {sprinter.FirstName} {sprinter.LastName}");
            sb.AppendLine($"Country: {sprinter.Country}");
            sb.AppendLine("Personal Records:");
            foreach (var record in records)
            {
                sb.AppendLine($"{record.Key}: {record.Value}");
            }
            return sb.ToString();
        }

        private bool ValidateMinAndMaxLength(string input, int minLength, int maxLength)
        {
            return input.Length >= minLength && input.Length <= maxLength;
        }
    }
}

