namespace CustomDependencyResolver
{
    // Custom dependency resolver integrating Unity container with ASP.NET Web API.
    public class UnityResolverWebApi : IDependencyResolver
    {
        private IUnityContainer _container;
        private bool disposed = false;

        // Constructor accepting the Unity container instance.
        public UnityResolverWebApi(IUnityContainer container)
        {
            if (container == null)
                throw new ArgumentNullException(nameof(container), "Container cannot be null.");

            _container = container;
        }

        // Retrieves a single service instance of the specified type.
        public object GetService(Type serviceType)
        {
            if (disposed)
                throw new ObjectDisposedException("UnityResolverWebApi");

            try
            {
                // Attempt to resolve the requested service.
                return _container.Resolve(serviceType);
            }
            catch (ResolutionFailedException)
            {
                // Gracefully handle the failure by returning null.
                return null;
            }
        }

        // Retrieves multiple service instances of the specified type.
        public IEnumerable<object> GetServices(Type serviceType)
        {
            if (disposed)
                throw new ObjectDisposedException("UnityResolverWebApi");

            try
            {
                // Return all resolved services.
                return _container.ResolveAll(serviceType);
            }
            catch (ResolutionFailedException)
            {
                // Return an empty list if resolution fails.
                return new List<object>();
            }
        }

        // Creates a nested dependency scope.
        public IDependencyScope BeginScope()
        {
            if (disposed)
                throw new ObjectDisposedException("UnityResolverWebApi");

            // Create a child container for managing scope-specific lifetimes.
            var childContainer = _container.CreateChildContainer();
            return new UnityResolverWebApi(childContainer);
        }

        // Implements the Dispose pattern to free resources.
        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }

        // Protected dispose method to free managed/unmanaged resources.
        protected virtual void Dispose(bool disposing)

