using UnityEngine;
using System.Collections.Generic;

public class FollowObject : MonoBehaviour
{
    public Transform m_Target;
    public bool m_TranslateXPosition = true;
    public bool m_TranslateYPosition = true;
    public bool m_TranslateZPosition = true;

    private Bounds m_Bounds;
    private Vector3 m_DifCenter;

    private void Start()
    {
        CalculateBoundsAndOffset();
    }

    private void CalculateBoundsAndOffset()
    {
        Renderer targetRenderer = m_Target.GetComponent<Renderer>();
        List<Renderer> renderers = new List<Renderer>();

        if (targetRenderer != null)
            renderers.Add(targetRenderer);

        Renderer[] childRenderers = m_Target.GetComponentsInChildren<Renderer>();
        foreach (Renderer r in childRenderers)
        {
            if (r.transform != m_Target)
                renderers.Add(r);
        }

        if (renderers.Count == 0)
        {
            m_DifCenter = Vector3.zero;
            return;
        }

        if (targetRenderer != null)
        {
            m_Bounds = renderers[0].bounds;
            for (int i = 1; i < renderers.Count; i++)
                m_Bounds.Encapsulate(renderers[i].bounds);

            m_DifCenter = m_Bounds.center - m_Target.position;
        }
        else
        {
            Vector3 sum = Vector3.zero;
            foreach (Renderer r in renderers)
                sum += r.bounds.center;

            m_DifCenter = (sum / renderers.Count) - m_Target.position;
        }
    }

    private void Update()
    {
        if (m_Target == null)
            return;

        Vector3 targetPosition = m_Target.position + m_DifCenter;
        Vector3 newPosition = transform.position;

        if (m_TranslateXPosition)
            newPosition.x = targetPosition.x;

        if (m_TranslateYPosition)
            newPosition.y = targetPosition.y;

        if (m_TranslateZPosition)
            newPosition.z = targetPosition.z;

        transform.position = newPosition;
    }
}

