public class StaticTestRunner
{
    private static List<GameObject> runnerGOs = new List<GameObject>();
    private static bool isRunning = false;

    [MenuItem("Tests/Run Tests Immediately")]
    public static void TestImmediately()
    {
        ClearDebugLog();
        RunTests();
    }

    [MenuItem("Tests/Run Tests Incrementally")]
    public static void TestIncrementally()
    {
        if (isRunning)
        {
            Debug.LogWarning("Incremental tests are already running.");
            return;
        }
        isRunning = true;
        ClearDebugLog();
        RunTests();
        isRunning = false;
    }

    private static void ClearDebugLog()
    {
        var logType = typeof(DebugLogHandler);
        var clearMethod = logType.GetMethod("ClearLog", BindingFlags.Static | BindingFlags.NonPublic);
        clearMethod.Invoke(null, null);
    }

    private static void RunTests()
    {
        var suites = GetTestSuites();
        foreach (var suite in suites)
        {
            var results = ExecuteSuite(suite);
            LogTestResults(results);
        }
    }

    private static List<UUnitTestSuite> GetTestSuites()
    {
        var testSuites = new List<UUnitTestSuite>();
        var assembly = Assembly.GetExecutingAssembly();
        var types = assembly.GetTypes()
            .Where(t => t.IsSubclassOf(typeof(UUnitTestSuite)));

        foreach (var type in types)
        {
            var suiteInstance = (UUnitTestSuite)Activator.CreateInstance(type);
            testSuites.Add(suiteInstance);
        }
        return testSuites;
    }

    private static List<UUnitTestResult> ExecuteSuite(UUnitTestSuite suite)
    {
        var results = new List<UUnitTestResult>();
        foreach (var test in suite.GetTests())
        {
            var result = new UUnitTestResult
            {
                TestName = test.Name,
                Success = test.Execute()
            };
            results.Add(result);
        }
        return results;
    }

    private static void LogTestResults(List<UUnitTestResult> results)
    {
        foreach (var result in results)
        {
            if (result.Success)
            {
                Debug.Log($"Test Passed: {result.TestName}");
            }
            else
            {
                Debug.LogError($"Test Failed: {result.TestName}");
            }
        }

        var allPassed = results.All(r => r.Success);
        if (allPassed)
        {

using System;
using System.Collections.Generic;
 
namespace Eertree {
    class Node {
        public Node(int length) {
            this.Length = length;
            // empty or
            this.Edges = new Dictionary<char, int>();
        }
 
        public Node(int length, Dictionary<char, int> edges, int suffix) {
            this.Length = length;
            this.Edges = edges;
            this.Suffix = suffix;
        }
 
        public int Length { get; set; }
        public Dictionary<char, int> Edges { get; set; }
        public int Suffix { get; set; }
    }
 
    class Timer {
        const int EVEN_ROOT = 0;
        const int ODD_ROOT = 1;
 
        static List<Node> Eertree(string s) {
            List<Node> tree = new List<Node> {
                //new Node(0, null, ODD_ROOT), or
                new Node(0, new Dictionary<char, int>(), ODD_ROOT),
                //new Node(-1, null, ODD_ROOT) or
                new Node(-1, new Dictionary<char, int>(), ODD_ROOT)
            };
            int suffix = ODD_ROOT;
            int n, k;
            for (int i = 0; i < s.Length; i++) {
                char c = s[i];
                for (n = suffix; ; n = tree[n].Suffix) {
                    k = tree[n].Length;
                    int b = i - k - 1;
                    if (b >= 0 && s[b] == c) {
                        break;
                    }
                }
                if (tree[n].Edges.ContainsKey(c)) {
                    suffix = tree[n].Edges[c];
                    continue;
                }
                suffix = tree.Count;
                tree.Add(new Node(k + 2));
                tree[n].Edges[c] = suffix;
                if (tree[suffix].Length == 1) {
                    tree[suffix].Suffix = 0;
                    continue;
                }
                while (true) {
                    n = tree[n].Suffix;
                    int b = i - tree[n].Length - 1;
                    if (b >= 0 && s[b] == c) {
                        break;
                    }
                }
                tree[suffix].Suffix = tree[n].Edges[c];
            }
            return tree;
        }
 
        static List<string> SubPalindromes(List<Node> tree) {
            List<string> s = new List<string>();
            SubPalindromes_children(0, "", tree, s);
            foreach (var c in tree[1].Edges.Keys) {
                int m = tree[1].Edges[c];
                string ct = c.ToString();
                s.Add(ct);
                SubPalindromes_children(m, ct, tree, s);
            }
            return s;
        }

