using System;
using System.Collections.Generic;
using System.Linq;
 
namespace Life
{
    class Stack
    {
        static void Main(string[] args)
        {
            var blinker = new HashSet<Cell>
            {
                new Cell(1, 0),
                new Cell(1, 1),
                new Cell(1, 2)
            };
 
            Life(blinker, 3, 3, 3);
 
            var glider = new HashSet<Cell>
            {
                new Cell(1, 0),
                new Cell(2, 1),
                new Cell(0, 2),
                new Cell(1, 2),
                new Cell(2, 2)
            };
 
            Life(glider, 20, 8, 8);
        }
 
        static void Life(HashSet<Cell> init, int iters, int width, int height)
        {
            var col = init;
            for (var i = 0; i <= iters; i++)
            {
                Console.WriteLine($"({i})");
                if (i!= 0)
                {
                    col = Generation(col);
                }
                PrintColony(col, width, height);
            }
        }
 
        static void PrintColony(HashSet<Cell> col, int width, int height)
        {
            for (var y = 0; y < height; y++)
            {
                for (var x = 0; x < width; x++)
                {
                    Console.Write(col.Contains(new Cell(x, y))? "O " : ". ");
                }
                Console.WriteLine();
            }
        }
 
        static HashSet<Cell> Generation(HashSet<Cell> col)
        {
            var ncnts = NeighbourCounts(col);
            return ncnts.Where(nc => (nc.Value == 2 && col.Contains(nc.Key)) || nc.Value == 3)
               .Select(nc => nc.Key)
               .ToHashSet();
        }
 
        static Dictionary<Cell, int> NeighbourCounts(HashSet<Cell> col)
        {
            var ncnts = new Dictionary<Cell, int>();
            foreach (var cell in col.SelectMany(Neighbours))
            {
                if (ncnts.ContainsKey(cell))
                {
                    ncnts[cell]++;
                }
                else
                {
                    ncnts.Add(cell, 1);
                }
            }
            return ncnts;
        }
 
        static IEnumerable<Cell> Neighbours(Cell cell)
        {
            return new[]
            {
                new Cell(cell.X - 1, cell.Y - 1),
                new Cell(cell.X, cell.Y - 1),
                new Cell(cell.X + 1, cell.Y - 1),
                new Cell(cell.X - 1, cell.Y),
                new Cell(cell.X + 1, cell.Y),
                new Cell(cell.X - 1, cell.Y + 1),

using System;
 
interface IOperable
{
    string Operate();
}
 
class Inoperable
{
}
 
class Operable : IOperable
{
    public string Operate()
    {
        return "Delegate implementation.";
    }
}
 
class Delegator : IOperable
{
    object Delegate;
 
    public string Operate()
    {
        var operable = Delegate as IOperable;
        return operable != null ? operable.Operate() : "Default implementation.";
    }
 
    static void Main()
    {
        var delegator = new Delegator();
