int[] data = new int[] {
    85, 88, 75, 66, 25, 29, 83, 39, 97,
    68, 41, 10, 49, 16, 65, 32, 92, 28, 98
};
 
int pick(int at, int remain, int accu, int treat) {
    if (remain == 0) return accu > treat? 1 : 0;
    return pick(at - 1, remain - 1, accu + data[at - 1], treat) +
           (at > remain? pick(at - 1, remain, accu, treat) : 0);
}
 
public static void Main(string[] args) {
    int treat = 0;
    double total = 1.0;
    for (int i = 0; i < 9; i++) treat += data[i];
    for (int i = 19; i > 9; i--) total *= i;
    for (int i = 9; i > 0; i--) total /= i;
    int gt = pick(19, 9, 0, treat);
    int le = (int)(total - gt);
    Console.WriteLine("<= : {0:F2}%  {1}", 100.0 * le / total, le);
    Console.WriteLine(" > : {0:F2}%  {1}", 100.0 * gt / total, gt);
}

