namespace CubanPrimes
{
    class Cache
    {
        static void Main(string[] args)
        {
            var primes = new List<long> { 3, 5 };
            const int cutOff = 200;
            const int bigUn = 100_000;
            const int chunks = 50;
            const int little = bigUn / chunks;
 
            Console.WriteLine($"The first {cutOff} cuban primes:");
            var showEach = true;
            var c = 0;
            var u = 0L;
            var v = 1L;
            var i = 1L;
            while (i > 0)
            {
                var found = false;
                u += 6;
                v += u;
                var mx = (int)Math.Ceiling(Math.Sqrt(v));
                foreach (var item in primes)
                {
                    if (item > mx) break;
                    if (v % item == 0)
                    {
                        found = true;
                        break;
                    }
                }
                if (!found)
                {
                    c++;
                    if (showEach)
                    {
                        var z = primes.Last() + 2;
                        while (z <= v - 2)
                        {
                            var fnd = false;
                            foreach (var item in primes)
                            {
                                if (item > mx) break;
                                if (z % item == 0)
                                {
                                    fnd = true;
                                    break;
                                }
                            }
                            if (!fnd)
                            {
                                primes.Add(z);
                            }
                            z += 2;
                        }
                        primes.Add(v);
                        Console.Write($"{v,11:N0}");
                        if (c % 10 == 0) Console.WriteLine();
                        if (c == cutOff)
                        {
                            showEach = false;
                            Console.Write($"\nProgress to the {bigUn}th cuban prime: ");
                        }
                    }
                    if (c % little == 0)
                    {
                        Console.Write(".");
                        if (c == bigUn) break;
                    }
                }
                i++;
            }

