namespace ExcelTableConverter
{
    public sealed class TableConversionManager
    {
        private static readonly Lazy<TableConversionManager> _instance =
            new Lazy<TableConversionManager>(() => new TableConversionManager());
        private readonly Dictionary<string, BaseTableConverter> _converters;

        public static TableConversionManager Instance => _instance.Value;
        public BaseTableConverter CurrentConverter { get; private set; }

        private TableConversionManager()
        {
            _converters = ReflectionConverterLoader.LoadConverters();
            CurrentConverter = _converters.Values.FirstOrDefault();
        }

        public string GetConvertedContent()
        {
            var table = GetExcelTable();
            return CurrentConverter?.Convert(table) ?? string.Empty;
        }

        public ExcelTable GetExcelTable()
        {
            var reader = ExcelReaderFactory.CreateReader();
            return reader.GetExcelTable(ExcelProperties.Instance);
        }

        public List<string> GetConverterNames() => _converters.Keys.ToList();

        public void SetCurrentConverter(string converterName)
        {
            if (_converters.TryGetValue(converterName, out var converter))
                CurrentConverter = converter;
        }
    }

    public static class ReflectionConverterLoader
    {
        public static Dictionary<string, BaseTableConverter> LoadConverters()
        {
            var converters = new Dictionary<string, BaseTableConverter>();
            var converterTypes = System.Reflection.Assembly.GetExecutingAssembly()
                .GetTypes()
                .Where(t => t.IsSubclassOf(typeof(BaseTableConverter)) && !t.IsAbstract);

            foreach (var type in converterTypes)
                if (System.Activator.CreateInstance(type) is BaseTableConverter converter)
                    converters.Add(converter.Name, converter);

            return converters;
        }
    }

    public abstract class BaseTableConverter
    {
        public abstract string Name { get; }
        public abstract string Convert(ExcelTable table);
    }

