[AttributeUsage(AttributeTargets.Method | AttributeTargets.Constructor | AttributeTargets.Struct | AttributeTargets.Class | AttributeTargets.Assembly, AllowMultiple = true, Inherited = false)]
public sealed class MySqlClientPermissionAttribute : DBDataPermissionAttribute
{
    public MySqlClientPermissionAttribute(SecurityAction action)
        : base(action)
    {
    }

    public override IPermission CreatePermission()
    {
        MySqlClientPermission permission = new MySqlClientPermission(this.PermissionState);
        if (this.PermissionState != PermissionState.Unrestricted)
        {
            foreach (DBDataPermissionEntry entry in this.GetPermissionEntries())
            {
                permission.Add(entry);
            }
        }
        return permission;
    }
}

[Serializable]
public sealed class MySqlClientPermission : DBDataPermission
{
    public MySqlClientPermission(PermissionState state)
        : base(state)
    {
    }

    public MySqlClientPermission()
        : base()
    {
    }

    public MySqlClientPermission(DBDataPermission permission)
        : base(permission)
    {
    }

    public void Add(string connectionString, string restrictions)
    {
        base.Add(connectionString, restrictions);
    }

    public override IPermission Copy()
    {
        return new MySqlClientPermission(this);
    }

    public override IPermission Union(IPermission target)
    {
        if (target == null)
        {
            return this.Copy();
        }
        if (!(target is MySqlClientPermission))
        {
            throw new ArgumentException("Invalid permission type");
        }
        MySqlClientPermission unionPermission = new MySqlClientPermission(PermissionState.None);
        unionPermission.SetFromPermission(this);
        unionPermission.SetFromPermission(target);
        return unionPermission;
    }

    public override IPermission Intersect(IPermission target)
    {
        if (target == null)
        {
            return null;
        }
        if (!(target is MySqlClientPermission))
        {
            throw new ArgumentException("Invalid permission type");
        }
        MySqlClientPermission intersectPermission = new MySqlClientPermission(PermissionState.None);
        intersectPermission.SetFromPermission(this);
        intersectPermission.SetFromPermission(target);
        intersectPermission.SetToIntersection(this, target);
        return intersectPermission;
    }

