        /// <summary>
        /// Converts a string input or DateTime object to a DateTime.
        /// If the input is invalid or null, returns the current date/time.
        /// </summary>
        /// <param name="value">The input value to convert.</param>
        /// <param name="targetType">The target type (typically DateTime).</param>
        /// <param name="parameter">Optional converter parameter.</param>
