        /// <returns>A DateTime object.</returns>
        public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
        {
            // If the value is null, return the current date/time as a default.
            if (value == null)
            {
                return DateTime.Now;
            }

            DateTime parsedDate;

            // Check if the supplied value is a string.
            if (value is string dateString)
            {
                // Try to parse the string using the provided culture.
                if (DateTime.TryParse(dateString, culture, DateTimeStyles.None, out parsedDate))
                {
                    return parsedDate;
                }
                else
                {
                    return DateTime.Now;
                }
            }

            // If the value is already a DateTime, return it.
            if (value is DateTime dateTimeValue)
            {
                return dateTimeValue;
            }

            // In any other case, fallback to current date/time.
            return DateTime.Now;
        }

