namespace Vector
{
    class Reader
    {
        public class node
        {
            public int intValue;
            public node left;
            public node right;
        }

        public static IEnumerable<int> leaves(node t)
        {
            var ch = new List<int>();
            // recursive function to walk tree.
            Action<node> f = null;
            f = (n) =>
            {
                if (n == null)
                {
                    return;
                }
                // leaves are identified by having no children.
                if (n.left == null && n.right == null)
                {
                    ch.Add(n.intValue);
                }
                else
                {
                    f(n.left);
                    f(n.right);
                }
            };
            // goroutine runs concurrently with others.
            // it walks the tree then closes the channel.
            Task.Run(() =>
            {
                f(t);
            });
            return ch;
        }

        public static bool sameFringe(node t1, node t2)
        {
            var f1 = leaves(t1);
            var f2 = leaves(t2);
            foreach (var l1 in f1)
            {
                // both trees must yield a leaf, and the leaves must be equal.
                if (f2.Count() == 0 || l1!= f2.First())
                {
                    return false;
                }
                f2 = f2.Skip(1);
            }
            // there must be nothing left in f2 after consuming all of f1.
            return f2.Count() == 0;
        }

