using System;

namespace ObjectPooling
{
    public class ObjectPool<TSource, TObject> where TObject : IDisposable
    {
        private readonly Queue<PooledObject<TSource, TObject>> _availableObjects;
        private int _currentVersion;

        public ObjectPool(Func<TSource, TObject> objectFactory, int initialCapacity = 10)
        {
            _availableObjects = new Queue<PooledObject<TSource, TObject>>(initialCapacity);
            _currentVersion = 0;
            for (int i = 0; i < initialCapacity; i++)
            {
                _availableObjects.Enqueue(new PooledObject<TSource, TObject>(this, default, objectFactory(default), _currentVersion));
            }
        }

        public PooledObject<TSource, TObject> GetObject(TSource source)
        {
            if (_availableObjects.Count == 0)
            {
                _currentVersion++;
                return new PooledObject<TSource, TObject>(this, source, new Func<TObject>(() => (TObject)Activator.CreateInstance(typeof(TObject)))(), _currentVersion);
            }

            var pooledObject = _availableObjects.Dequeue();
            pooledObject.UpdateSource(source);
            pooledObject.UpdateVersion(_currentVersion);
            return pooledObject;
        }

        public void ReturnObject(PooledObject<TSource, TObject> pooledObject)
        {
            pooledObject.Value.Dispose();
            pooledObject.UpdateVersion(_currentVersion);
            _availableObjects.Enqueue(pooledObject);
        }
    }

    public class PooledObject<TSource, TObject> : IDisposable where TObject : IDisposable
    {
        private readonly ObjectPool<TSource, TObject> _pool;
        private TSource _source;
        private int _version;

        public TObject Value { get; private set; }

        public PooledObject(ObjectPool<TSource, TObject> pool, TSource source, TObject value, int version)
        {
            _pool = pool;
            _source = source;
            Value = value;
            _version = version;
        }

        public void UpdateSource(TSource source)
        {
            _source = source;
        }

        public void UpdateVersion(int version)
        {
            _version = version;
        }

        public void Dispose()
        {
            _pool.ReturnObject(this);
        }
    }
}

