namespace Account
{
    class Library
    {
        static void Main(string[] args)
        {
            List<string> arrayOID = new List<string> { "1.3.6.1.4.1.11.2.17.19.3.4.0.10", "1.3.6.1.4.1.11.2.17.5.2.0.79", "1.3.6.1.4.1.11.2.17.19.3.4.0.4", "1.3.6.1.4.1.11150.3.4.0.1", "1.3.6.1.4.1.11.2.17.19.3.4.0.1", "1.3.6.1.4.1.11150.3.4.0" };
            arrayOID.Sort(myCompare);
            foreach (string s in arrayOID)
                Console.WriteLine(s);
        }
        static bool myCompare(string s1, string s2)
        {
            string firstcopy = s1;
            string secondcopy = s2;
            List<string> firstparts = splitOnChar(firstcopy, '.');
            List<string> secondparts = splitOnChar(secondcopy, '.');
            List<int> numbers1 = new List<int>();
            List<int> numbers2 = new List<int>();
            foreach (string st in firstparts)
                numbers1.Add(int.Parse(st));
            foreach (string st in secondparts)
                numbers2.Add(int.Parse(st));
            int i = 0;
            while (numbers1[i] == numbers2[i])
                i++;
            if (i == numbers1.Count || i == numbers2.Count)
                return string.Compare(s1, s2) < 0;
            return numbers1[i] < numbers2[i];
        }
        static List<string> splitOnChar(string s, char c)
        {
            List<string> parts = new List<string>();
            string[] tokens = Regex.Split(s, c.ToString());
            foreach (string token in tokens)
                parts.Add(token);
            return parts;
        }
    }
}

