namespace FakeSqlProvider
{
    public static class SqlCommandDefinitions
    {
        public const string Insert = "INSERT";
        public const string Update = "UPDATE";
        public const string Delete = "DELETE";
        public const string Select = "SELECT";
        public const string Count  = "COUNT";
    }

    public interface IFakeSqlCommand
    {
        string Execute();
    }

    public class FakeSqlConnection : IDisposable
    {
        private string _tableId;
        public Dictionary<string, bool> Features { get; private set; }
        public Action OnOpenAction { get; set; }

        public FakeSqlConnection(string tableId)
        {
            _tableId = tableId;
            Features = new Dictionary<string, bool>();
        }

        public void Open()
        {
            // Custom behavior on opening the connection
            OnOpenAction?.Invoke();
        }

        public IFakeSqlCommand CreateCommand(string commandText)
        {
            if (string.IsNullOrWhiteSpace(commandText))
            {
                throw new ArgumentException("Command text cannot be null or empty.");
            }

            string upperCmd = commandText.ToUpperInvariant();

            if (upperCmd.StartsWith(SqlCommandDefinitions.Insert))
                return new FakeInsertCommand(_tableId, commandText);
            if (upperCmd.StartsWith(SqlCommandDefinitions.Update))
                return new FakeUpdateCommand(_tableId, commandText);
            if (upperCmd.StartsWith(SqlCommandDefinitions.Delete))
                return new FakeDeleteCommand(_tableId, commandText);
            if (upperCmd.StartsWith(SqlCommandDefinitions.Select))
                return new FakeSelectCommand(_tableId, commandText);
            if (upperCmd.StartsWith(SqlCommandDefinitions.Count))
                return new FakeCountCommand(_tableId, commandText);

            throw new NotSupportedException("The provided SQL command is not supported in this fake connection.");
        }

        public void Dispose()
        {
            // No real resources to dispose
        }
    }

    public abstract class FakeSqlCommandBase : IFakeSqlCommand
    {
        protected string TableId { get; }
        protected string CommandText { get; }

        protected FakeSqlCommandBase(string tableId, string commandText)
        {
            TableId = tableId;
            CommandText = commandText;
        }

        public abstract string Execute();
    }

    public class FakeInsertCommand : FakeSqlCommandBase

