using System;
using System.Collections.Generic;
using System.Threading;
using ChakraCore.NET.API;

public interface IContextSwitchService : IDisposable
{
    void Enter(JavaScriptContext context);
    void Leave(JavaScriptContext context);
    void With(JavaScriptContext context, Action action);
    T With<T>(JavaScriptContext context, Func<T> func);
}

public class ContextSwitchService : IContextSwitchService
{
    private readonly Dictionary<JavaScriptContext, int> _contextRefCount = new Dictionary<JavaScriptContext, int>();
    private readonly Dictionary<JavaScriptContext, AutoResetEvent> _contextHandles = new Dictionary<JavaScriptContext, AutoResetEvent>();
    private readonly ThreadLocal<Stack<JavaScriptContext>> _currentContexts = new ThreadLocal<Stack<JavaScriptContext>>(() => new Stack<JavaScriptContext>());

    public void Enter(JavaScriptContext context)
    {
        if (context == null) throw new ArgumentNullException(nameof(context));

        var currentThreadContexts = _currentContexts.Value;
        if (currentThreadContexts.Contains(context))
        {
            _contextRefCount[context]++;
            return;
        }

        if (!_contextHandles.TryGetValue(context, out var handle))
        {
            handle = new AutoResetEvent(true);
            _contextHandles[context] = handle;
        }

        if (!handle.WaitOne())
        {
            throw new InvalidOperationException("Failed to acquire context lock.");
        }

        _contextRefCount[context] = 1;
        currentThreadContexts.Push(context);
    }

    public void Leave(JavaScriptContext context)
    {
        if (context == null) throw new ArgumentNullException(nameof(context));

        var currentThreadContexts = _currentContexts.Value;
        if (!currentThreadContexts.Contains(context))
        {
            throw new InvalidOperationException("Cannot leave a context that was not entered.");
        }

        _contextRefCount[context]--;
        if (_contextRefCount[context] == 0)
        {
            currentThreadContexts.Pop();
            _contextHandles[context].Set();
        }
    }

    public void With(JavaScriptContext context, Action action)
    {
        if (context == null) throw new ArgumentNullException(nameof(context));
        if (action == null) throw new ArgumentNullException(nameof(action));

        Enter(context);
        try
        {
            action();
        }
        finally
        {
            Leave(context);
        }
    }

    public T With<T>(JavaScriptContext context, Func<T> func)
    {

