using System;
using System.Runtime.InteropServices;
using Microsoft.VisualStudio.OLE.Interop;

public class ComEventSink<T> where T : class
{
    private IConnectionPointContainer connectionPointContainer;
    private IConnectionPoint connectionPoint;
    private int cookie;
    private bool isSubscribed;

    public ComEventSink(IConnectionPointContainer container)
    {
        if (container == null)
            throw new ArgumentNullException(nameof(container));

        this.connectionPointContainer = container;
    }

    public void Advise(T listener)
    {
        if (listener == null)
            throw new ArgumentNullException(nameof(listener));

        var listenerType = typeof(T);
        if (!listenerType.IsInterface)
            throw new ArgumentException("Listener must be an interface type.", nameof(listener));

        FindConnectionPoint(listenerType);
        AdviseSink(listener);
    }

    public void Unadvise()
    {
        if (!isSubscribed)
            return;

        try
        {
            connectionPoint.Unadvise(cookie);
            isSubscribed = false;
            cookie = 0;
        }
        catch (Exception ex)
        {
            throw new InvalidOperationException("Failed to unadvise the listener.", ex);
        }
    }

    private void FindConnectionPoint(Type listenerType)
    {
        Guid iid = listenerType.GUID;
        int hr = connectionPointContainer.FindConnectionPoint(ref iid, out connectionPoint);

        if (hr != 0)
            Marshal.ThrowExceptionForHR(hr);
    }

    private void AdviseSink(T listener)
    {
        int hr = connectionPoint.Advise(listener, out cookie);

        if (hr != 0)
            Marshal.ThrowExceptionForHR(hr);

        isSubscribed = true;
    }
}

public class ExampleUsage
{
    public void SetupComEventSink()
    {
        // Assuming comObject implements IConnectionPointContainer and exists in context
        IConnectionPointContainer comObject = GetComObject(); // Placeholder for actual COM object
        ComEventSink<IMyEventInterface> eventSink = new ComEventSink<IMyEventInterface>(comObject);

        MyEventListener listener = new MyEventListener();
        eventSink.Advise(listener);

        // Later in the process...
        eventSink.Unadvise();
    }

    private IConnectionPointContainer GetComObject()
    {
        // Implementation to retrieve a COM object implementing IConnectionPointContainer
        throw new NotImplementedException();
    }
}

