    // Base class for all setting mappings.
    public class BaseSettingMapping
    {
        protected PrinterConfiguration printerConfig;
        protected string canonicalName;
        protected string exportedName;

        public BaseSettingMapping(PrinterConfiguration printerConfig, string canonicalName, string exportedName)
        {
            this.printerConfig = printerConfig;
            this.canonicalName = canonicalName;
            this.exportedName = exportedName;
        }

        // Virtual property representing the setting's current value.
        public virtual double Value
        {
            get
            {
                return GetDefaultFanSpeed();
            }
        }

        // Default implementation returning a preset fan speed (e.g., 100%).
        protected double GetDefaultFanSpeed()
        {
            return 100;
        }
    }

    // Specialized mapping class for handling fan speed configuration.
    public class FanSpeedSettingMapping : BaseSettingMapping
    {
        // Configuration key for determining if the fan is enabled.
        private const string EnableFanKey = "EnableFan";

        public FanSpeedSettingMapping(PrinterConfiguration printerConfig, string canonicalName, string exportedName)
            : base(printerConfig, canonicalName, exportedName)
        {
        }

        // Overridden getter that returns the effective fan speed based on the printer configuration.
        public override double Value
        {
            get
            {
                bool isFanEnabled = printerConfig.GetSetting<bool>(EnableFanKey, false);

                // If the fan is enabled, return the base fan speed; if not, force it to zero.
                if (isFanEnabled)
                {
                    return base.Value;
                }
                else
                {
                    return 0;
                }
            }
        }
    }

