        public Guid ContainerKey { get; set; }
        public Guid LineItemTfKey { get; set; }

        public string Sku { get; set; }
        public string Name { get; set; }

        public int Quantity { get; set; }
        public decimal Price { get; set; }
        public bool Exported { get; set; }

        [JsonConverter(typeof(Newtonsoft.Json.Converters.StringEnumConverter))]
        public LineItemType LineItemType { get; set; }

        public List<ExtendedDataAttribute> ExtendedData { get; set; }

        protected LineItemDisplayBase()
        {
            Key = Guid.NewGuid();
            ExtendedData = new List<ExtendedDataAttribute>();
        }

        public abstract void AddExtendedData(string key, string value);
        public abstract void RemoveExtendedData(string key);

        public virtual decimal GetTotalPrice()
        {
            return Quantity * Price;
        }
    }

    public enum LineItemType
    {
        Product,
        Service,
        Discount,
        Tax,
        Shipping
    }

    public class ExtendedDataAttribute
    {
        public string Key { get; set; }
        public string Value { get; set; }

        public ExtendedDataAttribute(string key, string value)
        {
            Key = key;
            Value = value;
        }
    }

    public class ProductLineItem : LineItemDisplayBase
    {
        public override void AddExtendedData(string key, string value)
        {
            var existingData = ExtendedData.Find(data => data.Key == key);
            if (existingData != null)
            {
                existingData.Value = value;
            }
            else
            {
                ExtendedData.Add(new ExtendedDataAttribute(key, value));
            }
        }

        public override void RemoveExtendedData(string key)
        {
            ExtendedData.RemoveAll(data => data.Key == key);
        }
    }

    public class ServiceLineItem : LineItemDisplayBase
    {
        public override void AddExtendedData(string key, string value)
        {
            var existingData = ExtendedData.Find(data => data.Key == key);
            if (existingData != null)
            {
                existingData.Value = value;
            }
            else
            {
                ExtendedData.Add(new ExtendedDataAttribute(key, value));
            }
        }

