            // Assert
            Assert.NotSame(question, result);
            Assert.Equal(question.Name, result.Name);
            Assert.Equal(question.ClassName, result.ClassName);
            Assert.Equal(question.QuestionCategoryId, result.QuestionCategoryId);
        }

