namespace SqlCommandProfiler
{
    public class CommandStatisticsManager
    {
        private readonly Dictionary<string, CommandStatistics> _commandStatistics;
        private readonly ILogger _logger;

        public CommandStatisticsManager(ILogger logger)
        {
            _commandStatistics = new Dictionary<string, CommandStatistics>();
            _logger = logger;
        }

        public void SetCommandStatistics(Command command)
        {
            if (command == null) throw new ArgumentNullException(nameof(command));

            try
            {
                string normalizedHash = GetNormalizedSqlHash(command.Sql);
                if (_commandStatistics.TryGetValue(normalizedHash, out var existingStats))
                {
                    command.Statistics = existingStats;
                }
                else
                {
                    var newStats = RunAnalysis(command);
                    _commandStatistics[normalizedHash] = newStats;
                    command.Statistics = newStats;
                }
                command.NormalizedSqlHash = normalizedHash;
            }
            catch (Exception ex)
            {
                _logger.LogError("Error setting command statistics", ex);
            }
        }

        private CommandStatistics RunAnalysis(Command command)
        {
            // Simulate performance analysis by calculating dummy statistics
            var statistics = new CommandStatistics
            {
                ExecutionTime = MeasureExecutionTime(command),
                RowCount = GetRowCount(command),
                CommandText = command.Sql
            };

            return statistics;
        }

        private long MeasureExecutionTime(Command command)
        {
            // Implementing a simple measure logic (placeholder)
            return new Random().Next(1, 100); // Simulated execution time
        }

        private int GetRowCount(Command command)
        {
            // Simulating row count logic (placeholder)
            return new Random().Next(1, 500); // Simulated row count
        }

        private string GetNormalizedSqlHash(string sql)
        {
            // Normalize SQL command to create a consistent hash
            string normalizedSql = sql.ToLowerInvariant().Trim(); // Simplified normalization
            return normalizedSql.GetHashCode().ToString();
        }
    }

