public class Graph
{
    public static void Main()
    {
        var tests = new[] { "", "   ", "2", "333", ".55", "tttTTT", "4444 444k", "pépé", "🐶🐶🐺🐶", "🎄🎄🎄🎄" };
 
        foreach (var test in tests)
        {
            TestString(test);
        }
    }
 
    private static void TestString(string input)
    {
        Console.WriteLine($"Checking string {input} of length {input.Length}:");
 
        var chars = input.ToCharArray();
 
        var first = chars.FirstOrDefault();
 
        if (first!= default(char))
        {
            var character = chars.Skip(1).Select((c, i) => new { c, i }).FirstOrDefault(x => x.c!= first);
 
            if (character!= null)
            {
                Console.WriteLine("\tNot all characters are the same.");
                Console.WriteLine($"\t{character.c} (0x{(int)character.c:X}) at position {character.i + 1} differs.");
 
                return;
            }
        }
 
        Console.WriteLine("\tAll characters in the string are the same");
    }
}

