namespace MobileBackendTests
{
    public class TableControllerCacheTests
    {
        private HttpClient client;

        public TableControllerCacheTests()
        {
            var server = CreateTestServer();
            client = server.HttpClient;
        }

        private TestServer CreateTestServer()
        {
            return TestServer.Create(appBuilder =>
            {
                HttpConfiguration config = new HttpConfiguration();
                config.MapHttpAttributeRoutes();
                config.Routes.MapHttpRoute(
                    name: "DefaultApi",
                    routeTemplate: "api/{controller}/{id}",
                    defaults: new { id = RouteParameter.Optional }
                );

                new MobileAppConfiguration()
                    .AddTables()
                    .ApplyTo(config);

                appBuilder.UseWebApi(config);
            });
        }

        [Fact]
        public async Task TableController_AttributeRoute_AddsCacheHeaders()
        {
            var response = await client.GetAsync("/api/TodoItem");
            await VerifyResponse(response);
        }

        [Fact]
        public async Task TableController_RouteTable_AddsCacheHeaders()
        {
            var response = await client.GetAsync("/api/AnotherTable");
            await VerifyResponse(response);
        }

        private async Task VerifyResponse(HttpResponseMessage response)
        {
            Assert.Equal(HttpStatusCode.OK, response.StatusCode);
            var cacheControlHeader = response.Headers.CacheControl;
            Assert.NotNull(cacheControlHeader);
            Assert.True(cacheControlHeader.NoCache);
            Assert.False(cacheControlHeader.NoStore);
            Assert.False(cacheControlHeader.MustRevalidate);
            Assert.False(cacheControlHeader.ProxyRevalidate);
            Assert.Null(cacheControlHeader.MaxAge);
            Assert.Null(cacheControlHeader.SharedMaxAge);
            Assert.Empty(cacheControlHeader.NoCacheHeaders);
        }
    }

