    internal class OperatorSymbolReferenceFinder : AbstractReferenceFinder<IMethodSymbol>
    {
        public override async Task<ImmutableArray<Document>> DetermineDocumentsToSearchAsync(
            IMethodSymbol methodSymbol, Project project, CancellationToken cancellationToken)
        {
            // Only process user-defined operators
            if (!CanFind(methodSymbol))
            {
                return ImmutableArray<Document>.Empty;
            }

            // Get the operator type for further search narrowing
            var op = GetPredefinedOperator(methodSymbol);
            // In a real scenario, language services would be used here to narrow documents.
            // For demonstration, assume all project documents must be searched.
            return project.Documents.ToImmutableArray();
        }

        public override async Task<ImmutableArray<Location>> FindReferencesInDocumentAsync(
            IMethodSymbol methodSymbol, Document document, CancellationToken cancellationToken)
        {
            var locations = ImmutableArray.CreateBuilder<Location>();
            var op = GetPredefinedOperator(methodSymbol);

            var syntaxRoot = await document.GetSyntaxRootAsync(cancellationToken).ConfigureAwait(false);
            if (syntaxRoot == null)
            {
                return locations.ToImmutable();
            }

            // Examine tokens in the document's syntax tree
            foreach (var token in syntaxRoot.DescendantTokens())
            {
                if (IsPotentialReference(token, op))
                {
                    locations.Add(token.GetLocation());
                }
            }

            return locations.ToImmutable();
        }

        // Checks if the method symbol is a user-defined operator.
