            m_Controller = (byte)(liData & 63);
            m_PLCI = (byte)((liData >> 8) & 0xff);
        }
        public override uint GetValue()
        {
            return (uint)m_ControllerType + (uint)m_Controller + (uint)(m_PLCI << 8);
        }
    }
