namespace FileSystemExplorer
{
    public class UserDirectoryInfo
    {
        public string UserName { get; set; }
        public string SubPath { get; set; }
        public IEnumerable<RemoteFileInfo> Files { get; set; }
        public IEnumerable<DirectoryShortInfo> SubDirectories { get; set; }
        private DirectoryInfo directoryInfo;

        // Parameterless constructor for deserialization
        public UserDirectoryInfo()
        {
            UserName = string.Empty;
            SubPath = string.Empty;
            Files = Enumerable.Empty<RemoteFileInfo>();
            SubDirectories = Enumerable.Empty<DirectoryShortInfo>();
        }

        // Parameterized constructor
        public UserDirectoryInfo(string repositoryPath, string userName, string subPath = "")
        {
            if (string.IsNullOrWhiteSpace(userName) || !ValidationHelper.IsValidUserName(userName))
            {
                throw new ArgumentException("Invalid user name provided.", nameof(userName));
            }

            UserName = userName;
            SubPath = subPath;

            // Build the full directory path using Path.Combine which handles invalid path characters
            string fullPath = string.IsNullOrWhiteSpace(subPath)
                ? Path.Combine(repositoryPath, userName)
                : Path.Combine(repositoryPath, userName, subPath);

            if (!Directory.Exists(fullPath))
            {
                Files = Enumerable.Empty<RemoteFileInfo>();
                SubDirectories = Enumerable.Empty<DirectoryShortInfo>();
                return;
            }

            directoryInfo = new DirectoryInfo(fullPath);

            // Get files in the directory and project to RemoteFileInfo
            Files = directoryInfo.GetFiles()
                    .Select(f => new RemoteFileInfo
                    {
                        FileName = f.Name,
                        Size = f.Length,
                        CreationTime = f.CreationTime,
                        LastModified = f.LastWriteTime
                    }).ToList();

            // Get subdirectories and project to DirectoryShortInfo
            SubDirectories = directoryInfo.GetDirectories()
                    .Select(d => new DirectoryShortInfo
                    {
                        DirectoryName = d.Name,
                        LastModified = d.LastWriteTime
                    }).ToList();
        }
    }

