namespace Processor
{
    class Solution
    {
        static void Main(string[] args)
        {
            int i, prime, count = 0, index = 0, primeCount, longCount = 0, numberCount;
            int[] primes, longPrimes, totals;
            int[] numbers = { 500, 1000, 2000, 4000, 8000, 16000, 32000, 64000 };
 
            primes = new int[6500];
            numberCount = numbers.Length;
            totals = new int[numberCount];
            sieve(64000, primes, out primeCount);
            longPrimes = new int[primeCount];
            /* Surely longCount < primeCount */
            for (i = 0; i < primeCount; ++i)
            {
                prime = primes[i];
                if (findPeriod(prime) == prime - 1)
                {
                    longPrimes[longCount++] = prime;
                }
            }
            for (i = 0; i < longCount; ++i, ++count)
            {
                if (longPrimes[i] > numbers[index])
                {
                    totals[index++] = count;
                }
            }
            totals[numberCount - 1] = count;
            Console.WriteLine("The long primes up to {0} are:", numbers[0]);
            Console.Write("[");
            for (i = 0; i < totals[0]; ++i)
            {
                Console.Write("{0} ", longPrimes[i]);
            }
            Console.WriteLine("\b]");
 
            Console.WriteLine("\nThe number of long primes up to:");
            for (i = 0; i < 8; ++i)
            {
                Console.WriteLine("  {0,5} is {1}", numbers[i], totals[i]);
            }
            Console.ReadLine();
        }
 
        static void sieve(int limit, int[] primes, out int count)
        {
            bool[] c = new bool[limit + 1]; /* composite = TRUE */
            /* no need to process even numbers */
            int i, p = 3, p2, n = 0;
            p2 = p * p;
            while (p2 <= limit)
            {
                for (i = p2; i <= limit; i += 2 * p)
                    c[i] = true;
                do
                {
                    p += 2;
                } while (c[p]);
                p2 = p * p;
            }
            for (i = 3; i <= limit; i += 2)
            {
                if (!c[i]) primes[n++] = i;
            }
            count = n;
        }
 
        /* finds the period of the reciprocal of n */
        static int findPeriod(int n)
        {
            int i, r = 1, rr, period = 0;
            for (i = 1; i <= n + 1; ++i)

