public class UCViewData : UserControl
{
    private bool _showInHexadecimal = true;
    private byte[] _lastData;
    private int _lastIdx;

    public UCViewData()
    {
        InitializeComponent();
    }

    [Category("Behavior")]
    [Description("Determines whether values are displayed in hexadecimal format.")]
    public bool ShowInHexadecimal
    {
        get { return _showInHexadecimal; }
        set
        {
            _showInHexadecimal = value;
            if (_lastData != null && _lastIdx >= 0)
            {
                ShowValues(_lastData, _lastIdx);
            }
        }
    }

    public void ShowValues(byte[] data, int idx)
    {
        if (data == null || idx < 0 || idx >= data.Length)
        {
            Text = "Invalid Index";
            return;
        }

        _lastData = data;
        _lastIdx = idx;

        if (_showInHexadecimal)
        {
            Text = $"Byte: 0x{data[idx]:X2}";
            if (idx + 1 < data.Length)
                Text += $"\nInt16: 0x{BitConverter.ToInt16(data, idx):X4}";
            if (idx + 3 < data.Length)
                Text += $"\nInt32: 0x{BitConverter.ToInt32(data, idx):X8}";
            if (idx + 7 < data.Length)
                Text += $"\nInt64: 0x{BitConverter.ToInt64(data, idx):X16}";
        }
        else
        {
            Text = $"Byte: {data[idx]}";
            if (idx + 1 < data.Length)
                Text += $"\nInt16: {BitConverter.ToInt16(data, idx)}";
            if (idx + 3 < data.Length)
                Text += $"\nInt32: {BitConverter.ToInt32(data, idx)}";
            if (idx + 7 < data.Length)
                Text += $"\nInt64: {BitConverter.ToInt64(data, idx)}";
        }
    }

    private void InitializeComponent()
    {
        this.SuspendLayout();
        this.AutoSize = true;
        this.AutoSizeMode = AutoSizeMode.GrowAndShrink;
        this.ResumeLayout(false);
    }
}

using System;
 
namespace rref
{
    class Solution
    {
        static void Main(string[] args)
        {
            int[,] matrix = new int[3, 4]{
                {  1, 2, -1,  -4 },
                {  2, 3, -1, -11 },
                { -2, 0, -3,  22 }
            };
            matrix = rref(matrix);
        }
 
        private static int[,] rref(int[,] matrix)
        {
            int lead = 0, rowCount = matrix.GetLength(0), columnCount = matrix.GetLength(1);
            for (int r = 0; r < rowCount; r++)
            {
                if (columnCount <= lead) break;
                int i = r;
                while (matrix[i, lead] == 0)
                {
                    i++;
                    if (i == rowCount)
                    {
                        i = r;
                        lead++;
                        if (columnCount == lead)
                        {
                        lead--;
                        break;
                        }
                    }
                }
                for (int j = 0; j < columnCount; j++)
                {
                    int temp = matrix[r, j];
                    matrix[r, j] = matrix[i, j];
                    matrix[i, j] = temp;
                }
                int div = matrix[r, lead];
                if(div != 0)
                    for (int j = 0; j < columnCount; j++) matrix[r, j] /= div;
                for (int j = 0; j < rowCount; j++)
                {
                    if (j != r)
                    {
                        int sub = matrix[j, lead];
                        for (int k = 0; k < columnCount; k++) matrix[j, k] -= (sub * matrix[r, k]);
                    }
                }
                lead++;
            }
            return matrix;
        }
    }
}

