namespace CpsDbHelper.Extensions
{
    public static class DataReaderExtension
    {
        /// <summary>
        /// Check if the returned reader contains specific column
        /// </summary>
        /// <param name="reader"></param>
        /// <param name="columnName">the column name</param>
        /// <returns></returns>
        public static bool ContainsColumn(this IDataReader reader, string columnName)
        {
            for (var i = 0; i < reader.FieldCount; i++)
            {
                if (reader.GetName(i).Equals(columnName, StringComparison.OrdinalIgnoreCase))
                {
                    return true;
                }
            }
            return false;
        }

        /// <summary>
        /// Get value from specific reader column by column name
        /// </summary>
        /// <typeparam name="T">The return type</typeparam>
        /// <param name="reader"></param>
        /// <param name="columnName">column name</param>
        /// <returns></returns>
        public static T Get<T>(this IDataReader reader, string columnName)
        {
            if (reader.ContainsColumn(columnName))
            {
                var ordinal = reader.GetOrdinal(columnName);
                if (!reader.IsDBNull(ordinal))
                {
                    return (T)reader.GetValue(ordinal);
                }
            }
            return default(T);
        }

        /// <summary>
        /// Get value from specific reader column by column ordinal
        /// </summary>
        /// <typeparam name="T">The return type</typeparam>
        /// <param name="reader"></param>
        /// <param name="ordinal">column index</param>
        /// <returns></returns>
        public static T Get<T>(this IDataReader reader, int ordinal)
        {
            return (T)reader.GetValue(ordinal);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

public interface IHeap
{
    long ObtainHandle();
    void Release(long handle);
    bool Exists(long handle);
    void Write(long handle, byte[] data, long version);
    byte[] Read(long handle, long version);
    long GetLatest(long handle);
    long GetUsedSpace();
    void Commit();
    void Close();
}

public class VersionedBlockStorage : IHeap
{
    private struct Ptr
    {
        public byte[] Data;
        public long Version;
        public bool IsValid;
    }

    private Dictionary<long, List<Ptr>> _storage;
    private long _currentVersion;
    private long _nextHandle;

    public VersionedBlockStorage()
    {
        _storage = new Dictionary<long, List<Ptr>>();
        _currentVersion = 1;
        _nextHandle = 1;
    }

    public long ObtainHandle()
    {
        return _nextHandle++;
    }

    public void Release(long handle)
    {
        if (_storage.ContainsKey(handle))
        {
            _storage[handle].Clear();
            _storage.Remove(handle);
        }
    }

    public bool Exists(long handle)
    {
        return _storage.ContainsKey(handle) && _storage[handle].Any(p => p.IsValid);
    }

    public void Write(long handle, byte[] data, long version)
    {
        if (!_storage.ContainsKey(handle))
        {
            _storage[handle] = new List<Ptr>();
        }

        _storage[handle].Add(new Ptr
        {
            Data = data,
            Version = version,
            IsValid = true
        });
    }

    public byte[] Read(long handle, long version)
    {
        if (!_storage.ContainsKey(handle))
        {
            return null;
        }

        var matchingBlocks = _storage[handle]
            .Where(p => p.IsValid && p.Version <= version)
            .OrderByDescending(p => p.Version)
            .ToList();

        return matchingBlocks.Any() ? matchingBlocks.First().Data : null;
    }

    public long GetLatest(long handle)
    {
        return _storage.ContainsKey(handle)
            ? _storage[handle].Max(p => p.Version)
            : -1;
    }

    public long GetUsedSpace()
    {
        return _storage.Sum(entry => entry.Value.Sum(ptr => ptr.Data?.Length ?? 0));
    }

    public void Commit()
    {
        _currentVersion++;
    }

    public void Close()
    {
        _storage.Clear();
        _currentVersion = 1;
        _nextHandle = 1;
    }
}

using System;
