using Be.Stateless.BizTalk.Component;
using Be.Stateless.BizTalk.Dsl.Pipeline;
using Microsoft.BizTalk.Component;

namespace BizTalk.Pipelines
{
    [SuppressMessage("ReSharper", "UnusedMember.Global")]
    public class XmlReceive : ReceivePipeline
    {
        public XmlReceive()
        {
            Description = "Custom XML Receive Pipeline with Decode, Disassemble, and ResolveParty stages.";
            Version = new Version(1, 0, 0, 0);
            PipelineGuid = new Guid("A1B2C3D4-E5F6-G7H8-I9J0-K1L2M3N4O5P6");

            Stages.Decode.Add(new FailedMessageRoutingEnablerComponent
            {
                Enabled = false
            });

            Stages.Decode.Add(new XmlTransmit
            {
                Enabled = false
            });

            Stages.Decode.Add(new PassThruTransmit
            {
                Enabled = false
            });

            Stages.Decode.Add(new XmlReceive
            {
                Enabled = false
            });

            Stages.Decode.Add(new PassThruReceive
            {
                Enabled = true
            });

            Stages.Disassemble.Add(new XmlDisassembler
            {
                DocumentSpecNames = new[] { "Your.Document.Spec.Name, Your.Assembly.Name" },
                EnablePerformanceCounters = true
            });

            Stages.ResolveParty.Add(new ContextPropertyExtractorComponent
            {
                Enabled = true
            });

            Stages.ResolveParty.Add(new Policy
            {
                PolicyName = "YourPolicyName",
                Enabled = true
            });

            Stages.ResolveParty.Add(new BAMActivityTrackingComponent
            {
                Enabled = true,
                ActivityName = "YourActivityName"
            });

            Stages.ResolveParty.Add(new XsltTransform
            {
                Enabled = true,
                XsltPath = "YourXsltPath.xslt"
            });
        }
    }
}

