namespace SubtractiveGenerator
{
    class Service
    {
        static void Main(string[] args)
        {
            var gen = GetSeededXpat2Gen(292929);
 
            foreach (var n in gen.Take(5))
            {
                Console.WriteLine(n);
            }
        }
 
        static SubtractiveGenerator GetSeededXpat2Gen(int seed)
        {
            var gen = new SubtractiveGenerator(1_000_000_000, 55, 24);
 
            var stateSize = gen.Offsets.Item1;
 
            var preState = new List<int>();
            preState.Add(seed);
            preState.Add(1);
            for (var i = 2; i < stateSize; i++)
            {
                preState.Add((preState[i - 2] - preState[i - 1]) % gen.Modulo);
            }
 
            for (var i = 0; i < stateSize; i++)
            {
                gen.State.Add(preState[(34 * (i + 1)) % 55]);
            }
 
            gen.Position = 54;
            for (var i = 0; i < 165; i++)
            {
                gen.Next();
            }
 
            return gen;
        }
    }
 
    class SubtractiveGenerator
    {
        public int Modulo { get; }
        public Tuple<uint, uint> Offsets { get; }
        public List<int> State { get; }
        public int Position { get; set; }
 
        public SubtractiveGenerator(int modulo, uint firstOffset, uint secondOffset)
        {
            // The state size has to fit into a usize to index state properly
            // without overflow.
            var stateSize = firstOffset;
 
            // Both offsets have to fit in i32 for the substractions to work
            // without overflow.
            if (firstOffset > int.MaxValue)
            {
                throw new Exception("firstOffset is too big");
            }
 
            if (firstOffset <= secondOffset)
            {
                throw new Exception("firstOffset is not bigger than secondOffset");
            }
 
            Modulo = modulo;
            Offsets = new Tuple<uint, uint>(firstOffset, secondOffset);
            State = new List<int>();
            Position = 0;
        }
 
        public int Next()
        {
            var stateSize = Offsets.Item1;
 
            if (State.Count!= stateSize)
            {
                throw new Exception("State size is not correct");
            }
 
            Position = (Position + 1) % Offsets.Item1;
 
            var i1 = (Position - Offsets.Item1) % stateSize;
            var i2 = (Position - Offsets.Item2) % stateSize;
 
            var p1 = State[i1];

