    // Simple data model
    public class Project
    {
        public ObjectId Id { get; set; }
        public string Name { get; set; }
    }

    // Repository abstraction for MongoDB operations
    public interface IRepository<T>
    {
        Task InsertOneAsync(T item);
        Task<long> DeleteManyAsync(Expression<Func<T, bool>> predicate);
        Task<long> DeleteManyAsync(FilterDefinition<T> filter);
        Task<List<T>> FindAllAsync();
    }

    // MongoDB repository implementation
    public class ProjectRepository : IRepository<Project>
    {
        private readonly IMongoCollection<Project> _collection;

        public ProjectRepository(string connectionString, string dbName, string collectionName)
        {
            var client = new MongoClient(connectionString);
            var database = client.GetDatabase(dbName);
            _collection = database.GetCollection<Project>(collectionName);
        }

        public async Task InsertOneAsync(Project item)
        {
            await _collection.InsertOneAsync(item);
        }

        public async Task<long> DeleteManyAsync(Expression<Func<Project, bool>> predicate)
        {
            var result = await _collection.DeleteManyAsync(predicate);
            return result.DeletedCount;
        }

        public async Task<long> DeleteManyAsync(FilterDefinition<Project> filter)
        {
            var result = await _collection.DeleteManyAsync(filter);
            return result.DeletedCount;
        }

        public async Task<List<Project>> FindAllAsync()
        {
            return await _collection.Find(Builders<Project>.Filter.Empty).ToListAsync();
        }
    }

