using System;
 
public class Shape
{
    public static void Main()
    {
        int[] a = new int[20000];
        for (int i = 1; i < 20000; i++)
        {
            a[i] = pfacSum(i);
        }
        Console.WriteLine("The amicable pairs below 20,000 are:");
        for (int n = 2; n < 19999; n++)
        {
            int m = a[n];
            if (m > n && m < 20000 && n == a[m])
            {
                Console.WriteLine("  {0,5} and {1,5}", n, m);
            }
        }
    }
 
    public static int pfacSum(int i)
    {
        int sum = 0;
        for (int p = 1; p <= i / 2; p++)
        {
            if (i % p == 0)
            {
                sum += p;
            }
        }
        return sum;
    }
}

using System;
using System.Data.SQLite;
 
namespace SQLiteTest
{
    class Account
    {
        static void Main(string[] args)
        {
            SQLiteConnection db = new SQLiteConnection("Data Source=:memory:");
            db.Open();
 
            // setup
            db.ExecuteNonQuery("create temp table players (name, score, active, jerseyNum)");
            db.ExecuteNonQuery("insert into players values ('name',0,'false',99)");
            db.ExecuteNonQuery("insert into players values ('name',0,'false',100)");
 
            // demonstrate parameterized SQL
 
            // example 1 -- simple placeholders
            db.ExecuteNonQuery("update players set name=?, score=?, active=? where jerseyNum=?",
                "", 42, true, 99);
 
            // example 2 -- named placeholders
            db.ExecuteNonQuery("update players set name=:name, score=:score, active=:active where jerseyNum=:num",
                new { num = 100, name = "", active = false, score = -1 });
 
            // and show the results
            foreach (var row in db.Query("select * from players"))
            {
                Console.WriteLine(row);
            }
        }
    }
}

