    {
        IFluentPropertyMapping HasKey();
        IFluentPropertyMapping IsIdentity();
        IFluentPropertyMapping HasDatabaseGeneratedOption(DatabaseGeneratedOption option);
    }

    // Base class providing foundational mapping functionality.
    public abstract class PropertyMappingBase
    {
        protected PropertyInfo Property { get; private set; }

        protected PropertyMappingBase(PropertyInfo property)
        {
            Property = property;
        }

        // This method can be used to retrieve the configured mapping details.
        public abstract void ApplyMapping(PropertyMap propertyMap);
    }

