    {
        private bool _isKey;
        private bool _isIdentity;
        private DatabaseGeneratedOption? _databaseGeneratedOption;

        public FluentPropertyMapping(PropertyInfo property)
            : base(property)
        {
            _isKey = false;
            _isIdentity = false;
            _databaseGeneratedOption = null;
        }

        // Marks the property as a primary key.
        public IFluentPropertyMapping HasKey()
        {
            _isKey = true;
            return this;
        }

        // Marks the property as an identity (auto-increment) column.
        public IFluentPropertyMapping IsIdentity()
        {
            _isIdentity = true;
            return this;
        }

        // Sets the database generation option for the property.
        public IFluentPropertyMapping HasDatabaseGeneratedOption(DatabaseGeneratedOption option)
        {
            _databaseGeneratedOption = option;
            return this;
        }

        // Applies the mapping configuration to the given PropertyMap.
        public override void ApplyMapping(PropertyMap propertyMap)
        {
            if (_isKey)
