public class GPhotoException : Exception
{
    private readonly ErrorCode error;

    public ErrorCode Error => error;

    public GPhotoException(ErrorCode errorCode) : base()
    {
        error = errorCode;
    }

    public GPhotoException(ErrorCode errorCode, string message) : base(message)
    {
        error = errorCode;
    }

    public override string ToString()
    {
        return $"GPhotoException: ErrorCode={error}, Message={Message}";
    }
}

