using Reni;

namespace AutoCompleteTest
{
    [UnitTest]
    public sealed class AutoComplete
    {
        [UnitTest]
        public void DeclarationOptions()
        {
            const string text = @"
type Array16: Array(16, UInt1)

define array16_0: Array16()
define array16_1: Array16(1)

define f: dump_print(""Hallo"")
define f1: dump_print(""Hallo"")

define creator(count):
(
  define result: Array(count, UInt1);
  result
)

define result10: creator(10);
define result11: creator(11);
";
            var compiler = CompilerBrowser.FromText(text);

            for(var offset = 0; offset < text.Length; offset++)
            {
                if(offset + 1 < text.Length && text[offset] == '\r' && text[offset + 1] == '\n')
                    continue;

                var position = new SourcePosition(compiler.Source, offset);
                var items = compiler.GetDeclarationOptions(position).ToArray();
                Tracer.Assert(items != null);
            }
        }
    }
}

