public abstract class SocksHandler : IDisposable
{
    protected Socket LocalSocket { get; private set; }
    protected Socket RemoteSocket { get; private set; }
    protected IPEndPoint BindEndPoint { get; private set; }
    protected byte[] Buffer { get; private set; }
    protected EndPoint EndPoint { get; private set; }
    protected string Username { get; private set; }
    protected Socket AcceptSocket { get; private set; }
    private Thread requestThread;
    private bool disposed = false;

    public delegate void HandshakeCallback(bool success, Socket remoteSocket);

    protected SocksHandler(Socket localSocket, HandshakeCallback callback)
    {
        LocalSocket = localSocket;
        Buffer = new byte[1024];
        requestThread = new Thread(RequestThread);
        requestThread.Start(callback);
    }

    protected abstract void OnAccept();
    protected abstract void ProcessRequest();
    protected abstract void SendResponse();

    private void RequestThread(object callback)
    {
        HandshakeCallback handshakeCallback = (HandshakeCallback)callback;
        try
        {
            OnAccept();
            ProcessRequest();
            SendResponse();
            handshakeCallback(true, RemoteSocket);
        }
        catch (Exception)
        {
            handshakeCallback(false, null);
        }
        finally
        {
            Dispose();
        }
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    protected virtual void Dispose(bool disposing)
    {
        if (!disposed)
        {
            if (disposing)
            {
                LocalSocket?.Close();
                RemoteSocket?.Close();
                AcceptSocket?.Close();
            }
            disposed = true;
        }
    }

    protected void BeginRequestData()
    {
        if (LocalSocket != null && LocalSocket.Connected)
        {
            EndPoint = LocalSocket.RemoteEndPoint;
            int bytesRead = LocalSocket.Receive(Buffer);
            if (bytesRead > 0)
            {
                // Process the received data
            }
        }
    }
}

