public partial class VerifyPhoneNumber : Page
{
    protected HiddenField PhoneNumber;
    protected TextBox Code;
    protected Literal ErrorMessage;

    protected void Page_Load(object sender, EventArgs e)
    {
        if (!IsPostBack)
        {
            string number = Request.QueryString["PhoneNumber"];
            if (string.IsNullOrEmpty(number))
            {
                Response.Redirect("~/Error/InvalidRequest");
                return;
            }

            PhoneNumber.Value = number;
            string userId = User.Identity.GetUserId();
            string token = UserManager.GenerateChangePhoneNumberToken(userId, number);
            // Send token via SMS implementation would go here
        }
    }

    protected void Code_Click(object sender, EventArgs e)
    {
        if (!string.IsNullOrEmpty(Code.Text))
        {
            string code = Code.Text.Trim();
            string userId = User.Identity.GetUserId();

            try
            {
                var result = UserManager.ChangePhoneNumber(userId, PhoneNumber.Value, code);
                if (result.Succeeded)
                {
                    var user = UserManager.FindById(userId);
                    user.PhoneNumberConfirmed = true;
                    UserManager.Update(user);

                    SignInManager.SignIn(user, false, false);
                    Response.Redirect("~/Account/Manage?m=PhoneVerifySuccess");
                }
                else
                {
                    ErrorMessage.Text = "Invalid verification code";
                }
            }
            catch (Exception ex)
            {
                ErrorMessage.Text = $"Verification failed: {ex.Message}";
            }
        }
        else
        {
            ErrorMessage.Text = "Please enter verification code";
        }
    }

    private ApplicationUserManager _userManager;
    public ApplicationUserManager UserManager
    {
        get => _userManager ?? HttpContext.Current.GetOwinContext().GetUserManager<ApplicationUserManager>();
        private set => _userManager = value;
    }

    private ApplicationSignInManager _signInManager;
    public ApplicationSignInManager SignInManager
    {
        get => _signInManager ?? HttpContext.Current.GetOwinContext().Get<ApplicationSignInManager>();
        private set => _signInManager = value;
    }
}

