using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;
using PartsUnlimited.Models;

namespace PartsUnlimited.Data
{
    public class PartsUnlimitedContext : IdentityDbContext<ApplicationUser>, IPartsUnlimitedContext
    {
        private readonly string _connectionString;

        public DbSet<Product> Products { get; set; }
        public DbSet<Order> Orders { get; set; }
        public DbSet<Category> Categories { get; set; }
        public DbSet<CartItem> CartItems { get; set; }
        public DbSet<OrderDetail> OrderDetails { get; set; }
        public DbSet<Raincheck> Rainchecks { get; set; }
        public DbSet<Store> Stores { get; set; }

        public PartsUnlimitedContext(DbContextOptions<PartsUnlimitedContext> options, string connectionString = null)
            : base(options)
        {
            _connectionString = connectionString;
        }

        protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
        {
            if (!optionsBuilder.IsConfigured)
            {
                if (!string.IsNullOrEmpty(_connectionString))
                {
                    optionsBuilder.UseSqlServer(_connectionString);
                }
                else
                {
                    optionsBuilder.UseInMemoryDatabase("PartsUnlimited");
                }
            }
        }

        protected override void OnModelCreating(ModelBuilder builder)
        {
            base.OnModelCreating(builder);

            builder.Entity<Product>().HasKey(p => p.ProductId);
            builder.Entity<Order>().HasKey(o => o.OrderId);
            builder.Entity<Category>().HasKey(c => c.CategoryId);
            builder.Entity<CartItem>().HasKey(ci => ci.CartItemId);
            builder.Entity<OrderDetail>().HasKey(od => od.OrderDetailId);
            builder.Entity<Raincheck>().HasKey(r => r.RaincheckId);
            builder.Entity<Store>().HasKey(s => s.StoreId);

            // Ignore properties not intended for database storage
            builder.Entity<Product>().Ignore(p => p.ImageUrl);
            builder.Entity<Product>().Ignore(p => p.ThumbnailUrl);
        }
    }

    public interface IPartsUnlimitedContext
    {
        DbSet<Product> Products { get; set; }
        DbSet<Order> Orders { get; set; }
        DbSet<Category> Categories { get; set; }
        DbSet<CartItem> CartItems { get; set; }
        DbSet<OrderDetail> OrderDetails { get; set; }
        DbSet<Raincheck> Rainchecks { get; set; }
        DbSet<Store> Stores { get; set; }
    }
}

