using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.NodeServices;
using Microsoft.AspNetCore.SpaServices.Prerendering;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.AspNetCore.Hosting;

public static class HttpRequestExtensions
{
    public static AbstractRequestInfo GetAbstractRequestInfo(this HttpRequest request)
    {
        return new AbstractRequestInfo
        {
            Cookies = request.Cookies.ToDictionary(k => k.Key, v => v.Value),
            Headers = request.Headers.ToDictionary(k => k.Key, v => v.Value.ToString()),
            Host = $"{request.Scheme}://{request.Host}"
        };
    }

    public static async Task<RenderToStringResult> BuildPrerender(
        this HttpRequest request,
        INodeServices nodeServices,
        IHostingEnvironment env,
        TransferData transferData)
    {
        var applicationPath = env.ContentRootPath;
        var moduleExport = new JavaScriptModuleExport(applicationPath + "/ClientApp/dist/main-server");

        var prerenderResult = await nodeServices.RenderToString(
            new NodeInvocationOptions
            {
                HttpContext = request.HttpContext,
                CancelAfterTimeout = TimeSpan.FromSeconds(30),
                Timeout = TimeSpan.FromSeconds(30)
            },
            moduleExport.ModuleName,
            moduleExport.ExportName,
            new
            {
                location = request.Path.ToString(),
                request = request.GetAbstractRequestInfo(),
                transferData = transferData
            });

        return prerenderResult;
    }
}

