using System;
using System.Collections.Generic;
using NUnit.Framework;

public class Achievement
{
    private List<AchievementHistory> _history = new List<AchievementHistory>();

    public void Add(DateTime date, double value)
    {
        _history.Add(new AchievementHistory(date, value));
        _history.Sort((a, b) => a.Date.CompareTo(b.Date));
    }

    public double GetValueChangeFrom(DateTime referenceDate)
    {
        if (_history.Count == 0)
            return 0;

        if (referenceDate > DateTime.Now)
            return 0;

        AchievementHistory latestBeforeReference = null;
        AchievementHistory latestAfterReference = null;

        foreach (var entry in _history)
        {
            if (entry.Date <= referenceDate)
                latestBeforeReference = entry;

            if (entry.Date > referenceDate)
            {
                latestAfterReference = entry;
                break;
            }
        }

        if (latestBeforeReference == null)
            return 0;

        if (latestAfterReference == null)
            return _history[_history.Count - 1].Value - latestBeforeReference.Value;

        return latestAfterReference.Value - latestBeforeReference.Value;
    }
}

public class AchievementHistory
{
    public DateTime Date { get; }
    public double Value { get; }

    public AchievementHistory(DateTime date, double value)
    {
        Date = date;
        Value = value;
    }
}

[TestFixture]
public class AchievementTest
{
    [Test]
    public void GetValueChangeFrom_SingleHistoryEntry_ReturnsZero()
    {
        var achievement = new Achievement();
        achievement.Add(DateTime.Now.AddDays(-10), 100);
        var result = achievement.GetValueChangeFrom(DateTime.Now.AddDays(-10));
        Assert.AreEqual(0, result);
    }

    [Test]
    public void GetValueChangeFrom_MultipleEntries_CalculatesCorrectChange()
    {
        var achievement = new Achievement();
        achievement.Add(DateTime.Now.AddDays(-30), 50);
        achievement.Add(DateTime.Now.AddDays(-15), 100);
        achievement.Add(DateTime.Now, 200);

        var result = achievement.GetValueChangeFrom(DateTime.Now.AddDays(-20));
        Assert.AreEqual(50, result);
    }

    [Test]
    public void GetValueChangeFrom_FutureDate_ReturnsZero()
    {
        var achievement = new Achievement();
        achievement.Add(DateTime.Now.AddDays(-10), 100);
        var result = achievement.GetValueChangeFrom(DateTime.Now.AddDays(10));
        Assert.AreEqual(0, result);
    }
}

