using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

class CountWords
{
    private Dictionary<string, int> wordsDictionary;

    public CountWords()
    {
        wordsDictionary = new Dictionary<string, int>();
    }

    private string ReadFromFile(string filePath)
    {
        using (StreamReader reader = new StreamReader(filePath))
        {
            return reader.ReadToEnd();
        }
    }

    private void CountWordsOccurance(string wordsFilePath, string textFilePath)
    {
        string wordsContent = ReadFromFile(wordsFilePath);
        string textContent = ReadFromFile(textFilePath);

        string[] wordsToCount = wordsContent.Split(new[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
        string[] wordsInText = textContent.Split(new[] { ' ', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);

        foreach (string word in wordsToCount)
        {
            if (!wordsDictionary.ContainsKey(word))
            {
                wordsDictionary[word] = 0;
            }
        }

        foreach (string word in wordsInText)
        {
            if (wordsDictionary.ContainsKey(word))
            {
                wordsDictionary[word]++;
            }
        }
    }

    private void SaveResult(string resultFilePath)
    {
        var sortedWords = wordsDictionary.OrderByDescending(pair => pair.Value);

        using (StreamWriter writer = new StreamWriter(resultFilePath))
        {
            foreach (var pair in sortedWords)
            {
                writer.WriteLine($"{pair.Key}: {pair.Value}");
            }
        }
    }

    public void Execute(string wordsFilePath, string textFilePath, string resultFilePath)
    {
        CountWordsOccurance(wordsFilePath, textFilePath);
        SaveResult(resultFilePath);
    }
}

class Solution
{
    static void Main()
    {
        CountWords counter = new CountWords();
        counter.Execute("words.txt", "test.txt", "result.txt");
    }
}

using UnityEngine;
using UnityEditor;
using AGXUnity;

[CustomEditor(typeof(RigidBodyEmitterSink), true)]
public class RigidBodyEmitterSinkTool : Editor
{
    private RigidBodyEmitterSink Sink;
    private SerializedProperty m_templates;
    private List<GameObject> availableTemplates = new List<GameObject>();

    private void OnEnable()
    {
        Sink = (RigidBodyEmitterSink)target;
        m_templates = serializedObject.FindProperty("templates");
        LoadAvailableTemplates();
    }

    private void LoadAvailableTemplates()
    {
        availableTemplates.Clear();
        // Find all prefabs in resource folder or specify any valid path
        var prefabGuids = AssetDatabase.FindAssets("t:GameObject", new[] { "Assets/Prefabs" });
        foreach (var guid in prefabGuids)
        {
            var path = AssetDatabase.GUIDToAssetPath(guid);
            var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path);
            if (prefab != null && prefab.GetComponent<RigidBody>() != null)
            {
                availableTemplates.Add(prefab);
            }
        }
    }

    public override void OnInspectorGUI()
    {
        serializedObject.Update();
        EditorGUILayout.LabelField("Rigid Body Emitter Sink", EditorStyles.boldLabel);

        if (!Application.isPlaying)
        {
            EditorGUILayout.PropertyField(m_templates, true);

            if (GUILayout.Button("Add Template"))
            {
                OnTemplateAdd();
            }

            if (GUILayout.Button("Remove Template"))
            {
                OnTemplateRemove();
            }
        }
        else
        {
            EditorGUILayout.HelpBox("Cannot modify templates while in Play mode.", MessageType.Warning);
        }

        serializedObject.ApplyModifiedProperties();
    }

    private void OnTemplateAdd()
    {
        int selectedTemplateIndex = EditorGUILayout.Popup("Select Template", -1, GetTemplateNames());
        if (selectedTemplateIndex >= 0)
        {
            if (CanAddTemplate(availableTemplates[selectedTemplateIndex]))
            {
                Undo.RecordObject(Sink, "Add Rigid Body Template");
                m_templates.arraySize++;
                m_templates.GetArrayElementAtIndex(m_templates.arraySize - 1).objectReferenceValue = availableTemplates[selectedTemplateIndex];
            }
        }
    }

    private void OnTemplateRemove()
    {
        if (m_templates.arraySize > 0)
        {
            Undo.RecordObject(Sink, "Remove Rigid Body Template");
            m_templates.arraySize--;
        }
    }

