            for (int i = 1; i <= totalMessages; i++)
            {
                ProduceMessage(topic, $"Message {i}");
            }

            // Configure consumer settings
            var consumerSettings = ConsumerSettings<string, string>.Create(_system, SerDes.String, SerDes.String)
                .WithBootstrapServers("localhost:9092")
                .WithGroupId("test-group");

            int committedCount = 0;

            // Build the Akka Stream: consume, process asynchronously, batch offsets, and commit.
            var streamCompletion = KafkaConsumer<string, string>
                .CreatePlainSource(consumerSettings, Subscriptions.Topics(topic))
                .SelectAsync(4, async msg =>
                {
                    // Simulate asynchronous message processing
                    await Task.Delay(10);
                    return msg;
                })
                .Batch(10,
                    first => new List<CommittableMessage<string, string>> { first },
                    (batch, msg) =>
                    {
                        batch.Add(msg);
                        return batch;
                    })
                .SelectAsync(1, async batch =>
                {
                    // Simulate offset commit
                    await CommitOffsets(batch);
                    committedCount += batch.Count;
                    // Send batch size to the test probe for verification
                    _probe.Ref.Tell(batch.Count);
                    return batch;
                })

