using System.Collections.ObjectModel;
using AutoMapper;

public interface IItemized<TItem>
{
    List<TItem> Items { get; }
}

public class ItemizedTypeConverter<TIn, TOut, TItem> : ITypeConverter<TIn, IReadOnlyCollection<TOut>>
    where TIn : IItemized<TItem>
{
    public IReadOnlyCollection<TOut> Convert(TIn source, IReadOnlyCollection<TOut> destination, ResolutionContext context)
    {
        if (source == null || source.Items == null)
        {
            return null;
        }

        var cleanedItems = new List<TOut>();

        foreach (var item in source.Items)
        {
            var cleanedItem = context.Mapper.Map<TItem, TOut>(item);
            cleanedItems.Add(cleanedItem);
        }

        return new ReadOnlyCollection<TOut>(cleanedItems);
    }
}

// Example usage classes
public class XmlItem
{
    public string Name { get; set; }
    public int Value { get; set; }
}

public class JsonItem
{
    public string Name { get; set; }
    public int Value { get; set; }
}

public class XmlContainer : IItemized<XmlItem>
{
    public List<XmlItem> Items { get; set; }
}

class Validator
{
    static void Main()
    {
        var config = new MapperConfiguration(cfg =>
        {
            cfg.CreateMap<XmlItem, JsonItem>();
            cfg.CreateMap<XmlContainer, IReadOnlyCollection<JsonItem>>().ConvertUsing<ItemizedTypeConverter<XmlContainer, JsonItem, XmlItem>>();
        });

        var mapper = config.CreateMapper();

        var xmlContainer = new XmlContainer
        {
            Items = new List<XmlItem>
            {
                new XmlItem { Name = "Item1", Value = 10 },
                new XmlItem { Name = "Item2", Value = 20 }
            }
        };

        var jsonItems = mapper.Map<IReadOnlyCollection<JsonItem>>(xmlContainer);

        foreach (var item in jsonItems)
        {
            Console.WriteLine($"Name: {item.Name}, Value: {item.Value}");
        }
    }
}

