namespace MessagingReceiver
{
    public class HttpServiceBusReceiver
    {
        private readonly string _url;
        private readonly string _id;
        private readonly HttpClient _httpClient;
        private const string CLIENT_HEADER_NAME = "X-Client-Info";

        public HttpServiceBusReceiver(string url, string id)
        {
            _url = url ?? throw new ArgumentNullException(nameof(url));
            _id = id ?? throw new ArgumentNullException(nameof(id));
            _httpClient = new HttpClient();
        }

        public async Task<IncomingHttpMessage> ReceiveAsync(CancellationToken cancellationToken)
        {
            // Build the complete URL including identifier
            string requestUrl = $"{_url}/{_id}";

            // Create HTTP GET request
            using (var request = new HttpRequestMessage(HttpMethod.Get, requestUrl))
            {
                // Add custom header with process information
                request.Headers.Add(CLIENT_HEADER_NAME, GetClientHeaderValue());

                // Send the request asynchronously
                HttpResponseMessage response = await _httpClient.SendAsync(request, cancellationToken).ConfigureAwait(false);

                // If message is not found, wait briefly and return null
                if (response.StatusCode == HttpStatusCode.NotFound)
                {
                    await Task.Delay(100, cancellationToken).ConfigureAwait(false);
                    return null;
                }

                // Throw an exception if the status is not successful
                response.EnsureSuccessStatusCode();

                // Read the content as string
                string xmlContent = await response.Content.ReadAsStringAsync().ConfigureAwait(false);

                // Parse the XML content
                XElement xmlElement = XElement.Parse(xmlContent);

                // Wrap the XML payload into an IncomingHttpMessage object and return
                return new IncomingHttpMessage(xmlElement);
            }
        }

        /// <summary>
        /// Generates a custom client header value that includes process and machine information.
        /// </summary>
        /// <returns>A string with process ID, process name, and machine name.</returns>
        private string GetClientHeaderValue()
