public interface IXmlOriginalDocumentService
{
    XmlNodeList SelectNodes(string xpath);
}

public class XmlFileInfoDocument
{
    protected XmlDocument xmlDoc;

    public XmlFileInfoDocument()
    {
        xmlDoc = new XmlDocument();
    }

    public void Load(string filename)
    {
        xmlDoc.Load(filename);
    }

    public void Save(string filename)
    {
        xmlDoc.Save(filename);
    }

    public XmlNodeList SelectNodes(string xpath)
    {
        return xmlDoc.SelectNodes(xpath);
    }
}

public class XmlTransformableDocument : XmlFileInfoDocument, IXmlOriginalDocumentService
{
    private XmlDocument xmlOriginal;

    public XmlTransformableDocument() : base()
    {
        xmlOriginal = null;
    }

    public bool IsChanged
    {
        get
        {
            return !IsXmlEqual(xmlDoc, xmlOriginal);
        }
    }

    protected virtual void OnBeforeChange()
    {
        if (xmlOriginal == null)
        {
            CloneOriginalDocument();
        }
    }

    protected virtual void OnAfterChange()
    {
        // Additional logic after change can be added here
    }

    private void CloneOriginalDocument()
    {
        xmlOriginal = (XmlDocument)xmlDoc.Clone();
    }

    private bool IsXmlEqual(XmlDocument doc1, XmlDocument doc2)
    {
        // Placeholder for actual XML comparison logic
        return false;
    }

    public new XmlNodeList SelectNodes(string xpath)
    {
        if (xmlOriginal == null)
        {
            throw new InvalidOperationException("Original document not cloned yet.");
        }
        return xmlOriginal.SelectNodes(xpath);
    }

    public void ModifyDocument(Action<XmlDocument> modifyAction)
    {
        OnBeforeChange();
        modifyAction(xmlDoc);
        OnAfterChange();
    }
}

