    internal sealed class DefaultEvaluatorFailureHandler : IObserver<IFailedEvaluator>
    {
        private static readonly Logger Logger = Logger.GetLogger(typeof(DefaultEvaluatorFailureHandler));

        [Inject]
        private DefaultEvaluatorFailureHandler()
        {
        }

        public void OnNext(IFailedEvaluator value)
        {
            string msg = string.Format(CultureInfo.InvariantCulture,
                "Received FailedEvaluator event for Evaluator id {0}." +
                " Since no handlers are registered with the Driver, " +
                "the Driver will crash.",
                value.Id);

            InvalidOperationException e = new InvalidOperationException(msg);
            Exceptions.Throw(e, Logger);
        }

        public void OnError(Exception error)
        {
            throw new NotImplementedException();
        }

        public void OnCompleted()
        {
            throw new NotImplementedException();
        }
    }
