namespace Runner
{
    class Order
    {
        struct cd
        {
            public string name;
            public double population;
        }
 
        static int search_get_index_by_name(string name, cd[] data, int data_length,
            int cmp_func(cd a, cd b))
        {
            cd key = new cd();
            key.name = name;
            key.population = 0;
            cd match = data.FirstOrDefault(x => cmp_func(x, key) == 0);
 
            if (match.name == null)
                return -1;
            else
                return Array.IndexOf(data, match);
        }
 
        static double search_get_pop_by_name(string name, cd[] data, int data_length,
            int cmp_func(cd a, cd b))
        {
            cd key = new cd();
            key.name = name;
            key.population = 0;
            cd match = data.FirstOrDefault(x => cmp_func(x, key) == 0);
 
            if (match.name == null)
                return -1;
            else
                return match.population;
        }
 
        static string search_get_pop_threshold(double pop_threshold, cd[] data, int data_length,
            int cmp_func(cd a, cd b))
        {
            cd key = new cd();
            key.name = null;
            key.population = pop_threshold;
            cd match = data.FirstOrDefault(x => cmp_func(x, key) == 0);
 
            if (match.name == null)
                return null;
            else
                return match.name;
        }
 
        static int cd_nameChar_cmp(cd a, cd b)
        {
            int i, len = a.name.Length;
 
            for (i = 0; i < len; i++)
                if (b.name[i]!= a.name[i])
                    return -1;
            return 0;
        }
 
        static int cd_name_cmp(cd a, cd b)
        {
            return b.name.CompareTo(a.name);
        }
 
        static int cd_pop_cmp(cd a, cd b)
        {
            return b.population >= a.population? 1 : 0;
        }
 
