namespace IsoUnity
{
    public class IsoUnityCollectionType : IsoUnityType
    {
        private IsoUnityList l;
        private string whatIs;

        public IsoUnityCollectionType()
        {
            l = new IsoUnityList();
            whatIs = "IsoUnityList";
        }

        public override IsoUnityType clone()
        {
            IsoUnityCollectionType newType = new IsoUnityCollectionType();
            newType.l = new IsoUnityList(this.l);
            newType.whatIs = this.whatIs;
            return newType;
        }

        public override bool canHandle(object o)
        {
            return o is IList<object>;
        }

        public IsoUnityList Value
        {
            get { return l; }
            set
            {
                if (value is IsoUnityList)
                {
                    l = value;
                }
                else
                {
                    throw new ArgumentException("Value must be of type IsoUnityList");
                }
            }
        }

        public override void fromJSONObject(JSONObject json)
        {
            l.Clear();
            if (json.type == JSONObject.Type.ARRAY)
            {
                foreach (JSONObject item in json.list)
                {
                    IsoUnityType itemType = IsoUnityTypeFactory.createTypeFromJSONObject(item);
                    l.Add(itemType);
                }
            }
        }

        public override JSONObject toJSONObject()
        {
            JSONObject json = new JSONObject(JSONObject.Type.ARRAY);
            foreach (IsoUnityType item in l)
            {
                json.Add(item.toJSONObject());
            }
            return json;
        }

        public override string ToString()
        {
            return whatIs;
        }
    }

    public class IsoUnityType
    {
        public virtual IsoUnityType clone() { return null; }
        public virtual bool canHandle(object o) { return false; }
        public virtual void fromJSONObject(JSONObject json) { }
        public virtual JSONObject toJSONObject() { return new JSONObject(); }
    }

    public class IsoUnityList : List<IsoUnityType>
    {
        public IsoUnityList() : base() { }
        public IsoUnityList(IsoUnityList other) : base(other) { }
    }

    public class JSONObject
    {
        public enum Type { ARRAY, OBJECT, STRING, NUMBER, BOOL, NULL }
        public Type type;
        public List<JSONObject> list;

