public enum GP_AppStateStatusCodes
{
    Success = 0,
    KeyNotFound = 2001,
    NetworkError = 2002,
    InvalidData = 2003,
    VersionConflict = 2004,
    InternalError = 2005,
    NotFound = 2000,
    StaleData = 2006,
    AuthError = 2007,
    OperationNotSupported = 2008,
    Timeout = 2009,
    QuotaExceeded = 2010,
    UnknownError = -1
}

public class GoogleCloudResult
{
    private readonly byte[] stateData;
    private readonly byte[] serverConflictData;
    private readonly string resolvedVersion;
    private readonly string _stateKey;
    private readonly GP_AppStateStatusCodes statusCode;

    public GoogleCloudResult(string statusCodeString, byte[] stateData, string stateKey)
    {
        statusCode = TryParseStatusCode(statusCodeString);
        this.stateData = stateData;
        _stateKey = stateKey;
        serverConflictData = null;
        resolvedVersion = null;
    }

    public GoogleCloudResult(string statusCodeString, byte[] stateData, string stateKey,
                           byte[] serverConflictData, string resolvedVersion) : this(statusCodeString, stateData, stateKey)
    {
        this.serverConflictData = serverConflictData;
        this.resolvedVersion = resolvedVersion;
    }

    public string stateDataString
    {
        get
        {
            if (stateData == null || stateData.Length == 0) return null;
#if UNITY_WP8 || UNITY_METRO
            return null;
#else
            return Encoding.UTF8.GetString(stateData);
#endif
        }
    }

    public string serverConflictDataString
    {
        get
        {
            if (serverConflictData == null || serverConflictData.Length == 0) return null;
#if UNITY_WP8 || UNITY_METRO
            return null;
#else
            return Encoding.UTF8.GetString(serverConflictData);
#endif
        }
    }

    public bool isSuccess => statusCode == GP_AppStateStatusCodes.Success;
    public bool HasConflict => serverConflictData != null && resolvedVersion != null;
    public string ResolvedVersion => resolvedVersion;
    public string StateKey => _stateKey;

    public string StatusMessage
    {
        get
        {
            switch (statusCode)
            {
                case GP_AppStateStatusCodes.Success:
                    return "Operation completed successfully";
                case GP_AppStateStatusCodes.KeyNotFound:
                    return "Specified cloud data key not found";
                case GP_AppStateStatusCodes.NetworkError:
                    return "Network connectivity issue";

