    public class LiftLexEntryRepository
    {
        public event Action<LexEntry> EntryAdded;
        public event Action<LexEntry> EntryModified;
        public event Action<LexEntry> EntryDeleted;

        private readonly Dictionary<string, LexEntry> _entries = new();

        public void AddEntry(LexEntry entry)
        {
            _entries[entry.Id] = entry;
            EntryAdded?.Invoke(entry);
        }

        public void ModifyEntry(LexEntry entry)
        {
            if (_entries.ContainsKey(entry.Id))
            {
                _entries[entry.Id] = entry;
                EntryModified?.Invoke(entry);
            }
        }

        public void DeleteEntry(string id)
        {
            if (_entries.Remove(id, out var entry))
            {
                EntryDeleted?.Invoke(entry);
            }
        }
    }

