namespace ModelExtensions
{
    public static class ModelExtensions
    {
        public static IEnumerable<IModelElement> Descendants(this IModelElement element)
        {
            return new DescendantsCollection(element);
        }

        public static void Serialize(this IModelElement element, string path)
        {
            Serialize(element, path, null);
        }

        public static void Serialize(this IModelElement element, string path, Uri uri)
        {
            if (element == null) throw new ArgumentNullException(nameof(element));
            if (path == null) throw new ArgumentNullException(nameof(path));

            Serialize(element, File.OpenWrite(path), uri ?? new Uri(Path.GetFullPath(path)));
        }

        public static void Serialize(this IModelElement element, Stream stream, Uri uri = null)
        {
            if (element == null) throw new ArgumentNullException(nameof(element));
            if (stream == null) throw new ArgumentNullException(nameof(stream));

            IModelRepository repository = new ModelRepository();
            Model model = element.Model;

            if (model == null)
            {
                model = new Model { RootElements = { element } };
            }
            if(uri != null && model.ModelUri == null)
            {
                model.ModelUri = uri;
            }

            repository.Serializer.Serialize(model, stream);
        }

        private class DescendantsCollection : ModelElementCollection<IModelElement>
        {
            public DescendantsCollection(IModelElement parent) : base(parent) { }

            protected override void OnAdd(IModelElement item) { }

            protected override void OnRemove(IModelElement item) { }

            protected override void ClearItems() { }

            protected override void CopyAll(ICollection<IModelElement> collection) { }

            public override IEnumerator<IModelElement> GetEnumerator()
            {
                yield return Parent;
                foreach (IModelElement child in Parent.Children)
                {
                    foreach (IModelElement descendant in new DescendantsCollection(child))
                    {
                        yield return descendant;
                    }
                }
            }
        }
    }
}

