using System;
using System.Collections.Generic;
using System.Linq;
 
namespace DisjointSort
{
    class Task
    {
        static void DisjointSort(int[] array, int[] indices)
        {
            var sorted = indices.ToArray();
            Array.Sort(sorted, (a, b) => array[a].CompareTo(array[b]));
            var swaps = indices
               .Zip(sorted, (a, b) => new { a, b })
               .Select(x => x.a > x.b? (x.b, x.a) : (x.a, x.b))
               .Distinct()
               .ToArray();
            foreach (var (a, b) in swaps)
            {
                var temp = array[a];
                array[a] = array[b];
                array[b] = temp;
            }
        }
 
        static void Main(string[] args)
        {
            var array = new int[] { 7, 6, 5, 4, 3, 2, 1, 0 };
            var indices = new int[] { 6, 1, 7 };
            DisjointSort(array, indices);
            Console.WriteLine(string.Join(", ", array));
        }
    }
}

using System;
using System.Collections.Generic;
 
namespace RosettaCode.BogoSort
{
    public static class BogoSorter
    {
        public static void Sort<T>(List<T> list) where T:IComparable
        {
            while (!list.isSorted())
            {
                list.Shuffle();
            }
        }
 
        private static bool isSorted<T>(this IList<T> list) where T:IComparable
        {
            if(list.Count<=1)
                return true;
            for (int i = 1 ; i < list.Count; i++)
                if(list[i].CompareTo(list[i-1])<0) return false;
            return true;
        }
 
        private static void Shuffle<T>(this IList<T> list)
        {
            Random rand = new Random();
            for (int i = 0; i < list.Count; i++)
            {
                int swapIndex = rand.Next(list.Count);
                T temp = list[swapIndex];
                list[swapIndex] = list[i];
                list[i] = temp;
            }
        }
    }
 
    class TestProgram
    {
        static void Main()
        {
            List<int> testList = new List<int> { 3, 4, 1, 8, 7, 4, -2 };
            BogoSorter.Sort(testList);
            foreach (int i in testList) Console.Write(i + " ");
        }
 
    }
}

using System;
 
namespace RosettaCode {
 
    class PascalsTriangle {
 
        public static void CreateTriangle(int n) {
            if (n > 0) {
                for (int i = 0; i < n; i++) {
                    int c = 1;
                    Console.Write(" ".PadLeft(2 * (n - 1 - i)));
                    for (int k = 0; k <= i; k++) {
                        Console.Write("{0}", c.ToString().PadLeft(3));
                        c = c * (i - k) / (k + 1);
                    }
                    Console.WriteLine();
                }
            }
        }
 
        public static void Main() {
            CreateTriangle(8);
        }
    }
}

