namespace GameLauncher
{
    public class GameManager
    {
        public event Action<string> OnGameLog;
        public event Action OnGameExit;
        public event Action<string> OnError;

        public bool IsRunning { get; private set; }

        private string gamePath;
        private string javaPath;
        private string version;
        private string authToken;

        public GameManager(string gamePath, string javaPath, string version, string authToken)
        {
            this.gamePath = gamePath;
            this.javaPath = javaPath;
            this.version = version;
            this.authToken = authToken;
            IsRunning = false;
        }

        public void Run()
        {
            if (IsRunning)
            {
                Log("Game is already running.");
                return;
            }

            IsRunning = true;
            Log("Attempting to launch the game...");

            try
            {
                string arguments = BuildLaunchArguments();
                Process gameProcess = new Process
                {
                    StartInfo = new ProcessStartInfo
                    {
                        FileName = javaPath,
                        Arguments = arguments,
                        RedirectStandardOutput = true,
                        RedirectStandardError = true,
                        UseShellExecute = false,
                        CreateNoWindow = true
                    }
                };

                gameProcess.OutputDataReceived += (sender, e) => Log(e.Data);
                gameProcess.ErrorDataReceived += (sender, e) => Error(e.Data);
                gameProcess.EnableRaisingEvents = true;
                gameProcess.Exited += (sender, e) => Exit();

                gameProcess.Start();
                gameProcess.BeginOutputReadLine();
                gameProcess.BeginErrorReadLine();

                Log("Game launched successfully.");
            }
            catch (Exception ex)
            {
                IsRunning = false;
                Error($"Failed to launch game: {ex.Message}");
            }
        }

        private string BuildLaunchArguments()
        {
            return $"--version {version} --auth {authToken} --memory 2G";
        }

