    public class Asn1Integer : Base
    {
        private IntPtr ptr;

        public Asn1Integer()
        {
            ptr = Native.ASN1_INTEGER_new();
            if (ptr == IntPtr.Zero)
                throw new OutOfMemoryException("Failed to allocate ASN.1 INTEGER");
        }

        public Asn1Integer(int value)
        {
            ptr = Native.ASN1_INTEGER_new();
            if (ptr == IntPtr.Zero)
                throw new OutOfMemoryException("Failed to allocate ASN.1 INTEGER");

            Native.ExpectSuccess(Native.ASN1_INTEGER_set(ptr, value));
        }

        public Asn1Integer(IntPtr existingPtr, bool takeOwnership)
        {
            if (existingPtr == IntPtr.Zero)
                throw new ArgumentNullException(nameof(existingPtr));

            ptr = existingPtr;
            if (!takeOwnership)
                AddRef();
        }

        public int Value
        {
            get => Native.ASN1_INTEGER_get(ptr);
            set => Native.ExpectSuccess(Native.ASN1_INTEGER_set(ptr, value));
        }

        public int ToInt32()
        {
            return Native.ASN1_INTEGER_get(ptr);
        }

        protected override void OnDispose(bool disposing)
        {
            if (ptr != IntPtr.Zero)
            {
                Native.ASN1_INTEGER_free(ptr);
                ptr = IntPtr.Zero;
            }
            base.OnDispose(disposing);
        }
    }

    public class Base : IDisposable
    {
        private bool disposed;

        protected void AddRef()
        {
            // Implementation for reference counting if needed
        }

        protected virtual void OnDispose(bool disposing)
        {
            if (!disposed)
            {
                if (disposing)
                {
                    // Dispose managed resources
                }
                // Dispose unmanaged resources
                disposed = true;
            }
        }

        public void Dispose()
        {
            OnDispose(true);
            GC.SuppressFinalize(this);
        }

        ~Base()
        {
            OnDispose(false);
        }
    }

