namespace Indexer
{
    class Runner
    {
        static void Main(string[] args)
        {
            // files to be indexed entered as command line arguments
            if (args.Length == 0)
            {
                Console.WriteLine("No file names have been supplied");
                return;
            }
            foreach (var arg in args)
                indexFile(arg);
            Console.WriteLine();
            Console.WriteLine("Enter word(s) to be searched for in these files or 'q' to quit");
            while (true)
            {
                Console.Write(" ? : ");
                var word = Console.ReadLine();
                if (word.ToLower() == "q")
                    return;
                findWord(word);
            }
        }
 
        static readonly Dictionary<string, List<Location>> invIndex = new Dictionary<string, List<Location>>();
        static readonly List<string> fileNames = new List<string>();
        static readonly Regex splitter = new Regex(@"\W+");
 
        class Location
        {
            public string FileName { get; }
            public int WordNum { get; }
            public Location(string fileName, int wordNum)
            {
                FileName = fileName;
                WordNum = wordNum;
            }
            public override string ToString() => $"{{{FileName}, word number {WordNum}}}";
        }
 
        static void indexFile(string fileName)
        {
            if (fileNames.Contains(fileName))
            {
                Console.WriteLine($"'{fileName}' already indexed");
                return;
            }
            fileNames.Add(fileName);
            foreach (var line in File.ReadLines(fileName))
            {
                var words = line.ToLower().Split(splitter.Match(line).Cast<Match>().Select(m => m.Value).ToArray(), StringSplitOptions.RemoveEmptyEntries);
                for (var i = 0; i < words.Length; i++)
                {
                    var w = words[i];
                    List<Location> locations;
                    if (!invIndex.TryGetValue(w, out locations))
                    {
                        locations = new List<Location>();
                        invIndex.Add(w, locations);
                    }
                    locations.Add(new Location(fileName, i + 1));
                }
            }
            Console.WriteLine($"'{fileName}' has been indexed");
        }

