using System;
using System.Text.RegularExpressions;

public sealed class ExpectAction
{
    public Regex Expect { get; }
    public Action<string> Action { get; }

    public ExpectAction(Regex expect, Action<string> action)
    {
        Expect = expect ?? throw new ArgumentNullException(nameof(expect));
        Action = action ?? throw new ArgumentNullException(nameof(action));
    }

    public ExpectAction(string expectPattern, Action<string> action)
        : this(CreateLiteralRegex(expectPattern), action)
    {
    }

    private static Regex CreateLiteralRegex(string pattern)
    {
        if (pattern == null)
            throw new ArgumentNullException(nameof(pattern));

        return new Regex(
            Regex.Escape(pattern),
            RegexOptions.Compiled | RegexOptions.CultureInvariant
        );
    }

    public void Trigger(string input)
    {
        if (Expect.IsMatch(input))
        {
            Action(input);
        }
    }

    public bool TryTrigger(string input)
    {
        var match = Expect.Match(input);
        if (!match.Success) return false;

        Action(input);
        return true;
    }

    public Match CheckMatch(string input)
    {
        return Expect.Match(input);
    }

    public override string ToString()
    {
        return $"Expect: {Expect}, Action: {Action.Method.Name}";
    }

    public static ExpectAction CreateWithTimeout(
        string pattern,
        Action<string> action,
        TimeSpan timeout)
    {
        var regex = new Regex(
            Regex.Escape(pattern),
            RegexOptions.None,
            timeout
        );
        return new ExpectAction(regex, action);
    }
}

