namespace Account
{
    class Library
    {
        static void Main(string[] args)
        {
            double[] a = { 350, 10 };
            double[] b = { 90, 180, 270, 360 };
            double[] c = { 10, 20, 30 };
            Console.WriteLine(meanAngleDeg(a));
            Console.WriteLine(meanAngleDeg(b));
            Console.WriteLine(meanAngleDeg(c));
            Console.ReadKey();
        }
        static double sum(double[] a)
        {
            double s = 0;
            for (int i = 0; i < a.Length; i++) s += a[i];
            return s;
        }
        static double degToRad(double a)
        {
            return Math.PI / 180 * a;
        }
        static double meanAngleDeg(double[] a)
        {
            return 180 / Math.PI * Math.Atan2(
                sum(a.Select(degToRad).Select(Math.Sin).ToArray()) / a.Length,
                sum(a.Select(degToRad).Select(Math.Cos).ToArray()) / a.Length
            );
        }
    }
}

using Abp.Application.Services;
using Abp.Domain.Repositories;
using Abp.Domain.Uow;
using Abp.UI;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using System.Threading.Tasks;
using System.Transactions;

public class ProductDto
{
    public int Id { get; set; }
    public string Name { get; set; }
    public decimal Price { get; set; }
}

public class ProductCreateInput
{
    public string Name { get; set; }
    public decimal Price { get; set; }
}

public class ProductAppService : ApplicationService
{
    private readonly IRepository<Product> _productRepository;
    private readonly IUnitOfWorkManager _unitOfWorkManager;

    public ProductAppService(IRepository<Product> productRepository, IUnitOfWorkManager unitOfWorkManager)
    {
        _productRepository = productRepository;
        _unitOfWorkManager = unitOfWorkManager;
    }

    public async Task<List<ProductDto>> GetAllAsync()
    {
        var products = await _productRepository.GetAllListAsync();
        return products.Select(p => new ProductDto { Id = p.Id, Name = p.Name, Price = p.Price }).ToList();
    }

    public async Task<int> CreateProduct(ProductCreateInput input)
    {
        var product = new Product { Name = input.Name, Price = input.Price };
        await _productRepository.InsertAsync(product);
        return product.Id;
    }

    public async Task CreateProductAndRollback(ProductCreateInput input)
    {
        using (var uow = _unitOfWorkManager.Begin())
        {
            try
            {
                await CreateProduct(input);
                throw new UserFriendlyException("Simulated exception for rollback");
            }
            catch (UserFriendlyException)
            {
                // Rollback occurs here
                throw;
            }
        }
    }

    public async Task<List<ProductDto>> GetAllParallel()
    {
        var tasks = new List<Task<List<ProductDto>>>
        {
            GetAllParallelMethod(),
            GetAllParallelMethod(),
            GetAllParallelMethod(),
        };

        var results = await Task.WhenAll(tasks);
        return results.SelectMany(r => r).ToList();
    }

    private async Task<List<ProductDto>> GetAllParallelMethod()
    {
        var products = await _productRepository.GetAllListAsync();
        return products.Select(p => new ProductDto { Id = p.Id, Name = p.Name, Price = p.Price }).ToList();
    }
}

