using System;
using System.Numerics;

class CatalanNumberCalculator
{
    static void Main(string[] args)
    {
        Console.WriteLine("Catalan Number Calculator");
        Console.WriteLine("------------------------");

        while (true)
        {
            Console.Write("Enter a non-negative integer (or 'q' to quit): ");
            string input = Console.ReadLine();

            if (input.ToLower() == "q")
            {
                break;
            }

            if (!int.TryParse(input, out int n))
            {
                Console.WriteLine("Invalid input. Please enter a valid non-negative integer.");
                continue;
            }

            if (n < 0)
            {
                Console.WriteLine("Please enter a non-negative integer.");
                continue;
            }

            try
            {
                BigInteger catalanNumber = CalculateCatalanNumber(n);
                Console.WriteLine($"Catalan Number C({n}) = {catalanNumber}");
            }
            catch (OverflowException)
            {
                Console.WriteLine("Number is too large to calculate. Try a smaller value.");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"An error occurred: {ex.Message}");
            }
        }

        Console.WriteLine("Thank you for using Catalan Number Calculator!");
    }

    static BigInteger CalculateCatalanNumber(int n)
    {
        if (n == 0)
        {
            return 1;
        }

        BigInteger numerator = CalculateFactorial(2 * n);
        BigInteger denominator = CalculateFactorial(n + 1) * CalculateFactorial(n);

        return numerator / denominator;
    }

    static BigInteger CalculateFactorial(int number)
    {
        if (number < 0)
        {
            throw new ArgumentException("Factorial is not defined for negative numbers.");
        }

        BigInteger result = 1;
        for (int i = 2; i <= number; i++)
        {
            result *= i;
        }

        return result;
    }
}

