public abstract class Command
{
    [Argument(ArgumentType.Optional, ShortName: "q", LongName: "quiet")]
    public bool Quiet { get; set; }

    [Argument(ArgumentType.Optional, ShortName: "v", LongName: "verbose")]
    public bool Verbose { get; set; }

    protected void ConfigureTraceLevels(IEnumerable<TraceSource> sources)
    {
        SourceLevels defaultLevel = SourceLevels.Warning;

        if (Quiet)
        {
            defaultLevel = SourceLevels.Error;
        }
        else if (Verbose)
        {
            defaultLevel = SourceLevels.Verbose;
        }

        foreach (TraceSource source in sources)
        {
            source.Switch.Level = defaultLevel;
        }
    }

    protected void WriteTraceMessage(TraceSource source,
                                     TraceEventType eventType,
                                     string message)
    {
        if (source != null)
        {
            source.TraceEvent(eventType, 0, message);
            source.Flush();
        }
    }

    protected void WriteConsoleMessage(TraceEventType eventType, string message)
    {
        ConsoleColor originalColor = Console.ForegroundColor;

        switch (eventType)
        {
            case TraceEventType.Error:
                Console.ForegroundColor = ConsoleColor.Red;
                break;
            case TraceEventType.Warning:
                Console.ForegroundColor = ConsoleColor.Yellow;
                break;
            case TraceEventType.Information:
                Console.ForegroundColor = ConsoleColor.Green;
                break;
        }

        Console.WriteLine(message);
        Console.ForegroundColor = originalColor;
    }

    public abstract void Invoke(CompositionContainer container);
}

