static void InsertAfter(Link prev, int i)
{
    if (prev.next != null)
    {
        prev.next.prev = new Link() { item = i, prev = prev, next = prev.next };
        prev.next = prev.next.prev;
    }
    else
        prev.next = new Link() { item = i, prev = prev };
}

using System;
using System.Drawing;
using System.Runtime.InteropServices;

public static class ScreenCapture
{
    [DllImport("user32.dll")]
    private static extern IntPtr GetDesktopWindow();

    [DllImport("user32.dll")]
    private static extern IntPtr GetWindowDC(IntPtr hWnd);

    [DllImport("gdi32.dll")]
    private static extern IntPtr CreateCompatibleDC(IntPtr hdc);

    [DllImport("gdi32.dll")]
    private static extern IntPtr CreateCompatibleBitmap(IntPtr hdc, int width, int height);

    [DllImport("gdi32.dll")]
    private static extern bool BitBlt(IntPtr hdc, int x, int y, int cx, int cy,
        IntPtr hdcSrc, int x1, int y1, uint rop);

    [DllImport("gdi32.dll")]
    private static extern IntPtr SelectObject(IntPtr hdc, IntPtr hObject);

    [DllImport("gdi32.dll")]
    private static extern bool DeleteObject(IntPtr hObject);

    [DllImport("gdi32.dll")]
    private static extern bool DeleteDC(IntPtr hdc);

    public static Bitmap Capture(int x, int y, int width, int height)
    {
        IntPtr desktopWindow = GetDesktopWindow();
        IntPtr screenDC = GetWindowDC(desktopWindow);
        IntPtr memoryDC = CreateCompatibleDC(screenDC);

        IntPtr bitmap = CreateCompatibleBitmap(screenDC, width, height);
        IntPtr oldBitmap = SelectObject(memoryDC, bitmap);

        BitBlt(memoryDC, 0, 0, width, height, screenDC, x, y, 0x00CC0020);

        Bitmap result = Image.FromHbitmap(bitmap);

        SelectObject(memoryDC, oldBitmap);
        DeleteObject(bitmap);
        DeleteDC(memoryDC);
        DeleteDC(screenDC);

        return result;
    }
}

// IdentityMatrix is a "subclass" of Matrix
public class IdentityMatrix : Matrix
{
    public IdentityMatrix(int n)
    {
        this.height = n;
        this.width = n;
        this.mtx = new int[n][];
        for (int i = 0; i < n; i++)
        {
            this.mtx[i] = new int[n];
            for (int j = 0; j < n; j++)
            {
                this.mtx[i][j] = (i == j? 1 : 0);
            }
        }
    }
}
 
// the Matrix exponentiation function
// returns a new matrix
public Matrix exp(int n)
{
    Matrix result = new IdentityMatrix(this.height);
    for (int i = 1; i <= n; i++)
    {
        result = result.mult(this);
    }
    return result;
}
 
