using System;
using System.Collections.Generic;

public static class Users
{
    public class User
    {
        public int Id { get; set; }
        public string Username { get; set; }
        public string Email { get; set; }
        public string PasswordHash { get; set; }
        public string AuthToken { get; set; }
        public DateTime CreatedAt { get; set; }
        public bool IsActive { get; set; }
    }

    public static bool CreateUser(string username, string email, string password)
    {
        try
        {
            string passwordHash = HashPassword(password);
            object[] parameters = { username, email, passwordHash };
            return Sql.ExecuteStoredProcedure("CreateUserProcedure", parameters);
        }
        catch
        {
            return false;
        }
    }

    public static User AuthenticateUser(string email, string password)
    {
        try
        {
            object[] authParams = { email, HashPassword(password) };
            var result = Sql.QueryStoredProcedure("AuthenticateUserProcedure", authParams);

            return result != null
                ? new User
                {
                    Id = result.Id,
                    Email = result.Email,
                    AuthToken = CreateAuthToken(result.Id)
                }
                : null;
        }
        catch
        {
            return null;
        }
    }

    public static string CreateAuthToken(int userId)
    {
        string token = Guid.NewGuid().ToString();
        object[] tokenParams = { userId, token, DateTime.UtcNow.AddHours(2) };
        Sql.ExecuteStoredProcedure("CreateAuthTokenProcedure", tokenParams);
        return token;
    }

    public static bool UpdatePassword(int userId, string newPassword)
    {
        string hashedPassword = HashPassword(newPassword);
        object[] passwordParams = { userId, hashedPassword };
        return Sql.ExecuteStoredProcedure("UpdatePasswordProcedure", passwordParams);
    }

    public static bool HasPasswords()
    {
        return Sql.ExecuteScalarProcedure("CheckPasswordExistenceProcedure") > 0;
    }

    public static bool HasAdmin()
    {
        return Sql.ExecuteScalarProcedure("CheckAdminExistenceProcedure") > 0;
    }

    private static string HashPassword(string password)
    {
        // Implement secure password hashing
        return Convert.ToBase64String(
            System.Security.Cryptography.SHA256.Create()
            .ComputeHash(System.Text.Encoding.UTF8.GetBytes(password))
        );
    }
}

