[TestFixture]
public class WebRequestFactoryTests
{
    private IApiConfiguration _apiConfiguration;

    [SetUp]
    public void Setup()
    {
        _apiConfiguration = new ApiConfiguration
        {
            BaseUri = new Uri("https://api.myob.com/accountright/"),
            Accept = "application/json",
            CachePolicy = new RequestCachePolicy(RequestCacheLevel.NoCacheNoStore)
        };
    }

    private WebRequestFactory CreateWebRequestFactory(IApiConfiguration apiConfiguration)
    {
        return new WebRequestFactory(apiConfiguration);
    }

    [Test]
    public void WhenICreateAWebRequestObjectItIsPopulatedWithSuppliedUri()
    {
        var factory = CreateWebRequestFactory(_apiConfiguration);
        var uri = new Uri("https://api.myob.com/accountright/123456789/CompanyFile");
        var request = factory.Create(uri) as HttpWebRequest;

        Assert.IsNotNull(request);
        Assert.AreEqual(uri, request.RequestUri);
    }

    [Test]
    public void WhenICreateSeveralWebRequestObjectTheyAreNotTheSameObject()
    {
        var factory = CreateWebRequestFactory(_apiConfiguration);
        var uri1 = new Uri("https://api.myob.com/accountright/123456789/CompanyFile");
        var uri2 = new Uri("https://api.myob.com/accountright/987654321/CompanyFile");

        var request1 = factory.Create(uri1);
        var request2 = factory.Create(uri2);

        Assert.AreNotSame(request1, request2);
    }

    [Test]
    public void WhenISupplyAnAcceptHeader_ItIsAppliedTo_TheCreatedWebRequestObject()
    {
        var factory = CreateWebRequestFactory(_apiConfiguration);
        var uri = new Uri("https://api.myob.com/accountright/123456789/CompanyFile");
        var request = factory.Create(uri) as HttpWebRequest;

        Assert.IsNotNull(request);
        Assert.AreEqual(_apiConfiguration.Accept, request.Accept);
    }

    [Test]
    public void HttpCachePolicy_Is_Set_On_Webrequest()
    {
        var factory = CreateWebRequestFactory(_apiConfiguration);
        var uri = new Uri("https://api.myob.com/accountright/123456789/CompanyFile");
        var request = factory.Create(uri) as HttpWebRequest;

        Assert.IsNotNull(request);
        Assert.AreEqual(_apiConfiguration.CachePolicy.Level, request.CachePolicy.Level);
    }
}

