public class ContentElement : Element, ISilverlightContainerElement
{
    private FrameworkElement _rootElement;
    private readonly ContentControl _contentControl;

    public ContentElement()
    {
        _contentControl = new ContentControl
        {
            Margin = new Thickness(
                GetDefaultMarginLeft(),
                GetDefaultMarginTop(),
                GetDefaultMarginRight(),
                GetDefaultMarginBottom()
            ),
            IsTabStop = GetDefaultTabStop()
        };
    }

    public override FrameworkElement CreateFrameworkElement()
    {
        return _contentControl;
    }

    public void InsertChild(int index, FrameworkElement child)
    {
        if (_rootElement != null)
        {
            throw new InvalidOperationException("ContentElement can only contain one child.");
        }

        if (!IsValidChild(child.GetType()))
        {
            throw new ArgumentException("Invalid child type.");
        }

        _rootElement = child;
        _contentControl.Content = _rootElement;
    }

    public void RemoveChild(FrameworkElement child)
    {
        if (_rootElement == child)
        {
            _rootElement = null;
            _contentControl.Content = null;
        }
    }

    protected virtual bool IsValidChild(Type childType)
    {
        return typeof(FrameworkElement).IsAssignableFrom(childType);
    }

    protected virtual void InvalidChildError(INode child)
    {
        throw new ArgumentException($"Invalid child type: {child.GetType()}");
    }

    public override void AddChild(INode child)
    {
        if (child is FrameworkElement frameworkElement)
        {
            InsertChild(0, frameworkElement);
        }
        else
        {
            InvalidChildError(child);
        }
    }

    public override void RemoveChild(INode child)
    {
        if (child is FrameworkElement frameworkElement)
        {
            RemoveChild(frameworkElement);
        }
    }

    protected virtual double GetDefaultMarginLeft() => 0;
    protected virtual double GetDefaultMarginRight() => 0;
    protected virtual double GetDefaultMarginTop() => 0;
    protected virtual double GetDefaultMarginBottom() => 0;

    protected virtual bool GetDefaultTabStop() => false;
}

public interface ISilverlightContainerElement : ISilverlightElement
{
    void InsertChild(int index, FrameworkElement child);
    void RemoveChild(FrameworkElement child);
}

