using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Xunit;

namespace System.IO.Tests
{
    public class StreamMethods
    {
        protected virtual Stream CreateStream()
        {
            return new MemoryStream();
        }

        protected virtual Stream CreateStream(int bufferSize)
        {
            return new MemoryStream(new byte[bufferSize]);
        }

        [Fact]
        public void MemoryStreamSeekStress()
        {
            var ms1 = CreateStream();
            SeekTest(ms1, false);
        }
        [Fact]
        public void MemoryStreamSeekStressWithInitialBuffer()
        {
            var ms1 = CreateStream(1024);
            SeekTest(ms1, false);
        }

        [Fact]
        public async Task MemoryStreamStress()
        {
            var ms1 = CreateStream();
            await StreamTest(ms1, false);
        }

        public static void SeekTest(Stream stream, Boolean fSuppres)
        {
            long lngPos;
            byte btValue;

            stream.Position = 0;

            Assert.Equal(0, stream.Position);

            int length = 1 << 10; //fancy way of writing 2 to the pow 10
            byte[] btArr = new byte[length];
            for (int i = 0; i < btArr.Length; i++)
                btArr[i] = (byte)i;

            if (stream.CanWrite)
                stream.Write(btArr, 0, btArr.Length);
            else
                stream.Position = btArr.Length;

            Assert.Equal(btArr.Length, stream.Position);

            lngPos = stream.Seek(0, SeekOrigin.Begin);
            Assert.Equal(0, lngPos);

            Assert.Equal(0, stream.Position);

            for (int i = 0; i < btArr.Length; i++)
            {
                if (stream.CanWrite)
                {
                    btValue = (byte)stream.ReadByte();
                    Assert.Equal(btArr[i], btValue);
                }
                else
                {
                    stream.Seek(1, SeekOrigin.Current);
                }
                Assert.Equal(i + 1, stream.Position);
            }

            Assert.Throws<IOException>(() => stream.Seek(-5, SeekOrigin.Begin));

            lngPos = stream.Seek(5, SeekOrigin.Begin);
            Assert.Equal(5, lngPos);
            Assert.Equal(5, stream.Position);

            lngPos = stream.Seek(5, SeekOrigin.End);
            Assert.Equal(length + 5, lngPos);
            Assert.Throws<IOException>(() => stream.Seek(-(btArr.Length + 1), SeekOrigin.End));

            lngPos = stream.Seek(-5, SeekOrigin.End);

using System;
using SharpPcap.WinpkFilter;

namespace SharpPcap.WinpkFilter
{
    /// <summary>
    /// Options to configure the network adapter
    /// </summary>
    [Flags]
    public enum AdapterModes : UInt32
    {
        /// <summary>
        ///  No flags.
        /// </summary>
        None = 0x00000000,

        /// <summary>
        ///  This flag indicates that all packets sent by the MSTCP to the
        ///  interface and matching the active filters will be tunneled to the
        ///  application, i.e. the original packet will be dropped and a copy will
        ///  be delivered to the application.
        /// </summary>
        SentTunnel = 0x00000001,

        /// <summary>
        ///  This flag indicates that all packets received by the interface
        ///  and matching the active filters will be tunneled to the application,
        ///  i.e. the original packet will be dropped and a copy will be delivered
        ///  to the application.
        /// </summary>
        RecvTunnel = 0x00000002,

        /// <summary>
        /// Combination of <see cref="SentTunnel"/> and <see cref="RecvTunnel"/>.
        /// </summary>
        Tunnel = SentTunnel | RecvTunnel,

        /// <summary>
        ///  This flag indicates that all packets sent by the MSTCP and matching
        ///  the active filters will be delivered to the application, i.e.
        ///  original packet will be delivered as is and its copy will be delivered
        ///  to the application.
        /// </summary>
        SentListen = 0x00000004,

        /// <summary>
        ///  This flag indicates that all packets received by the interface
        ///  and matching the active filters will be delivered to the application,
        ///  i.e. original packet will be delivered as is and its copy will be
        ///  delivered to the application.
        /// </summary>
        RecvListen = 0x00000008,

        /// <summary>
        /// Combination of <see cref="SentListen"/> and <see cref="RecvListen"/>.
        /// </summary>
        Listen = SentListen | RecvListen,

        /// <summary>
        /// The filter is attached at the NDIS intermediate driver layer and can't
        /// intercept loopback traffic.
        /// </summary>
        FilterDirect = 0x00000100,

        /// <summary>
        ///  Enable loopback packets filtering
        /// </summary>
        LoopbackFilter = 0x00000200,

        /// <summary>
        ///  Block loopback packets
        /// </summary>
        LoopbackBlock = 0x00000400
    }
}

