using Robust.Client.Graphics.Shaders;
using Robust.Client.Interfaces.GameObjects.Components;
using Robust.Shared.GameObjects;
using Robust.Shared.IoC;
using Robust.Shared.Prototypes;

namespace Game.Components
{
    public class InteractionOutlineComponent : Component
    {
        public override string Name => "InteractionOutline";

        [Dependency] private readonly IPrototypeManager _prototypeManager = default!;

        private IShader _inRangeShader;
        private IShader _outOfRangeShader;
        private bool _isInRange;

        protected override void Initialize()
        {
            base.Initialize();

            // Load shader prototypes.
            _inRangeShader = _prototypeManager.Index<IShader>("InRangeOutline");
            _outOfRangeShader = _prototypeManager.Index<IShader>("OutOfRangeOutline");

            // Default to not in range.
            _isInRange = false;
        }

        public void OnMouseEnter()
        {
            if (Owner.TryGetComponent<ISpriteComponent>(out var sprite))
            {
                // Apply the appropriate shader based on current range state.
                sprite.Shader = _isInRange ? _inRangeShader : _outOfRangeShader;

                // Increase rendering order to ensure highlight overlays correctly.
                sprite.Order = sprite.Order + 1;
            }
        }

        public void OnMouseLeave()
        {
            if (Owner.TryGetComponent<ISpriteComponent>(out var sprite))
            {
                // Clear shader effect.
                sprite.Shader = null;

                // Reset rendering order to normal.
                sprite.Order = sprite.Order - 1;
            }
        }

        /// <summary>
        /// Updates the outline shader based on whether the object is in interaction range.
        /// </summary>
        /// <param name="inRange">True if object is in range; otherwise, false.</param>
        public void UpdateInRange(bool inRange)
        {
            // Only update if there is a change in state.
            if (_isInRange == inRange)
                return;

            _isInRange = inRange;

            if (Owner.TryGetComponent<ISpriteComponent>(out var sprite))
            {
                // Check if the cursor is still hovering over the object.
                // If yes, update the shader dynamically.
                if (sprite.Shader != null)
                {
                    sprite.Shader = _isInRange ? _inRangeShader : _outOfRangeShader;
                }
            }
        }
    }
}

