public abstract class ServerChannel : Channel
{
    private bool _isOpen;
    private uint _localWindowSize;
    private uint _remotePacketSize;
    protected Session Session { get; private set; }

    public bool IsOpen => _isOpen;

    protected ServerChannel(Session session, uint localChannelNumber, uint localWindowSize, uint localPacketSize)
        : base(session, localChannelNumber, localWindowSize, localPacketSize)
    {
        Session = session ?? throw new ArgumentNullException(nameof(session));
        _localWindowSize = localWindowSize;
        Session.ChannelWindowAdjustReceived += OnWindowAdjustReceived;
    }

    public void Initialize(uint remoteChannelNumber, uint remoteWindowSize, uint remotePacketSize)
    {
        RemoteChannelNumber = remoteChannelNumber;
        _remotePacketSize = remotePacketSize;
        RemoteWindowSize = remoteWindowSize;

        SendMessage(new ChannelOpenConfirmationMessage(
            RemoteChannelNumber,
            LocalChannelNumber,
            _localWindowSize,
            MaximumPacketSize
        ));

        _isOpen = true;
    }

    protected void SendMessage(Message message)
    {
        Session.SendMessage(message);
    }

    protected override void Dispose(bool disposing)
    {
        if (disposing && Session != null)
        {
            Session.ChannelWindowAdjustReceived -= OnWindowAdjustReceived;
            Session = null;
            _isOpen = false;
        }
        base.Dispose(disposing);
    }

    private void OnWindowAdjustReceived(object sender, MessageEventArgs<ChannelWindowAdjustMessage> e)
    {
        if (e.Message.LocalChannelNumber == LocalChannelNumber)
        {
            _localWindowSize += e.Message.BytesToAdd;
        }
    }

    protected override void OnData(byte[] data)
    {
        // Base implementation for data processing
        // Can be extended in derived classes
    }

    protected override void OnClose()
    {
        if (_isOpen)
        {
            SendMessage(new ChannelCloseMessage(RemoteChannelNumber));
            _isOpen = false;
        }
        base.OnClose();
    }

    // Example extensibility point for channel requests
    // protected virtual void OnChannelRequest(ChannelRequestMessage request)
    // {
    //     // Handle specific channel requests
    // }
}

