namespace NetworkSerialization
{
    // A serializable structure for a 3D vector,
    // compatible with Protocol Buffers and Unity's vector types.
    [ProtoContract]
    public struct SerializableVector3
    {
        // The X component of the vector.
        [ProtoMember(1)]
        public float x;

        // The Y component of the vector.
        [ProtoMember(2)]
        public float y;

        // The Z component of the vector.
        [ProtoMember(3)]
        public float z;

        // Constructor for explicit initialization.
        public SerializableVector3(float x, float y, float z)
        {
            this.x = x;
            this.y = y;
            this.z = z;
        }

        // Conversion from SerializableVector3 to UnityEngine.Vector3.
        public static explicit operator Vector3(SerializableVector3 sv)
        {
            return new Vector3(sv.x, sv.y, sv.z);
        }

        // Conversion from UnityEngine.Vector3 to SerializableVector3.
        public static explicit operator SerializableVector3(Vector3 v)
        {
            return new SerializableVector3(v.x, v.y, v.z);
        }

        // Conversion from SerializableVector3 to UnityEngine.Vector2.
        public static explicit operator Vector2(SerializableVector3 sv)
        {
            return new Vector2(sv.x, sv.y);
        }

        // Conversion from UnityEngine.Vector2 to SerializableVector3.
        // Sets the z component to zero.
        public static explicit operator SerializableVector3(Vector2 v)
        {
            return new SerializableVector3(v.x, v.y, 0f);
        }

        // Override ToString for simple debugging.
        public override string ToString()
        {
            return string.Format("({0}, {1}, {2})", x, y, z);
        }
    }

    // A sample class demonstrating usage of SerializableVector3.
    public class VectorConversionDemo : MonoBehaviour
    {
        // Unity's Start method to initialize the demo.
        void Start()
        {
            // Create a Unity Vector3.
            Vector3 unityVector = new Vector3(1.0f, 2.0f, 3.0f);

            // Cast Unity's Vector3 to SerializableVector3.
            SerializableVector3 serializedVector = (SerializableVector3)unityVector;
            Debug.Log("Serialized Vector from Vector3: " + serializedVector);

            // Convert SerializableVector3 back to Unity's Vector3.
            Vector3 convertedBackVector = (Vector3)serializedVector;
            Debug.Log("Converted Back to Vector3: " + convertedBackVector);

