    private float clipInterval = 10f; // Interval between clips
    private bool[] clipPlayingStatus;

    void Start()
    {
        // Initialize the connection status text
        deviceStatusText.text = "Checking device connection...";

        // Initialize haptic clip status UI
        clipPlayingStatus = new bool[hapticClipNames.Length];
        for (int i = 0; i < clipStatusTexts.Length; i++)
        {
            clipStatusTexts[i].text = $"{hapticClipNames[i]}: Not Playing";
        }

        // Start the haptic clips playback coroutine
        StartCoroutine(PlayClips());
    }

    void Update()
    {
        // Update connection status of haptic devices
        if (Bhaptics.Connected)
        {
            deviceStatusText.text = "Haptic Device: Connected";
        }
        else
        {
            deviceStatusText.text = "Haptic Device: Disconnected";
        }

        // Update the play status of each clip
        for (int i = 0; i < clipPlayingStatus.Length; i++)
        {
            if (clipPlayingStatus[i])
            {
                clipStatusTexts[i].text = $"{hapticClipNames[i]}: Playing";
            }
            else
            {
                clipStatusTexts[i].text = $"{hapticClipNames[i]}: Not Playing";
            }
        }
    }

    private IEnumerator PlayClips()
    {
        while (true)
        {
            for (int i = 0; i < hapticClipNames.Length; i++)
            {
                // Start playback of the haptic clip
                if (Bhaptics.Connected)
                {
                    Bhaptics.Play(hapticClipNames[i]);
                    clipPlayingStatus[i] = true;

                    // Wait for the defined clip play time
                    yield return new WaitForSeconds(clipPlayTime);

                    // Stop playback of the haptic clip
                    Bhaptics.Stop(hapticClipNames[i]);
                    clipPlayingStatus[i] = false;
                }
                else
                {
                    yield return new WaitForSeconds(clipInterval);
                }

                // Wait before playing the next clip
                yield return new WaitForSeconds(clipInterval);
            }
        }
    }
}

