            new[] {"D", "B"}, new[] {"F", "G", "H"}};
        var input = new[] {setCollection1, setCollection2, setCollection3, setCollection4};
 
        foreach (var sets in input) {
            Console.WriteLine("Start sets:");
            Console.WriteLine(string.Join(", ", sets.Select(s => "{" + string.Join(", ", s) + "}")));
            Console.WriteLine("Sets consolidated using Nodes:");
            Console.WriteLine(string.Join(", ", ConsolidateSets1(sets).Select(s => "{" + string.Join(", ", s) + "}")));
            Console.WriteLine("Sets consolidated using Set operations:");
            Console.WriteLine(string.Join(", ", ConsolidateSets2(sets).Select(s => "{" + string.Join(", ", s) + "}")));
            Console.WriteLine();
        }
    }
 
    /// <summary>
    /// Consolidates sets using a connected-component-finding-algorithm involving Nodes with parent pointers.
    /// The more efficient solution, but more elaborate code.
    /// </summary>
    private static IEnumerable<IEnumerable<T>> ConsolidateSets1<T>(IEnumerable<IEnumerable<T>> sets,
        IEqualityComparer<T> comparer = null)
    {
        if (comparer == null) comparer = EqualityComparer<T>.Default;
        var elements = new Dictionary<T, Node<T>>();
        foreach (var set in sets) {
            Node<T> top = null;
            foreach (T value in set) {
                Node<T> element;
                if (elements.TryGetValue(value, out element)) {
                    if (top != null) {
                        var newTop = element.FindTop();
                        top.Parent = newTop;
                        element.Parent = newTop;
                        top = newTop;
                    } else {
                        top = element.FindTop();
                    }
                } else {
                    elements.Add(value, element = new Node<T>(value));
                    if (top == null) top = element;
                    else element.Parent = top;
                }
            }
        }
        foreach (var g in elements.Values.GroupBy(element => element.FindTop().Value))

using System;
using System.Collections.Generic;
using System.Threading.Tasks;

public interface IStateManager
{
    event Action<string, object> StateChanged;
    IDictionary<string, object> GetCurrentStates();
}

public interface IStateBinder
{
    Task BindAsync(string groupName, object stateValue);
    Task UnbindAsync(string groupName);
}

public class StateManagerBinder : IStateBinder
{
    private readonly IStateManager _sourceManager;
    private readonly IStateManager _targetManager;
    private readonly bool _mutualUpdates;
    private readonly List<(string groupName, object sourceState, object targetState)> _groupBinders;

    public StateManagerBinder(IStateManager sourceManager, IStateManager targetManager, bool mutualUpdates)
    {
        _sourceManager = sourceManager;
        _targetManager = targetManager;
        _mutualUpdates = mutualUpdates;
        _groupBinders = new List<(string, object, object)>();

        _sourceManager.StateChanged += OnSourceStateChanged;
        if (_mutualUpdates)
        {
            _targetManager.StateChanged += OnTargetStateChanged;
        }
    }

    private async void OnSourceStateChanged(string groupName, object stateValue)
    {
        await InternalBind(groupName, stateValue, _targetManager);
    }

    private async void OnTargetStateChanged(string groupName, object stateValue)
    {
        await InternalBind(groupName, stateValue, _sourceManager);
    }

    public async Task BindAsync(string groupName, object stateValue)
    {
        await InternalBind(groupName, stateValue, _targetManager);
    }

    private async Task InternalBind(string groupName, object stateValue, IStateManager targetManager)
    {
        _groupBinders.Add((groupName, stateValue, targetManager.GetCurrentStates().GetValueOrDefault(groupName)));
        await targetManager.StateChanged.Invoke(groupName, stateValue);
    }

    public async Task UnbindAsync(string groupName)
    {
        await InternalUnbind(groupName);
    }

    private async Task InternalUnbind(string groupName)
    {
        foreach (var binder in _groupBinders)
        {
            if (binder.groupName == groupName)
            {
                await _targetManager.StateChanged.Invoke(groupName, null);
            }
        }
        _groupBinders.RemoveAll(b => b.groupName == groupName);
    }

    public void ClearBindings()
    {
        _groupBinders.Clear();
    }
}

