public class RewardBasedVideoAdManager : IRewardBasedVideoAdClient
{
    private RewardBasedVideoAd _rewardBasedVideoAd;
    private string _adUnitId;

    public event EventHandler<EventArgs> OnAdLoaded;
    public event EventHandler<AdFailedToLoadEventArgs> OnAdFailedToLoad;
    public event EventHandler<EventArgs> OnAdOpened;
    public event EventHandler<EventArgs> OnAdClosed;
    public event EventHandler<EventArgs> OnAdStarted;
    public event EventHandler<EventArgs> OnAdRewarded;
    public event EventHandler<EventArgs> OnAdLeftApplication;

    public void CreateRewardBasedVideoAd(string adUnitId)
    {
        _adUnitId = adUnitId;
        _rewardBasedVideoAd = RewardBasedVideoAd.Instance;

        _rewardBasedVideoAd.OnAdLoaded += HandleAdLoaded;
        _rewardBasedVideoAd.OnAdFailedToLoad += HandleAdFailedToLoad;
        _rewardBasedVideoAd.OnAdOpened += HandleAdOpened;
        _rewardBasedVideoAd.OnAdClosed += HandleAdClosed;
        _rewardBasedVideoAd.OnAdStarted += HandleAdStarted;
        _rewardBasedVideoAd.OnAdRewarded += HandleAdRewarded;
        _rewardBasedVideoAd.OnAdLeftApplication += HandleAdLeftApplication;
    }

    public void LoadAd(AdRequest request)
    {
        _rewardBasedVideoAd.LoadAd(request, _adUnitId);
    }

