namespace Reusable.ExceptionTesting
{
    public interface IPhantomException
    {
        void Throw();
    }

    public class PhantomException : IPhantomException
    {
        private readonly List<ITrigger> _triggers;

        public PhantomException(List<ITrigger> triggers)
        {
            _triggers = triggers;
        }

        public void Throw()
        {
            foreach (var trigger in _triggers)
            {
                if (trigger.ConditionMet())
                {
                    throw new InvalidOperationException(trigger.Name);
                }
            }
        }
    }

    public interface ITrigger
    {
        string Name { get; }
        bool ConditionMet();
    }

    public class CountedTrigger : ITrigger
    {
        private static int _count = 0;
        private readonly int _threshold;

        public string Name { get; }

        public CountedTrigger(string name, int threshold)
        {
            Name = name;
            _threshold = threshold;
        }

        public bool ConditionMet()
        {
            _count++;
            return _count >= _threshold;
        }
    }

    public class PhantomExceptionTest
    {
        private int _exceptionCount;

        [Fact]
        public void TestCountedTriggerThrowsExceptions()
        {
            var triggers = new List<ITrigger>
            {
                new CountedTrigger("FirstTrigger", 5),
                new CountedTrigger("SecondTrigger", 3)
            };

            var phantomException = new PhantomException(triggers);
            _exceptionCount = 0;

            for (int i = 0; i < 10; i++)
            {
                try
                {
                    phantomException.Throw();
                }
                catch (InvalidOperationException ex)
                {
                    if (NameMatches(ex.Message, "FirstTrigger"))
                    {
                        _exceptionCount++;
                    }
                }
            }

            Assert.Equal(2, _exceptionCount);
        }

        private bool NameMatches(string exceptionName, string pattern)
        {
            return Regex.IsMatch(exceptionName, pattern, RegexOptions.IgnoreCase);
        }

        [Fact]
        public void TestMultipleTriggersThrowing()
        {
            var triggers = new List<ITrigger>
            {
                new CountedTrigger("ErrorA", 1),
                new CountedTrigger("ErrorB", 2)
            };

