using System;
using System.Collections.Generic;
using bsn.GoldParser.Semantic;
using System.Linq;

namespace bsn.GoldParser.Semantic
{
    public interface IOptional
    {
        bool HasValue { get; }
    }

    public class TableHintGroup : SqlScriptableToken, IOptional
    {
        private readonly IList<TableHint> hints;

        public bool HasValue { get { return hints.Count > 0; } }

        public TableHintGroup(IEnumerable<TableHint> hints)
        {
            this.hints = hints.ToList();
        }

        public override void WriteTo(System.IO.TextWriter writer)
        {
            if (HasValue)
            {
                writer.WriteKeyword("WITH");
                writer.Write(WhitespacePadding.Space);
                writer.Write('(');
                writer.WriteScriptSequence(hints, ",");
                writer.Write(')');
            }
        }
    }

    public static class TextWriterExtensions
    {
        public static void WriteKeyword(this System.IO.TextWriter writer, string keyword)
        {
            writer.Write(keyword);
        }

        public static void WriteScriptSequence<T>(this System.IO.TextWriter writer, IEnumerable<T> items, string separator)
            where T : SqlScriptableToken
        {
            bool first = true;
            foreach (var item in items)
            {
                if (!first)
                {
                    writer.Write(separator);
                }
                item.WriteTo(writer);
                first = false;
            }
        }
    }

    public struct WhitespacePadding
    {
        public static readonly string Space = " ";
    }
}

using System;
