namespace DiagnosticFramework
{
    // Event arguments class encapsulating evaluation details.
    public class EvaluationEventArgs : EventArgs
    {
        private readonly Expression _expression;
        private readonly Exception _exception;
        private readonly object _result;
        private readonly object[] _arguments;
        private readonly IArgumentsProvider _lazyArgumentsProvider;

        // Gets the expression that triggered the event.
        public Expression Expression
        {
            get { return _expression; }
        }

        // Gets any exception that occurred during evaluation.
        public Exception Exception
        {
            get { return _exception; }
        }

        // Gets the result of the evaluation.
        public object Result
        {
            get { return _result; }
        }

        // Gets the arguments used for evaluation.
        public IEnumerable<object> Arguments
        {
            get
            {
                if (_lazyArgumentsProvider != null)
                    return _lazyArgumentsProvider.GetArguments();
                return _arguments;
            }
        }

        // Constructor accepting an immediate array of arguments.
        public EvaluationEventArgs(Expression expression, Exception exception, object[] arguments, object result)
        {
            if (expression == null)
                throw new ArgumentNullException(nameof(expression));

            _expression = expression;
            _exception = exception;
            _arguments = arguments ?? Array.Empty<object>();
            _result = result;
        }

        // Internal constructor accepting a lazy arguments provider.
        internal EvaluationEventArgs(Expression expression, Exception exception, IArgumentsProvider lazyArgumentsProvider, object result)
        {
            if (expression == null)
                throw new ArgumentNullException(nameof(expression));

            _expression = expression;
            _exception = exception;
            _lazyArgumentsProvider = lazyArgumentsProvider;
            _result = result;
        }
    }

