using System;
using System.Collections.Generic;
using System.Data.Entity;

public class BullsAndCowsData : IDisposable
{
    private readonly ApplicationDbContext context;
    private readonly IDictionary<Type, object> repositories;

    public BullsAndCowsData(ApplicationDbContext context = null)
    {
        this.context = context ?? new ApplicationDbContext();
        this.repositories = new Dictionary<Type, object>();
    }

    public IRepository<Player> Players => GetRepository<Player>();
    public IRepository<Game> Games => GetRepository<Game>();
    public IRepository<Guess> Guesses => GetRepository<Guess>();
    public IRepository<Notification> Notifications => GetRepository<Notification>();

    public IRepository<T> GetRepository<T>() where T : class
    {
        var type = typeof(T);
        if (!repositories.ContainsKey(type))
        {
            var repositoryType = typeof(EFRepository<T>);
            var repositoryInstance = Activator.CreateInstance(repositoryType, context);
            repositories.Add(type, repositoryInstance);
        }
        return (IRepository<T>)repositories[type];
    }

    public int SaveChanges()
    {
        return context.SaveChanges();
    }

    public void Dispose()
    {
        if (context != null)
        {
            context.Dispose();
        }
    }
}

public interface IRepository<T> where T : class
{
    IEnumerable<T> GetAll();
    T GetById(int id);
    void Add(T entity);
    void Update(T entity);
    void Delete(T entity);
}

public class EFRepository<T> : IRepository<T> where T : class
{
    private readonly ApplicationDbContext context;
    private readonly DbSet<T> dbSet;

    public EFRepository(ApplicationDbContext context)
    {
        this.context = context;
        this.dbSet = context.Set<T>();
    }

    public IEnumerable<T> GetAll()
    {
        return dbSet;
    }

    public T GetById(int id)
    {
        return dbSet.Find(id);
    }

    public void Add(T entity)
    {
        dbSet.Add(entity);
    }

    public void Update(T entity)
    {
        context.Entry(entity).State = EntityState.Modified;
    }

    public void Delete(T entity)
    {
        dbSet.Remove(entity);
    }
}

