    /// <summary>
    /// The Utils class contains a variety of utility methods for use in application and grain code.
    /// </summary>
    public static class Utils
    {
        /// <summary>
        /// Returns a human-readable text string that describes an IEnumerable collection of objects.
        /// </summary>
        /// <typeparam name="T">The type of the list elements.</typeparam>
        /// <param name="collection">The IEnumerable to describe.</param>
        /// <returns>A string assembled by wrapping the string descriptions of the individual
        /// elements with square brackets and separating them with commas.</returns>
        public static string EnumerableToString<T>(IEnumerable<T> collection, Func<T, string> toString = null,
                                                        string separator = ", ", bool putInBrackets = true)
        {
            if (collection == null)
            {
                if (putInBrackets) return "[]";
                else return "null";
            }
            var sb = new StringBuilder();
            if (putInBrackets) sb.Append("[");
            var enumerator = collection.GetEnumerator();
            bool firstDone = false;
            while (enumerator.MoveNext())
            {
                T value = enumerator.Current;
                string val;
                if (toString != null)
                    val = toString(value);
                else
                    val = value == null ? "null" : value.ToString();

                if (firstDone)
                {
                    sb.Append(separator);
                    sb.Append(val);
                }
                else
                {
                    sb.Append(val);
                    firstDone = true;
                }
            }
            if (putInBrackets) sb.Append("]");
            return sb.ToString();
        }

        /// <summary>
        /// Returns a human-readable text string that describes a dictionary that maps objects to objects.
        /// </summary>
        /// <typeparam name="T1">The type of the dictionary keys.</typeparam>
        /// <typeparam name="T2">The type of the dictionary elements.</typeparam>
        /// <param name="separateWithNewLine">Whether the elements should appear separated by a new line.</param>
        /// <param name="dict">The dictionary to describe.</param>

using System;
using System.Linq;
using System.Collections.Generic;
 
public class Order
{
    public static void Main() {
        var oids = new [] {
            "1.3.6.1.4.1.11.2.17.19.3.4.0.10",
            "1.3.6.1.4.1.11.2.17.5.2.0.79",
            "1.3.6.1.4.1.11.2.17.19.3.4.0.4",
            "1.3.6.1.4.1.11150.3.4.0.1",
            "1.3.6.1.4.1.11.2.17.19.3.4.0.1",
            "1.3.6.1.4.1.11150.3.4.0"
        };
 
        var comparer = Comparer<string>.Create((a, b) => {
            int c = a.Split('.').Select(int.Parse)
            .Zip(b.Split('.').Select(int.Parse),
                    (i, j) => i.CompareTo(j)).FirstOrDefault(x => x != 0);
            return c != 0 ? c : a.Length.CompareTo(b.Length);
        });
 
        Array.Sort(oids, comparer);
 
        Console.WriteLine(string.Join(Environment.NewLine, oids));
    }
}

using System;
using Emgu.CV;
using Emgu.CV.Features2D;
using Emgu.CV.Structure;
using System.Runtime.InteropServices;

public class Brisk : Feature2D, IDisposable
{
    private IntPtr _ptr;
    private bool _disposed = false;

    // Constructor for the BRISK feature detector
    public Brisk(double threshold = 30, int octaves = 3, float patternScale = 1.0f)
    {
        _ptr = CvInvoke.CvBriskCreate(threshold, octaves, patternScale);
        if (_ptr == IntPtr.Zero)
        {
            throw new InvalidOperationException("Failed to create BRISK detector.");
        }
    }

    // Method to detect keypoints and compute descriptors
    public void DetectAndCompute(IInputArray image, IInputArray mask, VectorOfKeyPoint keypoints, Mat descriptors)
    {
        if (_disposed)
            throw new ObjectDisposedException(nameof(Brisk));

        if (image == null)
            throw new ArgumentNullException(nameof(image));

        CvInvoke.CvBriskDetectAndCompute(_ptr, image, mask, keypoints);
        CvInvoke.CvBriskCompute(_ptr, image, keypoints, descriptors);
    }

    // Dispose method for clean-up and resource management
    protected virtual void Dispose(bool disposing)
    {
        if (!_disposed)
        {
            if (disposing)
            {
                // Managed resource clean-up
            }
            if (_ptr != IntPtr.Zero)
            {
                CvInvoke.CvReleaseObject(ref _ptr);
                _ptr = IntPtr.Zero;
            }
            _disposed = true;
        }
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    // Destructor to ensure resources are released
    ~Brisk()
    {
        Dispose(false);
    }

    // Static method to create an instance of BRISK
    public static Brisk Create(double threshold = 30, int octaves = 3, float patternScale = 1.0f)
    {
        return new Brisk(threshold, octaves, patternScale);
    }
}

