namespace Rextester
{
    public class Employee
    {
        public static void Main(string[] args)
        {
            Func<int, string> ordinalAbbrev = (int i) =>
            {
                if (i % 100 / 10 == 1)
                {
                    return "th";
                }
                else
                {
                    switch (i % 10)
                    {
                        case 1:
                            return "st";
                        case 2:
                            return "nd";
                        case 3:
                            return "rd";
                        default:
                            return "th";
                    }
                }
            };
            Func<IEnumerable<int>, string> ordinalAbbrev2 = (IEnumerable<int> i) =>
            {
                return string.Join(" ", i.Select(x => x.ToString() + ordinalAbbrev(x)));
            };
            var list = new List<IEnumerable<int>> { Enumerable.Range(0, 25), Enumerable.Range(250, 15), Enumerable.Range(1000, 25) };
            foreach (var item in list)
            {
                Console.WriteLine(ordinalAbbrev2(item));
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

/// <summary>
/// Add functionality to the phonebook from the previous task to print all
/// contacts ordered lexicographically when receive the command “ListAll”.
/// </summary>
public class PhonebookUpgrade
{
    public static void Main()
    {
        string command = string.Empty;
        SortedDictionary<string, string> phonebook = new SortedDictionary<string, string>();

        while (command != "END")
        {
            List<string> input = Console.ReadLine()
                .Split(new char[] { ' ' }, StringSplitOptions
                .RemoveEmptyEntries)
                .ToList();

            command = input[0];

            if (command == "A")
            {
                string value;
                bool phoneExists = phonebook.TryGetValue(input[1], out value);
                if (phoneExists == false)
                {
                    phonebook.Add(input[1], input[2]);
                }
                else
                {
                    phonebook[input[1]] = input[2];
                }
            }

            if (command == "S")
            {
                string value;
                bool phoneExists = phonebook.TryGetValue(input[1], out value);
                if (phoneExists == false)
                {
                    Console.WriteLine($"Contact {input[1]} does not exist.");
                }
                else
                {
                    Console.WriteLine($"{input[1]} -> {phonebook[input[1]]}");
                }
            }

            if (command == "ListAll")
            {
                foreach (KeyValuePair<string,string> kvp in phonebook)
                {
                    Console.WriteLine($"{kvp.Key} -> {kvp.Value}");
                }
            }
        }
    }
}

