namespace PropertyGraphTraversal
{
    // Interface for property visitor
    public interface IPropertyVisitor
    {
        void Visit(PropertyInfo property);
    }

    // Interface for factory that creates property visitors
    public interface IPropertyVisitorFactory
    {
        IPropertyVisitor GetVisitor(Type type);
    }

    // Main class for traversing a type's property graph
    public static class PropertyGraphExplorer
    {
        // Binding flags to fetch both public and non-public instance properties
        private const BindingFlags FLAGS = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance;

        // Public method to initiate traversal of a type's properties
        public static void TraverseProperties(Type type, IPropertyVisitorFactory factory)
        {
            var visitedTypes = new HashSet<Type>();
            TraverseRecursive(type, factory, visitedTypes);
        }

        // Recursive method that processes each property and its property types
        private static void TraverseRecursive(Type type, IPropertyVisitorFactory factory, HashSet<Type> visited)
        {
            if (visited.Contains(type))
            {
                return;
            }
            visited.Add(type);

            IPropertyVisitor visitor = factory.GetVisitor(type);
            if (visitor == null)
            {
                throw new InvalidOperationException($"No visitor available for type {type.FullName}");
            }

            PropertyInfo[] properties = type.GetProperties(FLAGS);
            foreach (PropertyInfo property in properties)
            {
                visitor.Visit(property);

                // Recursively traverse the property's type if not yet visited
                Type propType = property.PropertyType;
                if (!visited.Contains(propType))
                {
                    TraverseRecursive(propType, factory, visited);
                }
            }
        }
    }

    // Sample visitor that writes property name and type to the console.
    public class SimplePropertyVisitor : IPropertyVisitor
    {
        public void Visit(PropertyInfo property)
        {
            Console.WriteLine($"Visiting Property: {property.Name}, Type: {property.PropertyType.FullName}");
        }
    }

    // Simple factory that creates a SimplePropertyVisitor for any type.
    public class SimplePropertyVisitorFactory : IPropertyVisitorFactory
    {
        public IPropertyVisitor GetVisitor(Type type)
        {

