using Autofac;
using JetBrains.ReSharper.Feature.Services.StructuralSearch;
using System.Collections.Generic;

public class InNamespaceString : MultipleMatchBasedOnPatternBase
{
    private const string pattern = "InNamespace($namespace$)";
    private readonly List<FilteredRegistrationBase> registrations = new List<FilteredRegistrationBase>();

    public InNamespaceString()
    {
        ConfigureSearchPattern();
    }

    protected override void ConfigureSearchPattern()
    {
        var searchPattern = new SearchPattern(pattern);
        searchPattern.OnMatch += OnMatchFound;
        this.StartSearch(searchPattern);
    }

    private void OnMatchFound(SearchResult match)
    {
        var namespaceString = ExtractNamespaceFromMatch(match);
        if (!string.IsNullOrEmpty(namespaceString))
        {
            var registration = CreateRegistration(namespaceString);
            registrations.Add(registration);
        }
    }

    private string ExtractNamespaceFromMatch(SearchResult match)
    {
        var namespaceExpression = match.GetExpression("namespace");
        return namespaceExpression?.ToString() ?? string.Empty;
    }

    private FilteredRegistrationBase CreateRegistration(string namespaceString)
    {
        return new FilteredRegistrationBase
        {
            Namespace = namespaceString,
            // Additional registration configuration can be done here
        };
    }

    public IEnumerable<FilteredRegistrationBase> GetRegistrations()
    {
        return registrations;
    }
}

