namespace Finder
{
    class Cache
    {
        static void Main(string[] args)
        {
            Console.WriteLine("Set [0,25]:");
            for (int i = 0; i < 26; i++)
                Console.Write(i + Suffix(i) + " ");

            Console.WriteLine();

            Console.WriteLine("Set [250,265]:");
            for (int i = 250; i < 266; i++)
                Console.Write(i + Suffix(i) + " ");

            Console.WriteLine();

            Console.WriteLine("Set [1000,1025]:");
            for (int i = 1000; i < 1026; i++)
                Console.Write(i + Suffix(i) + " ");

            Console.WriteLine();

            Console.ReadKey();
        }

        static string Suffix(int num)
        {
            switch (num % 10)
            {
                case 1:
                    if (num % 100!= 11)
                        return "st";
                    break;
                case 2:
                    if (num % 100!= 12)
                        return "nd";
                    break;
                case 3:
                    if (num % 100!= 13)
                        return "rd";
                    break;
            }

            return "th";
        }
    }
}

using System;
 
public class GeneralFizzBuzz
{
    public static void Main()
    {
        int i;
        int j;
        int k;
 
        int limit;
 
        string iString;
        string jString;
        string kString;
 
        Console.WriteLine("First integer:");
        i = Convert.ToInt32(Console.ReadLine());
        Console.WriteLine("First string:");
        iString = Console.ReadLine();
 
        Console.WriteLine("Second integer:");
        j = Convert.ToInt32(Console.ReadLine());
        Console.WriteLine("Second string:");
        jString = Console.ReadLine();
 
        Console.WriteLine("Third integer:");
        k = Convert.ToInt32(Console.ReadLine());
        Console.WriteLine("Third string:");
        kString = Console.ReadLine();
 
        Console.WriteLine("Limit (inclusive):");
        limit = Convert.ToInt32(Console.ReadLine());
 
        for(int n = 1; n<= limit; n++)
        {
            bool flag = true;
            if(n%i == 0)
            {
                Console.Write(iString);
                flag = false;
            }
 
            if(n%j == 0)
            {
                Console.Write(jString);
                flag = false;
            }
 
            if(n%k == 0)
            {
                Console.Write(kString);
                flag = false;
            }
            if(flag)
                Console.Write(n);
            Console.WriteLine();
        }
    }
}

using UnityEngine;
using ColossalFramework;
using System;

namespace AmbulanceMod
{
    public static class AmbulanceHelper
    {
        private const Vehicle.Flags OperationalFlags = Vehicle.Flags.GoingBack |
                                                      Vehicle.Flags.WaitingTarget |
                                                      Vehicle.Flags.Emergency2;

        public static bool IsConfused(Vehicle vehicle)
        {
            try
            {
                if (vehicle == null)
                {
                    Debug.LogError("[AmbulanceHelper] Null vehicle reference.");
                    return false;
                }

                if (!IsValidAmbulance(vehicle))
                {
                    Debug.LogWarning($"[AmbulanceHelper] Vehicle {vehicle.m_instanceID} is not an ambulance.");
                    return false;
                }

                if (vehicle.m_targetBuilding == 0)
                {
                    Debug.Log($"[AmbulanceHelper] Ambulance {vehicle.m_instanceID} has invalid target.");
                    return true;
                }

                bool hasActiveFlags = (vehicle.m_flags & OperationalFlags) != 0;
                bool isConfused = !hasActiveFlags;

                if (isConfused)
                {
                    Debug.Log($"[AmbulanceHelper] Ambulance {vehicle.m_instanceID} is confused: No active task flags.");
                }

                return isConfused;
            }
            catch (Exception e)
            {
                Debug.LogError($"[AmbulanceHelper] Error: {e.Message}");
                return false;
            }
        }

        private static bool IsValidAmbulance(Vehicle vehicle)
        {
            try
            {
                return vehicle.Info?.m_vehicleAI is AmbulanceAI;
            }
            catch
            {
                return false;
            }
        }
    }
}

