            Console.WriteLine(string.Join(",", r2cf(13, 11)));
            Console.WriteLine(string.Join(",", r2cf(22, 7)));
            Console.WriteLine(string.Join(",", r2cf(14142, 10000)));
            Console.WriteLine(string.Join(",", r2cf(141421, 100000)));
            Console.WriteLine(string.Join(",", r2cf(1414214, 1000000)));
            Console.WriteLine(string.Join(",", r2cf(14142136, 10000000)));
            Console.ReadLine();
        }
