using System;
using System.Linq;
using System.Collections.Generic;
 
public class Order
{
    public static void Main()
    {
        const int maxSum = 100;
        var pairs = (
            from X in 2.To(maxSum / 2 - 1)
            from Y in (X + 1).To(maxSum - 2).TakeWhile(y => X + y <= maxSum)
            select new { X, Y, S = X + Y, P = X * Y }
            ).ToHashSet();
 
        Console.WriteLine(pairs.Count);
 
        var uniqueP = pairs.GroupBy(pair => pair.P).Where(g => g.Count() == 1).Select(g => g.Key).ToHashSet();
 
        pairs.ExceptWith(pairs.GroupBy(pair => pair.S).Where(g => g.Any(pair => uniqueP.Contains(pair.P))).SelectMany(g => g));
        Console.WriteLine(pairs.Count);
 
        pairs.ExceptWith(pairs.GroupBy(pair => pair.P).Where(g => g.Count() > 1).SelectMany(g => g));
        Console.WriteLine(pairs.Count);
 
        pairs.ExceptWith(pairs.GroupBy(pair => pair.S).Where(g => g.Count() > 1).SelectMany(g => g));
        Console.WriteLine(pairs.Count);
 
        foreach (var pair in pairs) Console.WriteLine(pair);
    }
}
 
public static class Extensions
{
    public static IEnumerable<int> To(this int start, int end) {
        for (int i = start; i <= end; i++) yield return i;
    }
 
    public static HashSet<T> ToHashSet<T>(this IEnumerable<T> source) => new HashSet<T>(source);
}

using System;
using System.Linq;
using dnSpy.Contracts.Debugger;
using dnSpy.Contracts.Debugger.Engine.Evaluation;
using dnSpy.Contracts.Debugger.Evaluation;

namespace Debugger.Utilities
{
    public static class DbgValueNodeUtils
    {
        public static DbgValueNode[] ToValueNodeArray(
            DbgEngineValueNode[] engineNodes,
            DbgEvaluationContext context)
        {
            if (engineNodes == null || context == null)
                return Array.Empty<DbgValueNode>();

            return engineNodes
                .Select(engineNode => CreateValueNode(engineNode, context))
                .Where(node => node != null)
                .ToArray();
        }

        public static DbgLocalsValueNodeInfo[] ToLocalsValueNodeInfoArray(
            DbgEngineLocalsValueNodeInfo[] engineLocalsNodes,
            DbgEvaluationContext context)
        {
            if (engineLocalsNodes == null || context == null)
                return Array.Empty<DbgLocalsValueNodeInfo>();

            return engineLocalsNodes
                .Select(engineLocalsNode => CreateLocalsValueNodeInfo(engineLocalsNode, context))
                .Where(info => info != null)
                .ToArray();
        }

        private static DbgValueNode CreateValueNode(
            DbgEngineValueNode engineNode,
            DbgEvaluationContext context)
        {
            if (engineNode == null)
                return null;

            try
            {
                return new DbgValueNodeImpl(
                    engineNode,
                    context,
                    engineNode.Name,
                    engineNode.Type,
                    engineNode.GetValue());
            }
            catch (Exception)
            {
                return null;
            }
            finally
            {
                engineNode?.Close();
            }
        }

        private static DbgLocalsValueNodeInfo CreateLocalsValueNodeInfo(
            DbgEngineLocalsValueNodeInfo engineLocalsNode,
            DbgEvaluationContext context)
        {
            if (engineLocalsNode == null)
                return null;

            try
            {
                return new DbgLocalsValueNodeInfo(
                    engineLocalsNode.Name,
                    CreateValueNode(engineLocalsNode.Value, context));
            }
            catch (Exception)
            {
                return null;
            }
            finally
            {
                engineLocalsNode?.Value?.Close();
            }
        }
    }
}

