        if (!inspectedObjects.Contains(target))
        {
            inspectedObjects.Add(target);
            RefreshInspector();
        }
    }

    public virtual void RemoveInspect(object target)
    {
        inspectedObjects.Remove(target);
        RefreshInspector();
    }

    protected virtual void RefreshInspector()
    {
        if (!uiInitialized)
        {
            InitializeVisibilityComponents();
            uiInitialized = true;
        }
    }

    private void InitializeVisibilityComponents()
    {
        VisibilityOptionsLoaded = true;
        EVisibilityLayers_Initialized = true;
        VisibilityClassLoaded = true;
    }

    public virtual void ApplyChanges()
    {
        foreach (var obj in inspectedObjects)
        {
            SyncObjectState(obj);
        }
    }

    public void ToggleGroupScript(string groupName, bool expanded)
    {
        groupStates[groupName] = expanded;
        RebuildGroupLayout();
    }

    private void RebuildGroupLayout()
    {
        foreach (var group in groupStates)
        {
            // Engine-specific UI layout update logic
        }
    }

    public void SetObjectField(string fieldName, object value)
    {
        undoSystem.BeginOperation("Field Modification");

        foreach (var obj in inspectedObjects)
        {
            PropertyInfo prop = obj.GetType().GetProperty(fieldName);
            if (prop != null && prop.CanWrite)
            {
                undoSystem.RecordState(obj, fieldName, prop.GetValue(obj));
                prop.SetValue(obj, value);
            }
        }

        undoSystem.CommitOperation();
        ApplyChanges();
    }

    private void SyncObjectState(object target)
    {
        // Property synchronization logic with engine backend
    }
}

