using System;
using System.Drawing;
using System.Linq;

public class InterceptOrder : MoveOrder
{
    private Ship _target;
    private bool _changeTarget;
    public PointF OrderPosition { get; private set; }
    public bool OrderComplete { get; private set; }

    public InterceptOrder(Ship target, bool changeTarget = false)
    {
        _target = target;
        _changeTarget = changeTarget;
        OrderComplete = false;
    }

    public override void Update(Ship ship)
    {
        if (_target == null || !_target.Active || _target.SectorId != ship.SectorId)
        {
            if (_changeTarget)
            {
                var validTargets = StrategyGame.GetUnitsInSector(ship.SectorId)
                    .Where(u => u.Active && u.Alliance != ship.Alliance)
                    .ToList();

                if (validTargets.Any())
                {
                    _target = validTargets[RandomItem(validTargets.Count)];
                }
                else
                {
                    OrderComplete = true;
                    if (ship.Type == ShipType.Lifepod)
                    {
                        ship.Dock();
                    }
                    return;
                }
            }
            else
            {
                OrderComplete = true;
                return;
            }
        }

        OrderPosition = _target.Center;
        if (ship.Position == OrderPosition)
        {
            OrderComplete = true;
        }
    }

    public override void Draw(Graphics g, PointF fromPos, int fromSectorId)
    {
        if (_target != null && _target.SectorId == fromSectorId)
        {
            using (var pen = new Pen(Color.LightGray, 2))
            {
                g.DrawLine(pen, fromPos, _target.Center);
            }
        }
    }

    private int RandomItem(int count)
    {
        return new Random().Next(count);
    }
}

public static class ShellSorter
{
    public static void Sort<T>(IList<T> list) where T : IComparable
    {
        int n = list.Count;
        int h = 1;
 
        while (h < (n >> 1))
        {
            h = (h << 1) + 1;
        }
 
        while (h >= 1)
        {
            for (int i = h; i < n; i++)
            {
                int k = i - h;
                for (int j = i; j >= h && list[j].CompareTo(list[k]) < 0; k -= h)
                {
                    T temp = list[j];
                    list[j] = list[k];
                    list[k] = temp;
                    j = k;
                }
            }
            h >>= 1;
        }
    }
}

