namespace Azure.Security.RedisCache
{
    /// <summary>
    /// Represents authentication keys for Redis cache access management
    /// </summary>
    public class RedisAccessKeys
    {
        // Private backing fields for key storage
        private readonly string _primaryKey;
        private readonly string _secondaryKey;

        /// <summary>
        /// Initializes a new instance of RedisAccessKeys
        /// </summary>
        /// <param name="primaryKey">The primary authentication key</param>
        /// <param name="secondaryKey">The secondary authentication key</param>
        public RedisAccessKeys(string primaryKey, string secondaryKey)
        {
            // Validate input keys
            if (string.IsNullOrWhiteSpace(primaryKey))
            {
                throw new ArgumentException("Primary key cannot be null or empty", nameof(primaryKey));
            }

            if (string.IsNullOrWhiteSpace(secondaryKey))
            {
                throw new ArgumentException("Secondary key cannot be null or empty", nameof(secondaryKey));
            }

            _primaryKey = primaryKey;
            _secondaryKey = secondaryKey;
        }

        /// <summary>
        /// Gets the primary authentication key
        /// </summary>
        public string PrimaryKey
        {
            get => _primaryKey;
        }

        /// <summary>
        /// Gets the secondary authentication key
        /// </summary>
        public string SecondaryKey
        {
            get => _secondaryKey;
        }

        /// <summary>
        /// Validates the provided authentication key
        /// </summary>
        /// <param name="key">The key to validate</param>
        /// <returns>True if the key matches either primary or secondary key, otherwise false</returns>
        public bool ValidateKey(string key)
        {
            if (string.IsNullOrWhiteSpace(key))
            {
                return false;
            }

            return key == _primaryKey || key == _secondaryKey;
        }

        /// <summary>
        /// Rotates the authentication keys
        /// </summary>
        /// <returns>A new RedisAccessKeys instance with rotated keys</returns>
        public RedisAccessKeys RotateKeys()
        {
            return new RedisAccessKeys(
                primaryKey: _secondaryKey,
                secondaryKey: GenerateNewKey()
            );
        }

        /// <summary>
        /// Generates a new random authentication key
        /// </summary>

