public class TableBuilder
{
    private Table _table;

    public TableBuilder()
    {
        _table = new Table();
    }

    public TableBuilder AddLine(string title, string data)
    {
        _table.AddLine(title, data);
        return this;
    }

    public string Build()
    {
        return _table.ToString();
    }
}

public class Table
{
    private List<TableLine> _lines;
    private int _titleColumnMinWidth;
    private int _dataColumnMinWidth;
    private const char hLineSymbol = '-';
    private const char vLineSymbol = '|';

    public Table()
    {
        _lines = new List<TableLine>();
        _titleColumnMinWidth = 0;
        _dataColumnMinWidth = 0;
    }

    public void AddLine(string title, string data)
    {
        _lines.Add(new TableLine(title, data));
        _titleColumnMinWidth = Math.Max(_titleColumnMinWidth, title.Length);
        _dataColumnMinWidth = Math.Max(_dataColumnMinWidth, data.Length);
    }

    public override string ToString()
    {
        StringBuilder sb = new StringBuilder();
        int totalWidth = _titleColumnMinWidth + _dataColumnMinWidth + 3;
        sb.AppendLine(new string(hLineSymbol, totalWidth));

        foreach (var line in _lines)
        {
            sb.Append(vLineSymbol);
            sb.Append(line.Title.PadRight(_titleColumnMinWidth));
            sb.Append(vLineSymbol);
            sb.Append(line.Data.PadRight(_dataColumnMinWidth));
            sb.AppendLine(vLineSymbol);
            sb.AppendLine(new string(hLineSymbol, totalWidth));
        }

        return sb.ToString();
    }
}

public class TableLine
{
    public string Title { get; }
    public string Data { get; }

    public TableLine(string title, string data)
    {
        Title = title;
        Data = data;
    }
}

