namespace MyApp.ViewModels
{
    public class SimpleHeaderViewModel : Screen
    {
        private readonly ICoreService _coreService;
        private readonly IDebugService _debugService;
        private Timer _frameTimeUpdateTimer;
        private string _frameTime;

        public string FrameTime
        {
            get => _frameTime;
            private set
            {
                if (_frameTime != value)
                {
                    _frameTime = value;
                    NotifyOfPropertyChange(() => FrameTime);
                }
            }
        }

        public SimpleHeaderViewModel(ICoreService coreService, IDebugService debugService)
        {
            _coreService = coreService ?? throw new ArgumentNullException(nameof(coreService));
            _debugService = debugService ?? throw new ArgumentNullException(nameof(debugService));
        }

        protected override void OnInitialActivate()
        {
            base.OnInitialActivate();
            // Initialize a timer to update frame time every 500ms.
            _frameTimeUpdateTimer = new Timer(500);
            _frameTimeUpdateTimer.Elapsed += OnFrameTimeUpdate;
            _frameTimeUpdateTimer.AutoReset = true;
            _frameTimeUpdateTimer.Start();

            // Initial frame time update.
            UpdateFrameTime();
        }

        protected override void OnClose()
        {
            base.OnClose();
            if (_frameTimeUpdateTimer != null)
            {
                _frameTimeUpdateTimer.Elapsed -= OnFrameTimeUpdate;
                _frameTimeUpdateTimer.Stop();
                _frameTimeUpdateTimer.Dispose();
                _frameTimeUpdateTimer = null;
            }
        }

        private void OnFrameTimeUpdate(object sender, ElapsedEventArgs e)
        {
            UpdateFrameTime();
        }

        private void UpdateFrameTime()
        {
            // Retrieve the current frame time from the core service.
            // Assuming GetCurrentFrameTime() returns the frame time in milliseconds.
            double currentFrameTime = _coreService.GetCurrentFrameTime();

            // Format the frame time and update the property.
            FrameTime = $"Frame Time: {currentFrameTime:F2} ms";
        }

        public void ShowDebugger()
        {
            // Invoke the debugging interface using the debug service.
            _debugService.LaunchDebugger();
        }
    }
}

using System;
using System.Text;
using System.Linq;
 
class Converter
{
    static string lookandsay(string number)
    {
        StringBuilder result = new StringBuilder();
 
        char repeat = number[0];
        number = number.Substring(1, number.Length-1)+" ";
        int times = 1;
 
        foreach (char actual in number)
        {
            if (actual != repeat)
            {
                result.Append(Convert.ToString(times)+repeat);
                times = 1;
                repeat = actual;
            }
            else
            {
                times += 1;
            }
        }
        return result.ToString();
    }
 
    static void Main(string[] args)
    {
        string num = "1";
 
        foreach (int i in Enumerable.Range(1, 10)) {
             Console.WriteLine(num);
             num = lookandsay(num);
        }
    }
}

using System.Windows;
using System.Windows.Controls;

namespace TournamentUI
{
    public partial class GrilleUC : UserControl
    {
        public GrilleUC()
        {
            InitializeComponent();
        }

        private void GenererTour_Click(object sender, RoutedEventArgs e)
        {
            // Get the MainWindow instance from the button's DataContext.
            var button = sender as Button;
            if (button != null)
            {
                var mainWindow = button.DataContext as MainWindow;
                if (mainWindow != null)
                {
                    // Generate the next tour in the tournament.
                    mainWindow.TournoiEnCours.GenererTour();

                    // Collapse all Expander controls within the user control.
                    CollapseAllExpanders();
                }
            }
        }

        private void CollapseAllExpanders()
        {
            foreach (var item in RoundsPanel.Children)
            {
                if (item is FrameworkElement element)
                {
                    Expander expander = FindVisualChild<Expander>(element);
                    if (expander != null)
                    {
                        expander.IsExpanded = false;
                    }
                }
            }
        }

        private T FindVisualChild<T>(FrameworkElement parent) where T : FrameworkElement
        {
            if (parent == null) return null;

            if (parent is T)
            {
                return (T)parent;
            }

            for (int i = 0; i < System.Windows.Media.VisualTreeHelper.GetChildrenCount(parent); i++)
            {
                DependencyObject child = System.Windows.Media.VisualTreeHelper.GetChild(parent, i);
                if (child is FrameworkElement frameworkElement)
                {
                    T result = FindVisualChild<T>(frameworkElement);
                    if (result != null)
                    {
                        return result;
                    }
                }
            }

            return null;
        }
    }
}

using System;
using ProtoBuf;

[ProtoContract]
public class ScsMessage
{
    [ProtoMember(1)]
    public string RepliedMessageId { get; set; }

    protected ScsMessage(string repliedMessageId = null)
    {
        RepliedMessageId = repliedMessageId;
    }
}

[ProtoContract]
public class ScsTextMessage : ScsMessage
{
    [ProtoMember(1)]
    public string Text { get; set; }

    // Constructor for a new message
    public ScsTextMessage(string text)
        : base()
    {
        Text = text;
    }

    // Constructor for a reply message
    public ScsTextMessage(string repliedMessageId, string text)
        : base(repliedMessageId)
    {
        Text = text;
    }

    // Override ToString for better debugging output
    public override string ToString()
    {
        if (!string.IsNullOrEmpty(RepliedMessageId))
        {
            return $"[Reply to {RepliedMessageId}]: {Text}";
        }
        else
        {
            return $"[New Message]: {Text}";
        }
    }

    // Example of a method to serialize the message
    public byte[] Serialize()
    {
        using (var stream = new System.IO.MemoryStream())
        {
            Serializer.Serialize(stream, this);
            return stream.ToArray();
        }
    }

    // Example of a method to deserialize the message
    public static ScsTextMessage Deserialize(byte[] data)
    {
        using (var stream = new System.IO.MemoryStream(data))
        {
            return Serializer.Deserialize<ScsTextMessage>(stream);
        }
    }
}

class Converter
{
    static void Main(string[] args)
    {
        // Create a new text message
        var message = new ScsTextMessage("Hello, world!");
        Console.WriteLine(message.ToString());

        // Create a reply message
        var reply = new ScsTextMessage("12345", "Thanks for your message!");
        Console.WriteLine(reply.ToString());

        // Serialize the original message
        var serializedMessage = message.Serialize();

        // Deserialize back to object
        var deserializedMessage = ScsTextMessage.Deserialize(serializedMessage);
        Console.WriteLine("Deserialized: " + deserializedMessage.ToString());
    }
}

