    public SourceWithOffsetContextIntegrationTests(KafkaFixture fixture, ITestOutputHelper output) : base(fixture)
    {
        _output = output;
        _topic = CreateTopic();
        _settings = CreateConsumerSettings();
    }

    [Fact]
    public void Should_Consume_And_Commit_Offsets_Correctly()
    {
        // Arrange
        var messages = ProduceStrings(_topic, ElementCount);
        var committerSettings = CommitterSettings.Create(Sys);

        // Act
        var (control, probe) = KafkaConsumer.SourceWithOffsetContext(_settings, Subscriptions.Topics(_topic))
            .SelectAsync(1, async record =>
            {
                await Task.Delay(10); // Simulate processing
                return record;
            })
            .Batch(BatchSize, records => records)
            .Via(Committer.FlowWithOffsetContext(committerSettings))
            .ToMaterialized(this.SinkProbe<CommittableOffsetBatch>(), Keep.Both)
            .Run(Materializer);

        // Assert
        probe.Request(ElementCount / BatchSize)
            .Within(TimeSpan.FromSeconds(10), () =>
            {
                var committedBatches = probe.ExpectNextN(ElementCount / BatchSize);
                committedBatches.Should().HaveCount(ElementCount / BatchSize);
                committedBatches.ForEach(batch => batch.BatchSize.Should().Be(BatchSize));
            });

        probe.Cancel();
        control.Shutdown().Wait();
    }

    private string CreateTopic() => Fixture.CreateTopic();
    private ConsumerSettings<string, string> CreateConsumerSettings() => Fixture.CreateConsumerSettings<string, string>();
    private List<string> ProduceStrings(string topic, int count) => Fixture.ProduceStrings(topic, count);
}

