namespace KafkaNet.Logging
{
    public enum LogLevel
    {
        Debug,
        Info,
        Warn,
        Error,
        Fatal
    }

    public interface IKafkaLog
    {
        void DebugFormat(string format, params object[] args);
        void InfoFormat(string format, params object[] args);
        void WarnFormat(string format, params object[] args);
        void ErrorFormat(string format, params object[] args);
        void FatalFormat(string format, params object[] args);
    }

    public class DefaultTraceLog : IKafkaLog
    {
        private readonly LogLevel _minLevel;

        public DefaultTraceLog(LogLevel minLevel = LogLevel.Info)
        {
            _minLevel = minLevel;
        }

        public void DebugFormat(string format, params object[] args)
        {
            Log(LogLevel.Debug, format, args);
        }

        public void InfoFormat(string format, params object[] args)
        {
            Log(LogLevel.Info, format, args);
        }

        public void WarnFormat(string format, params object[] args)
        {
            Log(LogLevel.Warn, format, args);
        }

        public void ErrorFormat(string format, params object[] args)
        {
            Log(LogLevel.Error, format, args);
        }

        public void FatalFormat(string format, params object[] args)
        {
            Log(LogLevel.Fatal, format, args);
        }

        private void Log(LogLevel level, string format, params object[] args)
        {
            if (level < _minLevel) return;

            var message = string.Format(format, args);
            var formattedMessage = $"{DateTime.Now:yyyy-MM-dd HH:mm:ss.fff} [{Thread.CurrentThread.ManagedThreadId}] {level}: {message}";

            switch (level)
            {
                case LogLevel.Debug:
                    Trace.WriteLine(formattedMessage, "Debug");
                    break;
                case LogLevel.Info:
                    Trace.WriteLine(formattedMessage, "Info");
                    break;
                case LogLevel.Warn:
                    Trace.WriteLine(formattedMessage, "Warning");
                    break;
                case LogLevel.Error:
                    Trace.WriteLine(formattedMessage, "Error");
                    break;
                case LogLevel.Fatal:
                    Trace.WriteLine(formattedMessage, "Fatal");
                    break;
            }
        }
    }
}

