using Remotion.Linq.Clauses;
using Remotion.Linq.Clauses.Expressions;
using Remotion.Linq.Parsing.ExpressionTreeVisitors.Transformation;
using System;
using System.Linq;
using System.Linq.Expressions;
using System.Reflection;

namespace ArangoDB.Client.Linq.Parsing.ExpressionNodes
{
    public class SkipExpressionNode : MethodCallExpressionNodeBase
    {
        public static readonly MethodInfo[] SupportedMethods =
        {
            GetSupportedMethod(() => Queryable.Skip<object>(null, 0)),
            GetSupportedMethod(() => Enumerable.Skip<object>(null, 0))
        };

        public Expression Count { get; }

        public SkipExpressionNode(MethodCallExpressionParseInfo parseInfo, Expression count)
            : base(parseInfo, null)
        {
            Count = count;
        }

        protected override Expression VisitChildren(ExpressionTreeVisitor visitor)
        {
            var count = visitor.VisitExpression(Count);
            return count != Count ? new SkipExpressionNode(ParseInfo, count) : this;
        }

        public override Expression Resolve(ParameterExpression inputParameter, Expression expressionToBeResolved, ClauseGenerationContext clauseGenerationContext)
        {
            if (expressionToBeResolved == null)
                throw new ArgumentNullException(nameof(expressionToBeResolved));

            if (inputParameter == null)
                throw new ArgumentNullException(nameof(inputParameter));

            var resolvedCount = clauseGenerationContext.CurrentParameterReplacer.ReplaceParameters(Count);
            return Source.Resolve(inputParameter, expressionToBeResolved, clauseGenerationContext);
        }

        protected override void ApplyNodeSpecificSemantics(QueryModel queryModel, ClauseGenerationContext clauseGenerationContext)
        {
            var skipTakeClause = queryModel.BodyClauses.OfType<SkipTakeClause>().FirstOrDefault();
            if (skipTakeClause != null)
            {
                skipTakeClause.SkipCount = Count;
            }
            else
            {
                queryModel.BodyClauses.Add(new SkipTakeClause(Count, null));
            }
        }

        private static MethodInfo GetSupportedMethod(Expression expression)
        {
            var methodCallExpression = expression as MethodCallExpression;
            if (methodCallExpression == null)
                throw new ArgumentException("Expression must be a method call.", nameof(expression));

            return methodCallExpression.Method.GetGenericMethodDefinition();
        }
    }
}

