    public partial class $safeitemname$ : Page
    {
        public $safeitemname$()
        {
            InitializeComponent();
        }

        protected override void OnNavigatedTo(NavigationEventArgs e)
        {
            base.OnNavigatedTo(e);

            var navigationParameter = e.Parameter;
            var pageKey = GetType().Name;
            var pageState = SuspensionManager.SessionState.ContainsKey(pageKey)
                ? SuspensionManager.SessionState[pageKey] as Dictionary<string, object>
                : null;

            LoadState(navigationParameter, pageState);
        }

        protected override void OnNavigatingFrom(NavigatingCancelEventArgs e)
        {
            base.OnNavigatingFrom(e);

            var pageKey = GetType().Name;
            var pageState = new Dictionary<string, object>();

            SaveState(pageState);

            if(pageState.Count > 0)
                SuspensionManager.SessionState[pageKey] = pageState;
            else if(SuspensionManager.SessionState.ContainsKey(pageKey))
                SuspensionManager.SessionState.Remove(pageKey);
        }

        protected virtual void LoadState(object navigationParameter, Dictionary<string, object> pageState)
        {
            // Implement in derived classes to load navigation parameter or saved state
        }

        protected virtual void SaveState(Dictionary<string, object> pageState)
        {
            // Implement in derived classes to preserve state before navigation/suspension
        }
    }
}

