namespace Queue
{
    class Generator
    {
        static void Main(string[] args)
        {
            var lstSuffix = "th st nd rd th th th th th th".Split(' ');

            Func<int, string> fnOrdinalForm = (n) => n.ToString() + (11 <= n % 100 && 13 >= n % 100? "th" : lstSuffix[n % 10]);

            Func<int, int, IEnumerable<int>> range = (m, n) => Enumerable.Range(m, n - m + 1);

            var result = new[] { new[] { 0, 25 }, new[] { 250, 265 }, new[] { 1000, 1025 } }
               .Select(tpl => range(tpl[0], tpl[1]).Select(fnOrdinalForm).Aggregate((a, b) => a + " " + b))
               .Aggregate((a, b) => a + "\n\n" + b);

            Console.WriteLine(result);
        }
    }
}

