using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.IO;
using System.Text.RegularExpressions;

namespace Builder
{
    class Graph
    {
        static void Main(string[] args)
        {
            var n = new Dictionary<string, int>();
            var downcase = File.ReadAllText("135-0.txt").ToLower();
            var scan = Regex.Matches(downcase, @"[A-Za-zÀ-ÿ]+");
            foreach (Match m in scan)
            {
                if (n.ContainsKey(m.Value))
                {
                    n[m.Value] += 1;
                }
                else
                {
                    n.Add(m.Value, 1);
                }
            }
            var sort = n.OrderBy(x => x.Value);
            var last10 = sort.Reverse().Take(10);
            foreach (var item in last10)
            {
                Console.WriteLine(item.Key + "->" + item.Value);
            }
            Console.ReadKey();
        }
    }
}

