using System;
using Umbraco.Core.Models;
using Umbraco.Web;

namespace FastTrack.Extensions
{
    public static class PublishedContentExtensions
    {
        /// <summary>
        /// Retrieves the raw data value for a specific property alias
        /// </summary>
        /// <param name="content">The published content item</param>
        /// <param name="propertyAlias">The alias of the property to retrieve</param>
        /// <returns>Raw property value or null if not found</returns>
        public static object GetDataValue(this IPublishedContent content, string propertyAlias)
        {
            if (content == null || string.IsNullOrWhiteSpace(propertyAlias))
                return null;

            var property = content.Properties.FirstOrDefault(p => p.Alias.InvariantEquals(propertyAlias));
            return property?.Value;
        }

        /// <summary>
        /// Retrieves a property value as a Guid
        /// </summary>
        /// <param name="content">The published content item</param>
        /// <param name="propertyAlias">The alias of the property to retrieve</param>
        /// <returns>Guid value or default Guid if conversion fails</returns>
        public static Guid GetDataValueAsGuid(this IPublishedContent content, string propertyAlias)
        {
            var rawValue = GetDataValue(content, propertyAlias);

            if (rawValue == null)
                return Guid.Empty;

            switch (rawValue)
            {
                case Guid guidValue:
                    return guidValue;
                case string stringValue:
