namespace Hofstadter_Q_sequence
{
    class Hffs
    {
        private Dictionary<int, int> sequence_r = new Dictionary<int, int>();
        private Dictionary<int, int> sequence_s = new Dictionary<int, int>();
 
        public Hffs()
        {
        }
 
        public int Ffr(int n)
        {
            // first try the cache
            int new_r;
            if (sequence_r.TryGetValue(n, out new_r))
            {
                return new_r;
            }
            else if (n == 0)
            {
                new_r = 1;
            }
            else
            {
                // call recursively
                new_r = Ffr(n - 1) + Ffs(n - 1);
            }
 
            // insert into the cache and return value
            sequence_r[n] = new_r;
            return new_r;
        }
 
        public int Ffs(int n)
        {
            // first try the cache
            int new_s;
            if (sequence_s.TryGetValue(n, out new_s))
            {
                return new_s;
            }
            else if (n == 0)
            {
                new_s = 2;
            }
            else
            {
                int lower = Ffs(n - 1) + 1;
                int upper = Ffr(n) + 1;
                // find next available S
                for (int i = lower; i <= upper; i++)
                {
                    if (!sequence_r.Values.Any(val => val == i))
                    {
                        new_s = i;
                        break;
                    }
                }
            }
 
            // insert into the cache and return value
            sequence_s[n] = new_s;
            return new_s;
        }
    }
 
    class Generator
    {
        static void Main(string[] args)
        {
            Hffs hof = new Hffs();
 
            for (int i = 0; i < 10; i++)
            {
                Console.WriteLine("H:{0} -> R: {1}, S: {2}", i, hof.Ffr(i), hof.Ffs(i));
            }
 
            List<int> r40 = Enumerable.Range(0, 40).Select(i => hof.Ffr(i)).ToList();
            List<int> s960 = Enumerable.Range(0, 960).Select(i => hof.Ffs(i)).ToList();
 
            s960.AddRange(r40);
            s960.Sort();
            List<int> f1000 = Enumerable.Range(1, 1000).ToList();
 
            if (f1000.SequenceEqual(s960))
            {
                Console.WriteLine("Matches");
            }
            else
            {
                Console.WriteLine("Does NOT match");
            }
        }
    }
}

