namespace LexicographicalOrder
{
    class Utils
    {
        static List<int> lexOrder(int n)
        {
            int first = 1;
            int last = n;
            if (n < 1)
            {
                first = n;
                last = 1;
            }
            return Enumerable.Range(first, last).Select(x => x.ToString()).OrderBy(x => x).Select(x => int.Parse(x)).ToList();
        }
 
        static void Main(string[] args)
        {
            Console.WriteLine("In lexicographical order:\n");
            foreach (int n in new List<int> { 0, 5, 13, 21, -22 })
            {
                Console.WriteLine("{0,3}: {1}", n, string.Join(", ", lexOrder(n)));
            }
        }
    }
}

