{
    // Interface that final binding configurations must implement.
    public interface IFinalBindingConfiguration
    {
        void ApplyBinding(IContainer container, BindingInfo info);
    }

    // Simplified container interface for dependency injection.
    public interface IContainer
    {
        void Register(BindingInfo bindingInfo);
    }

    // Represents the binding information that is exchanged with the container.
    public class BindingInfo
    {
        public string BindingDescription { get; set; }
    }

    // A simple object pool for BindingInfo objects.
    public static class BindingInfoPool
    {
        private static readonly Stack<BindingInfo> _pool = new Stack<BindingInfo>();

        public static BindingInfo Get()
        {
            return _pool.Count > 0 ? _pool.Pop() : new BindingInfo();
        }

        public static void Return(BindingInfo info)
        {
            // Reset state if needed.
            info.BindingDescription = null;
            _pool.Push(info);
        }
    }

