        public void SetFinalBindingConfiguration(IFinalBindingConfiguration config)
        {
            if (config == null)
                throw new ArgumentNullException(nameof(config));
            _finalBindingConfig = config;
        }

        // Adds a disposable resource for later cleanup.
        public void AddDisposable(IDisposable disposable)
        {
            if (disposable == null)
                throw new ArgumentNullException(nameof(disposable));
            _disposables.Add(disposable);
        }

        // Spawns a new BindingInfo instance from the pool.
        public BindingInfo SpawnBindingInfo()
        {
            BindingInfo info = BindingInfoPool.Get();
            info.BindingDescription = "Default Binding Info";
