using Yavsc.Abstract.FileSystem;
using Yavsc.Helpers;

public class UserDirectoryInfo
{
    public string UserName { get; }
    public string SubPath { get; }
    public RemoteFileInfo[] Files { get; }
    public DirectoryShortInfo[] SubDirectories { get; }

    public UserDirectoryInfo(string userRepoPath, string userName, string subPath = "")
    {
        if (string.IsNullOrEmpty(userName))
            throw new ArgumentException("Username cannot be empty.", nameof(userName));

        UserName = userName;
        SubPath = subPath;

        string fullPath = Path.Combine(userRepoPath, UserName, SubPath);

        if (!IsValidYavscPath(fullPath))
            throw new ArgumentException("Invalid path according to Yavsc rules.", nameof(fullPath));

        DirectoryInfo dInfo = new DirectoryInfo(fullPath);

        Files = dInfo.Exists ? dInfo.GetFiles().Select(f => new RemoteFileInfo(f)).ToArray() : Array.Empty<RemoteFileInfo>();
        SubDirectories = dInfo.Exists ? dInfo.GetDirectories().Select(d => new DirectoryShortInfo(d)).ToArray() : Array.Empty<DirectoryShortInfo>();
    }

    private bool IsValidYavscPath(string path)
    {
        // Placeholder for actual path validation logic
        // This method should adhere to Yavsc's specific path rules
        return Path.IsPathFullyQualified(path) && !path.Contains("..");
    }
}

