namespace BusinessRules.Transformations
{
  /// <summary>
  /// A transformation rule that converts the string value of a designated property to lowercase.
  /// This rule is intended to be applied on the client side before executes of other rules.
  /// </summary>
  public class LowerCaseTransformationRule : BusinessRule
  {
    /// <summary>
    /// Initializes a new instance of the <see cref="LowerCaseTransformationRule"/> class.
    /// Registers the target property as both an input and an affected property.
    /// </summary>
    /// <param name="primaryProperty">The property metadata that this rule applies to.</param>
    public LowerCaseTransformationRule(IPropertyInfo primaryProperty)
      : base(primaryProperty)
    {
      // Register the property as the primary input.
      InputProperties.Add(primaryProperty);

      // Mark the same property as affected because its value will be modified.
      AffectedProperties.Add(primaryProperty);
    }

    /// <summary>
    /// Executes the transformation of the property to lowercase.
    /// Reads the input value, converts it to lowercase, and writes the updated value back.
    /// </summary>
    /// <param name="context">The context object for rule execution.</param>
    protected override void Execute(RuleContext context)
    {
      // Retrieve the current value of the property.
      object currentValue = context.InputPropertyValues[PrimaryProperty];

      // If the current value is null, do nothing.
      if (currentValue == null)
      {
        return;
      }

      // Ensure the value is of type string before processing.
      string currentString = currentValue as string;
      if (currentString == null)
      {
        // If the value is not a string, exit without transformation.
        return;
      }

      // Convert the string to lowercase.
      string lowerCasedValue = currentString.ToLowerInvariant();

      // Update the property with the transformed (lowercase) value.
      context.AddOutValue(PrimaryProperty, lowerCasedValue);
    }
  }

