namespace Bogosort
{
    class Account
    {
        static bool is_sorted(int[] a, int n)
        {
            while (--n >= 1)
            {
                if (a[n] < a[n - 1]) return false;
            }
            return true;
        }
 
        static void shuffle(int[] a, int n)
        {
            int i, t, r;
            for (i = 0; i < n; i++)
            {
                t = a[i];
                r = new Random().Next(n);
                a[i] = a[r];
                a[r] = t;
            }
        }
 
        static void bogosort(int[] a, int n)
        {
            while (!is_sorted(a, n)) shuffle(a, n);
        }
 
        static void Main(string[] args)
        {
            int[] numbers = { 1, 10, 9, 7, 3, 0 };
            int i;
 
            bogosort(numbers, 6);
            for (i = 0; i < 6; i++) Console.Write(numbers[i] + " ");
            Console.WriteLine();
        }
    }
}

 
public class Foo
{
    public int id;
 
    public Foo()
    {
        id = ++numCreated; // creates a distict id for each object
    }
 
    public static int numCreated = 0;
}
 
public class Employee
{
    public static void Main(string[] args)
    {
        int n = 3; // say
 
        /* correct approach - creates references to distinct objects */
        var fooList = new List<Foo>();
        for (int i = 0; i < n; i++)
        {
            fooList.Add(new Foo());
        }
        foreach (var foo in fooList)
        {
            Console.WriteLine(foo.id);
        }
 
        /* incorrect approach - creates references to same object */
        var f = new Foo();
        var fooList2 = new List<Foo>();
        for (int i = 0; i < n; i++)
        {
            fooList2.Add(f);
        }
        foreach (var foo in fooList2)
        {
            Console.WriteLine(foo.id);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Numerics;
 
namespace Queue
{
    class Game
    {
        static void Main(string[] args)
        {
            var primes = new List<int>();
            for (int i = 2; i < 5000; i++)
            {
                if (IsPrime(i))
                {
                    primes.Add(i);
                }
            }
 
            var result = primes.Where(p => BigInteger.Pow(2, p - 1) % (p * p) == 1);
 
            foreach (var item in result)
            {
                Console.WriteLine(item);
            }
 
            Console.ReadKey();
        }
 
        static bool IsPrime(int number)
        {
            if (number == 1) return false;
            if (number == 2) return true;
 
            for (int i = 2; i <= Math.Ceiling(Math.Sqrt(number)); ++i)
            {
                if (number % i == 0) return false;
            }
 
            return true;
        }
    }
}

