namespace OData.ModelBuilder
{
    public abstract class StructuralPropertyConfiguration
    {
        protected PropertyInfo PropertyInfo { get; }
        protected Type DeclaringType { get; }

        protected StructuralPropertyConfiguration(PropertyInfo propertyInfo, Type declaringType)
        {
            PropertyInfo = propertyInfo ?? throw new ArgumentNullException(nameof(propertyInfo));
            DeclaringType = declaringType ?? throw new ArgumentNullException(nameof(declaringType));
        }

        public abstract PropertyKind Kind { get; }
        public abstract Type RelatedClrType { get; }
    }

    public enum PropertyKind
    {
        Primitive,
        Complex,
        Navigation
    }

    public class ComplexPropertyConfiguration : StructuralPropertyConfiguration
    {
        private bool _isRequired;

        public ComplexPropertyConfiguration(PropertyInfo propertyInfo, Type declaringType)
            : base(propertyInfo, declaringType)
        {
            _isRequired = true; // By default, properties are required
        }

        public override PropertyKind Kind => PropertyKind.Complex;

        public override Type RelatedClrType => PropertyInfo.PropertyType;

        public ComplexPropertyConfiguration IsOptional()
        {
            _isRequired = false;
            return this;
        }

        public ComplexPropertyConfiguration IsRequired()
        {
            _isRequired = true;
            return this;
        }

        public bool IsRequiredProperty() => _isRequired;

        public string PropertyName => PropertyInfo.Name;

        public Type PropertyType => PropertyInfo.PropertyType;
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

public class SymbolTable
{
    private class Scope
    {
        public Dictionary<string, int> Symbols { get; } = new Dictionary<string, int>();
    }

    private readonly Stack<Scope> Scopes = new Stack<Scope>();
    private readonly Scope globalScope = new Scope();
    private int nextGlobalIndex = 0;
    private int NextIndex = 0;

    public SymbolTable()
    {
        EnterScope(); // Initialize with the global scope
    }

    public void EnterScope()
    {
        Scopes.Push(new Scope());
        NextIndex = 0; // Reset local index for the new scope
    }

    public void LeaveScope()
    {
        if (Scopes.Count > 1) // Prevent removing the global scope
        {
            Scopes.Pop();
        }
    }

    public bool ContainsSymbol(string name)
    {
        foreach (var scope in Scopes)
        {
            if (scope.Symbols.ContainsKey(name))
            {
                return true;
            }
        }
        return false;
    }

    public bool ContainsGlobalSymbol(string name)
    {
        return globalScope.Symbols.ContainsKey(name);
    }

    public int GetSymbol(string name)
    {
        foreach (var scope in Scopes)
        {
            if (scope.Symbols.TryGetValue(name, out int index))
            {
                return index;
            }
        }
        throw new KeyNotFoundException($"Symbol '{name}' not found.");
    }

    public int GetGlobalSymbol(string name)
    {
        if (globalScope.Symbols.TryGetValue(name, out int index))
        {
            return index;
        }
        throw new KeyNotFoundException($"Global symbol '{name}' not found.");
    }

    public void AddSymbol(string name)
    {
        if (ContainsSymbol(name))
        {
            throw new InvalidOperationException($"Symbol '{name}' already exists in the current scope.");
        }
        Scopes.Peek().Symbols[name] = NextIndex++;
    }

    public void AddGlobalSymbol(string name)
    {
        if (ContainsGlobalSymbol(name))
        {
            throw new InvalidOperationException($"Global symbol '{name}' already exists.");
        }
        globalScope.Symbols[name] = nextGlobalIndex++;
    }

    public void HandleSymbol(string name, bool isGlobal = false)
    {
        if (isGlobal)
        {
            AddGlobalSymbol(name);
        }
        else
        {
            AddSymbol(name);
        }
    }
}

