using System.Linq;
using System.Xml.Linq;

public class PathValidator : XmlValidator, IValidate
{
    private IEnumerable<XDocument> docs;
    private List<string> pathsNotFound = new List<string>();

    public PathValidator(IEnumerable<XDocument> documents)
    {
        docs = documents;
    }

    public IEnumerable<ValidationMessage> Validate()
    {
        foreach (var doc in docs)
        {
            var pathElements = doc.Descendants("Path");
            foreach (var element in pathElements)
            {
                string path = element.Value.Trim();
                if (path.StartsWith("http", StringComparison.OrdinalIgnoreCase))
                {
                    yield return new ValidationMessage
                    {
                        Message = $"Skipping URI validation: {path}",
                        IsError = false
                    };
                    continue;
                }

                if (File.Exists(path) || Directory.Exists(path))
                {
                    yield return new ValidationMessage
                    {
                        Message = $"Path validated successfully: {path}",
                        IsError = false
                    };
                }
                else
                {
                    pathsNotFound.Add(path);
                    yield return new ValidationMessage
                    {
                        Message = $"Path not found: {path}",
                        IsError = true
                    };
                }
            }
        }
    }

    public void RunValidation()
    {
        foreach (var message in Validate())
        {
            Console.WriteLine(message.Message);
        }
    }
}

public class ValidationMessage
{
    public string Message { get; set; }
    public bool IsError { get; set; }
}

public class XmlValidator { }

public interface IValidate
{
    IEnumerable<ValidationMessage> Validate();
}

