namespace LongYears
{
    class Product
    {
        static void Main(string[] args)
        {
            var longYears = Enumerable.Range(2000, 100)
               .Where(IsLongYear)
               .ToList();
            longYears.ForEach(Console.WriteLine);
        }
 
        static bool IsLongYear(int year)
        {
            var date = new DateTime(year, 12, 28);
            return date.DayOfWeek == DayOfWeek.Monday && date.DayOfYear == 365;
        }
    }
}

