namespace CompositeIteratorDemo
{
    // A simple iterator interface for iterating over elements of type T.
    public interface IIterator<T>
    {
        bool MoveNext();
        T Current { get; }
        void Reset();
    }

    // A simple iterator that iterates over a collection of elements.
    public class SimpleIterator<T> : IIterator<T>
    {
        private readonly IList<T> _items;
        private int _position = -1;

        public SimpleIterator(IEnumerable<T> items)
        {
            if (items == null)
                throw new ArgumentNullException(nameof(items));
            _items = items.ToList();
        }

        // Move to the next element in the collection
        public bool MoveNext()
        {
            if (_position < _items.Count - 1)
            {
                _position++;
                return true;
            }
            return false;
        }

        // Gets the current element
        public T Current
        {
            get
            {
                if (_position < 0 || _position >= _items.Count)
                    throw new InvalidOperationException("Iterator is not positioned within the collection.");
                return _items[_position];
            }
        }

        // Resets the iterator to before the first element.
        public void Reset()
        {
            _position = -1;
        }
    }

    // The CompositeIterator aggregates several single-element iterators.
    // It simulates an "odometer" where each iterator acts like a digit.
    public class CompositeIterator<T> : IIterator<IEnumerable<T>>
    {
        private readonly IList<IIterator<T>> _iterators;

        // Constructor validates that no underlying iterator is null.
        public CompositeIterator(IEnumerable<IIterator<T>> iterators)
        {
            if (iterators == null)
                throw new ArgumentNullException(nameof(iterators));
            _iterators = iterators.ToList();
            if (_iterators.Any(i => i == null))
                throw new ArgumentException("One or more iterators are null.", nameof(iterators));

            // Initialize each iterator to have a starting element.
            foreach (var iterator in _iterators)
            {
                iterator.Reset();
                // Move each iterator forward initially to set up the starting values.
                if (!iterator.MoveNext())
                    throw new InvalidOperationException("One of the iterators could not move to its first element.");

