namespace CustomControls.Rendering
{
    public class ImageBrushCairoImplementation : BaseBrushImplementation
    {
        public Pattern PlatformBrush { get; private set; }

        public ImageBrushCairoImplementation(IBitmap bitmap, TileBrushSettings tileSettings, Rect bounds, Size targetSize)
        {
            // Calculate transformation and tiling parameters using TileBrushCalculator.
            var calculator = new TileBrushCalculator(tileSettings, bounds, targetSize);
            Matrix transform = calculator.Transform;
            Rect clipRect = calculator.ClipRect;

            // Create an intermediate surface to render the transformed image.
            using (var intermediateSurface = new ImageSurface(Format.Argb32, (int)targetSize.Width, (int)targetSize.Height))
            {
                using (var ctx = new Context(intermediateSurface))
                {
                    // Clear the surface.
                    ctx.SetSourceRGBA(0, 0, 0, 0);
                    ctx.Paint();

                    // Set clipping region.
                    ctx.Rectangle(clipRect.X, clipRect.Y, clipRect.Width, clipRect.Height);
                    ctx.Clip();

                    // Apply transformation.
                    ctx.Transform(transform);

                    // Draw the image onto the intermediate surface.
                    DrawBitmap(ctx, bitmap);
                }

                // Create a pattern from the intermediate surface.
                Pattern pattern = new SurfacePattern(intermediateSurface);

                // Configure tile mode extensions.
                if (tileSettings.TileMode == TileMode.Flip)
                {
                    pattern.Extend = Extend.Reflect;
                }
                else
                {
                    pattern.Extend = Extend.Repeat;
                }

                // Apply a translation to correct the pattern's position.
                Matrix patternMatrix = calculator.TranslateMatrix;
                pattern.SetMatrix(patternMatrix);

                PlatformBrush = pattern;
            }
        }

