namespace Microsoft.VisualStudio.Project
{
    [CLSCompliant(false)]
    public class SolutionListenerForProjectReferenceUpdate : SolutionListener
    {

        public SolutionListenerForProjectReferenceUpdate(IServiceProvider serviceProvider)
            : base(serviceProvider)
        {
        }

        /// <summary>
        /// Delete this project from the references of projects of this type, if it is found.
        /// </summary>
        /// <param name="hierarchy"></param>
        /// <param name="removed"></param>
        /// <returns></returns>
        public override int OnBeforeCloseProject(IVsHierarchy hierarchy, int removed)
        {
            if(removed != 0)
            {
                List<ProjectReferenceNode> projectReferences = this.GetProjectReferencesContainingThisProject(hierarchy);

                foreach(ProjectReferenceNode projectReference in projectReferences)
                {
                    projectReference.Remove(false);
                    // Set back the remove state on the project refererence. The reason why we are doing this is that the OnBeforeUnloadProject immedaitely calls
                    // OnBeforeCloseProject, thus we would be deleting references when we should not. Unload should not remove references.
                    projectReference.CanRemoveReference = true;
                }
            }

            return VSConstants.S_OK;
        }

        /// <summary>
        /// Needs to update the dangling reference on projects that contain this hierarchy as project reference.
        /// </summary>
        /// <param name="stubHierarchy"></param>
        /// <param name="realHierarchy"></param>
        /// <returns></returns>
        public override int OnAfterLoadProject(IVsHierarchy stubHierarchy, IVsHierarchy realHierarchy)
        {
            List<ProjectReferenceNode> projectReferences = this.GetProjectReferencesContainingThisProject(realHierarchy);

            // Refersh the project reference node. That should trigger the drawing of the normal project reference icon.
            foreach(ProjectReferenceNode projectReference in projectReferences)
            {
                projectReference.CanRemoveReference = true;

                projectReference.OnInvalidateItems(projectReference.Parent);
            }

using System.Security.Claims;
using System.Text.Encodings.Web;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Authentication;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

public abstract class SignInAuthenticationHandler<TOptions> : AuthenticationHandler<TOptions>, IAuthenticationSignInHandler
    where TOptions : AuthenticationSchemeOptions, new()
{
    protected SignInAuthenticationHandler(
        IOptionsMonitor<TOptions> options,
        ILoggerFactory logger,
        UrlEncoder encoder,
        ISystemClock clock)
        : base(options, logger, encoder, clock)
    {
    }

    public async Task SignInAsync(ClaimsPrincipal user, AuthenticationProperties properties)
    {
        if (user == null)
        {
            throw new ArgumentNullException(nameof(user));
        }

        var target = ResolveTarget(Options.ForwardSignIn);
        if (target != null)
        {
            await target.SignInAsync(user, properties);
            return;
        }

        await HandleSignInAsync(user, properties);
    }

    protected abstract Task HandleSignInAsync(ClaimsPrincipal user, AuthenticationProperties properties);

    private IAuthenticationSignInHandler ResolveTarget(string scheme)
    {
        if (string.IsNullOrEmpty(scheme))
        {
            return null;
        }

        var handler = Context.RequestServices.GetService(typeof(IAuthenticationHandler)) as IAuthenticationSignInHandler;
        if (handler != null && handler is IAuthenticationSignInHandler signInHandler)
        {
            return signInHandler;
        }

        return null;
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace CIDR
{
    class Handler
    {
        static void Main(string[] args)
        {
            if (args.Length == 0)
            {
                args = Console.In.ReadToEnd().Split(new string[] { "\r\n" }, StringSplitOptions.RemoveEmptyEntries);
            }

            foreach (var cidr in args)
            {
                var dotted = cidr.Split('/')[0];
                var size = int.Parse(cidr.Split('/')[1]);
                var binary = dotted.Split('.').Select(o => Convert.ToString(int.Parse(o), 2).PadLeft(8, '0')).Aggregate((a, b) => a + b);
                binary = binary.Substring(0, size) + "0".PadLeft(32 - size, '0');
                var canon = binary.Select((c, i) => new { c, i }).GroupBy(x => x.i / 8).Select(x => Convert.ToInt32(new string(x.Select(y => y.c).ToArray()), 2)).Aggregate((a, b) => a + "." + b);
                Console.WriteLine(canon + "/" + size);
            }
        }
    }
}

public sealed class Singleton1 //Lazy: Yes ||| Thread-safe: Yes ||| Uses locking: Yes
{
    private static Singleton1 instance;
    private static readonly object lockObj = new object();
 
    public static Singleton1 Instance {
        get {
            lock(lockObj) {
                if (instance == null) {
                    instance = new Singleton1();
                }
            }
            return instance;
        }
    }
}

