public class ThreeDView
{
    public delegate void ObjectMovedHandler(ThreeDModel model, Vector3 newPosition);
    public delegate void ObjectSelectedHandler(ThreeDModel model);

    public LinkedList<ThreeDModel> models;
    public bool editor;
    public bool autoupdateable;
    public int slowCounter;
    public uint timeCall;
    public bool objectsSelected;

    public event ObjectMovedHandler onObjectMoved;
    public event ObjectSelectedHandler onObjectSelected;

    public ThreeDView()
    {
        models = new LinkedList<ThreeDModel>();
        editor = false;
        autoupdateable = true;
        slowCounter = 0;
        timeCall = 0;
        objectsSelected = false;
    }

    public void SetEditor(bool mode)
    {
        editor = mode;
    }

    public void AddModel(ThreeDModel model)
    {
        models.AddLast(model);
    }

    public void RemoveModel(ThreeDModel model)
    {
        models.Remove(model);
    }

    public void MoveObject(ThreeDModel model, Vector3 newPosition)
    {
        model.Position = newPosition;
        onObjectMoved?.Invoke(model, newPosition);
    }

    public void SelectObject(ThreeDModel model)
    {
        objectsSelected = true;
        onObjectSelected?.Invoke(model);
    }

    public void DeselectObject()
    {
        objectsSelected = false;
    }

    public void Update()
    {
        if (autoupdateable)
        {
            // Update logic here
            slowCounter++;
            if (slowCounter >= 60)
            {
                slowCounter = 0;
                // Perform slow updates
            }
        }
    }

