    public class LexSense
    {
        public string Definition { get; set; }
    }

    // Represents a single lexical entry within the repository.
    public class LexEntry
    {
        public string Id { get; set; }
        public List<LexSense> Senses { get; set; } = new List<LexSense>();
    }

    // Repository class used to manage lexical entries.
    public class LiftLexEntryRepository : IDisposable
    {
        private readonly Dictionary<string, LexEntry> _entries = new Dictionary<string, LexEntry>();
        private readonly string _filePath;

        // Event raised whenever a new entry is added or an existing entry is modified.
        public event EventHandler<LexEntry> ModifiedEntryAdded;

        // Event raised after an entry is deleted.
        public event EventHandler<LexEntry> AfterEntryDeleted;

        public LiftLexEntryRepository(string filePath)
        {
            _filePath = filePath;
            // Simulate repository file creation.
            if (!File.Exists(_filePath))
            {
                File.Create(_filePath).Close();
            }
        }

        // Saves an entry into the repository and triggers the ModifiedEntryAdded event.
        public void SaveEntry(LexEntry entry)
        {
            bool isNew = !_entries.ContainsKey(entry.Id);
            _entries[entry.Id] = entry;
            OnModifiedEntryAdded(entry);
        }

        // Deletes an entry based on the entry identifier and triggers the AfterEntryDeleted event.
        public void DeleteEntry(string id)
        {
            if (_entries.TryGetValue(id, out LexEntry entry))
            {
                _entries.Remove(id);
                OnAfterEntryDeleted(entry);
            }
        }

        // Deletes an entry using the entry object and triggers the AfterEntryDeleted event.
        public void DeleteEntry(LexEntry entry)
        {
            if (entry != null && _entries.ContainsKey(entry.Id))
            {
                _entries.Remove(entry.Id);
                OnAfterEntryDeleted(entry);
            }
        }

        protected virtual void OnModifiedEntryAdded(LexEntry entry)
        {
            ModifiedEntryAdded?.Invoke(this, entry);
        }

        protected virtual void OnAfterEntryDeleted(LexEntry entry)
        {
            AfterEntryDeleted?.Invoke(this, entry);
        }

        public void Dispose()
        {

