using System;
using System.IO;
using System.Linq;
 
public class Shape
{
    public static void RemoveLines(string fileName, int startLine, int numLines)
    {
        if (string.IsNullOrEmpty(fileName) || startLine < 1 || numLines < 1)
        {
            throw new ArgumentException();
        }
        var f = new FileInfo(fileName);
        if (!f.Exists)
        {
            Console.WriteLine($"{fileName} does not exist");
            return;
        }
        var lines = File.ReadAllLines(fileName);
        var size = lines.Length;
        if (startLine > size)
        {
            Console.WriteLine("The starting line is beyond the length of the file");
            return;
        }
        var n = numLines;
        if (startLine + numLines - 1 > size)
        {
            Console.WriteLine("Attempting to remove some lines which are beyond the end of the file");
            n = size - startLine + 1;
        }
        lines = lines.Take(startLine - 1).Concat(lines.Skip(startLine + n - 1)).ToArray();
        File.WriteAllLines(fileName, lines);
    }
    public static void PrintFile(string fileName, string message)
    {
        if (string.IsNullOrEmpty(fileName))
        {
            throw new ArgumentException();
        }
        var f = new FileInfo(fileName);
        if (!f.Exists)
        {
            Console.WriteLine($"{fileName} does not exist");
            return;
        }
        Console.WriteLine($"\nContents of {fileName} {message}:\n");
        File.ReadAllLines(fileName).ToList().ForEach(Console.WriteLine);
    }
    public static void Main(string[] args)
    {
        PrintFile("input.txt", "before removal");
        RemoveLines("input.txt", 2, 3);
        PrintFile("input.txt", "after removal of 3 lines starting from the second");
    }
}

using System;
using StockSharp.Algo.Indicators;
using System.ComponentModel;

namespace FinancialAnalysis.Indicators
{
    [DisplayName("Relative Strength Index")]
    public class RelativeStrengthIndex : BaseIndicator
    {
        private decimal _last;
        private SmoothedMovingAverage _gain;
        private SmoothedMovingAverage _loss;
        private bool _isInitialized;

        public int Period { get; }

        public RelativeStrengthIndex(int period = 15)
        {
            Period = period;
            _gain = new SmoothedMovingAverage(period);
            _loss = new SmoothedMovingAverage(period);
        }

        public override void Reset()
        {
            base.Reset();
            _last = 0;
            _gain.Reset();
            _loss.Reset();
            _isInitialized = false;
        }

        protected override IIndicatorValue OnProcess(IIndicatorValue input)
        {
            if (input == null)
                throw new ArgumentNullException(nameof(input));

            var price = input.GetValue<decimal>();

            if (!_isInitialized)
            {
                _last = price;
                _isInitialized = true;
                return new DecimalIndicatorValue(this, 50);
            }

            decimal change = price - _last;
            decimal gain = change > 0 ? change : 0;
            decimal loss = change < 0 ? Math.Abs(change) : 0;

            _gain.Process(gain);
            _loss.Process(loss);

            _last = price;

            if (_gain.IsEmpty || _loss.IsEmpty)
                return new DecimalIndicatorValue(this, 50);

            decimal avgGain = _gain.Current.Value;
            decimal avgLoss = _loss.Current.Value;

            if (avgLoss == 0)
                return new DecimalIndicatorValue(this, 100);

            decimal relativeStrength = avgGain / avgLoss;
            decimal rsi = 100 - (100 / (1 + relativeStrength));

            return new DecimalIndicatorValue(this, rsi);
        }
    }
}

