using System;
using System.Linq;

namespace CSharp
{
    public class SubtractiveGenerator : IIntSupplier
    {
        private const int MOD = 1_000_000_000;
        private int[] state = new int[55];
        private int si, sj;

        public SubtractiveGenerator(int p1)
        {
            subrandSeed(p1);
        }

        private void subrandSeed(int p1)
        {
            int p2 = 1;

            state[0] = p1 % MOD;
            for (int i = 1, j = 21; i < 55; i++, j += 21)
            {
                if (j >= 55)
                    j -= 55;
                state[j] = p2;
                if ((p2 = p1 - p2) < 0)
                    p2 += MOD;
                p1 = state[j];
            }

            si = 0;
            sj = 24;
            for (int i = 0; i < 165; i++)
                getAsInt();
        }

        public int getAsInt()
        {
            if (si == sj)
                subrandSeed(0);

            if (si-- == 0)
                si = 54;
            if (sj-- == 0)
                sj = 54;

            int x = state[si] - state[sj];
            if (x < 0)
                x += MOD;

            return state[si] = x;
        }

        public static void Main(string[] args)
        {
            Enumerable.Range(0, 10).Select(i => new SubtractiveGenerator(292_929).getAsInt()).ToList().ForEach(Console.WriteLine);
        }
    }
}

