namespace NetworkProbe.Port
{
    public interface IProbeService
    {
        Task<NetworkProbe.Model.ProbeResult> ProbeAsync(NetworkProbe.Model.ProbeEntity entity);
    }

    public class TcpProbeService : IProbeService
    {
        public async Task<NetworkProbe.Model.ProbeResult> ProbeAsync(NetworkProbe.Model.ProbeEntity entity)
        {
            bool isActive = false;
            string responseData = string.Empty;
            try
            {
                using (var client = new TcpClient())
                {
                    var connectTask = client.ConnectAsync(entity.IPAddress, entity.Port);
                    var timeoutTask = Task.Delay(2000);
                    if (await Task.WhenAny(connectTask, timeoutTask) == connectTask && client.Connected)
                    {
                        isActive = true;
                        responseData = "Service Response"; // Placeholder for real service data
                    }
                }
            }
            catch { /* Ignore exceptions */ }
            return new NetworkProbe.Model.ProbeResult
            {
                ServiceType = entity.ServiceType,
                IPAddress = entity.IPAddress,
                Port = entity.Port,
                IsActive = isActive,
                DataFound = !string.IsNullOrEmpty(responseData),
                Data = responseData
            };
        }
    }

    public static class ProbeServiceFactory
    {
        public static IProbeService CreateService(string serviceType)
        {
            // For simplicity, we return a TcpProbeService regardless of the serviceType.
            return new TcpProbeService();
        }
    }
}

