using JetBrains.Application;
using JetBrains.Metadata.Utils;
using JetBrains.ReSharper.Psi.Impl.Reflection2.ExternalAnnotations;
using JetBrains.Util;

namespace XunitContrib.Runner.ReSharper.Tests.AcceptanceTests.Annotations
{
    [ShellComponent]
    public class ExternalAnnotationsProvider : IExternalAnnotationsFileProvider
    {
        private readonly OneToSetMap<string, FileSystemPath> annotations;
        private FileSystemPath cachedBaseTestDataPath;

        public ExternalAnnotationsProvider()
        {
            var location = TestDataPath2;
            annotations = new OneToSetMap<string, FileSystemPath>(StringComparer.OrdinalIgnoreCase);

            foreach (var file in location.GetChildFiles("*.xml"))
                annotations.Add(file.NameWithoutExtension, file);
            foreach (var directory in location.GetChildDirectories())
            {
                foreach (var file in directory.GetChildFiles("*.xml", PathSearchFlags.RecurseIntoSubdirectories))
                {
                    annotations.Add(file.NameWithoutExtension, file);
                    annotations.Add(file.Directory.Name, file);
                }
            }
        }

        public IEnumerable<FileSystemPath> GetAnnotationsFiles(AssemblyNameInfo assemblyName = null, FileSystemPath assemblyLocation = null)
        {
            if (assemblyName == null)
                return annotations.Values;
            return annotations[assemblyName.Name];
        }

        private FileSystemPath BaseTestDataPath
        {
            get
            {
                if (cachedBaseTestDataPath == null)
                    cachedBaseTestDataPath = TestUtil.GetTestDataPathBase(GetType().Assembly);
                return cachedBaseTestDataPath;
            }
        }

        private string RelativeTestDataPath
        {
            get { return @"..\..\ExternalAnnotations"; }
        }

        private FileSystemPath TestDataPath2
        {
            get { return BaseTestDataPath.Combine(RelativeTestDataPath); }
        }
    }
}

using System;
 
namespace ChineseZodiac
{
    class Counter
    {
        static string[] animalString = { "Rat", "Ox", "Tiger", "Rabbit", "Dragon", "Snake",
            "Horse", "Goat", "Monkey", "Rooster", "Dog", "Pig" };
        static string[] stemYYString = { "Yang", "Yin" };
        static string[] elementString = { "Wood", "Fire", "Earth", "Metal", "Water" };
        static char[] stemCh = { '甲', '乙', '丙', '丁', '戊', '己', '庚', '辛', '壬', '癸' };
        static char[] branchCh = { '子', '丑', '寅', '卯', '辰', '巳', '午', '未', '申', '酉', '戌', '亥' };
 
        static void Main(string[] args)
        {
            foreach (int yr in new int[] { 1935, 1938, 1968, 1972, 1976 })
            {
                string a, yy, e, sb;
                int cy;
                cz(yr, out a, out yy, out e, out sb, out cy);
                Console.WriteLine("{0}: {1} {2}, {3}, Cycle year {4} {5}",
                    yr, e, a, yy, cy, sb);
            }
        }
 
        static void cz(int yr, out string animal, out string yinYang, out string element, out string stemBranch, out int cycleYear)
        {
            yr -= 4;
            int stem = yr % 10;
            int branch = yr % 12;
            animal = animalString[branch];
            yinYang = stemYYString[stem % 2];
            element = elementString[stem / 2];
            stemBranch = new string(new char[] { stemCh[stem], branchCh[branch] });
            cycleYear = yr % 60 + 1;
        }
    }
}

using System;
using Microsoft.Practices.ObjectBuilder2;
using Microsoft.Practices.Unity.InterceptionExtension;

public class ExtendedTypeInterceptionStrategy : BuilderStrategy
{
    private readonly InterceptionConfiguration _interception;

    public ExtendedTypeInterceptionStrategy(InterceptionConfiguration interception)
    {
        _interception = interception ?? throw new ArgumentNullException(nameof(interception));
    }

    public override void PreBuildUp(IBuilderContext context)
    {
        Type typeToBuild = context.BuildKey.Type;
        if (!_interception.InterceptionEnabled) return;

        IInterceptionPolicy policy = context.Policies.Get<IInterceptionPolicy>(typeToBuild);
        IInstanceInterceptor interceptor = null;

        if (policy != null)
        {
            interceptor = policy.Interceptor;
            if (interceptor != null && interceptor.CanIntercept(typeToBuild))
            {
                ApplyInterceptorBehavior(interceptor, context, typeToBuild);
                return;
            }
        }

        interceptor = _interception.DefaultInterceptor;
        if (interceptor != null && interceptor.CanIntercept(typeToBuild))
        {
            ApplyInterceptorBehavior(interceptor, context, typeToBuild);
        }
    }

    private void ApplyInterceptorBehavior(
        IInstanceInterceptor interceptor,
        IBuilderContext context,
        Type typeToBuild)
    {
        var behavior = new InterceptionBehavior(interceptor);
        var behaviorPolicy = new InterceptionBehaviorPolicy(behavior);
        context.Policies.Set<InterceptionBehaviorPolicy>(behaviorPolicy, typeToBuild);
    }
}

public class InterceptionConfiguration
{
    public bool InterceptionEnabled { get; set; }
    public IInstanceInterceptor DefaultInterceptor { get; set; }
}

public interface IInterceptionPolicy : IBuilderPolicy
{
    IInstanceInterceptor Interceptor { get; }
}

