    interface IILVisitor {
        void OnInlineNone (OpCode opcode);
        void OnInlineSByte (OpCode opcode, sbyte value);
        void OnInlineByte (OpCode opcode, byte value);
        void OnInlineInt32 (OpCode opcode, int value);
