#if INSIDE_ROCKS
    public
#endif
    static class ILParser {

        class ParseContext {
            public CodeReader Code { get; set; }
            public int Position { get; set; }
            public MetadataReader Metadata { get; set; }
            public Collection<VariableDefinition> Variables { get; set; }
            public IILVisitor Visitor { get; set; }
        }

        public static void Parse (MethodDefinition method, IILVisitor visitor)
        {
            if (method == null)
                throw new ArgumentNullException ("method");
            if (visitor == null)
                throw new ArgumentNullException ("visitor");
            if (!method.HasBody || !method.HasImage)
                throw new ArgumentException ();

            method.Module.Read (method, (m, _) => {
                ParseMethod (m, visitor);
                return true;
            });
        }

        static void ParseMethod (MethodDefinition method, IILVisitor visitor)
        {
            var context = CreateContext (method, visitor);
            var code = context.Code;

            var flags = code.ReadByte ();

            switch (flags & 0x3) {
            case 0x2: // tiny
                int code_size = flags >> 2;
                ParseCode (code_size, context);
                break;
            case 0x3: // fat
                code.Advance (-1);
                ParseFatMethod (context);
                break;

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace Task
{
    class Sorter
    {
        static void Main(string[] args)
        {
            Console.WriteLine(pow(2, 10));
            Console.ReadLine();
        }
 
        static T pow<T>(T base1, int exp) where T : ICloneable, IOne, IMul<T>
        {
            if (exp == 0) return One<T>.one();
            while (exp & 1 == 0)
            {
                base1 = base1.clone().mul(base1);
                exp >>= 1;
            }
            if (exp == 1) return base1;
            T acc = base1.clone();
 
            while (exp > 1)
            {
                exp >>= 1;
                base1 = base1.clone().mul(base1);
                if (exp & 1 == 1)
                {
                    acc = acc.mul(base1.clone());
                }
            }
            return acc;
        }
    }
 
    interface IOne
    {
        T one();
    }
 
    interface IMul<T>
    {
        T mul(T other);
    }
 
    class One<T> : IOne
    {
        public static T one()
        {
            return default(T);
        }
    }
 
    class Int : ICloneable, IOne, IMul<Int>
    {
        public int value;
 
        public Int(int value)
        {
            this.value = value;
        }
 
        public object Clone()
        {
            return new Int(value);
        }
 
        public Int one()
        {
            return new Int(1);
        }
 
        public Int mul(Int other)
        {
            return new Int(value * other.value);
        }
    }
}

static void Main(string[] args)
{
    Console.WriteLine(DotProduct(new decimal[] { 1, 3, -5 }, new decimal[] { 4, -2, -1 }));
    Console.Read();
}
 
private static decimal DotProduct(decimal[] vec1, decimal[] vec2)
{
    if (vec1 == null)
        return 0;
 
    if (vec2 == null)
        return 0;
 
    if (vec1.Length != vec2.Length)
        return 0;
 
    decimal tVal = 0;
    for (int x = 0; x < vec1.Length; x++)
    {
        tVal += vec1[x] * vec2[x];
    }
 
    return tVal;
}

