    public interface IToolService : IService
    {
        Task<ToolDetailsDto> GetAsync(string model);
        Task<IEnumerable<ToolDto>> GetAllAsync();
        Task AddAsync(ToolDetailsDto dto);
        Task DeleteAsync(Guid id);
        Task UpdateAsync(ToolDetailsDto dto);
    }

    public class ToolService : IToolService
    {
        private readonly IToolRepository _toolRepository;
        private readonly IMapper _mapper;

        public ToolService(IToolRepository toolRepository, IMapper mapper)
        {
            _toolRepository = toolRepository;
            _mapper = mapper;
        }

        public async Task<ToolDetailsDto> GetAsync(string model)
        {
            var tool = await _toolRepository.GetByModelAsync(model);
            return _mapper.Map<ToolDetailsDto>(tool);
        }

        public async Task<IEnumerable<ToolDto>> GetAllAsync()
        {
            var tools = await _toolRepository.GetAllAsync();
            return _mapper.Map<IEnumerable<ToolDto>>(tools);
        }

        public async Task AddAsync(ToolDetailsDto dto)
        {
            var tool = new Tool(
                dto.Id,
                dto.Model,
                dto.Brand,
                dto.Type,
                dto.PurchaseDate,
                dto.LastMaintenanceDate,
                dto.Box
            );
            await _toolRepository.AddAsync(tool);
        }

        public Task DeleteAsync(Guid id)
        {
            // WARNING: ID translation not implemented
            throw new NotImplementedException("Delete operation requires ID mapping resolution.");
        }

        public Task UpdateAsync(ToolDetailsDto dto)
        {
            // WARNING: ID translation not implemented
            throw new NotImplementedException("Update operation requires ID mapping resolution.");
        }
    }
}

