        {
            get { return this.GetRepository<Guess>(); }
        }

        public IRepository<Notification> Notifications
        {
            get { return this.GetRepository<Notification>(); }
        }

        public int SaveChanges()
        {
            return this.context.SaveChanges();
        }

        // Lazy initialization of repositories using reflection
        private IRepository<T> GetRepository<T>() where T : class
        {
            var typeOfEntity = typeof(T);
            if (!this.repositories.ContainsKey(typeOfEntity))
            {
                // Dynamically create a GenericRepository instance passing the relevant DbSet
                var repositoryInstance = Activator.CreateInstance(
                    typeof(GenericRepository<T>),
                    this.context.Set<T>());
                this.repositories.Add(typeOfEntity, repositoryInstance);
            }
            return (IRepository<T>)this.repositories[typeOfEntity];
        }
    }

