namespace PascalMatrix
{
    class Graph
    {
        static int binomialCoef(int n, int k)
        {
            int result = 1;
            for (int i = 1; i <= k; i++)
                result = result * (n - i + 1) / i;
            return result;
        }
 
        static List<IEnumerable<int>> pascal(int n, Func<int, IEnumerable<int>> f)
        {
            return Enumerable.Range(0, n).Select(i => f(i)).ToList();
        }
 
        static List<IEnumerable<int>> pascalUpp(int n)
        {
            return pascal(n, i => Enumerable.Range(0, n).Select(j => binomialCoef(j, i)));
        }
 
        static List<IEnumerable<int>> pascalLow(int n)
        {
            return pascal(n, i => Enumerable.Range(0, n).Select(j => binomialCoef(i, j)));
        }
 
        static List<IEnumerable<int>> pascalSym(int n)
        {
            return pascal(n, i => Enumerable.Range(0, n).Select(j => binomialCoef(i + j, i)));
        }
 
        static void print(string label, List<IEnumerable<int>> result)
        {
            Console.WriteLine("\n" + label);
            foreach (var row in result)
            {
                foreach (var i in row)
                    Console.Write("{0,2} ", i);
                Console.WriteLine();
            }
        }
 
        static void Main(string[] a)
        {
            print("Upper: ", pascalUpp(5));
            print("Lower: ", pascalLow(5));
            print("Symmetric:", pascalSym(5));
        }
    }
}

