namespace Sorter
{
    class Processor
    {
        static void Main(string[] args)
        {
            int[] ary = Enumerable.Range(1, 9).ToArray();
            Random rnd = new Random();
            while (ary.SequenceEqual(ary.OrderBy(x => x)))
            {
                rnd.Shuffle(ary);
            }
            int score = 0;
            while (!ary.SequenceEqual(ary.OrderBy(x => x)))
            {
                Console.WriteLine(string.Join(",", ary));
                Console.Write("How many digits to reverse? ");
                int num = int.Parse(Console.ReadLine());
                Array.Reverse(ary, 0, num);
                score++;
            }
            Console.WriteLine(string.Join(",", ary));
            Console.WriteLine("Your score: {0}", score);
            Console.ReadKey();
        }
    }

    public static class RandomExtensions
    {
        public static void Shuffle<T>(this Random rng, T[] array)
        {
            int n = array.Length;
            while (n > 1)
            {
                int k = rng.Next(n--);
                T temp = array[n];
                array[n] = array[k];
                array[k] = temp;
            }
        }
    }
}

