namespace Game.Resources
{
    // Design-time configuration for a resource type.
    public class ResourceTypeInfo
    {
        public string Name;
        public Sprite EditorSprite;
        public string TerrainType;
        public List<string> AllowedTerrainTypes;
        public bool AllowUnderActors;
        public bool AllowUnderBuildings;
        public int ValuePerUnit;
        public int MaxDensity;
        public string PipColor;
        public Dictionary<string, string[]> Variants; // variant key => sprite id sequence
        public string Palette;

        // Factory method to create a runtime instance.
        public ResourceType Create()
        {
            return new ResourceType(this);
        }
    }

    // Called when world and renderer are ready.
    public interface IWorldObject
    {
        void WorldLoaded(World world, WorldRenderer renderer);
    }

    // Runtime resource instance that interacts with the game world.
    public class ResourceType : IWorldObject
    {
        private ResourceTypeInfo info;
        private Dictionary<string, Sprite[]> cachedSpriteSequences;
        private Palette loadedPalette;

        public string Name => info.Name;
        public int ValuePerUnit => info.ValuePerUnit;
        public int MaxDensity => info.MaxDensity;
        public Sprite EditorSprite => info.EditorSprite;

        public ResourceType(ResourceTypeInfo info)
        {
            this.info = info;
            cachedSpriteSequences = new Dictionary<string, Sprite[]>();
            foreach (var variant in info.Variants)
            {
                cachedSpriteSequences[variant.Key] = new Sprite[variant.Value.Length];
            }
        }

        // Called when the world has finished loading.
        public void WorldLoaded(World world, WorldRenderer renderer)
        {
            loadedPalette = world.GetPalette(info.Palette);
            foreach (var variant in info.Variants)
            {
                for (int i = 0; i < variant.Value.Length; i++)
                {
                    cachedSpriteSequences[variant.Key][i] = renderer.ResourceProvider.GetSprite(variant.Value[i], loadedPalette);
                }
            }
        }

        public Sprite[] GetSpriteSequence(string variantKey)
        {
            if (cachedSpriteSequences.TryGetValue(variantKey, out Sprite[] sequence))
                return sequence;
            throw new Exception("Variant not found: " + variantKey);
        }
    }

