namespace GameRealmNamespace
{
    [Flags]
    [SuppressMessage("Design", "CA1027:Use readonly static fields for well-known types", Justification = "Enum needed for Flags")]
    [DataContract]
    public enum RealmTypes
    {
        [EnumMember]
        None = 0,                // No specific realm type

        [EnumMember]
        Pve = 1 << 0,           // Player versus Environment

        [EnumMember]
        Pvp = 1 << 1,           // Player versus Player

        [EnumMember]
        RP = 1 << 2,            // Role Playing

        [EnumMember]
        RPPvp = 1 << 3,         // Role Playing and Player versus Player

        [EnumMember]
        PvePvp = Pve | Pvp,     // Both Pve and Pvp

        [EnumMember]
        All = Pve | Pvp | RP | RPPvp // All realm types combined
    }

    public class GameRealm
    {
        public RealmTypes RealmType { get; set; }

        public GameRealm(RealmTypes realmType)
        {
            RealmType = realmType;
        }

        public void DisplayRealmInfo()
        {
            Console.WriteLine($"Current Realm Type: {RealmType}");
            Console.WriteLine($"Is PvE: {HasPve()}");
            Console.WriteLine($"Is PvP: {HasPvp()}");
            Console.WriteLine($"Is RP: {HasRP()}");
            Console.WriteLine($"Is RPPvP: {HasRPPvp()}");
        }

        public bool HasPve() => (RealmType & RealmTypes.Pve) == RealmTypes.Pve;
        public bool HasPvp() => (RealmType & RealmTypes.Pvp) == RealmTypes.Pvp;
        public bool HasRP() => (RealmType & RealmTypes.RP) == RealmTypes.RP;
        public bool HasRPPvp() => (RealmType & RealmTypes.RPPvp) == RealmTypes.RPPvp;

        public void CombineRealmTypes(RealmTypes newRealmType)
        {
            RealmType |= newRealmType;
            Console.WriteLine($"Combined Realm Type: {RealmType}");
        }

        public void RemoveRealmType(RealmTypes realmTypeToRemove)
        {
            RealmType &= ~realmTypeToRemove;
            Console.WriteLine($"Updated Realm Type after removal: {RealmType}");
        }
    }

    class Validator
    {
        static void Main(string[] args)
        {
            GameRealm gameRealm = new GameRealm(RealmTypes.Pve);
            gameRealm.DisplayRealmInfo();

            gameRealm.CombineRealmTypes(RealmTypes.Pvp);
            gameRealm.DisplayRealmInfo();

            gameRealm.RemoveRealmType(RealmTypes.Pve);
            gameRealm.DisplayRealmInfo();
        }
    }
}

using System;
using System.Text;

public class GapfulNumbers
{
    private static string Commatize(long n)
    {
        var sb = new StringBuilder(n.ToString());
        var le = sb.Length;
        var i = le - 3;
        while (i >= 1)
        {
            sb.Insert(i, ',');
            i -= 3;
        }
        return sb.ToString();
    }

    public static void Main()
    {
        var starts = new long[] { 100, 1000000, 10000000, 1000000000, 7123 };
        var counts = new int[] { 30, 15, 15, 10, 25 };
        for (var i = 0; i < starts.Length; i++)
        {
            var count = 0;
            var j = starts[i];
            var pow = 100L;
            while (j >= pow * 10)
            {
                pow *= 10;
            }
            Console.Out.Write($"First {counts[i]} gapful numbers starting at {Commatize(starts[i])}:\n");
            while (count < counts[i])
            {
                var fl = j / pow * 10 + j % 10;
                if (j % fl == 0)
                {
                    Console.Out.Write($"{j} ");
                    count++;
                }
                j++;
                if (j >= 10 * pow)
                {
                    pow *= 10;
                }
            }
            Console.Out.Write("\n\n");
        }
    }
}

using System;

public class Timer
{
    public static void Main(string[] args)
    {
        char hle;
        int lowest = 1;
        int highest = 20;
        int guess = 10;
        Console.WriteLine("Please choose a number between 1 and 20 but don't tell me what it is yet\n");

        while (true)
        {
            Console.WriteLine("My guess is " + guess);

            do
            {
                Console.Write("Is this higher/lower than or equal to your chosen number h/l/e : ");
                hle = Console.ReadLine()[0];
                if (hle == 'l' && guess == highest)
                {
                    Console.WriteLine("It can't be more than " + highest + ", try again");
                    hle = 'i'; // signifies invalid
                }
                else if (hle == 'h' && guess == lowest)
                {
                    Console.WriteLine("It can't be less than " + lowest + ", try again");
                    hle = 'i';
                }
            }
            while (hle!= 'h' && hle!= 'l' && hle!= 'e');

            switch (hle)
            {
                case 'e':
                    {
                        Console.WriteLine("Good, thanks for playing the game with me!");
                        return;
                    }
                case 'h':
                    if (highest > guess - 1)
                        highest = guess - 1;
                    break;
                case 'l':
                    if (lowest < guess + 1)
                        lowest = guess + 1;
                    break;
            }

            guess = (lowest + highest) / 2;
        }
    }
}

