namespace BusDriver
{
    public class RequeueCommand
    {
        private readonly string _uriString;
        private readonly int _count;

        public RequeueCommand(string uriString, int count)
        {
            _uriString = uriString;
            _count = count;
        }

        public async Task Execute()
        {
            var uri = new Uri(_uriString);
            if (!TransportRegistry.Transports.TryGetTransport(uri, out IDuplexTransport transport))
            {
                Console.WriteLine($"Transport not found: {_uriString}");
                return;
            }

            int requeued = 0;
            var receiver = transport.CreateReceiver();

            await receiver.Start(async context =>
            {
                try
                {
                    var messageId = context.TransportHeaders.Get("MessageId", "Unknown");
                    Console.WriteLine($"Requeuing message: {messageId}");

                    var sendContext = new RequeueSendContext(context);
                    await transport.Send(uri, sendContext);

                    requeued++;
                    return requeued < _count;
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error requeueing message: {ex.Message}");
                    return true;
                }
            }, TimeSpan.Zero);

            Console.WriteLine($"Successfully requeued {requeued} messages.");
        }
    }

    public class RequeueSendContext : BaseSendContext
    {
        public RequeueSendContext(ReceiveContext source)
            : base(source.ContentType)
        {
            SourceAddress = source.InputAddress;
            Body = source.GetBody();

            foreach (var header in source.TransportHeaders.GetAll())
            {
                Headers.Set(header.Key, header.Value);
            }
        }

        public override byte[] Body { get; }
    }

    public static class TransportRegistry
    {
        public static readonly TransportProvider Transports = new TransportProvider();
    }

    public class TransportProvider
    {
        public bool TryGetTransport(Uri uri, out IDuplexTransport transport)
        {
            transport = new InMemoryDuplexTransport();
            return true;
        }
    }

