public class BxROM : IMemoryMapper
{
    private bool _is_nina07;
    private int _prg_bank_mask_32k;
    private int _chr_bank_mask_8k;
    private int _prg_bank_32k;
    private int _chr_bank_8k;

    private IMemoryDomains _memoryDomains;
    private readonly bool[] _mirroringConfig = new bool[2];

    public BxROM(bool isNina07 = false)
    {
        _is_nina07 = isNina07;
        ConfigureMapper();
    }

    private void ConfigureMapper()
    {
        _prg_bank_mask_32k = 0x1F;  // Default 32k PRG bank mask
        _chr_bank_mask_8k = 0x07;   // Default 8k CHR bank mask
        _prg_bank_32k = 0;          // Initial PRG bank
        _chr_bank_8k = 0;           // Initial CHR bank
    }

    public void WritePRG(int address, byte value)
    {
        if (_is_nina07)
        {
            // NINA-07 specific bank switching logic
            if (address >= 0x7FFD && address <= 0x7FFF)
            {
                int bankOffset = address - 0x7FFD;
                switch (bankOffset)
                {
                    case 0:
                        _chr_bank_8k = (value & _chr_bank_mask_8k);
                        break;
                    case 1:
                        _prg_bank_32k = (value & _prg_bank_mask_32k);
                        break;
                }
            }
        }
        else
        {
            // Standard BxROM bank switching
            if (address >= 0x8000)
            {
                _prg_bank_32k = (value & _prg_bank_mask_32k);
            }
        }
    }

    public byte ReadPRG(int address)
    {
        int bankAddress = (address & 0x7FFF);
        int mappedAddress = (_prg_bank_32k * 0x8000) + bankAddress;
        return _memoryDomains.PRGRom[mappedAddress & (_memoryDomains.PRGRom.Length - 1)];
    }

    public byte ReadPPU(int address)
    {
        if (address < 0x2000)
        {
            int mappedAddress = (_chr_bank_8k * 0x2000) + address;
            return _memoryDomains.CHRRom[mappedAddress & (_memoryDomains.CHRRom.Length - 1)];
        }
        return 0;
    }

    public void SetMirroring(bool horizontal)
    {
        _mirroringConfig[0] = horizontal;
        _mirroringConfig[1] = !horizontal;
    }

    public void SyncState(byte[] state)
    {
        _prg_bank_32k = BitConverter.ToInt32(state, 0);
        _chr_bank_8k = BitConverter.ToInt32(state, 4);
        _is_nina07 = BitConverter.ToBoolean(state, 8);
    }

    public byte[] GetState()
    {
        byte[] state = new byte[12];
        BitConverter.GetBytes(_prg_bank_32k).CopyTo(state, 0);

