namespace XACML.Policy
{
    public class ActionElement : TargetItemBase
    {
        private const string Xacml10Namespace = "urn:oasis:names:tc:xacml:1.0:policy";

        public ActionElement(XmlReader reader, string schemaVersion) : base(schemaVersion)
        {
            ReadXmlInternal(reader);
            IsReadOnly = true;
        }

        protected override void ReadXmlInternal(XmlReader reader)
        {
            reader.MoveToContent();
            if (reader.IsEmptyElement) return;

            reader.ReadStartElement("Action", Xacml10Namespace);

            while (reader.IsStartElement("ActionMatch", Xacml10Namespace))
            {
                var match = CreateMatch(reader, SchemaVersion);
                Matches.Add(match);
                reader.Read();
            }

            reader.ReadEndElement();
        }

        protected override MatchElement CreateMatch(XmlReader reader, string schemaVersion)
        {
            var matchId = reader.GetAttribute("MatchId");
            var dataType = reader.GetAttribute("DataType");
            var value = reader.ReadElementContentAsString();

            return new ActionMatchElement(matchId, dataType, value, schemaVersion);
        }
    }

    public abstract class TargetItemBase
    {
        protected readonly string SchemaVersion;
        public bool IsReadOnly { get; protected set; }
        public Collection<MatchElement> Matches { get; }

        protected TargetItemBase(string schemaVersion)
        {
            SchemaVersion = schemaVersion;
            Matches = new Collection<MatchElement>();
        }

        protected abstract void ReadXmlInternal(XmlReader reader);
        protected abstract MatchElement CreateMatch(XmlReader reader, string schemaVersion);
    }

    public class ActionMatchElement : MatchElement
    {
        public ActionMatchElement(string matchId, string dataType, string value, string schemaVersion)
        {
            MatchId = matchId;
            DataType = dataType;
            Value = value;
            SchemaVersion = schemaVersion;
        }

        public override string MatchId { get; }
        public override string DataType { get; }
        public override string Value { get; }
        public string SchemaVersion { get; }
    }

    public abstract class MatchElement
    {
        public abstract string MatchId { get; }
        public abstract string DataType { get; }
        public abstract string Value { get; }
    }
