        /// <returns>A function that accepts a collection and returns sliding windows.</returns>
        public static Func<IEnumerable<T>, IEnumerable<IEnumerable<T>>> Aperture<T>(this int windowSize)
        {
            return (IEnumerable<T> collection) => windowSize.Aperture(collection);
        }

