        protected readonly string fileExtension;

        protected CstGeneratorBase(string fileExtension)
        {
            this.fileExtension = fileExtension;
        }

        public abstract string LanguageName { get; }
        public abstract string LanguageVersion { get; }

        protected abstract Lexer CreateLexer(ICharStream input);
        protected abstract TParser CreateParser(ITokenStream tokens);

