    // Exporting the generator component for dependency injection frameworks.
    [Export(typeof(CstGeneratorBase<SmalltalkParser>))]
    public class SmalltalkCstGenerator : CstGeneratorBase<SmalltalkParser>
    {
        public SmalltalkCstGenerator() : base(".st")
        {
        }

        public override string LanguageName => "Smalltalk";
        public override string LanguageVersion => "1.0";

        protected override Lexer CreateLexer(ICharStream input)
        {
            return new SmalltalkLexer(input);
        }

        protected override SmalltalkParser CreateParser(ITokenStream tokens)
        {
            return new SmalltalkParser(tokens);
        }

        public override object Parse(string sourceCode)
        {
            // Convert source code to a character stream.
            ICharStream charStream = CharStreams.FromString(sourceCode);
            // Create the lexer and tokenize the input.
            Lexer lexer = CreateLexer(charStream);
            CommonTokenStream tokenStream = new CommonTokenStream(lexer);
            // Create the parser and process the tokens.
            SmalltalkParser parser = CreateParser(tokenStream);
            // Invoke the parsing rule corresponding to the program entry point.
            object syntaxTree = parser.Program();
            return syntaxTree;
        }
    }

