using System;
 
namespace Quaternion
{
    public struct Quaternion
    {
        public double a;
        public double b;
        public double c;
        public double d;
 
        public Quaternion(double a, double b, double c, double d)
        {
            this.a = a;
            this.b = b;
            this.c = c;
            this.d = d;
        }
 
        public static Quaternion operator +(Quaternion q1, Quaternion q2)
        {
            return new Quaternion(q1.a + q2.a, q1.b + q2.b, q1.c + q2.c, q1.d + q2.d);
        }
 
        public static Quaternion operator +(Quaternion q, double r)
        {
            return new Quaternion(q.a + r, q.b, q.c, q.d);
        }
 
        public static Quaternion operator +(double r, Quaternion q)
        {
            return new Quaternion(q.a + r, q.b, q.c, q.d);
        }
 
        public static Quaternion operator *(Quaternion q1, Quaternion q2)
        {
            return new Quaternion(
                q1.a * q2.a - q1.b * q2.b - q1.c * q2.c - q1.d * q2.d,
                q1.a * q2.b + q1.b * q2.a + q1.c * q2.d - q1.d * q2.c,
                q1.a * q2.c - q1.b * q2.d + q1.c * q2.a + q1.d * q2.b,
                q1.a * q2.d + q1.b * q2.c - q1.c * q2.b + q1.d * q2.a
            );
        }
 
        public static Quaternion operator *(Quaternion q, double r)
        {
            return new Quaternion(q.a * r, q.b * r, q.c * r, q.d * r);
        }
 
        public static Quaternion operator *(double r, Quaternion q)
        {
            return new Quaternion(q.a * r, q.b * r, q.c * r, q.d * r);
        }
 
        public static Quaternion operator -(Quaternion q)
        {
            return new Quaternion(-q.a, -q.b, -q.c, -q.d);
        }
 
        public Quaternion conj()
        {
            return new Quaternion(a, -b, -c, -d);
        }
 
        public double norm()
        {
            return Math.Sqrt(a * a + b * b + c * c + d * d);
        }
 
        public override string ToString()
        {
            return $"({a}, {b}, {c}, {d})";
        }
    }
 
    class Helper
    {
        static void Main(string[] args)
        {
            var q  = new Quaternion(1.0, 2.0, 3.0, 4.0);
            var q1 = new Quaternion(2.0, 3.0, 4.0, 5.0);
            var q2 = new Quaternion(3.0, 4.0, 5.0, 6.0);
            var r  = 7.0;
            Console.WriteLine($"q  = {q}");
            Console.WriteLine($"q1 = {q1}");
            Console.WriteLine($"q2 = {q2}");
            Console.WriteLine($"r  = {r}\n");
            Console.WriteLine($"norm(q) = {q.norm():f}");

