// Interface to expose a key element in a configuration element
public interface IKeyedConfigurationElement
{
    string Key { get; }
}

// Generic configuration element that holds a key-value pair.
// The key is of type string (serving as the identifier) and the value is of generic type T.
public class ConfigurableElement<T> : ConfigurationElement, IKeyedConfigurationElement
{
    // Static properties for configuration registration.
    private static readonly ConfigurationProperty nameProperty =
        new ConfigurationProperty("name", typeof(string), null,
            ConfigurationPropertyOptions.IsKey | ConfigurationPropertyOptions.IsRequired);

    private static readonly ConfigurationProperty valueProperty =
        new ConfigurationProperty("value", typeof(T), default(T),
            ConfigurationPropertyOptions.IsRequired);

    // Static collection of all configuration properties.
    private static readonly ConfigurationPropertyCollection properties = new ConfigurationPropertyCollection();

    // Static constructor to add properties to the collection.
    static ConfigurableElement()
    {
        properties.Add(nameProperty);
        properties.Add(valueProperty);
    }

    // Private fields to store lazy-assigned values.
    private bool _isNameSet = false;
    private bool _isValueSet = false;
    private string _name;
    private T _value;

    // Public property to expose the key (same as Name).
    public string Key
    {
        get { return Name; }
    }

    // Public property to get or set the name (identifier) of the element.
    public string Name
    {
        get
        {
            if (!_isNameSet)
            {
                _name = (string)this[nameProperty];
                _isNameSet = true;
            }
            return _name;
        }
        set
        {
            _name = value;
            _isNameSet = true;
            this[nameProperty] = value;
        }
    }

    // Public property to get or set the value of type T.
    public T Value
    {
        get
        {
            if (!_isValueSet)
            {
                _value = (T)this[valueProperty];
                _isValueSet = true;
            }
            return _value;
        }
        set
        {
            _value = value;
            _isValueSet = true;
            this[valueProperty] = value;
        }
    }

    // Override to return the configuration properties collection.
    protected override ConfigurationPropertyCollection Properties
    {
        get { return properties; }
    }

