        public mxCellCodec()
            : this(new mxCell(), new string[] { "children", "edges" }, new string[] { "parent", "source", "target" },
                    null) { }

        /// <summary>
        /// Constructs a new cell codec for the given template.
        /// </summary>
        public mxCellCodec(Object template) : this(template, null, null, null) { }

