using System;
using System.Collections.Generic;
 
namespace prog
{
    class MainClass
    {
        public static void Main (string[] args)
        {
            for( int i=1; i<=22; i++ )
            {
                List<int> f = Factorize(i);
                Console.Write( i + ":  " + f[0] );
                for( int j=1; j<f.Count; j++ )
                {
                    Console.Write( " * " + f[j] );
                }
                Console.WriteLine();
            }
        }
 
        public static List<int> Factorize( int n )
        {
            List<int> l = new List<int>();
 
            if ( n == 1 )
            {
                l.Add(1);
            }
            else
            {
                int k = 2;
                while( n > 1 )
                {
                    while( n % k == 0 )
                    {
                        l.Add( k );
                        n /= k;
                    }
                    k++;
                }
            }
            return l;
        }
    }
}

public readonly struct UnaryOperatorAnalysisResult
{
    public UnaryOperatorAnalysisResult(
        OperatorAnalysisResultKind kind,
        IMethodSymbol signature,
        Conversion conversion)
    {
        Kind = kind;
        Signature = signature;
        Conversion = conversion;
    }

    public OperatorAnalysisResultKind Kind { get; }
    public IMethodSymbol Signature { get; }
    public Conversion Conversion { get; }

    public bool IsApplicable => Kind == OperatorAnalysisResultKind.Applicable;
    public bool IsInapplicable => Kind == OperatorAnalysisResultKind.Inapplicable;
    public bool IsWorse => Kind == OperatorAnalysisResultKind.Worse;

    public static UnaryOperatorAnalysisResult Applicable(
        IMethodSymbol signature,
        Conversion conversion) =>
        new UnaryOperatorAnalysisResult(
            OperatorAnalysisResultKind.Applicable,
            signature,
            conversion);

    public static UnaryOperatorAnalysisResult Inapplicable(
        IMethodSymbol signature) =>
        new UnaryOperatorAnalysisResult(
            OperatorAnalysisResultKind.Inapplicable,
            signature,
            Conversion.None);

    public static UnaryOperatorAnalysisResult Worse(
        IMethodSymbol signature) =>
        new UnaryOperatorAnalysisResult(
            OperatorAnalysisResultKind.Worse,
            signature,
            Conversion.None);

    public UnaryOperatorAnalysisResult WithConversion(Conversion conversion) =>
        new UnaryOperatorAnalysisResult(Kind, Signature, conversion);
}

public enum OperatorAnalysisResultKind
{
    Applicable,
    Inapplicable,
    Worse
}

