using System;
using System.Collections.Generic;
using Android.App;
using Android.Content;
using KeePassLib;
using KeePassLib.Interfaces;

namespace Keepass2Android
{
    public class DeleteEntry : DeleteRunnable
    {
        private PwEntry _entry;
        private string _statusMessage;

        public DeleteEntry(PwEntry entry, Activity activity, IKp2aApp app)
            : base(activity, app)
        {
            _entry = entry;
        }

        protected override bool CanRecycle()
        {
            return Database.RecycleBinEnabled && _entry.ParentGroup.EnableRecycleBin;
        }

        protected override int QuestionRecycleResourceId()
        {
            return Resource.String.confirm_delete_recycle;
        }

        protected override int QuestionNoRecycleResourceId()
        {
            return Resource.String.confirm_delete_permanent;
        }

        protected override void PerformDelete(List<PwGroup> touchedGroups, List<PwGroup> permanentlyDeletedGroups)
        {
            if (CanRecycle())
            {
                Database.MoveToRecycleBin(_entry, touchedGroups);
                _statusMessage = Resource.String.entry_deleted_recycle;
            }
            else
            {
                Database.DeleteEntry(_entry, true, touchedGroups, permanentlyDeletedGroups);
                _statusMessage = Resource.String.entry_deleted_permanent;
            }
        }

        protected override string StatusMessage()
        {
            return _statusMessage;
        }
    }
}

