namespace Entropy
{
    class Parser
    {
        static void Main(string[] args)
        {
            Console.WriteLine(H("1223334444"));
        }

        static double H(string data)
        {
            if (data == "")
            {
                return 0;
            }
            double entropy = 0;
            for (int i = 0; i < 256; i++)
            {
                double px = (double)data.Count(x => x == (char)i) / (double)data.Length;
                if (px > 0)
                {
                    entropy += -px * Math.Log(px, 2);
                }
            }
            return entropy;
        }
    }
}

