public static List<HashSet<int>> consolidate(List<HashSet<int>> sets)
{
    List<HashSet<int>> setlist = new List<HashSet<int>>();
    foreach (var s in sets)
    {
        if (s!= null)
        {
            setlist.Add(s);
        }
    }
    for (int i = 0; i < setlist.Count; i++)
    {
        var s1 = setlist[i];
        if (s1!= null)
        {
            for (int j = i + 1; j < setlist.Count; j++)
            {
                var s2 = setlist[j];
                var intersection = s1.Intersect(s2);
                if (intersection.Any())
                {
                    s2.UnionWith(s1);
                    s1.Clear();
                    s1 = s2;
                }
            }
        }
    }
    return setlist.Where(s => s!= null).ToList();
}

using System;
using System.Collections.Generic;
using System.Windows.Forms;

public class Trait
{
    protected string name;
    protected string custom;
    protected int genNum;
    protected int profNum;
    protected string desc;
    protected int usedTP;
    protected static int totalTP = 100;

    public Trait()
    {
        name = "Default Trait";
        custom = "";
        genNum = 1;
        profNum = 0;
        desc = "No description available";
        usedTP = 0;
    }

    public Trait(string baseName, int generation = 1)
    {
        name = baseName;
        custom = "";
        genNum = generation;
        profNum = 0;
        desc = "Standard trait description";
        usedTP = 0;
    }

    public Trait(string baseName, string customName, int generation = 1)
    {
        name = baseName;
        custom = customName;
        genNum = generation;
        profNum = 0;
        desc = "Customized trait description";
        usedTP = 0;
    }

    public string getName()
    {
        return string.IsNullOrEmpty(custom) ? name : custom;
    }

    public int getTotal()
    {
        return totalTP - usedTP;
    }

    public void updateUsedTP(int points)
    {
        if (usedTP + points <= totalTP)
            usedTP += points;
        else
            MessageBox.Show("Insufficient trait points!");
    }
}

public class SpTrait : Trait
{
    private bool isSpecial;
    private List<string> variations;

    public SpTrait() : base()
    {
        isSpecial = false;
        variations = new List<string>();
    }

    public SpTrait(string baseName, bool special = false) : base(baseName)
    {
        isSpecial = special;
        variations = new List<string>();
    }

    public void addVariation(string variation)
    {
        if (!variations.Contains(variation))
            variations.Add(variation);
    }

    public List<string> getVariations()
    {
        return variations;
    }

    public bool checkSpecialStatus()
    {
        return isSpecial;
    }
}

