using Oberon0.Compiler.Definitions;
using Oberon0.Compiler.Expressions;
using Oberon0.Compiler.Expressions.Constant;
using Oberon0.Compiler.Expressions.Operations;
using Oberon0.Compiler.Types;

[ArithmeticOperation("*", PredefinedTypes.IntType, PredefinedTypes.IntType)]
[ArithmeticOperation("*", PredefinedTypes.RealType, PredefinedTypes.RealType)]
[ArithmeticOperation("*", PredefinedTypes.IntType, PredefinedTypes.RealType)]
[ArithmeticOperation("*", PredefinedTypes.RealType, PredefinedTypes.IntType)]
public class OpMulNumber : BinaryOperation
{
    protected override IExpression BinaryOperate(
        [NotNull] IExpression left,
        [NotNull] IExpression right)
    {
        var leftConst = left as Constant;
        var rightConst = right as Constant;

        if (leftConst?.IsConstant == true && rightConst?.IsConstant == true)
        {
            var leftType = leftConst.Type;
            var rightType = rightConst.Type;

            if (leftType == PredefinedTypes.IntType && rightType == PredefinedTypes.IntType)
            {
                var resultValue = (int)leftConst.Value * (int)rightConst.Value;
                return new Constant(resultValue, PredefinedTypes.IntType);
            }

            var leftVal = leftType == PredefinedTypes.IntType
                ? Convert.ToDouble((int)leftConst.Value)
                : (double)leftConst.Value;

            var rightVal = rightType == PredefinedTypes.IntType
                ? Convert.ToDouble((int)rightConst.Value)
                : (double)rightConst.Value;

            var resultType = leftType == PredefinedTypes.RealType || rightType == PredefinedTypes.RealType
                ? PredefinedTypes.RealType
                : PredefinedTypes.IntType;

            return resultType == PredefinedTypes.RealType
                ? new Constant(leftVal * rightVal, PredefinedTypes.RealType)
                : new Constant((int)(leftVal * rightVal), PredefinedTypes.IntType);
        }

        return new BinaryExpression(
            left,
            right,
            OberonGrammarLexer.STAR,
            GetResultType(left.Type, right.Type));
    }

    private static TypeDefinition GetResultType(TypeDefinition left, TypeDefinition right)
    {
        return left == PredefinedTypes.RealType || right == PredefinedTypes.RealType
            ? PredefinedTypes.RealType
            : PredefinedTypes.IntType;
    }
}

