{
    public static IEnumerable<IModelElement> Descendants(this IModelElement element)
    {
        if (element == null) throw new ArgumentNullException(nameof(element));

        var descendants = new DescendantsCollection(element);
        return descendants;
    }

    public static void Serialize(this IModelElement element, string path, IModelSerializer serializer)
    {
        if (element == null) throw new ArgumentNullException(nameof(element));
        if (string.IsNullOrEmpty(path)) throw new ArgumentNullException(nameof(path));
        if (serializer == null) throw new ArgumentNullException(nameof(serializer));

        var uri = new Uri(path, UriKind.RelativeOrAbsolute);
        Serialize(element, uri, serializer);
    }

    public static void Serialize(this IModelElement element, Uri uri, IModelSerializer serializer)
    {
        if (element == null) throw new ArgumentNullException(nameof(element));
        if (uri == null) throw new ArgumentNullException(nameof(uri));
        if (serializer == null) throw new ArgumentNullException(nameof(serializer));

        var model = element.Model;
        if (model == null)
        {
            model = new Model();
            model.RootElements.Add(element);
        }

        model.ModelUri = uri;
        serializer.Serialize(model, uri);
    }

    public static void Serialize(this IModelElement element, Stream target, IModelSerializer serializer)
    {
        if (element == null) throw new ArgumentNullException(nameof(element));
        if (target == null) throw new ArgumentNullException(nameof(target));
        if (serializer == null) throw new ArgumentNullException(nameof(serializer));

        var model = element.Model;
        if (model == null)
        {
            model = new Model();
            model.RootElements.Add(element);
        }

        serializer.Serialize(model, target);
    }

