namespace MyWebApp
{
    // Custom middleware for callback processing
    public class CallbackMiddleware
    {
        private readonly RequestDelegate _next;
        private readonly Action<HttpContext> _callback;

        public CallbackMiddleware(RequestDelegate next, Action<HttpContext> callback)
        {
            _next = next;
            _callback = callback;
        }

        public async Task InvokeAsync(HttpContext context)
        {
            // Execute custom callback logic before continuing the pipeline
            _callback(context);
            await _next(context);
        }
    }

    // Extension method to add the custom callback middleware
    public static class CallbackMiddlewareExtensions
    {
        public static IApplicationBuilder UseCallback(this IApplicationBuilder builder, Action<HttpContext> callback)
        {
            return builder.UseMiddleware<CallbackMiddleware>(callback);
        }
    }

