using System;
using System.Xml;

public interface IXmlOriginalDocumentService
{
    XmlNode GetOriginalNode(XmlNode transformedNode);
}

public class XmlTransformableDocument : XmlDocument, IXmlOriginalDocumentService
{
    private XmlDocument xmlOriginal;
    private bool isCloned = false;
    private bool isModified = false;

    public bool IsModified => isModified;

    public XmlNode GetOriginalNode(XmlNode transformedNode)
    {
        if (xmlOriginal == null)
            throw new InvalidOperationException("Original document not cloned.");

        string xpath = GetNodeXPath(transformedNode);
        return xmlOriginal.SelectSingleNode(xpath) ?? throw new Exception("Original node not found");
    }

    private string GetNodeXPath(XmlNode node)
    {
        if (node is XmlDocument) return "/";
        if (node.ParentNode == null) return node.Name;

        int index = GetSiblingIndex(node);
        return $"{GetNodeXPath(node.ParentNode)}/{node.Name}[{index}]";
    }

    private int GetSiblingIndex(XmlNode node)
    {
        int count = 1;
        foreach (XmlNode sibling in node.ParentNode.ChildNodes)
        {
            if (sibling == node) return count;
            if (sibling.Name == node.Name) count++;
        }
        return 1;
    }

    public void CloneOriginalDocument()
    {
        if (xmlOriginal != null) return;
        xmlOriginal = (XmlDocument)this.Clone();
        isCloned = true;
    }

    public bool IsXmlEqual()
    {
        return false; // Placeholder for XML diff logic
    }

    public void OnBeforeChange()
    {
        if (!isCloned) CloneOriginalDocument();
    }

    public void OnAfterChange()
    {
        isModified = true;
    }

    protected override XmlNode InsertBefore(XmlNode newNode, XmlNode refNode)
    {
        OnBeforeChange();
        var result = base.InsertBefore(newNode, refNode);
        OnAfterChange();
        return result;
    }

    protected override XmlNode InsertAfter(XmlNode newNode, XmlNode refNode)
    {
        OnBeforeChange();
        var result = base.InsertAfter(newNode, refNode);
        OnAfterChange();
        return result;
    }

    protected override XmlNode AppendChild(XmlNode newChild)
    {
        OnBeforeChange();
        var result = base.AppendChild(newChild);
        OnAfterChange();
        return result;
    }

    public override XmlNode RemoveChild(XmlNode oldChild)
    {
        OnBeforeChange();
        var result = base.RemoveChild(oldChild);
        OnAfterChange();
        return result;
    }
}

