using System;
using System.Linq;
using System.Collections.Generic;
 
public class MoveToFront
{
  private static readonly char[] ABC = Enumerable.Range('a', 'z' - 'a' + 1).Select(i => (char)i).ToArray();
 
  public static int[] Encode(string str)
  {
    var ar = ABC.ToArray();
    return str.Select(c =>
    {
      var i = Array.IndexOf(ar, c);
      Array.Copy(ar, i + 1, ar, i, ar.Length - i - 1);
      ar[0] = c;
      return i;
    }).ToArray();
  }
 
  public static string Decode(int[] indices)
  {
    var ar = ABC.ToArray();
    return indices.Aggregate("", (str, i) =>
    {
      str += ar[i];
      Array.Copy(ar, i + 1, ar, i, ar.Length - i - 1);
      ar[0] = str[str.Length - 1];
      return str;
    });
  }
}
 
public class Writer
{
  public static void Main()
  {
    var words = new[] { "broood", "bananaaa", "hiphophiphop" };
    foreach (var word in words)
    {
      var encoded = MoveToFront.Encode(word);
      var decoded = MoveToFront.Decode(encoded);
      Console.WriteLine(word == decoded);
    }
  }
}

