using UnityEngine;

public class GetDeviceRoll : MonoBehaviour
{
    public enum BaseOrientation
    {
        Portrait,
        LandscapeLeft,
        LandscapeRight,
        PortraitUpsideDown
    }

    [Header("Device Orientation Settings")]
    public BaseOrientation referenceOrientation = BaseOrientation.Portrait;
    public float limitAngle = 20.0f; // Limits the angle to this value if set
    public float smoothingFactor = 0.1f; // Factor for smoothing the angle transitions
    public bool continuousUpdate = true; // Whether to continuously update the angle

    private float storeAngle = 0.0f; // Variable to store the processed angle
    private float currentAngle = 0.0f; // Current angle for smoothing
    private bool isUpdating = false; // Indicates if the update is active

    void Start()
    {
        Reset();
    }

    void Update()
    {
        if (isUpdating && continuousUpdate)
        {
            OnUpdate();
        }
    }

    public void Reset()
    {
        storeAngle = 0.0f;
        currentAngle = 0.0f;
        isUpdating = false;
    }

    public void OnEnter()
    {
        isUpdating = true;
        DoGetDeviceRoll();
    }

    public void OnExit()
    {
        isUpdating = false;
    }

    private void OnUpdate()
    {
        DoGetDeviceRoll();
    }

    private void DoGetDeviceRoll()
    {
        Vector3 acceleration = Input.acceleration; // Get device acceleration
        float angle = CalculateAngle(acceleration); // Calculate the roll angle
        storeAngle = Mathf.Clamp(angle, -limitAngle, limitAngle); // Constrain the angle

        // Smooth the angle over time
        currentAngle = Mathf.Lerp(currentAngle, storeAngle, smoothingFactor);
        Debug.Log("Current Angle: " + currentAngle);
    }

    private float CalculateAngle(Vector3 acceleration)
    {
        float angle = 0.0f;

        switch (referenceOrientation)
        {
            case BaseOrientation.Portrait:
                angle = Mathf.Atan2(acceleration.x, acceleration.y) * Mathf.Rad2Deg;
                break;
            case BaseOrientation.LandscapeLeft:
                angle = Mathf.Atan2(acceleration.y, -acceleration.x) * Mathf.Rad2Deg;
                break;
            case BaseOrientation.LandscapeRight:
                angle = Mathf.Atan2(-acceleration.y, acceleration.x) * Mathf.Rad2Deg;
                break;
            case BaseOrientation.PortraitUpsideDown:
                angle = Mathf.Atan2(-acceleration.x, -acceleration.y) * Mathf.Rad2Deg;
                break;
        }

        return angle;
    }
}

using Microsoft.AspNetCore.Mvc;
