namespace DiscountAPI.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class DiscountsController : ControllerBase
    {
        private readonly IDiscountApplicationService _discountService;
        private readonly IGalleryApplicationService _galleryService;

        public DiscountsController(IDiscountApplicationService discountService, IGalleryApplicationService galleryService)
        {
            _discountService = discountService;
            _galleryService = galleryService;
        }

        [HttpGet("all")]
        public async Task<ActionResult<IEnumerable<DiscountDto>>> GetAllDiscountsAsync([FromQuery] string syncDate)
        {
            if (!string.IsNullOrEmpty(syncDate) && !DateTime.TryParse(syncDate, out _))
            {
                return BadRequest("Invalid date format.");
            }

            var discounts = await _discountService.GetAllDiscountsAsync(syncDate);
            return Ok(discounts);
        }

        [HttpGet("image/{id}")]
        public async Task<IActionResult> GetImageAsync(string id)
        {
            if (string.IsNullOrEmpty(id))
            {
                return BadRequest("Image identifier is required.");
            }

            var image = await _galleryService.GetImageAsync(id);
            if (image == null)
            {
                return NotFound("Image not found.");
            }

            return File(image.Content, image.ContentType);
        }

        [HttpGet("logo/{id}")]
        public async Task<IActionResult> GetLogoAsync(string id)
        {
            if (string.IsNullOrEmpty(id))
            {
                return BadRequest("Logo identifier is required.");
            }

            var logo = await _galleryService.GetLogoAsync(id);
            if (logo == null)
            {
                return NotFound("Logo not found.");
            }

            return File(logo.Content, logo.ContentType);
        }
    }

