using System;
using System.Threading;

public class RateCounter
{
    private readonly int resolutionMs;
    private readonly int slotCount;
    private readonly int[] counts;
    private int currentIndex;
    private long lastUpdatedTime;
    private int maxRate;
    private readonly object lockObject = new object();

    public RateCounter(int resolutionMs)
    {
        if (1000 % resolutionMs != 0)
            throw new ArgumentException("Resolution must be a divisor of 1000.");

        this.resolutionMs = resolutionMs;
        this.slotCount = 1000 / resolutionMs;
        this.counts = new int[slotCount];
        this.currentIndex = 0;
        this.lastUpdatedTime = Time.CurrentTimeMillis();
        this.maxRate = 0;
    }

    public void Count(long timeMillis, int count)
    {
        lock (lockObject)
        {
            UpdateSlots(timeMillis);
            counts[currentIndex] += count;
            maxRate = Math.Max(maxRate, GetCurrentRate());
        }
    }

    public int GetCurrentRate()
    {
        lock (lockObject)
        {
            UpdateSlots(Time.CurrentTimeMillis());
            int total = 0;
            for (int i = 0; i < slotCount; i++)
            {
                total += counts[i];
            }
            return total;
        }
    }

    public int GetMaxRate()
    {
        lock (lockObject)
        {
            return maxRate;
        }
    }

    private void UpdateSlots(long currentTime)
    {
        long timeElapsed = currentTime - lastUpdatedTime;
        if (timeElapsed >= resolutionMs)
        {
            int slotsToAdvance = (int)(timeElapsed / resolutionMs);
            for (int i = 0; i < slotsToAdvance; i++)
            {
                currentIndex = (currentIndex + 1) % slotCount;
                counts[currentIndex] = 0;
            }
            lastUpdatedTime += slotsToAdvance * resolutionMs;
        }
    }
}

public static class Time
{
    public static long CurrentTimeMillis()
    {
        return DateTimeOffset.Now.ToUnixTimeMilliseconds();
    }
}

