namespace VSTestValidation
{
    public class VSTestTests
    {
        private const string TestApplicationName = "VSTestSampleApp";
        private readonly string _testProjectRoot;
        private readonly string _configuration;

        public VSTestTests()
        {
            _testProjectRoot = Path.Combine(
                AppContext.BaseDirectory,
                "TestAssets",
                TestApplicationName
            );
            _configuration = Environment.GetEnvironmentVariable("CONFIGURATION") ?? "Debug";
        }

        [Fact]
        public void VSTestCommand_ShouldExecuteTestsSuccessfully()
        {
            // Arrange
            var testProject = new TestProjectWithNativeTools(
                _testProjectRoot,
                TestApplicationName
            );

            testProject.Restore()
                .WithSourceFiles()
                .WithRestoreFiles();

            var buildResult = buildResult = BuildCommand
                .Create(_testProjectRoot)
                .WithConfiguration(_configuration)
                .Execute();

            buildResult.Should().NotBeNull();
            buildResult.ExitCode.Should().Be(0, "Project build should succeed");

            // Act
            var testCommand = new VSTestCommand()
                .WithTestAssembly(GetTestAssemblyPath())
                .WithLogger("trx")
                .Execute();

            // Assert
            testCommand.ExitCode.Should().Be(0, "All tests should pass");
            testCommand.StdOut.Should().Contain("Passed", "Test suite should report successful tests");
            testCommand.StdOut.Should().NotContain("Failed", "No tests should fail");
        }

        private string GetTestAssemblyPath()
        {
            return Path.Combine(
                _testProjectRoot,
                "bin",
                _configuration,
                "netcoreapp3.1",
                $"{TestApplicationName}.dll"
            );
        }
    }

