public class CameraImageSensor : MonoBehaviour
{
    // Public sensor configuration fields
    public Camera sensorCamera;
    public int imageWidth = 640;
    public int imageHeight = 480;
    public float fieldOfView = 60f;
    public bool convertToGrayscale = false;
    public ImageEncodingFormat encodingFormat = ImageEncodingFormat.PNG;

    // Off-screen rendering objects
    private RenderTexture renderTexture;
    private Texture2D capturedTexture;

    // Captured image rectangle
    private Rect captureRect;

    // Sensor initialization flag
    private bool isInitialized = false;

    // Configure sensor parameters at runtime
    public void ConfigureSensor(Vector3 position, Quaternion rotation, float newFOV, int width, int height, bool toGrayscale, ImageEncodingFormat format)
    {
        // Adjust camera transform and fov
        if(sensorCamera != null)
        {
            sensorCamera.transform.position = position;
            sensorCamera.transform.rotation = rotation;
            sensorCamera.fieldOfView = newFOV;
        }

        // Set sensor parameters
        fieldOfView = newFOV;
        imageWidth = width;
        imageHeight = height;
        convertToGrayscale = toGrayscale;
        encodingFormat = format;

        // Reinitialize sensor to match new dimensions
        InitializeSensor();
    }

    // Initialize the render texture and the Texture2D that holds the captured image.
    public void InitializeSensor()
    {
        // Cleanup existing resources if they exist
        if(renderTexture != null)
        {
            renderTexture.Release();
            renderTexture = null;
        }
        if(capturedTexture != null)
        {
            Destroy(capturedTexture);
            capturedTexture = null;
        }

        // Setup the RenderTexture
        renderTexture = new RenderTexture(imageWidth, imageHeight, 24);
        if(sensorCamera != null)
        {
            sensorCamera.targetTexture = renderTexture;
        }

        // Create a texture to store the captured image
        capturedTexture = new Texture2D(imageWidth, imageHeight, TextureFormat.RGB24, false);
        captureRect = new Rect(0, 0, imageWidth, imageHeight);

        isInitialized = true;
    }

    // Capture the current view from the sensor camera
    public byte[] CaptureImage()
    {
        if (!isInitialized)
        {
            InitializeSensor();
        }

