    // Enum for metric counter fields
    public enum CounterFields
    {
        Requests,
        Errors,
        Warnings,
        Successes,
        Timeouts,
        // Additional fields can be added here
    }

    // Static class providing extension methods for IDictionary handling metric counter fields
    public static class MetricCounterFieldsExtensions
    {
        /// <summary>
        /// Excludes the specified fields from the dictionary.
        /// If the list of fields is null or empty, the entire dictionary is cleared.
        /// </summary>
        /// <param name="dictionary">The dictionary to modify.</param>
        /// <param name="fields">The fields to exclude.</param>
        /// <returns>The modified dictionary.</returns>
        public static IDictionary<CounterFields, string> Exclude(this IDictionary<CounterFields, string> dictionary, IEnumerable<CounterFields> fields)
        {
            if (dictionary == null)
            {
                throw new ArgumentNullException(nameof(dictionary));
            }

            if (fields == null || !fields.Any())
            {
                dictionary.Clear();
                return dictionary;
            }

            // Remove each specified field if it exists in the dictionary
            foreach (var field in fields)
            {
                if (dictionary.ContainsKey(field))
                {
                    dictionary.Remove(field);
                }
            }
            return dictionary;
        }

        /// <summary>
        /// Restricts the dictionary to only include the specified fields.
        /// Any field not in the provided list is removed.
        /// </summary>
        /// <param name="dictionary">The dictionary to filter.</param>
        /// <param name="fields">The fields to keep.</param>
        /// <returns>The filtered dictionary.</returns>
        public static IDictionary<CounterFields, string> OnlyInclude(this IDictionary<CounterFields, string> dictionary, IEnumerable<CounterFields> fields)
        {
            if (dictionary == null)
            {
                throw new ArgumentNullException(nameof(dictionary));
            }

            if (fields == null)
            {
                throw new ArgumentNullException(nameof(fields));
            }

            // Create a temporary list of keys to iterate over safely
            var keysToRemove = dictionary.Keys.Where(key => !fields.Contains(key)).ToList();

