public class ResourceTypeInfo
{
    public readonly string Name;
    public readonly string[] Variants;
    public readonly string[] TerrainTypes;
    public readonly int MaxDensity;
    public readonly int SpreadRadius;
    public readonly bool AllowSteepTerrain;
    public readonly int ValuePerUnit;

    public ResourceTypeInfo(string name, string[] variants, string[] terrainTypes,
        int maxDensity = 10, int spreadRadius = 3, bool allowSteepTerrain = false, int valuePerUnit = 100)
    {
        Name = name;
        Variants = variants;
        TerrainTypes = terrainTypes;
        MaxDensity = maxDensity;
        SpreadRadius = spreadRadius;
        AllowSteepTerrain = allowSteepTerrain;
        ValuePerUnit = valuePerUnit;
    }

    public virtual ResourceType Create(World world, WorldRenderer renderer)
    {
        return new ResourceType(this, world, renderer);
    }
}

public class ResourceType
{
    private readonly ResourceTypeInfo info;
    private readonly World world;
    private readonly WorldRenderer renderer;
    private readonly Dictionary<string, Sprite[]> spriteVariants;
    private readonly PaletteReference palette;

    public ResourceType(ResourceTypeInfo resourceInfo, World world, WorldRenderer renderer)
    {
        info = resourceInfo;
        this.world = world;
        this.renderer = renderer;
        palette = renderer.Palette(info.Name + "Palette");
        spriteVariants = GenerateSpriteVariants();
    }

    private Dictionary<string, Sprite[]> GenerateSpriteVariants()
    {
        var variants = new Dictionary<string, Sprite[]>();
        foreach (var variant in info.Variants)
        {
            variants[variant] = MakeArray(variant);
        }
        return variants;
    }

    private Sprite[] MakeArray(string variant)
    {
        var spriteSequence = renderer.Sequences.GetSequence(info.Name, variant);
        return spriteSequence.Frames;
    }

    public bool CanPlace(CPos cell)
    {
        var terrainType = world.Map.TerrainInfo.GetTerrainType(cell);
        return info.TerrainTypes.Contains(terrainType) &&
               (info.AllowSteepTerrain || world.Map.TerrainInfo.GetTerrainSlope(cell) <= 20);
    }

    public int GetResourceValue(int quantity)
    {
        return quantity * info.ValuePerUnit;
    }

    public void WorldLoaded()
    {
        foreach (var cell in world.Map.AllCells)
        {
            if (CanPlace(cell))
            {
                TrySpawnResource(cell);
            }
        }

