using System;
using System.Collections.Generic;
using System.Linq;
 
namespace LexicographicalOrder
{
    class Cache
    {
        static void Main(string[] args)
        {
            Console.WriteLine("In lexicographical order:\n");
            foreach (var n in new[] { 0, 5, 13, 21, -22 })
            {
                Console.WriteLine("{0,3}: {1}", n, string.Join(", ", LexOrder(n)));
            }
        }
 
        static IEnumerable<int> LexOrder(int n)
        {
            var first = 1;
            var last = n;
            var k = n;
            if (n < 1)
            {
                first = n;
                last = 1;
                k = 2 - n;
            }
            var strs = new string[k];
            for (var i = first; i <= last; i++)
            {
                strs[i - first] = i.ToString();
            }
            var ints = new int[k];
            for (var i = 0; i < k; i++)
            {
                ints[i] = int.Parse(strs[i]);
            }
            return ints;
        }
    }
}

