using Antlr4.Runtime;
using Rubberduck.VBEditor;

namespace Rubberduck.Parsing
{
    public class QualifiedContext
    {
        public QualifiedContext(QualifiedMemberName memberName, ParserRuleContext context)
            : this(memberName.QualifiedModuleName, context)
        {
            MemberName = memberName;
        }

        public QualifiedContext(QualifiedModuleName moduleName, ParserRuleContext context)
        {
            ModuleName = moduleName;
            Context = context;
        }

        public QualifiedMemberName MemberName { get; }
        public QualifiedModuleName ModuleName { get; }
        public ParserRuleContext Context { get; }

        public override int GetHashCode()
        {
            return Context.GetHashCode();
        }

        public override bool Equals(object obj)
        {
            var other = obj as QualifiedContext;
            if (other == null)
            {
                return false;
            }

            return other.ModuleName == ModuleName && other.MemberName == MemberName;
        }

        public static bool operator ==(QualifiedContext context1, QualifiedContext context2)
        {
            if ((object)context1 == null)
            {
                return (object)context2 == null;
            }

            return context1.Equals(context2);
        }

        public static bool operator !=(QualifiedContext context1, QualifiedContext context2)
        {
            if ((object)context1 == null)
            {
                return (object)context2 != null;
            }

            return !context1.Equals(context2);
        }
    }

    public class QualifiedContext<TContext> : QualifiedContext
        where TContext : ParserRuleContext
    {
        public QualifiedContext(QualifiedMemberName memberName, TContext context)
            : base(memberName, context)
        {
        }

        public QualifiedContext(QualifiedModuleName qualifiedName, TContext context)
            :base(qualifiedName, context)
        {
        }

        public new TContext Context => base.Context as TContext;
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
 
namespace AsciiTable
{
    class Helper
    {
        static void Main(string[] args)
        {
            Console.WriteLine(asciiTable());
        }
 
        // ------------------- ASCII TABLE -------------------
 
        // asciiTable :: String
        static string asciiTable() =>
            transpose(
                chunksOf(16)(
                    enumFromTo(32)(127)
                   .Select(asciiEntry)
                )
            )
           .Select(
                xs => xs.Select(justifyLeft(12)(" "))
               .Aggregate((a, b) => a + b)
            )
           .Aggregate((a, b) => a + "\n" + b);
 
        // asciiEntry :: Int -> String
        static string asciiEntry(int n)
        {
            var k = asciiName(n);
 
            return "" == k? (
                ""
            ) : $"{justifyRight(4)(" ")(n.ToString())} : {k}";
        }
 
        // asciiName :: Int -> String
        static string asciiName(int n) =>
            32 > n || 127 < n? (
                ""
            ) : 32 == n? (
                "Spc"
            ) : 127 == n? (
                "Del"
            ) : chr(n);
 
        // ---------------- GENERIC FUNCTIONS ----------------
 
        // chr :: Int -> Char
        static char chr(int x) =>
            // The character at unix code-point x.
            (char)x;
 
        // chunksOf :: Int -> [a] -> [[a]]
        static List<List<T>> chunksOf<T>(int n) =>
            // xs split into sublists of length n.
            // The last sublist will be short if n
            // does not evenly divide the length of xs.
            xs => {
                var go = xs_ => {
                    var chunk = xs_.Take(n).ToList();
 
                    return 0 < chunk.Count? (
                        new List<List<T>> { chunk }.Concat(
                            go(xs_.Skip(n).ToList())
                        ).ToList()
                    ) : new List<List<T>>();
                };
 
                return go(xs);
            };
 
        // enumFromTo :: Int -> Int -> [Int]
        static List<int> enumFromTo(int m) =>
            n => Enumerable.Range(m, 1 + n - m).ToList();
 
        // justifyLeft :: Int -> Char -> String -> String
        static Func<char, Func<string, string>> justifyLeft(int n) =>
            // The string s, followed by enough padding (with
            // the character c) to reach the string length n.
            c => s => n > s.Length? (
                s.PadRight(n, c)
            ) : s;

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Numerics;
using System.Diagnostics;
 
namespace Catalan
{
    class Stack
    {
        static void Main(string[] args)
        {
            var defs = new Func<int, BigInteger>[] { cat_direct, catR1, catR2 };
            var results = defs.Select(c => Enumerable.Range(0, 15).Select(i => c(i)).ToArray()).ToArray();
            var fmt = "{0,-10} {1,-10} {2,-10}";
            Console.WriteLine(fmt, defs.Select(c => c.Method.Name).ToArray());
            Console.WriteLine(fmt, Enumerable.Repeat("=", 3).ToArray());
            for (int i = 0; i < results[0].Length; i++)
            {
                Console.WriteLine(fmt, results.Select(r => r[i]).ToArray());
            }
        }
 
        static BigInteger fact(int n)
        {
            return Enumerable.Range(1, n).Aggregate(BigInteger.One, (a, b) => a * b);
        }
 
        static BigInteger cat_direct(int n)
        {
            return fact(2 * n) / (fact(n + 1) * fact(n));
        }
 
        static BigInteger catR1(int n)
        {
            if (n == 0) return 1;
            return Enumerable.Range(0, n).Aggregate(BigInteger.Zero, (a, i) => a + catR1(i) * catR1(n - 1 - i));
        }
 
        static BigInteger catR2(int n)
        {
            if (n == 0) return 1;
            return (4 * n - 2) * catR2(n - 1) / (n + 1);
        }
    }
}

