        [TestInitialize]
        public void Setup()
        {
            _mockContextWrapper = new Mock<IEfContextWrapper>();
            _mockArtistRepository = new Mock<IArtistRepository>();

            _creationService = new ArtistCreationService(
                _mockArtistRepository.Object,
                _mockContextWrapper.Object
            );
        }

        [TestMethod]
        public void CreateArtist_ValidName_ShouldAddToRepositoryAndSaveContext()
        {
            // Arrange
            string artistName = "John Doe";
            var expectedArtist = new Artist { Name = artistName };

            _mockArtistRepository
                .Setup(repo => repo.Add(It.IsAny<Artist>()))
                .Verifiable();

            _mockContextWrapper
                .Setup(context => context.SaveChanges())
                .Verifiable();

            // Act
            var result = _creationService.CreateArtist(artistName);

            // Assert
            _mockArtistRepository.Verify(
                repo => repo.Add(It.Is<Artist>(a => a.Name == artistName)),
                Times.Once
            );

            _mockContextWrapper.Verify(
                context => context.SaveChanges(),
                Times.Once
            );

            Assert.IsNotNull(result);
            Assert.AreEqual(artistName, result.Name);
        }

