using System.Drawing;
 
public class Pinstripe
{
    static void Main(string[] args)
    {
        var pinstripe = MakePinstripeImage(1366, 768);
        pinstripe.Save("pinstripe.png");
    }
 
    public static Bitmap MakePinstripeImage(int width, int height)
    {
        var image = new Bitmap(width, height);
        var quarterHeight = height / 4;
 
        for (var y = 0; y < height; y++)
        {
            var stripeWidth = (y / quarterHeight) + 1;
 
            for (var x = 0; x < width; x++)
            {
                var color = ((x / stripeWidth) % 2) == 0 ? Color.White : Color.Black;
                image.SetPixel(x, y, color);
            }
        }
 
        return image;
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
 
namespace ProjectEulerTasks
{
    internal class Task0063
    {
        public static void Run()
        {
            var cache = new List<List<BigInteger>> { new List<BigInteger> { 1 } };
            Console.WriteLine("rows:");
            for (var x = 1; x < 26; x++)
            {
                var v = Row(x, cache);
                var s = string.Join(" ", v.Select(e => e.ToString()));
                Console.WriteLine("{0}: {1}", x, s);
            }
            Console.WriteLine("sums:");
            foreach (var x in new[] { 23, 123, 1234, 12345 })
            {
                Cumu(x, cache);
                var v = cache[x];
                var s = v[v.Count - 1].ToString();
                Console.WriteLine("{0}: {1}", x, s);
            }
        }
 
        private static void Cumu(int n, List<List<BigInteger>> cache)
        {
            for (var l = cache.Count; l <= n; l++)
            {
                var r = new List<BigInteger> { 0 };
                for (var x = 1; x <= l; x++)
                {
                    var prev = r[r.Count - 1];
                    r.Add(prev + cache[l - x][Math.Min(x, l - x)]);
                }
                cache.Add(r);
            }
        }
 
        private static List<BigInteger> Row(int n, List<List<BigInteger>> cache)
        {
            Cumu(n, cache);
            var r = cache[n];
            var v = new List<BigInteger>();
            for (var i = 0; i < n; i++)
            {
                v.Add(r[i + 1] - r[i]);
            }
            return v;
        }
    }
}

