        static double sum(double[] arr)
        {
            return arr.Aggregate(0.0, (p, q) => p + q);
        }
 
        static double mean(double[] arr)
        {
            return sum(arr) / arr.Length;
        }
 
        static void Main(string[] args)
        {
            double[] v = { 2.0, 3.0, 5.0, 7.0, 13.0, 21.0, 33.0, 54.0 };
            Console.WriteLine("mean of {0}: {1}", string.Join(", ", v), mean(v));
 
            double[] w = { };
            Console.WriteLine("mean of {0}: {1}", string.Join(", ", w), mean(w));
        }
    }
}

