using System.Collections.Specialized;
using System.Web;
using Sitecore.Data.Items;
using Sitecore.Foundation.SitecoreExtensions.Extensions;
using Sitecore.Mvc;
using Sitecore.Mvc.Presentation;

public class AppDeeplinkViewModelRepository
{
    public AppDeeplinkViewModel Get()
    {
        Item contextItem = PageContext.Current?.Item;
        if (!ValidateContextItem(contextItem))
            return null;

        var viewModel = new AppDeeplinkViewModel
        {
            AppStoreUrl = GetContentField(contextItem, Constants.Fields.AppDeeplink.AppStoreUrl),
            AndroidUrl = GetContentField(contextItem, Constants.Fields.AppDeeplink.AndroidUrl),
            IOSUrl = GetContentField(contextItem, Constants.Fields.AppDeeplink.IOSUrl)
        };

        NameValueCollection deviceParams = ExtractDeviceParameters();
        viewModel.AndroidUrl = BuildDeviceUrlWithParams(viewModel.AndroidUrl, deviceParams);
        viewModel.IOSUrl = BuildDeviceUrlWithParams(viewModel.IOSUrl, deviceParams);

        return viewModel.IsValid() ? viewModel : null;
    }

    private bool ValidateContextItem(Item item)
    {
        return item != null && item.IsDerived(Constants.Templates.AppDeeplink);
    }

    private string GetContentField(Item item, string fieldId)
    {
        return item.Fields[fieldId]?.GetString();
    }

    private NameValueCollection ExtractDeviceParameters()
    {
        var parameters = new NameValueCollection();
        string paramPrefix = Constants.QueryParams.DeviceParams;

        foreach (string key in HttpContext.Current.Request.QueryString.AllKeys)
        {
            if (key?.StartsWith(paramPrefix) == true)
            {
                string cleanKey = key.Substring(paramPrefix.Length);
                parameters.Add(cleanKey, HttpContext.Current.Request.QueryString[key]);
            }
        }

        return parameters;
    }

    private string BuildDeviceUrlWithParams(string baseUrl, NameValueCollection parameters)
    {
        if (string.IsNullOrWhiteSpace(baseUrl))
            return null;

        try
        {
            var uriBuilder = new UriBuilder(baseUrl);
            NameValueCollection query = HttpUtility.ParseQueryString(uriBuilder.Query);

            foreach (string key in parameters)
                query[key] = HttpUtility.UrlEncode(parameters[key]);

            uriBuilder.Query = query.ToString();
            return uriBuilder.Uri.AbsoluteUri;
        }
        catch
        {
            return null;
        }
    }
}

