namespace StreamExtensionsDemo
{
    public static class StreamExtensions
    {
        // Reads the entire stream into a byte array.
        public static byte[] ReadAllBytes(this Stream stream)
        {
            if (stream == null)
                throw new ArgumentNullException(nameof(stream));

            if (stream is MemoryStream memoryStream)
            {
                return memoryStream.ToArray();
            }

            using (var tempStream = new MemoryStream())
            {
                stream.CopyTo(tempStream);
                return tempStream.ToArray();
            }
        }

        // Creates a factory function that returns a new stream instance based on buffered content.
        public static Func<Stream> ToStreamFactory(this Stream stream)
        {
            if (stream == null)
                throw new ArgumentNullException(nameof(stream));

            byte[] buffer = stream.ReadAllBytes();
            return () => new MemoryStream(buffer, writable: false);
        }

        // Reads the entire stream as a string, using specified encoding (defaulting to UTF8).
        public static string ReadToEnd(this Stream stream, Encoding encoding = null)
        {
            if (stream == null)
                throw new ArgumentNullException(nameof(stream));

            encoding = encoding ?? Encoding.UTF8;
            byte[] content = stream.ReadAllBytes();
            return encoding.GetString(content);
        }

        // Converts a string into a stream using specified encoding (defaulting to UTF8).
        public static Stream AsStream(this string text, Encoding encoding = null)
        {
            if (text == null)
                throw new ArgumentNullException(nameof(text));

            encoding = encoding ?? Encoding.UTF8;
            byte[] buffer = encoding.GetBytes(text);
            return new MemoryStream(buffer);
        }

        // Compares two streams by computing a checksum based on CRC32 algorithm.
        public static bool ContentEquals(this Stream stream1, Stream stream2)
        {
            if (stream1 == null)
                throw new ArgumentNullException(nameof(stream1));
            if (stream2 == null)
                throw new ArgumentNullException(nameof(stream2));

            byte[] data1 = stream1.ReadAllBytes();
            byte[] data2 = stream2.ReadAllBytes();
            uint checksum1 = Crc32.ComputeChecksum(data1);
            uint checksum2 = Crc32.ComputeChecksum(data2);
            return checksum1 == checksum2;

