public interface IFable : IDisposable
{
    string TopicName { get; }
    Task ProcessEventAsync(object payload);
}

public interface IStatefulTopic
{
    Task ReplayStateAsync();
}

public class EdgeSubscription
{
    public Guid Id { get; } = Guid.NewGuid();
    public string TopicName { get; }
    public Func<object, Task> Handler { get; }

    public EdgeSubscription(string topicName, Func<object, Task> handler)
    {
        TopicName = topicName;
        Handler = handler;
    }
}

public class EdgeHost
{
    private readonly ConcurrentDictionary<string, IFable> _fables = new ConcurrentDictionary<string, IFable>();
    private readonly ConcurrentDictionary<string, ConcurrentBag<EdgeSubscription>> _subscriptions = new ConcurrentDictionary<string, ConcurrentBag<EdgeSubscription>>();

    public void AddFable(IFable fable)
    {
        if (fable == null)
            throw new ArgumentNullException(nameof(fable));

        if (!_fables.TryAdd(fable.TopicName, fable))
            throw new InvalidOperationException($"Fable for topic {fable.TopicName} already exists");
    }

    public void RemoveFable(string topicName)
    {
        _fables.TryRemove(topicName, out _);
    }

    public EdgeSubscription SubscribeTopic(string topicName, Func<object, Task> handler)
    {
        var subscription = new EdgeSubscription(topicName, handler);
        return SubscribeTopicPrivate(subscription);
    }

    private EdgeSubscription SubscribeTopicPrivate(EdgeSubscription subscription)
    {
        var subscriptionCollection = _subscriptions.GetOrAdd(
            subscription.TopicName,
            _ => new ConcurrentBag<EdgeSubscription>()
        );

        subscriptionCollection.Add(subscription);

        if (_fables.TryGetValue(subscription.TopicName, out var fable) && fable is IStatefulTopic statefulTopic)
        {
            _ = statefulTopic.ReplayStateAsync();
        }

        return subscription;
    }

    public void UnsubscribeTopic(EdgeSubscription subscription)
    {
        if (_subscriptions.TryGetValue(subscription.TopicName, out var subscriptions))
        {
            var updatedSubscriptions = new ConcurrentBag<EdgeSubscription>(
                subscriptions.Where(s => s.Id != subscription.Id)
            );

            _subscriptions[subscription.TopicName] = updatedSubscriptions;
        }
    }

