public static class TestUtilities
{
    public static void AssertThrowsInvalidOperationException(Action action)
    {
        try
        {
            action.Invoke();
            Assert.Fail("Expected InvalidOperationException wasn't thrown.");
        }
        catch (InvalidOperationException) { }
        catch (Exception ex)
        {
            Assert.Fail($"Expected InvalidOperationException but got {ex.GetType().Name}.");
        }
    }

    public static void AssertThrowsArgumentException(Action action)
    {
        try
        {
            action.Invoke();
            Assert.Fail("Expected ArgumentException wasn't thrown.");
        }
        catch (ArgumentException) { }
        catch (Exception ex)
        {
            Assert.Fail($"Expected ArgumentException but got {ex.GetType().Name}.");
        }
    }

    public static void AssertAttached(DependencyObject obj, string behaviorName)
    {
        var isAttached = Behavior.GetBehavior(obj, behaviorName) != null;
        Assert.IsTrue(isAttached, $"Expected behavior '{behaviorName}' to be attached to the object.");
    }

    public static void AssertDetached(DependencyObject obj, string behaviorName)
    {
        var isAttached = Behavior.GetBehavior(obj, behaviorName) != null;
        Assert.IsFalse(isAttached, $"Expected behavior '{behaviorName}' to be detached from the object.");
    }

    public static void AssertNotAttached(DependencyObject obj, string behaviorName)
    {
        AssertDetached(obj, behaviorName);
    }

    public static void AssertNotDetached(DependencyObject obj, string behaviorName)
    {
        AssertAttached(obj, behaviorName);
    }
}

