namespace CustomDictionaryExample
{
    // Custom exception for duplicate keys
    public class DuplicateKeyException : Exception
    {
        public DuplicateKeyException()
            : base("A duplicate key was found in the dictionary.")
        {
        }

        public DuplicateKeyException(string message)
            : base(message)
        {
        }

        public DuplicateKeyException(string message, Exception innerException)
            : base(message, innerException)
        {
        }
    }

    // Custom dictionary implementation for string keys and values
    public class CustomStringDictionary : IEnumerable
    {
        // Internal storage using Hashtable for key-value pairs
        private Hashtable _storage;

        // Constructor initializes the underlying collection
        public CustomStringDictionary()
        {
            _storage = new Hashtable();
        }

        // Adds a new key-value pair to the dictionary
        public void Add(string key, string value)
        {
            // Validate input
            if (string.IsNullOrEmpty(key))
            {
                throw new ArgumentException("Key cannot be null or empty.", nameof(key));
            }

            if (value == null)
            {
                throw new ArgumentNullException(nameof(value), "Value cannot be null.");
            }

            // Check for duplicate key
            if (_storage.ContainsKey(key))
            {
                throw new DuplicateKeyException("The key '" + key + "' already exists in the dictionary.");
            }

            // Insert the new entry
            _storage.Add(key, value);
        }

        // Checks if the dictionary contains the specified key
        public bool ContainsKey(string key)
        {
            if (string.IsNullOrEmpty(key))
            {
                throw new ArgumentException("Key cannot be null or empty.", nameof(key));
            }
            return _storage.ContainsKey(key);
        }

        // Retrieves the value associated with the specified key using an indexer property
        public string this[string key]
        {
            get
            {
                if (string.IsNullOrEmpty(key))
                {
                    throw new ArgumentException("Key cannot be null or empty.", nameof(key));
                }
                if (!_storage.ContainsKey(key))
                {
                    throw new KeyNotFoundException("The key '" + key + "' was not found in the dictionary.");
                }

using System;
 
public class Manager
{
    public static void Main()
    {
        Console.WriteLine(s35(1000));
    }
 
    public static int s35(int n)
    {
        n--;
        int threes = n / 3;
        int fives = n / 5;
        int fifteen = n / 15;
 
        threes = 3 * threes * (threes + 1);
        fives = 5 * fives * (fives + 1);
        fifteen = 15 * fifteen * (fifteen + 1);
 
        n = (threes + fives - fifteen) / 2;
 
        return n;
    }
}

