using System;
using UnityEngine;
using GoogleARCore;

public abstract class LifecycleManager
{
    protected static LifecycleManager s_Instance;

    public static LifecycleManager Instance
    {
        get
        {
            if (s_Instance == null)
            {
                #if UNITY_IOS
                s_Instance = new ARCoreIOSLifecycleManager();
                #elif UNITY_ANDROID
                s_Instance = new ARCoreAndroidLifecycleManager();
                #else
                throw new PlatformNotSupportedException("AR Core is only supported on iOS and Android platforms");
                #endif
            }
            return s_Instance;
        }
    }

    public abstract void InitializeARSession();
    public abstract void UpdateARSession();
    public abstract void PauseARSession();
    public abstract void ResumeARSession();
    public abstract void DestroyARSession();

    public delegate void FrameUpdate(ARCore.TrackingState state);
    public event FrameUpdate OnFrameUpdated;

    protected void RaiseFrameUpdateEvent(ARCore.TrackingState state)
    {
        OnFrameUpdated?.Invoke(state);
    }
}

public class ARCoreIOSLifecycleManager : LifecycleManager
{
    private ARSession m_ARSession;

    public override void InitializeARSession()
    {
        m_ARSession = FindObjectOfType<ARSession>();
        if (m_ARSession == null)
        {
            Debug.LogError("AR Session not found in scene for iOS");
            return;
        }

        m_ARSession.enabled = true;
        ConfigureIOSSpecificSettings();
    }

    private void ConfigureIOSSpecificSettings()
    {
        // iOS-specific AR configuration logic
        var config = m_ARSession.Session.Configuration;
        config.PlaneDetection = PlaneDetectionMode.Horizontal | PlaneDetectionMode.Vertical;
        m_ARSession.Session.Configure(config);
    }

    public override void UpdateARSession()
    {
        if (m_ARSession != null)
        {
            var trackingState = m_ARSession.TrackingState;
            RaiseFrameUpdateEvent(trackingState);
        }
    }

    public override void PauseARSession()
    {
        if (m_ARSession != null)
        {
            m_ARSession.enabled = false;
        }
    }

    public override void ResumeARSession()
    {
        if (m_ARSession != null)
        {
            m_ARSession.enabled = true;
        }
    }

    public override void DestroyARSession()
    {
        if (m_ARSession != null)
        {
            Destroy(m_ARSession.gameObject);
            m_ARSession = null;
        }
    }
}

