namespace DependencyInjectionFramework
{
    public interface IBindingFinalizer
    {
        void FinalizeBinding();
    }

    public class BindStatement : IDisposable
    {
        private readonly List<IDisposable> _disposables;
        private IBindingFinalizer _bindingFinalizer;
        private bool _isFinalized;

        public BindStatement()
        {
            _disposables = new List<IDisposable>();
            _isFinalized = false;
        }

        public void SetFinalizer(IBindingFinalizer finalizer)
        {
            if (_isFinalized)
            {
                throw new InvalidOperationException("Cannot set finalizer after finalization.");
            }

            _bindingFinalizer = finalizer;
        }

        public void AddDisposable(IDisposable disposable)
        {
            if (_isFinalized)
            {
                throw new InvalidOperationException("Cannot add disposable after finalization.");
            }

            if(disposable == null)
            {
                throw new ArgumentNullException(nameof(disposable), "Disposable cannot be null.");
            }

            _disposables.Add(disposable);
        }

        public void SpawnBindInfo()
        {
            if (_isFinalized)
            {
                throw new InvalidOperationException("Cannot spawn bind info after finalization.");
            }

            // Logic to create and register binding information
        }

        public void FinalizeBinding()
        {
            AssertBindingComplete();
            _bindingFinalizer?.FinalizeBinding();
            _isFinalized = true;
        }

        private void AssertBindingComplete()
        {
            if (_bindingFinalizer == null)
            {
                throw new InvalidOperationException("Binding has not been completed.");
            }
        }

        public void Reset()
        {
            ClearDisposables();
            _isFinalized = false;
            _bindingFinalizer = null;
        }

        private void ClearDisposables()
        {
            foreach (var disposable in _disposables)
            {
                disposable.Dispose();
            }
            _disposables.Clear();
        }

        public void Dispose()
        {
            ClearDisposables();
            GC.SuppressFinalize(this);
        }
    }

