namespace Tree
{
    class Converter
    {
        static void Main(string[] args)
        {
            printBlock("21", 5);
            printBlock("", 5);
            printBlock("8", 10);
            printBlock("2323", 15);
            printBlock("23", 5);
        }
 
        static void printBlock(string data, int le)
        {
            char[] a = data.ToCharArray();
            int sumBytes = 0;
            foreach (char b in a)
            {
                sumBytes += (int)(b - 48);
            }
            Console.WriteLine("\nblocks {0}, cells {1}\n", data, le);
            if (le - sumBytes <= 0)
            {
                Console.WriteLine("No solution");
                return;
            }
            string[] prep = new string[a.Length];
            for (int i = 0; i < a.Length; i++)
            {
                prep[i] = new string('1', (int)(a[i] - 48));
            }
            foreach (string r in genSequence(prep, le - sumBytes + 1))
            {
                Console.WriteLine(r.Substring(1));
            }
        }
 
        static IEnumerable<string> genSequence(string[] ones, int numZeros)
        {
            if (ones.Length == 0)
            {
                return new string[] { new string('0', numZeros) };
            }
            List<string> result = new List<string>();
            for (int x = 1; x < numZeros - ones.Length + 2; x++)
            {
                string[] skipOne = ones.Skip(1).ToArray();
                foreach (string tail in genSequence(skipOne, numZeros - x))
                {
                    result.Add(new string('0', x) + ones[0] + tail);
                }
            }
            return result;
        }
    }
}

