    }

    public interface ISilverlightElement : INode
    {
        FrameworkElement GetFrameworkElement();
    }

    public interface INode
    {
    }

    public class Element : Object
    {
        public virtual int GetDefaultMarginLeft() { return 0; }
        public virtual int GetDefaultMarginRight() { return 0; }
        public virtual int GetDefaultMarginTop() { return 0; }
        public virtual int GetDefaultMarginBottom() { return 0; }
        public virtual bool GetDefaultTabStop() { return true; }
    }

    public class ContentElement : Element, ISilverlightContainerElement
    {
        private ISilverlightElement _rootElement;
        private ContentControl _contentControl;

        protected virtual FrameworkElement CreateFrameworkElement()
        {
            return new ContentControl();
        }

        public FrameworkElement GetFrameworkElement()
        {
            if (_contentControl == null)
            {
                _contentControl = (ContentControl)CreateFrameworkElement();
            }

            return _contentControl;
        }

        private void InsertChild(ISilverlightElement child)
        {
            _rootElement = child;
            _contentControl.Content = child.GetFrameworkElement();
        }

        private void RemoveChild()
        {
            _contentControl.Content = null;
            _rootElement = null;
        }

        public void AddChild(ISilverlightElement child)
        {
            if (!IsValidChild(child))
                throw InvalidChildError();
            InsertChild(child);
        }

        public void RemoveChild(ISilverlightElement child)
        {
            if (_rootElement == child)
                RemoveChild();
        }

        protected virtual bool IsValidChild(object child)
        {
            return _rootElement == null && child is ISilverlightElement;
        }

        protected virtual Exception InvalidChildError()
        {
            return new ClientException("Only one child allowed in Content element.");
        }
    }

