public static double pow(double base, double exp)
{
    if (exp!= Math.Floor(exp))
        throw new Exception("exponent must be an integer");
    if (exp < 0)
        return 1 / pow(base, -exp);
    double ans = 1;
    while (exp > 0)
    {
        ans *= base;
        exp--;
    }
    return ans;
}

