[AttributeUsage(AttributeTargets.Class)]
public class TestClassAttribute : Attribute { }

[AttributeUsage(AttributeTargets.Method)]
public class TestMethodAttribute : Attribute { }

public class UnitTestException : Exception
{
    public UnitTestException(string message) : base(message) { }
}

public class UnitTestRunner : MonoBehaviour
{
    private Stopwatch testSuiteTimer;
    private int totalTestsRun;
    private int passedTests;
    private int failedTests;

    private void Start()
    {
        RunUnitTests();
    }

    private void RunUnitTests()
    {
        testSuiteTimer = new Stopwatch();
        testSuiteTimer.Start();

        List<Type> testClasses = GetTestClasses();

        foreach (Type testClass in testClasses)
        {
            RunTestMethods(testClass);
        }

        testSuiteTimer.Stop();
        ReportTestResults();
    }

    private List<Type> GetTestClasses()
    {
        List<Type> testClasses = new List<Type>();

        foreach (Assembly assembly in AppDomain.CurrentDomain.GetAssemblies())
        {
            try
            {
                foreach (Type type in assembly.GetTypes())
                {
                    if (type.GetCustomAttributes(typeof(TestClassAttribute), false).Length > 0)
                    {
                        testClasses.Add(type);
                    }
                }
            }
            catch (Exception ex)
            {
                UnityEngine.Debug.LogError($"Error scanning assembly: {ex.Message}");
            }
        }

        return testClasses;
    }

    private void RunTestMethods(Type testClass)
    {
        object testInstance = Activator.CreateInstance(testClass);

        foreach (MethodInfo method in testClass.GetMethods())
        {
            if (method.GetCustomAttributes(typeof(TestMethodAttribute), false).Length > 0)
            {
                try
                {
                    totalTestsRun++;
                    method.Invoke(testInstance, null);
                    passedTests++;
                    UnityEngine.Debug.Log($"Test Passed: {testClass.Name}.{method.Name}");
                }
                catch (Exception ex)
                {
                    failedTests++;
                    UnityEngine.Debug.LogError($"Test Failed: {testClass.Name}.{method.Name} - {ex.Message}");
                }
            }
        }
    }

