    public interface IMemoryMonitor
    {
        double GetCurrentMemoryUsage();
        double GetAvailableMemory();
    }

    public class MemoryManager : IDisposable
    {
        private readonly IMemoryMonitor _memoryMonitor;
        private bool _disposed = false;

        public MemoryManager(IMemoryMonitor memoryMonitor)
        {
            _memoryMonitor = memoryMonitor ?? throw new ArgumentNullException(nameof(memoryMonitor));
        }

        // Checks if the current memory usage exceeds the provided threshold.
        public bool IsUsageAboveThreshold(double threshold)
        {
            double usage = _memoryMonitor.GetCurrentMemoryUsage();
            return usage > threshold;
        }

        // Determines if sufficient memory is available based on the threshold.
        // If the threshold is zero or negative, always returns true.
        public bool HasSufficientMemory(double requiredMemory)
        {
            if (requiredMemory <= 0)
                return true;

            double availableMemory = _memoryMonitor.GetAvailableMemory();
            return availableMemory >= requiredMemory;
        }

        public void Dispose()
        {
            if (!_disposed)
            {
                // Place cleanup code here if needed.
                _disposed = true;
            }
        }
    }

