        internal static string GetString(IntPtr ptr, string defaultValue)
        {
            if (ptr == IntPtr.Zero)
            {
                return defaultValue;
            }

            var l = new List<byte>();
            byte read = 0;
            do
            {
                read = Marshal.ReadByte(ptr, l.Count);
                l.Add(read);
            }
            while (read != 0);

            if (l.Count > 0)
            {
                return Encoding.UTF8.GetString(l.ToArray(), 0, l.Count - 1);
            }

            return string.Empty;
        }

