                int size = Marshal.SizeOf(typeof(byte)) * (array.Length + 1);

                IntPtr ptr = Marshal.AllocHGlobal(size);

                Marshal.Copy(array, 0, ptr, array.Length);
                Marshal.WriteByte(ptr, array.Length, 0);
                _allocated = true;
                return ptr;
