using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Xml;

public interface IValidate
{
    IEnumerable<string> Validate();
}

public class XmlValidator
{
    protected List<XmlDocument> docs = new List<XmlDocument>();

    public void LoadXmlDocuments(string[] xmlFilePaths)
    {
        foreach (var xmlFilePath in xmlFilePaths)
        {
            XmlDocument doc = new XmlDocument();
            doc.Load(xmlFilePath);
            docs.Add(doc);
        }
    }
}

public class PathValidator : XmlValidator, IValidate
{
    private List<string> messageContainer = new List<string>();
    private List<string> pathsNotFound = new List<string>();

    public IEnumerable<string> Validate()
    {
        foreach (var doc in docs)
        {
            XmlNodeList pathNodes = doc.SelectNodes("//path");
            foreach (XmlNode pathNode in pathNodes)
            {
                string pathValue = pathNode.InnerText;
                if (IsUri(pathValue))
                {
                    messageContainer.Add($"Skipping URI path: {pathValue}");
                    continue;
                }

                if (ValidatePath(pathValue))
                {
                    messageContainer.Add($"Valid path: {pathValue}");
                }
                else
                {
                    pathsNotFound.Add(pathValue);
                    yield return $"Invalid path: {pathValue}";
                }
            }
        }

        foreach (var message in messageContainer)
        {
            yield return message;
        }

        if (pathsNotFound.Any())
        {
            yield return "Paths not found:";
            foreach (var notFound in pathsNotFound)
            {
                yield return $"- {notFound}";
            }
        }
    }

    private bool IsUri(string path)
    {
        return Uri.IsWellFormedUriString(path, UriKind.RelativeOrAbsolute);
    }

    private bool ValidatePath(string path)
    {
        return Directory.Exists(path) || File.Exists(path);
    }
}

public class Calculator
{
    public static void Main()
    {
        string[] xmlFiles = { "paths.xml" }; // Example XML file path
        PathValidator validator = new PathValidator();
        validator.LoadXmlDocuments(xmlFiles);

        foreach (var message in validator.Validate())
        {
            Console.WriteLine(message);
        }
    }
}

