namespace AMing.KanColle.Plugin.Logging
{
    public class LogsModules : IModule
    {
        private static LogsModules _current;
        public static LogsModules Current => _current ?? (_current = new LogsModules());

        public SettingsViewModel SettingsViewModel { get; private set; }

        private LogsModules()
        {
            SettingsViewModel = new SettingsViewModel();
        }

        public void Initialize()
        {
            InitPublicModules();
        }

        private void InitPublicModules()
        {
            GenericMessager<LogMessage>.Subscribe(AppendLogs);
            GenericMessager<Exception>.Subscribe(AppendLogsForException);
        }

        private void AppendLogs(LogMessage logMessage)
        {
            var timestamp = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
            var formattedMessage = $"{timestamp} - {logMessage.Message}";
            SettingsViewModel.Logs.Add(formattedMessage);
            MessageLogHelper.Log(formattedMessage);
        }

        private void AppendLogsForException(Exception ex)
        {
            var timestamp = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
            var formattedMessage = $"{timestamp} - Exception: {ex.Message}\nStack Trace: {ex.StackTrace}";
            SettingsViewModel.Logs.Add(formattedMessage);
            ErrorLogHelper.Log(formattedMessage);
        }

        public void Dispose()
        {
            GenericMessager<LogMessage>.Unsubscribe(AppendLogs);
            GenericMessager<Exception>.Unsubscribe(AppendLogsForException);
            SettingsViewModel.Logs.Clear();
        }
    }

    public class LogMessage
    {
        public string Message { get; set; }

        public LogMessage(string message)
        {
            Message = message;
        }
    }

    public class SettingsViewModel
    {
        public List<string> Logs { get; private set; }

        public SettingsViewModel()
        {
            Logs = new List<string>();
        }
    }

    public static class MessageLogHelper
    {
        public static void Log(string message)
        {
            // Implement log storage or further processing
            Console.WriteLine($"Message Log: {message}");
        }
    }

    public static class ErrorLogHelper
    {
        public static void Log(string message)
        {

