namespace Task
{
    class Runner
    {
        static int compareInts(int i1, int i2)
        {
            return i1 - i2;
        }
        static void Main(string[] args)
        {
            int i, j, nsum, vsum, vcount, values, numbers;
            Random rand = new Random();
            for (;;)
            {
                vsum = 0;
                for (i = 0; i < 6; ++i)
                {
                    for (j = 0; j < 4; ++j)
                    {
                        numbers[j] = 1 + rand.Next(6);
                    }
                    Array.Sort(numbers, compareInts);
                    nsum = 0;
                    for (j = 1; j < 4; ++j)
                    {
                        nsum += numbers[j];
                    }
                    values[i] = nsum;
                    vsum += values[i];
                }
                if (vsum < 75) continue;
                vcount = 0;
                for (j = 0; j < 6; ++j)
                {
                    if (values[j] >= 15) vcount++;
                }
                if (vcount < 2) continue;
                Console.WriteLine("The 6 random numbers generated are:");
                Console.Write("[");
                for (j = 0; j < 6; ++j) Console.Write(values[j] + " ");
                Console.WriteLine("\b]");
                Console.WriteLine("\nTheir sum is {0} and {1} of them are >= 15", vsum, vcount);
                break;
            }
        }
    }
}

namespace formulate.api.Controllers
