    /// <summary>
    /// The rendering controller.
    /// </summary>
    public sealed class FormulateRenderingController : SurfaceController
    {
        /// <summary>
        /// Initializes a new instance of the <see cref="FormulateRenderingController"/> class.
        /// </summary>
        /// <param name="definitionHelper">
        /// The definition helper.
        /// </param>
        /// <remarks>The main constructor.</remarks>
        public FormulateRenderingController(IDefinitionHelper definitionHelper)
        {
            DefinitionHelper = definitionHelper;
        }

        /// <summary>
        /// Gets or sets the definition helper.
        /// </summary>
        private IDefinitionHelper DefinitionHelper { get; set; }

        /// <summary>
        /// A Child Action which renders a configured Formulate form.
        /// </summary>
        /// <param name="form">
        /// The configured form info.
        /// </param>
        /// <returns>
        /// The <see cref="ActionResult"/>.
        /// </returns>
        /// <remarks>Example usage: @Html.Action("Render", "FormulateRendering", new { form = Model.Form })</remarks>
        [ChildActionOnly]
        public ActionResult Render(ConfiguredFormInfo form)
        {
            var viewModel = new FormViewModel()
            {
                FormDefinition = DefinitionHelper.GetFormDefinition(form.FormId),
                LayoutDefinition = DefinitionHelper.GetLayoutDefinition(form.LayoutId),
                TemplatePath = DefinitionHelper.GetTemplatePath(form.TemplateId),
                PageId = CurrentPage.Id
            };

            return PartialView("~/Views/Partials/Formulate/RenderForm.cshtml", viewModel);
        }
    }
}

using UnityEngine;
using UnityEditor;

public enum InputType { DirectValue, RandomRange, GameObjectReference }

public class InputNode : BaseInputNode {
    [SerializeField] private InputType inputType = InputType.DirectValue;
    [SerializeField] private float randomFrom = 0f;
    [SerializeField] private float randomTo = 1f;
    [SerializeField] private float inputValue = 0f;
    [SerializeField] private GameObject inputObject;

    private const int PRECISION_FACTOR = 1000;
    private float currentValue;

    public override void DrawWindow() {
        base.DrawWindow();

        inputType = (InputType)EditorGUILayout.EnumPopup("Input Mode:", inputType);
        EditorGUILayout.Space(5);

        switch(inputType) {
            case InputType.DirectValue:
                inputValue = EditorGUILayout.FloatField("Value:", inputValue);
                currentValue = inputValue;
                break;

            case InputType.RandomRange:
                randomFrom = EditorGUILayout.FloatField("Min Value:", randomFrom);
                randomTo = EditorGUILayout.FloatField("Max Value:", randomTo);
                if (GUILayout.Button("Generate Random")) {
                    currentValue = calculateRandom();
                }
                EditorGUILayout.LabelField("Current Value: " + currentValue.ToString("F3"));
                break;

            case InputType.GameObjectReference:
                inputObject = (GameObject)EditorGUILayout.ObjectField("Target Object:", inputObject, typeof(GameObject), true);
                currentValue = inputObject ? inputObject.GetInstanceID() : 0;
                break;
        }
    }

    private float calculateRandom() {
        if (randomFrom > randomTo) {
            float temp = randomFrom;
            randomFrom = randomTo;
            randomTo = temp;
        }

        int scaledMin = Mathf.RoundToInt(randomFrom * PRECISION_FACTOR);
        int scaledMax = Mathf.RoundToInt(randomTo * PRECISION_FACTOR);
        return (float)Random.Range(scaledMin, scaledMax) / PRECISION_FACTOR;
    }

    public override object getResult() {
        switch(inputType) {
            case InputType.DirectValue:
                return inputValue;
            case InputType.RandomRange:
                return currentValue;
            case InputType.GameObjectReference:
                return inputObject;
        }
        return null;
    }

    public override void OnGUI() {
        base.OnGUI();
        windowRect.height = inputType == InputType.RandomRange ? 160 : 120;
    }
}

using System;
using System.Collections.Generic;

class PhonebookUpgrade
{
    private SortedDictionary<string, string> phonebook;

    public PhonebookUpgrade()
    {
        phonebook = new SortedDictionary<string, string>();
    }

    public void AddContact(string name, string number)
    {
        if (!phonebook.ContainsKey(name))
        {
            phonebook[name] = number;
            Console.WriteLine($"Contact '{name}' added successfully.");
        }
        else
        {
            Console.WriteLine($"Contact '{name}' already exists.");
        }
    }

    public void SearchContact(string name)
    {
        if (phonebook.TryGetValue(name, out string number))
        {
            Console.WriteLine($"Found contact: {name} - {number}");
        }
        else
        {
            Console.WriteLine($"Contact '{name}' not found.");
        }
    }

    public void ListContacts()
    {
        Console.WriteLine("Listing all contacts:");
        foreach (var entry in phonebook)
        {
            Console.WriteLine($"{entry.Key} - {entry.Value}");
        }
    }

    static void Main(string[] args)
    {
        PhonebookUpgrade phonebook = new PhonebookUpgrade();
        string command;

        Console.WriteLine("Welcome to the Phonebook application! Type 'exit' to quit.");

        while (true)
        {
            Console.Write("Enter command: ");
            command = Console.ReadLine();

            if (command.Equals("exit", StringComparison.OrdinalIgnoreCase))
            {
                break;
            }

            string[] parts = command.Split(' ');
            if (parts.Length < 1)
            {
                Console.WriteLine("Invalid command. Please try again.");
                continue;
            }

            string action = parts[0].ToUpper();
            switch (action)
            {
                case "A": // Add contact
                    if (parts.Length != 3)
                    {
                        Console.WriteLine("Usage: A <name> <number>");
                        break;
                    }
                    phonebook.AddContact(parts[1], parts[2]);
                    break;

                case "S": // Search contact
                    if (parts.Length != 2)
                    {
                        Console.WriteLine("Usage: S <name>");
                        break;
                    }
                    phonebook.SearchContact(parts[1]);
                    break;

                case "L": // List contacts
                    phonebook.ListContacts();

