namespace Library
{
    class Reader
    {
        static void Main(string[] args)
        {
            foreach (var p in sumpol(10))
            {
                Console.WriteLine(polstr(p));
            }
        }
 
        static IEnumerable<List<BigInteger>> sumpol(int n)
        {
            var u = new List<BigInteger> { 0, 1 };
            var v = new List<List<BigInteger>> { new List<BigInteger> { 1 }, new List<BigInteger> { 1, 1 } };
            yield return new List<BigInteger> { 0, 1 };
            for (int i = 1; i < n; i++)
            {
                v.Add(nextv(v.Last()));
                var t = new List<BigInteger>();
                for (int j = 0; j < i + 2; j++)
                {
                    t.Add(0);
                }
                BigInteger p = 1;
                for (int j = 0; j < u.Count; j++)
                {
                    BigInteger r = u[j] / (j + 1);
