using EloBuddy;
using EloBuddy.SDK;
using EloBuddy.SDK.Menu.Values;
using LeagueSharp.SDK;
using LeagueSharp.SDK.Core.Utils;

namespace OlafAIO.Logics
{
    public static class Combo
    {
        public static void Execute()
        {
            var target = Targets.Target;
            if (target == null || !target.IsValidTarget())
                return;

            if (ShouldCastW(target))
                CastW();

            if (ShouldCastQ(target))
                CastQ(target);
        }

        private static bool ShouldCastW(AIHeroClient target)
        {
            if (!Vars.W.IsReady())
                return false;

            if (!Vars.Menu["spells"]["w"]["combo"].Cast<CheckBox>().CurrentValue)
                return false;

            if (!target.IsInRange(Vars.W.Range))
                return false;

            if (ObjectManager.Player.HasBuff("olafwbuff"))
                return false;

            return true;
        }

        private static void CastW()
        {
            Vars.W.Cast();
        }

        private static bool ShouldCastQ(AIHeroClient target)
        {
            if (!Vars.Q.IsReady())
                return false;

            if (!Vars.Menu["spells"]["q"]["combo"].Cast<CheckBox>().CurrentValue)
                return false;

            if (target.HasBuffOfType(BuffType.Slow))
                return false;

            var prediction = Vars.Q.GetPrediction(target);
            if (prediction.Hitchance < HitChance.High)
                return false;

            return target.IsInRange(Vars.Q.Range);
        }

        private static void CastQ(AIHeroClient target)
        {
            var prediction = Vars.Q.GetPrediction(target);
            if (prediction.Hitchance >= HitChance.High && target.IsInRange(Vars.Q.Range))
                Vars.Q.Cast(prediction.CastPosition);
        }
    }
}

using System;
using System.Linq;
using System.Drawing;
using System.Diagnostics;
using System.Drawing.Drawing2D;
 
class Runner
{
    const int width = 380;
    const int height = 380;
    static PointF archimedeanPoint(int degrees)
    {
        const double a = 1;
        const double b = 9;
        double t = degrees * Math.PI / 180;
        double r = a + b * t;
        return new PointF { X = (float)(width / 2 + r * Math.Cos(t)), Y = (float)(height / 2 + r * Math.Sin(t)) };
    }
 
    static void Main(string[] args)
    {
        var bm = new Bitmap(width, height);
        var g = Graphics.FromImage(bm);
        g.SmoothingMode = SmoothingMode.AntiAlias;
        g.FillRectangle(new SolidBrush(Color.White), new Rectangle { X = 0, Y = 0, Width = width, Height = height });
        var pen = new Pen(Color.OrangeRed, 1.5f);
 
        var spiral = Enumerable.Range(0, 360 * 3).AsParallel().AsOrdered().Select(archimedeanPoint);
        var p0 = new PointF(width / 2, height / 2);
        foreach (var p1 in spiral)
        {
            g.DrawLine(pen, p0, p1);
            p0 = p1;
        }
        g.Save(); // is this really necessary ?
        bm.Save("archimedes-csharp.png");
        Process.Start("archimedes-csharp.png"); // Launches default photo viewing app
    }
}

