public class Widget : WidgetBase
{
    private const string MaxCountKey = "maxcount";
    private const string PatternKey = "pattern";
    private const string PatternAggregatedKey = "patternaggregated";
    private const int DefaultMaxCount = 5;
    private const string DefaultPattern = "{{name}} ({{count}} posts)";
    private const string DefaultAggregatedPattern = "{{name}} and {{total}} others";

    public AuthorList AuthorList1 { get; set; }

    public override void LoadWidget()
    {
        base.LoadWidget();
        StringDictionary settings = GetSettings() ?? new StringDictionary();

        int maxAuthors = ParseMaxCount(settings);
        string displayPattern = ValidatePattern(GetSettingValue(settings, PatternKey, DefaultPattern),
            DefaultPattern, "{{name}}", "{{count}}");
        string aggregatedPattern = ValidatePattern(GetSettingValue(settings, PatternAggregatedKey, DefaultAggregatedPattern),
            DefaultAggregatedPattern, "{{name}}", "{{total}}");

        ConfigureAuthorList(maxAuthors, displayPattern, aggregatedPattern);
    }

    private int ParseMaxCount(StringDictionary settings)
    {
        if (!settings.ContainsKey(MaxCountKey))
            return DefaultMaxCount;

        string value = settings[MaxCountKey];
        if (int.TryParse(value, out int result) && result > 0)
            return result;

        return DefaultMaxCount;
    }

    private string GetSettingValue(StringDictionary settings, string key, string defaultValue)
    {
        return settings.ContainsKey(key) && !string.IsNullOrWhiteSpace(settings[key])
            ? settings[key]
            : defaultValue;
    }

    private string ValidatePattern(string pattern, string defaultPattern, params string[] requiredTags)
    {
        foreach (string tag in requiredTags)
        {
            if (!pattern.Contains(tag))
                return defaultPattern;
        }
        return pattern;
    }

    private void ConfigureAuthorList(int maxAuthors, string displayPattern, string aggregatedPattern)
    {
        AuthorList1.MaxAuthors = maxAuthors;
        AuthorList1.DisplayPattern = displayPattern;
        AuthorList1.AggregatedDisplayPattern = aggregatedPattern;

        if (maxAuthors == 1)
        {
            AuthorList1.AggregationThreshold = 2;
        }
        else
        {
            AuthorList1.AggregationThreshold = maxAuthors + 1;
        }
    }
}

