namespace PowerShellTools
{
    internal sealed class OpenExplorerCommand
    {
        public const int CommandId = GuidList.CmdidDisplayExplorer;
        public static readonly Guid CommandSet = new Guid(GuidList.CmdSetGuid);

        private readonly AsyncPackage _package;

        private OpenExplorerCommand(AsyncPackage package, OleMenuCommandService commandService)
        {
            _package = package ?? throw new ArgumentNullException(nameof(package));
            commandService = commandService ?? throw new ArgumentNullException(nameof(commandService));

            var menuCommandID = new CommandID(CommandSet, CommandId);
            var menuItem = new OleMenuCommand(Execute, menuCommandID);
            menuItem.BeforeQueryStatus += OnBeforeQueryStatus;
            commandService.AddCommand(menuItem);
        }

        public static OpenExplorerCommand Instance { get; private set; }

        public static async Task InitializeAsync(AsyncPackage package)
        {
            await ThreadHelper.JoinableTaskFactory.SwitchToMainThreadAsync(package.DisposalToken);

            OleMenuCommandService commandService = await package.GetServiceAsync(typeof(IMenuCommandService)) as OleMenuCommandService;
            Instance = commandService != null ? new OpenExplorerCommand(package, commandService) : null;
        }

        private void Execute(object sender, EventArgs e)
        {
            ThreadHelper.ThrowIfNotOnUIThread();
            PowerShellToolsPackage.Instance.ShowToolWindow(
                typeof(PowerShellCommandExplorerWindow),
                0,
                true,
                PowerShellToolsPackage.Instance.DisposalToken
            );
        }

        private void OnBeforeQueryStatus(object sender, EventArgs e)
        {
            ThreadHelper.ThrowIfNotOnUIThread();
            if (sender is OleMenuCommand command)
            {
                command.Visible = true;
                command.Enabled = true;
                command.Supported = true;
            }
        }
    }
}

using System;

public struct Result<T>
{
    public T Value { get; }
    public Exception Error { get; }
    public bool IsSuccess { get; }

    public Result(T value)
    {
        Value = value;
        Error = null;
        IsSuccess = true;
    }

    public Result(Exception error)
    {
        Value = default;
        Error = error;
        IsSuccess = false;
    }
}

public class Pipeline<T>
{
    public Func<Result<T>> future;
    public Action<Exception> ExceptionHandler { get; set; }

    public Pipeline(Func<Result<T>> start)
    {
        future = start;
    }

    public Pipeline<T> Catch(Action<Exception> handler)
    {
        ExceptionHandler = handler;
        return this;
    }

    public Pipeline<T> ContinueWith(Func<T, T> func)
    {
        var prev = future;
        future = () =>
        {
            var res = prev();
            if (res.IsSuccess)
            {
                try
                {
                    return new Result<T>(func(res.Value));
                }
                catch (Exception ex)
                {
                    ExceptionHandler?.Invoke(ex);
                    return new Result<T>(ex);
                }
            }
            return res;
        };
        return this;
    }
        public Pipeline<T> ContinueWith(Action<T> action)
    {
         var prev = future;
        future = () =>
        {
            var res = prev();
            if (res.IsSuccess)
            {
                try
                {
                     action(res.Value);
                     return res;
                }
                catch (Exception ex)
                {
                    ExceptionHandler?.Invoke(ex);
                    return new Result<T>(ex);
                }
            }
            return res;
        };
        return this;

    }

    public Pipeline<TResult> ContinueWithNew<TResult>(Func<T, TResult> func)
      {
        var prev = future;
        var newFuture = new Pipeline<TResult>(() =>
        {
            var res = prev();
            if (res.IsSuccess)
            {
                try
                {
                    return new Result<TResult>(func(res.Value));
                }
                catch (Exception ex)
                {
                    if (ExceptionHandler != null) ExceptionHandler(ex);
                    return new Result<TResult>(ex);
                }
            }
            return new Result<TResult>(res.Error);
        });
        newFuture.ExceptionHandler = ExceptionHandler;
        return newFuture;
    }

using System;
using System.Linq;
using System.Collections.Generic;
 
public static class OrderedPartitions
{
    public static void Main() {
        var input = new [] { new[] { 0, 0, 0, 0, 0 }, new[] { 2, 0, 2 }, new[] { 1, 1, 1 } };
        foreach (int[] sizes in input) {
            foreach (var partition in Partitions(sizes)) {
                Console.WriteLine(partition.Select(set => set.Delimit(", ").Encase('{','}')).Delimit(", ").Encase('(', ')'));
            }
            Console.WriteLine();
        }
    }
 
    static IEnumerable<IEnumerable<int[]>> Partitions(params int[] sizes) {
        var enumerators = new IEnumerator<int[]>[sizes.Length];
        var unused = Enumerable.Range(1, sizes.Sum()).ToSortedSet();
        var arrays = sizes.Select(size => new int[size]).ToArray();
 
        for (int s = 0; s >= 0; ) {
            if (s == sizes.Length) {
                yield return arrays;
                s--;
            }
            if (enumerators[s] == null) {
                enumerators[s] = Combinations(sizes[s], unused.ToArray()).GetEnumerator();
            } else {
                unused.UnionWith(arrays[s]);
            }
            if (enumerators[s].MoveNext()) {
                enumerators[s].Current.CopyTo(arrays[s], 0);
                unused.ExceptWith(arrays[s]);
                s++;
            } else {
                enumerators[s] = null;
                s--;
            }
        }
    }
 
    static IEnumerable<T[]> Combinations<T>(int count, params T[] array) {
        T[] result = new T[count];
        foreach (int pattern in BitPatterns(array.Length - count, array.Length)) {
            for (int b = 1 << (array.Length - 1), i = 0, r = 0; b > 0; b >>= 1, i++) {
                if ((pattern & b) == 0) result[r++] = array[i];
            }
            yield return result;
        }
    }
 
    static IEnumerable<int> BitPatterns(int ones, int length) {
        int initial = (1 << ones) - 1;
        int blockMask = (1 << length) - 1;
        for (int v = initial; v >= initial; ) {
            yield return v;
            if (v == 0) break;
 
            int w = (v | (v - 1)) + 1;
            w |= (((w & -w) / (v & -v)) >> 1) - 1;
            v = w & blockMask;
        }
    }
 
    static string Delimit<T>(this IEnumerable<T> source, string separator) => string.Join(separator, source);
    static string Encase(this string s, char start, char end) => start + s + end;
}

