using System;
using System.IO;
using Microsoft.Build.Evaluation;

public static class MsBuildHelper
{
    private const string MsBuildOutputPathProperty = "OutputPath";
    private const string MsBuildOutputDirProperty = "OutDir";
    private const string MsBuildAssemblyNameProperty = "AssemblyName";
    private const string MsBuildTargetFrameworkProperty = "TargetFramework";
    private const string MsBuildProjectDirectoryProperty = "MSBuildProjectDirectory";
    private const string MsBuildProjectNameProperty = "MSBuildProjectName";

    public static string GetAssemblyForProject(string projectFilePath)
    {
        if (!File.Exists(projectFilePath))
        {
            throw new FileNotFoundException("Project file not found.", projectFilePath);
        }

        var projectCollection = new ProjectCollection();
        var project = new Project(projectFilePath, null, null, projectCollection);

        string outputPath = project.GetPropertyValue(MsBuildOutputPathProperty);
        string outDir = project.GetPropertyValue(MsBuildOutputDirProperty);
        string assemblyName = project.GetPropertyValue(MsBuildAssemblyNameProperty);
        string targetFramework = project.GetPropertyValue(MsBuildTargetFrameworkProperty);
        string projectDirectory = project.GetPropertyValue(MsBuildProjectDirectoryProperty);

        string finalOutputPath = !string.IsNullOrEmpty(outDir) ? outDir : outputPath;
        if (string.IsNullOrEmpty(finalOutputPath))
        {
            return GetOutputDll(projectDirectory, assemblyName, targetFramework);
        }

        return Path.Combine(projectDirectory, finalOutputPath, $"{assemblyName}.dll");
    }

    private static string GetOutputDll(string projectDirectory, string assemblyName, string targetFramework)
    {
        string defaultOutputPath = Path.Combine("bin", "Debug", targetFramework);
        return Path.Combine(projectDirectory, defaultOutputPath, $"{assemblyName}.dll");
    }
}

