namespace Logging
{
    public class RawExceptionLayout : PatternLayout
    {
        public override void Format(TextWriter writer, LoggingEvent loggingEvent)
        {
            if (loggingEvent.ExceptionObject != null)
            {
                writer.Write(loggingEvent.ExceptionObject.ToString());
            }
            else
            {
                base.Format(writer, loggingEvent);
            }
        }
    }

    public class Log4NetAdapter
    {
        private static readonly Dictionary<Type, ILog> _loggers = new Dictionary<Type, ILog>();
        private const string NullText = "<null>";

        static Log4NetAdapter()
        {
            log4net.Config.XmlConfigurator.Configure();
        }

        private static ILog GetLogger(Type type)
        {
            lock (_loggers)
            {
                if (!_loggers.ContainsKey(type))
                {
                    _loggers[type] = LogManager.GetLogger(type);
                }
                return _loggers[type];
            }
        }

        private static string Format(string message, params object[] args)
        {
            return args != null && args.Length > 0
                ? string.Format(message ?? NullText, args.Select(a => a ?? NullText).ToArray())
                : (message ?? NullText);
        }

        public static void Debug(Type type, string message, params object[] args)
        {
            var logger = GetLogger(type);
            if (logger.IsDebugEnabled)
                logger.Debug(Format(message, args));
        }

        public static void Debug(Type type, string message, Exception exception, params object[] args)
        {
            var logger = GetLogger(type);
            if (logger.IsDebugEnabled)
                logger.Debug(Format(message, args), exception);
        }

        public static void Info(Type type, string message, params object[] args)
        {
            var logger = GetLogger(type);
            if (logger.IsInfoEnabled)
                logger.Info(Format(message, args));
        }

        public static void Info(Type type, string message, Exception exception, params object[] args)
        {
            var logger = GetLogger(type);
            if (logger.IsInfoEnabled)
                logger.Info(Format(message, args), exception);
        }

        public static void Warn(Type type, string message, params object[] args)
        {
