        {
            NumberFormatInfo nfi = new NumberFormatInfo();

            // Valid values are 0, 1, 2, and 3.
            for (int value = 0; value <= 3; value++)
            {
                nfi.CurrencyPositivePattern = value;
                Assert.Equal(value, nfi.CurrencyPositivePattern);
            }
        }

        // Test that assigning an invalid value throws an ArgumentOutOfRangeException.
        [Fact]
        public void NegTest1()
        {
            NumberFormatInfo nfi = new NumberFormatInfo();

            // Attempt to assign an invalid negative value.
            VerificationHelper<ArgumentOutOfRangeException>(() =>
            {
                nfi.CurrencyPositivePattern = -1;
            });

            // Attempt to assign a value greater than the maximum allowed.
