using System;
using System.Globalization;
using RangeExceptions;

namespace RangeValidationDemo
{
    class MainClass
    {
        static void Main(string[] args)
        {
            try
            {
                Console.Write("Enter an integer between 0 and 100: ");
                int number = int.Parse(Console.ReadLine());
                ValidateNumber(number, 0, 100);
                Console.WriteLine("The number is valid.");
            }
            catch (InvalidRangeException<int> ex)
            {
                Console.WriteLine(ex.Message);
            }

            try
            {
                Console.Write("Enter a date between 01.01.1980 and 31.12.2013 (dd.MM.yyyy): ");
                DateTime date = DateTime.ParseExact(Console.ReadLine(), "dd.MM.yyyy", CultureInfo.InvariantCulture);
                DateTime startDate = new DateTime(1980, 1, 1);
                DateTime endDate = new DateTime(2013, 12, 31);
                ValidateDate(date, startDate, endDate);
                Console.WriteLine("The date is valid.");
            }
            catch (InvalidRangeException<DateTime> ex)
            {
                Console.WriteLine(ex.Message);
            }
        }

        static void ValidateNumber(int number, int min, int max)
        {
            if (number < min || number > max)
            {
                throw new InvalidRangeException<int>(number, min, max);
            }
        }

        static void ValidateDate(DateTime date, DateTime start, DateTime end)
        {
            if (date < start || date > end)
            {
                throw new InvalidRangeException<DateTime>(date, start, end);
            }
        }
    }

    namespace RangeExceptions
    {
        public class InvalidRangeException<T> : Exception where T : IComparable<T>
        {
            public T Value { get; private set; }
            public T Min { get; private set; }
            public T Max { get; private set; }

            public InvalidRangeException(T value, T min, T max)
                : base($"Value {value} is out of range [{min}, {max}].")
            {
                Value = value;
                Min = min;
                Max = max;
            }
        }
    }
}

