namespace GedReader
{
    public enum LB
    {
        Mac,    // \r
        Unix,   // \n
        Dos     // \r\n
    }

    public struct FileRead
    {
        public string Content { get; set; }
        public string FilePath { get; set; }
    }

    public static class ReadingUtil
    {
        public static FileRead BuildAndRead(string[] lines, LB lineBreak = LB.Dos, bool useBOM = true)
        {
            try
            {
                string lineTerminator = GetLineTerminator(lineBreak);
                string content = string.Join(lineTerminator, lines) + lineTerminator;

                string tempFilePath = MakeFile(content, useBOM);
                string fileContents = ReadFile(tempFilePath);

                return new FileRead
                {
                    Content = fileContents,
                    FilePath = tempFilePath
                };
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error building and reading file: {ex.Message}");
                return new FileRead { Content = null, FilePath = null };
            }
        }

        private static string GetLineTerminator(LB lineBreak)
        {
            return lineBreak switch
            {
                LB.Mac => "\r",
                LB.Unix => "\n",
                LB.Dos => "\r\n",
                _ => "\r\n"
            };
        }

        private static string MakeFile(string content, bool useBOM)
        {
            string tempFilePath = Path.GetTempFileName();

            try
            {
                Encoding encoding = useBOM ? Encoding.UTF8 : new UTF8Encoding(false);
                File.WriteAllText(tempFilePath, content, encoding);
                return tempFilePath;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error creating temp file: {ex.Message}");
                return null;
            }
        }

        private static string ReadFile(string filePath)
        {
            try
            {
                if (string.IsNullOrEmpty(filePath) || !File.Exists(filePath))
                    return null;

                string content = File.ReadAllText(filePath, Encoding.UTF8);
                File.Delete(filePath);
                return content;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error reading file: {ex.Message}");
                return null;
            }
            finally
            {
                try

using System;
 
public class DigitalFilter {
    private static double[] filter(double[] a, double[] b, double[] signal) {
        double[] result = new double[signal.Length];
        for (int i = 0; i < signal.Length; ++i) {
            double tmp = 0.0;
            for (int j = 0; j < b.Length; ++j) {
                if (i - j < 0) continue;
                tmp += b[j] * signal[i - j];
            }
            for (int j = 1; j < a.Length; ++j) {
                if (i - j < 0) continue;
                tmp -= a[j] * result[i - j];
            }
            tmp /= a[0];
            result[i] = tmp;
        }
        return result;
    }
 
    public static void Main(string[] args) {
        double[] a = new double[]{1.00000000, -2.77555756e-16, 3.33333333e-01, -1.85037171e-17};
        double[] b = new double[]{0.16666667, 0.5, 0.5, 0.16666667};
 
        double[] signal = new double[]{
            -0.917843918645, 0.141984778794, 1.20536903482, 0.190286794412,
            -0.662370894973, -1.00700480494, -0.404707073677, 0.800482325044,
            0.743500089861, 1.01090520172, 0.741527555207, 0.277841675195,
            0.400833448236, -0.2085993586, -0.172842103641, -0.134316096293,
            0.0259303398477, 0.490105989562, 0.549391221511, 0.9047198589
        };
 
        double[] result = filter(a, b, signal);
        for (int i = 0; i < result.Length; ++i) {
            Console.Write(String.Format("{0, 8:F8}", result[i]));
            Console.Write((i + 1) % 5!= 0? ", " : "\n");
        }
    }
}

