        {
            get { return _identity; }
        }

        public bool IsIdentity
        {
            get
            {
                return M11 == 1f && M22 == 1f && // Check diagonal element first for early out.
                                    M12 == 0f &&
                       M21 == 0f              &&
                       M31 == 0f && M32 == 0f;
            }
        }

