        {
            Matrix3x2 result;

            result.M11 = 1.0f; result.M12 = 0.0f;
            result.M21 = 0.0f; result.M22 = 1.0f;

            result.M31 = position.X;
            result.M32 = position.Y;

            return result;
        }

