using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;

public class SnapshottingCollection<T1, T2>
{
    protected Dictionary<T1, T2> snapshot;

    public SnapshottingCollection()
    {
        snapshot = new Dictionary<T1, T2>();
    }

    public Dictionary<T1, T2> GetSnapshot()
    {
        lock (snapshot)
        {
            return new Dictionary<T1, T2>(snapshot);
        }
    }
}

public class SnapshottingDictionary<TKey, TValue> : SnapshottingCollection<TKey, TValue>
{
    private ConcurrentDictionary<TKey, TValue> _dictionary;

    public SnapshottingDictionary()
    {
        _dictionary = new ConcurrentDictionary<TKey, TValue>();
    }

    public void Add(TKey key, TValue value)
    {
        if (!_dictionary.TryAdd(key, value))
        {
            throw new InvalidOperationException("An item with the same key has already been added.");
        }
        UpdateSnapshot();
    }

    public bool Remove(TKey key)
    {
        TValue removedValue;
        bool removed = _dictionary.TryRemove(key, out removedValue);
        if (removed)
        {
            UpdateSnapshot();
        }
        return removed;
    }

    public bool TryGetValue(TKey key, out TValue value)
    {
        return _dictionary.TryGetValue(key, out value);
    }

    public ICollection<TKey> Keys
    {
        get { return _dictionary.Keys.ToArray(); }
    }

    public ICollection<TValue> Values
    {
        get { return _dictionary.Values.ToArray(); }
    }

    private void UpdateSnapshot()
    {
        lock (snapshot)
        {
            snapshot = new Dictionary<TKey, TValue>(_dictionary);
        }
    }
}

class Logger
{
    static void Main(string[] args)
    {
        var snapshotDict = new SnapshottingDictionary<int, string>();

        snapshotDict.Add(1, "One");
        snapshotDict.Add(2, "Two");

        string value;
        if (snapshotDict.TryGetValue(1, out value))
        {
            Console.WriteLine($"Key 1: {value}");
        }

        foreach (var key in snapshotDict.Keys)
        {
            Console.WriteLine($"Key: {key}");
        }

        var snapshot = snapshotDict.GetSnapshot();
        Console.WriteLine("Snapshot contents:");
        foreach (var kvp in snapshot)
        {
            Console.WriteLine($"Key: {kvp.Key}, Value: {kvp.Value}");
        }

        snapshotDict.Remove(1);
        Console.WriteLine($"After removing key 1. Available keys: {string.Join(", ", snapshotDict.Keys)}");

        snapshot = snapshotDict.GetSnapshot();

