using System;
using System.IO;
using System.Runtime.InteropServices;
using System.Security;
using OpenSystem.Platform;

// Secure session provider object that uses the GNUTLS library to
// provide the underlying security functionality.

internal unsafe sealed class GNUTLS : ISecureSessionProvider
{
    // Internal state.
    private static bool initialized = false;

    // Constructor.
    public GNUTLS()
            {
                // Make sure that the GNUTLS library is initialized.
                lock(typeof(GNUTLS))
                {
                    if(!initialized)
                    {
                        try
                        {
                            gnutls_global_init();
                        }
                        catch(Exception)
                        {
                            // Could not find the functions to execute,
                            // so we probably don't have GNUTLS on this
                            // system or it isn't on the LD_LIBRARY_PATH.
                            throw new NotSupportedException();
                        }
                        initialized = true;
                    }
                }
            }

    // Implement the ISecureSessionProvider interface.
    public ISecureSession CreateClientSession(Protocol protocol)
            {
                return new GNUTLSSession(protocol, true);
            }
    public ISecureSession CreateServerSession(Protocol protocol)
            {
                return new GNUTLSSession(protocol, false);
            }

    // Credentials object for GNUTLS.
    private abstract class GNUTLSCredentials : IDisposable
    {
        // Internal state.
        protected IntPtr cred;
        private bool isDisposed;

        // Constructor.
        protected GNUTLSCredentials() {}

        // Finalizer.
        ~GNUTLSCredentials()
        {
            if(isDisposed == false)
            {
                Dispose();
            }
        }

        // Get the credential pointer.
        public IntPtr Cred
                {
                    get
                    {
                        return cred;
                    }
                }

        // Get the credential type.
        public abstract int CredType { get; }

        // Dispose of this object.
        public virtual void Dispose()
                {
                    cred = IntPtr.Zero;
                    isDisposed = true;
                }

    }; // class GNUTLSCredentials

using UnityEngine;
using System.Collections;

public class trashcan : MonoBehaviour {
  public bool ready = false;
  Material mat;
  menuManager manager;

  public AudioClip trashAct, trashOn, trashOff;

  Color offColor = new Color(.5f, .5f, .1f);
  Color onColor = new Color(1, 1, 1);

  void Awake() {
    mat = transform.GetChild(0).GetComponent<Renderer>().material;
    manager = transform.parent.parent.GetComponent<menuManager>();
    offColor = Color.HSVToRGB(.6f, .7f, .9f);
    mat.SetColor("_TintColor", offColor);
    mat.SetFloat("_EmissionGain", .2f);
  }

  public void trashEvent() {
    manager.GetComponent<AudioSource>().PlayOneShot(trashAct, .5f);
    StartCoroutine(flash());
  }

  IEnumerator flash() {
    float t = 0;
    mat.SetFloat("_EmissionGain", .6f);
    while (t < 1) {
      t = Mathf.Clamp01(t + Time.deltaTime * 2);
      mat.SetFloat("_EmissionGain", Mathf.Lerp(.6f, .2f, t));
      mat.SetColor("_TintColor", Color.Lerp(onColor, offColor, t));
      yield return null;
    }
  }

  public void setReady(bool on) {
    if (on) {
      mat.SetColor("_TintColor", onColor);
      manager.GetComponent<AudioSource>().PlayOneShot(trashOn, .15f);
    } else {
      manager.GetComponent<AudioSource>().PlayOneShot(trashOff, .15f);
      mat.SetColor("_TintColor", offColor);
    }
  }
}

