namespace AbandonedMutexTest
{
    class Order
    {
        // Total number of synchronization objects in the array.
        private const int HandleCount = 9;
        // Array holding a mix of synchronization primitives.
        private static WaitHandle[] syncHandles;

        // This manual reset event is used to signal when the worker thread has acquired all mutexes.
        private static ManualResetEvent workerSignal = new ManualResetEvent(false);

        static void Main(string[] args)
        {
            Console.WriteLine("Test starting: setting up synchronization objects...");
            syncHandles = CreateArray(HandleCount);

            // Start a worker thread to acquire (and eventually abandon) all mutex objects in our array.
            Thread workerThread = new Thread(AbandonAllMutexes);
            workerThread.Start();

            // Wait for the worker thread to signal that it has acquired all mutexes.
            Console.WriteLine("Main thread waiting for worker thread to acquire mutexes.");
            workerSignal.WaitOne();
            Console.WriteLine("Worker thread signaled completion. Now waiting on any sync object...");

            try
            {
                // Attempt to wait until any one of the synchronization objects is signaled.
                // Since one or more mutexes have been abandoned, we expect an AbandonedMutexException.
                int index = WaitHandle.WaitAny(syncHandles, 5000);
                Console.WriteLine("Unexpectedly returned from WaitAny: index " + index);
            }
            catch (AbandonedMutexException ex)
            {
                Console.WriteLine("Caught expected AbandonedMutexException:");
                Console.WriteLine("  Message: " + ex.Message);
                Console.WriteLine("  Mutex index: " + ex.MutexIndex);
                Console.WriteLine("Test Passed: Abandoned mutex was detected.");
            }
            catch (Exception ex)
            {
                Console.WriteLine("Test failed with unexpected exception: " + ex.Message);
            }

            // Clean up and ensure worker thread has finished.
            workerThread.Join();
            Console.WriteLine("Test finished. Press any key to exit.");
            Console.ReadKey();
        }

        // Create an array of synchronization objects.
        // The objects are created in a cyclic pattern of:
        // ManualResetEvent, Mutex, and Semaphore.
        private static WaitHandle[] CreateArray(int count)
        {

using UnityEngine;
using HutongGames.PlayMaker;

public enum BaseOrientation
{
    Portrait,
    LandscapeLeft,
    LandscapeRight,
    PortraitUpsideDown
}

public class GetDeviceRoll : FsmStateAction
{
    [RequiredField]
    public FsmOwnerDefault gameObject;

    [UIHint(UIHint.Variable)]
    public FsmFloat storeAngle;

    public BaseOrientation baseOrientation = BaseOrientation.Portrait;
    public bool limitAngle = true;
    public FsmFloat minAngle = -45f;
    public FsmFloat maxAngle = 45f;
    public bool smoothing = true;
    public FsmFloat smoothSpeed = 5f;

    private float currentAngle;
    private float targetAngle;
    private float lastAccelX;
    private float lastAccelY;

    public override void Reset()
    {
        gameObject = null;
        storeAngle = null;
        baseOrientation = BaseOrientation.Portrait;
        limitAngle = true;
        minAngle = -45f;
        maxAngle = 45f;
        smoothing = true;
        smoothSpeed = 5f;
        currentAngle = 0f;
        targetAngle = 0f;
    }

    public override void OnEnter()
    {
        if (!Input.gyro.enabled)
        {
            Input.gyro.enabled = true;
        }
        lastAccelX = Input.acceleration.x;
        lastAccelY = Input.acceleration.y;
    }

    public override void OnUpdate()
    {
        float deviceRoll = DoGetDeviceRoll();

        if (limitAngle)
        {
            deviceRoll = Mathf.Clamp(deviceRoll, minAngle.Value, maxAngle.Value);
        }

        if (smoothing)
        {
            currentAngle = Mathf.Lerp(currentAngle, deviceRoll, Time.deltaTime * smoothSpeed.Value);
        }
        else
        {
            currentAngle = deviceRoll;
        }

        storeAngle.Value = currentAngle;
    }

    private float DoGetDeviceRoll()
    {
        Vector3 acceleration = Input.acceleration;
        float angle = 0f;

        switch (baseOrientation)
        {
            case BaseOrientation.Portrait:
                angle = Mathf.Atan2(acceleration.x, acceleration.y) * Mathf.Rad2Deg;
                break;
            case BaseOrientation.LandscapeLeft:
                angle = Mathf.Atan2(acceleration.y, -acceleration.x) * Mathf.Rad2Deg;
                break;
            case BaseOrientation.LandscapeRight:
                angle = Mathf.Atan2(-acceleration.y, acceleration.x) * Mathf.Rad2Deg;
                break;
            case BaseOrientation.PortraitUpsideDown:
                angle = Mathf.Atan2(-acceleration.x, -acceleration.y) * Mathf.Rad2Deg;
                break;
        }

        return angle;
    }
}

