using System;
using System.Collections.Generic;
using System.Threading;
using System.Linq;
using System.Text;

class Monitor {
    private bool finish = false;
    private int interval = 1000;
    private string filename = "output";
    private LinkedList<string> processes = new LinkedList<string>();
    private LinkedList<MonitorResource> resources = new LinkedList<MonitorResource>();
    public void ThreadProc() {
        while (!finish) {
            Thread.Sleep(interval);
            foreach (MonitorResource resource in resources) {
                resource.captureValue();
            }
        }
        foreach (MonitorResource resource in resources) {
                resource.saveResults();
        }
    }
    public void start() { finish = false; Thread t = new Thread(new ThreadStart(this.ThreadProc)); t.Start(); }
    public void stop() { finish = true; }
    public void prepareMonitoring() {
        resources.AddLast(new MemoryMonitor("Memory", this.filename));
        resources.AddLast(new DiskResource("Disk", this.filename));
        resources.AddLast(new CPUMonitor("CPU", this.filename, processes));
    }
    public void setInterval(int interval) { this.interval = interval; }
    public void setFilename(string filename) { this.filename = filename; }
    public void setProcess(LinkedList<string> processes) { this.processes = processes; }
}
abstract class MonitorResource {
    protected string name; protected string filename;
    public MonitorResource(string name, string filename) { this.name = name; this.filename = filename; }
    public abstract void captureValue();
    public abstract void saveResults();
}
class MemoryMonitor : MonitorResource {
    public MemoryMonitor(string name, string filename) : base(name, filename) { }
    public override void captureValue() { }
    public override void saveResults() { }
}
class DiskResource : MonitorResource {
    public DiskResource(string name, string filename) : base(name, filename) { }
    public override void captureValue() { }
    public override void saveResults() { }
}
class CPUMonitor : MonitorResource {
    //   static void Main(string[] args) {}
    private LinkedList<string> processes;
    public CPUMonitor(string name, string filename, LinkedList<string> processes) : base(name, filename) { this.processes = processes; }
    public override void captureValue() { }
    public override void saveResults() { }
}

