using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Text;
using System.Threading;

public class ExpressionCache
{
    private readonly ConcurrentDictionary<string, WeakReference<object>> _expressionCache;
    private readonly CalcEngine _calcEngine;
    private readonly int _maxCacheSize;
    private long _hitCount;
    private readonly object _lockObject = new object();

    public ExpressionCache(CalcEngine calcEngine, int maxCacheSize = 1000)
    {
        _calcEngine = calcEngine ?? throw new ArgumentNullException(nameof(calcEngine));
        _maxCacheSize = maxCacheSize;
        _expressionCache = new ConcurrentDictionary<string, WeakReference<object>>();
    }

    public object this[string expression]
    {
        get
        {
            if (string.IsNullOrWhiteSpace(expression))
                throw new ArgumentException("Invalid expression", nameof(expression));

            Interlocked.Increment(ref _hitCount);

            if (_expressionCache.TryGetValue(expression, out var weakRef))
            {
                if (weakRef.TryGetTarget(out var cachedExpression))
                {
                    return cachedExpression;
                }
            }

            var parsedExpression = _calcEngine.Parse(expression);
            CacheExpression(expression, parsedExpression);
            return parsedExpression;
        }
    }

    private void CacheExpression(string expression, object parsedExpression)
    {
        lock (_lockObject)
        {
            if (_expressionCache.Count >= _maxCacheSize)
            {
                RemoveDeadReferences();
            }

            if (_expressionCache.Count < _maxCacheSize)
            {
                _expressionCache[expression] = new WeakReference<object>(parsedExpression);
            }
        }
    }

    private void RemoveDeadReferences()
    {
        var deadKeys = new List<string>();

        foreach (var entry in _expressionCache)
        {
            if (!entry.Value.TryGetTarget(out _))
            {
                deadKeys.Add(entry.Key);
            }
        }

        foreach (var key in deadKeys)
        {
            _expressionCache.TryRemove(key, out _);
        }
    }

    public void CleanupCache()
    {
        lock (_lockObject)
        {
            RemoveDeadReferences();
        }
    }

    public long GetHitCount() => _hitCount;

    public int CurrentCacheSize => _expressionCache.Count;
}

