            {
                Response.Redirect("~/Login.aspx");
                return;
            }

            InitializeAppointmentClient();
            LoadPatientAppointments();
            ConfigureCalendarView();
            PopulateAppointmentGrid();
        }
    }

    private void InitializeAppointmentClient()
    {
        _appointmentClient = new AppointmentClient();
        string patientId = Session["UserID"].ToString();

        try
        {
            _appointmentData = _appointmentClient.GetPatientAppointments(patientId);
        }
        catch (Exception ex)
        {
            HandleServiceException(ex);
        }
    }

    private void LoadPatientAppointments()
    {
        if (_appointmentData != null && _appointmentData.Rows.Count > 0)
        {
            CustomizeColumnNames();
            FilterFutureAppointments();
        }
    }

    private void CustomizeColumnNames()
    {
        Dictionary<string, string> columnMappings = new Dictionary<string, string>
        {
            { "AppointmentID", "Reference Number" },
            { "DoctorName", "Consulting Physician" },
            { "AppointmentDate", "Scheduled Date" },
            { "AppointmentTime", "Time Slot" },
            { "Department", "Medical Department" }
        };

        foreach (var mapping in columnMappings)
        {
            if (_appointmentData.Columns.Contains(mapping.Key))
            {
                _appointmentData.Columns[mapping.Key].ColumnName = mapping.Value;
            }
        }
    }

    private void FilterFutureAppointments()
    {
        DataView dv = new DataView(_appointmentData);
        dv.RowFilter = $"[Scheduled Date] >= '{DateTime.Now}' AND [Scheduled Date] <= '{DateTime.Now.AddDays(7)}'";

        CalendarView.DataSource = dv;
        CalendarView.DataBind();
    }

    private void ConfigureCalendarView()
    {
        CalendarView.SelectedDate = DateTime.Now;
        CalendarView.VisibleDate = DateTime.Now;
        CalendarView.Caption = "Upcoming Medical Appointments";
    }

