namespace RomanNumerals
{
    class Builder
    {
        static void Main(string[] args)
        {
            try
            {
                Console.WriteLine("MCMXC = " + Roman.ToInt("MCMXC"));
                Console.WriteLine("MMVIII = " + Roman.ToInt("MMVIII"));
                Console.WriteLine("MDCLXVI = " + Roman.ToInt("MDCLXVI"));
            }
            catch (Exception e)
            {
                Console.WriteLine(e.Message);
            }
        }
    }

    public class Roman
    {
        public static int ToInt(char c)
        {
            switch (c)
            {
                case 'I': return 1;
                case 'V': return 5;
                case 'X': return 10;
                case 'L': return 50;
                case 'C': return 100;
                case 'D': return 500;
                case 'M': return 1000;
            }
            throw new Exception("Invalid character");
        }

        public static int ToInt(string s)
        {
            int retval = 0, pvs = 0;
            for (int i = s.Length - 1; i >= 0; i--)
            {
                int inc = ToInt(s[i]);
                retval += inc < pvs? -inc : inc;
                pvs = inc;
            }
            return retval;
        }
    }
}

