    public class WebLinkSet : IWebLinkSet
    {
        public string Copy { get; private set; }
        public Entity Entity { get; private set; }
        public string Name { get; private set; }
        public string Title { get; private set; }
        public IEnumerable<IWebLink> WebLinks { get; private set; }
        public string DisplayName { get; private set; }
        public string Description { get; private set; }
        public string Url { get; } = null;
        public bool Editable { get; private set; } = false;

        public WebLinkSet(Entity entity, IPortalViewEntity viewEntity, IEnumerable<IWebLink> webLinks)
        {
            if (entity == null) throw new ArgumentNullException("entity");
            if (viewEntity == null) throw new ArgumentNullException("viewEntity");
            if (webLinks == null) throw new ArgumentNullException("webLinks");

            Entity = entity;
            WebLinks = webLinks.ToArray();

            Copy = GetAttributeValue<string>(viewEntity, "adx_copy");
            Name = GetAttributeValue<string>(viewEntity, "adx_name");
            Title = GetAttributeValue<string>(viewEntity, "adx_title");
            DisplayName = GetAttributeValue<string>(viewEntity, "adx_displayname") ?? Name;
            Description = Name;
            Editable = GetAttributeValue<bool?>(viewEntity, "adx_editable") ?? false;
        }

        public IPortalViewAttribute GetAttribute(string logicalName)
        {
            return new PortalViewAttribute(new PortalViewEntity(Entity, null), logicalName);
        }

        private T GetAttributeValue<T>(IPortalViewEntity entity, string logicalName)
        {
            return entity.GetAttribute(logicalName).GetValue<T>();
        }
    }
