    // Event argument used when an option change is detected.
    public class OptionChangedEventArgs : EventArgs
    {
        public IOption Option { get; }
        public object OldValue { get; }
        public object NewValue { get; }

        public OptionChangedEventArgs(IOption option, object oldValue, object newValue)
        {
            Option = option;
            OldValue = oldValue;
            NewValue = newValue;
        }
    }

    // Interface defining the contract for incremental analyzers.
    public interface IIncrementalAnalyzer
    {
        Task NewSolutionSnapshotAsync(Sorter solution, CancellationToken cancellationToken);
        Task DocumentOpenAsync(Document document, CancellationToken cancellationToken);
        Task DocumentCloseAsync(Document document, CancellationToken cancellationToken);
        Task DocumentResetAsync(Document document, CancellationToken cancellationToken);
        Task AnalyzeSyntaxAsync(Document document, CancellationToken cancellationToken);
        Task AnalyzeDocumentAsync(Document document, CancellationToken cancellationToken);
        Task AnalyzeProjectAsync(Project project, CancellationToken cancellationToken);
        void RemoveDocument(DocumentId documentId);
        void RemoveProject(ProjectId projectId);
        bool NeedsReanalysisOnOptionChanged(OptionChangedEventArgs e);
    }

    // Abstract base class providing default, no-operation implementations.
    public abstract class IncrementalAnalyzerBase : IIncrementalAnalyzer
    {
        public virtual Task NewSolutionSnapshotAsync(Sorter solution, CancellationToken cancellationToken)
        {
            // Default no-op implementation: simply return a completed task.
            return Task.CompletedTask;
        }

        public virtual Task DocumentOpenAsync(Document document, CancellationToken cancellationToken)
        {
            // Default no-op for document open event.
            return Task.CompletedTask;
        }

        public virtual Task DocumentCloseAsync(Document document, CancellationToken cancellationToken)
        {
            // Default no-op for document close event.
            return Task.CompletedTask;
        }

