namespace System.Net.Http.Headers
{
    public class WarningHeaderValue : ICloneable
    {
        private int _code;
        private string _agent;
        private string _text;
        private DateTimeOffset? _date;

        public int Code
        {
            get { return _code; }
        }

        public string Agent
        {
            get { return _agent; }
        }

        public string Text
        {
            get { return _text; }
        }

        public DateTimeOffset? Date
        {
            get { return _date; }
        }

        public WarningHeaderValue(int code, string agent, string text)
        {
            CheckCode(code);
            CheckAgent(agent);
            HeaderUtilities.CheckValidQuotedString(text, nameof(text));

            _code = code;
            _agent = agent;
            _text = text;
        }

        public WarningHeaderValue(int code, string agent, string text, DateTimeOffset date)
        {
            CheckCode(code);
            CheckAgent(agent);
            HeaderUtilities.CheckValidQuotedString(text, nameof(text));

            _code = code;
            _agent = agent;
            _text = text;
            _date = date;
        }

        private WarningHeaderValue()
        {
        }

        private WarningHeaderValue(WarningHeaderValue source)
        {
            Debug.Assert(source != null);

            _code = source._code;
            _agent = source._agent;
            _text = source._text;
            _date = source._date;
        }

        public override string ToString()
        {
            StringBuilder sb = StringBuilderCache.Acquire();

            // Warning codes are always 3 digits according to RFC2616
            sb.Append(_code.ToString("000", NumberFormatInfo.InvariantInfo));

            sb.Append(' ');
            sb.Append(_agent);
            sb.Append(' ');
            sb.Append(_text);

            if (_date.HasValue)
            {
                sb.Append(" \"");
                sb.Append(HttpRuleParser.DateToString(_date.Value));
                sb.Append('\"');
            }

            return StringBuilderCache.GetStringAndRelease(sb);
        }

        public override bool Equals(object obj)
        {
            WarningHeaderValue other = obj as WarningHeaderValue;

            if (other == null)
            {
                return false;
            }

using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.MSBuild;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

public class OperatorSymbolReferenceFinder : AbstractReferenceFinder
{
    private readonly IMethodSymbol _operatorSymbol;
    private readonly Project _project;

    public OperatorSymbolReferenceFinder(IMethodSymbol operatorSymbol, Project project)
    {
        _operatorSymbol = operatorSymbol;
        _project = project;
    }

    public static bool CanFind(IMethodSymbol methodSymbol)
    {
        return methodSymbol.IsOperator() && methodSymbol.MethodKind == MethodKind.UserDefinedOperator;
    }

    public async Task<List<Document>> FindReferencesAsync(IEnumerable<Document> documents)
    {
        var resultDocuments = new List<Document>();

        foreach (var document in documents)
        {
            var containsReference = await FindReferencesInDocumentAsync(document);
            if (containsReference)
            {
                resultDocuments.Add(document);
            }
        }

        return resultDocuments;
    }

    private async Task<bool> FindReferencesInDocumentAsync(Document document)
    {
        var semanticModel = await document.GetSemanticModelAsync();
        var syntaxRoot = await document.GetSyntaxRootAsync();

        return syntaxRoot.DescendantNodes()
            .OfType<IdentifierNameSyntax>()
            .Any(identifier => IsPotentialReference(identifier, semanticModel));
    }

    private bool IsPotentialReference(IdentifierNameSyntax identifier, SemanticModel semanticModel)
    {
        var symbol = semanticModel.GetSymbolInfo(identifier).Symbol as IMethodSymbol;

        if (symbol != null && symbol.Equals(_operatorSymbol))
        {
            return true;
        }

        return false;
    }

    public async Task<IEnumerable<Document>> DetermineDocumentsToSearchAsync()
    {
        var documents = await GetDocumentsInProjectAsync(_project);
        var filteredDocuments = documents.Where(doc => doc.SupportsSyntaxTree);
        return filteredDocuments;
    }

    private async Task<IEnumerable<Document>> GetDocumentsInProjectAsync(Project project)
    {
        return await Task.Run(() => project.Documents.ToList());
    }
}

