public class NUnitTestFixture : TestFixture
{
    private readonly List<MethodInfo> _fixtureSetUpMethods = new List<MethodInfo>();
    private readonly List<MethodInfo> _fixtureTearDownMethods = new List<MethodInfo>();
    private readonly List<MethodInfo> _setUpMethods = new List<MethodInfo>();
    private readonly List<MethodInfo> _tearDownMethods = new List<MethodInfo>();
    private object _fixtureInstance;
#if CLR_4_0
    private List<Action> _actions;
#endif

    public NUnitTestFixture(Type fixtureType, object[] constructorArgs)
        : base(fixtureType, constructorArgs)
    {
        InitializeFixtureMethods(fixtureType);
        _fixtureInstance = Activator.CreateInstance(fixtureType, constructorArgs);
    }

    private void InitializeFixtureMethods(Type fixtureType)
    {
        foreach (var method in fixtureType.GetMethods(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic))
        {
            if (method.IsDefined(typeof(FixtureSetUpAttribute), false))
                _fixtureSetUpMethods.Add(method);
            else if (method.IsDefined(typeof(FixtureTearDownAttribute), false))
                _fixtureTearDownMethods.Add(method);
            else if (method.IsDefined(typeof(SetUpAttribute), false))
                _setUpMethods.Add(method);
            else if (method.IsDefined(typeof(TearDownAttribute), false))
                _tearDownMethods.Add(method);
        }
    }

    public override void DoOneTimeSetUp(TestResult result)
    {
        int initialAsserts = Assert.GetAssertCount();
        base.DoOneTimeSetUp(result);
        ExecuteMethods(_fixtureSetUpMethods);
        result.AssertCount += Assert.GetAssertCount() - initialAsserts;
    }

    public override void DoOneTimeTearDown(TestResult result)
    {
        int initialAsserts = Assert.GetAssertCount();
        base.DoOneTimeTearDown(result);
        ExecuteMethods(_fixtureTearDownMethods);
        result.AssertCount += Assert.GetAssertCount() - initialAsserts;
    }

    protected override void DoSetUp()
    {
        base.DoSetUp();
        ExecuteMethods(_setUpMethods);
    }

    protected override void DoTearDown()
    {
        base.DoTearDown();
        ExecuteMethods(_tearDownMethods);
    }

    private void ExecuteMethods(IEnumerable<MethodInfo> methods)
    {
        foreach (var method in methods)
        {
            method.Invoke(_fixtureInstance, null);
        }
    }

