#include <stdio.h>
#include <math.h>
 
#define TIME_MAXIMUM 10.0
#define WHOLE_TOLERANCE 1.0e-5
#define T_START 0.0
#define Y_START 1.0
#define DT 0.10
 
double my_diff_eqn(double t, double y) { return t * sqrt(y); }
double my_solution(double t) { return (t*t + 4)*(t*t + 4) / 16; }
double find_error(double t, double y) { return fabs(y - my_solution(t)); }
int is_whole(double t) { return fabs(t - round(t)) < WHOLE_TOLERANCE; }
 
double (*dy)(double, double, double);
 
double calc_rk4(double (*f)(double, double)) {
  return (double (*)(double, double, double))([=](double t, double y, double dt) {
    double dy1 = dt * f(t, y);
    double dy2 = dt * f(t + dt / 2, y + dy1 / 2);
    double dy3 = dt * f(t + dt / 2, y + dy2 / 2);
    double dy4 = dt * f(t + dt, y + dy3);
    return (dy1 + 2 * dy2 + 2 * dy3 + dy4) / 6;
  });
}
 
int main() {
  dy = calc_rk4(my_diff_eqn);
  double t = T_START, y = Y_START;
  while (t <= TIME_MAXIMUM) {
    if (is_whole(t)) printf("y(%4.1f)\t= %12.6f \t error: %12.6e\n", t, y, find_error(t, y));
    t += DT;
    y += dy(t, y, DT);
  }
  return 0;
}

