    class Modulo : IComparable
    {
        private int n;
        private int m;

        public Modulo(int n = 0, int m = 13)
        {
            this.n = n % m;
            this.m = m;
        }

        public int ToInt()
        {
            return n;
        }

        public int CompareTo(object obj)
        {
            return n.CompareTo(((Modulo)obj).ToInt());
        }

        public static Modulo operator +(Modulo x, Modulo y)
        {
            return new Modulo(x.ToInt() + y.ToInt(), x.m);
        }

        public static Modulo operator -(Modulo x, Modulo y)
        {
            return new Modulo(x.ToInt() - y.ToInt(), x.m);
        }

        public static Modulo operator *(Modulo x, Modulo y)
        {
            return new Modulo(x.ToInt() * y.ToInt(), x.m);
        }

        public static Modulo operator **(Modulo x, Modulo y)
        {
            return new Modulo((int)Math.Pow(x.ToInt(), y.ToInt()), x.m);
        }

        public static Modulo operator +(Modulo x, int y)
        {
            return new Modulo(x.ToInt() + y, x.m);
        }

        public static Modulo operator +(int x, Modulo y)
        {
            return new Modulo(x + y.ToInt(), y.m);
        }

        public static Modulo operator -(Modulo x, int y)
        {
            return new Modulo(x.ToInt() - y, x.m);
        }

        public static Modulo operator -(int x, Modulo y)
        {
            return new Modulo(x - y.ToInt(), y.m);
        }

        public static Modulo operator *(Modulo x, int y)
        {
            return new Modulo(x.ToInt() * y, x.m);
        }

        public static Modulo operator *(int x, Modulo y)
        {
            return new Modulo(x * y.ToInt(), y.m);
        }

        public static Modulo operator **(Modulo x, int y)
        {
            return new Modulo((int)Math.Pow(x.ToInt(), y), x.m);
        }

        public static Modulo operator **(int x, Modulo y)
        {
            return new Modulo((int)Math.Pow(x, y.ToInt()), y.m);

