public enum ERR_TYPES_SERVER
{
    DATABASE_CONNECTION,
    NETWORK_TIMEOUT,
    AUTHENTICATION_FAILURE,
    RESOURCE_UNAVAILABLE,
    CONFIGURATION_ERROR,
    RUNTIME_EXCEPTION,
    SECURITY_VIOLATION,
    SYSTEM_OVERLOAD
}

public class ErrContainerServer
{
    public string i_ErrorMsg { get; private set; }
    public ERR_TYPES_SERVER i_ErrType { get; private set; }
    public DateTime i_ErrorTime { get; private set; }
    public string i_AdditionalInfo { get; private set; }
    public string i_ErrTypeStartMark { get; } = "<error_type>";
    public string i_ErrTypeEndMark { get; } = "</error_type>";

    public ErrContainerServer(string errorMsg, ERR_TYPES_SERVER errorType, string additionalInfo = null)
    {
        i_ErrorMsg = errorMsg;
        i_ErrType = errorType;
        i_ErrorTime = DateTime.Now;
        i_AdditionalInfo = additionalInfo;
    }

    public override string ToString()
    {
        string formattedError = $"Error Timestamp: {i_ErrorTime}\n" +
                                $"{i_ErrTypeStartMark}{i_ErrType}{i_ErrTypeEndMark}\n" +
                                $"Error Message: {i_ErrorMsg}\n";

        if (!string.IsNullOrEmpty(i_AdditionalInfo))
        {
            formattedError += $"Additional Context: {i_AdditionalInfo}";
        }

        return formattedError;
    }
}

