namespace RangeExceptions
{
    public class InvalidRangeException<T> : Exception
    {
        public T Start { get; }
        public T End { get; }

        public InvalidRangeException(string message, T start, T end) : base(message)
        {
            Start = start;
            End = end;
        }
    }

    class Cache
    {
        static void Main(string[] args)
        {
            try
            {
                Console.Write("Enter an integer between 0 and 100: ");
                int number = int.Parse(Console.ReadLine());
                ValidateRange(number, 0, 100, "Integer is out of range.");

                Console.Write("Enter a date between 1.1.1980 and 31.12.2013 (dd.MM.yyyy): ");
                DateTime date = DateTime.ParseExact(Console.ReadLine(), "dd.MM.yyyy", CultureInfo.InvariantCulture);
                DateTime startDate = new DateTime(1980, 1, 1);
                DateTime endDate = new DateTime(2013, 12, 31);
                ValidateRange(date, startDate, endDate, "Date is out of range.");

                Console.WriteLine("Input is valid!");
            }
            catch (InvalidRangeException<int> ex)
            {
                Console.WriteLine($"{ex.Message} Valid range is {ex.Start} to {ex.End}.");
            }
            catch (InvalidRangeException<DateTime> ex)
            {
                Console.WriteLine($"{ex.Message} Valid range is {ex.Start:dd.MM.yyyy} to {ex.End:dd.MM.yyyy}.");
            }
            catch (FormatException)
            {
                Console.WriteLine("Invalid input format.");
            }
        }

        static void ValidateRange<T>(T value, T start, T end, string errorMessage) where T : IComparable<T>
        {
            if (value.CompareTo(start) < 0 || value.CompareTo(end) > 0)
            {
                throw new InvalidRangeException<T>(errorMessage, start, end);
            }
        }
    }
}

