        {
            if (x == null || y == null)
                throw new ArgumentNullException();

            // Prioritize methods over other member types
            if (x is IMethod && !(y is IMethod))
                return -1;
            if (!(x is IMethod) && y is IMethod)
                return 1;

            // Prioritize properties over fields and events
            if (x is IProperty && !(y is IProperty))
                return -1;
            if (!(x is IProperty) && y is IProperty)
                return 1;

            // Prioritize fields over events
            if (x is IField && !(y is IField))
                return -1;
            if (!(x is IField) && y is IField)
                return 1;

            // If both members are of the same type, use type-specific comparison
            if (x is IMethod && y is IMethod)
                return CompareMethods((IMethod)x, (IMethod)y);

            // Default to name comparison for other member types
            return string.Compare(x.Name, y.Name, StringComparison.Ordinal);
        }

        private int CompareMethods(IMethod x, IMethod y)
        {
            // Compare names
            int nameComparison = string.Compare(x.Name, y.Name, StringComparison.Ordinal);
            if (nameComparison != 0)
                return nameComparison;

            // Compare parameter counts
            int paramCountComparison = x.Parameters.Count.CompareTo(y.Parameters.Count);
            if (paramCountComparison != 0)
                return paramCountComparison;

            // Compare parameter types
            for (int i = 0; i < x.Parameters.Count; i++)
            {
                int paramTypeComparison = string.Compare(
                    x.Parameters[i].Type.ReflectionName,
                    y.Parameters[i].Type.ReflectionName,
                    StringComparison.Ordinal);
                if (paramTypeComparison != 0)
                    return paramTypeComparison;
            }

            // Compare return types
            int returnTypeComparison = string.Compare(
                x.ReturnType.ReflectionName,
                y.ReturnType.ReflectionName,

