    public class StoreSettingsFaceBook
    {
        private readonly StoreSettings parent;

        public StoreSettingsFaceBook(StoreSettings storeSettings)
        {
            parent = storeSettings ?? throw new ArgumentNullException(nameof(storeSettings));
        }

        public bool IsFacebookIntegrationEnabled
        {
            get => parent.IsFacebookEnabled;
            set => parent.IsFacebookEnabled = value;
        }

        public string FacebookApplicationId
        {
            get => parent.FacebookAppId;
            set => parent.FacebookAppId = value;
        }

        public List<string> AdminAccountList
        {
            get => new List<string>(parent.AdminAccounts.Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries));
            set => parent.AdminAccounts = string.Join(";", value);
        }

        public void AddAdminAccount(string email)
        {
            var adminList = AdminAccountList;
            if (!adminList.Contains(email))
            {
                adminList.Add(email);
                AdminAccountList = adminList;
            }
        }

        public void RemoveAdminAccount(string email)
        {
            var adminList = AdminAccountList;
            if (adminList.Contains(email))
            {
                adminList.Remove(email);
                AdminAccountList = adminList;
            }
        }

        public void DisplaySettings()
        {
            Console.WriteLine($"Facebook Integration Enabled: {IsFacebookIntegrationEnabled}");
            Console.WriteLine($"Facebook Application ID: {FacebookApplicationId}");
            Console.WriteLine($"Admin Accounts: {parent.AdminAccounts}");
        }
    }

