        public static GravityEntryFile Load(string filePath = "default/path/to/gravityEntry.json", bool logErrors = false)
        {
            if (!File.Exists(filePath))
            {
                HandleError($"File not found: {filePath}", logErrors);
                return null;
            }

            try
            {
                string encryptedContent = File.ReadAllText(filePath);
                string decryptedContent = DecryptR3DES(encryptedContent);
                GravityEntryFile entry = JsonConvert.DeserializeObject<GravityEntryFile>(decryptedContent);
                return entry;
