            {
                HandleError("Decryption failed: " + ex.Message, logErrors);
            }
            catch (JsonException ex)
            {
                HandleError("Deserialization failed: " + ex.Message, logErrors);
            }
            catch (Exception ex)
            {
                HandleError("An unexpected error occurred: " + ex.Message, logErrors);
            }
            return null;
        }

