namespace Buckets
{
    class Game
    {
        const int N_BUCKETS = 15;
        static int[] buckets = new int[N_BUCKETS];
        static Mutex[] bucket_mutex = new Mutex[N_BUCKETS];
        static Thread equalizer;
        static Thread randomizer;
 
        static void transfer_value(int from, int to, int howmuch)
        {
            bool swapped = false;
 
            if ((from == to) || (howmuch < 0) ||
                (from < 0) || (to < 0) || (from >= N_BUCKETS) || (to >= N_BUCKETS)) return;
 
            if (from > to)
            {
                int temp1 = from;
                from = to;
                to = temp1;
                swapped = true;
                howmuch = -howmuch;
            }
 
            bucket_mutex[from].WaitOne();
            bucket_mutex[to].WaitOne();
 
            if (howmuch > buckets[from] &&!swapped)
                howmuch = buckets[from];
            if (-howmuch > buckets[to] && swapped)
                howmuch = -buckets[to];
 
            buckets[from] -= howmuch;
            buckets[to] += howmuch;
 
            bucket_mutex[from].ReleaseMutex();
            bucket_mutex[to].ReleaseMutex();
        }
 
        static void print_buckets()
        {
            int i;
            int sum = 0;
 
            for (i = 0; i < N_BUCKETS; i++) bucket_mutex[i].WaitOne();
            for (i = 0; i < N_BUCKETS; i++)
            {
                Console.Write("{0,3} ", buckets[i]);
                sum += buckets[i];
            }
            Console.WriteLine("= {0}", sum);
            for (i = 0; i < N_BUCKETS; i++) bucket_mutex[i].ReleaseMutex();
        }
 
        static void equalizer_start()
        {
            for (; ; )
            {
                int b1 = new Random().Next(N_BUCKETS);
                int b2 = new Random().Next(N_BUCKETS);
                int diff = buckets[b1] - buckets[b2];
                if (diff < 0)
                    transfer_value(b2, b1, -diff / 2);
                else
                    transfer_value(b1, b2, diff / 2);
            }
        }
 
        static void randomizer_start()
        {
            for (; ; )
            {
                int b1 = new Random().Next(N_BUCKETS);
                int b2 = new Random().Next(N_BUCKETS);
                int diff = new Random().Next(buckets[b1] + 1);
                transfer_value(b1, b2, diff);
            }
        }
 
