using UnityEngine;

//
// CalculateRollAction.cs
// This action calculates the roll (rotation around the z-axis) of a mobile device using accelerometer data.
// The roll angle represents the tilt of the device from a baseline orientation (Portrait, LandscapeLeft, LandscapeRight).
//

// Base class representing a state action in a state machine framework.
// In a real project, this would derive from the actual state machine base class.
public abstract class StateActionBase : MonoBehaviour
{
    public virtual void Reset() { }
    public virtual void OnEnter() { }
    public virtual void OnUpdate() { }
}

// Main action class to calculate device roll.
public class CalculateRollAction : StateActionBase
{
    // Enumeration for device base orientations.
    public enum Orientation
    {
        Portrait,
        LandscapeLeft,
        LandscapeRight
    }

    // Public Variables

    // The expected device holding orientation.
    public Orientation baseOrientation = Orientation.Portrait;

    // The maximum angle (in degrees) to which the roll is clamped. Set to 0 or negative to disable clamping.
    public float limitAngle = 45f;

    // Smoothing factor used in interpolation of the roll value.
    public float smoothingFactor = 0.1f;

    // If true, calculate roll every frame. If false, calculate only on entering the state.
    public bool updateContinuous = true;

    // The computed roll angle after processing, accessible for other parts of the game.
    [HideInInspector]
    public float rollAngle;

    // Private Variables

    // Stores the last roll angle value to apply smoothing between frames.
    private float lastAngle = 0f;

    // Reset method: Called when the action is added or reset.
    public override void Reset()
    {
        // Reset roll values.
        rollAngle = 0f;
        lastAngle = 0f;

        // Set default orientation and parameters.
        baseOrientation = Orientation.Portrait;
        limitAngle = 45f;
        smoothingFactor = 0.1f;
        updateContinuous = true;
    }

    // OnEnter method: Invoked when the state action begins execution.
    public override void OnEnter()
    {
        // When entering, process roll if not updating continuously.
        if (!updateContinuous)
        {
            ProcessRoll();
        }
    }

    // OnUpdate method: Invoked once per frame if the action is set to update continuously.
    public override void OnUpdate()
    {
        if (updateContinuous)
        {
            ProcessRoll();
        }
    }

