namespace Hazelcast.Security
{
    public interface ICredentials
    {
        string GetUsername();
        void SetUsername(string username);
        string GetPassword();
        void SetPassword(string password);
        string ToString();
    }

    public abstract class AbstractCredentials
    {
        private string _username;

        public virtual string GetUsername()
        {
            return _username;
        }

        public virtual void SetUsername(string username)
        {
            _username = username;
        }
    }

    [Serializable]
    public class UsernamePasswordCredentials : AbstractCredentials, ICredentials
    {
        private byte[] _password;

        public UsernamePasswordCredentials()
        {
        }

        public UsernamePasswordCredentials(string username, string password)
        {
            SetUsername(username);
            SetPassword(password);
        }

        public override string GetUsername()
        {
            return base.GetUsername();
        }

        public override void SetUsername(string username)
        {
            base.SetUsername(username);
        }

        public string GetPassword()
        {
            if (_password == null)
            {
                return null;
            }
            return Encoding.UTF8.GetString(_password);
        }

        public void SetPassword(string password)
        {
            if (password == null)
            {
                _password = null;
            }
            else
            {
                _password = Encoding.UTF8.GetBytes(password);
            }
        }

        public override string ToString()
        {
            return $"Username: {GetUsername()}, Password: {new string('*', GetPassword()?.Length ?? 0)}";
        }
    }
}

