namespace PokerTableManager.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class TableController : ControllerBase
    {
        private readonly CorePokerContext _db;

        public TableController(CorePokerContext db)
        {
            _db = db;
        }

        [HttpGet("{id}")]
        public async Task<IActionResult> Get(string id)
        {
            var table = await _db.Tables
                .Include(t => t.Players)
                .FirstOrDefaultAsync(t => t.Id == id);

            if (table == null)
            {
                return NotFound();
            }

            return Ok(table);
        }

        [HttpPost]
        public async Task<IActionResult> Post([FromBody] TablePayload tablePayload)
        {
            if (!ModelState.IsValid)
            {
                return BadRequest(ModelState);
            }

            var player = await _db.Players.FirstOrDefaultAsync(p => p.Name == tablePayload.PlayerName);
            if (player == null)
            {
                return NotFound("Player not found.");
            }

            var table = new Table
            {
                Id = Guid.NewGuid().ToString(),
                Name = tablePayload.TableName,
                CreatedAt = DateTime.UtcNow,
                OwnerId = player.Id
            };

            _db.Tables.Add(table);
            await _db.SaveChangesAsync();

            return CreatedAtAction(nameof(Get), new { id = table.Id }, table);
        }
    }

    public class TablePayload
    {
        [Required]
        [StringLength(50, ErrorMessage = "Table name must be less than 50 characters.")]
        public string TableName { get; set; }

        [Required]
        [StringLength(50, ErrorMessage = "Player name must be less than 50 characters.")]
        public string PlayerName { get; set; }
    }

    public class CorePokerContext : DbContext
    {
        public DbSet<Table> Tables { get; set; }
        public DbSet<Player> Players { get; set; }
        public DbSet<TablePlayer> TablePlayers { get; set; }

        public CorePokerContext(DbContextOptions<CorePokerContext> options) : base(options) { }
    }

