        public void Initialize(ActionExecutingContext actionContext)
        {
            ActionContext = actionContext ?? throw new ArgumentNullException(nameof(actionContext));
            var actionDescriptor = actionContext.ActionDescriptor;
            var controllerType = actionContext.Controller.GetType();
            var methodName = actionDescriptor?.RouteValues["action"];
            var methodInfo = controllerType.GetMethod(methodName);
            if (methodInfo != null)
            {
                // Extract parameter values based on method info and context
                var values = GetParameterValues(methodInfo, actionContext);
                foreach (var item in values)
                {
                    _parameterValues.Add(item.Key, item.Value);
                }
            }
        }

        private Dictionary<string, object> GetParameterValues(MethodInfo method, ActionExecutingContext context)
        {
            var dict = new Dictionary<string, object>();
            var parameters = method.GetParameters();
            foreach (var parameter in parameters)
            {
                if (context.ActionArguments.ContainsKey(parameter.Name))
                {
                    dict.Add(parameter.Name, context.ActionArguments[parameter.Name]);
                }
            }
            return dict;
        }

        public void Validate()
        {
            if (_isValidatedBefore)
                return;

            SetDataAnnotationAttributeErrors();
            _isValidatedBefore = true;
        }

