    public abstract class Fibonacci
    {
        public static readonly Fibonacci ITERATIVE = new Iterative();
        public static readonly Fibonacci RECURSIVE = new Recursive();
        public static readonly Fibonacci CACHING = new Caching();

        public static readonly Fibonacci[] Values = { ITERATIVE, RECURSIVE, CACHING };

        public abstract long this[int n] { get; }

        private class Iterative : Fibonacci
        {
            public override long this[int n]
            {
                get
                {
                    if (n < 2)
                    {
                        return n;
                    }
                    else
                    {
                        long n1 = 0;
                        long n2 = 1;
                        for (int i = 0; i < n; i++)
                        {
                            long sum = n1 + n2;
                            n1 = n2;
                            n2 = sum;
                        }
                        return n1;
                    }
                }
            }
        }

        private class Recursive : Fibonacci
        {
            public override long this[int n]
            {
                get
                {
                    if (n < 2)
                    {
                        return n;
                    }
                    else
                    {
                        return this[n - 1] + this[n - 2];
                    }
                }
            }
        }

        private class Caching : Fibonacci
        {
            private Dictionary<int, long> cache = new Dictionary<int, long> { { 0, 0 }, { 1, 1 } };

            public override long this[int n]
            {
                get
                {
                    if (n < 2)
                    {
                        return n;
                    }
                    else
                    {
                        return impl(n);
                    }
                }
            }

