using System;
 
public class LeapYear
{
    public static bool IsLeapYear(int year)
    {
        return (!(year % 4) && year % 100 ||!(year % 400))? true : false;
    }
 
    public static void Main()
    {
        int[] test_case = {1900, 1994, 1996, 1997, 2000};
        for (int key = 0, end = test_case.Length; key < end; ++key) {
            int year = test_case[key];
            Console.WriteLine("{0} is {1}a leap year.", year, (IsLeapYear(year) == true? "" : "not "));
        }
    }
}

