            for (int i = 0; i < x.Length; i++)
            {
                x[i] = rand.Next(-128, 127);
            }
            RadixSort(x);
            for (int i = 0; i < x.Length; i++)
            {
                Console.Write(x[i] + " ");
            }
            Console.ReadKey();
        }
        static void RadixSort(int[] a)
        {
            int len = a.Length;
            uint[] x = new uint[len];
            for (int i = 0; i < len; i++)
            {
                x[i] = (uint)a[i];
            }
            for (int i = 0; i < len; i++)
            {
                x[i] ^= 0x80000000;
            }
            RadixSortUnsigned(x);
            for (int i = 0; i < len; i++)
            {
                x[i] ^= 0x80000000;
            }
            for (int i = 0; i < len; i++)
            {
                a[i] = (int)x[i];
            }
        }
        static void RadixSortUnsigned(uint[] a)
        {
            int len = a.Length;
            uint[] x = new uint[len];
            for (int i = 0; i < len; i++)
            {
                x[i] = a[i];
            }
            RadixSortUnsigned(x, 0, len, 0x80000000);
            for (int i = 0; i < len; i++)
            {
                a[i] = x[i];
            }
        }
        static void RadixSortUnsigned(uint[] a, int from, int to, uint bit)
        {
            if (to <= from + 1 || bit == 0)
            {
                return;
            }
            int ll = from;
            int rr = to - 1;
            while (true)
            {
                while (ll < rr && (a[ll] & bit) == 0)
                {
                    ll++;
                }
                while (ll < rr && (a[rr] & bit)!= 0)
                {
                    rr--;
                }
                if (ll >= rr)
                {
                    break;
                }
                uint tmp = a[ll];
                a[ll] = a[rr];
                a[rr] = tmp;
            }
            if ((a[ll] & bit) == 0 && ll < to)
            {
                ll++;
            }
            bit >>= 1;
            RadixSortUnsigned(a, from, ll, bit);
            RadixSortUnsigned(a, ll, to, bit);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;
using Microsoft.AspNet.SignalR;
using System.Threading.Tasks;
using System.Collections.Concurrent;

namespace Auth.Net.Hubs
{
    public class AuthorisationHub : Hub
    {

        static readonly ConcurrentDictionary<string, string> _clientConnections = new ConcurrentDictionary<string, string>();

        public   static int GetLiveConnectionsCount(string userName)
        {
            return _clientConnections.Where(c => c.Value == userName).Count();
        }

        public static void Refresh(string userName)
        {
            var conections = _clientConnections.Where(c => c.Value == userName).Select(c => c.Key).Distinct().ToList();
            var hub = GlobalHost.ConnectionManager.GetHubContext<AuthorisationHub>();
            foreach (var con in conections)
            {
                hub.Clients.Client(con).refresh();

            }
        }

        public override Task OnConnected()
        {
            var userName = Context.User.Identity.IsAuthenticated? Context.User.Identity.Name:null;
            _clientConnections.AddOrUpdate(Context.ConnectionId, userName, (n, l)=> userName);
            return base.OnConnected();
        }

        public override Task OnReconnected()
        {
            var userName = Context.User.Identity.IsAuthenticated ? Context.User.Identity.Name : null;
            _clientConnections.AddOrUpdate(Context.ConnectionId, userName, (n, l) => userName);
            return base.OnReconnected();
        }

        public override Task OnDisconnected(bool stopCalled)
        {
            string userName;
            _clientConnections.TryRemove(Context.ConnectionId, out userName);
            return base.OnDisconnected(stopCalled);
        }
    }
}

