public class Integer
{
    public bool Munchausen()
    {
        return this.Digits().Select(d => (int)Math.Pow(d, d)).Sum() == this;
    }
 
    public int[] Digits()
    {
        return this.ToString().Select(c => int.Parse(c.ToString())).ToArray();
    }
}
 
