using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace ARSoft.Tools.Net.Dns
{
    public interface ITextRecord
    {
        string TextData { get; }
    }

    public abstract class DnsRecordBase
    {
        public string DomainName { get; protected set; }
        public int TimeToLive { get; protected set; }

        protected DnsRecordBase(string domainName, int timeToLive)
        {
            DomainName = domainName;
            TimeToLive = timeToLive;
        }

        public abstract void ParseRecordData(byte[] resultData, int startPosition, int length);
        public abstract byte[] EncodeRecordData();
        public abstract string RecordDataToString();
    }

    public class TxtRecord : DnsRecordBase, ITextRecord
    {
        public string TextData { get; private set; }

        public TxtRecord(string domainName, int timeToLive, string textData)
            : base(domainName, timeToLive)
        {
            TextData = textData;
        }

        public override void ParseRecordData(byte[] resultData, int startPosition, int length)
        {
            var stringBuilder = new StringBuilder();
            int position = startPosition;

            while (position < startPosition + length)
            {
                int chunkLength = resultData[position++];
                stringBuilder.Append(Encoding.UTF8.GetString(resultData, position, chunkLength));
                position += chunkLength;
            }

            TextData = stringBuilder.ToString();
        }

        public override byte[] EncodeRecordData()
        {
            var chunks = new List<byte[]>();
            var bytes = Encoding.UTF8.GetBytes(TextData);
            int position = 0;

            while (position < bytes.Length)
            {
                int chunkLength = Math.Min(255, bytes.Length - position);
                var chunk = new byte[chunkLength + 1];
                chunk[0] = (byte)chunkLength;
                Buffer.BlockCopy(bytes, position, chunk, 1, chunkLength);
                chunks.Add(chunk);
                position += chunkLength;
            }

            return chunks.SelectMany(c => c).ToArray();
        }

        public override string RecordDataToString()
        {
            return $"\"{TextData}\"";
        }

        public int MaximumRecordDataLength
        {
            get
            {
                int length = Encoding.UTF8.GetByteCount(TextData);
                return length + (length / 255) + (length % 255 > 0 ? 1 : 0);
            }
        }
    }
}

using System;
using System.Windows;
using System.Windows.Controls;

public class ContentElement : Element, ISilverlightContainerElement
{
    private ContentControl _contentControl;
    private UIElement _rootElement;

    public ContentElement()
    {
        _contentControl = CreateFrameworkElement() as ContentControl;
    }

    protected override FrameworkElement CreateFrameworkElement()
    {
        return new ContentControl();
    }

    public void InsertChild(UIElement child)
    {
        if (!IsValidChild(child))
        {
            throw InvalidChildError(child);
        }

        if (_rootElement != null)
        {
            throw new ClientException("Only one child element can be added.");
        }

        _rootElement = child;
        _contentControl.Content = child;
    }

    public void RemoveChild(UIElement child)
    {
        if (_rootElement == child)
        {
            _rootElement = null;
            _contentControl.Content = null;
        }
    }

    protected virtual bool IsValidChild(UIElement child)
    {
        return child is ISilverlightElement;
    }

    protected virtual ClientException InvalidChildError(UIElement child)
    {
        return new ClientException($"Child element of type {child.GetType().Name} is not valid.");
    }

    public override void AddChild(object value)
    {
        if (value is UIElement child)
        {
            InsertChild(child);
        }
        else
        {
            throw new ClientException("Value is not a valid UIElement.");
        }
    }

    public override void RemoveChild(object value)
    {
        if (value is UIElement child)
        {
            RemoveChild(child);
        }
        else
        {
            throw new ClientException("Value is not a valid UIElement.");
        }
    }

    public override double GetDefaultMarginLeft()
    {
        return 0;
    }

    public override double GetDefaultMarginRight()
    {
        return 0;
    }

    public override double GetDefaultMarginTop()
    {
        return 0;
    }

    public override double GetDefaultMarginBottom()
    {
        return 0;
    }

    public override bool GetDefaultTabStop()
    {
        return false;
    }
}

public interface ISilverlightContainerElement
{
    void InsertChild(UIElement child);
    void RemoveChild(UIElement child);
}

public abstract class Element : UIElement
{
    protected abstract FrameworkElement CreateFrameworkElement();

    public abstract void AddChild(object value);
    public abstract void RemoveChild(object value);

