namespace Manager
{
    class Calculator
    {
        static void Main(string[] args)
        {
            double i = 42;
            int n = 0;
            while (n < 42)
            {
                if (isPrime(i))
                {
                    n++;
                    Console.Write("n = ");
                    Console.Write(n);
                    //Only for Text Alignment
                    if (n < 10)
                    {
                        Console.Write("                                   ");
                    }
                    else
                    {
                        Console.Write("                                  ");
                    }
                    Console.WriteLine(i);
                    i += i - 1;
                }
                i++;
            }
        }
        static bool isPrime(double number)
        {
            for (double i = number - 1; i >= 2; i--)
            {
                if (number % i == 0)
                    return false;
            }
            return true;
        }
    }
}

