using ProtoBuf.Meta;
using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Linq;

public static class ProtoBufTypeModel
{
    private static readonly HashSet<Type> _systemTypes = new HashSet<Type>
    {
        typeof(string),
        typeof(int),
        typeof(long),
        typeof(bool),
        typeof(DateTime),
        typeof(decimal),
        typeof(Guid),
        typeof(double),
        typeof(float)
    };

    public static RuntimeTypeModel ConfigureAquaTypes(this RuntimeTypeModel model, bool includeSystemTypes = true)
    {
        if (model == null)
            throw new ArgumentNullException(nameof(model));

        model.AutoCompile = true;
        model.ForwardsOnly = false;

        if (includeSystemTypes)
        {
            ConfigureDefaultSystemTypes(model);
        }

        return ConfigureDynamicTypes(model);
    }

    private static RuntimeTypeModel ConfigureDefaultSystemTypes(RuntimeTypeModel model)
    {
        foreach (var systemType in _systemTypes)
        {
            if (!model.IsDefined(systemType))
            {
                model.Add(systemType, true)
                     .SetSurrogate(systemType)
                     .IgnoreListHandling();
            }
        }

        return model;
    }

    private static RuntimeTypeModel ConfigureDynamicTypes(RuntimeTypeModel model)
    {
        model.Add(typeof(object), false)
             .SetSurrogate(typeof(object))
             .AddSubType(100, typeof(Dictionary<string, object>))
             .AddSubType(101, typeof(List<object>));

        return model.Compile();
    }

    public static void RegisterTypeWithModel<T>(this RuntimeTypeModel model, int fieldNumber)
    {
        if (!model.IsDefined(typeof(T)))
        {
            model.Add(typeof(T), true)
                 .SetSurrogate(typeof(T))
                 .AddSubType(fieldNumber, typeof(T));
        }
    }
}

using Hazelcast.Client.Protocol.Util;
using Hazelcast.IO.Serialization;

// Client Protocol version, Since:1.0 - Update:1.0
namespace Hazelcast.Client.Protocol.Codec
{
    internal static class ListLastIndexOfCodec
    {
        private static int CalculateRequestDataSize(string name, IData value)
        {
            var dataSize = ClientMessage.HeaderSize;
            dataSize += ParameterUtil.CalculateDataSize(name);
            dataSize += ParameterUtil.CalculateDataSize(value);
            return dataSize;
        }

        internal static ClientMessage EncodeRequest(string name, IData value)
        {
            var requiredDataSize = CalculateRequestDataSize(name, value);
            var clientMessage = ClientMessage.CreateForEncode(requiredDataSize);
            clientMessage.SetMessageType((int) ListMessageType.ListLastIndexOf);
            clientMessage.SetRetryable(true);
            clientMessage.Set(name);
            clientMessage.Set(value);
            clientMessage.UpdateFrameLength();
            return clientMessage;
        }

        internal class ResponseParameters
        {
            public int response;
        }

        internal static ResponseParameters DecodeResponse(IClientMessage clientMessage)
        {
            var parameters = new ResponseParameters();
            var response = clientMessage.GetInt();
            parameters.response = response;
            return parameters;
        }
    }
}

using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.AspNetCore.Mvc;
using System;

namespace WebApplicationNamespace
{
    public class Startup
    {
        public IConfigurationRoot Configuration { get; }
        private readonly IHostingEnvironment _environment;

        public Startup(IHostingEnvironment env)
        {
            _environment = env;

            var builder = new ConfigurationBuilder()
                .SetBasePath(env.ContentRootPath)
                .AddJsonFile("appsettings.json", optional: false, reloadOnChange: true)
                .AddJsonFile($"appsettings.{env.EnvironmentName}.json", optional: true)
                .AddEnvironmentVariables();

            Configuration = builder.Build();
        }

        public void ConfigureServices(IServiceCollection services)
        {
            services.AddSingleton(Configuration);

            services.AddMvc()
                .SetCompatibilityVersion(CompatibilityVersion.Version_2_2);

            services.AddLogging(config =>
            {
                config.AddConsole();
                config.AddDebug();

                if (_environment.IsDevelopment())
                {
                    config.AddConfiguration(Configuration.GetSection("Logging"));
                }
            });

            services.AddCors(options =>
            {
                options.AddPolicy("DefaultPolicy",
                    builder => builder
                        .AllowAnyOrigin()
                        .AllowAnyMethod()
                        .AllowAnyHeader());
            });
        }

        public void Configure(IApplicationBuilder app, IHostingEnvironment env, ILoggerFactory loggerFactory)
        {
            if (env.IsDevelopment())
            {
                app.UseDeveloperExceptionPage();
                app.UseDatabaseErrorPage();
            }
            else
            {
                app.UseExceptionHandler("/Home/Error");
                app.UseHsts();
            }

            app.UseHttpsRedirection();
            app.UseStaticFiles();
            app.UseCookiePolicy();
            app.UseCors("DefaultPolicy");

            app.UseMvc(routes =>
            {
                routes.MapRoute(
                    name: "default",
                    template: "{controller=Home}/{action=Index}/{id?}");
            });
        }
    }
}

using UnityEngine;
using UnityEngine.UI;
using System.Collections;

public class BossFightIntroManager : MonoBehaviour
{
    // Scene object references
    public GameObject player;
    public GameObject boss;
    public Camera mainCamera;
    public Text bossAnnouncementText;

    // Controllers and managers
    public MusicManager musicManager;
    public PlayerController playerController;
    public CameraController cameraController;
    public BossManager bossManager;

    // Flags to control sequence and state
    private bool sequenceStarted = false;
    private bool bossDefeated = false;

    // Initialization routine to setup scene references
    void Start()
    {
        if (player == null)
            player = GameObject.FindWithTag("Player");

        if (boss == null)
            boss = GameObject.FindWithTag("Boss");

        if (mainCamera == null)
            mainCamera = Camera.main;

        if (bossAnnouncementText == null)
        {
            GameObject uiTextObj = GameObject.Find("BossAnnouncementText");
            if (uiTextObj != null)
                bossAnnouncementText = uiTextObj.GetComponent<Text>();
        }

        // Get required controllers from scene objects
        if (player != null)
            playerController = player.GetComponent<PlayerController>();

        if (mainCamera != null)
            cameraController = mainCamera.GetComponent<CameraController>();

        if (boss != null)
            bossManager = boss.GetComponent<BossManager>();
    }

    // Per-frame update method to monitor boss state
    void Update()
    {
        if (!bossDefeated && bossManager != null && bossManager.IsDefeated())
        {
            bossDefeated = true;
            // Revert background music after boss defeat
            if (musicManager != null)
                musicManager.ChangeToNormalMusic();
        }
    }

    // Coroutine to manage the sequence of events leading into the boss fight
    IEnumerator BossFightSequence()
    {
        // Disable player controls to start cutscene
        if (playerController != null)
            playerController.DisableControls();

        // Redirect camera to focus on the boss for a cinematic effect
        if (cameraController != null)
            cameraController.FocusOnTarget(boss.transform);

        // Update UI to announce the boss
        if (bossAnnouncementText != null)
            bossAnnouncementText.text = "The Mighty Dragon";

        // Change background music to boss theme
        if (musicManager != null)
            musicManager.ChangeToBossMusic();

