namespace FloydsTriangle
{
    class Stack
    {
        static void Main(string[] args)
        {
            floyds_tri t = new floyds_tri();
            int s;
            while (true)
            {
                Console.Write("Enter the size of the triangle ( 0 to QUIT ): ");
                s = Convert.ToInt32(Console.ReadLine());
                if (s == 0) return;
                if (s > 0) t.create(s);

                Console.WriteLine();
                Console.WriteLine();
                Console.ReadLine();
            }
        }
    }

    class floyds_tri
    {
        public floyds_tri()
        {
            lastLineLen = new byte[0];
        }

        public void create(int rows)
        {
            _rows = rows;
            calculateLastLineLen();
            display();
        }

        private void calculateLastLineLen()
        {
            lastLineLen = new byte[_rows];

            int s = 1 + (_rows * (_rows - 1)) / 2;

            for (int x = s, ix = 0; x < s + _rows; x++, ix++)
            {
                string cvr = x.ToString();
                lastLineLen[ix] = (byte)cvr.Length;
            }
        }

        private void display()
        {
            Console.WriteLine();
            Console.WriteLine("Floyd\'s Triangle - " + _rows + " rows");
            Console.WriteLine("===============================================");
            int number = 1;
            for (int r = 0; r < _rows; r++)
            {
                for (int c = 0; c <= r; c++)
                {
                    string cvr = number++.ToString();
                    string str = cvr;
                    while (str.Length < lastLineLen[c])
                        str = " " + str;
                    Console.Write(str + " ");
                }
                Console.WriteLine();
            }
        }

        private int _rows;
        private byte[] lastLineLen;
    }
}

