using System;

namespace ProcessingPattern
{
    // Interface for processing with only input
    public interface IProcessor<TInput>
    {
        void Process(TInput input);
    }

    // Interface for processing with context and input
    public interface IProcessor<TContext, TInput>
    {
        void Process(TContext context, TInput input);
    }

    // Interface for processing with context, input, and output
    public interface IProcessor<TContext, TInput, TOutput>
    {
        void Process(TContext context, TInput input, ref TOutput output);
    }

    // Example context class
    public class MansionContext
    {
        public string ContextInfo { get; set; }
    }

    // Example input class
    public class MansionInput
    {
        public string InputData { get; set; }
    }

    // Example output class
    public class MansionOutput
    {
        public string OutputData { get; set; }
    }

    // Implementation of IProcessor<TInput>
    public class SimpleProcessor : IProcessor<MansionInput>
    {
        public void Process(MansionInput input)
        {
            Console.WriteLine($"Processing input: {input.InputData}");
        }
    }

    // Implementation of IProcessor<TContext, TInput>
    public class ContextualProcessor : IProcessor<MansionContext, MansionInput>
    {
        public void Process(MansionContext context, MansionInput input)
        {
            Console.WriteLine($"Processing input: {input.InputData} with context: {context.ContextInfo}");
        }
    }

    // Implementation of IProcessor<TContext, TInput, TOutput>
    public class OutputProcessor : IProcessor<MansionContext, MansionInput, MansionOutput>
    {
        public void Process(MansionContext context, MansionInput input, ref MansionOutput output)
        {
            Console.WriteLine($"Processing input: {input.InputData} with context: {context.ContextInfo}");
            output.OutputData = $"Processed: {input.InputData} in {context.ContextInfo}";
        }
    }

    // Example usage
    public class Student
    {
        public static void Main()
        {
            var simpleProcessor = new SimpleProcessor();
            var contextualProcessor = new ContextualProcessor();
            var outputProcessor = new OutputProcessor();

            var context = new MansionContext { ContextInfo = "Main Mansion" };
            var input = new MansionInput { InputData = "Secret Document" };
            var output = new MansionOutput();

            simpleProcessor.Process(input);
            contextualProcessor.Process(context, input);

using System;
 
public class EthiopianMultiplication
{
    static bool tutor = true;
 
    public static int halve(int x)
    {
        return x / 2;
    }
 
    public static int double_(int x)
    {
        return x * 2;
    }
 
    public static bool even(int x)
    {
        return x % 2 == 0;
    }
 
    public static int ethiopian(int multiplier, int multiplicand)
    {
        if (tutor)
        {
            Console.WriteLine("Ethiopian multiplication of {0} and {1}",
                              multiplier, multiplicand);
        }
        int result = 0;
        while (multiplier >= 1)
        {
            if (even(multiplier))
            {
                if (tutor)
                {
                    Console.WriteLine("{0,4} {1,6} STRUCK",
                                      multiplier, multiplicand);
                }
            }
            else
            {
                if (tutor)
                {
                    Console.WriteLine("{0,4} {1,6} KEPT",
                                      multiplier, multiplicand);
                }
                result += multiplicand;
            }
            multiplier = halve(multiplier);
            multiplicand = double_(multiplicand);
        }
        if (tutor)
        {
            Console.WriteLine();
        }
        return result;
    }
}

