using UnityEngine;
using System.Collections;

public class ControlFeuVehicule : MonoBehaviour
{
    public Material[] feux;
    public GameObject feuVert;
    public GameObject feuOrange;
    public GameObject feuRouge;
    public GameObject feuVertPieton;
    public GameObject feuRougePieton;

    public static bool feuPieton;

    private int cpt;
    public int changementFeu;
    public static int changementEtat;

    void Start()
    {
        changementEtat = Random.Range(0, 3);
        cpt = 0;

        UpdateLights();
    }

    void Update()
    {
        cpt++;
        if (cpt > changementFeu)
        {
            cpt = 0;
            changementEtat++;
            if (changementEtat > 2)
            {
                changementEtat = 0;
            }
            UpdateLights();
        }
    }

    void UpdateLights()
    {
        switch (changementEtat)
        {
            case 0:
                feuVert.GetComponent<Renderer>().material = feux[0];
                feuOrange.GetComponent<Renderer>().material = feux[1];
                feuRouge.GetComponent<Renderer>().material = feux[5];
                feuVertPieton.GetComponent<Renderer>().material = feux[1];
                feuRougePieton.GetComponent<Renderer>().material = feux[0];
                feuPieton = false;
                break;
            case 1:
                feuVert.GetComponent<Renderer>().material = feux[1];
                feuOrange.GetComponent<Renderer>().material = feux[4];
                feuRouge.GetComponent<Renderer>().material = feux[1];
                feuVertPieton.GetComponent<Renderer>().material = feux[1];
                feuRougePieton.GetComponent<Renderer>().material = feux[0];
                feuPieton = false;
                break;
            case 2:
                feuVert.GetComponent<Renderer>().material = feux[1];
                feuOrange.GetComponent<Renderer>().material = feux[1];
                feuRouge.GetComponent<Renderer>().material = feux[2];
                feuVertPieton.GetComponent<Renderer>().material = feux[0];
                feuRougePieton.GetComponent<Renderer>().material = feux[1];
                feuPieton = true;
                break;
        }
    }
}

