using System;

public class CarControls
{
    private PedalControls pedals = new PedalControls();
    private SteeringWheelControls steeringWheel = new SteeringWheelControls();
    private GearShiftControls gearShift = new GearShiftControls();
    private int gasPedalLevel = 0;

    public void DriveForward()
    {
        Console.WriteLine("Driving Forward:");
        for (int i = 1; i <= 5; i++)
        {
            SetGasPedal(i * 20);
            IncreaseGear();
        }
    }

    public void TurnLeft()
    {
        Console.WriteLine("Turning Left:");
        SetSteeringWheel(-30);
        ReduceGasAndDownshift();
    }

    public void TurnRight()
    {
        Console.WriteLine("Turning Right:");
        SetSteeringWheel(30);
        ReduceGasAndDownshift();
    }
    private void ReduceGasAndDownshift()
    {
        SetGasPedal(20);
        ReduceGear();
    }

    public void StopCar()
    {
        Console.WriteLine("Stopping Car:");
        Stop();
    }

    private void SetGasPedal(int level) { gasPedalLevel = level; pedals.SetGas(level); }
    private void SetSteeringWheel(int angle) { steeringWheel.SetAngle(angle); }
    private void IncreaseGear() { gearShift.ShiftUp(); }
    private void ReduceGear() { gearShift.ShiftDown(); }
    private void Stop() { pedals.SetGas(0); steeringWheel.SetAngle(0); gearShift.Neutral(); }
}
public class PedalControls { public void SetGas(int level) { Console.WriteLine($"Gas pedal set to: {level}%"); } }
public class SteeringWheelControls { public void SetAngle(int angle) { Console.WriteLine($"Steering wheel angle: {angle} degrees"); } }
public class GearShiftControls
{
    private int currentGear = 0;
    public void ShiftUp() { currentGear++; Console.WriteLine($"Shifted up to gear: {currentGear}"); }
    public void ShiftDown() { if (currentGear > 0) currentGear--; Console.WriteLine($"Shifted down to gear: {currentGear}"); }
    public void Neutral() { currentGear = 0; Console.WriteLine($"Gear set to Neutral"); }
}

using System;
 
public class Game
{
    public static void Main()
    {
        Console.WriteLine(mcpi(1000));
        Console.WriteLine(mcpi(10000));
        Console.WriteLine(mcpi(100000));
        Console.WriteLine(mcpi(1000000));
        Console.WriteLine(mcpi(10000000));
    }
 
    public static double mcpi(int n)
    {
        double x, y, m = 0;
 
        for (int i = 0; i < n; i += 1)
        {
            x = Math.Random();
            y = Math.Random();
 
            if (x * x + y * y < 1)
            {
                m += 1;
            }
        }
 
        return 4 * m / n;
    }
}

using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using System.Xml.Linq;

namespace MessagingAbstractions
{
    public class HttpServiceBusReceiver : IMessagingReceiver
    {
        private const string CLIENT_HEADER_NAME = "X-Client-Context";
        private static readonly HttpClient _httpClient = new HttpClient();
        private readonly Uri _endpoint;
        private readonly string _resourceId;

        public HttpServiceBusReceiver(string serviceUrl, string resourceId)
        {
            _endpoint = new Uri(serviceUrl);
            _resourceId = resourceId;
        }

        public async Task<IncomingHttpMessage> ReceiveAsync()
        {
            using var request = new HttpRequestMessage(HttpMethod.Get, _endpoint);
            request.Headers.Add(CLIENT_HEADER_NAME, GenerateClientIdentifier());

            try
            {
                using var response = await _httpClient.SendAsync(request);

                if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
                    return await HandleEmptyQueueResponse();

                response.EnsureSuccessStatusCode();
                return await ParseMessageContent(response);
            }
            catch (HttpRequestException ex) when (ex.Message.Contains("timed out"))
            {
                return null;
            }
        }

        private async Task<IncomingHttpMessage> ParseMessageContent(HttpResponseMessage response)
        {
            var xmlContent = await response.Content.ReadAsStringAsync();
            var xdoc = XDocument.Parse(xmlContent);

            return new IncomingHttpMessage
            {
                MessageId = xdoc.Root.Element("MessageId").Value,
                Body = xdoc.Root.Element("Payload").Value,
                Properties = xdoc.Root.Element("Metadata")?.Elements()
                    .ToDictionary(e => e.Name.LocalName, e => e.Value)
                    ?? new Dictionary<string, string>()
            };
        }

        private async Task<IncomingHttpMessage> HandleEmptyQueueResponse()
        {
            await Task.Delay(TimeSpan.FromSeconds(2.5));
            return null;
        }

        private string GenerateClientIdentifier()
        {
            var process = Process.GetCurrentProcess();
            return $"[{_resourceId}] {Environment.MachineName}:{process.Id}";
        }
    }

