public class FixtureService : IFixtureService
{
    private readonly IFixtureRepository _fixtureRepository;

    public FixtureService(IFixtureRepository fixtureRepository)
    {
        _fixtureRepository = fixtureRepository;
    }

    public FixtureModel GetFixture(int id)
    {
        return _fixtureRepository.GetFixtureById(id);
    }

    public FixtureModel GetNextFixture(string edition)
    {
        var upcomingFixtures = _fixtureRepository.GetUpcomingFixtures(edition);
        return upcomingFixtures.OrderBy(f => f.Date).FirstOrDefault();
    }

    public IEnumerable<FixtureModel> GetFixtures(IEnumerable<int> ids)
    {
        return _fixtureRepository.GetFixturesByIds(ids);
    }

    public IEnumerable<FixtureModel> GetFixturesForDay(DateTime date)
    {
        return _fixtureRepository.GetFixturesForDay(date);
    }

    public IEnumerable<FixtureModel> GetFixturesForEdition(string edition)
    {
        return _fixtureRepository.GetFixturesForEdition(edition);
    }
