        static bool sameDigits(int n, int b)
        {
            int f = n % b;
            while ((n /= b) > 0)
            {
                if (n % b!= f)
                {
                    return false;
                }
            }
            return true;
        }
 
        static bool isBrazilian(int n)
        {
            if (n < 7)
            {
                return false;
            }
            if (n % 2 == 0)
            {
                return true;
            }
            for (int b = 2; b < n - 2; b++)
            {
                if (sameDigits(n, b))
                {
                    return true;
                }
            }
            return false;
        }
 
        static bool isPrime(int n)
        {
            if (n < 2)
            {
                return false;
            }
            if (n % 2 == 0)
            {
                return n == 2;
            }
            if (n % 3 == 0)
            {
                return n == 3;
            }
            int d = 5;
            while (d * d <= n)
            {
                if (n % d == 0)
                {
                    return false;
                }
                d = d + 2;
 
                if (n % d == 0)
                {
                    return false;
                }
                d = d + 4;
            }
            return true;
        }
 
