using System;
using System.Diagnostics;
using System.IO;
using Elastic.Elasticsearch.Ephemeral;
using Elastic.Elasticsearch.Managed.ConsoleWriters;

public class EnsureWatcherActionConfigurationSecretsInKeystore
{
    private readonly string _keystoreFile;
    private readonly string _binary;
    private readonly IConsoleWriter _writer;
    private readonly EphemeralClusterConfiguration _cluster;

    public EnsureWatcherActionConfigurationSecretsInKeystore(string keystoreFile, string binary, IConsoleWriter writer, EphemeralClusterConfiguration cluster)
    {
        _keystoreFile = keystoreFile;
        _binary = binary;
        _writer = writer;
        _cluster = cluster;
    }

    public void Run()
    {
        if (!File.Exists(_keystoreFile))
        {
            _writer.WriteDiagnostic($"Keystore file not found at {_keystoreFile}, creating a new one.");
            ExecuteBinary("create");
        }

        AddSecretToKeystore("watcher.slack.webhook.url", "https://hooks.slack.com/services/your/slack/webhook");
        AddSecretToKeystore("watcher.pagerduty.service_api_key", "your-pagerduty-api-key");

        _writer.WriteDiagnostic("Watcher action configuration secrets added to keystore successfully.");
    }

    private void AddSecretToKeystore(string key, string value)
    {
        _writer.WriteDiagnostic($"Adding secret {key} to keystore.");
        ExecuteBinary($"add --stdin {key}", value);
    }

    private void ExecuteBinary(string arguments, string input = null)
    {
        var processStartInfo = new ProcessStartInfo
        {
            FileName = _binary,
            Arguments = arguments,
            RedirectStandardInput = input != null,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            CreateNoWindow = true
        };

        using (var process = Process.Start(processStartInfo))
        {
            if (input != null)
            {
                process.StandardInput.WriteLine(input);
                process.StandardInput.Close();
            }

            string output = process.StandardOutput.ReadToEnd();
            string error = process.StandardError.ReadToEnd();

            process.WaitForExit();

            if (process.ExitCode != 0)
            {
                throw new Exception($"Failed to execute keystore binary: {error}");
            }

            _writer.WriteDiagnostic(output);
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using Simpler;

public class RunScripts : Task
{
    public Input Input { get; set; }

    public override void Execute()
    {
        foreach (var script in Input.Scripts)
        {
            var extension = Path.GetExtension(script.Path).ToLower();
            switch (extension)
            {
                case ".sql":
                    var sqlRunner = new RunSql
                    {
                        ConnectionName = Input.ConnectionName,
                        Script = script.Content
                    };
                    sqlRunner.Execute();
                    break;
                case ".py":
                    var pythonArgs = GetPythonArguments(script.Path, Config.PythonMode);
                    var pyRunner = new RunProcess
                    {
                        FileName = Config.PythonPath,
                        Arguments = pythonArgs,
                        Input = script.Content
                    };
                    pyRunner.Execute();
                    break;
                default:
                    throw new NotSupportedException($"Unsupported script type: {extension}");
            }
        }
    }

    private string GetPythonArguments(string scriptPath, string mode)
    {
        if (mode.Equals("Script", StringComparison.OrdinalIgnoreCase))
            return $"\"{scriptPath}\"";

        var moduleName = Path.GetFileNameWithoutExtension(scriptPath);
        return $"-m \"{moduleName}\"";
    }
}

public class Input
{
    public string ConnectionName { get; set; }
    public IEnumerable<Script> Scripts { get; set; }
}

public class Script
{
    public string Path { get; set; }
    public string Content { get; set; }
}

