public class VersionIntent
{
    private readonly IConversationResponseFactory _responseFactory;
    private readonly ITranslator _translator;
    private readonly HttpContextBase _context;

    public VersionIntent(IConversationResponseFactory responseFactory, ITranslator translator, HttpContextBase context)
    {
        _responseFactory = responseFactory;
        _translator = translator;
        _context = context;
    }

    public ConversationResponse Respond()
    {
        string path = _context.Server.MapPath("~/App_Data/sitecore.version.xml");
        if (!File.Exists(path))
        {
            return _responseFactory.Create(_translator.Text("VersionFileNotFound"));
        }

        try
        {
            XDocument xdoc = XDocument.Load(path);
            var versionElement = xdoc.Element("version");
            if (versionElement == null)
            {
                return _responseFactory.Create(_translator.Text("InvalidVersionFile"));
            }

            string major = versionElement.Element("major")?.Value ?? "0";
            string minor = versionElement.Element("minor")?.Value ?? "0";
            string revision = versionElement.Element("revision")?.Value ?? "0";

            string responseText = _translator.Text("VersionResponse", major, minor, revision);
            return _responseFactory.Create(responseText);
        }
        catch (Exception ex)
        {
            return _responseFactory.Create(_translator.Text("VersionParseError", ex.Message));
        }
    }
}

