    // Dummy evidence class for demonstration purposes.
    public class Evidence
    {
        // Simulated property representing evidence data.
        public string Data { get; set; }
    }

    // This interface defines a contract for evaluating security conditions on assemblies.
    [ComVisible(true)]
    public interface IMembershipCondition
    {
        // Evaluates whether the provided evidence meets the security condition.
        bool Check(Evidence evidence);

        // Produces an identical copy of the current membership condition.
        IMembershipCondition Copy();

        // Returns a human-readable string representation of the membership condition.
        string ToString();

        // Determines whether the specified object is equal to the current condition.
        bool Equals(object obj);
    }

    // A sample implementation of the IMembershipCondition interface.
    [ComVisible(true)]
    public class CustomMembershipCondition : IMembershipCondition
    {
        // For demonstration, a simple criterion based on a keyword.
        public string RequiredKeyword { get; set; }

        public CustomMembershipCondition(string keyword)
        {
            RequiredKeyword = keyword;
        }

        // Check if the provided Evidence contains the required keyword.
        public bool Check(Evidence evidence)
        {
            if (evidence == null || string.IsNullOrEmpty(evidence.Data))
                return false;

            return evidence.Data.Contains(RequiredKeyword, StringComparison.OrdinalIgnoreCase);
        }

        // Creates a copy of the current membership condition.
        public IMembershipCondition Copy()
        {
            return new CustomMembershipCondition(this.RequiredKeyword);
        }

        // Provides a human-readable representation of the membership condition.
        public override string ToString()
        {
            return $"CustomMembershipCondition: Requires keyword '{RequiredKeyword}'";
        }

        // Overrides Equals to compare if two membership conditions are logically equivalent.
        public override bool Equals(object obj)
        {
            if (obj is CustomMembershipCondition other)
            {
                return string.Equals(this.RequiredKeyword, other.RequiredKeyword, StringComparison.OrdinalIgnoreCase);
            }
            return false;
        }

