using System;
using System.Reflection;
using System.Reflection.Emit;
using Mono.Cecil;

namespace ActivationMechanism
{
    public class ActivateMethodEmitter
    {
        private readonly FieldInfo _activatorField;

        public ActivateMethodEmitter(FieldInfo activatorField)
        {
            _activatorField = activatorField ?? throw new ArgumentNullException(nameof(activatorField));
        }

        public MethodInfo CreateActivationMethod(Type purposeType)
        {
            if (!typeof(ActivationPurpose).IsAssignableFrom(purposeType))
            {
                throw new ArgumentException("Purpose type must derive from ActivationPurpose", nameof(purposeType));
            }

            var methodBuilder = NewExplicitMethod();
            ILGenerator il = methodBuilder.GetILGenerator();

            Label activateRequiredLabel = il.DefineLabel();
            Label endLabel = il.DefineLabel();

            // Load 'this' onto the evaluation stack
            il.Emit(OpCodes.Ldarg_0);
            // Get the field representing the activator
            il.Emit(OpCodes.Ldfld, _activatorField);
            // Check if the activator is null
            il.Emit(OpCodes.Brfalse, activateRequiredLabel);

            // Call the activation method on the activator
            il.Emit(OpCodes.Ldarg_1); // Load purpose parameter
            il.Emit(OpCodes.Callvirt, _activatorField.FieldType.GetMethod("Activate"));
            il.Emit(OpCodes.Br, endLabel);

            // Activate method code
            il.MarkLabel(activateRequiredLabel);
            il.Emit(OpCodes.Newobj, typeof(ActivationException).GetConstructor(Type.EmptyTypes));
            il.Emit(OpCodes.Throw);

            il.MarkLabel(endLabel);
            il.Emit(OpCodes.Ret);

            return methodBuilder.CreateMethod();
        }

        private MethodBuilder NewExplicitMethod()
        {
            var dynamicMethod = new DynamicMethod(
                "Activate",
                typeof(void),
                new Type[] { typeof(object) },
                typeof(ActivateMethodEmitter).Module);

            return dynamicMethod;
        }

        public interface IActivatable
        {
            void Activate(ActivationPurpose purpose);
        }

        public interface IActivator
        {
            void Activate(ActivationPurpose purpose);
        }

        public class ActivationPurpose
        {
            // Define fields and methods relevant to ActivationPurpose here
        }
    }
}

