/// <summary>
/// Represents an immutable combinatorial dimension containing a named set of values for test case generation.
/// </summary>
/// <remarks>
/// This class validates input parameters during construction and ensures internal state cannot be modified after initialization.
/// </remarks>
public sealed class CombinatorialDimension
{
    private readonly string _name;
    private readonly ReadOnlyCollection<object> _values;

    /// <summary>
    /// Gets the identifier for this combinatorial dimension.
    /// </summary>
    /// <value>The non-empty dimension name provided during initialization.</value>
    public string Name => _name;

    /// <summary>
    /// Gets the predefined values available for this dimension.
    /// </summary>
    /// <value>Immutable collection of possible values with at least one element.</value>
    public IReadOnlyList<object> Values => _values;

    /// <summary>
    /// Initializes a new combinatorial dimension with validated name and value set.
    /// </summary>
    /// <param name="name">Unique identifier for the dimension (non-empty string)</param>
    /// <param name="values">Collection of possible values (non-null, non-empty)</param>
    /// <exception cref="ArgumentException">Invalid name or empty values collection</exception>
    /// <exception cref="ArgumentNullException">Null values parameter</exception>
    public CombinatorialDimension(string name, IEnumerable<object> values)
    {
        if (string.IsNullOrWhiteSpace(name))
        {
            throw new ArgumentException(
                "Dimension name must contain non-whitespace characters",
                nameof(name)
            );
        }

        if (values == null)
        {
            throw new ArgumentNullException(
                nameof(values),
                "Dimension values collection cannot be null"
            );
        }

        var materializedValues = values.ToArray();
        if (materializedValues.Length == 0)
        {
            throw new ArgumentException(
                "Dimension must contain at least one value",
                nameof(values)
            );
        }

        _name = name.Trim();
        _values = new ReadOnlyCollection<object>(materializedValues);
    }

