    /// <summary>
    /// Provides extended functionality for IPublishedContent objects by allowing direct
    /// access to their underlying raw property data values without invoking any high-level converters.
    /// </summary>
    public static class PublishedContentExtensions
    {
        /// <summary>
        /// Retrieves the raw stored value of a property identified by its alias.
        /// This method bypasses higher-level converters to return the actual underlying data.
        /// </summary>
        /// <param name="content">The content object from which to retrieve the property data.</param>
        /// <param name="alias">The alias of the property.</param>
        /// <returns>The raw stored value of the property, or null if the property is missing or has no value.</returns>
        public static object GetDataValue(this IPublishedContent content, string alias)
        {
            if (content == null)
                throw new ArgumentNullException(nameof(content), "IPublishedContent object cannot be null.");

            if (string.IsNullOrWhiteSpace(alias))
                throw new ArgumentNullException(nameof(alias), "Property alias cannot be null or empty.");

            // Attempt to locate the property by its alias, ignoring case differences.
            var property = content.Properties.FirstOrDefault(p =>
                p.Alias.Equals(alias, StringComparison.InvariantCultureIgnoreCase));

            // Check if the property exists and holds a valid value.
            if (property == null || property.Value == null)
                return null;

            // Return the underlying raw data value.
            return property.Value;
        }

