using System;
using System.Collections.Generic;
using System.Reflection;
using UnityEngine;

public class UnitTestRunner : MonoBehaviour
{
    private Stopwatch timer;

    [RuntimeInitializeOnLoadMethod]
    private static void Start()
    {
        var runner = new GameObject("UnitTestRunner").AddComponent<UnitTestRunner>();
        runner.RunUnitTests();
    }

    private void RunUnitTests()
    {
        timer = new Stopwatch();
        timer.Start();

        List<Type> testClasses = GetTestClasses();
        int testCount = 0;

        foreach (Type testClass in testClasses)
        {
            testCount += RunTestMethods(testClass);
        }

        timer.Stop();
        Debug.Log($"Ran {testCount} tests in {timer.ElapsedMilliseconds} ms.");
    }

    private int RunTestMethods(Type testClass)
    {
        int testCount = 0;
        object instance = Activator.CreateInstance(testClass);
        MethodInfo[] methods = testClass.GetMethods(BindingFlags.Public | BindingFlags.Instance);

        foreach (MethodInfo method in methods)
        {
            if (method.GetCustomAttribute<TestMethodAttribute>() != null)
            {
                testCount++;
                try
                {
                    method.Invoke(instance, null);
                    Debug.Log($"Test {method.Name} passed.");
                }
                catch (Exception ex)
                {
                    Debug.LogError($"Test {method.Name} failed: {ex.InnerException?.Message ?? ex.Message}");
                }
            }
        }

        return testCount;
    }

    private List<Type> GetTestClasses()
    {
        List<Type> testClasses = new List<Type>();
        Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();

        foreach (Assembly assembly in assemblies)
        {
            foreach (Type type in assembly.GetTypes())
            {
                if (type.GetCustomAttribute<TestClassAttribute>() != null)
                {
                    testClasses.Add(type);
                }
            }
        }

        return testClasses;
    }
}

[AttributeUsage(AttributeTargets.Class)]
public class TestClassAttribute : Attribute { }

[AttributeUsage(AttributeTargets.Method)]
public class TestMethodAttribute : Attribute { }

public class UnitTestException : Exception
{
    public UnitTestException(string message) : base(message) { }
}
