using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace Manager
{
    class Writer
    {
        static void Main(string[] args)
        {
            var ARRS = new List<List<char>> {
                Enumerable.Range('a', 'z' - 'a' + 1).Select(i => (char)i).ToList(),
                Enumerable.Range('A', 'Z' - 'A' + 1).Select(i => (char)i).ToList(),
                Enumerable.Range('0', '9' - '0' + 1).Select(i => (char)i).ToList(),
                "!\"#$%&'()*+,-./:;<=>?@[]^_{|}~".ToCharArray().ToList()
            };
            var ALL = ARRS.SelectMany(x => x).ToList();
            var size = 8;
            var num = 3;
            if (size < ARRS.Count)
                throw new ArgumentException("Desired size too small");
            var result = new List<string>();
            for (int i = 0; i < num; i++)
            {
                var arr = ARRS.Select(x => x.OrderBy(y => Guid.NewGuid()).First()).ToList();
                for (int j = 0; j < size - ARRS.Count; j++)
                    arr.Add(ALL.OrderBy(y => Guid.NewGuid()).First());
                result.Add(string.Join("", arr.OrderBy(y => Guid.NewGuid())));
            }
            Console.WriteLine(string.Join("\n", result));
        }
    }
}

public class Bitmap
{
    public struct Color
    {
        public byte Red { get; set; }
        public byte Blue { get; set; }
        public byte Green { get; set; }
    }
    Color[,] _imagemap;
    public int Width { get { return _imagemap.GetLength(0); } }
    public int Height { get { return _imagemap.GetLength(1); } }
    public Bitmap(int width, int height)
    {
        _imagemap = new Color[width, height];
    }
    public void Fill(Color color)
    {
        for (int y = 0; y < Height; y++)
            for (int x = 0; x < Width; x++)
            {
                _imagemap[x, y] = color;
            }
    }
    public Color GetPixel(int x, int y)
    {
        return _imagemap[x, y];
    }
    public void SetPixel(int x, int y, Color color)
    {
        _imagemap[x, y] = color;
    }
}

