public class GameLoop
{
    private readonly IValueProvider _randomNumberProvider;
    private readonly IGameCommand _guessCommand;

    public GameLoop(IValueProvider randomNumberProvider, IGameCommand guessCommand)
    {
        _randomNumberProvider = randomNumberProvider;
        _guessCommand = guessCommand;
    }

    public void Start()
    {
        int randomNumber = _randomNumberProvider.Provide();
        bool guessedCorrectly = false;

        while (!guessedCorrectly)
        {
            Console.Write("Guess a number between 0 and 99: ");
            int guess = int.Parse(Console.ReadLine());

            guessedCorrectly = _guessCommand.Execute(guess, randomNumber);
        }
    }
}

public interface IValueProvider
{
    int Provide();
}

public class StaticRandomNumberValueProvider : IValueProvider
{
    private static int _number;

    static StaticRandomNumberValueProvider()
    {
        Random random = new Random();
        _number = random.Next(0, 100);
    }

    public int Provide()
    {
        return _number;
    }
}

