    {
        _tooLowCommand = tooLowCommand;
        _tooHighCommand = tooHighCommand;
        _youWinCommand = youWinCommand;
    }

    public bool Execute(int guess, int target)
    {
        if (guess < target)
        {
            _tooLowCommand.Execute(guess, target);
            return false;
        }
        else if (guess > target)
        {
            _tooHighCommand.Execute(guess, target);
            return false;
        }
        else
        {
            _youWinCommand.Execute(guess, target);
            return true;
        }
    }
}

public class TooLow : IGameCommand
{
    public bool Execute(int guess, int target)
    {
        Console.WriteLine("Too low!");
        return false;
    }
}

public class TooHigh : IGameCommand
{
    public bool Execute(int guess, int target)
    {
        Console.WriteLine("Too high!");
        return false;
    }
}

