namespace CefSharp
{
    [StructLayout(LayoutKind.Sequential)]
    public struct cef_settings_t
    {
        private static readonly int _sizeof;

        static cef_settings_t()
        {
            if (RuntimeInformation.IsOSPlatform(OSPlatform.Windows))
            {
                _sizeof = Marshal.SizeOf(typeof(cef_settings_windows_t));
            }
            else
            {
                _sizeof = Marshal.SizeOf(typeof(cef_settings_non_windows_t));
            }
        }

        private IntPtr size;
        private IntPtr no_sandbox;
        private IntPtr multi_threaded_message_loop;
        private IntPtr windowless_rendering_enabled;
        private IntPtr external_message_pump;
        private IntPtr command_line_args_disabled;
        private IntPtr cache_path;
        private IntPtr root_cache_path;
        private IntPtr user_data_path;
        private IntPtr persist_session_cookies;
        private IntPtr persist_user_preferences;
        private IntPtr ignore_certificate_errors;
        private IntPtr javascript_disabled;
        private IntPtr javascript_open_windows_disallowed;
        private IntPtr javascript_close_windows_disallowed;
        private IntPtr javascript_access_clipboard_disallowed;
        private IntPtr dom_paste_disabled;
        private IntPtr caret_browsing_disabled;
        private IntPtr context_menu_disabled;
        private IntPtr dev_tools_disabled;
        private IntPtr remote_debugging_port;
        private IntPtr log_severity;
        private IntPtr log_file;
        private IntPtr javascript_can_access_clipboard;
        private IntPtr default_encoding;
        private IntPtr locale;
        private IntPtr accept_language_list;

        public cef_settings_t(bool isWindows)
        {
            if (isWindows)
            {
                var winSettings = new cef_settings_windows_t();
                this = Unsafe.As<cef_settings_windows_t, cef_settings_t>(ref winSettings);
            }
            else
            {
                var nonWinSettings = new cef_settings_non_windows_t();
                this = Unsafe.As<cef_settings_non_windows_t, cef_settings_t>(ref nonWinSettings);
            }
            size = (IntPtr)_sizeof;
        }

        public static IntPtr Alloc()
        {
            IntPtr ptr = Marshal.AllocHGlobal(_sizeof);
            Marshal.WriteIntPtr(ptr, (IntPtr)_sizeof);
            return ptr;
        }

        public static void Free(IntPtr ptr)
        {
            Marshal.FreeHGlobal(ptr);
        }

