public class DatabaseObjectScripter
{
    private readonly IEnumerable<IDatabaseObjectScriptEngine> _engines;

    public DatabaseObjectScripter(IEnumerable<IDatabaseObjectScriptEngine> engines)
    {
        _engines = engines;
    }

    public DatabaseObjectScripter() : this(GetDefaultEngines()) { }

    public IEnumerable<SqlScriptObject> Script(Server server, string databaseName)
    {
        var scripts = new List<SqlScriptObject>();

        foreach (var engine in _engines)
        {
            scripts.AddRange(engine.Script(server, databaseName));
        }

        return scripts;
    }

    private static IEnumerable<IDatabaseObjectScriptEngine> GetDefaultEngines()
    {
        return new IDatabaseObjectScriptEngine[]
        {
                // Add default engines here, for example:
                new SqlScriptEngine<Assembly>(SqlObjectConverter.ConvertAssembly, (db) => db.Assemblies.Cast<Assembly>()),
                new SqlScriptEngine<Role>(SqlObjectConverter.ConvertRole, (db) => db.Roles.Cast<Role>()),
                new SqlScriptEngine<Schema>(SqlObjectConverter.ConvertSchema, (db) => db.Schemas.Cast<Schema>()),
        };
    }
}

public interface IDatabaseObjectScriptEngine
{
    IEnumerable<SqlScriptObject> Script(Server server, string databaseName);
}

public class SqlScriptObject
{
    public string Script { get; set; }
    public string ObjectName { get; set; }
    public string ObjectType { get; set; }
}

public class SqlScriptEngine<T> : IDatabaseObjectScriptEngine
{
    private readonly Func<T, SqlScriptObject> _converter;
    private readonly Func<Database, IEnumerable<T>> _objectSelector;

    public SqlScriptEngine(Func<T, SqlScriptObject> converter, Func<Database, IEnumerable<T>> objectSelector)
    {
        _converter = converter;
        _objectSelector = objectSelector;
    }
    public IEnumerable<SqlScriptObject> Script(Server server, string databaseName)
    {
        var database = server.Databases[databaseName];
        if (database == null) yield break;

        foreach (var obj in _objectSelector(database))
        {
            yield return _converter(obj);
        }
    }
}
