using AppStudio.DataProviders.Exceptions;
using AppStudio.DataProviders.Json.Parser;

namespace AppStudio.DataProviders
{
    public class JsonDataProvider<T> where T : JsonSchema
    {
        public async Task<ObservableCollection<T>> LoadDataAsync(JsonDataConfig config)
        {
            return await LoadDataAsync(config, new JsonParser<T>());
        }

        public async Task<ObservableCollection<T>> LoadDataAsync(JsonDataConfig config, IParser<T> parser)
        {
            Assertions(config, parser);

            using (var httpClient = new HttpClient())
            {
                try
                {
                    var jsonString = await httpClient.GetStringAsync(config.Url);
                    var result = parser.Parse(jsonString, config.ElementsPath);
                    return new ObservableCollection<T>(result);
                }
                catch (Exception ex)
                {
                    throw new RequestFailedException("Failed to load JSON data.", ex);
                }
            }
        }

        private void Assertions(JsonDataConfig config, IParser<T> parser)
        {
            if (config == null)
            {
                throw new ArgumentNullException(nameof(config), "Configuration cannot be null.");
            }

            if (string.IsNullOrEmpty(config.Url))
            {
                throw new ArgumentException("URL in configuration cannot be null or empty.", nameof(config.Url));
            }

            if (string.IsNullOrEmpty(config.ElementsPath))
            {
                throw new ArgumentException("ElementsPath in configuration cannot be null or empty.", nameof(config.ElementsPath));
            }

            if (parser == null)
            {
                throw new ArgumentNullException(nameof(parser), "Parser cannot be null.");
            }
        }
    }

    public class JsonSchema
    {
        // Base class for JSON schema
    }

    public class JsonDataConfig
    {
        public string Url { get; set; }
        public string ElementsPath { get; set; }
    }

    public interface IParser<T>
    {
        IEnumerable<T> Parse(string json, string elementsPath);
    }

    public class JsonParser<T> : IParser<T> where T : JsonSchema
    {
        public IEnumerable<T> Parse(string json, string elementsPath)
        {
            // Implement JSON parsing logic here
            return new List<T>();
        }
    }
}

