        ClassQuestion originalQuestion = dbContext.ClassQuestions.First();

        CodeQuestionDuplicator duplicator = GetCodeQuestionDuplicator(dbContext);

        ClassQuestion duplicateQuestion = await duplicator.DuplicateQuestionAsync(originalQuestion);

