            {
                SQLiteConnection.CreateFile(dbName);
                Console.WriteLine($"Database created successfully: {dbName}");
            }
            else
            {
                Console.WriteLine("Database already exists.");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error creating database: {ex.Message}");
        }
    }

    public void ExecuteSql(string sqlStr)
    {
        using (var connection = new SQLiteConnection(strConStr))
        {
            connection.Open();
            using (var command = new SQLiteCommand(sqlStr, connection))
            {
                try
                {
                    command.ExecuteNonQuery();
                    Console.WriteLine("SQL command executed successfully.");
                }
                catch (SQLiteException sqlex)
                {
                    Console.WriteLine($"SQL error: {sqlex.Message}");
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error executing command: {ex.Message}");
                }
            }
        }
    }

    // Example method for creating a table
    public void CreateTable(string tableName, string columns)
    {
        string sqlCreateTable = $"CREATE TABLE IF NOT EXISTS {tableName} ({columns});";
        ExecuteSql(sqlCreateTable);
    }

    // Example method for inserting data
    public void InsertData(string tableName, string columnNames, string values)
    {
        string sqlInsert = $"INSERT INTO {tableName} ({columnNames}) VALUES ({values});";
        ExecuteSql(sqlInsert);
    }

