namespace GameOrders
{
    // InterceptOrder inherits from MoveOrder to handle movement logic
    public class InterceptOrder : MoveOrder
    {
        private Ship targetShip;
        private bool allowTargetSwitch;
        private Vector2 interceptPoint;
        private int sector;
        private bool orderComplete = false;

        public InterceptOrder(Ship ship, Ship target, bool enableTargetSwitch)
            : base(ship)
        {
            targetShip = target;
            allowTargetSwitch = enableTargetSwitch;
            sector = ship.CurrentSector;
            UpdateInterceptPoint();
            // Initialize visual style for intercept order
            Renderer.SetLineStyle(ship.Id, Color.Yellow, 2);
        }

        public override void Update(double deltaTime)
        {
            if (orderComplete)
                return;

            // Check sector consistency first
            if (Ship.CurrentSector != sector)
            {
                orderComplete = true;
                return;
            }

            if (IsTargetValid(targetShip))
            {
                UpdateInterceptPoint();
            }
            else if (allowTargetSwitch)
            {
                Ship newTarget = FindAlternativeTarget();
                if (newTarget != null)
                {
                    targetShip = newTarget;
                    UpdateInterceptPoint();
                }
                else
                {
                    orderComplete = true;
                }
            }
            else
            {
                orderComplete = true;
            }

            // Execute standard movement update
            base.Update(deltaTime);

            // Special handling for specific ship types (e.g., Docking procedures)
            if (Ship.Type == ShipType.Frigate && orderComplete)
            {
                InitiateDocking();
            }
        }

        // Render the intercept line if both entities are in the same sector
        public override void Draw()
        {
            if (orderComplete)
                return;

            if (Ship.CurrentSector == sector && targetShip.CurrentSector == sector)
            {
                Vector2 shipCenter = Ship.GetCenterPosition();
                Vector2 targetCenter = targetShip.GetCenterPosition();
                Renderer.DrawLine(shipCenter, targetCenter, Color.Yellow, 2);
            }
        }

