namespace TemplateEngine
{
    public enum TagMode
    {
        StartTagAndEndTag,
        SelfClosing,
        StartTagOnly,
        EndTagOnly
    }

    // Base class for intermediate nodes.
    public abstract class IntermediateNode
    {
        public List<IntermediateNode> Children { get; } = new List<IntermediateNode>();

        public virtual void Accept(IVisitor visitor)
        {
            visitor.Visit(this);
            foreach (var child in Children)
            {
                child.Accept(visitor);
            }
        }

        public abstract string FormatNode();
    }

    // Visitor interface for the visitor pattern.
    public interface IVisitor
    {
        void Visit(IntermediateNode node);
        void Visit(TagHelperIntermediateNode node);
    }

    // Child node representing the body content.
    public class BodyIntermediateNode : IntermediateNode
    {
        public string Content { get; set; }
        public override string FormatNode() => $"Body: {Content}";
    }

    // Child node representing a tag helper property.
    public class PropertyIntermediateNode : IntermediateNode
    {
        public string PropertyName { get; set; }
        public string PropertyValue { get; set; }
        public override string FormatNode() => $"Property: {PropertyName} = {PropertyValue}";
    }

    // Child node representing an HTML attribute.
    public class HtmlAttributeIntermediateNode : IntermediateNode
    {
        public string AttributeName { get; set; }
        public string AttributeValue { get; set; }
        public override string FormatNode() => $"HTML Attribute: {AttributeName} = {AttributeValue}";
    }

    // Descriptor for a tag helper that provides additional metadata.
    public class TagHelperDescriptor
    {
        public string Name { get; set; }
    }

    // The main node that encapsulates tag helper information.
    public class TagHelperIntermediateNode : IntermediateNode
    {
        public string TagName { get; set; }
        public TagMode Mode { get; set; }
        public List<TagHelperDescriptor> Descriptors { get; set; } = new List<TagHelperDescriptor>();

        // Filtered child nodes for the body.
        public BodyIntermediateNode BodyNode => Children.OfType<BodyIntermediateNode>().FirstOrDefault();

        // Filtered child nodes for properties.
        public IEnumerable<PropertyIntermediateNode> PropertyNodes => Children.OfType<PropertyIntermediateNode>();

        // Filtered child nodes for HTML attributes.

