    [Serializable]
    public class SocialMediaConfig
    {
        private readonly StoreSettings _parentSettings;

        public SocialMediaConfig(StoreSettings parentSettings)
        {
            if (parentSettings == null)
                throw new ArgumentNullException(nameof(parentSettings));
            _parentSettings = parentSettings;
        }

        public bool IntegrationEnabled
        {
            get { return _parentSettings.GetBooleanValue("SocialMedia.IntegrationEnabled", false); }
            set { _parentSettings.SaveValue("SocialMedia.IntegrationEnabled", value.ToString()); }
        }

        public string AppId
        {
            get { return _parentSettings.GetStringValue("SocialMedia.AppId"); }
            set { _parentSettings.SaveValue("SocialMedia.AppId", value); }
        }

        public string AdminIds
        {
            get { return _parentSettings.GetStringValue("SocialMedia.AdminIds"); }
            set { _parentSettings.SaveValue("SocialMedia.AdminIds", value); }
        }
    }

    [Serializable]
    public class StoreSettings
    {
        private Dictionary<string, string> _settings;

        public StoreSettings()
        {
            _settings = new Dictionary<string, string>();
        }

        public bool GetBooleanValue(string key, bool defaultValue)
        {
            if (_settings.TryGetValue(key, out string value))
            {
                if (bool.TryParse(value, out bool result))
                    return result;
            }
            return defaultValue;
        }

        public string GetStringValue(string key)
        {
            if (_settings.TryGetValue(key, out string value))
                return value;
            return string.Empty;
        }

        public void SaveValue(string key, string value)
        {
            if (_settings.ContainsKey(key))
                _settings[key] = value;
            else
                _settings.Add(key, value);
        }
    }

