public class PhraseReversal
{
    public static void Main()
    {
        string str = "rosetta code phrase reversal";
        char delim ='';
 
        /* Original String */
        Console.WriteLine("Original:       \"{0}\"", str);
 
        /* Reversed string */
        string scopy = str;
        scopy = ReverseString(scopy);
        Console.WriteLine("Reversed:       \"{0}\"", scopy);
 
        /* Reversed words in string */
        scopy = str;
        scopy = ReverseWordsInOrder(scopy, delim);
        Console.WriteLine("Reversed words: \"{0}\"", scopy);
 
        /* Reversed order of words in string */
        scopy = str;
        scopy = ReverseOrderOfWords(scopy, delim);
        Console.WriteLine("Reversed order: \"{0}\"", scopy);
    }
 
    public static string ReverseString(string s)
    {
        return s.Length == 0? s : new string(s.Reverse().ToArray());
    }
 
    public static string ReverseWordsInOrder(string s, char delim)
    {
        if (s.Length == 0) return s;
 
        int i, j;
        for (i = 0; i < s.Length - 1; ++i)
        {
            for (j = 0; s[i + j]!= 0 && s[i + j]!= delim; ++j)
                ;
            s = ReverseSection(s, i, j - 1);
            s = s.Substring(j);
        }
        return s;
    }
 
    public static string ReverseSection(string s, int start, int length)
    {
        if (length == 0) return s;
 
        int i; char temp;
        for (i = 0; i < length / 2 + 1; ++i)
        {
            temp = s[i];
            s[i] = s[length - i];
            s[length - i] = temp;
        }
        return s;
    }
 
    public static string ReverseOrderOfWords(string s, char delim)
    {
        s = ReverseString(s);
        s = ReverseWordsInOrder(s, delim);
        return s;
    }
}

