using System;
using System.Collections.Generic;
using System.Text;
using System.Xml;
using System.Xml.Linq;

public interface IXmlOriginalDocumentService
{
    bool HasChanged { get; }
    IEnumerable<XElement> SelectNodes(string xpath);
}

public class XmlTransformableDocument : IXmlOriginalDocumentService
{
    private readonly XDocument xmlOriginal;
    private XDocument xmlCurrent;

    public XmlTransformableDocument(string xmlFilePath)
    {
        xmlOriginal = XDocument.Load(xmlFilePath);
        xmlCurrent = xmlOriginal.Clone();
    }

    public bool HasChanged => !XmlEquals(xmlOriginal, xmlCurrent);

    public void Transform(Action<XDocument> transformation)
    {
        transformation(xmlCurrent);
    }

    public IEnumerable<XElement> SelectNodes(string xpath)
    {
        var namespaces = GetNamespaces(xmlOriginal);
        var navigator = xmlOriginal.CreateNavigator();
        var nodes = navigator.Select(xpath, namespaces);
        while (nodes.MoveNext())
        {
            yield return XElement.Parse(nodes.Current.OuterXml);
        }
    }

    public void ResetToOriginal()
    {
        xmlCurrent = xmlOriginal.Clone();
    }

    private bool XmlEquals(XDocument doc1, XDocument doc2)
    {
        return XNode.DeepEquals(doc1.Root, doc2.Root);
    }

    private IDictionary<string, string> GetNamespaces(XDocument doc)
    {
        var namespaces = new Dictionary<string, string>();
        foreach (var element in doc.Descendants())
        {
            if (element.Name.NamespaceName != "")
            {
                namespaces[element.Name.NamespaceName] = element.Name.NamespaceName;
            }
        }
        return namespaces;
    }

    public string GetXmlString()
    {
        return xmlCurrent.ToString();
    }
}

// Example Usage of XmlTransformableDocument
class Validator
{
    static void Main()
    {
        var xmlDoc = new XmlTransformableDocument("example.xml");

        // Check if changes have been made
        Console.WriteLine($"Has Changes: {xmlDoc.HasChanged}");

        // Example transformation
        xmlDoc.Transform(doc =>
        {
            // Perform some transformation logic here
            var newElement = new XElement("NewElement", "This is a new element");
            doc.Root.Add(newElement);
        });

        Console.WriteLine($"Has Changes: {xmlDoc.HasChanged}");

        // Selecting nodes
        foreach (var node in xmlDoc.SelectNodes("//*"))
        {
            Console.WriteLine(node);
        }

        // Reset to original
        xmlDoc.ResetToOriginal();

