[NoReflectionBaking]
public class BindStatement : IDisposable
{
    private readonly List<IDisposable> _disposables = new List<IDisposable>();
    private IBindingFinalizer _bindingFinalizer;

    public bool HasFinalizer => _bindingFinalizer != null;
    public BindingInheritanceMethods BindingInheritanceMethod => _bindingFinalizer?.BindingInheritanceMethod ?? BindingInheritanceMethods.None;

    public void SetFinalizer(IBindingFinalizer bindingFinalizer)
    {
        Assert.IsNull(_bindingFinalizer, "Finalizer already set.");
        _bindingFinalizer = bindingFinalizer;
    }

    public void AssertHasFinalizer()
    {
        if (!HasFinalizer)
        {
            throw new ZenjectException("Binding statement has no finalizer.");
        }
    }

    public void AddDisposable(IDisposable disposable)
    {
        _disposables.Add(disposable);
    }

    public BindInfo SpawnBindInfo()
    {
        var bindInfo = new BindInfo();
        bindInfo.BindingInheritanceMethod = BindingInheritanceMethod;
        return bindInfo;
    }

    public void FinalizeBinding(DiContainer container)
    {
        AssertHasFinalizer();
        _bindingFinalizer.FinalizeBinding(container);
    }

    public void Reset()
    {
        _bindingFinalizer = null;
        _disposables.Clear();
    }

    public void Dispose()
    {
        foreach (var disposable in _disposables)
        {
            disposable.Dispose();
        }
        _disposables.Clear();
    }
}

