using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace Handler
{
    class Game
    {
        static void Main(string[] args)
        {
            Console.WriteLine("merge2: ");
            merge2(
                Console.Out,
                new StringReader("3 14 15"),
                new StringReader("2 17 18"));
            Console.WriteLine();

            Console.WriteLine("mergeN: ");
            mergeN(
                Console.Out,
                new StringReader("3 14 15"),
                new StringReader("2 17 18"),
                new StringReader(""),
                new StringReader("2 3 5 7"));
            Console.WriteLine();
        }

        static void merge2(TextWriter m, TextReader s1, TextReader s2)
        {
            int v1, v2;
            bool d1, d2;
            d1 = int.TryParse(s1.ReadLine(), out v1);
            d2 = int.TryParse(s2.ReadLine(), out v2);
            int v;
            while (d1 || d2)
            {
                if (!d2 || d1 && v1 < v2)
                {
                    v = v1;
                    d1 = int.TryParse(s1.ReadLine(), out v1);
                }
                else
                {
                    v = v2;
                    d2 = int.TryParse(s2.ReadLine(), out v2);
                }
                m.Write(v + " ");
            }
        }

        class sv : IComparable<sv>
        {
            public TextReader s;
            public int v;

            public int CompareTo(sv other)
            {
                return v.CompareTo(other.v);
            }
        }

        static void mergeN(TextWriter m, params TextReader[] s)
        {
            var h = new List<sv>();
            foreach (var r in s)
            {
                int v;
                if (int.TryParse(r.ReadLine(), out v))
                {
                    h.Add(new sv { s = r, v = v });
                }
            }
            h.Sort();
            while (h.Count > 0)
            {
                var p = h[0];
                m.Write(p.v + " ");
                h.RemoveAt(0);
                int v;
                if (int.TryParse(p.s.ReadLine(), out v))
                {
                    h.Add(new sv { s = p.s, v = v });
                    h.Sort();
                }
            }
        }
    }
}

