using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace Checker
{
    class Game
    {
        static void Main(string[] args)
        {
            var s = "The quick brown fox jumps over the lazy dog";
            Console.WriteLine(string.Format("{0:X8}", crc(s)));
        }

        static uint crc(string s)
        {
            var reversed_polynomial = 0xEDB88320uL;
            var table = generate_crc_lookup_table(reversed_polynomial);
            var checksum = 0xFFFFFFFFuL;
            foreach (var c in s)
            {
                checksum = table[(checksum ^ c) & 0xFFu] ^ (checksum >> 8);
            }
            return (uint)(checksum & 0xFFFFFFFFuL);
        }

        static uint[] generate_crc_lookup_table(uint reversed_polynomial)
        {
            var table = new uint[256];
            for (var n = 0; n < 256; n++)
            {
                var checksum = (uint)n;
                for (var i = 0; i < 8; i++)
                {
                    checksum = (checksum >> 1) ^ ((checksum & 0x1u)!= 0? reversed_polynomial : 0);
                }
                table[n] = checksum;
            }
            return table;
        }
    }
}

 
using System;
using System.Collections.Generic;
using System.Text;
using System.Text.RegularExpressions;
 
namespace InfixToPostfix
{
    class Processor
    {
        const string OPS = "-+/*^";
 
        static string InfixToPostfix(string infix)
        {
            var sb = new StringBuilder();
            var s = new Stack<int>();
            var rx = new Regex(@"\s");
            foreach (var token in rx.Split(infix))
            {
                if (token.Length == 0) continue;
                var c = token[0];
                var idx = OPS.IndexOf(c);
 
                // check for operator
                if (idx!= -1)
                {
                    if (s.Count == 0)
                    {
                        s.Push(idx);
                    }
                    else
                    {
                        while (s.Count!= 0)
                        {
                            var prec2 = s.Peek() / 2;
                            var prec1 = idx / 2;
                            if (prec2 > prec1 || (prec2 == prec1 && c!= '^'))
                            {
                                sb.Append(OPS[s.Pop()]).Append(' ');
                            }
                            else break;
                        }
                        s.Push(idx);
                    }
                }
                else if (c == '(')
                {
                    s.Push(-2);  // -2 stands for '('
                }
                else if (c == ')')
                {
                    // until '(' on stack, pop operators.
                    while (s.Peek()!= -2) sb.Append(OPS[s.Pop()]).Append(' ');
                    s.Pop();
                }
                else
                {
                    sb.Append(token).Append(' ');
                }
            }
            while (s.Count!= 0) sb.Append(OPS[s.Pop()]).Append(' ');
            return sb.ToString();
        }
 
        static void Main(string[] args)
        {
            var es = new List<string>
            {
                "3 + 4 * 2 / ( 1 - 5 ) ^ 2 ^ 3",
                "( ( 1 + 2 ) ^ ( 3 + 4 ) ) ^ ( 5 + 6 )"
            };
            foreach (var e in es)
            {
                Console.WriteLine("Infix : " + e);
                Console.WriteLine("Postfix : " + InfixToPostfix(e) + "\n");
            }
        }
    }
}

