namespace OpenDental.Integration {
    public static class VixWinBridge {
        public static bool SendData(Program ProgramCur, Patient pat) {
            if (pat == null || GetPropVal("ppImagePath") == "") {
                MessageBox.Show("Required patient data or configuration missing");
                return false;
            }

            long patNum;
            string identifierType = GetPropVal("PatientIdentifier");
            if (identifierType == "ChartNumber") {
                if (!long.TryParse(pat.ChartNumber, out patNum)) {
                    MessageBox.Show("Invalid chart number format");
                    return false;
                }
            }
            else {
                patNum = pat.PatNum;
            }

            string cleanFName = pat.FName.Replace(" ", "").Trim();
            if (cleanFName.Length > 20) cleanFName = cleanFName.Substring(0, 20);
            string cleanLName = pat.LName.Replace(" ", "").Trim();
            if (cleanLName.Length > 20) cleanLName = cleanLName.Substring(0, 20);

            string basePath = GetPropVal("ppImagePath");
            string subDir = (patNum % 100).ToString("00");
            string fullPath = Path.Combine(basePath, subDir);

            try {
                if (!Directory.Exists(fullPath)) {
                    Directory.CreateDirectory(fullPath);
                }
            }
            catch (Exception ex) {
                MessageBox.Show($"Directory creation error: {ex.Message}");
                return false;
            }

            string vixPath = GetProgramPath(ProgramCur.ProgNum);
            if (!File.Exists(vixPath)) {
                MessageBox.Show("VixWin executable not found");
                return false;
            }

            string args = $"-patid {patNum} -fname \"{cleanFName}\" " +
                          $"-lname \"{cleanLName}\" -imgpath \"{fullPath}\"";

            try {
                Process.Start(new ProcessStartInfo {
                    FileName = vixPath,
                    Arguments = args,
                    UseShellExecute = false
                });
            }
            catch (Exception ex) {
                MessageBox.Show($"Process launch failed: {ex.Message}");
                return false;
            }

            return true;
        }

