using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Xml.Linq;

public abstract class DivMathWithOuterBase : DivMath
{
    protected EquationContainer outerEquation;
    protected EquationContainer insideEquation;
    protected string divMathSign = "/";
    protected double LeftGap = 5.0;
    protected double ExtraHeight = 10.0;

    public double Width { get; protected set; }
    public double Height { get; protected set; }

    public DivMathWithOuterBase(EquationContainer parent) : base(parent)
    {
        outerEquation = new RowContainer(parent);
        outerEquation.Alignment = HorizontalAlignment.Right;
    }

    public override XElement Serialize()
    {
        XElement element = new XElement("DivMathWithOuter");
        element.Add(new XElement("OuterEquation", outerEquation.Serialize()));
        element.Add(new XElement("InsideEquation", insideEquation.Serialize()));
        return element;
    }

    public override void DeSerialize(XElement xElement)
    {
        var outerElement = xElement.Element("OuterEquation");
        if (outerElement != null)
        {
            outerEquation.DeSerialize(outerElement);
        }

        var insideElement = xElement.Element("InsideEquation");
        if (insideElement != null)
        {
            insideEquation.DeSerialize(insideElement);
        }
    }

    public override void CalculateSize()
    {
        CalculateWidth();
        CalculateHeight();
    }

    protected virtual void CalculateWidth()
    {
        double outerWidth = outerEquation?.Width ?? 0;
        double insideWidth = insideEquation?.Width ?? 0;
        Width = Math.Max(outerWidth, insideWidth) + LeftGap * 2;
    }

    protected virtual void CalculateHeight()
    {
        double outerHeight = outerEquation?.Height ?? 0;
        double insideHeight = insideEquation?.Height ?? 0;
        Height = outerHeight + insideHeight + ExtraHeight;
    }

    public override void ArrangeComponents()
    {
        if (outerEquation != null)
        {
            outerEquation.Top = 0;
            outerEquation.Left = Width - outerEquation.Width - LeftGap;
        }

        if (insideEquation != null)
        {
            insideEquation.Top = outerEquation?.Height + ExtraHeight / 2 ?? 0;
            insideEquation.Left = (Width - insideEquation.Width) / 2;
        }
    }
}

