using System;
using System.Collections.Generic;

public class RibbonQuickAccessToolbarItemCollection : RibbonItemCollection
{
    private readonly RibbonQuickAccessToolbar _ownerToolbar;

    public RibbonQuickAccessToolbarItemCollection(RibbonQuickAccessToolbar ownerToolbar)
    {
        _ownerToolbar = ownerToolbar ?? throw new ArgumentNullException(nameof(ownerToolbar));
    }

    public override void Add(RibbonItem item)
    {
        if (item == null) throw new ArgumentNullException(nameof(item));
        PrepareItem(item);
        base.Add(item);
    }

    public override void AddRange(IEnumerable<RibbonItem> items)
    {
        if (items == null) throw new ArgumentNullException(nameof(items));

        var itemsList = new List<RibbonItem>(items);
        foreach (var item in itemsList)
        {
            PrepareItem(item);
        }
        base.AddRange(itemsList);
    }

    public override void Insert(int index, RibbonItem item)
    {
        if (item == null) throw new ArgumentNullException(nameof(item));
        PrepareItem(item);
        base.Insert(index, item);
    }

    private void PrepareItem(RibbonItem item)
    {
        item.SizeMode = RibbonElementSizeMode.Compact;
        item.SetOwner(_ownerToolbar);
    }

    protected override void SetItem(int index, RibbonItem item)
    {
        PrepareItem(item);
        base.SetItem(index, item);
    }

    protected override void InsertItem(int index, RibbonItem item)
    {
        PrepareItem(item);
        base.InsertItem(index, item);
    }

    protected override void RemoveItem(int index)
    {
        var item = this[index];
        item.SetOwner(null);
        base.RemoveItem(index);
    }

    protected override void ClearItems()
    {
        foreach (var item in this)
        {
            item.SetOwner(null);
        }
        base.ClearItems();
    }
}

