using System.Threading;
using System.Threading.Tasks;
 
namespace Writer
{
    class Manager
    {
        static void Main(string[] args)
        {
            metered(TimeSpan.FromSeconds(2));
        }
 
        static void metered(TimeSpan duration)
        {
            const int MAX_COUNT = 4; // Total available resources
            const byte NUM_WORKERS = 10; // Number of workers contending for the resources
            var backoff = TimeSpan.FromMilliseconds(1); // Linear backoff time
            // Create a shared reference to the semaphore
            var sem = new CountingSemaphore(MAX_COUNT, backoff);
            // Create a channel for notifying the main task that the workers are done
            var tx = new List<TaskCompletionSource<bool>>();
            var rx = new List<TaskCompletionSource<bool>>();
            for (int i = 0; i < NUM_WORKERS; i++)
            {
                var tcs = new TaskCompletionSource<bool>();
                tx.Add(tcs);
                rx.Add(tcs);
            }
            for (int i = 0; i < NUM_WORKERS; i++)
            {
                var sem1 = sem;
                var tx1 = tx[i];
                Task.Run(() =>
                {
                    // Acquire the resource
                    var guard = sem1.acquire();
                    var count = sem1.count();
                    // Make sure the count is legal
                    if (count >= MAX_COUNT)
                    {
                        throw new Exception();
                    }
                    Console.WriteLine("Worker {0} after acquire: count = {1}", i, count);
                    // Sleep for `duration`
                    Thread.Sleep(duration);
                    // Release the resource
                    guard.Dispose();
                    // Make sure the count is legal
                    var count1 = sem1.count();
                    if (count1 > MAX_COUNT)
                    {
                        throw new Exception();
                    }
                    Console.WriteLine("Worker {0} after release: count = {1}", i, count1);
                    // Notify the main task of completion
                    tx1.SetResult(true);
                });
            }
            // Wait for all the subtasks to finish
            Task.WaitAll(rx.ToArray());
        }
    }
 
