using System;
using System.Collections.Generic;
using System.Linq;

public static class MetricCounterFieldsExtensions
{
    public static void Exclude(this Dictionary<CounterFields, string> metrics, params CounterFields[] fieldsToExclude)
    {
        if (metrics == null) throw new ArgumentNullException(nameof(metrics));
        if (fieldsToExclude == null) throw new ArgumentNullException(nameof(fieldsToExclude));

        foreach (var field in fieldsToExclude)
        {
            metrics.Remove(field);
        }
    }

    public static void OnlyInclude(this Dictionary<CounterFields, string> metrics, params CounterFields[] fieldsToInclude)
    {
        if (metrics == null) throw new ArgumentNullException(nameof(metrics));
        if (fieldsToInclude == null) throw new ArgumentNullException(nameof(fieldsToInclude));

        var fieldsToRemove = metrics.Keys.Except(fieldsToInclude).ToList();

        foreach (var field in fieldsToRemove)
        {
            metrics.Remove(field);
        }
    }

    public static void Set(this Dictionary<CounterFields, string> metrics, CounterFields field, string value)
    {
        if (metrics == null) throw new ArgumentNullException(nameof(metrics));

        if (string.IsNullOrWhiteSpace(value))
            throw new ArgumentException("Value cannot be null or whitespace.", nameof(value));

        metrics[field] = value;
    }
}

public enum CounterFields
{
    Requests,
    Errors,
    Latency,
    SuccessRate,
    Throughput
}

public class ExampleUsage
{
    public static void Main(string[] args)
    {
        var metrics = new Dictionary<CounterFields, string>
        {
            { CounterFields.Requests, "100" },
            { CounterFields.Errors, "5" },
            { CounterFields.Latency, "120ms" }
        };

        Console.WriteLine("Original Metrics:");
        DisplayMetrics(metrics);

        metrics.Exclude(CounterFields.Errors);
        Console.WriteLine("\nAfter Excluding 'Errors':");
        DisplayMetrics(metrics);

        metrics.OnlyInclude(CounterFields.Requests);
        Console.WriteLine("\nAfter Only Including 'Requests':");
        DisplayMetrics(metrics);

        metrics.Set(CounterFields.Requests, "150");
        Console.WriteLine("\nAfter Setting 'Requests' to '150':");
        DisplayMetrics(metrics);
    }

    private static void DisplayMetrics(Dictionary<CounterFields, string> metrics)
    {
        foreach (var metric in metrics)
        {
            Console.WriteLine($"{metric.Key}: {metric.Value}");
        }
    }
}

