namespace ProductPriceManagement
{
    public class Product
    {
        public int ProductId { get; set; }
        public string Name { get; set; }
        public virtual ICollection<Price> Prices { get; set; }

        public Product()
        {
            Prices = new List<Price>();
        }
    }

    public class Price
    {
        public int PriceId { get; set; }
        public decimal Amount { get; set; }
        public DateTime EffectiveDate { get; set; }
        public int ProductId { get; set; }
        public virtual Product Product { get; set; }
    }

    public class AppDbContext : DbContext
    {
        public DbSet<Product> Products { get; set; }
        public DbSet<Price> Prices { get; set; }

        public AppDbContext() : base("ProductPriceDb")
        {
            Configuration.LazyLoadingEnabled = true;
            Configuration.ProxyCreationEnabled = true;
        }

        protected override void OnModelCreating(DbModelBuilder modelBuilder)
        {
            modelBuilder.Entity<Product>()
                .HasMany(p => p.Prices)
                .WithRequired(p => p.Product)
                .HasForeignKey(p => p.ProductId);
        }

        public static void Initialize()
        {
            Database.SetInitializer(new Initializer());
            using (var context = new AppDbContext())
            {
                context.Database.Initialize(force: true);
            }
        }
    }

    public class Initializer : DropCreateDatabaseAlways<AppDbContext>
    {
        protected override void Seed(AppDbContext context)
        {
            AddItems(context);
            base.Seed(context);
        }

        private void AddItems(AppDbContext context)
        {
            var products = new List<Product>
            {
                new Product { Name = "Product A", Prices = new List<Price>
                {
                    new Price { Amount = 29.99m, EffectiveDate = DateTime.Now },
                    new Price { Amount = 24.99m, EffectiveDate = DateTime.Now.AddMonths(-1) }
                }},
                new Product { Name = "Product B", Prices = new List<Price>
                {
                    new Price { Amount = 39.99m, EffectiveDate = DateTime.Now },
                    new Price { Amount = 34.99m, EffectiveDate = DateTime.Now.AddMonths(-1) }
                }}
            };

            context.Products.AddRange(products);
            context.SaveChanges();
        }
    }

