[TestFixture]
public class ScriptCSFixture
{
    private TemporaryFile variablesFile;
    private VariableDictionary variables;

    [SetUp]
    public void SetUp()
    {
        variables = new VariableDictionary();
        variablesFile = new TemporaryFile(Path.GetTempFileName());
    }

    [TearDown]
    public void TearDown()
    {
        variablesFile.Dispose();
    }

    [Test]
    public void ScriptExecution_WithEncodedVariables_PrintsCorrectOutput()
    {
        variables.Set("EncodedVar", "Hello%20World");
        variables.Save(variablesFile.FilePath);

        var output = InvokeCalamari("run-script", "--script", GetFixtureResource("PrintEncodedVar.ps1"), "--variables", variablesFile.FilePath);
        AssertZero(output);
        AssertOutput(output, "Hello World");
    }

    [Test]
    public void ScriptExecution_WithArtifactCreation_CreatesArtifact()
    {
        var artifactPath = Path.Combine(Path.GetTempPath(), "test-artifact.txt");
        variables.Set("ArtifactPath", artifactPath);
        variables.Save(variablesFile.FilePath);

        var output = InvokeCalamari("run-script", "--script", GetFixtureResource("CreateArtifact.ps1"), "--variables", variablesFile.FilePath);
        AssertZero(output);
        Assert.IsTrue(File.Exists(artifactPath), "Artifact file was not created.");
    }

    [Test]
    public void ScriptExecution_WithVariableSubstitution_SubstitutesCorrectly()
    {
        variables.Set("SubstituteVar", "SubstitutedValue");
        variables.Save(variablesFile.FilePath);

        var output = InvokeCalamari("run-script", "--script", GetFixtureResource("SubstituteVar.ps1"), "--variables", variablesFile.FilePath);
        AssertZero(output);
        AssertOutput(output, "SubstitutedValue");
    }

    private string InvokeCalamari(params string[] args)
    {
        var calamari = new CalamariInvocation();
        return calamari.Invoke(args);
    }

    private void AssertZero(string output)
    {
        Assert.AreEqual(0, output.ExitCode, "Script execution failed with non-zero exit code.");
    }

    private void AssertOutput(string output, string expected)
    {
        StringAssert.Contains(expected, output, "Script output did not match expected result.");
    }

    private string GetFixtureResource(string resourceName)
    {
        return Path.Combine(TestContext.CurrentContext.TestDirectory, "Fixtures", resourceName);
    }
}

