    public class ArrestFinishCommand : IRocketCommand
    {
        public AllowedCaller AllowedCaller => AllowedCaller.Player;
        public string Name => "arrestfinish";
        public string Syntax => "/arrestfinish <playerName>";
        public string Help => "Finish the arrest process on another player.";
        public string[] Aliases => new string[] { "finisharrest" };
        public string Permissions => "arrest.finish";

        public void Execute(IRocketPlayer caller, string[] command)
        {
            // Check if the command is invoked correctly
            if (command.Length < 1)
            {
                UnturnedChat.Say(caller, "Usage: " + Syntax);
                return;
            }

            // Prevent console execution
            if (caller is ConsolePlayer)
            {
                Logger.LogWarning("Arrest finish command cannot be executed from the console.");
                return;
            }

            string playerName = command[0];
            var targetPlayer = FindPlayerByName(playerName);

            // Validate target player existence
            if (targetPlayer == null)
            {
                UnturnedChat.Say(caller, "Player not found: " + playerName);
                return;
            }

            // Permission checks
            if (!HasPermission(caller, Permissions))
            {
                UnturnedChat.Say(caller, "You do not have permission to finish an arrest.");
                return;
            }

            // Finishing the arrest
            FinishArrest(caller, targetPlayer);
        }

        private void FinishArrest(IRocketPlayer caller, IRocketPlayer targetPlayer)
        {
            // Logic to finalize the arrest
            // This should include updating game state (not implemented in this snippet)
            UnturnedChat.Say(caller, $"You have successfully finished the arrest of {targetPlayer.DisplayName}.");
            UnturnedChat.Say(targetPlayer, $"You have been released from arrest by {caller.DisplayName}.");
        }

        private IRocketPlayer FindPlayerByName(string playerName)
        {
            // Assuming GetPlayers is a method that retrieves all online players
            return Rocket.Core.Api.RocketPlayerManager.OnlinePlayers
                .FirstOrDefault(p => p.DisplayName.Equals(playerName, StringComparison.OrdinalIgnoreCase));
        }

using System;
using System.Collections.Generic;
using System.Linq;

public class TagHelperIntermediateNode
{
    public string TagName { get; set; }
    public string TagMode { get; set; }
    public List<TagHelperDescriptor> TagHelpers { get; set; }
    public IntermediateNodeCollection Children { get; set; }

    public TagHelperIntermediateNode()
    {
        Children = new IntermediateNodeCollection();
        TagHelpers = new List<TagHelperDescriptor>();
    }

    public IEnumerable<TagHelperBodyIntermediateNode> BodyNodes
    {
        get { return Children.OfType<TagHelperBodyIntermediateNode>(); }
    }

    public IEnumerable<TagHelperPropertyIntermediateNode> PropertyNodes
    {
        get { return Children.OfType<TagHelperPropertyIntermediateNode>(); }
    }

    public IEnumerable<TagHelperHtmlAttributeIntermediateNode> AttributeNodes
    {
        get { return Children.OfType<TagHelperHtmlAttributeIntermediateNode>(); }
    }

    public void Accept(IntermediateNodeVisitor visitor)
    {
        visitor.Visit(this);
        foreach (var child in Children)
        {
            child.Accept(visitor);
        }
    }

    public string FormatNode()
    {
        var formatter = new IntermediateNodeFormatter();
        return formatter.Format(this);
    }
}

public class IntermediateNodeCollection : List<IntermediateNode>
{
}

public abstract class IntermediateNode
{
    public abstract void Accept(IntermediateNodeVisitor visitor);
}

public abstract class IntermediateNodeVisitor
{
    public abstract void Visit(TagHelperIntermediateNode node);
    public abstract void Visit(IntermediateNode node);
}

public class IntermediateNodeFormatter
{
    public string Format(TagHelperIntermediateNode node)
    {
        var formattedString = $"TagHelper: {node.TagName}, Mode: {node.TagMode}\n";
        formattedString += "TagHelpers:\n";
        foreach (var tagHelper in node.TagHelpers)
        {
            formattedString += $"  {tagHelper}\n";
        }
        formattedString += "Children:\n";
        foreach (var child in node.Children)
        {
            formattedString += $"  {child}\n";
        }
        return formattedString;
    }
}

public class TagHelperDescriptor
{
    public string Name { get; set; }
    public override string ToString() => $"Name: {Name}";
}

public class TagHelperBodyIntermediateNode : IntermediateNode
{
    public string Content { get; set; }
    public override void Accept(IntermediateNodeVisitor visitor) => visitor.Visit(this);
    public override string ToString() => $"Body: {Content}";
}

