public struct alphaInfo
{
    public Color color;
    public float alpha;
    public bool isFadingIn;
    public bool isFadingOut;
}

public abstract class AlphaController : MonoBehaviour
{
    protected Dictionary<Graphic, alphaInfo> uiElements = new Dictionary<Graphic, alphaInfo>();
    protected bool isInFading = false;
    protected bool isBusy = false;
    protected float fadeSpeed = 0.5f;

    public void AddUIElement(Graphic element)
    {
        if (!uiElements.ContainsKey(element))
        {
            uiElements[element] = new alphaInfo
            {
                color = element.color,
                alpha = element.color.a,
                isFadingIn = false,
                isFadingOut = false
            };
        }
    }

    public void RemoveUIElement(Graphic element)
    {
        if (uiElements.ContainsKey(element))
        {
            uiElements.Remove(element);
        }
    }

    public void Show(Graphic element)
    {
        if (uiElements.ContainsKey(element))
        {
            uiElements[element].isFadingIn = true;
            uiElements[element].isFadingOut = false;
            isBusy = true;
            isInFading = true;
        }
    }

    public void Hide(Graphic element)
    {
        if (uiElements.ContainsKey(element))
        {
            uiElements[element].isFadingIn = false;
            uiElements[element].isFadingOut = true;
            isBusy = true;
            isInFading = true;
        }
    }

    protected virtual void Update()
    {
        foreach (var pair in uiElements)
        {
            var element = pair.Key;
            var info = pair.Value;

            if (info.isFadingIn)
            {
                info.alpha = Mathf.MoveTowards(info.alpha, 1f, fadeSpeed * Time.deltaTime);
                if (info.alpha >= 1f)
                {
                    info.isFadingIn = false;
                    isInFading = false;
                }
            }
            else if (info.isFadingOut)
            {
                info.alpha = Mathf.MoveTowards(info.alpha, 0f, fadeSpeed * Time.deltaTime);
                if (info.alpha <= 0f)
                {
                    info.isFadingOut = false;
                    isInFading = false;
                }
            }

            info.color.a = info.alpha;
            element.color = info.color;
            uiElements[element] = info;
        }

        if (!isInFading)
        {
            isBusy = false;
        }
    }

