namespace SquareAndCube
{
    class Stack
    {
        static void Main(string[] args)
        {
            int s = 1;
            int c = 1;
            int cube = 1;
            int n = 0;
            while (n < 30)
            {
                int square = s * s;
                while (cube < square)
                {
                    c += 1;
                    cube = c * c * c;
                }
                if (cube == square)
                {
                    Console.WriteLine("{0} is a square and a cube.", square);
                }
                else
                {
                    Console.WriteLine("{0}", square);
                    n += 1;
                }
                s += 1;
            }
        }
    }
}

