[AttributeUsage(AttributeTargets.Class)]
public class TestClassAttribute : Attribute { }

[AttributeUsage(AttributeTargets.Method)]
public class TestMethodAttribute : Attribute { }

public class UnitTestException : Exception
{
    public UnitTestException(string message) : base(message) { }
}

public class UnitTestRunner : MonoBehaviour
{
    // Called on start-up in the Unity Editor.
    private void Start()
    {
        RunUnitTests();
    }

    // Finds test classes and executes their test methods.
    private void RunUnitTests()
    {
        int totalTests = 0;
        Stopwatch timer = new Stopwatch();
        timer.Start();

        List<Type> testClasses = GetTestClasses();
        foreach (Type testClass in testClasses)
        {
            // Instantiate the test class.
            object testInstance = Activator.CreateInstance(testClass);
            MethodInfo[] methods = testClass.GetMethods(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);

            foreach (MethodInfo method in methods)
            {
                if (Attribute.IsDefined(method, typeof(TestMethodAttribute)))
                {
                    try
                    {
                        method.Invoke(testInstance, null);
                        totalTests++;
                        Debug.Log($"Test {method.Name} passed.");
                    }
                    catch (TargetInvocationException tie)
                    {
                        Exception innerEx = tie.InnerException;
                        if (innerEx is UnitTestException)
                        {
                            Debug.LogError($"Test {method.Name} failed: {innerEx.Message}");
                        }
                        else
                        {
                            Debug.LogError($"Test {method.Name} error: {innerEx}");
                        }
                    }
                    catch (Exception ex)
                    {
                        Debug.LogError($"Test {method.Name} error: {ex.Message}");
                    }
                }
            }
        }

        timer.Stop();
        Debug.Log($"Executed {totalTests} tests in {timer.ElapsedMilliseconds} ms");
    }

    // Uses reflection to find all classes annotated with [TestClassAttribute].
    private List<Type> GetTestClasses()
    {
        List<Type> testClasses = new List<Type>();

