public class TransportMessage
{
    public Address Source { get; }
    public Address Destination { get; }
    public Topic Topic { get; }
    public byte[] Payload { get; }
    public Dictionary<string, string> Headers { get; }

    public TransportMessage(Address source, Address destination, Topic topic, byte[] payload, Dictionary<string, string> headers = null)
    {
        Source = source;
        Destination = destination;
        Topic = topic;
        Payload = payload;
        Headers = headers ?? new Dictionary<string, string>();
    }
}

public abstract class MessageUnit
{
    public Address Address { get; }
    public CancellationTokenSource CancellationTokenSource { get; private set; }

    protected MessageUnit(Address address)
    {
        Address = address;
    }

    public abstract Task StartAsync(CancellationToken token);
    public abstract Task StopAsync();
    public abstract Task HandOver(TransportMessage message);
}

public class Broker
{
    private readonly ConcurrentDictionary<Address, List<MessageUnit>> _units = new ConcurrentDictionary<Address, List<MessageUnit>>();

    public void Register(MessageUnit unit)
    {
        _units.AddOrUpdate(
            unit.Address,
            new List<MessageUnit> { unit },
            (key, existingList) =>
            {
                existingList.Add(unit);
                return existingList;
            }
        );
    }

    public async Task StartAsync()
    {
        var startTasks = _units.Values
            .SelectMany(units => units)
            .Select(unit =>
            {
                unit.CancellationTokenSource = new CancellationTokenSource();
                return unit.StartAsync(unit.CancellationTokenSource.Token);
            });

        await Task.WhenAll(startTasks);
    }

    public async Task StopAsync()
    {
        var stopTasks = _units.Values
            .SelectMany(units => units)
            .Select(unit =>
            {
                unit.CancellationTokenSource?.Cancel();
                return unit.StopAsync();
            });

        await Task.WhenAll(stopTasks);
    }

