namespace CarControlSystemApp
{
    // Subsystem: Handles gas pedal operations
    public class GasPedalController
    {
        public int Acceleration { get; private set; }

        public void Accelerate(int increment)
        {
            Acceleration += increment;
            Console.WriteLine("Gas Pedal: Accelerating by " + increment + " (Current Acceleration: " + Acceleration + ").");
        }

        public void Decelerate(int decrement)
        {
            Acceleration = Math.Max(0, Acceleration - decrement);
            Console.WriteLine("Gas Pedal: Decelerating by " + decrement + " (Current Acceleration: " + Acceleration + ").");
        }

        public void Stop()
        {
            Acceleration = 0;
            Console.WriteLine("Gas Pedal: Stopped. Acceleration reset to 0.");
        }
    }

    // Subsystem: Handles steering wheel operations
    public class SteeringWheelController
    {
        public string Direction { get; private set; } = "Straight";

        public void Turn(string direction)
        {
            Direction = direction;
            Console.WriteLine("Steering Wheel: Turned to " + direction + ".");
        }

        public void Straighten()
        {
            Direction = "Straight";
            Console.WriteLine("Steering Wheel: Returned to Straight.");
        }
    }

    // Subsystem: Handles gear shifting
    public class GearShiftController
    {
        public int Gear { get; private set; } = 0;

        public void ShiftUp()
        {
            Gear++;
            Console.WriteLine("Gear Shift: Shifted up to gear " + Gear + ".");
        }

        public void ShiftDown()
        {
            Gear = Math.Max(0, Gear - 1);
            Console.WriteLine("Gear Shift: Shifted down to gear " + Gear + ".");
        }

        public void SetNeutral()
        {
            Gear = 0;
            Console.WriteLine("Gear Shift: Set to Neutral.");
        }
    }

    // Facade class encapsulating all car control operations
    public class CarControlFacade
    {
        private GasPedalController _gasPedal = new GasPedalController();
        private SteeringWheelController _steeringWheel = new SteeringWheelController();
        private GearShiftController _gearShift = new GearShiftController();

        public void DriveForward()
        {
            Console.WriteLine("Command: Drive Forward Initiated.");
            _gasPedal.Accelerate(10);
            _gearShift.ShiftUp();
            _gasPedal.Accelerate(5);
            _gearShift.ShiftUp();

using System;
