public class TrainerService
{
    private readonly LearningSystemDbContext _db;
    private readonly IMapper _mapper;

    public TrainerService(LearningSystemDbContext db, IMapper mapper)
    {
        _db = db;
        _mapper = mapper;
    }

    public async Task<IEnumerable<CourseListingServiceModel>> CoursesAsync(int trainerId)
    {
        return await _db.Courses
            .Where(c => c.TrainerId == trainerId)
            .ProjectTo<CourseListingServiceModel>(_mapper.ConfigurationProvider)
            .ToListAsync();
    }

    public async Task<bool> IsTrainerAsync(int userId, int courseId)
    {
        var course = await _db.Courses
            .FirstOrDefaultAsync(c => c.Id == courseId && c.TrainerId == userId);

        return course != null;
    }

    public async Task<IEnumerable<StudentInCourseServiceModel>> StudentsInCourseAsync(int courseId)
    {
        return await _db.StudentCourses
            .Where(sc => sc.CourseId == courseId)
            .Select(sc => sc.Student)
            .ProjectTo<StudentInCourseServiceModel>(_mapper.ConfigurationProvider)
            .ToListAsync();
    }

    public async Task<bool> AddGradeAsync(int courseId, int studentId, Grade grade)
    {
        var studentCourse = await _db.StudentCourses
            .FirstOrDefaultAsync(sc => sc.CourseId == courseId && sc.StudentId == studentId);

        if (studentCourse == null)
        {
            return false;
        }

        studentCourse.Grade = grade;
        await _db.SaveChangesAsync();
        return true;
    }
}

