namespace RazorTagHelpers
{
    public enum TagMode
    {
        StartTag,
        EndTag,
        SelfClosing
    }

    public class TagHelperDescriptor
    {
        public string Name { get; set; }
        public string[] Attributes { get; set; }
    }

    public abstract class IntermediateNode
    {
        public abstract void Accept(IVisitor visitor);
    }

    public interface IVisitor
    {
        void Visit(TagHelperIntermediateNode node);
    }

    public class TagHelperIntermediateNode : IntermediateNode
    {
        public TagMode Mode { get; }
        public string TagName { get; }
        public List<TagHelperDescriptor> TagHelpers { get; }
        public List<IntermediateNode> Children { get; }

        public TagHelperIntermediateNode(TagMode mode, string tagName)
        {
            Mode = mode;
            TagName = tagName;
            TagHelpers = new List<TagHelperDescriptor>();
            Children = new List<IntermediateNode>();
        }

        public void AddTagHelperDescriptor(TagHelperDescriptor descriptor)
        {
            TagHelpers.Add(descriptor);
        }

        public void AddChildNode(IntermediateNode child)
        {
            Children.Add(child);
        }

        public override void Accept(IVisitor visitor)
        {
            visitor.Visit(this);
            foreach (var child in Children)
            {
                child.Accept(visitor);
            }
        }

        public string FormatNode()
        {
            var formattedChildren = Children.Select(child => child.FormatNode()).ToList();
            var childrenOutput = string.Join(Environment.NewLine, formattedChildren);
            return $"Tag: {TagName}, Mode: {Mode}, TagHelpers: {TagHelpers.Count}" + Environment.NewLine + childrenOutput;
        }
    }

    public class TagHelperVisitor : IVisitor
    {
        public void Visit(TagHelperIntermediateNode node)
        {
            Console.WriteLine(node.FormatNode());
        }
    }

    class Manager
    {
        static void Main(string[] args)
        {
            var tagHelperNode = new TagHelperIntermediateNode(TagMode.StartTag, "example");
            tagHelperNode.AddTagHelperDescriptor(new TagHelperDescriptor { Name = "ExampleHelper", Attributes = new[] { "attribute1", "attribute2" } });
            tagHelperNode.AddChildNode(new TagHelperIntermediateNode(TagMode.SelfClosing, "child"));

            var visitor = new TagHelperVisitor();
            tagHelperNode.Accept(visitor);
        }
    }
}

using ApiAiSDK.Model;
