using System.Threading.Tasks;

public class BoletinDialog : IDialog<object>
{
    private AIResponse _response;

    public BoletinDialog(AIResponse response)
    {
        _response = response;
    }

    public async Task StartAsync(IDialogContext context)
    {
        // Generate initial message from AI response
        var fulfillmentMessage = _response.Result.Fulfillment.Speech;
        await context.PostAsync(fulfillmentMessage);

        // Fetch bulletin data from the proxy
        var boletinProxy = new BoletinProxy();
        var boletines = await boletinProxy.Obtener();

        // Format bulletins into interactive cards
        var cards = new List<Attachment>();
        foreach (var boletin in boletines)
        {
            var card = new HeroCard
            {
                Title = boletin.Titulo,
                Subtitle = boletin.Descripcion,
                Buttons = new List<CardAction>
                {
                    new CardAction
                    {
                        Type = ActionTypes.DownloadFile,
                        Title = "Descargar",
                        Value = boletin.EnlaceDescarga
                    }
                }
            };
            cards.Add(card.ToAttachment());
        }

        // Send the cards to the user
        var reply = context.MakeMessage();
        reply.AttachmentLayout = AttachmentLayoutTypes.Carousel;
        reply.Attachments = cards;
        await context.PostAsync(reply);

        // End the dialog
        context.Done<object>(null);
    }
}

