using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace Solution
{
    class Converter
    {
        static void Main(string[] args)
        {
            string test_string = "g";
            Console.WriteLine("input string: {0}", test_string);
            Console.WriteLine("output string: {0}", splitter(test_string));
 
            test_string = "";
            Console.WriteLine("input string: {0}", test_string);
            Console.WriteLine("output string: {0}", splitter(test_string));
 
            test_string = "gHHH5YY++///\\";
            Console.WriteLine("input string: {0}", test_string);
            Console.WriteLine("output string: {0}", splitter(test_string));
 
            Console.ReadKey();
        }
 
        static string splitter(string string_input)
        {
            List<string> result = new List<string>();
            int last_mismatch = 0;
            for (int i = 0; i < string_input.Length; i++)
            {
                if (i > 0 && string_input[i - 1]!= string_input[i])
                {
                    result.Add(string_input.Substring(last_mismatch, i - last_mismatch));
                    last_mismatch = i;
                }
                if (i == string_input.Length - 1)
                {
                    result.Add(string_input.Substring(last_mismatch, string_input.Length - last_mismatch));
                }
            }
            return string.Join(", ", result);
        }
    }
}

