        {
            throw new InvalidOperationException("Logging configuration has already been initialized.");
        }

        configuration = LogManager.Configuration ?? new LoggingConfiguration();
        CreateChainsawTarget();
        CreateMemoryTarget();
        SetGlobalLoggingRules();

        LogManager.Configuration = configuration;
        isConfigured = true;
    }

    private static void CreateChainsawTarget()
    {
        var chainsawTarget = new NetworkTarget(ChainsawTargetName)
        {
            Address = "udp://localhost:7071",
            Layout = "${longdate}|${level:uppercase=true}|${logger}|${message}"
        };

        configuration.AddTarget(chainsawTarget);
    }

    private static void CreateMemoryTarget()
    {
        var memoryTarget = new MemoryTarget(MemoryTargetName)
        {
            Layout = "${longdate}|${level:uppercase=true}|${logger}|${message}",
            MaxLogEntries = 1000
        };

        configuration.AddTarget(memoryTarget);
    }

    private static void SetGlobalLoggingRules()
    {
        var logLevel = Environment.MachineName.Contains("DEV")
            ? LogLevel.Trace
            : LogLevel.Info;

        var rule = new LoggingRule("*", logLevel, configuration.FindTargetByName(ChainsawTargetName));
        configuration.LoggingRules.Add(rule);

        rule = new LoggingRule("*", logLevel, configuration.FindTargetByName(MemoryTargetName));
        configuration.LoggingRules.Add(rule);
    }

    public static void SetChainsawLevel(LogLevel level)
    {
        ModifyTargetLevel(ChainsawTargetName, level);
