public class LoggingEventDataBuilder
{
    private static readonly ILog log = LogManager.GetLogger(typeof(LoggingEventDataBuilder));

    private string userId;
    private string severity;
    private string message;
    private IDictionary<string, string> properties = new Dictionary<string, string>();

    public LoggingEventDataBuilder(string userId, string severity, string message)
    {
        this.userId = userId;
        this.severity = severity;
        this.message = message;
    }

    public LoggingEventDataBuilder AddProperty(string key, string value)
    {
        if (!string.IsNullOrEmpty(key) && value != null)
        {
            properties[key] = value;
        }
        return this;
    }

    public LoggingEventData Build()
    {
        var stackFrame = new StackFrame(1, true);
        var method = stackFrame.GetMethod();
        var fileName = stackFrame.GetFileName();
        var lineNumber = stackFrame.GetFileLineNumber();
        var timestamp = DateTime.UtcNow;

        if (string.IsNullOrEmpty(userId))
        {
            userId = "Anonymous";
        }

        return new LoggingEventData
        {
            UserId = userId,
            Severity = severity,
            Message = message,
            Method = method.Name,
            FileName = fileName,
            LineNumber = lineNumber,
            Timestamp = timestamp,
            Properties = properties
        };
    }
}

public struct LoggingEventData
{
    public string UserId { get; set; }
    public string Severity { get; set; }
    public string Message { get; set; }
    public string Method { get; set; }
    public string FileName { get; set; }
    public int LineNumber { get; set; }
    public DateTime Timestamp { get; set; }
    public IDictionary<string, string> Properties { get; set; }
}

public static class LoggingExtensions
{
    public static string ToQuery(this IDictionary<string, string> properties)
    {
        return string.Join("&", properties.Select(kvp =>
            $"{WebUtility.UrlEncode(kvp.Key)}={WebUtility.UrlEncode(kvp.Value)}"));
    }
}

