public static class TextureFXUtilities
{
    public static void ApplyTargetSize(TextureFXSettings settings, EffectVectorVariable targetSizeVar)
    {
        var target = settings.CurrentTarget;
        var size = new Vector2(target.Description.Width, target.Description.Height);
        targetSizeVar?.Set(size);
    }

    public static void ApplyInvTargetSize(TextureFXSettings settings, EffectVectorVariable invTargetSizeVar)
    {
        var target = settings.CurrentTarget;
        var invSize = new Vector2(1f / target.Description.Width, 1f / target.Description.Height);
        invTargetSizeVar?.Set(invSize);
    }

    public static void ApplyFullTargetSize(TextureFXSettings settings, EffectVectorVariable fullTargetSizeVar)
    {
        var target = settings.CurrentTarget;
        int width = target.Description.Width;
        int height = target.Description.Height;
        var fullSize = new Vector4(width, height, 1f / width, 1f / height);
        fullTargetSizeVar?.Set(fullSize);
    }

    public static void ApplyInitialTexture(TextureFXSettings settings, EffectShaderResourceVariable initialTextureVar)
    {
        var texture = settings.InitialTexture ?? GetFallbackTexture();
        initialTextureVar?.SetResource(texture);
    }

    public static void ApplyPreviousTexture(TextureFXSettings settings, EffectShaderResourceVariable previousTextureVar)
    {
        var texture = settings.PreviousTexture ?? settings.InitialTexture ?? GetFallbackTexture();
        previousTextureVar?.SetResource(texture);
    }

    public static void ApplyPassIndex(TextureFXPassSettings passSettings, EffectScalarVariable passIndexVar)
    {
        passIndexVar?.Set(passSettings.PassIndex);
    }

    private static ShaderResourceView GetFallbackTexture()
    {
        // Implementation returns a 1x1 transparent texture
        // Cached instance should be used in real implementation
        return TextureCache.TransparentBlack;
    }
