namespace Runner
{
    class Checker
    {
        static void Main(string[] args)
        {
            var data = "12 127 28 42"; //...omitted...127 31 116 146";
            var m = new Dictionary<int, List<string>>();
            foreach (var s in data.Split(' '))
            {
                if (s.Length == 1)
                {
                    if (!m.ContainsKey(0))
                    {
                        m.Add(0, new List<string>());
                    }
                    m[0].Add(s);
                }
                else
                {
                    var i = int.Parse(s.Substring(0, s.Length - 1));
                    if (!m.ContainsKey(i))
                    {
                        m.Add(i, new List<string>());
                    }
                    m[i].Add(s.Substring(s.Length - 1));
                }
            }
            var s = m.Keys.ToList();
            s.Sort();
            for (var k = s[0]; ; k++)
            {
                var v = m[k];
                v.Sort();
                Console.WriteLine("{0} | {1}", k, string.Join(" ", v));
                if (k == s[s.Count - 1])
                {
                    break;
                }
            }
        }
    }
}

