    /// <summary>
    /// Represents a mapping between a span of code in a source file and a line in an external file.
    /// </summary>
    public class ExternalLineMapping
    {
        private readonly Location _Start;
        private readonly Location _Finish;
        private readonly string _File;
        private readonly int _Line;

        /// <summary>
        /// Initializes a new instance of the <see cref="ExternalLineMapping"/> class.
        /// </summary>
        /// <param name="start">The start location in the source file.</param>
        /// <param name="finish">The finish location in the source file.</param>
        /// <param name="file">The external file.</param>
        /// <param name="line">The line number in the external file.</param>
        public ExternalLineMapping(Location start, Location finish, string file, int line)
        {
            _Start = start;
            _Finish = finish;
            _File = file;
            _Line = line;
        }

        /// <summary>
        /// Gets the start location in the source file.
        /// </summary>
        public Location Start => _Start;

        /// <summary>
        /// Gets the finish location in the source file.
        /// </summary>
        public Location Finish => _Finish;

        /// <summary>
        /// Gets the external file.
        /// </summary>
        public string File => _File;

        /// <summary>
        /// Gets the line number in the external file.
        /// </summary>
        public int Line => _Line;
    }

    // Assuming Location is defined elsewhere:
    public struct Location
    {
        public int Line { get; set; }
        public int Column { get; set; }
    }
}

using System;
using System.Collections.Generic;
