public class TagHelperIntermediateNode : IntermediateNode
{
    public string TagName { get; set; }
    public TagMode TagMode { get; set; }
    public IList<object> TagHelpers { get; } = new List<object>();
    public IEnumerable<IntermediateNode> Body => Children.Where(n => n is BodyIntermediateNode);
    public IEnumerable<IntermediateNode> Properties => Children.Where(n => n is PropertyIntermediateNode);
    public IEnumerable<IntermediateNode> HtmlAttributes => Children.Where(n => n is HtmlAttributeIntermediateNode);

    public override void Accept(IntermediateNodeVisitor visitor)
    {
        if (visitor == null)
        {
            throw new ArgumentNullException(nameof(visitor));
        }

        visitor.VisitTagHelper(this);
    }

    public override void FormatNode(IntermediateNodeFormatter formatter)
    {
        if (formatter == null)
        {
            throw new ArgumentNullException(nameof(formatter));
        }

        formatter.WriteContent($"TagHelper: {TagName}");
        formatter.WriteProperty(nameof(TagMode), TagMode.ToString());
        formatter.WriteProperty(nameof(TagHelpers), string.Join(", ", TagHelpers));

        foreach (var child in Children)
        {
            child.FormatNode(formatter);
        }
    }
}

public enum TagMode
{
    StartTag,
    EndTag,
    SelfClosing
}

public abstract class IntermediateNode
{
    public IList<IntermediateNode> Children { get; } = new List<IntermediateNode>();

    public abstract void Accept(IntermediateNodeVisitor visitor);
    public abstract void FormatNode(IntermediateNodeFormatter formatter);
}

public class BodyIntermediateNode : IntermediateNode
{
    public override void Accept(IntermediateNodeVisitor visitor) => visitor.VisitBody(this);
    public override void FormatNode(IntermediateNodeFormatter formatter) => formatter.WriteContent("Body");
}

public class PropertyIntermediateNode : IntermediateNode
{
    public override void Accept(IntermediateNodeVisitor visitor) => visitor.VisitProperty(this);
    public override void FormatNode(IntermediateNodeFormatter formatter) => formatter.WriteContent("Property");
}

public class HtmlAttributeIntermediateNode : IntermediateNode
{
    public override void Accept(IntermediateNodeVisitor visitor) => visitor.VisitHtmlAttribute(this);
    public override void FormatNode(IntermediateNodeFormatter formatter) => formatter.WriteContent("HtmlAttribute");
}

