internal class GravityEntryFile
{
    public DateTime IssuedStamp { get; set; }
    public string IssuedTo { get; set; }

    public static GravityEntryFile Load(string path = null, bool throwException = true)
    {
        try
        {
            string filePath = SafeToString(path) ?? Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "default.gravity");

            if (!File.Exists(filePath))
            {
                if (throwException)
                    throw new FileNotFoundException($"File not found: {filePath}");
                return null;
            }

            string encryptedContent = File.ReadAllText(filePath, Encoding.UTF8);
            string decryptedContent = DecryptR3DES(encryptedContent);

            return JsonConvert.DeserializeObject<GravityEntryFile>(decryptedContent);
        }
        catch (Exception ex)
        {
            if (throwException)
                throw;
            else
            {
                Framework.ApiTracking.Handle(ex, "Failed to load GravityEntryFile.");
                return null;
            }
        }
    }

    private static string DecryptR3DES(string encryptedContent)
    {
        // Placeholder for decryption logic (e.g., Triple DES)
        // This should be replaced with actual decryption implementation.
        return encryptedContent; // For demonstration, return the same content.
    }

    private static string SafeToString(string value)
    {
        return string.IsNullOrWhiteSpace(value) ? null : value.Trim();
    }
}

