using Apache.NMS;
using NServiceBus;
using NServiceBus.Transport;

public class MsmqMessageHandler : IHandleMessages<TransportMessage>
{
    private readonly IConnectionFactory _connectionFactory;
    private readonly MsmqToActiveMqMessageConverter _converter;
    private readonly IBus _bus;

    public MsmqMessageHandler(IConnectionFactory connectionFactory, MsmqToActiveMqMessageConverter converter, IBus bus)
    {
        _connectionFactory = connectionFactory;
        _converter = converter;
        _bus = bus;
    }

    public async Task Handle(TransportMessage message, IMessageHandlerContext context)
    {
        // Skip processing for scheduled tasks
        if (message.Headers.ContainsKey("NServiceBus.EnclosedMessageTypes") &&
            message.Headers["NServiceBus.EnclosedMessageTypes"].Contains("ScheduledTask"))
        {
            return;
        }

        // Get the transport message and metadata
        var transportMessage = context.Extensions.Get<TransportMessage>();
        var messageType = transportMessage.Headers["NServiceBus.EnclosedMessageTypes"];

        // Convert MSMQ message to ActiveMQ message
        var activeMqMessage = _converter.CreateActiveMqTextMessageFromMsmqTransportMessage(transportMessage);

        // Determine the destination queue
        var destinationQueue = GetQueue(messageType);

        // Send the message to ActiveMQ
        using (var connection = _connectionFactory.CreateConnection())
        using (var session = connection.CreateSession())
        {
            var destination = session.GetQueue(destinationQueue);
            using (var producer = session.CreateProducer(destination))
            {
                producer.Send(activeMqMessage);
            }
        }
    }

    private string GetQueue(string messageType)
    {
        // Logic to determine the destination queue based on message type
        if (messageType.Contains("Order"))
        {
            return "OrdersQueue";
        }
        else if (messageType.Contains("Payment"))
        {
            return "PaymentsQueue";
        }
        return "DefaultQueue";
    }
}

public class MsmqToActiveMqMessageConverter
{
    public ITextMessage CreateActiveMqTextMessageFromMsmqTransportMessage(TransportMessage msmqMessage)
    {
        var textMessage = new TextMessage
        {
            Text = Encoding.UTF8.GetString(msmqMessage.Body),
            Properties = new Dictionary<string, object>()
        };

