namespace Content.Client.InteractionOutline
{
    public class InteractionOutlineComponent : Component
    {
        [Dependency] private readonly IPrototypeManager _prototypeManager = default!;

        private ShaderInstance _inRangeShader;
        private ShaderInstance _outOfRangeShader;
        private ShaderInstance _currentShader;
        private ISpriteComponent _sprite;

        public override string Name => "InteractionOutline";

        public override void Initialize()
        {
            base.Initialize();
            IoCManager.InjectDependencies(this);

            _inRangeShader = _prototypeManager.Index<ShaderPrototype>("SelectionOutlineInRange").Instance();
            _outOfRangeShader = _prototypeManager.Index<ShaderPrototype>("SelectionOutlineOutOfRange").Instance();
        }

        public void OnMouseEnter()
        {
            if (!Owner.TryGetComponent(out _sprite))
                return;

            _sprite.PostShader = _currentShader;
            _sprite.RenderOrder = 100; // Ensure outline is on top
        }

        public void OnMouseLeave()
        {
            if (_sprite == null)
                return;

            _sprite.PostShader = null;
            _sprite.RenderOrder = 0;
        }

        public void UpdateInRange(bool inRange)
        {
            if (inRange)
            {
                _currentShader = _inRangeShader;
            }
            else
            {
                _currentShader = _outOfRangeShader;
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
 
public static class PerfectShuffle
{
    static void Main()
    {
        foreach (int input in new [] {8, 24, 52, 100, 1020, 1024, 10000}) {
            int[] numbers = Enumerable.Range(1, input).ToArray();
            Console.WriteLine($"{input} cards: {ShuffleThrough(numbers).Count()}");
        }
 
        IEnumerable<T[]> ShuffleThrough<T>(T[] original) {
            T[] copy = (T[])original.Clone();
            do {
                yield return copy = Shuffle(copy);
            } while (!Enumerable.SequenceEqual(original, copy));
        }
    }
 
    public static T[] Shuffle<T>(T[] array) {
        if (array.Length % 2 != 0) throw new ArgumentException("Length must be even.");
        int half = array.Length / 2;
        T[] result = new T[array.Length];
        for (int t = 0, l = 0, r = half; l < half; t+=2, l++, r++) {
            result[t] = array[l];
            result[t+1] = array[r];
        }
        return result;
    }
 
}

