public class XmlRpcRequest
{
    public virtual string MethodName { get; protected set; }
    public virtual object[] Params { get; protected set; }

    public virtual string Serialize()
    {
        var requestXml = new XmlDocument();
        var methodCallElement = requestXml.CreateElement("methodCall");

        var methodNameElement = requestXml.CreateElement("methodName");
        methodNameElement.InnerText = MethodName;
        methodCallElement.AppendChild(methodNameElement);

        var paramsElement = requestXml.CreateElement("params");
        foreach (var param in Params)
        {
            var paramElement = requestXml.CreateElement("param");
            var valueElement = requestXml.CreateElement("value");
            valueElement.InnerText = param.ToString();
            paramElement.AppendChild(valueElement);
            paramsElement.AppendChild(paramElement);
        }
        methodCallElement.AppendChild(paramsElement);
        requestXml.AppendChild(methodCallElement);

        return requestXml.OuterXml;
    }
}

public class XmlRpcBoxcarRequest : XmlRpcRequest
{
    private ArrayList Requests;

    public XmlRpcBoxcarRequest()
    {
        Requests = new ArrayList();
    }

    public void AddRequest(string methodName, params object[] parameters)
    {
        var request = new XmlRpcRequest
        {
            MethodName = methodName,
            Params = parameters
        };
        Requests.Add(request);
    }

    public override string Serialize()
    {
        var boxcarXml = new StringBuilder("<methodCalls>");
        foreach (XmlRpcRequest request in Requests)
        {
            boxcarXml.Append(request.Serialize());
        }
        boxcarXml.Append("</methodCalls>");

        return boxcarXml.ToString();
    }

    public void Send(string url)
    {
        var requestData = Serialize();
        var httpWebRequest = (HttpWebRequest)WebRequest.Create(url);
        httpWebRequest.ContentType = "text/xml";
        httpWebRequest.Method = "POST";

        using (var streamWriter = new StreamWriter(httpWebRequest.GetRequestStream()))
        {
            streamWriter.Write(requestData);
            streamWriter.Flush();
        }

        using (var httpResponse = (HttpWebResponse)httpWebRequest.GetResponse())
        using (var streamReader = new StreamReader(httpResponse.GetResponseStream()))
        {
            string result = streamReader.ReadToEnd();
            Console.WriteLine(result);

