public partial class MasterPage : System.Web.UI.MasterPage
{
    protected Repeater rptrCategories;
    protected Repeater rptrTags;
    protected TextBox txtSearch;
    protected HyperLink hypAdmin;

    protected void Page_Load(object sender, EventArgs e)
    {
        if (!IsPostBack)
        {
            BindCategories();
            BindTags();
            ShowAdminLink();
        }
    }

    private void BindCategories()
    {
        // Retrieve categories from a data access layer.
        List<Category> categories = DataAccess.Instance.GetCategories();
        if (categories != null && categories.Any())
        {
            rptrCategories.DataSource = categories;
            rptrCategories.DataBind();
        }
    }

    private void BindTags()
    {
        // Retrieve tags including different type counts
        List<Tag> tags = DataAccess.Instance.GetTags();
        if (tags != null && tags.Any())
        {
            // Filter tags for a minimum length, aggregate counts, order by popularity.
            var filteredTags = tags.Where(t => t.Name.Length >= 3)
                                   .Select(t =>
                                   {
                                       t.TotalCount = t.ArticleCount + t.VideoCount + t.ImageCount;
                                       return t;
                                   })
                                   .OrderByDescending(t => t.TotalCount)
                                   .Take(20)
                                   .ToList();

            rptrTags.DataSource = filteredTags;
            rptrTags.DataBind();
        }
    }

    protected void SearchHyperLink_Click(object sender, EventArgs e)
    {
        string query = txtSearch.Text.Trim();
        if (!string.IsNullOrEmpty(query))
        {
            // Redirect to the search results page with the search term.
            Response.Redirect("SearchResults.aspx?query=" + Server.UrlEncode(query));
        }
    }

    private void ShowAdminLink()
    {
        // Conditionally display the admin link based on user role.
        if (HttpContext.Current.User != null && HttpContext.Current.User.IsInRole("Administrator"))
        {
            hypAdmin.Visible = true;
        }
        else
        {
            hypAdmin.Visible = false;
        }
    }
}

