            DefaultSeverity = defaultSeverity;
        }

        public static readonly ErrorCodes ADFC001 = new ErrorCodes("ADFC001", ErrorSeverity.Error);
        public static readonly ErrorCodes ADFC002 = new ErrorCodes("ADFC002", ErrorSeverity.Warning);
        public static readonly ErrorCodes ADFC003 = new ErrorCodes("ADFC003", ErrorSeverity.Error);
        public static readonly ErrorCodes ADFC004 = new ErrorCodes("ADFC004", ErrorSeverity.Warning);
        public static readonly ErrorCodes ADFC005 = new ErrorCodes("ADFC005", ErrorSeverity.Error);

        public static readonly Dictionary<string, ErrorCodes> All = new[]
        {
            ADFC001,
            ADFC002,
            ADFC003,
            ADFC004,
            ADFC005
        }.ToDictionary(errorCode => errorCode.Code, errorCode => errorCode);
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.Threading;

public abstract class SnapshottingCollection
{
    protected object _lock = new object();
    protected volatile object _snapshot;

    protected SnapshottingCollection()
    {
        _snapshot = CreateSnapshot();
    }

    protected abstract object CreateSnapshot();

    protected void UpdateSnapshot(object newSnapshot)
    {
        Volatile.Write(ref _snapshot, newSnapshot);
    }
}

public class SnapshottingDictionary<TKey, TValue> : SnapshottingCollection, IDictionary<TKey, TValue>
{
    private Dictionary<TKey, TValue> _collection;

    public SnapshottingDictionary()
    {
        _collection = new Dictionary<TKey, TValue>();
        _snapshot = CreateSnapshot(_collection);
    }

    protected override object CreateSnapshot()
    {
        lock (_lock)
        {
            return new Dictionary<TKey, TValue>(_collection);
        }
    }

    public void Add(TKey key, TValue value)
    {
        lock (_lock)
        {
            _collection.Add(key, value);
            UpdateSnapshot(CreateSnapshot());
        }
    }

    public bool Remove(TKey key)
    {
        bool result;
        lock (_lock)
        {
            result = _collection.Remove(key);
            if (result)
            {
                UpdateSnapshot(CreateSnapshot());
            }
        }
        return result;
    }

    public bool ContainsKey(TKey key)
    {
        var snapshot = Volatile.Read(ref _snapshot) as Dictionary<TKey, TValue>;
        return snapshot.ContainsKey(key);
    }

    public bool TryGetValue(TKey key, out TValue value)
    {
        var snapshot = Volatile.Read(ref _snapshot) as Dictionary<TKey, TValue>;
        return snapshot.TryGetValue(key, out value);
    }

    public TValue this[TKey key]
    {
        get
        {
            var snapshot = Volatile.Read(ref _snapshot) as Dictionary<TKey, TValue>;
            return snapshot[key];
        }
        set
        {
            lock (_lock)
            {
                _collection[key] = value;
                UpdateSnapshot(CreateSnapshot());
            }
        }
    }

    public ICollection<TKey> Keys
    {
        get
        {
            var snapshot = Volatile.Read(ref _snapshot) as Dictionary<TKey, TValue>;
            return snapshot.Keys;
        }
    }

    public ICollection<TValue> Values
    {
        get
        {
            var snapshot = Volatile.Read(ref _snapshot) as Dictionary<TKey, TValue>;
            return snapshot.Values;
        }
    }

