public class EnvelopedDataParser
{
    private Asn1SequenceParser _sequenceParser;
    private DerInteger _version;
    private Asn1SetParser _recipientInfos;
    private EncryptedContentInfoParser _encryptedContentInfo;
    private Asn1SetParser _unprotectedAttrs;

    public EnvelopedDataParser(Asn1SequenceParser sequenceParser)
    {
        _sequenceParser = sequenceParser ?? throw new ArgumentNullException(nameof(sequenceParser));
        ParseSequence();
    }

    private void ParseSequence()
    {
        try
        {
            // Parse version
            Asn1Object versionObj = _sequenceParser.NextObject();
            _version = versionObj as DerInteger;

            // Parse recipient infos
            Asn1Object recipientInfosObj = _sequenceParser.NextObject();
            _recipientInfos = recipientInfosObj as Asn1SetParser;

            // Parse encrypted content info
            Asn1Object encryptedContentInfoObj = _sequenceParser.NextObject();
            _encryptedContentInfo = new EncryptedContentInfoParser(encryptedContentInfoObj as Asn1SequenceParser);

            // Optional: parse unprotected attributes
            Asn1Object unprotectedAttrsObj = _sequenceParser.NextObject();
            if (unprotectedAttrsObj is Asn1TaggedObject taggedObject)
            {
                _unprotectedAttrs = taggedObject.GetObjectParser(0, true) as Asn1SetParser;
            }
        }
        catch (Exception ex)
        {
            throw new InvalidOperationException("Error parsing EnvelopedData sequence", ex);
        }
    }

    public int GetVersion()
    {
        return _version?.Value.IntValue ?? -1;
    }

    public Asn1SetParser GetRecipientInfos()
    {
        return _recipientInfos;
    }

    public EncryptedContentInfoParser GetEncryptedContentInfo()
    {
        return _encryptedContentInfo;
    }

    public Asn1SetParser GetUnprotectedAttrs()
    {
        return _unprotectedAttrs;
    }

    public X509CertificateParser GetCertificates()
    {
        // Placeholder for certificate parsing logic
        return null;
    }

    public X509CrlParser GetCrls()
    {
        // Placeholder for CRL parsing logic
        return null;
    }
}

