namespace YourApplication.Application.Services
{
    /// <summary>
    /// Defines interface for voyage schedule management operations
    /// </summary>
    public interface IScheduleApplicationService
    {
        /// <summary>
        /// Applies a delay to the specified voyage schedule
        /// </summary>
        Task DelayScheduleAsync(VoyageId voyageId, TimeSpan delay, CancellationToken cancellationToken);
    }

    /// <summary>
    /// Application service implementation for voyage schedule adjustments
    /// </summary>
    public class ScheduleApplicationService : IScheduleApplicationService
    {
        private readonly ICommandBus _commandBus;

        /// <summary>
        /// Initializes a new instance of the schedule application service
        /// </summary>
        /// <param name="commandBus">Command bus for domain command propagation</param>
        public ScheduleApplicationService(ICommandBus commandBus)
        {
            _commandBus = commandBus ?? throw new ArgumentNullException(nameof(commandBus));
        }

        /// <summary>
        /// Coordinates the voyage delay operation through command dispatching
        /// </summary>
        /// <exception cref="ArgumentNullException">Thrown when voyageId is null</exception>
        /// <exception cref="ArgumentException">Thrown when delay is negative</exception>
        public async Task DelayScheduleAsync(VoyageId voyageId, TimeSpan delay, CancellationToken cancellationToken)
        {
            if (voyageId == null)
                throw new ArgumentNullException(nameof(voyageId));

            if (delay < TimeSpan.Zero)
                throw new ArgumentException("Delay duration cannot be negative", nameof(delay));

            var command = new VoyageDelayCommand(
                voyageId: voyageId,
                delayDuration: delay
            );

            try
            {
                await _commandBus.PublishAsync(command, cancellationToken)
                    .ConfigureAwait(false);
            }
            catch (Exception ex)
            {
                throw new ApplicationException(
                    $"Failed to process delay for voyage {voyageId}", ex);
            }
        }

        // Additional schedule management methods could be added below
        // (commented example for future expansion)
        // public Task RescheduleVoyageAsync(...) { ... }
    }
}

using System;
