namespace OpenDental {
    public class VixWinNumbered {

        public static void SendData(Program ProgramCur, Patient pat) {
            string path = Programs.GetProgramPath(ProgramCur);
            if (pat == null) {
                MessageBox.Show(Lan.g("VixWinNumbered", "Please select a patient first."));
                return;
            }
            string ppImagePath = ProgramProperties.GetPropVal(ProgramCur.ProgramNum, "Image Path");
            if (string.IsNullOrEmpty(ppImagePath)) {
                MessageBox.Show(Lan.g("VixWinNumbered", "Image Path cannot be blank."));
                return;
            }
            string subDirNumbers = (pat.PatNum % 100).ToString("00");
            string fullPath = ODFileUtils.CombinePaths(ppImagePath, subDirNumbers, Path.DirectorySeparatorChar);
            try {
                if (!Directory.Exists(fullPath)) {
                    Directory.CreateDirectory(fullPath);
                }
            }
            catch (Exception ex) {
                MessageBox.Show(Lan.g("VixWinNumbered", "Error creating image directory:") + " " + ex.Message);
                return;
            }
            string info = "";
            bool usePatNum = ProgramProperties.GetPropVal(ProgramCur.ProgramNum, "Enter 0 to use PatientNum, or 1 to use ChartNum") == "0";
            if (usePatNum) {
                info += "/p" + pat.PatNum.ToString() + " ";
            }
            else {
                info += "/c" + pat.ChartNumber + " ";
            }
            info += "/n" + pat.FName.Replace(" ", "") + pat.LName.Replace(" ", "") + " ";
            info += "/f" + fullPath;
            try {
                Process.Start(path, info);
            }
            catch (Exception ex) {
                MessageBox.Show(ex.Message);
            }
        }
    }
}

