using System;
using System.Collections.Concurrent;
using System.Security.Claims;
using System.Threading.Tasks;
using Microsoft.Owin.Security;
using Microsoft.Owin.Security.Infrastructure;

public class RefreshTokenProvider : IAuthenticationTokenProvider
{
    private readonly ConcurrentDictionary<string, (AuthenticationTicket Ticket, DateTime Expires)> _refreshTokens
        = new ConcurrentDictionary<string, (AuthenticationTicket, DateTime)>();

    public async Task CreateAsync(AuthenticationTokenCreateContext context)
    {
        var tokenValue = Guid.NewGuid().ToString("n");
        var expiresUtc = DateTime.UtcNow.AddHours(2);

        var ticket = new AuthenticationTicket(
            new ClaimsIdentity(context.Ticket.Identity.Claims, "RefreshToken"),
            new AuthenticationProperties(context.Ticket.Properties.Dictionary)
            {
                ExpiresUtc = expiresUtc
            });

        _refreshTokens.TryAdd(tokenValue, (ticket, expiresUtc));
        context.SetToken(tokenValue);
    }

    public async Task ReceiveAsync(AuthenticationTokenReceiveContext context)
    {
        if (_refreshTokens.TryRemove(context.Token, out var storedData))
        {
            if (storedData.Expires > DateTime.UtcNow)
            {
                var ticket = new AuthenticationTicket(
                    storedData.Ticket.Identity,
                    new AuthenticationProperties(storedData.Ticket.Properties.Dictionary));

                context.SetTicket(ticket);
            }
        }
    }

    public void Create(AuthenticationTokenCreateContext context)
    {
        throw new NotSupportedException("Synchronous creation is not supported");
    }

    public void Receive(AuthenticationTokenReceiveContext context)
    {
        throw new NotSupportedException("Synchronous reception is not supported");
    }
}

using System;
using System.Threading.Tasks;
using Lime.Protocol;
using MTC2016.ArtificialIntelligence;
using Takenet.MessagingHub.Client;
using MTC2016.FeedbackAndRating;

public class RatingMessageReceiver : IMessageReceiver
{
    private readonly IMessageSender _sender;
    private readonly IFeedbackRepository _feedbackRepository;
    private readonly string _ratingConfirmation = "Thank you for your feedback!";
    private readonly string _ratingFailed = "Sorry, we couldn't process your feedback. Please try again later.";

    public RatingMessageReceiver(IMessageSender sender, IFeedbackRepository feedbackRepository)
    {
        _sender = sender ?? throw new ArgumentNullException(nameof(sender));
        _feedbackRepository = feedbackRepository ?? throw new ArgumentNullException(nameof(feedbackRepository));
    }

    public async Task ReceiveAsync(Message message)
    {
        string userMessage = message.Content.ToLowerInvariant();

        var feedback = new Feedback
        {
            UserId = message.From.Uri.ToString(),
            Content = userMessage,
            Timestamp = DateTime.UtcNow
        };

        try
        {
            await _feedbackRepository.SaveAsync(feedback);
            await SendConfirmationAsync(message.From);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error processing feedback: {ex.Message}");
            await SendFailureResponseAsync(message.From);
        }
    }

    private async Task SendConfirmationAsync(Uri userUri)
    {
        var responseMessage = new Message
        {
            From = userUri,
            To = userUri,
            Content = _ratingConfirmation
        };

        await _sender.SendAsync(responseMessage);
    }

    private async Task SendFailureResponseAsync(Uri userUri)
    {
        var responseMessage = new Message
        {
            From = userUri,
            To = userUri,
            Content = _ratingFailed
        };

        await _sender.SendAsync(responseMessage);
    }
}

public interface IMessageReceiver
{
    Task ReceiveAsync(Message message);
}

public interface IMessageSender
{
    Task SendAsync(Message message);
}

public interface IFeedbackRepository
{
    Task SaveAsync(Feedback feedback);
}

