[TestFixture]
public class IndexModifiedTests : RepositoryTestCase
{
    private DirCache _index;

    [SetUp]
    public new void SetUp()
    {
        base.SetUp();
        _index = Repository.LockDirCache();
    }

    [Test]
    public void ShouldSupportExtensionlessFiles()
    {
        string fileName = "testfile";
        WriteTrashFile(fileName, "initial");
        AddToIndex(fileName);
        _index.Read();

        WriteTrashFile(fileName, "modified");
        Thread.Sleep(1250); // Ensure timestamp change

        DirCacheEntry entry = _index.GetEntry(fileName);
        Assert.IsTrue(entry.IsModified(Repository.WorkingTree, true));
    }

    [Test]
    public void ShouldSupportNotModifiedExtensionlessFilesWithoutContentChecking()
    {
        string fileName = "testfile";
        WriteTrashFile(fileName, "stable");
        AddToIndex(fileName);
        _index.Read();

        // Update timestamp without content change
        File.SetLastWriteTimeUtc(Path.Combine(trash.FullName, fileName), DateTime.UtcNow);
        Thread.Sleep(1250);

        DirCacheEntry entry = _index.GetEntry(fileName);
        Assert.IsFalse(entry.IsModified(Repository.WorkingTree, false));
    }

    [Test]
    public void ShouldAllowComparingOfAlreadyOpenedFile()
    {
        string fileName = "testfile";
        WriteTrashFile(fileName, "original");
        AddToIndex(fileName);
        _index.Read();

        using (FileStream fs = File.Open(Path.Combine(trash.FullName, fileName),
               FileMode.Open, FileAccess.ReadWrite, FileShare.ReadWrite))
        {
            WriteTrashFile(fileName, "changed");
            Thread.Sleep(1250);

            DirCacheEntry entry = _index.GetEntry(fileName);
            Assert.IsTrue(entry.IsModified(Repository.WorkingTree, true));
        }
    }

    private void AddToIndex(string path)
    {
        DirCacheEditor editor = _index.Editor();
        editor.Add(new AddEntryEdit(path));
        editor.Commit();
    }

    private class AddEntryEdit : DirCacheEditor.PathEdit
    {
        public AddEntryEdit(string path) : base(path) { }

        public override void Apply(DirCacheEntry entry)
        {
            entry.FileMode = FileMode.RegularFile;
            entry.SetLength(new FileInfo(Path.Combine(((RepositoryTestCase)TestFixtureBase.CurrentTest).trash.FullName, Path)).Length);

