namespace Xacml.PolicySchema
{
    public enum XacmlVersion
    {
        Version1_0,
        Version2_0,
        Version3_0
    }

    public abstract class TargetItemBase
    {
        protected TargetItemBase(XacmlVersion version)
        {
            SchemaVersion = version;
            IsReadOnly = false;
        }

        public XacmlVersion SchemaVersion { get; private set; }
        public bool IsReadOnly { get; protected set; }

        public abstract TargetMatchReadWriteCollection CreateMatches(XmlReader reader);
    }

    public class TargetMatchReadWriteCollection : List<TargetMatchElement>
    {
        public TargetMatchReadWriteCollection() { }
    }

    public class TargetMatchElement
    {
        public TargetMatchElement(string matchId, string attributeName, string attributeValue)
        {
            MatchId = matchId;
            AttributeName = attributeName;
            AttributeValue = attributeValue;
        }

        public string MatchId { get; }
        public string AttributeName { get; }
        public string AttributeValue { get; }
    }

    public class ActionElement : TargetItemBase
    {
        private TargetMatchReadWriteCollection _matches;

        public ActionElement(TargetMatchReadWriteCollection match, XacmlVersion version) : base(version)
        {
            _matches = match;
            IsReadOnly = true;
        }

        public ActionElement(XmlReader reader, XacmlVersion version) : base(version)
        {
            _matches = new TargetMatchReadWriteCollection();
            ParseXml(reader);
            IsReadOnly = true;
        }

        private void ParseXml(XmlReader reader)
        {
            if (reader == null)
                throw new ArgumentNullException(nameof(reader));

            if (reader.NodeType != XmlNodeType.Element || reader.LocalName != "Action")
                throw new ArgumentException("Reader must be positioned at an Action element.");

            while (reader.Read())
            {
                if (reader.NodeType == XmlNodeType.Element && reader.LocalName == "ActionMatch")
                {
                    _matches.Add(CreateMatch(reader.ReadSubtree()));
                }
                else if (reader.NodeType == XmlNodeType.EndElement && reader.LocalName == "Action")
                {
                    break;
                }
            }
        }

        public override TargetMatchReadWriteCollection CreateMatches(XmlReader reader)
        {

