namespace MonitoringDemo
{
    // Generated example demonstrating how to retrieve a monitored resource descriptor.
    public class GeneratedMetricServiceClientSnippets
    {
        // Main entry point for the demonstration.
        public static void Main(string[] args)
        {
            Console.WriteLine("Starting Monitored Resource Descriptor Retrieval Demo...");
            Console.WriteLine("--------------------------------------------------------");

            try
            {
                // Create a MetricServiceClient to interact with the monitoring service.
                MetricServiceClient metricClient = MetricServiceClient.Create();

                // Prepare an unparsed resource name string to simulate a valid resource identifier.
                string resourceNameString = "projects/your-project/monitoredResources/custom_resource";
                UnparsedResourceName unparsedResourceName = new UnparsedResourceName(resourceNameString);

                // Retrieve the MonitoredResourceDescriptor using the flattened method signature.
                MonitoredResourceDescriptor resourceDescriptor =
                    metricClient.GetMonitoredResourceDescriptor(unparsedResourceName);

                // Output key details from the resource descriptor.
                Console.WriteLine("Monitored Resource Descriptor Retrieved Successfully:");
                Console.WriteLine("Name: " + resourceDescriptor.Name);
                Console.WriteLine("Type: " + resourceDescriptor.Type);
                Console.WriteLine("Display Name: " + resourceDescriptor.DisplayName);
                Console.WriteLine("Description: " + resourceDescriptor.Description);
                Console.WriteLine();

                // Optionally, list each label associated with the resource.
                Console.WriteLine("Labels:");
                foreach (var label in resourceDescriptor.Labels)
                {
                    Console.WriteLine($"- Key: {label.Key}, Description: {label.Value.Description}");
                }
            }
            catch (Exception ex)
            {
                // Output error details if any exception is thrown.
                Console.WriteLine("An error occurred while retrieving the resource descriptor:");
                Console.WriteLine(ex.Message);
            }

            Console.WriteLine();
            Console.WriteLine("Demo completed. Press any key to exit.");
            Console.ReadKey();
        }
    }
}

