using System;
using System.Linq;

public class PokerHand
{
    private static readonly string[] FACES = { "2", "3", "4", "5", "6", "7", "8", "9", "10", "j", "q", "k", "a" };
    private static readonly string[] SUITS = { "♥", "♦", "♣", "♠" };

    public static string AnalyzeHand(string hand)
    {
        var cards = hand.Split(' ').Where(x => x!= "joker");
        var jokers = hand.Split(' ').Length - cards.Count();

        var faces = cards.Select(card => Array.IndexOf(FACES, card.Substring(0, card.Length - 1)));
        var suits = cards.Select(card => Array.IndexOf(SUITS, card.Substring(card.Length - 1)));

        if (cards.Any(card => card.Any(c =>!char.IsDigit(c) &&!char.IsLetter(c))) || faces.Any(face => face == -1) || suits.Any(suit => suit == -1))
            return "invalid";

        var flush = suits.All(suit => suit == suits.First());
        var groups = FACES.Select((face, i) => faces.Count(j => i == j)).OrderByDescending(x => x).ToArray();
        var shifted = faces.Select(x => (x + 1) % 13);
        var distance = Math.Min(faces.Max() - faces.Min(), shifted.Max() - shifted.Min());
        var straight = groups[0] == 1 && distance < 5;
        groups[0] += jokers;

        if (groups[0] == 5)
            return "five-of-a-kind";
        else if (straight && flush)
            return "straight-flush";
        else if (groups[0] == 4)
            return "four-of-a-kind";
        else if (groups[0] == 3 && groups[1] == 2)
            return "full-house";
        else if (flush)
            return "flush";
        else if (straight)
            return "straight";
        else if (groups[0] == 3)
            return "three-of-a-kind";
        else if (groups[0] == 2 && groups[1] == 2)
            return "two-pair";
        else if (groups[0] == 2)
            return "one-pair";
        else
            return "high-card";
    }
}

