public class FakeCakeContext : ICakeContext
{
    public IFileSystem FileSystem { get; }
    public ICakeLog Log { get; }
    public ICakeEnvironment Environment { get; }
    public IGlobber Globber { get; }
    public ICakeArguments Arguments { get; }
    public IRegistry Registry { get; }
    public ICakeDataService DataService { get; }
    public IToolRepository Tools { get; }
    public ICakeConfiguration Configuration { get; }
    public IToolResolutionStrategy ToolResolutionStrategy { get; }
    public IToolLocator ToolLocator { get; }
    public IProcessRunner ProcessRunner { get; }
    public ICakeRuntime Runtime { get; }

    public DirectoryPath WorkingDirectory { get; }

    public FakeCakeContext(DirectoryPath workingDirectory = null)
    {
        WorkingDirectory = workingDirectory ?? new DirectoryPath("/Working");
        FileSystem = new FileSystem();
        Log = new FakeLog();
        Environment = new CakeEnvironment(new FakePlatform(), new WindowsRegistry(), new FakeCakeArguments(), new FakeConfiguration(), new CakeRuntime());
        Globber = new Globber(FileSystem, Environment);
        Arguments = new FakeCakeArguments();
        Registry = new WindowsRegistry();
        DataService = new FakeDataService();
        Tools = new ToolRepository(Environment, new ToolResolutionStrategy(Environment, new ToolLocator(Environment)));
        Configuration = new FakeConfiguration();
        ToolResolutionStrategy = new ToolResolutionStrategy(Environment, ToolLocator);
        ToolLocator = new ToolLocator(Environment);
        ProcessRunner = new ProcessRunner(Environment, new CakeLog());
        Runtime = new CakeRuntime();
    }

    public void DumpLogs()
    {
        foreach (var logEntry in GetLogs())
        {
            Console.WriteLine(logEntry);
        }
    }

    public IEnumerable<string> GetLogs()
    {
        return ((FakeLog)Log).Entries.Select(e => $"{e.Level}: {e.Message}");
    }
}

