    // Domain command for delaying a voyage
    public class VoyageDelayCommand
    {
        public VoyageId VoyageId { get; }
        public TimeSpan Delay { get; }
        public DateTime ScheduledTime { get; }

        public VoyageDelayCommand(VoyageId voyageId, TimeSpan delay)
        {
            VoyageId = voyageId;
            Delay = delay;
            ScheduledTime = DateTime.UtcNow.Add(delay);
        }

        public override string ToString() =>
            $"VoyageDelayCommand for Voyage: {VoyageId.Id}, Delay: {Delay}, ScheduledTime: {ScheduledTime}";
    }

    // Structure representing a voyage identifier
    public readonly struct VoyageId
    {
        public string Id { get; }
        public VoyageId(string id)
        {
            if (string.IsNullOrWhiteSpace(id))
                throw new ArgumentException("Voyage identifier cannot be null or empty.", nameof(id));
            Id = id;
        }
    }

    // Interface for the command bus responsible for dispatching domain commands
    public interface ICommandBus
    {
        Task PublishAsync<TCommand>(TCommand command, CancellationToken cancellationToken = default)
            where TCommand : class;
    }

    // Application-level service handling scheduling operations for voyages
    public class ScheduleApplicationService
    {
        private readonly ICommandBus _commandBus;

        // Constructor implementing dependency injection for the command bus
        public ScheduleApplicationService(ICommandBus commandBus)
        {
            _commandBus = commandBus ?? throw new ArgumentNullException(nameof(commandBus));
        }

        // Asynchronous method to schedule a delay for a voyage
        public async Task DelayScheduleAsync(VoyageId voyageId, TimeSpan delay, CancellationToken cancellationToken)
        {
            // Create command encapsulating the request to delay a voyage
            var command = new VoyageDelayCommand(voyageId, delay);
            // Publish the command asynchronously using the command bus
            await _commandBus.PublishAsync(command, cancellationToken);
        }
    }

