namespace MediatRTests
{
    public class Ping : IRequest<Pong>
    {
        public string Message { get; set; }
    }

    public class Pong
    {
        public string Message { get; set; }
    }

    public class PingHandler : IRequestHandler<Ping, Pong>
    {
        public Task<Pong> Handle(Ping request, CancellationToken cancellationToken)
        {
            return Task.FromResult(new Pong { Message = request.Message + " Pong" });
        }
    }

    public class PingPreProcessor : IRequestPreProcessor<Ping>
    {
        public Task Process(Ping request, CancellationToken cancellationToken)
        {
            request.Message += " PreProcessed";
            return Task.CompletedTask;
        }
    }

    public class RequestPreProcessorTests
    {
        private readonly IMediator mediator;

        public RequestPreProcessorTests()
        {
            var container = new Container(cfg =>
            {
                cfg.Scan(scanner =>
                {
                    scanner.AssemblyContainingType<RequestPreProcessorTests>();
                    scanner.IncludeNamespaceContainingType<RequestPreProcessorTests>();
                    scanner.WithDefaultConventions();
                    scanner.AddAllTypesOf(typeof(IRequestHandler<,>));
                    scanner.AddAllTypesOf(typeof(IRequestPreProcessor<>));
                });

                cfg.For<ServiceFactory>().Use<ServiceFactory>(ctx => ctx.GetInstance);
                cfg.For<IMediator>().Use<Mediator>();
            });

            mediator = container.GetInstance<IMediator>();
        }

        [Fact]
        public async Task Should_run_preprocessors()
        {
            var request = new Ping { Message = "Ping" };
            var response = await mediator.Send(request);

            response.Message.ShouldBe("Ping PreProcessed Pong");
        }
    }
}

