public class WebDAVStorageAdapterTests : IClassFixture<WebDAVStorageAdapterFixture>
{
    private readonly WebDAVStorageAdapterFixture _fixture;
    private readonly string _testPath;

    public WebDAVStorageAdapterTests(WebDAVStorageAdapterFixture fixture)
    {
        _fixture = fixture;
        _testPath = CreateTestPath();
    }

    private string CreateTestPath()
    {
        var uniquePath = Path.Combine("test-data", Guid.NewGuid().ToString());
        Directory.CreateDirectory(uniquePath);
        return uniquePath;
    }

    private void CleanupTestPath()
    {
        if (Directory.Exists(_testPath))
        {
            Directory.Delete(_testPath, true);
        }
    }

    [Fact]
    public async Task FileExists_ShouldReturnTrue_ForExistingFile()
    {
        var adapter = _fixture.CreateAdapter();
        var filePath = Path.Combine(_testPath, "testfile.txt");
        await File.WriteAllTextAsync(filePath, "Test content");

        var exists = await adapter.FileExists(filePath);
        Assert.True(exists);

        CleanupTestPath();
    }

    [Fact]
    public async Task GetFileInfo_ShouldReturnCorrectMetadata()
    {
        var adapter = _fixture.CreateAdapter();
        var filePath = Path.Combine(_testPath, "testfile.txt");
        await File.WriteAllTextAsync(filePath, "Test content");

        var fileInfo = await adapter.GetFileInfo(filePath);
        Assert.NotNull(fileInfo);
        Assert.Equal("testfile.txt", fileInfo.Name);
        Assert.True(fileInfo.Length > 0);

        CleanupTestPath();
    }

    [Fact]
    public async Task ContentIsNotModified_ShouldReturnTrue_ForUnchangedFile()
    {
        var adapter = _fixture.CreateAdapter();
        var filePath = Path.Combine(_testPath, "testfile.txt");
        await File.WriteAllTextAsync(filePath, "Test content");

        var initialHash = await adapter.GetFileHash(filePath);
        var isNotModified = await adapter.ContentIsNotModified(filePath, initialHash);
        Assert.True(isNotModified);

        CleanupTestPath();
    }

    [Fact]
    public async Task ContentIsNotModified_ShouldReturnFalse_ForChangedFile()
    {
        var adapter = _fixture.CreateAdapter();
        var filePath = Path.Combine(_testPath, "testfile.txt");
        await File.WriteAllTextAsync(filePath, "Test content");

        var initialHash = await adapter.GetFileHash(filePath);
        await File.WriteAllTextAsync(filePath, "Modified content");

