using System;
using System.Data.SqlClient;
using System.Security.Cryptography;
using System.Text;
 
class UserManager
{
    private SqlConnection dbConnection;
 
    private string MD5(string message)
    {
        var hexString = new StringBuilder();
        var bytes = Encoding.UTF8.GetBytes(message);
        var md = MD5.Create();
        var dig = md.ComputeHash(bytes);
        for (var i = 0; i < dig.Length; i++)
        {
            var hex = (0xff & dig[i]).ToString("x");
            if (hex.Length == 1) hexString.Append('0');
            hexString.Append(hex);
        }
        return hexString.ToString();
    }
 
    public void ConnectDB(string host, int port, string db, string user, string pwd)
    {
        dbConnection = new SqlConnection(
            $"Data Source={host},{port};Initial Catalog={db};User ID={user};Password={pwd}"
        );
        dbConnection.Open();
    }
 
    public bool CreateUser(string user, string pwd)
    {
        var random = new RNGCryptoServiceProvider();
        var salt = new byte[130];
        random.GetBytes(salt);
        var insert = "INSERT INTO users " +
            "(username, pass_salt, pass_md5) " +
            "VALUES (@user, @salt, @md5)";
        try
        {
            var cmd = new SqlCommand(insert, dbConnection);
            cmd.Parameters.AddWithValue("@user", user);
            cmd.Parameters.AddWithValue("@salt", Convert.ToBase64String(salt));
            cmd.Parameters.AddWithValue("@md5", MD5(Convert.ToBase64String(salt) + pwd));
            var rowCount = cmd.ExecuteNonQuery();
            cmd.Dispose();
            if (rowCount == 0) return false;
            return true;
        }
        catch (Exception)
        {
            return false;
        }
    }
 
    public bool AuthenticateUser(string user, string pwd)
    {
        var select = "SELECT pass_salt, pass_md5 FROM users WHERE username = @user";
        SqlDataReader res;
        try
        {
            var cmd = new SqlCommand(select, dbConnection);
            cmd.Parameters.AddWithValue("@user", user);
            res = cmd.ExecuteReader();
            res.Read();  // assuming that username is unique
            var passSalt = res.GetString(0);
            var passMD5 = res.GetString(1);
            cmd.Dispose();
            return passMD5 == MD5(passSalt + pwd);
        }
        catch (Exception)
        {
            return false;
        }
        finally
        {
            if (!res.IsClosed) res.Close();
        }
    }
 
