namespace standardDeviation
{
    class Timer
    {
        static void Main(string[] args)
        {
            List<double> nums = new List<double> { 2, 4, 4, 4, 5, 5, 7, 9 };
            for (int i = 1; i <= nums.Count; i++)
                Console.WriteLine(sdev(nums.GetRange(0, i)));
        }
 
        static double sdev(List<double> nums)
        {
            List<double> store = new List<double>();
            foreach (double n in nums)
                store.Add((n - nums.Average()) * (n - nums.Average()));
 
            return Math.Sqrt(store.Sum() / store.Count);
        }
    }
}

using System.Diagnostics;
using Box2D.Collision.Shapes;
using Box2D.Common;
using Box2D.Collision;

namespace Box2D.Collision
{
    public class b2PolygonAndCircleContact : b2Contact
    {
        public b2PolygonAndCircleContact(b2Fixture fixtureA, b2Fixture fixtureB)
            : base(fixtureA, fixtureB)
        {
            Debug.Assert(fixtureA.ShapeType == b2ShapeType.Polygon);
            Debug.Assert(fixtureB.ShapeType == b2ShapeType.Circle);
        }

        public override void Evaluate(b2Manifold manifold, b2Transform xfA, b2Transform xfB)
        {
            var polygon = (b2PolygonShape)FixtureA.Shape;
            var circle = (b2CircleShape)FixtureB.Shape;
            CollisionAlgo.CollidePolygonAndCircle(manifold, polygon, xfA, circle, xfB);
        }
    }

    internal static class CollisionAlgo
    {
        public static void CollidePolygonAndCircle(b2Manifold manifold, b2PolygonShape poly, b2Transform xfPoly, b2CircleShape circle, b2Transform xfCircle)
        {
            manifold.PointCount = 0;

            b2Vec2 circleCenter = b2Math.b2Mul(xfCircle, circle.Center);
            b2Vec2 centerLocal = b2Math.b2MulT(xfPoly, circleCenter);

            float radius = circle.Radius;
            float maxSeparation = -float.MaxValue;
            int edgeIndex = 0;
            int vertexCount = poly.VertexCount;

            for (int i = 0; i < vertexCount; ++i)
            {
                float separation = b2Math.b2Dot(poly.Normals[i], centerLocal - poly.Vertices[i]);
                if (separation > radius)
                {
                    return;
                }
                if (separation > maxSeparation)
                {
                    maxSeparation = separation;
                    edgeIndex = i;
                }
            }

            b2Vec2 v1 = poly.Vertices[edgeIndex];
            b2Vec2 v2 = poly.Vertices[(edgeIndex + 1) % vertexCount];
            b2Vec2 edge = v2 - v1;

            float u = b2Math.b2Dot(centerLocal - v1, edge) / b2Math.b2Dot(edge, edge);
            u = System.Math.Clamp(u, 0.0f, 1.0f);
            b2Vec2 closestPoint = v1 + u * edge;

            float distanceSqr = b2Math.b2DistanceSquared(centerLocal, closestPoint);
            if (distanceSqr > radius * radius)
            {
                return;
            }

            manifold.PointCount = 1;
            manifold.Type = b2ManifoldType.FaceA;
            manifold.LocalNormal = poly.Normals[edgeIndex];
            manifold.LocalPoint = closestPoint;
            manifold.Points[0].LocalPoint = circle.Center;

