public delegate void PacketReceivedHandler(NetworkPacket packet);

public class NetworkPacket
{
    public string Destination { get; set; }
    public object Payload { get; set; }
}

public struct NetworkPacketQueueEntry
{
    public NetworkPacket Packet { get; }
    public DateTime QueuedTime { get; }

    public NetworkPacketQueueEntry(NetworkPacket packet, DateTime queuedTime)
    {
        Packet = packet;
        QueuedTime = queuedTime;
    }
}

public class FakeNetwork : IDisposable
{
    private readonly ConcurrentDictionary<string, PacketReceivedHandler> _listeners = new();
    private readonly ConcurrentQueue<NetworkPacketQueueEntry> _queuedPackets = new();
    private readonly Timer _stateTimer;
    private readonly TimeSpan _simulatedDelay;
    private bool _disposed;

    public FakeNetwork(TimeSpan simulatedDelay, int timerIntervalMs)
    {
        _simulatedDelay = simulatedDelay;
        _stateTimer = new Timer(TimerCallback, null, timerIntervalMs, timerIntervalMs);
    }

    public void SendPacket(NetworkPacket packet)
    {
        if (packet == null) throw new ArgumentNullException(nameof(packet));
        _queuedPackets.Enqueue(new NetworkPacketQueueEntry(packet, DateTime.UtcNow));
    }

    public void AttachListener(string destination, PacketReceivedHandler handler)
    {
        if (string.IsNullOrEmpty(destination)) throw new ArgumentException("Invalid destination", nameof(destination));
        if (handler == null) throw new ArgumentNullException(nameof(handler));
        if (!_listeners.TryAdd(destination, handler))
            throw new InvalidOperationException($"Listener conflict for {destination}");
    }

    private void TimerCallback(object state)
    {
        var entries = new List<NetworkPacketQueueEntry>();
        while (_queuedPackets.TryDequeue(out var entry)) entries.Add(entry);

        foreach (var entry in entries)
        {
            if (DateTime.UtcNow - entry.QueuedTime >= _simulatedDelay)
            {
                if (_listeners.TryGetValue(entry.Packet.Destination, out var handler))
                    handler?.Invoke(entry.Packet);
            }
            else _queuedPackets.Enqueue(entry);
        }
    }

    public void Dispose()
    {
        if (_disposed) return;
        _stateTimer?.Dispose();
        _disposed = true;
        GC.SuppressFinalize(this);
    }
}

