public class Advent32
{
    private ArrayList points = new ArrayList();
    private ArrayList santaSteps = new ArrayList();
    private ArrayList roboSteps = new ArrayList();

    public void ReadFile(string path)
    {
        string directions = File.ReadAllText(path).Trim();
        SplitDirections(directions);
        CalculateVisits();
        Console.WriteLine(points.Count);
    }

    private void SplitDirections(string input)
    {
        for (int i = 0; i < input.Length; i++)
        {
            if (i % 2 == 0)
                santaSteps.Add(input[i]);
            else
                roboSteps.Add(input[i]);
        }
    }

    private Point Move(Point current, char direction)
    {
        switch (direction)
        {
            case '^': return new Point(current.X, current.Y + 1);
            case 'v': return new Point(current.X, current.Y - 1);
            case '>': return new Point(current.X + 1, current.Y);
            case '<': return new Point(current.X - 1, current.Y);
            default: return current;
        }
    }

    private bool IsVisited(Point p)
    {
        foreach (object item in points)
        {
            Point existing = (Point)item;
            if (existing.X == p.X && existing.Y == p.Y)
                return true;
        }
        return false;
    }

    private void TrackLocation(Point p)
    {
        if (!IsVisited(p))
            points.Add(p);
    }

    private void CalculateVisits()
    {
        Point santaPos = new Point(0, 0);
        Point roboPos = new Point(0, 0);
        TrackLocation(santaPos);

        int maxIterations = Math.Max(santaSteps.Count, roboSteps.Count);
        for (int i = 0; i < maxIterations; i++)
        {
            if (i < santaSteps.Count)
            {
                santaPos = Move(santaPos, (char)santaSteps[i]);
                TrackLocation(santaPos);
            }

            if (i < roboSteps.Count)
            {
                roboPos = Move(roboPos, (char)roboSteps[i]);
                TrackLocation(roboPos);
            }
        }
    }
}

