public class FormattedSlider : Slider
{
    private ToolTip _autoToolTip;
    private string _autoToolTipFormat = "{0}";

    static FormattedSlider()
    {
        DefaultStyleKeyProperty.OverrideMetadata(typeof(FormattedSlider), new FrameworkPropertyMetadata(typeof(FormattedSlider)));
    }

    public string AutoToolTipFormat
    {
        get => _autoToolTipFormat;
        set => _autoToolTipFormat = value;
    }

    protected override void OnInitialized(EventArgs e)
    {
        base.OnInitialized(e);
        CreateAutoToolTip();
    }

    private void CreateAutoToolTip()
    {
        _autoToolTip = new ToolTip();
        _autoToolTip.Content = FormatAutoToolTipContent(Value);
        Binding binding = new Binding("Value")
        {
            Source = this,
            Converter = new ValueToTooltipConverter(this)
        };
        _autoToolTip.SetBinding(ToolTip.ContentProperty, binding);
    }

    protected override void OnThumbDragStarted(DragStartedEventArgs e)
    {
        base.OnThumbDragStarted(e);
        UpdateToolTip();
    }

    protected override void OnThumbDragDelta(DragDeltaEventArgs e)
    {
        base.OnThumbDragDelta(e);
        UpdateToolTip();
    }

    private void UpdateToolTip()
    {
        if (_autoToolTip != null && _autoToolTip.IsOpen)
        {
            _autoToolTip.Content = FormatAutoToolTipContent(Value);
        }
        else if (_autoToolTip != null)
        {
            _autoToolTip.IsOpen = true;
            _autoToolTip.Content = FormatAutoToolTipContent(Value);
        }
    }

    private string FormatAutoToolTipContent(double value)
    {
        return string.Format(AutoToolTipFormat, value);
    }

    protected override void OnMouseEnter(System.Windows.Input.MouseEventArgs e)
    {
        base.OnMouseEnter(e);
        if (_autoToolTip != null && !_autoToolTip.IsOpen)
        {
            _autoToolTip.IsOpen = true;
        }
    }

    protected override void OnMouseLeave(System.Windows.Input.MouseEventArgs e)
    {
        base.OnMouseLeave(e);
        if (_autoToolTip != null)
        {
            _autoToolTip.IsOpen = false;
        }
    }
}

