        this.age = age;
    }
 
    public virtual Animal copy()
    {
        return new Animal(name, age);
    }
 
    public override string ToString()
    {
        return $"Name: {name}, Age: {age}";
    }
}
 
public class Dog : Animal
{
    public readonly string breed;
 
    public Dog(string name, int age, string breed) : base(name, age)
    {
        this.breed = breed;
    }
 
    public override Animal copy()
    {
        return new Dog(name, age, breed);
    }
 
    public override string ToString()
    {
        return base.ToString() + $", Breed: {breed}";
    }
}
 
public class Cache
{
    public static void Main(string[] args)
    {
        Animal a = new Dog("Rover", 3, "Terrier");
        Animal b = a.copy();  // calls Dog.copy() because runtime type of 'a' is Dog
        Console.WriteLine($"Dog 'a' = {a}");   // implicitly calls Dog.ToString()
        Console.WriteLine($"Dog 'b' = {b}");   // ditto
        Console.WriteLine($"Dog 'a' is {(a == b? "" : "not")} the same object as Dog 'b'");
    }
}

namespace MHDiff
{
    using System;
    using System.Collections;
    using System.Text;
    using System.Text.RegularExpressions;

    /// <summary>
    /// This Class implements the Difference Algorithm published in
    /// "An O(ND) Difference Algorithm and its Variations" by Eugene Myers
    /// Algorithmica Vol. 1 No. 2, 1986, p 251.
    ///
    /// There are many C, Java, Lisp implementations public available but they all seem to come
    /// from the same source (diffutils) that is under the (unfree) GNU public License
    /// and cannot be reused as a sourcecode for a commercial application.
    /// There are very old C implementations that use other (worse) algorithms.
    /// Microsoft also published sourcecode of a diff-tool (windiff) that uses some tree data.
    /// Also, a direct transfer from a C source to C# is not easy because there is a lot of pointer
    /// arithmetic in the typical C solutions and i need a managed solution.
    /// These are the reasons why I implemented the original published algorithm from the scratch and
    /// make it avaliable without the GNU license limitations.
    /// I do not need a high performance diff tool because it is used only sometimes.
    /// I will do some performace tweaking when needed.
    ///
    /// The algorithm itself is comparing 2 arrays of numbers so when comparing 2 text documents
    /// each line is converted into a (hash) number. See DiffText().
    ///
    /// Some chages to the original algorithm:
    /// The original algorithm was described using a recursive approach and comparing zero indexed arrays.
    /// Extracting sub-arrays and rejoining them is very performance and memory intensive so the same
    /// (readonly) data arrays are passed arround together with their lower and upper bounds.
    /// This circumstance makes the LCS and SMS functions more complicate.
    /// I added some code to the LCS function to get a fast response on sub-arrays that are identical,
    /// completely deleted or inserted.
    ///
    /// The result from a comparisation is stored in 2 arrays that flag for modified (deleted or inserted)
    /// lines in the 2 data arrays. These bits are then analysed to produce a array of Item objects.
    ///
    /// Further possible optimizations:
    /// (first rule: don't do it; second: don't do it yet)
    /// The arrays DataA and DataB are passed as parameters, but are never changed after the creation
    /// so they can be members of the class to avoid the paramter overhead.

