    public class PatternModel
    {

public static double NthRoot(double num, int nArg, int precArg)
{
    int n = nArg;
    int prec = precArg;

    double x = 1; // Initial guess.
    for (int i = 0; i < prec; i++)
    {
        x = 1 / n * ((n - 1) * x + (num / Math.Pow(x, n - 1)));
    }

    return x;
}

